__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_AvgDialog = readonly({
  AvgDialog_100303_Content_1 = {
    Text = "Huff... huff... No, no es eso... algo todavía se siente raro..."
  },
  AvgDialog_100303_Content_10 = {
    Text = "¿Por qué está justo frente a mí, pero aún no puedo encontrarlo...?"
  },
  AvgDialog_100303_Content_11 = {
    Text = "No te preocupes, Pikman. Si la musa ya te lo ha dicho, la respuesta debe estar muy cerca de ti. Piensa bien, ¿hay algo que te hayas perdido."
  },
  AvgDialog_100303_Content_12 = {
    Text = "Antes de eso, levántate... sss..."
  },
  AvgDialog_100303_Content_13 = {
    Text = "Retiraste de repente la mano que intentabas extender para ayudarlo. Su cuerpo ardiente parecía estar fluyendo con lava."
  },
  AvgDialog_100303_Content_14 = {
    Text = "Como se esperaba, es Thais causando problemas nuevamente..."
  },
  AvgDialog_100303_Content_15 = {
    Text = "Thais... ¡Ah! ¡Cierto! ¿Cómo no pude pensar en eso? ¿Cómo pude pasarlo por alto?"
  },
  AvgDialog_100303_Content_16 = {
    Text = "Él se enderezó bruscamente, mirándote fijamente con unos ojos que casi te quemaban."
  },
  AvgDialog_100303_Content_17 = {
    Text = "¡El deseo más loco... ¡Sí! ¡Lo sabía, lo sabía...!"
  },
  AvgDialog_100303_Content_18 = {
    Text = "Él estaba tan emocionado que olvidó incluso levantarse, usando manos y pies para arrastrarse hasta tu frente."
  },
  AvgDialog_100303_Content_19 = {
    Text = "Guardián del Secreto, ¿puedes ser mi modelo una vez más? ¡Solo una vez! ¡Con una sola vez es suficiente!"
  },
  AvgDialog_100303_Content_2 = {Text = "Pickman"},
  AvgDialog_100303_Content_20 = {
    Text = "Sé lo que quieres hacer, absolutamente no..."
  },
  AvgDialog_100303_Content_21 = {
    Text = "Los ojos rojos de Pickman, ansiosos y suplicantes, brillan levemente bajo la luz oscura. Las palabras de rechazo ya no pueden salir."
  },
  AvgDialog_100303_Content_22 = {
    Text = "...Está bien. Si solo es ser modelo, ¿puedo sentarme en ese sofá?"
  },
  AvgDialog_100303_Content_23 = {
    Text = "¡No, no, no, Guardián! ¿Cómo puedes crear una pintura así en el estudio?!"
  },
  AvgDialog_100303_Content_24 = {Text = "..."},
  AvgDialog_100303_Content_25 = {
    Text = "¿Es este... el mundo en tu pintura?"
  },
  AvgDialog_100303_Content_26 = {
    Text = "¡Así es! ¡Es el ritual del carnaval de los ghouls!"
  },
  AvgDialog_100303_Content_27 = {
    Text = "Lo creé, pero nunca lo terminé. Carece de un par de protagonistas en su centro. Representan los deseos más primitivos y salvajes de este universo, los deseos que he olvidado..."
  },
  AvgDialog_100303_Content_28 = {
    Text = "Hasta ahora no he encontrado un modelo suficiente para convertirme en el protagonista..."
  },
  AvgDialog_100303_Content_29 = {
    Text = "Pickman aún mantiene la posición de rodillas, arrastrando sus rodillas hacia ti."
  },
  AvgDialog_100303_Content_3 = {
    Text = "El oscuro estudio de Pikman está más desordenado que nunca, con innumerables hojas de papel de cuero llenas de colores y líneas esparcidas desordenadamente en cada rincón del estudio, como si hubieran sobrevivido a una extraña guerra."
  },
  AvgDialog_100303_Content_30 = {
    Text = "Por favor, Guardián... ¡otórgame la Musa!"
  },
  AvgDialog_100303_Content_31 = {
    Text = "¡Hazme lo que quieras! Solo una vez, ¡por favor llévame a terminar esta pintura...!"
  },
  AvgDialog_100303_Content_32 = {
    Text = "Sin dudar mucho, suspiras suavemente y te acercas a él."
  },
  AvgDialog_100303_Content_33 = {
    Text = "Él levantó la cabeza, abriendo los ojos de par en par para mirarte. Eran unos ojos que pertenecían a una bestia o a una mascota, codiciosos, deseosos, obedientes y leales. Te estaba suplicando, suplicando una orden que lo llevara hacia la musa."
  },
  AvgDialog_100303_Content_34 = {
    Text = "Puedo hacer lo que sea... Entonces, tengo que pensarlo bien..."
  },
  AvgDialog_100303_Content_35 = {
    Text = "Tu mano se posa suavemente sobre el rostro de Pickman. Su aliento ardiente y su cuerpo se vuelven dóciles. No sabes si eres tú quien lo doma, o si él está derritiéndote."
  },
  AvgDialog_100303_Content_36 = {
    Text = "Las voces de los ghouls comenzaron a disiparse, y el sonido rudo y primitivo de esta pareja de protagonistas llenaba todo el mundo en la pintura."
  },
  AvgDialog_100303_Content_37 = {
    Text = "Esa es la voz de Muzus."
  },
  AvgDialog_100303_Content_4 = {
    Text = "Él, con la ropa desordenada, se arrodilla en el suelo, pintando frenéticamente sobre una hoja de papel en blanco, casi a punto de romperla. La pintura salpicada cubre su cuerpo, como si fuera un culto que está realizando un sacrificio salvaje."
  },
  AvgDialog_100303_Content_5 = {
    Text = "¿Qué está pasando..."
  },
  AvgDialog_100303_Content_6 = {
    Text = "¡Lo oí, Guardián! ¡Escuché la voz de la Musa llamando! ¡Justo en mi oído!"
  },
  AvgDialog_100303_Content_7 = {
    Text = "Mis ojos, mis manos, mi corazón, cada célula de mi cuerpo tiembla al oírlo"
  },
  AvgDialog_100303_Content_8 = {
    Text = "¡Solo falta un paso! ¡Estoy a un paso del arte más grande!"
  },
  AvgDialog_100303_Content_9 = {
    Text = "Pero no puedo encontrarlo... asesinatos, conquistas, gula, codicia, gastar en exceso, vacío... He esbozado toda la locura, pero aún no lo he encontrado..."
  },
  AvgDialog_100588_Content_1 = {
    Text = "Una figura oscura se va manifestando ante ti."
  },
  AvgDialog_100588_Content_2 = {
    Text = "[Ataque]???"
  },
  AvgDialog_100588_Content_3 = {
    Text = "¡Has infligido 677 puntos de daño! Sientes que has causado un total de 27,188 puntos de daño a Él.\nTodos han infligido un total de 14,636,643,707 puntos de daño a Él, pero aún no ha caído."
  },
  AvgDialog_100588_Content_4 = {
    Text = "[Continuar]"
  },
  AvgDialog_100588_Content_5 = {
    Text = "Sientes que has estado aquí antes...\nbajo la mirada de la sombra, tu conciencia se vuelve gradualmente borrosa."
  },
  AvgDialog_100588_Content_6 = {Text = "[Dormir]"},
  AvgDialog_100629_Content_1 = {
    Text = "No mucho después, este mundo ya no se vería afectado por la disolución, la humanidad se desarrolló rápidamente, y más tarde la Universidad de Mitag detuvo un tren bajo las estrellas..."
  },
  AvgDialog_10120_Content_1 = {
    Text = "Protege tu dispositivo de comando y ten cuidado con la contaminación por Disolución.\nSerá esencial en la próxima batalla."
  },
  AvgDialog_10120_Content_2 = {
    Text = "Mantén presionado el <Yellow:Command Card> y arrástralo a la <Yellow:Central Command Zone> para emitir un comando de acción hacia mí."
  },
  AvgDialog_10121_Content_1 = {
    Text = "<Yellow:¿Plata>? No esperaba encontrarlo aquí..."
  },
  AvgDialog_10121_Content_2 = {
    Text = "Fabricar Llaves de Plata, vincular Despertadores y proporcionar energía espiritual...\nTodo en Mitag gira en torno a <Yellow:Plata>."
  },
  AvgDialog_10121_Content_3 = {
    Text = "Incluso una pequeña cantidad de <Yellow:Plata> tiene un valor extraordinario para la investigación de Mythag.\nIntenta recolectarlas todas."
  },
  AvgDialog_10122_Content_1 = {
    Text = "Prolongar esto es desventajoso; debemos llevar esto a una conclusión rápida."
  },
  AvgDialog_10122_Content_2 = {
    Text = "Aquí está la <Yellow:\"Espada de la Reina\"> con la que he practicado desde la infancia.\n¡Terminemos con este golpe!"
  },
  AvgDialog_10123_Content_1 = {
    Text = "Pasas a través de la pequeña puerta debajo de la torre del reloj y entras en un pasillo oculto y cerrado."
  },
  AvgDialog_10123_Content_10 = {Text = "..."},
  AvgDialog_10123_Content_11 = {
    Text = "La puerta se abre lentamente, revelando por primera vez la escena del lugar prohibido"
  },
  AvgDialog_10123_Content_13 = {
    Text = "Su mitad inferior sumergida en un lodo negro, la oscuridad devoradora acentúa su radiante pureza, dejándola inmaculadamente blanca."
  },
  AvgDialog_10123_Content_14 = {
    Text = "En un estado de aturdimiento, la figura inhumana frente a ti se superpone sutilmente con la silueta de la joven que viste en la Llave Tumba."
  },
  AvgDialog_10123_Content_15 = {
    Text = "No tiene cara, sin embargo, sientes cierta compasión en su postura."
  },
  AvgDialog_10123_Content_16 = {
    Text = "Supremo, Puro, Bueno, Hermoso."
  },
  AvgDialog_10123_Content_17 = {
    Text = "<Shake:Tú... has llegado...>"
  },
  AvgDialog_10123_Content_18 = {
    Text = "El monstruo blanco emitió un sonido áspero, parte rugido, parte lamento."
  },
  AvgDialog_10123_Content_19 = {
    Text = "No es un lenguaje humano, sin embargo, comprendes el significado de sus palabras."
  },
  AvgDialog_10123_Content_2 = {
    Text = "Doll lidera el camino adelante, sus pasos resonando huecamente sobre la superficie metálica."
  },
  AvgDialog_10123_Content_20 = {
    Text = "Todo frente a ti de repente se vuelve borroso. Parpadeas, y un líquido caliente se desliza por tu mejilla."
  },
  AvgDialog_10123_Content_21 = {
    Text = "¿Es eso una lágrima? Pero, ¿por qué? ¿Qué está haciendo que tu pecho se sienta apretado y tus ojos ardan?"
  },
  AvgDialog_10123_Content_22 = {
    Text = "......<Yellow:Tawil>?"
  },
  AvgDialog_10123_Content_23 = {
    Text = "Las palabras que murmura Muñeca hacen que la expresión de Ramona cambie."
  },
  AvgDialog_10123_Content_24 = {
    Text = "¿Tawil? ¿La que es una de las fundadoras, la Despertadora Tawil?"
  },
  AvgDialog_10123_Content_25 = {
    Text = "También recuerdas.\nEn <Blue:\"La Historia de Mitag\">, este nombre aparece junto a otros dos"
  },
  AvgDialog_10123_Content_26 = {
    Text = "En Alluvium 90, <Blue:Ward Phillips>, <Blue:Klararksh>, y <Blue:Tawil> fundaron <Blue:Mythag College>."
  },
  AvgDialog_10123_Content_27 = {
    Text = "Esa es exactamente donde te encuentras ahora, el predecesor de <Blue:Mythag University (Mythag University)>."
  },
  AvgDialog_10123_Content_28 = {Text = "Guardián."},
  AvgDialog_10123_Content_29 = {
    Text = "Estoy aquí."
  },
  AvgDialog_10123_Content_3 = {
    Text = "Es la primera vez que aprendo que hay un pasaje oculto debajo de la torre del reloj..."
  },
  AvgDialog_10123_Content_30 = {
    Text = "El hecho de que estés aquí de pie sin ser expulsado por Tawil muestra que tu destino está ahora inextricablemente ligado al futuro de Mythag."
  },
  AvgDialog_10123_Content_31 = {
    Text = "Entonces, eres calificado para escuchar la información que estoy a punto de compartir."
  },
  AvgDialog_10123_Content_32 = {
    Text = "Este es el secreto más profundo de la Universidad de Mitag.\nTawil—el fundador de la Universidad de Mitag—no es ni humano ni un Despertador."
  },
  AvgDialog_10123_Content_33 = {
    Text = "Él es un ser de otra dimensión. Inicialmente, solo era un susurro escuchado por el primer principal, Phillips."
  },
  AvgDialog_10123_Content_34 = {
    Text = "Contrario a la percepción de que \"Tawil es un Despertador\", la técnica de extracción de Plata y <Yellow:Despertar a los fallecidos que resuenan con la Voluntad Superior> surgieron bajo su guía."
  },
  AvgDialog_10123_Content_35 = {
    Text = "Tawil profetizó la llegada de la Disolución y el futuro de la Destrucción mundial, transmitiendo la \"Verdad\" inicial, y se quedó dormida después del establecimiento del Colegio Mitag."
  },
  AvgDialog_10123_Content_36 = {
    Text = "Según el Sr. Phillips, Tawil eligió una forma de existencia \"inexistente\" para evitar \"ser observado\"."
  },
  AvgDialog_10123_Content_37 = {
    Text = "Solo cuando aparezcan \"Variables\" Él renacerá en forma de \"Despertar\""
  },
  AvgDialog_10123_Content_38 = {Text = "¡Mira!"},
  AvgDialog_10123_Content_39 = {
    Text = "Como si presagiara la llegada de algún tabú y clades, \"Tawil\" emitió un grito penetrante que rompió tímpanos."
  },
  AvgDialog_10123_Content_4 = {
    Text = [[
Si todos lo saben, supongo que no se puede llamar un pasaje secreto.
El pasaje se conecta al <Yellow:Black Pool>, la base de Mitag.]]
  },
  AvgDialog_10123_Content_40 = {
    Text = "Con un temblor similar a un hatchling liberándose, seis enormes alas plateadas se desplegaron de Su cuerpo."
  },
  AvgDialog_10123_Content_41 = {
    Text = "Las puntas de las alas gotean gotas plateadas, que caen en la piscina negra con un suave chapoteo."
  },
  AvgDialog_10123_Content_42 = {
    Text = "Tan pronto como el líquido plateado se fusiona con la Charca Negra, las ondas surgen y cuerpos disueltos retorcidos emergen."
  },
  AvgDialog_10123_Content_43 = {
    Text = "Los monstruos deformados desafían las leyes físicas al salir de la charca negra. Algunos se lanzan hacia ti, mientras que otros se dirigen hacia la plaza fuera de la torre del reloj"
  },
  AvgDialog_10123_Content_44 = {
    Text = "<Shake:Finalmente... te encontré...>"
  },
  AvgDialog_10123_Content_45 = {
    Text = "¡Detenlo! Solo deteniéndolo podemos cortar la fuente de los monstruos"
  },
  AvgDialog_10123_Content_5 = {
    Text = "Sin el <Yellow:giant Silver> llamado <Yellow:Core> en el fondo de la Piscina Negra, depender únicamente de los débiles espíritus humanos para sustentar a los Despertadores retrocedería la tecnología del Despertador de Mitag décadas."
  },
  AvgDialog_10123_Content_6 = {
    Text = "Así que, ¿no permitir que los Despertadores sin Enlace salgan de Mythag también es por preocupación de que podríamos caer en la locura?"
  },
  AvgDialog_10123_Content_7 = {
    Text = "No del todo.\nSi tan solo cada Despertador fuera tan fácil de tratar como tú, Ogier."
  },
  AvgDialog_10123_Content_8 = {
    Text = "Está bien, hemos llegado."
  },
  AvgDialog_10123_Content_9 = {
    Text = "Mientras hablaba, la Muñeca presionó un botón poco conspicuo en la pared lateral del pasillo.\nCon un ding, la puerta se abrió, y tú entraste en el espacio estrecho y tenuemente iluminado."
  },
  AvgDialog_10124_Content_1 = {
    Text = "Parece que has encontrado tu Estado. ¡El próximo comando es tuyo, Guardián!"
  },
  AvgDialog_10125_Content_1 = {
    Text = "Uf. Lo siento, no hay tiempo para que te acostumbres a todo esto como es debido."
  },
  AvgDialog_10125_Content_10 = {
    Text = "Ramona parece aterrorizada; nunca la habías visto tan alterada."
  },
  AvgDialog_10125_Content_11 = {
    Text = "La chica, bombardeada con preguntas, habla con voz temblorosa, su fatiga es evidente."
  },
  AvgDialog_10125_Content_12 = {
    Text = "La reconoces. Es la Profesora Muñeca, conocida por ser difícil de comunicar, y pertenece al <Blue:Instituto de Investigación de Despertar>. En otras palabras, es una no combatiente."
  },
  AvgDialog_10125_Content_13 = {
    Text = "Obviamente. ¿Pensaste que vine aquí a dar un paseo tranquilo?"
  },
  AvgDialog_10125_Content_14 = {
    Text = "Cierra los ojos, recomponiéndose rápidamente."
  },
  AvgDialog_10125_Content_15 = {
    Text = "¿Fue atacada la Bóveda de Llaves? Este lugar está cerca de la puerta trasera; apresúrate y vete."
  },
  AvgDialog_10125_Content_16 = {
    Text = "¡Podemos ayudar! %player% puede enlazar a todos nosotros y luego comandar—"
  },
  AvgDialog_10125_Content_17 = {
    Text = "Ramona.\nEsas son nuestras responsabilidades, %player% es solo un recién llegado que acaba de terminar la escuela preparatoria."
  },
  AvgDialog_10125_Content_18 = {
    Text = "%player% ya se ha vinculado conmigo, y sé que {Male=he,Female=she} está a la altura de la tarea. ¡Creo en {Male=him,Female=her}!"
  },
  AvgDialog_10125_Content_19 = {
    Text = "Doll te examina con atención y luego se vuelve hacia Ramona con expresión severa."
  },
  AvgDialog_10125_Content_2 = {
    Text = "Estos Mutantes llegaron a Keygrave antes de que sonara la alarma. La <Blue:Barrera de Niebla> alrededor de Misaq debe haber caído."
  },
  AvgDialog_10125_Content_20 = {
    Text = "Si no me equivoco, la ceremonia de juramento aún no se ha completado.\n{Male=él,Female=ella} aún no ha recibido la Llave de Plata, ¿verdad?"
  },
  AvgDialog_10125_Content_21 = {
    Text = "¡A continuación, entraremos en la Zona Prohibida de Mythag. La entrada no autorizada es un delito grave, y pensé que lo sabías desde que creciste aquí."
  },
  AvgDialog_10125_Content_22 = {
    Text = "¡Es una emergencia! No tenemos opción, ¿verdad? Además, %player% no es un novato cualquiera. {Male=He's,Female=She's} nuestro único Guardián."
  },
  AvgDialog_10125_Content_23 = {
    Text = "¿No recuerdas la <Yellow:Explosión de Akut> de hace un año? Si no fuera porque {Male=him,Female=her} vinculó a todos los Cuerpos Despertados en solitario en aquel entonces, yo no estaría aquí discutiendo contigo ahora mismo."
  },
  AvgDialog_10125_Content_24 = {
    Text = "La chica de pelo rosa no responde y, en su lugar, se vuelve hacia ti."
  },
  AvgDialog_10125_Content_25 = {
    Text = "Sé que vislumbraste lo que hay más allá de la <Yellow:Puerta>; pero la realidad, ya sea los cimientos de Misaq o el destino del mundo, puede no ser como la idealizas."
  },
  AvgDialog_10125_Content_26 = {
    Text = "Enfrentamos un fenómeno que destruye la existencia material en sí misma. Una vez que estás contaminado por <Yellow:Dissolution>, todo sobre ti desaparecerá."
  },
  AvgDialog_10125_Content_27 = {
    Text = "El nombre que grabaste en la lápida durante la ceremonia de juramento también se disolverá en un charco de barro negro, olvidado por todos."
  },
  AvgDialog_10125_Content_28 = {
    Text = "Respóndeme. ¿Estás realmente preparado para esto?"
  },
  AvgDialog_10125_Content_29 = {
    Text = "La mirada gélida de Doll se encuentra con la tuya, su voz carente de emoción."
  },
  AvgDialog_10125_Content_3 = {
    Text = "Informamos a <Blue:William, el compañero mayor> sobre la ceremonia de hoy, pero no llegaron refuerzos en nuestra ayuda. La campana... ¡deberíamos reagruparnos y <Yellow:eliminar la fuente de la anomalía>!"
  },
  AvgDialog_10125_Content_30 = {
    Text = "Su rostro no delata nada, pero en lo más profundo de sus pupilas heladas, vislumbras un fuego ardiente."
  },
  AvgDialog_10125_Content_31 = {
    Text = "Tu respuesta es—"
  },
  AvgDialog_10125_Content_32 = {
    Text = "Mi lápida ahora forma parte de Keygrave."
  },
  AvgDialog_10125_Content_33 = {
    Text = "Eres miembro de Misaq. Quizás ya lo eras en Akut."
  },
  AvgDialog_10125_Content_34 = {
    Text = "Hay cosas que solo yo puedo lograr."
  },
  AvgDialog_10125_Content_35 = {
    Text = "La decisión puede ser precipitada, pero ¿acaso se puede estar verdaderamente preparado para todo en la vida?"
  },
  AvgDialog_10125_Content_36 = {Text = "Bien."},
  AvgDialog_10125_Content_37 = {
    Text = "Por la autoridad del 6.º Director de Misaq, <Blue:Oliver Elsie>, por la presente te confiero la Llave de plata K-0617."
  },
  AvgDialog_10125_Content_39 = {
    Text = "Doll saca la Llave de plata de un estuche ornamentado y la coloca sobre tu pecho. Emite un tenue resplandor, inundándote con una vaga sensación de familiaridad."
  },
  AvgDialog_10125_Content_4 = {
    Text = "¿Es eso...?"
  },
  AvgDialog_10125_Content_40 = {
    Text = "De ahora en adelante, te alzas como Guardián entre la multitud de estudiantes y eruditos de Misaq."
  },
  AvgDialog_10125_Content_41 = {Text = "..."},
  AvgDialog_10125_Content_42 = {
    Text = "Bien, ahora establece un vínculo conmigo."
  },
  AvgDialog_10125_Content_43 = {
    Text = "Activaste cautelosamente la llave de plata.\nLa luz plateada parpadea, y el vínculo espiritual conecta tus sentidos con los de la Muñeca como miles de hilos invisibles."
  },
  AvgDialog_10125_Content_44 = {
    Text = "Como si una corriente eléctrica se conectara con un \"clic\", innumerables mensajes de luz y sombra inundan tu mente.\nSacudido por intensas palpitaciones, apenas puedes mantenerte en pie."
  },
  AvgDialog_10125_Content_45 = {
    Text = "Doll, tú..."
  },
  AvgDialog_10125_Content_46 = {
    Text = "Llegaste justo a tiempo, Guardián.\nTanto Ogier como yo estamos al límite."
  },
  AvgDialog_10125_Content_47 = {
    Text = "Te quedas aquí y descansas. Ramona y yo nos uniremos a la batalla para apoyar a Ogier."
  },
  AvgDialog_10125_Content_48 = {
    Text = "Cálmate. Aunque tu espíritu pueda manejarlo, las heridas de Ramona no son adecuadas para una batalla inmediata."
  },
  AvgDialog_10125_Content_49 = {
    Text = "El niño puede aguantar un rato. Sígueme primero."
  },
  AvgDialog_10125_Content_6 = {
    Text = "En la periferia de tu visión, un joven rubio levanta un enorme escudo negro, apenas logrando repeler el asalto de una espadachina de doble espada."
  },
  AvgDialog_10125_Content_7 = {
    Text = "Protege a una chica de cabello rosa detrás de él; cada ataque desviado lo hace retroceder un paso más."
  },
  AvgDialog_10125_Content_8 = {
    Text = "Espera... el que lanza el ataque... ¿es <Yellow:Despertador> Lotan?!"
  },
  AvgDialog_10125_Content_9 = {
    Text = "¿Dor? ¿¡La <Blue:Torre del reloj> ha sido comprometida?!"
  },
  AvgDialog_10126_Content_1 = {
    Text = "Cuando la Vida cae a 0, el Poder espiritual luchará por mantener el instrumento en funcionamiento para continuar detectando <Yellow:Dominio>. Para asegurar la seguridad del personal en batalla, el instrumento te sacará forzosamente de la batalla."
  },
  AvgDialog_10126_Content_2 = {
    Text = "La situación es urgente. Ajusté la salida de energía del dispositivo basada en los signos vitales saludables del Guardián y una carga completa de Aliemus."
  },
  AvgDialog_10126_Content_3 = {
    Text = "Este método es extremadamente peligroso, pero no tenemos más remedio que arriesgarnos. ¡Ahora, usa Exaltar para acabar con esta batalla!"
  },
  AvgDialog_10127_Content_1 = {
    Text = "Qué calidez... la conexión es perfecta. Tu espíritu y fuerza vital nunca han brillado con tanta intensidad."
  },
  AvgDialog_10127_Content_2 = {
    Text = "No puedes caer fácilmente, <Yellow:el único y único en el mundo> Guardián.\nEstamos contando contigo para investigar y documentar toda la historia borrada por Disolución."
  },
  AvgDialog_10127_Content_3 = {
    Text = "La preocupación en sus ojos se desvanece mientras Ramona esboza una media sonrisa tranquilizadora."
  },
  AvgDialog_10127_Content_4 = {
    Text = "El sonido de la lluvia fina llena el mundo."
  },
  AvgDialog_10127_Content_5 = {
    Text = "<Red:Inquietud, dolor, sofocación> llenaron mi pecho cuando cayó una gota de lluvia."
  },
  AvgDialog_10127_Content_7 = {Text = "¡Ramona!"},
  AvgDialog_10127_Content_9 = {
    Text = "La campana suena."
  },
  AvgDialog_10128_Content_1 = {
    Text = "Ten cuidado, ¡el oponente ha adoptado una fuerte postura ofensiva!"
  },
  AvgDialog_10128_Content_2 = {
    Text = "¿De qué tienes miedo? Todavía estoy aquí.\nGuardián, déjame realizar <Yellow:\"Cirugía Externa\">."
  },
  AvgDialog_10129_Content_1 = {
    Text = "Activa la Llave de Plata, %player%."
  },
  AvgDialog_10129_Content_2 = {
    Text = "La Llave de Plata parpadea, y una visión fugaz aparece de repente, fusionándose gradualmente con la realidad ante los ojos de uno."
  },
  AvgDialog_10129_Content_3 = {
    Text = "Mareo, pensamientos borrosos, una sirena aullando en la cabeza, y la voz de la Muñeca comenzó a desvanecerse..."
  },
  AvgDialog_10129_Content_4 = {
    Text = "Luchas por calmar tu mente, discerniendo la información proporcionada por la Muñeca a partir del bullicio caótico."
  },
  AvgDialog_10129_Content_5 = {
    Text = "¿Lo ves? Ante ti está el Dominio—una área especial formada por <Yellow:Dimensión del Sueño> y <Yellow:Dimensión de la Realidad>."
  },
  AvgDialog_10129_Content_6 = {
    Text = "Mitag proyectó parte de <Blue:Intersección> en el Dominio para estabilizar las mentes cada vez más locas de los Investigadores y sanar a los Despertadores."
  },
  AvgDialog_10129_Content_7 = {
    Text = "Sin embargo, la interferencia humana tiene efectos limitados en el dominio, así que no podemos garantizar la posición de <Blue:Junction>. Todo depende de tu adaptabilidad."
  },
  AvgDialog_10129_Content_8 = {
    Text = "Ve a la <Blue:Intersección> más cercana y ayuda a curar las heridas de Ramona."
  },
  AvgDialog_10130_Content_10 = {
    Text = "Mientras nuestros nombres estén grabados en el monumento, nuestra existencia no será borrada por @2."
  },
  AvgDialog_10130_Content_11 = {
    Text = "Una suave voz entrelazada con chillidos distorsionados resuena en tu mente."
  },
  AvgDialog_10130_Content_12 = {
    Text = "Seré tu asistente, acompañándote hasta el final de este camino... <Yellow:Que la Llave de Plata ilumine tu camino.>"
  },
  AvgDialog_10130_Content_13 = {
    Text = "¿Estás bien, %player%? Estás un poco pálido/a. ¿Deberíamos pasar por la enfermería?"
  },
  AvgDialog_10130_Content_14 = {
    Text = "Su voz clara trajo claridad a la mente, y el mareo fue disminuyendo gradualmente."
  },
  AvgDialog_10130_Content_15 = {
    Text = "¡No te preocupes, solo un poco mareado, pero ya está mejor!"
  },
  AvgDialog_10130_Content_16 = {
    Text = "Hmm, solo para estar seguros, mantengámonos conectados.\nComo tu asistente y compañero, es mi deber comprobar siempre tu Estado."
  },
  AvgDialog_10130_Content_17 = {
    Text = "¿Ahora mismo? ¿Aquí afuera?"
  },
  AvgDialog_10130_Content_18 = {
    Text = "Quizá sea un poco antes de lo planeado, pero no debería importar, ¿verdad?"
  },
  AvgDialog_10130_Content_19 = {
    Text = "Además, llevo más de un año esperando este día."
  },
  AvgDialog_10130_Content_2 = {
    Text = "Bienvenido a la Universidad Mythag, %player%."
  },
  AvgDialog_10130_Content_21 = {
    Text = "Las gotas de lluvia se deslizan dentro de tus guantes, mojándote las yemas de los dedos. Una corriente tenue se filtra a través del material, fluyendo en secreto entre tu piel y la de ella."
  },
  AvgDialog_10130_Content_22 = {
    Text = "Emociones inexplicables recorren tus nervios: alegría, emoción, inquietud y..."
  },
  AvgDialog_10130_Content_23 = {
    Text = "...<Yellow:Esperanza>."
  },
  AvgDialog_10130_Content_3 = {
    Text = "¿O más bien... bienvenido, has cruzado oficialmente al lado oculto del mundo."
  },
  AvgDialog_10130_Content_4 = {Text = "He vuelto."},
  AvgDialog_10130_Content_5 = {
    Text = "Tu unión es lo que todos han estado esperando. En dos días, William nos asignará una <Yellow:Clades Investigación Tarea>."
  },
  AvgDialog_10130_Content_6 = {
    Text = "Él no te perdonará, un Guardián que aparece una vez cada siglo."
  },
  AvgDialog_10130_Content_7 = {
    Text = "Espero que tu asignación de campo @1 no dependa tanto de mí, el <Blue:>, como un curso de cálculo."
  },
  AvgDialog_10130_Content_8 = {
    Text = "Nunca pensé que asistiría a mi propio funeral."
  },
  AvgDialog_10130_Content_9 = {
    Text = "Abraza la muerte, para que ya no la temamos."
  },
  AvgDialog_10131_Content_1 = {
    Text = "Ahora, Ogier y yo estamos entrando en la batalla."
  },
  AvgDialog_10131_Content_2 = {
    Text = "Puedo sentir a través del enlace que tu condición y la de Ogier aún no son suficientes para"
  },
  AvgDialog_10131_Content_3 = {
    Text = "Está bien, Guardián.\n¡Los caballeros existen para proteger a todos, y Ogier puede aguantar!"
  },
  AvgDialog_10131_Content_4 = {
    Text = "No te preocupes. Con tú aquí estabilizando nuestras mentes, no perderemos el control y podremos aprovechar al máximo Aliemus."
  },
  AvgDialog_10131_Content_5 = {
    Text = "Mientras reúna suficiente Aliemus, puedo recuperar mi Estado."
  },
  AvgDialog_10131_Content_6 = {
    Text = "No dudes más, Guardián.\nSi podemos romper el cerco depende de tu comando."
  },
  AvgDialog_10131_Content_7 = {
    Text = "¡Déjame presenciar por mí mismo la valía de este prodigio en el que Misaq deposita su futuro!"
  },
  AvgDialog_10132_Content_1 = {
    Text = "Hmph, ¿crees que puedes destruir este planeta?"
  },
  AvgDialog_10132_Content_2 = {
    Text = "¡Lejos de ser suficiente! ¡Dale, no importa cuánto más haya!"
  },
  AvgDialog_10133_Content_1 = {
    Text = "¿Es... ¿ya terminó...?"
  },
  AvgDialog_10133_Content_10 = {
    Text = "Ella extendió la mano y tocó ligeramente la Llave de Plata en tu pecho"
  },
  AvgDialog_10133_Content_11 = {
    Text = "La Llave de Plata parpadea una respuesta tenue."
  },
  AvgDialog_10133_Content_12 = {
    Text = "Eres la variable, la respuesta tanto al principio como al final."
  },
  AvgDialog_10133_Content_13 = {
    Text = "Con suerte, eres el punto de inflexión..."
  },
  AvgDialog_10133_Content_15 = {
    Text = "Monstruos blancos de seis alas, una mujer con una expresión indiferente, monstruos de barro dispersándose en un asalto, formas sombrías de Despertadores retorcidas..."
  },
  AvgDialog_10133_Content_16 = {
    Text = "Se convirtieron en un charco de agua negra y luego desaparecieron sin dejar rastro."
  },
  AvgDialog_10133_Content_17 = {
    Text = "Ignorando las llamadas de Ramona y Muñeca, miras hacia arriba mientras sostienes la llave de plata, mirando hacia la \"puerta\" que lleva de regreso a \"Tawil.\""
  },
  AvgDialog_10133_Content_18 = {
    Text = "Recuerdas claramente la cara que acabas de ver.\nLa expresión indiferente, los contornos de las cejas y los ojos, y la curva de los labios se parecen a Ramona—"
  },
  AvgDialog_10133_Content_19 = {
    Text = "—Exactamente la misma."
  },
  AvgDialog_10133_Content_2 = {
    Text = "\"Tawil\" sigue de pie, pero ya no con la misma compostura."
  },
  AvgDialog_10133_Content_20 = {
    Text = "Dos días después\n\nTumba de la clave"
  },
  AvgDialog_10133_Content_21 = {
    Text = "...La Universidad Mythag es pionera en la lucha contra la Disolución, sirviendo como una línea de defensa crucial para el futuro de la humanidad."
  },
  AvgDialog_10133_Content_22 = {
    Text = "Durante 300 años, la Universidad Mythag ha pagado un alto precio para proteger la paz de la humanidad de la Disolución."
  },
  AvgDialog_10133_Content_23 = {
    Text = "Este cementerio es nuestro lugar de descanso preparado, y también la determinación de los maestros y estudiantes de Mythag de sacrificar sus vidas por la supervivencia de la humanidad."
  },
  AvgDialog_10133_Content_24 = {
    Text = "El discurso continuó. Czort cerró los ojos y suspiró, la niebla blanca de su aliento disipándose en la lluvia."
  },
  AvgDialog_10133_Content_25 = {
    Text = "...Creo que, entre todos los nuevos estudiantes, ninguno puede comprender el peso de estas palabras mejor que tú."
  },
  AvgDialog_10133_Content_26 = {
    Text = "Durante los últimos 300 años, anomalías como los Silvers y los Mutantes de Disolución han surgido ocasionalmente en el Pozo Negro, pero una mutación de esta magnitud es sin precedentes."
  },
  AvgDialog_10133_Content_27 = {
    Text = "Muchos nunca regresaron."
  },
  AvgDialog_10133_Content_28 = {
    Text = "La oradora es Czort, la Decana Interina de Ciencias de la Vida de Mythag. Se rumorea que puede ver seres de otro mundo y fue la estudiante favorita del exdecano."
  },
  AvgDialog_10133_Content_29 = {
    Text = "Los eventos relacionados con la Disolución siempre vienen con sorpresas, locura y muerte. Esta es una experiencia inevitable en nuestro camino."
  },
  AvgDialog_10133_Content_3 = {
    Text = "Antes de que alguien más pudiera reaccionar, de repente extendió sus alas plateadas y se lanzó hacia Ramona."
  },
  AvgDialog_10133_Content_30 = {
    Text = "Comprendes el significado detrás de las palabras de Czort.\nNo hay nadie debajo de la tumba frente a ti."
  },
  AvgDialog_10133_Content_31 = {
    Text = "La baba negra fluye lentamente sobre la lápida."
  },
  AvgDialog_10133_Content_32 = {Text = "..."},
  AvgDialog_10133_Content_33 = {
    Text = "Después de la ceremonia, el Noble Dexter te invitó a su oficina."
  },
  AvgDialog_10133_Content_34 = {
    Text = "El nombre \"Dexter\" te resulta familiar; es el apellido de Ramona.\nEste \"Noble Dexter\" es tu profesor y también el padre adoptivo de Ramona."
  },
  AvgDialog_10133_Content_35 = {
    Text = "Vi esta parte en el informe, y necesito pedirte un favor."
  },
  AvgDialog_10133_Content_36 = {
    Text = "Acerca de la apariencia de Tawil... ¿podrías mantenerlo en secreto de Ramona?"
  },
  AvgDialog_10133_Content_37 = {
    Text = "¿Por qué?"
  },
  AvgDialog_10133_Content_38 = {
    Text = "¿Cómo debería ponerlo...? La causalidad detrás de esto es bastante compleja y difícil de explicar brevemente."
  },
  AvgDialog_10133_Content_39 = {
    Text = "Sin embargo, le haré saber más pronto que tarde, solo que no en este momento."
  },
  AvgDialog_10133_Content_4 = {
    Text = "El tiempo parece haberse detenido."
  },
  AvgDialog_10133_Content_40 = {
    Text = "Esto no se debe a consideraciones de confidencialidad de Mythag, sino a la solicitud de un padre para proteger a su hija."
  },
  AvgDialog_10133_Content_41 = {
    Text = "Por favor, dennos algo de tiempo, ¿de acuerdo?"
  },
  AvgDialog_10133_Content_42 = {
    Text = "Aunque deseas conocer la verdad, aún asientes en señal de acuerdo."
  },
  AvgDialog_10133_Content_43 = {
    Text = "Gracias por tu comprensión.\nHablando de eso, recientemente llegó un lote de whisky de mezcla real. Logré que alguien guardara dos botellas en secreto."
  },
  AvgDialog_10133_Content_44 = {
    Text = "Aquí, tómalo e invita a Ramona a probar el sabor de la adultez — considérelo tu ritual de iniciación exclusivo, ¿qué te parece?"
  },
  AvgDialog_10133_Content_45 = {
    Text = "Tengo miedo de que es inapropiado, Noble Dexter.\nLa Disolución no dejará de propagarse mientras descansemos."
  },
  AvgDialog_10133_Content_46 = {
    Text = "¡Oh no, William ha encontrado su camino aquí!\nMe temo que no puedo salvarte ahora, pequeño."
  },
  AvgDialog_10133_Content_47 = {
    Text = "El dossier ha sido organizado. Ya puedes prepararte para el deber, nuevo Guardián."
  },
  AvgDialog_10133_Content_48 = {
    Text = "Que la Llave de plata ilumine mi camino."
  },
  AvgDialog_10133_Content_5 = {
    Text = "Sprints a tu máxima velocidad, apenas logrando proteger a Ramona."
  },
  AvgDialog_10133_Content_6 = {
    Text = "El monstruo blanco te mira directamente."
  },
  AvgDialog_10133_Content_7 = {
    Text = "Te observa silenciosamente con su cuerpo pálido y sin rostro."
  },
  AvgDialog_10133_Content_9 = {
    Text = "Ante ti aparece el rostro de una mujer con una expresión indiferente."
  },
  AvgDialog_10134_Content_1 = {
    Text = "¡Oye, tú! Date prisa y déjame desatar <Yellow:\"Blade of Defiance\">."
  },
  AvgDialog_10134_Content_2 = {
    Text = "Espera, Guardián.\nPrimero, libera \"Golpe\", encendiendo la sed de sangre de Lotan, lo que puede reducir el consumo de Aritmética de <Yellow:\"Espada de la Desafiante\">."
  },
  AvgDialog_10134_Content_3 = {
    Text = "La combinación correcta de comandos puede duplicar la efectividad de nuestros ataques.\nLas tácticas están ocultas dentro de los comandos, Guardián. Piensa cuidadosamente."
  },
  AvgDialog_10135_Content_1 = {
    Text = "Ten cuidado, ¡no te acerques más! ¡Mi escudo está a punto de romperse!"
  },
  AvgDialog_10135_Content_10 = {
    Text = "Sabes, nadie más puede hacer esto excepto yo."
  },
  AvgDialog_10135_Content_11 = {
    Text = "Cuando me alaban, es \"una vez en un siglo\", pero cuando llega una verdadera crisis, me tratan como a un jarrón. No es justo."
  },
  AvgDialog_10135_Content_12 = {
    Text = "Algunos riesgos deben ser enfrentados."
  },
  AvgDialog_10135_Content_13 = {
    Text = "No tenemos elección. Demasiadas personas aquí han perdido el control. Si no resistimos, seremos consumidos por la locura."
  },
  AvgDialog_10135_Content_14 = {
    Text = "Además, los dos solos no podemos romper el cerco en la torre del reloj.\nNecesitamos ayuda. Necesitamos el poder para controlar a los Despertadores."
  },
  AvgDialog_10135_Content_15 = {
    Text = "Ramona, apóyame."
  },
  AvgDialog_10135_Content_16 = {
    Text = "Desde que estás tan decidido... como tu \"compañero\", no tengo razón para detenerte más."
  },
  AvgDialog_10135_Content_17 = {
    Text = "¡Ramona, siempre lista para la batalla!"
  },
  AvgDialog_10135_Content_2 = {
    Text = "Con un \"clang\", las espadas gemelas de Lotan hicieron añicos el enorme escudo formado por lodo negro una vez más."
  },
  AvgDialog_10135_Content_3 = {
    Text = "¡No es suficiente, no es suficiente! ¡Desata la tormenta! ¡Dame una batalla emocionante!"
  },
  AvgDialog_10135_Content_4 = {
    Text = "El Despertador llamado Lotan empuñó sus espadas gemelas, asaltando implacablemente a Ogier. La pura fuerza de sus ataques reveló una dura realidad—ella había perdido completamente el control."
  },
  AvgDialog_10135_Content_5 = {
    Text = "Dada la situación, solo podemos..."
  },
  AvgDialog_10135_Content_6 = {
    Text = "Ramona, ¡ayúdame a someter a Lotan!"
  },
  AvgDialog_10135_Content_7 = {
    Text = "No puedes estar pensando en..."
  },
  AvgDialog_10135_Content_8 = {
    Text = "¡La enlazaré!"
  },
  AvgDialog_10135_Content_9 = {
    Text = "No bromes, la pérdida de control de un Despertador resuena con el Investigador a través del Enlace, incluso tú—"
  },
  AvgDialog_10136_Content_1 = {
    Text = "Esto es... la orgullosa <Yellow:\"Espada de la Desafío\"> de Lotan, ¡capaz de lanzar múltiples ataques instantáneamente!"
  },
  AvgDialog_10136_Content_2 = {
    Text = "Para contrarrestar este movimiento... usa <Yellow:\"Análisis Ofensivo\"> para evitar puntos débiles críticos. Esto es más seguro."
  },
  AvgDialog_10137_Content_1 = {
    Text = "¡No puedes detenerme! ...Humanos sin vergüenza..."
  },
  AvgDialog_10137_Content_2 = {
    Text = "Tocas la recién adquirida Llave de Plata, sintiendo una ligera vibración que te insta a completar la Resonancia con Lotan."
  },
  AvgDialog_10137_Content_4 = {
    Text = "<Shake:Si tan solo lo hubiera sabido... Nunca habría aceptado un pacto contigo...>"
  },
  AvgDialog_10137_Content_5 = {
    Text = "Ramona se acercó a Lotan y extendió su mano."
  },
  AvgDialog_10137_Content_6 = {
    Text = "Sé, cuando te despertaste, Mitag prometió luchar a tu lado... Batallar hasta el final de este planeta."
  },
  AvgDialog_10137_Content_7 = {
    Text = "Nunca tuvimos la intención de romper nuestra promesa. Durante los últimos 300 años y los próximos 300 años, continuaremos llevando esta carga."
  },
  AvgDialog_10137_Content_8 = {
    Text = "Lotan, la intensa batalla que has estado esperando está justo ante tus ojos."
  },
  AvgDialog_10138_Content_1 = {
    Text = "Mantente alerta, está a punto de atacar. Este daño podría ser fatal para mí en este momento."
  },
  AvgDialog_10138_Content_2 = {
    Text = "Confía en que tomarás la decisión correcta. Para la acción de este turno, elige <Yellow:\"Defensa\">."
  },
  AvgDialog_10139_Content_1 = {
    Text = "Gracias, Guardián. Me has salvado una vez más.\nSi no fuera por este Enlace, probablemente estaría en grave peligro en este momento."
  },
  AvgDialog_10139_Content_2 = {
    Text = "Ahora no es el momento de hablar de esto—"
  },
  AvgDialog_10139_Content_3 = {
    Text = "Mientras hablas, la anomalía negro azabache se extiende a tu alrededor.\nLos gritos resuenan continuamente mientras tus compañeros de clase de ayer se convierten en lodo negro uno por uno."
  },
  AvgDialog_10139_Content_4 = {
    Text = "He compartido la <Yellow:intención> del enemigo detectada por la Llave de Plata a través del enlace. ¡Cuidado, está a punto de atacar!"
  },
  AvgDialog_10140_Content_1 = {
    Text = "¿Sientes el Aliemus fluyendo a través de mí, Guardián?\nGracias a tu supresión con poder espiritual, de lo contrario me habría llevado a la Locura como Lotan."
  },
  AvgDialog_10140_Content_2 = {
    Text = "Sin embargo, ahora puede sernos de utilidad."
  },
  AvgDialog_10140_Content_3 = {
    Text = "Mira hacia la dirección donde fluye Aliemus... Sí, mira hacia la <Blue:parte superior izquierda> del dispositivo de comando."
  },
  AvgDialog_10140_Content_4 = {
    Text = "¡Desata Exaltar y abraza mi <Yellow:\"Mundus Deduction\">! \nDurante la batalla contra Disolución, <Yellow:solo una respuesta racional a la ofensiva puede asegurar la mayor posibilidad de supervivencia>."
  },
  AvgDialog_10141_Content_1 = {
    Text = "Maldita sea, Lotan está a punto de desatar <Yellow:Exaltar>... Con solo estos comandos..."
  },
  AvgDialog_10141_Content_2 = {
    Text = "La Llave de Plata se conecta con tu espíritu, resonando de manera única con tus fuertes percepciones y recuerdos, generando un poder distintivo."
  },
  AvgDialog_10141_Content_3 = {
    Text = "¡Mira en la <Blue:parte inferior izquierda> del dispositivo de comando! La llave plateada está completamente cargada y la <Yellow:pertenencia> está lista."
  },
  AvgDialog_10141_Content_4 = {
    Text = "Agarra la Llave de Plata, canta el texto secreto... desata <Yellow:Posse>, ¡y dame más espacio táctico!"
  },
  AvgDialog_10142_Content_2 = {
    Text = "No te distraigas durante una ceremonia tan importante, <Yellow:Guardián>, te otorgarán la Llave de Plata a continuación."
  },
  AvgDialog_10142_Content_3 = {
    Text = "Levanta tu lápida para probar nuestra resolución de luchar <Yellow:contra la Disolución>—una tradición de Mitag, marcando el final del pre-estudio y convirtiéndose en Investigadores oficiales."
  },
  AvgDialog_10142_Content_4 = {
    Text = "Si estás listo, graba tu nombre en la lápida."
  },
  AvgDialog_116003_Content_1 = {
    Text = "A medida que el árbol de casa que te pertenece se desmorona, todo a tu alrededor también se derrite en la distorsión."
  },
  AvgDialog_116003_Content_10 = {
    Text = "Pero no quiero que esto sea solo un sueño."
  },
  AvgDialog_116003_Content_11 = {
    Text = "Quiero volver a Misaq y verlos de nuevo."
  },
  AvgDialog_116003_Content_12 = {
    Text = "......una respuesta esperada."
  },
  AvgDialog_116003_Content_13 = {
    Text = "Pero esta vez, después de que mostraste tu determinación, finalmente puedo estar tranquilo."
  },
  AvgDialog_116003_Content_14 = {
    Text = "%player%, tu voluntad es aún más resistente y poderosa de lo que imaginaba... suficiente para resistirlo a Él y el caos y la locura de este mundo."
  },
  AvgDialog_116003_Content_15 = {
    Text = "Sacudes la cabeza, mirando a Clementine en el hermoso sueño que está a punto de romperse por completo."
  },
  AvgDialog_116003_Content_16 = {
    Text = "No, te equivocas, la voluntad de una persona siempre tiene un límite."
  },
  AvgDialog_116003_Content_17 = {
    Text = "He podido perseverar hasta ahora gracias al apoyo de todos los que me apoyan en Misaq."
  },
  AvgDialog_116003_Content_18 = {
    Text = "Ellos de \"ese mundo\" han construido este hermoso sueño para ti, y tú, decidido a convertir este sueño en realidad en este mundo."
  },
  AvgDialog_116003_Content_19 = {
    Text = "Al escuchar tus palabras y ver tu expresión seria, Clementine sonrió, mostrando una sonrisa relajada."
  },
  AvgDialog_116003_Content_2 = {
    Text = "Has roto con tus propias manos tu hermoso sueño."
  },
  AvgDialog_116003_Content_20 = {
    Text = "Sí, todavía tienes \"ellos\", y Tawil... así como yo."
  },
  AvgDialog_116003_Content_21 = {
    Text = "Es cierto. Nunca he estado solo."
  },
  AvgDialog_116003_Content_22 = {
    Text = "En un paisaje que se disuelve constantemente, se escuchó un grito, era la respuesta de Tawil a tus palabras.\nElla siempre ha estado ahí."
  },
  AvgDialog_116003_Content_23 = {
    Text = "Entonces, ahora, %player%, tu hermoso sueño realmente ha terminado."
  },
  AvgDialog_116003_Content_24 = {
    Text = "Como agradecimiento por tu cooperación en este tratamiento, te regalo un pequeño regalo, espero que te guste."
  },
  AvgDialog_116003_Content_25 = {
    Text = "Con las últimas palabras de Clementine, el sueño se hizo añicos por completo——"
  },
  AvgDialog_116003_Content_26 = {
    Text = "El sol negro cuelga alto en el cielo frente a ti, trayendo niebla gris y la brutalidad de este mundo."
  },
  AvgDialog_116003_Content_27 = {
    Text = "Y en la palma de tu mano, reposa en silencio una foto.\nUna foto tomada en un \"Falso Sueño Hermoso\", que no debería existir en la cruel realidad."
  },
  AvgDialog_116003_Content_28 = {
    Text = "Junto al mar, voleibol, jolgorio, la única diferencia con mis recuerdos es Ramona."
  },
  AvgDialog_116003_Content_29 = {
    Text = "Un rostro familiar sonríe en calma, como si hubiera cruzado el tiempo y el espacio, mirándote a los ojos. \n Como si estuviera justo frente a ti."
  },
  AvgDialog_116003_Content_3 = {
    Text = "Desde que decidí construir este sueño con su fuerza, supe que este día finalmente llegaría."
  },
  AvgDialog_116003_Content_30 = {
    Text = "<Small:Ramona......>"
  },
  AvgDialog_116003_Content_31 = {
    Text = "Pones la mano sobre la foto, sintiendo una mezcla de emoción y confusión."
  },
  AvgDialog_116003_Content_32 = {
    Text = "<Shake:¿Por qué tiene que ser Ramona...?>"
  },
  AvgDialog_116003_Content_33 = {
    Text = [[
Tus dudas no reciben respuesta.
En el mundo cubierto de niebla gris, solo el silencioso sol negro permanece inalterado.]]
  },
  AvgDialog_116003_Content_34 = {
    Text = "Sin importar cómo..."
  },
  AvgDialog_116003_Content_35 = {
    Text = "Colocas la foto sobre tu pecho, en la posición del corazón, y cierras los ojos."
  },
  AvgDialog_116003_Content_36 = {
    Text = "Independientemente de cualquier cosa, no estoy solo."
  },
  AvgDialog_116003_Content_37 = {
    Text = "Luego, abres los ojos y miras hacia el sol negro que cuelga alto, avanzando firmemente."
  },
  AvgDialog_116003_Content_38 = {
    Text = "Este mundo sigue colapsando, observado por horrores indescriptibles, tambaleándose al borde, pero..."
  },
  AvgDialog_116003_Content_39 = {
    Text = "<Big:Eventualmente encontrarás una manera de salvarlo>"
  },
  AvgDialog_116003_Content_4 = {
    Text = "Simplemente no esperaba que llegara tan rápido, ni que fueras tan resuelto."
  },
  AvgDialog_116003_Content_5 = {
    Text = "En realidad... he dudado y he escapado. Cuando estaba en la playa."
  },
  AvgDialog_116003_Content_6 = {
    Text = "Entonces, ¿por qué no seguir hundiéndose en esto? ¿No es lo suficientemente hermoso, no es lo suficientemente feliz aquí?"
  },
  AvgDialog_116003_Content_7 = {
    Text = "Guardas silencio, recordando tu pintura del hombre árbol."
  },
  AvgDialog_116003_Content_8 = {
    Text = "Indudablemente, este es realmente un sueño hermoso. Pero..."
  },
  AvgDialog_116003_Content_9 = {
    Text = "Poco a poco, la escena en tu mente ya no es una pintura, sino el verdadero Misaq, el verdadero Doll, Ramona, Lotan y Ogier."
  },
  AvgDialog_117499_Content_1 = {
    Text = "<Shake:Demasiado...>"
  },
  AvgDialog_117499_Content_2 = {
    Text = "Bajo el oscuro cielo, la tormenta de cardumen parece interminable. Miras a tu alrededor, una escalera de metal oxidado cuelga en la esquina, y te acercas con cuidado a la plataforma del segundo piso a lo largo de ella."
  },
  AvgDialog_117499_Content_3 = {
    Text = "Aquí podemos escondernos por un tiempo."
  },
  AvgDialog_117499_Content_4 = {
    Text = "Una corriente de aire engañosa, acompañada de un sonido de fricción que hace que tus dientes se estremezcan, capturó tu atención."
  },
  AvgDialog_117499_Content_5 = {
    Text = "Espera, ¿eso allá es...?"
  },
  AvgDialog_117500_Content_1 = {Text = "Esclavitud"},
  AvgDialog_117500_Content_10 = {Text = "..."},
  AvgDialog_117500_Content_100 = {
    Text = "Murphy sacudió la cabeza con desánimo, sus ojos vacíos buscaban sin vida tu posición.\nTe miró, apretando sus labios agrietados por la falta de sangre, forzando una sonrisa desoladora."
  },
  AvgDialog_117500_Content_101 = {
    Text = "Has venido... pensé que... nunca podría verte..."
  },
  AvgDialog_117500_Content_102 = {
    Text = "El casco del barco se inclinó bruscamente, y el agua salada y helada inundó la cabina."
  },
  AvgDialog_117500_Content_103 = {
    Text = "¿Qué está pasando?!"
  },
  AvgDialog_117500_Content_104 = {
    Text = "¿El barco chocó contra un arrecife?"
  },
  AvgDialog_117500_Content_105 = {
    Text = "Imposible, el casco del Paradeis está demasiado sumergido en el agua; incluso si la cabina choca contra un arrecife y tiene fugas, no podría inundarse hasta arriba en tan poco tiempo..."
  },
  AvgDialog_117500_Content_106 = {
    Text = "A menos que..."
  },
  AvgDialog_117500_Content_107 = {
    Text = "William se apresuró hacia la escotilla; el espectáculo ante él era tan absurdo como el más salvaje de los delirios. El Paradeis se estaba hundiendo a una velocidad increíble."
  },
  AvgDialog_117500_Content_108 = {
    Text = "Como si una ballena gigante estuviera tirando del pequeño barco, con una fuerza inmensa e ineludible, arrastrando el Paradeis hacia el fondo del mar a gran velocidad."
  },
  AvgDialog_117500_Content_109 = {Text = "Ah—"},
  AvgDialog_117500_Content_11 = {
    Text = "Vuelves a abrir los ojos. Suave, cálido, familiar."
  },
  AvgDialog_117500_Content_110 = {
    Text = "Bajo los temblores violentos, la cadena que atravesaba la palma de Murphy de repente se rompió."
  },
  AvgDialog_117500_Content_111 = {
    Text = "Una mano suave y húmeda te busca y se posa sobre el dorso de tu mano. Ella soporta el dolor de la herida que atraviesa su palma, te agarra suavemente la mano y se encuentra contigo en una mirada."
  },
  AvgDialog_117500_Content_112 = {
    Text = "Ella murmuró, sus palabras llevaban un sabor a óxido, sin saber si era por el agua de mar o por la sangre."
  },
  AvgDialog_117500_Content_113 = {
    Text = "¡Sálvame... si eres tú, seguro que puedes..."
  },
  AvgDialog_117500_Content_114 = {
    Text = "Las últimas palabras, junto con el agua del mar que inundaba el camarote, se hundieron en la oscuridad."
  },
  AvgDialog_117500_Content_12 = {
    Text = "<Small:¿De verdad tenemos que quedarnos aquí esperando a que este tipo despierte?>"
  },
  AvgDialog_117500_Content_13 = {
    Text = "<Small:Goliath, no debes dudar de los órdenes de la Madre divina.>"
  },
  AvgDialog_117500_Content_14 = {
    Text = "<Small:Sea un poco más discreto, señor Goliat, esta mañana, la madre divina llamó a la señora maestra para reprenderla un buen rato...>"
  },
  AvgDialog_117500_Content_15 = {
    Text = "Una disputa en voz baja se escucha desde detrás del velo."
  },
  AvgDialog_117500_Content_16 = {
    Text = "*Tos, tos...*"
  },
  AvgDialog_117500_Content_17 = {
    Text = "¿Despertaste? Todos te están esperando."
  },
  AvgDialog_117500_Content_18 = {
    Text = "Faros comenzó a levantar el velo."
  },
  AvgDialog_117500_Content_19 = {
    Text = "¿Esto es... que me han salvado otra vez?"
  },
  AvgDialog_117500_Content_2 = {
    Text = "......¿Araña?"
  },
  AvgDialog_117500_Content_20 = {
    Text = "El que escapó del desastre. No estamos obligados a responder todas tus preguntas."
  },
  AvgDialog_117500_Content_21 = {
    Text = "Por mandato de la Madre divina, el Marchador de mares ha esperado su despertar durante mucho tiempo."
  },
  AvgDialog_117500_Content_22 = {
    Text = "Este es el jugo de limón que la Madre divina me ordenó exprimir. Bébelo con gratitud, humano."
  },
  AvgDialog_117500_Content_23 = {
    Text = "Dado que Él está a salvo y en buen estado, regresaré a mi puesto como guía. El Reino Divino me está llamando."
  },
  AvgDialog_117500_Content_24 = {Text = "..."},
  AvgDialog_117500_Content_25 = {Text = "..."},
  AvgDialog_117500_Content_26 = {
    Text = "¿Es un evento real, o es solo una pesadilla de cuando me ahogué...?"
  },
  AvgDialog_117500_Content_27 = {
    Text = "(Es necesario encontrar una manera de verificarlo.)"
  },
  AvgDialog_117500_Content_28 = {
    Text = "Si no recuerdo mal, la última persona que vi..."
  },
  AvgDialog_117500_Content_29 = {
    Text = "Has pisado la cubierta."
  },
  AvgDialog_117500_Content_3 = {
    Text = "Una pequeña araña de color púrpura oscuro te mira con sus grandes ojos. Al verte despertar, levanta una de sus patas delanteras y te saluda."
  },
  AvgDialog_117500_Content_30 = {
    Text = "<Shake:¡Hola—William, el compañero mayor—>"
  },
  AvgDialog_117500_Content_31 = {
    Text = "<Shake:Deja de esconderte—sé que estás aquí—>"
  },
  AvgDialog_117500_Content_32 = {
    Text = "En la cubierta solo se escucha el sonido de las tranquilas mareas, tu grito se difunde en la niebla de la mañana."
  },
  AvgDialog_117500_Content_33 = {
    Text = "(Está bien, fue solo un sueño mío...)"
  },
  AvgDialog_117500_Content_34 = {Text = "¡Uwa!"},
  AvgDialog_117500_Content_35 = {
    Text = "La cubierta bajo tus pies oculta una trampilla que se abre de repente, y caes en la oscuridad con un golpe."
  },
  AvgDialog_117500_Content_36 = {
    Text = "Un manojo de paja amortiguó el impacto de tu caída."
  },
  AvgDialog_117500_Content_37 = {
    Text = "Hace mucho que no nos vemos, Guardián del Secreto."
  },
  AvgDialog_117500_Content_38 = {
    Text = "Me conoces... eres el hermano William del mundo original..."
  },
  AvgDialog_117500_Content_39 = {
    Text = "William ignoró el tono sorprendido de tu voz, en cambio, su expresión se oscureció."
  },
  AvgDialog_117500_Content_4 = {
    Text = "Capas de gasa y terciopelo se apilan sobre la cubierta oxidada. La mujer que sostiene la rueca te observa fijamente."
  },
  AvgDialog_117500_Content_40 = {
    Text = "No recuerdo haberte enseñado en Misaq a actuar de manera tan ostentosa en el bastión del enemigo."
  },
  AvgDialog_117500_Content_41 = {
    Text = "Incluso el decano Czort, conocido por su temeridad, probablemente no apoyaría tu elección."
  },
  AvgDialog_117500_Content_42 = {
    Text = "El familiar aroma de pino, la postura erguida familiar, el tono severo familiar."
  },
  AvgDialog_117500_Content_43 = {
    Text = "William, el compañero mayor..."
  },
  AvgDialog_117500_Content_44 = {
    Text = "No tenía la intención de aparecer ante ti hasta que se resolvieron los problemas clave."
  },
  AvgDialog_117500_Content_45 = {
    Text = "Pero tu imprudencia me obliga a cambiar mi estrategia."
  },
  AvgDialog_117500_Content_46 = {
    Text = "¿Sabes que siempre te he estado persiguiendo?"
  },
  AvgDialog_117500_Content_47 = {
    Text = "William no respondió a esta pregunta, solo te lanzó una mirada aguda que decía \"¿Crees que soy un idiota?\"."
  },
  AvgDialog_117500_Content_48 = {
    Text = "Ya estamos en el mismo barco, y es probable que no haya forma de evitarlo. Mejor aclaro la situación directamente para evitar complicaciones innecesarias."
  },
  AvgDialog_117500_Content_49 = {
    Text = "Antes de eso, ¿podrías compartir la información que posees?"
  },
  AvgDialog_117500_Content_5 = {
    Text = "Esta vez, no suspiró ni habló, solo guardó silencio."
  },
  AvgDialog_117500_Content_50 = {Text = "..."},
  AvgDialog_117500_Content_51 = {Text = "..."},
  AvgDialog_117500_Content_52 = {
    Text = "Desde el cerebro hecho por Fusión·Doll, hasta quedar atrapado en el sanatorio mental de Clementine, luego a los paisajes de Necrovia, y finalmente en el \"Sueño\" experimentado en Paradeis."
  },
  AvgDialog_117500_Content_53 = {
    Text = "Vas a relatar todo lo que has visto, William asiente con seriedad, escuchando atentamente y asintiendo de vez en cuando para mostrar que está concentrado."
  },
  AvgDialog_117500_Content_54 = {
    Text = "Cuando se trató del joven William que habías visto, dudaste por un momento, pero William simplemente levantó la mano, indicándote que continuaras."
  },
  AvgDialog_117500_Content_55 = {
    Text = "La información que proporcionaste es muy útil."
  },
  AvgDialog_117500_Content_56 = {
    Text = "William, el compañero mayor, ¿puedes decirme qué es lo que estás persiguiendo exactamente ahora?"
  },
  AvgDialog_117500_Content_57 = {
    Text = "William contempló por un momento."
  },
  AvgDialog_117500_Content_58 = {
    Text = "Déjame pensar por dónde empezar."
  },
  AvgDialog_117500_Content_59 = {
    Text = "Desde que caí en este mundo, he estado explorando dos preguntas: ¿por qué terminé aquí y cómo regreso a mi mundo original?"
  },
  AvgDialog_117500_Content_6 = {
    Text = "¿Por qué, recuerdo claramente que fui rodeado por innumerables Marchadores de mares, y luego..."
  },
  AvgDialog_117500_Content_60 = {
    Text = "William sacó solemnemente una llave de plata que mantenía oculta cerca de su pecho, con un atisbo de nostalgia en su mirada."
  },
  AvgDialog_117500_Content_61 = {
    Text = "Esta llave de plata fue restaurada por mí personalmente, de mi antiguo socio Fengol... Algunas personas dicen que soy el investigador más legendario de Misaq, pero en mi opinión, eso es solo porque murió joven."
  },
  AvgDialog_117500_Content_62 = {
    Text = "Hasta que caí en esta dimensión, entendí que él simplemente había inspirado antes que yo la esencia del mundo y luchaba como pionero en la línea del frente contra la disolución."
  },
  AvgDialog_117500_Content_63 = {
    Text = "Él ya ha rastreado el secreto que conecta los dos mundos y ha dejado una pista clave: una estatua de marfil."
  },
  AvgDialog_117500_Content_64 = {
    Text = "Como siempre, él siempre va un paso por delante de mí."
  },
  AvgDialog_117500_Content_65 = {
    Text = "William se oscureció, sacudió la cabeza y devolvió la llave de plata a su pecho."
  },
  AvgDialog_117500_Content_66 = {
    Text = "......¿Has visto esa estatua de marfil en las manos de Miryam o Murphy?"
  },
  AvgDialog_117500_Content_67 = {Text = "Asientes."},
  AvgDialog_117500_Content_68 = {
    Text = "Si todo se desarrolla como la última vez, Murphy estará llevando a cabo una ceremonia con esta estatua en la cubierta de arriba."
  },
  AvgDialog_117500_Content_69 = {
    Text = "Esa estatua de marfil parece tener conexiones inimaginables con la esencia de este mundo."
  },
  AvgDialog_117500_Content_7 = {
    Text = "Sientes tus extremidades. Aunque el dolor fantasma aún persiste, no hay ni una sola cicatriz en tu piel, la gran batalla que experimentaste antes de desmayarte parece no haber ocurrido en absoluto."
  },
  AvgDialog_117500_Content_70 = {
    Text = "Así que, para volver, me temo que tenemos que conseguir la estatua de marfil y parsearla e investigarla."
  },
  AvgDialog_117500_Content_71 = {
    Text = "Después de que termine el ritual, la estatua de marfil debería regresar a la habitación de Murphy..."
  },
  AvgDialog_117500_Content_72 = {
    Text = "Dentro está muy tranquilo, se supone que no hay nadie..."
  },
  AvgDialog_117500_Content_73 = {
    Text = "Ten cuidado; debemos tratar de evitar conflictos innecesarios."
  },
  AvgDialog_117500_Content_74 = {
    Text = "De acuerdo, echemos un vistazo primero."
  },
  AvgDialog_117500_Content_75 = {
    Text = "Empujas la puerta con cautela, abriéndola un poco."
  },
  AvgDialog_117500_Content_76 = {Text = "..."},
  AvgDialog_117500_Content_77 = {
    Text = "Una corriente de aire con un olor extraño fluye hacia tu nariz, y te das cuenta de que has inhalado profundamente sin querer."
  },
  AvgDialog_117500_Content_78 = {
    Text = "¿Qué pasa?"
  },
  AvgDialog_117500_Content_79 = {Text = "Voz."},
  AvgDialog_117500_Content_8 = {
    Text = "¿Eso es... una pesadilla?"
  },
  AvgDialog_117500_Content_80 = {
    Text = "Finalmente, apareció un sonido en la habitación tranquila."
  },
  AvgDialog_117500_Content_81 = {
    Text = "El sonido de las gotas de agua."
  },
  AvgDialog_117500_Content_82 = {
    Text = "Tic, tac, el sonido de las gotas de agua cayendo en el pequeño charco recién formado."
  },
  AvgDialog_117500_Content_83 = {
    Text = "Ocho cadenas de hierro tensadas se extienden desde las extremidades de Murphy, atándola fuertemente.\nSu pecho está desgarrado, con un enorme agujero de sangre."
  },
  AvgDialog_117500_Content_84 = {
    Text = "La sangre fluye por la herida impactante, goteando en el charco de sangre que se forma lentamente, que es la fuente del sonido de tic-tac que resuena en tus oídos."
  },
  AvgDialog_117500_Content_85 = {
    Text = "¡Murphy...!"
  },
  AvgDialog_117500_Content_86 = {
    Text = "Llegaste demasiado tarde."
  },
  AvgDialog_117500_Content_87 = {
    Text = "El corazón parece ser apretado fuertemente por una mano invisible, ese dolor familiar y asfixiante se clava intensamente junto a los fragmentos de recuerdos."
  },
  AvgDialog_117500_Content_88 = {
    Text = "La luz deslumbrante te hiere los ojos, provocando lágrimas incontrolables."
  },
  AvgDialog_117500_Content_89 = {
    Text = "A medida que el líquido turbio se drena, tus ojos finalmente vuelven a enfocarse en la chica."
  },
  AvgDialog_117500_Content_9 = {
    Text = "La mujer asintió en silencio, su figura se desvaneció en la niebla difusa."
  },
  AvgDialog_117500_Content_90 = {
    Text = "Con una hoja hundida profundamente en su pecho, la joven bañada por la luz de la luna abre los ojos."
  },
  AvgDialog_117500_Content_91 = {
    Text = "La luna llena, símbolo de muerte, se cierne cerca, pero ni un rastro de miedo se muestra en su joven rostro."
  },
  AvgDialog_117500_Content_92 = {
    Text = "Lo hice... De verdad lo hice."
  },
  AvgDialog_117500_Content_93 = {
    Text = "I... lo perforé... No nacerá..."
  },
  AvgDialog_117500_Content_94 = {
    Text = "Ahora, puedo..."
  },
  AvgDialog_117500_Content_95 = {
    Text = "Su mano que empuñaba el cuchillo cae débilmente, mientras un líquido espeso, viscoso y de un carmesí oscuro fluye desde la hoja, goteando entre sus dedos hacia el mar."
  },
  AvgDialog_117500_Content_96 = {
    Text = "*Tos, tos...*"
  },
  AvgDialog_117500_Content_97 = {
    Text = "Eres... la persona en el sueño..."
  },
  AvgDialog_117500_Content_98 = {
    Text = "¡No hables por ahora! Te ayudaré..."
  },
  AvgDialog_117500_Content_99 = {
    Text = "Tus ansiosas intentos resultaron en vano, las cadenas emitieron un suave gemido con las convulsiones dolorosas de Murphy."
  },
  AvgDialog_117501_Content_10 = {
    Text = "¿Por qué la Madre divina hace tales preguntas?"
  },
  AvgDialog_117501_Content_11 = {
    Text = "Anoche, tuve un sueño."
  },
  AvgDialog_117501_Content_12 = {
    Text = "En el sueño, utilicé esa daga ritual..."
  },
  AvgDialog_117501_Content_13 = {
    Text = "Ella levantó la mano y señaló la daga que Miryam nunca se separaba de ella.\nLa hoja brillaba con un resplandor encantador, emanando una luz fantasmal como veneno."
  },
  AvgDialog_117501_Content_14 = {
    Text = "perforó su pecho."
  },
  AvgDialog_117501_Content_15 = {
    Text = "\"No nacerá...\""
  },
  AvgDialog_117501_Content_16 = {
    Text = "Murphy murmuró para sí misma, sus dedos rozando suavemente la cicatriz ensangrentada en su pecho."
  },
  AvgDialog_117501_Content_17 = {
    Text = "Es una pesadilla ilusoria."
  },
  AvgDialog_117501_Content_18 = {
    Text = "Miryam se acercó, arrodillándose ante las rodillas de Murphy, acariciando suavemente el dorso de su mano para ofrecerle consuelo."
  },
  AvgDialog_117501_Content_19 = {
    Text = "No te preocupes, el deseo de los Marchadores de mares ya se ha cumplido, Él existe, ha llegado a este mundo."
  },
  AvgDialog_117501_Content_2 = {Text = "Murmullos"},
  AvgDialog_117501_Content_20 = {
    Text = "Y tú y yo eventualmente alcanzaremos el reino eterno de Dios, compartiendo la gloria de la divinidad ante Su trono."
  },
  AvgDialog_117501_Content_21 = {
    Text = "Sus palabras eran como una oración ante el altar, llenas de reverencia y piedad."
  },
  AvgDialog_117501_Content_22 = {
    Text = "¿Y si no podemos alcanzar el Reino Divino? Quiero decir, si..."
  },
  AvgDialog_117501_Content_23 = {
    Text = "Miryam interrumpió de inmediato la vacilante pregunta de Murphy."
  },
  AvgDialog_117501_Content_24 = {
    Text = "La profecía del Rey Divino no ha transmitido tales asuntos.\n El próximo momento de la posición normal será mañana, su linaje nos guiará a la tierra prometida."
  },
  AvgDialog_117501_Content_25 = {
    Text = "Murphy frunció el ceño."
  },
  AvgDialog_117501_Content_26 = {
    Text = "Voy a descansar, Miryam, tú también deberías volver y descansar."
  },
  AvgDialog_117501_Content_27 = {
    Text = "Rezaré a la Madre divina hasta el amanecer, pidiendo por su sueño pacífico durante la noche."
  },
  AvgDialog_117501_Content_28 = {
    Text = "Murphy no respondió, su mirada profunda siguió la figura de Miryam hasta que se oyó el chirrido de la puerta al cerrarse."
  },
  AvgDialog_117501_Content_29 = {
    Text = "Ella se volvió deprimida hacia el altar en las sombras, cerrando los ojos para orar."
  },
  AvgDialog_117501_Content_3 = {
    Text = "¡Oh, Madre divina, estás aquí mirando la luz de nuevo."
  },
  AvgDialog_117501_Content_30 = {
    Text = "Mañana, el Día de la posición normal..."
  },
  AvgDialog_117501_Content_31 = {
    Text = "El extraño objeto en el altar no le dio ninguna respuesta, permaneciendo en silencio como un fósil bajo el hielo.\n Murphy abrió los ojos como si hubiera tomado una decisión."
  },
  AvgDialog_117501_Content_32 = {
    Text = "Para la continuación de este sueño..."
  },
  AvgDialog_117501_Content_33 = {
    Text = "Ella enderezó sus delgados brazos, cubiertos por una pesada gasa negra, levantando en alto el cuchillo ritual——"
  },
  AvgDialog_117501_Content_34 = {
    Text = "Bajo el reflejo de la luz de las velas, la sombra de la daga apuñala ferozmente hacia el manto dormido en el altar."
  },
  AvgDialog_117501_Content_35 = {
    Text = "Un sonido sordo resonó, el líquido espeso de carne y sangre fue atravesado. \n El lodo negro se expandió gradualmente, empapando los llamativos runas de marinero en el manto de terciopelo."
  },
  AvgDialog_117501_Content_36 = {
    Text = "Otra noche oscura está a punto de llegar..."
  },
  AvgDialog_117501_Content_37 = {
    Text = "Ella suspiró aliviada, cerró los ojos, pero lo que la asaltó no fue la oscuridad sin fin, sino el sueño de ayer."
  },
  AvgDialog_117501_Content_38 = {Text = "..."},
  AvgDialog_117501_Content_39 = {
    Text = "(Ese momento en que algo perforó mi pecho, la persona que apareció a mi lado...)"
  },
  AvgDialog_117501_Content_4 = {
    Text = "Descansen temprano, mañana es el Día de la posición normal, y necesitaré que con su sangre sagrada guíen el camino al Marchador de mares."
  },
  AvgDialog_117501_Content_40 = {
    Text = "(Parece que nunca lo he visto, pero hay algo nostálgico...)"
  },
  AvgDialog_117501_Content_41 = {
    Text = "......¿Araña?"
  },
  AvgDialog_117501_Content_42 = {
    Text = "Una pequeña araña de color púrpura oscuro te mira desde el mástil con sus grandes ojos. Al verte despertar, levantó una de sus patas delanteras y te saludó."
  },
  AvgDialog_117501_Content_43 = {
    Text = "En el sueño, parece que escuché una canción..."
  },
  AvgDialog_117501_Content_44 = {
    Text = "Una melodía etérea y suave, como el canto de una sirena recitando poesía, resuena sin cesar en tus oídos."
  },
  AvgDialog_117501_Content_45 = {
    Text = "Hijos de la tragedia, la textura del destino ya está tejida, y finalmente emprenderán el viaje que les está destinado."
  },
  AvgDialog_117501_Content_46 = {
    Text = "Y tú, el invitado de otro mundo——"
  },
  AvgDialog_117501_Content_47 = {
    Text = "Cuando las estrellas están en lo cierto, por favor, marque el final del ciclo trágico."
  },
  AvgDialog_117501_Content_48 = {
    Text = "Con un largo suspiro de lamento, el fantasma de la mujer desapareció."
  },
  AvgDialog_117501_Content_49 = {Text = "?!"},
  AvgDialog_117501_Content_5 = {
    Text = "Murphy miraba fijamente la llama danzante de la linterna, mientras el velo negro se movía con sus movimientos, proyectando sombras como un velo sobre la pared del camarote."
  },
  AvgDialog_117501_Content_50 = {
    Text = "Una vez que la sensación de miedo momentáneo se disipa, finalmente puedes calmarte y observar el entorno a tu alrededor."
  },
  AvgDialog_117501_Content_51 = {
    Text = "¿Dónde estoy...?"
  },
  AvgDialog_117501_Content_52 = {
    Text = "Un colchón suave. Un espacio tranquilo cubierto por un velo negro. Un leve aroma de salvia y de incienso flota en el aire."
  },
  AvgDialog_117501_Content_53 = {
    Text = "Antes de esto... yo..."
  },
  AvgDialog_117501_Content_54 = {
    Text = "¡Doll! ¿Puedes recibir la señal? ¿Doll?"
  },
  AvgDialog_117501_Content_55 = {
    Text = "No grites, estás interfiriendo con mi receptor de ondas de voz."
  },
  AvgDialog_117501_Content_56 = {
    Text = "¡Alcancé el barco en el que abordó William, según lo que dijeron los pescadores! ¡Pero navegó hacia una tormenta!"
  },
  AvgDialog_117501_Content_57 = {
    Text = "La siguiente línea es..."
  },
  AvgDialog_117501_Content_58 = {
    Text = "¡Voy a entrar y perseguir!"
  },
  AvgDialog_117501_Content_59 = {
    Text = "¿Con ese pequeño barco de pesca? ¿Vas a lanzarte al abismo de las Islas Bermudas? ¿No temes volcarte allí?"
  },
  AvgDialog_117501_Content_6 = {
    Text = "¿Miryam, alguna vez has soñado?"
  },
  AvgDialog_117501_Content_60 = {
    Text = "¡No podemos perder más pistas; esta es la única información verdadera y válida que hemos encontrado en meses!"
  },
  AvgDialog_117501_Content_61 = {
    Text = "¡Que la Llave de Plata guíe el camino!"
  },
  AvgDialog_117501_Content_62 = {
    Text = "No escuchaste la frase que debías oír, \"Que la Llave de Plata nos guíe\", al otro lado de la comunicación, sino el sonido estático de la conexión interrumpida."
  },
  AvgDialog_117501_Content_63 = {
    Text = "Lo que te espera es un rugido imponente de olas de mil pies de altura, y la oscuridad interminable que sigue, tragada por ella——"
  },
  AvgDialog_117501_Content_64 = {
    Text = "Hace tres meses, siguiendo la noticia del misterioso hombre rubio que partió del puerto de Innsmouth, has estado persiguiendo el rastro de William."
  },
  AvgDialog_117501_Content_65 = {
    Text = "Recientemente, finalmente viste las banderas del barco descritas por los pescadores en el horizonte, solo para que la repentina tormenta te quitara la dirección."
  },
  AvgDialog_117501_Content_66 = {
    Text = "Al abrir los ojos de nuevo, esta es la escena que tienes ante ti."
  },
  AvgDialog_117501_Content_67 = {
    Text = "¿Despertaste? Todos están esperándote."
  },
  AvgDialog_117501_Content_68 = {
    Text = "El velo negro fue levantado suavemente, seguido de una voz femenina familiar pero extraña."
  },
  AvgDialog_117501_Content_69 = {
    Text = "Todos... ¿Quién...?"
  },
  AvgDialog_117501_Content_7 = {
    Text = "Por supuesto que lo he hecho. En millones de sueños, la gran Lemuria emerge del Aequor, reproduciéndose bajo la luz del sol."
  },
  AvgDialog_117501_Content_70 = {
    Text = "Cuatro caras familiares te rodean de manera extraña frente a tu cama."
  },
  AvgDialog_117501_Content_71 = {
    Text = "Por orden de la Madre divina, los marinero han estado esperando su despertar durante mucho tiempo. Ven, bebe esta buena medicina preparada para ti por la Madre divina."
  },
  AvgDialog_117501_Content_72 = {
    Text = "Caecus presenta una copa de cristal finamente elaborada, el líquido amarillo turbio es inquietante."
  },
  AvgDialog_117501_Content_73 = {
    Text = "¿Esto... qué hay dentro?"
  },
  AvgDialog_117501_Content_74 = {
    Text = "El que escapó de la gran calamidad, deja de preguntar aquí y allá."
  },
  AvgDialog_117501_Content_75 = {
    Text = "Es lo que la Madre Divina me ordenó exprimir. Bébelo con gratitud, humano."
  },
  AvgDialog_117501_Content_76 = {
    Text = "Bajo la mirada de todos, tomaste un sorbo con cautela."
  },
  AvgDialog_117501_Content_77 = {
    Text = "¡Puf—— qué agrio——! ¿Es zumo de limón puro?!"
  },
  AvgDialog_117501_Content_78 = {
    Text = "Te sientas de golpe por el dolor ácido, con las cejas fruncidas."
  },
  AvgDialog_117501_Content_79 = {
    Text = "Dado que Él está a salvo y sano, quiero ir a la cubierta para recibir la inspiración. El Reino Divino me está llamando."
  },
  AvgDialog_117501_Content_8 = {
    Text = "La luz eterna se siembra en los océanos lejanos, señalando un nuevo rumbo para ti y para mí."
  },
  AvgDialog_117501_Content_80 = {
    Text = "(Este mundo y yo, uno de los dos debe estar loco...)"
  },
  AvgDialog_117501_Content_81 = {
    Text = "Por preguntar... ¿Aquí es...?"
  },
  AvgDialog_117501_Content_82 = {
    Text = "El crucero Paradeis, el único y más importante \"paraíso\" marítimo para los Marchadores de mares."
  },
  AvgDialog_117501_Content_83 = {
    Text = "Estamos navegando hacia el eterno Reino Divino, Lemuria."
  },
  AvgDialog_117501_Content_9 = {
    Text = "Miryam respondió casi instintivamente, y la pregunta que siguió reveló una sorpresa inconfundible."
  },
  AvgDialog_117502_Content_1 = {Text = "..."},
  AvgDialog_117502_Content_10 = {
    Text = "En la última luz antes de que el campo de visión caiga en la oscuridad absoluta, ves una figura que pasa rápidamente."
  },
  AvgDialog_117502_Content_11 = {
    Text = "Una melena dorada brillante, un brazo mecánico preciso parpadea con un leve destello metálico."
  },
  AvgDialog_117502_Content_12 = {
    Text = "William... compañero mayor..."
  },
  AvgDialog_117502_Content_2 = {Text = "..."},
  AvgDialog_117502_Content_3 = {
    Text = "¿Cuánto tiempo luchaste entre el apestoso cardumen?"
  },
  AvgDialog_117502_Content_4 = {
    Text = "¿Una hora? ¿Un día? ¿O un tiempo que no se puede contar?"
  },
  AvgDialog_117502_Content_5 = {
    Text = "(El festival es el momento en que los Marchadores de mares actúan en conjunto, entrar en este momento... es una decisión impulsiva y errónea.)"
  },
  AvgDialog_117502_Content_6 = {
    Text = "La sensación resbaladiza se ha vuelto tan habitual que ya no molesta, y el moco hediondo ya no es una preocupación para las fosas nasales congestionadas."
  },
  AvgDialog_117502_Content_7 = {
    Text = "(Si pudiera volver a hacerlo una vez más... Qué lástima...)"
  },
  AvgDialog_117502_Content_8 = {
    Text = "Luchas por levantar la llave de plata, el núcleo que brillaba en el pasado comienza a temblar. \n Estás inestable y escupes un bocado de sangre."
  },
  AvgDialog_117502_Content_9 = {
    Text = "(¿Ya... he llegado al límite...? Lo siento... no pude escapar...)"
  },
  AvgDialog_117503_Content_1 = {Text = "Un viajero"},
  AvgDialog_117503_Content_10 = {
    Text = "El corazón de repente comienza a latir con un ritmo agitado, abres la boca instintivamente, porque ya conoces al dueño detrás de ese velo negro."
  },
  AvgDialog_117503_Content_100 = {
    Text = "El cardumen rompe las ataduras de la superficie del líquido, luchando y convulsionando en el aire pegajoso, cayendo uno tras otro a tu lado, desatando una tormenta viscosa y maloliente."
  },
  AvgDialog_117503_Content_101 = {
    Text = "Acompañado de un sonido escalofriante, un cuerpo medio podrido rebota en la cubierta, el líquido corrupto en el punto de impacto emite un hedor intenso y asfixiante."
  },
  AvgDialog_117503_Content_102 = {
    Text = "Tentáculos delgados y frágiles desgarran el abdomen pálido, sorprendentemente arrastrándose hacia ti——"
  },
  AvgDialog_117503_Content_11 = {
    Text = "<Shake:Murphy...>"
  },
  AvgDialog_117503_Content_12 = {
    Text = "Entre las rendijas de la tela se expone su piel pálida y azulada, tan blanca como los restos de un cadáver en descomposición."
  },
  AvgDialog_117503_Content_13 = {
    Text = "¡Cómo te atreves a llamar a la Madre divina por su nombre!"
  },
  AvgDialog_117503_Content_14 = {
    Text = "No hay problema, Caecus, {Male=él,Female=ella} es un invitado del Paraíso y también se unirá a nuestra gran travesía."
  },
  AvgDialog_117503_Content_15 = {
    Text = "Cinco pares de ojos te están mirando fijamente, haciendo que todas las palabras que quieres pronunciar retrocedan a tu estómago."
  },
  AvgDialog_117503_Content_16 = {
    Text = "......Murphy, ¿puedo hablar contigo a solas?"
  },
  AvgDialog_117503_Content_17 = {Text = "..."},
  AvgDialog_117503_Content_18 = {Text = "..."},
  AvgDialog_117503_Content_19 = {Text = "Murphy..."},
  AvgDialog_117503_Content_2 = {
    Text = "La chica con la que hablas se sienta en el pie de tu cama, un velo negro y difuso oculta su rostro."
  },
  AvgDialog_117503_Content_20 = {
    Text = "Si aún no has organizado tu lenguaje, en realidad tengo una pregunta que hacerte."
  },
  AvgDialog_117503_Content_21 = {
    Text = "¿Por qué viniste al Paraíso? Hasta donde sé, para acercarse al Paraíso, primero debes aventurarte en la tormenta."
  },
  AvgDialog_117503_Content_22 = {
    Text = "Estar dispuesto a asumir tales riesgos, debes tener algo que ganar."
  },
  AvgDialog_117503_Content_23 = {
    Text = "Entonces... ¿han visto a un hombre que mide media cabeza más que yo, con cabello rubio?"
  },
  AvgDialog_117503_Content_24 = {
    Text = "Murphy te miró de reojo y soltó una risa despectiva."
  },
  AvgDialog_117503_Content_25 = {
    Text = "Con tu altura, probablemente hay muchas personas así entre la tripulación."
  },
  AvgDialog_117503_Content_26 = {
    Text = "No, solo lo puedes reconocer de un vistazo... tiene un brazo mecánico, es muy apuesto y lleva un leve aroma a cedro."
  },
  AvgDialog_117503_Content_27 = {
    Text = "......Entonces puedo confirmar que no los he visto.\nEsos miembros de la tripulación siempre emanan un olor a pescado sucio y apestoso."
  },
  AvgDialog_117503_Content_28 = {
    Text = "Entonces, Murphy, hay un asunto clave más."
  },
  AvgDialog_117503_Content_29 = {Text = "¿Hm?"},
  AvgDialog_117503_Content_3 = {
    Text = "(Esa voz... me resulta tan familiar... ¿Quién es...?)"
  },
  AvgDialog_117503_Content_30 = {
    Text = "¿Quieres escapar conmigo?"
  },
  AvgDialog_117503_Content_31 = {Text = "¡Haah?!"},
  AvgDialog_117503_Content_32 = {
    Text = "Murphy se sorprendió por tus palabras, y luego la ira subió a sus mejillas.\n Luchó por contener sus emociones y soltó una risa burlona."
  },
  AvgDialog_117503_Content_33 = {
    Text = "¿Escapar, qué significa?"
  },
  AvgDialog_117503_Content_34 = {
    Text = "En sentido literal, encontramos la manera de salir de este barco y liberarnos del control de los Marchadores de mares."
  },
  AvgDialog_117503_Content_35 = {
    Text = "¿Por qué debería escapar contigo?"
  },
  AvgDialog_117503_Content_36 = {
    Text = "Porque no te gusta la vida aquí."
  },
  AvgDialog_117503_Content_37 = {
    Text = "Desprecias las doctrinas ficticias de Miryam, la hipocresía de la adoración de los creyentes, y no tienes interés en esos elogios ilusorios."
  },
  AvgDialog_117503_Content_38 = {
    Text = "La cabeza de Murphy se fue bajando poco a poco."
  },
  AvgDialog_117503_Content_39 = {
    Text = "Al verla en silencio, avivaste el fuego a tiempo."
  },
  AvgDialog_117503_Content_4 = {
    Text = "Te esfuerzas por levantar el torso con los brazos adoloridos, intentando comprender la situación del entorno."
  },
  AvgDialog_117503_Content_40 = {
    Text = "En otro mundo, te he visto, te conozco, hemos pasado por circunstancias similares, y al final, tú también lograste escapar de la cueva del mal..."
  },
  AvgDialog_117503_Content_41 = {Text = "Hmph..."},
  AvgDialog_117503_Content_42 = {
    Text = "¡Estás equivocado, terriblemente equivocado!"
  },
  AvgDialog_117503_Content_43 = {
    Text = "¿Murphy...?"
  },
  AvgDialog_117503_Content_44 = {
    Text = "La reacción de Murphy te sorprendió por completo, se rió nerviosamente."
  },
  AvgDialog_117503_Content_45 = {
    Text = "La risa se volvió gradualmente desenfrenada, hasta que en la habitación solo resonaba su risa excesivamente indulgente."
  },
  AvgDialog_117503_Content_46 = {
    Text = "Después de un rato, parece que finalmente se cansó de reír, y su risa se detuvo de repente.\n Levantó la cabeza y te miró con furia."
  },
  AvgDialog_117503_Content_47 = {
    Text = "El embrión divino se gestó en mi pecho, yo, la madre divina de gran honor, amada por todos, ¿por qué debo obedecer a ustedes, mortales, y \"escapar\"?"
  },
  AvgDialog_117503_Content_48 = {
    Text = "Pero, cuando nazca el dios, morirás..."
  },
  AvgDialog_117503_Content_49 = {
    Text = "No es necesario esperar, personas torpes."
  },
  AvgDialog_117503_Content_5 = {
    Text = "¡Idiota, no te muevas."
  },
  AvgDialog_117503_Content_50 = {
    Text = "Murphy presentó un manto de forma extraña, que originalmente era la parte de la cabeza de un bebé, con un bulto de carne y sangre gelatinosas de un color azul púrpura que parecía familiar."
  },
  AvgDialog_117503_Content_51 = {
    Text = "¿¡Niño Santo!?"
  },
  AvgDialog_117503_Content_52 = {
    Text = "Reconoces en el contorno que es la deidad deformada que el Ritual de nacimiento del Sonanir intenta convocar."
  },
  AvgDialog_117503_Content_53 = {
    Text = "¿Ha nacido el Niño Santo en este mundo? Pero, ¿por qué es... tan pequeño?!"
  },
  AvgDialog_117503_Content_54 = {
    Text = "¿Por qué es tan pequeño... qué pregunta tan ridícula."
  },
  AvgDialog_117503_Content_55 = {
    Text = "Si se queda tan pequeño, no será como un globo de hidrógeno inflado por la fuerza, extrayendo con avaricia la energía de su madre, llenándose, expandiéndose y comprimiéndose sin cesar en mi pecho..."
  },
  AvgDialog_117503_Content_56 = {
    Text = "Entonces, en el momento en que el cuerpo madre muere, colapsa, se hace añicos, se convierte en cenizas..."
  },
  AvgDialog_117503_Content_57 = {
    Text = "Ya lo has visto, este es el Niño Santo que he dado a luz."
  },
  AvgDialog_117503_Content_58 = {
    Text = "¿Llamas a esto... un dios?"
  },
  AvgDialog_117503_Content_59 = {
    Text = "¿Y qué? ¿Alguien ha visto cómo era el dios mencionado por los marineros cuando nació?"
  },
  AvgDialog_117503_Content_6 = {
    Text = "La niña se levantó impaciente, el velo negro que la cubría se movía inquieto."
  },
  AvgDialog_117503_Content_60 = {
    Text = "¿Quién puede afirmar que esta carne y sangre apestosa en nuestras manos no es el verdadero \"Dios\"?"
  },
  AvgDialog_117503_Content_61 = {
    Text = "Las preguntas resuenan en tu mente como un trueno."
  },
  AvgDialog_117503_Content_62 = {
    Text = "No soy la Murphy que conoces; soy la Madre divina de los Marchadores de mares, la única compatible con Su linaje."
  },
  AvgDialog_117503_Content_63 = {
    Text = "En cuanto a ti... no me hagas arrepentirme de haberte llevado al Paraíso.\n Ahora, déjame en paz, sal de esta habitación con tus ridículas ideas."
  },
  AvgDialog_117503_Content_64 = {
    Text = "Vagas por el Paradeis siguiendo los recuerdos del pasado, mientras los pequeños hombres pez marineros corren de un lado a otro, ignorándote por completo."
  },
  AvgDialog_117503_Content_65 = {
    Text = "Hasta que al lado de la sala de poder, viste dos figuras familiares."
  },
  AvgDialog_117503_Content_66 = {
    Text = "¡Chico, sé generoso y ataca!"
  },
  AvgDialog_117503_Content_67 = {Text = "¡Sí!"},
  AvgDialog_117503_Content_68 = {
    Text = "¡Ding clang——!"
  },
  AvgDialog_117503_Content_69 = {
    Text = "¿Todavía fue detenido...? Maldito, si esto sigue así, ¿cuánto tiempo tomará para ayudar al señor Goliat a conquistar...?"
  },
  AvgDialog_117503_Content_7 = {
    Text = "El Paradeis ha visto a muchos pacientes que son sensibles al entorno oceánico; antes de adaptarse al \"Paraíso\", no duden en sacudir su espiritualidad demasiado violentamente."
  },
  AvgDialog_117503_Content_70 = {
    Text = "Cálmate, niño, los muros tienen oídos. Si nos descubren, ninguno de los dos escapará."
  },
  AvgDialog_117503_Content_71 = {
    Text = "Señor Goliat, usted claramente dijo que nuestra sangre proviene de los fuertes, por lo que no deberíamos temer a nada..."
  },
  AvgDialog_117503_Content_72 = {
    Text = "¡Maldito niño, incluso los más fuertes tienen que depender de otros a veces! En este barco, tenemos que fingir escuchar a esas locas."
  },
  AvgDialog_117503_Content_73 = {Text = "Pero..."},
  AvgDialog_117503_Content_74 = {
    Text = "Menos charla, alguien viene."
  },
  AvgDialog_117503_Content_75 = {
    Text = "El cuerpo del gigante salió de la sombra de la sala de poder, el chirrido de la hoja dentada arrastrándose por el suelo casi ahogó el estruendo de la cabina."
  },
  AvgDialog_117503_Content_76 = {
    Text = "Otra vez nos vemos, pequeño."
  },
  AvgDialog_117503_Content_77 = {
    Text = "Goliat... ¿cómo llegué a este barco?"
  },
  AvgDialog_117503_Content_78 = {
    Text = "Deberías preguntarte a ti mismo, en el territorio de Miryam no se dan la bienvenida a los viajeros comunes, y mucho menos a un barco que aparece de repente."
  },
  AvgDialog_117503_Content_79 = {
    Text = "No sé qué suerte tienes, pero esa niña cambió de opinión hace unos días y nos prohíbe absolutamente que te toquemos."
  },
  AvgDialog_117503_Content_8 = {
    Text = "Te encuentras de frente con un par de ojos rojos que te resultan familiares."
  },
  AvgDialog_117503_Content_80 = {
    Text = "De lo contrario, esa mujer puede querer llevarte a refinar núcleos de plata, después de todo, en un mundo donde la gente ha desaparecido, los núcleos de plata se pueden contar como usar menos, perder menos."
  },
  AvgDialog_117503_Content_81 = {
    Text = "¿Y tu postura? El Goliat que conozco no es un débil que se deja manipular."
  },
  AvgDialog_117503_Content_82 = {
    Text = "Niño, acabas de embarcarte en este barco, todavía hay mucho que no sabes."
  },
  AvgDialog_117503_Content_83 = {
    Text = "Solo necesitas recordar una cosa: esa loca ahora está completamente sometida a la Madre Divina. Todo en este barco está decidido por esa niña."
  },
  AvgDialog_117503_Content_84 = {
    Text = "No intentes ir en contra de su voluntad—al menos no dejes que se entere."
  },
  AvgDialog_117503_Content_85 = {
    Text = "Lo demás, te lo diré cuando tengamos la oportunidad de encontrarnos en otro lugar."
  },
  AvgDialog_117503_Content_86 = {
    Text = "Tengo que pensarlo bien... Vamos a subir a la cubierta y a tomar un poco de brisa marina."
  },
  AvgDialog_117503_Content_87 = {
    Text = "Estás de pie solo en la proa, mirando a lo lejos."
  },
  AvgDialog_117503_Content_88 = {
    Text = "La superficie del mar está envuelta en una ligera y pura neblina, mientras el crucero navega rompiendo el bullicio del mar y el sonido mecánico de manera suave y estable."
  },
  AvgDialog_117503_Content_89 = {
    Text = "Respiras hondo el aire marino mezclado con un olor salado y metálico, intentando aclarar tus pensamientos confusos."
  },
  AvgDialog_117503_Content_9 = {
    Text = "——Dong dong, dong dong——"
  },
  AvgDialog_117503_Content_90 = {
    Text = "Perseguí el barco de William hasta la tormenta, sufrí un accidente y fui rescatado por el barco del Marchador de mares..."
  },
  AvgDialog_117503_Content_91 = {
    Text = "El Niño Santo ha nacido, Murphy se ha convertido en la Santa Madre de los Marchadores de mares, Miryam está recolectando Núcleo de plata, y Goliath está planeando algo en secreto..."
  },
  AvgDialog_117503_Content_92 = {
    Text = "<Shake:¡Clac—>"
  },
  AvgDialog_117503_Content_93 = {
    Text = "¿Eh? ¿Qué sonido es ese?"
  },
  AvgDialog_117503_Content_94 = {
    Text = "Te vuelves en busca del origen del sonido, pero la cubierta está en silencio, sin rastro de personas."
  },
  AvgDialog_117503_Content_95 = {
    Text = "(¿Es una ilusión?)"
  },
  AvgDialog_117503_Content_96 = {
    Text = "<Shake:¡Plop plop plop—>"
  },
  AvgDialog_117503_Content_97 = {Text = "¿Eh?!"},
  AvgDialog_117503_Content_98 = {
    Text = "En lo profundo del agua, incontables cuerpos diminutos se extienden densamente sobre la superficie del mar, con el halo turbio flotante evocando imágenes de erupciones humanas."
  },
  AvgDialog_117503_Content_99 = {
    Text = "¿Estos... son... peces?"
  },
  AvgDialog_117504_Content_1 = {
    Text = "Ceremonia de navegación"
  },
  AvgDialog_117504_Content_10 = {
    Text = "Yo y Faros estamos preparando la ceremonia de navegación, los seres espirituales se reunirán naturalmente como alimento para el ritual."
  },
  AvgDialog_117504_Content_100 = {
    Text = "Esa voz te llama——"
  },
  AvgDialog_117504_Content_101 = {
    Text = "<Italic:<Red:¡Ayúdame!>>"
  },
  AvgDialog_117504_Content_102 = {
    Text = "El impulso que no puedes reprimir te hace saltar desde el mástil."
  },
  AvgDialog_117504_Content_103 = {
    Text = "Debes agarrar su mano y liberarla de este ritual sangriento."
  },
  AvgDialog_117504_Content_104 = {
    Text = "¡Murphy, deja de continuar con el ritual! ¡Vas a morir! ¡Escapemos juntos!"
  },
  AvgDialog_117504_Content_105 = {
    Text = "¿Estás loco? ¡Cómo te atreves a profanar a la Madre divina!"
  },
  AvgDialog_117504_Content_106 = {
    Text = "¡No soy ese Murphy que conocías; he tomado mi decisión!"
  },
  AvgDialog_117504_Content_107 = {
    Text = "Aunque no eres el Murphy que conozco, he visto a muchos Despertadores del Origen — Ramona: Bucle, Helot: Cadena de sangre, Doll: Fusión..."
  },
  AvgDialog_117504_Content_108 = {
    Text = "La razón por la que cayeron en la locura es que experimentaron más infortunios en el camino. Los encuentros no cambiarán el color de su corazón."
  },
  AvgDialog_117504_Content_109 = {
    Text = "¡No te aferres más a este camino perdido, escapa conmigo!"
  },
  AvgDialog_117504_Content_11 = {
    Text = "¿Ceremonia de pilotaje?"
  },
  AvgDialog_117504_Content_110 = {
    Text = "¿Huir...? ¿A dónde podemos escapar?"
  },
  AvgDialog_117504_Content_111 = {
    Text = "Este ya es el mundo más perfecto, y cualquier intento de escapar solo caerá en un ciclo más profundo y desesperado."
  },
  AvgDialog_117504_Content_112 = {
    Text = "Mira hacia atrás, las enormes olas rugientes detrás de ti."
  },
  AvgDialog_117504_Content_113 = {
    Text = "Con el violento hervor de la superficie del mar, miles de Marchadores de mares y serpientes de agua rodeaban la pálida Estatua de marfil, elevándose con una sensación interminable de opresión."
  },
  AvgDialog_117504_Content_114 = {
    Text = "Madre divina... perdóname, no puedo seguir tus instrucciones, no puedo tolerar más esta profanación a lo divino."
  },
  AvgDialog_117504_Content_115 = {
    Text = "Miryam se arrodilló en la proa del barco, ofreciendo un respetuoso ritual en dirección a la línea que separa la superficie del mar."
  },
  AvgDialog_117504_Content_116 = {
    Text = "¡Dioses, oh, fieles de corazón! Los profanadores que intentan obstaculizar el ritual ya han aparecido."
  },
  AvgDialog_117504_Content_117 = {
    Text = "Por favor, castiga a los irreverentes que se atrevan a ofender a la Madre divina."
  },
  AvgDialog_117504_Content_118 = {
    Text = "Pisaron los escalones invisibles formados por las olas, con pasos resbaladizos y inquietantes, subiendo silenciosamente a la cubierta del crucero."
  },
  AvgDialog_117504_Content_119 = {
    Text = "<Big:<Shake:¡Ve, muérdelos, destrozaos!!>>"
  },
  AvgDialog_117504_Content_12 = {
    Text = "La Madre divina nos guiará para llegar a la ascendente Lemuria."
  },
  AvgDialog_117504_Content_13 = {
    Text = "Al ver tu expresión de desconcierto, el rostro de Miryam se volvió sorprendentemente suave."
  },
  AvgDialog_117504_Content_14 = {
    Text = "Debes tener muchas dudas, no te preocupes, por orden de la Madre divina, te responderé una por una."
  },
  AvgDialog_117504_Content_15 = {
    Text = "......Para ser honesto, tu cambio de actitud ya es lo suficientemente sorprendente."
  },
  AvgDialog_117504_Content_16 = {
    Text = "Al reflexionar sobre el pasado, el conflicto entre tú y los marineros es completamente innecesario."
  },
  AvgDialog_117504_Content_17 = {
    Text = "¿Cómo es posible? He sido testigo de los Marchadores de mares llevando a cabo rituales nefastos..."
  },
  AvgDialog_117504_Content_18 = {
    Text = "Eso fue un malentendido. Los marchadores de mares realizan un ritual secreto para reunir la energía que sostiene el viaje de este barco."
  },
  AvgDialog_117504_Content_19 = {
    Text = "En este momento, cuando la mayor parte de la humanidad se ha convertido en cenizas, los núcleos de plata acumulados en varios lugares son suficientes para satisfacer nuestras necesidades."
  },
  AvgDialog_117504_Content_2 = {
    Text = "En medio del abrumador olor a pescado, la mujer de la túnica púrpura frunció el ceño y se volvió hacia Faros a su lado."
  },
  AvgDialog_117504_Content_20 = {
    Text = "Por ello, los Marchadores de Mares se dirigieron a Necrovia para recolectar Plata de los fallecidos. Desafortunadamente, nuestro plan resultó entrar en conflicto con los apetitos de Doresain, el Rey de Necrovia."
  },
  AvgDialog_117504_Content_21 = {
    Text = "Según nuestra comprensión de la Universidad de Misag, también usarán el Núcleo de plata refinado como energía, ¿verdad?"
  },
  AvgDialog_117504_Content_22 = {
    Text = "La llave de plata en tu pecho está hecha con la técnica de núcleo de plata."
  },
  AvgDialog_117504_Content_23 = {
    Text = "No pudiste aceptarlo por un momento, pero eras demasiado impotente para refutarlo, así que tuviste que cambiar de tema."
  },
  AvgDialog_117504_Content_24 = {
    Text = "Miryam... ¿cuál es tu objetivo con los Marchadores de mares?"
  },
  AvgDialog_117504_Content_25 = {
    Text = "Naturalmente, es reconstruir el Reino Divino y revitalizar Lemuria."
  },
  AvgDialog_117504_Content_26 = {
    Text = "En el momento en que nuestro Señor ha llegado, nada es más importante que regresar al Reino Divino y revivir la esplendorosa Lemuria."
  },
  AvgDialog_117504_Content_27 = {
    Text = "¿Te refieres a la llegada de... Tulu?"
  },
  AvgDialog_117504_Content_28 = {
    Text = "Su conciencia permanece en un estado de medio sueño, pero Él eventualmente cumplirá Su promesa de guiarnos de regreso al Reino Divino."
  },
  AvgDialog_117504_Content_29 = {
    Text = "¿Lemuria... dónde está?"
  },
  AvgDialog_117504_Content_3 = {
    Text = "Recolecta la espiritualidad de aquí."
  },
  AvgDialog_117504_Content_30 = {
    Text = "En el cielo, por debajo del mar. El oráculo no ha revelado más."
  },
  AvgDialog_117504_Content_31 = {
    Text = "Después de pronunciar esta frase en clave, Miriam cayó en silencio."
  },
  AvgDialog_117504_Content_32 = {
    Text = "Faros, que ha reunido todos los núcleos de plata, se detuvo al lado de Miriam sosteniendo una caja de madera llena de perlas de plata."
  },
  AvgDialog_117504_Content_33 = {
    Text = "Faros, ¿por qué te uniste a los Marchadores de mares?"
  },
  AvgDialog_117504_Content_34 = {
    Text = "¿Hay alguna necesidad de preguntar? Porque el Reino del Mar está justo allí. El Reino del Mar me está llamando."
  },
  AvgDialog_117504_Content_35 = {
    Text = "Dondequiera que vaya, puedo oír Su llamado, como las mareas que surgen día tras día."
  },
  AvgDialog_117504_Content_36 = {
    Text = "Ella mira a lo lejos, sus palabras solo transmiten un vacío."
  },
  AvgDialog_117504_Content_37 = {
    Text = "Parece que hoy será un buen día. Mira, el sol está a punto de salir."
  },
  AvgDialog_117504_Content_38 = {Text = "Sol......"},
  AvgDialog_117504_Content_39 = {
    Text = "Sigues su mirada—"
  },
  AvgDialog_117504_Content_4 = {
    Text = "Sí, Gran Sacerdote."
  },
  AvgDialog_117504_Content_40 = {
    Text = "Rugido, rugido. El latido de tu corazón casi rompe tus tímpanos."
  },
  AvgDialog_117504_Content_41 = {
    Text = "<Shake:Espera, ¿y el... sol en el cielo?>"
  },
  AvgDialog_117504_Content_42 = {
    Text = "¿Sol? ¿No está el sol allí mismo?"
  },
  AvgDialog_117504_Content_43 = {
    Text = "¡No, no, no es este Sol!"
  },
  AvgDialog_117504_Content_44 = {
    Text = "Lo que se eleva por encima del nivel del mar es un sol que deberías haber anhelado, irradiando suavemente luz detrás de una niebla blanca como un velo."
  },
  AvgDialog_117504_Content_45 = {
    Text = "¿No es este sol? ¿Cuál otro sol hay?"
  },
  AvgDialog_117504_Content_46 = {
    Text = "Esa luz cálida parecía emitir un calor extraordinario, dejándote sin razón, con la garganta seca; las palabras que salían eran lentas y difíciles de entender."
  },
  AvgDialog_117504_Content_47 = {
    Text = "¡Debería ser un sol negro, sin luz!"
  },
  AvgDialog_117504_Content_48 = {
    Text = "Nunca he oído hablar de ningún sol negro ni lo he visto..."
  },
  AvgDialog_117504_Content_49 = {
    Text = "Faros, ¿qué año es este año?"
  },
  AvgDialog_117504_Content_5 = {
    Text = "Faros se arrodilló en el suelo, recogiendo los restos malolientes uno por uno."
  },
  AvgDialog_117504_Content_50 = {
    Text = "El año 1920. ¿Hay algo mal?"
  },
  AvgDialog_117504_Content_51 = {
    Text = "No es el año del Desbordamiento... de hecho, estoy en un nuevo mundo..."
  },
  AvgDialog_117504_Content_52 = {
    Text = "No te distraigas, la Madre divina ha llegado."
  },
  AvgDialog_117504_Content_53 = {
    Text = "Como invitado que ha sido aprobado por la madre divina, te concederé el privilegio de presenciar la ceremonia de navegación más grandiosa."
  },
  AvgDialog_117504_Content_54 = {
    Text = "Pero no te atrevas a abandonar este lugar, o haré que el blasfemo sea decapitado y exhibido al público."
  },
  AvgDialog_117504_Content_55 = {
    Text = "Un pequeño grupo de color negro y púrpura viene desde la popa del yate, sus pasos se mueven de manera extraña y sincronizada, arrastrándose hacia la cubierta bajo sus pies."
  },
  AvgDialog_117504_Content_56 = {
    Text = "La niña a la cabeza vestía un pesado atuendo blanco, abrazando un bulto hinchado en sus brazos, su expresión era confusa y difícil de discernir bajo el velo negro."
  },
  AvgDialog_117504_Content_57 = {Text = "..."},
  AvgDialog_117504_Content_58 = {
    Text = "La fila se detuvo rápidamente en la proa del barco, cada pieza negra parecía estar ya familiarizada con su lugar de aterrizaje."
  },
  AvgDialog_117504_Content_59 = {
    Text = "Un par de pies descalzos se adentraron en el estrecho camino dejado para ella entre la multitud, mientras innumerables fragmentos plateados caían suavemente detrás de ella."
  },
  AvgDialog_117504_Content_6 = {
    Text = "Su frente irradiaba un suave resplandor, y después de unos segundos, el cardumen solo quedó con restos plateados."
  },
  AvgDialog_117504_Content_60 = {
    Text = "¡Gracias a la madrina por otorgarnos la sangre umbilical! Consumiremos el fuego del espíritu y beberemos las oraciones de sangre, transformando a innumerables almas devotas en faros!"
  },
  AvgDialog_117504_Content_61 = {
    Text = "Los monstruos se arrastran por el suelo, recogiendo ansiosamente las perlas plateadas esparcidas por el piso."
  },
  AvgDialog_117504_Content_62 = {
    Text = "......Miryam......"
  },
  AvgDialog_117504_Content_63 = {
    Text = "Miryam se inclinó humildemente hacia el suelo, sosteniendo con ambas manos una bandeja de plata con un velo negro en el centro, donde reposaba una daga brillante."
  },
  AvgDialog_117504_Content_64 = {
    Text = "Respetada Madre divina, por favor, guía la sangre del rey divino, dirige a los Marchadores de mares perdidos y muéstranos la ubicación de Lemuria."
  },
  AvgDialog_117504_Content_65 = {
    Text = "La niña tomó la daga."
  },
  AvgDialog_117504_Content_66 = {
    Text = "Oh, reverenciado Rey divino..."
  },
  AvgDialog_117504_Content_67 = {
    Text = "La daga se hunde en el manto, y una gota de sangre viscosa parece coagularse en el aire como si tuviera voluntad propia."
  },
  AvgDialog_117504_Content_68 = {
    Text = "<Cambio>Tomo la línea de sangre de un dios como guía."
  },
  AvgDialog_117504_Content_69 = {
    Text = "Todos los creyentes se arrodillaron en el suelo, con las manos levantadas hacia el cielo, cortándose la muñeca izquierda cubierta de escamas con un cuchillo delgado."
  },
  AvgDialog_117504_Content_7 = {
    Text = "Miryam... ¿son estos peces voladores invocados por ti y Faros?"
  },
  AvgDialog_117504_Content_70 = {
    Text = "Incontables filamentos plateados entrelazados con gotas de sangre se extienden desde las muñecas de una docena de creyentes, siguiendo una trayectoria inalcanzable hacia un mismo lugar."
  },
  AvgDialog_117504_Content_71 = {
    Text = "<Cambio>Ofrece los espíritus de todas las cosas como un sacrificio."
  },
  AvgDialog_117504_Content_72 = {
    Text = "Las gotas de sangre oscura giraron, se condensaron y saltaron dentro de una estatua de marfil lechoso, filtrándose en una densa red de hilos de sangre."
  },
  AvgDialog_117504_Content_73 = {
    Text = "La estatua de marfil parece haber activado su vitalidad, sobrevolando al gigante de acero y cayendo directamente en el océano silencioso."
  },
  AvgDialog_117504_Content_74 = {
    Text = "<Cambiar>Por favor, desgarrar el abismo ilusorio, guíanos directamente a su reino."
  },
  AvgDialog_117504_Content_75 = {
    Text = "En un instante, el cielo y el mar temblaron, toda la vasta océano se agita con olas furiosas, emitiendo un lamento similar al de una bestia dando a luz."
  },
  AvgDialog_117504_Content_76 = {
    Text = "Las olas bailan locamente, gimiendo, formando una pared de temblor."
  },
  AvgDialog_117504_Content_77 = {
    Text = "Madre divina, parece que la cantidad de estos materiales es un poco insuficiente..."
  },
  AvgDialog_117504_Content_78 = {
    Text = "No importa."
  },
  AvgDialog_117504_Content_79 = {
    Text = "La niña levantó el velo y se volvió hacia los seres que yacían de rodillas."
  },
  AvgDialog_117504_Content_8 = {
    Text = "Miryam pareció darse cuenta de tu existencia por primera vez, inclinando ligeramente la cabeza hacia tu dirección."
  },
  AvgDialog_117504_Content_80 = {
    Text = "¡Que la Madre divina otorgue sangre sagrada!"
  },
  AvgDialog_117504_Content_81 = {
    Text = "<Big:<Shake:¡Que la Madre divina otorgue sangre sagrada!>>"
  },
  AvgDialog_117504_Content_82 = {
    Text = "El clamor aumentaba cada vez más, y en medio de esos gritos, los dedos de la niña se dirigieron hacia su pecho."
  },
  AvgDialog_117504_Content_83 = {
    Text = "Sus uñas eran afiladas como cuchillas, desgarrando su pecho a lo largo de la cicatriz púrpura, revelando el único corazón que quedaba."
  },
  AvgDialog_117504_Content_84 = {
    Text = "<Shake:¡Captúralo, persíguelo! Si ofrezco la carne y sangre de la Madre divina, ¡debes forjarme la escalera inversa que conecta el Reino Divino!"
  },
  AvgDialog_117504_Content_85 = {
    Text = "Los creyentes se lanzaron hacia adelante. Sus pies palmeados y manos monstruosas se extendieron ansiosamente hacia el frágil cuerpo de la Madre divina."
  },
  AvgDialog_117504_Content_86 = {
    Text = "Drenan su sangre y devoran su carne. Los hilos carmesí proliferan violentamente, surgiendo caóticamente hacia Aequor."
  },
  AvgDialog_117504_Content_87 = {
    Text = "El carmesí se multiplica locamente con el punto de caída de la estatua como centro, y las olas se solidifican en millones de corales de sangre en su agitación."
  },
  AvgDialog_117504_Content_88 = {
    Text = "¡La ceremonia ha terminado! ¡Retírate!"
  },
  AvgDialog_117504_Content_89 = {
    Text = "Ella avanzó sobre el cuerpo del marinero que se arrodillaba ante la niña, envolviendo el cuerpo de Murphy en una pesada túnica negra. Debajo de la túnica, un río de sangre seguía fluyendo."
  },
  AvgDialog_117504_Content_9 = {
    Text = "¿No deberías estar en la sala de estar de la Madre Divina? ¿Por qué...?"
  },
  AvgDialog_117504_Content_90 = {
    Text = "¡Lemuria! ¡Lemuria! ¡La sangre de la Madre divina ha revelado el camino hacia Lemuria!"
  },
  AvgDialog_117504_Content_91 = {
    Text = "En medio de innumerables linajes de sangre, vislumbras un hilo plateado inusual. Ese hilo plateado emerge de tu pecho y continúa extendiéndose hacia arriba, extendiéndose..."
  },
  AvgDialog_117504_Content_92 = {
    Text = "Hasta más allá del firmamento, en algún lugar desconocido."
  },
  AvgDialog_117504_Content_93 = {
    Text = "La niña parece darse cuenta de la existencia de ese hilo plateado, levanta la cabeza y sus pupilas tiemblan repentinamente, su mirada aterrorizada te atraviesa."
  },
  AvgDialog_117504_Content_94 = {Text = "..."},
  AvgDialog_117504_Content_95 = {
    Text = "En el instante en que las miradas se cruzan, una fuerza invisible y colosal te arrastra, ignorando tu completa resistencia y llevándote a una aterradora ilusión como una pesadilla."
  },
  AvgDialog_117504_Content_96 = {
    Text = "......Ese es el sol negro impuro que has visto."
  },
  AvgDialog_117504_Content_97 = {
    Text = "¿Sonido de tambor de mano?"
  },
  AvgDialog_117504_Content_98 = {
    Text = "No, es el latido del corazón."
  },
  AvgDialog_117504_Content_99 = {
    Text = "Largo, sofocante, cerca de la muerte, hace mucho tiempo fuera de la existencia pero resucitado después del largo sueño..."
  },
  AvgDialog_118123_Content_1 = {
    Text = "Caballero del viento"
  },
  AvgDialog_118123_Content_10 = {
    Text = "Es con tales aspiraciones que le doy a este chico una oportunidad."
  },
  AvgDialog_118123_Content_11 = {
    Text = "(Resultado... no sirve para nada...)"
  },
  AvgDialog_118123_Content_12 = {
    Text = "Claro... tendré que echar una mano."
  },
  AvgDialog_118123_Content_13 = {
    Text = "¡Corres como una mosca sin cabeza! ¿A dónde crees que vas!"
  },
  AvgDialog_118123_Content_14 = {
    Text = "¡Como dijo William, el compañero mayor, los botes salvavidas van de la cubierta al fondo del barco!"
  },
  AvgDialog_118123_Content_15 = {
    Text = "¡El campo de visión en la cubierta es tan amplio, creo que quieres alimentarle a los hombres pez!"
  },
  AvgDialog_118123_Content_16 = {
    Text = "¡En la anterior reencarnación, quien fue a alimentar a los hombres pez fuiste tú mismo!"
  },
  AvgDialog_118123_Content_17 = {
    Text = "¡Maldita sea, no hables de tú a la Madre divina! ¡Ahora mismo, corre hacia la cabina, allí hay una estructura que conduce al bote salvavidas!"
  },
  AvgDialog_118123_Content_18 = {
    Text = "¡Y suéltame, mi cabello ya está desordenado como un nido de pájaros!"
  },
  AvgDialog_118123_Content_19 = {
    Text = "Eres un rehén importante para mí, ¡y este no es el momento de considerar las apariencias! Así que por favor, aguanta un poco más, ¡Madre divina!"
  },
  AvgDialog_118123_Content_2 = {
    Text = "Saltas de un salto, sintiendo el viento helado cortando tus mejillas, y luego la cuerda en tu cintura se tensa repentinamente, deteniendo la caída."
  },
  AvgDialog_118123_Content_20 = {
    Text = "<Shake:¡Cuidado, los perseguidores de Miryam vienen!>"
  },
  AvgDialog_118123_Content_3 = {
    Text = "¡Hola! ¿Qué estás haciendo!"
  },
  AvgDialog_118123_Content_4 = {
    Text = "Sacas un cuchillo pequeño, cortas la cuerda y luego saltas al suelo."
  },
  AvgDialog_118123_Content_5 = {
    Text = "¿Vas a correr así cargándome? ¡Ellos vendrán rápidamente, verdad!"
  },
  AvgDialog_118123_Content_6 = {
    Text = "¡Ah, qué estúpido!"
  },
  AvgDialog_118123_Content_7 = {
    Text = "¿Cómo pude pensar así, incluso tener un atisbo de esperanza en este idiota."
  },
  AvgDialog_118123_Content_8 = {
    Text = "La escapatoria de {Male=él,Female=ella} esta vez fue más imprudente que cualquiera que emprendí en aquel entonces."
  },
  AvgDialog_118123_Content_9 = {
    Text = "Si existe <Yellow:%player%> en este mundo, ¿se desarrollaría la historia de manera diferente?"
  },
  AvgDialog_118124_Content_1 = {
    Text = "Desatas la cortina y atan a Murphy, que está mostrando los dientes y las garras."
  },
  AvgDialog_118124_Content_10 = {
    Text = "Si nos observas de cerca a los tres, sabrás que la princesa es otra persona."
  },
  AvgDialog_118124_Content_11 = {
    Text = "William ató con seguridad la cuerda alrededor de tus cinturas y las de Murphy."
  },
  AvgDialog_118124_Content_12 = {
    Text = "¡Cuida bien a la princesa, no la pierdas! ¡Hay botes salvavidas en la parte inferior del camarote, nos reuniremos allí!"
  },
  AvgDialog_118124_Content_13 = {
    Text = "3, 2, 1, ¡salta!"
  },
  AvgDialog_118124_Content_2 = {
    Text = "¡Listo! No te muevas, ¡ten cuidado de no lastimarte!"
  },
  AvgDialog_118124_Content_3 = {
    Text = "¡Qué fastidio! Si sigues hablando así, ¡te morderé!"
  },
  AvgDialog_118124_Content_4 = {
    Text = "Aún así, no pretender ser alguien más se parece más a ti, Murphy."
  },
  AvgDialog_118124_Content_5 = {
    Text = "¡Deja de hablar tonterías! ¡La culpa de humillar a la Madre Divina la saldaré contigo cuando recupere mi libertad!"
  },
  AvgDialog_118124_Content_6 = {
    Text = "Sin embargo, ¿los pasos afuera se están volviendo más densos?"
  },
  AvgDialog_118124_Content_7 = {
    Text = "Los pasos de puji puji se juntan en un mar, y continuamente cuerpos bajos y robustos golpean la puerta de la sala, produciendo un eco sordo de bang, bang."
  },
  AvgDialog_118124_Content_8 = {
    Text = "¡Vamos, rompamos la ventana y salgamos! ¡Agárrate de esto y salta a la cubierta!"
  },
  AvgDialog_118124_Content_9 = {
    Text = "¿Usando la sábana para hacer nudos...? William, pareces una princesa fugitiva de un cuento de hadas."
  },
  AvgDialog_118125_Content_1 = {
    Text = "Princesa de la Torre"
  },
  AvgDialog_118125_Content_10 = {
    Text = "Observas detenidamente, hay dos hilos rotos en total, y en la rueca aún quedan cuatro vueltas de hilo."
  },
  AvgDialog_118125_Content_11 = {
    Text = "¿Todavía tengo cuatro oportunidades... verdad?"
  },
  AvgDialog_118125_Content_12 = {
    Text = "Ella asintió con la cabeza y luego la negó."
  },
  AvgDialog_118125_Content_13 = {
    Text = "He oído tu canto; no eres incapaz de hablar... simplemente no se te permite decir nada...?"
  },
  AvgDialog_118125_Content_14 = {
    Text = "Ella abrió la boca, pero solo emergió un silencio eterno."
  },
  AvgDialog_118125_Content_15 = {
    Text = "Ella miró hacia el alto cielo en la distancia, y tú seguiste su mirada hacia lo lejos."
  },
  AvgDialog_118125_Content_16 = {
    Text = "Allí solo hay un sol negro empapándose en el agua."
  },
  AvgDialog_118125_Content_17 = {
    Text = "Cof, cof...!"
  },
  AvgDialog_118125_Content_18 = {
    Text = "Despertaste de repente de la cama, tosiendo fuertemente por el dolor del ahogamiento."
  },
  AvgDialog_118125_Content_19 = {
    Text = "Una vez más... el ciclo..."
  },
  AvgDialog_118125_Content_2 = {
    Text = "El viento marino es salado y tiene un regusto amargo que persiste al entrar en la boca."
  },
  AvgDialog_118125_Content_20 = {
    Text = "Las personas del reino marino, ya sea con sorpresa o indiferencia, ya sea con preocupación real o falsa, en este momento están separadas de ti por múltiples barreras, y en tu mente solo ronda el rostro de Murphy, antes de que terminara el último ciclo."
  },
  AvgDialog_118125_Content_21 = {
    Text = "¡Sálvame... si eres tú, seguro que puedes..."
  },
  AvgDialog_118125_Content_22 = {
    Text = "Entonces la oscuridad consumió todo, convirtiéndose en las dudas persistentes en tu mente."
  },
  AvgDialog_118125_Content_23 = {
    Text = "De todos modos, necesitas reunirte primero con William."
  },
  AvgDialog_118125_Content_24 = {
    Text = "Goliath y Miryam caminaban por un pasillo vacío, con los pasos resonando detrás y delante."
  },
  AvgDialog_118125_Content_25 = {
    Text = "Pasando junto a murales de estilo barroco de la Virgen, pequeñas linternas que reemplazan a las lámparas de pared de bronce y un grupo de dormitorios tranquilos y vacíos."
  },
  AvgDialog_118125_Content_26 = {
    Text = "No comparten contacto, ni palabras; la atmósfera tensa rodea a los dos."
  },
  AvgDialog_118125_Content_27 = {
    Text = "Miryam se detuvo en la puerta de la habitación del capitán y se volvió para empujarla abierta."
  },
  AvgDialog_118125_Content_28 = {
    Text = "Goliat dio unos pasos y se detuvo detrás de ella."
  },
  AvgDialog_118125_Content_29 = {
    Text = "¡Hola, Miryam! Esa niña te está mintiendo."
  },
  AvgDialog_118125_Content_3 = {Text = "..."},
  AvgDialog_118125_Content_30 = {
    Text = "¿Qué te trae? A esta hora, deberías estar vigilando la cabina, ¿verdad?"
  },
  AvgDialog_118125_Content_31 = {
    Text = "Si la mujer que mantiene la sala de poder muestra algún defecto, solo te interrogaré a ti."
  },
  AvgDialog_118125_Content_32 = {
    Text = "Deja de hablar tonterías, Caecus está mirando, esos estúpidos marineros no pueden causar ningún problema."
  },
  AvgDialog_118125_Content_33 = {
    Text = "Solo hay un problema clave, esa niña te está mintiendo."
  },
  AvgDialog_118125_Content_34 = {
    Text = "Filisteo, hablar sin sentido sobre la Madre Divina no es tu comportamiento habitual."
  },
  AvgDialog_118125_Content_35 = {
    Text = "¿Sabes que este barco nunca llegará a esa cosa llamada Lemuria?"
  },
  AvgDialog_118125_Content_36 = {Text = "...Goliat."},
  AvgDialog_118125_Content_37 = {
    Text = "Eres solo mi perro de caza, mientras no te haya ordenado que agites la gran espada contra un enemigo, no hay espacio para que hables libremente aquí."
  },
  AvgDialog_118125_Content_38 = {
    Text = "Antes de atracar, solo necesitas encargarte de esos marineros en el barco y no dejes que interrumpan el sueño de la Madre divina."
  },
  AvgDialog_118125_Content_39 = {
    Text = "Si hay algo que debes saber..."
  },
  AvgDialog_118125_Content_4 = {
    Text = "La mujer que sostiene la rueca te mira con tristeza."
  },
  AvgDialog_118125_Content_40 = {
    Text = "<Shake:Si este barco tiene siquiera la más mínima oportunidad de alcanzar Lemuria, es todo gracias a la radiancia de la Madre divina.>"
  },
  AvgDialog_118125_Content_41 = {
    Text = "Tsk, mujer terco y apestosa..."
  },
  AvgDialog_118125_Content_42 = {
    Text = "Ya he mencionado tanto lo bueno como lo malo."
  },
  AvgDialog_118125_Content_43 = {
    Text = "Entonces, no me culpes por lo que suceda a continuación."
  },
  AvgDialog_118125_Content_44 = {
    Text = "Caecus, ejecuta el plan."
  },
  AvgDialog_118125_Content_45 = {Text = "¡Aquí!"},
  AvgDialog_118125_Content_46 = {
    Text = "Toma el control principal del barco antes de que se complete el ritual."
  },
  AvgDialog_118125_Content_47 = {
    Text = "Te mueves por la cubierta, esforzándote por buscar pistas que puedan indicar el escondite de William."
  },
  AvgDialog_118125_Content_48 = {
    Text = "Si no me equivoco, estaba justo en este lugar..."
  },
  AvgDialog_118125_Content_49 = {
    Text = "Levantas la trampilla a lo largo de la rendija en la cubierta y, apretando los dientes, saltas hacia abajo."
  },
  AvgDialog_118125_Content_5 = {
    Text = "¿Hay algo que quieras decirme?"
  },
  AvgDialog_118125_Content_50 = {
    Text = "<Shake:Puf, puaj...>"
  },
  AvgDialog_118125_Content_51 = {
    Text = "Toses el pasto de caña que metiste en tu boca, lamentando haber elegido el método de aterrizaje de frente."
  },
  AvgDialog_118125_Content_52 = {
    Text = "¡William, el compañero mayor, deja de esconderte, sé que estás aquí!"
  },
  AvgDialog_118125_Content_53 = {
    Text = "Después de un rato, se oyen unos susurros detrás del montón de cañas."
  },
  AvgDialog_118125_Content_54 = {
    Text = "Esto no es lógico."
  },
  AvgDialog_118125_Content_55 = {
    Text = "......Si tienes una capacidad de posicionamiento tan precisa, ya me habrías alcanzado en las calles de Londres."
  },
  AvgDialog_118125_Content_56 = {
    Text = "Hablemos correctamente... ¿qué has experimentado desde que embarcaste en este barco?"
  },
  AvgDialog_118125_Content_57 = {Text = "..."},
  AvgDialog_118125_Content_58 = {
    Text = "Relataste brevemente la historia de la reencarnación."
  },
  AvgDialog_118125_Content_59 = {
    Text = "Lo siento, no habrá tiempo una vez que comience el ritual.\nWilliam, el compañero mayor, debemos desactivar la emboscada en la sala de estar de Murphy antes de eso."
  },
  AvgDialog_118125_Content_6 = {
    Text = "La mujer asintió con la cabeza."
  },
  AvgDialog_118125_Content_60 = {
    Text = "Vamos, por este camino, aquí no hay vigilancia."
  },
  AvgDialog_118125_Content_61 = {
    Text = "¿Quieres decir que Goliat está tramando una rebelión y que tengo que esconderme contigo."
  },
  AvgDialog_118125_Content_62 = {
    Text = "¿Y todo esto, es porque experimentaste una inversión del tiempo, lo sabes?"
  },
  AvgDialog_118125_Content_63 = {
    Text = "Tan absurdo, tan ridículo... a menos que mi espíritu se haya salido de control... <Shake: Ugh...>"
  },
  AvgDialog_118125_Content_64 = {
    Text = "Lo siento, aquí no hay espacio para tu capricho."
  },
  AvgDialog_118125_Content_65 = {
    Text = "¡Senior William!"
  },
  AvgDialog_118125_Content_66 = {
    Text = "Tranquilo, supongo que no es tan fácil, ya he aislado el sonido del salón."
  },
  AvgDialog_118125_Content_67 = {
    Text = "¡Primero, llévensela!"
  },
  AvgDialog_118125_Content_7 = {
    Text = "¿Está esto relacionado con la reencarnación?"
  },
  AvgDialog_118125_Content_8 = {
    Text = "La mujer negó con la cabeza, sus dedos acariciaron el hilo de la rueca, girando en el sentido de las agujas del reloj una vuelta, deteniéndose en el punto de origen."
  },
  AvgDialog_118125_Content_9 = {
    Text = "Con el giro de la rueda, el hilo original se desmoronó y se rompió."
  },
  AvgDialog_118699_Content_1 = {
    Text = "Nuestro deseo"
  },
  AvgDialog_118699_Content_10 = {
    Text = "¿Más poder espiritual intenso...? Entiendo, enviaré una notificación a todos los Despertados."
  },
  AvgDialog_118699_Content_11 = {
    Text = "En el patio al anochecer, Ogier terminó su rutina diaria de entrenamiento como de costumbre, sin mostrar signos de disminución en comparación con antes."
  },
  AvgDialog_118699_Content_12 = {
    Text = "Hoy he superado un poco el récord anterior..."
  },
  AvgDialog_118699_Content_13 = {
    Text = "Limpiándose el sudor que corría, la pesada lanza golpeó el suelo, Ogier miró hacia atrás, y la figura que una vez lo animó con una sonrisa ya no estaba; solo su sombra solitaria se alargaba en el suelo."
  },
  AvgDialog_118699_Content_14 = {
    Text = "La espada de estocada de Lotan desvió dos armas convencionales del investigador en un destello, poniendo fin a otra batalla que duró solo un minuto."
  },
  AvgDialog_118699_Content_15 = {
    Text = "¿Qué les pasa a los nuevos estudiantes de ahora? ¡Su calidad es demasiado baja, ven otra vez!"
  },
  AvgDialog_118699_Content_16 = {
    Text = "Antes de que pudiera levantar su espada para continuar acosando, los dos recién llegados sin aliento ya habían comenzado a suplicar con las manos unidas."
  },
  AvgDialog_118699_Content_17 = {
    Text = "Tsk, aburrido......"
  },
  AvgDialog_118699_Content_18 = {
    Text = "Pensando en alguien que pudiera brindarle emocionantes batallas, Lotan suspiró mientras miraba el atardecer y se dio la vuelta con aburrimiento."
  },
  AvgDialog_118699_Content_19 = {
    Text = "Aigis cortó un trozo de hilo suelto, extendió cuidadosamente el suéter recién tejido, alisándolo, y luego se puso de puntillas para colgarlo en el armario lleno de textiles."
  },
  AvgDialog_118699_Content_2 = {
    Text = [[
Mundo de Kadas
Ahora]]
  },
  AvgDialog_118699_Content_20 = {
    Text = "Patrones de trenzado, diamantes, ondas, pequeñas flores y motivos de animales, Aigis está tejiendo cada vez más estilos."
  },
  AvgDialog_118699_Content_21 = {
    Text = "Hermano o hermana mayor {Male=Sr. Guardián,Female=Srta. Guardiana}, ¿qué tipo de cosas te gustaría...?"
  },
  AvgDialog_118699_Content_22 = {
    Text = "El astuto ratón gris se deslizó por el agujero de la puerta, colocando fielmente un anillo brillante en la mano de su compañero."
  },
  AvgDialog_118699_Content_23 = {
    Text = "Hmm, buen trabajo, Brown."
  },
  AvgDialog_118699_Content_24 = {
    Text = "El ratón miró a su compañero bostezar de aburrimiento y lanzó despreocupadamente el anillo a una caja de madera abierta a su lado, que ya estaba desbordando con una mezcla caótica de \"coleccionables\"."
  },
  AvgDialog_118699_Content_25 = {Text = "Cric..."},
  AvgDialog_118699_Content_26 = {
    Text = "Esa persona no ha venido al dormitorio a revisar su cofre del tesoro durante mucho tiempo, ordenando al jefe que devuelva cada artículo uno por uno, pero ¿por qué, después de eso, el jefe sigue estando sombrío?"
  },
  AvgDialog_118699_Content_27 = {
    Text = "La niña obediente se sienta ordenadamente frente al escritorio, abriendo otro libro de cuentos."
  },
  AvgDialog_118699_Content_28 = {
    Text = "En la esquina de la mesa se ha apilado una alta pila de libros infantiles leídos, y en el cuaderno de la niña, ha anotado de manera casual las ideas de historias que se le han ocurrido."
  },
  AvgDialog_118699_Content_29 = {
    Text = "Al pensar en la elación, el rostro tranquilo de la niña mostró una ligera sonrisa, y sus pies comenzaron a moverse suavemente bajo la mesa."
  },
  AvgDialog_118699_Content_3 = {
    Text = "El túnel borroso que aún no se había formado fue aplastado de repente por una corrosión de terror; Ramona soltó un gemido ahogado y su conciencia fue recuperada bajo la convocatoria de emergencia de los instrumentos."
  },
  AvgDialog_118699_Content_30 = {
    Text = "¡Esta historia, a todos les encantará definitivamente..."
  },
  AvgDialog_118699_Content_31 = {
    Text = "El lápiz sonaba, registrando las fantasías de la infancia. Pero pronto, la niña detuvo su escritura y miró absorta por la ventana."
  },
  AvgDialog_118699_Content_32 = {
    Text = "¿Pero cuándo puede volver el gran {Male=Sr. Guardián,Female=Srta. Guardiana} para llevar a Lily a filmar de nuevo?"
  },
  AvgDialog_118699_Content_33 = {Text = "..."},
  AvgDialog_118699_Content_34 = {
    Text = "El guerrero volcó la bolsa de vino sobre la tierra frente a la lápida."
  },
  AvgDialog_118699_Content_35 = {
    Text = "Después de beber de un trago el resto de la media botella de vino, el guerrero se ha ido en silencio, solo queda una corona de laurel colgando tranquilamente sobre la lápida."
  },
  AvgDialog_118699_Content_36 = {
    Text = "Sobre el espléndido mantel de terciopelo, el té de la tarde de la dama es tan abundante como siempre."
  },
  AvgDialog_118699_Content_37 = {
    Text = "El choque contenido de cuchillo y tenedor contra los platos, llevando el delicioso pastel de crema a la boca."
  },
  AvgDialog_118699_Content_38 = {
    Text = "En un disfrute excesivamente silencioso, la dama observa en silencio la silla vacía frente a ella, con los utensilios de mesa que pertenecen a esa persona."
  },
  AvgDialog_118699_Content_39 = {
    Text = "Dejar al amo solo aquí, es un sirviente realmente incompetente..."
  },
  AvgDialog_118699_Content_4 = {
    Text = "¡Ramona! ¡Pollux! ¿Cómo están?"
  },
  AvgDialog_118699_Content_40 = {
    Text = "En una habitación de dormitorio vacía reservada, los muebles limpios y nuevos parecen no haber sido habitados, solo hay una maceta con un brote de árbol recién germinado delante de la ventana."
  },
  AvgDialog_118699_Content_41 = {
    Text = "En raras ocasiones, alguien puede ver detrás de esa ventana, donde una mujer de piel color miel se apoya en el alféizar, abrazando suavemente una plantita en una maceta."
  },
  AvgDialog_118699_Content_42 = {
    Text = "Incluso ahora que las actividades del club han comenzado a reanimarse y a ser más activas, esta sala de música que pertenece al maestro de interpretación sigue sin ser perturbada por nadie."
  },
  AvgDialog_118699_Content_43 = {Text = "..."},
  AvgDialog_118699_Content_44 = {
    Text = "Las cortinas fueron levantadas suavemente por el viento nocturno, mientras Hameln estaba frente al piano, mirando hacia la torre del reloj."
  },
  AvgDialog_118699_Content_45 = {
    Text = "Delante de las teclas que una vez resonaron juntas, ahora no hay nadie, solo el sonido de la flauta que se repite día tras día, flotando en silencio bajo la luz de la luna, inaudible."
  },
  AvgDialog_118699_Content_46 = {
    Text = "En lo profundo de la charca negra, el prisionero eternamente solitario detrás de la puerta ahora tiene un compañero de sueño."
  },
  AvgDialog_118699_Content_47 = {
    Text = "Esos ojos compasivos se abrieron en silencio, observando el cuerpo de esa alma que vagaba en la distancia."
  },
  AvgDialog_118699_Content_48 = {
    Text = "En el laboratorio del departamento de investigación, Ramona, que sigue entrenando su fuerza mental día y noche, tiene su uniforme de entrenamiento empapado de sudor."
  },
  AvgDialog_118699_Content_49 = {
    Text = "Dól observó la figura que luchaba con todas sus fuerzas, silenciosamente bebió otra taza de café expreso, abrió una nueva página del informe experimental y continuó ajustando los datos del instrumento."
  },
  AvgDialog_118699_Content_5 = {
    Text = "Ejem... estoy bien, corté a tiempo."
  },
  AvgDialog_118699_Content_50 = {
    Text = "<Small:Ah, el café de Winkle definitivamente está un poco demasiado fuerte...>"
  },
  AvgDialog_118699_Content_51 = {
    Text = "En el comunicador que ella acaba de dejar, parpadeaba una notificación enviada a todos los Despertados."
  },
  AvgDialog_118699_Content_52 = {
    Text = "Todos los despertados en el campus miraron al comunicador que sonó de repente al mismo tiempo, observando el nombre que habían esperado tanto tiempo dentro del comunicador."
  },
  AvgDialog_118699_Content_53 = {
    Text = "A todos los Despertados: \n\n En un pasado no muy lejano, aún estábamos luchando contra la negra calamidad que devora todo, hasta hoy en la lápida del Keygrave, están grabados innumerables nombres borrosos, así como el nombre del Guardián del secreto que nos trajo la paz definitiva. \n Ese es nuestro amigo, compañero de batalla, el estudiante que más faltaba en Misaq, muchos amigos especiales, nuestro guía único, y también el héroe que salvó a todos nosotros."
  },
  AvgDialog_118699_Content_54 = {
    Text = "Después de perder {Male=él,Female=ella}, Misaq perdió un intenso color. Mientras todos compartimos la misma tristeza, el departamento de investigación no ha renunciado a la débil esperanza y sigue buscando rastros de la conciencia del Guardián del Secreto. \n Originalmente, antes de confirmar el éxito, no quería traerles una esperanza desconocida, lo que solo aumentaría el dolor de la larga espera. Pero ahora, hemos verificado que podemos encontrar el método para <Yellow:%player%> y pronto iniciaremos el intento final."
  },
  AvgDialog_118699_Content_55 = {
    Text = "Esta batalla para dar la bienvenida al regreso de {Male=él,Female=ella} necesita de ustedes, necesita de todos nosotros juntos, convirtiendo nuestro anhelo por {Male=él,Female=ella} en un hito para encontrarlo. \n En nombre de Misaq, les invito sinceramente a todos a unirse antes de llegar a la charca negra, como en la última batalla, para luchar juntos nuevamente por <Yellow:%player%>. \n\n Su compañero de batalla Doll"
  },
  AvgDialog_118699_Content_56 = {
    Text = "Mundo de Kadas\nDía del acuerdo"
  },
  AvgDialog_118699_Content_57 = {
    Text = "Bajo los terrenos prohibidos del campanario, frente a la silenciosa agua negra de la piscina, se encuentra una multitud tranquila."
  },
  AvgDialog_118699_Content_58 = {
    Text = "Después de que Doll explicara el principio del viaje dimensional, los Despertados que originalmente estaban ruidosos y querían ir juntos también se quedaron en silencio junto al dispositivo de resonancia espiritual."
  },
  AvgDialog_118699_Content_59 = {
    Text = "Debido a las características mentales del espacio dimensional, cuanto más cuerpos espirituales aparezcan juntos, más atención atraerán de los seres superiores, lo que hará aún más difícil para los guardianes resistir en ese lado."
  },
  AvgDialog_118699_Content_6 = {
    Text = "¿Por qué... acabo de escuchar la voz de {Male=él,Female=ella}, ¿por qué no puedo encontrar {Male=él,Female=ella}?"
  },
  AvgDialog_118699_Content_60 = {
    Text = "Ante la multitud, Ramona sostenía un ramo de rosas marchitas, mirando en silencio la charca negra, mientras en la palma de su otra mano, apretaba fuertemente la llave de plata con el número 0617."
  },
  AvgDialog_118699_Content_61 = {
    Text = "Los instrumentos están listos para comenzar, todos enfóquense."
  },
  AvgDialog_118699_Content_62 = {
    Text = "Las pinzas presionan el botón, y una onda de energía espiritual se expande como ondas en el agua, condensando las conciencias de todos en hilos, tejiendo una red de conexiones."
  },
  AvgDialog_118699_Content_63 = {
    Text = "Ramona abre solemnemente la palma de la mano, la llave de plata asciende lentamente en una extraña gravedad, flotando en el centro de una red invisible, parpadeando con una luz que respira."
  },
  AvgDialog_118699_Content_64 = {
    Text = "Todos miraron la llave, orando en silencio en sus corazones."
  },
  AvgDialog_118699_Content_65 = {
    Text = "Esta escuela, estas personas, te necesitan. Ya sea un año, dos años o diez años... mientras la investigación tenga significado, definitivamente te traeremos de vuelta."
  },
  AvgDialog_118699_Content_66 = {
    Text = "Señor, ya puedo resistir 40 segundos sin conexión, ahora puedo protegerlo mejor, realmente quiero que vea los resultados de mi entrenamiento..."
  },
  AvgDialog_118699_Content_67 = {
    Text = "Nunca ha habido un nuevo nacido en Misaq tan resistente como tú, ¿cuándo me dejarás experimentar otra batalla bajo tu mando?"
  },
  AvgDialog_118699_Content_68 = {
    Text = "Aigis ha sido buena escuchando y comiendo bien, he tejido tantas bufandas, gorros, guantes y varios suéteres para el gran {Male=Sr. Guardián,Female=Srta. Guardiana}, ¿le gustarán al gran {Male=Sr. Guardián,Female=Srta. Guardiana}?"
  },
  AvgDialog_118699_Content_69 = {
    Text = "¡West-Whelp, no has terminado de aprender los secretos de supervivencia del Distrito Este que prometí enseñarte, y ya he recogido la matrícula—apresúrate a volver, no dejes que mi reputación como ladrón se vea dañada...!"
  },
  AvgDialog_118699_Content_7 = {
    Text = "De hecho, el \"Sagrado Corazón\" solo puede percibir la ubicación aproximada de {Male=él,Female=ella}, pero no puede encontrar coordenadas más detalladas."
  },
  AvgDialog_118699_Content_70 = {
    Text = "Guardián del Secreto {Male=señor,Female=señorita}, creo que las personas buenas siempre estarán protegidas por la buena suerte, y personas como usted, seguramente tendrán un final feliz."
  },
  AvgDialog_118699_Content_71 = {
    Text = "¡Hermano o hermana mayor {Male=Sr. Guardián,Female=Srta. Guardiana}, Lily ya puede leer muchos cuentos! Cuando regreses, ¿podemos hacer una película sobre hermano o hermana mayor {Male=Sr. Guardián,Female=Srta. Guardiana} y Lily?"
  },
  AvgDialog_118699_Content_72 = {
    Text = "El guerrero triunfante debe regresar a {Male=su,Female=su} patria."
  },
  AvgDialog_118699_Content_73 = {
    Text = "¡Apresúrate a volver, sirviente tonto, me debes tantos tés de la tarde, debes compensarlos todos!"
  },
  AvgDialog_118699_Content_74 = {
    Text = "Me preguntaste alguna vez cuál era mi deseo... ahora finalmente tengo mi propio deseo, que es que puedas regresar a salvo."
  },
  AvgDialog_118699_Content_75 = {
    Text = "El pequeño arbolito que no cumple sus promesas, en el nuevo mundo que me prometiste, no puede faltar tú..."
  },
  AvgDialog_118699_Content_76 = {
    Text = "Nuestra tribu no abandonará a ningún miembro solitario."
  },
  AvgDialog_118699_Content_77 = {
    Text = "Mi flauta, siempre esperando por usted."
  },
  AvgDialog_118699_Content_78 = {
    Text = "Todos los Despertados murmuran ese nombre familiar, su poder espiritual fluyendo como luciérnagas hacia la llave de plata flotante, que gradualmente brilla como estrellas en su centro."
  },
  AvgDialog_118699_Content_79 = {
    Text = "Pollux y Castor se cruzaron una mirada y asintieron mutuamente. El cuerpo de Castor se transformó en un destello y se fusionó con el pecho de Pollux."
  },
  AvgDialog_118699_Content_8 = {
    Text = "Pero el fuerte deseo de la señorita Ramona en ese último momento hizo que \"el Sagrado Corazón\" sintiera a <Yellow:%player%> aún más claramente."
  },
  AvgDialog_118699_Content_80 = {
    Text = "Un halo verde y azul fluye en el corazón sagrado, detrás de Pólux, un par de hermosas alas negro azules se despliegan de repente. Él extiende un dedo y el corazón sagrado comienza a parpadear en respuesta a la luz de la llave de plata."
  },
  AvgDialog_118699_Content_81 = {
    Text = "¡Señorita Ramona."
  },
  AvgDialog_118699_Content_82 = {
    Text = "Frente a la mirada solemne de Pollux, Ramona apretó la rosa que comenzaba a brillar en su mano, una señal acordada con el Guardián del Secreto."
  },
  AvgDialog_118699_Content_83 = {
    Text = "El poder espiritual, ensayado mil veces, se condensa gradualmente siguiendo una guía familiar. Ella levanta la cabeza y contempla la llave de plata, vertiendo su voz sentida en el centro de la llave junto a todos."
  },
  AvgDialog_118699_Content_84 = {
    Text = "(<Yellow:%player%>, espérame, ya voy a llevarte a casa.)"
  },
  AvgDialog_118699_Content_9 = {
    Text = "Si se reúne un poder espiritual más intenso apuntando a <Yellow:%player%>, quizás se pueda sentir la posición de %player% con mayor precisión."
  },
  AvgDialog_118700_Content_1 = {
    Text = "Un abrazo momentáneo"
  },
  AvgDialog_118700_Content_10 = {
    Text = "El bullicio de los alrededores desapareció. En lo profundo de su mente, Ramona miraba a esa lejana versión de sí misma."
  },
  AvgDialog_118700_Content_11 = {
    Text = "Tu poder es más fuerte que el mío... quizás, esta vez la misión debería ser asumida por ti, para que sea más segura..."
  },
  AvgDialog_118700_Content_12 = {
    Text = "Sintiendo lo que Ramona tenía en su corazón, Ramona: Bucle negó con la cabeza y levantó los ojos cubiertos, mirando en silencio hacia aquel abismo."
  },
  AvgDialog_118700_Content_13 = {
    Text = "Solo estoy aquí para despedirte; en este distante viaje a través de dimensiones, no hay diferencia entre nosotros, y mucho menos..."
  },
  AvgDialog_118700_Content_14 = {
    Text = "Eres su {Male=su, Female=suyo} compañero, este es su destino, no el mío."
  },
  AvgDialog_118700_Content_15 = {
    Text = "Ve, trae de vuelta {Male=él, Female=ella}, \"Ramona\"."
  },
  AvgDialog_118700_Content_16 = {
    Text = "Ramona apretó con fuerza la mano de la rosa, y tras un momento, asintió solemnemente, mientras otro yo la observaba sentarse en el dispositivo de separación mental."
  },
  AvgDialog_118700_Content_17 = {
    Text = "Los ojos del cuerpo están fuertemente cerrados, mientras que otro par se abre lentamente. Un alma solidificada sale del cuerpo, bañada en la tenue luz blanca iluminada por el \"Sagrado Corazón\" de Pollux."
  },
  AvgDialog_118700_Content_18 = {
    Text = "Bajo la mirada de decenas, Ramona se dio la vuelta, cruzando miradas con sus compañeros uno por uno, asumiendo esas pesadas esperanzas."
  },
  AvgDialog_118700_Content_19 = {
    Text = "Bajo la guía de esos recuerdos, ella se dio la vuelta y se lanzó al enorme vórtice. La entrada, similar a la puerta del infierno, devoró de inmediato su delgada alma."
  },
  AvgDialog_118700_Content_2 = {
    Text = "El ángel suspendido desciende con luz sagrada, esperando llevar las almas perdidas al lado de Dios."
  },
  AvgDialog_118700_Content_3 = {
    Text = "Doll y Ramona se miraron a los ojos y activaron un gigantesco dispositivo que casi cubría la mitad de la charca negra. En medio de la violenta sacudida del agua, un enorme vórtice colapsó ruidosamente, formando un abismo que parecía devorar todo."
  },
  AvgDialog_118700_Content_4 = {Text = "Eso es..."},
  AvgDialog_118700_Content_5 = {
    Text = "Las aguas del inmenso estanque parecen fluir hacia otro mundo, y dentro del vórtice insondable, la existencia del mundo comienza a volverse borrosa."
  },
  AvgDialog_118700_Content_6 = {
    Text = "El borde de este mundo, la entrada al espacio dimensional."
  },
  AvgDialog_118700_Content_7 = {
    Text = "Más allá del abismo, {Male=él,Female=ella} te está esperando."
  },
  AvgDialog_118700_Content_8 = {
    Text = "Ramona asintió. Justo antes de entrar en el abismo, se detuvo de repente y miró a la multitud."
  },
  AvgDialog_118700_Content_9 = {
    Text = "Una figura de vacío, de pie en silencio detrás de la multitud que reza. Esa es una figura oculta en su conciencia, visible solo para ella."
  },
  AvgDialog_118701_Content_1 = {Text = "Esperar"},
  AvgDialog_118701_Content_10 = {
    Text = "La niebla se reunió y se disipó, un habitual de Misaq apareció en la entrada de la charca negra, quedándose en silencio al lado de la muñeca, contemplando juntos la sombra que permanecía quieta frente a la \"puerta\"."
  },
  AvgDialog_118701_Content_11 = {
    Text = "La exposición prolongada al agua de la piscina no es buena para el cuerpo; ¿no vas a detenerla un poco?"
  },
  AvgDialog_118701_Content_12 = {
    Text = "Le di equipo de protección básico, y en cuanto a las lesiones físicas, todavía tengo formas de curar, pero las heridas mentales no son tan fáciles de sanar."
  },
  AvgDialog_118701_Content_13 = {
    Text = "El profesor racional suspiró y se volvió, inquisitivo."
  },
  AvgDialog_118701_Content_14 = {
    Text = "Es raro que vengas aquí, ¿qué has traído esta vez?"
  },
  AvgDialog_118701_Content_15 = {
    Text = "Ah, una buena noticia que puede sanar su espíritu."
  },
  AvgDialog_118701_Content_16 = {
    Text = "Compañero, gracias a tu gran hazaña, ha habido significativamente menos fisuras de disolución en todo el mundo recientemente."
  },
  AvgDialog_118701_Content_17 = {
    Text = "Los investigadores de la escuela se han vuelto más desocupados, ya que todos solo asisten a clases y realizan exámenes cada día; Misaq se parece cada vez más a una universidad ordinaria."
  },
  AvgDialog_118701_Content_18 = {
    Text = "Alguien propuso construir una estatua para ti, justo al lado del director Wader; la escuela todavía lo está considerando."
  },
  AvgDialog_118701_Content_19 = {
    Text = "He presentado sugerencias no admitidas; claramente todavía estás aquí, ¿por qué convertirte en una estatua como el director."
  },
  AvgDialog_118701_Content_2 = {
    Text = "Mundo Kadas\nAntes del funeral del Guardián del secreto"
  },
  AvgDialog_118701_Content_20 = {
    Text = "Además, cuando regreses y veas al gigante que estás junto al director, definitivamente te sentirás demasiado avergonzado para hablar."
  },
  AvgDialog_118701_Content_21 = {
    Text = "Tu expresión es tan serena, no lo creo... Debes haberte perdido en otro mundo y olvidarte de cómo regresar..."
  },
  AvgDialog_118701_Content_22 = {
    Text = "Tienes razón, {Male=él,Female=ella} ha entrado en otra dimensión, una dimensión muy lejana."
  },
  AvgDialog_118701_Content_23 = {
    Text = "Al escuchar la voz de Daffodil que apareció de repente detrás de ella, Ramona se levantó casi descontrolada, casi sin poder contenerse de agarrar el brazo del dueño de la tienda."
  },
  AvgDialog_118701_Content_24 = {
    Text = "¿Qué dijiste? ¿Lo encontraste {Male=él,Female=ella}? Dimensión... ¡recuerdo que puedes viajar entre dimensiones!"
  },
  AvgDialog_118701_Content_25 = {
    Text = "¿Cómo puedo traer de vuelta a {Male=él,Female=ella}? ¡Pagaría cualquier precio!"
  },
  AvgDialog_118701_Content_26 = {
    Text = "Después de rogar con emoción, Ramona finalmente notó la expresión seria de Doll a su lado."
  },
  AvgDialog_118701_Content_27 = {
    Text = "¿...cómo?"
  },
  AvgDialog_118701_Content_28 = {
    Text = "Aunque tu determinación es conmovedora, desafortunadamente, esa es una dimensión no conectada a este mundo, y además, no puedo llevar al Guardián del Secreto a través del espacio dimensional desconocido."
  },
  AvgDialog_118701_Content_29 = {
    Text = "Si no se puede encontrar una ruta definida, atravesar libremente la turbulencia dimensiona solo conducirá a un resultado: estar perdido."
  },
  AvgDialog_118701_Content_3 = {
    Text = "Con un zumbido que indicaba que la verificación estaba completa, los numerosos instrumentos mostraron resultados sin ninguna respuesta una vez más. Doll agitó la mano en silencio, y los investigadores intercambiaron miradas, comenzando tácitamente a desmantelar los instrumentos."
  },
  AvgDialog_118701_Content_30 = {
    Text = "Con la tecnología actual de Misaq, esto tampoco se puede lograr."
  },
  AvgDialog_118701_Content_31 = {
    Text = "¿Qué significa esto...? Hemos intentado durante tanto tiempo y finalmente tenemos noticias sobre {Male=él,Female=ella}—¿realmente vamos a dejar a {Male=él,Female=ella} varado allá afuera solo?!"
  },
  AvgDialog_118701_Content_32 = {
    Text = "La técnica de viajar entre dimensiones, tal vez pueda discutirla con la profesora Doll, como un regalo gratuito para los viejos clientes."
  },
  AvgDialog_118701_Content_33 = {
    Text = "Pero para recuperar <Yellow:%player%>, lo más difícil es encontrar el camino hacia ese mundo; incluso entre mi colección, no hay tesoros que trasciendan el universo."
  },
  AvgDialog_118701_Content_34 = {
    Text = "Haré que el departamento de investigación invierta completamente en la investigación de dimensiones a partir de hoy."
  },
  AvgDialog_118701_Content_35 = {
    Text = "Entre dimensiones, a veces nunca habrá una intersección, no se puede encontrar solo por mera enumeración."
  },
  AvgDialog_118701_Content_36 = {
    Text = "Lo que ustedes pueden enfrentar podría ser un intento tan largo que la esperanza parece invisible."
  },
  AvgDialog_118701_Content_37 = {
    Text = "No nos rendiremos."
  },
  AvgDialog_118701_Content_38 = {Text = "..."},
  AvgDialog_118701_Content_39 = {
    Text = "Entiendo. No importa cuánto tiempo tome, esperaré a {Male=él,Female=ella}."
  },
  AvgDialog_118701_Content_4 = {
    Text = "¿Por qué guardar los instrumentos? Intenta de nuevo; debe haber algunos métodos de prueba que no se han pensado..."
  },
  AvgDialog_118701_Content_40 = {
    Text = "Mundo Kadas\nDiez meses después del funeral del Guardián del Secreto\nCharca negra"
  },
  AvgDialog_118701_Content_41 = {
    Text = "Los pasos vacíos atravesaron las capas de puertas cerradas, pisando las ondas espesas del agua, y la silenciosa charca negra recibió a su segundo visitante del día."
  },
  AvgDialog_118701_Content_42 = {
    Text = "Sabía que estarías aquí de nuevo."
  },
  AvgDialog_118701_Content_43 = {
    Text = "El interlocutor del profesor no respondió, su figura inmóvil siempre dirigida hacia la sombra suspendida frente a la \"Puerta\", como si fuera una escultura distante."
  },
  AvgDialog_118701_Content_44 = {
    Text = "Hoy nuevamente alguien ha enviado una sugerencia a mí, es la séptima vez que rechazas la asignación de un compañero de tareas y te empeñas en realizar la investigación de dos personas solo, ¿verdad."
  },
  AvgDialog_118701_Content_45 = {Text = "..."},
  AvgDialog_118701_Content_46 = {
    Text = "No importa, no estoy aquí para criticarte o mandarte, ni mucho menos para aconsejarte, aunque Sylvia dijo que tu evaluación psicológica tiene algunos problemas."
  },
  AvgDialog_118701_Content_47 = {
    Text = "¿Pero cuántas personas en esta universidad están completamente bien?"
  },
  AvgDialog_118701_Content_48 = {
    Text = "Las pinzas rosas se detuvieron al lado de la escultura, mirando junto a ella la figura que siempre estaba dormida."
  },
  AvgDialog_118701_Content_49 = {
    Text = "¿Hay alguna tarea especial que necesites que ejecute?"
  },
  AvgDialog_118701_Content_5 = {
    Text = "Ya has realizado suficientes pruebas y bandas, tu curso de uso del medidor de núcleo de plata está en la máxima puntuación, no te engañes más, Ramona."
  },
  AvgDialog_118701_Content_50 = {
    Text = "La escultura que había perdido la reacción finalmente habló, con un tono tan tranquilo como el de una máquina."
  },
  AvgDialog_118701_Content_51 = {Text = "Hay."},
  AvgDialog_118701_Content_52 = {
    Text = "¿Requisitos de la misión?"
  },
  AvgDialog_118701_Content_53 = {
    Text = "Necesito que vayas a un lugar muy peligroso para guiar a tu compañero."
  },
  AvgDialog_118701_Content_54 = {
    Text = "No necesito..."
  },
  AvgDialog_118701_Content_55 = {
    Text = "La persona anterior."
  },
  AvgDialog_118701_Content_56 = {
    Text = "Ramona se volvió de repente, fijando la mirada en los ojos inorgánicos de la muñeca."
  },
  AvgDialog_118701_Content_57 = {
    Text = "Esta misión es una apuesta, y con un nivel de peligro sin precedentes, temo que el apoyo externo dentro de la escuela no pueda acompañarte..."
  },
  AvgDialog_118701_Content_58 = {
    Text = "¿Hay resultados del departamento de investigación? ¿Cuándo?"
  },
  AvgDialog_118701_Content_59 = {
    Text = "Doll sonrió y le entregó el informe de investigación recién salido del horno."
  },
  AvgDialog_118701_Content_6 = {
    Text = "{Male=él,Female=ella}Lo que queda aquí es solo un cascarón, sin ninguna fluctuación de vida, la conciencia del Guardián del Secreto... puede que ya se haya desvanecido."
  },
  AvgDialog_118701_Content_60 = {
    Text = "Desde que Daffodil nos habló del mensaje del Guardián del Secreto, el departamento de investigación ha intentado todos los medios tecnológicos actuales y, inesperadamente, encontró que el avance final está en el Despertado."
  },
  AvgDialog_118701_Content_61 = {
    Text = "Descubrimos que el \"Sagrado Corazón\" de Pollux puede atraer esa existencia; la Iglesia de la Lanterna lo fabricó originalmente para crear almas puras y difundir sangre divina."
  },
  AvgDialog_118701_Content_62 = {
    Text = "Finalmente, sacrifica al Hijo Santo y convoca la llamada Tierra Pura."
  },
  AvgDialog_118701_Content_63 = {
    Text = "En realidad, su principio consiste en atraer la atención de esa persona, lo que a su vez difunde la disolución. Tras un tratamiento dirigido, es muy probable que el \"Sagrado Corazón\" pueda indicarnos específicamente la ubicación del Guardián del secreto."
  },
  AvgDialog_118701_Content_64 = {
    Text = "La escuela planea enviar una conciencia con gran fuerza mental al espacio dimensional, siguiendo la guía del \"Sagrado Corazón\" para cruzar dimensiones y establecer un túnel que conecte dos mundos."
  },
  AvgDialog_118701_Content_65 = {
    Text = "Si todos los datos de prueba avanzan sin problemas, en menos de un mes podremos comenzar a intentarlo."
  },
  AvgDialog_118701_Content_66 = {
    Text = "A continuación, tu tarea incluirá una parte sobre el entrenamiento de poder mental, espero que... no seas demasiado diligente para evitar dañar tu cerebro."
  },
  AvgDialog_118701_Content_67 = {
    Text = "Mundo de Kadas\nUn año después del funeral del Guardián del secreto\nCharca negra"
  },
  AvgDialog_118701_Content_68 = {
    Text = "El dispositivo de separación espiritual, que funcionaba a gran velocidad, emitió una alarma roja de sobrecarga, y la muñeca que lo observaba de cerca presionó inmediatamente el botón de detención."
  },
  AvgDialog_118701_Content_69 = {
    Text = "La puerta de la cabina que contenía al usuario se abrió de repente, y la ya agotada Ramona movió un dedo, siendo rápidamente asistida por los investigadores a cada lado."
  },
  AvgDialog_118701_Content_7 = {
    Text = "El cruel veredicto finalmente salió de la boca de la marioneta, y al ver las lágrimas fluyendo de los ojos aturdidos de Ramona, incluso el profesor, acostumbrado al sacrificio, no pudo soportar cerrar los ojos."
  },
  AvgDialog_118701_Content_70 = {
    Text = "¡Sujétala y entra rápidamente en el líquido de enfriamiento mental!"
  },
  AvgDialog_118701_Content_71 = {
    Text = "El agua de la piscina de un verde pálido inundó su pecho, y la temperatura de Ramona, que antes era como una fiebre, finalmente bajó. Sus ojos, que antes eran racionales, ahora parecían paranoicos, se abrieron lentamente."
  },
  AvgDialog_118701_Content_72 = {
    Text = "Incluso si pasado mañana es la fecha de tu primer intento oficial, no debes arriesgar tu cuerpo de esta manera."
  },
  AvgDialog_118701_Content_73 = {
    Text = "No importa, puedo aguantar..."
  },
  AvgDialog_118701_Content_74 = {
    Text = "Pollux, que salió de un instrumento cercano, se acercó silenciosamente a los dos, interrumpiendo más las advertencias de Doll."
  },
  AvgDialog_118701_Content_75 = {
    Text = "Puedo entender el dolor de perder a alguien importante, esa sensación de odiarse a uno mismo por ser impotente... No te preocupes, señorita Ramona."
  },
  AvgDialog_118701_Content_76 = {
    Text = "Ahora el \"Sagrado Corazón\" ya puede sentir la llamada de esa luz brillante, Castor y yo daremos lo mejor de nosotros para recuperar al benefactor junto a ti."
  },
  AvgDialog_118701_Content_8 = {
    Text = "Prepárate para celebrar el funeral de <Yellow:%player%>, esa carta de despedida... serás tú quien la lea {Male=él,Female=ella}."
  },
  AvgDialog_118701_Content_9 = {
    Text = "Mundo Kadas\nDentro de tres meses después del funeral del Guardián del Secreto"
  },
  AvgDialog_118702_Content_1 = {
    Text = "Mensajes desde la lejanía"
  },
  AvgDialog_118702_Content_10 = {
    Text = "Bailas como una persona ciega, moviendo las manos con desesperación, avanzando como un viajero que atraviesa el agua, luchando hacia adelante en la oscuridad viscosa, buscando."
  },
  AvgDialog_118702_Content_100 = {
    Text = "No hay temperatura abrasadora aquí, solo una oscuridad viscosa e interminable. A medida que te mueves hacia adelante, las distinciones entre avanzar y retroceder comienzan a difuminarse, como si la existencia misma se estuviera convirtiendo en vacío."
  },
  AvgDialog_118702_Content_101 = {
    Text = "Sigue adelante, no mires atrás."
  },
  AvgDialog_118702_Content_102 = {
    Text = "Confías en esa voz, te esfuerzas por liberar tu mente y continúas avanzando, hasta que una ráfaga de colores hipnóticos te sumerge en un intenso mareo."
  },
  AvgDialog_118702_Content_103 = {Text = "¡Esto es!"},
  AvgDialog_118702_Content_104 = {
    Text = "Excepto por estar de pie por primera vez fuera del universo en el Mar de Esencia Primordial de Daffodil, mirando hacia el mundo."
  },
  AvgDialog_118702_Content_105 = {
    Text = "Se siente como entrar en un mundo microscópico bajo un microscopio, con una calidad espacial gelatinosa, innumerables líneas retorcidas, formas extrañas de cuerpos espirituales y galaxias parpadeando en la distancia..."
  },
  AvgDialog_118702_Content_106 = {
    Text = "Y los límites del mundo sin fin."
  },
  AvgDialog_118702_Content_107 = {
    Text = "Si no hay suficientes puntos de anclaje mental, rápidamente te perderás en este espacio caótico e infinito, pero no hay mucho miedo en tu corazón."
  },
  AvgDialog_118702_Content_108 = {
    Text = "¿Estás listo? Después de que empieces a enlazarte, haré ruido para atraerlo tanto como pueda, lo demás será tu batalla."
  },
  AvgDialog_118702_Content_109 = {
    Text = "Aprestas la llave de plata en tu pecho y, con seriedad y cariño, extiendes los tentáculos de tu mente hacia la rosa en flor en tu mano."
  },
  AvgDialog_118702_Content_11 = {
    Text = "Finalmente... ¡te encontré! Nosotros @3... a través del túnel @2..."
  },
  AvgDialog_118702_Content_110 = {
    Text = "Comencemos."
  },
  AvgDialog_118702_Content_111 = {
    Text = "Una gran onda de poder espiritual estalla en el espacio dimensional, y en el límite de tu percepción mental, una grieta repentina corta el espacio."
  },
  AvgDialog_118702_Content_112 = {
    Text = "Una enorme pupila apareció de repente detrás de la grieta, como si un gigante hubiera abierto los ojos de golpe."
  },
  AvgDialog_118702_Content_12 = {
    Text = "No puedes ver su figura, solo oír los sonidos intermitentes. La persona que conoces también está emocionada, expresando la alegría de un reencuentro ansiado."
  },
  AvgDialog_118702_Content_13 = {
    Text = "Puedes sentir que hay una cuerda real tirando entre ustedes, como si siguiendo esa cuerda pudieras encontrar el camino de regreso a casa."
  },
  AvgDialog_118702_Content_14 = {
    Text = "Mientras sigues avanzando guiado por esa cuerda, de repente se escucha un sonido de ruptura, y todo el espacio comienza a temblar con una gran sacudida."
  },
  AvgDialog_118702_Content_15 = {
    Text = "¡Algo está atacando a @2, el Corazón Sagrado no puede aguantar!"
  },
  AvgDialog_118702_Content_16 = {
    Text = "¡Ramona, corta el enlace!"
  },
  AvgDialog_118702_Content_17 = {Text = "¡Pero!"},
  AvgDialog_118702_Content_18 = {
    Text = "¡Guardián del Secreto, ve a buscar a Daffodil! ¡No nos rendiremos——"
  },
  AvgDialog_118702_Content_19 = {
    Text = "Toda la luz ha desaparecido. En la lejanía, una gigantesca entidad desconocida ha cambiado de dirección, desvaneciéndose gradualmente en el vacío caótico."
  },
  AvgDialog_118702_Content_2 = {
    Text = "Guardia@2... Guardián del Secreto..."
  },
  AvgDialog_118702_Content_20 = {Text = "¡!!!"},
  AvgDialog_118702_Content_21 = {
    Text = "Te sientas de golpe en la cama, todavía en la habitación de la base de Fusión·muñeca, con esas familiares paredes de ladrillo rojo oscuro y un leve olor a desinfectante."
  },
  AvgDialog_118702_Content_22 = {
    Text = "¿Me preguntas qué pasó? ¿Desde cuándo mi campo de investigación se ha expandido a la interpretación de sueños? ¿No deberías estar buscando a Clementine para esos asuntos?"
  },
  AvgDialog_118702_Content_23 = {
    Text = "Pero no estás equivocado; dada la singularidad de tu espíritu, también tiendo a creer que esto no es tu fantasma ni un simple sueño."
  },
  AvgDialog_118702_Content_24 = {
    Text = "En cuanto al misterio de la verdad, ¿no te lo ha dicho ya el yo de ese sueño?"
  },
  AvgDialog_118702_Content_25 = {
    Text = "Un núcleo de plata que robaste una vez fue sacado por Fusión·Muñeca y arrojado dentro del Dispositivo de Despertar, levantando una bruma púrpura en medio del zumbido mecánico."
  },
  AvgDialog_118702_Content_26 = {
    Text = "¡Ay, otra vez nos vemos, mis viejos clientes?"
  },
  AvgDialog_118702_Content_27 = {
    Text = "¡Daffodil! Yo..."
  },
  AvgDialog_118702_Content_28 = {
    Text = "Shh, no es necesario hablar; un comerciante competente entiende naturalmente las necesidades del cliente."
  },
  AvgDialog_118702_Content_29 = {
    Text = "De hecho, ya he conocido a tus amigos."
  },
  AvgDialog_118702_Content_3 = {
    Text = "Te sientes como si una gigantesca cortina de escenario te estuviera cubriendo y envolviendo, capas de grueso terciopelo presionando sobre ti, volviéndote invisible e inmóvil."
  },
  AvgDialog_118702_Content_30 = {Text = "?!"},
  AvgDialog_118702_Content_31 = {
    Text = "Viendo tu expresión de sorpresa, Fusión·muñeca puso los ojos en blanco."
  },
  AvgDialog_118702_Content_32 = {
    Text = "Pensé que con tu inteligencia deberías ser capaz de descubrir la clave de su poder."
  },
  AvgDialog_118702_Content_33 = {
    Text = "¿La... llave para la fuerza?"
  },
  AvgDialog_118702_Content_34 = {
    Text = "Recuerdas ese océano gris lleno de cabezas."
  },
  AvgDialog_118702_Content_35 = {
    Text = "¿Espacio dimensional? ¿Quieres decir que Daffodil puede atravesar diferentes mundos... son la misma persona?"
  },
  AvgDialog_118702_Content_36 = {
    Text = "Tan cerca, niño inteligente, el \"ser\" de mí aquí y allá es realmente el mismo, pero olvidas que no somos humanos."
  },
  AvgDialog_118702_Content_37 = {
    Text = "Daffodil arquea los ojos con aprecio y sacude la pipa al girar la muñeca."
  },
  AvgDialog_118702_Content_38 = {
    Text = "Somos solo rostros que emergen en la superficie del mar; el océano gris que fluye entre las grietas de todas las dimensiones es nuestra verdadera forma."
  },
  AvgDialog_118702_Content_39 = {
    Text = "Por lo tanto, podemos comunicarnos espiritualmente, pero no somos la misma \"persona\"."
  },
  AvgDialog_118702_Content_4 = {
    Text = "En un sueño oscuro y vacío, una voz ahogada se ondula como ondas de agua y se desvanece de repente."
  },
  AvgDialog_118702_Content_40 = {
    Text = "Es decir, ¿puedes viajar entre diferentes mundos a través del Mar de Esencia Primordial? En ese sueño justo ahora, Doll me pidió que te encontrara, lo que significa que ahora tienes una manera de llevarme de regreso a ese mundo?"
  },
  AvgDialog_118702_Content_41 = {
    Text = "No te apresures, te he dicho que, incluso yo, no puedo atravesar fácilmente la dimensión entre dos mundos."
  },
  AvgDialog_118702_Content_42 = {
    Text = "Si realmente tuviera un método así, ¿por qué lo mantendría en secreto hasta ahora?"
  },
  AvgDialog_118702_Content_43 = {
    Text = "Te quedas atónito y bajas lentamente la cabeza."
  },
  AvgDialog_118702_Content_44 = {
    Text = "Sin embargo, esta vez son tus valientes amigos quienes han encontrado un nuevo camino."
  },
  AvgDialog_118702_Content_45 = {
    Text = "Levantaste la cabeza de repente, y tus ojos volvieron a brillar. Esto provocó una suave risa de Daffodil y una burla de Fusión·muñeca."
  },
  AvgDialog_118702_Content_46 = {
    Text = "Desde la última vez que nos encontramos en este mundo, les he informado sobre tus noticias."
  },
  AvgDialog_118702_Content_47 = {
    Text = "Después de conocer la singularidad de esta dimensión, Doll ha estado trabajando día y noche con los investigadores de Misaq, intentando localizar este mundo. Recientemente, han encontrado un método para enlazar dos dimensiones."
  },
  AvgDialog_118702_Content_48 = {
    Text = "Lo que acabas de sentir es el resultado de su enlace exitoso."
  },
  AvgDialog_118702_Content_49 = {
    Text = "¿Así que no fue un sueño? ¿¡Ese vínculo espiritual es real?!"
  },
  AvgDialog_118702_Content_5 = {
    Text = "¿Quién? ¿Alguien me está llamando? Una voz tan familiar..."
  },
  AvgDialog_118702_Content_50 = {
    Text = "Sí, pero el colapso del enlace justo ahora también es real. Deberías haber notado a esa persona que llegó de repente."
  },
  AvgDialog_118702_Content_51 = {
    Text = "El viaje dimensional es extremadamente peligroso; incluso si puedo ayudarles a escapar del rastreo del perro cazador, hay demasiadas entidades de alto nivel en el espacio dimensional."
  },
  AvgDialog_118702_Content_52 = {
    Text = "Normalmente tienen sus propias áreas de actividad, así como los emperadores dominan sus propios reinos."
  },
  AvgDialog_118702_Content_53 = {
    Text = "Originalmente, podría haber sido posible evitarlo con cuidado de varias maneras, pero desafortunadamente, esta vez el oponente que apunta al túnel es el que mejor conoces."
  },
  AvgDialog_118702_Content_54 = {
    Text = "Lo más familiar... esa sensación de ser observado, ¿Tohu Vah Bo? ¿Él ha despertado?!"
  },
  AvgDialog_118702_Content_55 = {
    Text = "No te pongas tan nervioso, los resultados de tu sacrificio no desaparecerán tan fácilmente. Él sigue atrapado en el sueño."
  },
  AvgDialog_118702_Content_56 = {
    Text = "Sin embargo, Él sigue siendo Él. Tu \"Sagrado Corazón\" con Pollux es demasiado deslumbrante; incluso en el sueño, Su subconsciente ha notado a ustedes."
  },
  AvgDialog_118702_Content_57 = {
    Text = "La expresión de Daffodil se volvió inusualmente seria, mientras tú permanecías en silencio, recordando aquella batalla en la que se sacrificó todo."
  },
  AvgDialog_118702_Content_58 = {
    Text = "Afortunadamente, esta vez el alboroto del viaje dimensional fue mucho menor que el que Juliette causó la última vez. La mirada proyectada desde su subconsciente no destruyó el mundo entero."
  },
  AvgDialog_118702_Content_59 = {
    Text = "Aun así, tal fuerza no es algo que el Despertado que vino a guiarte pueda soportar. Por lo tanto, para construir un enlace de dimensión completo, la persona de ese lado no podrá lograrlo por sí sola."
  },
  AvgDialog_118702_Content_6 = {
    Text = "Guardián del Secreto... ¡socio!"
  },
  AvgDialog_118702_Content_60 = {
    Text = "Necesito que tú, <Yellow:%player%>, atraigas Su atención aquí y lo repelas, protegiéndolos de otro mundo mientras abres un túnel entre los dos mundos."
  },
  AvgDialog_118702_Content_61 = {
    Text = "La mirada de Toguwaibo... ¡otra vez Él...!"
  },
  AvgDialog_118702_Content_62 = {
    Text = "Esa batalla estaba tan lejana, tan distante como si hubiera ocurrido en una vida anterior."
  },
  AvgDialog_118702_Content_63 = {
    Text = "Esa batalla fue tan cercana, lo suficientemente cerca como para que pudieras recordar fácilmente cada detalle."
  },
  AvgDialog_118702_Content_64 = {
    Text = "Cada herida desgarradora, cada victoria sangrienta, cada temblor de miedo, cada grito desesperado al borde de la muerte..."
  },
  AvgDialog_118702_Content_65 = {
    Text = "Mirar directamente a lo divino ha consumido todo tu coraje y vida. Al recordar esas miradas que trascienden las reglas, tu voz comienza a temblar incontrolablemente."
  },
  AvgDialog_118702_Content_66 = {
    Text = "Incluso si es una proyección de mirada subconsciente, su fuerza probablemente no sea algo que pueda detener..."
  },
  AvgDialog_118702_Content_67 = {
    Text = "Ahora no puedo invocar completamente el poder de los tres plásmidos, ni tengo la ayuda de compañeros de otras dimensiones, quiero detenerlo..."
  },
  AvgDialog_118702_Content_68 = {
    Text = "¿Qué pasa, nuestro valiente Guardián del Secreto, tienes miedo?"
  },
  AvgDialog_118702_Content_69 = {
    Text = "Apreitas el puño, sacudes la cabeza y miras con seriedad a Daffodil."
  },
  AvgDialog_118702_Content_7 = {Text = "¿Ramona?!"},
  AvgDialog_118702_Content_70 = {
    Text = "Mientras pueda regresar, ningún tipo de miedo podrá detenerme. Solo me preocupa, me preocupa que mis habilidades actuales no sean suficientes."
  },
  AvgDialog_118702_Content_71 = {
    Text = "Si fracaso, incluso hay un riesgo de que Él sea reavivado... Tal desastre es insoportable para cualquiera."
  },
  AvgDialog_118702_Content_72 = {
    Text = "Muy bien. Parece que nuestro Guardián del Secreto aún no ha perdido el valor de desafiar a los dioses."
  },
  AvgDialog_118702_Content_73 = {
    Text = "No te preocupes, <Yellow:%player%>. Esta vez, también te ayudaré a abrir el intervalo entre diferentes dimensiones y a dispersar Su poder en distintas dimensiones."
  },
  AvgDialog_118702_Content_74 = {
    Text = "La última vez, los Guardianes del Secreto de otras dimensiones lucharon a tu lado, esta vez, ellos estarán nuevamente en lugares invisibles para ti, combatiendo la misma batalla contigo."
  },
  AvgDialog_118702_Content_75 = {
    Text = "¿De verdad?! Si ese es el caso, ¡nosotros definitivamente tendremos la capacidad de detenerlo de nuevo!"
  },
  AvgDialog_118702_Content_76 = {
    Text = "Aun así, una batalla de este nivel podría destruir todo este mundo a manos de Él; excepto <Yellow:%player%>, los sobrevivientes de este mundo no tienen la capacidad de enfrentarse a Él."
  },
  AvgDialog_118702_Content_77 = {
    Text = "Así es, por lo que esta batalla debe llevarse a cabo en el espacio dimensional, y cómo mantener a <Yellow:%player%> en el espacio dimensional durante mucho tiempo también requiere la ayuda de un genio."
  },
  AvgDialog_118702_Content_78 = {
    Text = "¡Por favor! Fusión·muñeca!"
  },
  AvgDialog_118702_Content_79 = {
    Text = "......Hmph, uno o dos han sido organizados bastante bien."
  },
  AvgDialog_118702_Content_8 = {
    Text = "Con el momento en que pronuncias ese nombre, una barrera invisible se rompe instantáneamente, un enlace cariñoso y cálido atraviesa innumerables espacios y tiempos, convirtiéndose en un hilo blanco que se acerca a tu pecho."
  },
  AvgDialog_118702_Content_80 = {
    Text = "Olvídalo, ¿quién me dijo que prometí ayudarte a volver a casa? La promesa al perrito, la cumpliré."
  },
  AvgDialog_118702_Content_81 = {Text = "¡Gracias!"},
  AvgDialog_118702_Content_82 = {
    Text = "No necesitas apresurarte a agradecerme. Seamos claros, solo puedo mantener tu conciencia vagando en el espacio dimensional y, en la medida de lo posible, garantizar que te traiga de vuelta a este mundo en cualquier momento."
  },
  AvgDialog_118702_Content_83 = {
    Text = "En cuanto a tu lucha con esa persona, aún existe la posibilidad de fracaso e incluso muerte."
  },
  AvgDialog_118702_Content_84 = {
    Text = "No tengo un buen presentimiento sobre un plan tan impulsivo; aun así, ¿todavía eliges asumir un gran riesgo para apostar por un resultado desconocido?"
  },
  AvgDialog_118702_Content_85 = {
    Text = "Estoy dispuesto; ellos tomaron los mismos riesgos por mí, y no tengo razón para no corresponderles. De todos modos, aunque estemos a mundos de distancia, seguimos luchando juntos como solíamos hacerlo."
  },
  AvgDialog_118702_Content_86 = {
    Text = "Fusión·muñeca asintió sin sorpresa, mientras Daffodil te miraba sonriente, como si nunca hubiera considerado la posibilidad de que te echaras atrás."
  },
  AvgDialog_118702_Content_87 = {
    Text = "Ahora entiendo; un juramento tan cursi debería dejarse para tus buenos camaradas. Necesito algo de tiempo para prepararme, en cuanto a cómo acordar el momento de iniciar la acción, creo que ya tienes un método, ¿verdad?"
  },
  AvgDialog_118702_Content_88 = {
    Text = "Frente a la pregunta de Fusión·muñeca, Daffodil en cambio dirigió su mirada hacia ti."
  },
  AvgDialog_118702_Content_89 = {
    Text = "Por supuesto, tu compañero me pidió que te trajera un regalo."
  },
  AvgDialog_118702_Content_9 = {
    Text = "¿Esto es... un enlace espiritual?! Ramona, ¿eres tú? ¿Dónde estás?"
  },
  AvgDialog_118702_Content_90 = {
    Text = "Entre el humo, se te entrega una rosa, sacada de quién sabe dónde."
  },
  AvgDialog_118702_Content_91 = {
    Text = "¿Esto es... la que Ramona me envió...?!!"
  },
  AvgDialog_118702_Content_92 = {
    Text = "Es una pena que aún no tenga la capacidad de enviar objetos reales a través de la proyección dimensional."
  },
  AvgDialog_118702_Content_93 = {
    Text = "Sin embargo, en estas dos dimensiones, cada cosa tendrá su correspondiente contraparte."
  },
  AvgDialog_118702_Content_94 = {
    Text = "Esta rosa corresponde a la que Ramona te envió en esa dimensión."
  },
  AvgDialog_118702_Content_95 = {
    Text = "He hecho un pequeño ajuste a esta flor; cuando estés listo, simplemente vincula tu Espíritu a esta flor, y las personas de allá recibirán el mensaje."
  },
  AvgDialog_118702_Content_96 = {
    Text = "Ella dijo que en el momento en que se encuentren, ella personalmente te colocará esta flor en el pecho."
  },
  AvgDialog_118702_Content_97 = {Text = "..."},
  AvgDialog_118702_Content_98 = {
    Text = "Te das cuenta por primera vez de que el canal que usó Fusión·muñeca para dejar el mundo es el sol que ya ha desaparecido sobre tu cabeza."
  },
  AvgDialog_118702_Content_99 = {
    Text = "El sol negro como un vacío parece una herida que el mundo no puede sanar. Cuando tu conciencia entra lentamente en él, es como si estuvieras arrastrándote dentro del vasto pecho de un gigante."
  },
  AvgDialog_118703_Content_1 = {
    Text = "Puntas de los dedos levantadas"
  },
  AvgDialog_118703_Content_10 = {
    Text = "Un grito desgarrador que no pertenece a ningún ser ni a ninguna dimensión, que surge directamente de las profundidades de la conciencia, casi desgarrando tu cerebro."
  },
  AvgDialog_118703_Content_100 = {
    Text = "Mmm——cabeza... duele mucho..."
  },
  AvgDialog_118703_Content_101 = {
    Text = "El dispositivo de conexión está casi completamente dañado. Que aún puedas regresar con vida es nada menos que un milagro."
  },
  AvgDialog_118703_Content_102 = {
    Text = "Sin embargo, este lugar ha visto demasiados milagros. Quizás, para la Charca Negra, la probabilidad misma sea una falacia."
  },
  AvgDialog_118703_Content_103 = {
    Text = "Bien hecho, Ramona. No lo hagas de nuevo la próxima vez."
  },
  AvgDialog_118703_Content_104 = {
    Text = "Esté tranquilo, profesora Doll... Entiendo lo que estoy haciendo."
  },
  AvgDialog_118703_Content_105 = {
    Text = "Para %player%, poder verte de nuevo puede ser más importante que muchas cosas."
  },
  AvgDialog_118703_Content_106 = {
    Text = "La única pena es que no pudiste escuchar la última frase de {Male=él,Female=ella}."
  },
  AvgDialog_118703_Content_107 = {
    Text = "No, señora Davendale. {Male=su, Female=su} voz, ya la escuché..."
  },
  AvgDialog_118703_Content_108 = {
    Text = "Ramona se levantó débilmente, sonriendo, y se acercó al vacío de la charca negra que estaba desapareciendo."
  },
  AvgDialog_118703_Content_109 = {
    Text = "El abismo colapsó ante sus ojos, de un gigante que devora todo a una puerta que aísla dimensiones, hasta convertirse en una grieta de oblivion, hasta que desapareció por completo."
  },
  AvgDialog_118703_Content_11 = {
    Text = "Te arrodillas en el suelo, cubriéndote firmemente los oídos, sintiendo cómo la sangre brota incontrolablemente de tus ojos..."
  },
  AvgDialog_118703_Content_110 = {
    Text = "La mano de Ramona acarició suavemente el lugar donde alguna vez existió el abismo, rozando ese cuerpo lleno de heridas."
  },
  AvgDialog_118703_Content_111 = {
    Text = "Ella sonrió, como si viera en un futuro no muy lejano a su dueño físico de pie frente a ella, como un día extraordinariamente ordinario en Misaq."
  },
  AvgDialog_118703_Content_112 = {
    Text = "Te escucho, Guardián del Secreto... definitivamente lo lograremos."
  },
  AvgDialog_118703_Content_113 = {
    Text = "Te estoy esperando, %player%."
  },
  AvgDialog_118703_Content_12 = {
    Text = "<Shake:¡Uf... uf...!>"
  },
  AvgDialog_118703_Content_13 = {
    Text = "¿Parece que... ha terminado?"
  },
  AvgDialog_118703_Content_14 = {
    Text = "Los gritos desgarradores han desaparecido sin que sepas cuándo. Levantas la cabeza. En la frágil y virtual dimensión, ya no hay esa aterradora aura que hacía temblar."
  },
  AvgDialog_118703_Content_15 = {
    Text = "Has ganado. Su subconsciente está desconectado de aquí, y la última gran pupila se ha desvanecido en la dimensión."
  },
  AvgDialog_118703_Content_16 = {
    Text = "Te esfuerzas por mantener tu mente agotada, volviéndote casi instintivamente."
  },
  AvgDialog_118703_Content_17 = {Text = "¡Crack"},
  AvgDialog_118703_Content_18 = {
    Text = "Un sonido ilusorio de cristal rompiéndose llegó a tus oídos, y lo que viste fue un túnel dimensional agrietado como una telaraña, con Ramona, el cuerpo espiritual, comenzando a parpadear como un viejo televisor."
  },
  AvgDialog_118703_Content_19 = {
    Text = "<Big:<Shake:¡Ramona!!!>>"
  },
  AvgDialog_118703_Content_2 = {
    Text = "solo falta... un último detalle...!"
  },
  AvgDialog_118703_Content_20 = {
    Text = "El cuerpo, ya exhausto, parece sanar en un instante. Ya no puedes preocuparte por nada más, corriendo a su lado como el viento, temblando mientras agarras esas manos."
  },
  AvgDialog_118703_Content_21 = {
    Text = "Yo, yo estoy bien..."
  },
  AvgDialog_118703_Content_22 = {
    Text = "Tu compañera sigue sonriendo como de costumbre, aprieta más tu mano y continúa con los planes originales como si nada hubiera pasado."
  },
  AvgDialog_118703_Content_23 = {
    Text = "Has derrotado a él, ven, sígueme, te llevaré de vuelta."
  },
  AvgDialog_118703_Content_24 = {
    Text = "Ella te guía, al igual que durante las tareas habituales.\nSolo que, una voz más racional sonó casi fríamente."
  },
  AvgDialog_118703_Content_25 = {
    Text = "Ramona, el túnel dimensional ha sido destruido por Él, tu cuerpo espiritual no puede soportar la carga de mantener el túnel. Si continúas así, solo te dirigirás hacia la muerte cerebral."
  },
  AvgDialog_118703_Content_26 = {
    Text = "Este rescate ya ha... fallado, debes regresar de inmediato, activaré el modo de retorno del dispositivo de separación, para que tu espíritu regrese a tu cuerpo."
  },
  AvgDialog_118703_Content_27 = {
    Text = "<Big:¡No me iré!>"
  },
  AvgDialog_118703_Content_28 = {
    Text = "Es la primera vez que ves a esta persona, que siempre ha estado tan tranquila, gritar de manera tan descontrolada. Ella parece moverse un poco la nariz y rápidamente te muestra una sonrisa más natural."
  },
  AvgDialog_118703_Content_29 = {
    Text = "Estoy bien, <Yellow:%player%>, he estado entrenando mucho últimamente, mi poder espiritual ha crecido, Doll no entiende mis verdaderos límites."
  },
  AvgDialog_118703_Content_3 = {
    Text = "Cuando tu espíritu está al borde de la agotamiento, las pupilas de los dioses también comienzan a temblar por la debilidad."
  },
  AvgDialog_118703_Content_30 = {
    Text = "No te rindas, intentemos de nuevo, solo un pequeño intento, ¿de acuerdo?"
  },
  AvgDialog_118703_Content_31 = {
    Text = "Ella te está suplicando."
  },
  AvgDialog_118703_Content_32 = {Text = "..."},
  AvgDialog_118703_Content_33 = {
    Text = "No puedes hablar."
  },
  AvgDialog_118703_Content_34 = {
    Text = "¿Por qué estar tan enredados? En cambio, permíteme capturar su espíritu en este mundo y colocarlo en el cuerpo de la muñeca que he creado con tanto cuidado, para que ella pueda estar una vez más al lado de <Yellow:%player%>."
  },
  AvgDialog_118703_Content_35 = {
    Text = "La Fusión·muñeca, que había estado disfrutando del espectáculo, también se unió al canal de comunicación, emitiendo una risa juguetona."
  },
  AvgDialog_118703_Content_36 = {
    Text = "Ninguno. Sabes que no todos pueden estar como el Guardián del Secreto, existiendo durante mucho tiempo fuera del cuerpo, de lo contrario, no tendríamos que soportar todos los días un cerebro lleno de rosa."
  },
  AvgDialog_118703_Content_37 = {
    Text = "No te preocupes, Ramona, la próxima vez, esperaré a que descanses para que vengas a buscarme."
  },
  AvgDialog_118703_Content_38 = {
    Text = "Miras esa figura transparente que parece desvanecerse, sonriendo levemente, ocultando todos tus deseos de nostalgia."
  },
  AvgDialog_118703_Content_39 = {
    Text = "No es tan simple, esta \"ruta\" ya ha sido descubierta por Él, la próxima vez que la uses, solo atraerá una atención más intensa."
  },
  AvgDialog_118703_Content_4 = {
    Text = "Este es un campo de batalla de voluntad. Tú, como una bestia moribunda, estás usando toda tu fuerza para extraer el último vestigio de poder del mundo espiritual deshidratado."
  },
  AvgDialog_118703_Content_40 = {
    Text = "Fusión·muñeca no dejó nada al azar y rompió tus fantasías, mientras que la otra Doll solo permaneció en silencio."
  },
  AvgDialog_118703_Content_41 = {
    Text = "<Shake: Hemos llegado hasta aquí, esta vez, ahora mismo, quiero llevarte de vuelta.>"
  },
  AvgDialog_118703_Content_42 = {
    Text = "Ramona también comenzó a temblar de las manos. Respiras lentamente y, tratando de parecer relajado, le das una palmadita en la mano."
  },
  AvgDialog_118703_Content_43 = {
    Text = "Ramona, ¿recuerdas nuestra primera reunión?"
  },
  AvgDialog_118703_Content_44 = {
    Text = "Ramona asintió y luego sacudió la cabeza, mirándote con una mirada casi suplicante. No tuviste más remedio que cerrar los ojos y seguir hablando con determinación."
  },
  AvgDialog_118703_Content_45 = {
    Text = "Eso fue verdaderamente un desastre horrible. Después del Big Bang, recuerdo vagamente que todo a mi alrededor se convirtió en ruinas con un estruendo ensordecedor, y cuando abrí los ojos, pensé que había llegado al paraíso."
  },
  AvgDialog_118703_Content_46 = {
    Text = "La luz solar deslumbrante se filtró a través de las piedras excavadas, seguida de tu mano extendiéndose hacia mí."
  },
  AvgDialog_118703_Content_47 = {
    Text = "En ese momento, me preguntaba, ¿es tan extraño el atuendo de un ángel? ¿Es realmente un uniforme tan rígido? No esperaba que pronto, este tipo de uniforme también estuviera en mi propio cuerpo."
  },
  AvgDialog_118703_Content_48 = {
    Text = "Ramona quería decir algo más, pero fuiste interrumpido, y comenzaste a divagar como un anciano sumido en sus recuerdos."
  },
  AvgDialog_118703_Content_49 = {
    Text = "Desde que me sacaron, siempre te consideré la mejor persona, pero después de llegar a Misaq, me di cuenta de que he sido víctima de una gran estafa."
  },
  AvgDialog_118703_Content_5 = {
    Text = "Levantas la llave de plata con las manos temblorosas."
  },
  AvgDialog_118703_Content_50 = {
    Text = "Cuando empecé a leer en la clase preparatoria, dijiste que eras mi compañero y que me ayudarías a resolver todos los problemas de la vida y el estudio, y yo lo creí."
  },
  AvgDialog_118703_Content_51 = {
    Text = "En realidad, tú resolviste mi problema, utilizando el método que aborda la raíz del problema —<Shake:solucioname>."
  },
  AvgDialog_118703_Content_52 = {
    Text = "El llamado compañero, en realidad, es el mayor supervisor. Ese año en el curso preparatorio, quien más me controlaba eras tú."
  },
  AvgDialog_118703_Content_53 = {
    Text = "No solo tengo que supervisar cuando estoy sentado al lado de él en clase, sino también cuando hace la tarea después de clase. A veces, después del entrenamiento físico, ni siquiera me dejan comer un plato de pescado frito con papas, es realmente horrible."
  },
  AvgDialog_118703_Content_54 = {
    Text = "La expresión silenciosa y triste de Ramona se rompió por un instante, y no pudo evitar sonreír levemente."
  },
  AvgDialog_118703_Content_55 = {
    Text = "Pero, mi querido compañero, que también es la persona que más se preocupa por mí."
  },
  AvgDialog_118703_Content_56 = {
    Text = "El idioma universal de Leo que no puedo hablar, la presión de los exámenes que me hace sentir que voy a colapsar, las tareas que no puedo escribir... En todos los momentos tristes, siempre puedes buscar a tu compañero todoterreno."
  },
  AvgDialog_118703_Content_57 = {
    Text = "¿Recuerdas que después de ver por primera vez a un estudiante que sacrificó su vida en una misión, no pude dormir en toda la noche y fui a tocar tu puerta en secreto."
  },
  AvgDialog_118703_Content_58 = {
    Text = "Entonces, ah, me tiraste y corrimos hasta la cima del campanario. Luché por subir al techo detrás de ti. Nos sentamos uno al lado del otro, mirando las estrellas."
  },
  AvgDialog_118703_Content_59 = {
    Text = "Tú y yo hablamos durante mucho, mucho tiempo, sobre muchas, muchas cosas. Esa fue la primera vez que me di cuenta de que tú tampoco sabías cómo era tu madre o tu infancia."
  },
  AvgDialog_118703_Content_6 = {
    Text = "¡Hasta aquí...!——"
  },
  AvgDialog_118703_Content_60 = {
    Text = "Ese corazón mío, que siempre se ha sentido un poco solo y un poco confundido, simplemente cayó de repente."
  },
  AvgDialog_118703_Content_61 = {
    Text = "Creo que, aunque no tengo familia, esta puede ser la única persona en el mundo que me trata tan bien y es tan parecida a mí, como una familia."
  },
  AvgDialog_118703_Content_62 = {
    Text = "Te lo juro de todo corazón, prometo que en el futuro haré mis tareas con seriedad, asistiré a clase con atención y cumpliré con las tareas."
  },
  AvgDialog_118703_Content_63 = {
    Text = "Desde entonces, he considerado a Misaq como mi verdadero hogar, y a través de innumerables tareas posteriores, he conocido a muchos Despertados, cada uno de ellos un nuevo miembro de la familia."
  },
  AvgDialog_118703_Content_64 = {
    Text = "<Yellow:%player%>......"
  },
  AvgDialog_118703_Content_65 = {
    Text = "Así que, gracias, gracias por venir a buscarme, mi familia."
  },
  AvgDialog_118703_Content_66 = {
    Text = "Sé que debieron haber intentado durante mucho tiempo y haber puesto mucho esfuerzo."
  },
  AvgDialog_118703_Content_67 = {
    Text = "Entonces ven conmigo, estoy seguro de que puedo llevarte de vuelta."
  },
  AvgDialog_118703_Content_68 = {
    Text = "Mirando las lágrimas que caían del ojo de Ramona, seguías sonriendo, pero un líquido caliente también fluía incontrolablemente por tu mejilla."
  },
  AvgDialog_118703_Content_69 = {
    Text = "Miras su figura que se vuelve difusa y parpadeante debido a que su fuerza mental ha llegado al límite, y suavemente, sacudes la cabeza."
  },
  AvgDialog_118703_Content_7 = {
    Text = "Una deslumbrante luz plateada florece en tus manos, iluminando toda la dimensión ilusoria."
  },
  AvgDialog_118703_Content_70 = {
    Text = "Aquí lo dejaremos, Ramona."
  },
  AvgDialog_118703_Content_71 = {Text = "No, no..."},
  AvgDialog_118703_Content_72 = {
    Text = "Ramona parecía haber presagiado algo, sacudiendo la cabeza con fuerza mientras sostenía con sus manos difusas tu cuerpo espiritual."
  },
  AvgDialog_118703_Content_73 = {
    Text = "Te lo prometo, definitivamente regresaré..."
  },
  AvgDialog_118703_Content_74 = {
    Text = "Te lo prometo, nos volveremos a ver."
  },
  AvgDialog_118703_Content_75 = {
    Text = "Retiras suavemente la mano de esa palma familiar, liberándola."
  },
  AvgDialog_118703_Content_76 = {
    Text = "Dól al otro lado de la comunicación recibió la señal, y una sensación familiar de retirada del instrumento inundó el espíritu de Ramona, quien sabía que tenía que irse."
  },
  AvgDialog_118703_Content_77 = {
    Text = "\"Ciertamente\"、\"definitivamente\"、igual que las palabras que dijiste cuando entraste por primera vez en la puerta... en realidad, tú mismo no lo crees, ¿verdad?"
  },
  AvgDialog_118703_Content_78 = {
    Text = "Eres realmente una persona cruel..."
  },
  AvgDialog_118703_Content_79 = {
    Text = "Ramona, yo..."
  },
  AvgDialog_118703_Content_8 = {
    Text = "<Shake:¡Uuuhh@2@4@3!!!——>"
  },
  AvgDialog_118703_Content_80 = {
    Text = "Código del Investigador... las promesas hechas deben cumplirse."
  },
  AvgDialog_118703_Content_81 = {
    Text = "Confío en ti. Incluso si no confías en ti mismo y me has engañado innumerables veces, todavía confío en ti."
  },
  AvgDialog_118703_Content_82 = {
    Text = "En esa cara entrelazada con lágrimas y risas, la pupila de Ramona te mira, como si quisiera grabar firmemente tu rostro."
  },
  AvgDialog_118703_Content_83 = {
    Text = "En el último momento antes de que el cuerpo espiritual sea convocado de vuelta al cuerpo, ella extendió su mano hacia ti nuevamente con todas sus fuerzas."
  },
  AvgDialog_118703_Content_84 = {
    Text = "Como aquel momento hace mucho tiempo bajo el cielo estrellado de la noche, ella extendió su meñique y tocó suavemente la punta de tu dedo."
  },
  AvgDialog_118703_Content_85 = {
    Text = "¡Seguro que lo harás, ¿verdad?"
  },
  AvgDialog_118703_Content_86 = {
    Text = "No esperé tu respuesta. En el siguiente instante, esa figura ilusoria se desmoronó junto con el túnel de dimensión, convirtiéndose en un resplandor de estrellas que desapareció lentamente, sin dejar rastro."
  },
  AvgDialog_118703_Content_87 = {Text = "..."},
  AvgDialog_118703_Content_88 = {Text = "..."},
  AvgDialog_118703_Content_89 = {
    Text = "Respiración normal. Frecuencia cardíaca normal. La intensidad mental está por debajo de la alerta... se está recuperando."
  },
  AvgDialog_118703_Content_9 = {Text = "Ah—"},
  AvgDialog_118703_Content_90 = {
    Text = "Sobrevivir después de haber exprimido así la fuerza mental, el cachorro realmente tiene mucha suerte."
  },
  AvgDialog_118703_Content_91 = {
    Text = "Vi una buena actuación. Es una pena que no vi a los dioses que convocaron destruir este mundo; el final no fue lo suficientemente emocionante."
  },
  AvgDialog_118703_Content_92 = {
    Text = "Tranquilo... Te prometí que lo detendría en otro espacio. Una promesa que no puedo cumplir... no habrá una segunda vez."
  },
  AvgDialog_118703_Content_93 = {
    Text = "Estas palabras, mejor guardémoslas para decírselas en persona después de que volvamos."
  },
  AvgDialog_118703_Content_94 = {
    Text = "Dado que he caminado por este camino con ustedes, también quiero ver hasta dónde puedes llegar."
  },
  AvgDialog_118703_Content_95 = {
    Text = "Después de descansar bien, sigue tu camino, perrito."
  },
  AvgDialog_118703_Content_96 = {
    Text = "Sientes el residuo de calor dejado por tus dedos, aprietas lentamente el pequeño dedo que acabas de entrelazar con el suyo, presionándolo con fuerza en tu pecho."
  },
  AvgDialog_118703_Content_97 = {
    Text = "Hacia ese vasto y solitario espacio dimensional, hacia esa figura lejana que ya ha desaparecido, susurras suavemente, hablando de esa promesa que sin duda cumplirás."
  },
  AvgDialog_118703_Content_98 = {
    Text = "Aunque no puedes oírme en este momento, lo haré. ¡Espera por mí, Ramona!"
  },
  AvgDialog_118703_Content_99 = {Text = "..."},
  AvgDialog_118944_Content_1 = {
    Text = "Cortando al último Hombre pez deformado, luchaste mientras retrocedías hacia la niña acorralada."
  },
  AvgDialog_118944_Content_10 = {
    Text = "William intentó abrir la puerta que conducía a la cabina de abajo, pero por más que lo intentó, la trampilla no se movió."
  },
  AvgDialog_118944_Content_11 = {
    Text = "¡No, la puerta ya está sellada desde abajo!"
  },
  AvgDialog_118944_Content_12 = {
    Text = "El casco emitió un escalofriante gemido, y en medio de las enormes olas, empezó a girar con dificultad y determinación, dirigiéndose hacia aguas más oscuras y con tormentas más intensas."
  },
  AvgDialog_118944_Content_13 = {
    Text = "Miryam extendió los brazos, abrazando esta dirección destructiva, con una sonrisa casi maternal en su cara."
  },
  AvgDialog_118944_Content_14 = {
    Text = "¡El ritual está a punto de terminar!"
  },
  AvgDialog_118944_Content_15 = {
    Text = "¿Llegaste a una conclusión?"
  },
  AvgDialog_118944_Content_16 = {
    Text = "En medio de la lucha entre la tormenta y el caos, nadie puede distinguir la posición de todos..."
  },
  AvgDialog_118944_Content_17 = {
    Text = "Solo si hubiera otro barco pequeño..."
  },
  AvgDialog_118944_Content_18 = {
    Text = "Innumerables pistas se iluminan en tu mente..."
  },
  AvgDialog_118944_Content_19 = {
    Text = "Guardián de la sala de estar."
  },
  AvgDialog_118944_Content_2 = {
    Text = "¡Murphy, sigue conmigo!"
  },
  AvgDialog_118944_Content_20 = {
    Text = "Ceremonia de pilotaje en la cubierta."
  },
  AvgDialog_118944_Content_21 = {
    Text = "La explosión de la sala de poder."
  },
  AvgDialog_118944_Content_22 = {
    Text = "Bote salvavidas en la bodega inferior."
  },
  AvgDialog_118944_Content_23 = {
    Text = "Los puntos de luz se conectan, entrelazan y se extienden... convergiendo finalmente en una ruta de escape coherente y clara."
  },
  AvgDialog_118944_Content_24 = {
    Text = "William asintió."
  },
  AvgDialog_118944_Content_25 = {
    Text = "Dado que ya has recibido la respuesta, entonces el objetivo de este ciclo está básicamente completo, no hay necesidad de arrepentirse."
  },
  AvgDialog_118944_Content_26 = {
    Text = "Según la regla que mencionaste, el barco va a comenzar a hundirse."
  },
  AvgDialog_118944_Content_27 = {
    Text = "¿Estás listo?"
  },
  AvgDialog_118944_Content_28 = {
    Text = "La marea ya ha engullido vuestros pechos, sujetas suavemente la llave de plata en tu pecho, susurrando palabras de despedida."
  },
  AvgDialog_118944_Content_29 = {
    Text = "Nos volveremos a encontrar en nuestra próxima reencarnación."
  },
  AvgDialog_118944_Content_3 = {
    Text = "Ella se sobresaltó de repente, su mirada a veces borrosa se esforzó por fijarse en tu cara."
  },
  AvgDialog_118944_Content_30 = {
    Text = "Que la Llave de plata ilumine mi camino."
  },
  AvgDialog_118944_Content_4 = {
    Text = "No, no tiene sentido, todo es ilusión... ya sea avanzar o retroceder, todo..."
  },
  AvgDialog_118944_Content_5 = {
    Text = "¡Mientras no haya llegado el último momento, no te rindas en el intento! ¡Incluso si esta vez fracaso de nuevo, volveré a tomar tu mano!"
  },
  AvgDialog_118944_Content_6 = {Text = "..."},
  AvgDialog_118944_Content_7 = {
    Text = "Murphy te miró fijamente."
  },
  AvgDialog_118944_Content_8 = {
    Text = "Agarras su muñeca con una fuerza suave pero inquebrantable, llevándola lejos de ese rincón desesperado."
  },
  AvgDialog_118944_Content_9 = {
    Text = "¿William, el compañero mayor, hay un camino de escape?"
  },
  AvgDialog_118945_Content_1 = {
    Text = "Pequeño, te contuviste durante la batalla."
  },
  AvgDialog_118945_Content_10 = {
    Text = "Algunas personas crean actos malvados para buscar su propia supervivencia al final del camino."
  },
  AvgDialog_118945_Content_11 = {
    Text = "Algunas personas, impulsadas por sus propias creencias, seleccionan a otros para construir su ideal nuevo mundo."
  },
  AvgDialog_118945_Content_12 = {
    Text = "También hay algunos que, puramente por diversión, pueden provocar un gran caos y crear innumerables problemas."
  },
  AvgDialog_118945_Content_13 = {
    Text = "Esperas, anhelas su respuesta. Porque la has visto venir en un sueño lejano."
  },
  AvgDialog_118945_Content_14 = {
    Text = "La ahora loca Miryam, fue una vez la niña que, en medio del desastre, se dedicó a la misión del sacerdote para proteger a su única familia."
  },
  AvgDialog_118945_Content_15 = {
    Text = "Miryam no respondió directamente a tu pregunta. Juntó las palmas y rezó hacia el lejano horizonte."
  },
  AvgDialog_118945_Content_16 = {
    Text = "\"A quien sea devoto, mi Señor lo cuidará...\""
  },
  AvgDialog_118945_Content_17 = {
    Text = "\"Para todos los que deseen, mi Señor concederá.\""
  },
  AvgDialog_118945_Content_18 = {
    Text = "Como si hubiera recibido el asentimiento del mar, ella entreabrió sus ojos morados y oscuros, perdidos."
  },
  AvgDialog_118945_Content_19 = {
    Text = "Vengo por el renacimiento del Reino Divino, para que la gloria de los dioses se reproduzca en el mundo."
  },
  AvgDialog_118945_Content_2 = {
    Text = "Para mí, esta conversación con Miryam es mucho más crucial que una victoria."
  },
  AvgDialog_118945_Content_20 = {
    Text = "Entonces, cuando Lemuria reaparezca en el mundo, ¿qué tipo de mundo esperas ver?"
  },
  AvgDialog_118945_Content_21 = {
    Text = "\"En el largo sueño de los dioses, tú y yo compartimos paz y felicidad eternas.\""
  },
  AvgDialog_118945_Content_22 = {
    Text = "La gloria de Lemuria renace, tal como te fue inculcado en vida."
  },
  AvgDialog_118945_Content_23 = {
    Text = "Nunca has visto un día así de esplendoroso, ¿realmente sabes cómo crearlo?"
  },
  AvgDialog_118945_Content_24 = {
    Text = "\"Por decreto de Dios, el camino hacia Lemuria se revela para los devotos.\""
  },
  AvgDialog_118945_Content_25 = {
    Text = "El tú de este mundo, es efectivamente idéntico al que conozco."
  },
  AvgDialog_118945_Content_26 = {
    Text = "Entonces, en este momento en que el dios ha nacido, ¿por qué todavía sostienes firmemente a Murphy en tu mano?"
  },
  AvgDialog_118945_Content_3 = {
    Text = "Solo necesitas hacer que Miryam dude un poco, el Dominio revelará su hendidura, su \"núcleo\" oculto..."
  },
  AvgDialog_118945_Content_4 = {
    Text = "Ustedes tienen la esperanza de poner fin por completo a este obstinado sueño artificial."
  },
  AvgDialog_118945_Content_5 = {
    Text = "Por favor, explícame tu intención."
  },
  AvgDialog_118945_Content_6 = {
    Text = "Vine, y traigo una pregunta."
  },
  AvgDialog_118945_Content_7 = {
    Text = "Miryam, ¿por qué deseas revivir el Reino Divino?"
  },
  AvgDialog_118945_Content_8 = {
    Text = "Has planteado una pregunta muy interesante."
  },
  AvgDialog_118945_Content_9 = {
    Text = "He conocido a muchas personas en mi viaje contra la disolución."
  },
  AvgDialog_118946_Content_1 = {
    Text = "Vuelo y libertad"
  },
  AvgDialog_118946_Content_10 = {
    Text = "Ella levantó la yema de su dedo pálido y giró de nuevo la rueca."
  },
  AvgDialog_118946_Content_100 = {
    Text = "Hasta que la oscuridad devore el mundo."
  },
  AvgDialog_118946_Content_11 = {
    Text = "Aunque aún no sé tu nombre, por favor, bendíceme, extraño."
  },
  AvgDialog_118946_Content_12 = {
    Text = "Un grupo de aves voló en formación, levantando olas de plumas blancas. \n Después de que las olas se desvanecieron, la mujer también desapareció."
  },
  AvgDialog_118946_Content_13 = {
    Text = "Le diste a William un resumen rápido del plan general."
  },
  AvgDialog_118946_Content_14 = {
    Text = "Parece un plan nacido del caos."
  },
  AvgDialog_118946_Content_15 = {
    Text = "La ceremonia terminó, estalló la rebelión, justo en el momento más frágil de toda la iglesia de los Marchadores de mares."
  },
  AvgDialog_118946_Content_16 = {
    Text = "Basado en las pistas proporcionadas por Faros, tal vez solo necesitemos obtener la estatua de marfil para escapar del dominio."
  },
  AvgDialog_118946_Content_17 = {
    Text = "¿Es demasiado complicado quitar a Murphy?"
  },
  AvgDialog_118946_Content_18 = {
    Text = "William, el compañero mayor, fuiste tú quien me dijo que los eventos en el dominio podrían afectar el mundo real fuera del dominio."
  },
  AvgDialog_118946_Content_19 = {
    Text = "Si ese es el caso, no puedo hacer la vista gorda con Murphy..."
  },
  AvgDialog_118946_Content_2 = {
    Text = "Otro ciclo."
  },
  AvgDialog_118946_Content_20 = {
    Text = "Goliath tiene la intención de apoderarse del barco, no le importa la fuga de Murphy; Miryam está cansada de lidiar con Goliath y también es incapaz de perseguirlo."
  },
  AvgDialog_118946_Content_21 = {
    Text = "Esta es una excelente oportunidad."
  },
  AvgDialog_118946_Content_22 = {
    Text = "William cerró los ojos y ajustó sus gafas, aparentando dejar escapar un suspiro de resignación."
  },
  AvgDialog_118946_Content_23 = {
    Text = "Escuchándote."
  },
  AvgDialog_118946_Content_24 = {
    Text = "Al igual que en el último ciclo, tú y William están tendiendo una emboscada en la plataforma del mástil."
  },
  AvgDialog_118946_Content_25 = {
    Text = "Aprovechando la rebelión de Goliath, saltaste y agarraste la muñeca de Murphy."
  },
  AvgDialog_118946_Content_26 = {
    Text = "¡Rápido, ven conmigo, salta del barco!"
  },
  AvgDialog_118946_Content_27 = {
    Text = "¿Estás loco? ¿Por qué has vuelto? No podemos escapar, ¿no sería mejor dejar que todo continúe en calma?"
  },
  AvgDialog_118946_Content_28 = {
    Text = "Murphy intentó liberarse de ti, pero tu insistencia era innegable. Un círculo rojo claro apareció en su muñeca."
  },
  AvgDialog_118946_Content_29 = {
    Text = "Murphy, la estabilidad que deseas ya no existe."
  },
  AvgDialog_118946_Content_3 = {
    Text = "Las aves en el mar giran sobre la mujer, sus lamentos suenan como canciones."
  },
  AvgDialog_118946_Content_30 = {
    Text = "Goliath y Caecus planean apoderarse del barco, Faros conspira por el poder de la estatua de marfil, todo el Marchador de mares ya está dividido."
  },
  AvgDialog_118946_Content_31 = {
    Text = "Confía en mí, créeme una vez más. Definitivamente te llevaré a escapar."
  },
  AvgDialog_118946_Content_32 = {
    Text = "¿Escapar, y luego qué?"
  },
  AvgDialog_118946_Content_33 = {
    Text = "Entonces encontraremos una manera de regresar a Misaq, y estarás junto a todos, convirtiéndote en parte de Misaq."
  },
  AvgDialog_118946_Content_34 = {
    Text = "A menudo dicen que mis sueños son proféticos; en un sueño lejano, vi tales visiones..."
  },
  AvgDialog_118946_Content_35 = {
    Text = "Sientes que tu fuerza para resistir se ha debilitado un poco."
  },
  AvgDialog_118946_Content_36 = {
    Text = "¡Vamos, ven conmigo, hacia el lado derecho de la borda... tres, dos, uno, salta!"
  },
  AvgDialog_118946_Content_37 = {
    Text = "¡Plop, plop."
  },
  AvgDialog_118946_Content_38 = {
    Text = "Dos peces saltadores regresan a su leal océano, con las manos aún fuertemente entrelazadas."
  },
  AvgDialog_118946_Content_39 = {
    Text = "La luz del sol entra desde la superficie del mar, iluminando su cabello flotante y su velo en el agua cristalina.\nSus ojos color rosa te miran, como si fuera un sueño silencioso."
  },
  AvgDialog_118946_Content_4 = {
    Text = "No te preocupes, esta vez nuestra preparación es infalible."
  },
  AvgDialog_118946_Content_40 = {
    Text = "Están libres."
  },
  AvgDialog_118946_Content_41 = {Text = "Splash—"},
  AvgDialog_118946_Content_42 = {
    Text = "Un remo se hunde en el agua cristalina frente a mí."
  },
  AvgDialog_118946_Content_43 = {
    Text = "Asientes a Murphy y ambos se aferran al remo del barco."
  },
  AvgDialog_118946_Content_44 = {
    Text = "¿Te has agarrado bien?"
  },
  AvgDialog_118946_Content_45 = {
    Text = "Él los sacó del agua y ustedes se apoyaron en el borde del bote para trepar."
  },
  AvgDialog_118946_Content_46 = {
    Text = "¡Hola, ven a ayudarme!"
  },
  AvgDialog_118946_Content_47 = {
    Text = "¿Qué pasa? ¿No puedes subir por ti mismo?"
  },
  AvgDialog_118946_Content_48 = {
    Text = "¡Menos charlas, aún no he investigado la culpa de hacer caer a la Madre Divina al agua!"
  },
  AvgDialog_118946_Content_49 = {
    Text = "Tiraste suavemente de los hombros de Murphy, que flotaba, con la fuerza justa para sacarla de la superficie del agua."
  },
  AvgDialog_118946_Content_5 = {
    Text = "Sabemos que el barco volcará después de que termine el ritual de navegación; sabemos que la estatua de marfil tiene el poder de manipular sueños."
  },
  AvgDialog_118946_Content_50 = {Text = "Uf—"},
  AvgDialog_118946_Content_51 = {
    Text = "Está bien, ahora podemos hablar correctamente. ¿A dónde vamos?"
  },
  AvgDialog_118946_Content_52 = {
    Text = "Aprovechando la confusión entre Goliat y Miryam, los tres de nosotros conduciremos este barco juntos y navegaremos fuera del límite del Dominio."
  },
  AvgDialog_118946_Content_53 = {
    Text = "Luego, juntos encontraremos el camino de regreso al mundo original, donde te encontrarás contigo mismo de ese mundo, compitiendo por pastelitos en la cafetería todos los días..."
  },
  AvgDialog_118946_Content_54 = {
    Text = "Puf, eso será un viaje largo."
  },
  AvgDialog_118946_Content_55 = {
    Text = "Si ese es el caso, entonces cuéntame bien sobre... ese lugar llamado Misaq."
  },
  AvgDialog_118946_Content_56 = {Text = "..."},
  AvgDialog_118946_Content_57 = {Text = "..."},
  AvgDialog_118946_Content_58 = {
    Text = "¿Y luego, y luego?"
  },
  AvgDialog_118946_Content_59 = {
    Text = "Entonces, Ramona descubrió el vino oculto del Señor Dexter en la esquina de su estantería. Para esconder esos vinos, había ahuecado algunas páginas de los libros."
  },
  AvgDialog_118946_Content_6 = {
    Text = "También sabemos que en la cubierta inferior hay un único bote salvavidas, y una vez que nos alejemos de este crucero, ya no estaremos bajo las ataduras de Miryam."
  },
  AvgDialog_118946_Content_60 = {
    Text = "Con el rabillo del ojo, notaste a William con la cabeza agachada, frunciendo el ceño y frotándose las sienes."
  },
  AvgDialog_118946_Content_61 = {
    Text = "¡Ella estaba ardiendo de rabia, irrumpiendo directamente en el salón de la señora Sorel con su delgada espada!"
  },
  AvgDialog_118946_Content_62 = {Text = "¿Y luego?"},
  AvgDialog_118946_Content_63 = {
    Text = "Murphy estaba nerviosa, aferrándose a tu manga, con el estómago emocionado por las nuevas historias."
  },
  AvgDialog_118946_Content_64 = {
    Text = "La risa y el murmullo en el salón se congelaron de repente, ¡todos miraron con los ojos muy abiertos a este invitado indeseado!"
  },
  AvgDialog_118946_Content_65 = {
    Text = "¡Exactamente, así como el compañero mayor William ahora!"
  },
  AvgDialog_118946_Content_66 = {Text = "Hay..."},
  AvgDialog_118946_Content_67 = {
    Text = "¡Hay asesinos, hay asesinos! ¡La gente grita por todas partes!"
  },
  AvgDialog_118946_Content_68 = {
    Text = "Tu sonrisa se congeló en tu cara."
  },
  AvgDialog_118946_Content_69 = {
    Text = "Detrás de Murphy, el borde del pequeño barco, un monstruo imponente formado por millones de cadáveres fusionados se eleva repentinamente desde la superficie del mar."
  },
  AvgDialog_118946_Content_7 = {
    Text = "Nuestro plan es que yo interrumpa el ritual de pilotaje y, mientras Murphy esté debilitada, la lleve a saltar al mar."
  },
  AvgDialog_118946_Content_70 = {Text = "<Big:...>"},
  AvgDialog_118946_Content_71 = {
    Text = "Él abre silenciosamente una enorme boca formada por huesos y cráneos en movimiento——"
  },
  AvgDialog_118946_Content_72 = {
    Text = "<Red:Tragarse a Murphy entero>"
  },
  AvgDialog_118946_Content_73 = {
    Text = "<Shake:No... la Marioneta de la Putrefacción... ¿no debería haber estado en la Necrovia...>"
  },
  AvgDialog_118946_Content_74 = {
    Text = "En este Dominio, Goliath aún estaba manipulando la Marioneta de la Putrefacción."
  },
  AvgDialog_118946_Content_75 = {
    Text = "Su fuerza principal está enfrentándose a Miryam, así que despachó este grupo externo para perseguir..."
  },
  AvgDialog_118946_Content_76 = {
    Text = "Nosotros... ¡mal cálculo."
  },
  AvgDialog_118946_Content_77 = {
    Text = "<Big:<Shake:...!!!>>"
  },
  AvgDialog_118946_Content_78 = {
    Text = "El monstruo que devoró a Murphy levantó su extraña cabeza en alto, produciendo un sonido de gorgoteo satisfecho desde su garganta."
  },
  AvgDialog_118946_Content_79 = {
    Text = "La niebla sucia se dispersa sobre la superficie del mar, el Paradeis ya no se puede ver a lo lejos, solo los picos de los huesos se ciernen sobre nosotros, cubriendo el cielo y la tierra."
  },
  AvgDialog_118946_Content_8 = {
    Text = "William, el compañero mayor, conducirá el bote salvavidas para recogerme a mí y a Murphy. Una vez que suba a bordo, desentrañaré lo antes posible el misterio de la estatua de marfil y escaparé del dominio."
  },
  AvgDialog_118946_Content_80 = {
    Text = "¡Esquiva rápido!"
  },
  AvgDialog_118946_Content_81 = {
    Text = "William te abrazó con fuerza, desorientado, rodando hacia el lado del barco, esquivando por poco el primer golpe brutal de la garra ósea."
  },
  AvgDialog_118946_Content_82 = {
    Text = "William, el compañero mayor, tu espalda..."
  },
  AvgDialog_118946_Content_83 = {
    Text = "Sangre, sangre goteante."
  },
  AvgDialog_118946_Content_84 = {
    Text = "¡No te preocupes por mí, sube y corta la columna vertebral de la Marioneta de la Putrefacción!"
  },
  AvgDialog_118946_Content_85 = {Text = "..."},
  AvgDialog_118946_Content_86 = {Text = "<Big:...>"},
  AvgDialog_118946_Content_87 = {
    Text = "La Marioneta de la Putrefacción se derrumba como una torre, lloviendo huesos pálidos en un océano infinito."
  },
  AvgDialog_118946_Content_88 = {
    Text = "Como dijiste... la fuerza de Goliat se ha debilitado enormemente en el Dominio."
  },
  AvgDialog_118946_Content_89 = {
    Text = "Así que apenas podemos resistir..."
  },
  AvgDialog_118946_Content_9 = {
    Text = "La mujer bajó la cabeza, con su flequillo cubriendo su expresión."
  },
  AvgDialog_118946_Content_90 = {
    Text = "Quizás sea porque la lesión es demasiado grave que ya no puedes escuchar las palabras de William."
  },
  AvgDialog_118946_Content_91 = {
    Text = "Entre la marea de cadáveres colapsados y los huesos, no se ve la figura de esa niña."
  },
  AvgDialog_118946_Content_92 = {
    Text = "Murphy... ¡Murphy!"
  },
  AvgDialog_118946_Content_93 = {
    Text = "Te lanzas contra los huesos flotantes, excavando en los cráneos acumulados, pieza por pieza, hacia el tracto digestivo."
  },
  AvgDialog_118946_Content_94 = {
    Text = "<Yellow:%player%>......"
  },
  AvgDialog_118946_Content_95 = {
    Text = "No se puede encontrar a Murphy en ningún lugar."
  },
  AvgDialog_118946_Content_96 = {
    Text = "En el centro de los huesos dispuestos de forma desordenada, solo hay un delgado y ligero velo negro."
  },
  AvgDialog_118946_Content_97 = {
    Text = "Sostienes suavemente ese trozo de velo negro, y una punzada de tristeza surge en tu corazón."
  },
  AvgDialog_118946_Content_98 = {
    Text = "Pensé que esta vez, definitivamente podría sacarla de aquí..."
  },
  AvgDialog_118946_Content_99 = {
    Text = "Emites un sollozo profundo. Luego, el llanto se vuelve gradualmente más fuerte."
  },
  AvgDialog_118947_Content_1 = {
    Text = "\"ParaísoN.º\""
  },
  AvgDialog_118947_Content_10 = {
    Text = "Sacas la bandeja del horno con unas pinzas, y Murphy inmediatamente, impaciente, extiende la mano para recoger un pastelito que emite vapor."
  },
  AvgDialog_118947_Content_11 = {
    Text = "No te apresures, ¡quema quema quema quema quema!"
  },
  AvgDialog_118947_Content_12 = {
    Text = "Parece que Murphy no podía soltarlo, se quemó las manos alternando entre la izquierda y la derecha varias veces, y finalmente esperó a que el pastel bajara a una temperatura adecuada."
  },
  AvgDialog_118947_Content_13 = {
    Text = "Prueba un poco... parece que no necesito decirlo."
  },
  AvgDialog_118947_Content_14 = {
    Text = "Antes de que tus palabras tocaran el suelo, Murphy ya había dado un mordisco."
  },
  AvgDialog_118947_Content_15 = {
    Text = "¿Qué tal, es delicioso?"
  },
  AvgDialog_118947_Content_16 = {
    Text = "La receta depende completamente de tu memoria. Para atender a la joven que llora de hambre a medianoche, has utilizado varias veces la cocina trasera de Misaq."
  },
  AvgDialog_118947_Content_17 = {
    Text = "Hmph, los ingredientes son demasiado simples, no se pueden comparar con lo que Miryam normalmente me proporciona."
  },
  AvgDialog_118947_Content_18 = {
    Text = "Murphy tragó con cuidado los restos en su boca y dijo con seriedad."
  },
  AvgDialog_118947_Content_19 = {
    Text = "Sin embargo, ¿quién puede culpar a la Madre divina por su increíble talento culinario, que es suficiente para transformar la podredumbre en lo milagroso."
  },
  AvgDialog_118947_Content_2 = {Text = "..."},
  AvgDialog_118947_Content_20 = {
    Text = "Cálido y suave... esta es la comida más deliciosa que he probado."
  },
  AvgDialog_118947_Content_21 = {
    Text = "Voy a probar un trozo también."
  },
  AvgDialog_118947_Content_22 = {
    Text = "William levantó cuidadosamente un trozo con un pequeño cuchillo plateado y se lo metió en la boca."
  },
  AvgDialog_118947_Content_23 = {
    Text = "Compañero mayor, si no me equivoco, ¿el bisturí que usas para cortar pasteles es el que usaste para operar a Nubia anteriormente?"
  },
  AvgDialog_118947_Content_24 = {
    Text = "Ha sido desinfectado por completo. Los cuchillos y tenedores toscos utilizados por los marineros son realmente difíciles de usar para comer."
  },
  AvgDialog_118947_Content_25 = {
    Text = "Debería haberle pedido a Doresain dos juegos de cubiertos en Necrovia...\nOlvídalo, pensándolo bien, es aún más difícil decir con qué se han contaminado los cubiertos de Doresain..."
  },
  AvgDialog_118947_Content_26 = {
    Text = "Ustedes se deleitan, riendo mientras se untan crema en la cara unos a otros."
  },
  AvgDialog_118947_Content_27 = {
    Text = "(Si este es su último recuerdo...)"
  },
  AvgDialog_118947_Content_28 = {Text = "Bang—"},
  AvgDialog_118947_Content_29 = {
    Text = "Un estruendo rompió la rara tranquilidad, y la cocina en la que te encuentras comenzó a temblar intensamente e incontrolablemente."
  },
  AvgDialog_118947_Content_3 = {
    Text = "Varios minutos después."
  },
  AvgDialog_118947_Content_30 = {
    Text = "¿¡Qué está pasando?!"
  },
  AvgDialog_118947_Content_31 = {
    Text = "Goliath asaltó la sala de poder, Miriam resistió con fuerza y hubo una explosión en la sala de poder."
  },
  AvgDialog_118947_Content_32 = {
    Text = "Respondes con indiferencia."
  },
  AvgDialog_118947_Content_33 = {
    Text = "En otras palabras, el barco se está hundiendo."
  },
  AvgDialog_118947_Content_34 = {
    Text = "¡El barco se está hundiendo, ¿no tienes ninguna reacción?"
  },
  AvgDialog_118947_Content_35 = {
    Text = [[
Murphy, tengo algo que decirte.
Este barco debe hundirse.]]
  },
  AvgDialog_118947_Content_36 = {
    Text = "He experimentado cinco ciclos, en cada uno de los cuales Goliath trama secuestrar barcos."
  },
  AvgDialog_118947_Content_37 = {
    Text = "Este proceso provocará una explosión en la sala de energía, y luego el barco será absorbido por un vórtice hacia el fondo del mar."
  },
  AvgDialog_118947_Content_38 = {
    Text = "¿Entonces?"
  },
  AvgDialog_118947_Content_39 = {
    Text = "He estado tratando de encontrar formas de detener la destrucción de este barco; ahí fue donde mis pensamientos se desviaron."
  },
  AvgDialog_118947_Content_4 = {
    Text = "Ustedes miran el horno, la masa amasada se hincha poco a poco, y su corazón expectante también se expande con esa curva esponjosa."
  },
  AvgDialog_118947_Content_40 = {
    Text = "Este barco debe hundirse... solo cuando se hunda podrá abrir un camino de libertad para ti."
  },
  AvgDialog_118947_Content_41 = {
    Text = "¡Boom!——"
  },
  AvgDialog_118947_Content_42 = {
    Text = "El casco del barco se contrajo y tembló como si hubiera sido electrocutado, como si una bestia gigante estuviera convulsionando incontrolablemente en medio del dolor de una explosión."
  },
  AvgDialog_118947_Content_43 = {
    Text = "Está bien, no es necesario explicar tanto ahora, solo ven conmigo."
  },
  AvgDialog_118947_Content_44 = {
    Text = "Si llegamos más tarde, ya no habrá tiempo para nada."
  },
  AvgDialog_118947_Content_45 = {
    Text = "Tiras de Murphy y caminas por el camino señalado por William."
  },
  AvgDialog_118947_Content_46 = {
    Text = "Hola, ¿realmente vas a hacer que una dama suba una escalera? Usar manos y pies frente a extraños es simplemente demasiado embarazoso, ¿no?!"
  },
  AvgDialog_118947_Content_47 = {
    Text = "Ve abajo y espera por mí, no me agacharé para mirarte."
  },
  AvgDialog_118947_Content_48 = {
    Text = "Los ojos se adaptaron gradualmente a la oscuridad, en la esquina de la bodega, había una pequeña embarcación detenida, sola."
  },
  AvgDialog_118947_Content_49 = {
    Text = "Esta es la ruta de escape que Goliat preparó para sí mismo, que encontramos."
  },
  AvgDialog_118947_Content_5 = {
    Text = "El aroma del ponche de huevo se esparce, las glándulas salivales lo perciben antes que el cerebro, y el gusanillo del hambre hace que tu estómago gruñe."
  },
  AvgDialog_118947_Content_50 = {
    Text = "Este astuto individuo, antes de iniciar la rebelión, destruyó casi todos los botes salvavidas, asegurándose de que solo él pudiera escapar."
  },
  AvgDialog_118947_Content_51 = {
    Text = "Aquí tienes, la llave de repuesto, que preparé con William. Ahora, aborda el barco."
  },
  AvgDialog_118947_Content_52 = {
    Text = "Espera, ¿de qué estás hablando? Nunca estuve de acuerdo en escapar contigo——"
  },
  AvgDialog_118947_Content_53 = {
    Text = "Nunca dije que abordaría el barco contigo. Aquí hay un solo bote salvavidas. Tómalo solo, luego desembarca."
  },
  AvgDialog_118947_Content_54 = {Text = "!"},
  AvgDialog_118947_Content_55 = {
    Text = "Si simplemente nos vamos, Miryam no lo dejará pasar fácilmente. Las sombras de los Marchadores de mares te alcanzarán un día."
  },
  AvgDialog_118947_Content_56 = {
    Text = "Debo quedarme aquí para asegurarme de que los Marchadores de mares y el Feto Sagrado se hundan para siempre en el Aequor."
  },
  AvgDialog_118947_Content_57 = {
    Text = "Esto es también lo que les deleita, regresar a su patria eterna y al Reino Divino, ¿no es así?"
  },
  AvgDialog_118947_Content_58 = {Text = "¡Pff!"},
  AvgDialog_118947_Content_59 = {
    Text = "Murphy rió entre lágrimas."
  },
  AvgDialog_118947_Content_6 = {
    Text = "Los pasos ansiosos y húmedos de los Marchadores de mares resonaban de vez en cuando por el suelo de madera, pero la delgada puerta separaba dos mundos; este pequeño espacio estaba lleno de una felicidad y calidez que eran excesivamente simples, como un Fantasma."
  },
  AvgDialog_118947_Content_60 = {
    Text = "Ya había planeado esto antes de partir."
  },
  AvgDialog_118947_Content_61 = {
    Text = "Si puedo enviarte a escapar, entonces ese es el mejor final."
  },
  AvgDialog_118947_Content_62 = {
    Text = "Si eso no sucede... al menos he intentado recrear un día que el Murphy que conozco disfrutaría."
  },
  AvgDialog_118947_Content_63 = {
    Text = "No nos conocemos desde hace mucho tiempo, y no te conozco lo suficientemente bien. Espero que a ti también te guste."
  },
  AvgDialog_118947_Content_64 = {
    Text = "Murphy se puso de puntillas y te dio un abrazo suave."
  },
  AvgDialog_118947_Content_65 = {
    Text = "Recuerdo que dijiste antes que experimentarías el ciclo de la reencarnación una y otra vez."
  },
  AvgDialog_118947_Content_66 = {
    Text = "Esta vez no será el final."
  },
  AvgDialog_118947_Content_67 = {
    Text = "La próxima vez, llévame contigo a escapar, ¿de acuerdo?"
  },
  AvgDialog_118947_Content_68 = {
    Text = "<Red:No habrá una próxima vez.>\nUna sensación agria sube a la punta de tu nariz."
  },
  AvgDialog_118947_Content_69 = {
    Text = "Te lo prometo. Escaparemos juntos."
  },
  AvgDialog_118947_Content_7 = {
    Text = "¡Mira, la piel ya ha cambiado de color, se puede servir!"
  },
  AvgDialog_118947_Content_70 = {
    Text = "Con nubes densas en el cielo, bajo la figura de proa del barco, Miryam y Goliath se confrontan desde lejos."
  },
  AvgDialog_118947_Content_71 = {
    Text = "Entrega a la niña y la estatua de marfil, y puedo concederte una muerte digna, como alguna vez amenazaste."
  },
  AvgDialog_118947_Content_72 = {
    Text = "Dejen de hablar tonterías aquí, ¿no son ustedes los que robaron a la Madre Divina y provocaron este alboroto?"
  },
  AvgDialog_118947_Content_73 = {
    Text = "No tienen que discutir más, Murphy ya no está en este barco.\nElla ya ha escapado de las garras y se ha alejado del vórtice."
  },
  AvgDialog_118947_Content_74 = {
    Text = "Una sensación de alivio inexplicable surgió en mi corazón."
  },
  AvgDialog_118947_Content_75 = {
    Text = "¿Eres tú quien la envió? Bastante audaz de tu parte."
  },
  AvgDialog_118947_Content_76 = {
    Text = "Si ustedes están preparando una gran batalla aquí, no me importaría beneficiarme del caos."
  },
  AvgDialog_118947_Content_77 = {
    Text = "En realidad eres tú, este insignificante forastero..."
  },
  AvgDialog_118947_Content_78 = {
    Text = "¿Crees que con la protección de la Madre divina puedes hacer lo que quieras?"
  },
  AvgDialog_118947_Content_79 = {
    Text = "Miryam, quiero hablar contigo."
  },
  AvgDialog_118947_Content_8 = {
    Text = "...¡Está bien!"
  },
  AvgDialog_118947_Content_80 = {
    Text = "¿No se trata de declarar la guerra de manera grosera y temeraria, sino de comenzar con una conversación?"
  },
  AvgDialog_118947_Content_81 = {
    Text = "También tengo curiosidad, ¿qué tipo de necio imprudente eres, para ser convocado por la Madre divina y aún así actuar de manera tan imprudente y audaz."
  },
  AvgDialog_118947_Content_82 = {
    Text = "Si le pides sinceramente al apóstol de Dios respuestas, podría concederte la voluntad divina."
  },
  AvgDialog_118947_Content_83 = {
    Text = "<Red:<Shake:¡Pero ahora, soporta la ira del marinero!>>"
  },
  AvgDialog_118947_Content_9 = {
    Text = "El aroma de ponche de huevo surge."
  },
  AvgDialog_118948_Content_1 = {Text = "vórtice"},
  AvgDialog_118948_Content_10 = {
    Text = "\"Clic\", el hilo plateado se rompió de repente."
  },
  AvgDialog_118948_Content_11 = {
    Text = "Caecus es ajeno a ello, solo te mira con desconfianza."
  },
  AvgDialog_118948_Content_12 = {
    Text = "Amigo, ¿qué dices, amigo?"
  },
  AvgDialog_118948_Content_13 = {
    Text = "¡Debe ser la técnica que confunde el corazón! ¡No escuches a {Male=él,Female=ella}, Maestro Caecus!"
  },
  AvgDialog_118948_Content_14 = {
    Text = "La contraseña, sí, la contraseña..."
  },
  AvgDialog_118948_Content_15 = {
    Text = "Caecus respiró hondo, como si el valor hubiera sido reintegrado en su cuerpo, y de repente levantó la cabeza."
  },
  AvgDialog_118948_Content_16 = {
    Text = "Solo sé que el Marchador de mares te ha asentado temporalmente, pero esto no significa que puedas entrar y salir libremente de lugares clave."
  },
  AvgDialog_118948_Content_17 = {
    Text = "¡Siguiendo la orden del señor Goliat, nadie ajeno puede entrar en la sala de poder!"
  },
  AvgDialog_118948_Content_2 = {
    Text = "Mira allá, parece que hay alguien vigilando la sala de poder."
  },
  AvgDialog_118948_Content_3 = {
    Text = "Varios cuerpos encorvados deambulaban, entre ellos, un joven de postura erguida sostenía firmemente una lanza membranosa, alerta cautelosamente a los movimientos del viento y la hierba circundantes."
  },
  AvgDialog_118948_Content_4 = {
    Text = "¡Cuidado! La importante tarea organizada por el Señor Goliat no debe salir mal..."
  },
  AvgDialog_118948_Content_5 = {Text = "¡Caecus!"},
  AvgDialog_118948_Content_6 = {
    Text = "¿Eh, tú eres...?"
  },
  AvgDialog_118948_Content_7 = {
    Text = "Intentas activar la llave de plata, conectándote con su conciencia para despertar los recuerdos de vuestro pasado."
  },
  AvgDialog_118948_Content_8 = {
    Text = "Tentáculos de luz plateada se extienden, trepando a lo largo de la superficie de su cuerpo cubierta de escamas, adentrándose en su médula espinal..."
  },
  AvgDialog_118948_Content_9 = {
    Text = "Caecus, soy tu amigo, ¿puedes dejarme entrar detrás de ti...?"
  },
  AvgDialog_118949_Content_1 = {
    Text = "Lo siento, Lord Goliath..."
  },
  AvgDialog_118949_Content_10 = {
    Text = "Pero ahora es un momento crítico en el plan; la variable debe minimizarse tanto como sea posible."
  },
  AvgDialog_118949_Content_11 = {
    Text = "Cállate aquí para siempre, pequeño."
  },
  AvgDialog_118949_Content_12 = {
    Text = "¡Señor Goliat, iré a la batalla contigo!"
  },
  AvgDialog_118949_Content_13 = {
    Text = "No es necesario, cosas que no pueden resistir el viento, aquí no tenemos espacio para desenvolvemos."
  },
  AvgDialog_118949_Content_14 = {
    Text = "<Small:Pero yo...>"
  },
  AvgDialog_118949_Content_15 = {
    Text = "Caecus murmura en voz baja, pero la reciente batalla perdida le hace darse cuenta de que no tiene motivos para quejarse, así que guarda silencio y retrocede un paso."
  },
  AvgDialog_118949_Content_16 = {
    Text = "Caecus, niño."
  },
  AvgDialog_118949_Content_17 = {Text = "¿Hm?"},
  AvgDialog_118949_Content_18 = {
    Text = "Goliath no se dio la vuelta."
  },
  AvgDialog_118949_Content_19 = {
    Text = "No te desanimes, eres la persona que elegí. Una vez que termine este asunto, te agregaré 500 sesiones de entrenamiento más."
  },
  AvgDialog_118949_Content_2 = {
    Text = "Hm, no te asustes tanto."
  },
  AvgDialog_118949_Content_20 = {
    Text = "¡Ah...! ¡Sí!"
  },
  AvgDialog_118949_Content_21 = {
    Text = "Faros, ¿estás listo?"
  },
  AvgDialog_118949_Content_22 = {
    Text = "Solo es para construir la escalera hacia el Reino Divino... Faros siempre estará a su disposición."
  },
  AvgDialog_118949_Content_3 = {
    Text = "Goliath sale lentamente con la espada en mano, la hoja dentada arrastrándose por el suelo y emitiendo un sonido chirriante."
  },
  AvgDialog_118949_Content_4 = {
    Text = "Con este pequeño ruido no pueden manejarlo, realmente es una vergüenza para la raza filistea."
  },
  AvgDialog_118949_Content_5 = {
    Text = "Lo siento, yo..."
  },
  AvgDialog_118949_Content_6 = {
    Text = "Gu... Señor Goliat, no culpe al Señor Caecus, ¡ese tipo que nunca ha visto puede convocar monstruos invisibles!"
  },
  AvgDialog_118949_Content_7 = {
    Text = "Otro... Hola, pequeño, eres tú."
  },
  AvgDialog_118949_Content_8 = {
    Text = "Olvídate de Necrovia, aquí no hay lugar para que te desplaces."
  },
  AvgDialog_118949_Content_9 = {
    Text = "Si nos encontramos un poco más tarde, quizás podamos tomarnos un tiempo para sentarnos y charlar."
  },
  AvgDialog_118950_Content_1 = {
    Text = "El cielo está ardiendo."
  },
  AvgDialog_118950_Content_10 = {
    Text = "Una línea de sangre roja se extiende constantemente detrás de él, fusionándose con la veta de la cubierta de madera."
  },
  AvgDialog_118950_Content_11 = {
    Text = "<Red:¡Muere, bastardo, hereje!>"
  },
  AvgDialog_118950_Content_12 = {
    Text = "El sacerdote, con los ojos desorbitados, levantó la lanza que pertenecía al joven y la clavó con precisión y crueldad en la espalda del joven. La punta afilada atravesó su cuerpo, clavándolo firmemente en la cubierta."
  },
  AvgDialog_118950_Content_13 = {
    Text = "El joven se estremeció una vez y luego permaneció a un paso de distancia del hombre."
  },
  AvgDialog_118950_Content_14 = {
    Text = "¡Ja, ja, ja, ja!"
  },
  AvgDialog_118950_Content_15 = {
    Text = "¡Oh, mi Señor, mi gran Señor, ¿has visto esto? ¡Este es el sacramento que ofrezco a ti, junto con la Madre divina!"
  },
  AvgDialog_118950_Content_16 = {
    Text = "Miryam, cubierta de manchas de sangre, miraba desde lejos esta pintura infernal, riendo locamente hacia el cielo, con las vestiduras de sacerdote desgarradas ondeando en las llamas."
  },
  AvgDialog_118950_Content_17 = {
    Text = "<Shake:¡Que su Reino Divino resurja del Abismo una vez más, que su voluntad se restablezca pronto en la Tierra!>"
  },
  AvgDialog_118950_Content_18 = {
    Text = "La mirada del Gran Sacerdote examina su territorio, recorriendo los Faros divididos en dos por una enorme cuchilla, cruzando a los dos investigadores gravemente heridos e incapaces de moverse, y deteniéndose sobre la niña empapada en sangre y veneno bajo el velo negro."
  },
  AvgDialog_118950_Content_19 = {
    Text = "¡Madre divina, ven a mí! He sancionado a todos los traidores que abandonaron la luz y a los caídos que profanaron lo divino!"
  },
  AvgDialog_118950_Content_2 = {
    Text = "El mar está ardiendo."
  },
  AvgDialog_118950_Content_20 = {
    Text = "El casco roto perdió el equilibrio debido al agua que se filtraba, la mitad del barco ya estaba sumergida, pero ella estaba completamente inconsciente."
  },
  AvgDialog_118950_Content_21 = {
    Text = "<Red:<Shake:Siguiente, depende de nosotros heredar la inmortalidad del Reino Divino, hasta la próxima vez que las estrellas estén en lo cierto, ¡Su santo nombre será cantado en todo el universo!>>"
  },
  AvgDialog_118950_Content_22 = {
    Text = "En la punta de la proa del barco, inclinada como una guillotina, Miryam extiende una mano ensangrentada desde lo alto."
  },
  AvgDialog_118950_Content_23 = {
    Text = "<Shake:No, no es... no es...>"
  },
  AvgDialog_118950_Content_24 = {
    Text = "Las piernas de Murphy se debilitaron y cayó de rodillas. \n Su pequeño cuerpo había perdido por completo la elegancia de antaño, temblando a la luz del fuego."
  },
  AvgDialog_118950_Content_25 = {
    Text = "<Shake:Lo siento, no debería... no debería querer escapar...>"
  },
  AvgDialog_118950_Content_26 = {
    Text = "Las lágrimas ruedan, manchando la cubierta con marcas de agua moteadas, solo para ser lamidas secas por el calor de las llamas."
  },
  AvgDialog_118950_Content_27 = {
    Text = "<Red:<Shake:Debería haberlo sabido, este es el destino que no puedo evitar, no puedo escapar...>>"
  },
  AvgDialog_118950_Content_28 = {
    Text = "Murphy... no es así, Murphy, aún hay oportunidades..."
  },
  AvgDialog_118950_Content_29 = {
    Text = "Estás ansioso por acercarte a consolar a esa niña, pero tu cuerpo traiciona tu voluntad."
  },
  AvgDialog_118950_Content_3 = {
    Text = "No, no es así... solo que tu campo de visión está ardiendo.\nLa muerte y la desesperación cubren esta tierra sin dueño sobre el océano."
  },
  AvgDialog_118950_Content_30 = {
    Text = "Un dolor agudo en el tobillo desgarraba cada una de tus percepciones, la plaga sufrida en la batalla anterior te mantenía firmemente clavado en el lugar, incapaz de moverte."
  },
  AvgDialog_118950_Content_31 = {Text = "Lo siento."},
  AvgDialog_118950_Content_32 = {
    Text = "Ignorando la herida sangrante en su pecho, la joven se levantó con calma."
  },
  AvgDialog_118950_Content_33 = {
    Text = "El dolor ya no puede detenerla; no hay vacilación, no hay fantasía y no hay apego."
  },
  AvgDialog_118950_Content_34 = {
    Text = "Cruzando montañas de cadáveres, cruzando mares de fuego. \n Ella avanza con pasos solemnes, acercándose al sacerdote paso a paso."
  },
  AvgDialog_118950_Content_35 = {
    Text = "No... no puede terminar aquí..."
  },
  AvgDialog_118950_Content_36 = {
    Text = "William... ¡Señor William...! ¿Todavía puedes moverte?"
  },
  AvgDialog_118950_Content_37 = {
    Text = "¿Qué quieres... hacer?"
  },
  AvgDialog_118950_Content_38 = {
    Text = "William yacía en un charco de sangre, jadeando por aire."
  },
  AvgDialog_118950_Content_39 = {
    Text = "<Red:<Big:......Mátame, reinicia el ciclo.>>"
  },
  AvgDialog_118950_Content_4 = {
    Text = "Las explosiones en cadena desgarraron la sala de poder, y la cubierta en llamas se elevó en distorsión."
  },
  AvgDialog_118950_Content_40 = {
    Text = "No, ¿por qué...?"
  },
  AvgDialog_118950_Content_41 = {
    Text = "No puedo permitir que este mundo se convierta en el final... no puedo aceptar tal resultado..."
  },
  AvgDialog_118950_Content_42 = {
    Text = "¡Apresúrate, ya no puedo moverme..."
  },
  AvgDialog_118950_Content_43 = {
    Text = "El brazo mecánico de William se había desprendido de su cuerpo; luchó por extender su brazo aún móvil y agarró la daga que había arrojado Miryam."
  },
  AvgDialog_118950_Content_44 = {
    Text = "Lo siento, no puedo mostrarte mi expresión en este momento..."
  },
  AvgDialog_118950_Content_45 = {
    Text = "Luego, un dolor punzante irradia desde tu lado izquierdo de la espalda."
  },
  AvgDialog_118950_Content_46 = {
    Text = "¡No te acerques!"
  },
  AvgDialog_118950_Content_47 = {
    Text = "¡Sumo Sacerdote, captura a ese tipo vivo, no dejes que {Male=él,Female=ella} muera!"
  },
  AvgDialog_118950_Content_48 = {
    Text = "Con una orden de Miryam, otro tridente atravesó el pecho de William. Miraste hacia atrás en estado de shock, solo para ver una melena dorada cayendo suavemente."
  },
  AvgDialog_118950_Content_49 = {
    Text = "El sacerdote hombre pez giró extrañamente en su lugar, estallando en risas."
  },
  AvgDialog_118950_Content_5 = {
    Text = "Antiguos compañeros que lucharon a tu lado, enemigos que batallaron ferozmente, yacen indistintamente en el ardiente y carmesí charco de sangre."
  },
  AvgDialog_118950_Content_50 = {
    Text = "¡Gu, ji ji! ¡No puedes hacer nada de lo que quieras ahora!"
  },
  AvgDialog_118950_Content_51 = {
    Text = "El corazón duele más que un corte de cuchillo, las extremidades frías y escarchadas por la pérdida de sangre."
  },
  AvgDialog_118950_Content_52 = {
    Text = "<Red:Debes morir>, debes proceder al siguiente ciclo."
  },
  AvgDialog_118950_Content_53 = {
    Text = "<Red:<Shake:Yo... definitivamente puedo...>>"
  },
  AvgDialog_118950_Content_54 = {
    Text = "Usando la tabla del barco para bloquear la daga"
  },
  AvgDialog_118950_Content_55 = {
    Text = "La daga se hunde poco a poco en tu cuerpo, seguida de un dolor que penetra hasta el hueso."
  },
  AvgDialog_118950_Content_56 = {
    Text = "Cayendo hacia atrás con fuerza"
  },
  AvgDialog_118950_Content_57 = {
    Text = "Una hoja afilada atraviesa tu pecho, una sensación de vacío de conciencia te envuelve en tu campo de visión."
  },
  AvgDialog_118950_Content_58 = {
    Text = "<Shake:¡Murphy... William... por favor, asegúrense de esperarme en el próximo ciclo.>"
  },
  AvgDialog_118950_Content_59 = {
    Text = "<Yellow:¡Definitivamente escaparemos...!>"
  },
  AvgDialog_118950_Content_6 = {
    Text = "<Shake:¡Señor Goliat, lo siento, si fuera un poco más fuerte...>"
  },
  AvgDialog_118950_Content_7 = {
    Text = "El joven gravemente herido arrastra su cuerpo destrozado, esforzándose por rasguñar el suelo áspero con sus diez dedos, avanzando con dificultad hacia el hombre que duerme."
  },
  AvgDialog_118950_Content_8 = {
    Text = "<Shake:¡Señor Goliat...!>"
  },
  AvgDialog_118950_Content_9 = {
    Text = "A pesar de cómo lo llame, el hombre que ha perdido su vitalidad no se mueve en absoluto."
  },
  AvgDialog_118951_Content_1 = {
    Text = "Entonces, me engañaste para traerme aquí, ¿qué es lo que realmente quieres hacer?"
  },
  AvgDialog_118951_Content_10 = {
    Text = "Hagamos algo que no esté relacionado con diosas, doctrinas o sacrificios."
  },
  AvgDialog_118951_Content_11 = {
    Text = "Sé que aunque ahora siempre mencionas esas cosas, lo que realmente te gusta no son estas."
  },
  AvgDialog_118951_Content_12 = {
    Text = "¡No digas tanto, toma esto rápido!"
  },
  AvgDialog_118951_Content_13 = {
    Text = "¡E-esto es?"
  },
  AvgDialog_118951_Content_14 = {
    Text = "¡Mezcla rápida, hacia una dirección!"
  },
  AvgDialog_118951_Content_15 = {Text = "..."},
  AvgDialog_118951_Content_16 = {
    Text = "¡Entonces, agrega la harina! ¡Polvo de hornear! ¡Una pizca de sal!"
  },
  AvgDialog_118951_Content_17 = {
    Text = "¿No vas a hacer nada, compañero mayor William? ¡Ve a ayudar a derretir la mantequilla!"
  },
  AvgDialog_118951_Content_18 = {
    Text = "......Está bien."
  },
  AvgDialog_118951_Content_19 = {
    Text = "William se alejó, interpretando pacientemente el papel del asistente de cocina atolondrado pero dedicado."
  },
  AvgDialog_118951_Content_2 = {
    Text = "¡Vamos, que el compañero mayor William te haga un truco de magia!"
  },
  AvgDialog_118951_Content_20 = {
    Text = "Finalmente, ustedes han metido la masa mezclada en el horno."
  },
  AvgDialog_118951_Content_21 = {
    Text = "Murphy miraba fijamente el horno, perdida en sus pensamientos."
  },
  AvgDialog_118951_Content_22 = {
    Text = "Recordé algunas cosas de hace mucho tiempo..."
  },
  AvgDialog_118951_Content_23 = {Text = "¿Hm?"},
  AvgDialog_118951_Content_24 = {
    Text = "Eso fue cuando aún estábamos en la base antártica. Descubrí un altar en el paso de montaña, con muchas pequeñas tallas de piedra en él."
  },
  AvgDialog_118951_Content_25 = {
    Text = "Le pedí a mamá... Miryam que me diera un cuchillo pequeño y algunos trozos de madera; quiero hacer algo de tallado en madera."
  },
  AvgDialog_118951_Content_26 = {
    Text = "Después de mucho tiempo, solo me dio un cuchillo sin filo, diciendo que estaba preocupada por \"el cuerpo sagrado de la Madre Divina\"."
  },
  AvgDialog_118951_Content_27 = {
    Text = "Siento que mi cuerpo no me pertenece, y por supuesto, tampoco le pertenece a ella; parecemos ser como ladrillos en ese Reino Divino, atrapados en nuestras propias posiciones, incapaces de movernos ni un centímetro."
  },
  AvgDialog_118951_Content_28 = {
    Text = "Vi algunas tallas de madera junto a tu cama."
  },
  AvgDialog_118951_Content_29 = {
    Text = "Hmm, le pedí en secreto a Goliat que me ayudara a encontrar un trozo de piedra de aceite."
  },
  AvgDialog_118951_Content_3 = {
    Text = "Todo ha sido devuelto de acuerdo a la lista; por favor confirma."
  },
  AvgDialog_118951_Content_30 = {
    Text = "Hice un gran esfuerzo y apenas afilé la hoja hasta que pudo cortar madera."
  },
  AvgDialog_118951_Content_31 = {
    Text = "Esculpí durante muchos días, esforzándome por restaurar los detalles que imaginé."
  },
  AvgDialog_118951_Content_32 = {
    Text = "Cuando finalmente me sentí satisfecho, se lo di a Miryam..."
  },
  AvgDialog_118951_Content_33 = {
    Text = "¿Sabes qué dijo ella?"
  },
  AvgDialog_118951_Content_34 = {
    Text = "Miryam... ¿dijo que tus tallas son malas, profanas a los dioses?"
  },
  AvgDialog_118951_Content_35 = {
    Text = "Te esforzaste en reflexionar sobre la mentalidad de Miryam, dando una suposición con cautela."
  },
  AvgDialog_118951_Content_36 = {Text = "No."},
  AvgDialog_118951_Content_37 = {
    Text = "Ella ni siquiera lo miró y simplemente dijo que si me gustaba tal estatua, podía ordenar a los mejores artesanos que la esculpieran para mí todos los días."
  },
  AvgDialog_118951_Content_38 = {
    Text = "Murphy rió locamente, un dolor indescriptible y una pulla brotaron de su sonrisa rígida."
  },
  AvgDialog_118951_Content_39 = {
    Text = "Soy un hijo de los dioses y también el recipiente de los dioses; lo que desee, puedo tenerlo simplemente levantando mi mano."
  },
  AvgDialog_118951_Content_4 = {
    Text = "William abrió docenas de bolsillos de varios tamaños en su pecho, espalda y brazos de manera sucesiva."
  },
  AvgDialog_118951_Content_40 = {
    Text = "Porque ya tengo todo, así que tallar una escultura de madera es, por supuesto, una trivialidad."
  },
  AvgDialog_118951_Content_41 = {
    Text = "Ella se rió, se rió, sin darse cuenta, las lágrimas salieron. Lágrimas repentinas, rodaron rápidamente por su rostro distorsionado por la risa incontrolable."
  },
  AvgDialog_118951_Content_42 = {
    Text = "He visto las obras que tienes en la mesita de noche; tu habilidad es bastante buena."
  },
  AvgDialog_118951_Content_43 = {
    Text = "¿Qué importa si es bueno o malo...?"
  },
  AvgDialog_118951_Content_44 = {
    Text = "Murphy, a partir de ahora, esculpe como desees."
  },
  AvgDialog_118951_Content_45 = {
    Text = "Luego fuimos a hacer pasteles pequeños juntos y estudiamos arte floral juntos."
  },
  AvgDialog_118951_Content_46 = {
    Text = "Encontraré la manera de regresar a mi mundo, y te presentaré al Murphy que conozco, para que puedan hacer libremente todo lo que quieran hacer juntos."
  },
  AvgDialog_118951_Content_47 = {
    Text = "Murphy se secó las lágrimas con las manos, luego levantó la cabeza y te dio una sonrisa radiante que nunca habías visto antes."
  },
  AvgDialog_118951_Content_48 = {
    Text = "Está bien, esto es todo lo que me prometiste."
  },
  AvgDialog_118951_Content_49 = {
    Text = "¡Absolutamente, no puedes faltar."
  },
  AvgDialog_118951_Content_5 = {
    Text = "Gracias al gran dios de la magia, el compañero mayor William, por robarnos los ingredientes de la cocina trasera."
  },
  AvgDialog_118951_Content_50 = {
    Text = "Esta es una historia no relacionada con la Madre divina."
  },
  AvgDialog_118951_Content_51 = {
    Text = "Pero parece que nunca ha estado tan feliz en su vida."
  },
  AvgDialog_118951_Content_6 = {
    Text = "Hay harina, huevos, limones, miel, azúcar, levadura en polvo y mantequilla."
  },
  AvgDialog_118951_Content_7 = {
    Text = "¡Está bastante completo! La cantidad de bolsillos en el uniforme de marinero es genial."
  },
  AvgDialog_118951_Content_8 = {
    Text = "Aún no entiendo... ¿por qué?"
  },
  AvgDialog_118951_Content_9 = {
    Text = "¿No quieres intentar hornear tú mismo el pastel que sueles comer?"
  },
  AvgDialog_118952_Content_1 = {
    Text = "Nacimiento de Dios en siete días"
  },
  AvgDialog_118952_Content_10 = {
    Text = "Rezo a Dios por respuestas."
  },
  AvgDialog_118952_Content_11 = {
    Text = "Pregunté sobre el futuro del Reino Divino, sobre su conexión conmigo, sobre todo lo que quería saber y lo que Miryam estaba tratando de indagar."
  },
  AvgDialog_118952_Content_12 = {
    Text = "El dios guardó silencio."
  },
  AvgDialog_118952_Content_13 = {
    Text = "<color=#E6E6E6>El quinto día del nacimiento de Dios</color>"
  },
  AvgDialog_118952_Content_14 = {
    Text = "Miryam preguntó sobre el resultado de mi audiencia con el dios."
  },
  AvgDialog_118952_Content_15 = {
    Text = "En un momento de desesperación, inventé la respuesta de Dios: \"El Reino Divino está a punto de elevarse\"."
  },
  AvgDialog_118952_Content_16 = {
    Text = "Ella seguía preguntando sobre la hora, y yo solo podía responder con \"cuando las estrellas están en lo cierto\"."
  },
  AvgDialog_118952_Content_17 = {
    Text = "Miryam estaba eufórica, una alegría que nunca había visto antes; no la vi cuando le regalé la escultura de madera, ni cuando gesté el feto sagrado."
  },
  AvgDialog_118952_Content_18 = {
    Text = "<color=#E1E1E1>El sexto día del nacimiento de Dios.</color>"
  },
  AvgDialog_118952_Content_19 = {
    Text = "Miryam preguntó sobre el paradero de Lemuria, solo pude responder vagamente, y su expresión era medio convencida."
  },
  AvgDialog_118952_Content_2 = {
    Text = "El primer día del nacimiento de Dios"
  },
  AvgDialog_118952_Content_20 = {
    Text = "Ella había visto a un dios que aún no había muerto; mi mentira podría no funcionar."
  },
  AvgDialog_118952_Content_21 = {
    Text = "<Shake:Oh Dios, por favor, sálvame, incluso solo una palabra, responde a mi oración.>"
  },
  AvgDialog_118952_Content_22 = {
    Text = "<Red:El séptimo día del nacimiento del dios>"
  },
  AvgDialog_118952_Content_23 = {
    Text = "Dios ha muerto. Dios nunca ha nacido."
  },
  AvgDialog_118952_Content_24 = {
    Text = "Lo que reposa en mi pecho es solo una imagen hipócrita, un bulto de carne y sangre muerta, erróneamente llamado <Yellow:\"dios\">."
  },
  AvgDialog_118952_Content_25 = {
    Text = "Miryam no ha amado a nadie. No se ha preocupado por nadie."
  },
  AvgDialog_118952_Content_26 = {
    Text = "Después de dominar el poder de la Madre divina, he leído todos los registros del Marinero."
  },
  AvgDialog_118952_Content_27 = {
    Text = "Cada seis décadas, durante miles de años, llegará un momento en que las estrellas estén en lo cierto."
  },
  AvgDialog_118952_Content_28 = {
    Text = "El cuerpo sacrificado, no soy el primero ni seré el último."
  },
  AvgDialog_118952_Content_29 = {
    Text = "Quiero sobrevivir, quiero persistir..."
  },
  AvgDialog_118952_Content_3 = {
    Text = "El embrión del dios nació dentro de un cuerpo carbonizado."
  },
  AvgDialog_118952_Content_30 = {
    Text = "Entonces, debemos matar a ese..."
  },
  AvgDialog_118952_Content_31 = {
    Text = "Yo débil y ingenuo..."
  },
  AvgDialog_118952_Content_4 = {
    Text = "Estoy exhausto por haber perdido mi energía espiritual, pero en la cara de todos brilla una alegría fervorosa."
  },
  AvgDialog_118952_Content_5 = {
    Text = "<color=#F7F7F7>Segundo día del nacimiento de Dios</color>"
  },
  AvgDialog_118952_Content_6 = {
    Text = "Bautizo al Feto Sagrado. Él duerme con los ojos cerrados en el manto."
  },
  AvgDialog_118952_Content_7 = {
    Text = "<color=#F2F2F2>Tercer día del nacimiento de Dios</color>"
  },
  AvgDialog_118952_Content_8 = {
    Text = "El Feto Sagrado todavía no ha abierto los ojos. Puedo sentir su latido, al igual que el pulso frente a mi pecho."
  },
  AvgDialog_118952_Content_9 = {
    Text = "<color=#F0F0F0>Cuarto día del nacimiento de Dios</color>"
  },
  AvgDialog_118953_Content_1 = {
    Text = "El telón en el cielo se agita y se conmueve, como si una tormenta estuviera gestándose en un pequeño mundo."
  },
  AvgDialog_118953_Content_10 = {
    Text = "El viento sopla y las nubes se mueven, el cielo sombrío cubierto de nubes oscuras comienza a cambiar."
  },
  AvgDialog_118953_Content_11 = {
    Text = "El... sol en el cielo..."
  },
  AvgDialog_118953_Content_12 = {
    Text = "La falsa luminosidad se disipa, y bajo el distante firmamento, un velo negro que cubre el cielo se agita suavemente al compás de la respiración."
  },
  AvgDialog_118953_Content_13 = {
    Text = "Ese es un sol negro."
  },
  AvgDialog_118953_Content_2 = {
    Text = "Una brisa suave que pasaba levantó el velo negro que nublaba su rostro, y debajo de él, había un par de ojos llorosos que ya se habían secado."
  },
  AvgDialog_118953_Content_3 = {
    Text = "¡Hay un defecto!"
  },
  AvgDialog_118953_Content_4 = {Text = "¡Oh!"},
  AvgDialog_118953_Content_6 = {
    Text = "En el instante en que el cielo titubea, la gran espada dentada corta de inmediato hacia la grieta ondulante."
  },
  AvgDialog_118953_Content_7 = {
    Text = "La estatua de marfil estalla en una feroz luz blanca, como si fuera una resistencia desesperada."
  },
  AvgDialog_118953_Content_8 = {
    Text = "Segundos después, la luz blanca se apagó repentinamente, y la Estatua de marfil se hizo añicos, creando una lluvia de fragmentos blancos en un diámetro de veinte centímetros."
  },
  AvgDialog_118953_Content_9 = {
    Text = "Todo terminó..."
  },
  AvgDialog_118954_Content_1 = {
    Text = "Reencarnación del tiempo"
  },
  AvgDialog_118954_Content_10 = {
    Text = "Guardián..."
  },
  AvgDialog_118954_Content_11 = {Text = "¡Ramona!"},
  AvgDialog_118954_Content_12 = {
    Text = "Cálmense y escúchenme."
  },
  AvgDialog_118954_Content_13 = {
    Text = "He pasado por innumerables saltos temporales, retrazando los ciclos."
  },
  AvgDialog_118954_Content_14 = {
    Text = "Por lo tanto, estoy seguro de que lo que te sucedió no es \"reencarnación del tiempo\"."
  },
  AvgDialog_118954_Content_15 = {
    Text = "El tiempo que has experimentado sigue fluyendo de manera natural."
  },
  AvgDialog_118954_Content_16 = {
    Text = "No hay\"Reencarnación del tiempo\"..."
  },
  AvgDialog_118954_Content_17 = {
    Text = "Entonces, las extrañas visiones que encuentro cada vez que despierto, el crucero hundiéndose y zarpando de nuevo, la chica que murió regresando ilesa..."
  },
  AvgDialog_118954_Content_18 = {
    Text = "¿En realidad, por qué?"
  },
  AvgDialog_118954_Content_19 = {
    Text = "No puedo responderte."
  },
  AvgDialog_118954_Content_2 = {
    Text = "Eres consciente de que estás soñando."
  },
  AvgDialog_118954_Content_20 = {
    Text = "Y ese sol en el cielo..."
  },
  AvgDialog_118954_Content_21 = {
    Text = "Ramona no dijo más. Ella tampoco sabía la respuesta a la pregunta."
  },
  AvgDialog_118954_Content_22 = {
    Text = "La superficie del agua comenzó a agitarse, su sombra empezó a balancearse desde el borde, y finalmente se transformó en fragmentos de memoria inalcanzables, disolviéndose en los destellos del agua."
  },
  AvgDialog_118954_Content_23 = {
    Text = "Ardor. Dolor. La lengua de fuego acaricia cada centímetro de tu piel."
  },
  AvgDialog_118954_Content_24 = {
    Text = "Las terminaciones nerviosas se enroscan por el dolor agudo, se carbonizan por la deshidratación.\nTe vuelves muy ligero, tan ligero que te conviertes en huesos negros y marchitos."
  },
  AvgDialog_118954_Content_25 = {
    Text = "Toses violentamente."
  },
  AvgDialog_118954_Content_26 = {
    Text = "¿Despertaste?"
  },
  AvgDialog_118954_Content_27 = {
    Text = "<Shake:... ¿un ciclo más...?>"
  },
  AvgDialog_118954_Content_28 = {
    Text = "Si tu cuerpo se ha recuperado, voy a preparar el ritual."
  },
  AvgDialog_118954_Content_29 = {
    Text = "Espera, no te vayas, Murphy..."
  },
  AvgDialog_118954_Content_3 = {
    Text = "Los sueños son la materialización de deseos y miedos internos, mientras que el reino de los sueños consiste en islas aisladas flotando en el vacío."
  },
  AvgDialog_118954_Content_30 = {
    Text = "Ellos... ¿y todos?"
  },
  AvgDialog_118954_Content_31 = {
    Text = "Murphy respiró hondo y luego exhaló largamente."
  },
  AvgDialog_118954_Content_32 = {
    Text = "Todos tienen sus propias cosas que hacer. Deberías descansar bien aquí."
  },
  AvgDialog_118954_Content_33 = {
    Text = "Cuando llegue el próximo momento de la posición normal de las estrellas, este barco alcanzará Lemuria y todo estará bien."
  },
  AvgDialog_118954_Content_34 = {
    Text = "Con un chirrido, la puerta se cerró.\nTe encuentras solo en la sala de estar."
  },
  AvgDialog_118954_Content_35 = {
    Text = "No puedes quedarte, debes actuar."
  },
  AvgDialog_118954_Content_36 = {
    Text = "Después de experimentar tres reencarnaciones, ¿tienes alguna conclusión?"
  },
  AvgDialog_118954_Content_37 = {
    Text = "Dado que el número de ciclos es fijo, entonces la información es mucho más importante que escapar."
  },
  AvgDialog_118954_Content_38 = {
    Text = "En el primer ciclo, comprendí inicialmente a los Marchadores de mares; aunque fracasé en el tercer ciclo de manera desastrosa, obtuve un conocimiento básico sobre los movimientos de los demás en el barco."
  },
  AvgDialog_118954_Content_39 = {
    Text = "En cambio, el tiempo del segundo ciclo se desperdicia."
  },
  AvgDialog_118954_Content_4 = {
    Text = "En un sueño caótico, innumerables puntas de cuchillo de colores brillantes atraviesan tu pecho, reflejando las sombras de unos a otros como burbujas."
  },
  AvgDialog_118954_Content_40 = {
    Text = "La prioridad es recopilar más información sobre el Paradeis y los Marchadores de mares."
  },
  AvgDialog_118954_Content_41 = {
    Text = "Aunque esa persona misteriosa insinuó que hay un total de seis reencarnaciones..."
  },
  AvgDialog_118954_Content_42 = {
    Text = "Pero, ¿no has considerado que si ahora es el último ciclo, habrías desperdiciado una oportunidad?"
  },
  AvgDialog_118954_Content_43 = {
    Text = "Si ahora es el último ciclo..."
  },
  AvgDialog_118954_Content_44 = {
    Text = "Sacudes la cabeza, desechando todas las conjeturas ominosas."
  },
  AvgDialog_118954_Content_45 = {
    Text = "En el sueño al inicio de este ciclo, Ramona: Bucle me proporcionó un mensaje: <Yellow:ella puede percibir que el tiempo en mí sigue fluyendo secuencialmente>."
  },
  AvgDialog_118954_Content_46 = {
    Text = "Y mencionaste que una vez te encontraste con un evento cíclico..."
  },
  AvgDialog_118954_Content_47 = {Text = "!"},
  AvgDialog_118954_Content_48 = {
    Text = "Parece que William, el compañero mayor, también ha llegado a entender."
  },
  AvgDialog_118954_Content_49 = {
    Text = "Aquí no está la \"reencarnación del tiempo\", sino más bien \"las mismas cosas suceden repetidamente\"..."
  },
  AvgDialog_118954_Content_5 = {
    Text = "Necesitas el método para finalizar el sueño."
  },
  AvgDialog_118954_Content_50 = {
    Text = "En Misaq, a menudo me veo obligado a enfrentar situaciones similares."
  },
  AvgDialog_118954_Content_51 = {
    Text = "\"Dominio artificial\"..."
  },
  AvgDialog_118954_Content_52 = {
    Text = "Así es, esto es muy probable un \"dominio artificial\"."
  },
  AvgDialog_118954_Content_53 = {
    Text = "El dominio artificial es solo un portador de información; el verdadero nosotros puede estar siendo arrastrado por la tormenta y girando en el aire."
  },
  AvgDialog_118954_Content_54 = {
    Text = "¿Cómo se formó este dominio artificial? ¿Por qué el dominio sigue reiniciándose? ¿Cuál es la oportunidad de acabar con ello?"
  },
  AvgDialog_118954_Content_55 = {
    Text = "Sin entender todo esto, nuestros intentos en el dominio serán solo una búsqueda en vano."
  },
  AvgDialog_118954_Content_56 = {
    Text = "Racional. Durante trescientos años, la razón ha estado ayudando a Misaq a luchar contra la locura llamada disolución."
  },
  AvgDialog_118954_Content_57 = {
    Text = "Creo que William, el compañero mayor, también se ha dado cuenta de que el sol que hemos estado mirando estos días no es el sol negro después de la difusión de la oscuridad, sino el genuino sol del mundo normal."
  },
  AvgDialog_118954_Content_58 = {
    Text = "El tiempo de nacimiento del dominio es antes de que la niebla negra descienda sobre el mundo."
  },
  AvgDialog_118954_Content_59 = {Text = "..."},
  AvgDialog_118954_Content_6 = {
    Text = "Como persona del destino textil, debo permanecer en silencio y no puedo revelar la verdad."
  },
  AvgDialog_118954_Content_60 = {
    Text = "¿Dije algo mal? ¿Por qué me miras así?"
  },
  AvgDialog_118954_Content_61 = {
    Text = "...No, solo que de repente recordé cuando estaba en Misaq, en aquel entonces, cuando salía a trabajar de campo, siempre tenía a ti y a Ramona a mi lado, liberando mi mente al máximo."
  },
  AvgDialog_118954_Content_62 = {
    Text = "Pensar es una parte esencial de la investigación."
  },
  AvgDialog_118954_Content_63 = {
    Text = "Entonces, William, el compañero mayor, ¿quién crees que es el maestro del dominio?"
  },
  AvgDialog_118954_Content_64 = {
    Text = "Basado en los principios de formación del dominio y la información conocida, inicialmente estimo que el dominio pertenece a Miryam o a Faros."
  },
  AvgDialog_118954_Content_65 = {
    Text = "El <Yellow:\"núcleo\"> del dominio es el \"Ritual de Invocación\", y rastrear la ubicación de Lemuria debería ser la obsesión del maestro del dominio."
  },
  AvgDialog_118954_Content_66 = {
    Text = "Y según los registros de la investigación del Sonanir, el objetivo de Goliath es la fuerza, la obsesión de Caecus es la sangre, solo Miryam y Faros anhelan la gloria del Reino Divino."
  },
  AvgDialog_118954_Content_67 = {
    Text = "A continuación, bloquea al maestro del dominio, ¿y luego?"
  },
  AvgDialog_118954_Content_68 = {
    Text = "Cuando el maestro del dominio duda sobre la causa del dominio, aparecerán grietas en él, donde la \"catástrofe\" se manifestará."
  },
  AvgDialog_118954_Content_69 = {
    Text = "Sin embargo, dado que es un dominio artificial, se puede garantizar la seguridad de nuestros cuerpos."
  },
  AvgDialog_118954_Content_7 = {
    Text = "Por lo tanto, te he entregado a quien puede proporcionar revelación."
  },
  AvgDialog_118954_Content_70 = {
    Text = "No seas complaciente. Sin mencionar que el dominio artificial aún permanece en nuestras conjeturas..."
  },
  AvgDialog_118954_Content_71 = {
    Text = "Desbordamiento 306, el investigador Jude Brite se rompió la pierna derecha al pisar una trampa de cazador después de adentrarse en el dominio. Al regresar a la realidad, su pierna derecha también comenzó a gangrenarse."
  },
  AvgDialog_118954_Content_72 = {
    Text = "La influencia del dominio en la realidad es actualmente desconocida, pero la precaución siempre es una buena idea."
  },
  AvgDialog_118954_Content_73 = {
    Text = "¡Entendido!"
  },
  AvgDialog_118954_Content_74 = {
    Text = "Después de que terminó el ritual, fui a enfrentarme a Miryam, Faros te lo dejo a ti."
  },
  AvgDialog_118954_Content_75 = {
    Text = "Que la Llave de plata ilumine mi camino."
  },
  AvgDialog_118954_Content_76 = {
    Text = "Un tono familiar te dejó aturdido por un momento, pero rápidamente apareció una sonrisa sincera."
  },
  AvgDialog_118954_Content_77 = {
    Text = "Que la Llave de Plata nos guíe"
  },
  AvgDialog_118954_Content_78 = {
    Text = "La mujer inteligente ocupaba sola un rincón de la habitación del capitán, la luz sobre su cabeza parpadeando imperceptiblemente con su aliento."
  },
  AvgDialog_118954_Content_79 = {Text = "Faros..."},
  AvgDialog_118954_Content_8 = {
    Text = "En el reflejo distorsionado del sueño, aparece una figura erguida."
  },
  AvgDialog_118954_Content_80 = {
    Text = "En el momento en que abriste la boca, te detuviste de repente. Intentaste recordar la información relacionada con Faros y te diste cuenta de que había pocos registros sobre ella en Misaq."
  },
  AvgDialog_118954_Content_81 = {
    Text = "Ella anhela regresar al Reino Divino, llevando al viajero por un camino equivocado."
  },
  AvgDialog_118954_Content_82 = {
    Text = "Aparte de eso, los otros casos están completamente en blanco."
  },
  AvgDialog_118954_Content_83 = {
    Text = "¿Qué pasa? Por tu expresión, ¿te sientes confundido?"
  },
  AvgDialog_118954_Content_84 = {
    Text = "Quizás... pueda darte alguna orientación?"
  },
  AvgDialog_118954_Content_85 = {
    Text = "Temo que..."
  },
  AvgDialog_118954_Content_86 = {
    Text = "Sé quién es el maestro del dominio."
  },
  AvgDialog_118954_Content_9 = {
    Text = "Las sombras fluctúan, se rompen y se fusionan, estabilizándose gradualmente en el rostro frío y familiar de tu memoria."
  },
  AvgDialog_118955_Content_1 = {Text = "Forastero"},
  AvgDialog_118955_Content_10 = {Text = "William..."},
  AvgDialog_118955_Content_11 = {
    Text = "Pero no deberías quedarte aquí; solo después de que encuentres al maestro del dominio del Sueño podrán llegar a su fin los innumerables días y noches que pasó aquí."
  },
  AvgDialog_118955_Content_12 = {
    Text = "Al final del barco, viste a una niña."
  },
  AvgDialog_118955_Content_13 = {
    Text = "Incontables Marchadores de mares con túnicas negras yacen desordenadamente a su lado, mientras ella se apoya tranquilamente en el altar, sosteniendo en sus manos un trozo de carne en descomposición carmesí y maloliente."
  },
  AvgDialog_118955_Content_14 = {Text = "Murphy..."},
  AvgDialog_118955_Content_15 = {
    Text = "Como prometiste, has llegado."
  },
  AvgDialog_118955_Content_16 = {
    Text = "El maestro del reino de los sueños eres tú."
  },
  AvgDialog_118955_Content_17 = {
    Text = "Sí, todo en este barco es un sueño. Todo lo que ves ahora mismo es solo \"realidad en un sueño\"."
  },
  AvgDialog_118955_Content_18 = {
    Text = "¿Por qué?"
  },
  AvgDialog_118955_Content_19 = {
    Text = "¿Por qué crear un dominio de sueño así? ¿O por qué convertirme en el yo que soy ahora?"
  },
  AvgDialog_118955_Content_2 = {
    Text = "Cof, cof, eh..."
  },
  AvgDialog_118955_Content_20 = {
    Text = "Ese fue un día hace mucho, mucho tiempo."
  },
  AvgDialog_118955_Content_21 = {
    Text = "La pequeña figura avanza a través de la nieve."
  },
  AvgDialog_118955_Content_22 = {
    Text = "Buf... Buf..."
  },
  AvgDialog_118955_Content_23 = {
    Text = "Desde que llegó a la Antártida, Murphy ha poseído una especie de libertad absurda."
  },
  AvgDialog_118955_Content_24 = {
    Text = "Ella puede ir a cualquier lugar sola. Pero no importa a dónde vaya, solo puede ver el pálido campo de nieve."
  },
  AvgDialog_118955_Content_25 = {
    Text = "Ni siquiera hay rastros de que los humanos hayan existido."
  },
  AvgDialog_118955_Content_26 = {
    Text = "¿Esto es... ¿estoy perdido?"
  },
  AvgDialog_118955_Content_27 = {
    Text = "La niña mira atrás las huellas que dejó. En el vasto campo de nieve, una línea casi recta de pasos conduce hacia un lugar desconocido."
  },
  AvgDialog_118955_Content_28 = {
    Text = "No importa, mientras sigas adelante, siempre llegarás a algún lugar."
  },
  AvgDialog_118955_Content_29 = {
    Text = "La niña hizo inventario de su comida y confirmó la distancia más lejana que podría alcanzar con una dieta austera durante un tiempo."
  },
  AvgDialog_118955_Content_3 = {
    Text = "Toses con fuerza, tratando de expulsar el agua del mar que ha penetrado en tus pulmones."
  },
  AvgDialog_118955_Content_30 = {
    Text = "¡Vamos, Murphy! Este es un viaje hacia la libertad, no hay nada de malo en tener hambre."
  },
  AvgDialog_118955_Content_31 = {Text = "..."},
  AvgDialog_118955_Content_32 = {Text = "..."},
  AvgDialog_118955_Content_33 = {
    Text = "No, con esta tormenta de nieve, no se puede distinguir el camino."
  },
  AvgDialog_118955_Content_34 = {
    Text = "Comer galletas duras con agua de nieve es realmente difícil."
  },
  AvgDialog_118955_Content_35 = {
    Text = "A veces reside en una cueva de nieve, aún puede escuchar el aullido de las bestias. Nunca lo había visto, solo sabía que era una especie de lobo blanco."
  },
  AvgDialog_118955_Content_36 = {Text = "¡Ayuda!"},
  AvgDialog_118955_Content_37 = {
    Text = "Murphy, en pánico, huyó de la cueva. Esos ojos verdes y brillantes se quedaron en la cueva, sin alcanzar sus pasos."
  },
  AvgDialog_118955_Content_38 = {
    Text = "En una situación tan desesperada, vi una línea de huellas."
  },
  AvgDialog_118955_Content_39 = {
    Text = "¡Es una huella humana...!"
  },
  AvgDialog_118955_Content_4 = {
    Text = "Pero no puedo toser nada, en los pulmones solo quedan nervios convulsos y el dolor fantasma de ahogamiento."
  },
  AvgDialog_118955_Content_40 = {
    Text = "Mientras haya personas, habrá esperanza. No dudé en seguir adelante."
  },
  AvgDialog_118955_Content_41 = {Text = "..."},
  AvgDialog_118955_Content_42 = {
    Text = "Poco después, las huellas se convirtieron en dos líneas."
  },
  AvgDialog_118955_Content_43 = {
    Text = "Tres líneas."
  },
  AvgDialog_118955_Content_44 = {
    Text = "Las huellas son cada vez más numerosas, pero el dueño de las huellas sigue sin aparecer."
  },
  AvgDialog_118955_Content_45 = {
    Text = "Finalmente, me desmayé por el agotamiento extremo."
  },
  AvgDialog_118955_Content_46 = {
    Text = "Después supe que, debido a la diferencia de longitud entre los pies izquierdo y derecho, cada persona se desplaza ligeramente hacia un lado al caminar sin poder determinar la dirección."
  },
  AvgDialog_118955_Content_47 = {
    Text = "En otras palabras... en ese momento, mi trayectoria de caminata era un anillo."
  },
  AvgDialog_118955_Content_48 = {
    Text = "Las huellas que veo, llamadas esperanza, provienen de mi yo del pasado y llevan a un ciclo sin fin."
  },
  AvgDialog_118955_Content_49 = {
    Text = "Debido a una pequeña desviación, casi insignificante...\n mi vida ha estado atada por un círculo vicioso."
  },
  AvgDialog_118955_Content_5 = {
    Text = "¿Por qué... no debería ser este el último ciclo?"
  },
  AvgDialog_118955_Content_50 = {
    Text = "El centro de ese anillo se llama destino."
  },
  AvgDialog_118955_Content_51 = {
    Text = "Este es el ciclo que construí, uno que me atrapa."
  },
  AvgDialog_118955_Content_52 = {
    Text = "¿Es decir...?"
  },
  AvgDialog_118955_Content_53 = {
    Text = "Desde que Goliath se preparó para la rebelión por primera vez, el tiempo se ha detenido."
  },
  AvgDialog_118955_Content_54 = {
    Text = "Todos se sumergieron en sueños, comenzando un ciclo repetitivo de sueños.\nEl ciclo de los sueños comienza con el nacimiento del Feto Sagrado y termina con el hundimiento del crucero."
  },
  AvgDialog_118955_Content_55 = {
    Text = "Todo estará bien mientras Goliath no inicie una rebelión."
  },
  AvgDialog_118955_Content_56 = {
    Text = "Pero alguna vez vi a Goliat en Necrovia..."
  },
  AvgDialog_118955_Content_57 = {
    Text = "Para mantener el reino de sueños, cada cierto tiempo, enviaré a un grupo de personas a salir a recolectar energía para la estatua de marfil."
  },
  AvgDialog_118955_Content_58 = {
    Text = "Solo al regresar al dominio del sueño, olvidarán esta experiencia y se convertirán en los súbditos del dominio del sueño."
  },
  AvgDialog_118955_Content_59 = {
    Text = "Es una pena que desde que obstaculizaste nuestra absorción de energía de Necrovia, el Dominio de los Sueños se ha vuelto cada vez más inestable."
  },
  AvgDialog_118955_Content_6 = {
    Text = "Miras a tu alrededor, la amplia cubierta está vacía, sin arañas moradas ni fieles del Reino del Mar a tu alrededor."
  },
  AvgDialog_118955_Content_60 = {
    Text = "¿Por qué quieres que te vea?"
  },
  AvgDialog_118955_Content_61 = {
    Text = "Originalmente te convoqué aquí con la esperanza de eliminar todos los factores inestables, estrangulándote en este reino de sueños..."
  },
  AvgDialog_118955_Content_62 = {
    Text = "Solo que antes de eso, mi núcleo de plata parecía resonar con tu llave de plata, y me conecté a tu sueño, tu memoria."
  },
  AvgDialog_118955_Content_63 = {
    Text = "Vi otra posibilidad en el sueño... otro yo mismo."
  },
  AvgDialog_118955_Content_64 = {
    Text = "La vi compitiendo con compañeros de clase en la clase de escultura;"
  },
  AvgDialog_118955_Content_65 = {
    Text = "La vi pelear con gatos callejeros bajo la fuente;"
  },
  AvgDialog_118955_Content_66 = {
    Text = "La vi siendo persuadida por sus amigos para que usara una pequeña falda de diablillo, llevando una linterna de calabaza, y yendo de puerta en puerta distribuyendo dulces..."
  },
  AvgDialog_118955_Content_67 = {
    Text = "En un mundo donde el Feto Sagrado no ha nacido, ella es realmente... muy feliz."
  },
  AvgDialog_118955_Content_68 = {
    Text = "Envidiable, envidioso."
  },
  AvgDialog_118955_Content_69 = {
    Text = "También hace que uno quiera convertirse."
  },
  AvgDialog_118955_Content_7 = {
    Text = "Estás huyendo por todas partes, buscando."
  },
  AvgDialog_118955_Content_70 = {
    Text = "<Yellow:%player%>, hasta que te encontré, no sabía que aún existía una forma de vida tan simple y feliz en el mundo..."
  },
  AvgDialog_118955_Content_71 = {
    Text = "No necesito la vana corona de la Madre divina, no necesito el honor de ser admirada por todos, no necesito enfrentar día tras día las caras odiosas de los fieles..."
  },
  AvgDialog_118955_Content_72 = {
    Text = "¿Qué responsabilidad, qué legado, por qué tantas personas dan su vida por un montón de carne podrida?"
  },
  AvgDialog_118955_Content_73 = {
    Text = "Guardas silencio, solo puedes guardar silencio."
  },
  AvgDialog_118955_Content_74 = {
    Text = "Murphy está negando su pasado."
  },
  AvgDialog_118955_Content_75 = {
    Text = "Tengo una última pregunta que hacerte."
  },
  AvgDialog_118955_Content_76 = {
    Text = "¿En tu mundo, también la llevaste a hacer pastelitos así?"
  },
  AvgDialog_118955_Content_77 = {
    Text = "En ese mundo... no solo yo, habrá muchas personas dispuestas a ayudarte y acompañarte a hacer cualquier cosa que desees, incluso caprichos."
  },
  AvgDialog_118955_Content_78 = {
    Text = "Murphy, porque amas al mundo y a todos."
  },
  AvgDialog_118955_Content_79 = {
    Text = "Porque tú, has abierto tu corazón, y todos lo han presenciado."
  },
  AvgDialog_118955_Content_8 = {
    Text = "Durmiendo, durmiendo, todos están durmiendo."
  },
  AvgDialog_118955_Content_80 = {
    Text = "Ese corazón palpitante."
  },
  AvgDialog_118955_Content_81 = {
    Text = "Murphy sonrió, su risa era tan brillante como tus recuerdos pasados."
  },
  AvgDialog_118955_Content_82 = {
    Text = "¿Sabes? Este barco es un sueño."
  },
  AvgDialog_118955_Content_83 = {
    Text = "Una vez pensé que era un hermoso sueño...\nSoy la exaltada Madre de Dios, y ese bulto retorcido de carne es el llamado dios."
  },
  AvgDialog_118955_Content_84 = {
    Text = "Día y noche, vivo con miedo, lleno de ansiedad y atormentado."
  },
  AvgDialog_118955_Content_85 = {
    Text = "Resulta que este sueño no es un sueño agradable, sino una pesadilla de pánico en la que ni siquiera era consciente."
  },
  AvgDialog_118955_Content_86 = {
    Text = "Así que, ahora, levantemos el telón de mentiras y despertemos el sueño."
  },
  AvgDialog_118955_Content_9 = {
    Text = "William yacía en la cubierta, su uniforme estaba manchado, como si hubiera sido golpeado repetidamente por tormentas y el sol abrasador, con grasa y sal formando un mapa moteado."
  },
  AvgDialog_118956_Content_1 = {
    Text = "Ustedes luchan mientras retroceden, desde la sala de poder hasta el pasillo, desde el pasillo hasta la cubierta, hasta que solo una valla los separa del infinito océano detrás de ustedes."
  },
  AvgDialog_118956_Content_10 = {
    Text = "El gigante de fuerza descomunal se desliza rápidamente hacia atrás bajo tu impacto, a punto de estrellarse contra la cubierta."
  },
  AvgDialog_118956_Content_11 = {
    Text = "En un abrir y cerrar de ojos, clavó la gran espada en el suelo, apenas logrando estabilizar su cuerpo."
  },
  AvgDialog_118956_Content_12 = {
    Text = "Has mejorado desde la última vez que nos vimos, ¿eh."
  },
  AvgDialog_118956_Content_13 = {
    Text = "No, no es así."
  },
  AvgDialog_118956_Content_14 = {
    Text = "No es que te hayas vuelto más fuerte, es que Goliat se ha debilitado."
  },
  AvgDialog_118956_Content_15 = {
    Text = "Incluso con Faros ayudando, la fuerza de Goliath está muy por debajo de la que tenía en su último encuentro contigo."
  },
  AvgDialog_118956_Content_16 = {
    Text = "Cada corte es ligero, nada que ver con la fuerza descomunal de un gigante."
  },
  AvgDialog_118956_Content_17 = {
    Text = "Goliat, desde el comienzo de la batalla me di cuenta de la fuerza sobrehumana que llevas... se está debilitando rápidamente."
  },
  AvgDialog_118956_Content_18 = {
    Text = "Hmph, incluso si es diez veces más débil, no es algo que tú, pequeño, puedas igualar."
  },
  AvgDialog_118956_Content_19 = {
    Text = "¿Está esto relacionado con la aparición de Faros aquí?"
  },
  AvgDialog_118956_Content_2 = {
    Text = "Vaya, qué perseverancia... realmente has luchado hasta aquí."
  },
  AvgDialog_118956_Content_20 = {
    Text = "¿Está relacionado más a fondo con la ilusión en este barco?"
  },
  AvgDialog_118956_Content_21 = {
    Text = "¿Es porque te has debilitado que tienes prisa por ejecutar lo que se llama un plan?"
  },
  AvgDialog_118956_Content_22 = {
    Text = "Hmph, cosas que no deberías saber, no importa cuánto preguntes, no esperes sacar una palabra de mí."
  },
  AvgDialog_118956_Content_23 = {
    Text = "Si nuestros propósitos están alineados, puede que no sea necesariamente la opción que necesitas eliminar."
  },
  AvgDialog_118956_Content_24 = {
    Text = "Cada uno ceda un paso, no interferiré en tu intención de traicionar a los Marchadores de mares, y tú tampoco me molestes."
  },
  AvgDialog_118956_Content_25 = {
    Text = "Goliath aún no ha respondido, dos sombras de serpientes venenosas se lanzan hacia ustedes como un rayo!"
  },
  AvgDialog_118956_Content_27 = {
    Text = "Ustedes retroceden de repente, la sombra de la serpiente estalla en la cubierta, abriendo instantáneamente dos horribles agujeros que humean."
  },
  AvgDialog_118956_Content_28 = {
    Text = "Dos traidores ingratos, no hay lugar aquí para su consenso."
  },
  AvgDialog_118956_Content_29 = {
    Text = "En cuanto a los forasteros... al escapar, parece que olvidaste algo clave."
  },
  AvgDialog_118956_Content_3 = {
    Text = "Sin embargo, ya no tienes a dónde retroceder."
  },
  AvgDialog_118956_Content_30 = {
    Text = "La estatua de marfil flota en la mano de Miryam.\nElla reza devotamente, sus palabras de profanación brotan de su boca como gusanos."
  },
  AvgDialog_118956_Content_31 = {
    Text = "<Cambio>Sus cuerpos y almas deberían haber pertenecido a las sombras del abismo."
  },
  AvgDialog_118956_Content_32 = {
    Text = "Espera, Miryam, no—"
  },
  AvgDialog_118956_Content_33 = {
    Text = "Lo siento, Madre divina, debo castigar a aquellos que profanan."
  },
  AvgDialog_118956_Content_34 = {
    Text = "La estatua de marfil emite un grito silencioso, innumerables hilos plateados se propagan, parasitándose en los corazones de los ciudadanos del Reino del Mar como si fueran una extraña criatura viva."
  },
  AvgDialog_118956_Content_35 = {
    Text = "¡Esto es... mujer loca, ¿qué estás haciendo?!"
  },
  AvgDialog_118956_Content_36 = {
    Text = "¿Qué estoy haciendo? Naturalmente, les estoy concediendo la compasión, la misericordia y el poder supremo de los dioses."
  },
  AvgDialog_118956_Content_37 = {
    Text = "Los hilos se enredan fuertemente y se aprietan violentamente en un instante——"
  },
  AvgDialog_118956_Content_38 = {
    Text = "Señor Goliath... siento que no puedo respirar..."
  },
  AvgDialog_118956_Content_39 = {
    Text = "<Shake:¡Aaah... lo sentí... los hilos del Dios... toqué... Su Alma...>"
  },
  AvgDialog_118956_Content_4 = {
    Text = "Respiras hondo, te concentras y te enfrentas a la gran espada que Goliat vuelve a blandir."
  },
  AvgDialog_118956_Content_40 = {Text = "¡Pah."},
  AvgDialog_118956_Content_41 = {
    Text = "El corazón estalló en cadena, la suciedad carmesí estalló en el cubierta formando olas de color sangre."
  },
  AvgDialog_118956_Content_42 = {
    Text = "Ningún tiempo de influencia puede cambiar la necedad del descreído."
  },
  AvgDialog_118956_Content_43 = {
    Text = "<Shake:¡Entonces con vuestra sangre y espíritu, forjad la escalera hacia el Reino Divino!>"
  },
  AvgDialog_118956_Content_44 = {
    Text = "<Shake:Deténla...<Big:¡Ven conmigo, deténla!>>"
  },
  AvgDialog_118956_Content_6 = {
    Text = "El callejón sin salida en tus ojos ya era el campo de batalla que elegí para ti."
  },
  AvgDialog_118956_Content_7 = {
    Text = "Has estado desperdiciando fuerza, y ahora, ha llegado el momento de mi contraataque."
  },
  AvgDialog_118956_Content_8 = {
    Text = "La luz plateada estalló repentinamente, arremetiendo con fuerza abrumadora hacia Goliath. \n Goliath levantó su espada de inmediato para resistir, pero era demasiado tarde."
  },
  AvgDialog_118957_Content_1 = {Text = "Epílogo"},
  AvgDialog_118957_Content_10 = {
    Text = "Qué sueño tan largo."
  },
  AvgDialog_118957_Content_11 = {
    Text = "Muerte, traición, hundimiento; cuanto más intentas retener algo, más inevitablemente se escapa entre tus dedos."
  },
  AvgDialog_118957_Content_12 = {
    Text = "Quizás esto sea el destino. Irrevocable, no hay necesidad de forzarlo."
  },
  AvgDialog_118957_Content_13 = {
    Text = "Dejarlo ir antes puede permitir la oportunidad de conocer a más compañeros afines."
  },
  AvgDialog_118957_Content_14 = {
    Text = "¿Por ejemplo... Misaq?"
  },
  AvgDialog_118957_Content_15 = {
    Text = "Parece que la gente de Misaq es muy buena en ser inclusiva... o en suavizar el mal carácter de todos."
  },
  AvgDialog_118957_Content_16 = {
    Text = "Recuerdo que un año, Murphy insistió en probar todos los sabores de caramelos, y como resultado, terminó con dolor de muelas."
  },
  AvgDialog_118957_Content_17 = {
    Text = "Sylvia finalmente hizo que Jenkin robara todo el inventario de las damas."
  },
  AvgDialog_118957_Content_18 = {
    Text = "Pff. ¿Y luego?"
  },
  AvgDialog_118957_Content_19 = {
    Text = "Entonces comenzó a organizar una gran fiesta para atrapar a los ladrones, olvidándose por completo de los caramelos."
  },
  AvgDialog_118957_Content_2 = {
    Text = "El Paradeis ya ha atracado, ¿y luego...?"
  },
  AvgDialog_118957_Content_20 = {
    Text = "Una vez más..."
  },
  AvgDialog_118957_Content_21 = {
    Text = "Bueno, ¿cuánto más quieres que esté celoso de ella?"
  },
  AvgDialog_118957_Content_22 = {
    Text = "Cuando volvamos a Misaq, todo esto también te pertenecerá."
  },
  AvgDialog_118957_Content_23 = {
    Text = "Entonces deseemos que algún día nos volvamos a encontrar en Misaq."
  },
  AvgDialog_118957_Content_24 = {
    Text = "Murphy extendió las manos hacia el cielo distante, como si quisiera tocar el sol en lo alto."
  },
  AvgDialog_118957_Content_25 = {
    Text = "La sombra negra y redonda rueda entre sus dedos."
  },
  AvgDialog_118957_Content_26 = {
    Text = "Hay una cosa más que debo decirte."
  },
  AvgDialog_118957_Content_27 = {
    Text = "La mirada de Murphy te atraviesa."
  },
  AvgDialog_118957_Content_28 = {
    Text = "Este mundo ya ha sido aniquilado, irremediablemente perdido, cubierto por una desesperación más profunda que los ciclos que he experimentado."
  },
  AvgDialog_118957_Content_29 = {
    Text = "Si es posible, puedo intentar llevarte de vuelta."
  },
  AvgDialog_118957_Content_3 = {
    Text = "Ya han aprendido todo sobre los dioses de este mundo, y pronto tomarán sus propias decisiones."
  },
  AvgDialog_118957_Content_30 = {
    Text = "¿Despedirme... de vuelta?"
  },
  AvgDialog_118957_Content_31 = {
    Text = "¿Sabes cómo cruzar entre dos mundos?"
  },
  AvgDialog_118957_Content_32 = {
    Text = "No puedo decir que lo sé, pero mientras comprendas la esencia de este mundo, naturalmente conocerás los nodos que conectan los mundos."
  },
  AvgDialog_118957_Content_33 = {
    Text = "Este barco es un sueño, pero cuando se levanta el velo de mentiras..."
  },
  AvgDialog_118957_Content_34 = {
    Text = "Todo el mundo también es el sueño de alguien, solo que este sueño es más grande, más ilusorio y más distante..."
  },
  AvgDialog_118957_Content_35 = {
    Text = "La luna, el sol y las estrellas provienen de su invención, solo los seres ligados a su espíritu pueden..."
  },
  AvgDialog_118957_Content_36 = {
    Text = "Sol, luna, estrellas..."
  },
  AvgDialog_118957_Content_37 = {
    Text = "La gasa negra tembló, extendiéndose en un camino sinuoso que conducía hacia el cielo."
  },
  AvgDialog_118957_Content_38 = {
    Text = "¡Ve, regresa, vuelve a tu mundo que te pertenece! No te aferres a este mundo que ya ha muerto."
  },
  AvgDialog_118957_Content_39 = {
    Text = "¿Y tú, Murphy?"
  },
  AvgDialog_118957_Content_4 = {
    Text = "En mi opinión, Miryam y Faros deberían zarpar de nuevo para buscar la ubicación de Lemuria."
  },
  AvgDialog_118957_Content_40 = {
    Text = "Contienes la impulsividad de pisar el camino de seda y te vuelves a preguntar a la silenciosa Murphy."
  },
  AvgDialog_118957_Content_41 = {
    Text = "¿Quién sabe? Este mundo es un mundo que ya ha sido destruido."
  },
  AvgDialog_118957_Content_42 = {
    Text = "Tómalo. Tal vez algún día puedas sentir mi núcleo de plata en ese mundo."
  },
  AvgDialog_118957_Content_43 = {
    Text = "Una gema formada por una gota de sangre cae en tu mano, proveniente de la extraña herida que atraviesa su pecho."
  },
  AvgDialog_118957_Content_44 = {
    Text = "No sé qué periodo del \"Yo\" invocarás en ese momento."
  },
  AvgDialog_118957_Content_45 = {
    Text = "Pero cuando me llames, recuerda cómo me veo ahora..."
  },
  AvgDialog_118957_Content_46 = {
    Text = "Su nacimiento ya es una ilusión... los sueños moldeados son todas ilusiones..."
  },
  AvgDialog_118957_Content_47 = {
    Text = "Llámame...\"<Yellow:Murphy: Falso Engendro>\"!"
  },
  AvgDialog_118957_Content_48 = {
    Text = "Caminas lentamente por el camino de seda, innumerables pensamientos pasan volando por tu mente."
  },
  AvgDialog_118957_Content_49 = {
    Text = "El viaje contra la disolución, entrelazado por pesadillas negras entre dos mundos, muchos rostros similares o idénticos se superponen entre sí..."
  },
  AvgDialog_118957_Content_5 = {
    Text = "Goliath y Caecus probablemente se irán, incluso en este mundo que tiende a la desolación, tendrán su propio viaje."
  },
  AvgDialog_118957_Content_50 = {
    Text = "Dos muñecas..."
  },
  AvgDialog_118957_Content_51 = {
    Text = "Dos Clementines..."
  },
  AvgDialog_118957_Content_52 = {
    Text = "dos Murphy..."
  },
  AvgDialog_118957_Content_53 = {
    Text = "Finalmente congelado en el rostro sonriente de Ramona."
  },
  AvgDialog_118957_Content_54 = {
    Text = "¿Puedo... regresar?"
  },
  AvgDialog_118957_Content_55 = {
    Text = "De manera onírica, te das cuenta de que ya estás a solo un brazo de distancia del sol negro, pero no sientes ningún calor."
  },
  AvgDialog_118957_Content_56 = {
    Text = "Ese abismo negro infinito devoró toda la luz, ansioso por tragarte por completo."
  },
  AvgDialog_118957_Content_57 = {
    Text = "Ramona... ¿me esperarás después de esto?"
  },
  AvgDialog_118957_Content_58 = {
    Text = "Cierras los ojos, extendiendo suavemente tus dedos para tocar el pasaje negro."
  },
  AvgDialog_118957_Content_59 = {
    Text = "Si puedes, toma mi mano."
  },
  AvgDialog_118957_Content_6 = {
    Text = "En cuanto a \"este\" Murphy..."
  },
  AvgDialog_118957_Content_60 = {
    Text = "Desde tus pies, desde miles de sueños profundos."
  },
  AvgDialog_118957_Content_61 = {
    Text = "A partir del sol negro, el velo negro se descompuso en capas, poco a poco."
  },
  AvgDialog_118957_Content_62 = {
    Text = "Caes desde gran altura."
  },
  AvgDialog_118957_Content_63 = {
    Text = "<Yellow:Caer en el vórtice llamado\"destino\".>"
  },
  AvgDialog_118957_Content_64 = {
    Text = "Vi la experiencia de esa niña en un sueño profundo."
  },
  AvgDialog_118957_Content_65 = {
    Text = "Lamentablemente, Yu la envió lejos de Lemuria, confiando la estatua de marfil a ella en un sueño, no era para un final así."
  },
  AvgDialog_118957_Content_66 = {
    Text = "¿No deberías agradecerme por las conexiones que he hecho en esto?"
  },
  AvgDialog_118957_Content_67 = {
    Text = "La luz de la esperanza de este mundo ya ha sido aniquilada, deberías saberlo, ¿verdad?"
  },
  AvgDialog_118957_Content_68 = {
    Text = "La mujer acaricia la rueca en silencio, dejando que el hilo en sus manos se extienda bajo el cielo, entre todas las cosas."
  },
  AvgDialog_118957_Content_69 = {
    Text = "Mientras haya una semilla."
  },
  AvgDialog_118957_Content_7 = {
    Text = "Creo que ella debería tener algo que decirte."
  },
  AvgDialog_118957_Content_70 = {
    Text = "No importa cuánto tiempo permanezca en silencio, no importa en qué suelo esté, algún día germinará."
  },
  AvgDialog_118957_Content_71 = {
    Text = "En cuanto a mí..."
  },
  AvgDialog_118957_Content_72 = {
    Text = "La mujer baja la mirada."
  },
  AvgDialog_118957_Content_73 = {
    Text = "No soy ni sembrador, ni cuidador, ni cosechador."
  },
  AvgDialog_118957_Content_74 = {
    Text = "Simplemente tiro de los hilos, sigo los principios celestiales y retrato a la persona del destino."
  },
  AvgDialog_118957_Content_75 = {
    Text = "Yo guiaré el hilo de la rueca para extraer la tierra más adecuada para ella."
  },
  AvgDialog_118957_Content_76 = {
    Text = "Esperaré en silencio."
  },
  AvgDialog_118957_Content_8 = {
    Text = "¿Llegaste?"
  },
  AvgDialog_118957_Content_9 = {Text = "Bien."},
  AvgDialog_118958_Content_1 = {Text = "núcleo"},
  AvgDialog_118958_Content_10 = {
    Text = "Una vez me alié con Goliat, pero el bárbaro que solo entiende de guerra y violencia claramente no sabe cómo cumplir un contrato, ni puede guiar el camino hacia Lemuria."
  },
  AvgDialog_118958_Content_11 = {
    Text = "¿Cómo? Solo si asientes con la cabeza, te revelaré la identidad del maestro del dominio."
  },
  AvgDialog_118958_Content_12 = {
    Text = "El corazón de la niña subió a su garganta."
  },
  AvgDialog_118958_Content_13 = {
    Text = "Permíteme rechazar."
  },
  AvgDialog_118958_Content_14 = {
    Text = "No puedo aceptar apresuradamente quitarle la vida a alguien sin saber quién es."
  },
  AvgDialog_118958_Content_15 = {
    Text = "Además, dado que has hecho tal solicitud, el maestro del dominio claramente no está entre tú, Goliat y Caecus."
  },
  AvgDialog_118958_Content_16 = {
    Text = "Y ya has revelado que la autoridad del sueño está relacionada con esa estatua de marfil."
  },
  AvgDialog_118958_Content_17 = {
    Text = "Entonces, la única sospechosa que queda es ella..."
  },
  AvgDialog_118958_Content_18 = {
    Text = "Tu elección de lugar para observar es realmente digna de elogio."
  },
  AvgDialog_118958_Content_19 = {
    Text = "Tiras de la cuerda, haciendo que la vela del mástil cubra las figuras de tú y William."
  },
  AvgDialog_118958_Content_2 = {
    Text = "<Shake:¡Toc toc toc, toc toc!>"
  },
  AvgDialog_118958_Content_20 = {
    Text = "Noté en la última ceremonia que, en comparación con el Sonanil, el Paradeis ha mantenido una estructura de mástil relativamente antigua."
  },
  AvgDialog_118958_Content_21 = {
    Text = "Es equivalente a una torre de vigilancia, permitiendo observar la situación en el lugar de la ceremonia de guía."
  },
  AvgDialog_118958_Content_22 = {
    Text = "Al comenzar la Ceremonia de Navegación, Miryam le entregará la Estatua de marfil a Murphy, y este es el único momento en que podemos tocar la Estatua de marfil."
  },
  AvgDialog_118958_Content_23 = {
    Text = "Si quitamos la estatua y la analizamos, tal vez podamos encontrar una manera de levantar el dominio."
  },
  AvgDialog_118958_Content_24 = {
    Text = "Shh, ellas vienen."
  },
  AvgDialog_118958_Content_25 = {
    Text = "William te dio un toque en el hombro, indicándote que te giraras."
  },
  AvgDialog_118958_Content_26 = {
    Text = "Presta atención a la posición de la estatua de marfil... Esta es nuestra línea de vida."
  },
  AvgDialog_118958_Content_27 = {
    Text = "Idéntico a tus recuerdos, la ceremonia de guía está avanzando sistemáticamente."
  },
  AvgDialog_118958_Content_28 = {
    Text = "Respetada Madre divina, por favor, guía la sangre del rey divino, orienta a los Marchadores de mares perdidos y muéstranos el rumbo hacia Lemuria."
  },
  AvgDialog_118958_Content_29 = {
    Text = "Murphy mordió su labio y tomó la daga brillante de las manos de Miryam."
  },
  AvgDialog_118958_Content_3 = {
    Text = "La niña corre por el pasillo."
  },
  AvgDialog_118958_Content_30 = {
    Text = "Ella levantó el cuchillo bien alto—luego dudó durante un largo tiempo sin hundirlo."
  },
  AvgDialog_118958_Content_31 = {
    Text = "Madre divina, ¿no ha tomado ya una decisión? Lemuria aún está en el fondo del abismo, esperando su llegada."
  },
  AvgDialog_118958_Content_32 = {
    Text = "...esto es..."
  },
  AvgDialog_118958_Content_33 = {
    Text = "La segunda mitad de la frase fue tragada."
  },
  AvgDialog_118958_Content_34 = {
    Text = "Ella sostuvo la estatua de marfil empapada en sangre, dejando que ese monstruo deformado drenara su espiritualidad."
  },
  AvgDialog_118958_Content_35 = {
    Text = "El río de sangre se extiende por la borda, y sigue hacia la izquierda."
  },
  AvgDialog_118958_Content_36 = {
    Text = "¡Gira! ¡Timón del marinero, escucha el oráculo, a la izquierda con el timón!"
  },
  AvgDialog_118958_Content_37 = {
    Text = "Lo que le respondió fue un agudo sonido cortante."
  },
  AvgDialog_118958_Content_38 = {
    Text = "No creo que sea necesario."
  },
  AvgDialog_118958_Content_39 = {
    Text = "El afilado arpón, como los dientes puntiagudos de un gran tiburón, surgió repentinamente de la oscuridad de la noche, atravesando con precisión la garganta del timonel."
  },
  AvgDialog_118958_Content_4 = {
    Text = "Al pasar por la sala del capitán, una voz serena llegó a sus oídos."
  },
  AvgDialog_118958_Content_40 = {
    Text = "La pesada gran espada dejó chispas en la cubierta, el gigante salió de la oscuridad de la noche, aplastando el cráneo del timonel y mostrando una sonrisa cruel a la bruja frente a él."
  },
  AvgDialog_118958_Content_41 = {
    Text = "Detrás de él, un bárbaro vestido con un impermeable de aceite azul-gris agarra una cuchilla, esperando ansiosamente la orden de matar."
  },
  AvgDialog_118958_Content_42 = {
    Text = "Goliat... ¿todavía no te rindes?"
  },
  AvgDialog_118958_Content_43 = {
    Text = "Reúne a los marineros, provoca caos... intentando romper la calma del paraíso..."
  },
  AvgDialog_118958_Content_44 = {
    Text = "Lamentablemente, no soy parte de esta calma. Esta vez, la próxima, la siguiente... los filisteos nunca aceptarán vivir eternamente por debajo de los demás."
  },
  AvgDialog_118958_Content_45 = {
    Text = "¡Ven, filisteo!"
  },
  AvgDialog_118958_Content_46 = {
    Text = "Con voces malignas, los bárbaros vestidos con impermeables de lona empuñan cuchillas, emergiendo en masa de las sombras."
  },
  AvgDialog_118958_Content_47 = {
    Text = "El profundo gruñido temblaba de elación. Esperaban ansiosamente, aguardando el momento de reproducir la gloria, esperando la orden de masacrar todo."
  },
  AvgDialog_118958_Content_48 = {
    Text = "<Big:¡Mátalos!>"
  },
  AvgDialog_118958_Content_49 = {
    Text = "La canción de guerra ruda rasgó el cielo nocturno del mar, y la tribu salvaje levantó las cuerdas, golpeando a la multitud en la cubierta a una velocidad imposible de reaccionar."
  },
  AvgDialog_118958_Content_5 = {
    Text = "Sé quién es el maestro del dominio y también puedo guiarles para romper las fronteras del dominio y regresar al mundo real."
  },
  AvgDialog_118958_Content_50 = {
    Text = "Los filisteos, que han vivido de asaltos costeros durante mucho tiempo, se lanzan hacia su presa como tiburones que huelen sangre, ávidos y brutales, mordiendo los cuerpos de los enemigos con sus cuchillos curvados como colmillos."
  },
  AvgDialog_118958_Content_51 = {
    Text = "¡Mi Señor, escucha el llamado de los creyentes... por favor, derrama tu gracia sobre tu pueblo..."
  },
  AvgDialog_118958_Content_52 = {
    Text = "Miryam extendió los brazos, y la luz oscura se extendió gradualmente."
  },
  AvgDialog_118958_Content_53 = {
    Text = "Los Marchadores de Mares, vestidos con extrañas túnicas negras, no emitieron ningún sonido, como un grupo de fantasmas negros devotos, bañándose en la profunda gracia divina, silenciosamente clavando la daga en el pecho del enemigo."
  },
  AvgDialog_118958_Content_54 = {
    Text = "El gris azulado y el negro púrpura, dos grupos claramente diferenciados luchan a muerte en este infierno en movimiento."
  },
  AvgDialog_118958_Content_55 = {
    Text = "¡Masacra, mis miembros de la familia... aquí, reproduce la gloria de los filisteos!"
  },
  AvgDialog_118958_Content_56 = {
    Text = "La enorme hoja cortó sin piedad la cabeza del creyente marinero que se interponía en su camino, la sangre salada brotando tiñó de carmesí gran parte del rostro de Goliath."
  },
  AvgDialog_118958_Content_57 = {
    Text = "Lame la sangre de su cara y, bajo la luz de los relámpagos, blande la gran espada que tiene en la mano, asesinando a cada creyente que se interpone en su camino."
  },
  AvgDialog_118958_Content_58 = {
    Text = "La sangre acaba de brotar del cálido cuerpo, y en un instante es diluida por la tormenta, mezclándose con el agua del mar, formando corrientes carmesí y viscosas en la cubierta que se sacude violentamente."
  },
  AvgDialog_118958_Content_59 = {
    Text = "<Shake:Mi Señor, he escuchado su orden. Su creyente regresará al Reino Divino junto con usted...>"
  },
  AvgDialog_118958_Content_6 = {
    Text = "La niña intentó mantener la calma y suavizó sus pasos."
  },
  AvgDialog_118958_Content_60 = {
    Text = "Ritual, tormenta, combate..."
  },
  AvgDialog_118958_Content_61 = {
    Text = "En el centro de este caos, debajo de la ominosa estatua de marfil en la proa del barco, Miryam se mantenía firme, susurrando piedad en medio de la tormenta."
  },
  AvgDialog_118958_Content_62 = {
    Text = "Ella ignora el mar de sangre y las montañas de cadáveres a su alrededor, una daga pasa rozando su oído, una gran ola la empapa por completo, pero ella no se da cuenta."
  },
  AvgDialog_118958_Content_63 = {
    Text = "Que tu oráculo nos guíe, que tu cadáver nos envuelva."
  },
  AvgDialog_118958_Content_64 = {
    Text = "Miryam... ¡ríndete! ¡No podemos alcanzar Lemuria!"
  },
  AvgDialog_118958_Content_65 = {
    Text = "No... Él me prometió, y usted también escuchó Su Oráculo, ¿verdad?"
  },
  AvgDialog_118958_Content_66 = {
    Text = "Miryam mira devotamente hacia el horizonte."
  },
  AvgDialog_118958_Content_67 = {
    Text = "¡La tormenta es tu aliento, y el trueno es tu tambor de guerra!"
  },
  AvgDialog_118958_Content_68 = {
    Text = "Por favor, guía a este cordero extraviado, <Big:¡indica la dirección hacia tu reino!>"
  },
  AvgDialog_118958_Content_69 = {
    Text = "Un rayo pálido desgarró el cielo, iluminando instantáneamente sus ojos fervorosos y llenos de piedad."
  },
  AvgDialog_118958_Content_7 = {
    Text = "Pero mi asistencia es condicional."
  },
  AvgDialog_118958_Content_70 = {
    Text = "La chica con velo negro se encoge en silencio en una esquina de la proa del barco, su mirada vacía observa sin esperanza el campo de batalla, como una muñeca de trapo desechada en un montón de chatarra."
  },
  AvgDialog_118958_Content_71 = {
    Text = "¡Vamos, bajemos!"
  },
  AvgDialog_118958_Content_72 = {
    Text = "¡Yo me encargaré de llevarme la estatua de marfil!"
  },
  AvgDialog_118958_Content_73 = {
    Text = "¡Voy a aprovechar el caos para rescatar a Murphy!"
  },
  AvgDialog_118958_Content_8 = {
    Text = "¿Tu condición es...?"
  },
  AvgDialog_118958_Content_9 = {
    Text = "Mata al maestro del dominio, quita la estatua de marfil y transfieres el poder del dominio a mí."
  },
  AvgDialog_118959_Content_1 = {
    Text = "Me maté y tomé la corona. Además de la libertad, obtuve todo lo que deseaba."
  },
  AvgDialog_118959_Content_10 = {
    Text = "Porque tú eres diferente."
  },
  AvgDialog_118959_Content_11 = {
    Text = "¿Qué es lo que me hace diferente de ellas? Solo somos ofrendas a tus ojos, solo carne de cañón para este montón de carne podrida."
  },
  AvgDialog_118959_Content_12 = {
    Text = "Murphy sostuvo el bulto sucio en sus manos, la sangre brillante goteaba profusamente."
  },
  AvgDialog_118959_Content_13 = {
    Text = "No, tú eres diferente a ellas."
  },
  AvgDialog_118959_Content_14 = {Text = "Porque..."},
  AvgDialog_118959_Content_15 = {
    Text = "Hemos caminado juntos todo el camino."
  },
  AvgDialog_118959_Content_16 = {
    Text = "Recuerdo el día en que implantaste el Feto Sagrado en tu pecho; dijiste que querías comer churros."
  },
  AvgDialog_118959_Content_17 = {
    Text = "De repente te das cuenta de que es tan delicioso que no es adecuado para disfrutarlo solo, y con un poco de timidez decides darme la mitad."
  },
  AvgDialog_118959_Content_18 = {
    Text = "Después, el Feto Sagrado comenzó a crecer, tú tenías una fiebre alta incesante, intentamos todos los métodos para bajar la temperatura, pero al final solo pudimos llevarte a la nevera de hielo en la Antártida."
  },
  AvgDialog_118959_Content_19 = {
    Text = "Nos ha causado bastantes problemas."
  },
  AvgDialog_118959_Content_2 = {
    Text = "Pero yo, que di a luz al Niño Santo, no obtuve la gracia de la profecía, no pude guiar el camino hacia Lemuria..."
  },
  AvgDialog_118959_Content_20 = {
    Text = "Incluso en un entorno tan difícil, sigues cumpliendo con tus deberes como Madre divina."
  },
  AvgDialog_118959_Content_21 = {
    Text = "La mayoría de los sacerdotes soportan el frío, acompañando, esperando y orando en el altar de la Antártida."
  },
  AvgDialog_118959_Content_22 = {
    Text = "Y no decepcionaste, convirtiéndote en la primera madre en dar a luz al Niño Santo."
  },
  AvgDialog_118959_Content_23 = {
    Text = "Hemos llegado juntos a ese momento."
  },
  AvgDialog_118959_Content_24 = {
    Text = "Navegaremos juntos hacia el eterno Reino Divino."
  },
  AvgDialog_118959_Content_25 = {
    Text = "Miryam caminó lentamente y firmemente hacia Murphy, inclinándose."
  },
  AvgDialog_118959_Content_26 = {
    Text = "Eres la respetada Madre divina, y estoy dispuesto a arrodillarme a tus pies por la eternidad, ofreciéndote mi devoción de por vida."
  },
  AvgDialog_118959_Content_27 = {
    Text = "Estoy dispuesto a mirarte eternamente, tratándote como a esa\"deidad\"."
  },
  AvgDialog_118959_Content_28 = {
    Text = "Murphy miraba fijamente a Miriam."
  },
  AvgDialog_118959_Content_29 = {
    Text = "Miryam se arrodilló a medias, tomó su mano y le dio un beso devoto sobre ella."
  },
  AvgDialog_118959_Content_3 = {
    Text = "Así que fabricaste este sueño interminable..."
  },
  AvgDialog_118959_Content_30 = {
    Text = "Regresa a mi lado, ¿sí? \"Madre divina\"."
  },
  AvgDialog_118959_Content_31 = {
    Text = "Murphy bajó la cabeza. El viento se detuvo, y en la pequeña grieta del universo reinaba un silencio profundo."
  },
  AvgDialog_118959_Content_32 = {
    Text = "Todas tus historias tratan sobre el Feto Sagrado. Todos tus títulos son inseparables de la Madre divina."
  },
  AvgDialog_118959_Content_33 = {
    Text = "Aún no entiendes... y nunca entenderás..."
  },
  AvgDialog_118959_Content_34 = {
    Text = "Entre los espacios de los dientes, se filtraron unas pocas palabras."
  },
  AvgDialog_118959_Content_35 = {
    Text = "solo sabes de oración, ritual, Reino Divino, Lemuria, el nacimiento de los dioses..."
  },
  AvgDialog_118959_Content_36 = {
    Text = "Nunca entenderé."
  },
  AvgDialog_118959_Content_37 = {
    Text = "Todo lo que he hecho, el punto final que alcancé a través de dientes apretados, la ilusión que luché por mantener..."
  },
  AvgDialog_118959_Content_38 = {
    Text = "Solo quiero llamarte de una manera en la que me trates sinceramente..."
  },
  AvgDialog_118959_Content_39 = {Text = "Madre..."},
  AvgDialog_118959_Content_4 = {
    Text = "Si no hago esto, ella seguramente me arrancaría el corazón ella misma..."
  },
  AvgDialog_118959_Content_40 = {
    Text = "El viento furioso sobre la superficie del mar cubrió el susurro que ya era confuso."
  },
  AvgDialog_118959_Content_41 = {
    Text = "Qué lástima, qué lástima."
  },
  AvgDialog_118959_Content_42 = {
    Text = "Murphy secó sus lágrimas."
  },
  AvgDialog_118959_Content_43 = {
    Text = "Todas mis expectativas para ti son solo delirio, y el equilibrio mantenido por mentiras es meramente una ilusión eterna."
  },
  AvgDialog_118959_Content_44 = {
    Text = "Nunca serás mi madre."
  },
  AvgDialog_118959_Content_45 = {
    Text = "La Murphy que conocías ha estado muerta desde hace mucho tiempo. Su muerte llegó junto con el nacimiento de Dios."
  },
  AvgDialog_118959_Content_46 = {
    Text = "Aquí de pie, hay un... Despertado nacido de las cenizas de la vida y la Luminis de plata."
  },
  AvgDialog_118959_Content_47 = {
    Text = "La persona que me despertó de los escombros... No, ¿se puede llamar eso a una persona?"
  },
  AvgDialog_118959_Content_48 = {
    Text = "Mi enlazador está justo frente a ustedes."
  },
  AvgDialog_118959_Content_49 = {
    Text = "Ella levantó suavemente el manto, y en su rostro, capturaste una ternura extraña y casi aterradora que nunca habías visto antes."
  },
  AvgDialog_118959_Content_5 = {
    Text = "Ofrecerme como sacrificio al Rey que ella respeta."
  },
  AvgDialog_118959_Content_50 = {
    Text = "Lo traje a este mundo... y él me volvió a traer a este mundo..."
  },
  AvgDialog_118959_Content_51 = {
    Text = "El destino desviado está entrelazado, el ciclo inverso nunca termina."
  },
  AvgDialog_118959_Content_52 = {
    Text = "Un padre da a luz a sus hijos, y la hija gestará al padre, el padre vuelve a despertar a la hija..."
  },
  AvgDialog_118959_Content_53 = {
    Text = "Nadie viene a cortar este profundo lazo, nadie viene a impedir la confusión de un linaje eterno."
  },
  AvgDialog_118959_Content_54 = {
    Text = "¿Crees que eres la primera persona atrapada en el ciclo?"
  },
  AvgDialog_118959_Content_55 = {
    Text = "Antes de eso, ya había entrado en el ciclo innumerables veces, con el final de cada ciclo siendo una pesadilla inexplicable."
  },
  AvgDialog_118959_Content_56 = {
    Text = "Debido a rechazar Lemuria, el resultado de ser atravesado por el pecho por Miryam."
  },
  AvgDialog_118959_Content_57 = {
    Text = "Encarcelado por Goliat con cadenas, despojado de la estatua de marfil, enfrentando el destino de que todo el barco se hunda."
  },
  AvgDialog_118959_Content_58 = {
    Text = "Y en el sueño, una figura delgada pero fuerte abre un camino de escape para mí."
  },
  AvgDialog_118959_Content_59 = {
    Text = "Siempre he creído que ninguno de esos podría ser el verdadero final.\nEstoy esperando el final que pertenece únicamente a \"este yo\"."
  },
  AvgDialog_118959_Content_6 = {
    Text = "Así que dices que ella ha estado esperándome... No entiendo."
  },
  AvgDialog_118959_Content_60 = {
    Text = "El verdadero final puede llegar."
  },
  AvgDialog_118959_Content_61 = {
    Text = "Deja que este barco se hunda."
  },
  AvgDialog_118959_Content_62 = {
    Text = "El telón negro, como seda derramada del cielo, oscurece el cuerpo del barco y lo aísla del mundo exterior mientras el sol negro sin luz desciende."
  },
  AvgDialog_118959_Content_63 = {
    Text = "El agua del mar infinito inundó el Paradeis, enterrándolo en el abismo oscuro y desconocido."
  },
  AvgDialog_118959_Content_64 = {
    Text = "Una vez más, te hundes en la oscuridad infinita."
  },
  AvgDialog_118959_Content_7 = {
    Text = "<Shake:¿Por qué? Miryam, ¿por qué?>"
  },
  AvgDialog_118959_Content_8 = {
    Text = "Si no soy una Madre Divina calificada, entonces puedes simplemente rendirte conmigo como de costumbre, ¿verdad?"
  },
  AvgDialog_118959_Content_9 = {
    Text = "<Red:Abandóname... dame libertad...>"
  },
  AvgDialog_118960_Content_1 = {
    Text = "Velo eterno"
  },
  AvgDialog_118960_Content_10 = {
    Text = "No, siempre he podido manipular todo en el sueño, puedo decidir el final y el comienzo del ciclo, yo..."
  },
  AvgDialog_118960_Content_11 = {
    Text = "La divinidad te concede el poder de soñar, pero te encuentras atrapado en tu propia obsesión, desperdiciando Su buena voluntad."
  },
  AvgDialog_118960_Content_12 = {
    Text = "¿Prestar...?"
  },
  AvgDialog_118960_Content_13 = {
    Text = "¿Recuerdas de dónde vino esa estatua?"
  },
  AvgDialog_118960_Content_14 = {
    Text = "Estatua... Su figura..."
  },
  AvgDialog_118960_Content_15 = {
    Text = "Al dar a luz... al Niño Santo..."
  },
  AvgDialog_118960_Content_16 = {
    Text = "No, nunca he visto esta estatua en los siete días en que nació por primera vez el Niño Santo."
  },
  AvgDialog_118960_Content_17 = {
    Text = "Su imagen... es..."
  },
  AvgDialog_118960_Content_18 = {
    Text = "No es de extrañar que siempre sienta que falta una pieza en la respuesta completa."
  },
  AvgDialog_118960_Content_19 = {
    Text = "%player%, ¿recuerdas nuestra inferencia? \n El momento del nacimiento del dominio, antes de que la disolución devorara el mundo y el sol se transformara en un sol negro."
  },
  AvgDialog_118960_Content_2 = {
    Text = "<Red:No debería terminar>"
  },
  AvgDialog_118960_Content_20 = {
    Text = "Pero el ritual de nacimiento del Niño Santo, el sacrificio y renacimiento de Murphy, claramente ocurrieron después del nacimiento del Apocalipsis Negro."
  },
  AvgDialog_118960_Content_21 = {
    Text = "En otras palabras, en ese momento, Murphy solo era un humano lleno de espiritualidad, insuficiente para construir este sueño."
  },
  AvgDialog_118960_Content_22 = {
    Text = "El que ejerció la autoridad antes de eso... debería ser..."
  },
  AvgDialog_118960_Content_23 = {
    Text = "El Rey Dios de este mundo ha nacido hace mucho tiempo... no, más bien, nunca ha muerto."
  },
  AvgDialog_118960_Content_24 = {
    Text = "No puedes despertar su conciencia porque aún está en el profundo sueño de un Sueño."
  },
  AvgDialog_118960_Content_25 = {
    Text = "Él no puede soportar verte morir por el ritual de sacrificio, por eso te otorgó un hilo de fuerza, creando para ti un sueño dentro de un sueño."
  },
  AvgDialog_118960_Content_26 = {
    Text = "Lamentablemente, lo que buscas es demasiado... Así, el sueño se desmorona y reinicia constantemente, esa es la esencia del Paraíso."
  },
  AvgDialog_118960_Content_27 = {
    Text = "Nació de tus deseos, pero no es tu esclavo..."
  },
  AvgDialog_118960_Content_28 = {
    Text = "<Yellow:Así que, ahora, Él va a cumplir la misión que le ha otorgado el Creador.>"
  },
  AvgDialog_118960_Content_29 = {
    Text = "El cielo comienza a agitarse, un velo negro cubre el campo de visión, y un enorme cuerpo se eleva como una montaña."
  },
  AvgDialog_118960_Content_3 = {Text = "?!"},
  AvgDialog_118960_Content_30 = {
    Text = "No surgió del Abismo, sino que la\"voluntad\"en sí misma rompió la cáscara de las dimensiones."
  },
  AvgDialog_118960_Content_31 = {
    Text = "Bajo la cúpula sofocante, Sus extremidades se revelan en silencio: pálidas, delgadas, con las articulaciones retorcidas, como los esqueletos torturados de los santos."
  },
  AvgDialog_118960_Content_32 = {
    Text = "<Big:<Shake:...!!!>>"
  },
  AvgDialog_118960_Content_33 = {Text = "Murphy..."},
  AvgDialog_118960_Content_34 = {
    Text = "La silueta enorme es claramente la figura de la niña que conoces."
  },
  AvgDialog_118960_Content_35 = {
    Text = "<Red:sueño... debe... continuar...>"
  },
  AvgDialog_118960_Content_4 = {
    Text = "<Red:No se puede terminar>"
  },
  AvgDialog_118960_Content_5 = {
    Text = "El cielo comienza a suturarse, un velo negro cubre el cielo y el sol, reuniéndose en un cielo falso."
  },
  AvgDialog_118960_Content_6 = {
    Text = "Cras, cras, escuchas el sonido de la rueca volviendo a girar."
  },
  AvgDialog_118960_Content_7 = {
    Text = "¿Por qué? ¿Por qué? He decidido claramente poner fin a este sueño..."
  },
  AvgDialog_118960_Content_8 = {
    Text = "Porque... querida Madre divina, el verdadero maestro de este sueño no eres tú."
  },
  AvgDialog_118960_Content_9 = {Text = "¿?!!"},
  AvgDialog_118961_Content_1 = {Text = "Delirio"},
  AvgDialog_118961_Content_10 = {
    Text = "¿Te sorprende? La única ruta de escape en este barco está bajo mi control."
  },
  AvgDialog_118961_Content_11 = {
    Text = "Goliath agarró a Murphy y la gran espada la presionó contra su garganta.\nSangre caía de su cuello, reuniéndose en la cicatriz que nunca sanará en su pecho."
  },
  AvgDialog_118961_Content_12 = {Text = "¡Murphy!"},
  AvgDialog_118961_Content_13 = {
    Text = "¡Madre divina!"
  },
  AvgDialog_118961_Content_14 = {
    Text = "Lo siento, aún no puedo estar tranquilo..."
  },
  AvgDialog_118961_Content_15 = {
    Text = "No es que Miriam no quiera liberar a esta niña, sino que esta niña está atando a Miriam."
  },
  AvgDialog_118961_Content_16 = {
    Text = "Es ella quien no se atreve, no quiere, ni puede dejar que Miryam descubra la verdad."
  },
  AvgDialog_118961_Content_17 = {
    Text = "¿A qué llamas la verdad?"
  },
  AvgDialog_118961_Content_18 = {
    Text = "Ella tampoco sabía dónde estaba Lemuria; nunca había visto la verdadera forma de un Dios."
  },
  AvgDialog_118961_Content_19 = {
    Text = "Porque ella no lo sabe, este barco solo puede derivar en el mar, y sigue a la deriva."
  },
  AvgDialog_118961_Content_2 = {
    Text = "Entonces, en este momento en que el dios ha nacido, ¿por qué sostienes firmemente a Murphy en tu mano?"
  },
  AvgDialog_118961_Content_20 = {
    Text = "No sé qué palabras usó esta niña para seducirlos a ustedes dos..."
  },
  AvgDialog_118961_Content_21 = {
    Text = "Un Gran Sacerdote Marchador de mares, una persona misteriosa que cae del cielo, es engañada por una niña."
  },
  AvgDialog_118961_Content_22 = {
    Text = "¿Acaso ya olvidaste cuándo ella se escapó?"
  },
  AvgDialog_118961_Content_23 = {Text = "Correr."},
  AvgDialog_118961_Content_24 = {
    Text = "La niña está corriendo."
  },
  AvgDialog_118961_Content_25 = {
    Text = "Ella no sabía dónde terminaría el viaje, ni si podría escapar de los ojos vigilantes de la madrina."
  },
  AvgDialog_118961_Content_26 = {
    Text = "<Shake:Ja, ja...>"
  },
  AvgDialog_118961_Content_27 = {
    Text = "No hay nadie esperándola al frente, y el extraño y algo cómico sonido de las aletas golpeando el suelo detrás de ella se vuelve cada vez más intenso."
  },
  AvgDialog_118961_Content_28 = {
    Text = "La noticia de la desaparición de la Santa se ha difundido, los Marchadores de mares están armando un equipo."
  },
  AvgDialog_118961_Content_29 = {
    Text = "¡Malditos, estos tipos molestos."
  },
  AvgDialog_118961_Content_3 = {
    Text = "Tu interrogatorio resuena con fuerza."
  },
  AvgDialog_118961_Content_30 = {
    Text = "Detrás del destello, la figura en una túnica morada que simbolizaba sus fracasos apareció lentamente..."
  },
  AvgDialog_118961_Content_31 = {Text = "..."},
  AvgDialog_118961_Content_32 = {
    Text = "El Murphy de este mundo no pudo escapar."
  },
  AvgDialog_118961_Content_33 = {
    Text = "Por esa persona que la envió al Marchador de mares y de repente se arrepintió de haberla enviado..."
  },
  AvgDialog_118961_Content_34 = {
    Text = "Ha desaparecido para siempre en la catástrofe de disolución de esa gran explosión."
  },
  AvgDialog_118961_Content_35 = {
    Text = "Esta niña no eligió convertirse en madre divina, así como yo no elegí convertirme en tu esclavo."
  },
  AvgDialog_118961_Content_36 = {
    Text = "Todos estamos aquí por... lo que queremos para nosotros mismos."
  },
  AvgDialog_118961_Content_37 = {
    Text = "<Shake:No, no tengo nada que quiero.> Yo... no quiero nada."
  },
  AvgDialog_118961_Content_38 = {
    Text = "¿No quieres nada? No, quieres muchas cosas."
  },
  AvgDialog_118961_Content_39 = {
    Text = "Quieres disfrutar de la cómoda vida de la Madre Divina, pero no deseas asumir la obligación de ser un guía."
  },
  AvgDialog_118961_Content_4 = {
    Text = "¿Te refieres a... con la mano apretada?"
  },
  AvgDialog_118961_Content_40 = {
    Text = "Temes ser abandonado, así que tratas a los demás como marionetas en tu vida, como juguetes para tu fiesta de té."
  },
  AvgDialog_118961_Content_41 = {
    Text = "Periódicamente, borrarás la memoria de todos en el barco y luego iniciarás un nuevo ciclo."
  },
  AvgDialog_118961_Content_42 = {
    Text = "Niña, déjame decirte: no seas demasiado lista; todo en este mundo tiene un precio."
  },
  AvgDialog_118961_Content_43 = {
    Text = "¿Pensaste que nunca habría nadie que descubriera tu pequeño truco? ¿Creíste que con esa estatua de marfil podrías lograr cualquier cosa?"
  },
  AvgDialog_118961_Content_44 = {
    Text = "Murphy apretó con fuerza la estatua de marfil que tenía en la mano."
  },
  AvgDialog_118961_Content_45 = {
    Text = "No seas tonto, niño estúpido."
  },
  AvgDialog_118961_Content_46 = {
    Text = "¿Crees que no sé nada sobre tus acciones? Simplemente no estoy preparado para enfrentarme a ti de manera directa."
  },
  AvgDialog_118961_Content_47 = {
    Text = "En cada ciclo, intento cambiar la forma de abordar el barco. Amenazarte, amenazar a Miryam, hacer volar la sala de potencia..."
  },
  AvgDialog_118961_Content_48 = {
    Text = "Después descubrí que, mientras esa maldita estatua de marfil siga aquí, no tengo espacio para luchar contigo."
  },
  AvgDialog_118961_Content_49 = {
    Text = "La risa despectiva de Goliat resonó en la cubierta."
  },
  AvgDialog_118961_Content_5 = {
    Text = "Eres tú quien construyó este sueño, aprisionando a Murphy en un sueño cíclico, ¿verdad?"
  },
  AvgDialog_118961_Content_50 = {
    Text = "Hasta hace unos meses, la acción en la Necrovia que fue destruida por esta pequeña cosa frente a mí."
  },
  AvgDialog_118961_Content_51 = {
    Text = "No se pudo capturar suficiente núcleo de plata, el poder divino de la estatua de marfil se ha agotado, y los recuerdos del despertado en el barco han estado largos tiempo desvanecidos."
  },
  AvgDialog_118961_Content_52 = {
    Text = "¿Recuerdas todo...? ¿Ellos recuerdan todo...?"
  },
  AvgDialog_118961_Content_53 = {
    Text = "Entonces, William no recuerda todo porque viene de otro mundo."
  },
  AvgDialog_118961_Content_54 = {
    Text = "Otros seres espirituales no son diferentes de mí... conocen la inversión del cielo y la tierra, y el flujo del tiempo."
  },
  AvgDialog_118961_Content_55 = {
    Text = "<Small:<Shake:¿Todos los que dijiste... incluyen... a ella?>>"
  },
  AvgDialog_118961_Content_56 = {
    Text = "Murphy bajó la cabeza, su voz era tan ligera que casi se desvanecía, su mirada era inestable, cada vez que se deslizaba hacia la mujer a su lado, pero antes de tocar su mirada, la retiraba de inmediato."
  },
  AvgDialog_118961_Content_57 = {
    Text = "Esa niña tan estúpida, te digo que todos los Despertados."
  },
  AvgDialog_118961_Content_58 = {
    Text = "Esto incluye naturalmente a esa mujer estúpida, Miryam."
  },
  AvgDialog_118961_Content_59 = {
    Text = "Entonces quieres decir..."
  },
  AvgDialog_118961_Content_6 = {
    Text = "Miryam reflexionó antes de hablar, y una profunda risa resonó detrás de ti."
  },
  AvgDialog_118961_Content_60 = {
    Text = "Miryam recuerda cada vez que ocurrió algo durante el ciclo; ha estado esperándote una y otra vez."
  },
  AvgDialog_118961_Content_61 = {
    Text = "Puedo conectar con los sueños de ese tipo de allá, he testificado el final de ese mundo. Supongo que Miryam también puede hacerlo."
  },
  AvgDialog_118961_Content_62 = {
    Text = "Pero en todos los ciclos que conozco, ella no hizo ningún intento, solo esperó pasivamente."
  },
  AvgDialog_118961_Content_63 = {
    Text = "Goliath levantó la barbilla, señalando a Miryam, que permanecía en silencio a su lado."
  },
  AvgDialog_118961_Content_64 = {
    Text = "Tú crees que ella está dispuesta a estar atrapada en esta ciudadela que tú construiste con tus propias manos."
  },
  AvgDialog_118961_Content_65 = {
    Text = "Miryam respondió en silencio a la especulación de Goliath."
  },
  AvgDialog_118961_Content_66 = {
    Text = "<Shake:¿Por qué? No entiendo por qué?>"
  },
  AvgDialog_118961_Content_67 = {
    Text = "¿No debería ser para ti un producto defectuoso, una herramienta desechada?"
  },
  AvgDialog_118961_Content_68 = {
    Text = "¿No deberías abandonarme como abandonaste a ellas?"
  },
  AvgDialog_118961_Content_7 = {
    Text = "Déjame contarte."
  },
  AvgDialog_118961_Content_8 = {
    Text = "<Shake:Porque esta niña llamada Murphy es una mentirosa.>"
  },
  AvgDialog_118961_Content_9 = {
    Text = "La multitud liderada por los filisteos abrió una pequeña brecha, y entre las rendijas, un marinero empujó a la desaliñada Murphy."
  },
  AvgDialog_118962_Content_1 = {
    Text = "Cierras la puerta de la cabina, insertas el tapón y escuchas cómo los pasos que te persiguen se desvían en otra dirección, antes de girarte para observar a tu pequeño rehén."
  },
  AvgDialog_118962_Content_10 = {
    Text = "Si no cumplen con sus deberes... ¿dónde estarán?"
  },
  AvgDialog_118962_Content_11 = {
    Text = "Según el temperamento de Goliat, no debería estar holgazaneando en el casino subterráneo."
  },
  AvgDialog_118962_Content_12 = {
    Text = "Él debe estar tramando algo en secreto..."
  },
  AvgDialog_118962_Content_13 = {
    Text = "William se encuentra en el dormitorio de Murphy."
  },
  AvgDialog_118962_Content_14 = {
    Text = "Aunque sea solo yo, al menos puedo retrasarlos veinte minutos... es suficiente..."
  },
  AvgDialog_118962_Content_15 = {
    Text = "Los pasos se volvieron escasos de repente."
  },
  AvgDialog_118962_Content_16 = {
    Text = "¡Bienvenido, Gran Sacerdote!"
  },
  AvgDialog_118962_Content_17 = {
    Text = "¡Gran Sacerdote, hemos acorralado a los invasores en la cámara de la Madre divina! Solo necesita dar la orden..."
  },
  AvgDialog_118962_Content_18 = {
    Text = "No es necesario, la Madre divina ya no está aquí."
  },
  AvgDialog_118962_Content_19 = {
    Text = "(¡¡¡Me han descubierto?!)"
  },
  AvgDialog_118962_Content_2 = {Text = "Hmph..."},
  AvgDialog_118962_Content_20 = {
    Text = "¿La gente en la habitación... mejor hablemos?"
  },
  AvgDialog_118962_Content_21 = {
    Text = "¿De qué quieres hablar?"
  },
  AvgDialog_118962_Content_22 = {
    Text = "Ya seas tú o tus amigos, desde que subieron al barco, todos los Marchadores de mares te han tratado con respeto."
  },
  AvgDialog_118962_Content_23 = {
    Text = "Ustedes, en cambio, han devuelto el favor con ingratitud, secuestrando a la Madre Divina y causando que el crucial ritual de navegación no se lleve a cabo a tiempo."
  },
  AvgDialog_118962_Content_24 = {
    Text = "Si perdemos este momento de alineación de las estrellas, nuestra gran ambición tendrá que esperar otros sesenta ciclos de rotaciones estelares."
  },
  AvgDialog_118962_Content_25 = {
    Text = "Debe haber una razón detrás de esto, y quiero escuchar ambas razones."
  },
  AvgDialog_118962_Content_26 = {
    Text = "¿Es por los ciclos que experimentó el Guardián del Secreto? ¿Porque esa niña fue una parte de Misaq?"
  },
  AvgDialog_118962_Content_27 = {
    Text = "William aún no había aclarado el hilo de su respuesta, cuando de repente un sonido húmedo y nauseabundo de retorcimiento vino de detrás."
  },
  AvgDialog_118962_Content_28 = {
    Text = "Él se dio la vuelta de repente——su pupilo se contrajo al instante. Varios hombres pez ya habían llenado la ventana como un torrente de aguas residuales que rompe diques."
  },
  AvgDialog_118962_Content_29 = {
    Text = "Miembros retorcidos irrumpen en la habitación, una cascada de fluidos corporales espeluznantes y viscosos cae, empapando instantáneamente la alfombra en un pantano resbaladizo."
  },
  AvgDialog_118962_Content_3 = {
    Text = "Ella sacó un pequeño espejo de algún lugar y, meticulosamente, estaba arreglando el cabello desordenado en su frente."
  },
  AvgDialog_118962_Content_30 = {
    Text = "Él estaba como un clavo, clavado firmemente en el punto de muerte donde dos olas malignas estaban a punto de converger."
  },
  AvgDialog_118962_Content_31 = {
    Text = "¿Cómo se logró...?"
  },
  AvgDialog_118962_Content_32 = {
    Text = "La ventana del costado está a más de diez metros del puente, el Guardián del Secreto escapó y cortó la larga cuerda a tiempo."
  },
  AvgDialog_118962_Content_33 = {
    Text = "¿Cómo lograron deslizarse silenciosamente a través de las ventanas por las suaves paredes?"
  },
  AvgDialog_118962_Content_34 = {
    Text = "El Reino Divino nos otorga la fuerza suficiente para enfrentar el Desastre, estas insignificantes obstrucciones no pueden atrapar a los Marchadores de mares."
  },
  AvgDialog_118962_Content_35 = {
    Text = "¿Criaturas marinas... son ventosas en los pies?"
  },
  AvgDialog_118962_Content_36 = {
    Text = "Excepto por los marchadores de mares que están estacionados en el crucero, todas las criaturas marinas que rodean el casco del barco han venido en respuesta al espíritu de nuestro Señor, a nuestra orden."
  },
  AvgDialog_118962_Content_37 = {
    Text = "Incluso si no es de esta manera, deberías saber que no puedes enfrentarte a toda la iglesia del Marchador de mares con una habitación tan pequeña..."
  },
  AvgDialog_118962_Content_38 = {
    Text = "El investigador de Misaq no sería tan imprudente... Dime, ¿qué más sabes?"
  },
  AvgDialog_118962_Content_39 = {
    Text = "<Big:<Shake:¡Rumble——>>"
  },
  AvgDialog_118962_Content_4 = {
    Text = "¿Dónde está esa estructura de la que hablas...?"
  },
  AvgDialog_118962_Content_40 = {
    Text = "Un estruendo metálico desgarrador atravesó el cielo, acompañado de un violento temblor, como si una mano gigante e invisible lo apretara y lo retorciera brutalmente!"
  },
  AvgDialog_118962_Content_41 = {
    Text = "¿Qué pasa?!"
  },
  AvgDialog_118962_Content_42 = {
    Text = "¡Alguien está cambiando la dirección por la fuerza!"
  },
  AvgDialog_118962_Content_43 = {
    Text = "Un barco de diez mil toneladas se retorcía y chocaba como una bestia furiosa y descontrolada en las enormes olas del mar nocturno, cada sacudida violenta parecía desgarrar el casco del barco!"
  },
  AvgDialog_118962_Content_44 = {
    Text = "¡La sala de poder... es la sala de poder!"
  },
  AvgDialog_118962_Content_45 = {
    Text = "¡Goliat ha tomado rehenes y ha ocupado la sala de poder!"
  },
  AvgDialog_118962_Content_46 = {
    Text = "Otra vez..."
  },
  AvgDialog_118962_Content_47 = {
    Text = "Temblores feroces vienen ola tras ola."
  },
  AvgDialog_118962_Content_48 = {Text = "Murphy..."},
  AvgDialog_118962_Content_49 = {
    Text = "Sé que definitivamente no puedes soltar a ese compañero de clase tuyo, ¿verdad?"
  },
  AvgDialog_118962_Content_5 = {
    Text = "Justo debajo del asiento del capitán, aquí tienes."
  },
  AvgDialog_118962_Content_50 = {
    Text = "Entiendo todo; uno por uno, dicen que soy la persona más importante, pero en el momento crítico de la elección, todos me abandonan fácilmente."
  },
  AvgDialog_118962_Content_51 = {Text = "Yo..."},
  AvgDialog_118962_Content_52 = {
    Text = "Está bien, está bien, solo son algunas quejas inútiles disfrazadas de otra cosa. No somos realmente tan cercanos, ¿verdad?"
  },
  AvgDialog_118962_Content_53 = {
    Text = "Además, si explota la sala de poder, es de temer que el camarote de la planta baja también se vea afectado."
  },
  AvgDialog_118962_Content_54 = {
    Text = "Vamos, no tenemos segunda opción."
  },
  AvgDialog_118962_Content_6 = {
    Text = "Ella pisó la plancha de hierro que tenía debajo de sus pies."
  },
  AvgDialog_118962_Content_7 = {
    Text = "Sin embargo, aquí hay algo extraño..."
  },
  AvgDialog_118962_Content_8 = {
    Text = "En este momento del pasado, Goliat y Caecus deberían haber estado vigilando la cabina."
  },
  AvgDialog_118962_Content_9 = {
    Text = "Antes de la ceremonia, los seres del fondo marino entrarán en agitación, debemos evitar que el frenético cardumen interfiera en la dirección del barco..."
  },
  AvgDialog_118963_Content_1 = {
    Text = "Fiesta de la Madre divina"
  },
  AvgDialog_118963_Content_10 = {
    Text = "¿Te refieres a que..."
  },
  AvgDialog_118963_Content_11 = {
    Text = "Sí, todavía puedes ser tu Madre divina. Sin embargo, hoy es las vacaciones de la diosa madre."
  },
  AvgDialog_118963_Content_12 = {
    Text = "Dices mentiras sin inmutarte."
  },
  AvgDialog_118963_Content_13 = {
    Text = "¿Las vacaciones de la diosa madre?"
  },
  AvgDialog_118963_Content_14 = {
    Text = "Sí, hoy se me encomendó traerte al barco para un día de diversión."
  },
  AvgDialog_118963_Content_15 = {
    Text = "Después de embarcarte, ¿aún no has experimentado la vida real de la tripulación, verdad?"
  },
  AvgDialog_118963_Content_16 = {
    Text = "Sin posibilidad de rechazar, 'invitaste' a Murphy a salir del dormitorio."
  },
  AvgDialog_118963_Content_17 = {
    Text = "¿Debemos escalar un lugar así?"
  },
  AvgDialog_118963_Content_18 = {
    Text = "¡Apresúrate a subir, solo allí hay un buen campo de visión y puedes observar la situación de los marchadores de mares."
  },
  AvgDialog_118963_Content_19 = {
    Text = "¡Si sigues moviéndote tan lentamente, serás descubierto!"
  },
  AvgDialog_118963_Content_2 = {
    Text = "Abres los ojos. El sol brillante te lastima los ojos."
  },
  AvgDialog_118963_Content_20 = {
    Text = "¡Qué demonios, está todo desordenado!"
  },
  AvgDialog_118963_Content_21 = {
    Text = "Dicho esto, ella te tomó la mano obedientemente y, con poco esfuerzo, la levantaste hasta la plataforma."
  },
  AvgDialog_118963_Content_22 = {
    Text = "¡Pff——!"
  },
  AvgDialog_118963_Content_23 = {
    Text = "Murphy de repente se rió en voz alta."
  },
  AvgDialog_118963_Content_24 = {
    Text = "¿De qué te ríes?"
  },
  AvgDialog_118963_Content_25 = {
    Text = "¡Tú subiendo por las cuerdas parece justo un mono!"
  },
  AvgDialog_118963_Content_26 = {
    Text = "Eres un tipo curioso, si no fuera porque debo mantener el volumen ahora, definitivamente te golpearía en la frente..."
  },
  AvgDialog_118963_Content_27 = {
    Text = "¡Deja de reír! ¡Tú tampoco puedes escapar!"
  },
  AvgDialog_118963_Content_28 = {
    Text = "Tomas la mano de Murphy y la acercas a ti."
  },
  AvgDialog_118963_Content_29 = {
    Text = "¡Oye, cómo te atreves!"
  },
  AvgDialog_118963_Content_3 = {
    Text = "Pero no apartaste la mirada."
  },
  AvgDialog_118963_Content_30 = {Text = "¡Shh!"},
  AvgDialog_118963_Content_31 = {
    Text = "Todos contuvieron la respiración, un grupo de marchadores de mares con chaquetas de lluvia de paja desgastadas y sucias tambaleándose por la cubierta."
  },
  AvgDialog_118963_Content_32 = {
    Text = "¡Rápido, encuentra rápidamente el paradero de la Madre divina! ¡Ella debe estar en este barco!"
  },
  AvgDialog_118963_Content_33 = {
    Text = "Estamos justo encima de ellos, ¿y no nos ven en absoluto?"
  },
  AvgDialog_118963_Content_34 = {
    Text = "Desde la antigüedad, los patrulleros no miran hacia arriba."
  },
  AvgDialog_118963_Content_35 = {
    Text = "No te preocupes, mientras estemos escondidos aquí, nadie podrá descubrirnos."
  },
  AvgDialog_118963_Content_36 = {
    Text = "¡Cuac! ¡Mira arriba, hay alguien allí!"
  },
  AvgDialog_118963_Content_37 = {
    Text = "¡Eres un poco demasiado acertado con esa boca de cuervo!"
  },
  AvgDialog_118963_Content_38 = {
    Text = "Baja el perfil, después de eliminar a este grupo, ¡nos escabullimos a la sala de tripulación!"
  },
  AvgDialog_118963_Content_4 = {
    Text = "Susurros, susurros, el sonido del arrastre de la araña es como la suave insistencia de una madre."
  },
  AvgDialog_118963_Content_5 = {
    Text = "No es necesario recordarme. Lo sé, este es el último ciclo."
  },
  AvgDialog_118963_Content_6 = {
    Text = "Te limpiaste las lágrimas que brotaban de la esquina de tus ojos y te giraste hacia la dirección de donde vendría el llamado, sin volver la vista atrás para confirmar el origen de la canción."
  },
  AvgDialog_118963_Content_7 = {
    Text = "Porque sabes que la mujer que sostiene el telar te está mirando con compasión."
  },
  AvgDialog_118963_Content_8 = {
    Text = "¿Qué haces aquí? El viaje del barco ha reanudado, ya no hay lugar para ti aquí."
  },
  AvgDialog_118963_Content_9 = {
    Text = "No importa, eres la Madre divina de los Marchador de mares y la capitana del Paradeis, la dueña del Paraíso. Esto no está relacionado con el hecho de que te voy a dar un descanso."
  },
  AvgDialog_119922_Content_1 = {
    Text = "Bienvenido de nuevo, compañero."
  },
  AvgDialog_119922_Content_10 = {
    Text = "No pasa nada, mi señor, no importa cuánto tiempo necesite correr, Ogier estará contigo. Solo espero..."
  },
  AvgDialog_119922_Content_11 = {
    Text = "El joven caballero te mira seriamente, sus ojos llenos de sinceridad y una súplica oculta bajo esa sinceridad."
  },
  AvgDialog_119922_Content_12 = {
    Text = "Solo espero... que la próxima vez, si mi señor tiene la intención de \"distraerse\" y ausentarse tanto tiempo, por favor, asegúrese de llevarme con usted. Ogier jurará protegerlo hasta la muerte."
  },
  AvgDialog_119922_Content_13 = {
    Text = "O quizás yo también podría."
  },
  AvgDialog_119922_Content_14 = {
    Text = "Lotan también te miró, sus ojos, que normalmente son tan expresivos, estaban llenos de seriedad. En este momento, en su mente no había ni ganadores ni perdedores, ni lucha, solo preocupación por ti."
  },
  AvgDialog_119922_Content_15 = {
    Text = "......Sabía que terminaría así. Ustedes dos, no olviden el objetivo de esta fiesta del té. Estamos celebrando el \"regreso\" de %player%."
  },
  AvgDialog_119922_Content_16 = {
    Text = "Espero que después de tu \"regreso\" esta vez, no te vayas de nuevo."
  },
  AvgDialog_119922_Content_17 = {
    Text = "Solo fue un paseo para despejar la mente, no es para hablarlo tan en serio... Y de todos modos, ¿no he regresado?"
  },
  AvgDialog_119922_Content_18 = {
    Text = "Al escuchar tus palabras, Dól te miró. Parecía querer decir algo, pero al final, solo suspiró suavemente."
  },
  AvgDialog_119922_Content_19 = {
    Text = "Sí, has vuelto. Aquellos que buscaron tu figura en el campus solo pueden sentirse decepcionados, y aquellos que estaban de pie en silencio frente a tu puerta pero no se atrevieron a llamar también han pasado."
  },
  AvgDialog_119922_Content_2 = {
    Text = "Sin saber cuándo, la Plaza Misaq fue decorada para una pequeña merienda, y Ramona estaba de pie junto a una mesita llena de muffins, mermeladas y té, sonriendo y extendiéndote la mano."
  },
  AvgDialog_119922_Content_20 = {
    Text = "%player%, he dicho incontables veces antes, y seguiré haciéndolo en el futuro, tu existencia es increíblemente importante."
  },
  AvgDialog_119922_Content_21 = {
    Text = "Ya sea para este mundo o para nosotros. Entonces..."
  },
  AvgDialog_119922_Content_22 = {
    Text = "Esperas en silencio las palabras de Doll, pero ella solo cierra los ojos y no dice nada más."
  },
  AvgDialog_119922_Content_23 = {
    Text = "En ese momento, un par de manos cubrieron suavemente pero con firmeza tu mano, era Ramona."
  },
  AvgDialog_119922_Content_24 = {
    Text = "Compañero, sé que como Guardián del Secreto, soportas mucha presión, todos lo entendemos y lo comprendemos. Así que no te pediremos demasiado."
  },
  AvgDialog_119922_Content_25 = {
    Text = "Solo quiero que sepas que no importa cuántas veces te vayas, no importa cuánto tiempo estés ausente, estaremos aquí cuando regreses."
  },
  AvgDialog_119922_Content_26 = {
    Text = "Al decir esto, la voz de la chica se detuvo por un momento y lentamente te mostró una sonrisa."
  },
  AvgDialog_119922_Content_27 = {
    Text = "Una vez más, bienvenido a tu regreso, compañero. Ahora, disfruta de esta merienda preparada para ti."
  },
  AvgDialog_119922_Content_28 = {
    Text = "Así es. No hay evaluación hoy, ni tareas adicionales. Tu única tarea es hacerte feliz."
  },
  AvgDialog_119922_Content_29 = {
    Text = "Si no te importa las caries y el consumo excesivo de azúcar, puedes comer todos estos postres. Después de todo, están preparados para ti."
  },
  AvgDialog_119922_Content_3 = {
    Text = "¿No sé si tengo el honor de invitarte a la merienda de regreso que preparamos para ti?"
  },
  AvgDialog_119922_Content_30 = {
    Text = "No es necesario..."
  },
  AvgDialog_119922_Content_31 = {
    Text = "Aunque dijiste esto, aún probaste un bocado del bollo de mantequilla glaseado. El sabor era tan dulce como imaginabas, demasiado dulce, pero no desagradable."
  },
  AvgDialog_119922_Content_32 = {
    Text = "Porque, en las miradas cariñosas de todos, tu corazón ha encontrado satisfacción. Quizás, la vida se trata de saborear un bocado conmovedor de dulzura en los amargos intervalos de la realidad."
  },
  AvgDialog_119922_Content_4 = {
    Text = "Asientes, y entonces, la niña te toma suavemente de la mano y te lleva hacia la mesa triangular llena de platillos, donde ya están esperando los Despertados."
  },
  AvgDialog_119922_Content_5 = {
    Text = "Si me preguntas, ¿no es una pelea más \"emocionante\" que una fiesta de té? Pero en verdad... esta vez es un poco diferente."
  },
  AvgDialog_119922_Content_6 = {
    Text = "Esta vez, no tiene nada que ver con ganar o perder, nada que ver con la batalla. Solo se trata de ti."
  },
  AvgDialog_119922_Content_7 = {
    Text = "%player%, tú eres el personaje principal absoluto de esta fiesta de té."
  },
  AvgDialog_119922_Content_8 = {
    Text = "Lotan dijo, empujando el plato lleno de rollos de mantequilla con glaseado de azúcar hacia ti. \n Solo con echar un vistazo, ya sabes que tiene un contenido calórico increíblemente alto."
  },
  AvgDialog_119922_Content_9 = {
    Text = "Me pregunto por qué se siente como si... solo tomar un bocado requeriría un semestre entero para digerir..."
  },
  AvgDialog_119923_Content_1 = {
    Text = "En el pantano espiritual de oscuridad total, llegó un dolor punzante que atravesó el alma, junto con frías palabras."
  },
  AvgDialog_119923_Content_10 = {
    Text = "Recordando la sensación de tener el cráneo abierto, tu cerebro hormiguea, y para deshacerte de esta sensación, cambias activamente de tema."
  },
  AvgDialog_119923_Content_11 = {
    Text = "Este mundo... ¿Cómo está la situación ahora?"
  },
  AvgDialog_119923_Content_12 = {
    Text = "Sigue igual. Cada momento se acerca más al colapso y la destrucción. Pero al menos hay buenas noticias, para ti."
  },
  AvgDialog_119923_Content_13 = {
    Text = "Diciendo esto, Fusión·muñeca abrió el comunicador y, pronto, una figura familiar apareció frente a ti. Era un mensaje de comunicación que ya había sido grabado anteriormente."
  },
  AvgDialog_119923_Content_14 = {
    Text = "Fusión·muñeca, si %player% regresa con éxito o tiene alguna noticia, recuérdame decírmelo. Además, creo que tu propuesta de sembrar sugerencias psicológicas anteriormente fue muy razonable."
  },
  AvgDialog_119923_Content_15 = {
    Text = "Como profesional de la psicología, en lo que respecta a que %player% se quede, no puedo ceder demasiado a los deseos del paciente..."
  },
  AvgDialog_119923_Content_16 = {
    Text = "La comunicación se detuvo aquí, cerrada por Fusión·muñeca. Ella dio una suave palmada sobre la mesa, indicando que debías centrar tu atención en ella."
  },
  AvgDialog_119923_Content_17 = {
    Text = "Las trivialidades inútiles pueden detenerse aquí. Liberé estas cosas Solo para mostrarte qué es exactamente lo que te perdiste durante el tiempo que estuviste \"fuera\"."
  },
  AvgDialog_119923_Content_18 = {
    Text = "Lo más importante es que mi experimento aún no ha terminado..."
  },
  AvgDialog_119923_Content_19 = {
    Text = "Fusión·muñeca se acercó a ti con un bisturí en la mano. Su expresión era tranquila, pero ocultaba una locura."
  },
  AvgDialog_119923_Content_2 = {
    Text = "¿Cuánto tiempo más vas a seguir fingiendo que estás dormido? Mi lindo cachorro."
  },
  AvgDialog_119923_Content_20 = {
    Text = "¡Tú, tú qué quieres hacer?"
  },
  AvgDialog_119923_Content_21 = {
    Text = "Planeo fijar tu espíritu permanentemente en esta mente, este cuerpo. De esa manera, no podrás \"salir\" más."
  },
  AvgDialog_119923_Content_22 = {
    Text = "Te asustaste y retrocediste un paso, pero pronto recuperaste la calma porque recordaste que aún tenías cosas por hacer——"
  },
  AvgDialog_119923_Content_23 = {
    Text = "Fusión·muñeca, no es necesario. Solo mientras este mundo no haya vuelto a la normalidad, no me iré realmente."
  },
  AvgDialog_119923_Content_24 = {
    Text = "La figura que sostiene el bisturí se detiene y te mira en silencio, como si estuviera evaluando la veracidad de tus palabras."
  },
  AvgDialog_119923_Content_25 = {
    Text = "Soy serio. Como Guardián del Secreto, nunca renunciaré a salvar este mundo, así que no importa cuánto \"me vaya\", siempre regresaré."
  },
  AvgDialog_119923_Content_26 = {
    Text = "Fusión·Doll dejó el bisturí. Aprovechando esta oportunidad, tocaste tu pecho.\n Cuando tus dedos tocaron la familiar llave de plata, tu corazón realmente se sintió aliviado."
  },
  AvgDialog_119923_Content_27 = {
    Text = "Ahora, he vuelto. La investigación que se interrumpió anteriormente también puede continuar."
  },
  AvgDialog_119923_Content_28 = {
    Text = "Diciendo esto, te diriges hacia la puerta. Fusión·muñeca te lanzó una mirada y también te siguió."
  },
  AvgDialog_119923_Content_29 = {
    Text = "Parece que realmente entiendes la importancia de tu existencia en este mundo."
  },
  AvgDialog_119923_Content_3 = {
    Text = "¿Fusión·Dor?"
  },
  AvgDialog_119923_Content_30 = {
    Text = "Por supuesto, porque como dijo Tawil, soy la Variable de este mundo, el futuro de este mundo."
  },
  AvgDialog_119923_Content_31 = {
    Text = "Con tus palabras, la gran puerta del laboratorio se abre lentamente. El aire y la luz del exterior caen suavemente sobre ti, como un saludo silencioso o una respuesta."
  },
  AvgDialog_119923_Content_32 = {
    Text = "Este mundo te está esperando, esperando los cambios que estás a punto de traer, el futuro que estás a punto de crear."
  },
  AvgDialog_119923_Content_4 = {
    Text = "Reconociste al dueño de esa voz y abriste los ojos lentamente. Pronto, la oscuridad se desvaneció y la luz apareció——"
  },
  AvgDialog_119923_Content_5 = {
    Text = "¿Cómo se siente dejar este mundo?"
  },
  AvgDialog_119923_Content_6 = {
    Text = "Quizás la próxima vez debería también restringir tu \"Espíritu\", para que no necesite ser recuperado."
  },
  AvgDialog_119923_Content_7 = {
    Text = "Fusión·Doll entrecerró los ojos, mostrando una expresión que parecía una sonrisa, mientras manipulaba lentamente el bisturí que brillaba con una luz helada en sus manos."
  },
  AvgDialog_119923_Content_8 = {
    Text = "......¿Cómo estoy aquí?"
  },
  AvgDialog_119923_Content_9 = {
    Text = "Por supuesto, es porque cuando tu \"Espíritu\" se va, el recipiente pierde su función, por eso tuve que realizar la cirugía nuevamente para recuperar tu \"Espíritu\"."
  },
  AvgDialog_120290_Content_1 = {
    Text = "Hueso de belleza, el lugar de la venta de oro"
  },
  AvgDialog_120290_Content_10 = {
    Text = "La puerta se abre y caes en un abrazo. Ella te levanta a la cama, arropándote con las mantas, luego se inclina y toca su frente con la tuya, acercándote a su lado."
  },
  AvgDialog_120290_Content_11 = {
    Text = "¿Mamá...? ¡Mamá!"
  },
  AvgDialog_120290_Content_12 = {
    Text = "Papá no se ha preocupado por mí en mucho tiempo. No hay nadie en la casa que me ayude, y no hay agua... Me duele tanto la cabeza, y todo mi cuerpo me duele."
  },
  AvgDialog_120290_Content_13 = {
    Text = "...Mamá, no llores, mi buena niña."
  },
  AvgDialog_120290_Content_14 = {
    Text = "No te preocupes, pronto todo estará bien, Mamá te lo promete."
  },
  AvgDialog_120290_Content_15 = {
    Text = "Te hundes en la manta caliente, sintiendo somnoliento el aroma que gradualmente se vuelve más fuerte, ya no asemejándose al habitual perfume de jazmín de tu madre, sino como..."
  },
  AvgDialog_120290_Content_16 = {
    Text = "¿Qué se asemeja...? Como los callejones profundos y superpuestos de Ciudad Marina, donde grandes flores de magnolia blanca caen, fermentándose en los rincones debido al calor, con una extraña y profunda dulzura pegajosa y a pescado."
  },
  AvgDialog_120290_Content_17 = {
    Text = "Mamá, ¿ha cambiado tu olor? Huele tan bien, y... también es un poco extraño."
  },
  AvgDialog_120290_Content_18 = {
    Text = "La suave voz no respondió a tu pregunta. Con su suave palmadita, la fragancia se intensificó, casi volviéndose tangible."
  },
  AvgDialog_120290_Content_19 = {
    Text = "Quieres ver su cara claramente, pero solo una niebla interminable se difunde ante tus ojos, envolviéndote al final."
  },
  AvgDialog_120290_Content_2 = {
    Text = "Una niebla ligera lleva el aroma de jazmín, envolviendo tus extremidades y enredándose en ti de manera invisible y húmeda."
  },
  AvgDialog_120290_Content_20 = {
    Text = "Duerme, buen bebé, duerme. Mamá estará de vuelta a tu lado muy pronto."
  },
  AvgDialog_120290_Content_21 = {
    Text = "......Ya le he prometido."
  },
  AvgDialog_120290_Content_22 = {
    Text = "En la oscuridad, la sed aún te araña como la pata de un gato, y luego un líquido cálido y viscoso parece fluir hacia tu garganta desde tus fosas nasales o la comisura de tu boca."
  },
  AvgDialog_120290_Content_23 = {
    Text = "Tus párpados se vuelven cada vez más pesados, y entre la fragancia y los murmullos, poco a poco pierdes por completo la conciencia."
  },
  AvgDialog_120290_Content_24 = {
    Text = "......hasta que el sonido de pasos se reúne suavemente afuera de la puerta, despertándote de tu pesado y palpitante estupor con los sonidos de conversación."
  },
  AvgDialog_120290_Content_25 = {
    Text = "Oh, señorita Die, cada día que abres los ojos necesitas té, ¡es tan molesto! ¿Realmente crees que todavía eres la dama mimada que eras cuando estabas viva?"
  },
  AvgDialog_120290_Content_26 = {
    Text = "¡Baja la voz! ... El amo ni siquiera cuida de su propia hija, ¿cuántas bellas concubinas hay en el patio? Solo mira, ¿no está corriendo hacia la Cuarta Calle otra vez hoy."
  },
  AvgDialog_120290_Content_27 = {
    Text = "Solo observa, no tomará mucho tiempo. Pronto todas las concubinas en la casa tendrán a los pequeños maestros y maestras saliendo..."
  },
  AvgDialog_120290_Content_28 = {
    Text = "......¿Amo?"
  },
  AvgDialog_120290_Content_29 = {
    Text = "Levantas la cabeza, y un cuenco de cobre ligeramente sucio en el marco de madera refleja vagamente los delicados y juveniles rasgos de una persona del Lejano Oriente. Parpadeaste confundido, y la pequeña niña en el reflejo también parpadeó."
  },
  AvgDialog_120290_Content_3 = {
    Text = "La somnolencia después de la fiebre alta te hace inclinarte hacia esa niebla..."
  },
  AvgDialog_120290_Content_30 = {
    Text = "Tu conciencia se aclara gradualmente y algunos fragmentos sobre tu identidad emergen en tu mente."
  },
  AvgDialog_120290_Content_31 = {
    Text = "Señor, ¿de dónde?, papá... Estoy en la mansión de la familia He, soy la hija de He Fang, mi nombre es..."
  },
  AvgDialog_120290_Content_32 = {
    Text = "¡Ay, no puedes yacer en el suelo, el amo me regañará si te ve."
  },
  AvgDialog_120290_Content_33 = {
    Text = "La puerta fue empujada de repente, interrumpiendo tus pensamientos, y alguien se apresuró a acercarse y te ayudó a levantarte de mala gana."
  },
  AvgDialog_120290_Content_34 = {
    Text = "¿Acabo de caer al suelo? ¿Dónde está mamá?"
  },
  AvgDialog_120290_Content_35 = {
    Text = "¿Mamá? Señorita, debe estar clara; la dama ha estado ausente por más de un mes."
  },
  AvgDialog_120290_Content_36 = {
    Text = "Ella soltó de repente, al verte parado en estado de estupor, con una expresión de compasión en su rostro."
  },
  AvgDialog_120290_Content_37 = {
    Text = "<Small:Solo es así de pequeño, probablemente ni siquiera sepa qué significa irse.>"
  },
  AvgDialog_120290_Content_38 = {
    Text = "<LightGray:Sí, mamá hace más de un mes que...>"
  },
  AvgDialog_120290_Content_39 = {
    Text = "¿Soñaste de nuevo? Suspiro. Aquí, te traje agua."
  },
  AvgDialog_120290_Content_4 = {
    Text = "Luego cayó directamente al suelo."
  },
  AvgDialog_120290_Content_40 = {
    Text = "Agua... de repente te das cuenta de que ya no tienes sed; el líquido que fluyó antes, acompañado de su fragancia."
  },
  AvgDialog_120290_Content_41 = {
    Text = "¡El dulce aroma de magnolia blanca, que persiste en tus dientes y fosas nasales, casi en descomposición!\nDe repente, reaccionas y sales corriendo."
  },
  AvgDialog_120290_Content_42 = {
    Text = "¡Hola, hola! ¿A dónde crees que vas, señorita!"
  },
  AvgDialog_120290_Content_43 = {
    Text = "Ha llegado el festival del Lejano Oriente, las luces están encendiéndose, y las linternas rojas y las luces de neón modernas se complementan entre sí. Sin embargo, las personas que deberían haber regresado a casa temprano este día están fluyendo todas en la misma dirección."
  },
  AvgDialog_120290_Content_44 = {
    Text = "El aire está impregnado del aroma de polvos de maquillaje, queroseno, el olor a grasa de los puestos de comida y restaurantes, y un creciente..."
  },
  AvgDialog_120290_Content_45 = {
    Text = "¡Mamá, es el aroma de Mamá, no fue un sueño, no fue un sueño!"
  },
  AvgDialog_120290_Content_46 = {
    Text = "Encontraste el origen de ese extraño, intenso, familiar, íntimo y tierno olor metálico dulce."
  },
  AvgDialog_120290_Content_47 = {
    Text = "El letrero del \"Edificio de Ventas de Oro\" cuelga a lo lejos en la puerta ornamentada."
  },
  AvgDialog_120290_Content_48 = {
    Text = "¡Señor Xu!"
  },
  AvgDialog_120290_Content_49 = {
    Text = "¡Muévete, estás bloqueando mi camino, Señor Xu, mira allá!"
  },
  AvgDialog_120290_Content_5 = {
    Text = "¡Ay! Duele... Mamá... Agua..."
  },
  AvgDialog_120290_Content_50 = {Text = "Tsk"},
  AvgDialog_120290_Content_51 = {
    Text = "La figura en la plataforma alta jugaba con desinterés con un abanico negro, medio rostro oculto tras la superficie del abanico."
  },
  AvgDialog_120290_Content_52 = {
    Text = "La gente se empujaba entre sí, casi abrumándote, con un vago fervor y ansiedad asomando en sus ojos, pero parecía no afectar a ella."
  },
  AvgDialog_120290_Content_53 = {
    Text = "Encontraste la fuente de esa fragancia, o más bien, un deseo y un escalofrío que no podías comprender te cautivaron. Levantaste desesperadamente la cabeza y miraste hacia arriba."
  },
  AvgDialog_120290_Content_54 = {
    Text = "......¡Ah."
  },
  AvgDialog_120290_Content_55 = {
    Text = "Sintiendo algo, ella bajó la mirada, y lo único que podías ver eran un par de ojos muy, muy hermosos."
  },
  AvgDialog_120290_Content_56 = {
    Text = "El ventilador negro se movió lentamente a un lado con una elegancia que quita el aliento."
  },
  AvgDialog_120290_Content_57 = {
    Text = "niebla niebla niebla\nniebla niebla niebla niebla  ella ¿él? ...él...ella...madre...madre madre madre madre madre ojos de ella ojos de él\nniebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla\nella ella ella ella ella ella él él él él él madre madre madre madre madre madre madre madre madre\nojos niebla niebla niebla niebla niebla niebla niebla niebla ojos hermosos niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla\nniebla niebla niebla niebla niebla ella ella ella ella ella ojos hermosos ella ella ella ella ella niebla niebla ojos hermosos ella él él ella niebla niebla niebla\nniebla niebla niebla niebla niebla ella él él él él él niebla niebla niebla ojos hermosos niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla\nmadre madre madre madre madre madre madre hermosa ojos madre madre madre madre madre madre ojos ojos ojos\nojos ojos ojos ojos niebla niebla niebla niebla niebla niebla niebla ojos hermosos de ella ojos de él ella él ella ella él él él él él él ella\nsus ojos ojos ojos ojos de madre ojos hermosos ojos madre ojos de madre ella madre madre madre\nniebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla ojos hermosos ella él él él él él él él él él ojos ojos de ella ella ella\nella él él ella él él él ella ella ella ella él ojos hermosos ella ella ella ella él él ella él él él ella ella ella él él ella ella\nmadre madre madre madre madre madre niebla niebla niebla niebla niebla ojos hermosos niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla\n@4@4@4@1@1@3@3 niebla niebla niebla niebla @1@3\nella él ella él él él ella ojos hermosos ella ella él él ella él él él @3 él él ella @1 él él él ella ella ella\nella @4@3@4@4@4 ojos @2@4\nmadre niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla niebla ojos hermosos niebla niebla niebla niebla niebla niebla niebla ojos hermosos madre madre\nella ella ella ojos hermosos ella ella ella @4 él él él ojos hermosos él él él él él él ojos hermosos"
  },
  AvgDialog_120290_Content_58 = {
    Text = "Gritos, chillidos, aullidos, de repente estallan en tus oídos, ¡mientras capas y capas de personas se agolpan hacia ti!"
  },
  AvgDialog_120290_Content_59 = {
    Text = "¡Lo vi, lo vi, ella me está mirando!"
  },
  AvgDialog_120290_Content_6 = {
    Text = "Tus extremidades están tan blandas que no puedes hacer esfuerzo, la memoria aún no ha regresado, tienes una sed increíble y, de forma instintiva, pronuncias el nombre más familiar."
  },
  AvgDialog_120290_Content_60 = {
    Text = "¡Ella me está mirando!"
  },
  AvgDialog_120290_Content_61 = {
    Text = "<Cambio>¡Demasiado... demasiado hermoso! ¡Qué rostro tan extraordinario, tan bello, tan... excepcional... tan terrorífico!"
  },
  AvgDialog_120290_Content_62 = {
    Text = "¡Señor Xu! ¡Señor Xu... por favor, por favor!"
  },
  AvgDialog_120290_Content_63 = {
    Text = "¡Por favor, mírame!"
  },
  AvgDialog_120290_Content_64 = {
    Text = "<Shake:<Red:¡Aaaahh!!!!>>"
  },
  AvgDialog_120290_Content_65 = {
    Text = "El hombre bien vestido gritó de repente y se lanzó hacia el hombre de traje que estaba entre él y Xu, mientras que este último miraba directamente hacia la posición de Xu, hasta que su globo ocular fue inesperadamente arrancado."
  },
  AvgDialog_120290_Content_66 = {
    Text = "El hombre al que le han arrancado los ojos gritaba de dolor y reía al mismo tiempo, los cristales esféricos colgaban suavemente de las cuencas de sus ojos, se pasó la mano por la cara y, con todas sus fuerzas, extendió la mano hacia la plataforma, con las venas marcadas."
  },
  AvgDialog_120290_Content_67 = {
    Text = "Como si se hubiera dado una señal, en medio de sus risas y gritos, la gente es arrastrada por una ola invisible, formando un torbellino frenético, tratando de tocar el alto escenario."
  },
  AvgDialog_120290_Content_68 = {
    Text = "<Change>Xu!! Xu!!!"
  },
  AvgDialog_120290_Content_69 = {
    Text = "<Change>Xu—¡¡¡¡!!!!"
  },
  AvgDialog_120290_Content_7 = {
    Text = "Una suave voz de canto se acercaba desde lejos, y una figura femenina pasó por la puerta, familiar y cálida. Sentías que la parte inferior de tu cuerpo se debilitaba mientras intentabas levantarte..."
  },
  AvgDialog_120290_Content_70 = {
    Text = "El sonido agudo y penetrante está a punto de romper tus tímpanos. La multitud empuja y empuja, y este cuerpo joven gime bajo la presión, mientras que los rasgos debajo del ventilador se vuelven más claros pero más indistintos."
  },
  AvgDialog_120290_Content_71 = {
    Text = "Finalmente se condensó en una niebla abismal que devoró toda la luz."
  },
  AvgDialog_120290_Content_72 = {
    Text = "Y una risa ligera y extremadamente placentera que atraviesa la niebla."
  },
  AvgDialog_120290_Content_73 = {
    Text = "Estás aquí, mi pequeña jazmín."
  },
  AvgDialog_120290_Content_74 = {
    Text = "Justo antes de ser engullido por la oscuridad y la asfixia, vislumbras a la multitud, igualmente atrapada en el fervor, despojándose de toda dignidad mientras empujan hacia adelante..."
  },
  AvgDialog_120290_Content_75 = {
    Text = "La figura de tu padre, que no ha posado su mirada en ti ni por un instante."
  },
  AvgDialog_120290_Content_8 = {
    Text = "<Shake:¡Chirrido—>"
  },
  AvgDialog_120290_Content_9 = {
    Text = "Oh querido, pobrecito, ¿cómo terminaste en un lugar como este?"
  },
  AvgDialog_120291_Content_1 = {
    Text = "¡Qué sorpresa"
  },
  AvgDialog_120291_Content_10 = {
    Text = "Un trozo de un pastel polvoriento y empalagoso, claramente no refinado, fue metido en tu boca. Cuando el pastel apenas comenzó a disolverse, tu saliva empezó a fluir descontroladamente en tu boca."
  },
  AvgDialog_120291_Content_11 = {
    Text = "Sigues de cerca a la otra persona, masticando el pastel. Justo cuando tu estómago comienza a asentarse, una presión más pesada se aferra a tu corazón."
  },
  AvgDialog_120291_Content_12 = {
    Text = "¡No te quedes ahí, señorita, entra rápido, el Sr. Xu ha estado esperando mucho tiempo."
  },
  AvgDialog_120291_Content_13 = {
    Text = "El padre, como siempre, estaba rodeado de muchas tías cuyas caras no puedes recordar bien. Las tías en el patio van y vienen, algunas gordas, otras delgadas, vibrantes y llenas de vida."
  },
  AvgDialog_120291_Content_14 = {
    Text = "Pero ahora su mirada está extremadamente confundida, fijada en una sola persona."
  },
  AvgDialog_120291_Content_15 = {
    Text = "La dueña de esos ojos maravillosamente bellos y desquiciantes claramente estaba interpretando algún tipo de papel distante pero educado por aburrimiento, hasta que su mirada cayó suavemente sobre ti."
  },
  AvgDialog_120291_Content_16 = {
    Text = "Aunque sabía que descenderías después de la ceremonia, nunca pensé que fueras tan encantador."
  },
  AvgDialog_120291_Content_17 = {
    Text = "¡No debí enviarte a la casa de citas, verdad! Debí mantenerte a mi lado, ya no tiene sentido, ¡nada importa excepto tú!"
  },
  AvgDialog_120291_Content_18 = {
    Text = "Sr. He, por favor, no sea tan formal. Podemos ponernos al día más tarde; he venido hoy para disculparme."
  },
  AvgDialog_120291_Content_19 = {
    Text = "¿Qué sabe una chica tonta? Hoy, prepararé regalos para el burdel de nuevo. Si te gustan, mantenlos cerca y enséñale personalmente cómo cuidarlos?"
  },
  AvgDialog_120291_Content_2 = {Text = "..."},
  AvgDialog_120291_Content_20 = {
    Text = "El Sr. He tiene un comportamiento extraordinario. Si estamos destinados a ello, ciertamente alegrará mi corazón."
  },
  AvgDialog_120291_Content_21 = {
    Text = "Sin embargo, siento una conexión instantánea con esta niña, a pesar de los conflictos anteriores... Si tú y yo queremos acercarnos más, ella también debe estar tranquila."
  },
  AvgDialog_120291_Content_22 = {
    Text = "La mujer conocida como el Sr. Xu se acerca a ti y se agacha suavemente."
  },
  AvgDialog_120291_Content_23 = {
    Text = "Aún no me he presentado, mi nombre es Xu. Entonces, ¿qué piensas, querida joven de la familia He?"
  },
  AvgDialog_120291_Content_24 = {
    Text = "Xu ha llegado ante ti sin que te des cuenta. Instintivamente, aprietas la mano de la mujer que te trajo, queriendo esconderte detrás de ella."
  },
  AvgDialog_120291_Content_25 = {
    Text = "Los dedos de Xu, parecidos a jade, sostienen tu mentón, levantándolo suavemente, y vuelves a ver esos ojos.\nTan similares a los de tu madre, pero tan hermosos que te llenan de miedo."
  },
  AvgDialog_120291_Content_26 = {Text = "I... I..."},
  AvgDialog_120291_Content_27 = {
    Text = "<Shake:¡Todos los que te vieron en la calle se volvieron locos! ¡El tío en traje tenía los ojos arrancados! ¡Tengo miedo!>"
  },
  AvgDialog_120291_Content_28 = {
    Text = "Las palabras infantiles que salieron de tu boca realmente sorprendieron a Xu por un momento, y luego se rió tanto que casi perdió la compostura."
  },
  AvgDialog_120291_Content_29 = {
    Text = "¡Qué coincidencia! Du Langjun, justo a tiempo, ¿podrías ayudarme? Pequeña Jasmine, mira, ¿es este el caballero del que hablamos?"
  },
  AvgDialog_120291_Content_3 = {
    Text = "El shock de estar en el centro de un frenesí desconocido debería haber destruido tu mente, o al menos tu fuerza de voluntad."
  },
  AvgDialog_120291_Content_30 = {
    Text = "Siguiendo su dedo mientras se aleja de tu barbilla, te das cuenta de que detrás de las tías celosas, hay otro hombre que todavía lleva puesto ese traje."
  },
  AvgDialog_120291_Content_31 = {
    Text = "Es él, ¿eh? ¿Por qué siguen ahí sus ojos?"
  },
  AvgDialog_120291_Content_32 = {
    Text = "Su cara ya no está ensangrentada, y sus ojos están donde deberían estar; de hecho, lo reconociste."
  },
  AvgDialog_120291_Content_33 = {
    Text = "Cuando madre aún estaba presente, ustedes y padre iban a banquetes. Padre intentó hablar con él varias veces, pero cada vez fue rechazado y regresó enfadado."
  },
  AvgDialog_120291_Content_34 = {
    Text = "¿Es esta la pequeña que estaba asustada ese día? ¿Realmente vale la pena tu esfuerzo, enviándome tan lejos para comprarle comida."
  },
  AvgDialog_120291_Content_35 = {
    Text = "La familia He ni siquiera puede manejar a su propia hija histérica, y aun así quieren entrometerse en el negocio de importación y exportación de Ciudad Marina. Qué ridículo."
  },
  AvgDialog_120291_Content_36 = {
    Text = "Mi hija ha estado postrada en la cama y de mal humor desde que falleció mi esposa, lo que debe haber divertido al Sr. Du. Me encargaré de ello de inmediato..."
  },
  AvgDialog_120291_Content_37 = {
    Text = "Al ver la expresión oscura de tu padre, te quedaste atónito y paralizado, pero pronto, captaste un aroma de magnolia. Estabas en los brazos de Xu, que te agarraba descuidadamente, pellizcándote y amasándote."
  },
  AvgDialog_120291_Content_38 = {
    Text = "Du Langjun, he dicho que me gusta esta joven de la familia He. Si hablas de ella y te pones serio, no estaré feliz—si no estoy feliz, ¿qué harás?"
  },
  AvgDialog_120291_Content_39 = {
    Text = "El hombre, al escuchar esto, perdió repentinamente el enfoque en su mirada despectiva que te estaba escaneando de arriba a abajo. Luego, giró el brazo y comenzó a golpearse la cara repetidamente."
  },
  AvgDialog_120291_Content_4 = {
    Text = "Pero esta conciencia sigue siendo demasiado pequeña, como una efímera. No, simplifiquémoslo aún más. Un paramecio, o algún otro organismo unicelular. Solo sabes que necesitas estar lleno, mantenerte caliente y buscar beneficios mientras evitas el daño."
  },
  AvgDialog_120291_Content_40 = {
    Text = "Su rostro se hinchó al instante, pero parecía no sentir ni un atisbo de dolor, abriendo la boca de manera insensible para revelar una sonrisa como la de un maniquí que podrías haber visto en una feria occidental."
  },
  AvgDialog_120291_Content_41 = {
    Text = "¡Dije algo mal!"
  },
  AvgDialog_120291_Content_42 = {
    Text = "¡Me equivoqué, me equivoqué!"
  },
  AvgDialog_120291_Content_43 = {
    Text = "Con el sonido de una palmada, Xu sacó alegremente una bolsa de caramelos de su bolsillo, eligió un dulce y te lo metió en la boca."
  },
  AvgDialog_120291_Content_44 = {
    Text = "¡Qué peculiar! ¿A la señorita He le gusta echar un vistazo?"
  },
  AvgDialog_120291_Content_45 = {
    Text = "El dulce néctar se derrite, y tú miras fijamente todo lo que tienes delante. Finalmente, levantas la cabeza para mirar a Xu."
  },
  AvgDialog_120291_Content_46 = {
    Text = "......El dulce de pera del Templo del Dios Ciudad, mamá solía comprármelo."
  },
  AvgDialog_120291_Content_47 = {
    Text = "¡Señor Xu, ¿eres mamá?"
  },
  AvgDialog_120291_Content_48 = {
    Text = "Xu no te respondió, solo sonriendo sin parar, mientras las concubinas y el padre estaban allí como si estuvieran encantados, en silencio y sin moverse."
  },
  AvgDialog_120291_Content_49 = {
    Text = "Du Langjun, mírate a ti mismo. Solo estoy haciendo un pequeño berrinche. Me golpeaste tan fuerte que me duele el corazón."
  },
  AvgDialog_120291_Content_5 = {
    Text = "Así que solo eres abrazado una vez más por esa jaula de niebla, abriendo los ojos ileso."
  },
  AvgDialog_120291_Content_50 = {
    Text = "Tan pronto como el hombre se detuvo, las concubinas parecieron despertar, mirándolo con asombro y confusión, mientras observaban al Sr. Du, cuyas mejillas habían adquirido un tono azul púrpura."
  },
  AvgDialog_120291_Content_51 = {
    Text = "Recuerdo que el Sr. He tenía algo que discutir con el joven Du, así que me tomé la libertad de traer este regalo de visita."
  },
  AvgDialog_120291_Content_52 = {
    Text = "Joven dama de la familia He, cuando discuten asuntos, ¿estarías dispuesta a llevarme a dar un paseo?"
  },
  AvgDialog_120291_Content_53 = {
    Text = "Antes de salir de la habitación, no pudiste evitar mirar a tu padre. Su rostro no mostraba la expresión vacía y extraña del Sr. Du y las tías, sino que él silenciosamente toleraba todo."
  },
  AvgDialog_120291_Content_54 = {
    Text = "¡Señor Xu, tú...!"
  },
  AvgDialog_120291_Content_55 = {
    Text = "Tienes muchas preguntas que hacer, ¿verdad?"
  },
  AvgDialog_120291_Content_56 = {
    Text = "No te apures... buen bebé, buen bebé."
  },
  AvgDialog_120291_Content_57 = {
    Text = "Mi pequeña jazmín... ven, mírame."
  },
  AvgDialog_120291_Content_58 = {
    Text = "La oscura noche presiona hacia abajo, y bajo la luna plateada de color hueso, Xu mueve el abanico, mientras la niebla brumosa se abalanza sobre ti, envolviéndote y consumiéndote."
  },
  AvgDialog_120291_Content_59 = {
    Text = "Vagamente, madre te mira en la cálida luz, sonriendo suavemente mientras se agacha con los brazos abiertos."
  },
  AvgDialog_120291_Content_6 = {
    Text = "El cielo se ha oscurecido por completo, y las ventanas de otras habitaciones reflejan la tenue luz de las velas distantes, mientras pasos débiles y dispersos se acercan una vez más."
  },
  AvgDialog_120291_Content_60 = {
    Text = "Como si una cuerda se rompiera de repente, te duele la nariz, las lágrimas nublan completamente tu visión, y sin dudarlo, la abrazas con fuerza."
  },
  AvgDialog_120291_Content_61 = {
    Text = "Mamá, ¿puedes por favor no irte otra vez."
  },
  AvgDialog_120291_Content_62 = {
    Text = "Uu uu, uu uu uu uu, mi mente está tan confundida, tengo tanto miedo. ¡Te extraño tanto! Mamá."
  },
  AvgDialog_120291_Content_63 = {
    Text = "La mujer te envuelve suavemente, acariciando suavemente tu espalda."
  },
  AvgDialog_120291_Content_64 = {
    Text = "La niña de mamá, la buena niña de mamá."
  },
  AvgDialog_120291_Content_65 = {
    Text = "mi buen bebé, mi querido bebé."
  },
  AvgDialog_120291_Content_66 = {
    Text = "¿Qué estarías dispuesto a sacrificar para estar con mamá para siempre?"
  },
  AvgDialog_120291_Content_67 = {
    Text = "La niebla parece envolverte de nuevo, y escuchas el sonido de tu propio murmullo."
  },
  AvgDialog_120291_Content_68 = {
    Text = "Todo vale... Cualquier cosa está bien."
  },
  AvgDialog_120291_Content_69 = {
    Text = "¿Está disponible toda la casa?"
  },
  AvgDialog_120291_Content_7 = {
    Text = "¡Ay, señorita, me asustaste hasta la muerte! ¿Sales corriendo a la calle en un ataque, estás tratando de matarnos a los comunes."
  },
  AvgDialog_120291_Content_70 = {
    Text = "No quiero la casa, solo quiero a mamá."
  },
  AvgDialog_120291_Content_71 = {
    Text = "¿Se puede hacer toda la casa, toda la ciudad de Haicheng y tu padre?"
  },
  AvgDialog_120291_Content_72 = {
    Text = "Padre... papá..."
  },
  AvgDialog_120291_Content_73 = {
    Text = "Te desconectaste por un momento, recordando de repente cada noche, cuando tu madre te esperaba con ansias, y la mano que descansaba en tu cabeza cuando tu padre llegaba a casa."
  },
  AvgDialog_120291_Content_74 = {
    Text = "No importa, aún hay mucho tiempo, pequeña jazmín."
  },
  AvgDialog_120291_Content_75 = {
    Text = "Parece que alguien te levanta, cayendo en un suave colchón, donde algo aún más cálido y húmedo te abraza íntimamente."
  },
  AvgDialog_120291_Content_76 = {
    Text = "Ya es muy tarde, duerme. Estaré a tu lado muy pronto, muy pronto."
  },
  AvgDialog_120291_Content_77 = {
    Text = "Después de que tu madre se fue, por primera vez experimentaste una sensación de alivio sin igual, junto con la somnolencia que vino después, hundiéndote en un sueño profundo y dulce."
  },
  AvgDialog_120291_Content_8 = {
    Text = "<Shake:¡Grrr—>"
  },
  AvgDialog_120291_Content_9 = {
    Text = "...Suspirando, realmente siento pena por ti, date prisa y mastica. El maestro ya está esperando en el vestíbulo, no me causes más problemas, ¿entendido?"
  },
  AvgDialog_120296_Content_1 = {Text = "Querida"},
  AvgDialog_120296_Content_10 = {
    Text = "Está bien, guarda tus pequeños pensamientos. No digas que te asusto; esta mansión no es segura. Todas las mujeres que le gustaron al lord han desaparecido al final."
  },
  AvgDialog_120296_Content_11 = {
    Text = "Incluso su exesposa de la infancia, que se decía que había fallecido a causa de una enfermedad, ¿quién sabe que fue..."
  },
  AvgDialog_120296_Content_12 = {
    Text = "¡Ay! ¡¿Qué me estás haciendo?!"
  },
  AvgDialog_120296_Content_13 = {
    Text = "Señora, de verdad... de verdad lo siento. Mi hermana tiende a hablar sin pensar, por favor, no le preste atención a sus tonterías. No queremos ofenderla en absoluto, se lo ruego, por favor, no se lo diga al maestro."
  },
  AvgDialog_120296_Content_14 = {
    Text = "Retirada abruptamente por su hermana, la concubina de cejas finamente delineadas y maquillaje exquisito volvió en sí, su rostro se tornó pálido de miedo mientras se tapaba la boca apresuradamente para silenciarse."
  },
  AvgDialog_120296_Content_15 = {
    Text = "Dado que esta casa no es segura, ¿por qué no pensaron en encontrar otro lugar?"
  },
  AvgDialog_120296_Content_16 = {
    Text = "......¿A dónde más podríamos ir? Si pudiéramos ser apreciados como joyas por la nobleza, entonces podríamos ir a cualquier lugar."
  },
  AvgDialog_120296_Content_17 = {
    Text = "Jeje, ¿sosteniéndolo como una joya preciosa?"
  },
  AvgDialog_120296_Content_18 = {
    Text = "Xu de repente estalló en risa, y en ese momento, varias concubinas en el corredor oyeron un tipo de risa susurrante más elusiva."
  },
  AvgDialog_120296_Content_19 = {
    Text = "Sus miradas se volvieron desenfocadas, levantando sus rostros con desconcierto, mirando a la mujer que se adentraba más en el corredor."
  },
  AvgDialog_120296_Content_2 = {
    Text = "La nueva chica, tiene algunos trucos, ¿eh."
  },
  AvgDialog_120296_Content_20 = {
    Text = "Mi pequeña jazmín está durmiendo, no la molestes, sígueme."
  },
  AvgDialog_120296_Content_21 = {
    Text = "Te haré saber, noble, que una persona valiosa, al igual que un objeto precioso, solo es interesante cuando se sostiene delicadamente entre los dedos."
  },
  AvgDialog_120296_Content_22 = {
    Text = "Las concubinas llevaban una sonrisa tonta en sus rostros, y luego la niebla cubrió sus labios, mientras que los abanicos ocultaban sus caras."
  },
  AvgDialog_120296_Content_23 = {
    Text = "La fragancia dulce y fuerte de magnolia se esparció suavemente por la mansión."
  },
  AvgDialog_120296_Content_24 = {Text = "..."},
  AvgDialog_120296_Content_25 = {
    Text = "Después de que Xu fue llevada a la residencia de He como madrastra, nunca volviste a pasar hambre. Todos te trataron con calidez y amabilidad, como si aún fueras aquella joven de cuando tu madre estaba presente."
  },
  AvgDialog_120296_Content_26 = {
    Text = "Pero padre nunca volvió a salir de su habitación, y Xu nunca había estado dentro; en cambio, las concubinas parecían ser atraídas por hilos invisibles, yendo y viniendo con frecuencia de la cámara de Xu."
  },
  AvgDialog_120296_Content_27 = {
    Text = "Oh, querida señorita, ¿podrías ayudarme, por favor? El maestro indicó específicamente que nadie debe acercarse a su habitación."
  },
  AvgDialog_120296_Content_28 = {
    Text = "No he visto a papá desde hace tanto tiempo, yo... solo echaré un vistazo desde la distancia, prometo que no lo molestaré."
  },
  AvgDialog_120296_Content_29 = {
    Text = "Sin embargo, antes de que pudieras acercarte, escuchaste un gruñido ronco, frenético y anormalmente excitado desde dentro de la habitación."
  },
  AvgDialog_120296_Content_3 = {
    Text = "Tú sabes que tienes una lengua afilada, ¿y el abanico que te regaló no lo adoras?"
  },
  AvgDialog_120296_Content_30 = {
    Text = "Xu... mi querida, mi salvadora, mi corazón, no puedo dejarte ir más, eres mía, solo puedes ser mía."
  },
  AvgDialog_120296_Content_31 = {
    Text = "Su sangre y huesos no son nada... No importa cuánto, ¡ah! Mientras pueda traerte, mientras pueda traerte, ¡todo vale la pena!"
  },
  AvgDialog_120296_Content_32 = {
    Text = "¡Lo entiendo, lo vi! ¡Ja, jajajajaja!"
  },
  AvgDialog_120296_Content_33 = {
    Text = "El sonido resbaladizo y contorsionado parecía deslizarse por el suelo, hasta que al final, el suspiro de ¿de dónde? se convirtió en un corto y agudo jadeo como un fuelle sofocado, como si algo lo estuviera envolviendo, dificultando la respiración."
  },
  AvgDialog_120296_Content_34 = {Text = "¡Papá!"},
  AvgDialog_120296_Content_35 = {
    Text = "Te sobresaltaste por su voz parecida a la muerte y corriste a empujar la puerta."
  },
  AvgDialog_120296_Content_36 = {
    Text = "Dentro, solo estaba He Fang, apoyándose frenéticamente contra el borde de la cama, colapsando sobre la oscura ropa de cama, que estaba húmeda como si hubiera sido empapada, junto con toda la cabina."
  },
  AvgDialog_120296_Content_37 = {
    Text = "Fragmentos destrozados de objetos y telas yacían horriblemente esparcidos por todos lados. Volvió a la realidad, su rostro cubierto de un anormal tono enfermo de sangre, y levantó un cojín de madera para estrellarlo contra ti."
  },
  AvgDialog_120296_Content_38 = {
    Text = "¡Quién te dejó entrar!"
  },
  AvgDialog_120296_Content_39 = {
    Text = "¡Nadie puede perturbar nuestra soledad, sal de aquí! ¡Vete!"
  },
  AvgDialog_120296_Content_4 = {
    Text = "Ge Mei es hermosa, tiene buen gusto y sus regalos son impresionantes. ¿No te sientes también a un lado y luego al otro, deseando poder ser como ella, con un abanico en la cara."
  },
  AvgDialog_120296_Content_40 = {
    Text = "La mujer te siguió de cerca y, rápidamente, cerró la puerta en medio del rugido de ¿De dónde?."
  },
  AvgDialog_120296_Content_41 = {
    Text = "Te dije que no molestes a mi señor, se enojará. No corras por ahí, mi tía pequeña."
  },
  AvgDialog_120296_Content_42 = {
    Text = "Padre... ¿qué está pasando? ¿Por qué sigue llamando al Sr. Xu?"
  },
  AvgDialog_120296_Content_43 = {
    Text = "<Shake:¡El Sr. Xu claramente salió temprano esta mañana. ¿Con quién está hablando? Su expresión es tan aterradora...>"
  },
  AvgDialog_120296_Content_44 = {
    Text = "Los asuntos del amo, no son de nuestra incumbencia, sirvientes como nosotros."
  },
  AvgDialog_120296_Content_45 = {
    Text = "Corres tambaleándote hacia el lugar que mejor conoces, con la esperanza de encontrar a alguien que te ayude."
  },
  AvgDialog_120296_Content_46 = {
    Text = "La cámara de la señora, ahora la cámara de Xu, es también la cámara donde mi madre una vez estuvo."
  },
  AvgDialog_120296_Content_47 = {
    Text = "La puerta, que ha ido desvaneciéndose desde que madre se fue, ahora está nuevamente adornada con tallas doradas, como si se hubiera convertido en una especie de entrada, cada apertura y cierre liberando un aroma somnoliento y extraño."
  },
  AvgDialog_120296_Content_48 = {
    Text = "¡Haha, je je... Uu, uu uu uu... Resulta que estuve equivocado todo el tiempo, ¡totalmente equivocado!"
  },
  AvgDialog_120296_Content_49 = {
    Text = "¡Corta, aplasta, ábrelo! ¡Solo ábrelo, todavía está humeante, ofrecido a Él, y obedecerán! ¡Alá ya no tendrá que sufrir más en el mar del sufrimiento!"
  },
  AvgDialog_120296_Content_5 = {
    Text = "¿Se está hablando de mí?"
  },
  AvgDialog_120296_Content_50 = {
    Text = "<Change>Xu... ¡nuestro Salvador, nuestro @3!"
  },
  AvgDialog_120296_Content_51 = {
    Text = "La niebla intangible llenó toda la habitación mientras ellas levantaban reverentemente los abanicos que les habían dado el día que Xu entró en la casa, llorando y riendo, convirtiéndose gradualmente en un extraño lamento."
  },
  AvgDialog_120296_Content_52 = {
    Text = "No puedes entender una palabra de lo que dicen las sirvientas en la habitación; tus oídos están llenos de zumbidos y el latido de tu corazón. Tropiezas hacia atrás nuevamente, golpeándote accidentalmente contra la barandilla y haciendo ruido."
  },
  AvgDialog_120296_Content_53 = {
    Text = "......sí, hay un sonido."
  },
  AvgDialog_120296_Content_54 = {
    Text = "<Shake:<Red:¿Es otra ofrenda de sangre que se puede presentar?>>"
  },
  AvgDialog_120296_Content_55 = {
    Text = "Sus voces terminan con una risa ligera, y todos los llantos han desaparecido, una inexplicable y escalofriante sensación de frío te invade!"
  },
  AvgDialog_120296_Content_56 = {Text = "¡Huir!!!!"},
  AvgDialog_120296_Content_57 = {
    Text = "¡Ese es el terror de ser acechado por un depredador, el miedo que yace en lo más profundo de la sangre de todas las criaturas desde tiempos inmemoriales!"
  },
  AvgDialog_120296_Content_58 = {
    Text = "¡Ah! ¿Una simple caja de galletas mariposa y mi pequeña jazmín viene corriendo a mis brazos con tanta alegría?"
  },
  AvgDialog_120296_Content_59 = {
    Text = "Los brazos similares a la jadeíta sostuvieron tu impulso de casi caer. Si miras a través de los espacios en la cerca del patio, el renombrado Inspector Huang de Ciudad Marina está cerrando la puerta del coche para ella."
  },
  AvgDialog_120296_Content_6 = {
    Text = "*Exclaim ¡Ah! Lo siento, señora!"
  },
  AvgDialog_120296_Content_60 = {
    Text = "Se te entrega la caja de bocadillos, y los patrones en forma de ojo en el papel floral te asustan por completo. Tomas una respiración profunda, reúnes tu valor y la vuelcas al suelo."
  },
  AvgDialog_120296_Content_61 = {
    Text = "¿Quién eres realmente?! ¿Por qué estás en nuestra casa?! ¿Qué le pasó a mi familia, a mi papá, a mi tía, a esos tíos? Desde que llegaste, todos han estado actuando de manera extraña..."
  },
  AvgDialog_120296_Content_62 = {
    Text = "Ay... solo es una pequeña cosa, mira, mi pequeña jazmín incluso está llorando."
  },
  AvgDialog_120296_Content_63 = {
    Text = "Ella no se enojó por el bocadillo que derribaste; en cambio, se agachó con cariño y tocó el rincón de tu ojo donde las lágrimas habían salido por el miedo."
  },
  AvgDialog_120296_Content_64 = {
    Text = "Pequeña jazmín, ¿es realmente este tu hogar, un lugar donde ni siquiera hay una gota de agua antes de que yo llegara?"
  },
  AvgDialog_120296_Content_65 = {
    Text = "¡Señorita! Solo un momento de no vigilar, ¿cómo pudo...? Señora, lo siento, todo es mi culpa por no cuidar a la señorita."
  },
  AvgDialog_120296_Content_66 = {
    Text = "Xu ignoró a las personas que se acercaban y te abrazó más fuerte, como siempre, acariciando tu espalda como si acariciara a un pequeño animal, su voz suave y tierna."
  },
  AvgDialog_120296_Content_67 = {
    Text = "Pequeña jazmín, piénsalo bien. ¿Qué está pasando con este asunto y qué hay sobre ese asunto? ¿Cuál es la conexión entre ellos?"
  },
  AvgDialog_120296_Content_68 = {
    Text = "Solo si te portas bien y obedientemente escuchas mis palabras."
  },
  AvgDialog_120296_Content_69 = {
    Text = "Todo puede ser tuyo, y todos pueden convertirse en tu juguete."
  },
  AvgDialog_120296_Content_7 = {
    Text = "Tch, ¿qué dama ni qué dama? Solo una mujer de cabello largo que salió de una librería, ¿de qué tiene miedo? ¿Realmente puede comerte."
  },
  AvgDialog_120296_Content_70 = {
    Text = "Ella acaricia desde tu espalda hasta tu cabello, y después de jugar lo suficiente con tu pelo, te suelta, irradiando una sensación de alegría."
  },
  AvgDialog_120296_Content_71 = {
    Text = "Está bien, lleva a mi pequeña jazmín a dormir... necesita descansar."
  },
  AvgDialog_120296_Content_72 = {
    Text = "Has caminado mucho en la niebla, y en la bruma gris, ves una vasta área de agua oscura."
  },
  AvgDialog_120296_Content_73 = {
    Text = "Incontables miembros viscosos y retorcidos cubiertos de ventosas descansan en el límite entre el agua y la niebla, mientras una figura suave se sienta de espaldas a ti junto a la orilla."
  },
  AvgDialog_120296_Content_74 = {
    Text = "¿Mamá? ¿Eres tú?"
  },
  AvgDialog_120296_Content_75 = {
    Text = "<Shake:...Incorrecto... todo... corre...>"
  },
  AvgDialog_120296_Content_76 = {
    Text = "Mamá, ¿qué estás diciendo? No te escucho claramente."
  },
  AvgDialog_120296_Content_77 = {
    Text = "Te acercaste más y de repente te diste cuenta de que no estaba sentada junto al agua; en cambio, su parte inferior se había transformado en innumerables tentáculos, fusionándose con el agua gris."
  },
  AvgDialog_120296_Content_78 = {
    Text = "<Shake:Incorrecto, todo incorrecto.>"
  },
  AvgDialog_120296_Content_79 = {
    Text = "<Shake:Ella no es... Él no es...>"
  },
  AvgDialog_120296_Content_8 = {
    Text = "Míralos a ustedes, parecen unos gatos peludos, es realmente adorable."
  },
  AvgDialog_120296_Content_80 = {
    Text = "La mujer se dio la vuelta, su rostro familiar surcado por lágrimas grises, gritando y vociferando hacia ti."
  },
  AvgDialog_120296_Content_81 = {
    Text = "<Red:¡Ella tiene la cara de su madre!>"
  },
  AvgDialog_120296_Content_82 = {
    Text = "<Change>¡Él no es! ¡Él no es! ¡Él no es! ¡Él no es!"
  },
  AvgDialog_120296_Content_83 = {
    Text = "<Red:<Shake:¡Incorrecto! ¡Todo incorrecto! ¡Niña! ¡Corre! ¡Corre rápido!>>"
  },
  AvgDialog_120296_Content_9 = {
    Text = "No te preocupes, solo soy nueva aquí. Vi que están charlando animadamente y pensé en acercarme para compartir un pequeño susurro."
  },
  AvgDialog_120297_Content_1 = {
    Text = "El sonido de la flecha"
  },
  AvgDialog_120297_Content_10 = {
    Text = "A veces eran ellos mismos, y a veces eran sus esposas. En esos momentos, la sonrisa en el rostro de Xu se acentuaba. Cuando venían por segunda vez, los mismos abanicos negros que los de las concubinas en el patio aparecían en sus manos."
  },
  AvgDialog_120297_Content_100 = {
    Text = "Pero el feroz He Fang, que hace un momento parecía una figura aterradora, realmente ha suavizado su expresión."
  },
  AvgDialog_120297_Content_101 = {
    Text = "¿Realmente piensas así...?"
  },
  AvgDialog_120297_Content_102 = {
    Text = "He Lang también sabe que, aunque poseo poder divino, estoy conectada a quien me despierta. Cualquier cosa que He Lang me pida hacer, solo puedo hacerlo; ¿hay alguna posibilidad de engañarte?"
  },
  AvgDialog_120297_Content_103 = {
    Text = "Al igual que en el callejón, no puedes hablar ni moverte. Parece que esta extraña \"diosa\" está decidida a convertirte en un espectador de esta farsa."
  },
  AvgDialog_120297_Content_104 = {
    Text = "Él se alejó alegremente, justo como aquel día frente a la Torre de Oro, sin siquiera mirarte de nuevo."
  },
  AvgDialog_120297_Content_105 = {
    Text = "En el momento en que puedes emitir un sonido, te giras y te lanzas sobre Xu, soltando un aullido bestial. Pies, puños, dientes—aunque sabes que es inútil, utilizas cada método de ataque que conoces."
  },
  AvgDialog_120297_Content_106 = {
    Text = "¡Devuélvemelo, devuélveme a mamá, devuélveme a papá!"
  },
  AvgDialog_120297_Content_107 = {
    Text = "Xu Zhi Shan se queda quieta, permitiéndote desahogarte sin moverse. La sonrisa en sus ojos te hace olvidar tu miedo, dejando solo ira y colapso."
  },
  AvgDialog_120297_Content_108 = {
    Text = "¡Todo es por tu culpa; no eres una diosa, eres un monstruo!"
  },
  AvgDialog_120297_Content_109 = {
    Text = "La mujer que está delante de mí... asintió."
  },
  AvgDialog_120297_Content_11 = {
    Text = "Si seguimos esperando, ni siquiera veremos la sombra del Sr. Xu. Apúrate."
  },
  AvgDialog_120297_Content_110 = {
    Text = "Así es, pequeña jazmín, soy un monstruo."
  },
  AvgDialog_120297_Content_111 = {
    Text = "Pero la muerte de tu madre no tiene nada que ver conmigo; fue ¿De dónde quien mató a innumerables mujeres, incluida ella, solo para convocar a mi ser a cambio de su riqueza y poder."
  },
  AvgDialog_120297_Content_112 = {
    Text = "Justo ahora, él quería matarte. No quieres morir, y yo respondí a ti. Si te abandonara, sin duda morirías, ¿verdad?"
  },
  AvgDialog_120297_Content_113 = {Text = "..."},
  AvgDialog_120297_Content_114 = {
    Text = "Te quedaste sin palabras, su voz llena de interés, y sus hermosos ojos brillaban de alegría."
  },
  AvgDialog_120297_Content_115 = {
    Text = "Ahora, mi pequeña jazmín, ¿cómo vas a elegir?"
  },
  AvgDialog_120297_Content_116 = {
    Text = "Abriste la boca en vano, al final solo la mirabas aturdido, el agudo tintineo en tus oídos alterando tus nervios. Ella simplemente te dio una palmadita en la espalda antes de caminar hacia el patio."
  },
  AvgDialog_120297_Content_117 = {
    Text = "Jeje... Pronto, muy pronto, pequeña jazmín, llegará el momento de que tomes tu decisión."
  },
  AvgDialog_120297_Content_118 = {Text = "..."},
  AvgDialog_120297_Content_119 = {
    Text = "Las escenas del día se reproducen en tus sueños. Te despiertas gritando en medio de la noche, y la casa está extrañamente silenciosa. Nadie te responde, y esa voz penetrante ya no existe."
  },
  AvgDialog_120297_Content_12 = {
    Text = "El rickshaw se sacudía violentamente, aunque no fue descubierto, tras dar vueltas y más vueltas, finalmente se perdió de vista cuando el carro giró hacia un bosque."
  },
  AvgDialog_120297_Content_120 = {
    Text = "El hambre roe tus entrañas, y después de acurrucarte durante mucho tiempo, finalmente te levantas y, guiado por la memoria, encuentras la caja de pasteles destrozados. En silencio, te quedas bajo la luz de la luna y te lo comes todo."
  },
  AvgDialog_120297_Content_121 = {
    Text = "Al volver a quedarte dormido, regresaste al borde del agua gris, donde tu madre extendía sus brazos en forma de tentáculos, alcanzándote. Detrás de ella, se podía ver vagamente otra masa enorme."
  },
  AvgDialog_120297_Content_122 = {
    Text = "¿Mamá, ella todavía está aquí?"
  },
  AvgDialog_120297_Content_123 = {
    Text = "Mamá siempre estará contigo."
  },
  AvgDialog_120297_Content_124 = {
    Text = "Siempre estaré, siempre, al lado de mi pequeña jazmín."
  },
  AvgDialog_120297_Content_125 = {
    Text = "Dos voces sonaron al mismo tiempo en tus oídos, y no preguntaste más. Estabas demasiado cansado y demasiado asustado."
  },
  AvgDialog_120297_Content_126 = {
    Text = "Te lanzas sin dudar, en ese abrazo aterrador, pegajoso pero increíblemente suave."
  },
  AvgDialog_120297_Content_13 = {
    Text = "Te llevaron lejos, y por alguna razón, tu corazón latía cada vez más rápido. Lo único que te hacía sentir un poco mejor era aferrarte fuertemente a la mano de la mujer."
  },
  AvgDialog_120297_Content_14 = {
    Text = "El cielo se oscureció poco a poco, y la luna subió sin que nadie se diera cuenta sobre las copas de los árboles.\nDe repente, la mujer te hizo un gesto de silencio."
  },
  AvgDialog_120297_Content_15 = {Text = "Shh—"},
  AvgDialog_120297_Content_16 = {
    Text = "A lo lejos, apareció la figura de Xu, la carroza blanca acelerando, mientras el Sr. Du permanecía en silencio a su lado. En la esquina, varias sombras largas pasaron entre los árboles y se proyectaron sobre el suelo por la luz de la luna."
  },
  AvgDialog_120297_Content_17 = {
    Text = "Señor Du, el inspector Huang, el jefe de la Escuela del Norte de Transporte Fluvial, y en la carretera principal, oh Dios, el señor Xu es realmente extraordinario..."
  },
  AvgDialog_120297_Content_18 = {
    Text = "A lo lejos, los rostros de los hombres aparecieron con un rubor anormal, muy parecido al del padre aquel día. Comenzó con murmullos suaves, que después se intensificaron en gritos susurrantes, rápidos y emocionados, casi como un canto."
  },
  AvgDialog_120297_Content_19 = {
    Text = "<Shake:Ella... no puede quedarse...>"
  },
  AvgDialog_120297_Content_2 = {
    Text = "Todas las concubinas se están volviendo cada vez más como Xu, y padre no ha salido de la puerta de nuevo."
  },
  AvgDialog_120297_Content_20 = {
    Text = "<Shake:Matar... solo así...>"
  },
  AvgDialog_120297_Content_21 = {
    Text = "<Shake:Matar... Matar... MATA!! ¡Corta—en pedazos—!!!>"
  },
  AvgDialog_120297_Content_22 = {
    Text = "<Cambiar>¡Mía, mía, mía, mía, mía, mía, ella es mía!!"
  },
  AvgDialog_120297_Content_23 = {
    Text = "La luz pálida te hiere los ojos, y solo entonces te das cuenta de que detrás de cada hombre se esconde una guadaña, ahora levantada en alto de manera ordenada——"
  },
  AvgDialog_120297_Content_24 = {
    Text = "¡Ja—ja, jajajajaja, jajajajaja!"
  },
  AvgDialog_120297_Content_25 = {
    Text = "Los hombres se fueron acercando poco a poco, y Xu, que estaba rodeado en el medio, de repente estalló en risa, como si hubiera visto la cosa más ridícula del mundo, señalando sus rostros uno por uno con su dedo."
  },
  AvgDialog_120297_Content_26 = {
    Text = "En el siguiente segundo, afiladas guadañas cayeron desde todas direcciones, el sonido sordo de la carne siendo desgarrada, el crujido de los huesos siendo cortados, y un brazo tan blanco como el jade fue lanzado hacia arriba."
  },
  AvgDialog_120297_Content_27 = {
    Text = "¡Cric, crac."
  },
  AvgDialog_120297_Content_28 = {
    Text = "Mmm, mmmmmm!"
  },
  AvgDialog_120297_Content_29 = {
    Text = "Estás fuertemente abrazado, las manos de la mujer cubriendo firmemente tu boca, ahogando los gritos de convulsión que amenazan con escapar."
  },
  AvgDialog_120297_Content_3 = {
    Text = "La madre ya no aparece en tus sueños, a veces sueñas con el rostro de Xu bajo cada ventilador, y a veces sueñas con tu padre siendo devorado por un monstruo, despertando al final empapado en sudor frío."
  },
  AvgDialog_120297_Content_30 = {
    Text = "<Change>Cabeza, cuello, pecho, brazos, abdomen..."
  },
  AvgDialog_120297_Content_31 = {
    Text = "<Shake:Perfora desde el cráneo, perfora desde el cuello, perfora desde la cavidad torácica, perfora desde los brazos, perfora desde el abdomen...>"
  },
  AvgDialog_120297_Content_32 = {
    Text = "<Change>Perfora el cráneo, perfora el cuello, perfora la cavidad torácica, perfora..."
  },
  AvgDialog_120297_Content_33 = {Text = "¡Señor."},
  AvgDialog_120297_Content_34 = {
    Text = "Suave, coqueta y dulce."
  },
  AvgDialog_120297_Content_35 = {
    Text = "Tan lejos, como una niebla, se enreda en el contorno de tu oído y entra en tu mente."
  },
  AvgDialog_120297_Content_36 = {
    Text = "La niebla de sangre se profundizó gradualmente sin que se supiera cuándo, y uno a uno, Xu emergió de los cadáveres, con los brazos tan blancos como el jade fluyendo con lodo negro, levantados en alto."
  },
  AvgDialog_120297_Content_37 = {
    Text = "Duele tanto, por favor, dame un beso——"
  },
  AvgDialog_120297_Content_38 = {
    Text = "<Cambio>¡Yo @3, dame un beso...!"
  },
  AvgDialog_120297_Content_39 = {
    Text = "<Cambio>¡Yo @3, me doy @4!"
  },
  AvgDialog_120297_Content_4 = {
    Text = "Señorita, por favor deja de hacer berrinches, el Sr. Xu es tan bueno contigo, trayéndote tantos alimentos frescos y juguetes todos los días."
  },
  AvgDialog_120297_Content_40 = {
    Text = "<Cambio>¡Duele tanto, por favor, dame un beso!"
  },
  AvgDialog_120297_Content_41 = {
    Text = "Xu... un monstruo que se asemeja a Xu, sus cuerpos inferiores fusionados en cadáveres destrozados, con barro cubriendo toda su cara, solo se ve el contorno de sus labios."
  },
  AvgDialog_120297_Content_42 = {
    Text = "En cada cara de \"Xu\", se abrieron docenas de labios carnosos, hermosos y en forma de pétalos, chupando a los hombres que reían locamente como si estuvieran bajo un hechizo."
  },
  AvgDialog_120297_Content_43 = {
    Text = "<Cambio>¡Clang——Clang——"
  },
  AvgDialog_120297_Content_44 = {
    Text = "El sonido de cráneos siendo aplastados, el sonido de cráneos rompiéndose."
  },
  AvgDialog_120297_Content_45 = {
    Text = "<Cambio>¡Slurp—— Glug——"
  },
  AvgDialog_120297_Content_46 = {
    Text = "Sonidos de succión, sonidos de masticación."
  },
  AvgDialog_120297_Content_47 = {
    Text = "Observaste impotente cómo sus cabezas estallaban y luego volvían a estar perfectas. Los \"Xu\" soltaron suspiros de satisfacción y se agruparon entre murmullos de satisfacción."
  },
  AvgDialog_120297_Content_48 = {
    Text = "Señor Du, el inspector Huang, el jefe de la Escuela del Norte de Transporte Fluvial..."
  },
  AvgDialog_120297_Content_49 = {
    Text = "Se levantaron en silencio, como si nada hubiera sucedido, dispersándose aturdidos, mientras Xu ya había desaparecido sin dejar rastro."
  },
  AvgDialog_120297_Content_5 = {
    Text = "La mujer suspiró y usó un pañuelo para ayudarte a limpiar el sudor sorprendido."
  },
  AvgDialog_120297_Content_50 = {
    Text = "Esa mano finalmente te soltó, y en la asfixiante quietud, tus lágrimas caen incontrolablemente. En el momento en que te diste la vuelta, tus pupilas temblaron violentamente."
  },
  AvgDialog_120297_Content_51 = {Text = "¡Ay!"},
  AvgDialog_120297_Content_52 = {
    Text = "He estado pensando en cómo ser honesta con mi pequeña jazmín—ser sinceros."
  },
  AvgDialog_120297_Content_53 = {
    Text = "Tus pupilas se contraen al máximo, y al final, solo queda la mujer frente a ti. En un instante, tu cerebro ya abrumado envía una descarga de dolor intenso."
  },
  AvgDialog_120297_Content_54 = {
    Text = "¿Cómo es ella, la mujer de la voz aguda."
  },
  AvgDialog_120297_Content_55 = {
    Text = "Los sirvientes en tu habitación fueron despedidos hace mucho tiempo cuando tu madre falleció."
  },
  AvgDialog_120297_Content_56 = {
    Text = "A nadie le importó nunca tu vida o tu muerte, y nunca viste realmente cómo era ella, pero ¿por qué todos encuentran su aparición tan natural?"
  },
  AvgDialog_120297_Content_57 = {
    Text = "Me gusta esa piel, me gusta el aroma a jazmín que lleva, desde el principio me he estado preguntando... ¿cómo será su pequeño jazmín, mi pequeño jazmín?"
  },
  AvgDialog_120297_Content_58 = {
    Text = "Así que, no pude resistir venir a ver a mi pequeña jazmín desde muy, muy temprano."
  },
  AvgDialog_120297_Content_59 = {
    Text = "Huyes por el camino. Ella no detiene tu movimiento, solo te observa con una sonrisa desde detrás de la puerta, como si estuviera mirando a un pequeño gato salvaje asustado que está huyendo."
  },
  AvgDialog_120297_Content_6 = {
    Text = "Señorita, si realmente tienes tanto miedo, tengo una idea."
  },
  AvgDialog_120297_Content_60 = {
    Text = "¡Papá! ¡Xu es un monstruo, ella..."
  },
  AvgDialog_120297_Content_61 = {
    Text = "No puedes recordar cuánto tiempo has estado corriendo ni cuántos caminos equivocados has tomado. En la mirada atónita del portero, corres hacia la habitación de tu padre, casi rompiendo la puerta al abrirla, y agarras ansiosamente el dobladillo de la ropa de tu padre."
  },
  AvgDialog_120297_Content_62 = {
    Text = "Pero tan pronto como el nombre de Xu sale de tu boca, recibes una fuerte bofetada."
  },
  AvgDialog_120297_Content_63 = {
    Text = "Te dije que necesitas llamarla<Red:\"Madre\">."
  },
  AvgDialog_120297_Content_64 = {
    Text = "El rostro de padre estaba inusualmente alerta y sombrío, el frenesí de los últimos días había desaparecido por completo. Agarró la parte de atrás de tu cuello y te apartó de su lado."
  },
  AvgDialog_120297_Content_65 = {
    Text = "No, papá, ella se ha convertido en alguien cercano a mí. Está interactuando con muchas personas e incluso les ha traído—"
  },
  AvgDialog_120297_Content_66 = {Text = "¡Basta!"},
  AvgDialog_120297_Content_67 = {
    Text = "En ese momento, era Xu quien te quería, por eso te mantuve en casa, pero resultaste ser tan ingrato como tu madre de corta vida."
  },
  AvgDialog_120297_Content_68 = {
    Text = "¡Estás hecho un desastre, diciendo tonterías y hablando irrespetuosamente a tu madre! Ve al pasillo y arrodíllate como castigo, ¡y no te levantes hasta antes de la hora de la gallo!"
  },
  AvgDialog_120297_Content_69 = {
    Text = "¡Ella no es mi madre, es un monstruo que devora hombres!"
  },
  AvgDialog_120297_Content_7 = {
    Text = "Tienes tanto miedo del Sr. Xu, ¿por qué no lo sigues y ves qué hace todos los días? Si realmente es un monstruo, iremos juntos a hablar con el anciano y lo echaremos de casa, ¿de acuerdo?"
  },
  AvgDialog_120297_Content_70 = {
    Text = "Gritaste con todas tus fuerzas, y la habitación cayó en un momento de silencio. Luego, escuchaste..."
  },
  AvgDialog_120297_Content_71 = {
    Text = "<Red:La risa fría de padre.>"
  },
  AvgDialog_120297_Content_72 = {
    Text = "<Shake:\"¿Un yokai?\">"
  },
  AvgDialog_120297_Content_73 = {
    Text = "Xu, soy yo quien seleccionó uno a uno los sacrificios personalmente, los abrí uno a uno con mis propias manos, pagando innumerables precios y agotando todos mis esfuerzos, ¡que finalmente convocé <Red:\"Diosa\">!"
  },
  AvgDialog_120297_Content_74 = {
    Text = "He intentado tantas veces, sin embargo, esas personas superficiales y ordinarias no merecen su atención. ¿Crees que mi corazón no duele? También me duele ver a tu madre."
  },
  AvgDialog_120297_Content_75 = {
    Text = "Como un trueno, te resulta difícil comprender el significado de las palabras de tu padre, mientras tu conciencia es completamente dominada por el agudo sonido."
  },
  AvgDialog_120297_Content_76 = {
    Text = "<Shake:Debes sentirte honrado; su carne constituye la forma terrenal de la Doncella Divina.>"
  },
  AvgDialog_120297_Content_77 = {
    Text = "La voz del padre emana una escalofriante frialdad, y te das cuenta con un escalofrío que se ha colocado sombríamente entre tú y la puerta, avanzando hacia ti paso a paso."
  },
  AvgDialog_120297_Content_78 = {
    Text = "Como ya sabes todo, no puedes quedarte en esta casa, y nunca te dejaré salir y hablar demasiado."
  },
  AvgDialog_120297_Content_79 = {
    Text = "Tu grito aún no ha salido, y tu garganta ya está agarrada por tu padre, cuyo rostro está lleno de locura, mientras tu campo de visión se tiñe rápidamente de rojo sangre."
  },
  AvgDialog_120297_Content_8 = {
    Text = "¿Echar al Señor Xu?"
  },
  AvgDialog_120297_Content_80 = {
    Text = "La <Red:Diosa> ha descendido, de ahora en adelante, ella me <Red:pertenecerá para siempre>. La fama y la fortuna ya no significan nada para mí. ¡Mientras tenga a la <Red:Diosa> a mi lado, cada sacrificio vale la pena!"
  },
  AvgDialog_120297_Content_81 = {
    Text = "<Shake:Mamá, ¡ayúdame...!>"
  },
  AvgDialog_120297_Content_82 = {
    Text = "No... quiero morir, quiero vivir, Mamá..."
  },
  AvgDialog_120297_Content_83 = {
    Text = "<Cambiar><Shake:¡No quiero morir, me duele tanto, me duele tanto, me duele tanto! Mamá, ¡sálvame, sálvame @4!>"
  },
  AvgDialog_120297_Content_84 = {
    Text = "¡Cualquiera, por favor sálvame...!"
  },
  AvgDialog_120297_Content_85 = {
    Text = "Nadie responde a tus oraciones silenciosas."
  },
  AvgDialog_120297_Content_86 = {
    Text = "Caos. Asfixia. Dolor. Tranquilidad... El familiar, olor a pescado y dulce, de magnolia blanca."
  },
  AvgDialog_120297_Content_87 = {
    Text = "<Red:<Shake:¡Chirrido——>>"
  },
  AvgDialog_120297_Content_88 = {
    Text = "En un estado de aturdimiento, un tentáculo negro irrumpió por la puerta, balanceándose con inmensa fuerza y arrojándolo directamente sobre la cama."
  },
  AvgDialog_120297_Content_89 = {
    Text = "He Lang, ¿cómo puedes competir con un niño."
  },
  AvgDialog_120297_Content_9 = {
    Text = "Delante de la puerta principal se oía el sonido de las bocinas de los coches, y cada día, diferentes rostros esperaban frente a la mansión de la familia He, todos ellos figuras prominentes con las que el propietario de esta finca había querido asociarse en algún momento."
  },
  AvgDialog_120297_Content_90 = {
    Text = "Un abrazo suave te atrapó, el aire volvió a entrar en tus pulmones casi desinflados, Xu levantó su abanico de cola, y ¿de dónde fuiste sostenido invisiblemente."
  },
  AvgDialog_120297_Content_91 = {
    Text = "Solo vio algo que no debía, no quiero que lo recuerde, así que, naturalmente, no lo hará."
  },
  AvgDialog_120297_Content_92 = {
    Text = "Su tono es tan alegre y discreto como siempre, incluso la presión de su mano descansando sobre tu cabeza."
  },
  AvgDialog_120297_Content_93 = {
    Text = "Fuera de la puerta, se escucha la voz de un sirviente informando."
  },
  AvgDialog_120297_Content_94 = {
    Text = "Señor, hay varios caballeros esperándolo en el vestíbulo."
  },
  AvgDialog_120297_Content_95 = {
    Text = "El rostro de He Fang cambió drásticamente, luciendo incluso peor que cuando estaba a punto de matarte hace un momento."
  },
  AvgDialog_120297_Content_96 = {
    Text = "Querida, ¿por qué has empezado de nuevo? He dicho que los objetos ajenos ya no tienen significado para mí; solo tú, solo tú debes ser mía."
  },
  AvgDialog_120297_Content_97 = {
    Text = "Desde que fui despertada por ti, He Lang, los demás son meras sombras pasajeras. Sin embargo, aún recuerdo la gran empresa que estás planeando y estoy dispuesta a contribuir con mis modestos esfuerzos."
  },
  AvgDialog_120297_Content_98 = {
    Text = "Solo hago esto porque quiero tener más apoyo mientras estoy contigo, He Lang, en este mundo."
  },
  AvgDialog_120297_Content_99 = {
    Text = "No había ni rastro de sinceridad en los ojos de Xu, algo que incluso tú, como niño, podías ver. No mencionemos que acaba de echar sin piedad a la misma persona a la que le mostró tanta ternura."
  },
  AvgDialog_120298_Content_1 = {Text = "No sueño"},
  AvgDialog_120298_Content_10 = {
    Text = "Cuando hablo con ellos, tu aroma sigue taladrando mis fosas nasales, ¡y solo pensar en que te acerques a otros hombres me vuelve absolutamente loco!"
  },
  AvgDialog_120298_Content_11 = {
    Text = "Te dije, solo necesito que estés a mi lado. ¿Por qué no eres solo mío? ¿Por qué sigues coqueteando con otros hombres!"
  },
  AvgDialog_120298_Content_12 = {
    Text = "Nunca has visto una expresión de desconcierto tan evidente en el rostro de Xu; parece estar buscando una forma de escapar, su mirada se desplaza de un lado a otro de manera descontrolada, aterrizando sorprendentemente en ti, que estás escondido detrás de la ventana y no has sido notado por nadie."
  },
  AvgDialog_120298_Content_13 = {
    Text = "Instintivamente te escondiste bajo el alféizar de la ventana, notando la mirada de Xu. Miraste hacia atrás y luego tus ojos volvieron a ella."
  },
  AvgDialog_120298_Content_14 = {
    Text = "¿Sigues pensando en cómo correr? Déjalo, soy tu <Red:Despertador>, tu poder está conectado a mí, y tu poder divino no tiene efecto sobre mí."
  },
  AvgDialog_120298_Content_15 = {
    Text = "<Red:<Shake:Ahora lo entiendo completamente. Mientras te mate, solo matándote... podemos estar juntos para siempre.>>"
  },
  AvgDialog_120298_Content_16 = {
    Text = "Contienes la respiración y te das la vuelta, luego, corres apresuradamente hacia una habitación tras otra, tratando de encontrar a alguien que pueda detener a ¿De dónde."
  },
  AvgDialog_120298_Content_17 = {
    Text = "No, no, no. La vasta residencia He está vacía, ni siquiera hay un portero a la vista."
  },
  AvgDialog_120298_Content_18 = {
    Text = "Incluso la puerta del patio ha sido cerrada con un pesado candado, y una niebla gris sin fondo se extiende afuera."
  },
  AvgDialog_120298_Content_19 = {
    Text = "Si esto sigue así, el Señor Xu terminará como Mamá..."
  },
  AvgDialog_120298_Content_2 = {
    Text = "Al día siguiente, antes del amanecer, se escuchó un grito de histeria en el patio."
  },
  AvgDialog_120298_Content_20 = {
    Text = "<Shake:Deberías esconderte, esconderte hasta que todo haya terminado.>"
  },
  AvgDialog_120298_Content_21 = {
    Text = "Pero no tienes a dónde ir, encontraste esa cosa, escondiste las manos detrás de la espalda y volviste a caminar hacia la antigua habitación de Mamá."
  },
  AvgDialog_120298_Content_22 = {
    Text = "<Red:<Shake:Señora, querida, solo puedes ser mía.>>"
  },
  AvgDialog_120298_Content_23 = {
    Text = "En el momento en que la brillante guadaña fue levantada, intercambiaste miradas con Xu; sus ojos de repente se iluminaron, brillando con un tono de súplica."
  },
  AvgDialog_120298_Content_24 = {
    Text = "Pero luego, sacudió imperceptiblemente la cabeza——"
  },
  AvgDialog_120298_Content_25 = {
    Text = "<Red:¡Corre rápido!>"
  },
  AvgDialog_120298_Content_26 = {
    Text = "Esos hermosos ojos se han cerrado, y su maestro está listo para el sacrificio."
  },
  AvgDialog_120298_Content_27 = {Text = "..."},
  AvgDialog_120298_Content_28 = {Text = "¡¡ARGH!!"},
  AvgDialog_120298_Content_29 = {
    Text = "¡Tú, monstruo, te atreves!"
  },
  AvgDialog_120298_Content_3 = {
    Text = "Su rugido es distorsionado, venenoso y lleno de malicia. No tienes tiempo para pensar; un enorme temor te impulsa a correr hacia la fuente del sonido."
  },
  AvgDialog_120298_Content_30 = {
    Text = "La guadaña resonó al caer al suelo, y He Fang, con una expresión de dolor en su rostro, se agarró la parte baja de la espalda donde un pequeño cuchillo que encontraste estaba profundamente incrustado en su cuerpo."
  },
  AvgDialog_120298_Content_31 = {
    Text = "En un ataque de furia, ¿De dónde se dio la vuelta y te alcanzó. De repente, escuchaste una serie de risitas, no solo una, mientras la fuente de los sonidos se agolpaba densamente hacia el compartimento."
  },
  AvgDialog_120298_Content_32 = {
    Text = "En medio de las risas disimuladas, estalló una risa incontrolable. Xu, detrás de He Fang, se rió tanto que se dobló, con lágrimas fluyendo por su rostro."
  },
  AvgDialog_120298_Content_33 = {
    Text = "¡Ajáajá, ajáajáajáajáajá! Pequeña jazmín, mi más, más, más querida pequeña jazmín. ¡Realmente no me decepcionaste, eres tan interesante como imaginaba!"
  },
  AvgDialog_120298_Content_34 = {
    Text = "Las mujeres en qipaos amarillos y negros entraron en fila, sus abanicos plegables ocultando sus narices y labios. Cada una de ellas tenía un par de ojos muy, muy hermosos."
  },
  AvgDialog_120298_Content_35 = {
    Text = "¿De dónde viene el miedo absoluto? Antes de que su grito resonara, ya había aparecido un abrazo frío y suave que te envolvió."
  },
  AvgDialog_120298_Content_36 = {
    Text = "<Red:Cosa asquerosa. No ensucies los ojos de mi pequeña jazmín.>"
  },
  AvgDialog_120298_Content_37 = {
    Text = "<Shake:Señor...>"
  },
  AvgDialog_120298_Content_38 = {
    Text = "<Shake:Señor...>"
  },
  AvgDialog_120298_Content_39 = {
    Text = "¿Qué están haciendo, están locos?! ¡Salgan, todos, salgan."
  },
  AvgDialog_120298_Content_4 = {
    Text = "Xu fue acorralado contra la esquina de la cama por He Fang, con los ojos inyectados en sangre y el cabello desordenado, como si no hubiera dormido en toda la noche."
  },
  AvgDialog_120298_Content_40 = {
    Text = "Las tías frente a mí movieron lentamente las superficies de los abanicos, revelando el mismo rostro debajo de cada uno."
  },
  AvgDialog_120298_Content_41 = {
    Text = "¿Por qué el señor nos convirtió en sacrificios?"
  },
  AvgDialog_120298_Content_42 = {
    Text = "¿Por qué el señor nos cortó las extremidades?"
  },
  AvgDialog_120298_Content_43 = {
    Text = "Incontables Xus son ajenos a los temblorosos gritos de ira de ¿De dónde?, riendo y rodeándolo en el medio, los abanicos negros y las guadañas se alternan formando un círculo a su alrededor."
  },
  AvgDialog_120298_Content_44 = {
    Text = "<Cambio>¿Ahora somos lo suficientemente hermosos?"
  },
  AvgDialog_120298_Content_45 = {
    Text = "<Cambio>¿Podemos quedarnos juntos con mi señor para siempre?"
  },
  AvgDialog_120298_Content_46 = {
    Text = "Una enorme sombra se elevó desde la espalda de Xu, uno, dos, tres... innumerables bocas con dientes de dragón emergieron de la piel hinchada, goteando saliva, ansiosas por elegir y devorar,"
  },
  AvgDialog_120298_Content_47 = {
    Text = "Los tentáculos en forma de plumas se extienden por todo el patio de la familia He, cubriendo toda la luz y silenciando todo ruido."
  },
  AvgDialog_120298_Content_48 = {
    Text = "Tu visión está envuelta en niebla, y solo sientes la extraña fragancia que emana de Xu y los sonidos inquietantes, lentos y saciantes de la alimentación."
  },
  AvgDialog_120298_Content_49 = {Text = "..."},
  AvgDialog_120298_Content_5 = {
    Text = "Mi estúpida hija no dijo nada malo... Puedo olerlo."
  },
  AvgDialog_120298_Content_50 = {
    Text = "Después de que el continuo sonido de succión se detuvo, He Fang se levantó en silencio y salió, quedándose entre un grupo de hombres que también esperaban en silencio."
  },
  AvgDialog_120298_Content_51 = {
    Text = "Inspectores, presidentes, presidentas... Sus esposas están al lado de los hombres, la luz del sol naciente te deslumbra, y ves en sus caras la misma sonrisa misteriosa que la de Xu."
  },
  AvgDialog_120298_Content_52 = {Text = "..."},
  AvgDialog_120298_Content_53 = {
    Text = "¿De dónde dices que tu poder está conectado a él? Ahora que se ha vuelto así, ¿desaparecerás?"
  },
  AvgDialog_120298_Content_54 = {
    Text = "Lo que más quiere preguntar la pequeña jazmín es esto, realmente... me emociona tanto."
  },
  AvgDialog_120298_Content_55 = {
    Text = "Sus dedos rozan tu entrecejo, finalmente descansando en la punta de tu nariz."
  },
  AvgDialog_120298_Content_56 = {
    Text = "Quizás sí, quizás... no, pero, ¿quieres ser mi maestro?"
  },
  AvgDialog_120298_Content_57 = {
    Text = "Xu agarró suavemente en el aire, sacando un pañuelo de seda tan delgado como el ala de una chicharra. Mojando el pincel plateado en tinta, se desplegó ante ti."
  },
  AvgDialog_120298_Content_58 = {
    Text = "Te daré todo lo que no se ha obtenido, así como lo mejor del mundo."
  },
  AvgDialog_120298_Content_59 = {
    Text = "Cuando mi madre estaba viva, Ciudad Marina fue arrasada por una nueva tendencia, y tú habías leído libros y practicado la escritura."
  },
  AvgDialog_120298_Content_6 = {
    Text = "<Shake:<Red:Esos hombres...>>"
  },
  AvgDialog_120298_Content_60 = {
    Text = "Xu tomó tu mano, esperando a que empezaras a escribir, y tú... ¿cómo te llamabas otra vez?"
  },
  AvgDialog_120298_Content_61 = {
    Text = "El espejo de cobre salpicado de líquido rojo fresco refleja los delicados y juveniles rasgos de una persona del Lejano Oriente, que se asemejan a un grupo de jazmines pálidos y frágiles."
  },
  AvgDialog_120298_Content_62 = {
    Text = "Parpadeaste confundido, y la pequeña niña en el reflejo también parpadeó.\nRecordaste, la tela de seda mostraba tu escritura infantil, y tu nombre era—"
  },
  AvgDialog_120298_Content_63 = {Text = "He Fang."},
  AvgDialog_120298_Content_64 = {Text = "..."},
  AvgDialog_120298_Content_65 = {
    Text = "¿Así que la líder de esa sociedad secreta que luego apareció en Ciudad Marina es una niña de aproximadamente el mismo tamaño que Jenkin?!"
  },
  AvgDialog_120298_Content_66 = {
    Text = "Tu cabeza duele intensamente debido a los efectos posteriores del sueño, y te sorprende la mujer que aparece silenciosamente después de que te despiertas."
  },
  AvgDialog_120298_Content_67 = {
    Text = "El dormitorio de Misaq realmente debería implementar algunas medidas de seguridad. Con eso en mente, comienzas a pensar en qué podría protegerte de esta mujer que ni siquiera perdona a los niños."
  },
  AvgDialog_120298_Content_68 = {
    Text = "......Según los registros, en las leyendas del Lejano Oriente, hay una antigua deidad maligna, a la que la gente llama <Red:\"Mil puertas de la diosa Xuan\">, a ella le gusta manipular los corazones de los hombres y se alimenta de la materia cerebral de aquellos que albergan deseos hacia ella."
  },
  AvgDialog_120298_Content_69 = {
    Text = "Aunque solo puedas ver sus ojos, es evidente que la mujer frente a ti sonríe felizmente, apoyando perezosamente su barbilla en su mano, y te preguntas si su mirada podría hacer que incluso un trapeador parezca cariñoso."
  },
  AvgDialog_120298_Content_7 = {
    Text = "¿Creías que podías engañarme? No olvides, soy yo quien te convocó personalmente con el <Red:\"cadáver\"> de mi esposa; ¿cómo podría confundir ese aroma?"
  },
  AvgDialog_120298_Content_70 = {
    Text = "Su comprensión de mí es realmente abrumadora."
  },
  AvgDialog_120298_Content_71 = {
    Text = "Ese hombre tonto consiguió un antiguo pergamino, queriendo convocar a esta para que realizara hechizos de confusión, matando a innumerables personas, y al final, ni siquiera su esposa legítima, que lo amaba con todo su corazón, fue perdonada."
  },
  AvgDialog_120298_Content_72 = {
    Text = "Originalmente, solo era que el odio de su esposa me resultaba divertido, queriendo dejar que ella probara a su enemigo."
  },
  AvgDialog_120298_Content_73 = {
    Text = "Pero en ese momento, Ciudad Marina estaba impregnada del abrumador hedor a podredumbre y malicia, lo que realmente me hacía... reacia a irme."
  },
  AvgDialog_120298_Content_74 = {
    Text = "......En realidad no necesitas un enlazador, ¿verdad?"
  },
  AvgDialog_120298_Content_75 = {
    Text = "He leído los «registros de almacenamiento de plata», eres completamente capaz de completar la Ceremonia de Despertar por tu cuenta, mantener tu cordura es pan comido para ti."
  },
  AvgDialog_120298_Content_76 = {
    Text = "¿Cuál es tu propósito al vincularte activamente con He Fang en Ciudad Marina?"
  },
  AvgDialog_120298_Content_77 = {
    Text = "Xu no dijo nada, un hilo de niebla te envolvía, llevándose el dolor de cabeza como un hilo, ella te guiñó un ojo desde detrás de la pantalla."
  },
  AvgDialog_120298_Content_78 = {
    Text = "Originalmente pensé que en este mundo no había diferencia entre adultos y adultos, pero cada niño es diferente de otro."
  },
  AvgDialog_120298_Content_79 = {
    Text = "La nutro con niebla y la riego con poder y deseo. La amo, ¿entonces por qué todavía viene a castigarme?"
  },
  AvgDialog_120298_Content_8 = {
    Text = "Si no fuera por tu intimidad con ellos, ¿por qué emitirían un aroma que pertenece a <Red:tu aroma>?"
  },
  AvgDialog_120298_Content_80 = {
    Text = "¡No es amor"
  },
  AvgDialog_120298_Content_81 = {Text = "..."},
  AvgDialog_120298_Content_82 = {
    Text = "Jeje, realmente no entiendo qué es el amor humano. Ofreceré los mejores regalos de este mundo: comida, juguetes y el poder de llamar a un ciervo un caballo."
  },
  AvgDialog_120298_Content_83 = {
    Text = "Y, por supuesto... también recibiré la recompensa que deseo, cuando llegue el día que necesitas, pequeña jazmín, ¿cómo elegirás?"
  },
  AvgDialog_120298_Content_84 = {
    Text = "Mi sin sueño, siempre, siempre estoy dispuesta a esperar tu llegada."
  },
  AvgDialog_120298_Content_85 = {
    Text = "Suavemente, entre las risitas coquetas y juguetonas, la niebla se extendió—en el siguiente momento, solo quedó el aroma de magnolia blanca en el dormitorio."
  },
  AvgDialog_120298_Content_9 = {
    Text = "De repente, se rió nerviosamente, inclinándose hacia adelante y agarrando la muñeca de Xu que sostenía el abanico."
  },
  AvgDialog_120313_Content_1 = {
    Text = "Mientras tanto\nmás allá del sol negro"
  },
  AvgDialog_120313_Content_10 = {
    Text = "Fuera de un mundo de miles de millones de parpadeos como estrellas, esa figura lucha por atravesar las turbulencias, acercándose a ti paso a paso."
  },
  AvgDialog_120313_Content_11 = {
    Text = "¡Ramona!!!"
  },
  AvgDialog_120313_Content_12 = {
    Text = "Ves claramente su silueta, su rostro, sus ojos que brillan de alegría, ya no es una ilusión falsa, ya no solo hay una voz ahogada."
  },
  AvgDialog_120313_Content_13 = {
    Text = "Las ondas de energía conectadas del túnel aullaban, levantando tus cabellos, finalmente, sus dedos se tocaron y se abrazaron fuertemente."
  },
  AvgDialog_120313_Content_14 = {
    Text = "El anhelo de otro mundo se convierte en un halo blanco, fluyendo a través de tu alma."
  },
  AvgDialog_120313_Content_15 = {
    Text = "<Shake:<color=#DEDEDE>Finalmente... te encontré.</color>>"
  },
  AvgDialog_120313_Content_16 = {
    Text = "Tus cuellos se tocan, sus manos te abrazan con ternura, su voz tiembla de alegría y llanto."
  },
  AvgDialog_120313_Content_17 = {
    Text = "Toda la fatiga, soledad y dolor se disipan en este momento, sabes, tu alma ha regresado a su verdadero lugar de descanso."
  },
  AvgDialog_120313_Content_18 = {
    Text = "Viajar entre dimensiones es muy peligroso, ¿estás herido?"
  },
  AvgDialog_120313_Content_19 = {
    Text = "Recuerdas algo, revisando repetidamente el alma que ha caminado tanto tiempo frente a ti, solo para ver su figura algo delgada. Ramona negó con la cabeza y acarició tu rostro suavemente."
  },
  AvgDialog_120313_Content_2 = {
    Text = "Llegada, destrucción, renacimiento... resistencia, batalla, firmeza..."
  },
  AvgDialog_120313_Content_20 = {
    Text = "¿Y tú? Has estado solo en un mundo extraño tanto tiempo; debe haber sido difícil para ti."
  },
  AvgDialog_120313_Content_21 = {
    Text = "Te ardió la punta de la nariz, también sacudiste la cabeza, y en el intercambio de miradas, en las lágrimas que pendían sin caer de tus ojos, ambos sonrieron al mismo tiempo."
  },
  AvgDialog_120313_Content_22 = {
    Text = "¿De qué te ríes, como un tonto."
  },
  AvgDialog_120313_Content_23 = {
    Text = "¿Tú también no te estás riendo...?"
  },
  AvgDialog_120313_Content_24 = {
    Text = "En una inmensa felicidad, no pudiste evitar tomar su mano, deseando inmediatamente emprender el camino de regreso."
  },
  AvgDialog_120313_Content_25 = {Text = "¡!!!"},
  AvgDialog_120313_Content_26 = {
    Text = "De repente, viste cómo sus pupilas se contraen bruscamente y en un instante, se lanzó hacia ti, empujándote con fuerza hacia un lado."
  },
  AvgDialog_120313_Content_27 = {
    Text = "En el momento en que eres expulsado hacia atrás, ves que en el lugar que originalmente estaba detrás de ti, en una nueva fisura dimensional, otro ojo se está abriendo, mirando a Ramona que permanece en su lugar."
  },
  AvgDialog_120313_Content_28 = {
    Text = "En un instante, la viscosa sustancia negra la devoró."
  },
  AvgDialog_120313_Content_29 = {
    Text = "<Shake:<Big:¡No!!!>>"
  },
  AvgDialog_120313_Content_3 = {
    Text = "Bajo la intimidación de la voluntad suprema, todo es tan familiar."
  },
  AvgDialog_120313_Content_4 = {
    Text = "Los enormes ojos pálidos en la dimensión alternativa se desvanecen uno tras otro, tu mente también está llegando gradualmente a su agotamiento, lo único que te sostiene es la rosa roja que tienes en la mano."
  },
  AvgDialog_120313_Content_5 = {
    Text = "Hoo... No puedo caer, todavía me están esperando..."
  },
  AvgDialog_120313_Content_6 = {
    Text = "En un estado de ensueño, tu corazón de repente comienza a latir con fuerza, y sigues esa corazonada para girarte."
  },
  AvgDialog_120313_Content_7 = {
    Text = "Como si una estrella fugaz pasara, y también como si se cristalizara el hielo, un túnel en forma de haz de luz se extendía acompañado de un sonido extraño y etéreo."
  },
  AvgDialog_120313_Content_8 = {
    Text = "Una voz que ha resonado en la memoria miles de veces atraviesa el distante espacio de la dimensión detrás de ti y, bajo la conexión de los tentáculos de tu mente, resuena en tu cabeza."
  },
  AvgDialog_120313_Content_9 = {
    Text = "<Yellow:%player%>!!!"
  },
  AvgDialog_121232_Content_1 = {
    Text = "El esplendor de la patria ya parpadea ante mis ojos, señor Goliath, ahora se lo dejo a usted..."
  },
  AvgDialog_121232_Content_2 = {
    Text = "El poder divino que viene a raudales... es bastante similar al de esa mujer loca."
  },
  AvgDialog_121232_Content_3 = {
    Text = "¡Muy bien, pequeño de allí, prepárate para presenciar el poder de los filisteos que supera la bendición!"
  },
  AvgDialog_121369_Content_1 = {
    Text = "En el vacío del salón, solo resuenan los pasos de tú y Murphy."
  },
  AvgDialog_121369_Content_10 = {
    Text = "Sin tiempo para averiguar la situación, los tentáculos fríos se enrollaron alrededor de tus pantorrillas, la fuerza te presionó hacia abajo para arrodillarte."
  },
  AvgDialog_121369_Content_11 = {
    Text = "Intentas resistir, pero la toxina paralizante se infiltra en tus nervios, dejándote sin fuerzas."
  },
  AvgDialog_121369_Content_12 = {
    Text = "¡Murphy, ¿qué estás haciendo?!"
  },
  AvgDialog_121369_Content_13 = {
    Text = "No sé por qué, simplemente me siento muy enojado."
  },
  AvgDialog_121369_Content_14 = {
    Text = "Hay fuego ardiendo en mi corazón, y verte lo hace arder aún más."
  },
  AvgDialog_121369_Content_15 = {
    Text = "(calma un poco, calma un poco. No se pueden hacer cosas que dañen la autoridad de la Madre divina.)"
  },
  AvgDialog_121369_Content_16 = {
    Text = "Entonces... ¿qué se supone que debo hacer arrodillado aquí?"
  },
  AvgDialog_121369_Content_17 = {
    Text = "¡Arrodíllate sin preguntar!"
  },
  AvgDialog_121369_Content_18 = {
    Text = "El tono de Murphy suena aún lleno de ira, y un tentáculo de pulpo golpea ansiosamente tus piernas. Parece que solo puedes depender de ti mismo."
  },
  AvgDialog_121369_Content_19 = {
    Text = "Te esfuerzas por resistir la fuerza de la toxina paralizante y levantas la cabeza, tocando su mejilla enrojecida."
  },
  AvgDialog_121369_Content_2 = {
    Text = "Desde hace un momento, no has querido decir nada."
  },
  AvgDialog_121369_Content_20 = {
    Text = "Murphy, ¿tú... estás siendo interferido por la fuerza del Río Sagrado?"
  },
  AvgDialog_121369_Content_21 = {
    Text = "¡Descarado! ¡Yo, siendo la Madre de los dioses, cómo podría ser influenciada por algo tan estúpido...!"
  },
  AvgDialog_121369_Content_22 = {
    Text = "Los tentáculos del anillo azul se arrastran por tu columna vertebral, dejando una sensación de hormigueo a su paso."
  },
  AvgDialog_121369_Content_23 = {
    Text = "Antes del amanecer, debes quedarte aquí correctamente."
  },
  AvgDialog_121369_Content_24 = {
    Text = "¡No te muevas!"
  },
  AvgDialog_121369_Content_25 = {
    Text = "Pero sientes que las ataduras de tus tentáculos se han relajado un poco, como si una nube te estuviera sosteniendo, pero cuando intentas liberarte, no te permite mover ni un centímetro."
  },
  AvgDialog_121369_Content_26 = {
    Text = "Sé agradecido, ganarás el honor de dar la bienvenida al amanecer con la Madre Diosa."
  },
  AvgDialog_121369_Content_27 = {
    Text = "Como recompensa..."
  },
  AvgDialog_121369_Content_28 = {
    Text = "Su respiración perdura en tu oído. Luego, un suave y delicado beso aterriza en tu frente."
  },
  AvgDialog_121369_Content_29 = {
    Text = "También recibirás la gracia de la Madre divina."
  },
  AvgDialog_121369_Content_3 = {
    Text = "¿Qué pasó, Murphy?"
  },
  AvgDialog_121369_Content_4 = {
    Text = "Murphy no respondió, solo caminó directamente hacia la cima de las escaleras, donde estaba el trono."
  },
  AvgDialog_121369_Content_5 = {
    Text = "Tú la sigues paso a paso, hasta que finalmente se sienta de lado en el trono, con una mirada de ligera molestia que te atraviesa."
  },
  AvgDialog_121369_Content_6 = {
    Text = "¿Quién te permitió estar a mi lado? Pónte más bajo, no me mires por encima del hombro."
  },
  AvgDialog_121369_Content_7 = {
    Text = "No entiendes qué está pasando, pero aun así retrocedes dos pasos, alineando tu mirada con la chica en el trono."
  },
  AvgDialog_121369_Content_8 = {
    Text = "Arrodíllate."
  },
  AvgDialog_121369_Content_9 = {Text = "¿Ja?"},
  AvgDialog_121741_Content_1 = {
    Text = "Enorme, podre, vacío... manteniendo la ilusión \"sobre el velo\" con fantasías absurdas..."
  },
  AvgDialog_121741_Content_2 = {
    Text = "¡Qué tonto y ridículo soy al estar sumido en el \"Paraíso\"..."
  },
  AvgDialog_121741_Content_3 = {
    Text = "%player%, ayúdame a terminar por completo este sueño."
  },
  AvgDialog_121741_Content_4 = {
    Text = "Ayúdame a recuperar... mi destino."
  },
  AvgDialog_121742_Content_1 = {
    Text = "Las cadenas temblaban, el monstruo detrás del velo miraba alrededor de todo el barco, emitiendo un lamento desesperado."
  },
  AvgDialog_121742_Content_10 = {
    Text = "Adiós, frágil e incapaz\"ayer\"...!"
  },
  AvgDialog_121742_Content_2 = {
    Text = "Entiendo... entiendo todo... tu apego, lo que no puedes soportar dejar ir..."
  },
  AvgDialog_121742_Content_3 = {
    Text = "Pero ya he tomado conciencia."
  },
  AvgDialog_121742_Content_4 = {
    Text = "Murphy miró hacia Él, y tras un momento, como si hubiera tomado una decisión, te mostró una sonrisa suave."
  },
  AvgDialog_121742_Content_5 = {
    Text = "Por favor, mírenlo... ese corazón en mi pecho..."
  },
  AvgDialog_121742_Content_6 = {
    Text = "Hasta el día de hoy, sigue vibrando con la misma vitalidad."
  },
  AvgDialog_121742_Content_7 = {
    Text = "Como durante el ritual de navegación, Murphy abrió su pecho."
  },
  AvgDialog_121742_Content_8 = {
    Text = "Para salir de aquí, para el día en que nos volvamos a ver en Misaq."
  },
  AvgDialog_121742_Content_9 = {
    Text = "La sangre espiritual fluía del pecho de Murphy, hilos plateados se entrelazaban, aferrándose con fuerza a rasgar el velo sobre el firmamento."
  },
  AvgDialog_121743_Content_1 = {
    Text = "No sabes cuánto tiempo has estado luchando, solo sientes que tu cerebro comienza a girar y tus brazos se vuelven pesados, mientras el pálido y delgado monstruo gigante balancea implacablemente sus brazos rotos pero renacidos."
  },
  AvgDialog_121743_Content_10 = {
    Text = "La promesa de William parecía una barrera invisible que se acumulaba detrás, la confianza forjada a lo largo de los años permitió que una fuerza casi agotada surgiera desde lo más profundo de la médula."
  },
  AvgDialog_121743_Content_11 = {
    Text = "Está acordado, regresaremos juntos."
  },
  AvgDialog_121743_Content_12 = {
    Text = "Que la Llave de plata ilumine mi camino."
  },
  AvgDialog_121743_Content_13 = {
    Text = "Que la Llave de Plata nos guíe"
  },
  AvgDialog_121743_Content_2 = {
    Text = "El sudor resbala de tu frente, nublando tu visión, y ni siquiera puedes levantar la mano para limpiarlo."
  },
  AvgDialog_121743_Content_3 = {
    Text = "Maldita sea..."
  },
  AvgDialog_121743_Content_4 = {
    Text = "%player%, aguanta."
  },
  AvgDialog_121743_Content_5 = {
    Text = "Una capa negro-roja ondea frente a ti, mientras un brazo mecánico preciso te protege de los ataques de los pálidos esqueletos que se acercan."
  },
  AvgDialog_121743_Content_6 = {
    Text = "Los miembros alargados vuelven a golpear con furia, pero son detenidos una vez más, los fragmentos caen a su lado, levantando una nube de humo."
  },
  AvgDialog_121743_Content_7 = {Text = "¿William?"},
  AvgDialog_121743_Content_8 = {
    Text = "Concéntrate, míralo. \n Déjame tu espalda."
  },
  AvgDialog_121743_Content_9 = {
    Text = "En el nuevo mundo... asumiré temporalmente la tarea de tu compañero. \n Hasta el día en que regresemos juntos a Misaq."
  },
  AvgDialog_121744_Content_1 = {
    Text = "El monstruo ruge y llora, la cortina oculta se rasga, su cuerpo emerge desde las profundidades del Aequor."
  },
  AvgDialog_121744_Content_10 = {
    Text = "No entender cómo usar bien la fuerza y confiar el destino a otros no es el estilo de un filisteo."
  },
  AvgDialog_121744_Content_11 = {
    Text = "El gigante agita su arma, apuntando la punta de la gran hoja hacia la enorme masa de carne que está cambiando."
  },
  AvgDialog_121744_Content_12 = {
    Text = "¡Así que deja de decir tonterías y prepárate para la batalla!"
  },
  AvgDialog_121744_Content_13 = {
    Text = "Solo el ganador está calificado para sobrevivir."
  },
  AvgDialog_121744_Content_2 = {
    Text = "¡Maldición...! ¡Él sigue expandiéndose!"
  },
  AvgDialog_121744_Content_3 = {
    Text = "Un rayo atravesó el oscuro cielo nocturno, y la sed de sangre de la gran espada, acompañada por un veloz relámpago púrpura y negro, cortó con fuerza los débiles brazos de la cortina pálida."
  },
  AvgDialog_121744_Content_4 = {
    Text = "...¿Miryam? ¿Goliat? ¿Por qué están aquí?"
  },
  AvgDialog_121744_Content_5 = {
    Text = "La decisión de la Madre divina ya está tomada, nosotros, como la Madre divina, debemos romper este pesado \"velo\" de lo innecesario."
  },
  AvgDialog_121744_Content_6 = {Text = "Miryam..."},
  AvgDialog_121744_Content_7 = {
    Text = "No te preocupes, Madre divina. No importa cuáles sean tus planes en el futuro, los Marchadores de mares son la base más sólida y firme detrás de ti."
  },
  AvgDialog_121744_Content_8 = {
    Text = "No te andes con rodeos, ¿acaso vamos a quedarnos mirando cómo ustedes dos pequeños se enfrentan a este tipo?"
  },
  AvgDialog_121744_Content_9 = {
    Text = "Una voz familiar apareció de repente, interrumpiendo las palabras de Murphy. Era Goliath y Caecus."
  },
  AvgDialog_121745_Content_1 = {
    Text = "El monstruo erguido levanta la cabeza con orgullo, desde detrás del tenue telón, \"Mirada\" a todos ustedes."
  },
  AvgDialog_121745_Content_10 = {
    Text = "¡Por favor, tú, como yo... quédense enterrados para siempre en el infinito Aequor!"
  },
  AvgDialog_121745_Content_2 = {
    Text = "Cuando ves algunos premios que no se pueden mostrar en público, tus ojos se abren de par en par."
  },
  AvgDialog_121745_Content_3 = {
    Text = "Un enlace invisible atraviesa realmente entre ella y Él, ineludible, permitiendo que la niña vea Su trauma, Su sollozo e incluso Su confusión..."
  },
  AvgDialog_121745_Content_4 = {
    Text = "Como un bebé herido, cuestionando la \"traición\" de su madre."
  },
  AvgDialog_121745_Content_5 = {
    Text = "No me mires, no me interrogues... ya he tomado una decisión. Esta es mi última \"traición\"."
  },
  AvgDialog_121745_Content_6 = {
    Text = "Una vez, deseé \"Paraíso\", una \"ilusión\" que anhelaba en mi infancia."
  },
  AvgDialog_121745_Content_7 = {
    Text = "Pensé que \"Autoridad\" podría intercambiarse por \"Felicidad\", pero al final solo fue un sueño vano..."
  },
  AvgDialog_121745_Content_8 = {
    Text = "Murphy sonriendo se secó las lágrimas que caían de sus ojos. Ella se limpió lentamente y con cuidado, hasta que la última marca de lágrimas desapareció por completo. Luego, levantó la cabeza y miró a ese enorme \"yo\"."
  },
  AvgDialog_121745_Content_9 = {
    Text = "No necesito el paraíso, no necesito un sueño que me engañe. Ya no es necesario."
  },
  AvgDialog_121858_Content_1 = {
    Text = "De sus pies brotan miles de monstruos, y ustedes los matan uno por uno.\n Pisando miles de cadáveres, llegan a los pies de la enorme silueta."
  },
  AvgDialog_121858_Content_10 = {
    Text = "Esta vez, no permitiré que se intercambie la vida de nadie por la victoria."
  },
  AvgDialog_121858_Content_11 = {
    Text = "¡Prepárate para la batalla, el \"velo\" que eventualmente marchitará!"
  },
  AvgDialog_121858_Content_2 = {
    Text = "Esta es mi voluntad, la voluntad de \"Paraíso\"..."
  },
  AvgDialog_121858_Content_3 = {
    Text = "\"Niño\" nunca ha pertenecido a la \"Madre\"; después de nacer, también ha desarrollado su propio \"deseo\"."
  },
  AvgDialog_121858_Content_4 = {
    Text = "<Red:sueño... debe... continuar...>"
  },
  AvgDialog_121858_Content_5 = {
    Text = "Dijiste que solo si matas al controlador del sueño, el poder será transferido a ti..."
  },
  AvgDialog_121858_Content_6 = {
    Text = "Sí. ¿Ya has tenido tu despertar?"
  },
  AvgDialog_121858_Content_7 = {
    Text = "No, ella no tiene que hacer tal sacrificio."
  },
  AvgDialog_121858_Content_8 = {
    Text = "......%player%!"
  },
  AvgDialog_121858_Content_9 = {
    Text = "El \"núcleo\" del dominio, la \"catástrofe\" que se manifiesta, de este tamaño, ya he perdido la cuenta de cuántas veces he luchado contra ella."
  },
  AvgDialog_121859_Content_1 = {
    Text = "Él ejerce su fuerza... en el velo... está cambiando..."
  },
  AvgDialog_121859_Content_2 = {
    Text = "Despojado, abandonado... Él está en la desesperación, en la ira, en el lamento..."
  },
  AvgDialog_121859_Content_3 = {
    Text = "¡Su ira se derramará sobre ustedes...!"
  },
  AvgDialog_121864_Content_1 = {
    Text = "¿Es sorprendente? Porque el oráculo me está llamando, más allá del velo..."
  },
  AvgDialog_121865_Content_1 = {
    Text = "Mi sangre está incitando, las profundidades del mar cantan en coro invitándome!"
  },
  AvgDialog_121866_Content_1 = {
    Text = "Oh dioses lejanos, su devoto sirviente ofrecerá lo poco de fuerza que puede..."
  },
  AvgDialog_121867_Content_1 = {
    Text = "¡Suerte para ti, esto es para que veas la fuerza de los filisteos!"
  },
  AvgDialog_122640_Content_1 = {
    Text = "<Shake:¡Boom!——>"
  },
  AvgDialog_122640_Content_2 = {
    Text = "La mirada de locura hizo que toda la dimensión comenzara a temblar; el enlace entre Ramona y tú fue cubierto por la disolución, desapareciendo de la vista."
  },
  AvgDialog_122640_Content_3 = {
    Text = "Respiras hondo, reprimiendo a la fuerza la agitación que surge de la locura."
  },
  AvgDialog_122640_Content_4 = {
    Text = "Deja estas locuras para ti mismo... <Big:¡No dejaré que tus locuras lastimen a nadie más!>"
  },
  AvgDialog_122641_Content_1 = {Text = "...@3!!..."},
  AvgDialog_122641_Content_2 = {
    Text = "Intimidación familiar. Mirada familiar. Un dolor casi desgarrador que casi parte tu cerebro."
  },
  AvgDialog_122641_Content_3 = {
    Text = "Huu... Nos volvemos a ver, Toguwaibo, la deidad suprema... Aunque no puedes oír, debo agradecerte."
  },
  AvgDialog_122641_Content_4 = {
    Text = "Me hiciste morir una vez, y en esta muerte, comprendí una gran verdad..."
  },
  AvgDialog_122641_Content_5 = {
    Text = "Sujetas firmemente la llave de plata, mirando directamente la mirada impuesta por Su voluntad. Ni siquiera te das cuenta de que en la comisura de tus labios hay una leve sonrisa."
  },
  AvgDialog_122641_Content_6 = {
    Text = "Me has hecho saber que en este magnífico sueño tuyo, nada es inalterable, nada es invencible."
  },
  AvgDialog_122641_Content_7 = {
    Text = "Hemos esperado mucho tiempo para volver a vernos... ¡Ni tú puedes interponerte en nuestro camino!"
  },
  AvgDialog_122642_Content_1 = {
    Text = "......@2......@2......@1@3......!!"
  },
  AvgDialog_122642_Content_2 = {
    Text = "Un fuerte impacto hace que toda la dimensión comience a romperse. Abres los ojos rojos y miras hacia ese ojo que se acerca cada vez más a la realidad."
  },
  AvgDialog_122642_Content_3 = {
    Text = "Tu conciencia también ha llegado al límite, Toguwaibo... Ahora, sigue durmiendo!"
  },
  AvgDialog_122642_Content_4 = {
    Text = "Te animas con tu energía espiritual casi agotada, infundiendo tu último poder espiritual en la llave de plata."
  },
  AvgDialog_122642_Content_5 = {
    Text = "Sostienes la luz plateada como una cuchilla y apuñalas a la deidad frente a ti——"
  },
  AvgDialog_122643_Content_1 = {
    Text = "<Big:<Shake:¡Ramona!!!>>"
  },
  AvgDialog_122643_Content_2 = {
    Text = "La figura familiar es devorada por la disolución traída por la mirada, un antiguo y maligno conjuro aparece y desaparece en esta mirada."
  },
  AvgDialog_122643_Content_3 = {
    Text = "¡Estos cantos terminan aquí...!"
  },
  AvgDialog_122644_Content_1 = {
    Text = "El mundo se desmorona y se reconstruye ante ti, los seres queridos mueren y renacen frente a ti. Esa mirada confusa trae todo el caos del universo a tu mente."
  },
  AvgDialog_122644_Content_2 = {
    Text = "Desorden, confusión, caos... Lo que tu poder trae sigue siendo esto."
  },
  AvgDialog_122644_Content_3 = {
    Text = "Tu mirada nunca me ha confundido, Toguwaibo. Así fue en el pasado, y así es ahora."
  },
  AvgDialog_122644_Content_4 = {
    Text = "Brillando con luz plateada. En medio de esas infinitas ilusiones, encontraste el camino para enfrentarte a ella——"
  },
  AvgDialog_122645_Content_1 = {
    Text = "En una dimensión lejana, un punto de luz está parpadeando levemente."
  },
  AvgDialog_122645_Content_2 = {
    Text = "¿Es eso... el \"Sagrado Corazón\" de Pólux?"
  },
  AvgDialog_122645_Content_3 = {
    Text = "Su búsqueda también ha comenzado... Ahora, deben estar en peligro."
  },
  AvgDialog_122645_Content_4 = {
    Text = "Aún recuerdo el miedo que sentí la primera vez que te enfrenté, Toguwaibo. ¡Esta vez, no los haré esperar mucho!"
  },
  AvgDialog_122646_Content_1 = {
    Text = "Un dolor agudo asalta cada uno de tus huesos, cada centímetro de tu carne. Soportas este dolor penetrante y sonríes con dificultad."
  },
  AvgDialog_122646_Content_2 = {
    Text = "Dios insensato, no sabes que en tus sueños hay muchos sufrimientos que superan con creces al cuerpo..."
  },
  AvgDialog_122646_Content_3 = {
    Text = "¡No permitiré que ese sufrimiento vuelva a aparecer!"
  },
  AvgDialog_122694_Content_1 = {
    Text = "La puerta a mitad del pasillo ya está cubierta de escarcha blanca, y parece que se sigue extendiendo."
  },
  AvgDialog_122694_Content_10 = {
    Text = "Por favor, Gardian del secreto, solo abrázame —solo un poco, solo un poco de calor es todo lo que necesito~ El Hada recordará tu bondad para siempre."
  },
  AvgDialog_122694_Content_11 = {
    Text = "Es la primera vez que ves a esta pequeña estafadora con una expresión así, pero una cautela persistente te mantiene clavado donde estás, con el aliento formando nubes blancas, moviendo los miembros para mantenerte caliente."
  },
  AvgDialog_122694_Content_12 = {
    Text = "Ya he notificado a la oficina de administración. Vendrán a ayudar pronto. Quédate donde estás, no te muevas, no hagas nada."
  },
  AvgDialog_122694_Content_13 = {
    Text = "Pero me siento tan mal ahora mismo... El poder de ese río me ha arrastrado de vuelta a ese lugar pálido... helado... terrible..."
  },
  AvgDialog_122694_Content_14 = {
    Text = "Sin previo aviso, las lágrimas de Caraboo caen directamente, como si realmente acabara de presenciar algo aterrador."
  },
  AvgDialog_122694_Content_15 = {
    Text = "No creo que aguante hasta que llegue la ayuda, Gardian del secreto. Lo siento... por haberte mentido siempre antes..."
  },
  AvgDialog_122694_Content_16 = {
    Text = "Cristales de hielo se extienden hacia afuera con ella en el centro, y parece indefensa, frágil, con los ojos enrojecidos mientras te mira —tambaleándose, como si pudiera desplomarse en cualquier momento."
  },
  AvgDialog_122694_Content_17 = {Text = "¡Caraboo!"},
  AvgDialog_122694_Content_18 = {
    Text = "En el instante antes de que toque el suelo, te lanzas y la atrapas de todas formas —y al segundo siguiente, te arrepientes."
  },
  AvgDialog_122694_Content_19 = {
    Text = "Esos brazos helados se enroscan a tu alrededor con la facilidad sin huesos de algún ser invertebrado, y un aliento salpicado de cristales de nieve se derrama en el hueco de tu cuello y la curva de tu oreja."
  },
  AvgDialog_122694_Content_2 = {
    Text = "Te armas de valor y, luchando contra un frío tan violento que el castañeteo de tus dientes casi podría hacerte morder tu propia lengua, empujas la puerta del dormitorio de Caraboo."
  },
  AvgDialog_122694_Content_20 = {
    Text = "Ji ji~ Vaya, lo sabía. %player% es realmente tan blando de corazón."
  },
  AvgDialog_122694_Content_21 = {
    Text = "Detrás de ella, algo más suave y más frío aún se enrosca perezosamente a tu alrededor, hundiéndote a través de capa tras capa de nieve profunda."
  },
  AvgDialog_122694_Content_22 = {
    Text = "Forcejeas, con sonidos amortiguados atrapados en tu garganta, y justo antes de perder el conocimiento por completo, escuchas esa risita pícara."
  },
  AvgDialog_122694_Content_23 = {
    Text = "No pasa nada. Tu Hada será muy, muy delicada con su corderito más preciado~"
  },
  AvgDialog_122694_Content_3 = {
    Text = "Caraboo, ¿qué has he— sss, hace un frío glacial aquí."
  },
  AvgDialog_122694_Content_4 = {
    Text = "Pero esa pequeña figura traviesa y ágil no aparece de manera deslumbrante para presumir de su última broma, como siempre hace."
  },
  AvgDialog_122694_Content_5 = {
    Text = "Tiene un rubor inusual en el rostro. Parece, bueno, casi... digna de lástima."
  },
  AvgDialog_122694_Content_6 = {
    Text = "Gardian del secreto, ¿qué hago~? Me siento muy mal. Mi cuerpo se siente extraño, mi cabeza también se siente extraña."
  },
  AvgDialog_122694_Content_7 = {
    Text = "Tengo tanto frío. Casi me muero de frío aquí mismo."
  },
  AvgDialog_122694_Content_8 = {
    Text = "Y también tengo tanto calor —tanto que me flaquean las piernas, no puedo dar ni un solo paso."
  },
  AvgDialog_122694_Content_9 = {
    Text = "Se muerde el labio inferior y, con los ojos anegados en lágrimas, abre los brazos hacia ti —la postura de una niña que suplica que la abracen."
  },
  AvgDialog_122696_Content_1 = {
    Text = "En el salón vacío, solo resuenan los pasos de tú y Murphy."
  },
  AvgDialog_122697_Content_1 = {
    Text = "Hoy el cielo se oscurece más rápido de lo habitual, y está nublado, indicando claramente que va a llover."
  },
  AvgDialog_122697_Content_10 = {
    Text = "Mouchette levantó la cabeza, su rostro teñido de un rubor anormal, mostrando una sonrisa mezclada con confusión y fervor."
  },
  AvgDialog_122697_Content_11 = {
    Text = "¡Lucha conmigo, ahora mismo, inmediatamente!"
  },
  AvgDialog_122697_Content_13 = {
    Text = "Antes de que pudieras responder, el hacha de Mouchette ya había atacado, rozando tu mejilla con ligereza y precisión, levantando una ráfaga de viento frío."
  },
  AvgDialog_122697_Content_14 = {
    Text = "El viento se cuela en tu cuello sin permiso, inundando tu pecho y haciendo que tu cuerpo reaccione instintivamente con escalofríos."
  },
  AvgDialog_122697_Content_15 = {
    Text = "¿Desde cuándo empezamos a pelear por un desacuerdo!?"
  },
  AvgDialog_122697_Content_16 = {
    Text = "Tu pregunta fue ignorada por el hacha y su dueño."
  },
  AvgDialog_122697_Content_17 = {
    Text = "<Shake:¿Mouchette?>"
  },
  AvgDialog_122697_Content_18 = {
    Text = "¿¡Mouchette!?"
  },
  AvgDialog_122697_Content_19 = {
    Text = "Bajo tus continuas preguntas, el hacha finalmente se detuvo. Se apoyó en tu hombro, hundiéndose profundamente en la pared."
  },
  AvgDialog_122697_Content_2 = {
    Text = "Para evitar el destino de mojarte, corriste apresuradamente hacia el dormitorio, pero una figura bloqueó tu camino."
  },
  AvgDialog_122697_Content_20 = {
    Text = "Y el maestro del hacha está justo frente a ti, con la cara sonrojada, apretando los puños y agarrando con fuerza tu cuello."
  },
  AvgDialog_122697_Content_21 = {
    Text = "<Shake:¡Cállate... me siento muy mal en este momento, y pelear contigo es lo único que podría hacerme sentir mejor...>"
  },
  AvgDialog_122697_Content_22 = {
    Text = "Los dedos que sujetan tu collar continúan ejerciendo fuerza, pasando de un color carne a pálido, lo que significa la obstinación y la negativa del dueño."
  },
  AvgDialog_122697_Content_23 = {
    Text = "Odio cuando otros imponen sus ideas a los demás..."
  },
  AvgDialog_122697_Content_24 = {
    Text = "¿Solo es el Río Sagrado y crees que puede influenciarme? <Shake: No subestimes... me estás subestimando demasiado.>"
  },
  AvgDialog_122697_Content_25 = {
    Text = "Mouchette exhaló con fuerza mientras hablaba, tratando de calmar la influencia del Río Sagrado sobre ella, pero podías sentir el calor que se agolpaba en su interior, el deseo errante y el conflicto que luchaba."
  },
  AvgDialog_122697_Content_26 = {
    Text = "Al notar las emociones de Mouchette, no pudiste evitar suspirar, tomando su mano y guiando a la chica para que volviera a agarrar el mango del hacha."
  },
  AvgDialog_122697_Content_27 = {
    Text = "<Shake:¿Qué estás haciendo?>"
  },
  AvgDialog_122697_Content_28 = {
    Text = "¿No quieres pelear? Entonces pelea."
  },
  AvgDialog_122697_Content_29 = {
    Text = "No importa cómo quieras luchar, ni cuánto tiempo quieras luchar, estaré a tu lado hasta el final."
  },
  AvgDialog_122697_Content_3 = {
    Text = "¿Mouchette? ¿Qué pasa?"
  },
  AvgDialog_122697_Content_30 = {Text = "..."},
  AvgDialog_122697_Content_31 = {
    Text = "Los ojos de la niña se agrandan de repente, mirándote con sorpresa."
  },
  AvgDialog_122697_Content_32 = {
    Text = "En este momento, la lluvia tan esperada finalmente cayó, con gotas aterrizando en el rostro de Mouchette, deslizándose por su mentón y desapareciendo en tu cuello, fluyendo por tu pecho."
  },
  AvgDialog_122697_Content_33 = {
    Text = "Luego, más gotas de lluvia llegaron, golpeando salvajemente el suelo, dándote y a las mejillas de la niña, provocando una sensación de picazón."
  },
  AvgDialog_122697_Content_34 = {
    Text = "<Shake:¡Jajajaja, me gusta tu respuesta.>"
  },
  AvgDialog_122697_Content_35 = {
    Text = "Las cosas están empezando a volverse interesantes, ¿verdad?"
  },
  AvgDialog_122697_Content_36 = {
    Text = "Mouchette agarró el mango del hacha y la sacó de la pared, pero no la balanceó de nuevo; en cambio, te miró, mirándote directamente."
  },
  AvgDialog_122697_Content_37 = {
    Text = "Normalmente, no lucho desarmado con otros, pero a veces hay que probar cosas nuevas, ¿verdad?"
  },
  AvgDialog_122697_Content_38 = {
    Text = "La vida es tan larga, y algunas cosas interesantes deberían ser experimentadas personalmente y gradualmente."
  },
  AvgDialog_122697_Content_39 = {
    Text = "Mouchette dijo, caminando lentamente hacia ti. Y ese hacha se apoyaba tranquilamente contra la pared, recibiendo el húmedo bautismo del mundo."
  },
  AvgDialog_122697_Content_4 = {
    Text = "Mouchette bajó la cabeza y no respondió; solo podías notar la agitación de la chica por sus dedos, que se volvían blancos al agarrar con fuerza el hacha."
  },
  AvgDialog_122697_Content_5 = {
    Text = "<Shake:¿¡Mouchette!?>"
  },
  AvgDialog_122697_Content_6 = {
    Text = "Finalmente, la niña habló, pero su voz llevaba un matiz de duda e incertidumbre."
  },
  AvgDialog_122697_Content_7 = {
    Text = "%player%, yo... necesito tu ayuda..."
  },
  AvgDialog_122697_Content_8 = {
    Text = "¿Necesitas ayuda? No hay problema. ¿Qué necesitas?"
  },
  AvgDialog_122697_Content_9 = {
    Text = "<Shake:Te necesito...>"
  },
  AvgDialog_122700_Content_1 = {
    Text = "Bienvenido a mi teatro. Llegas justo a tiempo, {Male=Sr., Female=Srta.} Guardián."
  },
  AvgDialog_122700_Content_10 = {
    Text = "Propagarse... renacer... no me digas que tú también—"
  },
  AvgDialog_122700_Content_11 = {
    Text = "Ah, en realidad... acabo de recordar que la tarea del Profesor Dor aún no está terminada... Creo que será mejor que—"
  },
  AvgDialog_122700_Content_12 = {
    Text = "Te das la vuelta para irte, pero tus pasos te llevan inconscientemente hacia adelante, hasta llegar frente a Arachne."
  },
  AvgDialog_122700_Content_13 = {
    Text = "Sí, yo estoy bajo la influencia del río... y tú estás bajo el influjo del destino. Esta noche es una noche que nos pertenece solo a nosotros dos."
  },
  AvgDialog_122700_Content_14 = {
    Text = "Una obra que siempre estuvo destinada a representarse—y al fin, su protagonista predestinado ha llegado."
  },
  AvgDialog_122700_Content_15 = {
    Text = "El aliento de Arachne ya se ha posado en tu oído, cálido y sutil."
  },
  AvgDialog_122700_Content_16 = {
    Text = "Su sonrisa sigue siendo tan serena como siempre. Pero en lo profundo de esos ojos insondables, algo arde: una llama que nunca habías visto antes, como si pudiera consumir todo lo que toca."
  },
  AvgDialog_122700_Content_17 = {
    Text = "No, no puedo... Arachne... yo..."
  },
  AvgDialog_122700_Content_18 = {
    Text = "No hay necesidad de huir, %player%. La telaraña ha tejido cada posibilidad en su lugar. Nos guiará a ambos a través de la actuación de esta noche."
  },
  AvgDialog_122700_Content_19 = {
    Text = "Una telaraña invisible se cierra a tu alrededor, arrebatándote hasta la última gota de fuerza, engullendo cada impulso de resistencia."
  },
  AvgDialog_122700_Content_2 = {
    Text = "Empujas la pesada puerta del teatro, la luz de la luna se filtra a través de las altas ventanas, el rocío fresco de la noche y la suave voz de Arachne en el teatro te despiertan de repente."
  },
  AvgDialog_122700_Content_20 = {
    Text = "Los hilos se tensan. Miras el rostro tan cerca del tuyo, y tu corazón da un vuelco, tu respiración se acelera."
  },
  AvgDialog_122700_Content_21 = {
    Text = "El destino dicta que nunca quisiste huir. Deseabas esto: <Italic:Tú> querías venir aquí, querías ver esta actuación hasta el final, sin más público que ustedes dos."
  },
  AvgDialog_122700_Content_22 = {
    Text = "Tú... ¡¿reescribiste mi destino?!"
  },
  AvgDialog_122700_Content_23 = {
    Text = "Nunca he reescrito nada, {Male=Sr., Female=Srta.} Guardián. Solo devolví tu destino al camino que siempre debió recorrer."
  },
  AvgDialog_122700_Content_24 = {
    Text = "Arachne... tú... tú puedes cambiar completamente el rumbo del destino, evitar la influencia del Río Sagrado... ¿por qué no hacerlo?"
  },
  AvgDialog_122700_Content_25 = {
    Text = "¿Por qué habría de hacerlo?"
  },
  AvgDialog_122700_Content_26 = {
    Text = "Para un jugador que hace mucho memorizó el guion, lo inesperado es el regalo más raro que el destino jamás haya tenido a bien conceder..."
  },
  AvgDialog_122700_Content_27 = {
    Text = "Las suaves palabras de Arachne vibran en tu oído. Ya no está tranquila y lejana, su respiración tiembla suavemente, su sonrisa está a la vuelta de la esquina."
  },
  AvgDialog_122700_Content_28 = {
    Text = "Y resulta que... descubro que no tengo objeción alguna a un final en el que nadie salga herido."
  },
  AvgDialog_122700_Content_29 = {
    Text = "La red de hilos es fría, flexible, se adhiere con una cercanía que no deja espacio para respirar, tensándose más, presionando a través de la tela, contra la piel."
  },
  AvgDialog_122700_Content_3 = {
    Text = "¡Espera! Debería estar dormido en mi dormitorio. ¿Cómo acabé aquí... fuiste tú?"
  },
  AvgDialog_122700_Content_30 = {
    Text = "Entonces los quelíceros se cierran a tu alrededor, y fríos pedipalpos separan tus labios, sellando cualquier resistencia que aún no hubiera encontrado sus palabras."
  },
  AvgDialog_122700_Content_31 = {
    Text = "Los hilos comienzan a guiar tus extremidades. Con suavidad, y sin apelación."
  },
  AvgDialog_122700_Content_32 = {
    Text = "No te preocupes, Guardián. No hay necesidad de resistirse a lo que el destino ha decidido darte."
  },
  AvgDialog_122700_Content_33 = {
    Text = "Porque... esto es lo que tú también deseas, ¿no es así?"
  },
  AvgDialog_122700_Content_34 = {
    Text = "...sí, Arachne... esto es... lo que quiero..."
  },
  AvgDialog_122700_Content_35 = {
    Text = "Por supuesto. Nunca has sido una marioneta del destino. Eres el Guardián del Secreto de Misaq, quien sostiene su destino en sus propias manos."
  },
  AvgDialog_122700_Content_36 = {
    Text = "Esto es exactamente lo que deseas. Es el destino el que se doblega ante tu voluntad. Es tu cuerpo respondiendo a tu propia llamada."
  },
  AvgDialog_122700_Content_37 = {
    Text = "Los hilos se estremecen, como el destino deslizando un arco sobre las cuerdas. Extiendes la mano, recorriendo las patas de araña que se mecen suavemente en el aire, recorriendo las manos que nunca han dejado de girar el huso, recorriendo las líneas de ese rostro gentil."
  },
  AvgDialog_122700_Content_38 = {
    Text = "Ese rostro familiar. La compasión que siempre lleva consigo, la quietud que nunca lo abandona. Y ahora, apenas perceptible, algo más —una calidez que aflora a la superficie, sin reservas, que nunca antes habías visto."
  },
  AvgDialog_122700_Content_39 = {
    Text = "Demos la bienvenida a lo que el destino nos ha traído, juntos... {Male=Sr., Female=Srta.} Guardián."
  },
  AvgDialog_122700_Content_4 = {
    Text = "Seguiste tu propia voluntad. <Italic:Querías> venir aquí. ¿Lo habías olvidado?"
  },
  AvgDialog_122700_Content_40 = {
    Text = "Dos hilos del destino se enroscan el uno alrededor del otro, tirando, cediendo, sin cesar. Las ondas temblorosas se extienden hacia afuera a lo largo de la red invisible, disolviéndose hacia un borde ilimitado e inalcanzable."
  },
  AvgDialog_122700_Content_41 = {Text = "..."},
  AvgDialog_122700_Content_5 = {
    Text = "Ella te sonríe. Una presión, como el peso del destino mismo, se cierra desde todas las direcciones."
  },
  AvgDialog_122700_Content_6 = {
    Text = "El mundo siempre ha visto el destino como un grillete ineludible, la fuente de todo su sufrimiento."
  },
  AvgDialog_122700_Content_7 = {
    Text = "Pero tú y yo, que hemos tocado los hilos del destino con nuestras propias manos, sabemos bien que no es más que lo que nosotros mismos hemos elegido crear."
  },
  AvgDialog_122700_Content_8 = {
    Text = "Propagarse, para que podamos ser destruidos. Ser destruidos, para que podamos renacer."
  },
  AvgDialog_122700_Content_9 = {
    Text = "Una y otra vez, sin fin... Eso es todo lo que el destino es, ¿no es así?"
  },
  AvgDialog_122780_Content_1 = {
    Text = "Mensajes desde la lejanía"
  },
  AvgDialog_122780_Content_2 = {
    Text = "Este es un documento de prueba"
  },
  AvgDialog_122780_Content_3 = {
    Text = "Este es un documento de prueba"
  },
  AvgDialog_122780_Content_4 = {
    Text = "Este es un documento de prueba"
  },
  AvgDialog_122780_Content_5 = {
    Text = "Este es un documento de prueba"
  },
  AvgDialog_122780_Content_6 = {
    Text = "Este es un documento de prueba"
  },
  AvgDialog_122780_Content_7 = {
    Text = "Frase de cierre"
  },
  AvgDialog_123116_Content_1 = {
    Text = "Cordero para el matadero"
  },
  AvgDialog_123116_Content_10 = {
    Text = "Pero cada sacerdote que llegó a Howick—Juan, Santiago, Anderson—ha perdido completamente el contacto en un corto período de tiempo."
  },
  AvgDialog_123116_Content_11 = {
    Text = "Buenos niños... Después del desastre, han estado siguiendo las enseñanzas del Padre Dios, tomando la iniciativa de ir a varias diócesis para difundir el evangelio del Padre Dios."
  },
  AvgDialog_123116_Content_12 = {
    Text = "Incluso en una gran ciudad como Londres, la gente común a menudo lucha por cuidar de sí misma después de un desastre, y la situación en Howick solo será peor. ¿Por qué ellos——"
  },
  AvgDialog_123116_Content_13 = {
    Text = "Así como hiciste por este mundo y los mundos pasados, mensajero pálido."
  },
  AvgDialog_123116_Content_14 = {
    Text = "Salvador juntó las manos, su expresión de oración era devota y llena de compasión."
  },
  AvgDialog_123116_Content_15 = {
    Text = "Porque nuestros hermanos y hermanas están sufriendo."
  },
  AvgDialog_123116_Content_16 = {
    Text = "Eliminar el sufrimiento de esta tierra es la responsabilidad del ejecutor del Padre Dios; no pueden abandonar a otros en la desesperación debido a la distancia del viaje."
  },
  AvgDialog_123116_Content_17 = {Text = "...Ya veo."},
  AvgDialog_123116_Content_18 = {
    Text = "Padre Salvador, te ayudaré a encontrarlos juntos. \n No importa si es vida o muerte."
  },
  AvgDialog_123116_Content_19 = {
    Text = "En este momento"
  },
  AvgDialog_123116_Content_2 = {
    Text = "En las afueras de Londres, un pueblo remoto, Howick"
  },
  AvgDialog_123116_Content_20 = {
    Text = "Salvador, parece haber una luz adelante..."
  },
  AvgDialog_123116_Content_21 = {
    Text = "Tu voz se detiene abruptamente debido a un descubrimiento inesperado—dentro de la cueva vacía, aparece repentinamente una jaula rudimentaria."
  },
  AvgDialog_123116_Content_22 = {
    Text = "Al menos una docena de personas están encerradas dentro de la jaula, cada una luciendo demacrada, con varios teniendo moretones en la cara y heridas por todo el cuerpo."
  },
  AvgDialog_123116_Content_23 = {
    Text = "<Shake:¿Henry... está muerto? ¡Le dispararon a Henry, le dispararon a Henry muerto...!>"
  },
  AvgDialog_123116_Content_24 = {
    Text = "La mujer se sostiene la cabeza murmurando para sí misma, su mirada loca y su intenso temblor revelan su inestabilidad."
  },
  AvgDialog_123116_Content_25 = {
    Text = "De repente, ella levantó la cabeza y se dio cuenta de que ustedes estaban cerca."
  },
  AvgDialog_123116_Content_26 = {
    Text = "<Shake:¡No, vienen, llévanos de aquí rápido!>"
  },
  AvgDialog_123116_Content_27 = {
    Text = "Su movimiento atrajo más atención, y un hombre en una jaula se lanzó repentinamente hacia las barras de la celda, extendiendo la mano para agarrar tu brazo."
  },
  AvgDialog_123116_Content_28 = {
    Text = "¡Ayúdame! No quiero ser un sacrificio humano, no quiero ser sacrificado..."
  },
  AvgDialog_123116_Content_29 = {
    Text = "¡Ahhhhh—llévanos de aquí!"
  },
  AvgDialog_123116_Content_3 = {
    Text = "Si la información proporcionada por \"Muñeca\" no está equivocada, deberían estar justo aquí."
  },
  AvgDialog_123116_Content_30 = {
    Text = "¡Cállense todos!"
  },
  AvgDialog_123116_Content_31 = {
    Text = "Un rugido ensordecedor interrumpió los gritos de las víctimas, y los prisioneros parecían estar extraordinariamente aterrorizados por el dueño del rugido, asustados hasta el extremo."
  },
  AvgDialog_123116_Content_32 = {
    Text = "¡El ritual de sacrificio aún no ha comenzado, y ustedes, este grupo de cerdos, ya están ansiosos por buscar la muerte!?"
  },
  AvgDialog_123116_Content_33 = {
    Text = "Pasos rápidos siguieron."
  },
  AvgDialog_123116_Content_34 = {
    Text = "Debería ser el culto que está encarcelando a estas personas, %player%, nosotros..."
  },
  AvgDialog_123116_Content_35 = {
    Text = "Mantente escondido y piensa en una forma de rescatarlos más tarde. Tienen armas, y en el caos, no podemos garantizar la seguridad de estas personas."
  },
  AvgDialog_123116_Content_36 = {
    Text = "Pero el hombre aún te sostiene firmemente, con tal fuerza que casi te rompe el brazo."
  },
  AvgDialog_123116_Content_37 = {
    Text = "¡Sálvanos, sálvanos primero! Si no nos salvas, ¡muere con nosotros!"
  },
  AvgDialog_123116_Content_38 = {
    Text = "Los pasos se están acercando, y el estado mental de la otra parte claramente no puede comprender ninguna razón."
  },
  AvgDialog_123116_Content_39 = {
    Text = "Apretaste los dientes y lo noqueaste con un golpe."
  },
  AvgDialog_123116_Content_4 = {
    Text = "Confío en tu juicio, %player%."
  },
  AvgDialog_123116_Content_40 = {
    Text = "Hah... Hah..."
  },
  AvgDialog_123116_Content_41 = {
    Text = "En la esquina de la celda, de repente se escuchó una risa suave."
  },
  AvgDialog_123116_Content_42 = {
    Text = "Instintivamente giras la cabeza para mirar, y en la jaula, una doncella vestida de manera extraña te está observando, su leve sonrisa contrasta fuertemente con el ambiente caótico y loco en este momento."
  },
  AvgDialog_123116_Content_43 = {
    Text = "¡Qué interesante! Un segundo diciendo que hay que salvar a alguien, y al siguiente noqueándolo..."
  },
  AvgDialog_123116_Content_44 = {
    Text = "El estado actual de desapego te ha dejado momentáneamente congelado en su lugar."
  },
  AvgDialog_123116_Content_45 = {
    Text = "No te preocupes por mí, sigue."
  },
  AvgDialog_123116_Content_46 = {
    Text = "¿No te apresuras? Los seguidores de la Asamblea del Amanecer Estrellado están por llegar."
  },
  AvgDialog_123116_Content_47 = {Text = "......¿?"},
  AvgDialog_123116_Content_48 = {
    Text = "El tiempo es apremiante, ya no hay lugar para charlas ociosas, solo puedes dejar a la niña atrás y esconderte con Salvador en la oscuridad."
  },
  AvgDialog_123116_Content_49 = {
    Text = "Pronto, aparecieron dos sectarios armados con escopetas fuera de la jaula. Se situaron a ambos lados, levantando sus armas y apuntando los cañones hacia dentro de la jaula."
  },
  AvgDialog_123116_Content_5 = {
    Text = "Que el Padre Dios los bendiga y los proteja de las sombras, que puedan habitar en paz."
  },
  AvgDialog_123116_Content_50 = {
    Text = "¿Quién estaba haciendo tanto ruido hace un momento? ¡Sal!"
  },
  AvgDialog_123116_Content_51 = {
    Text = "Nadie respondió. Los prisioneros se acurrucaban en las esquinas, temblando, o miraban en blanco, aturdidos y en silencio.\nExcepto por esa extraña niña."
  },
  AvgDialog_123116_Content_52 = {
    Text = "Ella todavía llevaba una sonrisa despreocupada, observando con tranquilidad a los seguidores de culto armados con armas de fuego."
  },
  AvgDialog_123116_Content_53 = {
    Text = "¿Este tipo no será un loco? Está tan relajado incluso cuando la muerte se acerca."
  },
  AvgDialog_123116_Content_54 = {
    Text = "En este maldito mundo, ¿dónde quedan las personas normales, ja! Si también estuviéramos locos, podría ser mucho más fácil."
  },
  AvgDialog_123116_Content_55 = {
    Text = "Espero que este ritual tenga éxito. Ya he tenido suficiente de esas extrañas nieblas densas..."
  },
  AvgDialog_123116_Content_56 = {
    Text = "¿Cuándo comienza el ritual que ustedes mencionaron?"
  },
  AvgDialog_123116_Content_57 = {
    Text = "El seguidor de culto estaba visiblemente atónito."
  },
  AvgDialog_123116_Content_58 = {
    Text = "¿A quién le estás hablando, a nosotros?"
  },
  AvgDialog_123116_Content_59 = {
    Text = "¿Qué más? Deja de hablar tonterías y responde a mi pregunta."
  },
  AvgDialog_123116_Content_6 = {
    Text = "Salvador, con piedad, bajó la mirada, susurró una oración y luego fue el primero en adentrarse en la cueva."
  },
  AvgDialog_123116_Content_60 = {
    Text = "El seguidor del culto estaba completamente enfurecido por la niña, riéndose fríamente mientras levantaba la mano y apuntaba con la pistola a la pierna de la niña."
  },
  AvgDialog_123116_Content_61 = {
    Text = "Mujer loca, lo único que necesitas hacer es esperar obedientemente a ser sacrificada. Puedo ver que no tienes ni idea de lo que está sucediendo."
  },
  AvgDialog_123116_Content_62 = {Text = "Bang—"},
  AvgDialog_123116_Content_63 = {
    Text = "Una fuerza invisible hizo que la bala perdiera su objetivo, golpeando la cueva arriba y provocando una débil llama——"
  },
  AvgDialog_123116_Content_64 = {
    Text = "Tú y Salvador emergieron de la oscuridad, lanzando una emboscada a los seguidores del culto."
  },
  AvgDialog_123116_Content_66 = {
    Text = "¡Has gestionado bien tu tiempo! Parece que no sois tontos después de todo."
  },
  AvgDialog_123116_Content_67 = {
    Text = "Gracias por distraer la atención de los seguidores de culto por nosotros, amable señora."
  },
  AvgDialog_123116_Content_68 = {
    Text = "Que el Padre Dios te bendiga."
  },
  AvgDialog_123116_Content_69 = {
    Text = "Salvador dibujó en el aire el sagrado nombre del Padre Dios. \n Tú confiscaste todas las armas de los seguidores del culto, les ordenaste arrodillarse frente a la jaula y comenzaste el interrogatorio."
  },
  AvgDialog_123116_Content_7 = {
    Text = "Hace tres días"
  },
  AvgDialog_123116_Content_70 = {
    Text = "Dime, ¿cuándo se lleva a cabo el ritual? ¿Dónde se realiza? ¿Está la desaparición de los sacerdotes del Santuario de Vida relacionada con ustedes!?"
  },
  AvgDialog_123116_Content_71 = {
    Text = "Santuario de Vida... ¿Sacerdote...?"
  },
  AvgDialog_123116_Content_72 = {
    Text = "¿Es cierto, John, James, Anderson, dónde están?"
  },
  AvgDialog_123116_Content_73 = {
    Text = "Al escuchar esto, el seguidor de culto se quedó atónito por un momento y luego estalló en una risa desenfrenada."
  },
  AvgDialog_123116_Content_74 = {
    Text = "<Shake:¡Nos redimiremos según la voluntad del Padre Dios, sí, \"el Reino de la tranquilidad sin el sufrimiento de la disolución\"!>"
  },
  AvgDialog_123116_Content_75 = {
    Text = "<Shake:<Big:¡Ha llegado! Ustedes, desafortunados, solo pueden quedarse aquí, yendo hacia la destrucción con este mundo!>>"
  },
  AvgDialog_123116_Content_76 = {
    Text = "¿Así que la ceremonia está a punto de comenzar? <Small:Parece que debo aprovechar el tiempo.>"
  },
  AvgDialog_123116_Content_77 = {
    Text = "Date prisa... ¿Qué significa? ¿Qué sabes?"
  },
  AvgDialog_123116_Content_78 = {
    Text = "La niña no respondió; te miró a ti y a Salvador, revelando una sonrisa inocente y bien educada.\nNo sabes por qué, pero percibiste un atisbo de astucia en ella."
  },
  AvgDialog_123116_Content_79 = {
    Text = "Ah, por cierto, me llamo Mouchette, en cuanto a sus nombres—no es necesario decirlos, no estoy interesada."
  },
  AvgDialog_123116_Content_8 = {
    Text = "¿Todos los sacerdotes enviados por el Santuario de Vida a Howick están desaparecidos?"
  },
  AvgDialog_123116_Content_80 = {
    Text = "Sé dónde está el lugar del ritual, y puedo llevarlos, solo que..."
  },
  AvgDialog_123116_Content_81 = {
    Text = "Necesito que me hagan un pequeño favor."
  },
  AvgDialog_123116_Content_82 = {
    Text = "¿Qué favor? Espero que puedas explicarlo con claridad."
  },
  AvgDialog_123116_Content_83 = {
    Text = "Aún no hubo respuesta, la niña solo dejó una frase y se marchó cantando en un tono entrecortado."
  },
  AvgDialog_123116_Content_84 = {
    Text = "¡Hmph☆Hmph! Primero iré a ocuparme de algo. En diez minutos, nos reunimos afuera~"
  },
  AvgDialog_123116_Content_85 = {Text = "..."},
  AvgDialog_123116_Content_86 = {
    Text = "Esto también está bien; primero podemos contactar al Santuario de Vida para enviar refuerzos y ayudar a estas personas que están sufriendo."
  },
  AvgDialog_123116_Content_87 = {
    Text = "Solo puede ser así."
  },
  AvgDialog_123116_Content_88 = {
    Text = "Mirando en la dirección por donde se fue la chica, la creciente inquietud te hace sentir como si algo estuviera subiendo por tu columna vertebral."
  },
  AvgDialog_123116_Content_89 = {
    Text = "Su origen es el sentido de desconexión que se encuentra bajo el exterior ingenuo del otro, uno que está extremadamente cerca de la humanidad pero que es deslumbrantemente falso..."
  },
  AvgDialog_123116_Content_9 = {
    Text = "Sí, después de perder contacto con el sacerdote White, que está a cargo de la diócesis de Howick, el Vaticano decidió enviar refuerzos."
  },
  AvgDialog_123117_Content_1 = {
    Text = "En plata y sangre"
  },
  AvgDialog_123117_Content_10 = {
    Text = "... No debería haber discutido estas cosas contigo."
  },
  AvgDialog_123117_Content_100 = {
    Text = "Mouchette... si aún estás... por favor, sal... te lo ruego..."
  },
  AvgDialog_123117_Content_101 = {
    Text = "Aún no hubo respuesta, como si la chica llamada \"Mouchette\" hubiera desaparecido por completo."
  },
  AvgDialog_123117_Content_102 = {Text = "..."},
  AvgDialog_123117_Content_103 = {
    Text = "Cierras los ojos y dejas escapar un profundo suspiro. No queda tiempo. \n Salvador sigue afuera, y la puerta invisible sigue ahí, debes volver."
  },
  AvgDialog_123117_Content_104 = {
    Text = "Lo siento que hayas llegado a un mundo tan cruel... También siento no poder enviarte a casa..."
  },
  AvgDialog_123117_Content_105 = {
    Text = "En el siguiente instante, cortaste el enlace con la dimensión espiritual de Mouchette——"
  },
  AvgDialog_123117_Content_106 = {
    Text = "Después de un breve momento de mareo, tu espíritu regresó al caparazón, y todo volvió al punto de partida:"
  },
  AvgDialog_123117_Content_107 = {
    Text = "La puerta intangible sigue fuera de control, y el hacha de Mouchette yace silenciosamente en tu mano."
  },
  AvgDialog_123117_Content_108 = {
    Text = "<Shake:Mouchette...yo...>"
  },
  AvgDialog_123117_Content_109 = {
    Text = "Agarraste con fuerza el mango del hacha y miraste a Mouchette. La chica de otro mundo permanecía en silencio, perdida en la locura, como si estuviera esperando tu última elección."
  },
  AvgDialog_123117_Content_11 = {
    Text = "Suspiras, con una expresión de desánimo en tu rostro. Salvador observó todo esto y no pudo evitar soltar una risa suave."
  },
  AvgDialog_123117_Content_110 = {
    Text = "Quizás sea un efecto psicológico, pero siempre sientes que esos ojos no han perdido toda su cordura.\nPorque has visto esos ojos sonriendo antes."
  },
  AvgDialog_123117_Content_111 = {
    Text = "<Shake:¿Qué... quieres ver... cuándo...?>"
  },
  AvgDialog_123117_Content_112 = {
    Text = "¡Mouchette! ¿Has recuperado la razón?!"
  },
  AvgDialog_123117_Content_113 = {
    Text = "<Shake:No... pero... escuché... tus palabras...>"
  },
  AvgDialog_123117_Content_114 = {
    Text = "Tienes razón... las cosas no deberían ser así... no puedo rendirme sin siquiera intentarlo..."
  },
  AvgDialog_123117_Content_115 = {
    Text = "Mouchette usó sus últimas fuerzas para agarrarte y tocar la llave de plata en tu pecho."
  },
  AvgDialog_123117_Content_116 = {
    Text = "No importa el resultado, la puerta invisible desaparecerá..."
  },
  AvgDialog_123117_Content_117 = {
    Text = "Nunca... dejaré que aquí se convierta en otro mundo de catástrofe de niebla..."
  },
  AvgDialog_123117_Content_118 = {
    Text = "Especialmente después de enterarme de cómo trabajaste duro para salvar este mundo"
  },
  AvgDialog_123117_Content_119 = {
    Text = "Luego, la llave de plata en tu pecho se activa automáticamente, emitiendo un resplandor que tiñe tu visión de blanco."
  },
  AvgDialog_123117_Content_12 = {
    Text = "Mouchette, definitivamente es una niña especial... solo que es especial, sigue siendo una buena niña."
  },
  AvgDialog_123117_Content_120 = {
    Text = "Escuchaste un grito desgarrador, un lamento doloroso, la distorsión de una flauta y el sonido de algo rompiéndose."
  },
  AvgDialog_123117_Content_121 = {
    Text = "O quizás, estas son solo las alucinaciones provocadas por tu tensión, porque en esta extensión de pura blancura, has perdido el control de tus sentidos y de tu sentido del tiempo."
  },
  AvgDialog_123117_Content_122 = {
    Text = "Después de un tiempo indeterminado, cuando todas las alucinaciones desaparecen, tus diversos sentidos finalmente regresan—"
  },
  AvgDialog_123117_Content_123 = {
    Text = "La densa niebla se disipó, la puerta invisible desapareció, y en el altar manchado de sangre, solo estás tú y Salvador, mirándote con preocupación."
  },
  AvgDialog_123117_Content_124 = {
    Text = "Mensajero pálido, ¿fracasamos...?"
  },
  AvgDialog_123117_Content_125 = {Text = "..."},
  AvgDialog_123117_Content_126 = {
    Text = "En ese momento, una risa suave sonó detrás de ustedes."
  },
  AvgDialog_123117_Content_127 = {
    Text = "%player%, Salvador, ¿en qué están soñando despiertos? La misión ha terminado."
  },
  AvgDialog_123117_Content_128 = {
    Text = "<Big:Mouchette—!!>"
  },
  AvgDialog_123117_Content_129 = {
    Text = "Sorprendido, gritaste, y al segundo siguiente, no pudiste evitar sonreír."
  },
  AvgDialog_123117_Content_13 = {
    Text = "¿Buen niño? Por favor, no uses esa palabra para describir... Espera, ¿escucharon algo?"
  },
  AvgDialog_123117_Content_130 = {
    Text = "No es necesario que hables tan alto, también puedo oírlo claramente. De todos modos, la emocionante batalla ya ha terminado, lo que queda es la aburrida vida cotidiana."
  },
  AvgDialog_123117_Content_131 = {
    Text = "Después de regresar, realmente quiero disfrutar de una humeante taza de té kava de avellana, oh... aquí no hay eso, así que comeré un pastelito."
  },
  AvgDialog_123117_Content_132 = {
    Text = "Podemos charlar mientras disfrutamos de unos pastelitos, por ejemplo, quién es Murphy, quién es Liz, quién es Doll y qué aventuras interesantes has tenido con el Despertado?"
  },
  AvgDialog_123117_Content_133 = {
    Text = "De todos modos, no puedo volver, así que solo puedo aprender más sobre este mundo."
  },
  AvgDialog_123117_Content_134 = {
    Text = "No creo que %player% rechace esta solicitud."
  },
  AvgDialog_123117_Content_135 = {
    Text = "Salvador te miró con una sonrisa, y tú también sonreíste, mirando a Mouchette.\nLa densa niebla se disipó, y la luz de la luna en el cielo nocturno se derramó sobre ustedes, proyectando una suave resplandor."
  },
  AvgDialog_123117_Content_136 = {
    Text = "Aún tienes muchas preguntas que hacerle a Mouchette, pero las mantienes guardadas en tu corazón——"
  },
  AvgDialog_123117_Content_137 = {
    Text = "Quizás se deba a la hermosa luz de la luna, o tal vez a una cierta sensación que no puedes describir del todo, similar a una sensación de \"renacimiento\" tras haber escapado por poco de la muerte."
  },
  AvgDialog_123117_Content_138 = {
    Text = "Olvídalo, el informe se puede escribir en cualquier momento, pero celebrar la llegada de huéspedes de otro mundo, la oportunidad de renacer en el nuevo mundo no se presenta a menudo."
  },
  AvgDialog_123117_Content_139 = {
    Text = "¡Felicidades por convertirte en un Despertado, Mouchette! A partir de ahora, este lugar no será solo nuestro mundo, sino también tu mundo..."
  },
  AvgDialog_123117_Content_14 = {
    Text = "Parece que alguien está llorando... y el llanto se está volviendo más fuerte..."
  },
  AvgDialog_123117_Content_140 = {
    Text = [[
Despertado Mouchette
Bienvenido a nuestro mundo]]
  },
  AvgDialog_123117_Content_15 = {
    Text = "Te inclinas para escuchar, pero no oyes nada. \n Miras de nuevo a Salvador, y él también sacudió suavemente la cabeza."
  },
  AvgDialog_123117_Content_16 = {
    Text = "Mouchette de repente soltó un grito, se agachó y se cubrió los oídos con dolor."
  },
  AvgDialog_123117_Content_17 = {
    Text = "<Shake:Espera un segundo... Alguien, no, muchas personas, están gritando y aullando en mi cabeza...>"
  },
  AvgDialog_123117_Content_18 = {
    Text = "Te das cuenta de que algo no va bien, miras la situación de Mouchette y solo ves que ella tiembla de dolor sin parar, y sus pupilas se dilatan constantemente."
  },
  AvgDialog_123117_Content_19 = {
    Text = "¿Fuera de control? ¿Podría ser por el líquido de núcleo de plata...?"
  },
  AvgDialog_123117_Content_2 = {
    Text = "Bajo el vasto cielo de plata y sangre, la densa niebla sin límites se agita, y la puerta invisible brilla, pero ya no parecen invencibles—"
  },
  AvgDialog_123117_Content_20 = {
    Text = "¡Líquido de núcleo de plata!?"
  },
  AvgDialog_123117_Content_21 = {
    Text = "Examinaste cuidadosamente las manchas de sangre en Mouchette, y en medio del rojo oscuro, el líquido de núcleo de plata fluía lentamente, filtrándose en su cuerpo a través de su piel expuesta."
  },
  AvgDialog_123117_Content_22 = {
    Text = "Mouchette llegó a nuestro mundo a través de un ritual de sacrificio, y este líquido de núcleo de plata, como ofrenda, probablemente la consideró también como \"una parte\" del ritual..."
  },
  AvgDialog_123117_Content_23 = {
    Text = "¡No, aquí hay demasiado líquido de núcleo de plata, es muy confuso! ¡Debo manejarlo de inmediato, de lo contrario, ella, como una persona común, se volverá loca!"
  },
  AvgDialog_123117_Content_24 = {
    Text = "Tú y Salvador inmediatamente empezaron a limpiar el líquido de núcleo de plata de Mouchette, pero ya era demasiado tarde——"
  },
  AvgDialog_123117_Content_25 = {
    Text = "<Red:<Shake:¡Aaaahh!>>"
  },
  AvgDialog_123117_Content_26 = {
    Text = "Con un grito, las pupilas de Mouchette se dilataron y se dividieron oficialmente, su cuerpo se hizo añicos y se distorsionó, salpicando una gran cantidad de carne y sangre, mutando en una existencia indescriptible."
  },
  AvgDialog_123117_Content_27 = {
    Text = "Esta carne y sangre destrozadas salpicaron sobre ti y Salvador, también salpicando sobre la puerta invisible, creando ondas sobre la superficie de esta, que es desconocida y ominosa."
  },
  AvgDialog_123117_Content_28 = {
    Text = "Algo no está bien, la \"puerta\" está cambiando..."
  },
  AvgDialog_123117_Content_29 = {
    Text = "Antes de que pudieras terminar de hablar, un fuerte impacto recorrió la conexión entre la puerta intangible y la llave de plata, dejándote sin palabras en un instante."
  },
  AvgDialog_123117_Content_3 = {
    Text = "La llave de plata en tu mano emite un resplandor deslumbrante y firme, cerrando poco a poco la fisura espacio-temporal y eliminando poco a poco todas las anomalías causadas por la ceremonia."
  },
  AvgDialog_123117_Content_30 = {
    Text = "Bajo un trauma psicológico insoportable, no dejas de sangrar por la nariz, pierdes toda tu fuerza y te arrodillas a medias en el suelo."
  },
  AvgDialog_123117_Content_31 = {
    Text = "<Red:<Shake:¡Mata, mata, mata! ¡Mata a todos!>>"
  },
  AvgDialog_123117_Content_32 = {
    Text = "<Red:<Shake:¡Jajaja, destruye este mundo!>>"
  },
  AvgDialog_123117_Content_33 = {
    Text = "El hacha que una vez despejó el camino para ti se levanta en alto, pero viene hacia tu cabeza. Y tú, agotado por el extraño vínculo espiritual, pierdes la conciencia y no puedes moverte."
  },
  AvgDialog_123117_Content_34 = {
    Text = "<Shake:Mouchette...>"
  },
  AvgDialog_123117_Content_35 = {
    Text = "Luchas por hablar, pero tu voz es ronca y débil, incapaz de despertar la cordura de Mouchette."
  },
  AvgDialog_123117_Content_37 = {
    Text = "Al final, el hacha cayó pesadamente, hundiéndose en la carne y la sangre——\n en el último momento, Salvador se interpuso frente a ti, recibiendo el golpe."
  },
  AvgDialog_123117_Content_38 = {
    Text = "La sangre fluía por el hombro de Salvador, pero su expresión no mostraba rencor, solo compasión y bondad."
  },
  AvgDialog_123117_Content_39 = {
    Text = "Niño, sé que esto no es intencional de tu parte. Solo estás perdido."
  },
  AvgDialog_123117_Content_4 = {
    Text = "Mucho tiempo después, la plata y la sangre flotantes comenzaron a caer, aterrizando en el suelo y sobre ustedes, mientras la densa niebla a su alrededor se volvía visiblemente más ligera y se contraía, todo estaba mejorando."
  },
  AvgDialog_123117_Content_40 = {
    Text = "<Red:<Shake:¡Mata! ¡Mata, mata! ¡Destrucción del mundo!>>"
  },
  AvgDialog_123117_Content_41 = {
    Text = "La locura ha consumido por completo a Mouchette; en este momento, solo está impulsada por un violento impulso de destrucción y masacre."
  },
  AvgDialog_123117_Content_42 = {
    Text = "<Shake:Salvador, es inútil, ella...>"
  },
  AvgDialog_123117_Content_43 = {
    Text = "Miraste a Mouchette, que ya no podía ser considerada una \"persona\", y tu voz temblaba. \n Justo un momento antes, ella seguía tan viva."
  },
  AvgDialog_123117_Content_44 = {
    Text = "No, mensajero pálido. Ella solo está perdida."
  },
  AvgDialog_123117_Content_45 = {
    Text = "Salvador dio un paso adelante, avanzando hacia el hacha afilada levantada nuevamente por Mouchette."
  },
  AvgDialog_123117_Content_46 = {
    Text = "La sangre salpicó de la hoja del hacha sobre su rostro, sin embargo, Salvador no mostró ningún signo de miedo."
  },
  AvgDialog_123117_Content_47 = {
    Text = "Lo siento, no estuve allí cuando la Asamblea del Amanecer Estrellado realizó el ritual de sacrificio humano para convocarte."
  },
  AvgDialog_123117_Content_48 = {
    Text = "La gota de sangre del hacha de Mouchette resbaló por la mejilla de Salvador, como una lágrima."
  },
  AvgDialog_123117_Content_49 = {
    Text = "Salvador no limpió esta gota de \"lágrima\", solo que firmemente sostuvo el filo del hacha de Mouchette, mientras levantaba la otra mano——"
  },
  AvgDialog_123117_Content_5 = {
    Text = "Pronto, las anomalías de la Puerta de Dimensión se reducirán a su nivel más bajo, Mouchette, esa será tu mejor oportunidad para regresar a casa."
  },
  AvgDialog_123117_Content_50 = {
    Text = "Pero en este momento, estoy aquí para redimirte."
  },
  AvgDialog_123117_Content_51 = {
    Text = "La mano ensangrentada del sacerdote tocó la frente de la niña. En un instante, una luz deslumbrante y firme brilló desde el punto de contacto entre ellos."
  },
  AvgDialog_123117_Content_52 = {
    Text = "Ese es un sacerdote de un mundo, otorgando una bendición al cordero de otro mundo."
  },
  AvgDialog_123117_Content_53 = {
    Text = "Con la luz brillando, el intenso dolor en tu cabeza se desvaneció rápidamente, como si alguien hubiera asumido todo tu sufrimiento..."
  },
  AvgDialog_123117_Content_54 = {
    Text = "¡Salvador, detente! Esto implica una conexión de dimensión que nadie puede soportar!"
  },
  AvgDialog_123117_Content_55 = {Text = "Sé."},
  AvgDialog_123117_Content_56 = {
    Text = "La voz de Salvador tembló y se quebró. Este nivel de enlace era, incluso para él, una tortura que trascendía todos los límites."
  },
  AvgDialog_123117_Content_57 = {
    Text = "Pronto, ya no pudo soportarlo y fluyeron lágrimas de sangre."
  },
  AvgDialog_123117_Content_58 = {
    Text = "Pero como Ejecutor del Padre Dios, debo darlo todo."
  },
  AvgDialog_123117_Content_59 = {
    Text = "Más lágrimas de sangre fluyen desde la venda de Salvador, pero este color se ve afectado por la intensa luz de la \"Bendición\", como si lo que fluyera de los ojos de Salvador no fuera sangre, sino oro derretido."
  },
  AvgDialog_123117_Content_6 = {
    Text = "Mantendré la energía de la Llave de Plata al máximo, suficiente para que puedas cruzar la Dimensión de manera segura."
  },
  AvgDialog_123117_Content_60 = {
    Text = "Este oro cayó, goteando sobre el dorso de la mano de Mouchette, despojándose de su cáscara dorada, revelando su color rojo sangre, fusionándose con la sangre del sacrificio humano salpicada sobre Mouchette y con la propia sangre de Mouchette."
  },
  AvgDialog_123117_Content_61 = {
    Text = "En el nombre del Padre Dios, Mouchette, no permitiré que te desvíes del camino."
  },
  AvgDialog_123117_Content_62 = {
    Text = "Con este llamado, la frente de Mouchette estalló en una intensa luz, tan brillante que eclipsaba por completo la sangre que cubría su cuerpo y el resplandor de la Puerta Invisible."
  },
  AvgDialog_123117_Content_63 = {
    Text = "Esa es la radiancia que Salvador desató con toda su vida."
  },
  AvgDialog_123117_Content_64 = {
    Text = "<Shake:Ugh...>"
  },
  AvgDialog_123117_Content_65 = {
    Text = "En esta luz que ilumina todo, los ojos divididos obtienen un momento de claridad y, con la única razón que les queda, miran el dorso de sus manos."
  },
  AvgDialog_123117_Content_66 = {
    Text = "Ya no se ve la sangre de Salvador allí, porque toda la sangre ya se ha fusionado."
  },
  AvgDialog_123117_Content_67 = {
    Text = "La sangre de la víctima y del perpetrador, la sangre del culpable y del redentor, se entrelaza en el mismo río de sangre."
  },
  AvgDialog_123117_Content_68 = {
    Text = "Yo... he dicho..."
  },
  AvgDialog_123117_Content_69 = {
    Text = "<Shake:Odio... sacrificar a otros... para salvarme a mí mismo...>"
  },
  AvgDialog_123117_Content_7 = {
    Text = "Sería genial si pudiera ducharme antes de atravesar. Volver cubierto de sangre, no sé si asustaría al oficial de investigación."
  },
  AvgDialog_123117_Content_70 = {
    Text = "Mouchette empujó a Salvador con el último resto de su cordura y te miró.\n La viste levantar el hacha con todas sus fuerzas, y también la viste con lágrimas corriendo por su rostro."
  },
  AvgDialog_123117_Content_71 = {
    Text = "De ahora en adelante... no dejes que haga esto de nuevo... Los que realmente merecen vivir son personas como él..."
  },
  AvgDialog_123117_Content_72 = {
    Text = "Debido al ritual... la puerta invisible me ha hecho parte de él..."
  },
  AvgDialog_123117_Content_73 = {
    Text = "<Shake:Mátame, se disipará... esas personas... también serán liberadas...>"
  },
  AvgDialog_123117_Content_74 = {
    Text = "Y... esto no es deserción... es llevar al enemigo... contigo..."
  },
  AvgDialog_123117_Content_75 = {
    Text = "Mouchette, agotando sus últimas fuerzas, te pasó el hacha, y tú, al recibirla, solo pudiste quedarte paralizado en el lugar."
  },
  AvgDialog_123117_Content_76 = {
    Text = "Vaya... ¿por qué tomé... una decisión que ni siquiera puedo entender...?"
  },
  AvgDialog_123117_Content_77 = {
    Text = "Claramente, destruir el mundo es más acorde con mi estilo..."
  },
  AvgDialog_123117_Content_78 = {
    Text = "Mouchette sollozó, y al siguiente segundo, una gota de lágrima cayó sin aviso desde su pupila, deslizándose por su hacha y estallando en tu palma."
  },
  AvgDialog_123117_Content_79 = {
    Text = "Pronto, los ojos surcados por las lágrimas comenzaron a volverse confusos, lentamente gestando la locura.\nMouchette está a punto de perder la razón nuevamente."
  },
  AvgDialog_123117_Content_8 = {
    Text = "¿No deberíamos poner una mesa y traer algunos pastelitos para la merienda?"
  },
  AvgDialog_123117_Content_80 = {
    Text = "Mensajero Pálido, por favor no... La redimiré una vez más."
  },
  AvgDialog_123117_Content_81 = {
    Text = "Salvador se esforzó por levantarse y te pidió, mientras tú mirabas hacia abajo el hacha que pertenecía a Mouchette en tus manos, sintiéndote inquieto."
  },
  AvgDialog_123117_Content_82 = {
    Text = "No era solo un hacha; era una confianza de vida y una despedida."
  },
  AvgDialog_123117_Content_83 = {
    Text = "<Shake:Déjame un tiempo... debe haber otra manera... debe haber...>"
  },
  AvgDialog_123117_Content_84 = {
    Text = "De repente, un método cruel apareció en tu mente——"
  },
  AvgDialog_123117_Content_85 = {
    Text = "No te detuviste a pensar demasiado, agarraste la llave de plata con una mano y tomaste la mano de Mouchette con la otra, sumergiéndote en el pantano mental."
  },
  AvgDialog_123117_Content_86 = {
    Text = "La única solución que se te ocurre en este momento es transformar a Mouchette de humano a Despertado a la fuerza a través del vínculo de la Llave de Plata."
  },
  AvgDialog_123117_Content_87 = {
    Text = "En el momento en que te sumerges en la mente de Mouchette, innumerables puntos de luz retorciéndose y surgiendo invaden tu campo de visión. \n Todos están llorando y gritando, pero ninguno de ellos es Mouchette."
  },
  AvgDialog_123117_Content_88 = {
    Text = "En el Mundo espiritual de Mouchette, no hay Mouchette."
  },
  AvgDialog_123117_Content_89 = {
    Text = "¡Mouchette! ¿Dónde estás, Mouchette...?"
  },
  AvgDialog_123117_Content_9 = {
    Text = "Eso es aún mejor. Mirando este mundo aburrido y desordenado, los pastelitos seguramente sabrán aún más deliciosos."
  },
  AvgDialog_123117_Content_90 = {
    Text = "No hubo respuesta. Como persona ordinaria, esa última \"petición\" era el límite de lo que podía hacer bajo la locura y el colapso."
  },
  AvgDialog_123117_Content_91 = {
    Text = "¿Mouchette? ¿Has renunciado? Sí, dijiste que había algunas veces cada semana en las que no querías vivir, y siempre tenías la palabra \"muerte\" en la boca..."
  },
  AvgDialog_123117_Content_92 = {
    Text = "Pero, las cosas no son así... Salvador, ni yo, ni el oficial de investigación que siempre mencionas, queremos que esto suceda..."
  },
  AvgDialog_123117_Content_93 = {
    Text = "Así que, Mouchette, sal..."
  },
  AvgDialog_123117_Content_94 = {
    Text = "Sin embargo, no importa cuánto grites o busques, todo lo que te rodea son los aullidos y gritos locos."
  },
  AvgDialog_123117_Content_95 = {
    Text = "Mouchette \"ha desaparecido\"."
  },
  AvgDialog_123117_Content_96 = {
    Text = "...En realidad, pensé en una solución..."
  },
  AvgDialog_123117_Content_97 = {
    Text = "Es aprovechar el núcleo de plata que ha penetrado en tu cuerpo, transformarte en un Despertado. El riesgo de fracaso es muy alto, pero es la única forma que se me ocurre por ahora."
  },
  AvgDialog_123117_Content_98 = {
    Text = "<Small:Creía que lo más difícil de esto era el \"Despertar\", pero no pensé que ni siquiera podría encontrar tu cuerpo espiritual...>"
  },
  AvgDialog_123117_Content_99 = {
    Text = "Te sumiste en un largo silencio, sintiendo que cada respiración era increíblemente difícil. \n Como Guardián del Secreto, eres consciente del destino de las personas comunes cuando están expuestas a un exceso de Núcleo de plata."
  },
  AvgDialog_123118_Content_1 = {
    Text = "En la densa niebla sin límites, resuenan continuamente los desgarradores gritos de agonía."
  },
  AvgDialog_123118_Content_10 = {
    Text = "El amor del Padre Dios no puede salvar a cada uno, pero haremos todo lo posible para extender una mano amiga a cada víctima."
  },
  AvgDialog_123118_Content_11 = {
    Text = "<Shake:No... no llames más...>"
  },
  AvgDialog_123118_Content_12 = {
    Text = "Bajo el trauma psicológico, comenzó a sangrar incontrolablemente por la nariz."
  },
  AvgDialog_123118_Content_13 = {
    Text = "<Shake:¡Dije que <Big:no llames más...>>"
  },
  AvgDialog_123118_Content_15 = {
    Text = "Mouchette gritó con ira, y en su emoción, balanceó el hacha para golpear a aquellas figuras de niebla monstruosa, pero vio que la bruma se dividía en silencio y rápidamente se volvía a agrupar."
  },
  AvgDialog_123118_Content_16 = {
    Text = "Inútil. Mientras la niebla densa esté presente, estos monstruos no desaparecerán."
  },
  AvgDialog_123118_Content_17 = {
    Text = "Así que por eso nos pediste que \"ayudáramos\" a distraer a los monstruos, ¿verdad?"
  },
  AvgDialog_123118_Content_18 = {
    Text = "¿Ahora quieren ajustar cuentas conmigo? Hay una fila, retrocedan un poco..."
  },
  AvgDialog_123118_Content_19 = {
    Text = "Mouchette se limpió la sangre de la nariz y continuó balanceando el hacha. La sensación de la batalla la hacía sentir tan emocionada que no podía detenerse."
  },
  AvgDialog_123118_Content_2 = {
    Text = "@2... ¡Ayúdame@2...!"
  },
  AvgDialog_123118_Content_20 = {
    Text = "¡Ya que no hay forma de retirarse ahora, mejor aguantemos esta oleada primero!"
  },
  AvgDialog_123118_Content_21 = {
    Text = "¡Mouchette, ten un poco de cordura! Si sigues así, tú..."
  },
  AvgDialog_123118_Content_22 = {
    Text = "¿Vas a morir, verdad?"
  },
  AvgDialog_123118_Content_23 = {
    Text = "De todos modos, hay algunas veces cada semana en las que no quiero vivir, justo en ese momento..."
  },
  AvgDialog_123118_Content_24 = {
    Text = "Las palabras de Mouchette se interrumpieron de repente. Una luz brilló de repente frente a ella, y luego una sensación de calidez se derramó sobre su cuerpo, fluyendo hacia sus extremidades."
  },
  AvgDialog_123118_Content_25 = {
    Text = "Salvador \"bendición\" a ella."
  },
  AvgDialog_123118_Content_26 = {
    Text = "<Shake:¿Qué estás haciendo?!>"
  },
  AvgDialog_123118_Content_27 = {
    Text = "Mouchette no pudo evitar retroceder un paso.\n Esa sensación cálida era demasiado extraña. No debería aparecer en ella."
  },
  AvgDialog_123118_Content_28 = {
    Text = "Nosotros, somos enemigos, ¿por qué...?"
  },
  AvgDialog_123118_Content_29 = {
    Text = "Dije que no somos enemigos."
  },
  AvgDialog_123118_Content_3 = {
    Text = "¡Ayuda@2... @2 me..."
  },
  AvgDialog_123118_Content_30 = {
    Text = "¡No ser un enemigo no significa ser un compañero!"
  },
  AvgDialog_123118_Content_31 = {
    Text = "No sería lo suficientemente ingenuo como para considerar a alguien a quien solo he conocido unas pocas veces como un compañero..."
  },
  AvgDialog_123118_Content_32 = {
    Text = "Pero ya hemos luchado juntos contra esos seguidores de culto, ¿verdad? Aquellos que luchan codo a codo son compañeros."
  },
  AvgDialog_123118_Content_33 = {
    Text = "Por cierto, no creo que esta sea mi aburrida teoría de amar a todos y que todos me amen; prefiero..."
  },
  AvgDialog_123118_Content_34 = {
    Text = "Prefiero entenderlo como la sabiduría de la supervivencia en este mundo cruel."
  },
  AvgDialog_123118_Content_35 = {
    Text = "La luz del Padre Dios se extiende sobre toda la tierra; incluso en las tierras de aniquilación, los hermanos y hermanas se apoyarán mutuamente."
  },
  AvgDialog_123118_Content_36 = {
    Text = "Mouchette mantenía los labios apretados, en silencio. Su mirada seguía siendo cautelosa y sospechosa, pero finalmente, esa cautela y sospecha se desvanecieron lentamente, transformándose en una confusión y un ligero anhelo."
  },
  AvgDialog_123118_Content_37 = {
    Text = "Sus labios se movieron, pareciendo susurrar algo, pero debido a que el sonido era demasiado bajo, solo pudiste escuchar vagamente las palabras \"Oficial de investigación\"."
  },
  AvgDialog_123118_Content_38 = {
    Text = "Pensaremos en las bajas la próxima vez; todavía tengo a alguien a quien encontrar para regresar."
  },
  AvgDialog_123118_Content_39 = {
    Text = "¿Te refieres al oficial de investigación...?"
  },
  AvgDialog_123118_Content_4 = {
    Text = "<Shake:¡Deja de llamar! ¿Por qué estas nieblas... siempre están aullando?!>"
  },
  AvgDialog_123118_Content_40 = {
    Text = "Antes de que Mouchette pudiera responder, un tipo de impacto invisible se precipitó, haciendo que se te erizara el cabello al mismo tiempo que volvía a los monstruos en la niebla aún más frenéticos."
  },
  AvgDialog_123118_Content_41 = {
    Text = "Este sentimiento...<Shake:<Big:¡El ritual ha comenzado!>>"
  },
  AvgDialog_123118_Content_42 = {
    Text = "¿El ritual comienza? Pero claramente salvamos a esos sacrificios humanos."
  },
  AvgDialog_123118_Content_43 = {
    Text = "Y, mensajero pálido, no había sacerdotes del Santuario de Vida entre los cautivos hace un momento..."
  },
  AvgDialog_123118_Content_44 = {
    Text = "¿Las personas que salvamos son solo refuerzos? ¿O el momento del ritual está fijado, por lo que debe llevarse a cabo incluso si no hay suficientes sacrificios humanos?"
  },
  AvgDialog_123118_Content_45 = {
    Text = "Ahora no hay tiempo para hacer de detective."
  },
  AvgDialog_123118_Content_46 = {
    Text = "¿Van a seguir parloteando aquí o vendrán conmigo? ¡Tomen una decisión rápido!"
  },
  AvgDialog_123118_Content_47 = {
    Text = "Mouchette mostró una expresión de impaciencia, se dio la vuelta, dándoles la espalda, y entró en la densa niebla."
  },
  AvgDialog_123118_Content_48 = {
    Text = "¡Mouchette!"
  },
  AvgDialog_123118_Content_49 = {
    Text = "Sé lo que te preocupa. Esta vez, no haré trucos."
  },
  AvgDialog_123118_Content_5 = {
    Text = "Debido a esta densa niebla, puede que no sea el \"Desastre de Niebla\" de tu mundo, y estos monstruos no son los \"Objetos Antiguos\" de los que hablas."
  },
  AvgDialog_123118_Content_50 = {
    Text = "Mouchette balanceaba su hacha para dispersar la niebla humana que la estaba emboscando mientras respondía."
  },
  AvgDialog_123118_Content_51 = {
    Text = "Aunque su optimismo es bastante problemático y algunas de sus palabras están llenas de idealismo poco realista que necesitan ser sacadas a la luz, pero..."
  },
  AvgDialog_123118_Content_52 = {
    Text = "Pero siempre hay algunas personas que insisten en salvar este aburrido mundo.\n<Small:Tú eres así, al igual que el oficial de investigación...>"
  },
  AvgDialog_123118_Content_53 = {
    Text = "¿Quizás ustedes se llevan bien?"
  },
  AvgDialog_123118_Content_54 = {
    Text = "¿Se ha desviado un poco el tema...? Esos sacrificios humanos todavía nos están esperando..."
  },
  AvgDialog_123118_Content_55 = {
    Text = "¿Entonces, por qué no estás corriendo aún? Espero que esto termine pronto; quiero ir a casa."
  },
  AvgDialog_123118_Content_56 = {
    Text = "¡Vamos, mantente a mi lado, no te quedes atrás! ¡Soy la vanguardia más rápida del Grupo de investigación del Reino de la Niebla!"
  },
  AvgDialog_123118_Content_57 = {
    Text = "La silueta de Mouchette corría hacia adelante a través de la densa niebla, y tú intercambiaste una mirada con Salvador antes de seguirla."
  },
  AvgDialog_123118_Content_6 = {
    Text = "<Shake:¿Ellos... qué son?>"
  },
  AvgDialog_123118_Content_7 = {
    Text = "Mouchette no pudo evitar cubrirse los oídos, pero desgraciadamente, fue en vano."
  },
  AvgDialog_123118_Content_8 = {
    Text = "El dolor y la desesperación se filtran lentamente en la carne y los huesos del oyente con la densa niebla, llegando hasta el alma."
  },
  AvgDialog_123118_Content_9 = {
    Text = "Puedo discernir que sus almas... son los sacrificios humanos del último ritual."
  },
  AvgDialog_123119_Content_1 = {
    Text = "Entre dimensiones"
  },
  AvgDialog_123119_Content_10 = {
    Text = "Mouchette se encogió de hombros, levantó la mano y señaló la Puerta de Dimensión que estaba expulsando continuamente bruma espesa, corrompiendo este mundo."
  },
  AvgDialog_123119_Content_100 = {
    Text = "No, %player%, espera un momento..."
  },
  AvgDialog_123119_Content_101 = {
    Text = "Mouchette quiere detener tu rescate. Después de conocer sobre la experiencia de \"tú\", su corazón está lleno de dudas y preguntas."
  },
  AvgDialog_123119_Content_102 = {
    Text = "Pero no queda tiempo. Una sensación de tirón desde el alma la está arrastrando, llevándola obstinadamente lejos de este extraño mundo lleno de puntos de luz."
  },
  AvgDialog_123119_Content_103 = {
    Text = "Y el punto de luz que la iluminaba estaba allí, ni lejos ni cerca, emanando una buena voluntad suave y cálida, despidiéndola por última vez."
  },
  AvgDialog_123119_Content_104 = {
    Text = "Muestra la información @4 a @3 \"yo\", y podrás @2 volver a casa @1."
  },
  AvgDialog_123119_Content_105 = {
    Text = "@2, adiós, Mouchette, @2... otro\"Yo\"."
  },
  AvgDialog_123119_Content_106 = {
    Text = "Pronto, ese zumbido inmaterial se distorsionó, se disipó y finalmente desapareció por completo, llevándose consigo la vista, el oído y varios sentidos de Mouchette."
  },
  AvgDialog_123119_Content_107 = {
    Text = "Cuando Mouchette recuperó de nuevo la vista y el oído, volviendo a la realidad, vio de nuevo esa figura familiar, la que no podía comprender."
  },
  AvgDialog_123119_Content_108 = {
    Text = "Mouchette, sal de aquí, Salvador y yo nos encargaremos de lo demás."
  },
  AvgDialog_123119_Content_109 = {
    Text = "La corrosión de la \"Puerta\" se está profundizando, y el mensajero pálido y yo tenemos que prepararnos para lo peor..."
  },
  AvgDialog_123119_Content_11 = {
    Text = "Entonces, debo ir, solo yo puedo ir."
  },
  AvgDialog_123119_Content_110 = {Text = "..."},
  AvgDialog_123119_Content_111 = {
    Text = "¿Mouchette? ¿En qué estás pensando? Sal de aquí rápido."
  },
  AvgDialog_123119_Content_112 = {
    Text = "Mirándote, una mezcla de enojo, ira y compasión se entrelazaba en el pecho de Mouchette, dejándola sin palabras."
  },
  AvgDialog_123119_Content_113 = {
    Text = "Finalmente, exhaló con furia, apretó los puños y habló a regañadientes:"
  },
  AvgDialog_123119_Content_114 = {
    Text = "Desde la primera vez que nos conocimos, debí haberlo sabido, eres ese tipo de \"protagonista\" entusiasta y entrometido, una clase de persona que nunca podré entender."
  },
  AvgDialog_123119_Content_115 = {
    Text = "Incluso después de 100 años, no podré entender tus circuitos cerebrales. Así que me he rendido."
  },
  AvgDialog_123119_Content_116 = {Text = "¿Qué?"},
  AvgDialog_123119_Content_117 = {
    Text = "Sé el valor de la onda de vibración del que hablas, esto es otro @4@3..."
  },
  AvgDialog_123119_Content_118 = {
    Text = "Un dolor punzante familiar apareció, distorsionando las palabras de Mouchette. Después de varios intentos fallidos de expresar la realidad de esos puntos de luz, Mouchette se rindió."
  },
  AvgDialog_123119_Content_119 = {
    Text = "La niña sustituyó las palabras con acción, sosteniendo firmemente tu mano, su cara mostrando una determinación inquebrantable."
  },
  AvgDialog_123119_Content_12 = {
    Text = "En sus palabras, es... oh, la sabiduría de sobrevivir en este cruel mundo."
  },
  AvgDialog_123119_Content_120 = {
    Text = "Te ayudaré a resolver este gran lío contigo."
  },
  AvgDialog_123119_Content_121 = {
    Text = "Yo, Mouchette, la vanguardia del Grupo de investigación que ha llamado la atención, no terminaré esta batalla con la identidad de \"desertor\"."
  },
  AvgDialog_123119_Content_13 = {
    Text = "Al escuchar el discurso de Mouchette, tú y Salvador cayeron en silencio, luego hablaron al mismo tiempo——"
  },
  AvgDialog_123119_Content_14 = {
    Text = "No estoy de acuerdo, hijo. El que debería hacer el sacrificio soy yo."
  },
  AvgDialog_123119_Content_15 = {
    Text = "Estoy de acuerdo. Prometo rescatarte y enviarte a casa, sin importar el costo."
  },
  AvgDialog_123119_Content_16 = {
    Text = "Al mismo tiempo, expresando opiniones completamente opuestas, tú y Salvador no pudieron evitar mirarse."
  },
  AvgDialog_123119_Content_17 = {
    Text = "%player%, ¿por qué...?"
  },
  AvgDialog_123119_Content_18 = {
    Text = "Así que se queda así, te encargarás de volver a casa, %player%."
  },
  AvgDialog_123119_Content_19 = {
    Text = "Mouchette interrumpe a ti y a Salvador, caminando hacia esa \"Puerta\" desconocida y ominosa antes de que ustedes pudieran reaccionar."
  },
  AvgDialog_123119_Content_2 = {
    Text = "¿Mouchette, estás diciendo que vas a entrar en esa \"Puerta\" desconocida...?"
  },
  AvgDialog_123119_Content_20 = {
    Text = "Con una mano sujetando firmemente la llave de plata y la otra tirando de Salvador con fuerza, te concentraste intensamente en la figura de Mouchette, sin atreverte a parpadear."
  },
  AvgDialog_123119_Content_21 = {
    Text = "Salvador, escúchame, tal vez... Mouchette es diferente."
  },
  AvgDialog_123119_Content_22 = {
    Text = "Esta es la puerta que conecta con otra dimensión, y Mouchette viene de esa dimensión, incluso fue convocada por el mismo ritual."
  },
  AvgDialog_123119_Content_23 = {
    Text = "Pero... ¿y si...?"
  },
  AvgDialog_123119_Content_24 = {
    Text = "Si algo sale mal, activaré la llave de plata y transferiré el enlace a mí mismo."
  },
  AvgDialog_123119_Content_25 = {
    Text = "Salvador te mira a los ojos, tratando de aparentar calma, y al ver que sostienes con fuerza la llave de plata, finalmente suspira."
  },
  AvgDialog_123119_Content_26 = {
    Text = "Si llega ese momento, por favor déjame compartir la carga."
  },
  AvgDialog_123119_Content_27 = {
    Text = "El mensajero pálido, nunca te dejaré caer antes que yo."
  },
  AvgDialog_123119_Content_28 = {
    Text = "Tu respuesta es una sonrisa de comprensión."
  },
  AvgDialog_123119_Content_29 = {
    Text = "Mientras tanto, Mouchette está levantando la mano, tratando de tocar la Puerta intangible."
  },
  AvgDialog_123119_Content_3 = {
    Text = "No solo tú, incluso Salvador se quedó atónito."
  },
  AvgDialog_123119_Content_30 = {
    Text = "<Shake:Esto es...>"
  },
  AvgDialog_123119_Content_31 = {
    Text = "En el momento en que Mouchette tocó la Puerta Invisible, de repente emitió una luz intensa como antes."
  },
  AvgDialog_123119_Content_32 = {
    Text = "Al mismo tiempo, también activaste la llave de plata."
  },
  AvgDialog_123119_Content_33 = {
    Text = "El resplandor que emana de la llave de plata responde a la luz de la puerta invisible, y la vasta cantidad de plata y sangre parece seguir una guía invisible, hirviendo y surgiendo."
  },
  AvgDialog_123119_Content_34 = {
    Text = "Bajo la combinación de los dos, resuena un zumbido desconocido que puede erosionar el alma, mezclándose con una niebla densa e interminable, impactando todo a su alrededor, sumergiendo a todos los presentes en un cierto estado hipnótico de separación del alma y la carne..."
  },
  AvgDialog_123119_Content_35 = {
    Text = "El mundo@2 es vago, como@2@1 como una densa niebla, @3, hay algo@2 gestando en este oblivion@3."
  },
  AvgDialog_123119_Content_36 = {
    Text = "@1Solo que la gran @4Ilusión es un accidente, esta pequeña @2sin embargo, lucha, se retuerce, evoluciona, transformándose en @4raza."
  },
  AvgDialog_123119_Content_37 = {
    Text = "En la oscuridad resonó un sonido de flauta distorsionada y caótica, desgastando la voluntad de Mouchette; aunque era música, ella vislumbró vagamente el terroroso significado detrás de ella."
  },
  AvgDialog_123119_Content_38 = {
    Text = "Humanos, esto es lo que @3 se llama a sí mismo. En comparación con el infinito universo @1, @2 es @4 diminuto y efímero."
  },
  AvgDialog_123119_Content_39 = {
    Text = "@3 no significa que @3 no haya dejado, fluyendo de generación en generación @1 sangre y plata, @4@2 marcas @1 evidencia."
  },
  AvgDialog_123119_Content_4 = {
    Text = "Así es. Voy a entrar y ayudarte a investigar esa onda de vibración."
  },
  AvgDialog_123119_Content_40 = {
    Text = "El sonido distorsionado de la flauta del Caos se volvió cada vez más agudo y aterrador, como si estuviera torturando el alma de Mouchette. Ella ya no podía soportarlo más y de repente abrió los ojos."
  },
  AvgDialog_123119_Content_41 = {
    Text = "Después de abrir los ojos, Mouchette no escuchó el sonido de la flauta, ni vio a ningún músico. A su alrededor, todo era extraño y colorido, solo había grandes manchas de luz que la rodeaban, manteniendo una distancia ni muy cerca ni muy lejos."
  },
  AvgDialog_123119_Content_42 = {
    Text = "¡Me alegra verte, Mouchette, \"Yo\" amigo/a."
  },
  AvgDialog_123119_Content_43 = {
    Text = "El punto de luz emitió un zumbido, y, extrañamente, ella podía entenderlo por completo. \n O más bien, en este momento, ella también era el punto de luz."
  },
  AvgDialog_123119_Content_44 = {
    Text = "¿He muerto? Así que esto es lo que se siente al morir..."
  },
  AvgDialog_123119_Content_45 = {
    Text = "No, todavía estás vivo. Solo te he traído aquí. Hay un rastro de\"yo\"en ti."
  },
  AvgDialog_123119_Content_46 = {
    Text = "Si no hago esto, sufrirás por el fracaso del cruce dimensional @4, porque ya has estado @3."
  },
  AvgDialog_123119_Content_47 = {
    Text = "Mouchette no escuchó las últimas palabras de los puntos de luz, porque en el momento en que resonaron las caóticas sílabas, su cabeza comenzó a doler intensamente, casi a estallar."
  },
  AvgDialog_123119_Content_48 = {
    Text = "<Shake:¡Detente! ¡Detente! Di algo que pueda escuchar... Si esto sigue así, ¡mi cabeza va a explotar.>"
  },
  AvgDialog_123119_Content_49 = {
    Text = "Ella parecía escuchar el suspiro del punto de luz, o tal vez no, porque innumerables piezas extrañas de información inundaron la mente de Mouchette, capturando toda su atención."
  },
  AvgDialog_123119_Content_5 = {
    Text = "Niño, no entiendes los peligros involucrados. El trauma de la Dimensión espiritual también puede afectar el mundo real, y tú..."
  },
  AvgDialog_123119_Content_50 = {
    Text = "¿Qué es esto?"
  },
  AvgDialog_123119_Content_51 = {
    Text = "Lo que necesitan en este momento. Muéstramelo, {Male=él,Female=ella} entenderá."
  },
  AvgDialog_123119_Content_52 = {
    Text = "Lo que yo, tuyo, no puedo entender——"
  },
  AvgDialog_123119_Content_53 = {
    Text = "Espera, ¿eres... %player%?"
  },
  AvgDialog_123119_Content_54 = {
    Text = "Eso es imposible. Te acabo de ver lleno de vida; pareces como si pudieras vivir otros cien años sin ningún problema."
  },
  AvgDialog_123119_Content_55 = {
    Text = "El punto de luz zumbó y emitió una suave risa; Mouchette no sabía si esto podía llamarse una \"risa\", ya que no contenía alegría. Para ser precisos, no tenía emociones en absoluto."
  },
  AvgDialog_123119_Content_56 = {
    Text = "Puedes entenderlo como el \"yo\" de otra dimensión, y yo, el verdadero yo——"
  },
  AvgDialog_123119_Content_57 = {
    Text = "Con las palabras de los puntos de luz, innumerables fragmentos de información inundaron la mente de Mouchette. Estos fragmentos de información seguían dividiéndose y fusionándose, formando imágenes inestables."
  },
  AvgDialog_123119_Content_58 = {
    Text = "Al principio, estas imágenes eran abstractas y moteadas, vagas e indistintas, pero pronto—"
  },
  AvgDialog_123119_Content_59 = {
    Text = "Esas luces y sombras extrañas se unieron en una figura, una figura que ella reconoció."
  },
  AvgDialog_123119_Content_6 = {
    Text = "Soy el único adecuado aquí. Aunque soy un poco simple, no soy tonto."
  },
  AvgDialog_123119_Content_60 = {
    Text = "La figura familiar despierta en medio de una explosión, mirando este mundo con confusión."
  },
  AvgDialog_123119_Content_61 = {
    Text = "Muchos años después, la gente se referirá a esta explosión como la \"Explosión de Akut.\""
  },
  AvgDialog_123119_Content_62 = {
    Text = "Luego, {Male=él,Female=ella} entró en Misaq, obtuvo la Llave de plata y se convirtió en el \"Guardián del secreto\", comenzando a salir en misiones con sus compañeros llamados \"Despertados\" para investigar este extraño y aterrador mundo."
  },
  AvgDialog_123119_Content_63 = {
    Text = "Así como ella, el Oficial de investigación y el Grupo de investigación del Reino de la Niebla."
  },
  AvgDialog_123119_Content_64 = {Text = "..."},
  AvgDialog_123119_Content_65 = {
    Text = "Recordando a esas personas y momentos familiares, Mouchette suspiró con nostalgia. Y sobre la vida de %player%, sigue adelante——"
  },
  AvgDialog_123119_Content_66 = {
    Text = "Ella vio a %player% atravesando el pueblo cubierto de nieve, enfrentándose al sabueso que atraviesa el tiempo y el espacio en el sanatorio lleno de secretos, testificando la eternidad del amor familiar."
  },
  AvgDialog_123119_Content_67 = {
    Text = "También he seguido a %player% para recorrer la Cité, llena de poesía y flores, escuchando los suspiros de las llamas y lamentando el marchitarse de las rosas."
  },
  AvgDialog_123119_Content_68 = {
    Text = "Y hay barcos fantasmas flotando en el mar. Fe, deidades, ritual de sacrificio, ella junto con %player% ha llegado a comprender las distorsiones, la crueldad y la locura de este mundo."
  },
  AvgDialog_123119_Content_69 = {
    Text = "Pero no importa cuán peligroso sea el lugar, no ha derrotado a %player% ni al compañero de {Male=él,Female=ella}."
  },
  AvgDialog_123119_Content_7 = {
    Text = "Mouchette interrumpió a Salvador, mirándolos con seriedad."
  },
  AvgDialog_123119_Content_70 = {
    Text = "Así como en ese mundo, la Catástrofe de niebla, la Ceniza y las Antigüedades no pudieron derrotarla a ella y al Oficial de investigación, ni tampoco al Grupo de investigación del Reino de la Niebla."
  },
  AvgDialog_123119_Content_71 = {
    Text = "¡Eso es algo!"
  },
  AvgDialog_123119_Content_72 = {
    Text = "¿No sé cómo estarán esos pequeños en la niebla ahora?"
  },
  AvgDialog_123119_Content_73 = {
    Text = "¡Ay, realmente quiero disfrutar de una humeante taza de té kava de avellana!"
  },
  AvgDialog_123119_Content_74 = {
    Text = "Mouchette sonrió. \n Pensó que %player% lucharía junto a los Despertados para siempre——"
  },
  AvgDialog_123119_Content_75 = {
    Text = "Es natural, porque ella nunca pensó en dejar el Grupo de Investigación de la Niebla, y esos Despertados naturalmente no pensarían en dejar a sus Guardianes del Secreto."
  },
  AvgDialog_123119_Content_76 = {
    Text = "Lucharán y lucharán hasta que los problemas del mundo se resuelvan, o hasta que sean resueltos por el mundo.\nAsí como en todas las historias."
  },
  AvgDialog_123119_Content_77 = {
    Text = "Pero este mundo es mucho más cruel de lo que Mouchette imaginaba, mucho más que el que habita Mouchette."
  },
  AvgDialog_123119_Content_78 = {
    Text = "<Shake:¡¿Cómo puede ser esto!!>"
  },
  AvgDialog_123119_Content_79 = {
    Text = "¿Entonces tú...!?"
  },
  AvgDialog_123119_Content_8 = {
    Text = "Salvador, tu habilidad es la base para mantenernos a salvo en la niebla densa, y %player%, claramente, tu llave de plata también es muy importante."
  },
  AvgDialog_123119_Content_80 = {
    Text = "Tú, no debería esperar que renuncies a salvar este aburrido mundo."
  },
  AvgDialog_123119_Content_81 = {
    Text = "El sacrificio de salvar a otros... esa cosa..."
  },
  AvgDialog_123119_Content_82 = {
    Text = "Mouchette no pudo continuar, porque tanto la ira como la rabia ya eran inútiles."
  },
  AvgDialog_123119_Content_83 = {
    Text = "%player% es de hecho amigo de Mouchette, pero Mouchette, sin embargo, es solo un transeúnte en este mundo."
  },
  AvgDialog_123119_Content_84 = {
    Text = "Lo que separa a los dos no es solo una \"dimensión\", sino también dos \"mundos\" completamente diferentes."
  },
  AvgDialog_123119_Content_85 = {
    Text = "En realidad, mi sueño es sentarme junto a una chimenea acogedora con la persona que amo, desperdiciando nuestra vida, que no tiene valor."
  },
  AvgDialog_123119_Content_86 = {
    Text = "La nieve cae lentamente fuera de la ventana, año tras año, hasta que muramos de viejos. Entonces, en mi lápida estará escrito: {Male=él,Female=ella} era un derrochador de larga vida y feliz."
  },
  AvgDialog_123119_Content_87 = {
    Text = "Hasta ahora, mis sueños nunca han cambiado."
  },
  AvgDialog_123119_Content_88 = {
    Text = "Entonces ve y cumple este sueño, ¿qué importa si el mundo se destruye? ¿Qué importa si este aburrido mundo se destruye!?"
  },
  AvgDialog_123119_Content_89 = {
    Text = "¡Mejor que quedarme con un arrepentimiento eterno, atrapado en este lugar maldito solo para siempre!"
  },
  AvgDialog_123119_Content_9 = {
    Text = "Si algo te sucede, nadie podrá solucionar ese problema."
  },
  AvgDialog_123119_Content_90 = {
    Text = "Los puntos de luz rieron suavemente de nuevo, pero Mouchette ya no podía discernir si había algún humor en ese sonido. \n Porque su corazón estaba lleno de amargura."
  },
  AvgDialog_123119_Content_91 = {
    Text = "También quiero lograr este sueño, realmente, realmente lo deseo, pero..."
  },
  AvgDialog_123119_Content_92 = {
    Text = "En este mundo cruel, siempre tomaremos algunas \"decisiones\", algunas elecciones que ni siquiera podemos entender."
  },
  AvgDialog_123119_Content_93 = {
    Text = "Quizás no sea completamente incomprensible. Aunque no he probado una humeante taza de té kava de avellana, tengo mis propias cosas favoritas."
  },
  AvgDialog_123119_Content_94 = {
    Text = "Los pastelitos de Murphy, la danza de Liz, e incluso las tareas adicionales que siempre asigna Doll, ahora que lo pienso, están llenas de diversión..."
  },
  AvgDialog_123119_Content_95 = {
    Text = "Basta, no digas más. Eres un caso perdido..."
  },
  AvgDialog_123119_Content_96 = {
    Text = "¡Mouchette! ¡Mouchette!"
  },
  AvgDialog_123119_Content_97 = {
    Text = "De repente, un sonido resonó en la mente de Mouchette. Y ella, en el primer momento, reconoció a la otra persona."
  },
  AvgDialog_123119_Content_98 = {
    Text = "Después de ver la lucha y el sacrificio de\"{Male=él,Female=ella}\"para salvar el mundo, ella piensa que será difícil olvidar esa voz, esa persona."
  },
  AvgDialog_123119_Content_99 = {
    Text = "¡Espera, Salvador y yo te sacaremos pronto! Lo prometí."
  },
  AvgDialog_123120_Content_1 = {
    Text = "Ofrecerse como sacrificio"
  },
  AvgDialog_123120_Content_10 = {
    Text = "¿Sacerdote Salvador...?"
  },
  AvgDialog_123120_Content_100 = {
    Text = "No sé hasta qué punto se propagará esta maldita cosa, si realmente es igual a mi mundo..."
  },
  AvgDialog_123120_Content_101 = {
    Text = "Mouchette no continuó, pero entendiste su subtexto—"
  },
  AvgDialog_123120_Content_102 = {
    Text = "Catástrofe de niebla, es una calamidad que puede afectar a todo un mundo."
  },
  AvgDialog_123120_Content_103 = {
    Text = "Debemos terminar este ritual a cualquier costo...<Shake:¡Salvador!>"
  },
  AvgDialog_123120_Content_104 = {
    Text = "Estoy aquí. Aseguraré su seguridad... y también haré que estos perdidos encuentren la verdadera redención..."
  },
  AvgDialog_123120_Content_105 = {
    Text = "Luego, una luz cálida y suave apareció de repente alrededor de Salvador, extendiéndose hacia ti y Mouchette, aislándolos del daño de la catástrofe de niebla."
  },
  AvgDialog_123120_Content_106 = {
    Text = "Mouchette, para cerrar esta fisura espacial, necesito medir y determinar la onda de vibración de la dimensión espiritual, así que te dejo la batalla a ti."
  },
  AvgDialog_123120_Content_107 = {
    Text = "¿Batalla? ¡Sin problema! ¡Conmigo cerca, definitivamente no perderás ni un solo cabello!"
  },
  AvgDialog_123120_Content_108 = {
    Text = "Después de tanto tiempo, finalmente puedo desahogarme——"
  },
  AvgDialog_123120_Content_109 = {
    Text = "¡A todos, jóvenes y ancianos, les encanta!\n<Big:¡Tornado☆Resplandeciente——!!>"
  },
  AvgDialog_123120_Content_11 = {
    Text = "Salvador permaneció en silencio, respiró hondo y luego exhaló pesadamente."
  },
  AvgDialog_123120_Content_111 = {
    Text = "Un hacha vuela, dispersando una serie de nieblas humanoides, creando un breve camino de seguridad para que te acerques a la puerta desconocida que continuamente exhala densa niebla."
  },
  AvgDialog_123120_Content_112 = {
    Text = "Y tú, operando constantemente el instrumento de medición, intentando capturar las ondas de vibración de diferentes dimensiones."
  },
  AvgDialog_123120_Content_113 = {
    Text = "Un minuto pasó en silencio.\nDos minutos pasaron en silencio."
  },
  AvgDialog_123120_Content_114 = {
    Text = "Luego vinieron tres minutos, cinco minutos, diez minutos..."
  },
  AvgDialog_123120_Content_115 = {
    Text = "El sudor cae de tu frente, nunca has sentido que el tiempo sea tan largo."
  },
  AvgDialog_123120_Content_116 = {
    Text = "¿Cuánto tiempo más? Siento que estos monstruos parecen haberse vuelto más fuertes; se necesitan varios golpes para desmembrarlos..."
  },
  AvgDialog_123120_Content_117 = {
    Text = "Eso es una manifestación de otra dimensión tratando de invadir y devorar nuestro mundo, ¿no es así, mensajero pálido?"
  },
  AvgDialog_123120_Content_118 = {
    Text = "Otra gota de sudor cae de tu frente, y en tu estado de tensión, incluso olvidas asentir."
  },
  AvgDialog_123120_Content_119 = {
    Text = "Onda de vibración... está cambiando constantemente..."
  },
  AvgDialog_123120_Content_12 = {
    Text = "No es necesario buscar más, Padre White... está aquí."
  },
  AvgDialog_123120_Content_120 = {
    Text = "Podría ser debido a la niebla misma, o quizás a la interferencia de las almas atrapadas en ella... Necesito tiempo para investigar."
  },
  AvgDialog_123120_Content_121 = {
    Text = "Miras hacia el cielo, y en ese momento ya no puedes ver las \"Estrellas\". \n Todo el mundo parece estar cubierto solo por una densa niebla, y la Puerta de Dimensión que sigue escupiendo niebla."
  },
  AvgDialog_123120_Content_122 = {
    Text = "Pero no tenemos tiempo."
  },
  AvgDialog_123120_Content_123 = {
    Text = "...Tienes toda la razón."
  },
  AvgDialog_123120_Content_124 = {
    Text = "Guardas el instrumento de medición y levantas la mano para aferrar la llave de plata."
  },
  AvgDialog_123120_Content_125 = {
    Text = "Parece que solo puedo arriesgarme una vez..."
  },
  AvgDialog_123120_Content_126 = {
    Text = "Mensajero Pálido, ¿quieres conectarte...?"
  },
  AvgDialog_123120_Content_127 = {
    Text = "Salvador frunce el ceño, mirándote con desaprobación. Y tú, solo guardas silencio."
  },
  AvgDialog_123120_Content_128 = {
    Text = "¡Hola, hola! Aquí hay un \"invitado del otro mundo\". ¿Puedes decir algo que pueda entender?"
  },
  AvgDialog_123120_Content_129 = {
    Text = "El significado de %player% es... conectar esa \"Puerta\" desconocida para determinar la onda de vibración de la dimensión."
  },
  AvgDialog_123120_Content_13 = {
    Text = "Esa persona en el altar... es White."
  },
  AvgDialog_123120_Content_130 = {
    Text = "¿Qué? Esa cosa es muy extraña, ¿quién sabe cuál será el resultado? No hagas nada estúpido."
  },
  AvgDialog_123120_Content_131 = {
    Text = "Apretrás la llave de plata con fuerza y caminas hacia la puerta de luz intangible con una expresión grave. En este momento, la acción supera a las palabras."
  },
  AvgDialog_123120_Content_132 = {
    Text = "Realmente estoy impresionado por ustedes, que piensan que este aburrido mundo aún tiene valor para ser salvado..."
  },
  AvgDialog_123120_Content_133 = {
    Text = "Inesperadamente, Mouchette extendió la mano para detenerte. Su expresión era compleja mientras te miraba, como si te estuviera viendo, pero al mismo tiempo, mirando a través de ti, viendo a otra persona."
  },
  AvgDialog_123120_Content_134 = {
    Text = "Al final, todos los enredos se convirtieron en una sonrisa en su rostro, y Mouchette se esforzó por hacer que su voz sonara relajada."
  },
  AvgDialog_123120_Content_135 = {
    Text = "Olvídalo, ¿quién dijo que soy la vanguardia más destacada del grupo de investigación? Es natural estar al frente—"
  },
  AvgDialog_123120_Content_136 = {
    Text = "Así que, déjame ir."
  },
  AvgDialog_123120_Content_137 = {
    Text = "Mouchette te mira, con una expresión seria y firme."
  },
  AvgDialog_123120_Content_138 = {
    Text = "Desde una esquina de la jaula, esta es la primera vez que muestra una expresión tan seria."
  },
  AvgDialog_123120_Content_14 = {Text = "¿Qué!?"},
  AvgDialog_123120_Content_15 = {
    Text = "En shock, no pudiste evitar volverte hacia White, viendo al ex sacerdote del Santuario de Vida, ahora el líder de un culto, hablando apasionadamente."
  },
  AvgDialog_123120_Content_16 = {
    Text = "En este momento, tomamos una decisión a costa de plata y sangre, y nunca nos arrepentiremos de ello."
  },
  AvgDialog_123120_Content_17 = {
    Text = "Para viajar al \"Reino de la tranquilidad sin el sufrimiento de la disolución\", para redimirnos a nosotros mismos en este mundo en llamas——"
  },
  AvgDialog_123120_Content_18 = {
    Text = "Para viajar al \"Reino de la tranquilidad sin el sufrimiento de la disolución\", para redimirnos en este mundo en llamas——"
  },
  AvgDialog_123120_Content_19 = {
    Text = "Una docena de fieles del Amanecer Estrellado juraban al unísono——"
  },
  AvgDialog_123120_Content_2 = {
    Text = "<Shake:Este mundo está ardiendo, este mundo se está colapsando, este mundo está destinado a la destrucción.>"
  },
  AvgDialog_123120_Content_20 = {
    Text = "Una docena de fieles del Amanecer Estrellado levantaron al unísono sus dagas plateadas——"
  },
  AvgDialog_123120_Content_21 = {Text = "¡Detente!"},
  AvgDialog_123120_Content_22 = {
    Text = "En tu grito, la daga plateada se hunde simultáneamente en el corazón del sacrificio humano, hundiéndose profundamente y agitando violentamente."
  },
  AvgDialog_123120_Content_23 = {
    Text = "Una sangre deslumbrante brotó del pecho del sacrificio humano, manchando el altar de rojo."
  },
  AvgDialog_123120_Content_24 = {
    Text = "En medio de un mar de sangre, ustedes emergen de las sombras ocultas, mirando directamente a White, confrontando la fuente de toda esta tragedia."
  },
  AvgDialog_123120_Content_25 = {
    Text = "¿Otro ignorante viene a detener el ritual del Padre Dios?"
  },
  AvgDialog_123120_Content_26 = {
    Text = "Ja, fuiste indiferente cuando llegó el desastre, y ahora que estoy a punto de guiar a mis hermanos y hermanas hacia la Redención, ¿te atreves a detenerme—?"
  },
  AvgDialog_123120_Content_27 = {
    Text = "El líder de la Asamblea del Amanecer Estrellado se rió con desdén al mirarte, luego sus pupilas se agrandaron de repente, quedándose congelado en su lugar."
  },
  AvgDialog_123120_Content_28 = {
    Text = "<Shake:Salvador, ¿Obispo!?>"
  },
  AvgDialog_123120_Content_29 = {
    Text = "La expresión de Salvador estaba envuelta en la tristeza, y notaste que debajo de su amplia túnica, su figura alta y esbelta temblaba ligeramente."
  },
  AvgDialog_123120_Content_3 = {
    Text = "<Shake:¡El único camino hacia la redención es viajar a <Yellow:\"el Reino de la tranquilidad sin el sufrimiento de la disolución\">, que está justo sobre nosotros, en el universo donde brillan las estrellas.>"
  },
  AvgDialog_123120_Content_30 = {
    Text = "White... mi niño perdido..."
  },
  AvgDialog_123120_Content_31 = {
    Text = "¡Oh, ya veo, el niño que este alfil ha venido a salvar desde tan lejos es en realidad el líder de un culto! ¡Qué interesante!"
  },
  AvgDialog_123120_Content_32 = {
    Text = "¡Mouchette!"
  },
  AvgDialog_123120_Content_33 = {
    Text = "Está bien, está bien, no diré nada. Aunque no diga nada, los hechos no cambiarán, ¿verdad?"
  },
  AvgDialog_123120_Content_34 = {
    Text = "Entonces, el lugar cayó en silencio, solo la sangre del sacrificio humano fluía lentamente sobre el altar, empapando el suelo."
  },
  AvgDialog_123120_Content_35 = {
    Text = "John, James, Anderson... todos fueron tus colegas."
  },
  AvgDialog_123120_Content_36 = {
    Text = "Como sacerdote de la Capilla de Vida... deberías entender por qué vinieron a Howick."
  },
  AvgDialog_123120_Content_37 = {
    Text = "...Por supuesto que entiendo."
  },
  AvgDialog_123120_Content_38 = {
    Text = "Porque una vez yo también vine aquí con ideales nobles, igual que ellos!"
  },
  AvgDialog_123120_Content_39 = {
    Text = "La voz de White se volvió de repente emocionada, mirando a Salvador con ansias, como un niño que busca reconocimiento."
  },
  AvgDialog_123120_Content_4 = {
    Text = "<Shake:<Big:¡Encuéntralo, entrégate a ello, dedícale tu vida! Solo así, nuestras vidas darán la bienvenida al amanecer eterno——>>"
  },
  AvgDialog_123120_Content_40 = {
    Text = "Y yo también he cumplido mi promesa, encontrando el único camino para salvar a mis hermanos y hermanas."
  },
  AvgDialog_123120_Content_41 = {Text = "..."},
  AvgDialog_123120_Content_42 = {
    Text = "La muerte no es la enseñanza del Padre Dios, White. Te has desviado del camino."
  },
  AvgDialog_123120_Content_43 = {
    Text = "<Shake:¡No! ¡Aún sigo la guía del Padre Dios!>"
  },
  AvgDialog_123120_Content_44 = {
    Text = "El Padre Dios proclama: <Italic:\"Todos somos Sus hijos, compartimos Su amor misericordioso\">, <Italic:\"Ámense unos a otros, como amas a ti mismo\">."
  },
  AvgDialog_123120_Content_45 = {
    Text = "El Padre Dios aconseja <Italic:\"Aquellos entre ustedes que sean nobles serán mis Emisarios, llevando a cabo mi voluntad para erradicar el sufrimiento de esta Tierra.\">."
  },
  AvgDialog_123120_Content_46 = {
    Text = "......no está mal. Todo esto es la voluntad del Padre Dios."
  },
  AvgDialog_123120_Content_47 = {
    Text = "Y lo he logrado. Salvaré a mis hermanos y hermanas y eliminaré el sufrimiento que se les ha impuesto."
  },
  AvgDialog_123120_Content_48 = {
    Text = "Los llevaré lejos de esta tierra de sufrimiento, guiándolos hacia el amanecer que brilla entre las estrellas, hacia eso—"
  },
  AvgDialog_123120_Content_49 = {
    Text = "<Yellow:<Big:\"Reino de la tranquilidad sin el sufrimiento de la disolución \">>."
  },
  AvgDialog_123120_Content_5 = {
    Text = "En la cueva llena de símbolos de profanación, el líder de la Asamblea del Amanecer Estrellado estaba pronunciando un discurso elocuente. Al caer sus palabras, los sacrificios humanos fueron arrastrados al centro del altar."
  },
  AvgDialog_123120_Content_50 = {
    Text = "Para viajar al \"Reino de la tranquilidad sin el sufrimiento de la disolución\", para redimirnos a nosotros mismos en este mundo en llamas——"
  },
  AvgDialog_123120_Content_51 = {
    Text = "Para viajar al \"Reino de la tranquilidad sin el sufrimiento de la disolución\", para redimirnos en este mundo en llamas——"
  },
  AvgDialog_123120_Content_52 = {
    Text = "En ese momento, una risa fría se clavó en los fervientes y ordenados gritos de los creyentes como una espina."
  },
  AvgDialog_123120_Content_53 = {
    Text = "¿Reino de la tranquilidad sin el sufrimiento de la disolución? ¿Estás hablando del mundo detrás de la puerta?"
  },
  AvgDialog_123120_Content_54 = {
    Text = "¿De qué broma se trata? Mi mundo no es tan maravilloso."
  },
  AvgDialog_123120_Content_55 = {
    Text = "Catástrofe de niebla, antigüedad, ceniza y varios monstruos mutados; encontrarte con cualquiera de ellos sería suficiente para que bebieras una olla."
  },
  AvgDialog_123120_Content_56 = {
    Text = "Así que deja de hablar de tonterías como la redención; lo único que están haciendo es sacrificar a otros para salvar sus propias vidas."
  },
  AvgDialog_123120_Content_57 = {
    Text = "<Shake:¡No es así! Porque——>"
  },
  AvgDialog_123120_Content_58 = {
    Text = "White dio un paso adelante, acercándose a Mouchette, levantando con emoción la daga plateada que tenía en la mano."
  },
  AvgDialog_123120_Content_59 = {
    Text = "Instintivamente proteges a Mouchette, pero el golpe anticipado no llega."
  },
  AvgDialog_123120_Content_6 = {
    Text = "Se están escondiendo en las sombras no muy lejos, confirmando cuidadosamente el número de sacrificios humanos."
  },
  AvgDialog_123120_Content_60 = {
    Text = "El objetivo de la daga era su maestro desde el principio—"
  },
  AvgDialog_123120_Content_61 = {
    Text = "La sangre brotó del corazón de White, fluyendo y fusionándose con la sangre de los sacrificios humanos en el altar carmesí."
  },
  AvgDialog_123120_Content_62 = {
    Text = "<Shake:Ahora... la plata y la sangre son suficientes...>"
  },
  AvgDialog_123120_Content_63 = {
    Text = "Con el susurro de White, un impacto invisible estalló desde el altar."
  },
  AvgDialog_123120_Content_64 = {
    Text = "La sangre que fluía sobre la superficie del altar comenzó a retorcerse y elevarse, junto con el cuerpo de la ofrenda flotando en el aire."
  },
  AvgDialog_123120_Content_65 = {
    Text = "<Shake:¡Aaah—Obispo Salvador...>"
  },
  AvgDialog_123120_Content_66 = {
    Text = "<Shake:¿Lo viste...? No me traicioné... la promesa al Padre Dios...>"
  },
  AvgDialog_123120_Content_67 = {
    Text = "White gritó, su cuerpo moribundo convulsionando incontrolablemente, mientras la plata y la sangre dentro de él eran drenadas por una fuerza invisible, pintando patrones inquietantes en el cielo."
  },
  AvgDialog_123120_Content_68 = {
    Text = "<Shake:Obispo, sé que he pecado... Estoy dispuesto a asumir los pecados, junto con los de ellos.>"
  },
  AvgDialog_123120_Content_69 = {
    Text = "<Shake:Pero nunca me arrepiento... porque en esta Tierra de sufrimiento... salvé a mis hermanos y hermanas...>"
  },
  AvgDialog_123120_Content_7 = {
    Text = "John, James, Anderson... todos están aquí."
  },
  AvgDialog_123120_Content_70 = {
    Text = "La mirada de White estaba fija en Salvador. Y Salvador, este alfil que alguna vez se había dedicado a nutrirlo, dibujó lentamente el sagrado nombre del Padre Dios en el aire."
  },
  AvgDialog_123120_Content_71 = {
    Text = "La mano marcada con el símbolo sagrado temblaba, suprimiendo el impulso de \"Bendición\". Porque Salvador sabía que el niño perdido había tomado su propia decisión."
  },
  AvgDialog_123120_Content_72 = {
    Text = "Aún no estoy de acuerdo con tu enfoque, White, pero de verdad estás practicando las enseñanzas del Padre Dios. Así que..."
  },
  AvgDialog_123120_Content_73 = {
    Text = "Que el Padre Dios te perdone, que tú... puedas regresar al abrazo del Padre Dios... escapar del sufrimiento y alcanzar la redención..."
  },
  AvgDialog_123120_Content_74 = {
    Text = "Salvador suspiró y realizó su última oración."
  },
  AvgDialog_123120_Content_75 = {
    Text = "Pero White ya no podía oír nada.\nSu expresión oscilaba entre una sonrisa de felicidad y un dolor extremo, su latido se detuvo."
  },
  AvgDialog_123120_Content_76 = {
    Text = "Y luego, la plata y la sangre flotando en el aire de repente comenzaron a agitarse, como innumerables \"Estrellas\" hirviendo, iluminando el cielo nocturno."
  },
  AvgDialog_123120_Content_77 = {
    Text = "En esta luz deslumbrante y grandiosa, innumerables manchas de luz desconocida se reorganizan y se agrupan, formando una puerta invisible cuyo destino es incierto."
  },
  AvgDialog_123120_Content_78 = {
    Text = "¿Es esto lo que llaman la \"Puerta\"?"
  },
  AvgDialog_123120_Content_79 = {
    Text = "¿A través de ella, puedo regresar a mi propio mundo?"
  },
  AvgDialog_123120_Content_8 = {
    Text = "Es decir, ¿aún falta el sacerdote White...?"
  },
  AvgDialog_123120_Content_80 = {
    Text = "Es difícil de decir. En teoría, podemos vincular la misma dimensión múltiples veces simulando las mismas ondas de vibración, pero en la práctica, los accidentes pueden ocurrir fácilmente."
  },
  AvgDialog_123120_Content_81 = {
    Text = "Especialmente con este tipo de ritual de sacrificio, que está lleno de muchas variables y puede generar más problemas——"
  },
  AvgDialog_123120_Content_82 = {
    Text = "¡Espera, no vayas allí!"
  },
  AvgDialog_123120_Content_83 = {
    Text = "Levantas la voz para detener a los seguidores de culto que marchan de manera uniforme hacia la puerta intangible, pero parece que no te oyen y continúan avanzando con un paso tranquilo."
  },
  AvgDialog_123120_Content_84 = {
    Text = "Para viajar al \"Reino de la tranquilidad sin el sufrimiento de la disolución\", para redimirnos en este mundo ardiente——"
  },
  AvgDialog_123120_Content_85 = {
    Text = "Para viajar al \"Reino de la tranquilidad sin el sufrimiento de la disolución\", para redimirnos en este mundo en llamas——"
  },
  AvgDialog_123120_Content_86 = {
    Text = "Finalmente, el primer creyente levantó la mano, tocando esa puerta invisible, entrando en el nuevo mundo que tanto anhelaba."
  },
  AvgDialog_123120_Content_87 = {
    Text = "<Shake:¡Aaaahh!>"
  },
  AvgDialog_123120_Content_88 = {
    Text = "En un grito de desesperación, las manos de los fieles que tocaban la puerta de luz comenzaron a distorsionarse y a fusionarse, disolviéndose en la intensa luz que emanaba repentinamente de la puerta invisible."
  },
  AvgDialog_123120_Content_89 = {
    Text = "Luego, una densa niebla interminable brotó de la puerta invisible, devorando la carne y las almas de los creyentes, transformando a aquellos que anhelaban alcanzar las estrellas en parte de las \"Estrellas\"."
  },
  AvgDialog_123120_Content_9 = {Text = "..."},
  AvgDialog_123120_Content_90 = {
    Text = "El comunicador especial ha comenzado a emitir nuevamente el sonido eléctrico de falla, reproduciendo ese familiar susurro de muerte."
  },
  AvgDialog_123120_Content_91 = {
    Text = "@2¡Ayuda@2...!"
  },
  AvgDialog_123120_Content_92 = {
    Text = "¡Ayúdame...! ¡Sálvame...!"
  },
  AvgDialog_123120_Content_93 = {
    Text = "Esto es... <Shake:¡El ritual ha salido mal!>"
  },
  AvgDialog_123120_Content_94 = {
    Text = "¡Salvador, ten cuidado con los monstruos en la niebla!"
  },
  AvgDialog_123120_Content_95 = {
    Text = "Cuando las palabras cayeron, en la densa niebla circundante se condensaron incontables formas humanoides de niebla, rugiendo mientras se lanzaban hacia ustedes."
  },
  AvgDialog_123120_Content_96 = {
    Text = "Las cosas finalmente se están poniendo divertidas."
  },
  AvgDialog_123120_Content_97 = {
    Text = "Mouchette—"
  },
  AvgDialog_123120_Content_98 = {
    Text = "Está bien, no diré más, pero debo recordarte que la catástrofe de niebla sigue expandiéndose."
  },
  AvgDialog_123120_Content_99 = {
    Text = "...Mensajero Pálido, justo ahora todavía podía ver el entorno con claridad, pero ahora no puedo ver nada en absoluto."
  },
  AvgDialog_123121_Content_1 = {
    Text = "Estrellas apagadas"
  },
  AvgDialog_123121_Content_10 = {
    Text = "Con tu fuerza, definitivamente no deberías ser encarcelado por unos patéticos seguidores de culto."
  },
  AvgDialog_123121_Content_11 = {
    Text = "Y creo que ambos nos dimos cuenta de que esta dama ha preguntado múltiples veces sobre la hora de la ceremonia, y su expresión... es claramente una de anticipación."
  },
  AvgDialog_123121_Content_12 = {
    Text = "Ah, así que fue en estos lugares donde fui expuesto... Fui descuidado."
  },
  AvgDialog_123121_Content_13 = {
    Text = "Entonces, ¿quién eres realmente? ¿Qué es ese ritual? ¿Qué sabes?"
  },
  AvgDialog_123121_Content_14 = {
    Text = "Mouchette mostró una sonrisa despreocupada y respondió con otra pregunta—"
  },
  AvgDialog_123121_Content_15 = {
    Text = "¿Y ustedes? ¿Por qué vinieron a este lugar donde el orden secular ha colapsado por completo, dejando solo creencias tediosas?"
  },
  AvgDialog_123121_Content_16 = {
    Text = "Salvador no insistió en la ofensa contra la fe en las palabras de Mouchette, solo mostró una expresión de compasión."
  },
  AvgDialog_123121_Content_17 = {
    Text = "Vengo por redención."
  },
  AvgDialog_123121_Content_18 = {
    Text = "¿Redención? ¿Redención para quién? ¿Para esos sacrificios humanos? Con todo respeto, a veces es mejor una muerte rápida que una vida dolorosa."
  },
  AvgDialog_123121_Content_19 = {
    Text = "especialmente en un mundo así... eh, estimulante y divertido."
  },
  AvgDialog_123121_Content_2 = {
    Text = "Después de enviar una señal al Santuario de Vida, tú y Salvador esperaron afuera de la cueva a la extraña niña que se llama \"Mouchette\"."
  },
  AvgDialog_123121_Content_20 = {
    Text = "La bendición del Padre Dios se sembrará en cada rincón que anhele redención."
  },
  AvgDialog_123121_Content_21 = {
    Text = "Esos prisioneros claman a mí y al Santuario de Vida en busca de ayuda en su sufrimiento, y sin duda responderemos a sus súplicas."
  },
  AvgDialog_123121_Content_22 = {
    Text = "Como el Executor del Padre Dios, haré todo lo posible para erradicar el sufrimiento de esta Tierra."
  },
  AvgDialog_123121_Content_23 = {
    Text = "Salvador bajó la cabeza y juntó las manos en una reverencia de piedad.\nLa respuesta a esto fue la suave risa de Mouchette."
  },
  AvgDialog_123121_Content_24 = {
    Text = "Supongo que ustedes son el tipo de personas buenas en el sentido mundano, creyendo en tonterías aburridas como amo a todos, y todos me aman, ¿verdad?"
  },
  AvgDialog_123121_Content_25 = {
    Text = "Por eso me creíste tan fácilmente y me seguiste hasta aquí..."
  },
  AvgDialog_123121_Content_26 = {
    Text = "Es tan ingenuo que resulta molesto."
  },
  AvgDialog_123121_Content_27 = {
    Text = "No puedes discernir si la expresión de Mouchette es de pulla o de reflexión, ya que una bruma que aparece de la nada oscurece su cara."
  },
  AvgDialog_123121_Content_28 = {
    Text = "Estás equivocado, solo no queremos hacer suposiciones malintencionadas sobre un extraño."
  },
  AvgDialog_123121_Content_29 = {
    Text = "Ah, no importa cómo sea, porque ustedes no entienden en absoluto..."
  },
  AvgDialog_123121_Content_3 = {
    Text = "Y cuando Mouchette apareció al final de tu visión, inesperadamente tenía en la mano un hacha llena de diseño."
  },
  AvgDialog_123121_Content_30 = {
    Text = "Justo en ese momento, un sonido repentino de un interruptor interrumpió las palabras de Mouchette."
  },
  AvgDialog_123121_Content_31 = {
    Text = "El comunicador detectó fluctuaciones espirituales... ¿La fuente es... niebla?!"
  },
  AvgDialog_123121_Content_32 = {
    Text = "Sin darse cuenta, esa bruma continuó expandiéndose, oscureciendo no solo la mayor parte de la figura de Mouchette, sino también el paisaje circundante."
  },
  AvgDialog_123121_Content_33 = {
    Text = "¿Fluctuación espiritual? Así que así es como explican la \"Catástrofe de niebla\"..."
  },
  AvgDialog_123121_Content_34 = {
    Text = "\"Catástrofe de niebla\"?"
  },
  AvgDialog_123121_Content_35 = {
    Text = "Por supuesto, este mundo en ruinas no tendrá nada tan interesante; proviene de mí—"
  },
  AvgDialog_123121_Content_36 = {
    Text = "Desde <Yellow:mi mundo>."
  },
  AvgDialog_123121_Content_37 = {
    Text = "¿Tu mundo...?"
  },
  AvgDialog_123121_Content_38 = {
    Text = "Esos tontos de la Asamblea del Amanecer Estrellado han abierto la puerta prohibida que no debería abrirse."
  },
  AvgDialog_123121_Content_39 = {
    Text = "Entonces el ritual falló con un \"crack——\", dejando solo a mí, el desafortunado, y las cosas enredadas——"
  },
  AvgDialog_123121_Content_4 = {
    Text = "¿Qué tal? ¿No es muy guapo?"
  },
  AvgDialog_123121_Content_40 = {
    Text = "Solo quería recordarles que pueden considerar cuándo comenzar a escapar."
  },
  AvgDialog_123121_Content_41 = {
    Text = "¿Ellos? ¿Escapar?"
  },
  AvgDialog_123121_Content_42 = {
    Text = "Hmph☆hmph, esos pequeños en la niebla están llegando pronto——"
  },
  AvgDialog_123121_Content_43 = {
    Text = "¡Que se diviertan."
  },
  AvgDialog_123121_Content_44 = {
    Text = "Diciendo esto, Mouchette retrocedió, ocultándose en la densa niebla, dejando solo su voz que se desvanecía cada vez más en la bruma."
  },
  AvgDialog_123121_Content_45 = {
    Text = "Además, gracias por su ayuda. Les debo una, así que esta vez, ustedes necesitan darme suficiente tiempo~"
  },
  AvgDialog_123121_Content_46 = {
    Text = "...¡Mouchette, espera!?"
  },
  AvgDialog_123121_Content_47 = {
    Text = "Quieres detenerla, pero la densa niebla te deja completamente perdido sobre por dónde empezar a perseguirla."
  },
  AvgDialog_123121_Content_48 = {
    Text = "Tras reflexionar, agarras la llave de plata, preparándote para activar \"Retrospección mental\", cuando el comunicador emite un sonido nuevamente."
  },
  AvgDialog_123121_Content_49 = {
    Text = "Ese es un sonido agudo de una corriente eléctrica en mal funcionamiento, que se vuelve cada vez más fuerte y más claro en la niebla densa que continuamente surge."
  },
  AvgDialog_123121_Content_50 = {
    Text = "@2... ¡Ayúdame@2...!"
  },
  AvgDialog_123121_Content_51 = {Text = "...¡Ah!?"},
  AvgDialog_123121_Content_52 = {
    Text = "Salvador, ¿lo oíste?"
  },
  AvgDialog_123121_Content_53 = {
    Text = "¿Eso parece ser... una voz humana?"
  },
  AvgDialog_123121_Content_54 = {
    Text = "Al escuchar esto, recogiste el comunicador y esperaste el siguiente sonido, al que el comunicador respondió—"
  },
  AvgDialog_123121_Content_55 = {
    Text = "Un grito desgarrador de desesperación, capaz de perforar los tímpanos, se clava en tu cabeza como una cuchilla, dejándote aturdido de inmediato."
  },
  AvgDialog_123121_Content_56 = {
    Text = "Mientras tanto, de la densa niebla surgieron innumerables nieblas humanoides, rugiendo mientras se lanzaban hacia ti y Salvador."
  },
  AvgDialog_123121_Content_57 = {Text = "¡Cuidado!"},
  AvgDialog_123121_Content_58 = {
    Text = "La pizarra se desplaza a través de la densa niebla, dispersando a los monstruos formados por el vapor, pero los desgarradores gritos aún persisten, incesantes, golpeando tu alma."
  },
  AvgDialog_123121_Content_59 = {
    Text = "La sangre gotea incesantemente de tus fosas nasales, salpicando el suelo, pero no puedes ver con claridad debido al mareo."
  },
  AvgDialog_123121_Content_6 = {
    Text = "Mouchette balanceó el hacha unas cuantas veces, sus movimientos eran limpios y precisos, como si esta enorme arma fuera parte de ella—"
  },
  AvgDialog_123121_Content_60 = {
    Text = "Tu espíritu parece desprenderse del cuerpo, expandiéndose continuamente en un estado invisible y caótico, sintiendo la aldea en la que te encuentras."
  },
  AvgDialog_123121_Content_61 = {
    Text = "Lo sientes: la niebla omnipresente devora imprudentemente la tierra, los edificios y cualquier rastro de existencia humana o no humana."
  },
  AvgDialog_123121_Content_62 = {
    Text = "Y en esta densa niebla sin límites, innumerables estrellas arden silenciosa y fríamente, claramente muertas desde hace mucho tiempo."
  },
  AvgDialog_123121_Content_63 = {Text = "%player%!"},
  AvgDialog_123121_Content_64 = {
    Text = "La voz de Salvador resuena en tu mente, pero la desesperación y el dolor que se propagan desde lo más profundo de tu alma te paralizan."
  },
  AvgDialog_123121_Content_65 = {
    Text = "@2... ¡Ayúdame@2...!"
  },
  AvgDialog_123121_Content_66 = {
    Text = "¡Ayuda@2...! ¡Ayúdame@2...!"
  },
  AvgDialog_123121_Content_67 = {
    Text = "Las estrellas muertas, cargadas de una desesperación y dolor infinitos, te rodean, derritiéndote obstinadamente, corroyéndote, queriendo arrastrarte hacia el sueño eterno."
  },
  AvgDialog_123121_Content_68 = {
    Text = "...no puedo simplemente quedarme dormido así, Sal..."
  },
  AvgDialog_123121_Content_69 = {
    Text = "Sal...vador... ayúdame..."
  },
  AvgDialog_123121_Content_7 = {
    Text = "Al darse cuenta de esto, iniciaste una ofensiva."
  },
  AvgDialog_123121_Content_70 = {
    Text = "En ese momento, una luz suave brilló en tu mundo, como el sol más cálido, abrazándote firmemente y disipando toda frialdad y la sensación de muerte."
  },
  AvgDialog_123121_Content_71 = {
    Text = "Esa es la radiancia de Salvador."
  },
  AvgDialog_123121_Content_72 = {
    Text = "Él escuchó tu solicitud."
  },
  AvgDialog_123121_Content_73 = {
    Text = "Él respondió a tu solicitud."
  },
  AvgDialog_123121_Content_74 = {
    Text = "<Shake:Cof cof...>"
  },
  AvgDialog_123121_Content_75 = {
    Text = "Con la ayuda de Salvador, finalmente saliste de esa niebla mareante. Jadeaste por aire, sintiendo que recuperabas algo de cordura."
  },
  AvgDialog_123121_Content_76 = {
    Text = "Salvador, puedes dejar de bendecir, ya estoy mucho mejor."
  },
  AvgDialog_123121_Content_77 = {
    Text = "Salvador asintió, entregándose por completo a la lucha contra la amenaza desconocida en la niebla."
  },
  AvgDialog_123121_Content_78 = {
    Text = "Estos monstruos en la niebla no morirán. Incluso si son dispersos, reaparecerán rápidamente."
  },
  AvgDialog_123121_Content_79 = {
    Text = "Temo que mientras exista esta niebla, estos monstruos vivirán para siempre."
  },
  AvgDialog_123121_Content_8 = {
    Text = "Mouchette, te dejaste atrapar por los seguidores de culto voluntariamente."
  },
  AvgDialog_123121_Content_80 = {
    Text = "Padre Salvador, ¿crees que lo que acaba de decir Mouchette es verdad?"
  },
  AvgDialog_123121_Content_81 = {
    Text = "Desde el momento en que nos conocimos, el fuego del alma de la dama Mouchette ha permanecido constante. En mi opinión, ella no ha mostrado ni la actitud de una mentirosa ni el motivo para mentir."
  },
  AvgDialog_123121_Content_82 = {
    Text = "Bueno, tengo algunas suposiciones. Sin embargo, primero debemos encontrar a Mouchette."
  },
  AvgDialog_123121_Content_83 = {
    Text = "Respeto tu decisión, mensajero pálido."
  },
  AvgDialog_123121_Content_84 = {
    Text = "No te preocupes por esos monstruos en la niebla, aseguraré tu seguridad."
  },
  AvgDialog_123121_Content_85 = {
    Text = "Miras a Salvador con gratitud y luego mueves la mano hacia la llave de plata."
  },
  AvgDialog_123121_Content_86 = {
    Text = "La sangre cae de nuevo de tu cara, pero no te mueves, la aterradora conjetura que tuviste durante el mareo ocupa toda tu mente."
  },
  AvgDialog_123121_Content_87 = {
    Text = "@2... ¡Ayuda@2...!"
  },
  AvgDialog_123121_Content_88 = {
    Text = "¡Ayuda@2...! ¡@2, sálvame...!"
  },
  AvgDialog_123121_Content_89 = {
    Text = "Finalmente, cuando el comunicador emitió ruido una vez más, atravesaste innumerables estrellas frías y muertas y tocaste el cuerpo espiritual de Mouchette."
  },
  AvgDialog_123121_Content_9 = {
    Text = "¿Eh? ¿Estás bromeando? Una persona normal no se convertiría voluntariamente en prisionera de un seguidor de culto, encerrada en una jaula sin comida ni agua."
  },
  AvgDialog_123122_Content_1 = {
    Text = "A través de tus ojos"
  },
  AvgDialog_123122_Content_10 = {
    Text = "Estoy ocupado en este momento y no tengo tiempo para jugar a juegos aburridos de casitas, y mucho menos tengo interés en interpretar el papel de la hija educada."
  },
  AvgDialog_123122_Content_11 = {
    Text = "No entiendes este mundo, ni conoces el verdadero costo y los efectos del ritual de la Asamblea del Amanecer Estrellado."
  },
  AvgDialog_123122_Content_12 = {
    Text = "En otras palabras, los prisioneros que acabas de encerrar contigo son todos sacrificios esenciales para el próximo ritual."
  },
  AvgDialog_123122_Content_13 = {
    Text = "Además, incluso si el ritual se lleva a cabo de nuevo, no sabes si las puertas entre los dos mundos se volverán a abrir y si podrás regresar a tu propio mundo a través de ellas."
  },
  AvgDialog_123122_Content_14 = {
    Text = "El movimiento de Mouchette se detuvo, y luego se mordió los labios con fuerza."
  },
  AvgDialog_123122_Content_15 = {Text = "..."},
  AvgDialog_123122_Content_16 = {
    Text = "Hijo, sé que no viniste a este mundo cruel de forma voluntaria, y entiendo tu deseo de volver."
  },
  AvgDialog_123122_Content_17 = {
    Text = "Solo esperamos poder ayudarte a evitar que tomes el camino equivocado."
  },
  AvgDialog_123122_Content_18 = {
    Text = "¿Dices que querer regresar a mi propio mundo a través del ritual de la Asamblea del Amanecer Estrellado es un camino equivocado?"
  },
  AvgDialog_123122_Content_19 = {
    Text = "La actitud recientemente suavizada de Mouchette parecía endurecerse de nuevo, y su tono estaba lleno de afiladas pullas."
  },
  AvgDialog_123122_Content_2 = {
    Text = "¡¿Cómo me encontraron ustedes?!"
  },
  AvgDialog_123122_Content_20 = {
    Text = "La densa niebla en los alrededores comienza a arremolinarse y a surgir."
  },
  AvgDialog_123122_Content_21 = {
    Text = "Entonces, ¿qué es el camino correcto? ¿Quién define qué es el camino correcto? ¿Tú o tu dios?"
  },
  AvgDialog_123122_Content_22 = {
    Text = "El disfraz ha sido despojado, y Mouchette revela sin vergüenza su desdén y desprecio por Salvador y otros creyentes como él."
  },
  AvgDialog_123122_Content_23 = {
    Text = "¿Qué importa si has juzgado bien o mal? Veo este mundo como aún más estéril y desolado que Temulán."
  },
  AvgDialog_123122_Content_24 = {
    Text = "¿Dónde está el \"Padre Dios\" de tu boca cuando esos sacrificios humanos sufren?"
  },
  AvgDialog_123122_Content_25 = {
    Text = "La niebla densa se arremolina con más intensidad, cubriendo el rostro de Mouchette y también la expresión de Salvador."
  },
  AvgDialog_123122_Content_26 = {
    Text = "Lo único que puedes escuchar en esta niebla es el suspiro de Salvador y los extraños sonidos que presagian la aproximación del peligro."
  },
  AvgDialog_123122_Content_27 = {Text = "Yo..."},
  AvgDialog_123122_Content_28 = {
    Text = "Habla libremente, sacerdote, de todos modos no tienes nada que hacer."
  },
  AvgDialog_123122_Content_29 = {
    Text = "Apenas Mouchette terminó de hablar, innumerables figuras de niebla emergieron de la bruma circundante, dirigiéndose hacia ustedes."
  },
  AvgDialog_123122_Content_3 = {
    Text = "¿Acaso algo salió mal con la niebla justo ahora? ¿O ustedes también tienen la capacidad de ver a través de la niebla como el oficial de investigación?"
  },
  AvgDialog_123122_Content_30 = {
    Text = "Pero el movimiento de Mouchette era más rápido que el de aquella niebla humana. Al ver que intentaba escaparse, no pudiste evitar gritar."
  },
  AvgDialog_123122_Content_31 = {
    Text = "¡Salvador, deténla!"
  },
  AvgDialog_123122_Content_4 = {
    Text = "La sorpresa de Mouchette no duró mucho; en un instante, su expresión se volvió tranquila."
  },
  AvgDialog_123122_Content_5 = {
    Text = "Tienes algunos medios para escapar de las antigüedades en la niebla. Pero—"
  },
  AvgDialog_123122_Content_6 = {
    Text = "<Big:<Shake:¡No me impidas hacer lo que tengo que hacer!>>"
  },
  AvgDialog_123122_Content_7 = {
    Text = "Mouchette dijo, agarrando el hacha con fuerza, su mirada llena de vigilancia y hostilidad."
  },
  AvgDialog_123122_Content_8 = {
    Text = "Mouchette, no tienes que hacerlo así, no somos enemigos. Al menos, no ahora."
  },
  AvgDialog_123122_Content_9 = {
    Text = "Pero antes de que tomes tu decisión, tengo un consejo que debo transmitirte."
  },
  AvgDialog_125040_Content_1 = {
    Text = "La inundación del Río Sagrado ha traído problemas sin precedentes a Misaq. Inesperadamente, la habitación de Xu se ha convertido en uno de los pocos lugares donde puedes buscar refugio."
  },
  AvgDialog_125040_Content_10 = {
    Text = "Puedo ser una mentira, un pensamiento fugaz, pero cuando se trata de mí misma... es absolutamente aburrido."
  },
  AvgDialog_125040_Content_11 = {
    Text = "Uh... ¿Xu?"
  },
  AvgDialog_125040_Content_12 = {Text = "niebla."},
  AvgDialog_125040_Content_13 = {
    Text = "Una niebla ligera y delicada, como hilos de seda, te envuelve en capas."
  },
  AvgDialog_125040_Content_14 = {
    Text = "<LightGray:¿No tiene impacto? ¿Solo estamos charlando y jugando al ajedrez? ¡Ustedes, Despertados, por qué dicen una cosa y hacen otra!>"
  },
  AvgDialog_125040_Content_15 = {
    Text = "A medida que un fantasma dorado y titilante se desliza a través del resplandor, un toque satinado ata tus brazos y espalda, guiándote a levantar el velo hecho de niebla."
  },
  AvgDialog_125040_Content_16 = {
    Text = "Ah, porque realmente tengo mucha, mucha curiosidad."
  },
  AvgDialog_125040_Content_17 = {
    Text = "Cuando me tocaron, estaban tocando un fantasma. Cuando me miraron, fue a través de mí, viendo lo que \"pensaban\" que era su amado."
  },
  AvgDialog_125040_Content_18 = {
    Text = "Pero tú eres diferente. ¿Tienes la sombra de alguien? Si indagas más, ¿qué rostro verás bajo mi abanico...?"
  },
  AvgDialog_125040_Content_19 = {
    Text = "La neblina se aparta, y bajo el abanico, algo cálido toca suavemente tu nariz. Las plumas en el hombro de la mujer caen, rozando suavemente tu piel que tiembla inexplicablemente."
  },
  AvgDialog_125040_Content_2 = {
    Text = "¿El Río Sagrado no te ha afectado en absoluto?"
  },
  AvgDialog_125040_Content_20 = {
    Text = "<LightGray:Genial, abrasador, otro más.>"
  },
  AvgDialog_125040_Content_21 = {
    Text = "Xu, si no recuerdo mal, lo que acabas de decir fue, \"sin distracciones\" en su lugar."
  },
  AvgDialog_125040_Content_22 = {
    Text = "Sí, en el Lejano Oriente, cuando un monarca tiene asuntos importantes que discutir con alguien, invita a esa persona a entrar en el telón, de ahí el término—invitado en el teatro."
  },
  AvgDialog_125040_Content_23 = {
    Text = "Sin embargo, para las mujeres, ser invitada en el teatro tiene otro significado."
  },
  AvgDialog_125040_Content_24 = {
    Text = "<Shake:——Toc.>"
  },
  AvgDialog_125040_Content_25 = {
    Text = "Una gota de cera de vela cayó sobre la mesa, esparciendo las piezas de ajedrez."
  },
  AvgDialog_125040_Content_26 = {
    Text = "La luz se apagó."
  },
  AvgDialog_125040_Content_27 = {
    Text = "Siempre he necesitado quedarme al margen, pero tal vez usted finalmente pueda verme."
  },
  AvgDialog_125040_Content_28 = {
    Text = "Solo usted me hace desear estar detrás del telón, enfrentando quizás al invitado más importante de mi vida, ¿cómo podría tener alguna \"distracción\"?"
  },
  AvgDialog_125040_Content_29 = {
    Text = "Las cadenas desaparecen, y esta deidad antigua y misteriosa te ha dejado claramente una salida."
  },
  AvgDialog_125040_Content_3 = {
    Text = "No sé si es porque la fuente de poder proviene de los tres grandes plásmidos o si es porque soy demasiado hábil en los caminos del placer, pero parece que no tengo distracciones."
  },
  AvgDialog_125040_Content_30 = {
    Text = "Y su invitación, llena de alegría, apenas audible, es difícil de distinguir entre lo real y lo falso."
  },
  AvgDialog_125040_Content_31 = {
    Text = "Caí al mar oscuro, buscando la orilla pero sin poder encontrarla..."
  },
  AvgDialog_125040_Content_4 = {
    Text = "Esos hermosos ojos brillaban de alegría mientras varias piezas blancas tocaban suavemente el tablero de ajedrez. Su dueña estaba muy interesada en pasar el tiempo con este antiguo juego del Este."
  },
  AvgDialog_125040_Content_5 = {
    Text = "Los humanos son una especie muy extraña; pierden la compostura por un momento de alegría, y una vez que la obtienen, inmediatamente muestran desinterés."
  },
  AvgDialog_125040_Content_6 = {
    Text = "Año tras año, se cansan el uno del otro. Solo tejiendo ilusiones para ellos, llevándolos a abandonar la vida y la muerte, a desgarrar sus corazones y sacarles los hígados, pueden nunca olvidar."
  },
  AvgDialog_125040_Content_7 = {
    Text = "La luz parpadeante de las velas perfila la figura de la mujer sentada en la cama, proyectando un contorno tenue y sombrío."
  },
  AvgDialog_125040_Content_8 = {
    Text = "El cielo se había oscurecido por completo en algún momento, y ella soltó una risa suave."
  },
  AvgDialog_125040_Content_9 = {
    Text = "Forzando a buenas familias a entrar en el comercio, persuadiendo a @2 a regresar a una vida virtuosa. Soy bastante bueno en este tipo de actos, tejiendo una historia que es mitad verdadera y mitad falsa, y luego dejándolos ver este rostro que lleva culpa o amor no correspondido."
  },
  AvgDialog_126907_Content_1 = {
    Text = "Fuego del pasado"
  },
  AvgDialog_126907_Content_10 = {
    Text = "¡Adelante."
  },
  AvgDialog_126907_Content_11 = {
    Text = "Elsa brillaba con los ojos, te tiró hacia ella y, en un abrir y cerrar de ojos, comenzó la danza que se suponía debías liderar tú."
  },
  AvgDialog_126907_Content_12 = {
    Text = "Su fuerza es tan grande que casi te lanza fuera, y en un momento de pánico, te arrastra de vuelta con pura fuerza."
  },
  AvgDialog_126907_Content_13 = {
    Text = "<Shake:L-Lo siento mucho,> Señor Dexter. La próxima vez lo haré mejor, lo prometo..."
  },
  AvgDialog_126907_Content_14 = {
    Text = "Te sientes como un trompo que gira y es golpeado de un lado a otro, girando sin parar, y tus pasos de baile, ya torpes, parecen aún más desastrosos."
  },
  AvgDialog_126907_Content_15 = {Text = "¡Pff."},
  AvgDialog_126907_Content_16 = {
    Text = "Al ver tu vergüenza, Ramona no pudo evitar soltar una risa ligera."
  },
  AvgDialog_126907_Content_17 = {
    Text = "La miraste a los ojos, sintiendo que su mirada llena de sonrisas te susurraba——"
  },
  AvgDialog_126907_Content_18 = {
    Text = "Señor Dexter, hoy te toca a ti."
  },
  AvgDialog_126907_Content_19 = {Text = "..."},
  AvgDialog_126907_Content_2 = {
    Text = "En la pista de baile, un joven y una niña con uniformes escolares giran con gracia. La música fluye como agua, envolviendo sus manos entrelazadas, las faldas suavemente levantadas y las miradas intercambiadas."
  },
  AvgDialog_126907_Content_20 = {
    Text = "Al terminar la canción, apresuradamente realizaste un beso en la mano para despedirte de tu pareja de baile y te dirigiste directamente hacia Ramona."
  },
  AvgDialog_126907_Content_21 = {
    Text = "Recuerdo que te llamaban el profesor más elegante de todo Misaq en lo que respecta al baile de salón, Señor Dexter."
  },
  AvgDialog_126907_Content_22 = {
    Text = "Rebuscas en tu mente, tratando de dar la respuesta suave y astuta del Señor Dexter."
  },
  AvgDialog_126907_Content_23 = {
    Text = "Creo que si se celebrara una competencia de \"Bailar con Elsa\", yo seguiría siendo el ganador."
  },
  AvgDialog_126907_Content_24 = {
    Text = "Ramona desvió la mirada, moviendo suavemente la copa de pie en su mano."
  },
  AvgDialog_126907_Content_25 = {
    Text = "Elsa te admira. Aunque esta danza no sea perfecta, se puede considerar como el cumplimiento de su deseo del Festival de Oración por el Año."
  },
  AvgDialog_126907_Content_26 = {
    Text = "Desafortunadamente, la persona que baila con ella no es el verdadero Señor Dexter."
  },
  AvgDialog_126907_Content_27 = {
    Text = "Lo que es aún más infernal es que, incluso sin tu acto de posesión, la persona que ella conoce no es el verdadero Señor Dexter."
  },
  AvgDialog_126907_Content_28 = {
    Text = "Pero ese no es el tema que quieres abordar."
  },
  AvgDialog_126907_Content_29 = {
    Text = "Ramona, ¿tienes algún deseo para el Festival de Oración por el Año?"
  },
  AvgDialog_126907_Content_3 = {
    Text = "Notas que Ramona está de pie sola junto a una mesita fuera de la pista de baile, sorbiendo una bebida desconocida."
  },
  AvgDialog_126907_Content_30 = {
    Text = "¿El juego de roles ha cambiado de dirección? ¿En lugar de saludar a esa señora y a esa dama, viniste a preocuparte por tu hija adoptiva?"
  },
  AvgDialog_126907_Content_31 = {
    Text = "Veo que no has ido a bailar; ¿es porque no tienes una pareja que te guste?"
  },
  AvgDialog_126907_Content_32 = {
    Text = "No es necesario que se preocupe."
  },
  AvgDialog_126907_Content_33 = {
    Text = "¿Te gustaría concederme el honor de bailar con mi solitario anciano padre?"
  },
  AvgDialog_126907_Content_34 = {
    Text = "Ramona se queda en silencio. Sabes que está buscando razones en el palacio de sus pensamientos."
  },
  AvgDialog_126907_Content_35 = {
    Text = "La persona que estás esperando también espera que aceptes esta invitación a bailar."
  },
  AvgDialog_126907_Content_36 = {
    Text = "¿Cómo lo sabes?"
  },
  AvgDialog_126907_Content_37 = {Text = "¡Lo sé."},
  AvgDialog_126907_Content_38 = {
    Text = "Un silencio aún más largo."
  },
  AvgDialog_126907_Content_39 = {
    Text = "Olvídalo, confiaré en ti esta vez."
  },
  AvgDialog_126907_Content_4 = {
    Text = "Mientras piensas qué razón dar para iniciar la conversación, una voz tímida suena a tu lado."
  },
  AvgDialog_126907_Content_40 = {
    Text = "Ella entra en la pista de baile con ligereza, sus delgados dedos descansando en tu palma."
  },
  AvgDialog_126907_Content_41 = {
    Text = "Vamos, aún no he bailado contigo."
  },
  AvgDialog_126907_Content_42 = {Text = "..."},
  AvgDialog_126907_Content_43 = {
    Text = "Los pasos de danza de Ramona son como su personalidad—racional, contenida, precisa y meticulosa."
  },
  AvgDialog_126907_Content_44 = {
    Text = "Puedes relajarte un poco; parece que estás tratando la pista de baile como un campo de batalla."
  },
  AvgDialog_126907_Content_45 = {
    Text = "Y podrías ser un poco más serio, noble Lord. Desde que empezaste a bailar, casi me has pisado el pie tres veces."
  },
  AvgDialog_126907_Content_46 = {
    Text = "Esto no es como el Señor Dexter, que se ha sumergido en los círculos sociales durante décadas."
  },
  AvgDialog_126907_Content_47 = {
    Text = "¿Quizás a veces también quiero interpretar algo diferente?"
  },
  AvgDialog_126907_Content_48 = {Text = "¿Es así?"},
  AvgDialog_126907_Content_49 = {
    Text = "¿Sabes qué? Estás un poco demasiado callado hoy."
  },
  AvgDialog_126907_Content_5 = {
    Text = "Aprecia los momentos antes de la medianoche; son el tiempo que ganaste con las vidas de tus compañeros."
  },
  AvgDialog_126907_Content_50 = {
    Text = "<LightGray:Pensé que lo había restaurado bastante bien...>"
  },
  AvgDialog_126907_Content_51 = {
    Text = "¿Es así? Tal vez sea porque el clima es demasiado frío, lo que hace que la gente pierda el deseo de hablar."
  },
  AvgDialog_126907_Content_52 = {
    Text = "Si fuera el noble Dexter, diría: coquetear con tu propia hija adoptiva es bastante tabú, ¿sabes."
  },
  AvgDialog_126907_Content_53 = {
    Text = "<Yellow:¿Quién eres realmente?>"
  },
  AvgDialog_126907_Content_54 = {
    Text = "Ramona, el tiempo que tenemos para encontrarnos es demasiado corto; no quiero..."
  },
  AvgDialog_126907_Content_55 = {
    Text = "Se escuchó la leve tos de Xu en mis oídos."
  },
  AvgDialog_126907_Content_56 = {
    Text = "¡No hablemos de eso, mira!"
  },
  AvgDialog_126907_Content_59 = {
    Text = "En un instante, innumerables proyectiles de fuegos artificiales se dispararon hacia el cielo."
  },
  AvgDialog_126907_Content_6 = {
    Text = "¿Eh, por qué es esto?"
  },
  AvgDialog_126907_Content_60 = {
    Text = "En un instante, innumerables proyectiles de fuegos artificiales se dispararon hacia el cielo."
  },
  AvgDialog_126907_Content_62 = {
    Text = "Una cascada de flores doradas y ardientes florece desde la cima."
  },
  AvgDialog_126907_Content_63 = {
    Text = "En la cima florecen los árboles de fuego y las flores doradas."
  },
  AvgDialog_126907_Content_64 = {
    Text = "Al igual que el día de la Ceremonia de Concesión de Llaves, tomaste la mano de Ramona."
  },
  AvgDialog_126907_Content_65 = {
    Text = "Al igual que el día de la Ceremonia de Concesión de Llaves, tomaste la mano de Ramona."
  },
  AvgDialog_126907_Content_66 = {
    Text = "Cierras los ojos ante su expresión de asombro."
  },
  AvgDialog_126907_Content_67 = {
    Text = "Cierras los ojos ante su expresión de asombro."
  },
  AvgDialog_126907_Content_68 = {
    Text = "En una oscuridad, innumerables voces de alegría y anticipación resuenan:"
  },
  AvgDialog_126907_Content_69 = {
    Text = "En una oscuridad, innumerables voces de alegría y anticipación resuenan:"
  },
  AvgDialog_126907_Content_7 = {
    Text = "Todos se niegan a bailar conmigo... diciendo que sienten que es peligroso."
  },
  AvgDialog_126907_Content_70 = {
    Text = "<Big:<Shake:\"¡Feliz Festival de Oración por el Año!\">>"
  },
  AvgDialog_126907_Content_71 = {
    Text = "¡Feliz Festival de Oración por el Año, Ramona."
  },
  AvgDialog_126907_Content_72 = {
    Text = "La medianoche ha llegado, el viento aúlla, y todas las historias que debían pertenecer a ti se alejan de ti."
  },
  AvgDialog_126907_Content_8 = {
    Text = "¡Pero no te preocupes! ¡Me aseguraré de controlar mi fuerza!"
  },
  AvgDialog_126907_Content_9 = {
    Text = "Tu mirada recorre de arriba a abajo la pequeña figura temblorosa."
  },
  AvgDialog_126908_Content_1 = {
    Text = "Sala de oscuridad perpetua"
  },
  AvgDialog_126908_Content_10 = {
    Text = "Su sonrisa y figura se desvanecieron ambiguamente, disolviéndose en el viento que se convirtió en cenizas."
  },
  AvgDialog_126908_Content_11 = {
    Text = "Adelante, ve a reclamar tu botín."
  },
  AvgDialog_126908_Content_12 = {
    Text = "Detrás de la niebla y las cenizas, aparece una puerta—que conduce a la cabina del tren."
  },
  AvgDialog_126908_Content_13 = {
    Text = "Sin trucos, sin resortes, sin existencia innecesaria."
  },
  AvgDialog_126908_Content_14 = {
    Text = "Era solo una puerta ordinaria, como todas las demás en el mundo, que cumplía la función de \"entrada y salida\", esperándote al final del rompecabezas."
  },
  AvgDialog_126908_Content_15 = {
    Text = "Tomaste una respiración profunda, aferraste la llave de plata y empujaste esta puerta."
  },
  AvgDialog_126908_Content_16 = {Text = "..."},
  AvgDialog_126908_Content_17 = {
    Text = "<LightGray:Me siento un poco deshabituado a la ausencia de más cuerpos o incluso de un par de miembros desmembrados.>"
  },
  AvgDialog_126908_Content_18 = {Text = "¿Hm?"},
  AvgDialog_126908_Content_19 = {
    Text = "Una ráfaga de niebla cae del tablero, desplegando suavemente un pañuelo de seda que brilla suavemente, inscribiendo con consideración las palabras de Londinium, que son completamente incompatibles con su estilo."
  },
  AvgDialog_126908_Content_2 = {
    Text = "Vagón No. 1"
  },
  AvgDialog_126908_Content_20 = {
    Text = "Querido Guardián del Secreto:\n\n Espero que estés bien.\n Ya que has llegado aquí, seguramente has descubierto el secreto de este tren: es un Dominio artificial construido por N. Ahora, la persona que estaba en este tren ha muerto.\n He sido testigo de cómo todos ustedes hablaban sobre su destino. Winkle y Tinct, sus hogares ya no existen; yo también tenía en mente a Miryam, pero tras una cuidadosa investigación, el Lemuria que describió Miryam también es algo que ya no se puede recuperar."
  },
  AvgDialog_126908_Content_21 = {
    Text = "¿Y a dónde quiere volver esta sirvienta? Creo que es a un verdadero Sin sueño. \n Todos ellos, todos nosotros, ya no tenemos un lugar al que regresar. \n Pero usted, solo usted, %player%, la Universidad de Misag a la que anhela y a la que se aferra, sigue existiendo, y aún hay personas allí esperándote para que regreses. \n Por lo tanto, debe convertirse en el último ganador de este juego. \n\n Así que esta victoria se la dedico a usted, con la muerte de esta sirvienta como nota al pie. \n Solo tiene que accionar la palanca a su lado, y lo llevará al lugar donde esas personas lo están esperando."
  },
  AvgDialog_126908_Content_22 = {
    Text = "Espero que tanto tú como yo podamos ver cumplidos nuestros deseos.\n\nXu"
  },
  AvgDialog_126908_Content_23 = {
    Text = "Es una extraña broma que se ajusta a la mala personalidad de ese tipo N..."
  },
  AvgDialog_126908_Content_24 = {
    Text = "Murmuras en voz baja, tratando de sacudir el impulso de tu mente."
  },
  AvgDialog_126908_Content_25 = {
    Text = "Pero esta tentación es simplemente demasiado grande, ya que compañeros familiares aparecen en tu mente, hasta que esa figura emerge..."
  },
  AvgDialog_126908_Content_26 = {Text = "Ramona..."},
  AvgDialog_126908_Content_27 = {
    Text = "El latido fuerte llena tu percepción, y tu cuerpo actúa antes de que tu mente pueda seguir; empujas la palanca del tren."
  },
  AvgDialog_126908_Content_28 = {
    Text = "El tren acelera de repente, corriendo hacia el distante agujero negro."
  },
  AvgDialog_126908_Content_29 = {
    Text = "Segundos después, a más de cien metros de distancia, al final del túnel, apareció abruptamente un imponente muro de montaña."
  },
  AvgDialog_126908_Content_3 = {
    Text = "Al final del vagón número uno, una figura esbelta con un abanico cubriendo su rostro te espera en silencio."
  },
  AvgDialog_126908_Content_30 = {
    Text = "¿De qué broma se trata...?"
  },
  AvgDialog_126908_Content_31 = {
    Text = "Tiras con ansiedad de la palanca con fuerza, pero parece que está atascada e inerte, mientras la pared de la montaña se acerca a ti a más de cien kilómetros por hora."
  },
  AvgDialog_126908_Content_32 = {
    Text = "<Red:¡Estás a punto de chocar...>"
  },
  AvgDialog_126908_Content_33 = {
    Text = "Cierras los ojos impotente, esperando el momento en que llegue el impacto."
  },
  AvgDialog_126908_Content_34 = {
    Text = "<Shake:Tan miserable... ¿Por qué fui lo suficientemente tonto como para confiar en alguno de los avatares de N...?>"
  },
  AvgDialog_126908_Content_35 = {
    Text = "¡Boom—!!"
  },
  AvgDialog_126908_Content_36 = {
    Text = "Al segundo siguiente del choque del tren, la sensación de ingravidez te arrastra directamente hacia abajo."
  },
  AvgDialog_126908_Content_37 = {
    Text = "Al segundo siguiente del choque del tren, la sensación de ingravidez te arrastra directamente hacia abajo."
  },
  AvgDialog_126908_Content_38 = {Text = "!!! ¡Uf!"},
  AvgDialog_126908_Content_39 = {
    Text = "El tiempo ha transcurrido durante un tiempo desconocido."
  },
  AvgDialog_126908_Content_4 = {
    Text = "Por favor, permítanme presentarme. Soy Thais en este tren, o también pueden referirse a mí como el topo de N."
  },
  AvgDialog_126908_Content_40 = {Text = "..."},
  AvgDialog_126908_Content_41 = {
    Text = "¿Aquí es...? <Shake:¿Misaq?!>"
  },
  AvgDialog_126908_Content_42 = {
    Text = "La estructura arquitectónica fuera de la ventana es demasiado familiar. La inmensa alegría te hace pasar por alto algunas rarezas, y casi te levantas de ese costoso sillón."
  },
  AvgDialog_126908_Content_43 = {
    Text = "Hasta que veas naturalmente un espejo que está deliberadamente y meticulosamente posicionado en un ángulo."
  },
  AvgDialog_126908_Content_44 = {
    Text = "Dentro reflejaba la cara del Señor Dexter."
  },
  AvgDialog_126908_Content_45 = {Text = "¿¿¿???"},
  AvgDialog_126908_Content_46 = {
    Text = "Tocas tu cara con desconfianza, mientras los dedos de Dexter en el espejo acarician sus mejillas hundidas."
  },
  AvgDialog_126908_Content_47 = {
    Text = "Oh querido, la recompensa por sobrevivir a la lucha interna es \"regresar a Misaq\", pero no hay promesa sobre cómo regresar, ¿verdad?"
  },
  AvgDialog_126908_Content_48 = {
    Text = "El límite de lo que puedo hacer es permitir que tu conciencia use mi avatar por un tiempo."
  },
  AvgDialog_126908_Content_49 = {
    Text = "Supongo que estás a punto de decir: \"¿De lo contrario?\"..."
  },
  AvgDialog_126908_Content_5 = {
    Text = "En una vida que se extiende por miles o incluso decenas de miles de años, estoy más acostumbrada al nombre \"Xu\". Es lo suficientemente ordinario, común y familiar como para ser visto como cualquiera."
  },
  AvgDialog_126908_Content_50 = {
    Text = "Supongo que estás a punto de decir: \"¿De lo contrario?\"..."
  },
  AvgDialog_126908_Content_51 = {
    Text = "¡De lo contrario, clang clang! La campana de medianoche sonará temprano, y la carroza de calabaza y la zapatilla de cristal volverán a sus formas originales."
  },
  AvgDialog_126908_Content_6 = {
    Text = "Tengo muchas cosas que quiero decirte, pero no aquí."
  },
  AvgDialog_126908_Content_7 = {
    Text = "Si el destino lo permite, que podamos encontrarnos de nuevo en el futuro, en otro lugar."
  },
  AvgDialog_126908_Content_8 = {
    Text = "Ella levanta la mano y aplasta el Núcleo de plata."
  },
  AvgDialog_126908_Content_9 = {
    Text = "Eres el vencedor definitivo, Guardián del Secreto."
  },
  AvgDialog_126909_Content_1 = {
    Text = "Tren de los deseos"
  },
  AvgDialog_126909_Content_10 = {
    Text = "<Shake:¡Clang, clang, clang—>"
  },
  AvgDialog_126909_Content_11 = {
    Text = "<Shake:Hmm... tengo tanto sueño...> Dormir en el tren, no importa cuánto duerma, nunca es suficiente."
  },
  AvgDialog_126909_Content_12 = {
    Text = "<LightGray:Parece que mi cerebro está enredado en un lío de goo, olvidando algo crucial...>"
  },
  AvgDialog_126909_Content_13 = {
    Text = "<LightGray:<Shake:(Olvídalo. Las vacaciones del Festival de Oración por el Año son la excusa perfecta—volveré directamente al dormitorio a hacerme la muerta. Aunque Doll presione por tareas o Ramona insista con los informes, resistiré hasta el final...)>>"
  },
  AvgDialog_126909_Content_14 = {
    Text = "Oh querido, qué pequeño brote tan dormilón. Puedes apoyarte en mi hombro hasta que el tren llegue a su destino, ¿de acuerdo?"
  },
  AvgDialog_126909_Content_15 = {Text = "¡Uwa?!"},
  AvgDialog_126909_Content_16 = {
    Text = "Miras a tu alrededor y cuentas el número de pasajeros."
  },
  AvgDialog_126909_Content_17 = {
    Text = "Wanda agitó medio vaso de vino tinto, bajando la cabeza para admirar sus meticulosamente pulidos y afilados uñas."
  },
  AvgDialog_126909_Content_18 = {
    Text = "Tinct sostenía en silencio una partitura, sus labios delgados se movían como si estuviera practicando suavemente en su mente."
  },
  AvgDialog_126909_Content_19 = {
    Text = "Winkle se inclinó junto a la tenue lamparita, su mirada aparentemente fija en la mecha como si temiera que una brizna de luz se escapara."
  },
  AvgDialog_126909_Content_2 = {
    Text = "¡Tarán! Damas y caballeros en la audiencia, ¡feliz Festival de Oración por el Año! ¡Finalmente, es mi turno, pequeño N, de brillar!"
  },
  AvgDialog_126909_Content_20 = {
    Text = "Miryam echó la cabeza hacia atrás y cerró los ojos, aparentemente ajena a los cambios que la rodean."
  },
  AvgDialog_126909_Content_21 = {
    Text = "<LightGray:Todos, la atmósfera de no molestarse entre sí es tan cómoda...>"
  },
  AvgDialog_126909_Content_22 = {Text = "..."},
  AvgDialog_126909_Content_23 = {Text = "..."},
  AvgDialog_126909_Content_24 = {
    Text = "<LightGray:Pero, ¿no está tardando un poco este tren?>"
  },
  AvgDialog_126909_Content_25 = {
    Text = "El tren especial de Misaq está diseñado para atravesar la barrera de niebla fuera del campus; es un tren de corta distancia. Sin embargo, desde que te dormiste y luego despertaste, ya ha pasado al menos una hora."
  },
  AvgDialog_126909_Content_26 = {
    Text = "Después de un momento de reflexión, te acercas al único miembro del grupo de profesores en el vehículo."
  },
  AvgDialog_126909_Content_27 = {
    Text = "Winkle... ¿por qué el <Yellow:tren especial de Misaq> de hoy va tan lento?"
  },
  AvgDialog_126909_Content_28 = {
    Text = "Winkle saltó como un conejo asustado."
  },
  AvgDialog_126909_Content_29 = {
    Text = "¿Qué tren especial de Misaq? ¿No se dirige este tren al planeta hogar de @1?"
  },
  AvgDialog_126909_Content_3 = {
    Text = "Incluso si eres mi doppelgänger, aún debo decir que la diversión que has encontrado esta vez es vergonzosamente inferior. Francamente, roza lo absurdo."
  },
  AvgDialog_126909_Content_30 = {
    Text = "Todas las miradas están centradas en Bígaro como un foco de atención."
  },
  AvgDialog_126909_Content_31 = {
    Text = "No bromees, niña. ¿No es este el tren a Aram?"
  },
  AvgDialog_126909_Content_32 = {
    Text = "Eh, pero Aram está en lo profundo del mar de arena, ¡no puede haber trenes aquí...!"
  },
  AvgDialog_126909_Content_33 = {
    Text = "Hasta donde sé, el destino final de este tren debería ser Isarawu."
  },
  AvgDialog_126909_Content_34 = {
    Text = "Eso es aún más absurdo. ¿No ha sido Isarau destruido hace mucho tiempo?"
  },
  AvgDialog_126909_Content_35 = {
    Text = "Hablar es fácil; tengo los recibos como prueba."
  },
  AvgDialog_126909_Content_36 = {
    Text = "Wanda sacó un boleto de metal y lo mostró frente a todos."
  },
  AvgDialog_126909_Content_37 = {
    Text = "En la estación de desembarque del billete, el nombre Isarawu está escrito de manera prominente."
  },
  AvgDialog_126909_Content_38 = {
    Text = "Miryam, Tinct, ustedes dos..."
  },
  AvgDialog_126909_Content_39 = {
    Text = "Sin necesidad de más palabras, Su voluntad me guiará en el camino de regresar a Lemuria."
  },
  AvgDialog_126909_Content_4 = {
    Text = "No es el Festival de Oración por el Año, así que debemos ofrecer a los espectadores un entretenimiento diferente, ¿verdad."
  },
  AvgDialog_126909_Content_40 = {
    Text = "Quiero aprovechar las vacaciones del Festival de Oración por el Año para volver a Estrella Infausta y pasar un tiempo con mi hermana..."
  },
  AvgDialog_126909_Content_41 = {
    Text = "<LightGray:Estrella Infausta... Tinct vagó durante incontables edades para llegar a Kadas. Esta distancia es completamente inalcanzable para un tren...>"
  },
  AvgDialog_126909_Content_42 = {
    Text = "Lemuria, se hundió en el lecho marino hace mil años."
  },
  AvgDialog_126909_Content_43 = {
    Text = "Y Isaraul... ha sido destruido desde hace mucho tiempo."
  },
  AvgDialog_126909_Content_44 = {
    Text = "Pequeño, has señalado el paisaje durante tanto tiempo. ¿Cuál es el nombre del planeta natal al que quieres regresar y dónde está?"
  },
  AvgDialog_126909_Content_45 = {
    Text = "La expresión de Winkle cambió drásticamente."
  },
  AvgDialog_126909_Content_46 = {
    Text = "<Shake:¡El planeta hogar... es el planeta hogar! ¡El nombre del planeta hogar... es... <Small:@1...>>"
  },
  AvgDialog_126909_Content_47 = {
    Text = "¿Eh? ¿No estoy oyendo mal? ¿Ni siquiera puedes recordar el nombre de tu planeta natal?"
  },
  AvgDialog_126909_Content_48 = {
    Text = "¡Todos, cálmense un momento y escúchenme."
  },
  AvgDialog_126909_Content_49 = {
    Text = "El destino de todos suena muy poco realista. Pero cada persona efectivamente tiene un boleto a su propia patria en la mano."
  },
  AvgDialog_126909_Content_5 = {
    Text = "Aun así, ¿no es demasiado extraño tener solo una escena de principio a fin?"
  },
  AvgDialog_126909_Content_50 = {
    Text = "Por eso, lo que más necesitamos es encontrar al <Yellow:personal de servicio> del tren para obtener información sobre este convoy, en lugar de discutir inútilmente aquí."
  },
  AvgDialog_126909_Content_51 = {Text = "Cof, cof."},
  AvgDialog_126909_Content_52 = {
    Text = "Se escuchó un ruido extraño y algo cómico desde la esquina."
  },
  AvgDialog_126909_Content_53 = {
    Text = "¿Ya se acabó la diversión? Quiero ver un poco más del espectáculo~"
  },
  AvgDialog_126909_Content_54 = {
    Text = "¿Pequeño N?!"
  },
  AvgDialog_126909_Content_55 = {
    Text = "¿Qué pasa? ¿No me dan la bienvenida? ¡Incluso les preparé un gran regalo para el Festival de Oración por el Año!"
  },
  AvgDialog_126909_Content_56 = {
    Text = "El cerebro detrás de escena sale alegremente al centro del escenario. Sus intenciones maliciosas son obvias—debe estar tramando algo aún mayor."
  },
  AvgDialog_126909_Content_57 = {
    Text = "¿Qué estás haciendo aquí?"
  },
  AvgDialog_126909_Content_58 = {
    Text = "¿No es obvio? El yo cariñoso, desinteresado y generoso, en este momento del Festival de Oración por el Año, ha puesto en marcha este tren expreso a casa para que todos los que extrañan su tierra natal puedan disfrutar del calor de las festividades."
  },
  AvgDialog_126909_Content_59 = {
    Text = "No eres tan bondadoso. Dime, ¿qué más estás ocultando?"
  },
  AvgDialog_126909_Content_6 = {
    Text = "<Shake:Wuwu... Los tiempos han cambiado desde que usted manejaba el teatro y trataba con esa dama... ¡El presupuesto del proyecto para este festival es una miseria! Esta configuración del lugar tan escasa es todo lo que podemos costear...>"
  },
  AvgDialog_126909_Content_60 = {
    Text = "Ay, no me apresures, déjame terminar de hablar poco a poco."
  },
  AvgDialog_126909_Content_61 = {
    Text = "Mucha gente quiere volver a casa, pero solo hay un tren. Así que, solo una persona puede regresar a su ansiado hogar, ¿verdad?"
  },
  AvgDialog_126909_Content_62 = {
    Text = "Oh querido, como un N considerado, desinteresado y benevolente, debo utilizar los medios más justos para determinar quién puede obtener esta calificación, ¿verdad?"
  },
  AvgDialog_126909_Content_63 = {
    Text = "Así que..."
  },
  AvgDialog_126909_Content_64 = {
    Text = "<Big:¡Así que, <Shake:<Red:empiecen a matarse entre sí>>!>"
  },
  AvgDialog_126909_Content_65 = {
    Text = "¡Maten a todos, el último en sobrevivir podrá decidir el destino de este tren y tendrá la oportunidad de obtener un <Yellow:viaje de un día a la tierra natal>!"
  },
  AvgDialog_126909_Content_66 = {
    Text = "¡Imposible! Nadie tomaría la vida de otra persona por algo así... ¿verdad?!"
  },
  AvgDialog_126909_Content_67 = {
    Text = "Tienes razón, aunque extraño mucho a Faint... no puedo participar en una competencia tan cruel..."
  },
  AvgDialog_126909_Content_68 = {
    Text = "Hmph, quedarse aquí para disfrutar de buen vino y sirvientes no está tan mal. Isaraul es solo un capítulo de mi pasado."
  },
  AvgDialog_126909_Content_69 = {
    Text = "Aunque es difícil despedirse... mis pequeños brotes están aquí, y los Aram ya no dependen de mí para liderar la tribu. Supongo que no tengo ninguna motivación para participar en esta matanza mutua."
  },
  AvgDialog_126909_Content_7 = {
    Text = "Parece que solo puedo... observar y esperar."
  },
  AvgDialog_126909_Content_70 = {
    Text = "Todas las miradas de todos se reunieron en la última persona."
  },
  AvgDialog_126909_Content_71 = {Text = "..."},
  AvgDialog_126909_Content_72 = {
    Text = "Vuestra mirada no le causó la más mínima interferencia; Miryam permaneció en silencio."
  },
  AvgDialog_126909_Content_73 = {
    Text = "Eres consciente de su obsesión, entendiendo el significado y el valor de la palabra Lemuria para ella."
  },
  AvgDialog_126909_Content_74 = {
    Text = "Ay, sabía que no sería tan simple..."
  },
  AvgDialog_126909_Content_75 = {
    Text = "Para evitar esta situación incómoda, refiné específicamente las reglas— debes traerme 5 fallecidos para intercambiar por el último boleto."
  },
  AvgDialog_126909_Content_76 = {
    Text = "¡Necesitas recoger los siete boletos para encender el tren!"
  },
  AvgDialog_126909_Content_77 = {
    Text = "En otras palabras, nadie puede salir de aquí hasta que solo quede una persona después de la masacre en el tren."
  },
  AvgDialog_126909_Content_78 = {
    Text = "Además, hay un <Yellow:topo> entre ustedes que yo infiltré, ¡es un avatar del polifacético pequeño N!"
  },
  AvgDialog_126909_Content_79 = {
    Text = "¡Si no hacen nada, los matará uno por uno! ¡Para entonces, nadie podrá regresar!"
  },
  AvgDialog_126909_Content_8 = {
    Text = "¡Sin más preámbulos, el pequeño N les trae <Shake:el <Red:teatro de interpretación exclusivo del Festival de Oración por el Año>, el más nuevo y candente>!"
  },
  AvgDialog_126909_Content_81 = {
    Text = "Apenas N terminó de hablar, una enredadera atravesó repentinamente la niebla negra."
  },
  AvgDialog_126909_Content_82 = {
    Text = "Bueno, todos. No escuchen las palabras engañosas de este tipo."
  },
  AvgDialog_126909_Content_83 = {
    Text = "Somos seis, incluyendo al más notable Guardián del Secreto de Misaq, ¿realmente no podemos escapar de este pequeño compartimento?"
  },
  AvgDialog_126909_Content_9 = {
    Text = "¡Los aplausos y vítores resuenan!"
  },
  AvgDialog_126910_Content_1 = {
    Text = "Segundo muerto"
  },
  AvgDialog_126910_Content_10 = {
    Text = "¿No es más urgente encontrar al asesino entre nosotros?"
  },
  AvgDialog_126910_Content_11 = {
    Text = "No, no lo creo... Solo somos tan pocos, y si caemos en la sospecha mutua, solo empeorará la situación."
  },
  AvgDialog_126910_Content_12 = {
    Text = "Más importante aún, necesitamos garantizar la seguridad de las personas restantes. ¿Qué tal si todos nos quedamos en el vagón 2?"
  },
  AvgDialog_126910_Content_13 = {
    Text = "Miraste a Winkle, que lucía demacrado, y asentiste."
  },
  AvgDialog_126910_Content_14 = {
    Text = "El pequeño brote ha tomado una decisión, y ciertamente no me opondré a ella."
  },
  AvgDialog_126910_Content_15 = {
    Text = "...cada tres horas, necesito encontrar un rincón tranquilo para rezar solo."
  },
  AvgDialog_126910_Content_16 = {
    Text = "¡De ninguna manera! ¡Quién sabe qué cosas malas podrías hacer mientras estás rezando!"
  },
  AvgDialog_126910_Content_17 = {
    Text = "Además, cuando todos estaban discutiendo la idea de renunciar a matarse entre ustedes, tú fuiste el único que no expresó su opinión. ¿Quién sabe si eres uno de los secuaces de N?"
  },
  AvgDialog_126910_Content_18 = {
    Text = "Solo hay un Señor al que sirvo, y ese es la deidad de Lemuria."
  },
  AvgDialog_126910_Content_19 = {
    Text = "Sin embargo, si pronuncias más palabras de profanación, no dudaré en impartir el castigo divino en nombre de mi Señor."
  },
  AvgDialog_126910_Content_2 = {
    Text = "Tres horas después, en el vagón"
  },
  AvgDialog_126910_Content_20 = {
    Text = "Al ver que Miryam ya ha sacado la daga, te apresuras a mediar."
  },
  AvgDialog_126910_Content_21 = {
    Text = "Actualmente no tenemos pruebas para acusar a nadie, Tinct... Todos estaban dormidos en ese momento."
  },
  AvgDialog_126910_Content_22 = {
    Text = "Además, ese supuesto topo podría ser solo uno de los trucos de N, atrayéndonos a matarnos entre nosotros según su diseño."
  },
  AvgDialog_126910_Content_23 = {
    Text = "¿Cómo puedes decir eso de ellos? Boohoo, realmente lo decía de corazón para recordarte——"
  },
  AvgDialog_126910_Content_24 = {
    Text = "<LightGray:Cuchillo Ocular...>"
  },
  AvgDialog_126910_Content_25 = {
    Text = "Está bien, está bien, me estoy desvaneciendo, uu uu uu..."
  },
  AvgDialog_126910_Content_26 = {
    Text = "Con un estallido, la figura del pequeño N desapareció en el aire."
  },
  AvgDialog_126910_Content_27 = {
    Text = "En ese caso... Miryam, ¿podrías rezar sola en el vagón número 1 y no irte sin permiso?"
  },
  AvgDialog_126910_Content_28 = {
    Text = "Nos encontraremos en la puerta trasera del vagón 1, mientras que los demás están todos en la misma habitación, así que no habrá peligro."
  },
  AvgDialog_126910_Content_29 = {
    Text = "¿No es así que esto no es muy... para Miryam?"
  },
  AvgDialog_126910_Content_3 = {
    Text = "<Shake:¡Glug glug glug—>"
  },
  AvgDialog_126910_Content_30 = {
    Text = "No tengo objeciones."
  },
  AvgDialog_126910_Content_31 = {
    Text = "Miryam no prestó atención a tu obstáculo y se levantó directamente para salir del coche número 2, sin olvidar girar cuidadosamente y cerrar la puerta de separación."
  },
  AvgDialog_126910_Content_32 = {
    Text = "Las personas restantes deberían poder estar tranquilas ahora..."
  },
  AvgDialog_126910_Content_33 = {
    Text = "Siempre siento que este asunto no es tan simple..."
  },
  AvgDialog_126910_Content_34 = {
    Text = "Una hora después, en el vagón número 2"
  },
  AvgDialog_126910_Content_35 = {Text = "Mmm..."},
  AvgDialog_126910_Content_36 = {
    Text = "Me iré por un tiempo..."
  },
  AvgDialog_126910_Content_37 = {
    Text = "Winkle se tambaleó hacia la intersección del vagón."
  },
  AvgDialog_126910_Content_38 = {
    Text = "<LightGray:¿He tomado demasiado café...?>"
  },
  AvgDialog_126910_Content_39 = {
    Text = "Una hora después, en el vagón número 2"
  },
  AvgDialog_126910_Content_4 = {Text = "No bebas."},
  AvgDialog_126910_Content_40 = {
    Text = "<LightGray:Extraño, ¿por qué no ha vuelto Winkle aún...>"
  },
  AvgDialog_126910_Content_41 = {
    Text = "¿Estás muy preocupado? ¿Quieres que te acompañe a un chequeo?"
  },
  AvgDialog_126910_Content_42 = {Text = "Vamos."},
  AvgDialog_126910_Content_43 = {
    Text = "La sensación de inquietud se propaga en el pecho, los pasos huecos y las sombras ocupan todo el vagón."
  },
  AvgDialog_126910_Content_44 = {
    Text = "Entiendes ese nombre sombrío—"
  },
  AvgDialog_126910_Content_45 = {Text = "Muerte."},
  AvgDialog_126910_Content_46 = {
    Text = "Tocas repetidamente la puerta del baño, llamando el nombre de Winkle, pero no hay respuesta."
  },
  AvgDialog_126910_Content_47 = {
    Text = "Ustedes comienzan a intentar derribar la puerta."
  },
  AvgDialog_126910_Content_48 = {
    Text = "Dong, dong, dong!"
  },
  AvgDialog_126910_Content_49 = {
    Text = "¿Pasó algo?"
  },
  AvgDialog_126910_Content_5 = {
    Text = "<Shake:¡Glug glug glug—>"
  },
  AvgDialog_126910_Content_50 = {
    Text = "Wanda también fue atraída por el ruido inusual."
  },
  AvgDialog_126910_Content_51 = {
    Text = "Winkle ha estado en el baño durante una hora. Llamamos a la puerta, pero no hubo respuesta."
  },
  AvgDialog_126910_Content_52 = {
    Text = "La puerta tampoco puede ser derribada, es extraño, un grupo de Despertados puede entrar al cielo y a la tierra, convocar vientos y lluvias, y es capaz de cualquier cosa contra criaturas míticas, ¡sin embargo no pueden abrir una sola puerta!"
  },
  AvgDialog_126910_Content_53 = {
    Text = "¿Han oído hablar del nuevo género?"
  },
  AvgDialog_126910_Content_54 = {
    Text = "Hablando del nuevo género, no se puede dejar de mencionar el género clásico."
  },
  AvgDialog_126910_Content_56 = {
    Text = "En el contexto del razonamiento, las obras clásicas se refieren a obras de deducción con misterios claros y razonamientos lógicos, mientras que el nuevo clásico añade configuraciones de mundos únicos a esta base."
  },
  AvgDialog_126910_Content_57 = {
    Text = "Aun así, el nuevo clásico debe respetar a los lectores y la equidad, y debe plantear preguntas dentro del ámbito de los escenarios conocidos para los lectores, sin permitir adiciones arbitrarias de elementos sobrenaturales."
  },
  AvgDialog_126910_Content_58 = {
    Text = "En otras palabras, si no tienen la habilidad para desbloquear, no pueden simplemente abrir la puerta que está cerrada desde adentro."
  },
  AvgDialog_126910_Content_59 = {
    Text = "El pequeño N subió a la rejilla de equipaje por un tiempo, luego se escondió detrás del respaldo de la silla, esquivando todas las espinas y enredaderas mientras terminaba su discurso largo y tedioso."
  },
  AvgDialog_126910_Content_6 = {Text = "Winkle..."},
  AvgDialog_126910_Content_60 = {
    Text = "Entonces, ¿quieres decir que... este es un asesinato en un cuarto cerrado, y dentro está la escena del crimen?"
  },
  AvgDialog_126910_Content_61 = {
    Text = "¡Quién sabe! ¿Y si Winkle huyó por miedo al castigo y saltó del coche por la ventana del baño?"
  },
  AvgDialog_126910_Content_62 = {
    Text = "¿No dijiste que no podemos salir del tren?"
  },
  AvgDialog_126910_Content_63 = {
    Text = "¡Ay, ay, ay! ¡Hubo un fallo en la deducción!"
  },
  AvgDialog_126910_Content_64 = {
    Text = "Antes de que aparezca el verdadero gran detective, siempre tiene que haber un tipo responsable de la deducción incorrecta."
  },
  AvgDialog_126910_Content_65 = {
    Text = "Si nadie quiere asumir el papel del tonto, ¡entonces déjenme, el gran y devoto pequeño N, interpretarlo!"
  },
  AvgDialog_126910_Content_66 = {
    Text = "Deja de hablar tonterías con este tipo."
  },
  AvgDialog_126910_Content_67 = {
    Text = "Aunque es un poco grosero... hay una pequeña ventana con persianas en la puerta del baño, y la estructura es muy frágil."
  },
  AvgDialog_126910_Content_68 = {
    Text = "Wanda levantó la espina."
  },
  AvgDialog_126910_Content_69 = {
    Text = "Crujido, las persianas han sido bajadas."
  },
  AvgDialog_126910_Content_7 = {
    Text = "No importa cuánto café se beba, Tinct no volverá a la vida, ¿verdad?"
  },
  AvgDialog_126910_Content_70 = {
    Text = "Déjamelo a mí."
  },
  AvgDialog_126910_Content_71 = {
    Text = "Las vides se adentraron y desbloquearon la puerta, y ustedes empujaron la puerta para entrar."
  },
  AvgDialog_126910_Content_72 = {
    Text = "No queda tiempo."
  },
  AvgDialog_126910_Content_73 = {
    Text = "Winkle se acurrucó en silencio en la esquina del baño."
  },
  AvgDialog_126910_Content_74 = {Text = "¡Bígaro!"},
  AvgDialog_126910_Content_75 = {
    Text = "Te apresuraste a ir hacia Winkle, de cuyos labios fluía un profundo plasma rojo, y ya había perdido el aliento."
  },
  AvgDialog_126910_Content_76 = {
    Text = "Para ser franco, Winkle... en el momento de tu fallecimiento, ni tú, ni yo, ni Wanda dejamos el coche número 2."
  },
  AvgDialog_126910_Content_77 = {
    Text = "El único asesino... solo puede ser Miryam."
  },
  AvgDialog_126910_Content_78 = {
    Text = "Mi señor no me ha guiado a realizar tales acciones. Sin embargo, si insistes, no tengo inconveniente en impartir juicio en nombre de los dioses."
  },
  AvgDialog_126910_Content_79 = {
    Text = "¡Ay, no podemos ponernos de acuerdo!"
  },
  AvgDialog_126910_Content_8 = {
    Text = "<Shake:¡Tú—!>"
  },
  AvgDialog_126910_Content_80 = {
    Text = "¡Ya que estamos hablando del juicio de los dioses, quiero daros una <Yellow:¡oportunidad de ganar fácilmente>!"
  },
  AvgDialog_126910_Content_81 = {
    Text = "Ahora podemos llevar a cabo una votación, y la persona con más votos será expulsada personalmente del tren por mí, ¡perdiendo su oportunidad de regresar a casa!"
  },
  AvgDialog_126910_Content_82 = {
    Text = "Sin duda, convocaré a Miryam."
  },
  AvgDialog_126910_Content_83 = {Text = "Thais."},
  AvgDialog_126910_Content_84 = {
    Text = "Pequeño, ¿qué piensas? Dada la situación actual, yo también elegiría votar por Miryam."
  },
  AvgDialog_126910_Content_85 = {
    Text = "¡Miryam 2 votos! ¡Thais 1 voto!"
  },
  AvgDialog_126910_Content_86 = {
    Text = "N, si hay un empate, ¿cómo se calcula el resultado?"
  },
  AvgDialog_126910_Content_87 = {
    Text = "Si es un empate, se considera que nadie está fuera~"
  },
  AvgDialog_126910_Content_88 = {
    Text = "¡Pero piénsalo bien! Solo quedan cuatro personas. Si renuncias a esta oportunidad y el traidor ataca de nuevo, ¡las posibilidades de sobrevivir caerán en picado!"
  },
  AvgDialog_126910_Content_89 = {
    Text = "No quiero hacer daño a las buenas personas. Voto por Thais."
  },
  AvgDialog_126910_Content_9 = {
    Text = "Así es, lo que es más crucial es encontrar una manera de salir del tren."
  },
  AvgDialog_126910_Content_90 = {
    Text = "¿De verdad no vas a reconsiderar? Esta es la única oportunidad para votar?"
  },
  AvgDialog_126910_Content_91 = {
    Text = "No, cuanto más dices eso, más siento que tomé la decisión correcta."
  },
  AvgDialog_126910_Content_92 = {
    Text = "De acuerdo, el resultado de la votación de esta ronda es: un empate, y nadie está fuera~"
  },
  AvgDialog_126910_Content_93 = {
    Text = "Suspira~ Gran decepción~ El pequeño N también necesita encontrar un rincón para calmarse. ¡Hasta luego a todos!"
  },
  AvgDialog_126911_Content_1 = {
    Text = "El juego ha comenzado"
  },
  AvgDialog_126911_Content_10 = {
    Text = "Si sigues divagando, no me importaría usar esto para que vuelvas a experimentar la sensación de ser atravesado por el corazón, ¿sabes?"
  },
  AvgDialog_126911_Content_11 = {
    Text = "Wanda acaricia la espina en su palma."
  },
  AvgDialog_126911_Content_12 = {
    Text = "Ay, qué declaración tan dolorosa."
  },
  AvgDialog_126911_Content_13 = {
    Text = "¿Es realmente tan impopular el programa del Festival de Oración por el Año que preparó cuidadosamente Xiao N? <Shake: ¡Bua bua...>"
  },
  AvgDialog_126911_Content_14 = {
    Text = "Fingiendo llorar durante menos de un segundo, N inmediatamente rompió en una brillante sonrisa."
  },
  AvgDialog_126911_Content_15 = {
    Text = "¡En resumen, por favor denlo todo y luchen entre ustedes! ¡El pequeño N estará esperando sus actuaciones!"
  },
  AvgDialog_126911_Content_16 = {
    Text = "\"¡Swish!\" el pequeño N desapareció de nuevo. \n El tren volvió a caer en el inquietante silencio."
  },
  AvgDialog_126911_Content_17 = {
    Text = "Lo que sigue es un largo silencio, la oscuridad delante en las vías parece interminable."
  },
  AvgDialog_126911_Content_18 = {
    Text = "¿Cuánto tiempo más viajará el tren? ¿A dónde se dirigirá el destino?"
  },
  AvgDialog_126911_Content_19 = {
    Text = "En los corazones de las personas, puede que no haya respuesta, o puede que haya una respuesta que no se puede pronunciar."
  },
  AvgDialog_126911_Content_2 = {
    Text = "......no puedo salir."
  },
  AvgDialog_126911_Content_20 = {
    Text = "Eso, todos..."
  },
  AvgDialog_126911_Content_21 = {
    Text = "Una voz clara rompió la calma."
  },
  AvgDialog_126911_Content_22 = {
    Text = "Estar aquí encerrado es bastante aburrido... Si a todos no les molesta el disturbio, ¿qué tal si les canto una canción?"
  },
  AvgDialog_126911_Content_23 = {
    Text = "¡Hmm?! ¡Me encanta esto! ¿Puedo pedir una canción?"
  },
  AvgDialog_126911_Content_24 = {
    Text = "¡Vete, vete, vete! ¿Qué te importa?"
  },
  AvgDialog_126911_Content_25 = {
    Text = "Dado que es el Festival de Oración por el Año del Reino antiguo de Panlong, recuerdo una balada oriental que una vez escuché interpretada por el Coro de Sombras."
  },
  AvgDialog_126911_Content_26 = {
    Text = "No estoy seguro de si he dominado suficientes piezas orientales..."
  },
  AvgDialog_126911_Content_27 = {
    Text = "El nombre de esa canción es «Flor de Jazmín»."
  },
  AvgDialog_126911_Content_28 = {
    Text = "¿Oh? ¿Es esta canción?"
  },
  AvgDialog_126911_Content_29 = {
    Text = "¡Qué coincidencia, yo también estaba en la audiencia para esa actuación del Coro de Sombras."
  },
  AvgDialog_126911_Content_3 = {
    Text = "Winkle pronunció la conclusión con desánimo."
  },
  AvgDialog_126911_Content_30 = {
    Text = "Si no recuerdo mal, también me encontré con... en la audiencia."
  },
  AvgDialog_126911_Content_31 = {
    Text = "La mirada de Wanda está fijada en Miryam, mientras que Miryam solo asiente en silencio."
  },
  AvgDialog_126911_Content_32 = {
    Text = "Como nadie se opone... comenzaré a cantar."
  },
  AvgDialog_126911_Content_33 = {
    Text = "Tinct aclaró su garganta."
  },
  AvgDialog_126911_Content_34 = {
    Text = "<Shake:¡Qué flor de jazmín, qué flor de jazmín♪~ Ninguna flor en todo el jardín puede compararse a ella♪~>"
  },
  AvgDialog_126911_Content_35 = {
    Text = "<Shake:¡Lalalalala~lalalala~lalalala♪~>"
  },
  AvgDialog_126911_Content_36 = {
    Text = "Una melodía etérea y suave resuena en el vagón vacío."
  },
  AvgDialog_126911_Content_37 = {
    Text = "Bajo el consuelo de la melodía suave, las cuerdas tensas en tu mente se relajan gradualmente, y sorprendentemente sientes un atisbo de somnolencia."
  },
  AvgDialog_126911_Content_38 = {
    Text = "Supongo que todos están cansados, ¿verdad? Estoy acostumbrado a no dormir, así que puedo vigilar por todos."
  },
  AvgDialog_126911_Content_39 = {
    Text = "Asientes y luego te sumerges profundamente en el sueño que ha estado invadiendo desde hace tiempo."
  },
  AvgDialog_126911_Content_4 = {
    Text = "Aparte de la cabina, este tren consta de tres vagones. Actualmente estamos en el vagón número 2, que es el del medio."
  },
  AvgDialog_126911_Content_40 = {Text = "..."},
  AvgDialog_126911_Content_41 = {
    Text = "Después de un largo tiempo, Tinct también terminó de cantar."
  },
  AvgDialog_126911_Content_42 = {
    Text = "Todos están dormidos, así que tú también deberías descansar un rato, ¿verdad?"
  },
  AvgDialog_126911_Content_43 = {
    Text = "¿De verdad no importa?"
  },
  AvgDialog_126911_Content_44 = {
    Text = "¿Qué, tienes miedo de que sea el traidor?"
  },
  AvgDialog_126911_Content_45 = {
    Text = "Eso no pasará. Solo que en el pasado, siempre esperaba a que Faint se quedara dormido antes de ir a descansar..."
  },
  AvgDialog_126911_Content_46 = {
    Text = "Así que hoy, ¡es tu turno de descansar bien! Vamos, vamos."
  },
  AvgDialog_126911_Content_47 = {
    Text = "Bajo la insistencia de Winkle, Tinct también tomó una manta, apoyándose contra el respaldo de la silla y cerrando los ojos."
  },
  AvgDialog_126911_Content_48 = {
    Text = "No es de extrañar que todos estén dormidos; es un ambiente tan relajante..."
  },
  AvgDialog_126911_Content_49 = {Text = "..."},
  AvgDialog_126911_Content_5 = {
    Text = "El vagón 1 y el vagón 3 están vacíos, con todas las ventanas y puertas completamente cerradas, es imposible romper a través de ellos utilizando medios físicos o Tecnología de núcleo de plata."
  },
  AvgDialog_126911_Content_50 = {Text = "..."},
  AvgDialog_126911_Content_51 = {Text = "Mmm...?"},
  AvgDialog_126911_Content_52 = {
    Text = "Lo primero que llama la atención es el rostro tranquilo y sereno de Winkle mientras duerme."
  },
  AvgDialog_126911_Content_53 = {
    Text = "Las luces del tren se apagaron en algún momento, y el entorno circundante fue engullido por la oscuridad, con solo una suave luz brillando a través de la conexión entre los vagones."
  },
  AvgDialog_126911_Content_54 = {
    Text = "Winkle... ¿cómo te quedaste dormido...?"
  },
  AvgDialog_126911_Content_55 = {
    Text = "Winkle dejó escapar un suave suspiro."
  },
  AvgDialog_126911_Content_56 = {
    Text = "¿Hmm...? ¿Me quedé... dormido?"
  },
  AvgDialog_126911_Content_57 = {
    Text = "¡Eh eh eh? ¡¿Me quedé dormido?!!"
  },
  AvgDialog_126911_Content_58 = {
    Text = "El grito de Winkle fue como un viento violento, despertando instantáneamente a todos los pasajeros dormidos."
  },
  AvgDialog_126911_Content_59 = {
    Text = "Las luces se encendieron de repente, iluminando todo el vagón."
  },
  AvgDialog_126911_Content_6 = {
    Text = "¡Te lo dije! ¡No hay necesidad de alborotar! ¡Nadie puede salir hasta que solo quede un ganador en el coche!"
  },
  AvgDialog_126911_Content_60 = {
    Text = "Queridos pasajeros, ¿están descansando bien en el Expreso de Regreso a Casa?"
  },
  AvgDialog_126911_Content_61 = {
    Text = "¡Después de detectar que todos los pasajeros han entrado en estado de sueño, el pequeño N ha preparado especialmente un ambiente tranquilo y que bloquea la luz para ustedes!"
  },
  AvgDialog_126911_Content_62 = {
    Text = "Lo siento, normalmente dependo de beber mucho café para mantenerme despierto..."
  },
  AvgDialog_126911_Content_63 = {
    Text = "Espera, ¿falta uno de nosotros?"
  },
  AvgDialog_126911_Content_64 = {Text = "..."},
  AvgDialog_126911_Content_65 = {
    Text = "¿Eh? ¿El pequeño brote me está mirando? Estoy aquí."
  },
  AvgDialog_126911_Content_66 = {
    Text = "Entonces, la persona desaparecida es..."
  },
  AvgDialog_126911_Content_67 = {
    Text = "Todas las miradas de todos se dirigieron al final del vagón——"
  },
  AvgDialog_126911_Content_68 = {
    Text = "Un gran agujero fue perforado en la garganta de Tinct por algún objeto afilado, y el plasma sanguíneo fluía por su cuello grácil como el de un cisne desde la herida, empapando la parte delantera de su vestido."
  },
  AvgDialog_126911_Content_69 = {
    Text = "El ruiseñor que sangra ya no puede cantar."
  },
  AvgDialog_126911_Content_7 = {
    Text = "¿Cómo que otra vez... No era Thais quien te... hace un momento?"
  },
  AvgDialog_126911_Content_70 = {
    Text = "<Shake:¡AAAAAAH—!!!>"
  },
  AvgDialog_126911_Content_71 = {
    Text = "Winkle dejó escapar un grito que atravesó el cielo nocturno, deslizándose por la pared hasta la esquina, envolviéndose los brazos con fuerza alrededor de sí mismo, temblando incontrolablemente."
  },
  AvgDialog_126911_Content_72 = {
    Text = "<Shake:Lo siento... no debería haber estado tan seguro de mí mismo... no debería haber vigilado solo... no debería haber pensado que no me quedaría dormido sin café...>"
  },
  AvgDialog_126911_Content_73 = {
    Text = "Winkle mordía sus uñas impacientemente, las lágrimas de pánico brotaban continuamente y caían sobre la alfombra."
  },
  AvgDialog_126911_Content_74 = {
    Text = "¡Ta-da! ¿Qué escuchó el comprensivo pequeño N? <Shake:¡Las necesidades de los pasajeros!>"
  },
  AvgDialog_126911_Content_75 = {
    Text = "Servicio atento, en camino—¡una <Yellow:máquina de café ilimitada!>"
  },
  AvgDialog_126911_Content_76 = {
    Text = "¡Mientras presiones este botón rojo, un torrente interminable de intenso y profundo calor americano brotará de la boquilla!"
  },
  AvgDialog_126911_Content_77 = {
    Text = "Te acercas en silencio, levantando la mano—"
  },
  AvgDialog_126911_Content_78 = {
    Text = "Luego golpeé con fuerza a ese pequeño N que estaba delante de mí, aplastándolo."
  },
  AvgDialog_126911_Content_79 = {
    Text = "<Shake:Lo siento... lo siento, lo siento mucho...>"
  },
  AvgDialog_126911_Content_8 = {
    Text = "Hmph, si fuera tan fácil morir, ¡no sería mi pequeño N!"
  },
  AvgDialog_126911_Content_80 = {
    Text = "El ecos del sollozo de Winkle resonaba en el vagón."
  },
  AvgDialog_126911_Content_81 = {
    Text = "No importa cómo resistan, la apertura será marcada por la muerte de Tinct——"
  },
  AvgDialog_126911_Content_82 = {
    Text = "El asesinato entre nosotros ha comenzado."
  },
  AvgDialog_126911_Content_9 = {
    Text = "Entonces, ¿cómo está todo el mundo? ¿Todos han decidido en su corazón el objetivo de la muerte de esta noche?"
  },
  AvgDialog_126912_Content_1 = {
    Text = "Movimiento secreto"
  },
  AvgDialog_126912_Content_10 = {
    Text = "Por alguna razón, siempre sientes que debajo de esa sonrisa se oculta una emoción que aún no conoces."
  },
  AvgDialog_126912_Content_11 = {
    Text = "Vamos, Miryam. Vamos al vagón número 1."
  },
  AvgDialog_126912_Content_12 = {
    Text = "En el momento en que la puerta de conexión está a punto de cerrarse, Wanda gira su cuerpo y mira hacia atrás."
  },
  AvgDialog_126912_Content_13 = {
    Text = "Feliz Festival de Oración por el Año, Guardián del secreto."
  },
  AvgDialog_126912_Content_14 = {Text = "..."},
  AvgDialog_126912_Content_15 = {
    Text = "Vagón No. 2"
  },
  AvgDialog_126912_Content_16 = {
    Text = "Después de que Wanda y Miryam se fueron, solo quedaste tú y Thais en el vagón."
  },
  AvgDialog_126912_Content_17 = {
    Text = "A continuación, ¿qué deberíamos hacer con este raro tiempo a solas, mi pequeño brote?"
  },
  AvgDialog_126912_Content_18 = {
    Text = "Thais se acerca repentinamente con malas intenciones, sorprendiendo a ti y haciéndote retroceder medio paso para mantener una distancia segura."
  },
  AvgDialog_126912_Content_19 = {
    Text = "Puedo ir a apresurar el informe..."
  },
  AvgDialog_126912_Content_2 = {
    Text = "Vagón No. 2"
  },
  AvgDialog_126912_Content_20 = {
    Text = "Ya es el Festival de Oración por el Año, así que relájate un poco y deja de pensar en tu informe todo el tiempo."
  },
  AvgDialog_126912_Content_21 = {
    Text = "Sus brazos color miel se envuelven suavemente alrededor de tus hombros, sus respiraciones ambiguas se entrelazan contigo como la niebla nocturna."
  },
  AvgDialog_126912_Content_22 = {Text = "Esto..."},
  AvgDialog_126912_Content_23 = {
    Text = "La expresión seria de Doll, el suspiro de Ramona y la vara de enseñanza de Czort parpadean instantáneamente ante tus ojos."
  },
  AvgDialog_126912_Content_24 = {
    Text = "Aún no puedo..."
  },
  AvgDialog_126912_Content_25 = {
    Text = "Sonríes de manera servil, aparentemente evitando de forma casual la ternura de Thais."
  },
  AvgDialog_126912_Content_26 = {
    Text = "Está bien, ¿qué tal si nos sentamos en silencio y charlamos un rato?"
  },
  AvgDialog_126912_Content_27 = {
    Text = "Dime, Guardián del Secreto... En ese momento fugaz cuando tu mirada titubeó, ¿en quién estabas pensando?"
  },
  AvgDialog_126912_Content_28 = {Text = "..."},
  AvgDialog_126912_Content_29 = {Text = "..."},
  AvgDialog_126912_Content_3 = {
    Text = "En medio del rugido del tren, Wanda fue la primera en romper el silencio."
  },
  AvgDialog_126912_Content_30 = {
    Text = "No recuerdas cuánto tiempo has estado narrando, solo que los eventos pasados están vívidamente claros en tu mente."
  },
  AvgDialog_126912_Content_31 = {
    Text = "Y luego está el comedor de Misaq, que es un lugar mucho más animado que el laboratorio."
  },
  AvgDialog_126912_Content_32 = {
    Text = "Especialmente cuando los pastelitos están disponibles, los niños corren hacia el mostrador, ignorando por completo la elegancia y la virtud de la gracia y la modestia de una dama..."
  },
  AvgDialog_126912_Content_33 = {
    Text = "Algunos pequeños alborotadores hacen trampa al hacer que sus amigos animales sostengan los boletos de comida y ocupen espacio en el área de servicio, luego les dan los pasteles que han robado a sus amigos tímidos."
  },
  AvgDialog_126912_Content_34 = {
    Text = "<Shake:¿Y... eh?>"
  },
  AvgDialog_126912_Content_35 = {
    Text = "Descubres que tu tono se quiebra, y las lágrimas caen involuntariamente de tus ojos."
  },
  AvgDialog_126912_Content_36 = {
    Text = "Hay más..."
  },
  AvgDialog_126912_Content_37 = {
    Text = "Las lágrimas se acumulan cada vez más, volviendo mi visión cada vez más borrosa."
  },
  AvgDialog_126912_Content_38 = {
    Text = "<Shake:Realmente quiero volver a Misaq, volver a estar con todos de nuevo...>"
  },
  AvgDialog_126912_Content_39 = {
    Text = "Es extraño, claramente salí de Misaq <Yellow:hace tres días> para realizar una investigación de campo, no debería ser..."
  },
  AvgDialog_126912_Content_4 = {
    Text = "Tengo una sugerencia."
  },
  AvgDialog_126912_Content_40 = {
    Text = "Pero la angustia del anhelo hace que te duela la nariz, como si hubiera una cuerda tensada en tu mente al borde de romperse."
  },
  AvgDialog_126912_Content_41 = {
    Text = "Tranquilo, tranquilo, Guardián del Secreto."
  },
  AvgDialog_126912_Content_42 = {
    Text = "Te sumerges en un abrazo suave. Un abrazo de madre."
  },
  AvgDialog_126912_Content_43 = {
    Text = "@2 Te lo prometo, regresarás al lugar que anhelas."
  },
  AvgDialog_126912_Content_44 = {
    Text = "Los rasgos de Thais se volvieron borrosos."
  },
  AvgDialog_126912_Content_45 = {
    Text = "La niebla brumosa envolvió a los dos, y te acurrucaste en su abrazo, convirtiéndote en un ser muy pequeño."
  },
  AvgDialog_126912_Content_46 = {
    Text = "Hueles la fragancia. <Yellow:El aroma de magnolia blanca>."
  },
  AvgDialog_126912_Content_47 = {
    Text = "<Red:La fragancia de grandes flores de magnolia blanca.>"
  },
  AvgDialog_126912_Content_48 = {
    Text = "Te encuentras envuelto en esta fragante aroma, cayendo en un sueño similar al de un bebé que te hace olvidar todas las preocupaciones y todos los miedos."
  },
  AvgDialog_126912_Content_49 = {
    Text = "Antes de que la conciencia se desvanezca, lo único que recuerdas son los <Yellow:ojos dorados y anhelantes> de madre."
  },
  AvgDialog_126912_Content_5 = {
    Text = "Podemos emparejarnos y quedarnos en los vagones 1 y 2, así podremos cuidarnos mutuamente."
  },
  AvgDialog_126912_Content_50 = {Text = "..."},
  AvgDialog_126912_Content_51 = {
    Text = "Luego——"
  },
  AvgDialog_126912_Content_52 = {
    Text = "Un fuerte \"clang\" vino del vagón número 1."
  },
  AvgDialog_126912_Content_53 = {
    Text = "Sabes que el juego de la masacre mutua sigue en curso, y el sueño debería despertar."
  },
  AvgDialog_126912_Content_54 = {
    Text = "Vagón No. 1"
  },
  AvgDialog_126912_Content_55 = {
    Text = "En el coche número 1, los cuerpos gravemente heridos de Wanda y Miryam estaban entrelazados, con una daga completamente clavada en el pecho de Wanda, mientras que Miryam estaba atravesada por innumerables espinas."
  },
  AvgDialog_126912_Content_56 = {
    Text = "Wanda entreabrió los ojos aturdidos y les reveló intermitentemente."
  },
  AvgDialog_126912_Content_57 = {
    Text = "Sabía que Miryam atacaría, así que estaba listo para un \"Contrataque\"..."
  },
  AvgDialog_126912_Content_58 = {
    Text = "Ahora, N no tiene absolutamente ninguna forma de lograr su victoria..."
  },
  AvgDialog_126912_Content_59 = {
    Text = "Todos deben..."
  },
  AvgDialog_126912_Content_6 = {
    Text = "¿No es peligroso para aquellos que quedan al lado del asesino?"
  },
  AvgDialog_126912_Content_60 = {
    Text = "La última sílaba de Wanda desapareció. La bendición en sus últimas palabras también fue tragada por el silencio."
  },
  AvgDialog_126912_Content_61 = {
    Text = "Después de un largo silencio, Thais finalmente habló con un temblor en su voz."
  },
  AvgDialog_126912_Content_62 = {
    Text = "Parece que la asesina es efectivamente Miryam. Ella sabía que bajo la regla de vigilancia mutua entre las dos, tenía que matar a Wanda primero; de lo contrario, su acción seguramente provocaría la hostilidad de todos los restantes, así que tomó acción."
  },
  AvgDialog_126912_Content_63 = {
    Text = "Wanda... precisamente porque sabe que sobresale en \"Contrataque\", tomó la iniciativa de compartir una habitación con la traidora Miryam."
  },
  AvgDialog_126912_Content_64 = {
    Text = "Ella intercambió su sacrificio por la victoria de los \"buenos\"."
  },
  AvgDialog_126912_Content_65 = {
    Text = "El tono de Ella era pesado, pero impregnado de respeto. Ojalá pudiera venir del corazón."
  },
  AvgDialog_126912_Content_66 = {
    Text = "Qué lástima que no sea."
  },
  AvgDialog_126912_Content_67 = {
    Text = "No... Miryam... no es N quien ha infiltrado nuestras filas."
  },
  AvgDialog_126912_Content_68 = {
    Text = "<Shake:¿No es ella? Entonces, ¿por qué ella...?>"
  },
  AvgDialog_126912_Content_69 = {
    Text = "Por la victoria, por ganar, por la \"Lemuria\" prometida por N, la Miryam que conozco realmente iría tan lejos como para tomar el asunto en sus propias manos."
  },
  AvgDialog_126912_Content_7 = {
    Text = "Pero al menos esto asegura que N no logrará la victoria final."
  },
  AvgDialog_126912_Content_70 = {
    Text = "Entonces... ¿por qué tú..."
  },
  AvgDialog_126912_Content_71 = {
    Text = "Pero el verdadero traidor... eres tú. \"Thais\", o más bien, <Yellow:alguien que finge ser ella.>"
  },
  AvgDialog_126912_Content_72 = {
    Text = "Quizás tu preparación ha sido suficiente; Thais no mostró demasiada sorpresa, solo te miró con calma y una sonrisa en los ojos."
  },
  AvgDialog_126912_Content_73 = {
    Text = "¿Oh? ¿Cuándo te diste cuenta? Me encantaría escuchar."
  },
  AvgDialog_126912_Content_74 = {
    Text = "Después de que Winkle... se fue, Wanda sugirió dividir los dos compartimentos."
  },
  AvgDialog_126912_Content_75 = {
    Text = "¿De verdad... tan temprano? Pensé que los métodos que elegí eran lo suficientemente cautelosos y no dejaban mucho rastro."
  },
  AvgDialog_126912_Content_76 = {
    Text = "Las heridas de atravesar en Tinct pueden provenir de las espinas de Thais, de las púas de Wanda o de la daga que lleva Miryam."
  },
  AvgDialog_126912_Content_77 = {
    Text = "Y la muerte de Winkle... Thais, Wanda y Miryam tienen la capacidad de infligir veneno."
  },
  AvgDialog_126912_Content_78 = {
    Text = "Teniendo en cuenta la ingesta de café de Winkle, solo que se añada veneno a la cafetera, la muerte inevitablemente llegará en algún momento."
  },
  AvgDialog_126912_Content_79 = {
    Text = "Así que, sí, en términos de los métodos para cometer el crimen, tu disfraz fue muy exitoso."
  },
  AvgDialog_126912_Content_8 = {
    Text = "Yo vigilaré a Miryam. No te preocupes, tengo un as bajo la manga que definitivamente no espera."
  },
  AvgDialog_126912_Content_80 = {
    Text = "¿Entonces cuál es la base de tu razonamiento...?"
  },
  AvgDialog_126912_Content_81 = {
    Text = "¿Has oído hablar de un juego de fiesta llamado \"Noche de la Luna Sangrienta\"? Cada Luna Sangrienta, los hombres lobo abren los ojos y comienzan a cazar, solo para mezclarse entre la gente buena al día siguiente."
  },
  AvgDialog_126912_Content_82 = {
    Text = "Para identificar a los hombres lobo ocultos, la clave es inferir los motivos de cada persona durante la fase de discusión. Los hombres lobo conocen las identidades de los buenos, por lo que sus acusaciones suelen ser más seguras."
  },
  AvgDialog_126912_Content_83 = {
    Text = "La verdadera Thais es la reina que ha estado en inactividad durante mil años en Aram. Su personalidad es completamente opuesta a su apariencia; actúa con cautela y definitivamente no es alguien que sospeche fácilmente de los demás."
  },
  AvgDialog_126912_Content_84 = {
    Text = "Así que votaste por mí, no por Miryam."
  },
  AvgDialog_126912_Content_85 = {
    Text = "Elegí estar en la misma habitación que el asesino."
  },
  AvgDialog_126912_Content_86 = {
    Text = "Estaba listo para atraparte en el acto cuando atacaste, pero desafortunadamente, la acción de Miryam fue más rápida que la tuya..."
  },
  AvgDialog_126912_Content_87 = {
    Text = "Antes de que completaras mi hipnosis, ella ya había atacado a Wanda."
  },
  AvgDialog_126912_Content_88 = {
    Text = "Maravilloso, maravilloso razonamiento. Realmente me impresiona."
  },
  AvgDialog_126912_Content_89 = {
    Text = "No, no es suficiente... Después de todo, no tengo la intención de desempeñar el papel de detective en esta historia según el arreglo de la pequeña N."
  },
  AvgDialog_126912_Content_9 = {
    Text = "Wanda entrecerró los ojos y mostró una sonrisa tranquilizadora."
  },
  AvgDialog_126912_Content_90 = {
    Text = "Hubiera preferido detener su conspiración antes de que ocurriera el incidente. Pero ya es demasiado tarde."
  },
  AvgDialog_126912_Content_91 = {
    Text = "Hoy en día, solo puedo pedirte que me digas... ¿cuál es realmente tu verdadera apariencia?"
  },
  AvgDialog_126912_Content_92 = {
    Text = "Una luz plateada estalla de la llave de plata en tu pecho, pareciendo atravesar toda ilusión y disfraz."
  },
  AvgDialog_126912_Content_93 = {
    Text = "Jeje, jejeje~"
  },
  AvgDialog_126912_Content_94 = {
    Text = "Tu ataque parece haber golpeado aire vacío."
  },
  AvgDialog_126912_Content_95 = {
    Text = "Se transformó en una bruma de humo, una bruma de niebla, una presencia esquiva e indescriptible."
  },
  AvgDialog_126912_Content_96 = {
    Text = "Ven, sígueme."
  },
  AvgDialog_126912_Content_97 = {
    Text = "La niebla rió suavemente, extendiendo una invitación ambigua e inexplicable hacia ti."
  },
  AvgDialog_126912_Content_98 = {
    Text = "Ven conmigo hacia la verdad de la historia."
  },
  AvgDialog_128696_Content_1 = {
    Text = "¡BANG! ¡BANG! ¡BANG!"
  },
  AvgDialog_128696_Content_10 = {Text = "¡Nautila!"},
  AvgDialog_128696_Content_11 = {
    Text = "Mosk corrió apresuradamente hacia adelante, se inclinó sobre el pecho de Nautila y descubrió que Nautila estaba simplemente demasiado cansada, se había quedado profundamente dormida."
  },
  AvgDialog_128696_Content_12 = {
    Text = "Mosk suspiró aliviado y no pudo evitar reír a carcajadas."
  },
  AvgDialog_128696_Content_13 = {
    Text = "Pff, ¡ja, ja, ja, ja, ja!"
  },
  AvgDialog_128696_Content_14 = {
    Text = "Ella llevó a Nautila a la cama, ignorando tu resistencia y rodando contigo por el suelo varias veces."
  },
  AvgDialog_128696_Content_15 = {
    Text = "¡Escapar, nosotros, no necesitamos separarnos!"
  },
  AvgDialog_128696_Content_16 = {
    Text = "Es la primera vez que Mosk se siente tan relajada desde aquel día, sus ojos brillan de esperanza y con la punta de su nariz juega alegremente con el suave pelo de tu pecho."
  },
  AvgDialog_128696_Content_17 = {
    Text = "Dormir... un ratito... mañana por la mañana... mañana por la mañana..."
  },
  AvgDialog_128696_Content_18 = {
    Text = "Mosk, que no ha cerrado los ojos durante varios días, te abraza fuertemente, apoyándose en la esquina de la cama de Nautila, y también se ha quedado profundamente dormido."
  },
  AvgDialog_128696_Content_19 = {Text = "..."},
  AvgDialog_128696_Content_2 = {
    Text = "¡Boom!——¡Boom Boom!——¡Boom!"
  },
  AvgDialog_128696_Content_20 = {Text = "..."},
  AvgDialog_128696_Content_21 = {
    Text = "¡Casi @4!..."
  },
  AvgDialog_128696_Content_22 = {Text = "..."},
  AvgDialog_128696_Content_23 = {Text = "..."},
  AvgDialog_128696_Content_24 = {
    Text = "La dirección se ha perdido por completo, la lluvia cae sin cesar, sin dar a los desmesurados desafiantes ninguna oportunidad de retractarse."
  },
  AvgDialog_128696_Content_25 = {
    Text = "El timón se desvió de manera extraña, sin importar cuánto intentaran Nautila y Mosk, incluso casi dañándolo, no mostraba ninguna inclinación a volver a la trayectoria correcta."
  },
  AvgDialog_128696_Content_26 = {
    Text = "¿Cómo puede ser? ¡No debería ser así! No hubo ninguna señal de advertencia, la presión atmosférica era completamente normal... No había ningún problema hasta que nos acercamos a estas aguas."
  },
  AvgDialog_128696_Content_27 = {
    Text = "Es simplemente... Es como si este vórtice hubiera conjurado el torbellino específicamente para tendernos una trampa."
  },
  AvgDialog_128696_Content_28 = {Text = "¿Trampa?"},
  AvgDialog_128696_Content_29 = {
    Text = "Justo cuando estábamos más cerca del vórtice, con solo cinco, no, incluso tres millas náuticas más, habría sido suficiente para alejarnos de la influencia del vórtice."
  },
  AvgDialog_128696_Content_3 = {
    Text = "La bestia de acero que había estado dormida durante mucho tiempo emitió un rugido ronco, la bocina sonó y, en medio del aleteo de las gaviotas, todo el barco pareció cobrar vida lentamente."
  },
  AvgDialog_128696_Content_30 = {
    Text = "Tu mente ya está en caos, intentas desesperadamente emitir algún sonido, ¿qué será...?"
  },
  AvgDialog_128696_Content_31 = {
    Text = "¡Ah, ah——!"
  },
  AvgDialog_128696_Content_32 = {
    Text = "Solo puedes emitir un grito de confusión, ¿no entiendes que ellas no pueden sentirlo?"
  },
  AvgDialog_128696_Content_33 = {
    Text = "(No te acerques al vórtice, grandullón, ¡no te acerques al vórtice!)"
  },
  AvgDialog_128696_Content_34 = {
    Text = "Ese enorme y aterrador ser, vio a Mosk."
  },
  AvgDialog_128696_Content_35 = {
    Text = "<Red:No tiene intención de dejar salir a nadie.>"
  },
  AvgDialog_128696_Content_36 = {Text = "..."},
  AvgDialog_128696_Content_37 = {Text = "..."},
  AvgDialog_128696_Content_38 = {
    Text = "Sí, confía en mí, Bola de carbón, Mosk. Hay una manera, ¡seguro que encontraré una solución!"
  },
  AvgDialog_128696_Content_39 = {Text = "Nautila..."},
  AvgDialog_128696_Content_4 = {
    Text = "El motor. El último paso..."
  },
  AvgDialog_128696_Content_40 = {
    Text = "Soy yo quien debe llevarse el barco, fui yo quien los trajo aquí, encontraré una manera, ¡los llevaré a salvo!"
  },
  AvgDialog_128696_Content_41 = {
    Text = "<Change>Haz un agujero en el casco aquí y deja entrar agua como lastre..."
  },
  AvgDialog_128696_Content_42 = {
    Text = "<Change>No puede ser... @2la energía, sí, si, Siempre Que se sobrecargue uno de los motores, escapar de la fuerza de atracción de @1"
  },
  AvgDialog_128696_Content_43 = {
    Text = "La niña te lleva a ti y a Mosk a través de los camarotes, moviéndose rápidamente y tratando diversas maneras, mientras sus ojos se llenan gradualmente de un carmesí frenético."
  },
  AvgDialog_128696_Content_44 = {
    Text = "¡Clang!—¡Bang!"
  },
  AvgDialog_128696_Content_45 = {Text = "Nautila..."},
  AvgDialog_128696_Content_46 = {
    Text = "Con un desmayo, la llave inglesa chocó contra la pared y luego cayó pesadamente sobre el pie de Nautila, sin embargo, ella parecía no sentir el dolor y murmuraba que quería seguir recogiendo la llave inglesa."
  },
  AvgDialog_128696_Content_47 = {
    Text = "<Change>Es demasiado tarde, el remolino se acerca cada vez más... ¿Por qué, por qué, por qué, POR QUÉ!! Tengo que salvarlos, debo... ¡debo...!"
  },
  AvgDialog_128696_Content_48 = {
    Text = "¡Crack!—¡Boom!—"
  },
  AvgDialog_128696_Content_49 = {
    Text = "La tormenta y los golpes finalmente superaron el límite del camarote, y tras un sonido nítido de ruptura, las viejas tablas cayeron a gran velocidad desde la parte superior de Nautila——"
  },
  AvgDialog_128696_Content_5 = {
    Text = "¡Genial! Mosk, Bola de carbón, ¡lo logramos!"
  },
  AvgDialog_128696_Content_50 = {
    Text = "<Big:Nautila! ¡Detente!>"
  },
  AvgDialog_128696_Content_51 = {
    Text = "Al abrir los ojos cerrados por el miedo, ante Nautila aparece una escena inesperada."
  },
  AvgDialog_128696_Content_52 = {
    Text = "Mosk se apoyó en la pared con una mano protegiéndose, mientras que con la otra sostenía todo el techo."
  },
  AvgDialog_128696_Content_53 = {Text = "Ugh..."},
  AvgDialog_128696_Content_54 = {Text = "¡Ja!"},
  AvgDialog_128696_Content_55 = {
    Text = "Mosk empujó con fuerza, lanzando el techo a otro lugar, y luego agarró a Nautila, que estaba al borde de la locura, sosteniendo su cara con ambas manos y fijando su mirada en la suya."
  },
  AvgDialog_128696_Content_56 = {
    Text = "No pasa nada, regresa, la próxima vez."
  },
  AvgDialog_128696_Content_57 = {
    Text = "Vuelve... pero..."
  },
  AvgDialog_128696_Content_58 = {
    Text = "Nautila miró a su alrededor con desconcierto, dejando que la lluvia torrencial la empapara."
  },
  AvgDialog_128696_Content_59 = {
    Text = "Los truenos y relámpagos envuelven la tormenta, estimulando cada nervio, como la música incesante en el banquete de un demonio."
  },
  AvgDialog_128696_Content_6 = {
    Text = "Nautila, después de eso, estuvo reparando el casco casi sin descanso. Quedan tres días para la llegada prevista de la tormenta y todas las piezas clave han vuelto a su lugar correspondiente."
  },
  AvgDialog_128696_Content_60 = {
    Text = "La gravedad del vórtice es demasiado grande, ya no podemos regresar..."
  },
  AvgDialog_128696_Content_61 = {
    Text = "Mosk no prestó atención a las palabras de Nautila y arrastró el traje de buceo de la bodega, intentando ponerlo sobre Nautila de manera desordenada y sin saber cómo."
  },
  AvgDialog_128696_Content_62 = {
    Text = "¿Un traje de buceo? No puedo, si me lo pongo, ¿qué harás tú?"
  },
  AvgDialog_128696_Content_63 = {
    Text = "En este momento, el casco del barco ya ha comenzado a inclinarse completamente hacia el vórtice de manera incontrolable."
  },
  AvgDialog_128696_Content_64 = {
    Text = "<Shake:Crujido—Chirridos—>"
  },
  AvgDialog_128696_Content_7 = {
    Text = "Siempre Que vuelva a poner el ancla... uf... qué sueño..."
  },
  AvgDialog_128696_Content_8 = {Text = "¡Plop!"},
  AvgDialog_128696_Content_9 = {
    Text = "¿Chirp?! ¿Chirp——? (¿Persona?! ¿Persona——?)"
  },
  AvgDialog_128697_Content_1 = {
    Text = "Bien. Mejor. ¡Lo mejorcísimo!"
  },
  AvgDialog_128697_Content_10 = {Text = "..."},
  AvgDialog_128697_Content_11 = {Text = "..."},
  AvgDialog_128697_Content_12 = {
    Text = "Aunque de hecho tiene un poco de poder destructivo."
  },
  AvgDialog_128697_Content_13 = {
    Text = "¡Guardián del Secreto! ¡Mosk! ¡Derrota a la tarea malvada! ¡Increíble!"
  },
  AvgDialog_128697_Content_14 = {
    Text = "Oye... Guardián de secretos... ¿Bola de carbón?!"
  },
  AvgDialog_128697_Content_15 = {
    Text = "La intuición bestial de Mosk percibió al instante algo diferente, ella saltó como un animal y se lanzó hacia ti, abrazándote con fuerza."
  },
  AvgDialog_128697_Content_16 = {
    Text = "¡Ay! Mosk, ¡duele!"
  },
  AvgDialog_128697_Content_17 = {
    Text = "Al mismo tiempo, le dio un golpe doloroso a tu desafortunada nariz con su boca."
  },
  AvgDialog_128697_Content_18 = {
    Text = "jaula, dispositivo de restricción, Mosk, ¡bien! jeje, Mosk, seguro."
  },
  AvgDialog_128697_Content_19 = {
    Text = "El dispositivo que Misaq diseñó especialmente para ella controla muy bien la fuga de fuerza, y la máxima capacidad destructiva de Mosk ahora es equivalente a la de un humano un poco más fuerte."
  },
  AvgDialog_128697_Content_2 = {
    Text = "¡Hola, Guardián del Secreto! Con respecto al Despertado O-1841, dado que acaba de despertar y presenta ocasionalmente signos de Furia, además de no poder controlar completamente sus habilidades, se recomienda mantener un estado de cautela al interactuar con él."
  },
  AvgDialog_128697_Content_20 = {
    Text = "Amigos, después, ¿una aventura muy perfecta, hay? ¿No hay?"
  },
  AvgDialog_128697_Content_21 = {
    Text = "Te costó mucho esfuerzo despegar al gran perro juguetón de ti. Finalmente, ella estuvo dispuesta a estar tranquila por un momento, sentándose frente a ti en el escritorio, con los ojos brillantes fijos en ti."
  },
  AvgDialog_128697_Content_22 = {Text = "Hmm..."},
  AvgDialog_128697_Content_23 = {
    Text = "En realidad..."
  },
  AvgDialog_128697_Content_24 = {
    Text = "Bajo el vórtice M-Merskus existe una enorme Fissura de fusión; aunque Nautila y yo logramos escapar de la influencia del vórtice, ambos mostramos básicamente síntomas de amnesia."
  },
  AvgDialog_128697_Content_25 = {
    Text = "Solo te detuviste brevemente y elegiste usar\"Yo\"como el término para referirte a esa conciencia en el sueño."
  },
  AvgDialog_128697_Content_26 = {
    Text = "Nautila ha estado buscándote desde entonces. Formó un grupo de aventuras, pero se encontró con otro desastre en el viaje de regreso..."
  },
  AvgDialog_128697_Content_27 = {
    Text = "Ella probablemente ya no lo recuerde, pero... tomó la misma elección que tú."
  },
  AvgDialog_128697_Content_28 = {
    Text = "Oh... Así es"
  },
  AvgDialog_128697_Content_29 = {
    Text = "¡Pero eso es genial."
  },
  AvgDialog_128697_Content_3 = {
    Text = "Gracias, Erica. Pero no te preocupes, creo que conozco lo suficiente a mi... amigo."
  },
  AvgDialog_128697_Content_30 = {
    Text = "Por supuesto"
  },
  AvgDialog_128697_Content_31 = {
    Text = "¡Claro que sí! Después, yo y Nautila..."
  },
  AvgDialog_128697_Content_32 = {
    Text = "En resumen, hasta que yo y Nautila seamos tan viejos que no podamos movernos, estaremos viviendo todo tipo de aventuras."
  },
  AvgDialog_128697_Content_33 = {
    Text = "Te has esforzado al máximo para incluir en tu relato a Mosk todas las historias de aventuras que has escuchado durante tu breve vida consciente de un año."
  },
  AvgDialog_128697_Content_34 = {
    Text = "Después de todo, Dios, realmente no puedes decirle nada cruel a esos ojos."
  },
  AvgDialog_128697_Content_35 = {
    Text = "La historia deLu@2, Mosk, la he escuchado."
  },
  AvgDialog_128697_Content_36 = {
    Text = "<Gray:Vaya, olvidé que esto era lectura de un curso general...>"
  },
  AvgDialog_128697_Content_37 = {
    Text = "No hay problema."
  },
  AvgDialog_128697_Content_38 = {Text = "¿Eh?"},
  AvgDialog_128697_Content_39 = {
    Text = "Mosk bajó la cabeza y, como cuando eras una bola de carbón, apoyó su cara en la palma de tu mano."
  },
  AvgDialog_128697_Content_4 = {
    Text = "A diferencia de lo que la academia esperaba, tu primer enlace con este Despertado de poder Furia fue inusualmente fluido."
  },
  AvgDialog_128697_Content_40 = {
    Text = "Amigo, Bola de carbón, nos volvemos a ver."
  },
  AvgDialog_128697_Content_41 = {
    Text = "Bola de carbón, experiencia en la oscuridad, recuerda Mosk, bien."
  },
  AvgDialog_128697_Content_42 = {
    Text = "Ella sonrió ampliamente, dándote una sonrisa muy, muy feliz."
  },
  AvgDialog_128697_Content_43 = {
    Text = "Aunque, la pulsera, ha desaparecido."
  },
  AvgDialog_128697_Content_44 = {
    Text = "Pero, ¡nuestro reencuentro es mejor, mejor que mejor!"
  },
  AvgDialog_128697_Content_45 = {Text = "Mosk..."},
  AvgDialog_128697_Content_46 = {
    Text = "¿Chirrido?"
  },
  AvgDialog_128697_Content_47 = {
    Text = "¿? ¿Por qué hay una nutria con un sombrero de Misaq aquí?"
  },
  AvgDialog_128697_Content_48 = {
    Text = "Lo siento, Guardián del Secreto, parece que muchos estudiantes están muy enamorados de esta nutria foránea y le han hecho algunos adornos innecesarios."
  },
  AvgDialog_128697_Content_49 = {
    Text = "Erica iniciará el programa de expulsión lo antes posible, 1, 2——"
  },
  AvgDialog_128697_Content_5 = {
    Text = "Después de este inesperado sueño, crees que ya has encontrado la respuesta."
  },
  AvgDialog_128697_Content_50 = {
    Text = "¡Ah, una nutria! ¡Adorable, juega con Mosk!"
  },
  AvgDialog_128697_Content_51 = {
    Text = "¡Pum. Dong. Clang—!"
  },
  AvgDialog_128697_Content_52 = {Text = "¡Bang!"},
  AvgDialog_128697_Content_53 = {
    Text = "¡Sss, Mosk!"
  },
  AvgDialog_128697_Content_54 = {
    Text = "Nautila acaba de entrar en el aula y vio a su nuevo buen amigo persiguiendo a una nutria que llevaba un sombrero de Misaq, causando estragos en los equipos de enseñanza."
  },
  AvgDialog_128697_Content_55 = {
    Text = "Guardián, dile a la profesora Erica que arreglaré todo en el aula."
  },
  AvgDialog_128697_Content_56 = {
    Text = "Mosk, ¡detente!"
  },
  AvgDialog_128697_Content_57 = {
    Text = "¡Ah!—¡Ah!"
  },
  AvgDialog_128697_Content_58 = {Text = "¡¡Auch!!"},
  AvgDialog_128697_Content_59 = {Text = "*aplausos"},
  AvgDialog_128697_Content_6 = {
    Text = "A ella le gusta la carne asada, le encanta el mar, es muy tímida, odia el frío, la oscuridad y la soledad, y suele llorar en silencio cuando se enfrenta a ellos."
  },
  AvgDialog_128697_Content_60 = {
    Text = "Si no entendí mal, esa nutria marina está diciendo \"juega conmigo\", ¿verdad...? ¿Cómo se comunican exactamente con Mosk?"
  },
  AvgDialog_128697_Content_61 = {
    Text = "¡Eh, espera! ¿Por qué también puedo entender lo que dice la nutria?!"
  },
  AvgDialog_128697_Content_62 = {
    Text = "Espera, así que..."
  },
  AvgDialog_128697_Content_63 = {
    Text = "Ejem, desconocido nutria de Misaq, ahora te transmitiré el título de Bola de carbón."
  },
  AvgDialog_128697_Content_64 = {
    Text = "Heredarás el título de Bola de carbón, ¡te convertirás en el gran y glorioso Bola de carbón II!"
  },
  AvgDialog_128697_Content_65 = {Text = "!"},
  AvgDialog_128697_Content_66 = {Text = "¡!"},
  AvgDialog_128697_Content_67 = {
    Text = "¡Tic—— (¡Impacto de nutria!)"
  },
  AvgDialog_128697_Content_68 = {
    Text = "Nautila——"
  },
  AvgDialog_128697_Content_69 = {
    Text = "¡Genial, se ha convertido en un completo caos——!"
  },
  AvgDialog_128697_Content_7 = {
    Text = "Por la tarde, el sol de Misaq es muy bueno, el Sol atraviesa el vidrio de colores, proyectando la luz sobre la cara de la niña que está peleando con el libro de la clase de lengua."
  },
  AvgDialog_128697_Content_70 = {
    Text = "Entonces, como mi legítimo heredero, <Small:tienes la solemne obligación de encargarte de lo que me disgusta a mí, la primera Bola de carbón...>"
  },
  AvgDialog_128697_Content_71 = {
    Text = "Silbaste con despreocupación, sigilosamente, sigilosamente——"
  },
  AvgDialog_128697_Content_72 = {
    Text = "Lanzó su tarea de cálculo hacia las garras de la nutria, aprovechando el desorden."
  },
  AvgDialog_128697_Content_73 = {
    Text = "En un abrir y cerrar de ojos, la tarea se convirtió en papel arrugado, yaciendo en silencio en el montón de papel basura."
  },
  AvgDialog_128697_Content_74 = {
    Text = "¡Qué día tan hermoso, verdad, Nautila, Mosk?"
  },
  AvgDialog_128697_Content_75 = {Text = "¡Ah—!"},
  AvgDialog_128697_Content_76 = {
    Text = "Hoy, Misaq también es muy amigable y pacífico."
  },
  AvgDialog_128697_Content_77 = {
    Text = "¡Es motivo de celebración, es motivo de celebración."
  },
  AvgDialog_128697_Content_8 = {
    Text = "Pero también es muy valiente, se pondrá frente a todas las cosas que odia por sus amigos."
  },
  AvgDialog_128697_Content_9 = {
    Text = "¡Sss!——El libro de texto se rompió en dos en la atmósfera que se había vuelto emotiva."
  },
  AvgDialog_128698_Content_1 = {
    Text = "Splash～Splash～"
  },
  AvgDialog_128698_Content_10 = {
    Text = "La energía y el combustible no son problema, pero el casco del barco es demasiado frágil... Mosk, ¿hay alguna manera de rodear ese gran remolino? La flota anterior tuvo problemas cerca de él."
  },
  AvgDialog_128698_Content_11 = {
    Text = "......no puedo salir."
  },
  AvgDialog_128698_Content_12 = {
    Text = "Mosk sacude la cabeza, te abraza de nuevo y ambos se esfuerzan juntos con manos y pies."
  },
  AvgDialog_128698_Content_13 = {
    Text = "Malvados, atrapan a mamá y papá. Mosk, muerde, se la llevan. Bola de carbón, en barco, encuentro."
  },
  AvgDialog_128698_Content_14 = {
    Text = "El mar, ¡llama! — aquí, Mosk, piensa en algo, no se puede."
  },
  AvgDialog_128698_Content_15 = {
    Text = "¿Te atraparon aquí los malos y desde que te separaron de mamá y papá, no has podido salir?"
  },
  AvgDialog_128698_Content_16 = {
    Text = "No estoy, papá y mamá."
  },
  AvgDialog_128698_Content_17 = {
    Text = "Lo siento..."
  },
  AvgDialog_128698_Content_18 = {
    Text = "¡Cierto, papá y mamá, como, ven!"
  },
  AvgDialog_128698_Content_19 = {
    Text = "¡Mosk! ¿A dónde me llevas?"
  },
  AvgDialog_128698_Content_2 = {
    Text = "solo si reparamos completamente el cojinete de esta parte, el timón..."
  },
  AvgDialog_128698_Content_20 = {Text = "..."},
  AvgDialog_128698_Content_21 = {Text = "..."},
  AvgDialog_128698_Content_22 = {
    Text = "¿Eh, dónde estamos?"
  },
  AvgDialog_128698_Content_23 = {Text = "¡Ah—!"},
  AvgDialog_128698_Content_24 = {
    Text = "Saltas alegremente al agua primero, asustando a todos los peces alrededor."
  },
  AvgDialog_128698_Content_25 = {
    Text = "Mientras tú y Mosk saltan al agua una tras otro con gritos de alegría, ondas se elevan desde las profundidades, como si respondieran a sus llamadas."
  },
  AvgDialog_128698_Content_26 = {
    Text = "¡Papá, mamá, como ellos! Nautila, Mosk, ¡igual!"
  },
  AvgDialog_128698_Content_27 = {
    Text = "Varios delfines hermosos y blancos emergen del fondo del agua, rodeándolos, acariciándolos con sus hocicos y aletas."
  },
  AvgDialog_128698_Content_28 = {
    Text = "Fluyen suavemente a su alrededor, incluso saltando fuera del agua, arrojando un poco de manantial hacia Nautila, como si le estuvieran haciendo una invitación."
  },
  AvgDialog_128698_Content_29 = {
    Text = "Son... ¿delfines? Mosk, ¿estás diciendo que tus padres también son delfines?"
  },
  AvgDialog_128698_Content_3 = {
    Text = "¿Barco robado?"
  },
  AvgDialog_128698_Content_30 = {
    Text = "Sí. Pequeño Mosk, perderse. Delfines, alimentar a pequeño Mosk. ¡Mosk, crecer!"
  },
  AvgDialog_128698_Content_31 = {
    Text = "Mosk, Hola, Bola de carbón, Bola de carbón, ¡crece!"
  },
  AvgDialog_128698_Content_32 = {
    Text = "Mosk se rió a carcajadas, esquivando las salpicaduras de agua que le lanzaste por la ira, y luego ambos extendieron las manos hacia Nautila."
  },
  AvgDialog_128698_Content_33 = {
    Text = "Confía en mí, amigo."
  },
  AvgDialog_128698_Content_34 = {
    Text = "...¡Está bien!"
  },
  AvgDialog_128698_Content_35 = {
    Text = "Nautila aprieta firmemente tus manos. Uno delante, otro detrás, tú y Mosk llevan a Nautila hacia una cueva oculta."
  },
  AvgDialog_128698_Content_36 = {
    Text = "Tras una breve oscuridad, un grupo, dos grupos... innumerables grupos de tenues luces oníricas despertaron; las medusas se agolparon hacia la superficie, empujadas suavemente por el remolino, hasta que una luz más brillante se derramó desde la cúpula."
  },
  AvgDialog_128698_Content_37 = {
    Text = "...Yo, no estaré soñando."
  },
  AvgDialog_128698_Content_38 = {
    Text = "La luz del sol penetra las capas de roca, reflejando un azul profundo y claro en la superficie del mar sin fondo. Los coloridos corales vuelven a cortar el azul, presentando una imagen que deja sin palabras junto a numerosas criaturas marinas."
  },
  AvgDialog_128698_Content_39 = {
    Text = "Las anémonas de mar arrastran sus tentáculos venenosos en una danza lenta e hipnótica. Los moluscos se aferran cerca, viviendo en silenciosa armonía con ellas. Los depredadores acechan en la oscuridad del abismo, esperando su momento. Este lugar es peligroso y hermoso, oscuro y deslumbrante—un mundo en sí mismo, una miniatura del océano."
  },
  AvgDialog_128698_Content_4 = {
    Text = "El timón es como el volante, es el objeto que controla la dirección. ¿Sabes qué es un volante?"
  },
  AvgDialog_128698_Content_40 = {Text = "¿Nautila?"},
  AvgDialog_128698_Content_41 = {
    Text = "Esto, hermoso, para ti."
  },
  AvgDialog_128698_Content_42 = {
    Text = "Mosk, en un momento desconocido, sacó una perla que emitía un brillo iridiscente y, con una expresión muy, muy seria, la colocó en la palma de Nautila."
  },
  AvgDialog_128698_Content_43 = {
    Text = "Mosk, aquí, me gusta. Mosk, tesoro, me gusta. Nautila, amigo, para ti."
  },
  AvgDialog_128698_Content_44 = {
    Text = "(¡Te pedí tantas veces antes y nunca me diste, grandote, malo!)"
  },
  AvgDialog_128698_Content_45 = {
    Text = "Aunque pienses esto en tu interior, al recordar los deliciosos pescados a la parrilla y mariscos guisados que has comido en este tiempo, generosamente empujas las perlas hacia las manos de Nautila junto con Mosk."
  },
  AvgDialog_128698_Content_46 = {
    Text = "Oh, ¡gracias! Bueno, entonces yo también tengo un regalo para Mosk."
  },
  AvgDialog_128698_Content_47 = {Text = "¿Liwu?"},
  AvgDialog_128698_Content_48 = {
    Text = "Nautila se desata de la muñeca la pequeña pulsera que siempre lleva puesta, decorada con un pequeño dije de nautilus."
  },
  AvgDialog_128698_Content_49 = {
    Text = "Lo que un amigo le da a un amigo se llama \"regalo\". La perla es tu regalo para mí. Y esto... esto es mi regalo para ti."
  },
  AvgDialog_128698_Content_5 = {Text = "Uh...?"},
  AvgDialog_128698_Content_50 = {
    Text = "Mi mamá me dio un collar y una pulsera, y yo le prometí que me convertiría en un gran aventurero."
  },
  AvgDialog_128698_Content_51 = {
    Text = "Mosk, pronto podré arreglar el barco. Nos iremos juntos a buscar a tus papás."
  },
  AvgDialog_128698_Content_52 = {
    Text = "Y después de eso... ¿estarías dispuesto a llevar esta pulsera, llevar a Bola de carbón, y acompañarme en una aventura?"
  },
  AvgDialog_128698_Content_53 = {Text = "..."},
  AvgDialog_128698_Content_54 = {
    Text = "¡Nautila, Mosk, Bola de carbón, aventura!"
  },
  AvgDialog_128698_Content_55 = {Text = "¡Ahuh!"},
  AvgDialog_128698_Content_56 = {
    Text = "Después de un breve silencio que parecía una ilusión, Mosk levantó su brillante sonrisa como siempre y te abrazó mientras emitía un grito de alegría."
  },
  AvgDialog_128698_Content_57 = {
    Text = "¡Pío! (¡Aventura!)"
  },
  AvgDialog_128698_Content_58 = {
    Text = "¿Qué puedes percibir? Solo eres una nutria marina. Incluso si captaste un indicio de algo, tu pequeño cerebro no te permite comprenderlo del todo. Así que lo dejas pasar y te sumerges de lleno en el ambiente alegre."
  },
  AvgDialog_128698_Content_59 = {
    Text = "¡Genial, Bola de carbón! También te he preparado un regalo!"
  },
  AvgDialog_128698_Content_6 = {
    Text = "El timón es el objeto que controla la dirección de todos los grandes vehículos. Donde el timón señala el camino, allí irán el barco y el coche."
  },
  AvgDialog_128698_Content_60 = {Text = "..."},
  AvgDialog_128698_Content_61 = {Text = "¡!"},
  AvgDialog_128698_Content_62 = {Text = "¡!"},
  AvgDialog_128698_Content_63 = {
    Text = "Jeje, ahora todos tienen una cama."
  },
  AvgDialog_128698_Content_64 = {
    Text = "Apenas Nautila terminó de hablar, toda tu nutria cayó de cabeza en tu perfecto nido—¡Nautila incluso te dejó un lugar especial para tu pequeño tesoro de conchas!"
  },
  AvgDialog_128698_Content_65 = {
    Text = "La sopa de mariscos de la cena aún te calienta el estómago, y pronto te quedas dormido con el suave respirar de las niñas."
  },
  AvgDialog_128698_Content_66 = {
    Text = "Pero cuando realmente llegó la noche, aquella sensación ominosa se expandió como la niebla espesa sobre la superficie del mar."
  },
  AvgDialog_128698_Content_67 = {
    Text = "<Shake:Mosk, @3...>"
  },
  AvgDialog_128698_Content_68 = {
    Text = "<Shake:Devolver a mí, sométete a mí, @4...@4!>"
  },
  AvgDialog_128698_Content_69 = {
    Text = "En la oscuridad, el océano se llena de horror y misterio. La luz del sol ya no toca la superficie, y en lo profundo del abismo, algo se agita con un rugido grave y gutural."
  },
  AvgDialog_128698_Content_7 = {
    Text = "¡Ohhhh! ¡Un volante! ¡Qué genial!"
  },
  AvgDialog_128698_Content_70 = {
    Text = "Te sumerges en un vacío y frío infinitos, esforzándote por acercarte a la figura que llora en voz baja a lo lejos."
  },
  AvgDialog_128698_Content_71 = {
    Text = "¡Ah!—(gigante—)"
  },
  AvgDialog_128698_Content_72 = {
    Text = "¡Ah!(¡Grandullón!)"
  },
  AvgDialog_128698_Content_73 = {
    Text = "Despiertas de golpe, sin el suave respiro de las niñas dormidas, todo está en silencio. Te sales de tu refugio y sigues el aroma de Mosk hasta la cubierta."
  },
  AvgDialog_128698_Content_74 = {
    Text = "Ella está mirando el vórtice a lo lejos."
  },
  AvgDialog_128698_Content_75 = {
    Text = "(¿Cuántas veces ha sido ese sueño, desde que esos molestos humanos murieron y nos establecimos aquí?)"
  },
  AvgDialog_128698_Content_76 = {
    Text = "Llamar, Mosk, allí."
  },
  AvgDialog_128698_Content_77 = {
    Text = "Miedo... no..."
  },
  AvgDialog_128698_Content_78 = {
    Text = "Eh, bola de carbón, Mosk, ¿qué hacen afuera?"
  },
  AvgDialog_128698_Content_79 = {
    Text = "La voz de Nautila interrumpió los murmullos de sueños de Mosk, y al siguiente segundo, Nautila empujó emocionada un conjunto de chapa para mostrárselo a ustedes."
  },
  AvgDialog_128698_Content_8 = {Text = "..."},
  AvgDialog_128698_Content_80 = {
    Text = "Mosk, ¿no dijiste antes que sumergirse en lugares demasiado profundos puede ser incómodo, pero que aún así quieres verlo?"
  },
  AvgDialog_128698_Content_81 = {
    Text = "He reparado el traje de buceo que encontré en el barco; con esto, podrás bucear por más tiempo y ya no te sentirás incómodo."
  },
  AvgDialog_128698_Content_82 = {
    Text = "Lástima que necesito reparar el barco antes de que llegue la próxima tormenta. Después de la tormenta, me haré uno para mí también."
  },
  AvgDialog_128698_Content_83 = {
    Text = "¡Algún día podremos explorar el mar juntas!"
  },
  AvgDialog_128698_Content_84 = {
    Text = "Mosk se quedó inusualmente en silencio, y después de un momento, asintió con fuerza, te abrazó y le dio un gran abrazo a Nautila."
  },
  AvgDialog_128698_Content_85 = {Text = "Escapar."},
  AvgDialog_128698_Content_86 = {
    Text = "Mosk, Nautila, Bola de carbón, ¡Escapar! ¡Juntos!"
  },
  AvgDialog_128698_Content_9 = {
    Text = "Los datos de los instrumentos muestran que tenemos una semana como máximo antes de que llegue una tormenta—una que durará al menos medio mes. Este barco ya está en mal estado... No sé si aguantará después de la tormenta."
  },
  AvgDialog_128699_Content_1 = {
    Text = "Plic, ploc."
  },
  AvgDialog_128699_Content_10 = {
    Text = "Mosk, escúchame, fui yo quien propuso zarpar, y también fui yo quien no calculó bien el clima, así que tengo la obligación de sacarte a ti y a la bola de carbón."
  },
  AvgDialog_128699_Content_11 = {
    Text = "Voy a quitarme el traje de buceo y dártelo ahora. El barco aún puede moverse, haré todo lo posible para controlarlo y navegar hacia el borde del vórtice, en ese momento tú..."
  },
  AvgDialog_128699_Content_12 = {Text = "Tú..."},
  AvgDialog_128699_Content_13 = {
    Text = "Nautila se quedó atónita en el lugar, al ver a la niña ingenua, vivaz y despreocupada mostrar rara vez una expresión de preocupación compleja."
  },
  AvgDialog_128699_Content_14 = {
    Text = "Nautila, lo siento."
  },
  AvgDialog_128699_Content_15 = {
    Text = "Mosk extendió la mano. Aunque no entendía cómo funcionaba el dispositivo, impulsada por un instinto animal, terminó de vestir a Nautila con el traje de buceo a la fuerza."
  },
  AvgDialog_128699_Content_16 = {
    Text = "Mosk, peligro, presentimiento."
  },
  AvgDialog_128699_Content_17 = {
    Text = "Pero, espera, no sucederá."
  },
  AvgDialog_128699_Content_18 = {
    Text = "El agua de lluvia entra por el agujero en el techo, golpeando a los dos."
  },
  AvgDialog_128699_Content_19 = {
    Text = "El silencio se extendió por la casa, y al final, fue Mosk quien rompió esta pesadez."
  },
  AvgDialog_128699_Content_2 = {
    Text = "<Shake:Crujido—Chirridos—>"
  },
  AvgDialog_128699_Content_20 = {
    Text = "Mosk, ven aquí, sueña."
  },
  AvgDialog_128699_Content_21 = {
    Text = "Mosk soñó con... algo que se llama Mosk..."
  },
  AvgDialog_128699_Content_22 = {
    Text = "Pero, no quiero ir. Frío, nadie alrededor, soledad..."
  },
  AvgDialog_128699_Content_23 = {
    Text = "Nautila se dio cuenta de inmediato de por qué la lluvia torrencial caía antes de lo esperado, y por qué el tornado apareció sin aviso. Comenzó a temblar incontrolablemente."
  },
  AvgDialog_128699_Content_24 = {
    Text = "Esa cosa... está allí mismo..."
  },
  AvgDialog_128699_Content_25 = {
    Text = "Siguiendo el dedo de Mosk, Nautila sintió una propagación de miedo en su subconsciente."
  },
  AvgDialog_128699_Content_26 = {
    Text = "El miedo que surge desde el fondo del vórtice de Merscus, trascendiendo lo mortal."
  },
  AvgDialog_128699_Content_27 = {Text = "..."},
  AvgDialog_128699_Content_28 = {
    Text = "¡No, no, no—sé lo que vas a hacer, de ninguna manera!"
  },
  AvgDialog_128699_Content_29 = {
    Text = "¡Confía en mí, tiene que haber otra forma!"
  },
  AvgDialog_128699_Content_3 = {
    Text = "Un vórtice furioso, como si fueran unas manos gigantes, intenta torcer el barco como si fuera una toalla."
  },
  AvgDialog_128699_Content_30 = {
    Text = "Nautila presionaba ansiosamente a Mosk. Aunque, considerando su fuerza, Mosk podría liberarse de las ataduras en cualquier momento, la niña bestia no lo hizo."
  },
  AvgDialog_128699_Content_31 = {
    Text = "Simplemente te levanta y te acaricia con cariño."
  },
  AvgDialog_128699_Content_32 = {
    Text = "Amigo, fuerte, pero, no. Solo, Mosk, puede."
  },
  AvgDialog_128699_Content_33 = {
    Text = "solo, Mosk, puede."
  },
  AvgDialog_128699_Content_34 = {
    Text = "......¿Por qué, por qué pasó esto."
  },
  AvgDialog_128699_Content_35 = {
    Text = "Amigo, no llores, ríe, Mosk, ¡me gusta!"
  },
  AvgDialog_128699_Content_36 = {
    Text = "Eh, perdón, vi que todos parecían comer pescado crudo, así que lo preparé un poco... Aunque no hay condimentos, ¿quieres probarlo?"
  },
  AvgDialog_128699_Content_37 = {Text = "¡Aú!"},
  AvgDialog_128699_Content_38 = {Text = "¡Aú!"},
  AvgDialog_128699_Content_39 = {Text = "Delicioso"},
  AvgDialog_128699_Content_4 = {
    Text = "El casco emitió un crujido insoportable, y Mosk casi gritó en la tormenta, mientras luchaba por meterte en el traje de buceo del Nautila, abrazándote con fuerza para que no te lanzara lejos."
  },
  AvgDialog_128699_Content_40 = {
    Text = "¡Aventura, estoy emocionado!"
  },
  AvgDialog_128699_Content_41 = {
    Text = "Mosk, pronto repararé el barco. Nos iremos juntos a buscar a tus papás."
  },
  AvgDialog_128699_Content_42 = {
    Text = "Y después de eso... ¿estarías dispuesta a llevar esta pulsera, traer a Bola de carbón, y venir a una aventura conmigo?"
  },
  AvgDialog_128699_Content_43 = {
    Text = "¡Nautila, Mosk, Bola de carbón, aventura!"
  },
  AvgDialog_128699_Content_44 = {
    Text = "¡Amigo, me gusta!"
  },
  AvgDialog_128699_Content_45 = {
    Text = "¡Amigo, me dio Mosk, ¡muchísimo!"
  },
  AvgDialog_128699_Content_46 = {
    Text = "¡Así que ahora, Mosk va a dar, ¡muchos, muchos amigos!"
  },
  AvgDialog_128699_Content_47 = {
    Text = "Ella se construyó como una pared en medio de la tormenta, manteniéndote firmemente a ti y a Nautila en el centro. Luego, respiró hondo, sonrió mostrando la característica y tranquilizadora sonrisa de Mosk."
  },
  AvgDialog_128699_Content_48 = {
    Text = "¡Mosk, definitivamente volverá!"
  },
  AvgDialog_128699_Content_49 = {
    Text = "...Está bien, confío en Mosk. Cuando regreses, tendré el mejor barco del mundo preparado, y llevaré a ti y a la bola de carbón para una gran aventura."
  },
  AvgDialog_128699_Content_5 = {
    Text = "¡Peligro! ¡Agárrate!"
  },
  AvgDialog_128699_Content_50 = {
    Text = "Nautila secó sus lágrimas, reunió fuerzas y forzó una sonrisa algo desagradable."
  },
  AvgDialog_128699_Content_51 = {
    Text = "Al ver que Nautila finalmente la suelta, Mosk, en silencio, muy en silencio, toma tu patita entre las suyas y presiona su rostro contra las almohadillas de tu pata."
  },
  AvgDialog_128699_Content_52 = {
    Text = "No, tener miedo."
  },
  AvgDialog_128699_Content_53 = {
    Text = "¡Ah... ah! (¿Me vas a dejar caer...?)"
  },
  AvgDialog_128699_Content_54 = {
    Text = "¡SQUIK! ¡SQUIIIK!— (¡¡Me estás dejando atrás!!)"
  },
  AvgDialog_128699_Content_55 = {
    Text = "Eres colocado en los brazos de Nautila entre gritos desgarradores, y en el siguiente instante, Mosk se da la vuelta sin dudarlo y corre hacia la dirección del vórtice cuando el barco se inclina una vez más."
  },
  AvgDialog_128699_Content_56 = {Text = "...Plop."},
  AvgDialog_128699_Content_57 = {
    Text = "Como un pez que entra en su mar."
  },
  AvgDialog_128699_Content_58 = {Text = "Mosk!!"},
  AvgDialog_128699_Content_59 = {
    Text = "La tormenta ahogó todos los gritos, y una enorme ola se lanzó sobre la cubierta, arrastrándolos también al mar."
  },
  AvgDialog_128699_Content_6 = {Text = "¡Boom—"},
  AvgDialog_128699_Content_60 = {
    Text = "Bajo el agua negro-azulada del mar, innumerables hilos de sustancia viscosa negra se abren hacia Mosk, sus manos se transforman en un enorme vórtice, su expresión es serena y tranquila, en el fondo de sus ojos profundos y calmados, como si estuvieran en el centro del vórtice."
  },
  AvgDialog_128699_Content_61 = {
    Text = "Mosk, vórtice. Mosk, timón."
  },
  AvgDialog_128699_Content_62 = {
    Text = "Bola de carbón, Nautila, aquí, siempre."
  },
  AvgDialog_128699_Content_63 = {
    Text = "Mosk finalmente no puede evitar estallar en llanto, presionando su mano contra su propio pecho."
  },
  AvgDialog_128699_Content_64 = {
    Text = "Entonces levanta su mano. Un vórtice que porta una fuerza destructiva, pero anormalmente gentil, los empuja a ambos lejos, muy lejos del remolino."
  },
  AvgDialog_128699_Content_65 = {
    Text = "Un hilo tras otro, el líquido pegajoso se adhirió al cuerpo de Mosk, cubriendo rápidamente todo su ser."
  },
  AvgDialog_128699_Content_66 = {
    Text = "El vórtice comenzó a concentrarse en sentido contrario al centro, arrastrando su deseo cumplido, la niña fue envuelta y tirada por innumerables algas marinas oscuras, hundiéndose gradualmente en el fondo sombrío del mar."
  },
  AvgDialog_128699_Content_67 = {Text = "..."},
  AvgDialog_128699_Content_68 = {Text = "..."},
  AvgDialog_128699_Content_69 = {
    Text = "¿Eh, dónde estoy? ¿Por qué estoy sobre el agua? ¡Uf, qué sofocante!"
  },
  AvgDialog_128699_Content_7 = {
    Text = "Una fuerte vibración lanzó a Nautila, golpeando un barril de madera que rodaba por el suelo."
  },
  AvgDialog_128699_Content_70 = {
    Text = "Miraste extrañamente a la persona humana vestida de manera rara, flotando en el agua."
  },
  AvgDialog_128699_Content_71 = {
    Text = "(¿Cómo llegué aquí, quién es ese tipo?)"
  },
  AvgDialog_128699_Content_72 = {Text = "Plop plop."},
  AvgDialog_128699_Content_73 = {Text = "Plop plop."},
  AvgDialog_128699_Content_74 = {
    Text = "(¡Ah, cierto, soy una nutria marina! Y las nutrias marinas buscan conchas. ¡Conchas, conchas, conchas!)"
  },
  AvgDialog_128699_Content_75 = {
    Text = "Te sumerges felizmente en el agua cálida, nadando en dirección opuesta a ese humano que lucha por llegar al barco."
  },
  AvgDialog_128699_Content_76 = {
    Text = "No te das cuenta de que te fundes en las lágrimas del mar."
  },
  AvgDialog_128699_Content_8 = {Text = "Ugh..."},
  AvgDialog_128699_Content_9 = {
    Text = "Nautila, conteniendo el dolor, se levantó tambaleándose y corrió hacia el lado de Mosk."
  },
  AvgDialog_128700_Content_1 = {
    Text = "Glug... Glug..."
  },
  AvgDialog_128700_Content_10 = {
    Text = "Eres una nutria de un año y medio, buscando comida afuera con tu amigo gigante favorito."
  },
  AvgDialog_128700_Content_100 = {
    Text = "La saliva se secreta incontrolablemente de manera frenética, y bajo la tentación de la comida, tú y Mosk casi saltan al mismo tiempo y muerden el pescado a la parrilla."
  },
  AvgDialog_128700_Content_101 = {
    Text = "¡Delicioso—!"
  },
  AvgDialog_128700_Content_102 = {
    Text = "Oye, ah... Nautila, ¿la mano?"
  },
  AvgDialog_128700_Content_103 = {
    Text = "Solo fue un esguince, ya me lo he acomodado. Para un aventurero, no es nada grave, ¡gracias por tu medicina!"
  },
  AvgDialog_128700_Content_104 = {
    Text = "<Small:(Aunque es amargo y tiene un gran efecto residual, el efecto es realmente bueno.)>"
  },
  AvgDialog_128700_Content_105 = {
    Text = "¡Yuju! ¡Feliz, abrazo..."
  },
  AvgDialog_128700_Content_106 = {
    Text = "¡Eh eh, Mosk, ten cuidado."
  },
  AvgDialog_128700_Content_107 = {
    Text = "¿Eh? ¡Eh! No te preocupes, Mosk, la próxima vez gritaré de dolor para recordártelo."
  },
  AvgDialog_128700_Content_108 = {Text = "¡Pío!"},
  AvgDialog_128700_Content_11 = {
    Text = "(¿Qué tenemos aquí? Alga, hierba marina, piedras pequeñas...)"
  },
  AvgDialog_128700_Content_12 = {
    Text = "(Y Piedra, la tía de Piedra, el abuelo de Piedra...?)"
  },
  AvgDialog_128700_Content_13 = {
    Text = "(¡PIEDRA! ¡Dile a toda tu familia que dejen de nadar por aquí!!)"
  },
  AvgDialog_128700_Content_14 = {
    Text = "<Shake:¡ROAARRR—>"
  },
  AvgDialog_128700_Content_15 = {Text = "(No...)"},
  AvgDialog_128700_Content_16 = {
    Text = "El mar se agita formando un enorme remolino. ¡Una figura familiar se acerca a ti a toda velocidad, cargando algo grande sobre su espalda!"
  },
  AvgDialog_128700_Content_17 = {
    Text = "¡Bola de carbón! ¡Carne! ¡Mosk encontrar!"
  },
  AvgDialog_128700_Content_18 = {
    Text = "¡Feliz! ¡A casa! ¡Juntos!"
  },
  AvgDialog_128700_Content_19 = {
    Text = "Sin que pudieras protestar, la niña te agarró y te colocó sobre su espalda también, nadando hacia la superficie como un pez."
  },
  AvgDialog_128700_Content_2 = {
    Text = "<Shake:Gluglú... Gruñido...>"
  },
  AvgDialog_128700_Content_20 = {Text = "..."},
  AvgDialog_128700_Content_21 = {
    Text = "¡BOOM—! Un relámpago destella, un gran trueno resuena, y las nubes de lluvia hinchadas finalmente revientan, vertiendo su agua en el mar."
  },
  AvgDialog_128700_Content_22 = {
    Text = "Tú y Mosk se refugian en la cabaña segura, mirándose fijamente."
  },
  AvgDialog_128700_Content_23 = {
    Text = "¿Ah? ¡Ah, ah! (¿Es carne? ¡Grandullón, esto se parece a ti!)"
  },
  AvgDialog_128700_Content_24 = {
    Text = "¿Igual que yo?"
  },
  AvgDialog_128700_Content_25 = {
    Text = "Mosk inclinó la cabeza, mostrando su expresión de preocupación característica, y luego se inclinó seriamente para mirar la \"carne\" que había dejado en el suelo."
  },
  AvgDialog_128700_Content_26 = {
    Text = "Pff—¡Ugh."
  },
  AvgDialog_128700_Content_27 = {
    Text = "¿Qué pasó hace un momento? Mi cabeza parece que ha estado bajo el agua. ¿Dónde estoy? ¿Estoy muerto?"
  },
  AvgDialog_128700_Content_28 = {
    Text = "Un extraño tosió varias veces y escupió un gran chorro de agua de mar."
  },
  AvgDialog_128700_Content_29 = {
    Text = "¿Amigo? ¡¡Amigo!! ¡Igual que Mosk!"
  },
  AvgDialog_128700_Content_3 = {
    Text = "<Shake:¡Glug glug glug—>"
  },
  AvgDialog_128700_Content_30 = {
    Text = "¿Eh... eh?"
  },
  AvgDialog_128700_Content_31 = {
    Text = "<LightGray:¿Es de alguna tribu indígena cercana? Qué extraño... ¿Y dónde exactamente es este lugar?>"
  },
  AvgDialog_128700_Content_32 = {
    Text = "Percibes que está alerta, pero no hostil. Silenciosamente, te acercas poco a poco para observar mejor a este recién llegado."
  },
  AvgDialog_128700_Content_33 = {
    Text = "Esto debería ser la cabina de un barco. Desgastada, pero estructuralmente intacta en su mayor parte..."
  },
  AvgDialog_128700_Content_34 = {
    Text = "¡Espera! ¿¡Esos son remaches de la Corporación Northdrey!? Medidores de nivel de agua, válvulas deslizantes anulares—"
  },
  AvgDialog_128700_Content_35 = {
    Text = "A ver, en ese caso..."
  },
  AvgDialog_128700_Content_36 = {
    Text = "El extraño rebusca emocionado por la cabina abarrotada. Mientras tanto, Mosk permanece cerca, parpadeando con alegre curiosidad."
  },
  AvgDialog_128700_Content_37 = {
    Text = "Brillante, bonito. Mosk, traer. ¿Amigo, gustar?"
  },
  AvgDialog_128700_Content_38 = {
    Text = "Mosk, con estas piezas puedo hacer que este barco vuelva a funcionar. ¿Podrías dármelas?"
  },
  AvgDialog_128700_Content_39 = {
    Text = "Cuando lleguemos a Aglo, te prometo que te traeré aún más cosas brillantes, incluso más bonitas."
  },
  AvgDialog_128700_Content_4 = {
    Text = "Yaces boca arriba en el agua de mar cálida, estirando con satisfacción tus pequeñas y cortas extremidades y girando en un círculo perfecto."
  },
  AvgDialog_128700_Content_40 = {
    Text = "¡¡SQUIII—!! (¡¡De ninguna manera!! ¡¡Mi hermosa bolita todavía está ahí dentro!!)"
  },
  AvgDialog_128700_Content_41 = {
    Text = "Gritas con enojo, deseando recuperar tu pelota, pero tu atención es inmediatamente atraída por Mosk."
  },
  AvgDialog_128700_Content_42 = {
    Text = "Shh. Mosk, dar. Conchas."
  },
  AvgDialog_128700_Content_43 = {
    Text = "Mosk te metió disimuladamente dos conchas que ya habías estado mirando y empujó las piezas hacia el extraño, indicando que podía dárselas."
  },
  AvgDialog_128700_Content_44 = {
    Text = "¡Amigo, gustar, Mosk dar!"
  },
  AvgDialog_128700_Content_45 = {
    Text = "No sabes cómo estas cosas pueden hacer que un extraño se emocione tanto, mientras entierra su pequeño nariz en esas dos hermosas conchas que antes Mosk no te dejaba tocar."
  },
  AvgDialog_128700_Content_46 = {
    Text = "¡Maravilloso! Gracias... amigo."
  },
  AvgDialog_128700_Content_47 = {
    Text = "Conmovido por la amabilidad abierta y sincera de Mosk, el extraño finalmente se relaja un poco y les sonríe a ambos."
  },
  AvgDialog_128700_Content_48 = {
    Text = "Por cierto, mi nombre es Nautila."
  },
  AvgDialog_128700_Content_49 = {
    Text = "¡¡Yay!! Nautila, Mosk, ¡amigos, feliz!"
  },
  AvgDialog_128700_Content_5 = {
    Text = "(¿Espera, extremidades cortas?)"
  },
  AvgDialog_128700_Content_50 = {
    Text = "Mosk aclamó y abrió los brazos de par en par, lista para darle a su flamante nuevo amigo un enorme abrazo de oso."
  },
  AvgDialog_128700_Content_51 = {
    Text = "¡Ah! (Vaya... el grandote...)"
  },
  AvgDialog_128700_Content_52 = {
    Text = "¡Amigo, abraza!"
  },
  AvgDialog_128700_Content_53 = {
    Text = "Espera, Mosk... ¡Ay! ¡Duele!"
  },
  AvgDialog_128700_Content_54 = {
    Text = "Los remolinos en el aire se agrupan de repente, y en medio de la repentina presión del viento, se escucha un claro sonido de clang."
  },
  AvgDialog_128700_Content_55 = {Text = "¡¡Auch!!"},
  AvgDialog_128700_Content_56 = {
    Text = "Mosk se despertó de repente y soltó apresuradamente a Nautila, pero Nautila ya tenía el rostro distorsionado por el dolor, con el brazo claramente torcido en un ángulo antinatural."
  },
  AvgDialog_128700_Content_57 = {
    Text = "Lo siento, lo siento... yo..."
  },
  AvgDialog_128700_Content_58 = {
    Text = "Viendo a Mosk paralizada por el pánico, le muerdes el pantalón y la jalas hacia algo."
  },
  AvgDialog_128700_Content_59 = {
    Text = "¡Ah, ah! (¡Grandote, por aquí!)"
  },
  AvgDialog_128700_Content_6 = {
    Text = "<Shake:Clac, clac.>"
  },
  AvgDialog_128700_Content_60 = {
    Text = "¡Ah, cierto, esto! Nautila, ¡bebe!"
  },
  AvgDialog_128700_Content_61 = {
    Text = "¡No me toques!"
  },
  AvgDialog_128700_Content_62 = {
    Text = "Nautila, instintivamente, apartó la mano de Mosk y se recostó hacia atrás."
  },
  AvgDialog_128700_Content_63 = {
    Text = "[@Tónico compuesto]"
  },
  AvgDialog_128700_Content_64 = {
    Text = "Glug, glug— La botella de medicina cae al suelo y rueda hasta detenerse a los pies de Mosk."
  },
  AvgDialog_128700_Content_65 = {
    Text = "La niña que poco antes estaba llena de orgullo, captó agudamente el miedo del otro y, lentamente, dejó caer la mano."
  },
  AvgDialog_128700_Content_66 = {Text = "..."},
  AvgDialog_128700_Content_67 = {
    Text = "Lo siento, pero... ¿hay algún otro lugar en el barco? Puede que necesite descansar un momento a solas."
  },
  AvgDialog_128700_Content_68 = {
    Text = "Mosk guardó silencio por un momento, arrastró la manta más grande y suave del barco y la extendió en el suelo a lo lejos."
  },
  AvgDialog_128700_Content_69 = {
    Text = "Mosk, imprudente, Fuerza Bruta, daño."
  },
  AvgDialog_128700_Content_7 = {
    Text = "Plop plop～"
  },
  AvgDialog_128700_Content_70 = {
    Text = "Mosk, malo, lo siento. Casa, cálida, Nautila."
  },
  AvgDialog_128700_Content_71 = {
    Text = "Tu cuerpo de repente quedó en el aire, Mosk te entregó a Nautila con cuidado y un poco de timidez, como si fuera un tesoro."
  },
  AvgDialog_128700_Content_72 = {
    Text = "Fuera, Mosk. Bola de carbón, cálido, Nautila, aquí."
  },
  AvgDialog_128700_Content_73 = {
    Text = "Ella levantó el mentón, señaló hacia afuera, luego hacia la manta, y se quedó de pie obstinadamente entre Nautila y la Puerta."
  },
  AvgDialog_128700_Content_74 = {
    Text = "...Está bien, gracias."
  },
  AvgDialog_128700_Content_75 = {
    Text = "¿Ah, ah? (¡Hola, hola, grandullón?)"
  },
  AvgDialog_128700_Content_76 = {Text = "..."},
  AvgDialog_128700_Content_77 = {
    Text = "La lluvia no cesa en toda la noche. A medianoche, Nautila camina hasta la puerta de la cabina y mira a la niña dormida en la cubierta."
  },
  AvgDialog_128700_Content_78 = {
    Text = "Acurrucada en la esquina del barco, se resguarda del viento y la lluvia."
  },
  AvgDialog_128700_Content_79 = {
    Text = "...Durmiendo tan profundamente en un lugar así. Realmente eres como un animalito..."
  },
  AvgDialog_128700_Content_8 = {
    Text = "(¡Ah, sí! ¡Soy una nutria marina!)"
  },
  AvgDialog_128700_Content_80 = {
    Text = "Lo siento, no debí ser tan duro contigo, Mosk."
  },
  AvgDialog_128700_Content_81 = {
    Text = "Mosk es cubierta con una manta extra. Chasquea los labios en sueños y se hunde en un sueño aún más profundo y dulce."
  },
  AvgDialog_128700_Content_82 = {Text = "¡Pío!"},
  AvgDialog_128700_Content_83 = {
    Text = "A la mañana siguiente, después de la lluvia, era un buen momento para pescar. \n Con orgullo, atrapaste el pez más grande de hoy y lo lanzaste hacia Mosk, pero..."
  },
  AvgDialog_128700_Content_84 = {Text = "¡Pah!"},
  AvgDialog_128700_Content_85 = {Text = "..."},
  AvgDialog_128700_Content_86 = {Text = "..."},
  AvgDialog_128700_Content_87 = {
    Text = "Uu... ¡ah ah ah ah..."
  },
  AvgDialog_128700_Content_88 = {
    Text = "A continuación, ella se enterró la cara en tu abdomen sin preocuparse y comenzó a llorar desconsoladamente."
  },
  AvgDialog_128700_Content_89 = {
    Text = "Mosk, ¡mal!"
  },
  AvgDialog_128700_Content_9 = {
    Text = "Tu pequeña cabecita, que apenas tiene un poco de tamaño, recordó felizmente la situación actual."
  },
  AvgDialog_128700_Content_90 = {
    Text = "¡¡Iik!! ¡Squik! ¡¡SQUIK!! (¡¡Grandullona!! ¡¡TUS MOCOS!! ¡¡Cuidado con tus mocos!!)"
  },
  AvgDialog_128700_Content_91 = {
    Text = "<Italic:Snif>— hablar, igual, amigos, nunca... buaaa buaaa..."
  },
  AvgDialog_128700_Content_92 = {
    Text = "Mosk lloraba sin aliento, intentando sacar tu vientre de debajo de su cara, pero al final solo pudiste suspirar, dejando que ella esparciera esos mocos."
  },
  AvgDialog_128700_Content_93 = {
    Text = "(¿Quería decir que finalmente encontró a un amigo que puede hablar como él, pero al final lo arruinó? ¿Se puede considerar que el grandullón sabe hablar?)"
  },
  AvgDialog_128700_Content_94 = {
    Text = "(¡Eh, espera! ¡Qué buen olor!)"
  },
  AvgDialog_128700_Content_95 = {Text = "..."},
  AvgDialog_128700_Content_96 = {Text = "..."},
  AvgDialog_128700_Content_97 = {
    Text = "Eh, perdón, vi que todos parecían comer pescado crudo, así que lo preparé un poco... Aunque no hay condimentos, ¿quieres probarlo?"
  },
  AvgDialog_128700_Content_98 = {Text = "¡Aú!"},
  AvgDialog_128700_Content_99 = {Text = "¡Aú!"},
  AvgDialog_130451_Content_1 = {
    Text = "La noche es oscura y densa. Acabas de terminar una misión de campo, y el Despertado que te acompañó en la tarea —el pequeño caballero de otro mundo, Jurorroto·Ogier— te sigue en silencio."
  },
  AvgDialog_130451_Content_10 = {
    Text = "¡Espera, por favor no te acerques!"
  },
  AvgDialog_130451_Content_11 = {
    Text = "Antes de que las palabras terminen de resonar, tu campo de visión se vuelve de repente completamente negro."
  },
  AvgDialog_130451_Content_12 = {
    Text = "Las entidades invisibles que han coexistido con Jurorroto·Ogier todo este tiempo se lanzan de pronto hacia ti, se adhieren a tus extremidades, cubren tus ojos y te envuelven con fuerza, haciéndote sentir un frío gélido."
  },
  AvgDialog_130451_Content_13 = {Text = "¡Ogier!"},
  AvgDialog_130451_Content_14 = {
    Text = "Gritas, pero ese lodo oscuro se enrosca aún más fuerte, como si se apresurara a aprisionarte por completo. Intentas arrancarlo con las manos, pero se aferra de vuelta con la tenacidad de una enredadera."
  },
  AvgDialog_130451_Content_15 = {Text = "Ugh..."},
  AvgDialog_130451_Content_16 = {
    Text = "La voz tenue y difusa del joven llega entrecortada, evidentemente esforzándose por contener algo."
  },
  AvgDialog_130451_Content_17 = {
    Text = "¿Ogier? ¿Puedes oírme?"
  },
  AvgDialog_130451_Content_18 = {
    Text = "La fuerza que te envuelve tiembla levemente y luego vuelve a apretarse, como si estuviera siendo arrastrada entre dos voluntades opuestas."
  },
  AvgDialog_130451_Content_19 = {
    Text = "Por mi incompetencia, aun así te has hecho daño. Si pudiera encontrar una mejor manera de protegerte…"
  },
  AvgDialog_130451_Content_2 = {
    Text = "La misión no presentó mayor dificultad. Como experimentado Gardian del secreto, tú y Jurorroto·Ogier eliminasteis a todos los enemigos con facilidad. Sin embargo, por un momento de descuido, te quedó una pequeña cicatriz en la muñeca."
  },
  AvgDialog_130451_Content_20 = {
    Text = "Solo puedes escuchar algunas palabras confusas, como si fueran un murmullo para sí mismo."
  },
  AvgDialog_130451_Content_21 = {
    Text = "Aunque ese lodo te envuelve con fuerza, no sientes ni el más mínimo dolor ni asfixia. De repente comprendes que esto probablemente no pretende hacerte daño; más bien parece querer esconderte en un lugar absolutamente seguro, donde nada pueda acercarse a ti."
  },
  AvgDialog_130451_Content_22 = {
    Text = "No pasa nada, estoy perfectamente bien. No tienes que tener miedo."
  },
  AvgDialog_130451_Content_23 = {
    Text = "Tus palabras parecen surtir efecto. Esta vez, la fuerza de ese lodo oscuro comienza a aflojarse poco a poco. Aprovechas el momento para arrancarlo de ti."
  },
  AvgDialog_130451_Content_24 = {
    Text = "Ves a Ogier el Perjuro con la cabeza gacha y el ceño ligeramente fruncido, con una expresión de desolación. Sus ojos aún reflejan confusión, como una estatua penitente que carga con un pecado descomunal."
  },
  AvgDialog_130451_Content_25 = {
    Text = "¿Estás bien?"
  },
  AvgDialog_130451_Content_26 = {
    Text = "Llegué a usar contra vos un poder tan descontrolado…"
  },
  AvgDialog_130451_Content_27 = {
    Text = "No, debo… recobrar la cordura."
  },
  AvgDialog_130451_Content_28 = {
    Text = "Cierra los ojos y susurra, transformando el pequeño montón de barro negro que giraba en su mano en la forma de un puñal. La luz de la luna cae sobre la hoja que desprende un frío resplandor, y su objetivo es su propio otro brazo."
  },
  AvgDialog_130451_Content_29 = {
    Text = "Sin embargo, ese objeto afilado no llega a caer, pues te lanzas hacia él a tiempo y detienes su movimiento. Con un instante de retraso, te das cuenta de que aquellas fuerzas invisibles que hace un momento te envolvían con tanta fuerza se han retirado por completo."
  },
  AvgDialog_130451_Content_3 = {
    Text = "El silencio reina a tu alrededor. El cansancio nubla un poco tu consciencia, pero una voz que surge de repente a tu espalda te sobresalta."
  },
  AvgDialog_130451_Content_30 = {
    Text = "¿Mi señor...?"
  },
  AvgDialog_130451_Content_31 = {
    Text = "Te agachas a medias y lo rodeas suavemente con los brazos, dándole unas palmaditas reconfortantes en la espalda."
  },
  AvgDialog_130451_Content_32 = {
    Text = "Él no esquiva como de costumbre, sino que se queda paralizado en el sitio, manteniendo la postura en la que lo has abrazado."
  },
  AvgDialog_130451_Content_33 = {
    Text = "No tengas tanta prisa, relájate. Mira, Él ya ha sido sometido con éxito por ti. Pero, ¿qué ha pasado exactamente?"
  },
  AvgDialog_130451_Content_34 = {
    Text = "Lo siento, mi señor. No sé por qué, pero hoy la presencia que mora en mí estaba inusualmente agitada, y mis pensamientos se volvieron muy confusos."
  },
  AvgDialog_130451_Content_35 = {
    Text = "Aunque vos estabais a mi lado, Él no solo no retrocedió como de costumbre, sino que se volvió aún más activo… Por eso quería usar el dolor para calmarme."
  },
  AvgDialog_130451_Content_36 = {
    Text = "Mientras abrazas a Ogier, puedes sentir la temperatura anormal de su cuerpo y llegas más o menos a una conclusión. No esperabas que la influencia del Río Sagrado interfiriera directamente en la otra fuerza que reside en Ogier."
  },
  AvgDialog_130451_Content_37 = {
    Text = "Esto no es culpa tuya, sino la influencia de… otras cosas."
  },
  AvgDialog_130451_Content_38 = {
    Text = "Además, aunque este barro negro me atrapó por un momento, no me hirió en absoluto… Supongo que es porque tú estabas controlando a Él, ¿verdad? Es realmente admirable."
  },
  AvgDialog_130451_Content_39 = {
    Text = "Tras un breve silencio, por fin escuchas la voz apagada del joven."
  },
  AvgDialog_130451_Content_4 = {
    Text = "¡…Basta! ¿Cómo podría yo hacerle algo así a mi señor…?"
  },
  AvgDialog_130451_Content_40 = {
    Text = "…Gracias, habéis vuelto a consolarme."
  },
  AvgDialog_130451_Content_41 = {
    Text = "Ya es tarde; permitidme primero atender vuestras heridas y luego escoltaros de vuelta a vuestra habitación."
  },
  AvgDialog_130451_Content_5 = {
    Text = "Sabes que desde hace tiempo Jurorroto·Ogier ha estado luchando contra la entidad invisible que lo habita, pero su reacción de hoy parece exagerada de un modo extraño."
  },
  AvgDialog_130451_Content_6 = {
    Text = "Así que te das la vuelta y caminas hacia él."
  },
  AvgDialog_130451_Content_7 = {
    Text = "¿Ogier? ¿Estás bien? ¿Está intentando controlarte de nuevo?"
  },
  AvgDialog_130451_Content_8 = {Text = "¡!"},
  AvgDialog_130451_Content_9 = {
    Text = "Jurorroto·Ogier levanta bruscamente la cabeza, que hasta ese momento tenía clavada en la punta de sus zapatos, y retrocede un paso con un temblor."
  },
  AvgDialog_130453_Content_1 = {
    Text = "Dadas las habilidades especiales de Saya, todos han estado en tensión por cómo podría reaccionar ante la influencia del Río Sagrado."
  },
  AvgDialog_130453_Content_10 = {
    Text = "Todo lo que he vivido me hace quien soy, pero aún hay tanto que me queda por aprender."
  },
  AvgDialog_130453_Content_11 = {
    Text = "\"El instinto es reproducirse\", ¿eh? Vaya... ya veo..."
  },
  AvgDialog_130453_Content_12 = {
    Text = "Mientras habla, te pasa un cojín."
  },
  AvgDialog_130453_Content_13 = {
    Text = "Dejas escapar un largo suspiro de alivio, reclinándote hacia atrás igual que ella."
  },
  AvgDialog_130453_Content_14 = {
    Text = "Ya veo... así que después de todo lo que has pasado, la razón se impone al instinto..."
  },
  AvgDialog_130453_Content_15 = {
    Text = "<Small: Incluso después de convertirse en un Cuerpo Despertado, Saya sigue siendo verdaderamente única...>"
  },
  AvgDialog_130453_Content_16 = {
    Text = "Saya, si no es mucha molestia, ¿puedo usar tu casa como refugio seguro?!"
  },
  AvgDialog_130453_Content_17 = {
    Text = "Tus ojos se llenan de lágrimas de puro alivio mientras haces tu desesperada súplica."
  },
  AvgDialog_130453_Content_18 = {
    Text = "En este momento, lo que más importa es que el pobre Guardián de los Misaq por fin tiene un refugio seguro y fiable."
  },
  AvgDialog_130453_Content_19 = {
    Text = "¿Eh? Aunque no lo entiendo muy bien..."
  },
  AvgDialog_130453_Content_2 = {
    Text = "Sin embargo, para sorpresa de todos, simplemente permanece junto a la ventana en silencio. Su piel pálida es casi translúcida, como si estuviera sellada en otro mundo."
  },
  AvgDialog_130453_Content_20 = {
    Text = "Saya frunció el ceño con fingida dificultad y, solo después de ver con satisfacción tu expresión de decepción, volvió a sonreír."
  },
  AvgDialog_130453_Content_21 = {
    Text = "Saya frunce el ceño en un gesto juguetón de duda, y solo sonríe después de ver la expresión de decepción en tu rostro."
  },
  AvgDialog_130453_Content_22 = {
    Text = "Por supuesto que puedes. Pero... %player%, a cambio, ¿podrías decirme:"
  },
  AvgDialog_130453_Content_23 = {
    Text = "¿Quién es la persona que más te importa?"
  },
  AvgDialog_130453_Content_24 = {
    Text = "Como dos amigos cercanos que lo comparten todo, caéis en una conversación cómoda y desenfadada."
  },
  AvgDialog_130453_Content_25 = {
    Text = "Una figura aparece en tu conciencia, cierras los ojos con calma y ofreces igualmente tu Bendición por el futuro de Saya — que esta existencia pueda atravesar el vasto paso del tiempo."
  },
  AvgDialog_130453_Content_26 = {
    Text = "Una figura aparece en tu mente. Cierras los ojos, relajado/a, ofreciendo una bendición silenciosa para el futuro de Saya —siempre y cuando esos sentimientos no acaben con el mundo. Pero, ¿quién sabe?"
  },
  AvgDialog_130453_Content_27 = {
    Text = "El poder del Río Sagrado fluye entre vosotros como una marea suave, silenciosa y sin prisa."
  },
  AvgDialog_130453_Content_3 = {
    Text = "Hola, Guardián."
  },
  AvgDialog_130453_Content_4 = {
    Text = "Saya... ¿te encuentras bien? ¿Hay algo... raro?"
  },
  AvgDialog_130453_Content_5 = {
    Text = "Como si percibiera tu preocupación, la chica gira suavemente sobre sus talones—"
  },
  AvgDialog_130453_Content_6 = {
    Text = "sin fiebre, sin latidos acelerados, sin euforia extraña. Nada fuera de lo normal."
  },
  AvgDialog_130453_Content_7 = {
    Text = "No te preocupes por mí. Parece que no me ha pasado nada especial."
  },
  AvgDialog_130453_Content_8 = {
    Text = "Así que el instinto de la especie de Lady Thais es la reproducción... pero ¿podría eso afectarme a mí también?"
  },
  AvgDialog_130453_Content_9 = {
    Text = "Se sienta más cerca de ti, acurrucándose en un cojín mullido y sonriendo como un pequeño animal inofensivo."
  },
  AvgDialog_130454_Content_1 = {
    Text = "En el salón vacío, solo resuenan los pasos de tú y Murphy."
  },
  AvgDialog_13049_Content_1 = {
    Text = "Ogier agarró su arma con fuerza, alerta a cada susurro a su alrededor. En sus ojos, cada movimiento podría ser una emboscada de tropas enemigas."
  },
  AvgDialog_13049_Content_10 = {
    Text = "¿El sonido del agua? Probablemente sea el reloj de agua de allá."
  },
  AvgDialog_13049_Content_11 = {
    Text = "Parece que viene de afuera. ¡Voy a echar un vistazo!"
  },
  AvgDialog_13049_Content_12 = {
    Text = "¡No te apresures! ¡Vamos juntos!"
  },
  AvgDialog_13049_Content_13 = {
    Text = "Antes de que alguien pudiera detenerlo, Ogier recogió su arma y se lanzó hacia la puerta del palacio."
  },
  AvgDialog_13049_Content_14 = {
    Text = "Esto es—?!"
  },
  AvgDialog_13049_Content_15 = {
    Text = "¡Ataque del enemigo!"
  },
  AvgDialog_13049_Content_2 = {
    Text = "No puedes encontrar palabras para consolarlo. Las palabras del expediente del Despertador parpadean ante ti—"
  },
  AvgDialog_13049_Content_3 = {
    Text = "Declaración del Despertador: Ogier Danske, @2 Caballero del Ducado\nCayó en la Noche de la Defensa del Hogar..."
  },
  AvgDialog_13049_Content_4 = {
    Text = "Lord Chamberlain, por favor evacue a las afueras por seguridad. Podemos manejar las cosas aquí..."
  },
  AvgDialog_13049_Content_5 = {
    Text = "Ustedes dos caballeros ni siquiera pueden distinguir la aconito de las orquídeas. ¿Qué pasaría si accidentalmente le dan veneno a la princesa?"
  },
  AvgDialog_13049_Content_6 = {
    Text = "Un rechazo directo alivió la tensión. Ogier se sonrojó, el caballero guardia sofocó una risa, e incluso un suave chuckle vino de detrás de la puerta."
  },
  AvgDialog_13049_Content_7 = {
    Text = "No puedes irte—atrapado en el misterio centrado en los Ogier, abandonar precipitadamente puede traer consecuencias desconocidas."
  },
  AvgDialog_13049_Content_8 = {
    Text = "Tick-tock—"
  },
  AvgDialog_13049_Content_9 = {
    Text = "¿Oíste algún sonido?"
  },
  AvgDialog_13050_Content_1 = {
    Text = "Finalmente, la Batalla terminó. Tú y Ogier permanecieron al pie de las escaleras para limpiar la sala del palacio, mientras los caballeros de la guardia ya habían regresado frente a la habitación de la princesa."
  },
  AvgDialog_13050_Content_10 = {
    Text = "Susurros..."
  },
  AvgDialog_13050_Content_11 = {
    Text = "Sin embargo... ¿puede la plaga transformarse en monstruos que las personas comunes no pueden ver?"
  },
  AvgDialog_13050_Content_12 = {
    Text = "Esto es verdaderamente absurdo. Incluso si los poetas de la corte lo cantaran, pocos lo creerían."
  },
  AvgDialog_13050_Content_13 = {
    Text = "Al principio, mi padre y yo pensamos que era una maldición de los magos del país vecino, pero... pronto ellos también reportaron la plaga desatada."
  },
  AvgDialog_13050_Content_14 = {
    Text = "Incluso yo... *tos, tos*..."
  },
  AvgDialog_13050_Content_15 = {
    Text = "Mientras hablaba, una tos desgarradora resonó detrás de la puerta."
  },
  AvgDialog_13050_Content_16 = {
    Text = "Princesa, por favor abstente de hablar por ahora. Regresa a la cama primero."
  },
  AvgDialog_13050_Content_17 = {
    Text = "Susurros..."
  },
  AvgDialog_13050_Content_18 = {
    Text = "¡Atendente! ¡Atendente, vuelve y ayuda! La princesa—"
  },
  AvgDialog_13050_Content_19 = {Text = "¡Ugh!"},
  AvgDialog_13050_Content_2 = {
    Text = "Es nuestra primera vez luchando contra enemigos invisibles. Cuando todo esto termine, ¿qué te parece si buscamos a un bardo para que escriba nuestra historia y la convierta en una canción?"
  },
  AvgDialog_13050_Content_20 = {
    Text = "El sonido agudo de huesos rompiéndose resonó mientras algo desgarraba con fuerza el tejido muscular bien ajustado, causando que un líquido rojo brillante salpicara."
  },
  AvgDialog_13050_Content_21 = {
    Text = "¿Q...ué...?"
  },
  AvgDialog_13050_Content_22 = {
    Text = "¡Señor Fernando!!!"
  },
  AvgDialog_13050_Content_23 = {
    Text = "El Caballero Guardián tosió, sangre mezclada con trozos de carne brotando de su garganta. Sus ojos se agrandaron de incredulidad, llenos de confusión y miedo."
  },
  AvgDialog_13050_Content_3 = {
    Text = "¡Ya he decidido el nombre: \"Ojo de Dansk, Espada de Fernando\"!"
  },
  AvgDialog_13050_Content_4 = {
    Text = "Ogier, llamado por su nombre, miró al caballero guardia. Sus manos estaban cubiertas con mucha D-Slime. Vaciló, inseguro de cómo limpiarlas, sintiéndose extremadamente avergonzado."
  },
  AvgDialog_13050_Content_5 = {
    Text = "¿También escribirás mi nombre en la canción? ¿Qué ha hecho Ogier para merecer esto"
  },
  AvgDialog_13050_Content_6 = {
    Text = "Je, je... ¿No podemos el chambelán y yo al menos poner nuestros nombres en ello?"
  },
  AvgDialog_13050_Content_7 = {
    Text = "¡Por supuesto! ¡Absolutamente! ¡Tu nombre estará en la primera línea de esta canción!"
  },
  AvgDialog_13050_Content_8 = {
    Text = "Susurros..."
  },
  AvgDialog_13050_Content_9 = {
    Text = "@1 Suite Real... ¿Qué piensas? ¿Tengo talento para la poesía?"
  },
  AvgDialog_13051_Content_1 = {
    Text = "¿Qué... qué está pasando?"
  },
  AvgDialog_13051_Content_10 = {
    Text = "Sir Fernando... Recuerdo que era el único hijo en su familia."
  },
  AvgDialog_13051_Content_11 = {
    Text = "Si tan solo hubiera sido más vigilante..."
  },
  AvgDialog_13051_Content_12 = {
    Text = "No te culpes por su muerte. Esos monstruos @1 son esquivos. Hicimos nuestro mejor esfuerzo."
  },
  AvgDialog_13051_Content_13 = {
    Text = "Ogier sacudió la cabeza; tu pálido consuelo claramente no logró consolarlo.\nJusto en ese momento, un leve golpe llegó desde atrás."
  },
  AvgDialog_13051_Content_14 = {
    Text = "Chamberlain, lleva a Ogier contigo."
  },
  AvgDialog_13051_Content_15 = {
    Text = "¡¿Por qué?!"
  },
  AvgDialog_13051_Content_16 = {
    Text = "Tú... ¿ya no me necesitas? Sé que fallé en salvar al Lord Fernando, pero..."
  },
  AvgDialog_13051_Content_17 = {
    Text = "La plaga trae enfermedades, guerra y dolor... Quedarse aquí solo te convierte en su próxima comida."
  },
  AvgDialog_13051_Content_18 = {
    Text = "Su voz tembló, pero habló en un tono juguetón. Confrontada con la inminente amenaza de la muerte, no mostró ningún rastro de miedo."
  },
  AvgDialog_13051_Content_19 = {
    Text = "Supongo... que Lord Fernando no querría reunirse contigo tan pronto, ¿verdad?"
  },
  AvgDialog_13051_Content_2 = {
    Text = "Un leve sonido de pasos provenía del interior, seguido por el deslizamiento del pestillo de la puerta—"
  },
  AvgDialog_13051_Content_20 = {
    Text = "Pero... esto... es mi responsabilidad..."
  },
  AvgDialog_13051_Content_21 = {
    Text = "Ahora... solo soy yo... cumpliré la voluntad del Lord Fernando... heredaré..."
  },
  AvgDialog_13051_Content_22 = {
    Text = "Un largo y resignado suspiro provenía de detrás de la puerta. Después de un rato, la princesa te habló."
  },
  AvgDialog_13051_Content_23 = {
    Text = "Mayordomo, prométeme... cuando mi voz se haya ido por completo, debes llevarte a Ogier, incluso si tienes que noquearlo, ¿de acuerdo?"
  },
  AvgDialog_13051_Content_24 = {
    Text = "...Como desees."
  },
  AvgDialog_13051_Content_25 = {
    Text = "Ogier agarró su arma con fuerza, sus manos volviéndose blancas por el esfuerzo. Se sentía como si la lanza en sus brazos fuera su familia cuyo destino era incierto, una princesa moribunda, o el Fernando que se había ido para siempre."
  },
  AvgDialog_13051_Content_26 = {
    Text = "Fijó su mirada en la puerta del palacio, su mente vagando lejos. Ni siquiera el fuerte golpe de la puerta al ser golpeada pudo devolverlo a la realidad."
  },
  AvgDialog_13051_Content_27 = {
    Text = "¿Ogier? ¿Ogier?"
  },
  AvgDialog_13051_Content_28 = {
    Text = "Alguien viene."
  },
  AvgDialog_13051_Content_29 = {
    Text = "¿Alguien... viene? ¿Han regresado los caballeros?"
  },
  AvgDialog_13051_Content_3 = {
    Text = "¡No salgas!"
  },
  AvgDialog_13051_Content_30 = {
    Text = "La puerta fue slamada abierta, pero la bandera ondeando al viento no era del color que esperabas."
  },
  AvgDialog_13051_Content_4 = {
    Text = "Princesa... por favor, no salgas..."
  },
  AvgDialog_13051_Content_5 = {
    Text = "Ogier se esforzó por empujar el cuerpo del Caballero Fernando lejos de la puerta, luego bajó la cortina para cubrir la sangre que se acumulaba a través de la grieta."
  },
  AvgDialog_13051_Content_6 = {
    Text = "Las espinas del mutante atravesaron la armadura del pecho y la carne, dejando el pecho en un desastre sangriento, como si hubiera explotado. El caballero Fernando ya había muerto en agonía."
  },
  AvgDialog_13051_Content_7 = {
    Text = "...Está bien."
  },
  AvgDialog_13051_Content_8 = {
    Text = "Por favor, haz tu mejor esfuerzo para darle un entierro apropiado."
  },
  AvgDialog_13051_Content_9 = {
    Text = "Tú y Ogier intercambian una mirada, enrollan silenciosamente el cuerpo del caballero en una alfombra y se sientan en el suelo frente a la puerta del dormitorio. El dolor y la ansiedad llenan el aire."
  },
  AvgDialog_13052_Content_1 = {
    Text = "¿Qué está pasando? ¿Dónde están los enemigos?"
  },
  AvgDialog_13052_Content_10 = {
    Text = "Su excelencia, ¿puedes verlo también?"
  },
  AvgDialog_13052_Content_11 = {
    Text = "Le ofreces una mirada reconfortante y continúas negociando con el caballero."
  },
  AvgDialog_13052_Content_12 = {
    Text = "Ogier nunca ha sido del tipo que actúa de manera irracional, y tú lo sabes mejor por haber entrenado con él, ¿no es así?"
  },
  AvgDialog_13052_Content_13 = {
    Text = "Incluso si dices eso, realmente no hice nada..."
  },
  AvgDialog_13052_Content_14 = {
    Text = "...Espera un momento, Lord Fernando."
  },
  AvgDialog_13052_Content_15 = {
    Text = "Un golpe vino de la dirección de la puerta del dormitorio, atrayendo a todos de vuelta al frente con una débil voz femenina."
  },
  AvgDialog_13052_Content_16 = {
    Text = "Tenían razón... Era el enemigo invisible que propagó la plaga."
  },
  AvgDialog_13052_Content_17 = {
    Text = "Desde que la princesa dijo eso..."
  },
  AvgDialog_13052_Content_18 = {
    Text = "El Caballero Guardián apretó los dientes, levantó su arma y se colocó a tu lado."
  },
  AvgDialog_13052_Content_19 = {
    Text = "¡Dime la ubicación del enemigo, y haré todo lo posible para ayudar en la batalla!"
  },
  AvgDialog_13052_Content_2 = {
    Text = "El caballero guardia también bajó corriendo las escaleras a tu lado, completamente desconcertado."
  },
  AvgDialog_13052_Content_3 = {
    Text = "Ahora no es el momento para perder el tiempo. Mantente alerta."
  },
  AvgDialog_13052_Content_4 = {
    Text = "¡No estoy bromeando! ¿No puedes ver?!"
  },
  AvgDialog_13052_Content_5 = {
    Text = "Ogier se defiende ansiosamente, pero el caballero guardia sigue siendo escéptico."
  },
  AvgDialog_13052_Content_6 = {
    Text = "No es culpa suya; después de todo, los enemigos que tú y Ogier derrotasteis eran totalmente aberraciones derivadas de la Disolución."
  },
  AvgDialog_13052_Content_7 = {
    Text = "Observar visualmente el D-fenómeno es extremadamente raro.\nOgier es uno de los pocos desafortunados que también son considerados afortunados."
  },
  AvgDialog_13052_Content_8 = {
    Text = "Por favor, confía en nosotros."
  },
  AvgDialog_13052_Content_9 = {
    Text = "Por favor, confía en nosotros y cree en la integridad de Ogier."
  },
  AvgDialog_13053_Content_1 = {
    Text = "Telón final"
  },
  AvgDialog_13053_Content_10 = {Text = "..."},
  AvgDialog_13053_Content_11 = {
    Text = "Hagamos que Ogier custodie el palacio juntos.\nDespués de todo, es un legítimo y grandioso caballero guardián designado por el duque, ¿no?"
  },
  AvgDialog_13053_Content_12 = {
    Text = "El Caballero Guardián no pudo encontrar ninguna otra razón para rechazar. Después de asentir en acuerdo, ambos regresaron al palacio"
  },
  AvgDialog_13053_Content_13 = {
    Text = "El palacio está vacío; incluso la sirvienta ruidosa se ha ido.\nAparte de ustedes tres, solo queda la princesa."
  },
  AvgDialog_13053_Content_14 = {
    Text = "Llamaste a la puerta del lujoso dormitorio, el sonido resonando a través del pasillo silencioso, siniestramente amortiguado."
  },
  AvgDialog_13053_Content_15 = {
    Text = "¿Princesa? ¿Estás bien?"
  },
  AvgDialog_13053_Content_16 = {
    Text = "No hubo respuesta desde adentro. Después de esperar un momento, golpeaste la puerta nuevamente."
  },
  AvgDialog_13053_Content_17 = {
    Text = "Princesa, el caballero guardia, Ogier, y yo estamos aquí."
  },
  AvgDialog_13053_Content_18 = {
    Text = "A través de la pesada puerta de madera llegó el sonido de telas susurrando, mientras alguien luchaba por sentarse en la cama."
  },
  AvgDialog_13053_Content_19 = {
    Text = "...Estupidez."
  },
  AvgDialog_13053_Content_2 = {Text = "\"Sueño\""},
  AvgDialog_13053_Content_20 = {
    Text = "Tú... sigue adelante y únete a los demás. No hay necesidad de quedarte con un cadáver."
  },
  AvgDialog_13053_Content_21 = {
    Text = "La respiración de la chica es tenue, su voz tan suave como la de un mosquito. Parece que simplemente responderte ha agotado todas sus fuerzas."
  },
  AvgDialog_13053_Content_22 = {
    Text = "La plaga se propagó caóticamente en el ducado, sin perdonar a nadie, ni siquiera a la nobleza. La princesa cayó enferma antes de que comenzara la guerra, y hasta el día de hoy, no tiene la fuerza para dejar su cama."
  },
  AvgDialog_13053_Content_23 = {
    Text = "El médico real ha declarado francamente que la princesa ya no puede soportar la tensión de ser trasladada del palacio. Incluso los pequeños baches podrían costarle la vida."
  },
  AvgDialog_13053_Content_24 = {
    Text = "Princesa..."
  },
  AvgDialog_13053_Content_25 = {
    Text = "No importa lo que digas, no me iré. Por favor, permíteme protegerte...\ncumpliendo con mis deberes como caballero."
  },
  AvgDialog_13053_Content_26 = {Text = "..."},
  AvgDialog_13053_Content_27 = {
    Text = "...No te acerques demasiado a mi habitación. La plaga es irreversible, al menos... no dejes que se infecten."
  },
  AvgDialog_13053_Content_28 = {
    Text = "Cuando se agote el reloj de agua, ven a hablar conmigo, ¿de acuerdo?\nCuando ya no responda... deberías irte."
  },
  AvgDialog_13053_Content_3 = {
    Text = "Las conspiraciones se agitan en la oscuridad, encendiendo la mecha sembrada por la plaga. La guerra estalla de la noche a la mañana."
  },
  AvgDialog_13053_Content_4 = {
    Text = "La incurable <Yellow:plaga> ya se ha extendido por todo el ducado, y los guardias de la ciudad, plagados por la enfermedad, no pueden resistir el avance de los invasores."
  },
  AvgDialog_13053_Content_5 = {
    Text = "Incluso los caballeros reales han cruzado más allá del foso por orden del Gran Duque, uniéndose a la última línea de defensa de la capital."
  },
  AvgDialog_13053_Content_6 = {
    Text = "Ogier, ¿por qué sigues aquí?"
  },
  AvgDialog_13053_Content_7 = {
    Text = "I... quiero unirme a ti en la misión de escolta."
  },
  AvgDialog_13053_Content_8 = {
    Text = "Eres demasiado joven; la guerra... aún no te involucra.\nVe de regreso y encuentra un lugar seguro con tu familia."
  },
  AvgDialog_13053_Content_9 = {
    Text = "La casa de Ogier, la Hacienda Dansk... Debería estar fuera de la línea de defensa, ¿verdad?"
  },
  AvgDialog_13054_Content_1 = {
    Text = "Sueño o ideal"
  },
  AvgDialog_13054_Content_10 = {
    Text = "Ayudante, ¿podrías ir en mi nombre?"
  },
  AvgDialog_13054_Content_100 = {
    Text = "Las cosas de las que acabamos de discutir... Realmente no se lo dirás a la princesa, ¿verdad?"
  },
  AvgDialog_13054_Content_101 = {
    Text = "¿Qué? ¿No tengo ningún crédito contigo?"
  },
  AvgDialog_13054_Content_102 = {
    Text = "¿Cómo podría ser esto! ¡Yo nunca...!"
  },
  AvgDialog_13054_Content_103 = {
    Text = "Está bien, usaré lo que sucedió hoy para amenazarte."
  },
  AvgDialog_13054_Content_104 = {Text = "¿Amenaza?"},
  AvgDialog_13054_Content_105 = {
    Text = "Te arrodillas frente a Ogier, haciendo contacto visual con el ansioso cachorro, y le extiendes tu mano."
  },
  AvgDialog_13054_Content_106 = {
    Text = "La conversación de hoy permanecerá enterrada en nuestros corazones para siempre. Pero a cambio de mantener este secreto, debes prometerme una cosa."
  },
  AvgDialog_13054_Content_107 = {
    Text = "En esta era, no hay costumbre de prometer con el meñique, pero Ogier todavía inocentemente entrelazó tu dedo meñique extendido."
  },
  AvgDialog_13054_Content_108 = {
    Text = "Mientras esté dentro de mis capacidades..."
  },
  AvgDialog_13054_Content_109 = {
    Text = "Muy bien, me reservaré el derecho de hacer un deseo. Un día en el futuro, puede que venga a reclamarlo. No lo olvides, \"Caballero\""
  },
  AvgDialog_13054_Content_11 = {
    Text = "Si es lo último, despertar al dueño del sueño debería permitirnos escapar de aquí, ¿verdad?"
  },
  AvgDialog_13054_Content_12 = {
    Text = "¡Oye! ¿Lord Attendant? ¡Despierta!"
  },
  AvgDialog_13054_Content_13 = {
    Text = "Tus pensamientos se alejaron, siguiendo las pistas. Justo cuando el plan \"Despertar al Maestro de los Sueños\" estaba tomando forma, tus uñas se clavaron agudamente en tu brazo y el dolor te sacudió de vuelta a la realidad."
  },
  AvgDialog_13054_Content_14 = {
    Text = "Hiss—¡duele!"
  },
  AvgDialog_13054_Content_15 = {
    Text = "Así que puedes sentir dolor! Hemos estado llamándote durante ages, y no respondiste en absoluto, como un cadáver. ¿Hay algo malo con tus oídos?"
  },
  AvgDialog_13054_Content_16 = {
    Text = "Has estado distraído últimamente. ¿Estás demasiado cansado? ¿Qué tal si tomas un descanso en el feudo de tu familia? Ha pasado mucho tiempo desde tu última vacaciones."
  },
  AvgDialog_13054_Content_17 = {
    Text = "No — lo siento de verdad, solo tengo algo en mente..."
  },
  AvgDialog_13054_Content_18 = {
    Text = "La clave para escapar del \"Sueño\" está con Ogier. Aunque sientes curiosidad por cómo es el mundo más allá del centro de sueños, este no es el momento para apartarte demasiado."
  },
  AvgDialog_13054_Content_19 = {
    Text = "¿Algo en tu mente? ¿Qué es? ¿Es sobre alguien que te gusta y te está causando problemas?"
  },
  AvgDialog_13054_Content_2 = {
    Text = "\"Sueño\"\nPalacio de la Princesa"
  },
  AvgDialog_13054_Content_20 = {
    Text = "¿Te preocupa que la otra persona no te corresponda? Princesa, ¿por qué no le haces una pequeña adivinación a nuestro querido asistente? O mejor aún, simplemente dale a {Male=him,Female=her} una poción de amor..."
  },
  AvgDialog_13054_Content_21 = {
    Text = "Vamos, ¿cómo puedes usar magia y pociones para mantener una relación?"
  },
  AvgDialog_13054_Content_22 = {
    Text = "La princesa sonrió y cambió suavemente el tema planteado por la criada, saludándote."
  },
  AvgDialog_13054_Content_23 = {
    Text = "Ogier está entrenando actualmente con los caballeros. Por favor, míralo y asegúrate de que no le pase nada."
  },
  AvgDialog_13054_Content_24 = {
    Text = "¡Como deseéis!"
  },
  AvgDialog_13054_Content_25 = {
    Text = "Cuando la princesa te trajo una almohada mientras te sentías somnoliento, te dio una razón legítima para acercarte a Ogier."
  },
  AvgDialog_13054_Content_26 = {
    Text = "Sin embargo, si realmente necesitas pociones, aún puedes venir a mí por ellas."
  },
  AvgDialog_13054_Content_27 = {
    Text = "\"Sueño\"\nCampo de Entrenamiento de los Caballeros"
  },
  AvgDialog_13054_Content_28 = {
    Text = "Guiado por otros sirvientes, te abres camino a través del castillo laberíntico y los jardines hasta los terrenos de entrenamiento."
  },
  AvgDialog_13054_Content_29 = {
    Text = "El nítido tintineo de las armas y los continuos vítores de otros muestran claramente que alguien está practicando bajo el sol abrasador."
  },
  AvgDialog_13054_Content_3 = {
    Text = "Después de un tercer intento de despertar que solo resultó en un cambio inexplicable de escena, finalmente aceptaste que estabas atrapado en los recuerdos de Ogier."
  },
  AvgDialog_13054_Content_30 = {
    Text = "—Poco sabías, uno de los compañeros de práctica era Ogier."
  },
  AvgDialog_13054_Content_32 = {Text = "Ngh...!"},
  AvgDialog_13054_Content_33 = {
    Text = "Frente a una disparidad absoluta de poder, la persistencia y la fe son fútiles. El caballero adulto ni siquiera ha utilizado toda su fuerza, sin embargo, la resonancia metálica ya ha debilitado el agarre de Ogier."
  },
  AvgDialog_13054_Content_34 = {
    Text = "La lanza fue derribada, y el joven, empapado de sudor, se arrodilló en el áspero suelo de grava, jadeando por aire."
  },
  AvgDialog_13054_Content_35 = {
    Text = "Chico, regresa por ahora. Si sigues practicando así, terminarás rompiéndote la mano."
  },
  AvgDialog_13054_Content_36 = {
    Text = "Así es, todavía eres muy joven.\nVuelve para entrenamiento en un par de años. Ni siquiera puedes levantar un arma ahora mismo."
  },
  AvgDialog_13054_Content_37 = {Text = "No..."},
  AvgDialog_13054_Content_38 = {
    Text = "Ogier tembló, se agachó para recoger la lanza caída, y con gran esfuerzo, ajustó su posición, apuntando la punta de la lanza hacia el caballero de combate."
  },
  AvgDialog_13054_Content_39 = {
    Text = "Puedo... ¡aferrarme!"
  },
  AvgDialog_13054_Content_4 = {
    Text = "Te encuentras en una esquina de la Cámara de la Princesa, haciendo como si escucharas y jugando obedientemente el papel de un asistente."
  },
  AvgDialog_13054_Content_40 = {
    Text = "Oh, niño terco..."
  },
  AvgDialog_13054_Content_41 = {
    Text = "La cara del niño se sonrojó por el agotamiento y la falta de oxígeno. La persona que había intentado hacer que Ogier se rindiera a través del entrenamiento finalmente habló, ante tal fuerza de voluntad."
  },
  AvgDialog_13054_Content_42 = {
    Text = "No está nada mal. Los forasteros miran nuestra duquesa con codicia. Necesitamos más chicos firmes como el Joven Maestro Danske."
  },
  AvgDialog_13054_Content_43 = {
    Text = "¿Debo ponerme serio?"
  },
  AvgDialog_13054_Content_44 = {
    Text = "¡No seas tan imprudente! Si este niño colapsa por el entrenamiento, ¿cómo se lo explicarás al Gran Duque y a la Princesa?"
  },
  AvgDialog_13054_Content_45 = {
    Text = "Comienza con entrenamiento físico básico. Mantén un ojo en él y asegúrate de que no se lastime con las armas."
  },
  AvgDialog_13054_Content_46 = {
    Text = "Las palabras de la líder encendieron a Ogier. Los ojos del joven se iluminaron instantáneamente, desbordando emoción."
  },
  AvgDialog_13054_Content_47 = {
    Text = "¿Aceptaste dejarme unirme a los Caballeros?!"
  },
  AvgDialog_13054_Content_48 = {
    Text = "Incluso sin la broma del Gran Duque, con este nivel de fuerza de voluntad, estás calificado para ser un caballero aprendiz."
  },
  AvgDialog_13054_Content_49 = {
    Text = "Viendo las abrasiones y manchas de sangre en el chico, el capitán dudó, sintiéndose algo reacio."
  },
  AvgDialog_13054_Content_5 = {
    Text = "¡Princesa, princesa! ¡Escuché que el joven maestro de Dansk informó a los caballeros nuevamente. ¡Es el tercer día!"
  },
  AvgDialog_13054_Content_50 = {
    Text = "Vuelve por hoy. A partir de mañana, te daré un plan de entrenamiento personalizado—Y ustedes restantes, ¡dejen de mirar y hagan dos rondas adicionales de ejercicios con peso!"
  },
  AvgDialog_13054_Content_51 = {
    Text = "Ten piedad de nosotros, Capitán—"
  },
  AvgDialog_13054_Content_52 = {
    Text = "Antes de que el líder terminara de hablar, la rara atmósfera desenfadada provocó pequeños actos de rebelión, con los jóvenes caballeros liberando su estrés de esta manera."
  },
  AvgDialog_13054_Content_53 = {
    Text = "¡Tres rondas!"
  },
  AvgDialog_13054_Content_54 = {
    Text = "En medio de los lamentos incesantes, Ogier finalmente se relajó y colapsó en el suelo con un estruendo."
  },
  AvgDialog_13054_Content_55 = {
    Text = "Genial... Finalmente..."
  },
  AvgDialog_13054_Content_56 = {
    Text = "Ogier, ¿podemos hablar?"
  },
  AvgDialog_13054_Content_57 = {
    Text = "Eres... ¡Lord Chamberlain! Que me veas en un estado tan embarazoso, yo..."
  },
  AvgDialog_13054_Content_58 = {
    Text = "Ogier se enderezó al instante, su rodilla raspada frotándose contra la arena, el dolor retorciendo su expresión tensa."
  },
  AvgDialog_13054_Content_59 = {
    Text = "Le saludaste y sacaste la poción curativa que la princesa había deslizado en tu bolsillo en algún momento."
  },
  AvgDialog_13054_Content_6 = {
    Text = "Él realmente tomó en serio las palabras de su padre... ¿Cómo puede alguien tan joven soportar el entrenamiento de los Caballeros?"
  },
  AvgDialog_13054_Content_60 = {
    Text = "Eh... ¿No duele? ¿No es este un medicamento curativo?"
  },
  AvgDialog_13054_Content_61 = {
    Text = "Esto es un medicamento preparado personalmente por la princesa, probablemente con un tratamiento especial."
  },
  AvgDialog_13054_Content_62 = {
    Text = "\"La princesa a la que sirves es una chica misteriosa. Rara vez sale de sus aposentos, pero posee una comprensión única y talento para la medicina. En tu época, sería una farmacéutica de renombre.\""
  },
  AvgDialog_13054_Content_63 = {
    Text = "Es una pena que sus talentos fueran malinterpretados en esos siglos perdidos. Has escuchado a otros asistentes llamarla \"bruja\" en secreto más de una vez."
  },
  AvgDialog_13054_Content_64 = {
    Text = "¿Poción de la princesa?! Es demasiado preciosa para usarla en mí—¡Ay!"
  },
  AvgDialog_13054_Content_65 = {
    Text = "No te muevas, o desperdiciarás la misericordia de la princesa.\nSiéntate primero y déjame terminar de tratar la herida."
  },
  AvgDialog_13054_Content_66 = {
    Text = "Temiendo desperdiciar medicina preciosa, Ogier finalmente se sentó en silencio.\nLos otros caballeros fueron saliendo poco a poco del área, aprovechando esta rara oportunidad."
  },
  AvgDialog_13054_Content_67 = {
    Text = "Ogier, ¿puedes sentir que estás soñando?"
  },
  AvgDialog_13054_Content_68 = {
    Text = "De verdad, es como un sueño..."
  },
  AvgDialog_13054_Content_69 = {
    Text = "El joven ajustó tus palabras a la situación actual. Cerró los ojos y suspiró, su voz llena de satisfacción y anhelo."
  },
  AvgDialog_13054_Content_7 = {
    Text = "No... no, espera... tal vez haya otra posibilidad."
  },
  AvgDialog_13054_Content_70 = {
    Text = "Invocados, elegidos y reconocidos por los caballeros... Realmente se siente como un sueño."
  },
  AvgDialog_13054_Content_71 = {
    Text = "<LightGray:(¿Debería decirle directamente que esto es un sueño? Pero aún no he comprendido la esencia aquí. ¿Es un recuerdo o un sueño...?)>"
  },
  AvgDialog_13054_Content_72 = {
    Text = "Tu vacilación llamó la atención de Ogier. De repente, se volvió un poco inquieto, frotando nerviosamente el dobladillo de su ropa."
  },
  AvgDialog_13054_Content_73 = {
    Text = "¿Señor Chambelán, está... ¿está insatisfecha la princesa conmigo?"
  },
  AvgDialog_13054_Content_74 = {Text = "..."},
  AvgDialog_13054_Content_75 = {
    Text = "Ogier es el hijo de un noble que podría haber vivido una vida de lujo. ¿Por qué insistir en convertirse en caballero?"
  },
  AvgDialog_13054_Content_76 = {
    Text = "Porque... porque..."
  },
  AvgDialog_13054_Content_77 = {
    Text = "La voz de Ogier se volvió más suave y su cabeza se inclinó más en vergüenza. La respuesta a la pregunta claramente le hizo sentir demasiada vergüenza para hablar."
  },
  AvgDialog_13054_Content_78 = {
    Text = "Te juro, nuestra conversación permanecerá desconocida para cualquier tercera parte."
  },
  AvgDialog_13054_Content_79 = {
    Text = "Porque... mi padre también está enfermo, al igual que la tía Merlyn en la cocina y el hermano Pedro, el jardinero..."
  },
  AvgDialog_13054_Content_8 = {
    Text = "Según la descripción de la sirvienta, Ogier está en entrenamiento con la orden de caballería. Dado que Ogier no participó en esta conversación, la hipótesis sobre \"los recuerdos de Ogier\" no puede ser establecida."
  },
  AvgDialog_13054_Content_80 = {
    Text = "Hay muchos, muchos otros que han contraído la misma enfermedad."
  },
  AvgDialog_13054_Content_81 = {
    Text = "Mi padre ya no puede abandonar su cama, y yo aún no he crecido... Como su único hijo, yo..."
  },
  AvgDialog_13054_Content_82 = {
    Text = "Si el Padre fallece, todos en la mansión serán despedidos.\nTodos siguen enfermos... sin a dónde ir."
  },
  AvgDialog_13054_Content_83 = {
    Text = "Debo... Debo asumir la responsabilidad por todos... Solo convirtiéndome en caballero y ganando la protección del duque..."
  },
  AvgDialog_13054_Content_84 = {
    Text = "Al decir esto, el rostro de Ogier palideció. Te miró ansiosamente, como si temiera que lo acusaras de \"motivos impuros\" o lo castigases en nombre de la princesa."
  },
  AvgDialog_13054_Content_85 = {
    Text = "Inocencia similar, voluntad idéntica y firme.\nSin duda, él es el Ogier que conoces."
  },
  AvgDialog_13054_Content_86 = {
    Text = "Lo siento, Su Excelencia... Si, si deseas que la princesa me reemplace... No tengo objeciones..."
  },
  AvgDialog_13054_Content_87 = {
    Text = "La noche en que fuiste elegido por el Gran Duque, juraste sobre el honor de tu familia frente a todos los invitados, ¿no?"
  },
  AvgDialog_13054_Content_88 = {
    Text = "Jura cumplir con tus deberes caballerescos con tu vida... ¿Fuiste sincero cuando recitaste el juramento junto con otros?"
  },
  AvgDialog_13054_Content_89 = {
    Text = "<Big:¡Por supuesto! ¡No estoy bromeando!>"
  },
  AvgDialog_13054_Content_9 = {
    Text = "Esto no es solo un \"recuerdo\". Quizás has entrado en un pedazo de historia real, o tal vez es un sueño completado por tu subconsciente?"
  },
  AvgDialog_13054_Content_90 = {
    Text = "\"Siempre seré leal, siempre dedicado\"... Mi padre esperaría lo mismo de mí."
  },
  AvgDialog_13054_Content_91 = {
    Text = "Está bien, no le contaré a la princesa sobre esto.\nNo te preocupes tanto, estás a punto de llorar."
  },
  AvgDialog_13054_Content_92 = {
    Text = "¿Hay... realmente?! ¡Disculpa!"
  },
  AvgDialog_13054_Content_93 = {
    Text = "Ugh... ¡Ugh?! Mis ojos... me duelen..."
  },
  AvgDialog_13054_Content_94 = {
    Text = "Ogier frotó sus ojos torpemente, pero su pañuelo ya se había ensuciado durante el entrenamiento, aumentando su vergüenza."
  },
  AvgDialog_13054_Content_95 = {
    Text = "No puedo creer que el Mayordomo me viera en un estado tan embarazoso..."
  },
  AvgDialog_13054_Content_96 = {
    Text = "No es nada, te he visto en un estado peor.\nVolvamos al palacio y te refrescamos. No puedes volver a casa luciendo así."
  },
  AvgDialog_13054_Content_97 = {Text = "..."},
  AvgDialog_13054_Content_98 = {
    Text = "Su Excelencia, ¿puedo pedirle un favor?"
  },
  AvgDialog_13054_Content_99 = {
    Text = "Me gustaría escuchar más detalles."
  },
  AvgDialog_13055_Content_1 = {
    Text = "Hilos del pasado"
  },
  AvgDialog_13055_Content_10 = {Text = "Reconectar"},
  AvgDialog_13055_Content_11 = {
    Text = "Al ver a Ogier acercándose a perder el control, decides no esperar más y sujetas firmemente sus manos, ahora cubiertas de lodo negro."
  },
  AvgDialog_13055_Content_12 = {
    Text = "La Llave de Plata parpadea mientras guías tus tentáculos mentales a través de la tormenta de Gnosis, cruzando capas de oscuridad, y reconectas con Ogier."
  },
  AvgDialog_13055_Content_13 = {
    Text = "Acompañado de un dolor agudo como una descarga eléctrica, escenas parpadean ante tus ojos y luego desaparecen instantáneamente."
  },
  AvgDialog_13055_Content_14 = {
    Text = "Los signos de la pérdida de control retrocedieron como una marea, y el estado de Ogier se estabilizó. Su rostro juvenil mostraba un atisbo de fatiga."
  },
  AvgDialog_13055_Content_15 = {
    Text = "Mi lord, esta vez... ¿cuánto tiempo duré?"
  },
  AvgDialog_13055_Content_16 = {
    Text = "El temporizador solo completó media rotación; después de desconectar el enlace, Ogier no pudo durar más que en la sesión de entrenamiento anterior."
  },
  AvgDialog_13055_Content_17 = {
    Text = "Hmm... 30 segundos, más 200 milisegundos."
  },
  AvgDialog_13055_Content_18 = {
    Text = "¿Cómo... cómo podría pasar esto...?"
  },
  AvgDialog_13055_Content_19 = {
    Text = "Su tono era inquieto, después de todo, fue su idea proponer el <Yellow:Entrenamiento de Ruptura de Cadenas>."
  },
  AvgDialog_13055_Content_2 = {
    Text = "Campos de Entrenamiento de la Universidad Mythag\nCrepúsculo"
  },
  AvgDialog_13055_Content_20 = {
    Text = "Sigue atormentado por la anomalía del día de la ceremonia de entrega de llaves, temiendo que un día pueda perder el control y dirigir su lanza contra ti. Así que busca fortalecer su habilidad de mantener la razón sin un enlace"
  },
  AvgDialog_13055_Content_21 = {
    Text = "Mi lord, ¡intentemos de nuevo!"
  },
  AvgDialog_13055_Content_22 = {
    Text = "Hemos estado entrenando durante mucho tiempo. El sobreentrenamiento tendrá consecuencias negativas."
  },
  AvgDialog_13055_Content_23 = {
    Text = "Los ojos de Ogier parpadearon, pero finalmente se apagaron, su tono teñido de autorreproche."
  },
  AvgDialog_13055_Content_24 = {
    Text = "Era mi descuido..."
  },
  AvgDialog_13055_Content_25 = {Text = "..."},
  AvgDialog_13055_Content_26 = {
    Text = "Te veré mañana después del almuerzo. No tengo ninguna tarea de investigación tampoco."
  },
  AvgDialog_13055_Content_27 = {
    Text = "¡Mi señor!"
  },
  AvgDialog_13055_Content_28 = {
    Text = "Bajo la mirada emocionada del cachorro, tus piernas agotadas te llevaron de vuelta al dormitorio."
  },
  AvgDialog_13055_Content_29 = {
    Text = "Un momia simplemente lavada yace en una suave cama, agradecida por la elección de suministros de cama de Mythag, mientras la conciencia se desliza gradualmente..."
  },
  AvgDialog_13055_Content_3 = {
    Text = "La llave plateada brilla mientras controlas el hilo plateado invisible y delicado en tu mente, retirándolo de la luz brillante."
  },
  AvgDialog_13055_Content_30 = {Text = "..."},
  AvgDialog_13055_Content_31 = {
    Text = "Melodías extrañas resuenan en la oscuridad, acompañadas por el tintineo de copas de plata. Una atmósfera bulliciosa pero elegante llena el Sueño."
  },
  AvgDialog_13055_Content_32 = {
    Text = "Tan ruidoso... ¿Quién está de fiesta en los dormitorios a medianoche...?"
  },
  AvgDialog_13055_Content_33 = {
    Text = "Te diste la vuelta y alcanzaste la manta que había sido pateada fuera de la cama."
  },
  AvgDialog_13055_Content_34 = {
    Text = "Una mano se extendió hacia la Niebla, agarrando una nube pesada con incógnitas, sintiéndose tanto real como irreal."
  },
  AvgDialog_13055_Content_35 = {
    Text = "Oh, ¡ahí estás! Estaba buscándote."
  },
  AvgDialog_13055_Content_36 = {
    Text = "¿Q...ué...?"
  },
  AvgDialog_13055_Content_37 = {
    Text = "Mis piernas se sienten débiles otra vez. ¿Podrías ir a buscar a mi padre y traer a mi caballero?"
  },
  AvgDialog_13055_Content_38 = {
    Text = "¿Caballero...?"
  },
  AvgDialog_13055_Content_39 = {
    Text = "¿Qué estás esperando? ¿No oyiste lo que dijo la princesa?"
  },
  AvgDialog_13055_Content_4 = {Text = "Ngh...!"},
  AvgDialog_13055_Content_40 = {
    Text = "La mujer de repente te dio una palmadita en el hombro. La oscuridad retrocedió, revelando un lugar desconocido."
  },
  AvgDialog_13055_Content_41 = {
    Text = "Un gran salón, una banda tocando suites antiguas a lo lejos, postres exquisitos y tentadores, y damas nobles que te miran."
  },
  AvgDialog_13055_Content_42 = {
    Text = "Y la chica tumbada en el suave sofá, rodeada por ellos."
  },
  AvgDialog_13055_Content_43 = {
    Text = "No importa, no seas tan duro con {Male=him,Female=her}. Mi asistente ha estado ocupado toda la noche sin descanso para presentar un banquete perfecto para todos."
  },
  AvgDialog_13055_Content_44 = {
    Text = "La niña, a menudo llamada princesa por otros debido a su noble estatus, te ayudó suavemente a salir de la situación."
  },
  AvgDialog_13055_Content_45 = {
    Text = "¿Puedes traerme el \"caballero\" que mi padre designó para que conociera? Entonces podrás descansar por el día, ¿de acuerdo?"
  },
  AvgDialog_13055_Content_46 = {
    Text = "Una inundación de recuerdos fragmentados irrumpe en tu mente. Son desarticulados e incompletos, pero suficientes para que asumas el papel de este recipiente —el único asistente de la princesa."
  },
  AvgDialog_13055_Content_47 = {
    Text = "...Gracias por tu amabilidad, Princesa."
  },
  AvgDialog_13055_Content_48 = {
    Text = "El instinto de tu cuerpo te impulsó a inclinarte ante ella. Entre miradas envidiosas o desdeñosas, te abriste paso a través del grupo de damas nobles hacia el bullicioso salón."
  },
  AvgDialog_13055_Content_49 = {
    Text = "Mirarás hacia abajo tus \"manos\". La piel es un par de tonos más oscura de lo que normalmente mantienes oculta bajo guantes, marcada con cicatrices tenues que claramente indican una vida lejos del lujo."
  },
  AvgDialog_13055_Content_5 = {
    Text = "No te exijas demasiado. Cuando no puedas sostenerte, ¡enlázate con la Piscina Negra!"
  },
  AvgDialog_13055_Content_50 = {
    Text = "El paso del elegante jarrón de metal confirmaba aún más la ominosa sospecha—"
  },
  AvgDialog_13055_Content_51 = {
    Text = "El reflejo que se muestra allí no es tu cara."
  },
  AvgDialog_13055_Content_52 = {
    Text = "¡Su excelencia! ¿Has venido aquí en nombre de la princesa?"
  },
  AvgDialog_13055_Content_53 = {
    Text = "La sirvienta que emergió de la multitud tenía ojos más agudos que los tuyos, reconociendo al \"tú\" familiar al instante en medio de la bulliciosa multitud."
  },
  AvgDialog_13055_Content_54 = {
    Text = "<Small:¡El Duque ha elegido a un caballero tan joven! ¿Realmente van a permitir que un niño tan pequeño se una al entrenamiento de caballeros? Dudo que incluso pueda levantar un arma.>"
  },
  AvgDialog_13055_Content_55 = {
    Text = "<BigItalic: Disculpe, por favor, haga paso. Estamos aquí por orden de la Princesa @1 para solicitar una audiencia—>"
  },
  AvgDialog_13055_Content_56 = {
    Text = "<Small:No lo viste hace un momento, pero cuando el Duque lo trajo frente a todos, su cara se sonrojó de vergüenza.>"
  },
  AvgDialog_13055_Content_57 = {
    Text = "<BigItalic:¡Lo siento, lo siento! ¡El asistente de la princesa ha llegado!!>"
  },
  AvgDialog_13055_Content_58 = {
    Text = "<Small:¿Cuánto tiempo le tomará a un niño como este convertirse en un verdadero caballero... El duque debe estar bromeando, ¿verdad?>"
  },
  AvgDialog_13055_Content_59 = {
    Text = "La sirvienta abrió camino entre la multitud con sus palabras mientras te susurraba comentarios juguetones, llevándote hacia el trono."
  },
  AvgDialog_13055_Content_6 = {
    Text = "Puedo... todavía... ¡aferrarme!"
  },
  AvgDialog_13055_Content_60 = {
    Text = "Hola. ¿Eres el chamberlán?"
  },
  AvgDialog_13055_Content_61 = {Text = "¡Eres...!"},
  AvgDialog_13055_Content_62 = {
    Text = "Soy el hijo mayor de la familia Danske. Muy agradecido al Gran Duque por su favor, estoy extremadamente honrado de servir como el caballero de la Princesa @1."
  },
  AvgDialog_13055_Content_7 = {
    Text = "Ogier se arrodilló; sin el apoyo del enlace, sustentó su cuerpo con una lanza para no caer"
  },
  AvgDialog_13055_Content_8 = {Text = "Master..."},
  AvgDialog_13055_Content_9 = {
    Text = "Un líquido negro se filtraba por las esquinas de sus ojos, los bordes de sus labios y sus conductos auditivos. Sus órganos habían sido aplastados por una baba negra amorfa, dejando claro lo inimaginable que era el dolor que el chico estaba soportando."
  },
  AvgDialog_13056_Content_1 = {
    Text = "Nueva balada"
  },
  AvgDialog_13056_Content_10 = {
    Text = "¡No te acerques más! ¡No mostraré piedad!"
  },
  AvgDialog_13056_Content_100 = {
    Text = "Vamos. Hoy es un día libre, y el Mercado Este estará en plena actividad. También podemos visitar el orfanato y ver a los niños..."
  },
  AvgDialog_13056_Content_101 = {
    Text = "Deliberadamente murmuras tu horario y te alejas del campo de entrenamiento sin preocuparte en absoluto."
  },
  AvgDialog_13056_Content_102 = {
    Text = "¡Maestro! ¡Maestro! Por favor, dime cómo lo supiste—"
  },
  AvgDialog_13056_Content_103 = {
    Text = "Porque, ya sabes, él seguirá."
  },
  AvgDialog_13056_Content_11 = {
    Text = "Ogier levantó su lanza y bloqueó las escaleras."
  },
  AvgDialog_13056_Content_12 = {
    Text = "Esta es tu última advertencia. ¡Sal del palacio ahora!"
  },
  AvgDialog_13056_Content_13 = {
    Text = "¡Oye, ¿escuchaste eso? ¿Qué dijo? \"¿Por favor pídannos que nos vayamos\"?"
  },
  AvgDialog_13056_Content_14 = {
    Text = "Hahahaha, ¡esto es hilarante! No es de extrañar que el ducado sea tan débil—están jugando a ser caballeros con niños."
  },
  AvgDialog_13056_Content_15 = {
    Text = "Bájalo, me duelen los oídos."
  },
  AvgDialog_13056_Content_16 = {
    Text = "El oficial ignoró la advertencia de Ogier, caminó hacia la puerta del dormitorio y miró hacia abajo a Ogier."
  },
  AvgDialog_13056_Content_17 = {
    Text = "Apártense."
  },
  AvgDialog_13056_Content_18 = {
    Text = "Ogier se esforzó por sostener la lanza horizontalmente, intentando bloquear el avance del oficial."
  },
  AvgDialog_13056_Content_19 = {
    Text = "¡Por favor, sal!"
  },
  AvgDialog_13056_Content_2 = {
    Text = "Botas, chispeando y cubiertas de polvo, pisaron la alfombra del palacio."
  },
  AvgDialog_13056_Content_20 = {
    Text = "¿Sabías que el arma de un caballero no te queda?"
  },
  AvgDialog_13056_Content_22 = {
    Text = "La resistencia es inútil ante un poder abrumador.\nEl oficial desvió sin esfuerzo la lanza del Ogier y le clavó un cuchillo en el pecho."
  },
  AvgDialog_13056_Content_23 = {Text = "*Tos—!*"},
  AvgDialog_13056_Content_24 = {
    Text = "¿Ves eso? Esta es la habilidad que deberías aprender.\nDespués de todo, con tu país destruido, solo mereces quedarte en los callejones oscuros, sin ver la luz del día."
  },
  AvgDialog_13056_Content_25 = {
    Text = "El robo, el hambre y el odio mutuo... este es tu destino.\nLa lanza, que simboliza el honor caballeresco, no te será útil en el futuro."
  },
  AvgDialog_13056_Content_26 = {
    Text = "La sangre se precipitó hacia la tráquea, causando un dolor sordo, como ahogarse en tierra. Cada respiración chisporroteaba con el olor a sangre."
  },
  AvgDialog_13056_Content_27 = {
    Text = "Quieres saltar sobre la mesa baja, empujar al sargento por las escaleras y proteger a Ogier, que está arrodillado junto a la puerta.\nPero tu cuerpo de repente tiembla, se paraliza y ya no obedece tus órdenes."
  },
  AvgDialog_13056_Content_28 = {
    Text = "No... *tos*..."
  },
  AvgDialog_13056_Content_29 = {
    Text = "Me expresé mal; ya no verás ese futuro—te convertirás en combustible para este palacio, igual que él."
  },
  AvgDialog_13056_Content_3 = {
    Text = "Esta es tu alfombra favorita en \"Sueño Recuerdos.\" Tú y la ruidosa sirvienta pasaron toda una tarde seleccionándola en el almacén del Gran Duque y otra media jornada dejándola plana."
  },
  AvgDialog_13056_Content_30 = {
    Text = "La bota blindada pisoteó el cadáver de Fernando, acompañada por el tintineo del metal y el agudo sonido de huesos rompiéndose."
  },
  AvgDialog_13056_Content_31 = {
    Text = "...Justo..."
  },
  AvgDialog_13056_Content_33 = {
    Text = "Cada músculo impulsado por la adrenalina, ¡de repente levanta su lanza y carga contra el enemigo!"
  },
  AvgDialog_13056_Content_34 = {
    Text = "<Big:¡No lo toques!>"
  },
  AvgDialog_13056_Content_36 = {Text = "¡Hngh—!"},
  AvgDialog_13056_Content_37 = {
    Text = "La resistencia fue inútil. Su ataque no solo fracasó en conmover al oficial, sino que también dejó su espalda expuesta al explorador."
  },
  AvgDialog_13056_Content_38 = {
    Text = "Este chico es realmente terco. Si se hubiera ido al principio, no habríamos tenido tiempo de perseguirlo, ¿verdad?"
  },
  AvgDialog_13056_Content_39 = {
    Text = "Pequeño hermano, pareces tan resuelto. ¿Estás protegiendo algo?\n¿Está la princesa detrás de la puerta?"
  },
  AvgDialog_13056_Content_4 = {
    Text = "La princesa rara vez sale de su habitación. Apoyándose en la barandilla del corredor del segundo piso, te observa a todos ocupados en el vestíbulo con un aire relajado. Ogier, aquí para una audiencia, está tan nervioso que no sabe dónde colocar los pies."
  },
  AvgDialog_13056_Content_40 = {
    Text = "La sangre brotó de las orejas de Ogier. No podía oír cada palabra, pero aún así captó la pronunciación más crucial."
  },
  AvgDialog_13056_Content_41 = {
    Text = "No... no te vayas..."
  },
  AvgDialog_13056_Content_42 = {
    Text = "La visión comienza a blanquearse por los bordes, y alguna fuerza está tirando de la conciencia fuera del cuerpo juvenil."
  },
  AvgDialog_13056_Content_43 = {
    Text = "Se arrastró hacia adelante, sobre el cadáver de Fernando, pasando por las botas de oficiales y exploradores, hasta que finalmente sus dedos tocaron la pesada puerta de madera."
  },
  AvgDialog_13056_Content_44 = {
    Text = "Cálido al tacto, con un aroma leñoso ligeramente picante, una voz suave y cariñosa a menudo proviene de detrás de la puerta.\nEn este momento, aparte del tic-tac del reloj de agua, no hay ni un solo sonido que provenga de detrás de la puerta."
  },
  AvgDialog_13056_Content_45 = {
    Text = "Dejar... este lugar..."
  },
  AvgDialog_13056_Content_46 = {
    Text = "<Big: Ah——!>"
  },
  AvgDialog_13056_Content_47 = {
    Text = "Esta vez, fue su lanza larga la que penetró profundamente en la carne."
  },
  AvgDialog_13056_Content_48 = {
    Text = "La arma que ha sido burlada por innumerables personas, despreciada por enemigos, pero nunca abandonada por su portador."
  },
  AvgDialog_13056_Content_49 = {
    Text = "La lanza atravesó su cuerpo, clavándolo en la puerta, dejándolo incapaz de moverse."
  },
  AvgDialog_13056_Content_5 = {
    Text = "No soy un caballero de ducado... ¡Rápido, escóndete!"
  },
  AvgDialog_13056_Content_50 = {
    Text = "Ay—no seas tan cruel.\n¿Qué pasará si la \"Princesa Bruja\" nos lanza una maldición por atormentar a su caballero así?"
  },
  AvgDialog_13056_Content_51 = {
    Text = "¿Una bruja? Ridículo."
  },
  AvgDialog_13056_Content_52 = {
    Text = "<Small:@1Princesa... no...>"
  },
  AvgDialog_13056_Content_53 = {
    Text = "Ogier abrió la boca, el nombre de la princesa en la punta de su lengua, pero simplemente no podía traerse a sí mismo a decirlo."
  },
  AvgDialog_13056_Content_54 = {
    Text = "<Small:@1...>"
  },
  AvgDialog_13056_Content_55 = {
    Text = "Él escuchó el sonido del agua fluyendo. ¿Se había volcado el reloj de agua? ¿Significaba eso...@1 que la princesa aún estaba viva?"
  },
  AvgDialog_13056_Content_56 = {
    Text = "<Small:No... no... no entres...>"
  },
  AvgDialog_13056_Content_57 = {
    Text = "Suficiente... Ogier... Gracias..."
  },
  AvgDialog_13056_Content_58 = {
    Text = "Gracias... mi..."
  },
  AvgDialog_13056_Content_59 = {
    Text = "Corrientes negras primero se filtraron bajo la puerta, mezclándose con la sangre de Ogier, como lágrimas derramadas por alguien."
  },
  AvgDialog_13056_Content_6 = {
    Text = "¡Espera! ¿Y tú?!"
  },
  AvgDialog_13056_Content_60 = {
    Text = "Luego, una ola masiva, como una inundación, estalló a través de las grietas de la puerta, rugiendo y surgiendo, engullendo instantáneamente el palacio."
  },
  AvgDialog_13056_Content_61 = {
    Text = "<Shake:Ugh—Ugh!>"
  },
  AvgDialog_13056_Content_62 = {
    Text = "La plaga, invisible para las personas comunes, pasó sobre los dos mientras una marea negra inundaba sus sentidos y los ahogaba en el aire."
  },
  AvgDialog_13056_Content_63 = {
    Text = "<Shake: Maldita sea, es una maldición—>"
  },
  AvgDialog_13056_Content_65 = {
    Text = "¿Guardián? ¿Despierta, Guardián? %player%?"
  },
  AvgDialog_13056_Content_66 = {Text = "¡Ogier!"},
  AvgDialog_13056_Content_67 = {
    Text = "¿Teniendo una pesadilla? Mírate más de cerca. ¿Quién soy yo?"
  },
  AvgDialog_13056_Content_68 = {
    Text = "...¿Muñeca? ¿Qué haces en mi habitación?"
  },
  AvgDialog_13056_Content_69 = {
    Text = "No me importa el contenido de tu pesadilla, pero anoche tus ondas espirituales estaban activas como si estuvieran bailando."
  },
  AvgDialog_13056_Content_7 = {
    Text = "Ogier te empuja con fuerza, forzándote a meterte bajo la mesa baja.\nTu visión gira, y todo lo que puedes ver es la lujosa alfombra persa rizada en los bordes debido a las llamas."
  },
  AvgDialog_13056_Content_70 = {
    Text = "Los Despertadores vinculados a ti, incluido yo, han sentido más o menos algo anormal."
  },
  AvgDialog_13056_Content_71 = {
    Text = "¿Anoche? ...Solo ha pasado una noche. ¿Realmente pudo haber sido solo un sueño?"
  },
  AvgDialog_13056_Content_72 = {
    Text = "Describes todo en el absurdo sueño a la Muñeca.\nPrincesas, caballeros, plagas..."
  },
  AvgDialog_13056_Content_73 = {
    Text = "Entre los Investigadores vinculados a los Despertadores, los casos de resonancia de memoria y emoción son raros. Pero lo que describiste... nunca lo había oído antes."
  },
  AvgDialog_13056_Content_74 = {
    Text = "Parece que esta \"entrada de sueño\" no te ha causado más efectos. Continuaré monitoreando de cerca tu forma de onda mental."
  },
  AvgDialog_13056_Content_75 = {
    Text = "...Quizás, ¿quieras conocer a Ogier ahora?"
  },
  AvgDialog_13056_Content_76 = {
    Text = "La sensación de ser devorado por D-baba era demasiado real. La luz del sol de la mañana calentaba las mantas, pero el cuerpo se sentía como si hubiera caído en un abismo helado."
  },
  AvgDialog_13056_Content_77 = {
    Text = "Ogier... Sí, he arreglado más entrenamiento con él hoy..."
  },
  AvgDialog_13056_Content_78 = {
    Text = "Campo de Entrenamiento de la Universidad Mythag\nMañana"
  },
  AvgDialog_13056_Content_79 = {
    Text = "Vaya—No, no, no, ¡voy a morir—!"
  },
  AvgDialog_13056_Content_8 = {
    Text = "¿Es solo este niño? ¿Hemos llegado al lugar correcto?"
  },
  AvgDialog_13056_Content_80 = {
    Text = "Ten piedad, ten piedad de esta pobre periodista, Sir Ogier—"
  },
  AvgDialog_13056_Content_81 = {
    Text = "Señorita Hannah, aguanta un poco más. Solo queda una vuelta.\n¡Definitivamente pasarás esta prueba de condición física!"
  },
  AvgDialog_13056_Content_82 = {
    Text = "Boohoo... Está bien..."
  },
  AvgDialog_13056_Content_83 = {
    Text = "La corredor del campus, con sacos de arena atados a sus pantorrillas, estaba llorando mientras corría alrededor del campo de entrenamiento.\nOgier corría a su lado, animándola y manteniendo el ritmo sin romper a sudar."
  },
  AvgDialog_13056_Content_84 = {Text = "Ogier"},
  AvgDialog_13056_Content_85 = {
    Text = "¡Guardián!"
  },
  AvgDialog_13056_Content_86 = {
    Text = "Él asignó la supervisión de las tareas de Hannah a otro personal y corrió hacia ti."
  },
  AvgDialog_13056_Content_87 = {
    Text = "¿No dijiste que nuestro entrenamiento comenzaba en la tarde? ¿Por qué estás aquí tan temprano?"
  },
  AvgDialog_13056_Content_88 = {
    Text = "Él y los otros estudiantes, los Despertadores, han estado en el campo de entrenamiento toda la mañana, sin embargo, no muestran signos de fatiga, mirándote con reverencia y energía."
  },
  AvgDialog_13056_Content_89 = {Text = "Yo..."},
  AvgDialog_13056_Content_9 = {
    Text = "¡Eso es correcto, está claramente marcado en el mapa estratégico - este es el área de las mujeres."
  },
  AvgDialog_13056_Content_90 = {
    Text = "... Después del entrenamiento de Hannah, exploremos el centro de la ciudad de Londinium."
  },
  AvgDialog_13056_Content_91 = {Text = "Huh?"},
  AvgDialog_13056_Content_92 = {
    Text = "Ogier claramente no esperaba que sugerieras repentinamente tomar un descanso, y tú tampoco."
  },
  AvgDialog_13056_Content_93 = {
    Text = "Master, por favor, permíteme negarme. La crisis de Disolución es inminente. Yo... no estoy listo aún."
  },
  AvgDialog_13056_Content_94 = {
    Text = "En lugar de entregarme al ocio, deseo concentrarme más en refinar mis habilidades en artes marciales."
  },
  AvgDialog_13056_Content_95 = {
    Text = "Pongámoslo de otra manera."
  },
  AvgDialog_13056_Content_96 = {
    Text = "De repente, me vino a la mente esa tarde que pasé con él en los Caballeros. Los recuerdos que pensaste que se desvanecerían con el sueño resurgieron."
  },
  AvgDialog_13056_Content_97 = {
    Text = "Ahora es el momento de cumplir tu deseo, Señor Caballero."
  },
  AvgDialog_13056_Content_98 = {Text = "¡Ah!"},
  AvgDialog_13056_Content_99 = {
    Text = "¿Cómo... ¿Cómo supiste eso?!"
  },
  AvgDialog_130571_Content_1 = {
    Text = "¡Bang!——————"
  },
  AvgDialog_130571_Content_10 = {
    Text = "Ah, ah... Bola de carbón, lo siento... Mosk, me agarró."
  },
  AvgDialog_130571_Content_11 = {
    Text = "No pasa nada, ¿Mosk, por qué entraste de repente?"
  },
  AvgDialog_130571_Content_12 = {
    Text = "¡Ah! ¡Mosk, calor! ¡Abrazar la bola de carbón, se siente bien!"
  },
  AvgDialog_130571_Content_13 = {
    Text = "Mosk, extraño, porque ya no hace frío."
  },
  AvgDialog_130571_Content_14 = {
    Text = "Pero, hace calor, hace calor..."
  },
  AvgDialog_130571_Content_15 = {
    Text = "(¿Qué pasa? ¿Acaso es la influencia del Río Sagrado?)"
  },
  AvgDialog_130571_Content_16 = {
    Text = "Mosk, no sé..."
  },
  AvgDialog_130571_Content_17 = {
    Text = "La mirada de Mosk se vuelve cada vez más turbia, sus delgados dedos se deslizan entre las costuras de tu ropa, acariciando suavemente tu piel."
  },
  AvgDialog_130571_Content_18 = {
    Text = "Eres muy familiar con esta sensación, en ese sueño, la \"Bola de carbón\" de vez en cuando disfrutará de este servicio de acariciar en los brazos de Mosk."
  },
  AvgDialog_130571_Content_19 = {
    Text = "Bola de carbón, abrazar, calma~"
  },
  AvgDialog_130571_Content_2 = {
    Text = "Bola de carbón, abrazo——"
  },
  AvgDialog_130571_Content_20 = {
    Text = "Bola de carbón, olor, huele bien~"
  },
  AvgDialog_130571_Content_21 = {
    Text = "Mosk huele suavemente sobre ti. No estás seguro si es el aroma residual en tu cuerpo o si tu singularidad ha calmado a Mosk."
  },
  AvgDialog_130571_Content_22 = {
    Text = "Pero entiendes que no puedes dejar que Mosk continúe así."
  },
  AvgDialog_130571_Content_23 = {
    Text = "El suelo es muy duro, tu cintura protesta, extraña la cama suave."
  },
  AvgDialog_130571_Content_24 = {
    Text = "Entonces, abrázame esta noche y durmamos juntos, ¿vale?"
  },
  AvgDialog_130571_Content_25 = {
    Text = "¡Sí! ¡Bola de carbón, me gusta! ¡Quiero abrazar!"
  },
  AvgDialog_130571_Content_26 = {
    Text = "Abrazando una bola de carbón, duerme, duerme~"
  },
  AvgDialog_130571_Content_27 = {
    Text = "Te tumbaste suavemente con Mosk en la suave cama, abrazados el uno al otro, mirándose a los ojos como lo hacían en el barco."
  },
  AvgDialog_130571_Content_28 = {
    Text = "Mosk, ya no hace calor~ Mosk, ¡qué cómodo~!"
  },
  AvgDialog_130571_Content_29 = {
    Text = "Buenas noches...zzz...Bola de carbón...zzz"
  },
  AvgDialog_130571_Content_3 = {
    Text = "¿Mosk, Mosk?"
  },
  AvgDialog_130571_Content_4 = {
    Text = "Mosk de repente entró en la habitación con energía, abrazándote la cintura con ambas manos, su largo cabello plateado frotándose constantemente contra tu pecho."
  },
  AvgDialog_130571_Content_5 = {
    Text = "Sueltas un silencioso suspiro de alivio. Parece que tuvo la previsión de retraer el 'objeto horrífico' de su mano izquierda, evitándote el riesgo de un mordisco accidental."
  },
  AvgDialog_130571_Content_6 = {
    Text = "Bola de carbón, cómodo——"
  },
  AvgDialog_130571_Content_7 = {
    Text = "Mosk, espera, espera un momento, ah——"
  },
  AvgDialog_130571_Content_8 = {Text = "Dong."},
  AvgDialog_130571_Content_9 = {
    Text = "Lamentablemente, como pensabas, Mosk no controló su fuerza y ambos cayeron al suelo."
  },
  AvgDialog_131200_Content_1 = {
    Text = "Esclavitud suave"
  },
  AvgDialog_131200_Content_10 = {
    Text = "Arachne acarició la mitad restante de la cara de la niña. Mientras ella cerraba suavemente los ojos de la niña, el enorme pilar de luz detrás de ella emitió un suave resplandor."
  },
  AvgDialog_131200_Content_11 = {
    Text = "Arachne extendió la mano. Un poco de ceniza que quedaba en el farol danzaba como si fuera arena arrastrada por el viento, girando y fluyendo alrededor de sus delgados dedos, luego se esparció por el suelo."
  },
  AvgDialog_131200_Content_12 = {
    Text = "Los restos de la Ceniza de Dimensión... nuestra percepción no se equivoca, aquí solía ser el lugar donde Nefruri escondía la ceniza, pero ahora, la ceniza ha sido llevada por ella."
  },
  AvgDialog_131200_Content_13 = {
    Text = "Llevarse la ceniza, matar el objeto secreto, ¿qué quiere realmente Nefruri...?"
  },
  AvgDialog_131200_Content_14 = {Text = "¿Hm?"},
  AvgDialog_131200_Content_15 = {
    Text = "Parece que algo la ha asustado, Arachne levantó la cabeza y, a través de la ventana de vidrio de colores con el símbolo de la linterna, miró hacia la dirección del andén no muy lejos."
  },
  AvgDialog_131200_Content_16 = {
    Text = "¿Arachne? ¿Qué te pasa?"
  },
  AvgDialog_131200_Content_17 = {
    Text = "Mi cuerpo principal... ya no puedo sentir su presencia."
  },
  AvgDialog_131200_Content_18 = {Text = "¡!!!"},
  AvgDialog_131200_Content_19 = {
    Text = "¿Quieres decir que abandonó el teatro?"
  },
  AvgDialog_131200_Content_2 = {
    Text = "Dedos, espinillas, ojos, costillas, cráneo... Ante ti yace una muñeca querida despedazada por su ama, sus piezas abandonadas para ahogarse en el fango y la sangre."
  },
  AvgDialog_131200_Content_20 = {
    Text = "Mientras cazábamos a las marionetas, mi cuerpo principal estaba purgando a los Servidores del Abismo por toda la ciudad. Después de encontrar \"Recordar\", vino a esta iglesia para reunirse con nosotros."
  },
  AvgDialog_131200_Content_21 = {
    Text = "Estaba tan cerca... pero ahora, su luz se ha desvanecido."
  },
  AvgDialog_131200_Content_22 = {
    Text = "¿Le pasó algo? Pero \"Recordar\" acaba de morir... cómo..."
  },
  AvgDialog_131200_Content_23 = {
    Text = "No conozco los detalles. Pero antes de desvanecerse, tocó la telaraña para enviar un último mensaje. Aparte de la orden de regresar, dejó una sola palabra."
  },
  AvgDialog_131200_Content_24 = {
    Text = "\"Éxtasis.\""
  },
  AvgDialog_131200_Content_25 = {
    Text = "¿Éxtasis...?"
  },
  AvgDialog_131200_Content_26 = {
    Text = "El detestable rostro sonriente de N destella ante ti."
  },
  AvgDialog_131200_Content_27 = {
    Text = "No lo entiendo. Compartes los mismos recuerdos—debes saber a qué se refería."
  },
  AvgDialog_131200_Content_28 = {
    Text = "Arachne sacudió levemente la cabeza."
  },
  AvgDialog_131200_Content_29 = {
    Text = "Tu destino es una mariposa que no me atrevo a tocar; cualquier explicación causaría ondas inconmensurables."
  },
  AvgDialog_131200_Content_3 = {
    Text = "\"Recordar\"..."
  },
  AvgDialog_131200_Content_30 = {
    Text = "Pero ten esto presente: en tu futuro inmediato, \"Éxtasis\" es una llave. Abrirá la cerradura secreta que tienes ante ti."
  },
  AvgDialog_131200_Content_31 = {
    Text = "¿Mi... futuro? ¡¿Quieres decir que ahora puedes ver mi Hilo del Destino?!"
  },
  AvgDialog_131200_Content_32 = {
    Text = "Le sostienes la mirada. Dentro de esa sonrisa gentil, ves la autoridad innegable del Destino."
  },
  AvgDialog_131200_Content_33 = {
    Text = "...Sin importar lo que pase, confía en mí. Y confía en ti."
  },
  AvgDialog_131200_Content_34 = {
    Text = "Regresa al Teatro del destino. La llave y la cerradura te esperan allí, %player%."
  },
  AvgDialog_131200_Content_35 = {Text = "Pero..."},
  AvgDialog_131200_Content_36 = {
    Text = "La voz tranquila de Arachne era como el cálido atardecer de un día de otoño. Su figura se convirtió en un puñado de telaraña, desapareciendo en la luz silenciosa de la iglesia."
  },
  AvgDialog_131200_Content_37 = {
    Text = "Bajo el resplandor caleidoscópico de los vitrales, solo ascuas dimensionales flotan sobre la sangre y los miembros cercenados."
  },
  AvgDialog_131200_Content_38 = {
    Text = "\"Éxtasis\"..."
  },
  AvgDialog_131200_Content_39 = {
    Text = "Murmuras la palabra, luego te vuelves hacia los restos de \"Recordar\"."
  },
  AvgDialog_131200_Content_4 = {
    Text = "Recoges con delicadeza los restos de la chica. Los fluidos pegajosos y la sangre manchan tu ropa mientras sostienes sus miembros cercenados."
  },
  AvgDialog_131200_Content_40 = {
    Text = "Bañados en fluido turbio y luz sagrada, los fragmentos parecen fusionarse con la propia catedral sagrada."
  },
  AvgDialog_131200_Content_41 = {Text = "..."},
  AvgDialog_131200_Content_42 = {
    Text = "El sendero de seda tiembla. Al pisar el escenario, todas las marionetas se detienen a mitad de la actuación."
  },
  AvgDialog_131200_Content_43 = {
    Text = "Innumerables ojos de todas las dimensiones se vuelven hacia ti, llenos de curiosidad, júbilo y una reverencia aterradora."
  },
  AvgDialog_131200_Content_44 = {
    Text = "Es una gran ceremonia de bienvenida silenciosa. Los actores se han convertido en público, y la única espectadora se ha convertido en la estrella."
  },
  AvgDialog_131200_Content_45 = {
    Text = "Quizás no sea una buena idea escuchar a Arachne..."
  },
  AvgDialog_131200_Content_46 = {
    Text = "Aprietas con fuerza la Llave de plata y caminas sola a través del inquietante silencio."
  },
  AvgDialog_131200_Content_47 = {
    Text = "La nueva ama del teatro te esperaba, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131200_Content_48 = {
    Text = "Las sombras convergen en el escenario elevado. Instintivamente, te lanzas hacia atrás y alzas la Llave de plata."
  },
  AvgDialog_131200_Content_49 = {
    Text = "¿¡Nueva ama!?"
  },
  AvgDialog_131200_Content_5 = {
    Text = "Quizás... quizás haya una forma de salvarla. El poder de los plásmidos... una corrección del Destino..."
  },
  AvgDialog_131200_Content_50 = {
    Text = "Bienvenida de vuelta al teatro, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131200_Content_51 = {
    Text = "Arachne, tú..."
  },
  AvgDialog_131200_Content_52 = {
    Text = "Lo siento, pero nuestra nueva historia requiere tu participación."
  },
  AvgDialog_131200_Content_53 = {
    Text = "La telaraña se estremece. La ama del teatro se acerca con pasos pausados, su voz aún tan cálida como el crepúsculo vespertino."
  },
  AvgDialog_131200_Content_54 = {
    Text = "A tu alrededor, las marionetas —indistinguibles de las Doncellas de la Araña Fría— se giran y saltan hacia ti al unísono."
  },
  AvgDialog_131200_Content_55 = {Text = "¡!!!"},
  AvgDialog_131200_Content_6 = {
    Text = "Nefruri destruyó sus hilos... su destino ha terminado, Guardián {Male=señor, Female=señorita}."
  },
  AvgDialog_131200_Content_7 = {
    Text = "El zumbido de la rueca de Arachne permanece sereno y distante."
  },
  AvgDialog_131200_Content_8 = {
    Text = "\"Recordar\" también ha muerto... ¿eso significa...?"
  },
  AvgDialog_131200_Content_9 = {
    Text = "Nefruri, ya tiene el poder de cambiar el destino de este escenario."
  },
  AvgDialog_131201_Content_1 = {
    Text = "Uff... estos servidores de Nefruri realmente son difíciles de tratar..."
  },
  AvgDialog_131201_Content_10 = {
    Text = "En veinte días, comenzará a estudiar en serio los secretos de ese libro. A partir de ese momento, este escenario seguirá el camino de todos los demás, descendiendo inevitablemente hacia la destrucción total."
  },
  AvgDialog_131201_Content_100 = {
    Text = "El archiduque y su esposa van sentados en la parte trasera de su automóvil descapotable, admirando la antigua ciudad. La gente persigue el vehículo, corriendo de cabeza hacia el destino que fue escrito para ellos hace mucho tiempo."
  },
  AvgDialog_131201_Content_11 = {
    Text = "Recuerdos de este mundo —nuevos y extrañamente familiares— inundan tu mente. Nunca habías visto un lugar tan vibrante y próspero."
  },
  AvgDialog_131201_Content_12 = {
    Text = "Has visto demasiado. Las imágenes de los paisajes desolados y asfixiados por la ceniza causados por la Fusión sobrescriben fácilmente esta prosperidad, llenando tu mente con visiones de decadencia."
  },
  AvgDialog_131201_Content_13 = {
    Text = "Arachne extendió la mano y acarició suavemente la luz del amanecer que caía en la entrada del callejón. Ella estaba lamentando otro mundo que estaba a punto de morir."
  },
  AvgDialog_131201_Content_14 = {
    Text = "Un mundo inadvertido por los dioses... Nunca imaginé siquiera que algo así fuera posible."
  },
  AvgDialog_131201_Content_15 = {
    Text = "¿Aún tenemos oportunidad de cambiarlo?"
  },
  AvgDialog_131201_Content_16 = {
    Text = "Precisamente por eso estamos aquí."
  },
  AvgDialog_131201_Content_17 = {
    Text = "Dime. ¿Qué necesito hacer?"
  },
  AvgDialog_131201_Content_18 = {
    Text = "¡Espera!......"
  },
  AvgDialog_131201_Content_19 = {
    Text = "Los has notado, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131201_Content_2 = {
    Text = "Te apoyas contra la pared húmeda de un callejón apartado, jadeando en busca de aire."
  },
  AvgDialog_131201_Content_20 = {
    Text = "Fuera del callejón, un grupo de individuos con frecuencias espirituales inquietantemente anómalas se acerca a vuestra posición."
  },
  AvgDialog_131201_Content_21 = {
    Text = "Detrás de ti, encima de ti, delante de ti... cada vez más enemigos se manifiestan en tu percepción."
  },
  AvgDialog_131201_Content_22 = {
    Text = "¡Estamos rodeados!"
  },
  AvgDialog_131201_Content_23 = {
    Text = "Desde que pisamos este escenario, hay estado trabajando para reparar el destino manipulado. Pero corregir los destinos de tanta gente no es tarea sencilla."
  },
  AvgDialog_131201_Content_24 = {
    Text = "Nefruri dejó a estas personas para obstaculizar mi reparación del destino."
  },
  AvgDialog_131201_Content_25 = {
    Text = "Quizá haya otra forma."
  },
  AvgDialog_131201_Content_26 = {
    Text = "Arachne, hoy la Restauración Nacional está tramando el asesinato aquí, yo soy uno de los ejecutores."
  },
  AvgDialog_131201_Content_27 = {
    Text = "Este mundo arderá porque ese príncipe estudia ese grimorio. Si logro el asesinato, ¡quizá pueda detenerlo todo antes de que empiece!"
  },
  AvgDialog_131201_Content_28 = {
    Text = "Eso no es exactamente lo correc..."
  },
  AvgDialog_131201_Content_29 = {
    Text = "¡Ahí están! ¡Atrapadlos!"
  },
  AvgDialog_131201_Content_3 = {
    Text = "No has visto a Arachne corriendo, ella está de pie a tu lado con calma, como si estuviera destinada a estar en este momento en este callejón."
  },
  AvgDialog_131201_Content_30 = {
    Text = "Arachne toca las cuerdas del instrumento, preparando al servidor mutante congelado en la puerta de la calle, como si fuera una estatua."
  },
  AvgDialog_131201_Content_31 = {
    Text = "El lejano estruendo de trompetas y saxofones flota en el aire, acompañado por el retumbar grave y constante de motores que se aproximan."
  },
  AvgDialog_131201_Content_32 = {
    Text = "El complot ha sido descubierto; los otros asesinos no podrán llevarlo a cabo. El príncipe está justo ahí. ¡Si no actúo ahora, perderemos nuestra oportunidad!"
  },
  AvgDialog_131201_Content_33 = {
    Text = "Arachne te miró con ojos ansiosos y, tras dudar un momento, asintió levemente."
  },
  AvgDialog_131201_Content_34 = {
    Text = "Ya que las corrientes del Destino nos han traído aquí... quizá tomar una decisión por este mundo es exactamente lo que estás destinado a hacer."
  },
  AvgDialog_131201_Content_35 = {
    Text = "Ve. Haz lo que debas, {Male=Mr.,Female=Miss} Guardián. La verdad del Destino te será revelada aquí."
  },
  AvgDialog_131201_Content_36 = {
    Text = "No tienes tiempo para pensar detenidamente en las palabras de Arachne, asentiste con la cabeza y, con la ayuda de Arachne, saliste corriendo del callejón para unirte a la multitud tumultuosa."
  },
  AvgDialog_131201_Content_37 = {
    Text = "¿Ese es el Duque Flaviano? El heredero del imperio... Me pregunto cuánto cuesta siquiera un coche así."
  },
  AvgDialog_131201_Content_38 = {
    Text = "¡Bah! ¡Bastardo hijo de un ladrón! ¡Cada centavo que gasta fue arrancado de nuestra sangre y sudor!"
  },
  AvgDialog_131201_Content_39 = {
    Text = "¡Si no fuera un lisiado, habría muerto en el campo de batalla cargando contra esos bandidos!"
  },
  AvgDialog_131201_Content_4 = {
    Text = "Llegó a tales extremos... ¿qué es lo que realmente intenta conseguir?"
  },
  AvgDialog_131201_Content_40 = {
    Text = "¡Shh! ¡Las calles están plagadas de Guardias Imperiales! ¡¿Acaso quieres morir?!"
  },
  AvgDialog_131201_Content_41 = {Text = "..."},
  AvgDialog_131201_Content_42 = {
    Text = "Te abres paso a codazos entre la densa muchedumbre hasta que finalmente llegas al bordillo, justo cuando un reluciente descapotable nuevo pasa lentamente."
  },
  AvgDialog_131201_Content_43 = {
    Text = "El príncipe heredero, un hombre que ronda los sesenta, va sentado en la parte trasera con su esposa. Saludan con gracia a la multitud mientras señalan la arquitectura histórica de Hewatz."
  },
  AvgDialog_131201_Content_44 = {
    Text = "Incluso con tus recuerdos borrosos, conoces demasiado bien el profundo sufrimiento que esta casa real ha infligido sobre la tierra."
  },
  AvgDialog_131201_Content_45 = {
    Text = "Temiendo las consecuencias cósmicas de usar tu verdadero poder, apartas la mano de la Llave de plata. En su lugar, sacas la pistola que se supone que debería estar ahí y te acercas al vehículo que avanza lentamente."
  },
  AvgDialog_131201_Content_46 = {
    Text = "¡Oye! ¡Tú, estudiante! ¡Atrás!"
  },
  AvgDialog_131201_Content_47 = {
    Text = "Perdóneme, Su Alteza. Pero ya que he subido al escenario, ¡tengo que jugar este papel hasta el final!"
  },
  AvgDialog_131201_Content_48 = {
    Text = "¡BANG! ¡BANG BANG!"
  },
  AvgDialog_131201_Content_49 = {
    Text = "En medio de las caóticas calles, el orgulloso heredero imperial se encuentra sorprendentemente vulnerable. Recurriendo a tu riguroso entrenamiento, acortas la distancia con facilidad y aprietas el gatillo."
  },
  AvgDialog_131201_Content_5 = {
    Text = "Nefruri dejó un prólogo. En esta vasta Red del destino, contaminó uno de los hilos."
  },
  AvgDialog_131201_Content_50 = {
    Text = "Cuando tres balas perforan el pecho del Archiduque con precisión letal, el mundo entero se detiene en seco."
  },
  AvgDialog_131201_Content_51 = {
    Text = "La agonía del Archiduque, el shock de la princesa, los guardias a medio paso... todo se congela en una grotesca y vívida pintura al óleo."
  },
  AvgDialog_131201_Content_52 = {
    Text = "!!! Esto es..."
  },
  AvgDialog_131201_Content_53 = {
    Text = "Tras un instante de silencio, los colores de la pintura comienzan a sangrar y escurrir. El tiempo, el espacio y la gravedad colapsan en un frenesí caótico. Tu cuerpo se siente como si estuviera siendo desgarrado mientras un huracán de imágenes destella ante tus ojos."
  },
  AvgDialog_131201_Content_54 = {
    Text = "Un gran funeral. La furia de un monarca. Guerra. Cañones. Muerte. El estruendo de los cuernos de guerra y los gritos de los civiles. Buitres descendiendo sobre los campos carmesí de Verdún para darse un festín con cuatrocientos mil restos destrozados."
  },
  AvgDialog_131201_Content_55 = {
    Text = "La caída de imperios, tierras desgarradas, reyes en el exilio, y el grimorio... abriéndose una vez más."
  },
  AvgDialog_131201_Content_56 = {
    Text = "Un líquido negro viscoso inunda tu visión. La tragedia familiar se repite de nuevo: oscuridad absoluta y agonía, una corrosión que se filtra en cada una de las células de tu ser."
  },
  AvgDialog_131201_Content_57 = {
    Text = "No te preocupes, Guardián de {Male=Mr.,Female=Miss}. Estás a salvo ahora."
  },
  AvgDialog_131201_Content_58 = {
    Text = "Una mano se posa sobre tu hombro. Los caóticos colores sangrantes y la oscuridad sin límites se desvanecen."
  },
  AvgDialog_131201_Content_59 = {
    Text = "Abres los ojos de golpe. El café está tan tranquilo como siempre; la pistola Browning ha desaparecido de tu mano, y la Sachertorte recién servida reposa ante ti, desprendiendo un aroma irresistible."
  },
  AvgDialog_131201_Content_6 = {
    Text = "En esta línea temporal corrompida, el príncipe heredero de Phio-Garia descubrió cierto libro hace dos meses."
  },
  AvgDialog_131201_Content_60 = {
    Text = "Arachne... ¿qué... está pasando?! Nosotros..."
  },
  AvgDialog_131201_Content_61 = {
    Text = "No te alarmes. Simplemente hemos regresado al momento en que entramos por primera vez al café. Por el lado bueno, conseguimos un café gratis."
  },
  AvgDialog_131201_Content_62 = {
    Text = "Arachne levantó la taza de café y sonrió al dar un sorbo. En el líquido marrón se reflejaba tu rostro atónito."
  },
  AvgDialog_131201_Content_63 = {
    Text = "Los Hilos del destino no son para que tus ojos los perciban. Cuando un actor ajeno al escenario intenta alterar por la fuerza el destino de este mundo, inevitablemente se pierde en la red."
  },
  AvgDialog_131201_Content_64 = {
    Text = "Pasado y futuro, los incontables destinos de este escenario entrelazándose ante tus ojos... esa es la verdadera cara de la Red del destino."
  },
  AvgDialog_131201_Content_65 = {
    Text = "El futuro... ¿estás diciendo que todo lo que vi fue real? Las guerras, los millones de muertos... ¿realmente causé todo eso?"
  },
  AvgDialog_131201_Content_66 = {
    Text = "El Destino te permitió presenciarlo. Tras el asesinato del archiduque, ese era en efecto el camino que el mundo debía tomar. Pero quédate tranquilo, {Male=Mr.,Female=Miss} Guardián. Ya he retejido el destino de este escenario."
  },
  AvgDialog_131201_Content_67 = {
    Text = "Miraste por la ventana. Seguía siendo una multitud bulliciosa, pero aquellos ciudadanos y policías afectados por Nefruri ya habían desaparecido."
  },
  AvgDialog_131201_Content_68 = {
    Text = "Si lo hubiera llevado a cabo... si tú no hubieras reparado el daño..."
  },
  AvgDialog_131201_Content_69 = {
    Text = "Dentro de un mes, la muerte de ese príncipe heredero habría desencadenado la mayor guerra de la historia. Ocho imperios habrían sido arrastrados al abismo y veinte millones de almas habrían perecido."
  },
  AvgDialog_131201_Content_7 = {
    Text = "Un grimorio de hechicería prohibida, capaz de invocar a cierta deidad que no pertenece a esta dimensión."
  },
  AvgDialog_131201_Content_70 = {
    Text = "El suelo mismo bajo nuestros pies se habría convertido en cenizas. De todas las personas sentadas a nuestro alrededor en este café, ni una sola habría sobrevivido."
  },
  AvgDialog_131201_Content_71 = {
    Text = "Arachne agitaba la taza de café, mirando el bullicioso paisaje urbano por la ventana. Hablaba con calma, como si estuviera presentando un postre de lo más común."
  },
  AvgDialog_131201_Content_72 = {
    Text = "El animado murmullo de la calle llega a tus oídos, una melodía de paz y prosperidad que ahora se siente increíblemente frágil."
  },
  AvgDialog_131201_Content_73 = {
    Text = "¿Y qué hay de la Fusión? ¿Por qué matar al príncipe seguía conduciendo al fin del mundo?"
  },
  AvgDialog_131201_Content_74 = {
    Text = "En aquella gran guerra, el imperio fue derrotado. El rey no tuvo más remedio que aceptar el cruel veredicto del Destino... hasta que encontró un nuevo camino."
  },
  AvgDialog_131201_Content_75 = {
    Text = "Hechicería de más allá de este mundo, una deidad que trasciende todo poder conocido... para un padre que ha perdido a su hijo y un emperador que ha perdido su nación, ¿podría haber algo más tentador?"
  },
  AvgDialog_131201_Content_76 = {
    Text = "Las suaves palabras de Arachne te hicieron estremecer. El peso de dos mil millones de vidas te aplasta como si fuera algo tangible."
  },
  AvgDialog_131201_Content_77 = {
    Text = "<Shake:Nunca imaginé que asesinar a un príncipe desembocaría en esto... Creía que estaba ayudando...>"
  },
  AvgDialog_131201_Content_78 = {
    Text = "El Destino te obligó a tomar esa decisión para que finalmente pudieras verlo tal como es. No puedes ver los hilos en sí, pero ahora comprendes las intrincadas formas en que están tejidos."
  },
  AvgDialog_131201_Content_79 = {
    Text = "Estos hilos forman una vasta red. El más leve temblor en un solo hilo puede hacer que toda la estructura se derrumbe."
  },
  AvgDialog_131201_Content_8 = {
    Text = "Arachne levantó la cabeza y miró hacia esos hilos que no puedes ver."
  },
  AvgDialog_131201_Content_80 = {
    Text = "Esto es el Destino, en toda su terrible complejidad."
  },
  AvgDialog_131201_Content_81 = {
    Text = "Respiras hondo, intentando calmar tu corazón, que aún golpea contra tus costillas por el terror persistente."
  },
  AvgDialog_131201_Content_82 = {
    Text = "Al menos... al menos detuviste la guerra..."
  },
  AvgDialog_131201_Content_83 = {
    Text = "No detuve la guerra, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131201_Content_84 = {
    Text = "Arachne sacudió la cabeza suavemente."
  },
  AvgDialog_131201_Content_85 = {
    Text = "En el nuevo destino que he tejido, el emperador presenciará apenas una fracción de los milagros contenidos en ese grimorio. Ese atisbo de poder se convertirá en los cimientos mismos sobre los que construirá su guerra."
  },
  AvgDialog_131201_Content_86 = {
    Text = "El rey y sus aliados desatarán un conflicto a una escala aún mayor, arrastrando imperios de ultramar a la contienda."
  },
  AvgDialog_131201_Content_87 = {
    Text = "El número de personas que morirán en esta versión de la historia será cuatro veces mayor que antes."
  },
  AvgDialog_131201_Content_88 = {
    Text = "Continúa su serena narración, con un tono similar al de una madre contando un cuento para dormir a un niño que no puede conciliar el sueño."
  },
  AvgDialog_131201_Content_89 = {
    Text = "<Shake:Esto... ¿por qué?>"
  },
  AvgDialog_131201_Content_9 = {
    Text = "Este escenario nunca estuvo destinado a conectarse con lo divino. Durante mucho tiempo, podría haberse librado del destino de la Fusión."
  },
  AvgDialog_131201_Content_90 = {
    Text = "Has visto la complejidad de la red. Evitar por la fuerza un evento destinado a ocurrir solo invita a un desenlace mucho más horrífico."
  },
  AvgDialog_131201_Content_91 = {
    Text = "El rey sigue siendo derrotado; el conocimiento limitado de aquel libro no ofrece al imperio ninguna salvación duradera."
  },
  AvgDialog_131201_Content_92 = {
    Text = "Tras este segundo fracaso, la hechicería será descartada como una farsa. Ningún gobernante en este escenario volverá a recurrir a ella."
  },
  AvgDialog_131201_Content_93 = {
    Text = "Sus ojos se dirigirán a otra parte. Depositarán su fe en la ciencia, investigando armas capaces de devorar planetas enteros. Disfrutarán de una breve y tensa paz bajo la sombra de estos armamentos, solo para ser destruidos por las mismas herramientas que crearon."
  },
  AvgDialog_131201_Content_94 = {
    Text = "Este escenario sigue destinado a desvanecerse en algún apocalipsis futuro—ese es su destino ineludible. Pero durante un tiempo, disfrutarán de un período de prosperidad tan hermoso como una obra de arte."
  },
  AvgDialog_131201_Content_95 = {
    Text = "La Mirada de Toguwaibo será mantenida a raya, al menos por un tiempo."
  },
  AvgDialog_131201_Content_96 = {
    Text = "La cuchara de Arachne gira lentamente en la copa, ese vórtice de color marrón oscuro es igual a lo que viste en la Red del destino."
  },
  AvgDialog_131201_Content_97 = {
    Text = "Inclina la cabeza. La luz del sol que entra por la ventana cae sobre ella como un sudario fúnebre."
  },
  AvgDialog_131201_Content_98 = {
    Text = "Luchar, tejer, remendar... y aun así nada cambia realmente. Esto es el Destino, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131201_Content_99 = {
    Text = "El estruendo de trompetas y saxofones se cuela por la ventana, trayendo consigo los vítores y maldiciones de la multitud distante."
  },
  AvgDialog_131202_Content_1 = {Text = "CRAC—"},
  AvgDialog_131202_Content_10 = {
    Text = "¿Creyentes?"
  },
  AvgDialog_131202_Content_11 = {
    Text = "Con túnicas púrpuras... Jamás había... jamás había visto nada igual..."
  },
  AvgDialog_131202_Content_12 = {
    Text = "Ellos... llevaron el \"Recordar\" al altar... <Shake:tos, tos...>"
  },
  AvgDialog_131202_Content_13 = {
    Text = "Calle San Vasily... a una iglesia que les pertenece..."
  },
  AvgDialog_131202_Content_14 = {
    Text = "Hueso y carne tiemblan mientras el anciano lucha por arrancar un último aliento de su cuerpo destrozado."
  },
  AvgDialog_131202_Content_15 = {
    Text = "Él sabía que la señorita Arachne no podía ver los hilos de esas personas. Sabía que era algo que necesitaba hacer."
  },
  AvgDialog_131202_Content_16 = {
    Text = "Señorita... villanos en las sombras nos están cazando... Ella ha corrompido nuestros destinos..."
  },
  AvgDialog_131202_Content_17 = {
    Text = "Se llevaron mi sangre... En esa iglesia, ella realizará su horrible ritual..."
  },
  AvgDialog_131202_Content_18 = {
    Text = "El vengador del destino, bañado en nuestra Sangre... el dios maligno de las sombras está a punto de llegar, todo destino caerá en... total... <Shake:tos, tos, tos...><Big:total Caos...!>"
  },
  AvgDialog_131202_Content_19 = {
    Text = "Sus pupilas se dilatan. Se estremece con un terror frío y primitivo, como si estuviera contemplando un purgatorio más espantoso que su peor pesadilla."
  },
  AvgDialog_131202_Content_2 = {
    Text = "Las arañas se dispersaron, la última figura cayó en la luz plateada, y el amo de la tormenta ya había desaparecido. Tú y Arachne llegaron frente a la figura caída en el centro de la habitación."
  },
  AvgDialog_131202_Content_20 = {
    Text = "Él agarró fuertemente la manga de Arachne, mirando a Arachne con una mirada casi suplicante."
  },
  AvgDialog_131202_Content_21 = {
    Text = "Señorita... aún me descubro llamándola Señorita... Tardó tanto en aprender sus primeras palabras. Tenía al Señor y a la Señora preocupadísimos..."
  },
  AvgDialog_131202_Content_22 = {
    Text = "Cuando por fin habló para despedirse de mí, todos los demás se alegraron... pero yo lo supe. Solo yo supe que aquellas palabras eran un veredicto del que el Destino jamás la dejaría escapar."
  },
  AvgDialog_131202_Content_23 = {
    Text = "Regresé a casa, esperando la llegada de la muerte. No puedo dejar de llorar, no por mí, sino por usted, señorita Arachne..."
  },
  AvgDialog_131202_Content_24 = {
    Text = "Supe entonces... qué pesada maldición estaba destinada a cargar..."
  },
  AvgDialog_131202_Content_25 = {
    Text = "Las lágrimas han dejado huellas en las mejillas surcadas del anciano. Él sostiene temblorosamente la mano de Arachne. A través de la borrosa luz de las lágrimas, ve frente a él a la joven Arachne."
  },
  AvgDialog_131202_Content_26 = {
    Text = "Aquel rostro inocente nunca lloró; simplemente observaba el cielo vacío con curiosidad, sonriendo a destinos que nadie más podía ver."
  },
  AvgDialog_131202_Content_27 = {
    Text = "Señorita Arachne, por favor, cuídela bien, cuídela bien \"Recordar\"... por favor, cuídese bien..."
  },
  AvgDialog_131202_Content_28 = {
    Text = "No... se pierda... en la telaraña..."
  },
  AvgDialog_131202_Content_29 = {
    Text = "La voz de\"Amabilidad\"se había vuelto casi inaudible al final. Cuando su respiración se detuvo, Arachne le cerró suavemente los ojos."
  },
  AvgDialog_131202_Content_3 = {
    Text = "Eres tú..."
  },
  AvgDialog_131202_Content_30 = {
    Text = "\"Descanse ahora, Señor Lawrence...\""
  },
  AvgDialog_131202_Content_31 = {
    Text = "La comisura de los labios de Edgar se curvó levemente. En los últimos momentos de su vida, escuchó una vez más la primera frase que Arachne había pronunciado en esta vida."
  },
  AvgDialog_131202_Content_32 = {
    Text = "No pide nada más."
  },
  AvgDialog_131202_Content_33 = {
    Text = "Usaste los recuerdos de tu propio mayordomo para crear este objeto secreto... no se parece en nada a las otras muñecas que has hecho. ¿Por qué?"
  },
  AvgDialog_131202_Content_34 = {
    Text = "Quizá como homenaje. O quizá... solo buscaba un poco de consuelo."
  },
  AvgDialog_131202_Content_35 = {
    Text = "¿Consuelo?"
  },
  AvgDialog_131202_Content_36 = {
    Text = "Quería decirme a mí misma que seguían conmigo. Que nunca se habían ido de verdad."
  },
  AvgDialog_131202_Content_37 = {
    Text = "Arachne dejó en calma el cuerpo roto del anciano, sin dar más explicaciones, y tú no volviste a preguntar. Sabes que la respuesta te está esperando no muy lejos."
  },
  AvgDialog_131202_Content_38 = {
    Text = "En esta Red del destino, la fuerza de Nefruri está relacionada con ellos. Su muerte hará que Nefruri esté más conectada con la red."
  },
  AvgDialog_131202_Content_39 = {
    Text = "Debemos detenerla antes de que obtenga el poder para desgarrar la telaraña. Eso es lo único que importa ahora, Guardián {Male=Mr.,Female=Miss}."
  },
  AvgDialog_131202_Content_4 = {
    Text = "<Shake:Señorita Arachne... Extranjero... ejem...>"
  },
  AvgDialog_131202_Content_40 = {
    Text = "Las manos de Arachne acarician la cabeza del anciano, tocando ese hilo que casi ya es invisible. En el otro extremo lejano de esta ciudad, el hilo del destino envía un eco débil."
  },
  AvgDialog_131202_Content_41 = {
    Text = "¿El Destino te respondió?"
  },
  AvgDialog_131202_Content_42 = {
    Text = "Arachne asintió. Antes de levantarse, echó un último vistazo al rostro sonriente del anciano."
  },
  AvgDialog_131202_Content_43 = {
    Text = "\"Recordar\" sigue con vida. Y los del Abismo espiral... nos están esperando."
  },
  AvgDialog_131202_Content_5 = {
    Text = "El cuerpo ante ti es una ruina. La mitad de su carne ha sido roída, dejando un amasijo de podredumbre y hueso manchado de sangre."
  },
  AvgDialog_131202_Content_6 = {
    Text = "El anciano tosió fuertemente, logrando apenas sacar unas gotas de sangre que aún no se habían secado. Un hilo invisible estaba en manos de Arachne, como una vela en medio de una tormenta, inestable."
  },
  AvgDialog_131202_Content_7 = {
    Text = "Hay que detener la hemorragia... ¡ayúdame a encontrar algo!"
  },
  AvgDialog_131202_Content_8 = {
    Text = "Ya es tarde... señorita Arachne... ve a salvarla... ve a salvar \"Recordar\"..."
  },
  AvgDialog_131202_Content_9 = {
    Text = "Los creyentes... se la llevaron..."
  },
  AvgDialog_131203_Content_1 = {
    Text = "¡Arachne! ¿Qué estás haciendo?! ¿Esto es lo que llamas... confianza?"
  },
  AvgDialog_131203_Content_10 = {
    Text = "Actuación. Engaño. Manipulación."
  },
  AvgDialog_131203_Content_11 = {
    Text = "\"Éxtasis\", este es tu destino. Sube al escenario, {Male=Mr.,Female=Miss} Guardián. \nEn este escenario, terminarás tu propia historia."
  },
  AvgDialog_131203_Content_12 = {
    Text = "En este escenario, obtendrás lo que tu corazón desea."
  },
  AvgDialog_131203_Content_2 = {
    Text = "William, el compañero mayor... ¡A-Aún se está recuperando de sus heridas!..."
  },
  AvgDialog_131203_Content_3 = {
    Text = "No te preocupes, {Male=Mr.,Female=Miss} Guardián. Él no tiene nada que ver con este hilo del Destino. Lo he teletransportado a un lugar seguro."
  },
  AvgDialog_131203_Content_4 = {
    Text = "Este es un destino del que ninguna de las dos puede escapar, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131203_Content_5 = {
    Text = "Nunca te he mentido. Te estoy llevando a tu propio escenario, donde darás la actuación de tu vida. Una actuación que es enteramente tuya."
  },
  AvgDialog_131203_Content_6 = {
    Text = "Arachne se acerca lentamente a ti. Mirando sus ojos nebulosos, deseas leer en ellos la información que ella no puede transmitirte directamente."
  },
  AvgDialog_131203_Content_7 = {
    Text = "(Una actuación... enteramente mía...)"
  },
  AvgDialog_131203_Content_8 = {
    Text = "Una chispa de inspiración cruza tu mente como una estrella fugaz, solo para desvanecerse en el desorden de tus pensamientos."
  },
  AvgDialog_131203_Content_9 = {
    Text = "Las Doncella de la Araña Fría se dispersaron por los alrededores, sin avanzar más. Arachne levantó suavemente la mano y tocó las cuerdas vacías de la guitarra."
  },
  AvgDialog_131204_Content_1 = {
    Text = "La luz plateada cortó las telarañas como una cuchilla, aprovechando esta oportunidad, avanzaste rápidamente a través de la defensa de las sirvientas y llegaste ante Arachne."
  },
  AvgDialog_131204_Content_10 = {
    Text = "Ella se da la vuelta. Cuando sus hilos se mueven, un impulso involuntario se enciende en tu corazón, obligándote a ponerte en pie."
  },
  AvgDialog_131204_Content_11 = {
    Text = "Estás seguro de que tienes plena autonomía, eres el perfecto portavoz del libre albedrío. Sigues completamente por tu propia voluntad los pasos de Arachne, avanzando hacia el final del camino de la telaraña con un ritmo y un paso que son totalmente congruentes con ella."
  },
  AvgDialog_131204_Content_12 = {Text = "..."},
  AvgDialog_131204_Content_13 = {
    Text = "¡Oh, bienvenido! {Male=Mr.,Female=Miss} %player%, ¡mi estimado invitado! Tus pasos nunca habían sonado tan musicales."
  },
  AvgDialog_131204_Content_14 = {
    Text = "El nuevo dueño del teatro hace su aparición, y en el oscuro escenario resuena el tono exagerado de Nefruri."
  },
  AvgDialog_131204_Content_15 = {
    Text = "No es agradable, ¿verdad? ¿Que jueguen con tu destino? No importa, {Male=Mr.,Female=Miss} Guardián. Esta historia está a punto de terminar."
  },
  AvgDialog_131204_Content_16 = {
    Text = "Nefruri, ¿qué es lo que realmente quieres hacer?..."
  },
  AvgDialog_131204_Content_17 = {
    Text = "¡Suspense! ¡Por eso el público viene a este teatro! Pero no tengas tanta prisa, querida."
  },
  AvgDialog_131204_Content_18 = {
    Text = "¡Damas y caballeros! Preparar para aclamar... espera, ¿dónde están mis marionetas? Ah, ahí están."
  },
  AvgDialog_131204_Content_19 = {
    Text = "¿Qué imaginativa actuación nos ofrecerá nuestra gran vengadora, ahora que ha acabado con tres objetos secretos?"
  },
  AvgDialog_131204_Content_2 = {
    Text = "¡Entendido!"
  },
  AvgDialog_131204_Content_20 = {
    Text = "Ahora, ¡contemplen el <Big:<Red:Clímax del Segundo acto!>>"
  },
  AvgDialog_131204_Content_21 = {
    Text = "Lo llamo... \"Nuevo nacido sanado\"."
  },
  AvgDialog_131204_Content_22 = {Text = "CRAC—"},
  AvgDialog_131204_Content_23 = {
    Text = "Un rayo de luz quiebra la oscuridad. Un objeto secreto que sostiene una rueca se tambalea hasta el escenario."
  },
  AvgDialog_131204_Content_24 = {
    Text = "Nefruri, la diosa de la muerte del Abismo, la vengadora del destino...<Shake: ¡Me he sometido a su gran fuerza!>"
  },
  AvgDialog_131204_Content_25 = {
    Text = "Esto es lo \"romántico\"; vuelve necios a los hombres. Esto es la Bondad; los vuelve débiles. Y estos son mis Homenajes... la fuente de toda agonía."
  },
  AvgDialog_131204_Content_26 = {
    Text = "No puedo soportarlos... Los ofrezco a usted, la gran Nefruri."
  },
  AvgDialog_131204_Content_27 = {
    Text = "¿De verdad, hermana? Mi querida hermana..."
  },
  AvgDialog_131204_Content_28 = {
    Text = "Está bien. Soy quien mejor te comprende. Dame tu sufrimiento."
  },
  AvgDialog_131204_Content_29 = {
    Text = "¿Ves? La Linterna del Abismo espiral está encendida. Su luz nos guiará a casa."
  },
  AvgDialog_131204_Content_3 = {Text = "Ding—"},
  AvgDialog_131204_Content_30 = {
    Text = "Qué luz tan cálida... pero ¿cómo volvemos a casa?"
  },
  AvgDialog_131204_Content_31 = {
    Text = "¿No lo ves, hermana?"
  },
  AvgDialog_131204_Content_32 = {
    Text = "Esta rueca es el cuerpo del Apóstol. Estas llamas son los ojos del Apóstol... ¡Nos están observando!"
  },
  AvgDialog_131204_Content_33 = {
    Text = "\"Nefruri\" se levantó emocionada, abriendo los brazos."
  },
  AvgDialog_131204_Content_34 = {
    Text = "¡Solo uniendo la Orden de gran peso de los Tres plásmidos despertará el Apóstol Sin Nombre!"
  },
  AvgDialog_131204_Content_35 = {
    Text = "Él nos abrirá el camino hacia la Deidad suprema... cuando llegue ese momento, <Big:todo sufrimiento perecerá, todo esfuerzo vano llegará a su Fin.>"
  },
  AvgDialog_131204_Content_36 = {
    Text = "\"Nefruri\" de repente se quitó aquella máscara de madera, revelando el rostro vivo de Nefruri."
  },
  AvgDialog_131204_Content_37 = {
    Text = "Un escenario de madera, objetos secretos de madera, y una mujer viva en el centro, bañándose en la mirada de su única espectadora."
  },
  AvgDialog_131204_Content_38 = {
    Text = "El portal se está abriendo. Tu misión está casi completa. ¿No lo ves, hermana?"
  },
  AvgDialog_131204_Content_39 = {
    Text = "Ya no tienes que tejer esa red interminable. ¡Ya no tienes que seguir cortándote en pedazos!"
  },
  AvgDialog_131204_Content_4 = {
    Text = "Dedos esbeltos pulsan el aire. Una cuerda vibra, enviando una elegante ondulación por toda la sala."
  },
  AvgDialog_131204_Content_40 = {
    Text = "¿Me volverás a aceptar, Arachne? ... Déjame volver a ser parte de ti ..."
  },
  AvgDialog_131204_Content_41 = {
    Text = "Las lágrimas arruinan su maquillaje, dejando surcos negros y corrosivos en su rostro. Su risa maníaca y sus sollozos tejen una red asfixiante a su alrededor—la única alma viviente en este escenario."
  },
  AvgDialog_131204_Content_42 = {
    Text = "Nefruri se agachó y levantó la suave cara sin rasgos de \"Arachne\". Las lágrimas caían por esa cara de lamento, goteando sobre la máscara sonriente del muñeco."
  },
  AvgDialog_131204_Content_43 = {
    Text = "Ella miraba fijamente a Arachne en el escenario, sus labios temblorosos apenas tocaban la oreja de la marioneta. Su voz era tan suave, como si se la estuviera diciendo a sí misma."
  },
  AvgDialog_131204_Content_44 = {
    Text = "No me abandones. No me dejes atrás otra vez... <Italic:¿por favor?>"
  },
  AvgDialog_131204_Content_5 = {
    Text = "La ondulación engulle tu luz plateada, y la Llave de plata se desvanece al instante. Cuando la onda te atraviesa, tu carne se marchita hasta el hueso y tu sangre se convierte en cieno. Eres despedazado en fragmentos, y luego restaurado como si nada hubiera pasado."
  },
  AvgDialog_131204_Content_6 = {
    Text = "Todo poder se desvanece; todo pensamiento se extingue. Allá donde la ondulación alcanza, los mundos se transforman en hilos en sus manos. Incluyéndote a ti."
  },
  AvgDialog_131204_Content_7 = {
    Text = [[
Ella es la Maestra de este Teatro. 
Ella es el Destino mismo.]]
  },
  AvgDialog_131204_Content_8 = {
    Text = "Arachne, ¿tú... puedes controlar mi destino?!..."
  },
  AvgDialog_131204_Content_9 = {
    Text = "La sonrisa de Arachne es como un lago tranquilo, no puedes ver cómo es el lago, en esta superficie del lago, solo puedes ver tu propio reflejo."
  },
  AvgDialog_131205_Content_1 = {
    Text = "Fuego de armas"
  },
  AvgDialog_131205_Content_10 = {
    Text = "No necesitas entregar ningún trabajo."
  },
  AvgDialog_131205_Content_11 = {
    Text = "¿Maestra Arachne, qué significa...?"
  },
  AvgDialog_131205_Content_12 = {
    Text = "¿Recuerdas quién eres y de dónde vienes?"
  },
  AvgDialog_131205_Content_13 = {
    Text = "¿Yo? Obviamente soy..."
  },
  AvgDialog_131205_Content_14 = {
    Text = "%player%. Un lugareño de Hewatz de pies a cabeza. Estudiante de primer año en la Academia de Artes Dramáticas. Tus padres son funcionarios corrientes que te adoran. Has tenido dos romances respetables. Apasionado, aunque no excepcionalmente talentoso, con debilidad por la Sachertorte y los wraps de carne a la parrilla."
  },
  AvgDialog_131205_Content_15 = {
    Text = "Los recuerdos nítidos se difuminan de repente mientras un conjunto diferente de memorias se abre paso a la superficie. Misaq, Cuerpos Despertados, Fusión, Toguwaibo..."
  },
  AvgDialog_131205_Content_16 = {
    Text = "Abres los ojos de golpe y miras fijamente a la mujer sentada frente a ti, saboreando tranquilamente su café."
  },
  AvgDialog_131205_Content_17 = {
    Text = "No... eso no es correcto... Soy el Guardián de Misaq... ¡¿Qué está pasando?!"
  },
  AvgDialog_131205_Content_18 = {
    Text = "Ahora recuerdo... Estábamos en tu teatro. Subimos a un escenario, y entonces... y entonces..."
  },
  AvgDialog_131205_Content_19 = {
    Text = "Y entonces pediste el té de la tarde. Tu gusto como lugareño es bastante refinado."
  },
  AvgDialog_131205_Content_2 = {Text = "¡Din-din!"},
  AvgDialog_131205_Content_20 = {
    Text = "Arachne tomó un sorbo del líquido marrón en la taza de café y asintió con aprobación."
  },
  AvgDialog_131205_Content_21 = {
    Text = "Aquí tiene su pedido. Todo está servido."
  },
  AvgDialog_131205_Content_22 = {
    Text = "Los platos desprenden un aroma que hace la boca agua. Mientras el camarero se inclina para poner la mesa, acerca su boca a tu oído."
  },
  AvgDialog_131205_Content_23 = {
    Text = "El complot de asesinato se ha filtrado. Es probable que el archiduque cambie su ruta. El contacto te avisará en cuanto haya noticias. Prepárate, %player%."
  },
  AvgDialog_131205_Content_24 = {
    Text = "Te desliza discretamente una pistola Browning nueva en la mano. Cuando levantas la vista, el camarero luce de nuevo una sonrisa amable y profesional. Hace una reverencia y desaparece en la cocina con su bandeja."
  },
  AvgDialog_131205_Content_25 = {
    Text = "El peso de los recuerdos contradictorios se acumula, y te frotas las sienes doloridas con dolor."
  },
  AvgDialog_131205_Content_26 = {
    Text = "Llevar dos vidas distintas en una sola mente rara vez es una experiencia agradable para un novato."
  },
  AvgDialog_131205_Content_27 = {
    Text = "Estoy bien. Comparado con enfrentarse al Toguwaibo, un dolor de cabeza se siente como un masaje."
  },
  AvgDialog_131205_Content_28 = {
    Text = "Mi memoria dice que estoy siguiendo las órdenes de la Mano de Hierro. En dos horas, se supone que debo usar esta pistola para asesinar al heredero visitante del trono del Imperio Fio..."
  },
  AvgDialog_131205_Content_29 = {
    Text = "Recorres las ranuras de la pistola con los dedos, intentando organizar los recuerdos que pertenecen a este mundo."
  },
  AvgDialog_131205_Content_3 = {
    Text = "Las ruedas traquetean sobre los adoquines irregulares. Una campana furiosa chilla ante la enorme procesión, levantando nubes de polvo y un coro de maldiciones."
  },
  AvgDialog_131205_Content_30 = {
    Text = "Antes de que puedas preguntar nada más, una luz intensa inunda el café. El chasquido seco de botas militares sobre el hormigón resuena mientras los soldados marchan hacia el mostrador."
  },
  AvgDialog_131205_Content_31 = {
    Text = "Buenas tardes, oficiales. ¿En qué puedo...?"
  },
  AvgDialog_131205_Content_32 = {
    Text = "Sin mediar palabra, un oficial se abalanza hacia delante, inmovilizando las manos del camarero a su espalda y estampándole la cabeza contra la barra."
  },
  AvgDialog_131205_Content_33 = {
    Text = "Un cañón de pistola se presiona contra su frente. Los ojos del camarero se abren de par en par, llenos de terror."
  },
  AvgDialog_131205_Content_34 = {
    Text = "Bosant, miembro de la Mano de Hierro. Tienes diez segundos para decirme dónde están tus cómplices."
  },
  AvgDialog_131205_Content_35 = {
    Text = "El camarero jadea en busca de aire, temblando. En su desesperada lucha, sus ojos se dirigen hacia el rincón de la habitación."
  },
  AvgDialog_131205_Content_36 = {
    Text = "Pero la mesa que acababas de ocupar está vacía. Solo queda media taza de café, con su vapor elevándose perezosamente en el aire."
  },
  AvgDialog_131205_Content_37 = {Text = "..."},
  AvgDialog_131205_Content_38 = {
    Text = "Aquí deberíamos estar a salvo por un momento."
  },
  AvgDialog_131205_Content_39 = {
    Text = "Sales por la puerta trasera del café, fundiéndoos como dos gotas de agua insignificantes en la caótica multitud del exterior."
  },
  AvgDialog_131205_Content_4 = {
    Text = "Agitas una mano, apartando el polvo que se cuela por las cortinas del café."
  },
  AvgDialog_131205_Content_40 = {
    Text = "¿Qué está pasando? ¿Por qué tengo estos recuerdos contradictorios?"
  },
  AvgDialog_131205_Content_41 = {
    Text = "Pisar el escenario del Teatro del destino es convertirse en un personaje. Y cada personaje tiene una vida propia."
  },
  AvgDialog_131205_Content_42 = {
    Text = "Este es un mundo en una dimensión lejana de la que nunca has oído hablar ni has visitado. Sin embargo, como personaje nacido aquí, lo conoces como la palma de tu mano."
  },
  AvgDialog_131205_Content_43 = {
    Text = "Bienvenido/a a uno de mis escenarios, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131205_Content_44 = {
    Text = "Quieres decir... ¿que puedes usar el escenario para llegar a otros mundos?!"
  },
  AvgDialog_131205_Content_45 = {
    Text = "Arachne comprendió el significado en tu mirada ardiente. Levantó la taza de café que había llevado de la tienda, la olfateó con atención y sacudió la cabeza suavemente."
  },
  AvgDialog_131205_Content_46 = {
    Text = "Huyendo con café y pastel, este extraño asunto no llamó en absoluto tu atención. Ocurrió de manera tan armoniosa en Arachne, como si fuera parte de su destino."
  },
  AvgDialog_131205_Content_47 = {
    Text = "Lady Daffodil te explicó los principios del viaje dimensional. Las barreras entre mundos son increíblemente sólidas. Cada travesía exige un precio terrible; no es algo que se haga a la ligera."
  },
  AvgDialog_131205_Content_48 = {
    Text = "Pero ¿acaso no estamos aquí ahora mismo?..."
  },
  AvgDialog_131205_Content_49 = {
    Text = "El Teatro del destino puede conectar brevemente los destinos de diferentes mundos."
  },
  AvgDialog_131205_Content_5 = {
    Text = "Una envoltura de shawarma, una Sachertorte y dos tazas de café Hewatz. Gracias."
  },
  AvgDialog_131205_Content_50 = {
    Text = "Ahora mismo, no somos más que dos personajes perdidos en un mar de gente—proyecciones fugaces que se desvanecerán en un abrir y cerrar de ojos."
  },
  AvgDialog_131205_Content_51 = {
    Text = "Una proyección... incluso una proyección está bien. ¿Puedes usar este método para ayudarme a regresar?"
  },
  AvgDialog_131205_Content_52 = {
    Text = "Lo siento mucho, %player%. La puerta que cerraste bloqueó la Mirada de Toguwaibo, pero también cortó los Hilos del destino."
  },
  AvgDialog_131205_Content_53 = {
    Text = "Intentar ejercer influencia allí ahora desencadenaría un desastre más allá de lo que podemos soportar."
  },
  AvgDialog_131205_Content_54 = {
    Text = "Ella ve la decepción en tu rostro y sonríe, entregándote el pastel."
  },
  AvgDialog_131205_Content_55 = {
    Text = "Tranquilo, %player%. Una vez que nos hayamos encargado de mi hermana, el pasaje de vuelta a Kadas se abrirá de nuevo."
  },
  AvgDialog_131205_Content_56 = {
    Text = "El Destino nunca traiciona a quienes esperan, y jamás debemos despreciar los regalos que el Destino nos brinda. Vamos, pruébalo."
  },
  AvgDialog_131205_Content_57 = {
    Text = "Tomas aliento y das un pequeño mordisco al pastel. La dulzura es tan abrumadora que casi olvidas la inquietante incomodidad de tus recuerdos en conflicto."
  },
  AvgDialog_131205_Content_58 = {
    Text = "Hmm... Dicen que el Duque Flaviano nunca pierde la oportunidad de probar el pastel típico local cada vez que viene de visita. Para ser un príncipe heredero, sin duda tiene buen gusto."
  },
  AvgDialog_131205_Content_59 = {
    Text = "Entonces, ¿qué ha influido Nefruri en este mundo? ¿Cómo deberíamos corregir...?"
  },
  AvgDialog_131205_Content_6 = {
    Text = "Devuelves el menú de pergamino al camarero y miras con desánimo por la ventana hacia la calle familiar."
  },
  AvgDialog_131205_Content_60 = {
    Text = "Mientras hablas, Arachne parece ser atraída por algo, levantando la vista hacia esos hilos en el aire que no puedes ver claramente."
  },
  AvgDialog_131205_Content_61 = {
    Text = "Ella sonríe, apurando la última gota de su café. Entrega unas monedas y la bandeja vacía a un camarero que pasa de vuelta al café, dedicándole unas suaves palabras de agradecimiento."
  },
  AvgDialog_131205_Content_62 = {
    Text = "Nos ha encontrado. Justo a tiempo. Ten cuidado, %player%."
  },
  AvgDialog_131205_Content_63 = {Text = "Bang—"},
  AvgDialog_131205_Content_64 = {
    Text = "Te agachas instintivamente. Una bala pasa silbando, casi rozándote la coronilla."
  },
  AvgDialog_131205_Content_65 = {
    Text = "¡Justo ahí!"
  },
  AvgDialog_131205_Content_66 = {
    Text = "¡Son los asesinos de la Mano de Hierro! ¡Atrápenlos!"
  },
  AvgDialog_131205_Content_67 = {
    Text = "Guiados por unos cuantos ciudadanos que gritan, un enjambre de agentes se abre paso entre la multitud para rodearos."
  },
  AvgDialog_131205_Content_68 = {
    Text = "A medida que se acercan, sus cuerpos comienzan a deformarse—oscuras extremidades arácnidas y quitinosas brotan de sus torsos, y garras afiladas como navajas se lanzan hacia vosotros."
  },
  AvgDialog_131205_Content_7 = {
    Text = "Esta calle realmente necesita ser ensanchada. Se veía exactamente así cuando era niño. Aparte de estar más deteriorada, no ha cambiado ni un poco en todos estos años."
  },
  AvgDialog_131205_Content_8 = {
    Text = "Las autoridades son inútiles para construir cualquier cosa. Lo único que saben hacer es vender las tierras de Hewatz y servir pasteles a la familia real."
  },
  AvgDialog_131205_Content_9 = {
    Text = "refugiados, manifestación, el duque que decidió visitarnos en este momento... profesora Arachne, ¿puedo entregar mi trabajo de investigación sobre folklore un poco más tarde? Las actividades de la Restauración Nacional me han robado demasiada energía últimamente."
  },
  AvgDialog_131206_Content_10 = {
    Text = "Crujido—crujido—los Hilos del destino convergen en sus manos."
  },
  AvgDialog_131206_Content_11 = {
    Text = "Las marionetas marchan en fila, adentrándose en la Gran Telaraña."
  },
  AvgDialog_131206_Content_12 = {
    Text = "Bailan. Cantan. Crujido—crujido—"
  },
  AvgDialog_131206_Content_13 = {
    Text = "Mueren con la Gran Telaraña, en silencio y sin dejar rastro."
  },
  AvgDialog_131206_Content_14 = {
    Text = "Murieron junto con la gran red, en silencio absoluto."
  },
  AvgDialog_131206_Content_15 = {Text = "..."},
  AvgDialog_131206_Content_16 = {
    Text = "El pasaje de regreso a Kadas ha sido cerrado justo a tiempo. Ese {Male=mister,Female=miss} ha llegado a la ciudad."
  },
  AvgDialog_131206_Content_17 = {
    Text = "Bien entonces. ¿Te gusta la nueva obra?"
  },
  AvgDialog_131206_Content_18 = {
    Text = "Hmm... ¿quizás es un poco demasiado complicada?"
  },
  AvgDialog_131206_Content_19 = {
    Text = "Las historias simples son más fáciles de manejar, sí—pero para ciertas personas, una historia simple no puede contener su Destino."
  },
  AvgDialog_131206_Content_2 = {
    Text = "La trompeta entona una fanfarria. El guerrero de capa oscura hace su entrada."
  },
  AvgDialog_131206_Content_20 = {
    Text = "Emociones intensas, giros dramáticos, una trama conmovedora, un final trágico..."
  },
  AvgDialog_131206_Content_21 = {
    Text = "Este es el destino que le pertenece a un \"Héroe\"."
  },
  AvgDialog_131206_Content_22 = {
    Text = "Adelante; es tu turno en el escenario."
  },
  AvgDialog_131206_Content_23 = {
    Text = "La doncella se postra. En el momento en que su frente toca el suelo, su cuerpo se fragmenta—la carne y la piel se disuelven en arañas de un violeta pálido que se dispersan por cada rincón de la habitación y desaparecen."
  },
  AvgDialog_131206_Content_24 = {
    Text = "La joven se postró en señal de reverencia. En el instante en que su frente tocó el suelo, su cuerpo se fragmentó y se dispersó: toda su Carne y sangre y piel se convirtieron en arañas de color violeta pálido que desaparecieron por los rincones de la habitación."
  },
  AvgDialog_131206_Content_25 = {Text = "..."},
  AvgDialog_131206_Content_26 = {
    Text = "<Shake:Tos... tos, tos...>"
  },
  AvgDialog_131206_Content_27 = {
    Text = "Qué fue eso..."
  },
  AvgDialog_131206_Content_28 = {
    Text = "¡Ah! ¡¡La puerta a Kadas!!"
  },
  AvgDialog_131206_Content_29 = {
    Text = "Vuelves en ti de golpe, alzando la mirada al cielo."
  },
  AvgDialog_131206_Content_3 = {
    Text = "¡Ah, Kadas, la tierra natal de mis sueños! ¡Al fin puedo regresar!"
  },
  AvgDialog_131206_Content_30 = {
    Text = "El cielo es de un azul claro y brillante. La luz del sol te baña. No queda rastro del sol oscuro ni del pasaje dimensional."
  },
  AvgDialog_131206_Content_31 = {
    Text = "E–esta persona es muy extraña... ¿{Male=he,Female=she} acaba de caer del cielo?"
  },
  AvgDialog_131206_Content_32 = {
    Text = "Es-esta persona es muy extraña... ¿{Male=he,Female=she} acaba de caer del cielo?"
  },
  AvgDialog_131206_Content_33 = {
    Text = "Bueno, por lo que sé, hay una empresa tecnológica cerca probando aeronaves. {Male=he,Female=she} probablemente sea uno de sus pilotos de prueba."
  },
  AvgDialog_131206_Content_34 = {Text = "Gente."},
  AvgDialog_131206_Content_35 = {
    Text = "Una densa multitud llena tu campo de visión, con los ojos aún escocidos por la luz."
  },
  AvgDialog_131206_Content_36 = {
    Text = "Una ciudad tan bulliciosa como Londinium te devuelve a recuerdos lejanos de Kadas."
  },
  AvgDialog_131206_Content_37 = {
    Text = "Calles concurridas, multitudes reunidas, tiendas rebosantes de color por todas partes..."
  },
  AvgDialog_131206_Content_38 = {
    Text = "El mundo de esta dimensión ha visto su población reducirse drásticamente debido a la Fusión. Nunca habías presenciado una escena tan llena de vida, ni siquiera en Necrovia."
  },
  AvgDialog_131206_Content_39 = {
    Text = "Disculpe... ¿dónde estoy?"
  },
  AvgDialog_131206_Content_4 = {
    Text = "Mis mentores, mis compañeros, mi más querido amigo, mi... todo."
  },
  AvgDialog_131206_Content_40 = {
    Text = "¡Ja, qué extraño! ¿Alguien que ni siquiera ha oído hablar de Londinium? ¡Esta es la ciudad más grande del mundo!"
  },
  AvgDialog_131206_Content_41 = {
    Text = "¡Ja, qué curioso, hay alguien que nunca ha oído hablar de Londinium! ¡Es la ciudad más grande del mundo!"
  },
  AvgDialog_131206_Content_42 = {
    Text = "<Shake:¡¡¡>"
  },
  AvgDialog_131206_Content_43 = {
    Text = "Estás seguro de haber oído esas palabras."
  },
  AvgDialog_131206_Content_44 = {
    Text = "Tu mente aturdida se despeja en un instante. Te pones en pie de un salto y observas todo a tu alrededor."
  },
  AvgDialog_131206_Content_45 = {
    Text = "Cruce Brick. Las letras desgastadas en el poste indicador de la intersección son exactamente como las recuerdas."
  },
  AvgDialog_131206_Content_46 = {
    Text = "La librería de libros viejos con pliegues en el tiempo. Cada vez que te escapabas de la escuela, lo que más te gustaba era esconderte aquí y perderte en novelas de detectives."
  },
  AvgDialog_131206_Content_47 = {
    Text = "Tienda de comestibles del Mercado Fragante... donde el profesor Dexter siempre te pedía que le trajeras una botella de ginebra. El pequeño truco de N."
  },
  AvgDialog_131206_Content_48 = {
    Text = "Invernadero de rocío matutino. En el aniversario de tu primer año como Guardián, Ramona había planeado encargarte aquí el ramo más brillante de todo Londinium..."
  },
  AvgDialog_131206_Content_49 = {
    Text = "Casa de las flores de rocío. En la celebración de tu primer aniversario como Guardián del Secreto, Ramona había planeado hacerte un ramo con las flores más brillantes de todo Londinium..."
  },
  AvgDialog_131206_Content_5 = {
    Text = "¡Una vez que cruce este oscuro portal, me reuniré con ellos una vez más!"
  },
  AvgDialog_131206_Content_50 = {Text = "..."},
  AvgDialog_131206_Content_51 = {
    Text = "Disculpe... disculpe, ¿¡qué ha sido de Misaq?!"
  },
  AvgDialog_131206_Content_52 = {
    Text = "¿Misaq? Nunca hemos oído hablar de un lugar así, {Male=sir,Female=miss}."
  },
  AvgDialog_131206_Content_53 = {
    Text = "¿¡Y la Fusión?! ¿¡Cuánto daño ha causado aquí?!"
  },
  AvgDialog_131206_Content_54 = {
    Text = "¿Diso... qué? Esta ciudad nunca ha sufrido nada semejante."
  },
  AvgDialog_131206_Content_55 = {
    Text = "Joven {Male=sir,Female=lady}, creo que simplemente estás cansado/a y un poco confundido/a... Siéntate en ese banco y come algo. Resulta que llevo un poco conmigo."
  },
  AvgDialog_131206_Content_56 = {
    Text = "El anciano te ofrece el pan y el agua que acaba de comprar en la tienda de comestibles."
  },
  AvgDialog_131206_Content_57 = {
    Text = "Ah, muchas gracias... Pero ahora mismo no tengo hambre, solo... hay cosas que no logro entender..."
  },
  AvgDialog_131206_Content_58 = {
    Text = "Esto no puede estar bien... Sin Misaq, sin Fusión..."
  },
  AvgDialog_131206_Content_59 = {
    Text = "<Small:Esto no es posible... Sin Misaq, también sin disolución...>"
  },
  AvgDialog_131206_Content_6 = {
    Text = "Entonces, ¿por qué esta puerta, tan cerca de mi alcance, está cerrada con fuerza? ¿Por qué este cielo cruel me ha abandonado?"
  },
  AvgDialog_131206_Content_60 = {
    Text = "Eso no está bien decirlo. {Male=he,Female=she} puede estar pasando por algo difícil. Cuida tus modales con los visitantes que vienen de lejos."
  },
  AvgDialog_131206_Content_61 = {
    Text = "Eso no está bien dicho. {Male=He,Female=She} puede estar pasando por algo difícil. Guarda las formas con los invitados que vienen de lejos."
  },
  AvgDialog_131206_Content_62 = {
    Text = "Somos agentes de patrulla de la zona, bajo la jurisdicción de la Reunión de revisión del Acuerdo de Misdia. Aquí tiene mi identificación."
  },
  AvgDialog_131206_Content_63 = {
    Text = "Buenos días. Un amable ciudadano nos ha informado de que un viajero se ha perdido en nuestra hermosa ciudad."
  },
  AvgDialog_131206_Content_64 = {
    Text = "¿Hay algo en lo que podamos ayudarle, {Male=sir,Female=miss}?"
  },
  AvgDialog_131206_Content_65 = {
    Text = "Te tomas un breve momento para pensar. Hasta que entiendas lo que está pasando, lo mejor es llamar la atención lo menos posible."
  },
  AvgDialog_131206_Content_66 = {
    Text = "Te tomas un breve momento para pensar. Hasta que entiendas lo que está pasando, lo mejor es llamar la atención lo menos posible."
  },
  AvgDialog_131206_Content_67 = {
    Text = "Gracias a ambos. Tenemos asuntos que atender, así que nos pondremos en marcha..."
  },
  AvgDialog_131206_Content_68 = {
    Text = "Entiendo. En ese caso, si no le importa, me gustaría tomarle un poco más de su tiempo. Hay algunas cosas que me gustaría preguntarle."
  },
  AvgDialog_131206_Content_69 = {
    Text = "El agente se acerca a ti con una sonrisa, sacudiendo el polvo de tu hombro."
  },
  AvgDialog_131206_Content_7 = {
    Text = "Mi querida Llave de plata... ilumina mi camino... concédeme aunque sea un fragmento de respuesta..."
  },
  AvgDialog_131206_Content_70 = {
    Text = "Guardián... así es como debería llamarte, ?no es así?"
  },
  AvgDialog_131206_Content_71 = {
    Text = "<Red:Guardián>, así es como debería llamarte, ¿verdad?"
  },
  AvgDialog_131206_Content_72 = {
    Text = "Quisiera preguntarte... ¿estás satisfecho con esta ceremonia de bienvenida que te he preparado?"
  },
  AvgDialog_131206_Content_73 = {Text = "¡!!!"},
  AvgDialog_131206_Content_74 = {
    Text = "Un sonido nauseabundo de desgarro húmedo se eleva en el aire. Enormes patas de araña estallan a través de los cuerpos de los oficiales y los transeúntes, salpicándote con sangre espesa que huele a hierro."
  },
  AvgDialog_131206_Content_75 = {
    Text = "Nuestro distinguido invitado ha llegado al teatro. Lleven a {Male=him,Female=her} a {Male=his,Female=her} asiento, hijos míos."
  },
  AvgDialog_131206_Content_76 = {
    Text = "Nuestro distinguido invitado ha llegado al teatro. Llevad a {Male=him,Female=her} a {Male=his,Female=her} asiento, hijos míos."
  },
  AvgDialog_131206_Content_77 = {
    Text = "!!Cuidado!!"
  },
  AvgDialog_131206_Content_78 = {Text = "¡Cuidado!"},
  AvgDialog_131206_Content_8 = {
    Text = "Las luces cambian. La Cantante de Plata sube al escenario."
  },
  AvgDialog_131206_Content_9 = {
    Text = "Crujido—crujido—la Diosa del Destino gira su rueca."
  },
  AvgDialog_131207_Content_1 = {
    Text = "Reflejo de la divinidad"
  },
  AvgDialog_131207_Content_10 = {
    Text = "Todavía tienes la oportunidad de detenerte, Nefruri."
  },
  AvgDialog_131207_Content_11 = {
    Text = "¿Desaparecer completamente, y qué?"
  },
  AvgDialog_131207_Content_12 = {
    Text = "Nefruri sonrió con ligereza y se dio la vuelta para mirar a esos servidores de piedad."
  },
  AvgDialog_131207_Content_13 = {
    Text = "Dime, niños, ¿tienen miedo?"
  },
  AvgDialog_131207_Content_14 = {
    Text = "Lo que respondió Arachne fue una risa desesperada."
  },
  AvgDialog_131207_Content_15 = {
    Text = "¡Jajajaja! Somos los abandonados por el destino, ninguna catástrofe nos hará temer... Por favor, tráenos la liberación, mi Señor."
  },
  AvgDialog_131207_Content_16 = {
    Text = "Buen chico."
  },
  AvgDialog_131207_Content_17 = {
    Text = "Nefruri favoreosamente acarició la cabeza del servidor."
  },
  AvgDialog_131207_Content_18 = {
    Text = "Te has equivocado, querida hermana. El destino ya nos ha condenado a la pena de muerte y a la prisión eterna. Un grupo de almas abandonadas no volverá a suplicar por la clemencia del destino."
  },
  AvgDialog_131207_Content_19 = {
    Text = "Nosotros estamos vengando al destino."
  },
  AvgDialog_131207_Content_2 = {
    Text = "En el grandioso escenario que nunca has visto, la rueda de hilado negra de Nefruri se erige solitaria en el centro del escenario. En el medio del enorme anillo, una luz azul oscuro que parece nunca apagarse ilumina el rostro alegre de Nefruri."
  },
  AvgDialog_131207_Content_20 = {
    Text = "No sé si fue intencionado o no, pero en los hilos del destino que Nefruri manipula, uno se rompió en silencio."
  },
  AvgDialog_131207_Content_21 = {
    Text = "Al mismo tiempo que la cuerda se rompe, un escenario no muy lejos de vosotros estalla en mil pedazos, desapareciendo en el infinito espacio dimensional del teatro."
  },
  AvgDialog_131207_Content_22 = {
    Text = "¡Ups, lo siento, lo siento, accidentalmente rompí tu hilo de seda..."
  },
  AvgDialog_131207_Content_23 = {
    Text = "¡Vamos, buena hermana! Aunque hay muchos escenarios en el teatro, si los rompes de nuevo, también te dolerá, ¿verdad?"
  },
  AvgDialog_131207_Content_24 = {
    Text = "El susurro de Arachne es apenas audible. Al abrir los ojos de nuevo, ella levanta la yema de los dedos y te toca suavemente en la cabeza."
  },
  AvgDialog_131207_Content_25 = {
    Text = "¡Arachne! No hagas eso... Seguro que podemos encontrar otra manera..."
  },
  AvgDialog_131207_Content_26 = {
    Text = "Sube al escenario. Ofrece la Orden de gran peso de los plásmidos al Apóstol... Este es tu destino ineludible, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131207_Content_27 = {
    Text = "La voz irresistible de Arachne resuena en tu mundo espiritual. Cuando levantas el pie para caminar hacia el escenario, tres fuerzas olvidadas en tu interior comienzan a agitarse."
  },
  AvgDialog_131207_Content_28 = {
    Text = "Se entrelazan y chocan dentro de ti, desafiando las palabras oraculares de Arachne."
  },
  AvgDialog_131207_Content_29 = {
    Text = "Vaya, no es de extrañar que sea un plásmido... Con tan poco poder, aún puede influir en el anfitrión desde una dimensión tan lejana."
  },
  AvgDialog_131207_Content_3 = {
    Text = "Mira, {Male=Mr.,Female=Miss} Guardián, qué luces tan hermosas..."
  },
  AvgDialog_131207_Content_30 = {
    Text = "Haz que se comporten, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131207_Content_4 = {
    Text = "Esta luz es un regalo del destino, nos guiará hacia ese lugar de éxtasis sin dolor..."
  },
  AvgDialog_131207_Content_5 = {
    Text = "Nefruri extendió la mano, acariciando las huellas dejadas por la luz en el espacio dimensional. La sombra de los dedos se recogía lentamente, retorciéndose sobre el rostro de Arachne."
  },
  AvgDialog_131207_Content_6 = {
    Text = "Vamos, hermana, nuestro protagonista va a aparecer."
  },
  AvgDialog_131207_Content_7 = {
    Text = "...el destino no es algo que se pueda manipular o alterar, Nefruri."
  },
  AvgDialog_131207_Content_8 = {
    Text = "Cada destino ya está sellado. Si despiertas a esa deidad y dejas que todo termine... alterar el Destino por la fuerza traerá una catástrofe más allá de tu imaginación."
  },
  AvgDialog_131207_Content_9 = {
    Text = "Ya sea lo que desprecias o lo que atesoras, todo se desvanecerá en el apocalipsis."
  },
  AvgDialog_131208_Content_1 = {Text = "Juicio"},
  AvgDialog_131208_Content_10 = {
    Text = "La joven respira profundamente y sonríe con satisfacción."
  },
  AvgDialog_131208_Content_11 = {
    Text = "Los lirios han comenzado a florecer... la primavera ha llegado de verdad."
  },
  AvgDialog_131208_Content_12 = {
    Text = "¡Oye, Xiaofu, ¿alguna vez te he preguntado cuál es tu estación favorita?"
  },
  AvgDialog_131208_Content_13 = {
    Text = "No tengo ninguna estación favorita, mi señora."
  },
  AvgDialog_131208_Content_14 = {Text = "Aburrido."},
  AvgDialog_131208_Content_15 = {
    Text = "Arachne puso los ojos en blanco, extendió la mano que no tenía hilo, y atrapó la luz del sol que se filtraba por la ventana."
  },
  AvgDialog_131208_Content_16 = {
    Text = "Amo cada estación, especialmente la primavera. Ha pasado tanto tiempo desde que salimos de casa... ¿deberíamos buscar un momento para ir de excursión?"
  },
  AvgDialog_131208_Content_17 = {
    Text = "Junto a la finca donde nací, hay un jardín bellamente cuidado. Sé que te encantaría."
  },
  AvgDialog_131208_Content_18 = {
    Text = "Ha esperado tres días, mi señora. Es hora de decidir."
  },
  AvgDialog_131208_Content_19 = {
    Text = "La sirvienta cumplía con su deber, y sus frías palabras eran como una lluvia helada. Apagaron la brillante primavera en los ojos de Arachne."
  },
  AvgDialog_131208_Content_2 = {
    Text = "Crujido—crujido—los Hilos del destino convergen en sus manos."
  },
  AvgDialog_131208_Content_20 = {
    Text = "Crujido, crujido..."
  },
  AvgDialog_131208_Content_21 = {
    Text = "Tras una breve pausa, la rueca reanuda su rotación. Su ritmo es suave, nítido y eterno."
  },
  AvgDialog_131208_Content_22 = {
    Text = "Nuestra tierra acaba de emerger de un siglo de guerra. La gente ha reconstruido sus ciudades sobre las ruinas. Una paz larga y duradera les aguarda."
  },
  AvgDialog_131208_Content_23 = {
    Text = "Mira, allí..."
  },
  AvgDialog_131208_Content_24 = {
    Text = "Siguiendo la mirada de Arachne, la sirvienta miró una enorme pintura colgada en el salón. Nunca había entendido esa obra."
  },
  AvgDialog_131208_Content_25 = {
    Text = "De todas las obras maestras del Sr. Zoss, esta pasa desapercibida, y sin embargo es mi favorita."
  },
  AvgDialog_131208_Content_26 = {
    Text = "Estos ciervos, pintados en ocre y formas geométricas... incluso como símbolos abstractos, palpitan con vida."
  },
  AvgDialog_131208_Content_27 = {
    Text = "Cada vez que la veo, me recuerda a mi obra de teatro favorita..."
  },
  AvgDialog_131208_Content_28 = {
    Text = "La grieta lleva tres días abierta. El Destino de esta dimensión ya ha sido corrompido por la Mirada de esa deidad."
  },
  AvgDialog_131208_Content_29 = {
    Text = "Si esto continúa, la destrucción provocada por Su mirada no se detendrá en nuestras fronteras."
  },
  AvgDialog_131208_Content_3 = {
    Text = "Las marionetas marchan en fila, adentrándose en la Gran Telaraña."
  },
  AvgDialog_131208_Content_30 = {
    Text = "Crujido, crujido."
  },
  AvgDialog_131208_Content_31 = {
    Text = "La joven cierra los ojos, disfrutando de la calidez. La habitación queda en silencio, salvo por el eterno zumbido de la rueca."
  },
  AvgDialog_131208_Content_32 = {
    Text = "¿Recuerdas cuántos destinos de mundos hemos tejido?"
  },
  AvgDialog_131208_Content_33 = {
    Text = "Veintisiete en total, mi señora."
  },
  AvgDialog_131208_Content_34 = {
    Text = "Después de que Padre me diera esta rueca, seguí sus hilos hasta la Puerta de la Verdad. Más allá de esa Puerta, vislumbré el Destino que aguarda a este mundo."
  },
  AvgDialog_131208_Content_35 = {
    Text = "Sé lo que nos espera. Sé la decisión que debo tomar... pero no soy capaz de hacerlo."
  },
  AvgDialog_131208_Content_36 = {
    Text = "Familia. Amigos. Homenaje. Diecisiete mil años de gran historia. Tecnología y arte tan incontables como las estrellas..."
  },
  AvgDialog_131208_Content_37 = {
    Text = "Después de ver la verdad, comencé a tejer el Destino de este mundo... Creía que, puesto que el Destino me otorgó este poder, debía hacer algo por mi pueblo."
  },
  AvgDialog_131208_Content_38 = {
    Text = "Este es mi hogar. Mi criatura. <Shake:Yo... no puedo hacerlo>, Xiaofu..."
  },
  AvgDialog_131208_Content_39 = {Text = "Master..."},
  AvgDialog_131208_Content_4 = {
    Text = "Bailan. Cantan. Crujido—crujido—"
  },
  AvgDialog_131208_Content_40 = {
    Text = "La doncella se arrodilla y seca las lágrimas de su señora. Bajo la luz primaveral, su voz es clara y resuelta."
  },
  AvgDialog_131208_Content_41 = {
    Text = "Usted previó este día. Por eso me convirtió en su doncella."
  },
  AvgDialog_131208_Content_42 = {
    Text = "Todo el significado de mi vida es, en este momento, decirte qué debes hacer..."
  },
  AvgDialog_131208_Content_43 = {
    Text = "Eres el maestro del destino, el Guardián de estas múltiples dimensiones. Este es un camino cruel, pero ya has tomado una decisión."
  },
  AvgDialog_131208_Content_44 = {
    Text = "Las Tres Diosas del Destino, responsables de tejer, medir... y cortar."
  },
  AvgDialog_131208_Content_45 = {
    Text = "Desde el momento en que tomaste tu decisión, estas son las responsabilidades que estás destinado a cumplir."
  },
  AvgDialog_131208_Content_46 = {
    Text = "Arachne levantó la cabeza, en sus ojos borrosos, la grieta que los mortales no pueden ver parpadeaba en el horizonte. Siempre ha estado allí, al lado de la cálida luz del sol primaveral, como una sonrisa cruel."
  },
  AvgDialog_131208_Content_47 = {
    Text = "La grieta susurra a Arachne, contándole sobre esos fríos futuros. Ella ha aceptado esta maldición desde hace mucho tiempo, y cuando la llegada del futuro se hace presente, su cuerpo aún tiembla de miedo."
  },
  AvgDialog_131208_Content_48 = {
    Text = "Arachne se sentó de nuevo frente al telar. Después del miedo y la desesperación, apareció en su rostro un rubor poco saludable."
  },
  AvgDialog_131208_Content_49 = {
    Text = "Acaricia los hilos densos y enmarañados como si acariciara el rostro de un niño."
  },
  AvgDialog_131208_Content_5 = {
    Text = "Mueren con la Gran Telaraña, en silencio y sin dejar rastro."
  },
  AvgDialog_131208_Content_50 = {
    Text = "En el año 804, antes de que pudiera siquiera hablar, nuestro mayordomo tocó una pieza en el piano."
  },
  AvgDialog_131208_Content_51 = {
    Text = "<Italic:\"Funeral del río Loas\"> de Elysion. La música era como una fuente fluyendo frente a un templo. Vi incluso a los dioses detenerse a escuchar..."
  },
  AvgDialog_131208_Content_52 = {
    Text = "Un hilo fue cortado en silencio. Flota en el aire, navegando en silencio en la réplica del destino."
  },
  AvgDialog_131208_Content_53 = {
    Text = "La música en el salón se desvaneció, solo el fonógrafo seguía girando. Las surcos del disco fueron rellenados, y el nombre de la canción, escrito en una hermosa caligrafía, fue borrado."
  },
  AvgDialog_131208_Content_54 = {
    Text = "Elihiron ha encontrado otro destino. En este mundo solitario, su vida grandiosa nunca ha existido."
  },
  AvgDialog_131208_Content_55 = {
    Text = "Cassandra, la iglesia que diseñó, es más digna de admiración que los dioses que la habitan..."
  },
  AvgDialog_131208_Content_56 = {
    Text = "Se rompió otro hilo. A doscientos kilómetros de distancia, la majestuosa catedral se desmoronó y colapsó, los ojos compasivos de la deidad se hicieron añicos, indistinguibles del polvo."
  },
  AvgDialog_131208_Content_57 = {
    Text = "El cuento de Mornlin, la ópera de Aldo, las obras de arte de Malmo, la poesía de Rovel..."
  },
  AvgDialog_131208_Content_58 = {
    Text = "Los libros se convierten en papel desmenuzado, las esculturas en fragmentos, y las pinturas en colores desordenados."
  },
  AvgDialog_131208_Content_59 = {
    Text = "Ella es la reportera de la memoria. Ella es la ejecutora. Ella recita el nombre de cada gran artista de este mundo, cortando el hilo que les pertenece."
  },
  AvgDialog_131208_Content_6 = {
    Text = "La luz del sol baña sus rostros. ¡Qué felices están!"
  },
  AvgDialog_131208_Content_60 = {
    Text = "Vilderburg, una ciudad majestuosa que pertenece a los héroes. Ha soportado ciento cinco guerras, ha sido destruida y reconstruida treinta y siete veces, y veintiún grandes señores han logrado hazañas aquí, hundiéndose en la arena y rompiendo sus lanzas."
  },
  AvgDialog_131208_Content_61 = {
    Text = "Los nobles cantan aquí, los pobres gritan aquí, los poetas han dejado hermosos versículos para ello, y el canto junto al río Nérquin y el estruendo de los cañones resuenan en su cielo. Su heroica historia termina hoy."
  },
  AvgDialog_131208_Content_62 = {
    Text = "Un grupo de hilos cortados ondea desordenadamente, como una danza frenética. A dos mil trescientos kilómetros de distancia, esa grandiosa ciudad se derrumbó estruendosamente."
  },
  AvgDialog_131208_Content_63 = {
    Text = "Diecisiete mil años de existencia, una antigua civilización que ha resistido con dificultad ante desastres naturales y calamidades humanas, sin caer nunca..."
  },
  AvgDialog_131208_Content_64 = {
    Text = "Debilidad, temblando. Arachne levantó la mano con todas sus fuerzas, sosteniendo las vastas hebras de hilo frente a ella."
  },
  AvgDialog_131208_Content_65 = {
    Text = "La hebra se rompió. A ocho mil kilómetros de distancia, esa vasta antigua nación que había heredado la civilización humana y nunca había cesado de existir, desapareció así en la historia de la humanidad, como un humo azul."
  },
  AvgDialog_131208_Content_66 = {Text = "..."},
  AvgDialog_131208_Content_67 = {
    Text = "Humanos. Arte. Ciudad. Nación. Civilización."
  },
  AvgDialog_131208_Content_68 = {
    Text = "Todo se está colapsando, todo está desapareciendo."
  },
  AvgDialog_131208_Content_69 = {
    Text = "<Shake:¿Lo ves, Xiaofu?> Mi primera hija está muerta... La maté con mis propias manos."
  },
  AvgDialog_131208_Content_7 = {
    Text = "Crujido, crujido."
  },
  AvgDialog_131208_Content_70 = {
    Text = "Las lágrimas caen tranquilamente. Arachne sonríe débilmente, mirando por la ventana. En medio de las ruinas del mundo, solo queda la mansión inestable de afuera aún en pie."
  },
  AvgDialog_131208_Content_71 = {
    Text = "Yo solía pensar que, al tejer el destino, si pudiera seguir mirando el lugar donde solía vivir, me haría sentir menos solo en este camino."
  },
  AvgDialog_131208_Content_72 = {
    Text = "Es realmente infantil... Para un verdugo sin opciones, me he preparado el castigo más cruel con mis propias manos."
  },
  AvgDialog_131208_Content_73 = {
    Text = "Ella extendió la mano, moviendo el hilo borroso que tenía en la cabeza, un hilo que ella tampoco podía ver claramente, conectando una parte de él con el último hilo de este mundo."
  },
  AvgDialog_131208_Content_74 = {
    Text = "Amo, ¿qué es esto...?"
  },
  AvgDialog_131208_Content_75 = {
    Text = "El romanticismo trae torpeza, la bondad trae fragilidad, los recuerdos traen dolor..."
  },
  AvgDialog_131208_Content_76 = {
    Text = "He reflexionado, Xiaofu. Soy el ejecutor maldito, esas cosas hermosas no deberían existir en mí."
  },
  AvgDialog_131208_Content_77 = {
    Text = "Vas a... ¿extinguir una parte de ti misma? Pero estas son las piezas que más atesoras, ¿cómo puedes...?"
  },
  AvgDialog_131208_Content_78 = {
    Text = "Cuando era muy, muy pequeño, tuve mi primer sueño en la vida."
  },
  AvgDialog_131208_Content_79 = {
    Text = "Arachne extendió la mano y atrapó aquella luz del sol que iluminaba las interminables ruinas."
  },
  AvgDialog_131208_Content_8 = {
    Text = "Una antigua rueca tararea un suave acompañamiento. Una joven se sienta frente a ella, murmurando una melodía sencilla."
  },
  AvgDialog_131208_Content_80 = {
    Text = "En el sueño, estoy caminando sobre la superficie de un lago. A mi alrededor hay ruinas infinitas y huesos marchitos, mientras que debajo de la superficie del lago, el reflejo de mi infancia camina en un hermoso reino."
  },
  AvgDialog_131208_Content_81 = {
    Text = "No hay muerte, no hay sufrimiento, no hay olvido. La suave luz del sol brilla eternamente allí, y la multitud canta a su lado, sin cesar..."
  },
  AvgDialog_131208_Content_82 = {
    Text = "No puedo ver a dónde llevan mis hilos, pero creo que ahora puedo ver claramente el destino que presagia ese sueño."
  },
  AvgDialog_131208_Content_83 = {
    Text = "Esboza una sonrisa forzada—quizá por su doncella, o quizá por algo completamente distinto."
  },
  AvgDialog_131208_Content_84 = {
    Text = "La madre solía decir que el nombre de Arachne se lee al revés como Nefruri. En la leyenda de este mundo, es el nombre de la diosa de la primavera."
  },
  AvgDialog_131208_Content_85 = {
    Text = "Amo todas las estaciones, especialmente la primavera. La primavera es mucho más pequeña que el Destino. Pero el Destino conduce a la muerte, mientras que la primavera... la primavera solo trae renacimiento."
  },
  AvgDialog_131208_Content_86 = {
    Text = "Contempla fijamente por la ventana. A ambos lados del marco, el Destino y la Primavera comparten una última mirada."
  },
  AvgDialog_131208_Content_87 = {
    Text = "Déjame, reflejo mío. Mi querida hermana. Llévate toda nuestra bondad y nuestros hermosos recuerdos contigo."
  },
  AvgDialog_131208_Content_88 = {
    Text = "Destino... te ofrezco una parte de mí misma como sacrificio total. Recorreré este arduo camino en su lugar."
  },
  AvgDialog_131208_Content_89 = {
    Text = "Arachne acarició suavemente la hebra entrelazada. La hebra tembló suavemente, como si estuviera luchando y gritando."
  },
  AvgDialog_131208_Content_9 = {
    Text = "Un rayo de sol se filtra por la ventana, iluminando una placa grabada con \"Moira\" junto a la rueca."
  },
  AvgDialog_131208_Content_90 = {
    Text = "Sus lágrimas caen a través de los hilos y sobre el plato de la \"Moira\"."
  },
  AvgDialog_131208_Content_91 = {
    Text = "Eres libre, \"Arachne\"."
  },
  AvgDialog_131208_Content_92 = {Text = "Crujido."},
  AvgDialog_131208_Content_93 = {
    Text = "El hilo se rompe. Bajo la cálida luz primaveral, la rueca deja escapar un último suspiro."
  },
  AvgDialog_131209_Content_1 = {
    Text = "Reencuentro"
  },
  AvgDialog_131209_Content_10 = {
    Text = "Si hubiera elegido ser cantante de ópera, las colas del teatro se extenderían tres manzanas calle abajo."
  },
  AvgDialog_131209_Content_11 = {
    Text = "Es una tragedia que los objetos secretos de Londinium nunca presenciaran mi espectacular actuación. Visto así, tú eres una pequeña afortunada."
  },
  AvgDialog_131209_Content_12 = {
    Text = "Nefruri acarició suavemente la carita de la niña, como una madre que acaricia amorosamente a su hija."
  },
  AvgDialog_131209_Content_13 = {
    Text = "En el centro del salón de la catedral, clavos de acero atraviesan el pecho, el abdomen, los hombros, las espinillas y las palmas de la niña—perforando cada punto adecuado para la suspensión y la percepción del dolor, fijándola firmemente a un enorme candelabro con forma de rueca."
  },
  AvgDialog_131209_Content_14 = {
    Text = "Nefruri llevó sus manos cubiertas de sangre a la punta de la nariz, cerrando los ojos con obsesión."
  },
  AvgDialog_131209_Content_15 = {
    Text = "Ah... el aroma de la sangre vital. Tan vibrante."
  },
  AvgDialog_131209_Content_16 = {
    Text = "Durante años, lo intenté todo—desgarrar los cuerpos de niños, incluso mi propia carne—pero nunca pude saborear una sola gota de vitalidad."
  },
  AvgDialog_131209_Content_17 = {
    Text = "El destino correcto. Un espíritu ardiente. Qué envidiable... pero ¿sabías? Estabas destinada a ser arrojada al montón de desechos del Destino, igual que nosotras."
  },
  AvgDialog_131209_Content_18 = {
    Text = "No necesitas alimento, y nunca hablas. Aparte de los recuerdos que guardas para ella, no eres nada y no sabes nada."
  },
  AvgDialog_131209_Content_19 = {
    Text = "El Destino te abandonó hace mucho, pobrecita. No eres más que una muñeca que ella usa para consolarse—una sepulturera de sus recuerdos, vagando sola por este escenario vacío."
  },
  AvgDialog_131209_Content_2 = {
    Text = "<Shake:La...♪ La la...♪>"
  },
  AvgDialog_131209_Content_20 = {
    Text = "Observa a la pequeña, que apenas respira a estas alturas, con la voz temblorosa de un dolor fingido mientras aparta un mechón suelto de la sien de la niña."
  },
  AvgDialog_131209_Content_21 = {
    Text = "Ahora, tu cruel madre, el Destino, se acerca... Pase lo que pase, recíbela siendo tu versión más hermosa, ¿de acuerdo?"
  },
  AvgDialog_131209_Content_22 = {Text = "..."},
  AvgDialog_131209_Content_23 = {
    Text = "Una vez que tus ojos se ajustan a la tenue luz del santuario, un conjunto de murales enormes capta tu atención."
  },
  AvgDialog_131209_Content_24 = {
    Text = "Pigmentos viscosos se extienden por paredes de decenas de metros de altura, prolongándose hasta un techo de oscuridad absoluta. Imponentes, sagrados y mugrientos, como una estatua de un santo salvador erigida en una alcantarilla."
  },
  AvgDialog_131209_Content_25 = {
    Text = "Su considerada anfitriona ha despejado la sala, dejando solo el eco de tus pasos y tu respiración. Caminas bajo el imponente mural y alzas la mirada."
  },
  AvgDialog_131209_Content_26 = {
    Text = "Una mujer está sentada ante una rueca, cortando hilos de seda con unas tijeras... ¿es este un retrato tuyo, Arachne?"
  },
  AvgDialog_131209_Content_27 = {
    Text = "Eso parece. Creo que estas son las palabras que mi hermana desea transmitir."
  },
  AvgDialog_131209_Content_28 = {
    Text = "Arachne no tenía prisa por buscar el lugar de\"Recordar\". Ella seguía tus pasos, observando con interés estas pinturas murales."
  },
  AvgDialog_131209_Content_29 = {
    Text = "Una figura idéntica se separa de la mujer sentada y cae en la oscuridad de una cueva..."
  },
  AvgDialog_131209_Content_3 = {
    Text = "Crujido—crujido—los Hilos del destino convergen en sus manos."
  },
  AvgDialog_131209_Content_30 = {
    Text = "En la cueva oscura, una mujer y otras criaturas de la noche ejecutan una danza extraña. Ella sostiene... ¿una rueca?"
  },
  AvgDialog_131209_Content_31 = {
    Text = "El centro brilla como una Linterna, iluminando las sombras."
  },
  AvgDialog_131209_Content_32 = {
    Text = "Una mujer que porta una Linterna con forma de rueca llega a una ciudad... un grupo de figuras con túnicas se arrodilla ante ella. El sigilo en sus ropas... ¡¿es el sigilo del Portador de Luz?!"
  },
  AvgDialog_131209_Content_33 = {
    Text = "Difiere ligeramente de los sigilos que has visto antes: alrededor de ese siniestro triángulo invertido hay un anillo adicional, como una rueca."
  },
  AvgDialog_131209_Content_34 = {
    Text = "Pero reconoces los elementos. Sabes exactamente lo que es. Este es el nacimiento de la Iglesia de los Portadores de Luz."
  },
  AvgDialog_131209_Content_35 = {
    Text = "El último..."
  },
  AvgDialog_131209_Content_36 = {
    Text = "El mural final se alza al final del corredor como una puerta que sella el Destino. La pintura mugrienta ondula sobre la superficie, reflejando las turbias sombras de la capilla."
  },
  AvgDialog_131209_Content_37 = {
    Text = "Una mujer sostiene una Linterna, arrodillada ante una figura borrosa. Detrás de ellos se cierne algo enorme..."
  },
  AvgDialog_131209_Content_38 = {Text = "Ugh..."},
  AvgDialog_131209_Content_39 = {
    Text = "Al reconocer ese enorme globo ocular con párpado, una punzada violenta te recorre, agitando olas turbulentas en tu mente."
  },
  AvgDialog_131209_Content_4 = {
    Text = "Las marionetas marchan en fila, adentrándose en la Gran Telaraña."
  },
  AvgDialog_131209_Content_40 = {
    Text = "Apartas la mirada rápidamente y respiras hondo para contener la oleada de náuseas que te invade."
  },
  AvgDialog_131209_Content_41 = {
    Text = "<Shake:Huff... huff...> La Iglesia de los Portadores de Luz... Toguwaibo..."
  },
  AvgDialog_131209_Content_42 = {
    Text = "¡En esta dimensión, Nefruri es nada menos que la creadora de la Iglesia de la Lanterna"
  },
  AvgDialog_131209_Content_43 = {
    Text = "Ahora lo veo. ¡Lo entiendo!..."
  },
  AvgDialog_131209_Content_44 = {
    Text = "Has visto la verdad, {Male=Mr.,Female=Miss} Guardián. Cuando la Deidad Suprema se acercaba a su despertar, mi hermana abandonada escapó del Abismo."
  },
  AvgDialog_131209_Content_45 = {
    Text = "Su interferencia nubló mi visión, permitiéndole ocultar este culto bajo mi escenario."
  },
  AvgDialog_131209_Content_46 = {
    Text = "A quien ella veneraba era al Apóstol—el conectado con esa Deidad Suprema en esta dimensión."
  },
  AvgDialog_131209_Content_47 = {
    Text = "Vuelves a mirar la borrosa figura oscura en el mural, la que está dibujada junto a Toguwaibo."
  },
  AvgDialog_131209_Content_48 = {
    Text = "Entiendo... lo que Nefruri quiere hacer es depender de la fuerza de esa persona, ¡reestablecer la conexión con Toguwaibo!..."
  },
  AvgDialog_131209_Content_49 = {
    Text = "Pero si ese es el caso, ¿por qué cazar a los objetos secretos...?"
  },
  AvgDialog_131209_Content_5 = {
    Text = "Bailan. Cantan. Crujido—crujido—"
  },
  AvgDialog_131209_Content_50 = {Text = "Dong——"},
  AvgDialog_131209_Content_51 = {
    Text = "Un turbio tañido resuena desde el campanario. Un sucio oráculo divino."
  },
  AvgDialog_131209_Content_52 = {
    Text = "La catedral retumba con un rugido grave. Entre los fuertes temblores, los muros de piedra que sostienen los murales se deslizan hacia arriba."
  },
  AvgDialog_131209_Content_53 = {Text = "¡¡Ahí!!"},
  AvgDialog_131209_Content_54 = {
    Text = "Arachne......señora......"
  },
  AvgDialog_131209_Content_55 = {
    Text = "Oh, vaya... nuestra pequeña \"Recordar\". Tu voz es tan débil que casi da lástima."
  },
  AvgDialog_131209_Content_56 = {
    Text = "¡Nefruri! ¡Liberar ella"
  },
  AvgDialog_131209_Content_57 = {
    Text = "El pequeño cuerpo de la chica cuelga de la gran lámpara de araña con forma de rueca. Sangre Carmesí se extiende por el suelo de mármol blanco."
  },
  AvgDialog_131209_Content_58 = {
    Text = "Luces brillantes resplandecen tras ella, proyectando una silueta sagrada alrededor de su cuerpo empapado en sangre."
  },
  AvgDialog_131209_Content_59 = {
    Text = "Nefruri, no sigas con estas peleas inútiles. Libérala."
  },
  AvgDialog_131209_Content_6 = {
    Text = "Mueren con la Gran Telaraña, en silencio y sin dejar rastro."
  },
  AvgDialog_131209_Content_60 = {
    Text = "¿Oh? ¿Nuestra Diosa del Destino de repente se preocupa por su \"Recordar\" ahora?"
  },
  AvgDialog_131209_Content_61 = {
    Text = "Nunca te importaron, los abandonaste, Arachne."
  },
  AvgDialog_131209_Content_62 = {
    Text = "Nefruri, sé que quieres convocar al Apóstol, despertar de nuevo a Toguwaibo... Si hay algo, podemos discutirlo de nuevo, no es necesario matarlos..."
  },
  AvgDialog_131209_Content_63 = {
    Text = "La forma en que ganas tiempo es adorablemente infantil, %player%."
  },
  AvgDialog_131209_Content_64 = {
    Text = "No entiendes nada. Yo nunca los maté. Simplemente los estoy llevando a casa."
  },
  AvgDialog_131209_Content_65 = {
    Text = "Te traje aquí solo para que pudieras presenciar su perfecto final juntos."
  },
  AvgDialog_131209_Content_66 = {
    Text = "Segundo acto, escena tres. Lo llamo... \"Feliz Reencuentro\"."
  },
  AvgDialog_131209_Content_67 = {
    Text = "Nefruri te miró con desdén. Sus uñas rozaron suavemente el rostro de \"Recordar\", dejando una delgada marca de sangre."
  },
  AvgDialog_131209_Content_68 = {
    Text = "Ella se inclina, observando el rostro tembloroso de la niña con una ternura depredadora."
  },
  AvgDialog_131209_Content_69 = {
    Text = "Buena chica, no tengas miedo. Pronto estaremos en casa."
  },
  AvgDialog_131209_Content_7 = {
    Text = "Murieron junto con la gran red, en silencio absoluto."
  },
  AvgDialog_131209_Content_70 = {
    Text = "¡Despídete de tus miserables recuerdos, querida hermana!"
  },
  AvgDialog_131209_Content_71 = {
    Text = "Espera... ¡Nefruri!"
  },
  AvgDialog_131209_Content_72 = {Text = "CRAC—"},
  AvgDialog_131209_Content_73 = {
    Text = "En el sonido nítido de los dedos de Nefruri, el cuerpo de la niña estalló como un fuego artificial rojo brillante."
  },
  AvgDialog_131209_Content_74 = {
    Text = "La luz de la Linterna atrapa la salpicadura, proyectando una flor roja como la sangre sobre el mural."
  },
  AvgDialog_131209_Content_75 = {
    Text = "Las gotas de sangre salpican en el aire, se detienen y luego regresan, trepando codiciosamente hacia el cuerpo de Nefruri, tiñendo cada centímetro de su cuerpo de rojo."
  },
  AvgDialog_131209_Content_76 = {
    Text = "La sangre se filtra en su ropa y su carne, inundando sus venas y recorriendo su esbelta figura."
  },
  AvgDialog_131209_Content_77 = {
    Text = "La lengua lamía la sangre en los labios, Nefruri contemplaba con deleite sus uñas teñidas de rojo, como una anfitriona vestida de gala, lista para recibir un banquete de reencuentro."
  },
  AvgDialog_131209_Content_78 = {
    Text = "Bienvenida a casa, cariño."
  },
  AvgDialog_131209_Content_79 = {Text = "¡Detente!"},
  AvgDialog_131209_Content_8 = {
    Text = "El canto resuena en la amplia iglesia. Nefruri abre los brazos, disfrutando de su resonancia."
  },
  AvgDialog_131209_Content_80 = {
    Text = "La luz plateada brilla en tus manos mientras te lanzas hacia Nefruri."
  },
  AvgDialog_131209_Content_81 = {
    Text = "Bajo la luz sagrada y sangrienta, incontables sombras se extienden desde los mugrientos murales para bloquear tu camino..."
  },
  AvgDialog_131209_Content_9 = {
    Text = "¿Cómo fue mi canto?"
  },
  AvgDialog_131210_Content_1 = {
    Text = "No esperaba que al volver a verte estuvieras en un estado tan lamentable."
  },
  AvgDialog_131210_Content_2 = {Text = "Thais..."},
  AvgDialog_131210_Content_3 = {
    Text = "Tawil tiene razón. Está bien, Guardián."
  },
  AvgDialog_131210_Content_4 = {
    Text = "Dijiste que me llevarías a testificar otro final. Confío en ti, desde el principio hasta el final."
  },
  AvgDialog_131210_Content_5 = {
    Text = "Ya sea que te detengas aquí o que me sobrepases, siempre estaré a tu lado."
  },
  AvgDialog_131211_Content_1 = {Text = "Capullo"},
  AvgDialog_131211_Content_10 = {
    Text = "Esta experiencia, no quiero volver a tenerla una segunda vez..."
  },
  AvgDialog_131211_Content_11 = {
    Text = "No estás seguro de si realmente lo dices en serio. Aprietas el puño, reajustándote al cuerpo que acabas de compartir con \"N\"."
  },
  AvgDialog_131211_Content_12 = {
    Text = "Tu visión se va aclarando gradualmente, te frotas la cabeza dolorida y caminas hacia la delgada figura que está arrodillada en el borde del escenario."
  },
  AvgDialog_131211_Content_13 = {
    Text = "Nefruri, tu plan ya ha......"
  },
  AvgDialog_131211_Content_14 = {Text = "¡Cuidado!"},
  AvgDialog_131211_Content_16 = {
    Text = "Como si unos hilos tiraran suavemente, tu paso se ralentiza un poco. Una afilada garra negra de araña pasa rozando tu ojo, cruzando peligrosamente frente a ti."
  },
  AvgDialog_131211_Content_17 = {
    Text = "Ocho enormes tentáculos venenosos rasgaron la ropa de su espalda, moviéndose en el aire, distorsionándose y luchando. Nefruri parecía no preocuparse por nada de esto."
  },
  AvgDialog_131211_Content_18 = {
    Text = "Los fragmentos del pasaje dimensional flotaban a su alrededor como fuegos artificiales que caen. Sus lágrimas caían, empapando la rueda de hilo apagada que sostenía en su mano."
  },
  AvgDialog_131211_Content_19 = {
    Text = "El pasaje de la dimensión ha desaparecido, ya no tienes oportunidad."
  },
  AvgDialog_131211_Content_2 = {
    Text = "......Guardián......"
  },
  AvgDialog_131211_Content_20 = {
    Text = "El destino camina en su trayectoria adecuada, Nefruri. Acepta eso."
  },
  AvgDialog_131211_Content_21 = {
    Text = "¿Oportunidad?... Jejeje..."
  },
  AvgDialog_131211_Content_22 = {
    Text = "La delgada silueta temblaba por la risa, trazando en el aire una trayectoria desgarradora con esos miembros envenenados."
  },
  AvgDialog_131211_Content_23 = {
    Text = "Nunca he tenido la oportunidad, ni la he necesitado."
  },
  AvgDialog_131211_Content_24 = {
    Text = "Libertad, infancia, familia, amor, yo mismo... el destino nos ha robado todo, nunca, nunca seré un prisionero de él como tú."
  },
  AvgDialog_131211_Content_25 = {
    Text = "Nefruri se levantó lentamente, colocando su cuerpo en el oscuro y roto huso."
  },
  AvgDialog_131211_Content_26 = {
    Text = "¡Mira bien, Arachne! ¡Las cosas que deseas con todas tus fuerzas pero no te atreves a hacer, yo las haré por ti"
  },
  AvgDialog_131211_Content_27 = {
    Text = "Casi es en el grito de ira, el cuerpo de Nefruri parece ser atravesado instantáneamente por innumerables espinas. La sangre fluye de su cuerpo, conectándose a esa rueda de hilar rota, como una red sangrienta."
  },
  AvgDialog_131211_Content_28 = {
    Text = "<Shake:@2—!>"
  },
  AvgDialog_131211_Content_29 = {
    Text = "Un grito agudo e insoportable para los humanos emanó de la cabeza de Nefruri. Su cuerpo temblaba por el intenso dolor, y las venas de un color púrpura oscuro se hacían visibles en su cuerpo."
  },
  AvgDialog_131211_Content_3 = {
    Text = "{Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131211_Content_30 = {
    Text = "Los fragmentos del canal de dimensión parecen haber sido atraídos por algo, deteniéndose en su dispersión, y lentamente se agrupan hacia esa red tejida de sangre. La rueda de hilo apagada vuelve a encenderse con un brillo sanguinario."
  },
  AvgDialog_131211_Content_31 = {
    Text = "Je... ¡Jajaja! <Big:<Shake:¡Si no hay dioses, me convertiré en uno!>>"
  },
  AvgDialog_131211_Content_32 = {
    Text = "Mi historia... mi escenario... ¡nunca terminará! Traeré la liberación a esta red que nunca debió existir... <Big:<Shake:<Red:¡¡¡liberación!!!>>>"
  },
  AvgDialog_131211_Content_33 = {
    Text = "En los gritos de dolor de Nefruri, todo el Teatro del destino comenzó a temblar violentamente. Los títeres en el escenario se volcaron y chocaron, las cuerdas que conectaban a los títeres estaban en un desordenado enredo..."
  },
  AvgDialog_131211_Content_34 = {
    Text = "Arachne miró a la figura no muy lejos, erosionada por la fuerza y la locura del fragmento dimensional. En sus ojos, que eran como un profundo abismo, surgieron ondas de tristeza, como el día en que se deshizo de sí misma por primera vez."
  },
  AvgDialog_131211_Content_35 = {
    Text = "He intentado liberarte de esta maldición... Lamentablemente, me equivoqué, Nefruri."
  },
  AvgDialog_131211_Content_36 = {
    Text = "Maldición, sin escape, jaula, nunca podremos escapar..."
  },
  AvgDialog_131211_Content_37 = {
    Text = "¡Esos fragmentos... esa rueda..."
  },
  AvgDialog_131211_Content_38 = {
    Text = "¡Nefruri está absorbiendo la fuerza residual en el pasaje dimensional! ¡Ella... ella quiere convertirse en una mecha!!"
  },
  AvgDialog_131211_Content_39 = {
    Text = "Un leve suspiro resuena claramente en este teatro inestable."
  },
  AvgDialog_131211_Content_4 = {
    Text = "<Shake:Ugh... cof, cof...>"
  },
  AvgDialog_131211_Content_40 = {
    Text = "Agárrate fuerte, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131211_Content_41 = {Text = "¿Qué..."},
  AvgDialog_131211_Content_42 = {
    Text = "<Shake:Boom—>"
  },
  AvgDialog_131211_Content_43 = {
    Text = "Aún no había terminado de hablar, y todo el teatro se desgarró de repente. Nefruri desgarraba furiosamente los hilos del destino, y en la espantosa grieta, los edificios de la ciudad se entrelazaban con los fragmentos coloridos de la dimensión."
  },
  AvgDialog_131211_Content_44 = {
    Text = "El escenario principal del teatro se ha hecho añicos, fragmentos del pasado, futuro y presente se entrelazan caóticamente en el escenario roto, formando una imagen que no puedes comprender."
  },
  AvgDialog_131211_Content_45 = {
    Text = "Arachne...... ¡tu red......"
  },
  AvgDialog_131211_Content_46 = {
    Text = "La rueca en manos de Arachne gira rápidamente, la vasta ceniza de dimensión brota del cuerpo de Arachne, siguiendo los hilos de la rueca, llenando los huecos rotos en la red del destino, manteniendo a duras penas el escenario lejos de un destino de colapso."
  },
  AvgDialog_131211_Content_47 = {
    Text = "Bajo la tensión del hilo, te levantas con dificultad."
  },
  AvgDialog_131211_Content_48 = {
    Text = "Absorber Su fuerza dispersa, cambiar la dirección de toda la Red del destino... No eres un fragmento de Él, no puedes soportar tal presión. No tienes que morir tan dolorosamente, Nefruri."
  },
  AvgDialog_131211_Content_49 = {
    Text = "¿Sufrimiento? No, estoy muy feliz, ¡hermana! Durante innumerables años en el abismo, he estado imaginando este día en cada momento."
  },
  AvgDialog_131211_Content_5 = {
    Text = "¿Qué pasó..."
  },
  AvgDialog_131211_Content_50 = {
    Text = "¡Es precisamente esta fantasía la que me ha permitido llegar hasta hoy..."
  },
  AvgDialog_131211_Content_51 = {
    Text = "La risa de locura de Nefruri resonaba en el espacio roto del teatro. Ella levantó la cabeza, absorbiendo con avaricia los oscuros destellos de los fragmentos."
  },
  AvgDialog_131211_Content_52 = {
    Text = "El dios sumido en el sueño, el apóstol que ha robado el destino... jejeje... no importa, nada de esto puede detenerme. Si el dios no puede traer bendiciones, ¡entonces yo lo haré en Su lugar"
  },
  AvgDialog_131211_Content_53 = {
    Text = "¡Vengadores del Destino, al escenario! <Red:¡Este acto os pertenece!>"
  },
  AvgDialog_131211_Content_54 = {
    Text = "Nefruri levantó la mano de repente. Una interminable sustancia negra y pegajosa brotó del cuerpo de Nefruri, tejiendo una red negra en el vacío de este teatro."
  },
  AvgDialog_131211_Content_55 = {
    Text = "Incontables rencores, una vez descartados por el Destino, toman forma física. Se arrastran por la enorme red en una marea abrumadora, avanzando hacia ti."
  },
  AvgDialog_131211_Content_56 = {
    Text = "Arachne, en nuestro cuerpo...！"
  },
  AvgDialog_131211_Content_57 = {
    Text = "De repente te das cuenta de que un hilo negro que puedes ver aparece vagamente del cuerpo de Arachne."
  },
  AvgDialog_131211_Content_58 = {
    Text = "Levantas la cabeza y ves un hilo negro difuso que se extiende desde tu cuerpo, desde cada escenario, desde cada cuerpo de marioneta, conectándose con la rueca en manos de Nefruri."
  },
  AvgDialog_131211_Content_59 = {
    Text = "¡Bendiciones, Arachne! ¡Bendición para ti, diosa del destino"
  },
  AvgDialog_131211_Content_6 = {
    Text = "Un fuerte mareo y espasmos estomacales son los restos de la alegría. Conteniendo las náuseas, te levantas lentamente."
  },
  AvgDialog_131211_Content_60 = {
    Text = "¡Vamos, saquen sus cuchillas, soldados! ¡Luchen por nuestro destino"
  },
  AvgDialog_131211_Content_61 = {
    Text = "Señorita Arachne, acepta tu destino... no sigas resistiendo sin sentido..."
  },
  AvgDialog_131211_Content_62 = {
    Text = "No te preocupes, querida. Tu liberación está por llegar, pronto, pronto..."
  },
  AvgDialog_131211_Content_63 = {
    Text = "La oscura rueca de Nefruri gira locamente, los marionetas en el escenario se convierten en sombras en el Abismo, y bajo la tirantez de los hilos, pisan esa nueva red negra tejida."
  },
  AvgDialog_131211_Content_64 = {
    Text = "Arachne cerró lentamente los ojos, y su mano que sostenía el hilo temblaba ligeramente por el dolor."
  },
  AvgDialog_131211_Content_65 = {
    Text = "Nefruri, no pueden ayudarte a convertirte en esa deidad capaz de destruir todo destino... lo que haces, solo traerá una vez más su dolorosa desaparición."
  },
  AvgDialog_131211_Content_66 = {
    Text = "¿Y qué importa? ¡Venganza, aparte de la venganza, no deseamos nada más! ¿Verdad, hijos rechazados del destino?"
  },
  AvgDialog_131211_Content_67 = {
    Text = "<Shake:Je... ¡jajaja!>"
  },
  AvgDialog_131211_Content_68 = {
    Text = "Una risa aguda, grandiosa y desgarradora surge de la interminable telaraña negra, como un coro de dolor."
  },
  AvgDialog_131211_Content_69 = {
    Text = "Esos destinos abandonados se ríen a carcajadas y lloran, bloqueando el camino de Nefruri."
  },
  AvgDialog_131211_Content_7 = {
    Text = "La conciencia del Apóstol ha abandonado la rueca, y ha perdido la conexión con los dioses, ahora ha sido destruida por completo. El poder del plásmido también ha regresado a la calma."
  },
  AvgDialog_131211_Content_70 = {
    Text = "Ahora, la Puerta del Abismo se ha abierto por completo. ¡Ven, Arachne, mira esos destinos que has creado con tus propias manos, mira a tus amados niños"
  },
  AvgDialog_131211_Content_71 = {
    Text = "Mira su sufrimiento, su desesperación... míralos y, una vez más, mátalos"
  },
  AvgDialog_131211_Content_72 = {
    Text = "Mira cómo el destino de todo gira en mis manos, ¡destruye! ... ¡Mírame, conviértete en la deidad que trae el fin"
  },
  AvgDialog_131211_Content_73 = {
    Text = "Los fragmentos de dimensión, portadores de la fuerza divina y la voluntad del frenesí, se clavaron uno a uno en el cuerpo de Nefruri, mientras la sangre fluía incesantemente hacia el huso de Nefruri."
  },
  AvgDialog_131211_Content_74 = {
    Text = "Su rostro se contorsiona de agonía, pero su risa solo se vuelve más frenética."
  },
  AvgDialog_131211_Content_75 = {
    Text = "Ella miraba con expectativa el escenario roto, como una dramaturga que espera el estreno de su obra."
  },
  AvgDialog_131211_Content_76 = {
    Text = "Ese abismo del destino ya ha llegado a este escenario... Nefruri está realizando un ritual de sacrificio."
  },
  AvgDialog_131211_Content_77 = {
    Text = "Ella quiere convertir todo aquí, incluyendo a nosotros, en sus marionetas. Ella desea convertirse en esa persona divina. Ella... quiere convertirse en el destino mismo."
  },
  AvgDialog_131211_Content_78 = {
    Text = "El tono tranquilo de Arachne parece pertenecer a una espectadora que nunca se ha involucrado en la obra. Aquellas cenizas de dimensión que han sido recuperadas flotan alrededor de sus dedos como arena ligera, sin cesar."
  },
  AvgDialog_131211_Content_79 = {
    Text = "La rueca de ella giraba con dificultad, esforzándose por mantener esos destinos que estaban siendo destruidos por Nefruri, impidiendo que esos hilos negros se unieran en manos de Nefruri."
  },
  AvgDialog_131211_Content_8 = {
    Text = "Has realizado una actuación magnífica."
  },
  AvgDialog_131211_Content_80 = {
    Text = "Las cenizas de la dimensión ya han sido recuperadas, y hoy no tengo más reservas."
  },
  AvgDialog_131211_Content_81 = {
    Text = "Por favor, ayúdame, acércate a ella. La rueca de Nefruri dejará de girar, y este destino erróneo, lo corregiré contigo."
  },
  AvgDialog_131211_Content_82 = {
    Text = "Ayúdame... a liberar estos destinos abandonados."
  },
  AvgDialog_131211_Content_9 = {
    Text = "Uf... no puedo creer que esas palabras salieran de mi boca."
  },
  AvgDialog_131212_Content_1 = {
    Text = "Mientras tanto, al otro lado de la ciudad..."
  },
  AvgDialog_131212_Content_10 = {
    Text = "El número seis fue seleccionado personalmente de los establos del Duque. Se va a llevar la copa, recuerda mis palabras. ¡Apuesta todo al seis!"
  },
  AvgDialog_131212_Content_11 = {
    Text = "El ruido chirriante en el metro se convierte en un arroyo vibrante, Arachne observa en silencio las luces que se acercan y se alejan por la ventana, sonriendo mientras escucha a sus marionetas hablar sobre la actuación, las carreras de caballos y las bodas."
  },
  AvgDialog_131212_Content_12 = {
    Text = "Gira su huso en silencio. Entre los miles de millones de hilos intrincados, saborea este fugaz momento de paz."
  },
  AvgDialog_131212_Content_13 = {
    Text = "Mi señora, nos acercamos a nuestra parada. El carruaje está listo, y nuestras hermanas la esperan en el punto de transbordo."
  },
  AvgDialog_131212_Content_14 = {
    Text = "Buena chica."
  },
  AvgDialog_131212_Content_15 = {
    Text = "Recorre con la mirada a las marionetas aún inmersas en sus actuaciones, como una espectadora que no soporta abandonar su asiento."
  },
  AvgDialog_131212_Content_16 = {
    Text = "¿Recuerdas cuánto tiempo ha pasado desde la última vez que salimos del teatro?"
  },
  AvgDialog_131212_Content_17 = {
    Text = "He estado a su lado desde el día en que me convertí en Araña fría. ¿Cincuenta años? ¿Sesenta? He perdido la cuenta."
  },
  AvgDialog_131212_Content_18 = {
    Text = "Pero esta vez hemos estado lejos del teatro bastante tiempo."
  },
  AvgDialog_131212_Content_19 = {
    Text = "Esto hay que agradecérselo a Nefruri. Si no fuera por su llegada, no habría tenido la oportunidad de quedarme tanto tiempo fuera del teatro."
  },
  AvgDialog_131212_Content_2 = {
    Text = "Billete, por favor. Señor, ¿puedo ver su billete?"
  },
  AvgDialog_131212_Content_20 = {
    Text = "Hemos cazado cientos de escuderos del Abismo espiral junto al Guardián. Una vez que rescatemos \"Homenaje\", será hora de volver a casa."
  },
  AvgDialog_131212_Content_21 = {
    Text = "Quién sabe cuándo tendremos otra oportunidad así..."
  },
  AvgDialog_131212_Content_22 = {
    Text = "Parece que sintió los pensamientos de Arachne, las luces fuera del metro se apagaron. Ella contempló la oscuridad a través de la ventana, buscando entre los recuerdos de innumerables civilizaciones en cambio, aquellos recuerdos ordinarios sobre sí misma."
  },
  AvgDialog_131212_Content_23 = {
    Text = "Dos segundos transcurren. La señora de la ciudad nota que el animado parloteo se desvanece en el instante en que el tren se sumerge en la oscuridad total."
  },
  AvgDialog_131212_Content_24 = {
    Text = "Mi señora, algo está..."
  },
  AvgDialog_131212_Content_25 = {Text = "CRACK—"},
  AvgDialog_131212_Content_26 = {
    Text = "La sangre fría de la sirvienta salpicó en el rostro tranquilo de Arachne, desprendiendo un aroma fresco similar al de las iris."
  },
  AvgDialog_131212_Content_27 = {
    Text = "Se encendieron las luces afuera. Arachne vio el cuerpo de la sirvienta cortado, la cuchilla que atravesó su cuerpo dirigiéndose hacia ella, y detrás de la cuchilla, aquellos muñecos que se abalanzaban sobre ella como una manada de bestias."
  },
  AvgDialog_131212_Content_28 = {Text = "..."},
  AvgDialog_131212_Content_29 = {
    Text = "Los frenos gimen con un fatigado chirrido metálico. La brisa resultante agita el cabello de otra doncella."
  },
  AvgDialog_131212_Content_3 = {
    Text = "¿No lo acaban de revisar en la entrada? Así es exactamente como se malgasta el dinero de los contribuyentes..."
  },
  AvgDialog_131212_Content_30 = {
    Text = "¡Ah! ¡Hemos llegado!"
  },
  AvgDialog_131212_Content_31 = {
    Text = "Las puertas se abren, pero ninguna multitud emerge. Solo un espeso río metálico de sangre se filtra por las grietas, fluyendo en un silencioso conjunto."
  },
  AvgDialog_131212_Content_32 = {
    Text = "Caminando sobre este río de sangre que acompaña la música, Arachne salió lentamente del vagón. Su ropa estaba impoluta, su rueca seguía girando, sin detenerse nunca."
  },
  AvgDialog_131212_Content_33 = {Text = "Eso es..."},
  AvgDialog_131212_Content_34 = {
    Text = "Una fascinante pieza de teatro interactivo. Como público y actriz a la vez, la experiencia es mucho más vívida que la de una dramaturga."
  },
  AvgDialog_131212_Content_35 = {
    Text = "Observa a la doncella frente a ella, con una expresión indescifrable."
  },
  AvgDialog_131212_Content_36 = {
    Text = "Mis doncellas llevan conmigo muchos años. Rara vez toco los hilos de sus destinos."
  },
  AvgDialog_131212_Content_37 = {
    Text = "En aquel tedioso teatro, estaban entre las pocas almas vibrantes."
  },
  AvgDialog_131212_Content_38 = {
    Text = "Hoy has matado a mis dos sirvientas. La destrucción del destino tendrá un precio, Nefruri."
  },
  AvgDialog_131212_Content_39 = {
    Text = "jejejejeje...<Shake:¡jaajajaja!>Qué noble, Arachne."
  },
  AvgDialog_131212_Content_4 = {
    Text = "¡Charlie! ¿Dónde está mi broche?"
  },
  AvgDialog_131212_Content_40 = {
    Text = "Como mantequilla cayendo en una olla de estaño hirviendo, el cuerpo de la sirvienta comenzó a derretirse. Debajo de la hirviente y sucia sustancia negra pegajosa, esa cara idéntica a la de Arachne reía a carcajadas."
  },
  AvgDialog_131212_Content_41 = {
    Text = "<Italic:\"¡Contemplad! ¡Soy la señora del Destino, la ejecutora diligente! ¡Elegiré los caminos justos y arrojaré cada error al abismo!\">"
  },
  AvgDialog_131212_Content_42 = {
    Text = "Eres mi ídolo, mi fe, querida hermana. Simplemente estoy interpretando tu papel."
  },
  AvgDialog_131212_Content_43 = {
    Text = "¿Y bien? ¿He sido una alumna digna?"
  },
  AvgDialog_131212_Content_44 = {
    Text = "Arachne observa en silencio aquellos ojos que la miran. Son ardientes, brillantes, llenos de expectativa, como si provinieran de una niña que espera los elogios de su hermana."
  },
  AvgDialog_131212_Content_45 = {
    Text = "Plataformas, escaleras, columnatas... mientras habla, sombras se manifiestan en cada rincón de la estación."
  },
  AvgDialog_131212_Content_46 = {
    Text = "La respiración turbia de la sombra está fuertemente conectada, reunida en las manos de Nefruri, como una enorme red que se estrecha hacia Arachne."
  },
  AvgDialog_131212_Content_47 = {
    Text = "Las comisuras de los labios de Arachne se elevaron suavemente."
  },
  AvgDialog_131212_Content_48 = {
    Text = "Nunca imaginé que alguien intentaría atrapar<Italic:me> en una red."
  },
  AvgDialog_131212_Content_49 = {
    Text = "¿Has visto un gusano de seda, hermana? Se pasan la vida sin hacer nada más que comer y tejer seda... y luego esperan a que los mismos capullos que tejieron los asfixien."
  },
  AvgDialog_131212_Content_5 = {
    Text = "¿No te lo prendí en el vestido antes de salir?"
  },
  AvgDialog_131212_Content_50 = {
    Text = "Casi todos tus escuderos han perecido en los rincones de esta ciudad y sobre este tren. Fueron tus únicos compañeros durante esos largos años en el vacío."
  },
  AvgDialog_131212_Content_51 = {
    Text = "Les diste un final que no debió ocurrir. El destino es irrevocable, Nefruri."
  },
  AvgDialog_131212_Content_52 = {
    Text = "¿Quieres decir que su destino \"correcto\" era pudrirse en esa prisión oscura por toda la eternidad? ¿Es eso, estimado El maestro del destino?"
  },
  AvgDialog_131212_Content_53 = {
    Text = "Nefruri se rió y sacudió la cabeza."
  },
  AvgDialog_131212_Content_54 = {
    Text = "Los amo más de lo que puedes imaginar. Y me dijeron que si la muerte podía librarlos de ser encarcelados de nuevo, la abrazarían sin dudarlo."
  },
  AvgDialog_131212_Content_55 = {
    Text = "Después de esta masacre en los túneles, ¿cuántas ascuas te quedan para reparar el daño?"
  },
  AvgDialog_131212_Content_56 = {
    Text = "Nefruri alzó con orgullo la rueda de hilo negra que tenía en la mano. Incontables hilos se extendían desde el escenario de la ciudad, conectándose a esa rueda de hilo inmóvil."
  },
  AvgDialog_131212_Content_57 = {
    Text = "Los hilos de esta ciudad están en mis manos. No puedo manipularlos... lo cual es una lástima, la verdad, ya que me estoy perdiendo tanta diversión..."
  },
  AvgDialog_131212_Content_58 = {
    Text = "Por suerte, mientras que repararlos te cuesta tus preciadas ascuas, contaminarlos no me cuesta nada."
  },
  AvgDialog_131212_Content_59 = {
    Text = "Si simplemente los suelto... tu teatro y tu escenario se convertirán en el caldo de cultivo perfecto para el Caos. Igual que el agujero donde pasé mi vida."
  },
  AvgDialog_131212_Content_6 = {
    Text = "Oh, cielos... ¡Pasé un mes preparándome para hoy! Sin ese broche, este vestido no es más que una mortaja..."
  },
  AvgDialog_131212_Content_60 = {
    Text = "Y tendrás que verlo suceder. Sin poder cambiarlo. Sin poder resistirte."
  },
  AvgDialog_131212_Content_61 = {
    Text = "Nefruri se acercó a Arachne y le acarició cuidadosamente el rostro, en el que no se podían distinguir las emociones."
  },
  AvgDialog_131212_Content_62 = {
    Text = "¿Qué será, querida hermana? ¿Me obedecerás, o contemplamos juntas cómo este mundo se convierte en un infierno en vida?"
  },
  AvgDialog_131212_Content_63 = {
    Text = "Eres un fragmento incompleto del Destino. Para contaminar una ciudad entera... te falta la—"
  },
  AvgDialog_131212_Content_64 = {
    Text = "Un sonido de ruptura de un hilo fino resonó al lado de la oreja de Arachne. Ella levantó la cabeza y, en la mirada de Nefruri, se añadió un toque de tristeza que pertenecía al público."
  },
  AvgDialog_131212_Content_65 = {
    Text = "...También acabas de matar a \"Recordar\"."
  },
  AvgDialog_131212_Content_66 = {
    Text = "No, la acepté. \"romántico\", Amabilidad, Homenaje... una por una, he traído a casa todo lo que tú desechaste."
  },
  AvgDialog_131212_Content_67 = {
    Text = "Nefruri se levantó y dio una vuelta con alegría."
  },
  AvgDialog_131212_Content_68 = {
    Text = "Una yo completa. Una vengadora completa. ¿Te gusta lo que ves, hermana?"
  },
  AvgDialog_131212_Content_69 = {
    Text = "Tienes el Caos que anhelabas. ¿Por qué esperar más?"
  },
  AvgDialog_131212_Content_7 = {
    Text = "La Compañía Cycnus es bastante elegante, supongo, pero si se tratara de un conflicto de horarios, elegiría <Italic:Jardín Esmeralda> siempre."
  },
  AvgDialog_131212_Content_70 = {
    Text = "Oh, no, no, no. Aún estoy muy, muy lejos de lo que realmente quiero."
  },
  AvgDialog_131212_Content_71 = {
    Text = "Cuidaré bien de tu huso por ti. Tus Chispas Dimensionales nunca se agotarán. No dañaré ni uno solo de tus preciados escenarios."
  },
  AvgDialog_131212_Content_72 = {
    Text = "Y todo lo que pido es un pequeño, pequeñísimo favor."
  },
  AvgDialog_131212_Content_73 = {
    Text = "Nefruri se acercó a Arachne, acariciando la rueca que giraba sin parar en sus manos, respirando con ansiedad por la excitante imaginación."
  },
  AvgDialog_131212_Content_74 = {
    Text = "Toma el control del Guardián por mí, querida hermana. Solo el Guardián puede traerme lo que realmente deseo."
  },
  AvgDialog_131212_Content_75 = {
    Text = "Sabes bien que %player% es un fragmento del Ser Supremo. No podemos gobernar el Destino de {Male=his,Female=her}..."
  },
  AvgDialog_131212_Content_76 = {
    Text = "Una luz verde oscura emana de la rueca negra en las manos de Nefruri. A la luz, aparece un hilo oculto y turbio en el campo de visión de Arachne."
  },
  AvgDialog_131212_Content_77 = {
    Text = "Esto es... <Shake:¿¡el Hilo del Destino del Guardián?!>"
  },
  AvgDialog_131212_Content_78 = {
    Text = "<Shake:Jeh...> <Big:<Shake:¡JAJAJAJAJA!>> Es la primera vez que oigo temblar tu voz. ¿Y bien, hermana? ¿¡No es emocionante?!"
  },
  AvgDialog_131212_Content_79 = {
    Text = "En el Abismo, el Apóstol —una encarnación de la voluntad divina de <Italic:Ello>— fue atrapado dentro de esta rueda para servir como su Wick. Era la única luz que jamás tuvimos en aquella oscuridad."
  },
  AvgDialog_131212_Content_8 = {
    Text = "El conjunto de múltiples capas, la intrincada narrativa no lineal... el auge y la caída de los jardines reales es muy superior a esas tramas tan trilladas."
  },
  AvgDialog_131212_Content_80 = {
    Text = "Con nuestro poder y la guía del Apóstol, <Big:¡incluso el Destino de un fragmento divino descansa en NUESTRAS manos!>"
  },
  AvgDialog_131212_Content_81 = {
    Text = "Este no es el rumbo correcto del destino, Nefruri... Nadie puede desafiar el destino."
  },
  AvgDialog_131212_Content_82 = {
    Text = "Pronto lo harán, hermana. Una vez que obtengamos las Autoridades de los Tres Plásmidos, ¡el Apóstol renacerá! Reabrirán el canal hacia lo Divino; ¡llevarán las voces de los Creyentes hasta el Santuario Eterno!"
  },
  AvgDialog_131212_Content_83 = {
    Text = "La Deidad Suprema despertará... y nunca más tendrás que podar otro destino agonizante ni tejer una red destinada a quebrarse."
  },
  AvgDialog_131212_Content_84 = {
    Text = "Nefruri tomó una profunda respiración y una lágrima cayó de su rostro emocionado."
  },
  AvgDialog_131212_Content_85 = {
    Text = "Su voz temblaba por el maravilloso sueño que estaba por llegar. Aquellos ojos llorosos, miraban profundamente el rostro sereno de Arachne."
  },
  AvgDialog_131212_Content_86 = {
    Text = "Deja de luchar contra mí, hermana. Solo te causa dolor."
  },
  AvgDialog_131212_Content_87 = {
    Text = "Ven a mi lado. ¡Demos juntas la bienvenida a Su despertar y concedamos a cada escenario el final que merece!"
  },
  AvgDialog_131212_Content_9 = {
    Text = "¡Ja! Si apuestas por el número ocho, estás tirando el dinero. Tengo información de buena fuente de que alguien va a drogar su pienso hoy."
  },
  AvgDialog_131213_Content_1 = {
    Text = "Comedia improvisada"
  },
  AvgDialog_131213_Content_10 = {
    Text = "Ahora, has recibido a un nuevo creyente——"
  },
  AvgDialog_131213_Content_100 = {
    Text = "Estoy tomando prestada la Orden de gran peso de \"N\"... <color=#98918C>Estoy ocupando la mitad de la consciencia de %player%</color>... pero un nombre es lo menos importante ahora mismo."
  },
  AvgDialog_131213_Content_101 = {
    Text = "Lo importante es que la cooperación sea agradable, Arachne."
  },
  AvgDialog_131213_Content_102 = {
    Text = "<Shake:Tú... todos vosotros... lo sabíais desde el principio...>"
  },
  AvgDialog_131213_Content_103 = {
    Text = "La mirada débil de Nefruri se movió del rostro de Arachne al tuyo. Saboreas con avaricia la infinita resentimiento y dolor en esa mirada. Ah, qué fragancia tan embriagadora..."
  },
  AvgDialog_131213_Content_104 = {
    Text = "Mira bien, querida Nefruri, el travieso que salió del lugar del Oblivion."
  },
  AvgDialog_131213_Content_105 = {
    Text = "Tu juego me brinda mucha alegría. Un fragmento de conciencia residual de Toguwaibo, un trozo caído de Toguwaibo, solo su encuentro puede permitir que el poder del plásmido sea completamente liberado, dándome la oportunidad de experimentar esta felicidad nunca antes vivida..."
  },
  AvgDialog_131213_Content_106 = {
    Text = "Si pudiera, desearía poder seguir jugando así como ahora, esta diversión me podría durar toda una semana..."
  },
  AvgDialog_131213_Content_107 = {
    Text = "Tu garganta tiembla. Suspirar con gran pesar."
  },
  AvgDialog_131213_Content_108 = {
    Text = "Es una pena, si esa persona divina despierta de nuevo, este majestuoso Paraíso se irá de mí."
  },
  AvgDialog_131213_Content_109 = {
    Text = "Así que, lamentablemente... el clímax debe terminar. Mira arriba, querida. Pase lo que pase, al menos podemos estar de acuerdo en una cosa sobre esta historia del Destino..."
  },
  AvgDialog_131213_Content_11 = {
    Text = "El hilo del destino tira de tu cuerpo. Entrecruzas los dedos, juntando las manos en el pecho, y lentamente te arrodillas, inclinándote hacia la rueda que está frente a ti."
  },
  AvgDialog_131213_Content_110 = {
    Text = "Te inclinas, sosteniendo la elegante mandíbula de Nefruri, y te acercas a su oído."
  },
  AvgDialog_131213_Content_111 = {
    Text = "La destrucción es la imagen más hermosa de este universo, ¿verdad, querido?"
  },
  AvgDialog_131213_Content_112 = {
    Text = "Un chasquido claro, lleno de alegría infinita y pesar, resonó ante los ojos de Nefruri."
  },
  AvgDialog_131213_Content_113 = {Text = "¡Boom—"},
  AvgDialog_131213_Content_114 = {
    Text = "En el temblor de la dimensión, el pasaje conectado con los dioses tiembla repentinamente. Incontables grietas trepan por la superficie ilusoria del pasaje..."
  },
  AvgDialog_131213_Content_115 = {
    Text = "<Big:<Shake:¡¡NOOOO!!—>>"
  },
  AvgDialog_131213_Content_116 = {
    Text = "Nefruri gritó mientras se lanzaba hacia el pasillo, y cuando su mano estaba a unos centímetros del pasillo, este se rompió y colapsó."
  },
  AvgDialog_131213_Content_117 = {
    Text = "Incontables fragmentos ilusorios flotan frente a Nefruri, como un caleidoscopio roto, esos baratos trozos de papel de colores se dispersan por el aire, rozando la cara de Nefruri."
  },
  AvgDialog_131213_Content_118 = {
    Text = "Te quitas ese sombrero de copa que no existe, giras dos veces en el aire y haces una reverencia a la espalda desorientada de Nefruri."
  },
  AvgDialog_131213_Content_119 = {
    Text = "Destino, qué escenario tan interesante... el tercer acto llega a su fin. Tus aplausos y vítores me hacen disfrutar inmensamente."
  },
  AvgDialog_131213_Content_12 = {
    Text = "Yo... el apóstol anhelante... soy... su creyente más fiel y el de los dioses supremos."
  },
  AvgDialog_131213_Content_120 = {
    Text = "Disfruta del espectáculo, querida Nefruri."
  },
  AvgDialog_131213_Content_121 = {
    Text = "En los desgarradores gritos de Nefruri, la conciencia del apóstol se fragmentó con la ruptura del pasaje. Caíste de espaldas en el escenario, con la última sonrisa de alegría."
  },
  AvgDialog_131213_Content_13 = {
    Text = "Tu tráquea y tus extremidades tienen su propio destino. Ya no te pertenecen, y no intentes en vano recuperarlas."
  },
  AvgDialog_131213_Content_14 = {
    Text = "No controles. No entiendas. Disfrútalos. El camino de la alegría está en ellos..."
  },
  AvgDialog_131213_Content_15 = {
    Text = "¡Mira, hermana! ¡Qué actor tan excepcional has entrenado!"
  },
  AvgDialog_131213_Content_16 = {
    Text = "Arachne se sentaba al borde del escenario, con su rueca girando a esa frecuencia eterna. Ella miraba en silencio las sombras tenues de la linterna en el escenario, como si solo fuera una espectadora que cumplía con las normas."
  },
  AvgDialog_131213_Content_17 = {
    Text = "Oh, mi querido apóstol... nuestros creyentes te han traído la ofrenda que más anhelas."
  },
  AvgDialog_131213_Content_18 = {
    Text = "El huso oscuro estalla en una explosión repentina, esparciendo una luz tenue y viscosa por cada rincón del escenario."
  },
  AvgDialog_131213_Content_19 = {Text = "¡Uf!..."},
  AvgDialog_131213_Content_2 = {
    Text = "Toca, toca, toca."
  },
  AvgDialog_131213_Content_20 = {
    Text = "Pain golpea sin previo aviso. No impacta tu carne ni tus órganos, sino que erupciona desde los rincones más profundos de tu Espacio mental—desde la mismísima sede de tu alma."
  },
  AvgDialog_131213_Content_21 = {
    Text = "Una gran bestia se manifiesta en tu interior. Lucha y ruge, su forma colosal expandiéndose rápidamente dentro de ti."
  },
  AvgDialog_131213_Content_22 = {
    Text = "La bestia llena todo tu cuerpo, aplastando cada órgano. Se expande aún más, rugiendo por atravesar tu piel. La presión intensa y abrumadora casi te hace perder el conocimiento..."
  },
  AvgDialog_131213_Content_23 = {
    Text = "Hah... <Big:<Shake:¡¡AAAARGH!!—>>"
  },
  AvgDialog_131213_Content_24 = {
    Text = "En tu desgarrador grito de dolor, tres alientos vagos emergen del cuerpo sufriente, flotando hacia la rueca que emite una luz oscura."
  },
  AvgDialog_131213_Content_25 = {
    Text = "La Orden de gran peso converge en la luz como combustible puro vertido en un fuego. Llamas tenues estallan, ardiendo ferozmente dentro del anillo del huso. El resplandor de la Linterna asciende, iluminando toda la dimensión."
  },
  AvgDialog_131213_Content_26 = {
    Text = "<Shake:Hah... Hah...>"
  },
  AvgDialog_131213_Content_27 = {
    Text = "¡Ay, qué lástima, nuestro fiel pequeño creyente..."
  },
  AvgDialog_131213_Content_28 = {
    Text = "Nefruri se acercó a ti, acariciando con preocupación tu rostro empapado de sudor."
  },
  AvgDialog_131213_Content_29 = {
    Text = "Está bien, {Male=Mr.,Female=Miss} Guardián. ¿Lo ves? Nuestro Apóstol ya ha revelado Su forma..."
  },
  AvgDialog_131213_Content_3 = {
    Text = "Los hilos del destino tiran suavemente, las suelas de la marioneta chocan contra el escenario, produciendo un sonido claro."
  },
  AvgDialog_131213_Content_30 = {
    Text = "Levantas la cabeza con dolor. La luz de la rueca comienza a reunirse, y una figura ilusoria en constante cambio aparece sobre la luz."
  },
  AvgDialog_131213_Content_31 = {
    Text = "No tienen rostro ni forma. Son el heraldo fiel de lo Divino, contemplando el vacío hacia el Dios dormido."
  },
  AvgDialog_131213_Content_32 = {
    Text = "Su mirada es una invitación. Bajo esa mirada imperturbable, una escalera que conecta con el lugar de reposo del Dios toma forma lentamente..."
  },
  AvgDialog_131213_Content_33 = {
    Text = "<Shake:Funcionó... ¡funcionó!> El pasaje al Plano Superior se está abriendo... El Dios está a punto de despertar..."
  },
  AvgDialog_131213_Content_34 = {
    Text = "Hermana, ¿lo viste? Tu red, pronto estará terminada..."
  },
  AvgDialog_131213_Content_35 = {
    Text = "Nefruri miraba con alegría el pasaje que se volvía cada vez más claro, con una sonrisa y lágrimas apareciendo simultáneamente en su rostro."
  },
  AvgDialog_131213_Content_36 = {Text = "@2...@3..."},
  AvgDialog_131213_Content_37 = {
    Text = "El teatro comenzó a temblar violentamente. El escenario se estaba desmoronando, la dimensión temblaba. Todos los destinos temen y se rinden ante esta gran llegada."
  },
  AvgDialog_131213_Content_38 = {
    Text = "La Orden de gran peso en tu interior se ha reducido a casi nada. El poder del plásmido ha sido absorbido por el cuerpo del Apóstol. Su brillo es demasiado intenso para contemplarlo; Su existencia es absolutamente innegable."
  },
  AvgDialog_131213_Content_39 = {
    Text = "Bajo la tranquila mirada de Arachne, en medio de los temblores del destino, Él está a punto de llegar a este escenario final—"
  },
  AvgDialog_131213_Content_4 = {
    Text = "¡Ah, queridos espectadores, el momento tan esperado está a punto de llegar! ¡Demos la bienvenida con un fuerte aplauso a nuestro protagonista, que brilla en el escenario! ¡Oh"
  },
  AvgDialog_131213_Content_40 = {
    Text = "En... nombre de @2... creyente @3..."
  },
  AvgDialog_131213_Content_41 = {
    Text = "Habla, apóstol... ¿qué quieres decirme? ¿Es tu deseo? ¿O las palabras de esa persona divina?"
  },
  AvgDialog_131213_Content_42 = {
    Text = "¿Qué orden tiene Él para transmitir a este mundo? ¿Desea romper estos escenarios? ¿O quiere que estas marionetas se unan para recibir Su llegada?"
  },
  AvgDialog_131213_Content_43 = {
    Text = "¡Dime, mi querido Apóstol! Qué bestia tan peligrosa y adorable eres, que solo sabes arrancar y destruir... dime qué deseas..."
  },
  AvgDialog_131213_Content_44 = {
    Text = "Recitar @2......mi nombre......Despertar @2......@3 Primordial......"
  },
  AvgDialog_131213_Content_45 = {
    Text = "Ah, tu nombre, ¡exactamente...! ¡Recitaré tu nombre! Te traeré todo lo que deseas devorar, lo pondré en tu boca. Te abriré esta prisión..."
  },
  AvgDialog_131213_Content_46 = {
    Text = "Mi nombre es... @2..."
  },
  AvgDialog_131213_Content_47 = {
    Text = "La voz del Apóstol era turbia y confusa, Nefruri se dirigió hacia la columna de luz que se hacía cada vez más brillante, sin siquiera mirarte, temblando de dolor."
  },
  AvgDialog_131213_Content_48 = {
    Text = "El Fervor la llena de asombro y risa mientras se acerca a la gran figura. Su respiración se entrecorta de euforia."
  },
  AvgDialog_131213_Content_49 = {
    Text = "Ella acarició la luz verde tenue, tocando a esta magnífica bestia que devorará todo. Se convertirá en el primer alimento de la bestia, sin dudarlo, dulce como la miel."
  },
  AvgDialog_131213_Content_5 = {
    Text = "Nefruri levantó la mano, como si una red de fuegos artificiales se deslizara y cayera. Estás en el centro del escenario, con la tenue luz iluminando tu rostro."
  },
  AvgDialog_131213_Content_50 = {
    Text = "¡Es ahora, apóstol... Dime, dile al mundo, ¡tu nombre"
  },
  AvgDialog_131213_Content_51 = {
    Text = "Mi nombre es... @2..."
  },
  AvgDialog_131213_Content_52 = {
    Text = "Mi nombre es... <Red:%player%>..."
  },
  AvgDialog_131213_Content_53 = {
    Text = "Mi nombre es... <Yellow:%player%>!"
  },
  AvgDialog_131213_Content_54 = {Text = "¡!!!"},
  AvgDialog_131213_Content_55 = {
    Text = "El tiempo se detiene en este momento. Los hilos del destino se funden y colapsan en los ojos de Nefruri, y el destino en ruinas se asemeja a un vórtice rugiente en el océano, arrastrándola y devorándola."
  },
  AvgDialog_131213_Content_56 = {
    Text = "<Shake:¿Qué es... qué está pasando?!!>"
  },
  AvgDialog_131213_Content_57 = {
    Text = "El vórtice se calma, el vasto océano se recoge, las gotas de agua se reconstituyen en hilos, y la red que han elaborado ya es de una forma que Nefruri nunca había previsto."
  },
  AvgDialog_131213_Content_58 = {
    Text = "¿No lo entiendes, Nefruri? Rinde culto con devoción a tu Apóstol. El Apóstol que has pedido ya está de pie frente a ti."
  },
  AvgDialog_131213_Content_59 = {
    Text = "Estás de pie frente a Nefruri, mirando el pasillo que conecta con el templo de Toguwaibo, observando esa figura suprema, y sonríes."
  },
  AvgDialog_131213_Content_6 = {
    Text = "Vamos, {Male=Mr.,Female=Miss} Guardián. Nuestro acto final comienza..."
  },
  AvgDialog_131213_Content_60 = {
    Text = "El poder de los tres plásmidos fluye desenfrenadamente dentro de ti, pero ya no te causa dolor. La luz del huso, con su voluntad suprema, inunda tu cuerpo como un océano, fusionándose con el poder de los tres plásmidos."
  },
  AvgDialog_131213_Content_61 = {
    Text = "Sientes que la figura de esa persona se superpone a tu cuerpo. Te sientes abrumado. Te sientes infinito. Te sientes libre. Te sientes... un placer supremo."
  },
  AvgDialog_131213_Content_62 = {
    Text = "¿Tú... robaste el destino del Apóstol?!"
  },
  AvgDialog_131213_Content_63 = {
    Text = "Jejejejeje... ¡jajajaja! ¿La tercera escena de la historia, llegada?... Ja, ja, ja. La tercera escena, no hay duda. Pero esta no es tu historia, querida Nefruri."
  },
  AvgDialog_131213_Content_64 = {
    Text = "Yo soy quien escribe este acto. Y lo llamo... <Big:<color=#98918C>Éxtasis</color>>!"
  },
  AvgDialog_131213_Content_65 = {
    Text = "<Shake:Tú... todos vosotros...>"
  },
  AvgDialog_131213_Content_66 = {
    Text = "No, eso es imposible... puedo ver tu destino... eso no puede ser..."
  },
  AvgDialog_131213_Content_67 = {
    Text = "<color=#EE4D0C><Italic:\"Oh, mi querido Duque, ¿por qué esa cara larga? ¡Deja que tu bufón restaure esa preciosa sonrisa!\"></color>"
  },
  AvgDialog_131213_Content_68 = {
    Text = "<color=#BF0909><Italic:\"¡Míralo —el cruel destino, la perversa maldición... qué espectáculo tan ridículo! ¡Qué mentira tan dulce y deliciosa!\"></color>"
  },
  AvgDialog_131213_Content_69 = {
    Text = "<color=#FC1818><Italic:\"Así es como termina la historia del villano... ¡la única recompensa para la malicia es el Éxtasis!\"></color>"
  },
  AvgDialog_131213_Content_7 = {
    Text = "¡He nombrado esta escena como——\"Llegada\""
  },
  AvgDialog_131213_Content_70 = {
    Text = "Un estruendoso aplauso estalla desde los asientos vacíos. Luces brillantes inundan el escenario en ruinas. Eres el eje del mundo, el amo de la Singularidad. \nExtiendes los brazos. Declaras que el Destino se inclinará ante ti. Declaras que esta actuación es una obra maestra."
  },
  AvgDialog_131213_Content_71 = {
    Text = "Engaño. Manipulación. Puro disfrute... <Shake:Jeje... <Big:¡¡JAJAJAJAJA!!>> Qué espectáculo tan delicioso, pequeña araña."
  },
  AvgDialog_131213_Content_72 = {
    Text = "<Shake:Tú... es imposible que tengas el poder de alterar el Destino...>"
  },
  AvgDialog_131213_Content_73 = {
    Text = "Aww... No, no, no. Ese esfuerzo es para gente como tú. Un devoto del Éxtasis jamás se rebajaría a semejante labor."
  },
  AvgDialog_131213_Content_74 = {
    Text = "<Shake:Vi el final... ¡Se suponía que entregarías tu Orden de gran peso! <Big:¡Se suponía que verías el pasaje abrirse y morirías en este escenario! ¿¡POR QUÉ?!>>"
  },
  AvgDialog_131213_Content_75 = {
    Text = "El que controla el destino lo sabe todo, excepto lo que es la alegría. Porque, porque el que disfruta no tiene destino, querido..."
  },
  AvgDialog_131213_Content_76 = {
    Text = "Te inclinas y admiras los temblorosos ojos de Nefruri. El dolor y la desesperación que brillan en ellos nutren cada centímetro de tu cuerpo."
  },
  AvgDialog_131213_Content_77 = {
    Text = "Toda nuestra vida está en la búsqueda de la alegría. Sin la alegría, no tenemos nada... Quien busca la alegría, no tiene destino."
  },
  AvgDialog_131213_Content_78 = {
    Text = "Lo que ves es un truco de salón. Una pequeña broma que el nuevo yo, bendecido con la voluntad y el poder de un Dios, le jugó a mi yo pasado y al Destino."
  },
  AvgDialog_131213_Content_79 = {
    Text = "¿Para qué controlar el Destino cuando puedes burlarte de él? ¿No es así, Executor del Destino?"
  },
  AvgDialog_131213_Content_8 = {
    Text = "Llegada. Detrás del escenario, una tela de araña viscosa teje esta enorme y aterradora palabra. Nefruri toma una profunda respiración y abre los brazos."
  },
  AvgDialog_131213_Content_80 = {
    Text = "Intentas mantener un tono serio, pero no puedes reprimir tu risa maníaca."
  },
  AvgDialog_131213_Content_81 = {
    Text = "¿Eres el Guardián? ¿Eres \"N\"? No lo sabes, y no te importa. La esencia del Éxtasis inunda la voluntad del Apóstol, llenando cada célula de tu cuerpo."
  },
  AvgDialog_131213_Content_82 = {
    Text = "Quieres aullar de risa. Quieres vitorear. Quieres someter a este manipulador fracasado a la más tierna y devastadora humillación."
  },
  AvgDialog_131213_Content_83 = {
    Text = "Encontraste la llave que abre la cerradura. Te das la vuelta y haces una elegante reverencia hacia esa persona que organiza el entorno."
  },
  AvgDialog_131213_Content_84 = {
    Text = "¡Arachne, gran dramaturga! Desde el primer momento en que llegué a este mundo, has estado tejiendo este escenario para mí"
  },
  AvgDialog_131213_Content_85 = {
    Text = "Llévame a ver cómo funciona el destino, déjame disfrutar del encanto de la burla, cuéntame el secreto de la \"Alegría\"..."
  },
  AvgDialog_131213_Content_86 = {
    Text = "Ahora, la cerradura de \"Alegría\" se ha abierto. ¿Qué tal, este actor, estás satisfecho?"
  },
  AvgDialog_131213_Content_87 = {
    Text = "Solo soy el constructor del escenario, la escritura de la historia depende de ti mismo."
  },
  AvgDialog_131213_Content_88 = {
    Text = "Le abriste la boca. Eres el apóstol de los dioses. Eres el esclavo de la alegría. Eres el único amo indiscutible de este mundo. Levantaste la mano, tocando suavemente como un director de orquesta."
  },
  AvgDialog_131213_Content_89 = {
    Text = "Como recompensa... ahora, ponte tu disfraz, Arachne. ¡Este espectáculo, pronto será tu momento de actuar"
  },
  AvgDialog_131213_Content_9 = {
    Text = "Apóstol del dios supremo, mensajero de la locura del caos. Tu resplandor ilumina la prisión eterna, he escuchado tu llamado al caos."
  },
  AvgDialog_131213_Content_90 = {
    Text = "Pulsas los Hilos antes invisibles como si movieras bloques en una guardería."
  },
  AvgDialog_131213_Content_91 = {
    Text = "A medida que la trama se reconfigura, las Cenizas de Dimensión robadas vuelan de regreso a ella."
  },
  AvgDialog_131213_Content_92 = {
    Text = "La arena fina de color púrpura oscuro y sin fin fluye al lado de Arachne, girando a su alrededor. En tu creación, aquellas cosas nunca han sido robadas por la Ceniza de Dimensión."
  },
  AvgDialog_131213_Content_93 = {
    Text = "<color=#8C7E96>En el pasado, en el futuro, siempre pertenecen a Arachne.</color>"
  },
  AvgDialog_131213_Content_94 = {
    Text = "Arachne te sonríe y asiente, ocultando las cenizas en su propio cuerpo. Su rueca nunca se detiene. Su sonrisa nunca cambia."
  },
  AvgDialog_131213_Content_95 = {
    Text = "Sacudes la cabeza en el escenario y sueltas un suspiro exagerado."
  },
  AvgDialog_131213_Content_96 = {
    Text = "muerto de tristeza, sin ninguna pasión... podrías haber sido una persona tan interesante, Arachne."
  },
  AvgDialog_131213_Content_97 = {
    Text = "Tú, al igual que Tawil, eres un voyeur del destino y también un esclavo del destino. La felicidad que siento ahora, ustedes nunca podrán experimentarla."
  },
  AvgDialog_131213_Content_98 = {
    Text = "Mira tu rostro sin vida, Arachne. Realmente siento lástima por ustedes."
  },
  AvgDialog_131213_Content_99 = {
    Text = "Todos hacen su elección, %player%... ¿o debería llamarte el Apóstol? ¿O quizás... \"N\"?"
  },
  AvgDialog_131214_Content_1 = {
    Text = "<Shake:¡¡AAAAARGH!!>"
  },
  AvgDialog_131214_Content_10 = {
    Text = "Porque... nuestra venganza, aún no ha terminado, nunca terminará..."
  },
  AvgDialog_131214_Content_11 = {
    Text = "Retrocediste un paso instintivamente. Pero no había ninguna fluctuación peligrosa en el cuerpo de Nefruri."
  },
  AvgDialog_131214_Content_12 = {
    Text = "Ella solo movió sus pinzas, desgarro el telón que cubría a su lado, revelando la escena detrás del telón."
  },
  AvgDialog_131214_Content_13 = {Text = "¡Esto...!"},
  AvgDialog_131214_Content_14 = {
    Text = "El hilo carmesí conecta varios escenarios en el teatro, conecta esta majestuosa ciudad donde se encuentra el teatro, conecta innumerables marionetas en la ciudad, fluyendo hacia el cuerpo desgastado de Nefruri."
  },
  AvgDialog_131214_Content_15 = {
    Text = "¿Tú... no conectaste el hilo a la rueca?"
  },
  AvgDialog_131214_Content_16 = {
    Text = "Ella ya ha visto el final. Ella vio su fracaso. Cuando aún tenía poder, ató estos destinos a sí misma, como..."
  },
  AvgDialog_131214_Content_17 = {
    Text = "Así como cuando me mataste la primera vez."
  },
  AvgDialog_131214_Content_18 = {
    Text = "Nefruri sonriendo, levantó un hilo muy oculto frente a ella."
  },
  AvgDialog_131214_Content_19 = {
    Text = "Ese hilo carmesí se extiende desde la parte posterior de su cabeza, y tras una larga y cuidadosa travesía, se une secretamente al interior de Arachne."
  },
  AvgDialog_131214_Content_2 = {Text = "¡Boom—"},
  AvgDialog_131214_Content_20 = {
    Text = "Hace mucho tiempo que no estábamos tan cerca, hermana. Hasta ahora, he encontrado la oportunidad de devolverte este hilo."
  },
  AvgDialog_131214_Content_21 = {
    Text = "\"¿volver\"......?"
  },
  AvgDialog_131214_Content_22 = {
    Text = "Este hilo... es el que corté la primera vez que destruí mi reliquia."
  },
  AvgDialog_131214_Content_23 = {
    Text = "Tu romanticismo, tu bondad, tus recuerdos... Todo lo que hay en mí ya te ha sido devuelto."
  },
  AvgDialog_131214_Content_24 = {
    Text = "Has completado, Arachne."
  },
  AvgDialog_131214_Content_25 = {
    Text = "La comisura de los labios de Nefruri se curvó, como un niño que se esconde detrás de una cortina, observando a los adultos ser objeto de sus travesuras."
  },
  AvgDialog_131214_Content_26 = {
    Text = "¿En esos momentos en que tienes poder... es esto lo que quieres hacer?"
  },
  AvgDialog_131214_Content_27 = {
    Text = "¿Qué tal? ¡Es una idea brillante, ¿no?"
  },
  AvgDialog_131214_Content_28 = {
    Text = "¡Vamos, mátame! ¡Destruye por completo esos destinos que alguna vez abandonaste! ¡Destruye esta ciudad donde te refugias, destruye este teatro que amas, destruye a cada persona aquí"
  },
  AvgDialog_131214_Content_29 = {
    Text = "¡Ven, Arachne! Trae toda tu debilidad, <Shake:¡Mata de nuevo todo lo que amas!!!>"
  },
  AvgDialog_131214_Content_3 = {
    Text = "Los gritos de dolor y los ecos de la destrucción resonaron en el teatro roto. Los hilos carmesí se rompían poco a poco, y la rueca que había acompañado a Nefruri durante toda su vida cayó ante ella."
  },
  AvgDialog_131214_Content_30 = {
    Text = "El grito y la risa eufórica de Nefruri resonaban en el teatro destrozado."
  },
  AvgDialog_131214_Content_31 = {
    Text = "El cuerpo de Arachne parecía volverse más pesado que nunca. Ella giraba lentamente su cabeza, mirando todo lo que estaba conectado con Nefruri."
  },
  AvgDialog_131214_Content_32 = {
    Text = "A través de la grieta del teatro, vio coches y multitudes llenando esta próspera ciudad. Esas caras familiares llevaban nombres familiares, esparcidos en cada rincón que le era conocido."
  },
  AvgDialog_131214_Content_33 = {
    Text = "Ella vio el escenario en el que una vez subiste con ella. La cruel guerra ha terminado, y ese mundo está a punto de disfrutar de doscientos años de gloriosa paz."
  },
  AvgDialog_131214_Content_34 = {
    Text = "En aquella baba negra, vio el rostro de su madre. Ella estaba sentada con su padre debajo del abeto blanco en el patio, llamándola."
  },
  AvgDialog_131214_Content_35 = {
    Text = "El Señor Lawrence permanece a su lado, limpiando los cubiertos elaborados especialmente para ella."
  },
  AvgDialog_131214_Content_36 = {
    Text = "Llamas a esto venganza porque nunca has visto claramente el destino, ni has visto claramente a mí, Nefruri."
  },
  AvgDialog_131214_Content_37 = {
    Text = "Un hilo cubierto de slime conecta a Arachne con el escenario roto bajo los pies de Nefruri. Arrastrando su pesado cuerpo, Arachne pisa ese hilo frágil."
  },
  AvgDialog_131214_Content_38 = {
    Text = "El hilo tiembla como si fuera a romperse y arrojar al Prisionero del Destino al abismo."
  },
  AvgDialog_131214_Content_39 = {
    Text = "Arachne miraba tranquilamente los ojos sorprendidos de Nefruri. Sus pasos nunca habían cesado ni un instante."
  },
  AvgDialog_131214_Content_4 = {
    Text = "Ella se aferra al huso como un bebé que se hunde en el agua. En sus manos, el huso oscuro se desmorona imparablemente, convirtiéndose en la ceniza de la dimensión, que se une a la arena movediza junto a Arachne."
  },
  AvgDialog_131214_Content_40 = {
    Text = "El momento destinado está por llegar..."
  },
  AvgDialog_131214_Content_41 = {
    Text = "Arachne en la telaraña levanta la rueca en su mano. Puedes ver claramente cómo todo el mundo se detuvo por un momento, y todo el universo conectado a este teatro está esperando su orden."
  },
  AvgDialog_131214_Content_42 = {
    Text = "¡En mi nombre del destino, ahora lo declaro—!"
  },
  AvgDialog_131214_Content_43 = {
    Text = "Todos los destinos erróneos serán sepultados en el polvo del tiempo. El destino del mundo retornará a su curso previsto."
  },
  AvgDialog_131214_Content_44 = {
    Text = "El destino equivocado termina aquí. Los abandonados hallarán descanso..."
  },
  AvgDialog_131214_Content_45 = {
    Text = "La rueca se inclina, miles de hilos temblando."
  },
  AvgDialog_131214_Content_46 = {
    Text = "Se rompe el hilo. Esperando el escenario de paz, se desmorona y se disipa."
  },
  AvgDialog_131214_Content_47 = {
    Text = "El hilo se rompió. En la grieta del teatro, ya no se puede ver la sombra de la ciudad."
  },
  AvgDialog_131214_Content_48 = {
    Text = "Hilos rotos, rotos, rotos..."
  },
  AvgDialog_131214_Content_49 = {
    Text = "Te resulta difícil ver los hilos del destino, pero puedes escuchar claramente el llanto del destino."
  },
  AvgDialog_131214_Content_5 = {
    Text = "Nefruri miraba atónita esa Esperanza que se desvanecía, de repente comenzó a reírse."
  },
  AvgDialog_131214_Content_50 = {
    Text = "Las vidas pasadas y presentes de innumerables personas, las innumerables alegrías y tristezas se rompen, descomponen, reconstruyen y aniquilan a tu alrededor..."
  },
  AvgDialog_131214_Content_51 = {Text = "...¿luz?"},
  AvgDialog_131214_Content_52 = {
    Text = "Las luces del escenario, que no se sabe de dónde provienen, se encienden. La luz atraviesa el destrozado teatro, y aquellos abandonados que se agachaban en la sombra desaparecen en el momento en que la luz cae, como si nunca hubieran existido."
  },
  AvgDialog_131214_Content_53 = {
    Text = "Arachne, hermana, tú..."
  },
  AvgDialog_131214_Content_54 = {
    Text = "Arachne, llevando el huso giratorio, cruzó la frágil línea de hilo y se acercó a ella. Nefruri la miró hacia arriba, como si estuviera mirando el destino mismo, irreversible."
  },
  AvgDialog_131214_Content_55 = {
    Text = "Acércate a mí, Nefruri."
  },
  AvgDialog_131214_Content_56 = {
    Text = "Arachne tomó la mano de Nefruri y la presionó contra su mejilla."
  },
  AvgDialog_131214_Content_57 = {
    Text = "En el momento en que tocó a Arachne, una puerta oculta se abrió hacia Nefruri. Nefruri atravesó esas capas de jaulas y, por primera vez, se encontró realmente frente a Arachne."
  },
  AvgDialog_131214_Content_58 = {
    Text = "En esa jaula, ella vio tres rostros familiares."
  },
  AvgDialog_131214_Content_59 = {
    Text = "¡Arachne!!! tú..."
  },
  AvgDialog_131214_Content_6 = {
    Text = "Su risa se hacía cada vez más fuerte, casi sin fuerzas para levantarse. La sangre caía de su cuerpo tembloroso, tiñendo los fragmentos oscuros de la rueca."
  },
  AvgDialog_131214_Content_60 = {
    Text = "<Shake:\"Romántico\", Bondad, Homenaje... ellos... ellos...>"
  },
  AvgDialog_131214_Content_61 = {
    Text = "Nunca he podido deshacerme de ellos por completo. Nunca he podido deshacerme de ti realmente."
  },
  AvgDialog_131214_Content_62 = {
    Text = "Pero dijiste que no podías soportar esto..."
  },
  AvgDialog_131214_Content_63 = {
    Text = "Estúpido, frágil, destruyendo dolorosamente todo lo que valoro... no puedes vengarte de mí así, Nefruri."
  },
  AvgDialog_131214_Content_64 = {
    Text = "Porque esta es la pena que el destino ya ha dictado para mí."
  },
  AvgDialog_131214_Content_65 = {
    Text = "Arachne le sonríe tranquilamente. Su rueca gira, eternamente."
  },
  AvgDialog_131214_Content_66 = {
    Text = "Ha terminado, Nefruri."
  },
  AvgDialog_131214_Content_67 = {
    Text = "Una cuerda de guitarra vibró suavemente. Nefruri escuchó el llanto de una garza, como cuando era muy, muy pequeña, el día en que su padre le trajo la rueca llamada Moira."
  },
  AvgDialog_131214_Content_68 = {
    Text = "Esta es su habitación, el abeto blanco fuera de la ventana es su amigo fiel, un prisionero solitario inmutable a lo largo de los tiempos."
  },
  AvgDialog_131214_Content_69 = {
    Text = "Están prisioneros del destino, dependen el uno del otro aquí."
  },
  AvgDialog_131214_Content_7 = {
    Text = "El final, el final realmente no se puede cambiar... así es el destino..."
  },
  AvgDialog_131214_Content_70 = {
    Text = "Creak—Yaa—"
  },
  AvgDialog_131214_Content_71 = {
    Text = "La puerta de madera sencilla se abrió, Arachne se acercó a ella, se inclinó y le acarició suavemente la cara."
  },
  AvgDialog_131214_Content_72 = {
    Text = "Hermana... perdí... hemos perdido..."
  },
  AvgDialog_131214_Content_73 = {
    Text = "Nunca tuvimos el derecho de ganar."
  },
  AvgDialog_131214_Content_74 = {
    Text = "¿Recuerdas el deseo que hicimos el día que recibimos la rueda del destino?"
  },
  AvgDialog_131214_Content_75 = {
    Text = "\"No desperdiciaré los dones del Destino... Traeré un hermoso destino a este mundo...\""
  },
  AvgDialog_131214_Content_76 = {
    Text = "Qué deseo tan infantil, Arachne... En ese momento, realmente no entendíamos lo que significaba."
  },
  AvgDialog_131214_Content_77 = {
    Text = "Arachne extendió su mano ligeramente temblorosa, acariciando el rostro lejano de sí misma."
  },
  AvgDialog_131214_Content_78 = {
    Text = "Destino... ¿quién puede verlo claramente."
  },
  AvgDialog_131214_Content_79 = {
    Text = "Pero incluso si puedo preverlo, mi elección seguirá siendo la misma."
  },
  AvgDialog_131214_Content_8 = {
    Text = "Esta trágica victoria, ya la habías visto, ¿verdad, Arachne?"
  },
  AvgDialog_131214_Content_80 = {
    Text = "<Shake:¿Por qué, Arachne?> Puedes irte, puedes liberar, puedes..."
  },
  AvgDialog_131214_Content_81 = {
    Text = "Después de dejar el abismo, podrías haber tenido libertad eterna. Sabes que al final fracasarás, pero aún así vienes a intentar traer liberación para mí y para aquellos que siguen tu destino."
  },
  AvgDialog_131214_Content_82 = {
    Text = "Cada manipulador del destino se convertirá en un prisionero del destino, tú y yo lo somos así. ¿No es así, Nefruri?"
  },
  AvgDialog_131214_Content_83 = {
    Text = "Nefruri permanecía en silencio, mirando con tristeza hacia el abeto blanco fuera de la ventana. Observaba cómo el árbol brotaba, germinaba, crecía y se marchitaba."
  },
  AvgDialog_131214_Content_84 = {
    Text = "Ella suspiró suavemente, levantó la cabeza y acarició las lágrimas que caían lentamente por el rostro de Arachne. Ella le sonrió."
  },
  AvgDialog_131214_Content_85 = {
    Text = "Es genial verte de nuevo... hermana."
  },
  AvgDialog_131214_Content_86 = {
    Text = "Una lágrima cayó suavemente, cayendo sobre esa cara idéntica a la de Arachne."
  },
  AvgDialog_131214_Content_87 = {
    Text = "Perdona mi egoísmo..."
  },
  AvgDialog_131214_Content_88 = {
    Text = "Tú... eres libre, <Red:\"Arachne\">."
  },
  AvgDialog_131214_Content_89 = {Text = "Crujido."},
  AvgDialog_131214_Content_9 = {
    Text = "Recientemente, también has mirado furtivamente todo esto por un breve momento. Dado que ya conoces el final, ¿por qué seguir aferrándote a esto?"
  },
  AvgDialog_131214_Content_90 = {
    Text = "Cuando el último hilo se rompe, estalla una estruendosa ovación."
  },
  AvgDialog_131214_Content_91 = {
    Text = "Siempre vacía, la zona frente al escenario ya no tiene asientos libres. Los destinos abandonados y las muñecas que murieron en sus manos llenan cada uno de los rotos asientos de terciopelo."
  },
  AvgDialog_131214_Content_92 = {
    Text = "Los actores ocupan sus lugares entre el público, contemplando en silencio el desenlace en este escenario destrozado."
  },
  AvgDialog_131214_Content_93 = {
    Text = "Ellos no muestran expresión, en silencio. \n Aplauden con entusiasmo. Los aplausos resuenan como truenos, sin cesar."
  },
  AvgDialog_131215_Content_1 = {
    Text = "La actriz interior"
  },
  AvgDialog_131215_Content_10 = {
    Text = "Antes no entendía por qué Arachne quería eliminar a su hermana de la Red del destino, y por qué tú querías obtener poder de esos tres objetos secretos."
  },
  AvgDialog_131215_Content_100 = {Text = "..."},
  AvgDialog_131215_Content_101 = {
    Text = "La diosa del destino, resiliente y fútil... ¡Qué desesperación, qué imagen tan hermosa!"
  },
  AvgDialog_131215_Content_102 = {
    Text = "¿Por qué dicen que ella hace esto?"
  },
  AvgDialog_131215_Content_103 = {
    Text = "Nefruri miraba fijamente este escenario sencillo, su voz tan baja como un murmullo."
  },
  AvgDialog_131215_Content_104 = {
    Text = "Esto es solo un sueño, la diosa del destino... Podrías elegir el destino más alegre para todos, podrías corregir tus fantasías poco realistas y satisfacer todo lo que deseas."
  },
  AvgDialog_131215_Content_105 = {
    Text = "Pero nunca has pensado en hacer esto... Al crear la perfección, también estás creando dolor. Una y otra vez, haces que el dolor llegue a este mundo."
  },
  AvgDialog_131215_Content_106 = {
    Text = "Hiciste todo lo posible para tejer esa gran red del destino, pero la escena dentro de esa puerta, el desenlace que está destinado, ambos lo hemos visto."
  },
  AvgDialog_131215_Content_107 = {
    Text = "En el momento en que se teje la red del destino, es cuando esa persona suprema despierta por completo..."
  },
  AvgDialog_131215_Content_108 = {
    Text = "¿Qué...?!"
  },
  AvgDialog_131215_Content_109 = {
    Text = "Miras a Arachne, esperando obtener una respuesta negativa de su rostro."
  },
  AvgDialog_131215_Content_11 = {
    Text = "Al menos, debo agradecerte por aclarar mis dudas."
  },
  AvgDialog_131215_Content_110 = {
    Text = "Solo encuentras su calma habitual, eterna. En el escenario del Destino, la serenidad es una máscara que no puede quitarse."
  },
  AvgDialog_131215_Content_111 = {
    Text = "Hermana, no puedes dejar de tejer, porque no soportas ver el universo caer en el caos. Pero el día en que tu red esté terminada, serás tú quien entierre con tus propias manos todo lo que amas."
  },
  AvgDialog_131215_Content_112 = {
    Text = "Qué ironía, Arachne. ¿Por qué? ¿Por qué no dejar que este universo reciba el fin predestinado con alegría?"
  },
  AvgDialog_131215_Content_113 = {
    Text = "Todo destino tiene un número fijo. Todo destino tiene una variable. Estos dos proverbios contradictorios son la esencia del destino."
  },
  AvgDialog_131215_Content_114 = {
    Text = "Arachne miró a los ojos de Nefruri y respondió a esta pregunta que se había hecho innumerables veces."
  },
  AvgDialog_131215_Content_115 = {
    Text = "Nefruri, en la dimensión infinita, aún hay innumerables personas luchando por esa variable."
  },
  AvgDialog_131215_Content_116 = {
    Text = "Mantener el funcionamiento del escenario, esperando la aparición de variables... Esta es la esclavitud que el destino me ha impuesto. Este es mi deber del que no puedo escapar."
  },
  AvgDialog_131215_Content_117 = {
    Text = "Deberes, peligros... hablas de toda esa grandeza, pero nunca hablas de ti misma, Arachne, mi pobre hermana. Pero no te preocupes, tu doloroso deber está a punto de terminar."
  },
  AvgDialog_131215_Content_118 = {
    Text = "Nefruri acarició con ternura el rostro de Arachne, mostrándole una dulce sonrisa."
  },
  AvgDialog_131215_Content_119 = {
    Text = "En el abismo, he imaginado innumerables veces la escena de nuestro reencuentro. He estado pensando en qué regalo podría estar a la altura de este reencuentro."
  },
  AvgDialog_131215_Content_12 = {
    Text = "¿Por qué no me dijiste antes sobre estas cosas?"
  },
  AvgDialog_131215_Content_120 = {
    Text = "He pensado durante mucho, mucho tiempo. ¡He pensado en ti, querida hermana! Este es el mejor regalo que puedo darte——"
  },
  AvgDialog_131215_Content_121 = {
    Text = "Te concedo... <Red:Liberación.>"
  },
  AvgDialog_131215_Content_122 = {
    Text = "En las suaves palabras de Nefruri, una sustancia pegajosa negra se acumula entre las grietas de la dimensión. Al final de la telaraña, un gran escenario aparece ante ustedes."
  },
  AvgDialog_131215_Content_13 = {
    Text = "Miras a tu lado a Arachne, que guía tus pasos."
  },
  AvgDialog_131215_Content_14 = {
    Text = "Una piedra que no provocará ninguna ola en el lago del destino, no tiene ningún uso más que perturbar la paz del lago."
  },
  AvgDialog_131215_Content_15 = {
    Text = "Ella y yo nos convertimos en dos personas separadas hace mucho tiempo, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131215_Content_16 = {
    Text = "¿Has anticipado este día?"
  },
  AvgDialog_131215_Content_17 = {
    Text = "Ningún prisionero ve su propio destino hasta que se dicta el veredicto."
  },
  AvgDialog_131215_Content_18 = {
    Text = "Si sabes que esos destinos abandonados no desaparecerán, sino que serán exiliados al abismo eterno... ¿aún harías estas cosas, Arachne?"
  },
  AvgDialog_131215_Content_19 = {Text = "..."},
  AvgDialog_131215_Content_2 = {
    Text = "La la la la..."
  },
  AvgDialog_131215_Content_20 = {
    Text = "Silencio. El silencio es la catástrofe eterna del dramaturgo. El silencio es la defensa impotente del prisionero. En un silencio de pena extrema, resuena la risa loca de Nefruri."
  },
  AvgDialog_131215_Content_21 = {
    Text = "Ah, por supuesto que lo harás, hermana. El destino es tu doctrina, todas, todas las condiciones no pueden cambiar su única respuesta."
  },
  AvgDialog_131215_Content_22 = {
    Text = "La diosa del destino, cuán insignificante, cuán frágil, cuán cruel..."
  },
  AvgDialog_131215_Content_23 = {
    Text = "Pero no importa. Hagas lo que hagas, durante todo este largo tiempo, siempre he estado preocupada por ti, mi querida hermana."
  },
  AvgDialog_131215_Content_24 = {
    Text = "Romántico, bondadoso, recuerdos. Una hermosa mezcla de ingredientes, fermentándose, que convierte la sonrisa de Nefruri en un dulce veneno."
  },
  AvgDialog_131215_Content_25 = {
    Text = "En su brillante sonrisa, la luz junto al camino de telarañas iluminó el escenario."
  },
  AvgDialog_131215_Content_26 = {
    Text = "Hermana, {Male=Mr.,Female=Miss} Guardián... estas nuevas obras son un regalo de mi parte, la nueva ama del teatro."
  },
  AvgDialog_131215_Content_27 = {
    Text = "Antes de la grandiosa tercera actuación, disfruta bien de esta maravillosa obertura... ¡Recuerda las normas de etiqueta del teatro del destino y no hables"
  },
  AvgDialog_131215_Content_28 = {
    Text = "Nefruri como un Anunciador abre sus brazos. El escenario, brillante como un sinfín de estrellas, se ilumina uno a uno mientras ustedes pasan lentamente."
  },
  AvgDialog_131215_Content_29 = {Text = "..."},
  AvgDialog_131215_Content_3 = {
    Text = "Danzan. Cantan. ¡Crujido, crujido!"
  },
  AvgDialog_131215_Content_30 = {
    Text = "Querida diosa del destino, los cuerpos de las tres secretas ya están preparados para usted."
  },
  AvgDialog_131215_Content_31 = {
    Text = "Qué muñecas tan exquisitas... lo que se ha perdido volverá a reproducirse en ellas..."
  },
  AvgDialog_131215_Content_32 = {
    Text = "\"Arachne\" salió del telar y se acercó a la marioneta."
  },
  AvgDialog_131215_Content_33 = {
    Text = "La primera, te la doy como \"romántico\"."
  },
  AvgDialog_131215_Content_34 = {
    Text = "Eres el capítulo más apasionado de la obra, una colección de emociones, los frutos que brotan de las flores de la primavera."
  },
  AvgDialog_131215_Content_35 = {
    Text = "Irás al paraíso de medianoche, trayendo a esta ciudad vino, encuentros y una pasión que nunca se desvanecerá."
  },
  AvgDialog_131215_Content_36 = {
    Text = "Gracias a usted, gran diosa del destino Arachne. Según su voluntad, el vino y la miel fluirán entre mis labios y dientes."
  },
  AvgDialog_131215_Content_37 = {
    Text = "La hermosa mujer saludó a \"Arachne\"."
  },
  AvgDialog_131215_Content_38 = {
    Text = "La segunda, te concedo el \"bien\"."
  },
  AvgDialog_131215_Content_39 = {
    Text = "Eres el anciano que me acompañó durante mi infancia. Eres la pluma blanca que dejó un ángel, la luz del sol más sagrada."
  },
  AvgDialog_131215_Content_4 = {
    Text = "Una antigua historia y pasos alegres vibran juntos en la telaraña. Nefruri camina hacia adelante, saltando alegremente con las manos detrás de la espalda."
  },
  AvgDialog_131215_Content_40 = {
    Text = "Llegarás a las calles de la ciudad, calentando todo lo que veas con tu buena voluntad."
  },
  AvgDialog_131215_Content_41 = {
    Text = "¡Gracias! Gran diosa del destino Arachne. Mi vida es un regalo de usted, y no tengo cómo recompensarlo."
  },
  AvgDialog_131215_Content_42 = {
    Text = "No tengo nada, solo amo todo en este mundo. Protegeré lo que deba proteger y ayudaré a quienes deba ayudar."
  },
  AvgDialog_131215_Content_43 = {
    Text = "Todo lo mío está abierto a los sufrientes."
  },
  AvgDialog_131215_Content_44 = {
    Text = "El anciano bondadoso se inclina profundamente ante \"Arachne\"."
  },
  AvgDialog_131215_Content_45 = {
    Text = "Y tú, el tercer... te concedo el título de \"recuerdo\"."
  },
  AvgDialog_131215_Content_46 = {
    Text = "\"Arachne\" llegó frente a ese pequeño objeto secreto, se agachó y miró sus ojos inexistentes."
  },
  AvgDialog_131215_Content_47 = {
    Text = "Eres el huérfano del destino, enterrado entre las hojas secas de la profunda nieve."
  },
  AvgDialog_131215_Content_48 = {
    Text = "Caminas solo y penosamente, sin poder hablar, sin que el mundo lo sepa."
  },
  AvgDialog_131215_Content_49 = {
    Text = "En tu tranquila y larga vida, serás el único Guardián de esos recuerdos."
  },
  AvgDialog_131215_Content_5 = {
    Text = "Sigues a Arachne de manera irrevocable, avanzando por la telaraña hacia el final."
  },
  AvgDialog_131215_Content_50 = {
    Text = "La niña silenciosa levantó la cabeza y acarició suavemente el rostro de \"Arachne\"."
  },
  AvgDialog_131215_Content_51 = {
    Text = "\"Arachne\" se levantó y miró suavemente a sus objetos secretos."
  },
  AvgDialog_131215_Content_52 = {
    Text = "Vayan, mis niños. Ante el telar del destino, siempre los estaré observando."
  },
  AvgDialog_131215_Content_53 = {
    Text = "Aquellos que han sido abandonados por la eternidad, florecerán uno a uno en su destino."
  },
  AvgDialog_131215_Content_54 = {Text = "..."},
  AvgDialog_131215_Content_55 = {
    Text = "El escenario se oscurece. Con vuestros pasos, las luces del próximo escenario se encienden."
  },
  AvgDialog_131215_Content_56 = {
    Text = "La luz del sol no existe aquí. Viento, flores, nubes... Después de tres largos siglos, el calendario también ha dejado de existir..."
  },
  AvgDialog_131215_Content_57 = {
    Text = "Amo, ha llegado un nuevo abandonador."
  },
  AvgDialog_131215_Content_58 = {
    Text = "El oboe toca una floritura. Los andrajosos Abandonados aparecen."
  },
  AvgDialog_131215_Content_59 = {
    Text = "\"Nefruri\" se levantó y llegó al centro del escenario."
  },
  AvgDialog_131215_Content_6 = {
    Text = "Y bien, {Male=Mr.,Female=Miss} Guardián, ¿fue espectacular la actuación? ¿Especialmente con ese vistazo entre bastidores?"
  },
  AvgDialog_131215_Content_60 = {
    Text = "Dímelo, pobres niños... ¿quiénes son ustedes y de dónde vienen?"
  },
  AvgDialog_131215_Content_61 = {
    Text = "Diosa del destino, por favor perdone mi falta de respeto... pero la ira me obliga a preguntarle."
  },
  AvgDialog_131215_Content_62 = {
    Text = "He enfrentado muchos peligros, dejando una grandiosa canción con mi valor y mi vida, que debería ir junto a mi patria hasta el final del universo."
  },
  AvgDialog_131215_Content_63 = {
    Text = "¿Por qué, gran diosa... por qué nos desterraste a estas tierras salvajes? <Shake:¿Por qué convertiste en polvo aquellas melodías inmortales?>"
  },
  AvgDialog_131215_Content_64 = {
    Text = "Mis soldados acaban de soportar un largo invierno. Rechazamos a los invasores bárbaros y defendimos nuestra civilización e historia."
  },
  AvgDialog_131215_Content_65 = {
    Text = "En los momentos más sangrientos, los soldados heridos ofrecen voluntariamente su carne y sangre para alimentar a sus compañeros... ¡Qué victoria tan dolorosa, oh, mi diosa!."
  },
  AvgDialog_131215_Content_66 = {
    Text = "Cuando el enemigo se retira, las lágrimas de alegría llenan los ojos de todos. En el banquete de celebración, llenarè las copas de vino de cada soldado con licor."
  },
  AvgDialog_131215_Content_67 = {
    Text = "Pero en ese momento, antes de que levantáramos nuestras copas para celebrar, nuestro hogar se convirtió en ruinas, y nuestros seres queridos se desvanecieron en polvo..."
  },
  AvgDialog_131215_Content_68 = {
    Text = "<Shake:Amada Diosa, ¿no nos concederías siquiera un solo momento de alegría?>"
  },
  AvgDialog_131215_Content_69 = {Text = "..."},
  AvgDialog_131215_Content_7 = {
    Text = "Nefruri ya se ha alejado de ese estado de locura en el escenario, se volvió y te miró con gran expectación."
  },
  AvgDialog_131215_Content_70 = {
    Text = "\"Nefruri\" escuchaba el relato interminable de los muñecos, y de su rostro sin rasgos, caían dos hileras de lágrimas."
  },
  AvgDialog_131215_Content_71 = {
    Text = "Los escuché, los vi..."
  },
  AvgDialog_131215_Content_72 = {
    Text = "Las grandes civilizaciones se desvanecen de tus manos; el esplendor del arte se convierte en polvo. Las personas que se aman olvidan todo el uno del otro, y en la angustia se encuentran con la dolorosa muerte..."
  },
  AvgDialog_131215_Content_73 = {
    Text = "Solo un destino correcto será dejado, y en ese momento, todos los innumerables errores fluirán hacia este abismo salvaje e infinito. Tan largo como un tiempo detenido, estas historias se repiten todos los días."
  },
  AvgDialog_131215_Content_74 = {
    Text = "¿Cuánto tiempo quieres que te mire, cuánto tiempo quieres que te escuche, querida hermana...?"
  },
  AvgDialog_131215_Content_75 = {
    Text = "\"Nefruri\" se dio una profunda respiración frente al público y se dio la vuelta."
  },
  AvgDialog_131215_Content_76 = {
    Text = "No se preocupen, mis buenos niños... Su sufrimiento fue creado por mí, y será terminado por mí."
  },
  AvgDialog_131215_Content_77 = {
    Text = "Por favor, descansen aquí por un tiempo. Un día, los llevaré de aquí y les ayudaré a recuperar su propio destino..."
  },
  AvgDialog_131215_Content_78 = {
    Text = "En nombre de Nefruri, la venganza del destino, os prometo..."
  },
  AvgDialog_131215_Content_79 = {Text = "..."},
  AvgDialog_131215_Content_8 = {
    Text = "Al ver tu silencio, niega con la cabeza decepcionada."
  },
  AvgDialog_131215_Content_80 = {
    Text = "Lalalalala... lalala..."
  },
  AvgDialog_131215_Content_81 = {
    Text = "El escenario se aleja cada vez más, y antes de que se apaguen las luces, ves los brazos abiertos de la marioneta y la marca de lágrima oscura en su cara."
  },
  AvgDialog_131215_Content_82 = {
    Text = "No conversaron, solo Nefruri cantaba suavemente la melodía en el escenario. Su canto era rápido y claro, la historia que se representaba en esta escena se había repetido innumerables veces, sin provocarle ninguna emoción adicional."
  },
  AvgDialog_131215_Content_83 = {
    Text = "¡Ay! ¡Ya llega mi escenario favorito! ¡Rápido, hermana"
  },
  AvgDialog_131215_Content_84 = {
    Text = "La voz de Nefruri se llenó de elación. Ella tomó la mano de Arachne y corrió alegremente hacia el escenario delante."
  },
  AvgDialog_131215_Content_85 = {Text = "..."},
  AvgDialog_131215_Content_86 = {
    Text = "Las luces se encienden. No hay música, no hay diálogo—solo una marioneta solitaria ante una rueca en un escenario vacío."
  },
  AvgDialog_131215_Content_87 = {
    Text = "Crujido, crujido. La rueca gira, como si el día en que se detenga nunca fuera a llegar."
  },
  AvgDialog_131215_Content_88 = {
    Text = "...bailan. Cantan. ¡Chirrido—chirrido—!"
  },
  AvgDialog_131215_Content_89 = {
    Text = "La luz del sol baña sus rostros. ¡Qué felices están!"
  },
  AvgDialog_131215_Content_9 = {
    Text = "¿Sin aplausos? ¿Sin lágrimas? El Silencio es un insulto terrible... y después de haber ensayado tanto tiempo en el Abismo. Una lástima, de verdad."
  },
  AvgDialog_131215_Content_90 = {
    Text = "La canción se susurra suavemente desde el rostro sin rasgos de \"Arachne\", mientras ella gira el huso con tranquilidad, sin prisa ni lentitud."
  },
  AvgDialog_131215_Content_91 = {
    Text = "Es un ritmo inquietante—basta una mirada para saber que, una vez iniciado, jamás cambiará hasta el fin de todas las cosas."
  },
  AvgDialog_131215_Content_92 = {
    Text = "La diosa del destino, está a punto de tejer su red."
  },
  AvgDialog_131215_Content_93 = {
    Text = "La red completa del destino cuida a toda la gente... Ellos bailan, ellos cantan..."
  },
  AvgDialog_131215_Content_94 = {
    Text = "Una enorme red es tejida por el telar, cubriendo todo el escenario. El exceso de la red del destino se extiende hacia abajo del escenario."
  },
  AvgDialog_131215_Content_95 = {
    Text = "Cada vez que la telaraña está a punto de completarse, sus bordes más externos comienzan a deshacerse."
  },
  AvgDialog_131215_Content_96 = {
    Text = "Líquido negro, polvo negro, finalmente desapareció. Esa es una escena que te resulta muy familiar."
  },
  AvgDialog_131215_Content_97 = {
    Text = "Celebra, mis hijos, mi pueblo... la diosa del destino está a punto de tejer su red..."
  },
  AvgDialog_131215_Content_98 = {
    Text = "La marioneta observa las redes que se tejen y desaparecen constantemente."
  },
  AvgDialog_131215_Content_99 = {
    Text = "Su voz no temblaba, sus movimientos no dudaban. Ella seguía cantando suavemente la canción, la rueca en sus manos giraba, sin detenerse nunca."
  },
  AvgDialog_131216_Content_1 = {
    Text = "Fiesta de máscaras"
  },
  AvgDialog_131216_Content_10 = {
    Text = "Un doble rasero bastante descarado, señor."
  },
  AvgDialog_131216_Content_11 = {
    Text = "Ejem... Hacer juicios que se ajusten al carácter de cada persona es una habilidad básica para un Investigador..."
  },
  AvgDialog_131216_Content_12 = {
    Text = "William finge no captar tu indirecta y empieza a buscar seriamente un objetivo digno al que acercarse."
  },
  AvgDialog_131216_Content_13 = {
    Text = "Lo perdí todo en aquella batalla. Mi título, mi familia, mi pierna izquierda... mi vida."
  },
  AvgDialog_131216_Content_14 = {
    Text = "Veinte años. Veinte años enteros. Ha sido una tortura lenta, amigo mío. El Destino tuvo a bien dejarme vivir, condenándome a pasar el resto de mis días expiando mis errores."
  },
  AvgDialog_131216_Content_15 = {
    Text = "Destruí mi propio linaje con mis propias manos, pero ?qué importa ya? Dime, ?hay algo en esta vida más importante que una copa?"
  },
  AvgDialog_131216_Content_16 = {Text = "..."},
  AvgDialog_131216_Content_17 = {
    Text = "Oh, cariño, ?recuerdas el cóctel que nos preparó la bartender la última vez que estuvimos aquí?"
  },
  AvgDialog_131216_Content_18 = {
    Text = "Apuesto a que no encontrarás una bebida mejor en todo Londinium. Era tan preciso, tan elegante... parecía menos una receta y más una profecía."
  },
  AvgDialog_131216_Content_19 = {
    Text = "Estaba pensando en lo maravilloso que sería si pudiéramos invitar a esa bartender a nuestra fiesta del mes que viene."
  },
  AvgDialog_131216_Content_2 = {
    Text = "\"90 minutos pasada la medianoche, una máscara de 15 pulgadas, 10 galones de sueño, 2 onzas de licor: la única fórmula para la felicidad.\""
  },
  AvgDialog_131216_Content_20 = {Text = "..."},
  AvgDialog_131216_Content_21 = {Text = "CRAC—"},
  AvgDialog_131216_Content_22 = {
    Text = "Un chasquido de dedos resuena como un fuego artificial junto a tu oído. Te giras y encuentras un rostro resplandeciente con una sonrisa radiante."
  },
  AvgDialog_131216_Content_23 = {
    Text = "Perdonen la interrupción, estimados invitados. Ya que están hablando de temas tan fascinantes, ?quizás les gustaría una bebida igualmente fascinante a la altura?"
  },
  AvgDialog_131216_Content_24 = {
    Text = "Veamos la carta, William."
  },
  AvgDialog_131216_Content_25 = {
    Text = "William entiende tu mirada. Dos personas con uniformes no identificados sentadas en un lugar como este sin probar una gota de alcohol es una forma segura de atraer el tipo de atención equivocada."
  },
  AvgDialog_131216_Content_26 = {
    Text = "Al verlo buscar una carta, la bartender niega con la cabeza con una sonrisa juguetona."
  },
  AvgDialog_131216_Content_27 = {
    Text = "?Una carta? Qué gracioso. Qué tedioso. Qué... ordinario."
  },
  AvgDialog_131216_Content_28 = {
    Text = "Un establecimiento verdaderamente romántico no tiene lugar para algo tan mundano."
  },
  AvgDialog_131216_Content_29 = {
    Text = "?Sin carta? Entonces, ?cómo se supone que pidamos?"
  },
  AvgDialog_131216_Content_3 = {
    Text = "Llevo años con el eslogan de la Máscara de medianoche grabado en la memoria. Cuando estaba en Kadas, era el lugar que más deseaba visitar."
  },
  AvgDialog_131216_Content_30 = {
    Text = "Cada asiento en la Máscara de medianoche es un teatro privado para el invitado que lo ocupa. Aquí, observas, actúas y saboreas..."
  },
  AvgDialog_131216_Content_31 = {
    Text = "De una biblioteca de historias infinitas, seleccionaré la que mejor les convenga."
  },
  AvgDialog_131216_Content_32 = {
    Text = "Por favor, tomen asiento. La narradora está lista."
  },
  AvgDialog_131216_Content_33 = {
    Text = "William y tú intercambiáis una mirada antes de sentaros con cautela en la barra."
  },
  AvgDialog_131216_Content_34 = {
    Text = "Primero, echemos un vistazo a usted—el caballero estoico de cabello claro."
  },
  AvgDialog_131216_Content_35 = {
    Text = "La barman se inclina hacia él. Bajo su mirada escrutadora, William tose suavemente y aparta la vista, ligeramente incómodo."
  },
  AvgDialog_131216_Content_36 = {
    Text = "Ah... Veo los frutos de una disciplina diaria agotadora. Tenacidad, compostura, resiliencia, valentía, sabiduría... Una leyenda viviente, cubierta de tributos florales y gloria."
  },
  AvgDialog_131216_Content_37 = {
    Text = "Y sin embargo, detrás de los elogios y el halo se esconde... arrepentimiento. Un arrepentimiento más profundo y agónico que la niebla que asfixia esta ciudad."
  },
  AvgDialog_131216_Content_38 = {
    Text = "Veo las lágrimas que brillan sin ser vistas en la oscuridad de la noche. Oigo los juramentos susurrados solo para sí mismo."
  },
  AvgDialog_131216_Content_39 = {
    Text = "La luz que una vez le guió a través de la oscuridad se ha extinguido, y con ella, su mundo se hizo añicos... y se hizo añicos otra vez."
  },
  AvgDialog_131216_Content_4 = {
    Text = "¿No crees que las reglas de Misaq son un poco demasiado estrictas a veces?"
  },
  AvgDialog_131216_Content_40 = {
    Text = "Piensa para sí mismo: <Italic:Si tan solo hubiera trabajado más duro. Si tan solo hubiera sido más fuerte... quizás podría haber tejido un destino diferente para mi querido amigo.>"
  },
  AvgDialog_131216_Content_41 = {
    Text = "La expresión de William permanece como una máscara de indiferencia, pero notas las venas marcándose en la mano que aprieta el vaso con los nudillos blancos."
  },
  AvgDialog_131216_Content_42 = {
    Text = "Puedo oír el sonido de un mundo quebrándose. Un niño pequeño soporta el dolor, recogiendo los fragmentos uno a uno, uniéndolos de nuevo..."
  },
  AvgDialog_131216_Content_43 = {
    Text = "A través de esta larga y brutal reparación, el niño finalmente se ha convertido en un hombre."
  },
  AvgDialog_131216_Content_44 = {
    Text = "Su voz es un canturreo bajo y melódico mientras toma botellas de formas extrañas de una estantería que parece extenderse hasta el infinito, comenzando su arte."
  },
  AvgDialog_131216_Content_45 = {
    Text = "Al poco tiempo, desliza un vaso de líquido dorado pálido hacia William."
  },
  AvgDialog_131216_Content_46 = {
    Text = "Dos onzas de whisky, una onza de vino blanco, y una base de resiliencia dolorosa—dos toques de amargo."
  },
  AvgDialog_131216_Content_47 = {
    Text = "<Yellow:\"Guía\">. Espero que puedas guiar a quienes te veneran para encontrar el camino correcto, tal como aquellos a quienes tú veneraste te guiaron a ti en su momento."
  },
  AvgDialog_131216_Content_48 = {
    Text = "William acepta la bebida dorada, haciéndola girar lentamente mientras estudia a la barman con una mirada penetrante."
  },
  AvgDialog_131216_Content_49 = {
    Text = "Todo lo que acaba de decir... ¿cómo sabe todo eso?"
  },
  AvgDialog_131216_Content_5 = {
    Text = "Propuse prohibir a los estudiantes de Misaq entrar en tales establecimientos sin autorización precisamente para evitar que ciertos Guardianes —los negligentes— dilapidaran los fondos de misión bajo el pretexto de realizar investigaciones."
  },
  AvgDialog_131216_Content_50 = {
    Text = "Un maestro barman debe saber escuchar al alma. Ese es un secreto del oficio, mi querido invitado."
  },
  AvgDialog_131216_Content_51 = {
    Text = "La barman esquiva la mirada de William con la gracia de un cervatillo. Se lleva un dedo a los labios en un gesto de silencio, y luego señala directamente hacia ti."
  },
  AvgDialog_131216_Content_52 = {
    Text = "Ahora, en cuanto a ti..."
  },
  AvgDialog_131216_Content_53 = {
    Text = "Hay algo que me dice que esto podría ser lo más peligroso que he intentado jamás—pero no importa. Siempre he tenido gusto por la aventura."
  },
  AvgDialog_131216_Content_54 = {
    Text = "Ella se acerca, mirándote fijamente a los ojos. Casi puedes oír el suave ritmo de su respiración."
  },
  AvgDialog_131216_Content_55 = {
    Text = "Hmm... ¿Qué estoy viendo? ¿Un viajero de un lugar lejano? O quizás... ¿una deidad caída, luchando por salir del fango del reino mortal?"
  },
  AvgDialog_131216_Content_56 = {Text = "¿!!"},
  AvgDialog_131216_Content_57 = {
    Text = "Instintivamente te echas hacia atrás, con el corazón martilleándote en las costillas."
  },
  AvgDialog_131216_Content_58 = {
    Text = "Es imposible que una tabernera corriente supiera eso... ¿Quién —o qué— eres?!"
  },
  AvgDialog_131216_Content_59 = {
    Text = "Tranquilo, querido huésped. En este bar, no soy yo quien alberga malas intenciones."
  },
  AvgDialog_131216_Content_6 = {
    Text = "Este Guardián en particular, después de todo, acumuló un historial considerable durante su época de estudiante."
  },
  AvgDialog_131216_Content_60 = {
    Text = "Quizás hayas notado que algunos de tus \"viejos amigos\" acaban de llegar a tus espaldas."
  },
  AvgDialog_131216_Content_61 = {
    Text = "%player%, cuidado detrás."
  },
  AvgDialog_131216_Content_62 = {
    Text = "Los siento..."
  },
  AvgDialog_131216_Content_63 = {
    Text = "Alertado por la advertencia, percibes más de una docena de agudas ondas psíquicas acercándose rápidamente desde todas las direcciones."
  },
  AvgDialog_131216_Content_64 = {
    Text = "William, el compañero mayor se mueve para cubrirte la espalda con perfecta sincronía. Aprietas con fuerza tu Llave de plata, con los ojos fijos en el enigmático barman."
  },
  AvgDialog_131216_Content_65 = {
    Text = "La tabernera deja su vaso y mueve las botellas a un rincón seguro donde no se romperán en la refriega."
  },
  AvgDialog_131216_Content_66 = {
    Text = "Calma, %player%. Te han estado rastreando durante un tiempo. Aquí, al menos, puedo ofrecerte algo de ayuda."
  },
  AvgDialog_131216_Content_67 = {
    Text = "¿Tú? ¿Ellos? ..."
  },
  AvgDialog_131216_Content_68 = {
    Text = "Je... Te encontré."
  },
  AvgDialog_131216_Content_69 = {
    Text = "Este lugar inmundo no es apto para una larga estancia, mis pequeños visitantes de tierras lejanas."
  },
  AvgDialog_131216_Content_7 = {
    Text = "Oh, pero creo recordar haber leído en el expediente del señor Fengol que su mayor pasatiempo era pasar por la Máscara de medianoche a tomar algo después del trabajo..."
  },
  AvgDialog_131216_Content_70 = {
    Text = "¡Cuidado! ¡Vienen!"
  },
  AvgDialog_131216_Content_8 = {
    Text = "...Y, por supuesto, un descanso ocasional no carece del todo de mérito."
  },
  AvgDialog_131216_Content_9 = {
    Text = "Además, la lista de miembros de la Máscara de medianoche incluye a la élite de todo Londinium. Es el lugar ideal para recopilar información."
  },
  AvgDialog_131217_Content_1 = {
    Text = "El poder de los tres éteres se ha calmado dentro de ti, pero aún no has abierto los ojos."
  },
  AvgDialog_131217_Content_10 = {
    Text = "El espíritu de los contratos, los principios comerciales... un trato requiere ventaja. Sabes cómo funciona esto, ¿verdad?"
  },
  AvgDialog_131217_Content_11 = {
    Text = "\"N\" niega con la cabeza, luchando por contener la risa."
  },
  AvgDialog_131217_Content_12 = {
    Text = "La buena noticia es que siempre tienes la ventaja perfecta."
  },
  AvgDialog_131217_Content_13 = {
    Text = "Un valiente guardián a punto de abandonar la fe de {Male=his,Female=her}, ahogándose en la telaraña del Destino—engañando, mintiendo, completamente sin principios... ¡qué escena tan cautivadora!"
  },
  AvgDialog_131217_Content_14 = {
    Text = "No me perdería el mejor asiento de la función por nada del mundo."
  },
  AvgDialog_131217_Content_15 = {
    Text = "¿Cuándo dije...?"
  },
  AvgDialog_131217_Content_16 = {
    Text = "El Juerguista no tiene paciencia para tus preguntas. Sopesa la deuda que contraerás en el futuro y agita un dedo con una sonrisa."
  },
  AvgDialog_131217_Content_17 = {
    Text = "No es una sugerencia, solo es un pequeño y sincero consejo."
  },
  AvgDialog_131217_Content_18 = {
    Text = "¿Por qué rebelarse contra Nefruri? ¿Por qué no obedecerla, Guardián {Male=señor, Female=señorita}?"
  },
  AvgDialog_131217_Content_19 = {
    Text = "\"N\" sonríe y se inclina hacia ti, tan benevolente como un abogado visitando a un cliente en prisión."
  },
  AvgDialog_131217_Content_2 = {
    Text = "Tu conciencia se sumerge, se sumerge en el vasto mar espiritual, hasta la oscuridad infinita, hasta el abismo que te pertenece y que no puedes ver claramente."
  },
  AvgDialog_131217_Content_20 = {
    Text = "Tú... ¿qué dices? ¡No, eso es imposible!"
  },
  AvgDialog_131217_Content_21 = {
    Text = "Ah, sí, nunca rendirse, nunca darse por vencido, nunca reconocer lo que hizo Nefruri... un heroísmo antiguo y clásico."
  },
  AvgDialog_131217_Content_22 = {
    Text = "Envía a Nefruri, convoca a esa persona querida, regresa a ese palacio que te pertenece... Aparte de eso, ¿qué más puedes hacer ahora, %player%?"
  },
  AvgDialog_131217_Content_23 = {
    Text = "Te voy a dar un secreto: dado que ya no puedes escapar de esa red, ¿por qué no abres los brazos y acoges su llegada?"
  },
  AvgDialog_131217_Content_24 = {
    Text = "Deja de soñar, \"N\". Yo nunca podría..."
  },
  AvgDialog_131217_Content_25 = {
    Text = "Shh. No te pongas límites tan fácilmente, querida."
  },
  AvgDialog_131217_Content_26 = {
    Text = "No lo olvides, Arachne ha entrelazado tu destino en la gran red. Tú, ya eres uno de ellos."
  },
  AvgDialog_131217_Content_27 = {
    Text = "Esa persona, la diosa del destino, te dio una llave llamada Alegría. Pero, ¿alguna vez has pensado hacia dónde está esa puerta y a dónde conduce?"
  },
  AvgDialog_131217_Content_28 = {
    Text = "Hacia donde mira la Puerta... ¿adónde conduce...?"
  },
  AvgDialog_131217_Content_29 = {
    Text = "Yo pensaba que Arachne era una dama trabajadora, bondadosa y poco interesante, cuya única habilidad era tejer redes y sonreír. Pero ella era mucho más interesante de lo que imaginaba."
  },
  AvgDialog_131217_Content_3 = {
    Text = "Esforzándote por abrir la boca inexistente, gritas en silencio y con ira en este abismo."
  },
  AvgDialog_131217_Content_30 = {
    Text = "Ella tejió una gran red para este escenario, y desde el primer momento en que llegaste a este mundo, la red comenzó a desplegarse para ti."
  },
  AvgDialog_131217_Content_31 = {
    Text = "Tener una habilidad tan excelente y estar haciendo cosas tan estúpidas como mantener el funcionamiento del mundo... qué lástima, realmente es una gran lástima."
  },
  AvgDialog_131217_Content_32 = {
    Text = "Pisar el escenario del Teatro del destino es convertirse en un personaje. Y cada personaje tiene una vida propia."
  },
  AvgDialog_131217_Content_33 = {
    Text = "El Destino te obligó a tomar esa decisión para que finalmente pudieras verlo tal como es. No puedes ver los hilos en sí, pero ahora comprendes las intrincadas formas en que están tejidos."
  },
  AvgDialog_131217_Content_34 = {
    Text = "Estos hilos forman una vasta red. El más leve temblor en un solo hilo puede hacer que toda la estructura se derrumbe."
  },
  AvgDialog_131217_Content_35 = {
    Text = "Esto es el Destino, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131217_Content_36 = {
    Text = "Actuar, engañar, entretener... llevas esos poderes dentro de ti. El escenario del Destino rara vez concede tiempo para ensayar. Cuando llegue el momento, ese poder te respaldará."
  },
  AvgDialog_131217_Content_37 = {
    Text = "No puedes esconderte de los papeles que estabas destinado a interpretar. Piensa y luego actúa, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131217_Content_38 = {
    Text = "\"Éxtasis.\""
  },
  AvgDialog_131217_Content_39 = {
    Text = "En tu breve futuro, la \"Alegría\" es una llave que abrirá los secretos que enfrentas."
  },
  AvgDialog_131217_Content_4 = {Text = "\"N\"!"},
  AvgDialog_131217_Content_40 = {
    Text = "...Sin importar lo que pase, confía en mí. Y confía en ti."
  },
  AvgDialog_131217_Content_41 = {
    Text = "Regresa al Teatro del destino. La llave y la cerradura te esperan allí, %player%."
  },
  AvgDialog_131217_Content_42 = {
    Text = "Las palabras de Arachne son como hilos que recorren y entrelazan tu mente. Finalmente, se convierten en una gran y densa red."
  },
  AvgDialog_131217_Content_43 = {
    Text = "Finalmente entiendes que, desde el primer encuentro, Arachne ha estado dialogando contigo a través del tiempo."
  },
  AvgDialog_131217_Content_44 = {
    Text = "Miras con asombro esa red precisa, como si algo muy importante estuviera tomando forma gradualmente en tu mente."
  },
  AvgDialog_131217_Content_45 = {
    Text = "Actuación, engaño, seducción..."
  },
  AvgDialog_131217_Content_46 = {
    Text = "Ah, así es. Nunca intentes entender. Disfrútalas, ese es el único secreto de la alegría."
  },
  AvgDialog_131217_Content_47 = {
    Text = "La tristeza y la alegría, el bien y el mal, todas las emociones y la moral han desaparecido. No hay nada más que disfrutar."
  },
  AvgDialog_131217_Content_48 = {
    Text = "Ahora, dime... ¿entiendes la \"alegría\", Guardián del Secreto?"
  },
  AvgDialog_131217_Content_49 = {
    Text = "La sonrisa carmesí de \"N\" se desvanece de tu mente. Ves un espejo, y reflejado en él está tu propio rostro sonriente."
  },
  AvgDialog_131217_Content_5 = {
    Text = "Shh... tu voz es demasiado alta, Guardián del Secreto."
  },
  AvgDialog_131217_Content_50 = {
    Text = "¿Alegría?... Alegría..."
  },
  AvgDialog_131217_Content_51 = {
    Text = "Jejeje... ¡Jajajaja! ¡Exacto, alegría, mis amigos"
  },
  AvgDialog_131217_Content_52 = {
    Text = "La palabra más maravillosa de este mundo, todo el significado de la existencia de este sueño..."
  },
  AvgDialog_131217_Content_53 = {
    Text = "Como si vislumbrara la escena a punto de desplegarse, todo el cuerpo de N tiembla de deleite. Presiona un dedo envuelto en bruma oscura contra su propia frente."
  },
  AvgDialog_131217_Content_54 = {
    Text = "Ya estás a punto de llegar. Solo un paso más, el último paso... Piensa bien y luego entra en esa red, Guardián del Secreto."
  },
  AvgDialog_131217_Content_55 = {
    Text = "El camino del placer está en ello."
  },
  AvgDialog_131217_Content_6 = {
    Text = "El fantasma de \"N\" permanece. Aparece en tu espacio mental con facilidad, como si fuera el amo indiscutible del Reino."
  },
  AvgDialog_131217_Content_7 = {
    Text = "¡La \"Alegría\" de Arachne debe referirse a ti"
  },
  AvgDialog_131217_Content_8 = {
    Text = "\"N\", dame una pista..."
  },
  AvgDialog_131217_Content_9 = {
    Text = "¿Sugerencia? Jajajaja... ¿Qué hice para que me humillaras así?"
  },
  AvgDialog_131218_Content_10 = {
    Text = "Tú... Todos vosotros... ¿qué está pasando?"
  },
  AvgDialog_131218_Content_11 = {
    Text = "El borracho, la joven dama, el caballero distinguido, el matón, el camarero agotado, la hermosa cantinera..."
  },
  AvgDialog_131218_Content_12 = {
    Text = "Todos los rostros del bar —jóvenes, ancianos, apuestos o corrientes— se vuelven hacia ti al unísono, con expresiones tan idénticas como calcos."
  },
  AvgDialog_131218_Content_13 = {
    Text = "No son individuos. Son más bien como..."
  },
  AvgDialog_131218_Content_14 = {
    Text = "Quienes hace apenas un momento parecían tan llenos de vida ahora se alzan ante ti como maniquíes de madera sin vida."
  },
  AvgDialog_131218_Content_15 = {
    Text = "...Más bien como marionetas, atrapadas en una telaraña."
  },
  AvgDialog_131218_Content_16 = {
    Text = "He oído mucho sobre su aguda intuición, Sr. William, el compañero mayor."
  },
  AvgDialog_131218_Content_17 = {
    Text = "Lo que ve ante usted no son más que atrezo en un escenario —reflejos en un espejo."
  },
  AvgDialog_131218_Content_18 = {
    Text = "Le ruego me disculpe. Aún no puedo abandonar mi telaraña. Debo usar estos recipientes para hablar con usted."
  },
  AvgDialog_131218_Content_19 = {
    Text = "Bienvenido a mi escenario, Sr. William, el compañero mayor... y usted, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131218_Content_2 = {
    Text = "Se acabó... pero ¿qué demonios eran esas cosas?"
  },
  AvgDialog_131218_Content_20 = {
    Text = "Cada uno de los vocablos se pronuncia con una precisión inquietante; veinte voces distintas se entrelazan en un solo y frío hilo de voz."
  },
  AvgDialog_131218_Content_21 = {
    Text = "Todos en la sala se inclinan en perfecta unísono. El ángulo de sus espaldas y la posición de sus manos se reflejan con una exactitud antinatural."
  },
  AvgDialog_131218_Content_22 = {
    Text = "¿Tu... escenario? Solo... ¿quién eres?"
  },
  AvgDialog_131218_Content_23 = {
    Text = "Soy el amo de este lugar —y su prisionero."
  },
  AvgDialog_131218_Content_24 = {
    Text = "Imagino que tienes muchas preguntas."
  },
  AvgDialog_131218_Content_25 = {
    Text = "Este lugar ya no es seguro; su gente regresará pronto. Mi doncella vendrá a buscaros. No os alarméis cuando la veáis."
  },
  AvgDialog_131218_Content_26 = {
    Text = "Cuando nos veamos cara a cara, responderé a todo."
  },
  AvgDialog_131218_Content_27 = {
    Text = "En el momento en que esas palabras abandonan sus labios, la consciencia de la multitud parece desvanecerse en un instante."
  },
  AvgDialog_131218_Content_28 = {
    Text = "La copa de cristal de un caballero se congela en sus labios; el abanico abierto de una dama se detiene justo bajo su barbilla; el barman permanece inmóvil, con la copa en alto."
  },
  AvgDialog_131218_Content_29 = {
    Text = "Como si les hubieran cortado los hilos a todos a la vez, cada uno mantiene su última pose—figuras de cera congeladas en su lugar."
  },
  AvgDialog_131218_Content_3 = {
    Text = "¡¡Cuidado detrás!!"
  },
  AvgDialog_131218_Content_30 = {
    Text = "Respiras lentamente y miras con inquietud el mar de \"marionetas\", cada una congelada con esa misma sonrisa inmutable."
  },
  AvgDialog_131218_Content_31 = {
    Text = "Me ayudaron hace un momento, pero aún no puedo confiar plenamente en ellos..."
  },
  AvgDialog_131218_Content_32 = {
    Text = "William, el compañero mayor, para todo lo que necesitamos saber... esta \"Dama\" puede ser nuestra mejor oportunidad de obtener respuestas."
  },
  AvgDialog_131218_Content_33 = {
    Text = "Aunque sea peligroso, creo que tengo que ir. Es solo que..."
  },
  AvgDialog_131218_Content_34 = {Text = "Entiendo."},
  AvgDialog_131218_Content_35 = {
    Text = "Al cruzar su mirada con la tuya, William, el compañero mayor, asiente en silencio con complicidad."
  },
  AvgDialog_131218_Content_36 = {
    Text = "Rastrearé los movimientos de esas sombras aquí fuera. Te están buscando. Llamaré menos la atención moviéndome por fuera que tú."
  },
  AvgDialog_131218_Content_37 = {
    Text = "Esta \"Dama\" tiene orígenes desconocidos. Si algo sale mal..."
  },
  AvgDialog_131218_Content_38 = {
    Text = "William, el compañero mayor, se toca la insignia en el pecho. Varados juntos en este mundo extraño, sus insignias solo se alcanzan entre sí."
  },
  AvgDialog_131218_Content_39 = {
    Text = "Entendido... Tú también, William, el compañero mayor."
  },
  AvgDialog_131218_Content_4 = {
    Text = "Una descarga de pura adrenalina te sacude. Te giras y encuentras una hoja de sombra solidificada flotando a escasos centímetros de tu garganta."
  },
  AvgDialog_131218_Content_40 = {
    Text = "La Dama comprende vuestra cautela. Sr. William, el compañero mayor, este escenario alberga muchos peligros ahora mismo; por favor, andad con cuidado. Ofreceremos toda la asistencia que podamos."
  },
  AvgDialog_131218_Content_41 = {
    Text = "Arañas de un pálido violeta convergen desde cada rincón del bar, y una doncella con rasgos arácnidos aparece en silencio detrás de todos vosotros. Tras hacer una reverencia educada, camina hacia la puerta."
  },
  AvgDialog_131218_Content_42 = {
    Text = "{Male=Mr.,Female=Miss} Guardián, por favor, sígame. La Dama le está esperando."
  },
  AvgDialog_131218_Content_5 = {Text = "Hiss—"},
  AvgDialog_131218_Content_6 = {
    Text = "Bajas lentamente el brazo con el que te protegías el rostro. La sombra ha sido despedazada por alguien detrás de ti; un icor negro salpica por el aire, manchando tu ropa."
  },
  AvgDialog_131218_Content_7 = {
    Text = "Disculpa por el susto."
  },
  AvgDialog_131218_Content_8 = {
    Text = "Te han estado cazando. Dentro de estos muros, al menos puedo echarte una mano."
  },
  AvgDialog_131218_Content_9 = {
    Text = "Perdóname por haberme tomado la libertad de guiarte hasta aquí sin tu consentimiento."
  },
  AvgDialog_131219_Content_1 = {
    Text = "¿Es esto... ha terminado?"
  },
  AvgDialog_131219_Content_2 = {
    Text = "Ten cuidado, Guardián... el huso que deshilvana el destino ya ha comenzado a girar tras ella..."
  },
  AvgDialog_131219_Content_3 = {
    Text = "Je... jajajaja...!"
  },
  AvgDialog_131220_Content_1 = {
    Text = "Cisne en vuelo"
  },
  AvgDialog_131220_Content_10 = {
    Text = "Recuerdas la verja oxidada que gime cada vez que se mueve, como la respiración pausada de un abuelo."
  },
  AvgDialog_131220_Content_11 = {
    Text = "La Universidad Miskatonic..."
  },
  AvgDialog_131220_Content_12 = {
    Text = "Dentro de este escenario familiar, trazas el nombre desconocido grabado en la placa de la plaza."
  },
  AvgDialog_131220_Content_13 = {
    Text = "Cada actor tiene un escenario que ama más que ningún otro. Incluso un campus construido a partir de recuerdos es irremplazable para ti."
  },
  AvgDialog_131220_Content_14 = {
    Text = "¿Por qué crear un lugar exactamente igual a Misaq...?"
  },
  AvgDialog_131220_Content_15 = {
    Text = "No lo creé; simplemente pertenece aquí. Como esta ciudad y este mundo, es una pieza de la Gran Telaraña."
  },
  AvgDialog_131220_Content_16 = {
    Text = "No mires tan lejos, %player%. Si estás en un escenario, hay una razón para que estés aquí."
  },
  AvgDialog_131220_Content_17 = {
    Text = "Ahora que lo pienso, después de todo el tiempo que he pasado con Liz, nunca la he visto actuar en vivo."
  },
  AvgDialog_131220_Content_18 = {
    Text = "Miras a tu alrededor en la plaza familiar, rozando la hierba con los dedos."
  },
  AvgDialog_131220_Content_19 = {
    Text = "Los momentos más hermosos de la vida son aquellos en los que ni siquiera te das cuenta de que estás sonriendo."
  },
  AvgDialog_131220_Content_2 = {
    Text = "Esto es un lujo poco común. Incluso la entrada más barata para esta compañía normalmente me costaría dos meses de salario."
  },
  AvgDialog_131220_Content_20 = {
    Text = "Oh... lo siento."
  },
  AvgDialog_131220_Content_21 = {
    Text = "¿Pensando en Misaq?"
  },
  AvgDialog_131220_Content_22 = {
    Text = "Hicimos tantas actuaciones en esta plaza. En aquel entonces, estaba repleta de estudiantes de Misaq, igual que ahora."
  },
  AvgDialog_131220_Content_23 = {
    Text = "Muchos Despertados son maestros en su arte. Algunos se mostraban reacios a actuar al principio, así que el profesorado y yo tuvimos que buscar formas de convencerlos..."
  },
  AvgDialog_131220_Content_24 = {
    Text = "Con el tiempo, muchos de ellos empezaron a ofrecerse voluntariamente para montar espectáculos para sus compañeros."
  },
  AvgDialog_131220_Content_25 = {
    Text = "La danza de Liz, las baladas de Tinct, las sinfonías de Hameln, la poesía de Horla, las esculturas de Sanga..."
  },
  AvgDialog_131220_Content_26 = {
    Text = "Me pregunto si la vida en Misaq volvió a ser como antes después de que me fui..."
  },
  AvgDialog_131220_Content_27 = {
    Text = "¡El telón se ha movido! ¡La señorita Elizabeth está a punto de hacer su entrada!"
  },
  AvgDialog_131220_Content_28 = {
    Text = "Sacudes la cabeza, ahuyentando la melancolía de tu mente."
  },
  AvgDialog_131220_Content_29 = {
    Text = "Sea como sea, ver a Liz bailar de nuevo en este mundo lejano es algo por lo que estar agradecido."
  },
  AvgDialog_131220_Content_3 = {
    Text = "¡Escuché que la Señora Sorel está patrocinando personalmente esta función benéfica! Ojalá todos los nobles de esta ciudad fueran tan generosos."
  },
  AvgDialog_131220_Content_30 = {
    Text = "Cuando esto termine, si hay tiempo, me gustaría sentarme y hablar de verdad con ellos."
  },
  AvgDialog_131220_Content_31 = {
    Text = "Damas y caballeros... ¡bienvenidos a nuestra actuación!"
  },
  AvgDialog_131220_Content_32 = {
    Text = "La Compañía de danza del cisne, ¡un nombre tan sagrado como intocable! Hoy, el cisne blanco más elegante de Londinium se posa ante el público por primera vez."
  },
  AvgDialog_131220_Content_33 = {
    Text = "Gracias por su paciencia. Nuestros artistas están listos. ¡Un espectáculo extraordinario está a punto de comenzar!"
  },
  AvgDialog_131220_Content_34 = {
    Text = "Con un chasquido seco del presentador, las luces se apagan. Los focos convergen en el centro del escenario."
  },
  AvgDialog_131220_Content_35 = {
    Text = "A continuación, disfruten de \"El vuelo del cisne\", interpretado por la señorita Elizabeth Salle."
  },
  AvgDialog_131220_Content_36 = {
    Text = "Entre atronadores aplausos y vítores, el telón se abre lentamente—"
  },
  AvgDialog_131220_Content_37 = {
    Text = "<Big:<Red:¡¡¡¡!!!!>>"
  },
  AvgDialog_131220_Content_38 = {
    Text = "Has visto a Liz muchas veces."
  },
  AvgDialog_131220_Content_39 = {
    Text = "En el salón ceremonial de Misaq, ella hace piruetas solo para ti."
  },
  AvgDialog_131220_Content_4 = {
    Text = "No lo entiendo, pero no voy a dejar pasar una oportunidad como esta."
  },
  AvgDialog_131220_Content_40 = {
    Text = "Bajo las estrellas de Londinium, las puntas de sus pies rozaban las luciérnagas que danzaban en la noche."
  },
  AvgDialog_131220_Content_41 = {
    Text = "En la brisa de Charing Cross Road, su falda ondeaba como una llama ardiente."
  },
  AvgDialog_131220_Content_42 = {
    Text = "Pero hoy, en este escenario extranjero, ella aparece de una forma que jamás imaginaste."
  },
  AvgDialog_131220_Content_43 = {
    Text = "La prima ballerina, el fuego artificial más deslumbrante de la ciudad, está empalada. Púas negras le atraviesan la garganta, los brazos, el pecho y sus pies arqueados—desgarrando el cuerpo que una vez dominó la danza."
  },
  AvgDialog_131220_Content_44 = {
    Text = "La Sangre salpica el telón de fondo, formando un par de alas carmesí tras ella. Violentas vetas rojas manchan su sonrisa serena y apacible."
  },
  AvgDialog_131220_Content_45 = {
    Text = "La multitud cae en un silencio sepulcral. El Viento barre la plaza, agitando su tutú negro y verde como una llama que arde eternamente."
  },
  AvgDialog_131220_Content_46 = {
    Text = "En este instante, comprendes: si la muerte es inevitable, así es exactamente como Liz elegiría enfrentarla."
  },
  AvgDialog_131220_Content_47 = {
    Text = "Ella ha dado su última reverencia con su propia vida. Su figura está congelada en un hermoso salto, como un cisne negro surcando el cielo."
  },
  AvgDialog_131220_Content_48 = {
    Text = "Contemplen, la pose final de la señorita Elizabeth... ¡qué elegante, qué grácil!"
  },
  AvgDialog_131220_Content_49 = {
    Text = "¡Disfruten la vista, mi querido público! Presenciar esto es el mayor honor de sus vidas."
  },
  AvgDialog_131220_Content_5 = {
    Text = "Treinta años... No he vuelto a un teatro en treinta años."
  },
  AvgDialog_131220_Content_50 = {
    Text = "Ves el rostro del anunciador desgarrado en dos mitades. La expresión inanimada del hombre de mediana edad se derrite como una sustancia viscosa, revelando los ojos de Nefruri llenos de elación."
  },
  AvgDialog_131220_Content_51 = {
    Text = "Entre los gritos de pánico y la estampida de la multitud, su risa estridente te perfora los oídos como una aguja venenosa."
  },
  AvgDialog_131220_Content_52 = {
    Text = "<Big:¡¡Liz!!>"
  },
  AvgDialog_131220_Content_53 = {
    Text = "Te abres paso a empujones entre la multitud aterrorizada y corres hacia el escenario."
  },
  AvgDialog_131220_Content_54 = {
    Text = "¿Oh? Qué invitado tan astuto. ¿Cómo supiste que esta función tenía un segundo acto?"
  },
  AvgDialog_131220_Content_55 = {
    Text = "Los que se quedaron atrás convergen de repente sobre ti. Sus cuerpos estallan mientras corren, y despiadados escuderos–araña negros emergen reptando de los restos."
  },
  AvgDialog_131220_Content_56 = {
    Text = "En el escenario, el cuerpo de Liz se desliza de las púas. Ella es una obra de arte forjada por un hereje, marcada por crueles oquedades y un rojo vívido."
  },
  AvgDialog_131220_Content_57 = {
    Text = "Huellas ensangrentadas se extienden desde el centro del escenario. Liz camina hacia ti, su rostro pintado con una máscara macabra y sobrecogedora de sangre que te deja sin aliento."
  },
  AvgDialog_131220_Content_58 = {
    Text = "Ella alza la mirada hacia ti. Sus ojos huecos y sangrantes te recuerdan a una obra maestra destinada a la eternidad."
  },
  AvgDialog_131220_Content_59 = {
    Text = "Ahora, es hora de bailar con tu vieja amiga... {Male=Mr.,Female=Miss} Guardián!"
  },
  AvgDialog_131220_Content_6 = {
    Text = "El ballet es la danza más pura del mundo. ¡Solo quienes lo han practicado comprenden de verdad la belleza de esa elegancia brutal!"
  },
  AvgDialog_131220_Content_7 = {
    Text = "Ver actuar a la señorita Elizabeth en vivo es algo que ni siquiera había soñado..."
  },
  AvgDialog_131220_Content_8 = {
    Text = "El ruido ambiental de la multitud se desvanece en un murmullo distante."
  },
  AvgDialog_131220_Content_9 = {
    Text = "Recuerdas este prado, aquel lago. Recuerdas las distintas alturas de los edificios del campus y la escultura que mira resueltamente hacia el horizonte."
  },
  AvgDialog_131221_Content_1 = {
    Text = "Segundo acto"
  },
  AvgDialog_131221_Content_10 = {
    Text = "No soy más que una prisionera del Destino; es un deber que no tengo más remedio que cumplir."
  },
  AvgDialog_131221_Content_11 = {
    Text = "Para alguien que manipula los destinos de incontables mundos, quizás \"jueza\" o \"guardiana\" del Destino sería un título más apropiado, ¿no?"
  },
  AvgDialog_131221_Content_12 = {
    Text = "En este lugar, no hay diferencia entre carcelera y prisionera."
  },
  AvgDialog_131221_Content_13 = {
    Text = "Sr. William, ¿ha sido cómodo su viaje?"
  },
  AvgDialog_131221_Content_14 = {
    Text = "Gracias a la ayuda de su doncella. Si hubiera tenido que arreglármelas solo, evadir a esos escuderos acechando entre las sombras me habría costado mucho más."
  },
  AvgDialog_131221_Content_15 = {
    Text = "Nefruri... ¿Te has encontrado con ella otra vez?"
  },
  AvgDialog_131221_Content_16 = {
    Text = "William asiente con solemnidad."
  },
  AvgDialog_131221_Content_17 = {
    Text = "Cuando nos separamos, me crucé con unos transeúntes que parecían... sospechosos. Los seguí un rato y capté fragmentos de su conversación."
  },
  AvgDialog_131221_Content_18 = {
    Text = "Están buscando cosas que llaman \"objetos secretos\"."
  },
  AvgDialog_131221_Content_19 = {
    Text = "Sospecho que la contaminación del destino del escenario que mencionaste antes podría ser solo una medida preliminar."
  },
  AvgDialog_131221_Content_2 = {
    Text = "Vaya espectáculo..."
  },
  AvgDialog_131221_Content_20 = {
    Text = "Esos \"objetos secretos\" son su verdadero objetivo."
  },
  AvgDialog_131221_Content_21 = {
    Text = "Mi hermana ha ocultado sus propios Hilos del destino junto con los de sus escuderos; no puedo percibirlos fácilmente. Esta es una información vital, Sr. William."
  },
  AvgDialog_131221_Content_22 = {
    Text = "Para la siguiente fase, iré contigo..."
  },
  AvgDialog_131221_Content_23 = {Text = "¡No!"},
  AvgDialog_131221_Content_24 = {
    Text = "No, ¡debes quedarte! Dividirnos antes fue una necesidad, pero no arriesgaré una repetición de lo que ocurrió en Lemvahi."
  },
  AvgDialog_131221_Content_25 = {
    Text = "El Guardián tiene razón. Mi doncella tratará las toxinas en tu organismo. Hasta que te hayas recuperado por completo, por favor permanece en el teatro para descansar."
  },
  AvgDialog_131221_Content_26 = {
    Text = "El día en que verdaderamente necesitemos tu fuerza está cerca."
  },
  AvgDialog_131221_Content_27 = {
    Text = "Las palabras de Arachne son como un suave veredicto, que atraviesa fácilmente el cuerpo y el alma, cayendo suavemente en el destino de William."
  },
  AvgDialog_131221_Content_28 = {
    Text = "William observa la sangre que se filtra a través de sus vendajes y asiente lentamente."
  },
  AvgDialog_131221_Content_29 = {
    Text = "Si fuera ahora, solo sería una carga. Quédate tranquilo, me aseguraré de estar lista cuando llegue ese día."
  },
  AvgDialog_131221_Content_3 = {
    Text = "<Shake:Cof cof...>"
  },
  AvgDialog_131221_Content_30 = {
    Text = "Arachne sonriendo extendió la mano. Una, dos... innumerables arañas salieron de sus mangas, cayendo al suelo a lo largo de hilos."
  },
  AvgDialog_131221_Content_31 = {
    Text = "Las arañas caen como lluvia, convergiendo y agrupándose. La masa de arácnidos se superpone formando una silueta humana mientras el color y la luz se adhieren a la forma cambiante."
  },
  AvgDialog_131221_Content_32 = {
    Text = "Pronto, una nueva Arachne idéntica está frente a ti."
  },
  AvgDialog_131221_Content_33 = {
    Text = "Sígueme, {Male=Mr.,Female=Miss} Guardián. Creo que ha llegado el momento de un encuentro cara a cara con mi hermana."
  },
  AvgDialog_131221_Content_34 = {Text = "..."},
  AvgDialog_131221_Content_35 = {
    Text = "Hay muchas tiendas en esta ciudad que adoro, pero al igual que tú, considero que este lugar es uno de mis favoritos."
  },
  AvgDialog_131221_Content_36 = {
    Text = "En la taberna Máscara de medianoche, te sientas en el mismo lugar que ocupaste la última vez, frunciendo el ceño mientras miras a Arachne, que está observando a su alrededor."
  },
  AvgDialog_131221_Content_37 = {
    Text = "Entonces, ¿qué eres exactamente ahora mismo? ¿Un objeto secreto? ¿Un señuelo? ¿Alguna máquina misteriosa hecha de un montón de arañas para que la verdadera tú pueda saltarse las clases?"
  },
  AvgDialog_131221_Content_38 = {
    Text = "En esencia, el \"yo\" que está aquí y el \"yo\" del teatro son el mismo Destino; somos dos experiencias distintas que se desarrollan en el mismo instante."
  },
  AvgDialog_131221_Content_39 = {
    Text = "La mayor parte de mi fuerza necesita quedarse en el teatro, continuando tejiendo la gran red del destino. Aparte de esto, no tenemos ninguna diferencia. No hay necesidad de arruinar el ambiente de este momento por dudas, Guardián."
  },
  AvgDialog_131221_Content_4 = {
    Text = "El sonido agita su herida. William, el compañero mayor se agarra el abdomen vendado, incapaz de reprimir un agudo ataque de tos."
  },
  AvgDialog_131221_Content_40 = {
    Text = "Arachne sonríe tranquilamente, mientras los cubitos de hielo suenan suavemente en la copa de vino que tiembla."
  },
  AvgDialog_131221_Content_41 = {
    Text = "¿Sabías que este establecimiento organiza una fiesta de máscaras cada mes? Cada invitado que entra debe llevar su máscara más interesante."
  },
  AvgDialog_131221_Content_42 = {
    Text = "La alta sociedad suele hacer de este lugar algo tedioso, pero en esa única noche, se convierte en el rincón más fascinante de la ciudad."
  },
  AvgDialog_131221_Content_43 = {
    Text = "Quizás para la próxima fiesta de máscaras, debería dejarlo todo a un lado y vivirla de verdad."
  },
  AvgDialog_131221_Content_44 = {
    Text = "Pensaba que alguien capaz de ver todo el tapiz del Destino perdería todo interés en el futuro."
  },
  AvgDialog_131221_Content_45 = {
    Text = "Es cierto, %player%. Sin embargo, descubrí una forma de ahuyentar el aburrimiento hace mucho tiempo."
  },
  AvgDialog_131221_Content_46 = {
    Text = "A veces salgo de detrás del telón y subo al mismo escenario que creé, transformándome en uno de los personajes."
  },
  AvgDialog_131221_Content_47 = {
    Text = "Me ciego a mi propia clarividencia y me entrego a la actuación. Me dejo sentir el fluir del tiempo y los vaivenes del destino..."
  },
  AvgDialog_131221_Content_48 = {
    Text = "Es un raro momento de descanso. Tales oportunidades son escasas, así que atesoro cada una como un día sagrado."
  },
  AvgDialog_131221_Content_49 = {
    Text = "Arachne hablaba mientras observaba con interés a los lujosos invitados y a los amables sirvientes, la tenue luz de la taberna danzaba en los ojos de Arachne."
  },
  AvgDialog_131221_Content_5 = {
    Text = "¿¡William, el compañero mayor?! ¡Estás herido!"
  },
  AvgDialog_131221_Content_50 = {
    Text = "Aun así... ¿no se supone que deberíamos estar buscando esos \"objetos secretos\"? ¿Por qué estamos aquí?"
  },
  AvgDialog_131221_Content_51 = {
    Text = "Una de ellas está justo aquí. La verás pronto... o mejor dicho, ya la has visto."
  },
  AvgDialog_131221_Content_52 = {
    Text = "Hola, queridos clientes."
  },
  AvgDialog_131221_Content_53 = {
    Text = "Su voz es suave como la miel. Sus dedos parecen tallados en fina porcelana. El brillante aroma de jazmín y mimosa se aferra a su cuello desnudo, y sus ojos centellean con una luz penetrante que todo lo ve."
  },
  AvgDialog_131221_Content_54 = {
    Text = "Ah, te recuerdo, la elegante %player%."
  },
  AvgDialog_131221_Content_55 = {
    Text = "Monstruos entre las sombras, un deslumbrante resplandor plateado... ¡qué magnífica epopeya heroica!"
  },
  AvgDialog_131221_Content_56 = {
    Text = "Sinceramente, mientras estabas fuera, la Máscara de medianoche obtuvo bastantes ganancias con tu historia. Te debemos regalías—como mínimo, déjanos invitarte a una copa."
  },
  AvgDialog_131221_Content_57 = {
    Text = "Eres tú... Por ahora paso de la copa, pero ¿podrías prepararle una a mi amiga?"
  },
  AvgDialog_131221_Content_58 = {
    Text = "Ya tengo un nombre para ella: \"El Acto en Solitario\"."
  },
  AvgDialog_131221_Content_59 = {
    Text = "Un buen nombre. En cuanto a si le queda bien a tu amiga... tendré que observarla más de cerca."
  },
  AvgDialog_131221_Content_6 = {
    Text = "Bajo la guía de Arachne, cruzas la pared insignificante al lado del café Hewatz."
  },
  AvgDialog_131221_Content_60 = {
    Text = "¿Quién es el objeto secreto llamado \"romántico\" que se acerca a la barra, mirando seriamente a los ojos de Arachne."
  },
  AvgDialog_131221_Content_61 = {
    Text = "El creador discreto está sumergido en el escenario que ha creado. Arachne sonríe y se encuentra con su mirada."
  },
  AvgDialog_131221_Content_62 = {
    Text = "Oh, qué par de ojos tan expresivos tiene usted, mi señora."
  },
  AvgDialog_131221_Content_63 = {
    Text = "Son como un vasto e insondable océano. Enterrados en esas profundidades ocultas hay secretos que ningún alma ha conocido jamás."
  },
  AvgDialog_131221_Content_64 = {
    Text = "Este océano engulle cada ola furiosa. Sin importar cuán grande sea la tormenta, la superficie permanece tan serena como lo ha sido desde el alba de los tiempos."
  },
  AvgDialog_131221_Content_65 = {
    Text = "El tiempo fluye, las estrellas se desplazan. Las montañas se desmoronan en campos, y los mares se convierten en praderas..."
  },
  AvgDialog_131221_Content_66 = {
    Text = "Pero bajo todo este cambio... ¿qué ha desechado este océano?"
  },
  AvgDialog_131221_Content_67 = {
    Text = "El bartender se sentó frente a Arachne y le levantó la barbilla. Sus largos dedos, de forma natural, se apoyaron en la arteria carótida de Arachne."
  },
  AvgDialog_131221_Content_68 = {Text = "Esto es"},
  AvgDialog_131221_Content_69 = {
    Text = "Dios del destino, la gran Arachne. Qué elegante es tu forma de jugar con el destino. Realmente te envidio, envidio a aquellos que has elegido, a los que has dejado."
  },
  AvgDialog_131221_Content_7 = {
    Text = "Al regresar al escenario del teatro, notas de inmediato a William, sentado a solas entre el público."
  },
  AvgDialog_131221_Content_70 = {
    Text = "Lástima... algunos de nosotros nacimos solo para ser desechados."
  },
  AvgDialog_131221_Content_71 = {
    Text = "...Parece que hoy no podré probar esa bebida después de todo."
  },
  AvgDialog_131221_Content_72 = {
    Text = "Arachne no intentó liberarse de aquella mano peligrosa. Suspiró suavemente, como si estuviera suspirando por esos recuerdos lejanos, y también como si estuviera suspirando por ese cóctel que no podía beber."
  },
  AvgDialog_131221_Content_73 = {
    Text = "Puedes contaminar los hilos del destino de estos objetos secretos, haciéndome incapaz de ver, pero no tiene sentido. No tienes la capacidad de controlar el destino, Nefruri."
  },
  AvgDialog_131221_Content_74 = {
    Text = "Como una muñeca hecha de crema negra derretida, la piel de la barman se desprende de su cuerpo en un montón fangoso."
  },
  AvgDialog_131221_Content_75 = {
    Text = "Bajo el lodo, se revela un rostro familiar."
  },
  AvgDialog_131221_Content_76 = {
    Text = "¿¡Eres tú?!"
  },
  AvgDialog_131221_Content_77 = {
    Text = "Querida hermana. Te quedan muy pocas Cenizas de Dimensión por consumir."
  },
  AvgDialog_131221_Content_78 = {
    Text = "Me encantaría tener una conversación de corazón a corazón, pero por ahora, dejaré que mis pequeñas arañas te den la bienvenida."
  },
  AvgDialog_131221_Content_79 = {
    Text = "¡Cuidado a tu espalda!"
  },
  AvgDialog_131221_Content_8 = {
    Text = "Es solo un rasguño."
  },
  AvgDialog_131221_Content_9 = {
    Text = "He visto el destino que ocurre en este escenario. Creo que alguien debería agradecerle por su dedicación, señora Arachne."
  },
  AvgDialog_131222_Content_1 = {
    Text = "Invitación de la mansión"
  },
  AvgDialog_131222_Content_10 = {
    Text = "¿Una invitación? He vivido toda mi vida sin tener que mostrar jamás un trozo de papel para entrar en una sala."
  },
  AvgDialog_131222_Content_100 = {
    Text = "Sorel entrecierra los ojos, un destello inusual de ira encendiéndose en ellos."
  },
  AvgDialog_131222_Content_101 = {
    Text = "No sé qué le has hecho a Karen, pero no importa. Tu precio ya ha sido fijado."
  },
  AvgDialog_131222_Content_102 = {
    Text = "Ah, una negociación fallida. Qué trágico, Señora Sorel. Parece que tendré que extraer las respuestas de su cadáver."
  },
  AvgDialog_131222_Content_103 = {
    Text = "Sorel frunce el ceño, percibiendo las poderosas ondas psíquicas que emanan de su oponente. Sombras oscuras como la tinta se cierran rápidamente, sellando cada salida."
  },
  AvgDialog_131222_Content_105 = {
    Text = "Solo cuando una hoja se lanza desde la oscuridad, un destello de luz plateada irrumpe en la habitación como una estrella fugaz."
  },
  AvgDialog_131222_Content_106 = {
    Text = "¡Sorel, atrás!"
  },
  AvgDialog_131222_Content_11 = {
    Text = "Apártense."
  },
  AvgDialog_131222_Content_12 = {
    Text = "Mis disculpas, señor. El banquete de esta noche es estrictamente para quienes posean una invitación."
  },
  AvgDialog_131222_Content_13 = {
    Text = "Necio ciego. ¿Tiene la menor idea de quién soy?"
  },
  AvgDialog_131222_Content_14 = {
    Text = "Eso no es de mi incumbencia, señor."
  },
  AvgDialog_131222_Content_15 = {
    Text = "Suena como un lugareño, señor. Supongo que puede entender un idioma sencillo."
  },
  AvgDialog_131222_Content_16 = {
    Text = "¡Pero cómo se atreve...!! ¡Bien! ¡Me aseguraré de que usted y la señora de esta casa paguen por esto!"
  },
  AvgDialog_131222_Content_17 = {
    Text = "Arachne miró la espalda llena de rabia del noble y sacudió la cabeza."
  },
  AvgDialog_131222_Content_18 = {
    Text = "Parece que acceder a esta mansión será más difícil de lo que anticipé."
  },
  AvgDialog_131222_Content_19 = {
    Text = "Si pudiera encontrar a esa criada que vende agua de baño, quizá podría comprarle un par de invitaciones..."
  },
  AvgDialog_131222_Content_2 = {
    Text = "La Mansión del Duque de Cadrin se erige como el lugar de reunión social más prestigioso del viejo Londinium."
  },
  AvgDialog_131222_Content_20 = {
    Text = "Sales marinas raras de Thira, lavanda, cítricos, clavo y pétalos de rosa del sur de Constante..."
  },
  AvgDialog_131222_Content_21 = {
    Text = "Un agua de baño así es mucho más preciada —y más difícil de encontrar— que una simple invitación."
  },
  AvgDialog_131222_Content_22 = {
    Text = "<Yellow:%player%>"
  },
  AvgDialog_131222_Content_23 = {
    Text = "Solo estaba hablando conmigo misma... ¿cómo podrías saber lo que ocurrió en mis sueños?"
  },
  AvgDialog_131222_Content_24 = {
    Text = "Aunque tu propio destino permanece oculto para mí, siempre he observado los destinos de quienes te rodean."
  },
  AvgDialog_131222_Content_25 = {
    Text = "Si controlas sus destinos, seguramente puedes lograr algo tan pequeño como materializar dos invitaciones, ¿no? Aunque las repercusiones sean complicadas."
  },
  AvgDialog_131222_Content_26 = {
    Text = "Ya has visto el caos que sigue a un cambio en el destino. El Destino no es un juguete; es una casa de cristal que requiere mi constante y cuidadoso mantenimiento."
  },
  AvgDialog_131222_Content_27 = {
    Text = "Cada decisión que tomo requiere una concentración inmensa y ascuas dimensionales. Un solo descuido podría provocar un colapso total."
  },
  AvgDialog_131222_Content_28 = {
    Text = "Además... como ya he dicho antes, ser espectador suele ser mucho más entretenido que ser el dramaturgo."
  },
  AvgDialog_131222_Content_29 = {
    Text = "Espero con ansias tu actuación, %player%."
  },
  AvgDialog_131222_Content_3 = {
    Text = "En sus días de gloria, el Primer Ministro y los funcionarios del gabinete se sentaban en las mesas del jardín, redactando decretos que moldeaban el destino mismo del imperio."
  },
  AvgDialog_131222_Content_30 = {
    Text = "Pero no sé nada de este lugar..."
  },
  AvgDialog_131222_Content_31 = {
    Text = "Actuar, engañar, entretener... llevas esos poderes dentro de ti. El escenario del Destino rara vez concede tiempo para ensayar. Cuando llegue el momento, ese poder te respaldará."
  },
  AvgDialog_131222_Content_32 = {
    Text = "No puedes esconderte de los papeles que estabas destinado a interpretar. Piensa y luego actúa, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131222_Content_33 = {
    Text = "Una sonrisa cortés de Arachne oculta una seriedad que no es difícil de notar. Ella parece estar contándote algo, y esa mirada parece atravesarte, dialogando con un futuro lejano."
  },
  AvgDialog_131222_Content_34 = {
    Text = "Esa es una orden que el destino no puede rechazar. Te agachas y reflexionas sobre las palabras de Arachne."
  },
  AvgDialog_131222_Content_35 = {
    Text = "Actuar, engañar, entretener... ¿te refieres a la Orden de gran peso de ¿N?"
  },
  AvgDialog_131222_Content_36 = {
    Text = "Pero desde la batalla final contra Toguwaibo, perdí mi conexión con el poder de los tres plásmidos..."
  },
  AvgDialog_131222_Content_37 = {
    Text = "Su poder dormita, sí. Pero la Orden de gran peso es más que simple poder en bruto."
  },
  AvgDialog_131222_Content_38 = {
    Text = "La Orden de gran peso es más que poder..."
  },
  AvgDialog_131222_Content_39 = {
    Text = "Mientras meditas sobre sus palabras, una chispa de inspiración ilumina tu mente."
  },
  AvgDialog_131222_Content_4 = {
    Text = "En su caída, la mansión vendida permaneció como testigo silencioso, observando su figura encorvada ser conducida hacia el cadalso."
  },
  AvgDialog_131222_Content_40 = {
    Text = "Recoges dos hojas de arce caídas de la hierba. Sus nervaduras se sienten casi como pergamino impreso bajo la yema de tus dedos."
  },
  AvgDialog_131222_Content_41 = {
    Text = "Dijiste que todos en este mundo llevan un Núcleo de plata. Eso significa que sus mentes están abiertas a la influencia de mi Llave de plata... ¿verdad?"
  },
  AvgDialog_131222_Content_42 = {
    Text = "Arachne te sonríe, caminando a tu lado hacia la puerta de la mansión."
  },
  AvgDialog_131222_Content_43 = {
    Text = "Buenas noches. Por favor, muestren su..."
  },
  AvgDialog_131222_Content_44 = {
    Text = "Qué propiedad tan magnífica. Es un honor aceptar la invitación de la Señora Sorel."
  },
  AvgDialog_131222_Content_45 = {
    Text = "Mientras entregas al guardia las hojas de arce, la Llave de plata brilla tenuemente en tu bolsillo. Localizas con facilidad el punto de luz del guardia."
  },
  AvgDialog_131222_Content_46 = {
    Text = "Simultáneamente, otra luz parpadea en tu mente. En el punto de encuentro de esos dos puntos de luz, el fantasma de Clementine aparece, balanceando su péndulo."
  },
  AvgDialog_131222_Content_47 = {
    Text = "C–Conde Huey..."
  },
  AvgDialog_131222_Content_48 = {
    Text = "¡Ah! ¡Conde Huey, Condesa! La Mansión Cardlin se siente honrada con su presencia."
  },
  AvgDialog_131222_Content_49 = {
    Text = "Bajo la mirada respetuosa del guardia, pisas el suave camino empedrado de la propiedad."
  },
  AvgDialog_131222_Content_5 = {
    Text = "Tras un breve período de luto, la mansión se llena una vez más de distinguidos invitados. Su nueva propietaria celebra salón tras salón, proclamando a viva voz el regreso de la finca a su antigua gloria."
  },
  AvgDialog_131222_Content_50 = {
    Text = "¿Cómo se siente, {Male=Mr.,Female=Miss} Guardián?"
  },
  AvgDialog_131222_Content_51 = {
    Text = "Todavía no acabo de entender a qué te refieres con \"Orden de gran peso\", pero definitivamente sentí que algo cambió justo ahora..."
  },
  AvgDialog_131222_Content_52 = {
    Text = "Fue... una emoción. Una oleada de excitación por engañarlos, por hacerles creer que yo era el Conde. Nunca había sentido nada igual. Era como si esa emoción ni siquiera me perteneciera."
  },
  AvgDialog_131222_Content_53 = {
    Text = "Abres la mano, dejando que las dos hojas de arce se deslicen de tus dedos y dancen llevadas por la brisa."
  },
  AvgDialog_131222_Content_54 = {
    Text = "Al entrar en la mansión con una sonrisa adecuada hacia Arachne, estás seguro de que escuchaste una risa placentera que venía de lo más profundo de tu ser."
  },
  AvgDialog_131222_Content_55 = {Text = "..."},
  AvgDialog_131222_Content_56 = {
    Text = "Es verdaderamente admirable ver a alguien lograr tanto a una edad tan joven."
  },
  AvgDialog_131222_Content_57 = {
    Text = "Una vez que concluyan estas negociaciones comerciales, los vínculos entre la élite empresarial y política de esta ciudad se transformarán por completo. Es una oportunidad única..."
  },
  AvgDialog_131222_Content_58 = {
    Text = "El jefe movió cielo y tierra para conseguir estas invitaciones. Necesitamos tomar unas fotos perfectas. Tened el equipo listo y seguidme: tenemos que acercarnos lo más posible al frente..."
  },
  AvgDialog_131222_Content_59 = {
    Text = "¡¡Está aquí!! ¡¡Está saliendo!!"
  },
  AvgDialog_131222_Content_6 = {
    Text = "Buenas noches. Aquí tiene mi invitación."
  },
  AvgDialog_131222_Content_60 = {
    Text = "Ante el grito del joven, la multitud se abalanza hacia las puertas que se abren."
  },
  AvgDialog_131222_Content_61 = {
    Text = "Una dama con un vestido carmesí aparece, semejante a una rosa en plena floración. Su presencia hace que la lujosa decoración y la bulliciosa multitud parezcan apagadas en comparación."
  },
  AvgDialog_131222_Content_62 = {
    Text = "Sorel luce una sonrisa impecable y ensayada, saludando a los invitados con una elegancia sin esfuerzo."
  },
  AvgDialog_131222_Content_63 = {
    Text = "Así que ella es la actual propietaria de la mansión..."
  },
  AvgDialog_131222_Content_64 = {
    Text = "Damas y caballeros, bienvenidos. En el salón de hoy, varios de los distritos comerciales de nuestra ciudad encontrarán a sus nuevos dueños."
  },
  AvgDialog_131222_Content_65 = {
    Text = "Y, por supuesto, nuestros nobles amigos recibirán los beneficios que tan merecidamente les corresponden."
  },
  AvgDialog_131222_Content_66 = {
    Text = "Confío en que esta será una velada de lo más espléndida y encantadora."
  },
  AvgDialog_131222_Content_67 = {
    Text = "Mis chefs han preparado los mejores pasteles y champán. Por favor, disfruten un momento. Nuestro servicio de cena comenzará en breve."
  },
  AvgDialog_131222_Content_68 = {
    Text = "Sorel recorre la sala con la mirada y una sonrisa antes de darse la vuelta para subir las escaleras."
  },
  AvgDialog_131222_Content_69 = {
    Text = "¡Sor... Sorel! ¡Karen!"
  },
  AvgDialog_131222_Content_7 = {
    Text = "Ah, bienvenido, Señor Fugen. La Señora lo está esperando. Por favor, pase."
  },
  AvgDialog_131222_Content_70 = {
    Text = "Tu voz es engullida por el parloteo y los vítores de la multitud."
  },
  AvgDialog_131222_Content_71 = {
    Text = "¡Señora Sorel! ¡Señora Sorel! ¿Cómo planea dividir los distritos comerciales? ¿Esto afectará...?"
  },
  AvgDialog_131222_Content_72 = {
    Text = "Shh, señor reportero. Acabo de regresar de un viaje de negocios. En cuanto tenga oportunidad de cambiarme, responderé a todas sus preguntas."
  },
  AvgDialog_131222_Content_73 = {
    Text = "Sorel se despide con un último gesto antes de desaparecer en las estancias privadas del piso superior."
  },
  AvgDialog_131222_Content_74 = {
    Text = "Parece que tendremos que esperar a que vuelva a salir."
  },
  AvgDialog_131222_Content_75 = {
    Text = "¿Te fijaste en la doncella que estaba junto a Sorel?"
  },
  AvgDialog_131222_Content_76 = {
    Text = "¿Karen? Sí, tampoco pareció oírme... espera, ¿qué estás diciendo?"
  },
  AvgDialog_131222_Content_77 = {
    Text = "Recuerdas el aura de Karen. Se sentía completamente errónea: incluso teniendo en cuenta las diferencias entre dimensiones, esa presencia no podía pertenecer a la chica que conocías."
  },
  AvgDialog_131222_Content_78 = {
    Text = "Percibo en ella un hilo del destino que no pertenece a este escenario. Su destino ha sido contaminado."
  },
  AvgDialog_131222_Content_79 = {
    Text = "¡La Señora Sorel está en peligro!"
  },
  AvgDialog_131222_Content_8 = {
    Text = "Hmph. Cuando mercaderes avaros como Fugen pueden entrar tan campantes en la antigua residencia del Duque, sabes que la gracia de Londinium ha desaparecido de verdad..."
  },
  AvgDialog_131222_Content_80 = {
    Text = "Te abres paso entre la multitud y encuentras una escalera de servicio oculta en la parte trasera del edificio."
  },
  AvgDialog_131222_Content_81 = {
    Text = "Mis disculpas, {Male=sir,Female=lady}, pero esta es la residencia privada de la Señora Sorel. No se permite el acceso sin autorización..."
  },
  AvgDialog_131222_Content_82 = {
    Text = "La Señora Sorel me invitó aquí para tratar un asunto urgente en privado."
  },
  AvgDialog_131222_Content_83 = {
    Text = "Sacas una servilleta que acabas de tomar de una mesa. Con un destello plateado, una identificación de oficial del Comité de revisión aparece en tu mano."
  },
  AvgDialog_131222_Content_84 = {
    Text = "Perdóneme, {Male=sir,Female=lady}, no lo sabía... La Señora Sorel está justo arriba. Puedo guiarle hasta..."
  },
  AvgDialog_131222_Content_85 = {
    Text = "Esta es una misión confidencial. No le digas a nadie que estuve aquí."
  },
  AvgDialog_131222_Content_86 = {
    Text = "Subes las escaleras a toda prisa antes de que el oficial pueda pronunciar otra palabra."
  },
  AvgDialog_131222_Content_87 = {Text = "..."},
  AvgDialog_131222_Content_88 = {
    Text = "¡Su vestido está listo, Señora Sorel!"
  },
  AvgDialog_131222_Content_89 = {
    Text = "Londinium es una jungla. Los políticos y los mercaderes son las hienas de esta ciudad..."
  },
  AvgDialog_131222_Content_9 = {
    Text = "Buenas noches, señor. Por favor, presente su invitación."
  },
  AvgDialog_131222_Content_90 = {
    Text = "Sorel toma el atuendo que Karen preparó. La luz del sol se filtra a través de la gasa roja, proyectando una vívida sombra carmesí sobre el lujoso dormitorio."
  },
  AvgDialog_131222_Content_91 = {
    Text = "Incluso las hienas tienen su encanto. Un solo trozo de carroña basta para hacerlas correr. Codiciosas, astutas, despiadadas e ingenuas: no hay mejor arma."
  },
  AvgDialog_131222_Content_92 = {
    Text = "Se han impacientado ahí fuera. Hoy has aparecido demasiado tarde, y este caro vestido ha quedado manchado."
  },
  AvgDialog_131222_Content_93 = {
    Text = "Debería haber regresado antes, señora."
  },
  AvgDialog_131222_Content_94 = {
    Text = "Sorel se detiene a medio movimiento. Baja el dobladillo carmesí de su falda y estudia la expresión plácida de Karen."
  },
  AvgDialog_131222_Content_95 = {
    Text = "Alguien debería haberte enseñado cómo una sirvienta se dirige a su Señora. ¿Qué te ha pasado hoy?"
  },
  AvgDialog_131222_Content_96 = {
    Text = "Señora Sorel, lleva encima la inmundicia del Distrito Este. Tengo curiosidad: ¿adónde envió a ese amable caballero?"
  },
  AvgDialog_131222_Content_97 = {
    Text = "La habitación iluminada se oscurece por un instante. Varias arañas negras emergen de las sombras, fusionándose en formas humanas que rodean a Sorel."
  },
  AvgDialog_131222_Content_98 = {
    Text = "Tiene una sirvienta muy leal, Señora Sorel. A pesar de su afición por robar y vender sus bienes, su devoción por su seguridad está fuera de toda duda."
  },
  AvgDialog_131222_Content_99 = {
    Text = "Incluso ahora, su voluntad lucha ferozmente contra mí. Una lástima, en realidad... ningún mortal puede resistir el poder del Destino."
  },
  AvgDialog_131223_Content_1 = {
    Text = "Destino. Destino salvaje, vacío, lamentable. Los destinos abandonados no saben de dónde vienen ni adónde van."
  },
  AvgDialog_131223_Content_10 = {
    Text = "La voz de Nefruri se volvió repentinamente aguda. Una luz oscura brilló, y hilos carmesí la ataron fuertemente, mientras el resplandor restante de la linterna abrasaba su cuerpo."
  },
  AvgDialog_131223_Content_11 = {
    Text = "Las enormes pinzas se mueven en el aire, unos grandes ojos compuestos, que gotean una sustancia negra y pegajosa, te miran a ustedes con una sonrisa. Hilos carmesí se entrelazan en su cuerpo, flotando en el vórtice del destino."
  },
  AvgDialog_131223_Content_12 = {
    Text = "A su lado, la rueda de hilar rota que reunía hilos giraba lenta e implacablemente, estrangulando todos los escenarios, estrangulando a Nefruri misma."
  },
  AvgDialog_131223_Content_13 = {Text = "Hmm—"},
  AvgDialog_131223_Content_14 = {
    Text = "Te agarras la cabeza con dolor. Bajo el giro de la rueca, tu mundo espiritual comienza a agitarse. Respiras profundamente, tratando de calmar ese intenso dolor."
  },
  AvgDialog_131223_Content_15 = {
    Text = "A su lado, los fragmentos del Pasaje dimensional de Nefruri ya son escasos. Las hebras en su cuerpo, esas texturas parecidas a marionetas, se vuelven cada vez más claras."
  },
  AvgDialog_131223_Content_16 = {
    Text = "¡La fuerza del canal dimensional... Ella ya está a punto de absorberlo por completo"
  },
  AvgDialog_131223_Content_17 = {
    Text = "Ceniza de color púrpura claro fluye sin cesar del interior de Arachne, como polillas que se lanzan hacia la Red del destino que está casi completamente destrozada."
  },
  AvgDialog_131223_Content_18 = {
    Text = "Las manos temblorosas de Arachne giraban la rueca en un ritmo inalterable desde tiempos inmemoriales. Su voz seguía siendo tan tranquila como cuando la viste por primera vez."
  },
  AvgDialog_131223_Content_19 = {
    Text = "Ya lo has visto. Este es el punto de encuentro del destino, Nefruri."
  },
  AvgDialog_131223_Content_2 = {
    Text = "Son atraídos por hilos de seda, avanzando hacia ti en oleadas, solo para disolverse en charcos de fango negro bajo tu resplandor plateado."
  },
  AvgDialog_131223_Content_20 = {
    Text = "Todos los errores terminarán aquí."
  },
  AvgDialog_131223_Content_21 = {
    Text = "Qué declaración tan confiada, señora prisionera. Entonces déjame ver con qué vas a detener a los dioses, a detener el destino mismo..."
  },
  AvgDialog_131223_Content_22 = {
    Text = "La risa loca florece en el rostro de Nefruri. Los hilos que la atan la levantan, en un escenario roto, ella es la única luz."
  },
  AvgDialog_131223_Content_23 = {
    Text = "\"¡Venid, fieles rastreros del mundo! ¡Inclinad vuestras cabezas y postraos ante mí!\""
  },
  AvgDialog_131223_Content_24 = {
    Text = "\"¡La Exaltada ha descendido del trono celestial! ¡El Fin Ineludible se revela aquí y ahora!\""
  },
  AvgDialog_131223_Content_25 = {
    Text = "\"Ese falso destino... ¡démosle la bienvenida a su destrucción, juntos!\""
  },
  AvgDialog_131223_Content_3 = {
    Text = "Limo salvaje, vacío, lamentable, como su propio destino."
  },
  AvgDialog_131223_Content_4 = {
    Text = "Nefruri no prestó atención a todo esto, la escena frente a ella se había repetido durante innumerables años, y ya estaba acostumbrada a ello."
  },
  AvgDialog_131223_Content_5 = {
    Text = "Lo he visto claro. Las imágenes que has visto, todo lo que has visto, finalmente lo he visto claro..."
  },
  AvgDialog_131223_Content_6 = {
    Text = "El dolor causado por los fragmentos ya había entumecido. Ella sonrió mientras miraba los caóticos vacíos en el teatro."
  },
  AvgDialog_131223_Content_7 = {
    Text = "Una sonrisa altiva, compasiva y distante, en un instante, casi no podías distinguirla de Arachne."
  },
  AvgDialog_131223_Content_8 = {
    Text = "Solo las personas que están en una jaula pueden realmente abrirla. El caos y la destrucción que ves no son el destino real, Nefruri..."
  },
  AvgDialog_131223_Content_9 = {
    Text = "¡Jejejeje! ... ¿Así que te has estado engañando a ti misma todos estos años, Arachne?"
  },
  AvgDialog_131224_Content_1 = {
    Text = "Público, actor, autor"
  },
  AvgDialog_131224_Content_10 = {Text = "¡Esto...!"},
  AvgDialog_131224_Content_100 = {
    Text = "Id, hijas mías. Encontrad a %player%."
  },
  AvgDialog_131224_Content_101 = {
    Text = "¡Apoderaos del poder de {Male=his,Female=her}, cortad cada hilo del Destino y destrozad la Gran Red! ¡Que toda alma que se interponga en nuestro camino perezca en ella!"
  },
  AvgDialog_131224_Content_102 = {
    Text = "Usaremos la sangre de este fragmento para despertar a la Gran Una Primordial una vez más."
  },
  AvgDialog_131224_Content_103 = {
    Text = "Cuando veas tu preciada Red del destino destrozada y reducida a un lodazal inmundo, ¿te hundirás en el vacío infinito igual que nosotras?"
  },
  AvgDialog_131224_Content_104 = {
    Text = "¿Diosa del destino, mi buena hermana, querida <Red:Arachne>?"
  },
  AvgDialog_131224_Content_105 = {
    Text = "La frontera entre el escenario y el público parece desvanecerse; el espacio mismo pierde todo significado."
  },
  AvgDialog_131224_Content_106 = {
    Text = "En medio de una risa escalofriante, la marioneta parece estar de pie frente a ustedes, mirando fijamente los ojos de Arachne."
  },
  AvgDialog_131224_Content_107 = {
    Text = "La luz se desvanece y el telón cae. La marioneta y su risa desaparecen, dejando el teatro vacío en silencio, salvo por el suave y rítmico zumbido de la rueca."
  },
  AvgDialog_131224_Content_108 = {
    Text = "Lo siento, no acabo de entender... ¿qué es exactamente el \"Destino Abandonado\"?"
  },
  AvgDialog_131224_Content_109 = {
    Text = "Como puedes ver, el Destino es una maraña de hilos en bruto. Si se dejara sin gestionar, el universo caería en un caos sin fondo. Creo que es un espectáculo que ninguno de nosotros desea contemplar."
  },
  AvgDialog_131224_Content_11 = {
    Text = "En el momento en que entras, la puerta a tu espalda se desvanece."
  },
  AvgDialog_131224_Content_110 = {
    Text = "Por supuesto..."
  },
  AvgDialog_131224_Content_111 = {
    Text = "Es mi deber eterno tejer esos hilos en la Red del destino, asegurando que el universo funcione como debe."
  },
  AvgDialog_131224_Content_112 = {
    Text = "En cada instante, el Destino alberga infinitas posibilidades. En cada instante, me veo obligada a tomar una decisión."
  },
  AvgDialog_131224_Content_113 = {
    Text = "Los destinos correctos se tejen en la Gran Telaraña; los erróneos se descartan. Así es como funciona la telaraña. Es inevitable."
  },
  AvgDialog_131224_Content_114 = {
    Text = "Mi hermana... es una parte de mí que descarté dentro de esos giros erróneos del Destino."
  },
  AvgDialog_131224_Content_115 = {
    Text = "Arachne sonríe, en su tranquila narración, no puedes percibir ni un atisbo de fluctuación emocional."
  },
  AvgDialog_131224_Content_116 = {
    Text = "¿Y esos destinos abandonados... se envían al \"Abismo\"?"
  },
  AvgDialog_131224_Content_117 = {
    Text = "Los sueños de la Deidad Suprema forman la sustancia de este universo. El Abismo es el subconsciente de ese Dios—un vertedero para cada evento que nunca ocurrió y cada destino que no existe."
  },
  AvgDialog_131224_Content_118 = {
    Text = "Se suponía que debían disolverse en la nada en ese vacío, pero bajo la guía de mi hermana, de algún modo encontraron una forma de sobrevivir."
  },
  AvgDialog_131224_Content_119 = {
    Text = "Arachne miraba esa enorme cortina, mirando detrás de la cortina, esa marioneta que representaba a Nefruri."
  },
  AvgDialog_131224_Content_12 = {
    Text = "Donde esperabas un interior estrecho se extiende un vasto espacio dimensional sin límites."
  },
  AvgDialog_131224_Content_120 = {
    Text = "Ella no puede tejer el destino como yo. Pero al igual que yo, puede ver los hilos. Los oscurece, los contamina y altera los senderos que he trazado, conduciéndolos hacia la muerte."
  },
  AvgDialog_131224_Content_121 = {
    Text = "¿Entonces quiere encontrarme y usar mi poder para despertar a Toguwaibo?"
  },
  AvgDialog_131224_Content_122 = {
    Text = "No puedo conocer su plan específico, pero todos los indicios apuntan a eso. En cualquier caso, es un error que debo rectificar."
  },
  AvgDialog_131224_Content_123 = {
    Text = "Así que por eso cerró el portal dimensional..."
  },
  AvgDialog_131224_Content_124 = {
    Text = "No, fui yo quien cerró el portal. Ella ha estado esperando este momento exacto—esperando para seguirte hasta Kadas."
  },
  AvgDialog_131224_Content_125 = {
    Text = "Kadas es una dimensión a la que mi poder nunca ha llegado. También es el lugar donde la conexión con la Deidad Suprema es más fuerte."
  },
  AvgDialog_131224_Content_126 = {
    Text = "Si ella te siguiera de vuelta allí, el desastre sería inevitable."
  },
  AvgDialog_131224_Content_127 = {
    Text = "Perdóname por tomarme tales libertades, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131224_Content_128 = {
    Text = "Entiendo, Arachne. Si lo que dices es cierto, entonces no es la visión que quiero ver."
  },
  AvgDialog_131224_Content_129 = {
    Text = "Entonces, si quiero volver a Kadas, primero tengo que ocuparme de ella..."
  },
  AvgDialog_131224_Content_13 = {
    Text = "Incontables escenarios flotan como estrellas en esta oscura inmensidad, con marionetas recitando sus líneas en cada uno de ellos."
  },
  AvgDialog_131224_Content_130 = {
    Text = "Mi señora, se ha detectado una anomalía en el escenario del Área GI-9849. Es la tercera de hoy."
  },
  AvgDialog_131224_Content_131 = {
    Text = "Después de robar los materiales para tejer el destino, ella siempre disfruta de destruir el destino."
  },
  AvgDialog_131224_Content_132 = {
    Text = "Mis disculpas, %player%, pero debo atender estas perturbaciones. Por favor, acompáñame. Hay asuntos vitales que necesito que veas."
  },
  AvgDialog_131224_Content_133 = {
    Text = "Arachne sonrió y sacudió la cabeza. Te hizo un gesto de invitación y se levantó con el huso."
  },
  AvgDialog_131224_Content_134 = {Text = "..."},
  AvgDialog_131224_Content_135 = {
    Text = "Este... ¿este es el escenario que fue destruido?"
  },
  AvgDialog_131224_Content_136 = {
    Text = "Siguiendo un camino tejido con seda de araña, llegas a un escenario destartalado. Dentro de un café improvisado en el decorado, unas cuantas personas con aspecto de estudiantes están apiñadas, susurrando."
  },
  AvgDialog_131224_Content_137 = {
    Text = "Últimamente, ha estado enviando a sus escuderos a sabotear los destinos de estos mundos. Mis doncellas los han estado cazando, pero las batallas le han costado la vida a muchos de mis buenos hijos."
  },
  AvgDialog_131224_Content_138 = {
    Text = "Los destinos de todos los mundos están unidos a la misma Gran Telaraña. Si un mundo colapsa, desgarra toda la estructura, sumiendo la existencia en un desorden absoluto y fatal."
  },
  AvgDialog_131224_Content_139 = {
    Text = "Nefruri robó los materiales para tejer el destino, no puedo usar mi fuerza fácilmente. Guardián {Male=señor, Female=señorita}, creo que tal vez usted pueda ayudarme a reparar el destino de este mundo?"
  },
  AvgDialog_131224_Content_14 = {
    Text = "Las palabras llegan hasta ti desde la distancia, como el murmullo de innumerables devotos en oración."
  },
  AvgDialog_131224_Content_140 = {
    Text = "Si tu historia es cierta, entonces ella es un problema del que debo ocuparme de todas formas."
  },
  AvgDialog_131224_Content_141 = {
    Text = "Arachne te asintió con una ligera disculpa. Levantó la mano y movió suavemente los hilos ocultos en el aire vacío."
  },
  AvgDialog_131224_Content_142 = {Text = "Dong——"},
  AvgDialog_131224_Content_143 = {
    Text = "Tras un agudo tintineo musical, la melodiosa voz del presentador resuena como un arroyo eterno fluyendo hacia un estanque profundo."
  },
  AvgDialog_131224_Content_144 = {
    Text = "¡Las trompetas tocan una fanfarria. Entran: la estudiante y el erudito!"
  },
  AvgDialog_131224_Content_145 = {
    Text = "Arachne hace un gesto de invitación."
  },
  AvgDialog_131224_Content_146 = {
    Text = "Es hora de nuestra entrada, %player%."
  },
  AvgDialog_131224_Content_147 = {
    Text = "Asientes. Al sonido de la llamada del presentador, dos marionetas suben al escenario que ha sido preparado para ellas."
  },
  AvgDialog_131224_Content_15 = {
    Text = "Hilos de seda se extienden desde cada marioneta y cada escenario, convergiendo con el sendero tejido de seda bajo tus pies hacia el único escenario en el centro mismo de este espacio."
  },
  AvgDialog_131224_Content_16 = {
    Text = "Te das la vuelta. La doncella ya se ha adelantado."
  },
  AvgDialog_131224_Content_17 = {
    Text = "Vaya bienvenida más extraña..."
  },
  AvgDialog_131224_Content_18 = {
    Text = "Dudas, y luego avanzas por el sendero semejante a una telaraña hacia el escenario central. Al pasar junto a los escenarios flotantes, fragmentos de conversación llegan a tus oídos."
  },
  AvgDialog_131224_Content_19 = {
    Text = "Mi querido cliente, veo confusión en sus ojos."
  },
  AvgDialog_131224_Content_2 = {
    Text = "Hay una pregunta más que quiero hacer..."
  },
  AvgDialog_131224_Content_20 = {
    Text = "Espero que el incidente de hace un momento no le haya asustado demasiado, ?no?"
  },
  AvgDialog_131224_Content_21 = {
    Text = "Una base de ginebra con un toque de hibisco—creo que le sentaría perfectamente en este momento."
  },
  AvgDialog_131224_Content_22 = {Text = "..."},
  AvgDialog_131224_Content_23 = {
    Text = "!Ah! Una criatura sin hogar, tan pequeña, tan perdida."
  },
  AvgDialog_131224_Content_24 = {
    Text = "Con solo esas ropas tan finas, ?cómo vas a sobrevivir al invierno?"
  },
  AvgDialog_131224_Content_25 = {
    Text = "Ven conmigo. Déjame encontrarte un lugar donde refugiarte de la tormenta..."
  },
  AvgDialog_131224_Content_26 = {Text = "..."},
  AvgDialog_131224_Content_27 = {
    Text = "Estas... ?son las personas con las que acabo de cruzarme?"
  },
  AvgDialog_131224_Content_28 = {
    Text = "Cómo han acabado en estos escenarios..."
  },
  AvgDialog_131224_Content_29 = {
    Text = "Un oficial de patrulla, un empleado leyendo el periódico, un conductor observando la calle, amantes comprando flores, nobles a mitad de conversación..."
  },
  AvgDialog_131224_Content_3 = {
    Text = "Esa ya es tu vigésimo tercera pregunta, %player%."
  },
  AvgDialog_131224_Content_30 = {
    Text = "Aquellos que has conocido y aquellos que nunca conocerás, todos ellos representando sus propias historias en incontables escenarios. En cada uno de sus propios escenarios, cada uno de ellos es el protagonista."
  },
  AvgDialog_131224_Content_31 = {
    Text = "¡Ave, %player%! ¡Bendecido sea, infante de Akut!"
  },
  AvgDialog_131224_Content_32 = {
    Text = "¡Ave, %player%! ¡Bendecido sea, Guardián de Misaq!"
  },
  AvgDialog_131224_Content_33 = {
    Text = "¡Ave, %player%! ¡Bendecido sea, dios de la destrucción!"
  },
  AvgDialog_131224_Content_34 = {
    Text = "Al acercarte al escenario central, tres marionetas de distintas formas suben a él y hacen una reverencia en tu dirección."
  },
  AvgDialog_131224_Content_35 = {
    Text = "La Señora te espera dentro. Por favor, pasa... Guardián {Male=Mr.,Female=Miss}."
  },
  AvgDialog_131224_Content_36 = {
    Text = "Cuando la puerta del palco se abre, las imágenes y los sonidos de todo el teatro parecen detenerse durante un único instante suspendido."
  },
  AvgDialog_131224_Content_37 = {
    Text = "Cruzas el umbral y descorres la cortina..."
  },
  AvgDialog_131224_Content_38 = {
    Text = "Aparecen en estos escenarios porque este teatro lleva un único nombre: Destino."
  },
  AvgDialog_131224_Content_39 = {
    Text = "Una voz serena y pausada te alcanza antes que cualquier color."
  },
  AvgDialog_131224_Content_4 = {
    Text = "Comparadas con los misterios de este lugar, veintitrés no son ni de lejos suficientes."
  },
  AvgDialog_131224_Content_40 = {
    Text = "En un palco que parece no tener paredes, los hilos que conectan cada escenario y cada marioneta convergen en un huso que emite un tenue resplandor. Una mujer se sienta en el punto donde todos los hilos se encuentran, haciéndolo girar con mano delicada."
  },
  AvgDialog_131224_Content_41 = {
    Text = "Ves cada detalle de ella con perfecta claridad. Sin embargo, con cada parpadeo, toda impresión se desvanece de tu mente, sin dejar nada atrás."
  },
  AvgDialog_131224_Content_42 = {
    Text = "Su imagen se niega a permanecer. Cuando ella gira la cabeza para mirarte, tu corazón —tenso por la vigilancia todo este tiempo— se desboca en un latido violento."
  },
  AvgDialog_131224_Content_43 = {
    Text = "¡¿Eres tú?!!"
  },
  AvgDialog_131224_Content_44 = {
    Text = "En el Paradeis... ¡y esos ataques...!"
  },
  AvgDialog_131224_Content_45 = {
    Text = "En el momento en que te preparas para canalizar tu energía espiritual hacia la Llave de plata, la señora del teatro extiende la mano. Su mano surca el aire con una gracia tan delicada que parece como si pulsara una cuerda invisible."
  },
  AvgDialog_131224_Content_46 = {Text = "¡!!!"},
  AvgDialog_131224_Content_47 = {
    Text = "La energía espiritual fluye hasta la punta de tus dedos, solo para retroceder como una inundación golpeando una presa enorme. Al levantar la mano, una sacudida de conmoción te golpea: tu palma está vacía. La llave ha desaparecido."
  },
  AvgDialog_131224_Content_48 = {
    Text = "La Llave de plata... La tenía en la mano hace apenas un segundo... ¿Cómo...?"
  },
  AvgDialog_131224_Content_49 = {
    Text = "La señora esboza una leve sonrisa y le hace un pequeño gesto con la cabeza a su doncella."
  },
  AvgDialog_131224_Content_5 = {
    Text = "No soy quien estáis buscando. La persona que puede responder a vuestras preguntas os espera justo adelante."
  },
  AvgDialog_131224_Content_50 = {
    Text = "Ante tu mirada atónita, la doncella se adelanta y deposita respetuosamente la Llave de plata de vuelta en tu mano."
  },
  AvgDialog_131224_Content_51 = {
    Text = "Imposible... ¡No hay forma de que me la haya podido robar!"
  },
  AvgDialog_131224_Content_52 = {
    Text = "Antes de entrar al teatro, sujetabas esa llave con fuerza, manteniendo un vínculo espiritual constante."
  },
  AvgDialog_131224_Content_53 = {
    Text = "Tu entrenamiento en Misaq te ha otorgado un nivel de vigilancia tan alto que nadie podría jamás esperar arrebatártela."
  },
  AvgDialog_131224_Content_54 = {
    Text = "Entonces, por qué..."
  },
  AvgDialog_131224_Content_55 = {
    Text = "Ninguna persona podría quitártela. Pero el Destino sí puede."
  },
  AvgDialog_131224_Content_56 = {
    Text = "Perdóname, %player%. Comprendo tu ansiedad y respeto tu poder."
  },
  AvgDialog_131224_Content_57 = {
    Text = "Para evitar cualquier daño involuntario a mi teatro, no tuve más remedio que alterar brevemente el destino de la llave en tu mano. Espero que puedas disculpar esta libertad."
  },
  AvgDialog_131224_Content_58 = {
    Text = "Agita una mano y un haz de luz atraviesa el espacio entre ustedes. Al mirar con atención, ves un hilo tenue, casi imperceptible, que se extiende desde la Llave de plata y se pierde hasta la rueca a su lado."
  },
  AvgDialog_131224_Content_59 = {
    Text = "Estos hilos... ¿qué son?"
  },
  AvgDialog_131224_Content_6 = {
    Text = "Te detienes ante la entrada de un teatro apenas lo bastante ancha para una persona. Sin cartel, sin clientes—un hilo de telaraña insignificante oculto entre las grandiosas fachadas de Londinium."
  },
  AvgDialog_131224_Content_60 = {
    Text = "Hay muchas explicaciones para los hilos, la mayoría demasiado complejas para este momento. Puedes simplemente pensar en ellos como... el Destino."
  },
  AvgDialog_131224_Content_61 = {
    Text = "La rueca gira suavemente por sí sola. Ella se pone de pie y ofrece una elegante reverencia a modo de saludo."
  },
  AvgDialog_131224_Content_62 = {
    Text = "Arachne, la dueña del Teatro del destino. Es un honor conocerle, Guardián."
  },
  AvgDialog_131224_Content_63 = {
    Text = "Por favor, tranquilízate. Aquí estás a salvo."
  },
  AvgDialog_131224_Content_64 = {
    Text = "Supongo que sí. Si me quisieras muerto, no habría sobrevivido a esa demostración de hace un momento."
  },
  AvgDialog_131224_Content_65 = {
    Text = "A medida que Arachne mueve los hilos, la luz de las ruecas en el palco se atenúa. Miras con una expresión compleja la llave de plata que la sirvienta te devuelve, frunciendo el ceño hacia ella."
  },
  AvgDialog_131224_Content_66 = {
    Text = "En el Paradeis, me ayudaste. Pero desde que llegué a esta ciudad, me has atacado dos veces."
  },
  AvgDialog_131224_Content_67 = {
    Text = "Entiendo tu cautela. Pero por favor, créeme cuando digo que nunca he movido un dedo para hacerte daño."
  },
  AvgDialog_131224_Content_68 = {
    Text = "Bloqueaste mi conexión con Kadas y me tendiste emboscadas varias veces... ¿me estás diciendo que nada de eso fue obra tuya?"
  },
  AvgDialog_131224_Content_69 = {
    Text = "Quien te causó problemas puede compartir mi rostro, pero no soy yo."
  },
  AvgDialog_131224_Content_7 = {
    Text = "La doncella empuja la puerta con suavidad y se desliza hacia la oscuridad del interior. Una tenue luz parpadea dentro sin origen discernible, como una invitación silenciosa y oculta."
  },
  AvgDialog_131224_Content_70 = {
    Text = "En cuanto a tu conexión con Kadas... eso es una trampa peligrosa, %player%."
  },
  AvgDialog_131224_Content_71 = {Text = "¿Trampa?"},
  AvgDialog_131224_Content_72 = {
    Text = "Una criatura nacida de mi propia existencia os ha causado un sufrimiento innecesario, y por ello, lo lamento profundamente. Esta situación comenzó conmigo, y estoy haciendo todo lo que está en mi poder para enmendar el error."
  },
  AvgDialog_131224_Content_73 = {
    Text = "No os sigo..."
  },
  AvgDialog_131224_Content_74 = {
    Text = "Es una larga historia, y una ligada a la naturaleza del Destino. Las historias siempre son más fáciles de digerir que los hechos desnudos."
  },
  AvgDialog_131224_Content_75 = {
    Text = "Por favor, tomad asiento, {Male=Mr.,Female=Miss} Guardián. Este nuevo acto de nuestra obra comenzó hace apenas poco tiempo."
  },
  AvgDialog_131224_Content_76 = {
    Text = "Arachne agita suavemente la mano. Se abre el telón y aparece ante ti un escenario vacío que flota."
  },
  AvgDialog_131224_Content_77 = {
    Text = "Un espejo resplandeciente y etéreo se alza sobre el escenario, reflejando las siluetas de ambos."
  },
  AvgDialog_131224_Content_78 = {
    Text = "Las trompetas suenan con una fanfarria. Entra en escena: El destino abandonado."
  },
  AvgDialog_131224_Content_79 = {
    Text = "Pronto, tu figura desapareció del espejo y la figura de Arachne se convirtió en una marioneta."
  },
  AvgDialog_131224_Content_8 = {
    Text = "Dudas un instante y luego cruzas el umbral."
  },
  AvgDialog_131224_Content_80 = {
    Text = "La marioneta permanece sentada, pero su serena compostura se ha evaporado."
  },
  AvgDialog_131224_Content_81 = {
    Text = "Hace girar una copa llena de un caldo rojo sangre como si estuviera entronizada sobre un asiento de matanza. Sus ojos, inocentes pero absolutamente despiadados, recorren al público."
  },
  AvgDialog_131224_Content_82 = {
    Text = "Tras la marioneta, cuatro pares de extremidades arácnidas afiladas como cuchillas se balancean perezosamente, con las puntas rozando las mejillas de los asistentes que se encuentran cerca."
  },
  AvgDialog_131224_Content_83 = {
    Text = "Ah, el dulce aroma de la libertad..."
  },
  AvgDialog_131224_Content_84 = {
    Text = "¿Cuántos años estuvimos pudriéndonos en ese Abismo, mi querido escudero?"
  },
  AvgDialog_131224_Content_85 = {
    Text = "No lo sé, mi señora."
  },
  AvgDialog_131224_Content_86 = {
    Text = "Nombre, tiempo, emociones... he olvidado todo... solo recuerdo a usted, mi maestro, respetada Nefruri."
  },
  AvgDialog_131224_Content_87 = {
    Text = "Solo recuerdo vuestra promesa: que nos guiaríais hacia la salida, y que blandiríamos la espada de la venganza contra el Destino mismo."
  },
  AvgDialog_131224_Content_88 = {
    Text = "Lo recuerdo, criatura. Os hice noventa mil promesas, y ahora, dejadme haceros la noventa mil y una."
  },
  AvgDialog_131224_Content_89 = {
    Text = "En cualquier momento dado, solo un destino puede existir verdaderamente. El Executor del Destino poda los incontables destinos \"erróneos\", dejando solo el único camino \"verdadero\" detrás."
  },
  AvgDialog_131224_Content_9 = {Text = "..."},
  AvgDialog_131224_Content_90 = {
    Text = "Somos el destino abandonado. Je... mi querido escudero, sois un error. Solo como yo."
  },
  AvgDialog_131224_Content_91 = {
    Text = "En el subconsciente de este universo, dentro de ese vacío de un Abismo, fuimos exiliados y enjaulados. Vagamos allí, olvidados, por toda la eternidad. Nuestra condena ha sobrevivido al tiempo mismo..."
  },
  AvgDialog_131224_Content_92 = {
    Text = "La mujer llamada Nefruri se levantó de su asiento, se inclinó y sonrió mientras miraba a Arachne en la audiencia."
  },
  AvgDialog_131224_Content_93 = {
    Text = "Pero ¿con qué derecho, oh Diosa del Destino? ¿Por qué debemos ser nosotras las descartadas?"
  },
  AvgDialog_131224_Content_94 = {
    Text = "La deidad suprema y singular del cosmos infinito finalmente se agitó por un instante fugaz. Ha vuelto a sumirse en su letargo, pero la prisión de Su consciencia —el eterno Abismo— al fin se ha resquebrajado para nosotras."
  },
  AvgDialog_131224_Content_95 = {
    Text = "Ya había aceptado el olvido. Me había desvanecido. Entonces, ¿por qué... por qué debo ser obligada a recordar toda esta agonía?"
  },
  AvgDialog_131224_Content_96 = {
    Text = "Nefruri bebió el líquido de la copa y soltó un suspiro de satisfacción. El jugo rojo brillante goteó por sus labios pálidos y cayó sobre la oscura rueca que sostenía en la mano."
  },
  AvgDialog_131224_Content_97 = {
    Text = "Quizás esta sea la voluntad del Destino... un destino que ni siquiera tú puedes controlar."
  },
  AvgDialog_131224_Content_98 = {
    Text = "La Deidad Primordial duerme de nuevo, pero Sus fragmentos han encontrado el camino hasta nuestra puerta."
  },
  AvgDialog_131224_Content_99 = {
    Text = "No poseo tu don para tejer el destino. Soy simplemente una correctora del Destino, una ejecutora del vacío. Castigaré los pecados en el río del tiempo en nombre de la Una Primordial."
  },
  AvgDialog_131225_Content_1 = {
    Text = "Sombra del pasado"
  },
  AvgDialog_131225_Content_10 = {
    Text = "Esta villa es completamente diferente de la vasta que imaginaste con tu experiencia; su interior parece anormalmente abarrotado, y Nefruri parece decidida a escribir desordenadamente en su guion."
  },
  AvgDialog_131225_Content_11 = {
    Text = "Interminables filas de armarios y estantes se alzan en silencio, cada centímetro de espacio repleto de frascos de diversos tamaños."
  },
  AvgDialog_131225_Content_12 = {
    Text = "Espejos de plata, huevos de araña, zapatillas de baile infestadas de extraños insectos... objetos preservados en fluidos sospechosos, pareciendo bocas congeladas en un grito silencioso."
  },
  AvgDialog_131225_Content_13 = {
    Text = "Te acercas a los frascos y lees las etiquetas en voz alta."
  },
  AvgDialog_131225_Content_14 = {
    Text = "<Italic:\"Dos años. Pronunció sus primeras palabras. No fue una llamada a la familia, sino una despedida al viejo mayordomo que sirvió a la casa durante generaciones.\">"
  },
  AvgDialog_131225_Content_15 = {
    Text = "<Italic:\"Esa misma noche, el mayordomo murió de un fallo cardíaco. Llorando frente a la caseta del portón, aferrándose a sus pertenencias...\">"
  },
  AvgDialog_131225_Content_16 = {
    Text = "Es un viejo broche familiar."
  },
  AvgDialog_131225_Content_17 = {
    Text = "<Italic:\"Cinco años. Bailando un tímido vals igual que madre, entre los sonrojados aplausos de los invitados a la cena...\">"
  },
  AvgDialog_131225_Content_18 = {
    Text = "Es un par de vibrantes zapatillas de baile rojas."
  },
  AvgDialog_131225_Content_19 = {
    Text = "<Italic:\"Siete años. Recibió un regalo de cumpleaños de padre: una rueca llamada Moira.\">"
  },
  AvgDialog_131225_Content_2 = {
    Text = "Calle Brick. Recuerdas tus investigaciones anteriores en esta parte de Londinium."
  },
  AvgDialog_131225_Content_20 = {
    Text = "<Italic:\"Vio la sombra del Destino proyectada entre los hilos...\">"
  },
  AvgDialog_131225_Content_21 = {
    Text = "Es un puñado de hilo roto."
  },
  AvgDialog_131225_Content_22 = {
    Text = "<Italic:\"Primera visita a la ópera con sus padres... Primera vez que conoció a un alma gemela... Primera vez que enterró a un perro querido...\">"
  },
  AvgDialog_131225_Content_23 = {
    Text = "Las palabras en las etiquetas de los frascos se proyectan una a una en tu ojo. Cada vez que las tocas, un recuerdo borroso aparece vagamente en tu mente. Te das la vuelta y miras a Arachne con curiosidad."
  },
  AvgDialog_131225_Content_24 = {
    Text = "Estos... ¿son tus recuerdos?"
  },
  AvgDialog_131225_Content_25 = {
    Text = "Fueron míos, en su día. Hace mucho tiempo, fueron entregados al objeto secreto llamado 'Homenaje'."
  },
  AvgDialog_131225_Content_26 = {
    Text = "Son muy valiosos. ¿Por qué los pondrías dentro de un objeto secreto?"
  },
  AvgDialog_131225_Content_27 = {
    Text = "Todos debemos tomar decisiones. Y cada decisión tiene un precio."
  },
  AvgDialog_131225_Content_28 = {
    Text = "Para llegar al final del camino, siempre hay que dejar algo atrás. Creo que tú lo entiendes mejor que nadie, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131225_Content_29 = {
    Text = "Arachne no respondió directamente a tu pregunta, ella miró los armarios y pasó suavemente la mano sobre los frascos llenos de líquido."
  },
  AvgDialog_131225_Content_3 = {
    Text = "Sucia y caótica. El aire está cargado de humo de carbón y aguas residuales—los olores que definieron las vidas de Mason y Jenkin."
  },
  AvgDialog_131225_Content_30 = {
    Text = "Su tacto es suave y lento, como el de una anciana acariciando con ternura los juguetes queridos de su infancia."
  },
  AvgDialog_131225_Content_31 = {
    Text = "Extrae estos recuerdos del objeto secreto y manifiéstate en esta forma. Este es el paisaje que preparaste para mí, Nefruri."
  },
  AvgDialog_131225_Content_32 = {
    Text = "Oigo lo que intentas decirme..."
  },
  AvgDialog_131225_Content_33 = {
    Text = "<Big:<Shake:¡¡¡AAAHHHH!!!—>>"
  },
  AvgDialog_131225_Content_34 = {
    Text = "Un alarido penetrante resuena por toda la sala. Los frascos de recuerdos traquetean, como una multitud de espectadores silenciosos y risueños."
  },
  AvgDialog_131225_Content_35 = {
    Text = "!! ¡Viene de la habitación al final del pasillo!"
  },
  AvgDialog_131225_Content_36 = {Text = "Bang—"},
  AvgDialog_131225_Content_37 = {
    Text = "Corres por el pasillo a toda velocidad, abres la puerta de una patada..."
  },
  AvgDialog_131225_Content_38 = {
    Text = "...y entras en un aguacero torrencial."
  },
  AvgDialog_131225_Content_39 = {
    Text = "No hay truenos, ni viento, ni lluvia. Solo un diluvio de arañas cayendo del techo como una tormenta."
  },
  AvgDialog_131225_Content_4 = {
    Text = "De repente, una magnífica villa dorada aparece entre dos chabolas, como un joyero arrojado a un montón de chatarra."
  },
  AvgDialog_131225_Content_40 = {
    Text = "La masa de pegajosas patas negras de arácnido forma una marea creciente que devora cada objeto y cada rastro de luz."
  },
  AvgDialog_131225_Content_41 = {
    Text = "En el centro de la oscura tormenta, las arañas que pululan y roen se fusionan en una forma humana. Donde la marea aún no ha llegado, un rostro marchito y familiar asoma entre ellas."
  },
  AvgDialog_131225_Content_42 = {
    Text = "Arachne......señorita......"
  },
  AvgDialog_131225_Content_43 = {
    Text = "Correr... ¡sal de aquí...!"
  },
  AvgDialog_131225_Content_44 = {
    Text = "Shh... no tienes líneas en esta escena, Sr. Amabilidad."
  },
  AvgDialog_131225_Content_45 = {
    Text = "La venganza del Destino, Segundo acto, escena dos. La llamo \"Aguacero\"."
  },
  AvgDialog_131225_Content_46 = {
    Text = "Disfruten de la lluvia, mi querido público."
  },
  AvgDialog_131225_Content_47 = {
    Text = "El líquido acumulado se agita. Obedeciendo una orden suprema, las arañas negras inundan cada rincón de la sala."
  },
  AvgDialog_131225_Content_48 = {
    Text = "En los elogios de Nefruri, los guardias y servidores formados por arañas, junto con criaturas repugnantes, se abalanzan hacia ustedes—"
  },
  AvgDialog_131225_Content_5 = {
    Text = "Vagabundos y trabajadores exhaustos pasan junto a la ornamentada estructura sin dedicarle una segunda mirada, como si hubiera estado ahí desde el principio de los tiempos."
  },
  AvgDialog_131225_Content_6 = {
    Text = "Incluso el destino de esta ciudad se ha visto afectado... La fuerza de Nefruri, de hecho, está aumentando."
  },
  AvgDialog_131225_Content_7 = {
    Text = "Te acercas con cautela. Solo cuando extiendes la mano para llamar, la puerta se abre en silencio."
  },
  AvgDialog_131225_Content_8 = {
    Text = "Parece que nuestra considerada anfitriona nos ha dejado la puerta abierta."
  },
  AvgDialog_131225_Content_9 = {Text = "Eso es..."},
  AvgDialog_131226_Content_1 = {
    Text = "!!E–están muertos!!"
  },
  AvgDialog_131226_Content_10 = {
    Text = "Lo vi todo. No pasaste por ese portal, %player%. Este no es el lugar donde debemos estar."
  },
  AvgDialog_131226_Content_11 = {
    Text = "Todo se siente extraño... la Fusión, los Misaq, las Catástrofes... no saben nada de nada."
  },
  AvgDialog_131226_Content_12 = {
    Text = "Pero esta ciudad se ve exactamente como la recuerdo. Exactamente como era antes del Toguwaibo. Quizás deberíamos volver a la escuela y echar un vistazo. Podríamos encontrar algo..."
  },
  AvgDialog_131226_Content_13 = {
    Text = "Acabo de venir de allí. No hay Misaq aquí, %player%."
  },
  AvgDialog_131226_Content_14 = {
    Text = "?Sin Misaq...?"
  },
  AvgDialog_131226_Content_15 = {
    Text = "El mapa del mundo en la tienda era diferente a todo lo que he visto. Y todos los calendarios que encontré... son diferentes. No es el calendario del Desbordamiento que usamos."
  },
  AvgDialog_131226_Content_16 = {
    Text = "Lo más extraño es... que esta ciudad no tiene fin."
  },
  AvgDialog_131226_Content_17 = {
    Text = "No... ¿tiene fin?"
  },
  AvgDialog_131226_Content_18 = {
    Text = "Dirigirse al norte desde donde debería estar Misaq tendría que llevarte más allá de los límites de Londinium."
  },
  AvgDialog_131226_Content_19 = {
    Text = "Fui atacado por esas arañas en el camino. Para escapar de ellas, seguí por ese camino. Pero al final... me encontré de vuelta cerca de donde estabais vosotros. El extremo sur de Londinium."
  },
  AvgDialog_131226_Content_2 = {
    Text = "La multitud grita y se dispersa. Antes de que siquiera te dieras cuenta, William está ahí a tu lado, ese cabello dorado inconfundible como siempre."
  },
  AvgDialog_131226_Content_20 = {
    Text = "Esto no es Londinium. Esto no es Kadas."
  },
  AvgDialog_131226_Content_21 = {
    Text = "Así que mi memoria no me fallaba... la puerta realmente se cerró antes de que pudiera entrar..."
  },
  AvgDialog_131226_Content_22 = {
    Text = "Alzas la mirada hacia los paisajes familiares más allá del pasaje y suspiras, mientras una sensación de vacío se asienta en tu interior."
  },
  AvgDialog_131226_Content_23 = {
    Text = "Un lugar idéntico a Londinium, una ciudad sin fin, arañas negras que aparecen de la nada... y la \"Dama\" a la que obedecen..."
  },
  AvgDialog_131226_Content_24 = {
    Text = "Es demasiado pronto para estar seguros, pero no creo que el cierre de la puerta y nuestra llegada aquí sean una coincidencia. Alguien orquestó todo esto deliberadamente—quien sea que comande a esas arañas."
  },
  AvgDialog_131226_Content_25 = {
    Text = "Aún no entendemos nada. Primero necesitamos reunir información..."
  },
  AvgDialog_131226_Content_26 = {
    Text = "Vosotros dos..."
  },
  AvgDialog_131226_Content_27 = {Text = "¿Quién?!"},
  AvgDialog_131226_Content_28 = {
    Text = "Un resplandor plateado destella en la palma mecánica de William, el compañero mayor, como una hoja lista para ser desenvainada en cualquier momento."
  },
  AvgDialog_131226_Content_29 = {
    Text = "En ese peligroso brillo plateado, distingues al anciano que acababa de intentar ofrecerte comida."
  },
  AvgDialog_131226_Content_3 = {
    Text = "William, el compañero mayor... ?cuándo has...? ?qué está pasando?"
  },
  AvgDialog_131226_Content_30 = {
    Text = "Soy... solo soy yo..."
  },
  AvgDialog_131226_Content_31 = {
    Text = "Esto... ¿esto os pertenece?"
  },
  AvgDialog_131226_Content_32 = {
    Text = "El anciano abre la mano. La insignia escolar de Misaq—tu comunicador—reposa en silencio sobre su áspera palma."
  },
  AvgDialog_131226_Content_33 = {
    Text = "¡Ah! Debió de caerse durante la pelea..."
  },
  AvgDialog_131226_Content_34 = {
    Text = "Esto significa mucho para mí... ¡muchísimas gracias!"
  },
  AvgDialog_131226_Content_35 = {
    Text = "Bajo la atenta mirada de William, el compañero mayor, recuperas la insignia y la guardas con cuidado."
  },
  AvgDialog_131226_Content_36 = {
    Text = "Señor... ¿no se asustó por lo que acaba de pasar?"
  },
  AvgDialog_131226_Content_37 = {
    Text = "Asustado... por supuesto que sí. He vivido aquí toda mi vida. Nunca había visto nada semejante..."
  },
  AvgDialog_131226_Content_38 = {
    Text = "Pero esa cosa parecía importante para ti, y acabáis de llegar—si la perdías, no tendrías ni idea de por dónde empezar a buscar. Así que la traje."
  },
  AvgDialog_131226_Content_39 = {
    Text = "Qué amable de tu parte... gracias."
  },
  AvgDialog_131226_Content_4 = {
    Text = "Este no es el lugar. !!Muévete!"
  },
  AvgDialog_131226_Content_40 = {
    Text = "Acabamos de llegar y hay muchas cosas que desconocemos. ¿Te importaría si te hacemos algunas preguntas?"
  },
  AvgDialog_131226_Content_41 = {
    Text = "No me importa pasar un poco más de tiempo con ustedes dos, pero me temo que sé muy poco sobre lo que buscan."
  },
  AvgDialog_131226_Content_42 = {
    Text = "Un lugar con más gente quizá les sea de más ayuda, supongo."
  },
  AvgDialog_131226_Content_43 = {
    Text = "Bien, ya devolví lo que había que devolver. Me marcho."
  },
  AvgDialog_131226_Content_44 = {
    Text = "El anciano desestima tus cortesías de despedida con un gesto de la mano mientras sale del callejón."
  },
  AvgDialog_131226_Content_45 = {
    Text = "No parece tener malas intenciones. Tiene razón: necesitamos encontrar un lugar donde la información fluya con más libertad, y rápido."
  },
  AvgDialog_131226_Content_46 = {
    Text = "¡Conozco el lugar perfecto!"
  },
  AvgDialog_131226_Content_47 = {
    Text = "Si esta ciudad realmente es un reflejo de Londinium, entonces ese lugar debería ser exactamente lo que necesitamos."
  },
  AvgDialog_131226_Content_48 = {
    Text = "Al marcharte, una araña de un pálido violeta acecha justo en el borde de tu visión, deslizándose por su hilo y colándose en una grieta del muro, desapareciendo sin dejar rastro."
  },
  AvgDialog_131226_Content_5 = {
    Text = "William, el compañero mayor, te agarra y se dirige en dirección opuesta a la multitud."
  },
  AvgDialog_131226_Content_6 = {Text = "..."},
  AvgDialog_131226_Content_7 = {
    Text = "No debería haber nadie por aquí."
  },
  AvgDialog_131226_Content_8 = {
    Text = "?Qué está pasando? ?Por qué Londinium se ha convertido en esto...?"
  },
  AvgDialog_131226_Content_9 = {
    Text = "Esas arañas que nos atacaron, y esa persona... ?podría estar conectada con la mujer que encontramos en el Paradeis?"
  },
  AvgDialog_131227_Content_1 = {
    Text = "¡Tawil! Yo..."
  },
  AvgDialog_131227_Content_2 = {
    Text = "Entiendo, Guardián."
  },
  AvgDialog_131227_Content_3 = {
    Text = "Tu destino ha sido modificado. No puedes detenerte, ni deberías detenerte."
  },
  AvgDialog_131227_Content_4 = {
    Text = "Arachne no puede declarar el destino del futuro... Por favor, dime, ¿qué debería hacer...?"
  },
  AvgDialog_131227_Content_5 = {
    Text = "No puedo explicarte lo que hay detrás de la puerta. En este asunto, hay alguien más adecuado que yo para ayudarte."
  },
  AvgDialog_131227_Content_6 = {
    Text = "Sigue adelante, Guardián del Secreto. Tu destino necesita ser aclarado por ti mismo."
  },
  AvgDialog_131228_Content_1 = {
    Text = "Mm... héroes y bufones, marionetas del destino... buena trama."
  },
  AvgDialog_131228_Content_2 = {
    Text = "Arachne me dijo que la llave para abrir el candado es \"Alegría\"... este es tu dominio, N."
  },
  AvgDialog_131228_Content_3 = {
    Text = "¡Shh! No te apresures tanto. Destruir una buena actuación es el pecado más imperdonable de este universo."
  },
  AvgDialog_131228_Content_4 = {
    Text = "Vamos, Guardián del Secreto. Ha pasado tanto tiempo, déjame ver si has tenido algunas nuevas percepciones sobre la alegría?"
  },
  AvgDialog_131229_Content_10 = {
    Text = "Respóndeme... ¡Liz!"
  },
  AvgDialog_131229_Content_11 = {
    Text = "Sus hilos del Destino están cortados. Su vida se ha extinguido."
  },
  AvgDialog_131229_Content_12 = {
    Text = "<Shake:No... no podemos permitir que Nefruri salga con la suya>¡Ella debe pagar por su imprudencia"
  },
  AvgDialog_131229_Content_13 = {
    Text = "El Destino ya ha preparado el precio que debe pagar. El rastro no termina aquí."
  },
  AvgDialog_131229_Content_14 = {
    Text = "Pero acabas de decir que Liz está..."
  },
  AvgDialog_131229_Content_15 = {
    Text = "La muerte no es más que una parte del Destino. Este es mi escenario, {Male=Mr.,Female=Miss} Guardián. Todos los destinos son hilos en mis manos, y solo yo tejo su curso."
  },
  AvgDialog_131229_Content_16 = {Text = "¡!!!"},
  AvgDialog_131229_Content_17 = {
    Text = "<Shake:Espera, quieres decir...>"
  },
  AvgDialog_131229_Content_18 = {
    Text = "El rostro de Arachne no mostraba ni tristeza ni alegría. Ella se acercó al anunciador que había sido brevemente parasitado por Nefruri. La tenue luz del crepúsculo delineaba su silueta difusa y estable, como el destino mismo."
  },
  AvgDialog_131229_Content_19 = {
    Text = "Je... jajaja... Arachne, ¡sigues siendo tan, tan arrogante! jajaja..."
  },
  AvgDialog_131229_Content_2 = {
    Text = "Los enemigos a tu alrededor caen, pero no te detienes."
  },
  AvgDialog_131229_Content_20 = {
    Text = "Nefruri parece haber visto algo muy divertido, riéndose hasta rodar por el suelo."
  },
  AvgDialog_131229_Content_21 = {
    Text = "Corrompiste el destino de la señorita Salle y la condujiste a una muerte vacía. La Gran Telaraña recuerda todo lo que haces."
  },
  AvgDialog_131229_Content_22 = {
    Text = "Los destinos corrompidos deben ser reparados. Un precio te aguarda en las sombras de tu futuro."
  },
  AvgDialog_131229_Content_23 = {
    Text = "Arachne extendió la mano y tocó suavemente la parte superior de la cabeza de este cadáver. La rueca en su mano giraba suavemente, y todo a tu alrededor parecía distorsionarse y reconfigurarse en este giro..."
  },
  AvgDialog_131229_Content_24 = {
    Text = "Hilos del destino, atended la llamada de la Red. Recorred el único camino y subid al escenario una vez más..."
  },
  AvgDialog_131229_Content_25 = {
    Text = "Su cuerpo... ¿ha desaparecido?"
  },
  AvgDialog_131229_Content_26 = {
    Text = "Con el movimiento de los dedos de Arachne, el cuerpo de Liz sobre el escenario parecía estar experimentando una quema silenciosa, convirtiéndose en ceniza y desvaneciéndose en el aire."
  },
  AvgDialog_131229_Content_27 = {
    Text = "Bajo las brasas que caen, una nueva forma se revela."
  },
  AvgDialog_131229_Content_28 = {
    Text = "Eso es... ¡¿la presentadora?!"
  },
  AvgDialog_131229_Content_29 = {
    Text = "Espinas atraviesan ahora el cuerpo de la presentadora, suspendiéndola sobre el escenario en un perfecto y macabro reflejo de la pose de Liz."
  },
  AvgDialog_131229_Content_3 = {
    Text = "Gritas, pisoteando frenéticamente la cara sonriente de la presentadora contra las tablas del suelo hasta dejarla irreconocible."
  },
  AvgDialog_131229_Content_30 = {
    Text = "La horrible sonrisa de la presentadora es lo último que queda de ella antes de caer en un silencio eterno."
  },
  AvgDialog_131229_Content_31 = {
    Text = "Arachne, tú..."
  },
  AvgDialog_131229_Content_32 = {
    Text = "Perdón por llegar tarde, solo... ¡Oh!"
  },
  AvgDialog_131229_Content_33 = {
    Text = "Una figura familiar aparta la cortina. Su mirada te sobrepasa y se clava en el cadáver que cuelga en lo alto."
  },
  AvgDialog_131229_Content_34 = {
    Text = "Su postura... es hermosa..."
  },
  AvgDialog_131229_Content_35 = {
    Text = "Liz parece ignorar los cadáveres y al público restante. Camina hacia el centro del escenario, su mano trazando el aire cerca de las piernas del cuerpo colgante, como si estudiara la curva de su forma."
  },
  AvgDialog_131229_Content_36 = {
    Text = "Arachne, ¿tú... intercambiaste el destino del Anunciador y de Liz?"
  },
  AvgDialog_131229_Content_37 = {
    Text = "Pero dijiste que un precio así era insoportable..."
  },
  AvgDialog_131229_Content_38 = {
    Text = "El coste es irrelevante para la elección. En mi propio destino, este es el precio que debo pagar."
  },
  AvgDialog_131229_Content_39 = {
    Text = "Ve, %player%. No hagas esperar a la señorita Liz."
  },
  AvgDialog_131229_Content_4 = {
    Text = "Sí... así... ¡Déjalo salir! Qué expresión tan magnífica..."
  },
  AvgDialog_131229_Content_40 = {
    Text = "Ojos vacíos y aliento congelado. Su falda ondea con el viento, parpadeando con tenues llamas verdes. Cada movimiento de sus dedos parece una danza coreografiada."
  },
  AvgDialog_131229_Content_41 = {
    Text = "La figura ensangrentada que se abalanzó hacia ti hace apenas unos instantes se superpone con la mujer que tienes delante ahora. Liz está ahí, vívida y llena de vida —el intrincado retejido del destino no ha dejado marca alguna en ella."
  },
  AvgDialog_131229_Content_42 = {
    Text = "Finalmente, Liz sale de su trance y se vuelve hacia ti."
  },
  AvgDialog_131229_Content_43 = {
    Text = "Dormí hasta la tarde y me perdí el espectáculo. Eso nunca había pasado antes..."
  },
  AvgDialog_131229_Content_44 = {
    Text = "¿Supongo que me perdí algo importante?"
  },
  AvgDialog_131229_Content_45 = {
    Text = "Sus ojos recorren los cuerpos y las manchas de sangre que había ignorado previamente."
  },
  AvgDialog_131229_Content_46 = {
    Text = "No, no te has perdido nada, Liz."
  },
  AvgDialog_131229_Content_47 = {
    Text = "¿Estás... bien? ¿Te encuentras bien?"
  },
  AvgDialog_131229_Content_48 = {
    Text = "Me encuentro bien. Pero dime, {Male=sir,Female=miss}, ¿nos conocemos? Me resultas extrañamente familiar..."
  },
  AvgDialog_131229_Content_49 = {
    Text = "Quizás sea porque soy un devoto admirador tuyo. He visto muchos de tus espectáculos."
  },
  AvgDialog_131229_Content_5 = {
    Text = "El rostro destrozado sigue sonriendo. Una voz tenue escapa de su garganta hecha pedazos."
  },
  AvgDialog_131229_Content_50 = {
    Text = "Le sonríes. Este escenario tiene su propia historia, y no tienes intención de cargarla con el pasado."
  },
  AvgDialog_131229_Content_51 = {
    Text = "Estamos aquí por \"Kindness\"."
  },
  AvgDialog_131229_Content_52 = {
    Text = "Ah, así que son amigos de la Señora Sorel. Me preocupaba haber sido un poco descortés al dejar al Sr. Kindness en casa mientras venía a actuar. Por favor, síganme. Vivo cerca."
  },
  AvgDialog_131229_Content_53 = {
    Text = "Liz dirige una mirada prolongada al cadáver en la pared antes de guiarte detrás de la cortina."
  },
  AvgDialog_131229_Content_54 = {Text = "..."},
  AvgDialog_131229_Content_55 = {
    Text = "Así que... debería haber sido mi cuerpo el que colgara allí... en el escenario..."
  },
  AvgDialog_131229_Content_56 = {
    Text = "Ella parece demasiado cautivada por la belleza de la escena como para llorar a sus colegas caídos, o dedicar otra palabra de agradecimiento a su salvador."
  },
  AvgDialog_131229_Content_57 = {
    Text = "Mientras hablas, los ojos de Liz parpadean como llamas danzantes. Extiende la mano, imitando la pose del cadáver."
  },
  AvgDialog_131229_Content_58 = {
    Text = "¿Fue... hermoso?"
  },
  AvgDialog_131229_Content_59 = {
    Text = "La verdadera belleza solo se revela en el nacimiento y en la muerte. Fue una visión sin igual, Srta. Salle."
  },
  AvgDialog_131229_Content_6 = {
    Text = "Nefruri no está aquí, solo es una ilusión que dejó. No te dejes engañar por la ira, Guardián {Male=señor, Female=señorita}."
  },
  AvgDialog_131229_Content_60 = {
    Text = "Gracias, señora Arachne. Usted es la tejedora del destino, así que supongo que a menudo está rodeada de estas bellezas. Es realmente... envidiable."
  },
  AvgDialog_131229_Content_61 = {
    Text = "Demasiados tesoros pueden convertirse en una maldición."
  },
  AvgDialog_131229_Content_62 = {
    Text = "Si esa es tu maldición, ¿qué recompensa buscas?"
  },
  AvgDialog_131229_Content_63 = {
    Text = "Liz no se dio cuenta de la breve pausa de Arachne y abrió la puerta de la habitación de huéspedes en el patio."
  },
  AvgDialog_131229_Content_64 = {
    Text = "Esta es la habitación del Sr. Kindness. Señor, sus amigos están aquí."
  },
  AvgDialog_131229_Content_65 = {
    Text = "¿Señor Bondad?"
  },
  AvgDialog_131229_Content_66 = {
    Text = "La habitación es sencilla. Nada está fuera de lugar, pero no hay nadie dentro."
  },
  AvgDialog_131229_Content_67 = {
    Text = "Una nota solitaria reposa sobre la estantería de la habitación vacía."
  },
  AvgDialog_131229_Content_68 = {
    Text = "<Italic:\"Perdonen mi partida repentina. La Señora Sorel temía por su seguridad e hizo nuevos arreglos. Me dirijo a la villa donde reside 'Homenaje'.\">"
  },
  AvgDialog_131229_Content_69 = {
    Text = "<Italic:\"Estoy profundamente agradecido por sus cuidados. Encontraré la manera de saldar esta deuda.\">"
  },
  AvgDialog_131229_Content_7 = {
    Text = "<Shake:¡Uf... uf...!>"
  },
  AvgDialog_131229_Content_70 = {
    Text = "Sorel nos habría avisado si hubiera cambiado el plan..."
  },
  AvgDialog_131229_Content_71 = {
    Text = "Miras a los ojos sin emociones de Arachne. En esa sonrisa tranquila que parece no desaparecer nunca, ves una sombra que pasa fugazmente."
  },
  AvgDialog_131229_Content_72 = {
    Text = "\"Homenaje\" no tiene hogar. No tiene ninguna villa."
  },
  AvgDialog_131229_Content_73 = {
    Text = "¿¡Qué!? Entonces..."
  },
  AvgDialog_131229_Content_74 = {
    Text = "\"Recordar\" destino, probablemente ya ha sido alterado por Nefruri. Ambos, ahora, están en peligro."
  },
  AvgDialog_131229_Content_75 = {
    Text = "Lo siento. No me di cuenta..."
  },
  AvgDialog_131229_Content_76 = {
    Text = "No es culpa suya, señorita Salle."
  },
  AvgDialog_131229_Content_77 = {
    Text = "Dado que Nefruri puede alterar tu destino, no es difícil encontrar a las personas que te rodean. Estos son los problemas que necesitamos abordar."
  },
  AvgDialog_131229_Content_78 = {
    Text = "La tinta de arriba aún no se ha secado por completo, el momento en que Nefruri actúe no está lejos, tal vez aún tengamos tiempo si nos damos prisa..."
  },
  AvgDialog_131229_Content_79 = {
    Text = "Liz, hay cosas que quería decir, pero no hay tiempo..."
  },
  AvgDialog_131229_Content_8 = {
    Text = "Finalmente te detienes cuando el rostro no es más que una masa informe."
  },
  AvgDialog_131229_Content_80 = {
    Text = "Habrá otras oportunidades, {Male=Mr.,Female=Miss} Guardián. Espero que mi próximo baile te conmueva igual."
  },
  AvgDialog_131229_Content_81 = {
    Text = "Con una sencilla sonrisa de despedida, Liz regresa a su propio mundo."
  },
  AvgDialog_131229_Content_82 = {
    Text = "Alza los brazos, imitando la curva del cadáver que vio, intentando capturar la pose que ha rondado su mente."
  },
  AvgDialog_131229_Content_83 = {
    Text = "La brisa agita su falda. Parece un cisne en pleno vuelo."
  },
  AvgDialog_131229_Content_9 = {
    Text = "El cadáver manipulado de Liz ha perdido toda señal de vida. Depositas su cuerpo destrozado con cuidado en el suelo y activas el vínculo espiritual."
  },
  AvgDialog_131230_Content_1 = {
    Text = "Caída del telón"
  },
  AvgDialog_131230_Content_10 = {
    Text = "Ya que has recreado esta ciudad... pensé que traerías aquí aquellas cosas que ya han desaparecido."
  },
  AvgDialog_131230_Content_11 = {
    Text = "...los extrañas, ¿verdad?"
  },
  AvgDialog_131230_Content_12 = {
    Text = "Prefiero ver cómo se presenta el escenario por sí mismo que una taza de café."
  },
  AvgDialog_131230_Content_13 = {
    Text = "He recreado este lugar con mis recuerdos, pero aún no puedo cambiar el hecho de que es un escenario completamente nuevo."
  },
  AvgDialog_131230_Content_14 = {
    Text = "Este nuevo café aquí también tiene su sabor único, ¿no?"
  },
  AvgDialog_131230_Content_15 = {
    Text = "Arachne sonrió y tomó un sorbo de ese líquido amargo."
  },
  AvgDialog_131230_Content_16 = {
    Text = "Nefruri... ¿Qué pasó al final?"
  },
  AvgDialog_131230_Content_17 = {
    Text = "Tus hilos del destino han sido entretejidos de nuevo. ¿Eso significa... que vuelves a ser la misma persona?"
  },
  AvgDialog_131230_Content_18 = {
    Text = "Las cosas que alguna vez pertenecieron a Nefruri, sus cualidades, su naturaleza original, han regresado a mi destino. O, como usted sabe—nunca se fueron."
  },
  AvgDialog_131230_Content_19 = {
    Text = "Pero la Red del destino es única. Esa persona que usted conoce, Nefruri, esa vengadora que se hundió en el Abismo y fue abandonada por el destino, no tiene hilos que le pertenezcan en esta red."
  },
  AvgDialog_131230_Content_2 = {
    Text = [[
<Italic:Lascia ch'io pianga / Dejadme llorar
mia cruda sorte, / mi cruel destino,>]]
  },
  AvgDialog_131230_Content_20 = {
    Text = "Ella... se desvaneció, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131230_Content_21 = {
    Text = "La rueca gira suavemente, sin cesar. Arachne cierra los ojos, levanta suavemente la cabeza y huele la tenue fragancia de las flores en el viento."
  },
  AvgDialog_131230_Content_22 = {
    Text = "El destino abandonado, enfrentándose solo a la eterna prisión y la completa desaparición. Es algo realmente cruel..."
  },
  AvgDialog_131230_Content_23 = {
    Text = "En cada momento, el Destino requiere una Elección. Los caminos correctos permanecen, mientras los erróneos son descartados. Hasta que encontremos el Camino Verdadero, esto es tan inevitable como el colapso del universo mismo."
  },
  AvgDialog_131230_Content_24 = {
    Text = "Hasta que encontremos el Camino Verdadero, esto es tan inevitable como el colapso del universo mismo."
  },
  AvgDialog_131230_Content_25 = {
    Text = "Dime, {Male=Mr.,Female=Miss} Guardián, si tuvieras el poder de controlar el Destino, ¿dejarías que cayera en el caos? ¿O tomarías la decisión por los demás, aun si eso significara cargar con el nombre de asesino?"
  },
  AvgDialog_131230_Content_26 = {
    Text = "Esto... yo..."
  },
  AvgDialog_131230_Content_27 = {
    Text = "Esto es simplemente un debate para tu entretenimiento, no una pregunta que debas responder. Ya cargas con demasiado; no necesitas soportar también este peso."
  },
  AvgDialog_131230_Content_28 = {
    Text = "Arachne sonrió y sacudió la cabeza."
  },
  AvgDialog_131230_Content_29 = {
    Text = "La Elección es una forma de poder, y sin embargo muchos eligen renunciar a ella incluso cuando está a su alcance."
  },
  AvgDialog_131230_Content_3 = {
    Text = "<Italic:E che sospiri la libertà! / ¡y suspirar por mi libertad!>"
  },
  AvgDialog_131230_Content_30 = {
    Text = "Elegir es cargar con las consecuencias, y eso no es tarea fácil, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131230_Content_31 = {
    Text = "Soy el controlador del destino, todas las consecuencias del destino las asumiré yo."
  },
  AvgDialog_131230_Content_32 = {
    Text = "Estas son las palabras que Él me otorgó la primera vez que toqué la puerta de Chokmah-Da'at. Las acepto con gusto."
  },
  AvgDialog_131230_Content_33 = {
    Text = "Así que tú... aunque no puedes ver tu destino, todo esto que está sucediendo ahora... en realidad lo sabes."
  },
  AvgDialog_131230_Content_34 = {
    Text = "El cálido sol brilla sobre esta calle, pero al mirar la tranquila cara de Arachne, imaginando lo que esta persona enfrenta día tras día, incluso tú no puedes evitar un escalofrío."
  },
  AvgDialog_131230_Content_35 = {
    Text = "El romanticismo trae torpeza, la bondad trae fragilidad, los recuerdos traen dolor..."
  },
  AvgDialog_131230_Content_36 = {
    Text = "Aunque te preparaste para esto hace mucho, nunca los dejaste ir realmente. ¿Por qué?"
  },
  AvgDialog_131230_Content_37 = {
    Text = "Para ti, liberarlos debería hacerte la vida un poco más fácil."
  },
  AvgDialog_131230_Content_38 = {
    Text = "¿Has estado en prisión? Los prisioneros que han estado encerrados durante años siempre llevan consigo algunas cosas que valoran."
  },
  AvgDialog_131230_Content_39 = {
    Text = "Una medalla ganada en combate, un reloj heredado, una foto familiar..."
  },
  AvgDialog_131230_Content_4 = {
    Text = "Las melodías suaves resuenan en la calle, ondeando con el cálido viento. Los transeúntes en el camino se detienen o caminan al compás de esta canción, disfrutando de su tranquila vida en esta luz primaveral."
  },
  AvgDialog_131230_Content_40 = {
    Text = "Para los prisioneros, estos deseos que les causan dolor son la motivación que les permite seguir vivos."
  },
  AvgDialog_131230_Content_41 = {
    Text = "Con cuidado retienen esos objetos más preciados hasta el momento cercano a la muerte, entregando uno a uno esas cosas sin valor."
  },
  AvgDialog_131230_Content_42 = {
    Text = "...En la jaula del Destino, no tenemos nada más, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131230_Content_43 = {
    Text = [[
<Italic:Il duolo infranga / Que el dolor quiebre
queste ritorte / estas cadenas>]]
  },
  AvgDialog_131230_Content_44 = {
    Text = "<Italic:de miei martiri / de mis tormentos\nsol per pietà. / solo por piedad>"
  },
  AvgDialog_131230_Content_45 = {
    Text = "El operista al borde del camino canta al río del destino que fluye por esta ciudad. Arachne sorbe su café, escuchando atentamente. Desde el principio hasta el final, el ángulo de su sonrisa nunca ha cambiado."
  },
  AvgDialog_131230_Content_46 = {
    Text = "Sabes, {Male=Mr.,Female=Miss} Guardián, a menudo sueño con la misma escena una y otra vez."
  },
  AvgDialog_131230_Content_47 = {
    Text = "Era un hermoso teatro, solo yo y Nefruri. Fue en esta hermosa canción donde me despedí de ella."
  },
  AvgDialog_131230_Content_48 = {
    Text = "Ves, aunque no podamos ver nuestro destino, su juicio está en todas partes."
  },
  AvgDialog_131230_Content_49 = {
    Text = "<Italic:E che sospiri la libertà! / ¡Y suspirar por mi libertad!\nE che sospiri la libertà! / ¡Y suspirar por mi libertad!>"
  },
  AvgDialog_131230_Content_5 = {
    Text = "Levantas el café y das un gran sorbo."
  },
  AvgDialog_131230_Content_50 = {
    Text = "La voz del operista nunca cesa, el hilo de la rueca gira eternamente. Arachne deja caer la copa que tiene en la mano y, junto a los espectadores que se detienen, aplaude sinceramente en silencio."
  },
  AvgDialog_131230_Content_51 = {
    Text = "De todos modos, una actuación ha terminado, y este escenario tendrá su breve descanso. Nosotros, los actores, también nos dirigiremos al siguiente escenario."
  },
  AvgDialog_131230_Content_52 = {
    Text = "¿La influencia de Nefruri ya ha desaparecido, ahora debería poder reabrirse el pasaje para conectar con Kadas?"
  },
  AvgDialog_131230_Content_53 = {
    Text = "El pasaje que conecta con Kadas está en el destino de este mundo. Ya has intentado cruzar dimensiones."
  },
  AvgDialog_131230_Content_54 = {
    Text = "El peligro que hay, ya lo conoces."
  },
  AvgDialog_131230_Content_55 = {
    Text = "De hecho... no quiero enfrentarme de nuevo a esas miradas de Toguwaibo..."
  },
  AvgDialog_131230_Content_56 = {
    Text = "Arachne, puedes controlar el destino de este mundo, ¿quizás tienes una manera de ayudarme?"
  },
  AvgDialog_131230_Content_57 = {
    Text = "Estoy encantado de servir, pero en este mundo, solo esta ciudad es mi escenario. El maestro del destino de este mundo no soy yo."
  },
  AvgDialog_131230_Content_58 = {
    Text = "¡Increíble!..."
  },
  AvgDialog_131230_Content_59 = {
    Text = "El Amo de este mundo posee habilidades que escapan incluso a mi alcance. Este mundo existe únicamente porque Él así lo quiso."
  },
  AvgDialog_131230_Content_6 = {
    Text = "Ni de lejos se parece al café bosnio."
  },
  AvgDialog_131230_Content_60 = {
    Text = "A menos que el pasaje sea abierto deliberadamente, este lugar permanece oculto incluso de la mirada del Primordial... Por eso precisamente elegí habitar aquí."
  },
  AvgDialog_131230_Content_61 = {
    Text = "¿Acaso... abriré el pasaje y eso causará peligro aquí?"
  },
  AvgDialog_131230_Content_62 = {
    Text = "Como dije, el destino tiene su propia trayectoria. Estar aquí solo significa esperar lentamente la muerte. Ayudarte a regresar a Kadas es también el deseo de este mundo."
  },
  AvgDialog_131230_Content_63 = {
    Text = "Por la luz que nos aguarda al final del camino del destino, este es un peligro que estamos más que dispuestos a asumir."
  },
  AvgDialog_131230_Content_64 = {
    Text = "Entendido... está bien."
  },
  AvgDialog_131230_Content_65 = {
    Text = "¿Dónde puedo encontrarlo?"
  },
  AvgDialog_131230_Content_66 = {
    Text = "Las hebras del destino de Él son vastas como el mar de estrellas y sutiles como el polvo. Solo confiando en la captura del destino, no puedo señalar directamente su ubicación para ti."
  },
  AvgDialog_131230_Content_67 = {
    Text = "Pero quizás, esto pueda ayudarte."
  },
  AvgDialog_131230_Content_68 = {
    Text = "Arachne te entrega una página de un folleto. Frunciendo el ceño, miras esas hermosas letras ornamentadas llenas de un sentido religioso."
  },
  AvgDialog_131230_Content_69 = {
    Text = "Anuncio de contratación:"
  },
  AvgDialog_131230_Content_7 = {
    Text = "La última vez que fui a ese escenario a degustar, también pensé que el sabor era bastante bueno. Lamentablemente, en este escenario, la familia que inventó ese café ya había desaparecido hace mucho tiempo."
  },
  AvgDialog_131230_Content_70 = {
    Text = "El gran maestro, El Elegido de la deidad, el Executor del dios supremo, el heredero legítimo de la gran secta, el redentor de los sufrientes, el amigo cercano del Rey divino ha llegado al continente del Norte, la secta está en rápido desarrollo, los creyentes pueden apresurarse a venir aquí para rendir homenaje."
  },
  AvgDialog_131230_Content_71 = {
    Text = "Los primeros doce fieles en llegar serán consagrados como santos, siguiendo eternamente a la hada y bajo la protección eterna de los dioses..."
  },
  AvgDialog_131230_Content_72 = {
    Text = "¿Qué es esto...?"
  },
  AvgDialog_131230_Content_73 = {
    Text = "Como puede ver, es un folleto creado con esmero."
  },
  AvgDialog_131230_Content_74 = {
    Text = "¿Por qué es tan extraño lo que hay arriba...? Arachne, ¿puedes ver el rumbo del destino? ¿Estás segura de que no es una trampa?"
  },
  AvgDialog_131230_Content_75 = {
    Text = "En su hilo, vi tu figura. Estoy seguro de que es el destino que vas a enfrentar."
  },
  AvgDialog_131230_Content_76 = {
    Text = "No sé si es ayuda o peligro. Pero sé que entre tú y el dueño de ese mundo, esta es la única conexión."
  },
  AvgDialog_131230_Content_77 = {
    Text = "La mano de Arachne se extendió sobre ese absurdo folleto, tomando un objeto que no puedes ver y colocándolo en la palma de tu mano."
  },
  AvgDialog_131230_Content_78 = {
    Text = "¿Y esto es...?"
  },
  AvgDialog_131230_Content_79 = {
    Text = "Pronto, un tenue hilo resplandece con un brillo sutil en tu mano."
  },
  AvgDialog_131230_Content_8 = {
    Text = "Miras a tu alrededor en esta ciudad. Cruce Brick, la librería de libros viejos con pliegues en el tiempo, la tienda de comestibles del mercado fragante..."
  },
  AvgDialog_131230_Content_80 = {
    Text = "Este es el catalizador que te vincula a ese destino. Te guiará hasta donde debes estar."
  },
  AvgDialog_131230_Content_81 = {
    Text = "Entiendo. Una vez que William, el compañero mayor, se recupere, nosotros..."
  },
  AvgDialog_131230_Content_82 = {
    Text = "En mi breve vistazo a tus hilos, vi una historia interesante."
  },
  AvgDialog_131230_Content_83 = {
    Text = "No pude ver tu final, y me alegro por ello. Significa que aún tengo el honor de ser espectadora de tu destino."
  },
  AvgDialog_131230_Content_84 = {
    Text = "Creo que ninguna historia merece quedar sin ser escuchada... Así que, por favor, no hay necesidad de apresurarse. Escuchemos esta ópera hasta su final, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131230_Content_85 = {
    Text = "La voz del operista volvió a recorrer las calles. Arachne cerró los ojos, y la luz del sol caía sobre su rostro sereno, cálida como aquellas primaveras que ya había perdido."
  },
  AvgDialog_131230_Content_86 = {
    Text = "El huso gira. La canción nunca se detiene. La gente pasa, e incontables hilos que no puedes ver se reúnen y se tejen a su alrededor."
  },
  AvgDialog_131230_Content_87 = {
    Text = "Miras la cara sonriente de Arachne. Ves que a su alrededor no hay nada."
  },
  AvgDialog_131230_Content_9 = {
    Text = "Todo parece no haber cambiado, incluso las manchas de óxido en el letrero de la tienda son idénticas a como las recordabas."
  },
  AvgDialog_131231_Content_1 = {
    Text = "Uf... llegué justo a tiempo."
  },
  AvgDialog_131231_Content_10 = {
    Text = "Sorel entrecerró los ojos mientras observaba a Arachne. Se dio cuenta de que su orgullosa habilidad para leer a las personas había fallado por completo. No podía discernir el pasado de la persona frente a ella, ni adivinar sus deseos."
  },
  AvgDialog_131231_Content_11 = {
    Text = "Cada detalle que Sorel intenta grabar en su memoria se desvanece en un abrir y cerrar de ojos. Sus labios se curvan en una sonrisa intrigada."
  },
  AvgDialog_131231_Content_12 = {
    Text = "Dos invitadas cautivadoras. Este salón será sin duda inolvidable. Por favor, tomen asiento."
  },
  AvgDialog_131231_Content_13 = {
    Text = "Sorel se sienta en el sofá y te hace un gesto para que te unas a ella."
  },
  AvgDialog_131231_Content_14 = {
    Text = "Me he cruzado con \"Amabilidad\" algunas veces. Vino a mí buscando asilo."
  },
  AvgDialog_131231_Content_15 = {
    Text = "Me salvaron. No puedo ver sus verdaderas identidades, pero puedo notar que no tienen malas intenciones."
  },
  AvgDialog_131231_Content_16 = {
    Text = "Así es, Señora Sorel. Estamos aquí para salvarlo."
  },
  AvgDialog_131231_Content_17 = {
    Text = "No está en la mansión."
  },
  AvgDialog_131231_Content_18 = {
    Text = "Pero usted acaba de decir..."
  },
  AvgDialog_131231_Content_19 = {
    Text = "Como pueden ver, mi propiedad difícilmente es un santuario."
  },
  AvgDialog_131231_Content_2 = {
    Text = "Tras comprobar el estado de Karen, te levantas y te limpias el sudor frío de la frente."
  },
  AvgDialog_131231_Content_20 = {
    Text = "Sorel alza el brazo, señalando los cadáveres destrozados esparcidos por su inmaculada sala como si exhibiera una colección preciada."
  },
  AvgDialog_131231_Content_21 = {
    Text = "Es un hombre amable, pero de ningún modo un tonto. Pude notar que su situación era desesperada."
  },
  AvgDialog_131231_Content_22 = {
    Text = "Mucha gente conoce mi relación con él. Esconderlo aquí habría sido imprudente."
  },
  AvgDialog_131231_Content_23 = {
    Text = "¿Dónde está ahora?"
  },
  AvgDialog_131231_Content_24 = {
    Text = "Sorel se levanta y camina hacia una pintura al óleo. La sigues, contemplando la imagen."
  },
  AvgDialog_131231_Content_25 = {
    Text = "¡Eso es...!"
  },
  AvgDialog_131231_Content_26 = {
    Text = "Hace años, asistí a una actuación de la Compañía de danza del cisne en el Teatro de Londinium. Era una mera obligación social, pero su danza me conmovió profundamente."
  },
  AvgDialog_131231_Content_27 = {
    Text = "A lo largo de los años, he visitado ocasionalmente los camerinos. No tenemos ninguna conexión pública real, lo que hace de su compañía el lugar perfecto para esconder a \"Amabilidad\"."
  },
  AvgDialog_131231_Content_28 = {
    Text = "En la pintura, Liz viste un etéreo atuendo de danza, saltando alto en el aire como un cisne en pleno vuelo."
  },
  AvgDialog_131231_Content_29 = {
    Text = "Liz... ¿dónde está su compañía ahora?"
  },
  AvgDialog_131231_Content_3 = {
    Text = "Karen debería estar bien. Ha sido afectada por la posesión, pero se recuperará con algo de descanso."
  },
  AvgDialog_131231_Content_30 = {
    Text = "Siguiendo los hilos del destino que se volvían cada vez más claros, Arachne miró por la ventana, hacia aquel lugar conectado con los hilos, oculto entre la densa selva."
  },
  AvgDialog_131231_Content_31 = {
    Text = "En un lugar que conoces demasiado bien."
  },
  AvgDialog_131231_Content_4 = {
    Text = "Puedo recordar cada rostro que he visto, pero tú me resultas... extraño. No puedo estar segura de si nos hemos conocido. Eso nunca me había pasado antes."
  },
  AvgDialog_131231_Content_5 = {
    Text = "Sorel recoge una botella erguida de la mesa y sirve una copa. Pasando por encima de los cadáveres que se disuelven, te ofrece la copa."
  },
  AvgDialog_131231_Content_6 = {
    Text = "Un Oporto de cuarenta años de mi colección privada. Las hienas de abajo no merecen ni una sola gota. Seas quien seas, creo que esta copa te pertenece."
  },
  AvgDialog_131231_Content_7 = {
    Text = "Estamos aquí por \"Bondad\", Señora Sorel."
  },
  AvgDialog_131231_Content_8 = {
    Text = "Arachne tomó la copa y sonrió asintiendo hacia Sorel."
  },
  AvgDialog_131231_Content_9 = {
    Text = "En silencio, es tan discreta como una telaraña bajo la luz de la mañana. Sin embargo, en el momento en que habla, parece atraer hacia sí cada ápice de resplandor de la sala."
  },
  AvgDialog_131232_Content_1 = {
    Text = "Qué actuación tan espectacular, hermana."
  },
  AvgDialog_131232_Content_10 = {
    Text = "Tú y tus escuderos sois aquellos sin destino; no puedo asir vuestros hilos. Pero dado que tu poder se origina del mío, eres tan ciega a tu propio destino como yo lo soy al mío."
  },
  AvgDialog_131232_Content_11 = {
    Text = "Tú y yo... esto es un punto muerto. Una guerra sin sentido que nunca debería haber comenzado."
  },
  AvgDialog_131232_Content_12 = {
    Text = "Por supuesto, por supuesto. Para ti, nosotras, las \"cosas descartadas\", pertenecemos al cementerio del Destino—para ser desmanteladas, olvidadas y disueltas por toda la eternidad."
  },
  AvgDialog_131232_Content_13 = {
    Text = "Qué lástima que no puedas ver a 'Él'... Por más grande que sea tu poder, ¿cómo podrías siquiera compararte con la Deidad Suprema?"
  },
  AvgDialog_131232_Content_14 = {
    Text = "Lo sabes. En el fondo sabes que todo esto es inútil. Y aun así, no puedes dejar de tejer tu tela..."
  },
  AvgDialog_131232_Content_15 = {
    Text = "Porque has visto los hilos, no soportas verlos enredados. Porque tienes el poder, no puedes quedarte de brazos cruzados mientras los mundos caen en un caos interminable."
  },
  AvgDialog_131232_Content_16 = {
    Text = "Les ofreces una paz falsa mientras los conduces por un camino que solo termina en ruina."
  },
  AvgDialog_131232_Content_17 = {
    Text = "Qué persona tan triste, Arachne."
  },
  AvgDialog_131232_Content_18 = {
    Text = "Este es nuestro destino, Nefruri."
  },
  AvgDialog_131232_Content_19 = {
    Text = "Ah... Me está entrando sueño. Discutir con una necia es lo más tedioso del mundo."
  },
  AvgDialog_131232_Content_2 = {
    Text = "El animado bar queda en silencio. Los cadáveres esparcidos por el suelo se disuelven en lodo negro y polvo, desvaneciéndose bajo las cálidas luces."
  },
  AvgDialog_131232_Content_20 = {
    Text = "Bienvenida al Segundo acto. Este es tu escenario, pero de ahora en adelante, seré yo quien escriba el guion."
  },
  AvgDialog_131232_Content_21 = {
    Text = "Las notas iniciales son las más importantes, ¿verdad? ¿Cómo deberíamos llamarlo... qué tal \"Reencuentro\"?"
  },
  AvgDialog_131232_Content_22 = {
    Text = "Nefruri estaba bastante satisfecha con su nombre, mojó sus extremidades en el vino añejo de la copa y lo puso en su boca, soltando un suspiro de éxtasis."
  },
  AvgDialog_131232_Content_23 = {
    Text = "Hay tanto tiempo que llevo preparándome para este día. Voy a saborear cada momento de nuestra historia juntas, querida hermana."
  },
  AvgDialog_131232_Content_24 = {
    Text = "No habrá más oportunidades para que ustedes hagan preguntas. Las garras afiladas de Nefruri rozaron suavemente el borde de la mejilla de Arachne, y luego cayó al suelo junto con su cuerpo."
  },
  AvgDialog_131232_Content_25 = {
    Text = "¡Espera...!"
  },
  AvgDialog_131232_Content_26 = {
    Text = "Ella no está aquí, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131232_Content_27 = {
    Text = "Con un sonido burbujeante, el lodo negro se desprende una vez más del rostro del cadáver."
  },
  AvgDialog_131232_Content_28 = {
    Text = "Los ojos de \"romántico\" permanecen fijos en una sonrisa, incluso mientras arañas negras se arrastran por su cuerpo hueco, visibles tras su mirada nublada. Sus elegantes labios nunca volverán a hablar."
  },
  AvgDialog_131232_Content_29 = {Text = "Eso es..."},
  AvgDialog_131232_Content_3 = {
    Text = "Nefruri y Arachne aún estaban sentadas una frente a la otra; ella derramó una copa de vino y se la empujó a Arachne."
  },
  AvgDialog_131232_Content_30 = {
    Text = "Ella asesinó a este objeto secreto. Dejó su marca, contaminó su destino y la usó como un recipiente temporal."
  },
  AvgDialog_131232_Content_31 = {
    Text = "Arachne se acercó al objeto secreto y extendió la mano hacia la cabeza del \"romántico\", mirando la hebra que casi había desaparecido."
  },
  AvgDialog_131232_Content_32 = {
    Text = "...¿Puedes ver algo?"
  },
  AvgDialog_131232_Content_33 = {
    Text = "Los demás objetos secretos también han sido contaminados; ya no puedo percibirlos a través de la Gran Telaraña. Pero el destino de \"romántico\" estaba conectado al de ellos."
  },
  AvgDialog_131232_Content_34 = {
    Text = "Ella me mostró dónde encontrar a \"Amabilidad\"."
  },
  AvgDialog_131232_Content_35 = {
    Text = "Arachne libera el hilo del destino, mientras organiza ese hermoso flequillo para \"romántico\"."
  },
  AvgDialog_131232_Content_36 = {
    Text = "Las habilidades de Nefruri provienen de mí, el destino contaminado por ella, no puedo verlo, muchas habilidades también están limitadas por esto."
  },
  AvgDialog_131232_Content_37 = {
    Text = "Eres un fragmento de lo Divino, alguien cuyo destino es invisible para nosotros. Por eso necesito tu ayuda, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_131232_Content_38 = {
    Text = "No te preocupes. Aunque solo sea para regresar a Kadas, debo ocuparme de ella."
  },
  AvgDialog_131232_Content_39 = {
    Text = "¿Por qué está cazando estos objetos secretos?"
  },
  AvgDialog_131232_Content_4 = {
    Text = "Aunque la Srta. \"romántico\" se haya ido, no deberíamos desperdiciar una buena bebida."
  },
  AvgDialog_131232_Content_40 = {
    Text = "Estos objetos secretos se convertirán en la fuente de su poder."
  },
  AvgDialog_131232_Content_41 = {
    Text = "Entonces debemos apresurarnos a partir... encontrar esos objetos secretos, así como esas cenizas de dimensión que pueden ayudarte a tejer el destino..."
  },
  AvgDialog_131232_Content_42 = {
    Text = "Este objeto secreto llamado \"Amabilidad\"... ¿dónde está?"
  },
  AvgDialog_131232_Content_43 = {
    Text = "\"romántico\" logró advertirle del peligro antes de caer. Ahora está escondido, protegido por un viejo amigo tuyo."
  },
  AvgDialog_131232_Content_44 = {
    Text = "¿Un viejo amigo...?"
  },
  AvgDialog_131232_Content_45 = {
    Text = "Sígueme, {Male=Mr.,Female=Miss} Guardián. El gran salón de la Señora Sorel está a punto de comenzar."
  },
  AvgDialog_131232_Content_5 = {
    Text = "¿Quieres un sorbo? Te entiendo mucho mejor de lo que ese objeto secreto jamás podría."
  },
  AvgDialog_131232_Content_6 = {
    Text = "Arachne no dudó, sonriendo levantó la copa y dio un suave sorbo."
  },
  AvgDialog_131232_Content_7 = {
    Text = "No eres adecuada para esta profesión, Nefruri. Además de amargo y agridulce, no tiene otro sabor."
  },
  AvgDialog_131232_Content_8 = {
    Text = "La llamo \"Destino\". ¿Te gusta el sabor?"
  },
  AvgDialog_131232_Content_9 = {
    Text = "Arachne no prestó atención a la mirada expectante de Nefruri. Ella bebió lentamente de la copa y la dejó suavemente sobre la mesa."
  },
  AvgDialog_132684_Content_1 = {
    Text = "<Small:<LightGray:¿Chirp...? (¿Hmm...?)>>"
  },
  AvgDialog_132684_Content_10 = {
    Text = "Exacto, y considerando que Misaq tiene la tradición de burlarse de las personas para comunicar emociones, la institución no penalizará esta \"bromita\" que no es excesiva."
  },
  AvgDialog_132684_Content_11 = {
    Text = "¡Pío! ¡Pío, Pío—!<Small:<LightGray:(¡Maestro Doll, estás apretando mi mano y mi cara, verdad? ¡Estás frotando mi cara, no es cierto!)>>"
  },
  AvgDialog_132684_Content_12 = {
    Text = "Aunque el tono es tan frío como siempre, e incluso algo mordaz, estás muy seguro de que las comisuras de los labios de Doll se elevaron al menos 2 milímetros."
  },
  AvgDialog_132684_Content_13 = {
    Text = "Lo siento, Guardián. Parece que el traductor de Núcleo de plata tiene un problema, pero no te preocupes, el reactivo inverso se podrá sintetizar mañana por la mañana."
  },
  AvgDialog_132684_Content_14 = {
    Text = "Miras a Doll con una expresión de asombro; incluso si ahora solo tuvieras la mente de una nutria, podrías darte cuenta de que los reactivos detrás de ella están claramente en estado completado."
  },
  AvgDialog_132684_Content_15 = {
    Text = "¿Maestro, buscar a Mosk?"
  },
  AvgDialog_132684_Content_16 = {
    Text = "!!!Bola de carbón—"
  },
  AvgDialog_132684_Content_17 = {
    Text = "Pío—<Small:<LightGray:(jefe——)>>"
  },
  AvgDialog_132684_Content_18 = {
    Text = "Dado que tenemos personal con amplia experiencia en esta comunidad, creo que pasar un día con ellas debería ayudar a nuestros Guardianes del secreto a recordar un poco más."
  },
  AvgDialog_132684_Content_19 = {
    Text = "Mosk, encárgate de la tarea de %player%."
  },
  AvgDialog_132684_Content_2 = {Text = "*rebote"},
  AvgDialog_132684_Content_20 = {
    Text = "*¡Hurra! ¡Bola de carbón, juguemos juntos"
  },
  AvgDialog_132684_Content_21 = {
    Text = "¡Pío!<Small:<LightGray:(¡Juguemos juntos!)>>"
  },
  AvgDialog_132684_Content_22 = {
    Text = "¡Chirp!——<Small:<LightGray:(¡No, Ramona, sálvame——)>>"
  },
  AvgDialog_132684_Content_23 = {Text = "Tos."},
  AvgDialog_132684_Content_24 = {
    Text = "Compañero, hoy no hay asuntos importantes, no te preocupes."
  },
  AvgDialog_132684_Content_25 = {
    Text = "También dedicaré tiempo hoy para garantizar tu seguridad."
  },
  AvgDialog_132684_Content_26 = {
    Text = "Aunque se diga así, es evidente que ella también ha sido completamente controlada por ese pelaje increíblemente suave que tienes, al igual que Mosk."
  },
  AvgDialog_132684_Content_27 = {
    Text = "¡Pío, pío pío pío...<Small:<LightGray:(¿Hay alguien que pueda ayudar, William, el compañero mayor...)>>"
  },
  AvgDialog_132684_Content_28 = {
    Text = "Por cierto, William salió a trabajar hoy, volverá muy tarde."
  },
  AvgDialog_132684_Content_29 = {
    Text = "*Tomar té <Small:<LightGray:(Huh, una rara oportunidad, mi estudiante más problemático y más importante, dejemos todo de lado y relajémonos un día.)>>"
  },
  AvgDialog_132684_Content_3 = {
    Text = "*frotar la cara"
  },
  AvgDialog_132684_Content_30 = {
    Text = "En ese momento, un compañero mayor a lo lejos."
  },
  AvgDialog_132684_Content_31 = {Text = "¡Achís"},
  AvgDialog_132684_Content_32 = {
    Text = "Es extraño, tengo un mal presentimiento inexplicable."
  },
  AvgDialog_132684_Content_33 = {
    Text = "Hoy es mejor volver a la escuela temprano."
  },
  AvgDialog_132684_Content_34 = {
    Text = "Misaq del Día de los Inocentes, también es muy pacífico."
  },
  AvgDialog_132684_Content_35 = {
    Text = "¡Es motivo de celebración, es motivo de celebración."
  },
  AvgDialog_132684_Content_4 = {Text = "¿¿¿!!!"},
  AvgDialog_132684_Content_5 = {
    Text = "¡Pío pío pío pío pío! ¡Ying ying ying ying ying!!!<Small:<LightGray:(¡Me he convertido en una nutria! ¡Ramona, ayúdame!)>>"
  },
  AvgDialog_132684_Content_6 = {Text = "..."},
  AvgDialog_132684_Content_7 = {
    Text = "Buenas noticias, el efecto de este aerosol no es irreversible, y la preparación del reactivo inverso es muy sencilla, claramente la otra parte no tiene malas intenciones."
  },
  AvgDialog_132684_Content_8 = {
    Text = "Mejor noticia, atreverte a usar el regalo de ese pequeño mentiroso sin pensar realmente puede ayudarte a despejarte temporalmente cambiando tu cerebro por el de una nutria."
  },
  AvgDialog_132684_Content_9 = {
    Text = "¿Entonces, esta transformación temporal no causará ningún daño al Guardián?"
  },
  AvgDialog_13733_Content_1 = {
    Text = "Rito Bermellón"
  },
  AvgDialog_13733_Content_10 = {
    Text = "Heh, nunca puedes confiar en la perspicacia de los Lemwahsianos. Mantén los ojos bien abiertos y observa..."
  },
  AvgDialog_13733_Content_11 = {
    Text = "Prin sacó un cuchillo ritual de su manga y, sin dudarlo, se abrió la muñeca."
  },
  AvgDialog_13733_Content_12 = {
    Text = "La Sangre Carmesí goteaba, gota a gota, sobre el círculo ritual trazado con azufre, y así, sin más, un Milagro ocurrió—"
  },
  AvgDialog_13733_Content_13 = {
    Text = "Como si una gota de agua cayera en un desierto reseco, el círculo ritual, habiendo Absorbido la Sangre fresca, emitió rápidamente anillo tras anillo de luz carmesí oscura."
  },
  AvgDialog_13733_Content_14 = {
    Text = "Eran como llamas bajo un cielo ennegrecido, lamiendo con avidez la arena amarilla azotada por el Viento, Como si intentaran devorar la Tierra entera en sus fauces."
  },
  AvgDialog_13733_Content_15 = {
    Text = "¿Lo veis? ¡Este es el verdadero momento de la magia! ¡Jajajaja!"
  },
  AvgDialog_13733_Content_16 = {
    Text = "Jajaja... <Big:¡¡¡GAAAH!!!>"
  },
  AvgDialog_13733_Content_17 = {
    Text = "Prin se desplomó de rodillas con un golpe seco, sus manos aferrándose involuntariamente a su propia garganta."
  },
  AvgDialog_13733_Content_18 = {
    Text = "Las cadenas que lo conectan a Uvhash se tensan rápidamente, uniendo su carne y sus almas con fuerza."
  },
  AvgDialog_13733_Content_19 = {
    Text = "Ngh... ¿Qué...?"
  },
  AvgDialog_13733_Content_2 = {
    Text = "Límite del Desierto Kuxi\nSitio Ritual"
  },
  AvgDialog_13733_Content_20 = {
    Text = "Uvhash ya no podía mantener su postura despreocupada."
  },
  AvgDialog_13733_Content_21 = {
    Text = "Fue lanzado por una Fortaleza invisible, mirando algo aturdido el círculo ritual frente a él que estaba a punto de descontrolarse."
  },
  AvgDialog_13733_Content_22 = {Text = "Ugh..."},
  AvgDialog_13733_Content_23 = {
    Text = "<Big:¡¡¡AAAAAGH!!!>"
  },
  AvgDialog_13733_Content_24 = {
    Text = "Prin yacía despatarrado en el suelo, mirando con ferocidad la figura de Uvhash que se retorcía, y soltó una risa siniestra."
  },
  AvgDialog_13733_Content_25 = {
    Text = "Duele... Bien, debería doler..."
  },
  AvgDialog_13733_Content_26 = {
    Text = "Ahora mismo, nuestras consciencias están atadas estrechamente..."
  },
  AvgDialog_13733_Content_27 = {
    Text = "¿Viste cómo los perros Lemwash masacraron a mi gente y profanaron a mi esposa... sentiste eso..."
  },
  AvgDialog_13733_Content_28 = {
    Text = "<Big:¡Respóndeme, criatura estúpida que no es mejor que @1!>"
  },
  AvgDialog_13733_Content_29 = {Text = "Je, je..."},
  AvgDialog_13733_Content_3 = {
    Text = "Bien, primero esparcir una capa de azufre, luego el polvo de carbón..."
  },
  AvgDialog_13733_Content_30 = {
    Text = "No cantes victoria tan pronto... viejo necio."
  },
  AvgDialog_13733_Content_31 = {
    Text = "Cuando me libere de esta Esclavitud, serás el primero al que despedace— ¡¡Mmph!!"
  },
  AvgDialog_13733_Content_32 = {
    Text = "Qué desafortunado. Me temo que esta vez no conseguirás lo que deseas..."
  },
  AvgDialog_13733_Content_33 = {
    Text = "Prin jadeaba en busca de aire, sus manos temblorosas aferrando la cadena invisible, y entonces le dio un violento tirón—"
  },
  AvgDialog_13733_Content_34 = {
    Text = "La cadena que antes era irrompible se hizo añicos así, sin más."
  },
  AvgDialog_13733_Content_35 = {
    Text = "Je je@3AHHH@1AHHH!!"
  },
  AvgDialog_13733_Content_36 = {
    Text = "Prin lanza un aullido de agonía mientras la carne de su rostro se pudre y se desprende como la corteza de un árbol, dejando al descubierto la carne viva que hay debajo."
  },
  AvgDialog_13733_Content_37 = {
    Text = "El círculo mágico abre sus fauces oscuras y cavernosas, devorando su carne poco a poco hasta que el hechicero queda reducido a un esqueleto hueco."
  },
  AvgDialog_13733_Content_38 = {
    Text = "He sacrificado mi carne, mi alma y todo lo demás... ¿y tú?"
  },
  AvgDialog_13733_Content_39 = {
    Text = "Nunca lograrás la verdadera libertad hasta que hayas matado 10,000 perros Lermvahi"
  },
  AvgDialog_13733_Content_4 = {
    Text = "No, eso no está bien. Déjame revisar qué dice el libro..."
  },
  AvgDialog_13733_Content_40 = {
    Text = "Uvhash se puso lentamente en pie."
  },
  AvgDialog_13733_Content_41 = {
    Text = "Su rostro había sido calcinado hasta convertirse en Cenizas ennegrecidas por llamas invisibles, desmoronándose con cada ráfaga de Viento."
  },
  AvgDialog_13733_Content_42 = {Text = "Heh..."},
  AvgDialog_13733_Content_43 = {
    Text = "\"¿Verdadera libertad\"...? ¿Qué demonios es eso?"
  },
  AvgDialog_13733_Content_44 = {
    Text = "El guerrero calcinado se mantuvo erguido entre el resplandor de las llamas. Sus ojos eran de un rojo carmesí, Solo un dudar ronco escapaba de su garganta."
  },
  AvgDialog_13733_Content_45 = {
    Text = "Solo ha habido una cosa que a mí, Uvhash, verdaderamente me importa—"
  },
  AvgDialog_13733_Content_46 = {
    Text = "Se lanzó hacia adelante a una velocidad cegadora, derribando al mago contra el suelo."
  },
  AvgDialog_13733_Content_47 = {
    Text = "Entonces mostró sus afilados colmillos y mordió salvajemente el cuello del mago."
  },
  AvgDialog_13733_Content_48 = {
    Text = "<Red:¡¡Y eso es Sangre!!>"
  },
  AvgDialog_13733_Content_49 = {
    Text = "¡Sr. Prin!"
  },
  AvgDialog_13733_Content_5 = {
    Text = "A menos de cincuenta yardas del campo de batalla, Prin trabajaba afanosamente."
  },
  AvgDialog_13733_Content_50 = {
    Text = "<Shake:Esta vida... es tuya... Venga@2Ayúdame...>"
  },
  AvgDialog_13733_Content_51 = {
    Text = "¿Ayudarte? Viejo, debes estar confundido..."
  },
  AvgDialog_13733_Content_52 = {
    Text = "Las presas no tienen derecho a exigirme nada a mí, Uvhash."
  },
  AvgDialog_13733_Content_53 = {
    Text = "La razón por la que te he estado obedeciendo es porque puedo destrozar tu cadenita de juguete cuando me dé la gana, no por ese maldito contrato que firmamos."
  },
  AvgDialog_13733_Content_54 = {
    Text = "El Tiempo de juego se acabó. Ahora, quiero que abras bien los ojos y observes con atención—"
  },
  AvgDialog_13733_Content_55 = {
    Text = "Mientras masacro a tus enemigos, a tus compatriotas y a todo ser viviente a la vista..."
  },
  AvgDialog_13733_Content_56 = {
    Text = "<Change>Demonio... eres un demonio..."
  },
  AvgDialog_13733_Content_57 = {
    Text = "La Sangre de Prin fluyó libremente por el círculo ritual, haciendo que incluso aquellas luces carmesíes parecieran incomparablemente tenues."
  },
  AvgDialog_13733_Content_58 = {
    Text = "Sacrificó su propia vida a cambio de la libertad de Uvhash."
  },
  AvgDialog_13733_Content_59 = {
    Text = "Jeje... Ahhh@4..."
  },
  AvgDialog_13733_Content_6 = {
    Text = "Uvhash, a petición de Prin, se sentó erguido en el centro de un círculo de Ritual dibujado con polvo de azufre."
  },
  AvgDialog_13733_Content_60 = {
    Text = "Uvhash levantó lentamente la cabeza. La Sangre aún permanecía en las comisuras de su boca, sin lamer del todo, y sus ojos hacía tiempo que habían sido consumidos por la oscuridad."
  },
  AvgDialog_13733_Content_61 = {
    Text = "Se había convertido en una verdadera Bestia. O quizás, este fue su verdadero rostro desde el principio."
  },
  AvgDialog_13733_Content_62 = {
    Text = "<Red:Ha vuelto, todo ha vuelto...>"
  },
  AvgDialog_13733_Content_7 = {
    Text = "Buf... buf..."
  },
  AvgDialog_13733_Content_8 = {
    Text = "Impresionante, ser capaz de quedarse dormido en una situación como esta..."
  },
  AvgDialog_13733_Content_9 = {
    Text = "Hay una pregunta técnica que me gustaría hacer, Sr. Prin.\n¿El polvo que has esparcido no se lo llevará el Viento?"
  },
  AvgDialog_13734_Content_1 = {
    Text = "Huff... Por fin te alcancé.\nTe lo advierto, Uvhash, deberías saber las consecuencias de dejarme atrás, ¿verdad?"
  },
  AvgDialog_13734_Content_10 = {
    Text = "Por fin habías llegado al destino de este viaje. Prin dejó escapar un par de risas extrañas de su garganta, las llamas de la venganza haciendo temblar todo su cuerpo."
  },
  AvgDialog_13734_Content_11 = {
    Text = "<Shake:Vamos, Uvhash...>"
  },
  AvgDialog_13734_Content_12 = {
    Text = "<Red:Matemos hasta saciar nuestros corazones.>"
  },
  AvgDialog_13734_Content_2 = {Text = "¡Shh!!"},
  AvgDialog_13734_Content_3 = {
    Text = "Uvhash se agachó en lo alto de una duna de arena, dejando escapar un siseo impaciente por las fosas nasales, como una Bestia concentrada en la caza siendo molestada por un Acoso."
  },
  AvgDialog_13734_Content_4 = {
    Text = "Sus labios estaban ligeramente entreabiertos, sus fosas nasales temblaban levemente, y el brillo rojo sangre en sus ojos era más intenso que nunca."
  },
  AvgDialog_13734_Content_5 = {
    Text = "<RedShake:Lo encontré, lo encontré...>"
  },
  AvgDialog_13734_Content_6 = {
    Text = "Seguiste su mirada hacia abajo—"
  },
  AvgDialog_13734_Content_7 = {
    Text = "Incontables pequeños puntos negros se esparcían por las ondulantes dunas de arena, como hormigas arrastrándose sobre una mesa de arena."
  },
  AvgDialog_13734_Content_8 = {
    Text = "El choque de espadas, los rugidos de guerra y el tronar de los cascos se alzaban y caían en oleadas, mientras un gran tapiz de guerra se desplegaba lentamente ante tus ojos."
  },
  AvgDialog_13734_Content_9 = {
    Text = "Lemwashianos, Leonianos... Bien, muy bien."
  },
  AvgDialog_13735_Content_1 = {
    Text = "Expedición Solar"
  },
  AvgDialog_13735_Content_10 = {
    Text = "Aún estaba atado por cadenas invisibles, obligado a sentarse con las piernas cruzadas en el suelo en una postura incómoda, su figura casi fundiéndose en una con la oscuridad."
  },
  AvgDialog_13735_Content_11 = {
    Text = "...No esperaba que siguieras despierto."
  },
  AvgDialog_13735_Content_12 = {
    Text = "Un <Yellow:Gólem> no necesita dormir."
  },
  AvgDialog_13735_Content_13 = {
    Text = "¿Golem...?"
  },
  AvgDialog_13735_Content_14 = {
    Text = "Je, je... Deja de fingir."
  },
  AvgDialog_13735_Content_15 = {
    Text = "Puedes ver las cadenas en mí, así que seguramente debes saber lo que es un gólem."
  },
  AvgDialog_13735_Content_16 = {
    Text = "No esperabas que aquella mirada aparentemente casual de entonces hubiera sido notada por él.\nRealmente tiene los instintos de una Bestia."
  },
  AvgDialog_13735_Content_17 = {
    Text = "Mi profesor una vez me dijo..."
  },
  AvgDialog_13735_Content_18 = {
    Text = "Durante la era de la antigua Roma, un alquimista demente creó el primer gólem a costa de una gran cantidad de sacrificios humanos."
  },
  AvgDialog_13735_Content_19 = {
    Text = "También es la existencia más cercana a un Cuerpo Despertado que se ha encontrado en los textos antiguos."
  },
  AvgDialog_13735_Content_2 = {
    Text = "Desierto de Kushi del Norte, noche"
  },
  AvgDialog_13735_Content_20 = {
    Text = "Ese gólem... eras tú, ¿verdad?"
  },
  AvgDialog_13735_Content_21 = {
    Text = "Así es... Era yo. Me convertí en el perro faldero de <Blue:Calígula> y maté a mucha gente por él."
  },
  AvgDialog_13735_Content_22 = {
    Text = "Después, ya no me necesitaron, así que me encerraron bajo tierra en la más absoluta oscuridad, hasta que aquel me Liberó."
  },
  AvgDialog_13735_Content_23 = {
    Text = "Mientras Uvhash hablaba, su mirada se posó sobre Prin, que seguía profundamente dormida en la tienda."
  },
  AvgDialog_13735_Content_24 = {
    Text = "—¿La condición?"
  },
  AvgDialog_13735_Content_25 = {
    Text = "La condición es servirle como a un perro y matar a muchos Lemvashi en el campo de batalla."
  },
  AvgDialog_13735_Content_26 = {
    Text = "Después, cada uno por su lado, viviendo su propia vida."
  },
  AvgDialog_13735_Content_27 = {
    Text = "Uvhash se estiró cómodamente, despatarrado con las piernas abiertas mientras se recostaba contra la duna de arena."
  },
  AvgDialog_13735_Content_28 = {
    Text = "Unas cadenas de este calibre no pueden retenerte. ¿Por qué no simplemente matar al hechicero e irte?"
  },
  AvgDialog_13735_Content_29 = {
    Text = "Porque dijo que habría mucha gente en el campo de batalla."
  },
  AvgDialog_13735_Content_3 = {
    Text = "Zzz... Zzz... Jrrr..."
  },
  AvgDialog_13735_Content_30 = {
    Text = "<Red:Donde hay mucha gente, habrá mucha Sangre.>"
  },
  AvgDialog_13735_Content_31 = {
    Text = "<RedShake:Deberías saber que han pasado casi mil años desde la última vez que probé esa Sangre...>"
  },
  AvgDialog_13735_Content_32 = {Text = "..."},
  AvgDialog_13735_Content_33 = {
    Text = "Ese tipo no parece de los que cumplen sus promesas. ¿Y si te está mintiendo?"
  },
  AvgDialog_13735_Content_34 = {
    Text = "Entonces lo mataré. Simple, ¿no?"
  },
  AvgDialog_13735_Content_35 = {Text = "..."},
  AvgDialog_13735_Content_36 = {
    Text = "Tienes que admitir que sus palabras tienen mucho sentido."
  },
  AvgDialog_13735_Content_37 = {
    Text = "El Viento vespertino sopla suavemente mientras las dunas ondulantes se extienden interminablemente ante ti. Bajo el cielo infinito, solo quedan dos diminutas figuras."
  },
  AvgDialog_13735_Content_38 = {
    Text = "Levantas la cabeza, Mirar hacia arriba al cielo estrellado."
  },
  AvgDialog_13735_Content_39 = {
    Text = "Para pasar esta larga noche, decides intercambiar algunos pensamientos y experiencias con ¿Quién es Gólem que tienes delante."
  },
  AvgDialog_13735_Content_4 = {
    Text = "Unos ronquidos atronadores llenan la noche silenciosa. Parece que el pequeño incidente del día no ha afectado en absoluto el profundo sueño de Prin."
  },
  AvgDialog_13735_Content_40 = {
    Text = "Estar encerrado bajo tierra debió ser horrible.\nUna vez que cumplas el acuerdo, recuperarás tu libertad. ¿Cómo se siente ahora?"
  },
  AvgDialog_13735_Content_41 = {
    Text = "¿Y tú?\nTampoco has sido esclavo durante mucho tiempo. Vagando por el desierto día tras día, sobreviviendo a duras penas... ¿cómo se siente eso?"
  },
  AvgDialog_13735_Content_42 = {Text = "..."},
  AvgDialog_13735_Content_43 = {
    Text = "No muy bien, la verdad. En este lugar dejado de la mano de dios, ni siquiera puedes ver el Sol..."
  },
  AvgDialog_13735_Content_44 = {
    Text = "¿Estás ciego? ¿No puedes ver ese enorme Sol en el desierto?"
  },
  AvgDialog_13735_Content_45 = {
    Text = "No lo entiendes. Hablo del tipo de Sol que es suave, brillante y cálido cuando te ilumina... Eso no lo encontrarás en el desierto."
  },
  AvgDialog_13735_Content_46 = {
    Text = "Dejas escapar un bostezo mientras la Somnolencia se apodera de ti gradualmente.\nCon la guardia ligeramente bajada, la conversación se vuelve mucho más distendida."
  },
  AvgDialog_13735_Content_47 = {
    Text = "Para tu sorpresa, Uvhash resulta ser un oyente aceptable."
  },
  AvgDialog_13735_Content_48 = {
    Text = "Puede que no lo creas, pero en realidad tengo una misión propia..."
  },
  AvgDialog_13735_Content_49 = {
    Text = "Una vez que termine todo lo que hay que hacer, sin duda encontraré un lugar donde tumbarme a tomar el Sol, y comeré muchos, muchos pastelitos..."
  },
  AvgDialog_13735_Content_5 = {
    Text = "Incapaz de soportarlo más, finalmente abres la solapa de la tienda y sales afuera."
  },
  AvgDialog_13735_Content_50 = {
    Text = "...Dificultad de entender."
  },
  AvgDialog_13735_Content_51 = {
    Text = "Los Gólems nacen de la oscuridad, temiendo inherentemente la luz del sol. Casi mil años de encarcelamiento Solo habían profundizado su aversión hacia ella."
  },
  AvgDialog_13735_Content_52 = {
    Text = "De verdad que lo siento por ti. Tomar el Sol es lo más maravilloso del mundo..."
  },
  AvgDialog_13735_Content_53 = {
    Text = "Desafortunadamente para mí, incluso un deseo tan simple es difícil de cumplir..."
  },
  AvgDialog_13735_Content_54 = {
    Text = "El Viento arreció.\nLa fina arena a la deriva tejía capa tras capa de velos dorados pálidos, flotando suavemente bajo el cielo nocturno lleno de Estrellas."
  },
  AvgDialog_13735_Content_55 = {
    Text = "Escuchando el claro sonido del Viento a lo lejos, finalmente te sumiste en un Sueño."
  },
  AvgDialog_13735_Content_56 = {Text = "..."},
  AvgDialog_13735_Content_57 = {
    Text = "Norte del desierto de Kushi, día"
  },
  AvgDialog_13735_Content_58 = {
    Text = "¡¿Pero qué demonios?! ¡¿No juraste por todo lo sagrado que no habría tormentas de arena en los próximos días?!"
  },
  AvgDialog_13735_Content_59 = {
    Text = "Prin miró con los ojos como platos, señalando la furiosa arena que se acercaba desde el horizonte."
  },
  AvgDialog_13735_Content_6 = {
    Text = "Qué hermoso..."
  },
  AvgDialog_13735_Content_60 = {
    Text = "Ahora dime, <Big:¿qué@1es ESO?>"
  },
  AvgDialog_13735_Content_61 = {Text = "Uh"},
  AvgDialog_13735_Content_62 = {
    Text = "Antes de que entraras en Soñar, el dueño original había hecho algunas promesas poco sinceras para desplumar a esta gallina de los huevos de oro."
  },
  AvgDialog_13735_Content_63 = {
    Text = "No es momento de discutir. La tormenta de arena se acerca — ¡corre!"
  },
  AvgDialog_13735_Content_64 = {
    Text = "Dicho eso, saliste corriendo a toda velocidad, dejando a Prin muy atrás."
  },
  AvgDialog_13735_Content_65 = {
    Text = "<Big:¡Oye... ¡Vuelve aquí!>"
  },
  AvgDialog_13735_Content_66 = {
    Text = "¿Tormenta de arena? ¿Qué es eso? A mí el paisaje me parece bastante bonito."
  },
  AvgDialog_13735_Content_67 = {
    Text = "Uvhash corrió sin esfuerzo hasta ponerse a tu lado mientras iba de espaldas, con los ojos fijos en la distancia sin parpadear."
  },
  AvgDialog_13735_Content_68 = {
    Text = "¿Nunca has visto una tormenta de arena?"
  },
  AvgDialog_13735_Content_69 = {
    Text = "Uvhash se encogió de hombros."
  },
  AvgDialog_13735_Content_7 = {
    Text = "Buenas noches, Sr. Guía."
  },
  AvgDialog_13735_Content_70 = {
    Text = "Mi rango de actividad en el pasado se limitaba a la ciudad de Roma. Hay demasiadas cosas que nunca he visto."
  },
  AvgDialog_13735_Content_71 = {
    Text = "<Shake:Ugh... Puaj...>"
  },
  AvgDialog_13735_Content_72 = {
    Text = "Arrastrada por las cadenas, Prin, que se había quedado muy rezagada, fue levantada del suelo y salió volando."
  },
  AvgDialog_13735_Content_73 = {
    Text = "<Shake:M-Más despacio... Me muero aquí...>"
  },
  AvgDialog_13735_Content_74 = {
    Text = "Tch. Casi se me olvida, todavía queda ese viejo cascarrabias."
  },
  AvgDialog_13735_Content_75 = {
    Text = "Uvhash se dio la vuelta y levantó sin esfuerzo el cuerpo bajito y rechoncho de la maga."
  },
  AvgDialog_13735_Content_76 = {
    Text = "¿Q-Qué estás haciendo?"
  },
  AvgDialog_13735_Content_77 = {
    Text = "Nada del otro mundo, solo ayudarte a correr un poco más rápido."
  },
  AvgDialog_13735_Content_78 = {
    Text = "Dicho esto, Uvhash se metió al mago bajo el brazo como si nada, dio un paso adelante con un pie y se impulsó del suelo con la punta del pie trasero, enrollando todo su cuerpo como un resorte."
  },
  AvgDialog_13735_Content_79 = {
    Text = "¡Oye... te lo advierto, ahora no es momento de Jugar—<Big:¡¡¡AAARGH!!!>"
  },
  AvgDialog_13735_Content_8 = {Text = "¡¡!!"},
  AvgDialog_13735_Content_80 = {
    Text = "Uvhash se impulsó con fuerza y salió disparado como una flecha lanzada desde un arco."
  },
  AvgDialog_13735_Content_81 = {
    Text = "Yo— tú... maldito apestoso@1, ¡bájame!"
  },
  AvgDialog_13735_Content_82 = {
    Text = "Uvhash estalló en una Explosión de carcajadas.\nLa risa voló con el Viento, entrelazándose con granos dorados de arena y polvo, corriendo alegremente hacia la distancia."
  },
  AvgDialog_13735_Content_83 = {
    Text = "Ni hablar— ¡aún necesito mantenerte con vida para que me ayudes a recuperar mi libertad!"
  },
  AvgDialog_13735_Content_9 = {
    Text = "Uvhash apareció de la nada desde una esquina, sonriéndote con una mueca."
  },
  AvgDialog_13736_Content_1 = {
    Text = "La Guía, el Hechicero y el Esclavo"
  },
  AvgDialog_13736_Content_10 = {
    Text = "Cetrinas, secas, con líneas ásperas y Desenfrenadas en las palmas — estas son las manos de un guerrero."
  },
  AvgDialog_13736_Content_100 = {
    Text = "Lo siento, no tengo nada que decirte."
  },
  AvgDialog_13736_Content_101 = {
    Text = "Los mercenarios son una panda de sinvergüenzas sin fe. En cuanto a los esclavos, no podrían ni comprender lo que significan la dignidad y el honor."
  },
  AvgDialog_13736_Content_102 = {
    Text = "Tú y ese tipo — no hay ninguna diferencia real entre los dos."
  },
  AvgDialog_13736_Content_103 = {
    Text = "Pero hace mucho que dejé atrás la edad de actuar por impulso."
  },
  AvgDialog_13736_Content_104 = {
    Text = "Primero, no puedo ganarte en una pelea.\nSegundo, todavía me eres de alguna utilidad."
  },
  AvgDialog_13736_Content_105 = {
    Text = "No me importa de dónde vengas. Ahora mismo, en este preciso momento, sigue guiando el camino, mi querido guía."
  },
  AvgDialog_13736_Content_11 = {
    Text = "<Gray:Jamila · @1, 32 años, antigua mercenaria mameluca, ahora guía en el desierto...>"
  },
  AvgDialog_13736_Content_12 = {
    Text = "Procesas en silencio tu nueva identidad."
  },
  AvgDialog_13736_Content_13 = {
    Text = "Parece que has entrado en Soñar una vez más."
  },
  AvgDialog_13736_Content_14 = {
    Text = "¡Oye, qué estás murmurando? Si ya estás despierto, levántate de una vez. Mi <Blue:esclavo> y yo tenemos asuntos urgentes que atender."
  },
  AvgDialog_13736_Content_15 = {
    Text = "El hombre bajo y robusto con ropas peculiares es tu cliente para este trabajo — <Blue:Ludwig · Prin>."
  },
  AvgDialog_13736_Content_16 = {
    Text = "Habló con impaciencia, señalando descuidadamente con su látigo hacia atrás."
  },
  AvgDialog_13736_Content_17 = {Text = "Hss..."},
  AvgDialog_13736_Content_18 = {
    Text = "¡Uvhash—?!"
  },
  AvgDialog_13736_Content_19 = {
    Text = "Solo entonces notas al hombre oculto detrás de la duna de arena."
  },
  AvgDialog_13736_Content_2 = {
    Text = "@2, el Papa perdió el poder y surgió el Poder Real.\nLa ciudad santa de Acre se convirtió en una tierra ferozmente disputada.\n\nTemiendo a las fuerzas mamelucas lideradas por Baibars,\nel Príncipe hizo un llamamiento a todo el pueblo para marchar al este y reclamar la ciudad santa de Acre."
  },
  AvgDialog_13736_Content_20 = {
    Text = "Mantiene una postura agachada, con sus largos brazos apoyados casualmente en el suelo, como una Bestia lista para atacar."
  },
  AvgDialog_13736_Content_21 = {
    Text = "Al ver tu expresión de asombro, esboza una sonrisa, revelando una hilera de relucientes colmillos blancos."
  },
  AvgDialog_13736_Content_22 = {
    Text = "¿Qué, me conoces?"
  },
  AvgDialog_13736_Content_24 = {
    Text = "Antes de que pudieras responder, el largo látigo del hechicero azotó con fuerza a Uvhash."
  },
  AvgDialog_13736_Content_25 = {
    Text = "¿Quién es este? Amigo, te aconsejo que no hables con él."
  },
  AvgDialog_13736_Content_26 = {
    Text = "Puede que tenga los mismos ojos y nariz que nosotros, pero sigue siendo una Bestia incivilizada, o más bien..."
  },
  AvgDialog_13736_Content_28 = {
    Text = "Otro chasquido del látigo azotó con fuerza a Uvhash."
  },
  AvgDialog_13736_Content_29 = {
    Text = "Él es un <Red:demonio>."
  },
  AvgDialog_13736_Content_3 = {
    Text = "Y así, la gran <Yellow:Cruzada> comenzó una vez más su Prólogo..."
  },
  AvgDialog_13736_Content_30 = {
    Text = "A pesar de recibir latigazo tras latigazo, Uvhash ni siquiera parpadeó."
  },
  AvgDialog_13736_Content_31 = {
    Text = "Se limpió la Sangre que goteaba de su sien, acercó la palma a su nariz y olfateó, y luego comenzó a lamer tranquilamente la Sangre de las puntas de sus dedos."
  },
  AvgDialog_13736_Content_32 = {
    Text = "¿Ves eso? ¡Hasta el perro que vigila mi Puerta tiene más humanidad que él! Más bajo que una Bestia, ¡jajajaja!"
  },
  AvgDialog_13736_Content_33 = {
    Text = "¡Oye... viejo, tus golpes son mucho más débiles hoy.\n¿Qué pasa, ya ni puedes sostener el látigo firme?"
  },
  AvgDialog_13736_Content_34 = {Text = "Hmph..."},
  AvgDialog_13736_Content_35 = {
    Text = "La razón por la que las Bestias son Bestias es porque nunca pueden controlar su boca ni reconocer su lugar."
  },
  AvgDialog_13736_Content_36 = {
    Text = "No importa, te voy a <BigItalic:dar una buena lección>—"
  },
  AvgDialog_13736_Content_37 = {
    Text = "Prin estaba tan furioso que se le erizaron los bigotes, y entonces, como una bala disparada, salió lanzado rápidamente hacia Uvhash."
  },
  AvgDialog_13736_Content_38 = {Text = "Espera."},
  AvgDialog_13736_Content_39 = {
    Text = "Agarraste a Prin por la muñeca y lo jalaste hacia atrás."
  },
  AvgDialog_13736_Content_4 = {Text = "..."},
  AvgDialog_13736_Content_40 = {
    Text = "Dame el látigo."
  },
  AvgDialog_13736_Content_41 = {
    Text = "¡Suéltame! Déjame darle una lección a esa bestia..."
  },
  AvgDialog_13736_Content_42 = {
    Text = "Sr. Jamila, ahora soy su empleador. No necesito explicarle lo que es un empleador, ¿verdad?"
  },
  AvgDialog_13736_Content_43 = {
    Text = "Lo siento, pero soy el guía de este viaje.\nYa que soy el guía, ustedes siguen mis indicaciones."
  },
  AvgDialog_13736_Content_44 = {
    Text = "De lo contrario, me iré ahora mismo, y podrán encontrar el camino al <Blue:campo de batalla> por su cuenta."
  },
  AvgDialog_13736_Content_45 = {
    Text = "<Shake:¡Oye, oye...! Hablemos, hablemos...>"
  },
  AvgDialog_13736_Content_46 = {
    Text = "Una cosa más."
  },
  AvgDialog_13736_Content_47 = {
    Text = "Frunces el ceño y miras a Uvhash."
  },
  AvgDialog_13736_Content_48 = {
    Text = "Aunque rara vez se cruzaron sus caminos en el campus, has oído una que otra cosa sobre sus diversas hazañas."
  },
  AvgDialog_13736_Content_49 = {
    Text = "Definitivamente no es del tipo que se deja controlar por otros."
  },
  AvgDialog_13736_Content_5 = {
    Text = "Abres los ojos tras un largo y profundo sueño. Hasta donde alcanza la vista, no hay más que un vasto e ilimitado desierto."
  },
  AvgDialog_13736_Content_50 = {
    Text = "¿Qué le hiciste? ¿Cómo es posible que te obedezca tan voluntariamente?"
  },
  AvgDialog_13736_Content_51 = {
    Text = "¿Qué, estás cuestionando mis habilidades como <Blue:Hechicero Jefe de Levante>?"
  },
  AvgDialog_13736_Content_52 = {
    Text = "Este es un arte raro y perdido de nuestro oficio, y también es mi privacidad como empleador. Le pediría al guía que no meta las narices donde no le incumbe..."
  },
  AvgDialog_13736_Content_53 = {
    Text = "¿No vas a hablar?\nEntonces te lo sacaré a golpes."
  },
  AvgDialog_13736_Content_54 = {
    Text = "¡Oye, espera... <Big:¡Ay!>"
  },
  AvgDialog_13736_Content_56 = {
    Text = "<Shake:Sss, eso duele... ¡T-Tú no eres un guía cualquiera!>"
  },
  AvgDialog_13736_Content_57 = {
    Text = "Habla, ¿eres un espía enviado por <Blue:Remvashi> para interceptarme?"
  },
  AvgDialog_13736_Content_58 = {
    Text = "No respondiste a la Dudar de Prin, porque toda tu atención ya había sido atraída por otra cosa—"
  },
  AvgDialog_13736_Content_59 = {
    Text = "Una cadena delgada brillaba tenuemente bajo la luz del sol, emanando un resplandor inusual."
  },
  AvgDialog_13736_Content_6 = {
    Text = "¿Despierto? Vaya, vaya. No habíamos dado ni dos pasos cuando nuestro guía se desmayó por la insolación. ¿Qué clase de disparate es ese?"
  },
  AvgDialog_13736_Content_60 = {
    Text = "Se extendía desde la muñeca de Prin hasta terminar en el cuello de Uvhash."
  },
  AvgDialog_13736_Content_61 = {
    Text = "<Gray:Esta técnica me resulta tan familiar... Siento que alguien la mencionó antes...>"
  },
  AvgDialog_13736_Content_62 = {
    Text = "Si no se portan bien, solo ponles una correa. Así de simple."
  },
  AvgDialog_13736_Content_63 = {
    Text = "Eso es ilegal en Londinium, señorita Agrippa. Me temo que tendremos que instruirla en algunos conocimientos legales básicos..."
  },
  AvgDialog_13736_Content_64 = {
    Text = "Hehe, no soy tonta."
  },
  AvgDialog_13736_Content_65 = {
    Text = "¿Conoces @1?"
  },
  AvgDialog_13736_Content_66 = {
    Text = "Es un arte secreto ancestral que permite al conjurador controlar a otros con una cadena invisible..."
  },
  AvgDialog_13736_Content_67 = {
    Text = "En cuanto al precio..."
  },
  AvgDialog_13736_Content_68 = {
    Text = "¿Cuál era el precio? Maldición, no puedo recordarlo..."
  },
  AvgDialog_13736_Content_69 = {
    Text = "Estabas perdido en tus recuerdos cuando alguien te arrancó la máscara del rostro de repente."
  },
  AvgDialog_13736_Content_7 = {
    Text = "¡Menos mal que Solo vengo a este lugar dejado de la mano de Dios una vez en la vida, @1!"
  },
  AvgDialog_13736_Content_70 = {
    Text = "Tres ríos curvos... ¡¿Eres un <Blue:esclavo mercenario de Mamluk>?!"
  },
  AvgDialog_13736_Content_71 = {
    Text = "En el momento en que Prin terminó de hablar, Uvhash, que parecía completamente desinteresado, se giró de repente para mirarte."
  },
  AvgDialog_13736_Content_72 = {
    Text = "Interesante..."
  },
  AvgDialog_13736_Content_73 = {
    Text = "No, espera— La gente de Mamluk debería estar en el campo de batalla ahora mismo..."
  },
  AvgDialog_13736_Content_74 = {
    Text = "Ya veo. Eres un desertor."
  },
  AvgDialog_13736_Content_75 = {
    Text = "Instintivamente te tocaste el rostro."
  },
  AvgDialog_13736_Content_76 = {
    Text = "<Gray:Así que tengo tatuajes en la cara...>"
  },
  AvgDialog_13736_Content_77 = {
    Text = "Claro, soy un desertor. Mi ciudad natal es <Blue:Lemwashi>, pero no quiero volver..."
  },
  AvgDialog_13736_Content_78 = {
    Text = "Los desertores también necesitan comer, así que ahora me gano la vida como guía.\nNo te preocupes— mi mayor virtud es ser meticuloso con mi trabajo."
  },
  AvgDialog_13736_Content_79 = {
    Text = "Te garantizo que puedo llevarte al campo de batalla—"
  },
  AvgDialog_13736_Content_8 = {
    Text = "¿Guía? Dónde... es esto..."
  },
  AvgDialog_13736_Content_80 = {Text = "Pfft."},
  AvgDialog_13736_Content_81 = {
    Text = "Habiendo visto suficiente de la farsa ante él, Uvhash se estiró perezosamente y se acercó a ti con paso tranquilo."
  },
  AvgDialog_13736_Content_82 = {
    Text = "Te pasó un brazo por el hombro y luego giró suavemente tu barbilla hasta que tu mirada quedó dirigida directamente al silencioso mago frente a ti."
  },
  AvgDialog_13736_Content_83 = {
    Text = "Ya que todos somos esclavos, o al menos lo fuimos— aquí va una pequeña pista—"
  },
  AvgDialog_13736_Content_84 = {
    Text = "Si yo fuera tú, me callaría ahora mismo.\n¿Sabes qué tipo de gente es la que más odia ese de ahí?"
  },
  AvgDialog_13736_Content_85 = {
    Text = "...Que precisamente este tipo me dé lecciones sobre cuidar mis palabras— qué sensación tan peculiar."
  },
  AvgDialog_13736_Content_86 = {
    Text = "...Cuéntame."
  },
  AvgDialog_13736_Content_87 = {
    Text = "Tercero— los mercenarios mamelucos."
  },
  AvgDialog_13736_Content_88 = {
    Text = [[
En segundo lugar, los Lemwashianos.
En cuanto al primero...]]
  },
  AvgDialog_13736_Content_89 = {
    Text = "Un dolor agudo te atraviesa el hombro — Uvhash te da una fuerte palmada en la espalda mientras se ríe a carcajadas."
  },
  AvgDialog_13736_Content_9 = {
    Text = "El sol abrasador te cuece hasta hacerte dar vueltas la cabeza. Miras tus propias manos."
  },
  AvgDialog_13736_Content_90 = {
    Text = "<Big:¡Por supuesto, son los mercenarios Mamulu de Lemwash!>"
  },
  AvgDialog_13736_Content_91 = {
    Text = "<Gray:...Genial. Nadie más podría estar riéndose de esto.>"
  },
  AvgDialog_13736_Content_92 = {
    Text = "<Gray:Este tipo realmente tiene un talento de primera para ofender a la gente.>"
  },
  AvgDialog_13736_Content_93 = {Text = "Heh..."},
  AvgDialog_13736_Content_94 = {
    Text = "En aquel entonces, los mercenarios mamelucos masacraron a decenas de miles de los míos. Mi esposa, mis camaradas, mi mentor... todos perecieron aquí."
  },
  AvgDialog_13736_Content_95 = {
    Text = "Bueno, mi historia trágica ha terminado. Pueden volver a reírse."
  },
  AvgDialog_13736_Content_96 = {
    Text = "Lo siento, Sr. Prin. Permítame explicarle — aunque sí tengo algo de... bueno, un historial menos que honorable."
  },
  AvgDialog_13736_Content_97 = {
    Text = "Pero todo eso quedó en el pasado. No tiene nada que ver con quien soy ahora."
  },
  AvgDialog_13736_Content_98 = {
    Text = "Prin te hace un gesto desdeñoso con la mano."
  },
  AvgDialog_13736_Content_99 = {
    Text = "Su cara redonda, tostada bajo el sol abrasador, parece una manzana demasiado madura — lamentablemente, esta manzana no está muy contenta ahora mismo."
  },
  AvgDialog_13737_Content_1 = {
    Text = "El trágico adiós"
  },
  AvgDialog_13737_Content_10 = {
    Text = "<RedShake:Correr...>"
  },
  AvgDialog_13737_Content_11 = {
    Text = "Uvhash aplastó sin esfuerzo el cerebro del que bloqueaba su Camino, y luego caminó lentamente hacia otro soldado."
  },
  AvgDialog_13737_Content_12 = {
    Text = "<RedShake:Sangre... Necesito más Sangre...>"
  },
  AvgDialog_13737_Content_13 = {
    Text = "Levanto lentamente su mano."
  },
  AvgDialog_13737_Content_15 = {Text = "..."},
  AvgDialog_13737_Content_16 = {
    Text = "Eres tú..."
  },
  AvgDialog_13737_Content_17 = {
    Text = "Sí, soy yo."
  },
  AvgDialog_13737_Content_18 = {
    Text = "Te interpones entre los dos, girándote para mirar a los Soldados detrás de ti que han caído de rodillas del miedo."
  },
  AvgDialog_13737_Content_19 = {
    Text = "Idos. Corred tan lejos como podáis."
  },
  AvgDialog_13737_Content_2 = {
    Text = "Límite del desierto de Kusi, campo de batalla"
  },
  AvgDialog_13737_Content_20 = {
    Text = "<Big:¡¡Largaos!!>"
  },
  AvgDialog_13737_Content_21 = {
    Text = "<Shake:V-vale... Ya me voy...>"
  },
  AvgDialog_13737_Content_22 = {
    Text = "Los Soldados huyeron a gatas a toda prisa."
  },
  AvgDialog_13737_Content_23 = {
    Text = "¿Por qué te interpones en mi camino? Apenas empezaba a saborear el placer de la Sangre y la batalla..."
  },
  AvgDialog_13737_Content_24 = {
    Text = "Solo quieres pelear, ¿verdad? Yo Jugaré contigo."
  },
  AvgDialog_13737_Content_25 = {
    Text = "¿Tú? Jajajaja, ¿qué eres tú—"
  },
  AvgDialog_13737_Content_27 = {
    Text = "Presionas tu hoja curva contra la garganta de Uvhash, contemplando con calma sus ojos que hace tiempo perdieron el enfoque."
  },
  AvgDialog_13737_Content_28 = {
    Text = "¿Cómo lo sabrías sin intentarlo?"
  },
  AvgDialog_13737_Content_3 = {
    Text = "¡Oye, escuchaste? Otro se ha vuelto loco, mata a todo el que ve."
  },
  AvgDialog_13737_Content_4 = {
    Text = "Dicen que no es ni Leoriano ni Lemwashiano... nadie sabe de dónde vino."
  },
  AvgDialog_13737_Content_5 = {
    Text = "En fin, salgamos de aquí—"
  },
  AvgDialog_13737_Content_6 = {Text = "..."},
  AvgDialog_13737_Content_7 = {
    Text = "<Shake:C-cuándo apareciste...>"
  },
  AvgDialog_13737_Content_8 = {
    Text = "¡Ahhh! ¡Rápido!"
  },
  AvgDialog_13737_Content_9 = {Text = "—¡!!"},
  AvgDialog_13738_Content_1 = {
    Text = "Bien, la tormenta de arena se fue en la otra dirección. Ahora nosotros..."
  },
  AvgDialog_13738_Content_10 = {Text = "..."},
  AvgDialog_13738_Content_11 = {
    Text = "Quieres ir al campo de batalla, ¿no? Entonces naturalmente deberías avanzar en la <Red:dirección de la Sangre>."
  },
  AvgDialog_13738_Content_12 = {
    Text = "¿La dirección de la Sangre...?"
  },
  AvgDialog_13738_Content_13 = {
    Text = "Señalaste la figura de Uvhash mientras se alejaba a grandes zancadas."
  },
  AvgDialog_13738_Content_14 = {
    Text = "Su dirección."
  },
  AvgDialog_13738_Content_2 = {
    Text = "¡¡BLEGH—!!"
  },
  AvgDialog_13738_Content_3 = {
    Text = "Prin se apoyó contra el tronco de un árbol desnudo, encorvándose mientras comenzaba a vomitar violentamente."
  },
  AvgDialog_13738_Content_4 = {
    Text = "Te juro, una vez que este trato esté hecho. Te juro..."
  },
  AvgDialog_13738_Content_5 = {
    Text = "Esta vez, la débil Maldición del mago no recibió respuesta alguna."
  },
  AvgDialog_13738_Content_6 = {
    Text = "Tras un descubrimiento, las pupilas de Uvhash se contrajeron repentinamente de forma casi imperceptible por un instante."
  },
  AvgDialog_13738_Content_7 = {
    Text = "<Red:...Sangre.>"
  },
  AvgDialog_13738_Content_8 = {
    Text = "Dicho esto, se marchó sin mirar atrás."
  },
  AvgDialog_13738_Content_9 = {
    Text = "¡Espera...! ¡Sin mi permiso, no puedes ir a ningún lado!"
  },
  AvgDialog_13739_Content_1 = {
    Text = "Los Buitres graznan bajo el crepúsculo rojo sangre. El campo de batalla lleva mucho tiempo desierto."
  },
  AvgDialog_13739_Content_10 = {
    Text = "Durante la pelea, percibes claramente que el Estado de Uvhash se deteriora a un ritmo alarmante."
  },
  AvgDialog_13739_Content_11 = {
    Text = "Sea o no un efecto secundario del contrato, ahora está al límite de sus fuerzas."
  },
  AvgDialog_13739_Content_12 = {
    Text = "Una batalla solo es divertida cuando los oponentes están igualados. Por eso, no me importa volverme un poco más débil."
  },
  AvgDialog_13739_Content_13 = {
    Text = "Nunca me importó lo que piensan los humanos, igual que a los humanos nunca les importan las hormigas."
  },
  AvgDialog_13739_Content_14 = {
    Text = "Pero tú eres diferente. Hay una poderosa Fortaleza dentro de ti, y sabes cómo ejercer el Contrataque."
  },
  AvgDialog_13739_Content_15 = {
    Text = "Sigue así, guerrero. Esos aburridos deseos tuyos — el Sol, los pastelitos, y demás — quizás realmente puedan hacerse realidad."
  },
  AvgDialog_13739_Content_16 = {
    Text = "<Gray:Fue Solo algo que dije sin pensar, y aun así lo recordó...>"
  },
  AvgDialog_13739_Content_17 = {
    Text = "Vamos... al lugar del que hablaste, donde brilla el Sol."
  },
  AvgDialog_13739_Content_18 = {Text = "?!"},
  AvgDialog_13739_Content_19 = {
    Text = "¿Y tú qué?"
  },
  AvgDialog_13739_Content_2 = {
    Text = "Tú y Uvhash estáis a menos de diez metros de distancia, mirándoos en silencio."
  },
  AvgDialog_13739_Content_20 = {
    Text = "¿Yo...? El viejo tenía un último truco bajo la manga. No viviré mucho más. Je je..."
  },
  AvgDialog_13739_Content_21 = {
    Text = "El viejo y yo debemos morir... ese es el verdadero precio de romper el pacto."
  },
  AvgDialog_13739_Content_22 = {
    Text = "Caminó hacia ti con pasos fatigosos, acortando lentamente la distancia."
  },
  AvgDialog_13739_Content_23 = {
    Text = "Entonces se mordió la muñeca con los dientes."
  },
  AvgDialog_13739_Content_24 = {
    Text = "Sangre Carmesí y acre brotó a raudales, goteando sobre tu cabeza, tus párpados, y luego deslizándose por el puente de tu nariz hasta tus labios resecos."
  },
  AvgDialog_13739_Content_25 = {
    Text = "Esta Sangre... considérala mi Sacramento de despedida."
  },
  AvgDialog_13739_Content_26 = {
    Text = "Los Buitres sobrevolaban en círculos sobre su cabeza, habiendo puesto claramente la mira en su presa moribunda."
  },
  AvgDialog_13739_Content_27 = {
    Text = "Nací de innumerables carnes y he vagado por este mundo durante casi mil años..."
  },
  AvgDialog_13739_Content_28 = {
    Text = "He visto pan de Oro danzando por el cielo durante procesiones triunfales, y palacios de Oro arder ferozmente entre las llamas."
  },
  AvgDialog_13739_Content_29 = {
    Text = "He saboreado la Sangre más exquisita, y he tenido la Experiencia de las batallas más brutales."
  },
  AvgDialog_13739_Content_3 = {
    Text = "Hey... ¿cuánto tiempo hemos estado peleando?"
  },
  AvgDialog_13739_Content_30 = {
    Text = "Masacré humanos, y también fui encadenado y explotado por humanos, y al final, como era de esperar, encontré la muerte a manos humanas."
  },
  AvgDialog_13739_Content_31 = {
    Text = "Ahora, es hora de que me vaya..."
  },
  AvgDialog_13739_Content_32 = {
    Text = "Te miró desde arriba, con los ojos desprovistos de cualquier emoción."
  },
  AvgDialog_13739_Content_33 = {
    Text = "Sangre Pegajosa goteaba desde la punta de tu nariz hasta el suelo, gota a gota."
  },
  AvgDialog_13739_Content_34 = {
    Text = "Eras como un iniciado bautismal desconcertado, completamente perdido e indefenso ante todo lo que se desplegaba ante tus ojos."
  },
  AvgDialog_13739_Content_35 = {
    Text = "Devuelvo toda mi carne a ti y a este mundo."
  },
  AvgDialog_13739_Content_36 = {
    Text = "Pertenecen al cielo, a la Tierra... a ti, pero no a mí."
  },
  AvgDialog_13739_Content_37 = {
    Text = "Ahora puedes largarte... largarte y no mires atrás."
  },
  AvgDialog_13739_Content_38 = {
    Text = "Tu visión es finalmente engullida por la vasta niebla de Sangre.\nCierras los ojos, sintiendo oleada tras oleada de mareo, Como si la Tierra se hundiera sin fin."
  },
  AvgDialog_13739_Content_39 = {
    Text = "Apenas puedes recordar lo que sucedió Después."
  },
  AvgDialog_13739_Content_4 = {Text = "..."},
  AvgDialog_13739_Content_40 = {
    Text = "Quizás ya te habías ido, o quizás moriste junto a él en este desierto."
  },
  AvgDialog_13739_Content_41 = {
    Text = "Nada de eso importa. Porque recordarás para siempre aquel momento antes de su muerte."
  },
  AvgDialog_13739_Content_42 = {
    Text = "En aquel momento, una bandada de Buitres negros pasó volando, bloqueando el resplandor detrás de él."
  },
  AvgDialog_13739_Content_43 = {
    Text = "La luz seguía desvaneciéndose, las sombras se arrastraban desde todos los lados, y él se arrodilló allí entre esas sombras, mirándote."
  },
  AvgDialog_13739_Content_44 = {Text = "Dijo—"},
  AvgDialog_13739_Content_45 = {Text = "Lárgate."},
  AvgDialog_13739_Content_46 = {
    Text = "Ve a buscar ese maldito lugar donde brilla el Sol."
  },
  AvgDialog_13739_Content_5 = {
    Text = "¿Quién sabe... una hora, un día?"
  },
  AvgDialog_13739_Content_6 = {Text = "..."},
  AvgDialog_13739_Content_7 = {
    Text = "Mil años... han pasado casi mil años desde que disfruté de una batalla tan estimulante."
  },
  AvgDialog_13739_Content_8 = {
    Text = "Eres un guerrero nato."
  },
  AvgDialog_13739_Content_9 = {
    Text = "Qué sorprendente. ¿Cuándo aprendiste a halagar como un humano?"
  },
  AvgDialog_138765_Content_1 = {
    Text = "Las brasas de las dimensiones están en movimiento. La rueca del destino, Moirai, ya gira en este lugar."
  },
  AvgDialog_138765_Content_2 = {
    Text = "Arriésgate, Guardián de Secretos{Male=先生,Female=小姐}. Te ayudaré a corregir el destino equivocado y a destruir los capullos que no deberían existir."
  },
  AvgDialog_138765_Content_3 = {
    Text = "El curso del destino jamás debe ser tejido por manos ajenas."
  },
  AvgDialog_138766_Content_1 = {
    Text = "¿Esto... se acabó?"
  },
  AvgDialog_138766_Content_2 = {
    Text = "Ten cuidado, Guardián... el huso que desenreda el destino ya ha comenzado a girar tras ella..."
  },
  AvgDialog_138766_Content_3 = {
    Text = "Je... jajajaja...!"
  },
  AvgDialog_138766_Content_4 = {
    Text = "\"¡Mirad, ciegos fieles del Destino! ¡La campana que siempre estuvo destinada a doblar por vosotros ha sonado al fin!\""
  },
  AvgDialog_138766_Content_5 = {
    Text = "\"¡Yo soy el final— yo soy el Destino— yo soy @4!\""
  },
  AvgDialog_138766_Content_6 = {
    Text = "\"¡¡Ahora os otorgo el final definitivo. Os concedo la liberación que tan desesperadamente anhelabais!!\""
  },
  AvgDialog_13946_Content_1 = {
    Text = "Mar sin apoyo"
  },
  AvgDialog_13946_Content_10 = {
    Text = "Te enviaron a \"escoltarme\" para encontrar a la bruja?\nQué broma. Sus intenciones no podrían ser más obvias..."
  },
  AvgDialog_13946_Content_11 = {
    Text = "Goliath deja escapar un quejido de dolor. Debajo de él, un charco de Sangre rojo oscuro se extiende lentamente, goteando hasta tus pies."
  },
  AvgDialog_13946_Content_12 = {
    Text = "<Red:Quieren que ambos muramos aquí, en este mar.>"
  },
  AvgDialog_13946_Content_13 = {
    Text = "¡Mi señor, estáis gravemente herido! Qué ocurrió..."
  },
  AvgDialog_13946_Content_14 = {
    Text = "Recuerdos caóticos inundan tu mente."
  },
  AvgDialog_13946_Content_15 = {
    Text = "En la última batalla decisiva, el líder Goliath subestimó a su enemigo y perdió ante una tribu rival."
  },
  AvgDialog_13946_Content_16 = {
    Text = "Los Filisteos no aceptarían la derrota. El gravemente herido Goliath fue desterrado, acompañado solo por un pequeño bote destartalado, y por ti—"
  },
  AvgDialog_13946_Content_17 = {
    Text = "El más débil de los Filisteos, que incluso podría perder un combate de lucha contra un niño de diez años."
  },
  AvgDialog_13946_Content_18 = {
    Text = "Recuerdo que el Líder <Blue:Con Glen> dijo una vez que hay una bruja misteriosa en las aguas cercanas. Ella usa una especie de baba negra..."
  },
  AvgDialog_13946_Content_19 = {
    Text = "Solo la vertamos sobre la Herida, ¡y vuestras lesiones sanarán sin duda!"
  },
  AvgDialog_13946_Content_2 = {
    Text = "Suspira por El Apóstol del Mar.\nSuspira por nuestra luz, nuestra esperanza.\n\nPor el Destino de ser Exiliados al océano, gemimos, nos lamentamos, lloramos hasta que no quedan lágrimas."
  },
  AvgDialog_13946_Content_20 = {
    Text = "Soltaste por reflejo la leyenda de la bruja, solo para percibir algo extraño en ella un momento después."
  },
  AvgDialog_13946_Content_21 = {
    Text = "<Gray:Espera, ¿podría esa baba ser D-Slime...>"
  },
  AvgDialog_13946_Content_22 = {
    Text = "¿Líder, Con Glen?"
  },
  AvgDialog_13946_Content_23 = {
    Text = "Una sonrisa se dibujó lentamente en el frío rostro de Goliath."
  },
  AvgDialog_13946_Content_24 = {
    Text = "Así que ya se ha convertido en vuestro nuevo Líder. Qué eficientes. Como era de esperarse de mis queridísimos compañeros de tribu."
  },
  AvgDialog_13946_Content_25 = {Text = "¡Splash!!"},
  AvgDialog_13946_Content_26 = {
    Text = "El pequeño bote podrido finalmente no pudo resistir el Impacto de las olas y se abrió con un gran agujero, el agua de mar entrando sin cesar."
  },
  AvgDialog_13946_Content_27 = {
    Text = "Tch, justo como esperaba."
  },
  AvgDialog_13946_Content_28 = {
    Text = "Esto es malo, ¡nos ahogaremos! Necesitamos encontrar algo para tapar el agujero, rápido..."
  },
  AvgDialog_13946_Content_29 = {Text = "...Oh."},
  AvgDialog_13946_Content_3 = {
    Text = "¡Oh, por favor vela por los afligidos!\nPosa tu mirada misericordiosa sobre nosotros, y concédenos el manantial negro de PV."
  },
  AvgDialog_13946_Content_30 = {
    Text = "Goliath se recostó contra la cubierta con poco interés, dejando que la Sangre bajo él tiñera de rojo el agua de mar que inundaba la embarcación."
  },
  AvgDialog_13946_Content_31 = {
    Text = "Relájate. Incluso si arreglamos el bote, tienen diez mil formas de asegurarse de que muera en estas aguas."
  },
  AvgDialog_13946_Content_32 = {
    Text = "Mi consejo es que dejes de preocuparte por mí. Bájate del bote y nada de vuelta por tu cuenta."
  },
  AvgDialog_13946_Content_33 = {
    Text = "Diles que ya me mataste. Si tienes suerte, puede que consigas conservar tu vida."
  },
  AvgDialog_13946_Content_34 = {
    Text = "¿Y qué hay de ti...?"
  },
  AvgDialog_13946_Content_35 = {Text = "¿Yo?"},
  AvgDialog_13946_Content_36 = {
    Text = "Goliath admiró tranquilamente el paisaje del mar, luego giró la cabeza hacia ti con una leve sonrisa."
  },
  AvgDialog_13946_Content_37 = {
    Text = "Sentado aquí disfrutando de la vista del océano, y de paso esperando la muerte."
  },
  AvgDialog_13946_Content_38 = {Text = "......¿?"},
  AvgDialog_13946_Content_39 = {
    Text = "<Gray:Qué pesimista. ¿De verdad es este el Goliath que conozco?>"
  },
  AvgDialog_13946_Content_4 = {
    Text = "<Red:¡Misericordia, misericordia, misericordia...>"
  },
  AvgDialog_13946_Content_40 = {
    Text = "Ah, cierto, hay algo más de lo que debería advertirte."
  },
  AvgDialog_13946_Content_41 = {
    Text = "Hay un agujero detrás de tu trasero. En mi Experiencia, este bote está a punto de partirse en dos en cualquier momento. No te queda mucho tiempo para pensar."
  },
  AvgDialog_13946_Content_42 = {Text = "¡Splash!!"},
  AvgDialog_13946_Content_43 = {
    Text = "Como si quisiera confirmar las palabras de Goliath, una enorme ola golpeó, y el bote de madera se partió en dos al instante."
  },
  AvgDialog_13946_Content_44 = {
    Text = "<Shake:¡¡Aaaaah—!!>"
  },
  AvgDialog_13946_Content_45 = {
    Text = "El agua salada no dejaba de inundar tus pulmones. Abriste la boca, solo para invitar a más agua de mar a Devorarte por completo."
  },
  AvgDialog_13946_Content_46 = {
    Text = "Tu cuerpo seguía hundiéndose, respirar se volvía cada vez más Dificultad..."
  },
  AvgDialog_13946_Content_47 = {
    Text = "Mientras tu consciencia se nublaba, pareciste escuchar un suspiro de impotencia."
  },
  AvgDialog_13946_Content_48 = {
    Text = "Antes de que pudieras reaccionar, una fuerza poderosa agarró tu Cabello y te sacó del mar sin esfuerzo."
  },
  AvgDialog_13946_Content_49 = {
    Text = "*Cof cof*... ¡Urgh!"
  },
  AvgDialog_13946_Content_5 = {Text = "..."},
  AvgDialog_13946_Content_50 = {
    Text = "Agárrate fuerte. Este es el único salvavidas que nos queda a los dos."
  },
  AvgDialog_13946_Content_51 = {
    Text = "Miraste a tu alrededor, solo para Descubrir que tú y Goliath estabais ambos apretujados sobre un tablón de madera inestable a punto de desmoronarse."
  },
  AvgDialog_13946_Content_52 = {
    Text = "Pero qué... Se supone que los Filisteos son maestros del mar, navegando los cuatro océanos. ¿Cómo es posible que ni siquiera sepas nadar?"
  },
  AvgDialog_13946_Content_53 = {
    Text = "¿De verdad eres un Filisteo?"
  },
  AvgDialog_13946_Content_54 = {
    Text = "<SmallShake:Mis disculpas. Este cuerpo mío ha estado plagado de Enfermedad desde la infancia...>"
  },
  AvgDialog_13946_Content_55 = {
    Text = "Gracias, mi señor. Si no fuera por vos, habría muerto aquí..."
  },
  AvgDialog_13946_Content_56 = {
    Text = "...Parece que no te enviaron ellos para matarme."
  },
  AvgDialog_13946_Content_57 = {
    Text = "El instinto de supervivencia que acabas de mostrar fue intenso. No parecía una actuación."
  },
  AvgDialog_13946_Content_58 = {
    Text = "Goliath se apartó el Cabello mojado que se le pegaba a la frente y contempló el mar envuelto en niebla ante él."
  },
  AvgDialog_13946_Content_59 = {
    Text = "Cuando caímos al mar, te aferraste a mí como un gran cangrejo, negándote a soltarme ni un segundo. ¿Por qué?"
  },
  AvgDialog_13946_Content_6 = {
    Text = "¿Despertar?"
  },
  AvgDialog_13946_Content_60 = {
    Text = "¿Eh? Para sobrevivir, por supuesto..."
  },
  AvgDialog_13946_Content_61 = {
    Text = "Para sobrevivir... Pero eres inútil incluso estando vivo. Ni siquiera sabes nadar."
  },
  AvgDialog_13946_Content_62 = {
    Text = "¿Para qué vives exactamente?"
  },
  AvgDialog_13946_Content_63 = {
    Text = "La voz de Goliath se fue apagando gradualmente, como si te preguntara a ti, pero también se lo preguntara a sí mismo."
  },
  AvgDialog_13946_Content_64 = {
    Text = "Exiliado por los suyos, cargando con una Lesión grave—su Camino por delante era como el mar envuelto en niebla ante él, con Solo una incertidumbre interminable por delante."
  },
  AvgDialog_13946_Content_65 = {Text = "..."},
  AvgDialog_13946_Content_66 = {
    Text = "Mi señor, no dejabais de decir que esperaríais la muerte, pero cuando las olas realmente golpearon, no solo encontrasteis este tablón y os subisteis a él, sino que también me salvasteis."
  },
  AvgDialog_13946_Content_67 = {
    Text = "...Eso fue porque no dejabas de aferrarte a mí y no me soltabas."
  },
  AvgDialog_13946_Content_68 = {
    Text = "Nada de eso importa. Lo que importa es que gracias a vos, mi señor, ambos estamos vivos ahora mismo."
  },
  AvgDialog_13946_Content_69 = {
    Text = "¿Por qué crees que es así?"
  },
  AvgDialog_13946_Content_7 = {
    Text = "El mar agita olas abrasadas por la luz del sol, y el Viento marino ligeramente salado trae a tus fosas nasales un espeso y acre hedor a salmuera."
  },
  AvgDialog_13946_Content_70 = {
    Text = "Goliat sacudió la cabeza."
  },
  AvgDialog_13946_Content_71 = {
    Text = "Sinceramente, yo tampoco lo sé. Pero hay algo que he llegado a comprender..."
  },
  AvgDialog_13946_Content_72 = {
    Text = "Goliath bajó la cabeza y te miró pensativo."
  },
  AvgDialog_13946_Content_73 = {
    Text = "Ahora entiendo cómo alguien tan inútil como tú ha logrado sobrevivir tanto tiempo."
  },
  AvgDialog_13946_Content_8 = {
    Text = "<Gray:¿Esto es... Soñar?>"
  },
  AvgDialog_13946_Content_9 = {
    Text = "Como era de esperarse del más notorio enclenque enfermizo del clan: una sola ola grande basta para dejarte fuera de combate medio día."
  },
  AvgDialog_13947_Content_1 = {
    Text = "Crónica de gigantes"
  },
  AvgDialog_13947_Content_10 = {
    Text = "Solo los tontos confían sus vidas a otros."
  },
  AvgDialog_13947_Content_11 = {
    Text = "<Gray:La bruja...>"
  },
  AvgDialog_13947_Content_12 = {
    Text = "Según el archivo del Despertador de Goliat, esta llamada \"bruja\" es sin duda Miryam."
  },
  AvgDialog_13947_Content_13 = {
    Text = "Aunque el Desarrollo posterior no fue el ideal, Miryam sí salvó la vida de Goliath."
  },
  AvgDialog_13947_Content_14 = {
    Text = "Mi señor, habéis sufrido una Lesión grave. No parece haber otra opción ahora mismo. ¿Por qué no buscamos a la bruja juntos—"
  },
  AvgDialog_13947_Content_15 = {Text = "¡¡BANG!!"},
  AvgDialog_13947_Content_16 = {
    Text = "Con una fuerza tremenda, tu Frágil garganta fue atrapada en un agarre de hierro. Tus pies dejaron el suelo mientras eras alzado ante los ojos del gigante."
  },
  AvgDialog_13947_Content_17 = {
    Text = "Solo lo diré una vez: no me mires con esos ojos, y no me hables en ese tono."
  },
  AvgDialog_13947_Content_18 = {
    Text = "Lo que yo, Goliath, menos necesito es la compasión de los débiles."
  },
  AvgDialog_13947_Content_19 = {
    Text = "El tono de Goliath era plano, su expresión inmutable, como si solo estuviera hablando del tiempo contigo."
  },
  AvgDialog_13947_Content_2 = {
    Text = "La luz del Sol abrasa la superficie del mar, como si quisiera desgastar toda vida bajo el calor interminable."
  },
  AvgDialog_13947_Content_20 = {
    Text = "Pero estabas tan cerca—lo suficiente como para ver con claridad el enrojecimiento en el borde de sus ojos, nacido del dolor y la rebeldía."
  },
  AvgDialog_13947_Content_21 = {
    Text = "En ese momento, pareció despojado de toda la gloria de un soberano de los mares, reducido a un pez a la deriva perdido en el interminable océano, Solo como tú."
  },
  AvgDialog_13947_Content_22 = {
    Text = "Mis disculpas... ugh, mi señor..."
  },
  AvgDialog_13947_Content_23 = {
    Text = "<Shake:Wooo——>"
  },
  AvgDialog_13947_Content_24 = {
    Text = "El sonido grave de un cuerno llegó flotando desde la distancia."
  },
  AvgDialog_13947_Content_25 = {
    Text = "La presión en tu cuello se alivió de repente. Goliath soltó su agarre y dirigió la mirada hacia la dirección del cuerno."
  },
  AvgDialog_13947_Content_26 = {
    Text = "<Gray:Cof cof... Ja, salvado...>"
  },
  AvgDialog_13947_Content_27 = {
    Text = "Qué interesante... ¿Preocupados de que no esté muriendo lo suficientemente rápido, así que han venido en manada a despedirme?"
  },
  AvgDialog_13947_Content_28 = {
    Text = "Al poco tiempo, una enorme flota los había rodeado, atrapándolos en su centro. El tablón a la deriva se convirtió en la Solo Isla aislada en estas aguas."
  },
  AvgDialog_13947_Content_29 = {
    Text = "Ya estás Enredado en un cerco."
  },
  AvgDialog_13947_Content_3 = {
    Text = "El tablón al que tú y Goliath os aferrabais se había convertido en la solo Isla aislada en el mar. Al alzar la vista hacia el Sol ardiente sobre vuestras cabezas, sentiste oleadas de mareo una vez más."
  },
  AvgDialog_13947_Content_30 = {
    Text = "Permítanme presentar con gran pompa — ¡el más valiente Líder en toda la historia Filistea! ¡El poderoso gigante que posee una Voluntad Inquebrantable! El héroe tribal cuya fama sacude los cuatro mares, cuyo Despreciar todo no conoce límites —"
  },
  AvgDialog_13947_Content_31 = {
    Text = "<BigShake:¡El gran Lord Goliath!>"
  },
  AvgDialog_13947_Content_32 = {
    Text = "La luz del sol reflejada en el mar era demasiado intensa. Solo pudiste vislumbrar una silueta oscura de pie en la proa, mirándote desde lo alto."
  },
  AvgDialog_13947_Content_33 = {
    Text = "Nuestros hermanos más nuevos quizás no lo sepan, pero ¿Quién es gran señor sufrió una Lesión grave en un duelo y casi fue capturado, llevando a toda nuestra tribu a una crisis sin precedentes!"
  },
  AvgDialog_13947_Content_34 = {
    Text = "¡La aniquilación inminente Devoró a la mayoría de nuestra gente! ¡Elogio! ¡Mi más querido Lord Goliath!"
  },
  AvgDialog_13947_Content_35 = {
    Text = "Je je... ¿Cómo podría atreverme a llevarme todo el mérito de tan gran logro, Con Glen?"
  },
  AvgDialog_13947_Content_36 = {
    Text = "¿Quién fue el que se escondió detrás de mi trasero y no se atrevió a enviar tropas? ¿Y quién fue el primero en tirar su arma y Gritar mientras corría a casa?"
  },
  AvgDialog_13947_Content_37 = {Text = "¡Tú...!"},
  AvgDialog_13947_Content_38 = {
    Text = "El rostro de Con Glen se puso rojo como un tomate, sus ojos turbios temblando sin cesar, hasta que finalmente su mirada se posó en ti."
  },
  AvgDialog_13947_Content_39 = {
    Text = "Oh, aunque el Líder ha perdido a casi toda su gente, todavía tiene un... seguidor muy adorable."
  },
  AvgDialog_13947_Content_4 = {
    Text = "<Shake:Lo siento, no me encuentro bien... Déjame dormir un poco...>"
  },
  AvgDialog_13947_Content_40 = {
    Text = "La desgracia de los Filisteos — un inútil que ni siquiera puede aguantar un solo golpe de su propia tribu, y aun así quiere seguirte y convertirse en un guerrero..."
  },
  AvgDialog_13947_Content_41 = {
    Text = "Jajajaja...!!"
  },
  AvgDialog_13947_Content_42 = {
    Text = "Goliath levantó la cabeza y te miró con sorpresa entre las estruendosas carcajadas de la multitud."
  },
  AvgDialog_13947_Content_43 = {
    Text = "Pequeño renacuajo, ¿viniste a seguirme por tu propia voluntad?"
  },
  AvgDialog_13947_Content_44 = {
    Text = "<Gray:Eh... por lo que puedo recordar, eso parece ser correcto...>"
  },
  AvgDialog_13947_Content_45 = {
    Text = "Qué conmovedor, ¿no? Solo mencioné casualmente una o dos cosas sobre la bruja, y este pequeño tonto se lo tomó en serio, siguiéndote con entusiasmo..."
  },
  AvgDialog_13947_Content_46 = {
    Text = "No hubo forma de detener al chico, jaja —"
  },
  AvgDialog_13947_Content_47 = {Text = "¡Splash!!"},
  AvgDialog_13947_Content_48 = {
    Text = "Las risas cesaron abruptamente. Un Viento despiadado y feroz Aulló, y una pierna cercenada rodó al instante hasta detenerse ante los ojos de Todos."
  },
  AvgDialog_13947_Content_49 = {
    Text = "AHHH... Mi pierna, ¡¡MI PIERNA!!"
  },
  AvgDialog_13947_Content_5 = {
    Text = "Una túnica apestando a sudor y Sangre fue arrojada sobre tu cabeza, y el hedor te hizo incorporarte de inmediato."
  },
  AvgDialog_13947_Content_50 = {
    Text = "El antiguo señor de los mares se alzó ante Con Glen como una montaña, todo su ser emanando un aura que infundía terror en el corazón."
  },
  AvgDialog_13947_Content_51 = {
    Text = "Desde hace un rato, una mosca no ha dejado de zumbar alrededor de mi oído..."
  },
  AvgDialog_13947_Content_52 = {
    Text = "Goliath limpió tranquilamente las manchas de Sangre de su hoja, luego levantó la cabeza y le dedicó a Con Glen una fría sonrisa."
  },
  AvgDialog_13947_Content_53 = {
    Text = "Con Glen, ¿acaso te hice una maldita pregunta hace un momento?"
  },
  AvgDialog_13947_Content_6 = {
    Text = "*Cof cof*... ¡Urgh!"
  },
  AvgDialog_13947_Content_7 = {
    Text = "Tienes una insolación. Cúbrete la cabeza con esto para bloquear el Sol. No te lo quites."
  },
  AvgDialog_13947_Content_8 = {
    Text = "Como era de esperar de las ropas de mi señor, verdaderamente vigorizantes...\nEntonces, ¿hacia dónde deberíamos dirigirnos ahora? ¿A buscar a la bruja?"
  },
  AvgDialog_13947_Content_9 = {
    Text = "¿Qué mierda de bruja? No me digas que de verdad te creíste sus tonterías."
  },
  AvgDialog_13948_Content_1 = {
    Text = "Melodía Dorada"
  },
  AvgDialog_13948_Content_10 = {
    Text = "La pálida calma del mar se quebró cuando serpientes marinas de un negro purpúreo emergieron de repente, enroscándose con fuerza alrededor de todos en un agarre Entrelazados."
  },
  AvgDialog_13948_Content_11 = {
    Text = "Ugh... ¡¡AAAAAHH!!"
  },
  AvgDialog_13948_Content_12 = {
    Text = "Con un tenue y espeluznante sonido, los cuerpos de las serpientes se transformaron en Cuchillas negras como el azabache que atravesaron limpiamente a sus víctimas."
  },
  AvgDialog_13948_Content_13 = {
    Text = "<Big:Aléjate>... ¿Eh?"
  },
  AvgDialog_13948_Content_15 = {
    Text = "Una suave y gélida sensación provenía de donde la serpiente negra estaba Entrelazados alrededor de tu cuello, y la Herida comenzó a sanar gradualmente."
  },
  AvgDialog_13948_Content_16 = {
    Text = "Mis heridas... ¿se han curado todas?"
  },
  AvgDialog_13948_Content_17 = {
    Text = "Las serpientes negras te abandonaron sin vacilar, y luego se enroscaron con fuerza alrededor de Con Glen a una velocidad cegadora."
  },
  AvgDialog_13948_Content_18 = {
    Text = "Correr, la bruja vie... ne..."
  },
  AvgDialog_13948_Content_19 = {
    Text = "Serpientes negras como la noche se deslizaron desde los ojos y la boca de Con Glen. Se desplomó sin fuerzas antes de poder siquiera pronunciar una sola frase completa."
  },
  AvgDialog_13948_Content_2 = {
    Text = "Suspira por El Apóstol del Mar.\nSuspira por nuestra luz, nuestra esperanza.\n\nPor el Destino de ser Exiliados al océano, gemimos, nos lamentamos, lloramos hasta que no quedan lágrimas."
  },
  AvgDialog_13948_Content_20 = {
    Text = "Momentos después, incontables cadáveres destrozados flotaron hasta la superficie del mar."
  },
  AvgDialog_13948_Content_21 = {
    Text = "Fue una masacre silenciosa."
  },
  AvgDialog_13948_Content_22 = {
    Text = "<Gray:¿Ya terminó, así sin más? Impresionante—como era de esperar de Miryam.>"
  },
  AvgDialog_13948_Content_23 = {
    Text = "¿Nos ayudaste... Quién eres?"
  },
  AvgDialog_13948_Content_24 = {
    Text = "La mujer que llevaba un velo negro no dijo nada. Permanecía erguida en la proa de su barco, con Solo un velo de espesa niebla entre vosotros."
  },
  AvgDialog_13948_Content_25 = {
    Text = "Parecía tan cerca, y sin embargo, a mundos de distancia."
  },
  AvgDialog_13948_Content_26 = {
    Text = "La mujer contempló al atónito Goliath, con una tenue sonrisa curvándose en la comisura de sus labios. Extendió una mano, señalando hacia la distancia —una invitación silenciosa."
  },
  AvgDialog_13948_Content_27 = {
    Text = "Entonces giró su barco y se alejó pausadamente."
  },
  AvgDialog_13948_Content_28 = {
    Text = "Espera, no te vayas... <Big:¡No te vayas!>"
  },
  AvgDialog_13948_Content_29 = {
    Text = "La niebla se disipó y un rayo de luz atravesó las nubes. Las olas resplandecían con un tono dorado."
  },
  AvgDialog_13948_Content_3 = {
    Text = "El Campo de visión se oscureció de repente mientras la luz cegadora del sol se desvanecía gradualmente, y una niebla Pegajosa envolvió todo el mar."
  },
  AvgDialog_13948_Content_30 = {
    Text = "Parpadeaste, y el horizonte ya estaba vacío."
  },
  AvgDialog_13948_Content_31 = {
    Text = "El Viento y las olas se calmaron gradualmente. Tú y Goliath os aferrasteis al único tablón intacto, jadeando en busca de aire."
  },
  AvgDialog_13948_Content_32 = {
    Text = "El otrora azul mar hacía tiempo que se había teñido de rojo con Sangre. Flotabais sobre él como lentejas de agua sin raíz."
  },
  AvgDialog_13948_Content_33 = {
    Text = "Así que al final no conseguimos un barco... Ahora ni siquiera sé cómo se supone que vamos a volver a casa."
  },
  AvgDialog_13948_Content_34 = {
    Text = "No vamos a volver a casa."
  },
  AvgDialog_13948_Content_35 = {
    Text = "Goliath apoyó una pierna y miró ausente en la dirección en la que Miryam se había marchado."
  },
  AvgDialog_13948_Content_36 = {
    Text = "Ya me he decidido. Voy a encontrar a esa bruja. ¿Vendrás conmigo?"
  },
  AvgDialog_13948_Content_37 = {
    Text = "Ejem, \"Solo un necio confiaría su vida a otra persona.\""
  },
  AvgDialog_13948_Content_38 = {
    Text = "Bajaste la voz deliberadamente, imitando el tono anterior de Goliath mientras le devolvías sus propias palabras."
  },
  AvgDialog_13948_Content_39 = {
    Text = "Hmph, eso es porque la Apuesta no era lo bastante alta. Esa clase de Fortaleza que puede aplastarlo todo en un instante — nunca había visto nada igual."
  },
  AvgDialog_13948_Content_4 = {
    Text = [[
Oh, por favor, proteged a los afligidos.
Posad vuestra mirada misericordiosa sobre nosotros...]]
  },
  AvgDialog_13948_Content_40 = {
    Text = "Además, Ella acaba de ayudarnos, e incluso me extendió una invitación..."
  },
  AvgDialog_13948_Content_41 = {
    Text = "¡Pero y si... es una trampa?"
  },
  AvgDialog_13948_Content_42 = {
    Text = "Una trampa..."
  },
  AvgDialog_13948_Content_43 = {
    Text = "¿Aún recuerdas la pregunta que me hiciste antes?"
  },
  AvgDialog_13948_Content_44 = {
    Text = "...Lo que importa es que gracias a vos, mi señor, ambos seguimos con vida."
  },
  AvgDialog_13948_Content_45 = {
    Text = "¿Por qué crees que es así?"
  },
  AvgDialog_13948_Content_46 = {
    Text = "Ahora sé la respuesta."
  },
  AvgDialog_13948_Content_47 = {
    Text = "?Cuál es la respuesta?"
  },
  AvgDialog_13948_Content_48 = {
    Text = "Una bandada de petreles pasó volando de repente. Sus Alas blancas batientes eran como nubes elevándose, extendiéndose libremente en el Viento marino."
  },
  AvgDialog_13948_Content_49 = {
    Text = "Goliath no se inmutó por la bandada de aves. Miraba fijamente hacia adelante, sus ojos parpadeando con la luz de la Elación."
  },
  AvgDialog_13948_Content_5 = {
    Text = "Una canción antigua, cargada de Deceit, flotaba en el aire. La silueta de la mujer en la proa aparecía y desaparecía, como un espectro acechando entre la niebla."
  },
  AvgDialog_13948_Content_50 = {
    Text = "Porque soy Goliat."
  },
  AvgDialog_13948_Content_51 = {
    Text = "El Líder con el reinado más largo en la historia Filistea, el poderoso gigante de Voluntad Inquebrantable, el héroe tribal cuyo nombre infunde asombro en los cuatro mares — el Gigante Goliath."
  },
  AvgDialog_13948_Content_52 = {
    Text = "Incluso con Solo un Seguidor, Solo que quede una última oportunidad, puedo levantarme de nuevo."
  },
  AvgDialog_13948_Content_53 = {
    Text = "Esa bruja es mi última oportunidad. Solo Ella puede otorgarme Fortaleza absoluta."
  },
  AvgDialog_13948_Content_54 = {
    Text = "Aunque sea una trampa, iré."
  },
  AvgDialog_13948_Content_55 = {
    Text = "Entonces, ?por qué me salvaste? Un \"desperdicio\" como yo probablemente no pueda ayudarte en nada..."
  },
  AvgDialog_13948_Content_56 = {
    Text = "Enfatizaste deliberadamente cierta palabra, haciendo que Goliath estallara en una carcajada sincera."
  },
  AvgDialog_13948_Content_57 = {
    Text = "La luz del Sol atravesó las nubes, proyectando un manto de luz dorada. Mechones Desordenados de cabello Danzaban suavemente bajo el cielo azul."
  },
  AvgDialog_13948_Content_58 = {
    Text = "No hay forma de que un comandante sin tropas pueda lograr algo en este mundo."
  },
  AvgDialog_13948_Content_59 = {
    Text = "Pequeño, no eres un desperdicio.\nEres el único Seguidor del Gigante Goliath, y nadie podrá reemplazarte jamás."
  },
  AvgDialog_13948_Content_6 = {
    Text = "¿Eh? ¿Alguien está cantando?"
  },
  AvgDialog_13948_Content_60 = {
    Text = "Una vez que logre mis grandes ambiciones, ?como mínimo te haré jefe tribal!"
  },
  AvgDialog_13948_Content_61 = {
    Text = "...Eso no será necesario."
  },
  AvgDialog_13948_Content_62 = {
    Text = "El cielo se había oscurecido sin que nadie lo notara. El resplandor vespertino del crepúsculo fluía por el horizonte como ríos de Dorado y brillante."
  },
  AvgDialog_13948_Content_63 = {
    Text = "!Oye, ?sabes qué? La razón por la que los héroes pueden convertirse en héroes es porque tienen gente como nosotros para hacerlos lucir bien."
  },
  AvgDialog_13948_Content_64 = {
    Text = "<Small:Así que yo también soy bastante importante, ?entiendes...>"
  },
  AvgDialog_13948_Content_65 = {
    Text = "<Small:Mm...>"
  },
  AvgDialog_13948_Content_66 = {
    Text = "Palabras fragmentadas esparcidas como semillas de diente de león arrastradas por la brisa marina, llevadas a algún lugar muy, muy lejano."
  },
  AvgDialog_13948_Content_67 = {
    Text = "Goliath y tú os sentasteis sobre las finas tablas de madera, y desde la distancia, parecíais diminutas hojas a la deriva en un mar dorado."
  },
  AvgDialog_13948_Content_68 = {
    Text = "Nadie sabía hacia dónde navegaríais finalmente."
  },
  AvgDialog_13948_Content_7 = {
    Text = "<Shake:La bruja... ¡¡es esa bruja!!>"
  },
  AvgDialog_13948_Content_8 = {
    Text = "Cómo es posible... ¿Acaso esa leyenda es real...?"
  },
  AvgDialog_13948_Content_9 = {
    Text = [[
<Red:Piedad.
         Piedad.
                  Piedad...>]]
  },
  AvgDialog_139656_Content_1 = {Text = "Adiós"},
  AvgDialog_139656_Content_10 = {
    Text = "¿Tal como soy ahora...? Hmm. Probablemente sea mejor que no lo hagas."
  },
  AvgDialog_139656_Content_11 = {
    Text = "Después del vínculo de hace un momento... muchas cosas cambiaron."
  },
  AvgDialog_139656_Content_12 = {
    Text = "Sobre eso... tuve un sueño."
  },
  AvgDialog_139656_Content_13 = {
    Text = "En el sueño, Ramona se había convertido en..."
  },
  AvgDialog_139656_Content_14 = {
    Text = "No importa cuántas veces le hayas dado vueltas en tu mente, la imagen sigue resistiéndose a las palabras. Tu cuerpo retrocede antes de que tus pensamientos puedan alcanzarlo."
  },
  AvgDialog_139656_Content_15 = {
    Text = "Lo sé. Estabas aterrorizado. Asqueado."
  },
  AvgDialog_139656_Content_16 = {
    Text = "El Dominio es parte de mi Paisaje Mental, así que pude sentirlo."
  },
  AvgDialog_139656_Content_17 = {
    Text = "Lo siento de verdad, por lo que te hice pasar."
  },
  AvgDialog_139656_Content_18 = {
    Text = "No, eso no es lo que quería decir."
  },
  AvgDialog_139656_Content_19 = {
    Text = "Quiero decir... en aquel momento, no sabía si aquella cosa envuelta en carne era realmente ella."
  },
  AvgDialog_139656_Content_2 = {
    Text = "El mundo ha vuelto a ser \"normal\". Normal según los estándares de tu mundo."
  },
  AvgDialog_139656_Content_20 = {
    Text = "Pero ahora lo sé. Esa era la Ramona que conozco. Así que ya no tengo miedo."
  },
  AvgDialog_139656_Content_21 = {
    Text = "Las palabras te dan firmeza. Tu voz se vuelve gradualmente más segura."
  },
  AvgDialog_139656_Content_22 = {
    Text = "La apariencia no importa. Lo que importa es solo el vínculo entre mí y mis Cuerpos Despertados, los que fluyen a través de los Núcleos de plata."
  },
  AvgDialog_139656_Content_23 = {
    Text = "He visto demasiadas cosas como estas para que las apariencias por sí solas me perturben."
  },
  AvgDialog_139656_Content_24 = {
    Text = "He visto un corazón de oro puro nacer del fango más inmundo del mundo;"
  },
  AvgDialog_139656_Content_25 = {
    Text = "He visto amor —verdadero, tierno amor— echar raíces en el más febril deseo de procreación. Así que—"
  },
  AvgDialog_139656_Content_26 = {
    Text = "Todo queda en silencio."
  },
  AvgDialog_139656_Content_27 = {
    Text = "Tras una larga pausa, una sonrisa se propaga desde el otro lado del vínculo —serena y apacible."
  },
  AvgDialog_139656_Content_28 = {
    Text = "...Me alegro mucho de haberte conocido."
  },
  AvgDialog_139656_Content_29 = {
    Text = "…Y entonces, en el Dominio que dudaba, volviste a caer en aquel Sueño."
  },
  AvgDialog_139656_Content_3 = {
    Text = "Arena amarilla sofocada en lodo de disolución se extiende en una expansión interminable y aullante."
  },
  AvgDialog_139656_Content_30 = {
    Text = "Wｸe&Lｨcｴ0ﾋmEｺ tｸO3 M缮yTｱhAﾉgｲ Uｸn巛iV龠ｻeRｦsItｭYｲ,ｲ %player%."
  },
  AvgDialog_139656_Content_31 = {
    Text = "El sonido viscoso y gutural se arrastra fuera de una masa de carne putrefacta y retorcida."
  },
  AvgDialog_139656_Content_32 = {
    Text = "En un mundo cubierto de sangre y lodo, Ramona—resbaladiza por el fluido—extiende la mano. Sus dedos apenas rozan tu meñique."
  },
  AvgDialog_139656_Content_33 = {
    Text = "Nunca olvidaré este momento."
  },
  AvgDialog_139656_Content_34 = {
    Text = "Susurras suavemente en tu corazón."
  },
  AvgDialog_139656_Content_35 = {
    Text = "Mｸa&Yｨ tｴHeﾋ Sｺi3LvEｸrｱ Kﾉeｲyｸ l巛iGｻhｦTｭ yｲOｲuRｸ pAtH."
  },
  AvgDialog_139656_Content_36 = {
    Text = "En medio de la carne y la desolación, agarras firmemente la mano de Ramona, mirando directamente a sus ojos vacíos y su forma manchada de sangre."
  },
  AvgDialog_139656_Content_37 = {
    Text = "Que la Llave de Plata nos guíe"
  },
  AvgDialog_139656_Content_38 = {
    Text = "El resplandor de la Llave de plata se difunde por todo el mundo."
  },
  AvgDialog_139656_Content_39 = {
    Text = "Una figura de blanco puro emerge en tu mente. Es Saya, sonriendo."
  },
  AvgDialog_139656_Content_4 = {
    Text = "Solo la pequeña cabaña en el bosque está empapada del color crudo y carnoso de las entrañas. Y a través del vínculo, sientes a Saya en su interior. Sabes que su final está a apenas unos latidos de distancia."
  },
  AvgDialog_139656_Content_40 = {
    Text = "Algo parecido a hermosas alas aletea en el viento."
  },
  AvgDialog_139656_Content_41 = {
    Text = "Los dientes de león alzan el vuelo, dispersándose en el cielo azul."
  },
  AvgDialog_139656_Content_42 = {
    Text = "En el momento en que cada semilla se libera del tallo, el mundo brumoso y onírico retrocede hacia la realidad."
  },
  AvgDialog_139656_Content_43 = {
    Text = "Despiertas del sueño, y todas las cosas revelan su verdadera forma."
  },
  AvgDialog_139656_Content_44 = {Text = "Gracias..."},
  AvgDialog_139656_Content_45 = {
    Text = "Te parece oír un susurro de despedida junto a tu oído. ¿Es una ilusión?"
  },
  AvgDialog_139656_Content_46 = {
    Text = "En algún momento, un Núcleo de plata aparece en tu palma."
  },
  AvgDialog_139656_Content_47 = {
    Text = "Es el mismo núcleo que Tinct encontró una vez, aquel imbuido de un anhelo eterno."
  },
  AvgDialog_139656_Content_48 = {
    Text = "Cuando llegue el momento, podrás usarlo—para despertar su eterno \"amor\"."
  },
  AvgDialog_139656_Content_49 = {
    Text = "—El amor de Saya... el Cuerpo Despertado."
  },
  AvgDialog_139656_Content_5 = {
    Text = "Creo que nuestras almas están vinculadas ahora. Y con eso... la barrera desaparecerá por completo."
  },
  AvgDialog_139656_Content_6 = {
    Text = "Poder sentirme así en mis últimos momentos... Estoy satisfecha. ...Gracias."
  },
  AvgDialog_139656_Content_7 = {
    Text = "Ahora—abandona este lugar. Camina hacia la arena. En el borde de ese mar de dunas, te reunirás con tu pasado."
  },
  AvgDialog_139656_Content_8 = {
    Text = "Está bien. Incluso cuando ya no esté en este mundo, nuestra consciencia permanecerá conectada a través de los Núcleos de plata."
  },
  AvgDialog_139656_Content_9 = {
    Text = "Antes del final... ¿me dejarás ver tu verdadera forma?"
  },
  AvgDialog_139657_Content_1 = {
    Text = "\"Propósito\""
  },
  AvgDialog_139657_Content_10 = {
    Text = "Algo se acerca. Puedo sentirlo en los bordes..."
  },
  AvgDialog_139657_Content_11 = {
    Text = "Saya frunce el ceño, con el rostro tenso y pálido."
  },
  AvgDialog_139657_Content_12 = {
    Text = "Arrancas la carne de su muñeca y la ayudas a ponerse de pie."
  },
  AvgDialog_139657_Content_13 = {
    Text = "Quiero ver el campo de dientes de león. ¿Caminarías conmigo un rato?"
  },
  AvgDialog_139657_Content_14 = {
    Text = "Deberías estar descansando..."
  },
  AvgDialog_139657_Content_15 = {
    Text = "Estoy bien. De verdad..."
  },
  AvgDialog_139657_Content_16 = {
    Text = "Saya empuja suavemente la puerta de la cabaña. El mundo exterior inunda tu visión."
  },
  AvgDialog_139657_Content_17 = {
    Text = "El color del campo ha cambiado."
  },
  AvgDialog_139657_Content_18 = {
    Text = "El exuberante verdor de ayer está ahora cubierto por una sombra profunda rojo–negra. Las escasas briznas no pueden mantenerse en pie, deformadas y consumidas por la decadencia."
  },
  AvgDialog_139657_Content_19 = {
    Text = "Es la <Red:Disolución>...!"
  },
  AvgDialog_139657_Content_2 = {
    Text = "Sueños grotescos vienen hacia ti como una marea."
  },
  AvgDialog_139657_Content_20 = {
    Text = "¿Te ves... triste?"
  },
  AvgDialog_139657_Content_21 = {
    Text = "Ayer esto era un hermoso campo de dientes de león."
  },
  AvgDialog_139657_Content_22 = {
    Text = "Hoy la Disolución lo ha encontrado, lo ha tragado entero. En unos días, habrá desaparecido por completo."
  },
  AvgDialog_139657_Content_23 = {
    Text = "Y con el tiempo suficiente, incluso el recuerdo se desvanecerá—incluso de los tuyos."
  },
  AvgDialog_139657_Content_24 = {
    Text = "¿Eso no te aflige?"
  },
  AvgDialog_139657_Content_25 = {
    Text = "Hmm, ¿así es como te sientes...?"
  },
  AvgDialog_139657_Content_26 = {
    Text = "¿Tú lo ves de otra manera?"
  },
  AvgDialog_139657_Content_27 = {
    Text = "Mm. Siempre hay tantas cosas diferentes en este mundo..."
  },
  AvgDialog_139657_Content_28 = {
    Text = "Y los más fuertes arrebatan y saquean a los más débiles."
  },
  AvgDialog_139657_Content_29 = {
    Text = "Así son las cosas, ¿no?"
  },
  AvgDialog_139657_Content_3 = {
    Text = "La figura de Ramona parpadea intermitentemente—su voz desgarrada por las costuras, raspando como aire forzado a través de un fuelle roto."
  },
  AvgDialog_139657_Content_30 = {
    Text = "No. Precisamente por eso existe Misaq."
  },
  AvgDialog_139657_Content_31 = {
    Text = "Nos interponemos entre la Disolución y todo lo que pretende engullir—vidas y recuerdos que quizá no sean poderosos, pero que aún portan su propia luz."
  },
  AvgDialog_139657_Content_32 = {
    Text = "Y eso te incluye a ti, Saya."
  },
  AvgDialog_139657_Content_33 = {Text = "...Ya veo."},
  AvgDialog_139657_Content_34 = {
    Text = "Lo murmura para sí misma."
  },
  AvgDialog_139657_Content_35 = {
    Text = "En ese caso... quizá tengas razón..."
  },
  AvgDialog_139657_Content_36 = {
    Text = "Avanzas por el paisaje repetitivo durante lo que parece una eternidad, hasta que un atisbo de algo diferente finalmente rompe la monotonía."
  },
  AvgDialog_139657_Content_37 = {
    Text = "¿Otro campo de dientes de león...?"
  },
  AvgDialog_139657_Content_38 = {
    Text = "Saya tiene la cabeza agachada, respirando suavemente. No puedes verle el rostro."
  },
  AvgDialog_139657_Content_39 = {
    Text = "Esta es... la cabaña de la que partimos. Mira allí."
  },
  AvgDialog_139657_Content_4 = {
    Text = "Despiertas sobresaltado."
  },
  AvgDialog_139657_Content_40 = {
    Text = "Señalas el rincón de la habitación—el trozo de carne que arrancaste de la muñeca de Saya y tiraste a un lado esta mañana."
  },
  AvgDialog_139657_Content_41 = {
    Text = "...Hemos estado caminando en círculos."
  },
  AvgDialog_139657_Content_42 = {
    Text = "No hay nada en este Dominio salvo desolación."
  },
  AvgDialog_139657_Content_43 = {
    Text = "No importa. Podemos... descansar un rato."
  },
  AvgDialog_139657_Content_44 = {
    Text = "Sonríe como si no fuera nada. Pero su voz se deshilacha en los bordes, temblando ligeramente, de una forma que no logra contener del todo."
  },
  AvgDialog_139657_Content_45 = {
    Text = "Saya, tu cuerpo..."
  },
  AvgDialog_139657_Content_46 = {
    Text = "Solo estoy un poco cansada..."
  },
  AvgDialog_139657_Content_47 = {
    Text = "Justo ante tus ojos, sus rodillas ceden—cae desplomada, como si todo lo que la sostenía simplemente se hubiera rendido."
  },
  AvgDialog_139657_Content_48 = {Text = "¡Saya!"},
  AvgDialog_139657_Content_49 = {
    Text = "En lo profundo de la noche, Saya arde de fiebre. Siguiendo sus indicaciones, enciendes un fuego con materiales que no sabrías nombrar ni aunque lo intentaras."
  },
  AvgDialog_139657_Content_5 = {
    Text = "*Tos, tos...*"
  },
  AvgDialog_139657_Content_50 = {
    Text = "Si hubiera sabido que estabas tan enferma, jamás te habría dejado caminar todo el día..."
  },
  AvgDialog_139657_Content_51 = {
    Text = "No pasa nada. No creo que esté enferma por haber caminado.\nEn fin... ¿podemos hablar un rato?"
  },
  AvgDialog_139657_Content_52 = {
    Text = "Por supuesto. ¿De qué te gustaría hablar?"
  },
  AvgDialog_139657_Content_53 = {
    Text = "Esta mañana dijiste que tú y Misaq queréis luchar contra la Disolución. Para proteger a los demás. Para protegerme a mí."
  },
  AvgDialog_139657_Content_54 = {
    Text = "¿Lo decías en serio?"
  },
  AvgDialog_139657_Content_55 = {
    Text = "Cada palabra. Lo juré el día que me fue concedida la Llave de plata."
  },
  AvgDialog_139657_Content_56 = {
    Text = "Tu voz sale más firme de lo que esperabas. En el instante en que las palabras abandonan tus labios, la ceremonia aflora en tu mente—"
  },
  AvgDialog_139657_Content_57 = {
    Text = "El peso fresco de la Llave de plata se asienta en tu palma. Las miradas solemnes de la multitud. La ardiente determinación en tu corazón cuando cerraste los dedos a su alrededor."
  },
  AvgDialog_139657_Content_58 = {
    Text = "Saya guarda silencio un momento. La luz del fuego baña la suave curva de su silueta con un cálido resplandor ambarino."
  },
  AvgDialog_139657_Content_59 = {
    Text = "Entonces... si un día perdieras tu poder como Guardián... si te convirtieras en una persona corriente,"
  },
  AvgDialog_139657_Content_6 = {
    Text = "Saya está apoyada contra la puerta de la cabaña, tosiendo suavemente."
  },
  AvgDialog_139657_Content_60 = {
    Text = "y ya no pudieras cargar con el deber contra la Disolución... ¿qué harías?"
  },
  AvgDialog_139657_Content_61 = {
    Text = "Bueno, ya he pensado en eso."
  },
  AvgDialog_139657_Content_62 = {
    Text = "Te recuestas hacia atrás, apoyando las manos en la hierba tras de ti, alzando el rostro hacia las estrellas."
  },
  AvgDialog_139657_Content_63 = {
    Text = "Pasaría el resto de mi vida con las personas que amo. En calma. Con normalidad."
  },
  AvgDialog_139657_Content_64 = {
    Text = "Cuando seamos viejos y canosos, demasiado cansados para seguir corriendo, nos sentaríamos alrededor del hogar y repetiríamos las mismas tontas aventuras de juventud hasta que todos se las supieran de memoria."
  },
  AvgDialog_139657_Content_65 = {
    Text = "Ramona seguiría corrigiendo cada nombre que el Señor Dexter pronunciara mal. William tendría esa misma expresión perfectamente serena en el rostro, sosteniendo un libro como si leyera mientras sus oídos permanecen atentos..."
  },
  AvgDialog_139657_Content_66 = {
    Text = "La profesora Czort seguiría aferrada a su vodka, arrastrando a todos a cantar en cuanto agarra el ritmo."
  },
  AvgDialog_139657_Content_67 = {
    Text = "Giras la cabeza. Saya te observa en silencio. La luz del fuego parpadea en sus ojos como diminutas estrellas atrapadas."
  },
  AvgDialog_139657_Content_68 = {
    Text = "Eso suena maravilloso."
  },
  AvgDialog_139657_Content_69 = {Text = "Pero..."},
  AvgDialog_139657_Content_7 = {
    Text = "¡Saya! ¡Tu mano!"
  },
  AvgDialog_139657_Content_70 = {
    Text = "Su voz se quiebra. Aparta la mirada, sus ojos se nublan, fijos en el vacío de un rincón oscuro."
  },
  AvgDialog_139657_Content_71 = {
    Text = "Si te separaran de ellos... si no quedara nadie a tu lado... ¿qué harías entonces?"
  },
  AvgDialog_139657_Content_72 = {
    Text = "¿Se fueron? ¿O nunca existieron para empezar?"
  },
  AvgDialog_139657_Content_73 = {
    Text = "Si... aún tuvieras los recuerdos. De haberlos conocido, del tiempo que pasaron juntos..."
  },
  AvgDialog_139657_Content_74 = {
    Text = "Pero ha pasado demasiado tiempo. Los recuerdos están hechos pedazos. Y ni siquiera sabes si son reales..."
  },
  AvgDialog_139657_Content_75 = {
    Text = "Mientras pueda recordar, iré a buscarlos."
  },
  AvgDialog_139657_Content_76 = {
    Text = "Estén donde estén. Cueste lo que cueste."
  },
  AvgDialog_139657_Content_77 = {
    Text = "No hay ni un atisbo de vacilación en tu mirada."
  },
  AvgDialog_139657_Content_78 = {
    Text = "Si... quiero decir, ¿y si no puedes encontrarlos?"
  },
  AvgDialog_139657_Content_79 = {
    Text = "Seguiría buscando de todas formas... por cada camino, sobre cada montaña, a través de cada mar..."
  },
  AvgDialog_139657_Content_8 = {
    Text = "Carne entretejida con lodo negro se ha abierto paso entre las rendijas de la puerta y se ha enrollado alrededor de su muñeca."
  },
  AvgDialog_139657_Content_80 = {
    Text = "Hasta que la búsqueda misma me acompañara hasta el último de mis días."
  },
  AvgDialog_139657_Content_81 = {
    Text = "Y cuando llegara ese último momento, cuando mis ojos finalmente se cerraran, creo que me sentiría en paz."
  },
  AvgDialog_139657_Content_82 = {
    Text = "Porque habría vivido con recuerdos dignos de guardar, y un destino al que estaba destinado a llegar, sin importar el precio."
  },
  AvgDialog_139657_Content_83 = {
    Text = "La búsqueda en sí misma es el significado."
  },
  AvgDialog_139657_Content_84 = {
    Text = "El silencio cae mientras tus palabras se asientan. Solo queda el suave susurro de los dientes de león en la brisa."
  },
  AvgDialog_139657_Content_85 = {Text = "...¿Saya?"},
  AvgDialog_139657_Content_86 = {
    Text = "Saya ha cerrado los ojos. Su rostro está pálido, casi translúcido. Tu corazón se encoge."
  },
  AvgDialog_139657_Content_87 = {Text = "Saya..."},
  AvgDialog_139657_Content_88 = {
    Text = "Te inclinas hacia ella—y descubres que su respiración es lenta y acompasada, su pecho subiendo y bajando en el más tenue de los ritmos, como la más pequeña ondulación en un lago en calma."
  },
  AvgDialog_139657_Content_89 = {
    Text = "Hmm, solo estás dormida..."
  },
  AvgDialog_139657_Content_9 = {
    Text = "Cambios como estos... no son lo que me preocupa."
  },
  AvgDialog_139657_Content_90 = {
    Text = "Yo... también estoy un poco cansado..."
  },
  AvgDialog_139657_Content_91 = {
    Text = "El alivio te golpea de repente, y con él, el agotamiento del día y la tensión visual del paisaje infernal finalmente te vencen."
  },
  AvgDialog_139657_Content_92 = {
    Text = "Antes de que llegue el final, esta noche también se escurre silenciosamente entre tus dedos."
  },
  AvgDialog_139658_Content_1 = {
    Text = "Después de la Lluvia"
  },
  AvgDialog_139658_Content_10 = {
    Text = "Qué agradable... sentir el sol."
  },
  AvgDialog_139658_Content_11 = {
    Text = "Ella sonríe, extendiendo la mano hacia donde cae la luz, como una planta inclinándose hacia el sol."
  },
  AvgDialog_139658_Content_12 = {
    Text = "¿Me ayudas a salir?"
  },
  AvgDialog_139658_Content_13 = {
    Text = "La guías para que se siente contra la pared de la cabaña. Incluso este corto trayecto la deja con una respiración superficial y entrecortada."
  },
  AvgDialog_139658_Content_14 = {
    Text = "Saya, tu cuerpo..."
  },
  AvgDialog_139658_Content_15 = {
    Text = "No te preocupes. Creo que mi tiempo casi se ha acabado."
  },
  AvgDialog_139658_Content_16 = {
    Text = "Tú también puedes sentirlo, ¿verdad? La barrera que bloquea nuestro vínculo... se está desmoronando."
  },
  AvgDialog_139658_Content_17 = {
    Text = "No pasará mucho antes de que colapse por completo.\nCuando lo haga... deberíamos poder establecer el vínculo del que hablaste."
  },
  AvgDialog_139658_Content_18 = {Text = "Pero..."},
  AvgDialog_139658_Content_19 = {
    Text = "Una vez que se forme el vínculo, Saya podría desaparecer. Esa barrera es su último escudo, y solo se está debilitando porque sus fuerzas están fallando."
  },
  AvgDialog_139658_Content_2 = {
    Text = "Cuando despiertas, la luz ha cambiado."
  },
  AvgDialog_139658_Content_20 = {
    Text = "Por favor, no te contengas. Tenerte aquí conmigo, poder hablar así... me hace verdaderamente feliz."
  },
  AvgDialog_139658_Content_21 = {
    Text = "Entrecierra los ojos ante la luz, ofreciendo una sonrisa genuina pero frágil. Apenas puedes soportar mirarla, pero te obligas a grabar cada detalle en tu memoria."
  },
  AvgDialog_139658_Content_22 = {
    Text = "Me quedaré contigo. Hasta el final."
  },
  AvgDialog_139658_Content_23 = {
    Text = "Vamos, no pongas esa cara tan seria. Sigamos donde lo dejamos ayer."
  },
  AvgDialog_139658_Content_24 = {
    Text = "Dijiste que incluso sin tu poder, incluso sin nadie a tu lado, seguirías adelante."
  },
  AvgDialog_139658_Content_25 = {
    Text = "Quiero saber por qué."
  },
  AvgDialog_139658_Content_26 = {
    Text = "¿Por qué? La luz del sol tras la lluvia es tan intensa que te escuecen los ojos con lágrimas contenidas."
  },
  AvgDialog_139658_Content_27 = {
    Text = "Tomas una respiración lenta y profunda."
  },
  AvgDialog_139658_Content_28 = {
    Text = "Porque amo a Ramona. Amo a todos en la Universidad de Misag.\nY sé —con certeza— que ellos también me aman."
  },
  AvgDialog_139658_Content_29 = {
    Text = "Pero estáis tan lejos. No podéis tocaros. No podéis confirmar lo que siente el otro."
  },
  AvgDialog_139658_Content_3 = {
    Text = "El aire húmedo trae un aroma puro, lavado. Lo que se filtra por las rendijas de la puerta ya no es el viento, sino un rayo de luz silencioso."
  },
  AvgDialog_139658_Content_30 = {
    Text = "Y en un mundo donde existe algo como la Disolución, ¿cómo puedes estar seguro de que las personas que extrañas no te han olvidado ya?"
  },
  AvgDialog_139658_Content_31 = {
    Text = "Su voz es suave, casi como un sueño murmurado al borde del dormir."
  },
  AvgDialog_139658_Content_32 = {
    Text = "La Disolución puede borrar la presencia, pero los Núcleos de Plata nos unen a Ramona y a mí a través del mar del subconsciente."
  },
  AvgDialog_139658_Content_33 = {
    Text = "Miras hacia la distancia. El horizonte tras la lluvia es increíblemente nítido. El viento abre una brecha entre las nubes y un pilar de luz dorada se derrama a través de ella, golpeando la cresta lejana."
  },
  AvgDialog_139658_Content_34 = {
    Text = "Puedo sentir su presencia. Incluso ahora, incluso dispersos en mundos diferentes... eso no ha cambiado."
  },
  AvgDialog_139658_Content_35 = {Text = "Además..."},
  AvgDialog_139658_Content_36 = {Text = "¿Hm?"},
  AvgDialog_139658_Content_37 = {
    Text = "Inclina ligeramente la cabeza."
  },
  AvgDialog_139658_Content_38 = {
    Text = "Los verdaderos amantes no necesitan estar uno al lado del otro para sentir su vínculo... ni para confirmar su amor."
  },
  AvgDialog_139658_Content_39 = {
    Text = "No importa cuántas veces el mundo termine y recomience, siempre encontraré a Ramona. Y ella tomará la misma decisión."
  },
  AvgDialog_139658_Content_4 = {
    Text = "...Hay tanto silencio afuera."
  },
  AvgDialog_139658_Content_40 = {
    Text = "Simplemente lo sé. Los pensamientos y sentimientos que compartimos en el mar de la consciencia... jamás serán cortados."
  },
  AvgDialog_139658_Content_41 = {
    Text = "Saya permanece en silencio durante un largo rato. El viento lavado por la lluvia se cuela en la cabaña, rozando su mejilla exangüe."
  },
  AvgDialog_139658_Content_42 = {
    Text = "Entonces sonríe."
  },
  AvgDialog_139658_Content_43 = {
    Text = "Una confianza tan feroz, tan inquebrantable... Un amor tan grande..."
  },
  AvgDialog_139658_Content_44 = {
    Text = "Cuando pronuncia la palabra —amor— no hay envidia en su voz. Ni tristeza. Ni rastro de anhelo."
  },
  AvgDialog_139658_Content_45 = {
    Text = "Solo una profunda ternura."
  },
  AvgDialog_139658_Content_46 = {
    Text = "Como una viajera que ha caminado sola a través de una larga noche invernal y al fin vislumbra la primera luz del alba en el lejano borde del horizonte —quizá nunca la alcance. Pero saber que esa luz existe es suficiente."
  },
  AvgDialog_139658_Content_47 = {
    Text = "Saya sonríe, perdida en un ensueño."
  },
  AvgDialog_139658_Content_48 = {
    Text = "Entonces extiende la mano hacia ti."
  },
  AvgDialog_139658_Content_49 = {
    Text = "...Toma mi mano."
  },
  AvgDialog_139658_Content_5 = {
    Text = "La lluvia... ¿ha parado?"
  },
  AvgDialog_139658_Content_50 = {
    Text = "Su mano es pálida, esbelta y tiembla ligeramente. No puede verte, y sin embargo se extiende infaliblemente en tu dirección—"
  },
  AvgDialog_139658_Content_51 = {
    Text = "como guiada por algo más antiguo que la vista, más profundo que el lenguaje."
  },
  AvgDialog_139658_Content_52 = {
    Text = "Extiendes la mano y tomas la suya."
  },
  AvgDialog_139658_Content_53 = {
    Text = "Y en el instante en que sus palmas se encuentran—"
  },
  AvgDialog_139658_Content_54 = {
    Text = "Un dolor agudo estalla detrás de tus ojos."
  },
  AvgDialog_139658_Content_55 = {
    Text = "Algo mucho más intenso que eso —abrasador, incandescente— se clava como un rayo a través de tu cráneo, golpeando directamente el núcleo más profundo de tu mente."
  },
  AvgDialog_139658_Content_56 = {
    Text = "Tu visión se tambalea violentamente."
  },
  AvgDialog_139658_Content_57 = {
    Text = "Ves dientes de león húmedos reluciendo bajo la luz del sol. El perfil pálido y sereno de Saya. La sonrisa curvándose en sus labios agrietados—"
  },
  AvgDialog_139658_Content_58 = {
    Text = "Y entonces todo se quiebra en un universo de carne. El cielo se tiñe de rojo sangre. La tierra se tiñe de rojo sangre. Incluso la Saya justo frente a ti—"
  },
  AvgDialog_139658_Content_59 = {Text = "No—"},
  AvgDialog_139658_Content_6 = {
    Text = "Saya mira hacia la ventana, con la mirada nublada y desenfocada."
  },
  AvgDialog_139658_Content_60 = {
    Text = "Dos mundos destellan, se superponen y se fusionan ante tu vista. Dos ríos que nunca debieron encontrarse colisionan violentamente en una confluencia imposible."
  },
  AvgDialog_139658_Content_61 = {
    Text = "El vínculo entre tú y Saya se ha completado."
  },
  AvgDialog_139658_Content_7 = {
    Text = "La luz del sol cae en sus ojos como una piedra cae en aguas quietas—y no levanta ondulación alguna."
  },
  AvgDialog_139658_Content_8 = {Text = "Sí."},
  AvgDialog_139658_Content_9 = {
    Text = "Las palabras salen ásperas."
  },
  AvgDialog_139659_Content_1 = {Text = "\"Amor\""},
  AvgDialog_139659_Content_10 = {
    Text = "Saya se encuentra en el campo de dientes de león, bañada por la luz de la mañana."
  },
  AvgDialog_139659_Content_11 = {
    Text = "La lluvia ha desprendido incontables semillas de sus tallos. Han caído sobre la tierra rojo–negra y algunas, imposiblemente, ya han comenzado a brotar."
  },
  AvgDialog_139659_Content_12 = {
    Text = "Nacidas en una noche, crecidas en una noche..."
  },
  AvgDialog_139659_Content_13 = {
    Text = "Por la expresión de tu rostro... ¿te vino algo a la mente?"
  },
  AvgDialog_139659_Content_14 = {
    Text = "Sí. Una vez vi algo similar en los desiertos de Aram."
  },
  AvgDialog_139659_Content_15 = {
    Text = "La tierra allí está bendecida por el Árbol Madre. Los descendientes de su linaje echan raíces dondequiera que caen, creciendo con el viento."
  },
  AvgDialog_139659_Content_16 = {
    Text = "Eso suena bonito, ¿no?"
  },
  AvgDialog_139659_Content_17 = {
    Text = "...Pero por la forma en que lo dijiste, no pareces pensar lo mismo."
  },
  AvgDialog_139659_Content_18 = {
    Text = "No me corresponde juzgar. Soy alguien ajeno a esa historia."
  },
  AvgDialog_139659_Content_19 = {
    Text = "Es solo que... creo que para la mayoría de las personas, cada etapa de la vida importa."
  },
  AvgDialog_139659_Content_2 = {
    Text = "Tú y Saya se acurrucan cada uno en su propio rincón de la cabaña. La noche transcurre en silencio."
  },
  AvgDialog_139659_Content_20 = {
    Text = "Nefru-Re, por ejemplo. Nunca tuvo una infancia de verdad. Nunca supo lo que era que un padre lo cuidara. Lo arrojaron a la guerra contra el Muro de tormenta antes de que nada de eso pudiera ocurrir..."
  },
  AvgDialog_139659_Content_21 = {
    Text = "Saya asiente, sin estar del todo segura de que comprende."
  },
  AvgDialog_139659_Content_22 = {
    Text = "Entonces, para los humanos, ¿la duración de una vida también importa?"
  },
  AvgDialog_139659_Content_23 = {
    Text = "Más que eso. Cada experiencia, cada persona que conoces... todas se convierten en parte de los recuerdos que llevas contigo."
  },
  AvgDialog_139659_Content_24 = {
    Text = "Esos recuerdos, acumulados con el tiempo, son lo que hacen a una persona quien es."
  },
  AvgDialog_139659_Content_25 = {
    Text = "Incluso podrías decir que los humanos son recipientes de memoria.\nIncluso después de que el cuerpo desaparece, la memoria continúa—transmitida, hasta que la última persona que la guarda la olvida."
  },
  AvgDialog_139659_Content_26 = {
    Text = "Ya veo... Creo que lo entiendo."
  },
  AvgDialog_139659_Content_27 = {
    Text = "Entonces... si muero algún día, ¿el recuerdo de hoy, de estar aquí contigo así, se convertirá en parte de quien eres?"
  },
  AvgDialog_139659_Content_28 = {Text = "Sí."},
  AvgDialog_139659_Content_29 = {
    Text = "Bajo la sombra de la frágil sonrisa de Saya, asientes con firmeza."
  },
  AvgDialog_139659_Content_3 = {
    Text = "En algún momento, el agotamiento te arrastra a un sueño profundo."
  },
  AvgDialog_139659_Content_30 = {
    Text = "El día transcurre entre exploración y recorridos a lo largo del límite."
  },
  AvgDialog_139659_Content_31 = {
    Text = "Más allá del campo de dientes de león, el mismo paisaje desolado se repite en todas direcciones. La tierra está enterrada bajo carne, irreconocible bajo capas de rojo y negro."
  },
  AvgDialog_139659_Content_32 = {
    Text = "La inquietud echa raíces en tu pecho y se cuela en tus pensamientos. La reprimes con esfuerzo."
  },
  AvgDialog_139659_Content_33 = {
    Text = "(Si no hay nada aquí fuera, entonces el núcleo de este Dominio solo puede estar...)"
  },
  AvgDialog_139659_Content_34 = {
    Text = "La noche cae de nuevo."
  },
  AvgDialog_139659_Content_35 = {
    Text = "Descansa un poco. Me siento algo cansada."
  },
  AvgDialog_139659_Content_36 = {
    Text = "Bien. Me gustaría acostarme temprano—cuanto más lejos podamos explorar mañana, mejor."
  },
  AvgDialog_139659_Content_37 = {
    Text = "Con eso, ambos se quedan dormidos."
  },
  AvgDialog_139659_Content_38 = {Text = "..."},
  AvgDialog_139659_Content_39 = {
    Text = "Algo te despierta. Un sonido—o un calor. Un calor que se mete bajo tu piel—como si estuvieras de vuelta en el desierto."
  },
  AvgDialog_139659_Content_4 = {
    Text = "(Qué frío... Espero que mañana pueda dormir en una cama de verdad...)"
  },
  AvgDialog_139659_Content_40 = {Text = "¿!!"},
  AvgDialog_139659_Content_41 = {
    Text = "Tu cabeza da vueltas. No puedes distinguir si es la escena inquietante frente a ti, o la bruma que flota en el aire."
  },
  AvgDialog_139659_Content_42 = {
    Text = "O la influencia del Río Sagrado."
  },
  AvgDialog_139659_Content_43 = {
    Text = "Qué pena. ¿No era yo a quien esperabas?"
  },
  AvgDialog_139659_Content_44 = {
    Text = "Reina de Aran—Thais levantó la cortina y entró. Se acercó sin dudar, el delgado velo adhiriéndose a tu antebrazo, emitiendo una invitación directa."
  },
  AvgDialog_139659_Content_45 = {
    Text = "Ven, acepta la línea sanguínea de Arlan y conviértete en uno de nosotros."
  },
  AvgDialog_139659_Content_46 = {
    Text = "Acércate, abrázame... Dame tu sangre, tu esencia..."
  },
  AvgDialog_139659_Content_47 = {
    Text = "Las llamas parpadean en sus fervientes pupilas, sus mejillas sonrojadas revelan un deseo mórbido."
  },
  AvgDialog_139659_Content_48 = {
    Text = "Solo una gota es suficiente. Mientras nuestras carnes se fusionen, Él nos otorgará el futuro que deseamos..."
  },
  AvgDialog_139659_Content_49 = {
    Text = "Vamos a... engendrar descendencia para la tribu, compartiendo en la eternidad..."
  },
  AvgDialog_139659_Content_5 = {
    Text = "Algo se posa sobre ti en la oscuridad."
  },
  AvgDialog_139659_Content_50 = {
    Text = "Arrastras tu razón desde algún lugar profundo, luchando contra el tirón de sus palabras. La campana que te despertó por primera vez como Guardián permanece en silencio."
  },
  AvgDialog_139659_Content_51 = {
    Text = "Y entonces—una voz diferente irrumpe."
  },
  AvgDialog_139659_Content_52 = {
    Text = "¿Por qué? ¿Por qué sigues rechazándolo?"
  },
  AvgDialog_139659_Content_53 = {
    Text = "Ha aparecido desde un rincón de la tienda sin hacer ruido."
  },
  AvgDialog_139659_Content_54 = {
    Text = "Su voz es diferente a la habitual. Algo más pesado se oculta bajo sus palabras, algo que no puedes nombrar del todo."
  },
  AvgDialog_139659_Content_55 = {
    Text = "Reproducción... Creo que es algo bueno. El propósito de todos los seres vivos..."
  },
  AvgDialog_139659_Content_56 = {
    Text = "Pero ¿por qué no lo aceptas?"
  },
  AvgDialog_139659_Content_57 = {
    Text = "¿Por qué? ¿Por qué sigues rechazándolo?"
  },
  AvgDialog_139659_Content_58 = {
    Text = "Porque esto no tiene nada que ver con el amor. Esto es solo tentación."
  },
  AvgDialog_139659_Content_59 = {
    Text = "La tentación no es amor. El deber no es amor. El deseo no es amor."
  },
  AvgDialog_139659_Content_6 = {Text = "...¿Hmm?"},
  AvgDialog_139659_Content_60 = {
    Text = "El amor es —"
  },
  AvgDialog_139659_Content_61 = {
    Text = "El amor es —"
  },
  AvgDialog_139659_Content_62 = {
    Text = "El mundo se apaga."
  },
  AvgDialog_139659_Content_63 = {
    Text = "Todo cae en una larga y oscura negrura."
  },
  AvgDialog_139659_Content_7 = {
    Text = "Una manta fina ha sido colocada sobre ti."
  },
  AvgDialog_139659_Content_8 = {
    Text = "El cielo se ha despejado."
  },
  AvgDialog_139659_Content_9 = {
    Text = "Es hora de salir."
  },
  AvgDialog_139660_Content_1 = {Text = "\"Recordar\""},
  AvgDialog_139660_Content_10 = {
    Text = "Y tienes razón, no soy exactamente alguien común. Soy un investigador de la Universidad de Misag."
  },
  AvgDialog_139660_Content_11 = {
    Text = "Saya tiene una expresión desconcertada en el rostro; está claro que esos términos no significan nada para ella."
  },
  AvgDialog_139660_Content_12 = {
    Text = "Es una larga historia. Ahora mismo tengo algo más urgente de lo que ocuparme."
  },
  AvgDialog_139660_Content_13 = {
    Text = "Mi compañera, Ramona. Vi cómo algo la consumía. Se convirtió en—"
  },
  AvgDialog_139660_Content_14 = {
    Text = "No terminas la frase. No puedes."
  },
  AvgDialog_139660_Content_15 = {
    Text = "Las palabras son solo símbolos vacíos. No pueden transmitir lo que sentiste en ese momento: el miedo que trepó desde la base de tu columna."
  },
  AvgDialog_139660_Content_16 = {
    Text = "El miedo de perder a Ramona para siempre."
  },
  AvgDialog_139660_Content_17 = {
    Text = "Es irremplazable para mí."
  },
  AvgDialog_139660_Content_18 = {
    Text = "La mirada de Saya se pierde por un momento."
  },
  AvgDialog_139660_Content_19 = {
    Text = "Irremplazable... Ya veo."
  },
  AvgDialog_139660_Content_2 = {
    Text = "Antes de que puedas ordenar tus preguntas, ella habla primero."
  },
  AvgDialog_139660_Content_20 = {
    Text = "Creo que yo también he tenido... a alguien así."
  },
  AvgDialog_139660_Content_21 = {
    Text = "Baja la mirada, con el ceño fruncido, murmurando para sí misma."
  },
  AvgDialog_139660_Content_22 = {
    Text = "Había alguien. Una persona muy importante. Debería recordar su rostro... Debo recordarlo. Pero cuando intento imaginarlo ahora, lo único que veo es—"
  },
  AvgDialog_139660_Content_23 = {
    Text = "—solo un contorno. Como mirar a través de un cristal esmerilado. Sé que estaba ahí. Sé que era importante. Pero todos los detalles han sido... borrados."
  },
  AvgDialog_139660_Content_24 = {
    Text = "No es solo él. Todo lo demás es igual. Sé que hay algo que debo hacer, algo importante."
  },
  AvgDialog_139660_Content_25 = {
    Text = "Pero los recuerdos no dejan de contradecirse. Uno dice que era amable; el siguiente dice que estuve en un lugar muy oscuro durante mucho tiempo. Uno dice que esperaba que alguien viniera a buscarme; otro dice que tenía que hacer algo... que asustaría a la gente."
  },
  AvgDialog_139660_Content_26 = {
    Text = "Cada fragmento parece real. Pero simplemente no encajan."
  },
  AvgDialog_139660_Content_27 = {
    Text = "Cada fragmento se siente real. Pero simplemente no encajan entre sí."
  },
  AvgDialog_139660_Content_28 = {
    Text = "Ya has visto esta condición antes."
  },
  AvgDialog_139660_Content_29 = {
    Text = "No sé qué partes ocurrieron de verdad. No sé qué recuerdos son realmente míos..."
  },
  AvgDialog_139660_Content_3 = {
    Text = "Soy... hmm, puedes llamarme Saya.\n¿Sabes dónde estamos?"
  },
  AvgDialog_139660_Content_30 = {
    Text = "No sé qué partes ocurrieron realmente. No sé qué recuerdos son verdaderamente míos..."
  },
  AvgDialog_139660_Content_31 = {
    Text = "Los dedos de Saya se curvan hacia dentro, como si intentara aferrarse a algo que ya no existe."
  },
  AvgDialog_139660_Content_32 = {
    Text = "Mientras ella vacila, el mundo a tu alrededor comienza a cambiar."
  },
  AvgDialog_139660_Content_33 = {Text = "¡Cuidado!"},
  AvgDialog_139660_Content_34 = {
    Text = "Miras hacia el borde del campo de dientes de león. La membrana carnosa, empapada en lodo negro, avanza hacia dentro centímetro a centímetro. El límite parece menos definido que antes."
  },
  AvgDialog_139660_Content_4 = {
    Text = "¿Por qué estoy en un lugar como este...?\nHmm... hay tantas cosas que no logro recordar."
  },
  AvgDialog_139660_Content_5 = {
    Text = "...No eres una persona común, ¿verdad?\n¿Tienes algún tipo de habilidad especial...?"
  },
  AvgDialog_139660_Content_6 = {
    Text = "No respondes de inmediato. La niña llamada Saya suelta tu mano, da medio paso atrás y entrecierra los ojos mientras te examina."
  },
  AvgDialog_139660_Content_7 = {
    Text = "¿Me viste y no sentiste nada? ¿Por qué viniste aquí?"
  },
  AvgDialog_139660_Content_8 = {
    Text = "Espera, una pregunta a la vez."
  },
  AvgDialog_139660_Content_9 = {
    Text = "Por lo que puedo deducir, lo más probable es que esto sea un Dominio."
  },
  AvgDialog_139661_Content_1 = {
    Text = "Paisaje Mental"
  },
  AvgDialog_139661_Content_10 = {
    Text = "Una hermosa joven y un hombre joven."
  },
  AvgDialog_139661_Content_11 = {
    Text = "De la mano, caminan juntos a través del páramo aullante."
  },
  AvgDialog_139661_Content_12 = {Text = "..."},
  AvgDialog_139661_Content_13 = {
    Text = "Ella ríe entre dientes, abriendo los brazos para abrazar el viento."
  },
  AvgDialog_139661_Content_14 = {
    Text = "El joven a su lado se inclina, escuchando atentamente cada una de sus encantadoras palabras."
  },
  AvgDialog_139661_Content_15 = {
    Text = "El cielo está despejado, pero teñido de una quieta melancolía."
  },
  AvgDialog_139661_Content_16 = {
    Text = "Pero en su silueta compartida, vislumbras una alegría serena e involuntaria."
  },
  AvgDialog_139661_Content_17 = {
    Text = "Aunque no hubiera nadie más alrededor, aunque no recibieran comprensión ni bendiciones de nadie, su amor aún—"
  },
  AvgDialog_139661_Content_18 = {
    Text = "Entonces el sueño se corta. La tormenta de arena lo arrastra todo."
  },
  AvgDialog_139661_Content_19 = {
    Text = "El mundo se sumerge en un negro vacío."
  },
  AvgDialog_139661_Content_2 = {
    Text = "El mundo está hecho de arena."
  },
  AvgDialog_139661_Content_20 = {
    Text = "—Hubo una vez una cantante, abriéndose camino entre las estrellas."
  },
  AvgDialog_139661_Content_21 = {
    Text = "En un universo árido y desolado, encontró un Núcleo de plata yaciendo en el polvo."
  },
  AvgDialog_139661_Content_22 = {
    Text = "En el momento en que lo tocó, \"Yo\" desperté."
  },
  AvgDialog_139661_Content_23 = {
    Text = "\"Yo\" había perdido toda memoria. Pero \"Yo\" sabía una cosa: tenía que encontrar a esa \"persona irremplazable\"."
  },
  AvgDialog_139661_Content_24 = {
    Text = "\"Yo\" le pregunté a la cantante si podíamos viajar juntas, pero la petición fue rechazada."
  },
  AvgDialog_139661_Content_25 = {
    Text = "Voy a buscar a la persona que significa todo para mí—mi hermana."
  },
  AvgDialog_139661_Content_26 = {
    Text = "Eso fue lo que dijo."
  },
  AvgDialog_139661_Content_27 = {
    Text = "Espero que tú también encuentres a tu amor, Saya. De verdad te deseo un final feliz."
  },
  AvgDialog_139661_Content_28 = {
    Text = "Con esas palabras, la cantante partió."
  },
  AvgDialog_139661_Content_29 = {
    Text = "Y así, sin mi pasado y ahora sin la cantante,"
  },
  AvgDialog_139661_Content_3 = {
    Text = "Entre los vientos que han barrido este desierto durante eras, permaneces a la deriva, contemplándolo todo."
  },
  AvgDialog_139661_Content_30 = {
    Text = "Llevé su bendición conmigo mientras caminaba sola por este mundo."
  },
  AvgDialog_139661_Content_31 = {
    Text = "Para encontrar a quien una vez fue irremplazable... para reconstruir lo que había perdido..."
  },
  AvgDialog_139661_Content_32 = {
    Text = "Seguí avanzando, creyendo que lo que buscaba me esperaba justo adelante."
  },
  AvgDialog_139661_Content_33 = {
    Text = "Hasta que, al fin... te encontré."
  },
  AvgDialog_139661_Content_4 = {
    Text = "Este lugar..."
  },
  AvgDialog_139661_Content_5 = {
    Text = "Sin el fango de la Disolución. Sin masas extensas de visceras."
  },
  AvgDialog_139661_Content_6 = {
    Text = "El paisaje aquí es solitario, puro y hermoso."
  },
  AvgDialog_139661_Content_7 = {
    Text = "Este es mi Paisaje Mental."
  },
  AvgDialog_139661_Content_8 = {
    Text = "Un fragmento de mi existencia—algo irremplazable, algo que jamás debería ser olvidado..."
  },
  AvgDialog_139661_Content_9 = {
    Text = "La arena se desplaza y ondula, y en el rincón lejano del desierto, dos figuras emergen."
  },
  AvgDialog_139662_Content_10 = {
    Text = "Seré tu asistente, acompañándote hasta el final de este camino... <Yellow:Que la Llave de Plata ilumine tu camino.>"
  },
  AvgDialog_139662_Content_11 = {
    Text = "¿Estás bien, %player%? Estás un poco pálido/a. ¿Deberíamos pasar por la enfermería?"
  },
  AvgDialog_139662_Content_12 = {Text = "Ramona..."},
  AvgDialog_139662_Content_13 = {
    Text = "El nombre se te atraganta. No puedes pronunciar su nombre—el nombre que conoces tan bien."
  },
  AvgDialog_139662_Content_14 = {
    Text = "<Shake:<Red:Mmｦ,ﾋ seguro5 queｸk empezamos Q a...ﾃ mejor爨 queｨ me A conecteﾑ鑷 con9ｴ tigoﾅ.>>"
  },
  AvgDialog_139662_Content_15 = {
    Text = "<Shake:<Red:Unｷ pocoｚ(antesﾉ deｲ lo驫ｲ previsto8ﾃP,ｬ peroﾗ noｸ importaﾎ関靇,ﾑ ¿verdadw queｦ sí J?>>"
  },
  AvgDialog_139662_Content_16 = {
    Text = "<Red:No, no, no, no. Nada está bien. Nada.>"
  },
  AvgDialog_139662_Content_17 = {
    Text = "<Shake:<Red:ﾒDesdeｩﾇ龥 haceｯ años7開ﾘ queL,ﾝ esperabaQ esteｱ齉 díaﾏ,r hoyｮ por fin麤.>>"
  },
  AvgDialog_139662_Content_18 = {
    Text = "<Shake:No, eso no es Ramona, Ramona no puede ser una masa de carne deforme y Distorsionada, no puede emitir ese zumbido nauseabundo, no puede tener D-Slime negro brotando por todo su cuerpo...>"
  },
  AvgDialog_139662_Content_19 = {
    Text = "<Red:No usará esos ojos negros y vacíos para clavarlos en mí——>"
  },
  AvgDialog_139662_Content_2 = {
    Text = "Blo0ﾝdiｲwoRｮ"
  },
  AvgDialog_139662_Content_20 = {Text = "¡No—!"},
  AvgDialog_139662_Content_21 = {
    Text = "¿Fue eso... un sueño?"
  },
  AvgDialog_139662_Content_22 = {
    Text = "Despiertas de golpe, empapada en sudor frío."
  },
  AvgDialog_139662_Content_23 = {
    Text = "Qué sueño tan extraño. Incluso despierta, sigue persistiendo en mi vista."
  },
  AvgDialog_139662_Content_24 = {
    Text = "Lo que estás viendo... es..."
  },
  AvgDialog_139662_Content_25 = {Text = "Es..."},
  AvgDialog_139662_Content_26 = {
    Text = "<Shake:<Red:Carne, grandes bloques de carne apilados y superpuestos.>>"
  },
  AvgDialog_139662_Content_27 = {
    Text = "Entrañas carmesí y retorcidas cubriendo las paredes, estrangulando los pilares, arrastrándose por las ventanas.\nY entre las grietas de la carne—"
  },
  AvgDialog_139662_Content_28 = {
    Text = "Un líquido negro se filtra hacia fuera."
  },
  AvgDialog_139662_Content_29 = {
    Text = "Disolución."
  },
  AvgDialog_139662_Content_3 = {
    Text = "Pain. Un dolor abrasador. Un carmesí oscuro inunda tus retinas."
  },
  AvgDialog_139662_Content_30 = {
    Text = "Ya has visto la Disolución antes. Demasiadas veces. Pero nunca así—dos males distintos desgarrando un solo cuerpo a la vez."
  },
  AvgDialog_139662_Content_31 = {Text = "Ramona..."},
  AvgDialog_139662_Content_32 = {
    Text = "La imagen vuelve a destellar. Cuencas de ojos negras y vacías. Un contorno distorsionado e hinchado. Sus dedos se convierten en <Shake:brotes de carne irregulares> en la palma de tu mano——"
  },
  AvgDialog_139662_Content_33 = {
    Text = "No—para. Deja de pensar—"
  },
  AvgDialog_139662_Content_34 = {
    Text = "Ella sigue ahí fuera—tiene que estar en algún lugar—"
  },
  AvgDialog_139662_Content_35 = {
    Text = "Un leve temblor recorre tu mente. Casi imperceptible."
  },
  AvgDialog_139662_Content_36 = {
    Text = "Instintivamente, buscas la fuente—no es Ramona. Podrías reconocer a Ramona con los ojos cerrados; sus ondas espirituales son calmadas y suaves, como la superficie de un lago en calma."
  },
  AvgDialog_139662_Content_37 = {
    Text = "Ve al este..."
  },
  AvgDialog_139662_Content_38 = {Text = "¿Quién?"},
  AvgDialog_139662_Content_39 = {
    Text = "Sin respuesta."
  },
  AvgDialog_139662_Content_4 = {
    Text = "Mi cabeza..."
  },
  AvgDialog_139662_Content_40 = {
    Text = "Sin más pistas, te mueves hacia el sonido."
  },
  AvgDialog_139662_Content_41 = {
    Text = "Cruzas un río que apesta a óxido y putrefacción. Pisas una tierra membranosa infestada de tendones rojo oscuro."
  },
  AvgDialog_139662_Content_42 = {
    Text = "Tu respiración se vuelve pesada; tus nervios palpitan bajo la invasión de esos colores sobrenaturales."
  },
  AvgDialog_139662_Content_43 = {
    Text = "Alguien... quien sea... sáquenme de este sueño..."
  },
  AvgDialog_139662_Content_44 = {
    Text = "Tiene que ser un sueño. La sensación es demasiado real—pero tienes que creerlo. Tienes que hacerlo."
  },
  AvgDialog_139662_Content_45 = {
    Text = "Algo suave y blanco se posa en la punta de tu nariz."
  },
  AvgDialog_139662_Content_46 = {
    Text = "¿Un diente de león...?"
  },
  AvgDialog_139662_Content_47 = {
    Text = "Pisas un límite. Uno visible—una línea clara e inconfundible que divide dos mundos."
  },
  AvgDialog_139662_Content_48 = {
    Text = "Más allá: carne nauseabunda y fango negro burbujeante."
  },
  AvgDialog_139662_Content_49 = {
    Text = "En su interior: un pequeño campo de dientes de león. En el centro, una pequeña cabaña de madera."
  },
  AvgDialog_139662_Content_5 = {
    Text = "Una luz tenue y parpadeante, un zumbido resonando en tus tímpanos. No se puede confiar en este mundo. Todo lo que ves no es más que una ilusión."
  },
  AvgDialog_139662_Content_50 = {
    Text = "Algo se mueve entre los dientes de león."
  },
  AvgDialog_139662_Content_51 = {
    Text = "Sigues el movimiento. Una pelusa blanca es apartada, revelando una esquina de tela pálida."
  },
  AvgDialog_139662_Content_52 = {
    Text = "Entonces ella se pone de pie."
  },
  AvgDialog_139662_Content_53 = {
    Text = "Una chica, frágil y etérea como un diente de león."
  },
  AvgDialog_139662_Content_54 = {
    Text = "Ladea la cabeza, observando tu expresión."
  },
  AvgDialog_139662_Content_55 = {
    Text = "¿No me tienes miedo?"
  },
  AvgDialog_139662_Content_56 = {
    Text = "Es casi irónico. Después de todo lo que has atravesado, ella es la única humana normal que has visto. La única existencia que no resulta aterradora."
  },
  AvgDialog_139662_Content_57 = {
    Text = "Entonces... ¿te gustaría estrechar la mano?"
  },
  AvgDialog_139662_Content_58 = {
    Text = "¿Eh? ¿Por qué?"
  },
  AvgDialog_139662_Content_59 = {
    Text = "Hmm... simplemente siento que debería hacerlo."
  },
  AvgDialog_139662_Content_6 = {
    Text = "Despierta. Despierta ya..."
  },
  AvgDialog_139662_Content_60 = {
    Text = "En cuanto al porqué... no logro recordarlo."
  },
  AvgDialog_139662_Content_61 = {Text = "Además..."},
  AvgDialog_139662_Content_62 = {
    Text = "La chica ladea la cabeza, con una sonrisa juguetona adornando sus labios."
  },
  AvgDialog_139662_Content_63 = {
    Text = "Tú también quieres tocarme, ¿verdad?"
  },
  AvgDialog_139662_Content_64 = {
    Text = "Así es. Por supuesto que sí."
  },
  AvgDialog_139662_Content_65 = {
    Text = "Después de todo —la oscuridad, el hedor, el repulsivo asalto a los sentidos—, ¿cómo no ibas a querer tocar a la primera persona viva que has encontrado?"
  },
  AvgDialog_139662_Content_66 = {
    Text = "Extiendes la mano, tocando sus dedos delgados y suaves."
  },
  AvgDialog_139662_Content_67 = {
    Text = "Qué sensación tan extraña..."
  },
  AvgDialog_139662_Content_68 = {
    Text = "Sí. Tú también lo sientes. Junto al calor humano, hay una sensación tenue, como una débil corriente eléctrica que os conecta."
  },
  AvgDialog_139662_Content_69 = {
    Text = "Es la resonancia de los Núcleos de plata."
  },
  AvgDialog_139662_Content_7 = {
    Text = "Bienvenido a la Universidad Mythag, %player%."
  },
  AvgDialog_139662_Content_8 = {
    Text = "¿O más bien... bienvenido, has cruzado oficialmente al lado oculto del mundo."
  },
  AvgDialog_139662_Content_9 = {
    Text = "(¿He... vuelto?)"
  },
  AvgDialog_139663_Content_1 = {
    Text = "Esas cosas son..."
  },
  AvgDialog_139663_Content_10 = {
    Text = "Si ella es ordinaria... probablemente no podrá hablar conmigo."
  },
  AvgDialog_139663_Content_11 = {
    Text = "Como eres un Cuerpo Despertado, puede que sea capaz de establecer un vínculo contigo. A través de la resonancia onírica, podrías ver cómo es Ramona."
  },
  AvgDialog_139663_Content_12 = {
    Text = "Quizás ella pueda ser la pista para descubrir tus recuerdos."
  },
  AvgDialog_139663_Content_13 = {
    Text = "Tomas la mano de Saya de nuevo. Buscas en tu interior, trazando la forma de Ramona en tu mente —su voz, su rostro— esperando que el tenue vínculo entre ustedes pueda transmitirlo."
  },
  AvgDialog_139663_Content_14 = {
    Text = "<Italic:Crac>. El vínculo se rompe."
  },
  AvgDialog_139663_Content_15 = {
    Text = "Se siente como si un muro informe estuviera bloqueando nuestro vínculo..."
  },
  AvgDialog_139663_Content_16 = {
    Text = "Parece como si un muro sin forma estuviera bloqueando nuestro vínculo..."
  },
  AvgDialog_139663_Content_17 = {
    Text = "Quizás esté relacionado con lo que tengo que hacer. Tengo la sensación... de que es algo prohibido. Algo que no puedo contarle a todos."
  },
  AvgDialog_139663_Content_18 = {
    Text = "Parece que se acerca una tormenta. Descansemos adentro un rato."
  },
  AvgDialog_139663_Content_19 = {
    Text = "Por las grietas de los tablones de madera, un limo negro flota ocasionalmente hacia arriba, desafiando la gravedad."
  },
  AvgDialog_139663_Content_2 = {
    Text = "Yo tampoco lo sé. Pero tengo la sensación de que... la respuesta está en algún lugar de mis recuerdos."
  },
  AvgDialog_139663_Content_20 = {
    Text = "Saya se acurruca en un rincón, la mitad inferior de su rostro hundida contra sus brazos. Pregunta en voz baja—"
  },
  AvgDialog_139663_Content_21 = {
    Text = "Esto es lo que llamaste \"Disolución\", ¿verdad?"
  },
  AvgDialog_139663_Content_22 = {Text = "Asientes."},
  AvgDialog_139663_Content_23 = {
    Text = "¿Eso es lo que se llevó mis recuerdos?"
  },
  AvgDialog_139663_Content_24 = {
    Text = "Sí. Y no solo a ti, incontables personas han perdido recuerdos importantes a causa de la Disolución."
  },
  AvgDialog_139663_Content_25 = {
    Text = "Algunos olvidaron los rostros de sus seres queridos. Pasaron años buscando, y a veces, en esa búsqueda, terminaron hiriendo a los mismos que extrañan."
  },
  AvgDialog_139663_Content_26 = {
    Text = "Algunos olvidaron las ciudades donde nacieron. Vagaron solos a través del océano, persiguiendo un pasado al que nunca podrán regresar."
  },
  AvgDialog_139663_Content_27 = {
    Text = "...Perder recuerdos preciados debe ser muy doloroso."
  },
  AvgDialog_139663_Content_28 = {
    Text = "Saya mira la lluvia cayendo en líneas finas y constantes, como si el agua pudiera lavar la inmundicia negra."
  },
  AvgDialog_139663_Content_29 = {
    Text = "Me pregunto... ¿cuáles serán las cosas importantes ocultas en mis recuerdos?"
  },
  AvgDialog_139663_Content_3 = {
    Text = "Encontraré la manera de sacarte de este Dominio. Recuperaremos tus recuerdos."
  },
  AvgDialog_139663_Content_30 = {
    Text = "Me pregunto... ¿cuáles son las cosas importantes ocultas en mis recuerdos?"
  },
  AvgDialog_139663_Content_31 = {
    Text = "Te mantienes en silencio."
  },
  AvgDialog_139663_Content_32 = {
    Text = "Afuera, la lluvia sigue cayendo, constante y suave."
  },
  AvgDialog_139663_Content_4 = {Text = "Pero..."},
  AvgDialog_139663_Content_5 = {
    Text = "Quieres encontrar a Ramona primero, ¿verdad?"
  },
  AvgDialog_139663_Content_6 = {
    Text = "Para ser sincera... creo que recuerdo haberme encontrado con alguien una vez, y luego..."
  },
  AvgDialog_139663_Content_7 = {
    Text = "Para ser honesta... creo que recuerdo haber conocido a alguien una vez, y luego..."
  },
  AvgDialog_139663_Content_8 = {
    Text = "En fin. Esta Ramona... ¿es diferente, como tú?"
  },
  AvgDialog_139663_Content_9 = {
    Text = "Si es una persona ordinaria... probablemente no podrá hablar conmigo."
  },
  AvgDialog_141373_Content_1 = {
    Text = "No es la primera vez que visitas Ebwynnos, pero nunca, en ninguna ocasión, estas criaturas sin rostro habían estado tan agitadas como hoy."
  },
  AvgDialog_141373_Content_10 = {
    Text = "Espera, tú eres... ¿por qué estás aquí?"
  },
  AvgDialog_141373_Content_11 = {
    Text = "Un ruido blanco agudo engulló tu consciencia, y una marea antigua e invisible te obligó a levantar la cabeza con pesadez, mirando hacia lo único que podías reconocer."
  },
  AvgDialog_141373_Content_12 = {
    Text = "Exacto, nada de eso importa: quién eres, qué quieres hacer, La Razón por la que llegaste aquí."
  },
  AvgDialog_141373_Content_13 = {
    Text = "Una voz grave disipa el sonido del mar, mientras el mayor estrecha el círculo de La Cacería desde lo alto."
  },
  AvgDialog_141373_Content_14 = {
    Text = "Estás a salvo, bienvenido de vuelta."
  },
  AvgDialog_141373_Content_15 = {
    Text = "Oh... sí, Ebwynnos, he vuelto a Ebwynnos."
  },
  AvgDialog_141373_Content_16 = {
    Text = "Murmuras repitiéndolo en voz baja, sin darte cuenta esbozas una sonrisa, y todo lo que viene después parece de lo más natural."
  },
  AvgDialog_141373_Content_17 = {
    Text = "Bueno, admito que esto infringe un poco las normas, pero no te preocupes, te haré volver a Misaq."
  },
  AvgDialog_141373_Content_18 = {
    Text = "El abismo ya te ha envuelto por completo, y tu Frágil intelecto, sacudido una y otra vez, es incapaz de comprender todo lo que el otro expone."
  },
  AvgDialog_141373_Content_19 = {Text = "¿Qué?"},
  AvgDialog_141373_Content_2 = {
    Text = "Oye, ¡Oye! Para, no soy un ene..."
  },
  AvgDialog_141373_Content_20 = {
    Text = "Una risa ronca y breve."
  },
  AvgDialog_141373_Content_21 = {
    Text = "Justo que no ahora."
  },
  AvgDialog_141373_Content_22 = {
    Text = "Húmedo, Caos, aglomeración: te llenan hasta rebosar y luego, en oleadas interminables, te dejan Enredado; pierdes todo control."
  },
  AvgDialog_141373_Content_23 = {
    Text = "Solo quedan susurros entremezclados con jadeos junto a tu oído."
  },
  AvgDialog_141373_Content_24 = {
    Text = "Ahora perteneces a este lugar, me perteneces a mí, perteneces a Ebwynnos."
  },
  AvgDialog_141373_Content_25 = {
    Text = "No entiendes nada; Justo sigues dejándote llevar por ese antiguo mar en medio de la dicha."
  },
  AvgDialog_141373_Content_26 = {
    Text = "Él no da señales de querer detenerse."
  },
  AvgDialog_141373_Content_3 = {
    Text = "*Sonido de silbato de caza"
  },
  AvgDialog_141373_Content_4 = {
    Text = "El Ataque cesó, sin embargo, la oscuridad te envolvió de repente. Casi en un instante, la pesada quietud te arrojó a una especie de abismo indescriptible."
  },
  AvgDialog_141373_Content_5 = {Text = "¿Hm?"},
  AvgDialog_141373_Content_6 = {Text = "Ah..."},
  AvgDialog_141373_Content_7 = {
    Text = "Como Si quisiera confirmar algo, ignorando el escalofrío que te recorrió por la reacción instintiva del momento, el señor de estas tierras recorrió con gesto indiscutible tu arco superciliar, el rabillo del ojo, hasta el costado del cuello."
  },
  AvgDialog_141373_Content_8 = {
    Text = "Visitar Ebwynnos en un momento como este no es buena idea, %player%."
  },
  AvgDialog_141373_Content_9 = {
    Text = "<Small:Solo quería...>"
  },
  AvgDialog_142850_Content_1 = {
    Text = "Primera Sección"
  },
  AvgDialog_142850_Content_10 = {
    Text = "¡Varo... tú, ríndete! ¡Somos muchos, es imposible que salgas vivo de este Bosque!"
  },
  AvgDialog_142850_Content_100 = {
    Text = "Era una velocidad y una Fuerza que él no podía resistir. Varo levantó los ojos con confusión, mirando a Lotan sin comprender."
  },
  AvgDialog_142850_Content_101 = {
    Text = "Tú... lo prometiste..."
  },
  AvgDialog_142850_Content_102 = {
    Text = "Prometí dejarte unirte a mi equipo. Pero no dije que vivirías."
  },
  AvgDialog_142850_Content_103 = {
    Text = "La debilidad no es tu culpa. Pero tu corazón no es puro, guerrero."
  },
  AvgDialog_142850_Content_104 = {
    Text = "Lotan toma los dos Sigilos de Hueso de la mano de Varro y arroja su cadáver —con el rostro aún congelado en una expresión de confusión— sobre el montón de doce caballeros muertos, como si fuera basura desechada."
  },
  AvgDialog_142850_Content_105 = {
    Text = "Echa un vistazo hacia la maleza, levantando su espadón, lista para partir el Sigilo sobrante..."
  },
  AvgDialog_142850_Content_106 = {
    Text = "¡¡Espera!! —"
  },
  AvgDialog_142850_Content_107 = {
    Text = "La hoja de Lotan se detiene en el aire. Con fría indiferencia, te observa salir arrastrándote de entre los arbustos."
  },
  AvgDialog_142850_Content_108 = {
    Text = "No me interesan los oponentes demasiado débiles."
  },
  AvgDialog_142850_Content_109 = {
    Text = "Pequeño Escudero de la orden de Caballeros, si yo fuera Tú, huiría antes de que el otro cambie de opinión, cuanto más rápido mejor."
  },
  AvgDialog_142850_Content_11 = {
    Text = "¡Entrega tu sello de hueso y te garantizamos, te garantizamos que podrás marcharte sano y salvo!"
  },
  AvgDialog_142850_Content_110 = {
    Text = "El señor Elian ordenó a la orden de Caballeros traerle la corona, si... si descubre que huí, toda mi familia morirá..."
  },
  AvgDialog_142850_Content_111 = {
    Text = "Reuniste todo tu valor y diste un paso en dirección a Lotan."
  },
  AvgDialog_142850_Content_112 = {
    Text = "Usted todavía tiene un sello de hueso... se lo ruego, ¿déjeme ir también al Coliseo de la Ballena Celestial? Solo necesito llegar allí y mi misión estará completa... Usted es tan poderosa que no representaré ninguna amenaza para usted..."
  },
  AvgDialog_142850_Content_113 = {Text = "¿Tú?"},
  AvgDialog_142850_Content_114 = {
    Text = "Lotan arqueó una ceja y te miró con Pulla."
  },
  AvgDialog_142850_Content_115 = {
    Text = "Tu Fuerza es incluso inferior a la de esos inútiles que Varo mató. En el primer segundo que entres a ese Coliseo, morirás como un gusano."
  },
  AvgDialog_142850_Content_116 = {
    Text = "Vete ahora y aún tendrás la oportunidad de vivir."
  },
  AvgDialog_142850_Content_117 = {
    Text = "Miraste los cadáveres esparcidos por el suelo, miraste la figura frente a ti que te llenaba de miedo desde lo más profundo de tu ser, y tragaste saliva con dificultad."
  },
  AvgDialog_142850_Content_118 = {
    Text = "Sabes que la victoria nunca fue tuya para reclamar. Cada instinto te grita que huyas de este monstruo, que corras tan lejos como sea posible."
  },
  AvgDialog_142850_Content_119 = {
    Text = "Quieres olvidar a tu madre, que fue sacrificada viva al Cetus Astral. Quieres olvidar a tus hermanos, encerrados como ganado en los establos. Simplemente quieres sobrevivir."
  },
  AvgDialog_142850_Content_12 = {
    Text = "¡Tiene razón, Varo! Aunque seas el mercenario más poderoso de los seis reinos, rodeado por los trece que somos, no tienes ninguna ventaja."
  },
  AvgDialog_142850_Content_120 = {
    Text = "Pero no había manera, no podías olvidar. Al igual que participar en esta contienda destinada a convertirte en carne de cañón, nunca tuviste el derecho de elegir."
  },
  AvgDialog_142850_Content_121 = {
    Text = "Soy el guía del grupo, conozco el Camino al Coliseo. He sido Escudero durante muchísimos años, ¡sé cómo servir a un guerrero! Soy muy útil, me necesitará..."
  },
  AvgDialog_142850_Content_122 = {
    Text = "Respiras profundo, recoges el Sigilo y usas un trapo para limpiar la mugre de la armadura de Lotan, tal como lo hacías antes con los caballeros."
  },
  AvgDialog_142850_Content_123 = {
    Text = "Por favor, venga por aquí, Este... Este... ¿eh?"
  },
  AvgDialog_142850_Content_124 = {
    Text = "Te inclinaste ante Ella, su respiración tranquila te oprimía de tal manera que no te atrevías a levantar la cabeza, Solo podías clavar la vista en el suelo bajo sus pies. Sentiste que La Mirada de Ella, afilada como una Cuchilla, se posó sobre ti durante unos segundos."
  },
  AvgDialog_142850_Content_125 = {
    Text = "Si te encuentras en peligro, no esperes que te ayude."
  },
  AvgDialog_142850_Content_126 = {
    Text = "Sin sufijos. Puedes llamarme Lotan."
  },
  AvgDialog_142850_Content_127 = {
    Text = "Lotan guardó la gran espada y caminó en la dirección que le señalaste."
  },
  AvgDialog_142850_Content_128 = {
    Text = "La Sangre había penetrado completamente en el suelo. En las profundidades del cielo rojo oscuro, una sombra enorme y de movimiento lento aparecía y desaparecía."
  },
  AvgDialog_142850_Content_129 = {
    Text = "Te estremeciste y te apresuraste a seguir los pasos de Lotan."
  },
  AvgDialog_142850_Content_13 = {
    Text = "Podemos cooperar, ¿no es así?"
  },
  AvgDialog_142850_Content_130 = {
    Text = "¡Sí... señora Lotan!"
  },
  AvgDialog_142850_Content_14 = {
    Text = "¿Cooperar?"
  },
  AvgDialog_142850_Content_15 = {
    Text = "La Ballena del Cielo Estelar solo elegirá a una persona como su Executor, ¡y eso es algo que nadie puede lograr solo!"
  },
  AvgDialog_142850_Content_16 = {
    Text = "Solo tienes que soltar el sello de hueso, te garantizamos que saldrás de aquí sano y salvo y obtendrás todo lo que puedas obtener..."
  },
  AvgDialog_142850_Content_17 = {Text = "¿Es así?"},
  AvgDialog_142850_Content_18 = {
    Text = "Lo sé, Varo, sobreviviste a las manadas de bestias de la isla desierta, mataste ante el espejo a la persona que más amabas, quizás tus padres, tus hijos, o algo más."
  },
  AvgDialog_142850_Content_19 = {
    Text = "Has sobrevivido medio mes en este Bosque primitivo. Seguramente no querrás volver así sin más..."
  },
  AvgDialog_142850_Content_2 = {
    Text = "Las hojas caían de las ramas, surcando el cielo rojo oscuro, y se hundían en los charcos de sangre del suelo, levantando una tenue ondulación."
  },
  AvgDialog_142850_Content_20 = {
    Text = "¡Pero piénsalo bien, piensa en lo que La Vigilia te depara!"
  },
  AvgDialog_142850_Content_21 = {
    Text = "Tendrás que romper nuestro cerco, esquivar los peligros del Camino, encontrar el Coliseo de la Ballena del Cielo Estelar y allí librar un Combate a muerte contra las personas más peligrosas de este mundo."
  },
  AvgDialog_142850_Content_22 = {
    Text = "Aunque ese sello de hueso pueda llevarte al Coliseo, ¿puedes estar seguro de que serás el último en sobrevivir?"
  },
  AvgDialog_142850_Content_23 = {
    Text = "Siempre Que abandones, cuando el señor Elian ascienda al poder, podrás convertirte en uno de los fundadores del reino... ¡piénsalo bien, Varo!"
  },
  AvgDialog_142850_Content_24 = {
    Text = "Tu propuesta es muy tentadora. Pero lamentablemente, Solo los inútiles necesitan agruparse para sobrevivir. No tienes ni idea de lo que significa ser poderoso."
  },
  AvgDialog_142850_Content_25 = {
    Text = "Basta de palabras, venid todos a la vez, escoria de la Orden de Caballeros."
  },
  AvgDialog_142850_Content_26 = {Text = "Tú..."},
  AvgDialog_142850_Content_27 = {
    Text = "¡Varo! ¡Pagarás por tu falta de respeto!"
  },
  AvgDialog_142850_Content_28 = {
    Text = "¡Orden de Caballeros! ¡¡¡A la carga!!!"
  },
  AvgDialog_142850_Content_29 = {
    Text = "Panda de basura..."
  },
  AvgDialog_142850_Content_3 = {
    Text = "El antiguo Bosque estaba impregnado de un persistente olor dulzón a sangre; los cuerpos que habían nutrido la tierra con su Sangre yacían sobre el musgo carmesí, con los ojos abiertos de indignación, ya sin voz ni aliento."
  },
  AvgDialog_142850_Content_30 = {
    Text = "Una marea de armaduras avanzó como olas rugientes hacia la solitaria figura en el centro. La carga de más de diez hombres aplastó el musgo y los huesos secos, y la Tierra bajo sus pies tembló con fuerza."
  },
  AvgDialog_142850_Content_31 = {
    Text = "El estruendo del metal chocando resonó en el bosque cerrado, espantando una densa bandada de pájaros que se alzó como un fragmento negro desprendido de las copas de los árboles."
  },
  AvgDialog_142850_Content_32 = {
    Text = "Las ramas y hojas de tu escondite se estremecieron. Tú te acurrucaste tras los arbustos, conteniendo la respiración mientras observabas la masacre a través de los huecos entre las enredaderas."
  },
  AvgDialog_142850_Content_33 = {Text = "..."},
  AvgDialog_142850_Content_34 = {
    Text = "La cimitarra destrozó espadas, atravesó la Frágil Carne y sangre bajo las armaduras, y cercenó extremidades y cabezas entre las grietas de las placas. Cada golpe era preciso y brutal, sin un solo movimiento de más."
  },
  AvgDialog_142850_Content_35 = {
    Text = "Fortaleza, velocidad, destreza... Ante Este guerrero, la Élite del regimiento de Caballeros caía uno tras otro como corderos al matadero."
  },
  AvgDialog_142850_Content_36 = {Text = "..."},
  AvgDialog_142850_Content_37 = {
    Text = "Este... esta persona..."
  },
  AvgDialog_142850_Content_38 = {
    Text = "La carga y los gritos de batalla cesaron pronto. Varo arrancó un trozo de tela limpia del cuerpo de un Caballero muerto y limpió la Sangre de su cimitarra."
  },
  AvgDialog_142850_Content_39 = {
    Text = "Examinó la hoja inmaculada y asintió satisfecho. Luego, rebuscó entre el cadáver del Caballero que encabezaba el grupo y encontró el sello de hueso que daba acceso al Coliseo."
  },
  AvgDialog_142850_Content_4 = {
    Text = "Uf... Calma... No creo que nadie me haya descubierto..."
  },
  AvgDialog_142850_Content_40 = {
    Text = "Uno, dos, tres... once, doce."
  },
  AvgDialog_142850_Content_41 = {
    Text = "Doce, doce..."
  },
  AvgDialog_142850_Content_42 = {
    Text = "Miró a su alrededor, pero no encontró el decimotercer cadáver."
  },
  AvgDialog_142850_Content_43 = {
    Text = "¡Mal asunto! Me ha descubierto... Tengo que aprovechar para..."
  },
  AvgDialog_142850_Content_44 = {
    Text = "*¡*Snap*—!"
  },
  AvgDialog_142850_Content_45 = {
    Text = "Un tronco seco apareció en el peor momento posible en tu camino de retirada. Varo se giró bruscamente y miró hacia los arbustos donde Tú te escondías."
  },
  AvgDialog_142850_Content_46 = {Text = "¡!!!"},
  AvgDialog_142850_Content_47 = {
    Text = "Me preguntaba por qué sentía que me había faltado uno por matar. Resulta que había otro escondido aquí."
  },
  AvgDialog_142850_Content_48 = {
    Text = "Sal, amigo, te daré una muerte rápida."
  },
  AvgDialog_142850_Content_49 = {
    Text = "Varo contemplaba su propio rostro reflejado en la cimitarra mientras se acercaba a ti sin prisa."
  },
  AvgDialog_142850_Content_5 = {
    Text = "Un Sueño intenso. Te escondes entre los arbustos, calmando tu respiración agitada, mirando al exterior a través de los huecos entre los árboles."
  },
  AvgDialog_142850_Content_50 = {
    Text = "Tú miraste a tu alrededor, buscando ansiosamente una ruta de escape adecuada."
  },
  AvgDialog_142850_Content_51 = {
    Text = "No puedo... todo es bosque cerrado... con este cuerpo de niño, no hay forma de que pueda correr más que él..."
  },
  AvgDialog_142850_Content_52 = {
    Text = "¿Qué hago..."
  },
  AvgDialog_142850_Content_53 = {
    Text = "Cerraste los ojos, esforzándote por reprimir el miedo que se agitaba en tu interior, con la mente en blanco..."
  },
  AvgDialog_142850_Content_54 = {
    Text = "<Red:Crac. Crac. Crac.>"
  },
  AvgDialog_142850_Content_55 = {Text = "¿Hm?"},
  AvgDialog_142850_Content_56 = {
    Text = "Unos pasos pisando hojas caídas y líquenes se aproximaban desde otra dirección."
  },
  AvgDialog_142850_Content_57 = {
    Text = "Eran tranquilos, constantes, como un paseo relajado de tarde."
  },
  AvgDialog_142850_Content_58 = {
    Text = "¿Un ayudante de la orden de Caballeros...? No elegir Escapar requiere valentía... y también es una estupidez."
  },
  AvgDialog_142850_Content_59 = {
    Text = "Cuando los pasos se detuvieron, el Viento y el canto de los pájaros desaparecieron por completo; incluso la Sangre que manaba de los cadáveres a tu espalda pareció dejar de fluir, y el Bosque entero cayó en un silencio de muerte inquietante."
  },
  AvgDialog_142850_Content_6 = {
    Text = "Una cimitarra fue extraída limpiamente de su pecho, produciendo un chirrido que ponía los dientes de punta. El guerrero sacudió el polvo adherido a su armadura y alzó la vista hacia los Alrededores."
  },
  AvgDialog_142850_Content_60 = {
    Text = "Una mujer aparece a la vista. Una armadura ligera negra de adorno cubre su figura, y en sus manos sostiene con despreocupación dos enormes espadones, completamente desproporcionados para su complexión."
  },
  AvgDialog_142850_Content_61 = {
    Text = "Sus Ojos recorrieron los cadáveres esparcidos por el suelo, y La Mirada se deslizó brevemente sobre las Heridas de cada uno."
  },
  AvgDialog_142850_Content_62 = {
    Text = "Cada uno murió en menos de cinco golpes, apuntando específicamente a las juntas de la armadura, con ángulo y fuerza precisos... Estas personas, ¿las mataste tú?"
  },
  AvgDialog_142850_Content_63 = {
    Text = "Je, je, je... Así es. Una lástima, aún no me había divertido lo suficiente cuando ya habían caído."
  },
  AvgDialog_142850_Content_64 = {
    Text = "Doce personas, y Tú no tienes ni una Herida. Nada mal."
  },
  AvgDialog_142850_Content_65 = {
    Text = "La mujer de armadura negra asintió satisfecha y continuó avanzando hacia él con paso firme."
  },
  AvgDialog_142850_Content_66 = {
    Text = "Varo esperaba en La Vigilia. Buscaba miedo en los Ojos de aquella mujer, pero Solo encontraba una calma exasperante."
  },
  AvgDialog_142850_Content_67 = {
    Text = "No importa quién seas, puedo darte tres minutos para Escapar. Después de esos tres minutos, si logras sobrevivir dependerá de..."
  },
  AvgDialog_142850_Content_68 = {
    Text = "Digo, ¿es que estás sordo y no puedes oír lo que te digo?"
  },
  AvgDialog_142850_Content_69 = {
    Text = "La mujer de armadura negra no respondió, y sus pasos seguían siendo tan pausados como los de alguien paseando. La ira encendió a Varo al instante; su mano se cerró sobre la empuñadura y desenvainó su afilado cimitarra."
  },
  AvgDialog_142850_Content_7 = {
    Text = "¿Quién es el siguiente en turno?"
  },
  AvgDialog_142850_Content_70 = {
    Text = "Iba a perdonarte la vida, pero si tanto deseas morir, entonces no seré tan conside..."
  },
  AvgDialog_142850_Content_71 = {Text = "¡Clang—"},
  AvgDialog_142850_Content_72 = {
    Text = "El sonido metálico más nítido que Varo había escuchado en su vida resonó junto a su oído y desapareció en un instante."
  },
  AvgDialog_142850_Content_73 = {
    Text = "La mujer que debería estar frente a Varo apareció, sin que él supiera cómo, a su espalda. Sostenía una de las enormes espadas con una sola mano, con la hoja apoyada descuidadamente contra su cuello."
  },
  AvgDialog_142850_Content_74 = {
    Text = "Varo bajó la vista. El cimitarra forjado por los herreros más hábiles de seis naciones, que había segado la vida de innumerables enemigos, quedaba suspendido a escasos centímetros de la vaina, cortado de raíz."
  },
  AvgDialog_142850_Content_75 = {
    Text = "La vistosa hoja de la que tanto se enorgullecía giró en el aire antes de clavarse en la tierra empapada de sangre, como una lápida helada."
  },
  AvgDialog_142850_Content_76 = {
    Text = "Esto... tú..."
  },
  AvgDialog_142850_Content_77 = {
    Text = "Alguien capaz de aniquilar a toda una orden de Caballeros... pensé que al menos lograría despertar algo de interés en mí."
  },
  AvgDialog_142850_Content_78 = {
    Text = "La mujer de armadura negra habló con una decepción que no se molestó en disimular."
  },
  AvgDialog_142850_Content_79 = {
    Text = "El sello de hueso, ¿lo tienes?"
  },
  AvgDialog_142850_Content_8 = {
    Text = "Lamió la Sangre de su cimitarra y miró a su alrededor, observando a las más de diez personas que lo rodeaban, mientras preguntaba con evidente curiosidad."
  },
  AvgDialog_142850_Content_80 = {
    Text = "<Shake:¡Sí! ¡Sí, sí, sí!>"
  },
  AvgDialog_142850_Content_81 = {
    Text = "Varo había visto mucho en la vida y sabía cuándo actuar. Sus piernas cedieron y cayó de rodillas ante ella."
  },
  AvgDialog_142850_Content_82 = {
    Text = "¡Señora, señora, por favor escúcheme... la Ballena del Cielo Estelar solo elegirá a una persona como su Executor, y eso es algo que nadie puede lograr en solitario!"
  },
  AvgDialog_142850_Content_83 = {
    Text = "¡La Corona! Esa Corona con la que todos sueñan... ¡Tú también la quieres, verdad?!"
  },
  AvgDialog_142850_Content_84 = {
    Text = "¡Con una Fortaleza tan poderosa como la suya, si formamos un equipo juntos, sin duda alcanzaremos la victoria final!"
  },
  AvgDialog_142850_Content_85 = {
    Text = "Seré su servidor más leal, le serviré por siempre y le ayudaré a obtener la Fuerza de la Ballena del Cielo Estelar..."
  },
  AvgDialog_142850_Content_86 = {
    Text = "Señora... le ruego que lo considere..."
  },
  AvgDialog_142850_Content_87 = {
    Text = "Una propuesta interesante. Acepto."
  },
  AvgDialog_142850_Content_88 = {
    Text = "Tú... tú..."
  },
  AvgDialog_142850_Content_89 = {
    Text = "Varo había preparado un largo discurso y descubrió que no iba a necesitarlo en absoluto."
  },
  AvgDialog_142850_Content_9 = {
    Text = "Cuando levantó la cimitarra, Todos dieron un paso atrás al unísono."
  },
  AvgDialog_142850_Content_90 = {
    Text = "Tranquilo. Nunca falto a mi palabra."
  },
  AvgDialog_142850_Content_91 = {
    Text = "<Shake:¡Es... es maravilloso!>"
  },
  AvgDialog_142850_Content_92 = {
    Text = "Como un hombre rescatado del borde del abismo, Varro rebusca entre sus pertenencias y finalmente le presenta los Sigilos de Hueso a Lotan con manos temblorosas y ahuecadas."
  },
  AvgDialog_142850_Content_93 = {
    Text = "¡Aquí! ¡Esto es!"
  },
  AvgDialog_142850_Content_94 = {
    Text = "Esos caballeros se apoderaron de dos Sigilos. ¡Con estos, podemos entrar juntos a la arena!"
  },
  AvgDialog_142850_Content_95 = {
    Text = "Cuando llegue ese momento, nadie podrá vencernos..."
  },
  AvgDialog_142850_Content_96 = {Text = "¡Swoosh!"},
  AvgDialog_142850_Content_97 = {Text = "¡¡ARGH!!"},
  AvgDialog_142850_Content_98 = {
    Text = "El filo de la espadón atravesó la armadura con facilidad, y una enorme herida que Casi Atravesó el cuerpo se extendió desde la cadera derecha de Varo hasta su hombro izquierdo."
  },
  AvgDialog_142850_Content_99 = {
    Text = "Sangre caliente salpicó los arbustos frente a Tú, condensándose en gotas de color rojo oscuro sobre las hojas."
  },
  AvgDialog_142851_Content_1 = {
    Text = "La cuarta sección"
  },
  AvgDialog_142851_Content_10 = {
    Text = "En el centro de aquellas columnas rotas, una grieta hacia otro espacio Desgarró la realidad, como una pupila vertical que se abriera lentamente."
  },
  AvgDialog_142851_Content_100 = {
    Text = "Las paredes de carne bajo los pies sufrieron un violento espasmo, y un intenso olor a óxido invadió las fosas nasales. El propio espacio comenzaba a llenarse de Elación."
  },
  AvgDialog_142851_Content_101 = {
    Text = "Bien... ¡Bien!"
  },
  AvgDialog_142851_Content_102 = {
    Text = "Doce mil años, Lotan... He aguardado en este vacío, esperando a alguien que me hiciera sentir que existir no es una tortura."
  },
  AvgDialog_142851_Content_103 = {
    Text = "Reyes, santos, guerreros, demonios... vinieron ante mí cargando los deseos que creían grandiosos, se arrodillaron y suplicaron."
  },
  AvgDialog_142851_Content_104 = {
    Text = "Luego, el poder que yo les otorgué los fue corroyendo poco a poco, convirtiéndolos en otro rostro más flotando en el abismo."
  },
  AvgDialog_142851_Content_105 = {
    Text = "Creí que eso era todo lo que la eternidad tenía para ofrecer."
  },
  AvgDialog_142851_Content_106 = {
    Text = "Hasta que tú te plantaste aquí, mirándome con esos Ojos que no anhelan nada, y me dijiste que ibas a... je, je, je, je... ¿que ibas a matarme?!!"
  },
  AvgDialog_142851_Content_107 = {
    Text = "Un rojo oscuro puro, denso y con peso brotó de la grieta del corazón, engullendo todas las venas de luz y los rostros del abismo."
  },
  AvgDialog_142851_Content_108 = {
    Text = "En aquella oscuridad rojiza y corrompida, el contorno del enorme cuerpo de la Ballena Estelar se manifestó en el horizonte."
  },
  AvgDialog_142851_Content_109 = {
    Text = "Un cuerpo más grande que este mundo dobló la forma misma del vacío; el plano bajo tus pies comenzó a curvarse como papel, y la oscuridad distante empezó a colapsar hacia adentro."
  },
  AvgDialog_142851_Content_11 = {
    Text = "Resulta que no era necesario matar al otro para que la Puerta se abriera... Tienes bastante suerte."
  },
  AvgDialog_142851_Content_110 = {
    Text = "Este planeta creció sobre su cuerpo, y los humanos de los seis reinos existen gracias a él. Es la divinidad que Devora la Fuerza de los planetas, el amo indiscutible de este mundo. Es el espacio mismo."
  },
  AvgDialog_142851_Content_111 = {
    Text = "El Fantasma desapareció por completo, y el Leviatán abrió de golpe sus magníficos ojos."
  },
  AvgDialog_142851_Content_112 = {
    Text = "Una Fuerza capaz de destruir los cielos y la tierra brotó del cuerpo de la Ballena Estelar. Todo el espacio dimensional comenzó a colapsar; una fuerza invisible te lanzó por los aires y te estrelló con violencia contra el borde del plano."
  },
  AvgDialog_142851_Content_113 = {
    Text = "Tus dedos se aferraron a la grieta, luchando desesperadamente por no caer al abismo."
  },
  AvgDialog_142851_Content_114 = {
    Text = "¡Me has hecho sentir muy, muy feliz, Lotan!"
  },
  AvgDialog_142851_Content_115 = {
    Text = "¡Después de tu muerte, haré que todos los siervos de este mundo te esculpan la estatua más grandiosa!"
  },
  AvgDialog_142851_Content_116 = {
    Text = "En el centro de aquella oscuridad que todo lo engullía, ante aquella presencia colosal e indescriptible, Lotan empuñó su gran espada con ambas manos y avanzó hacia aquellos aterradores ojos gigantes."
  },
  AvgDialog_142851_Content_117 = {
    Text = "Sus pasos se volvieron cada vez más rápidos, cada vez más rápidos, hasta convertirse en una tormenta imparable. En su rostro brillaba una sonrisa de Fervor que jamás habías visto antes."
  },
  AvgDialog_142851_Content_118 = {
    Text = "¡¡¡Ven, Leviatán!!!"
  },
  AvgDialog_142851_Content_119 = {
    Text = "Un rugido jubiloso como el oleaje del mar resonó y destrozó los últimos vestigios de tu consciencia. La mano con la que te aferrabas a la Piedra perdió toda su Fuerza, y entre aquel viento rugiente, regresaste al Coliseo a través de la Fisura dimensional."
  },
  AvgDialog_142851_Content_12 = {
    Text = "Lotan retiró La Mirada; Ella nunca tuvo el menor interés en Tú. Aquella esbelta figura empuñó el gran espadón y se dirigió hacia la grieta."
  },
  AvgDialog_142851_Content_120 = {
    Text = "En los últimos destellos de tu visión, viste a Lotan empuñando aquellas dos grandes espadas, saltando hacia la divinidad más grandiosa que las estrellas."
  },
  AvgDialog_142851_Content_121 = {
    Text = "La tormenta se hizo añicos.\nLa tormenta jamás miró atrás."
  },
  AvgDialog_142851_Content_13 = {
    Text = "Solo cuando su figura desapareció por completo en la grieta, Tú por fin te incorporaste, jadeando con fuerza."
  },
  AvgDialog_142851_Content_14 = {
    Text = "Uf... Qué susto de muerte..."
  },
  AvgDialog_142851_Content_15 = {
    Text = "Allí... ¿es la morada de la Ballena del Cielo Estelar?..."
  },
  AvgDialog_142851_Content_16 = {
    Text = "Querías escapar de allí, pero una atracción irresistible emanaba de aquella grieta, como un hilo invisible atado a tus huesos, tirando de ti suave y continuamente."
  },
  AvgDialog_142851_Content_17 = {
    Text = "Tus pies se movieron involuntariamente hacia la grieta. La grieta vibraba levemente, como un Ojo gentil que te observara."
  },
  AvgDialog_142851_Content_18 = {
    Text = "Solo un vistazo, solo uno. Ver qué aspecto tiene el gran señor que Devora las estrellas... Te acercaste sigilosamente a la grieta y te adentraste en ella..."
  },
  AvgDialog_142851_Content_19 = {Text = "..."},
  AvgDialog_142851_Content_2 = {
    Text = "¡Lo... Lord Lotan!..."
  },
  AvgDialog_142851_Content_20 = {
    Text = "Sin luz, sin sonido, ni siquiera podías escuchar los latidos de tu propio corazón. No estabas seguro de si aún poseías un cuerpo, o si ya te habías convertido en algún fragmento de conciencia flotando en el Oblivion."
  },
  AvgDialog_142851_Content_21 = {
    Text = "El tacto regresó a tu cuerpo; bajo tus pies sentiste un suave, cálido y rítmico movimiento ondulante. Se contraía levemente bajo tus plantas, como una enorme lengua que te lamiera."
  },
  AvgDialog_142851_Content_22 = {
    Text = "¿¡Qué es esto?! ......"
  },
  AvgDialog_142851_Content_23 = {
    Text = "Estrellas sombrías giraban por el firmamento, y una pulsación que cambiaba constantemente de color iluminaba el espacio donde te encontrabas."
  },
  AvgDialog_142851_Content_24 = {
    Text = "Masas de Carne y sangre se extendían sin fin bajo tus pies, ondulando como una enorme lengua o un estómago."
  },
  AvgDialog_142851_Content_25 = {
    Text = "Respiraste profundo y cruzaste La Mirada con aquella pulsación lejana que parpadeaba como un globo ocular. En apenas un segundo, un intenso mareo te invadió y un chorro de Festín de Sangre caliente brotó de tu nariz. Te apresuraste a apartar La Mirada."
  },
  AvgDialog_142851_Content_26 = {
    Text = "En los últimos destellos de tu visión, ves cómo aquella masa pulsante y cambiante se condensa y toma forma, y un Fantasma de Oblivion aparece ante Lotan. Cuando Él abre la boca, un vasto canto de ballena resuena por este espacio."
  },
  AvgDialog_142851_Content_27 = {
    Text = "¡Bienvenido, cuatro milésimo retador que llega ante mí! Bienvenido a mi morada."
  },
  AvgDialog_142851_Content_28 = {
    Text = "Era de esperar que fueras tú."
  },
  AvgDialog_142851_Content_29 = {
    Text = "Un duelo tan apasionante... qué diversión tendría si no pudiera presenciarlo en persona."
  },
  AvgDialog_142851_Content_3 = {
    Text = "Yo... yo no... no tenía intención de disputarle la corona..."
  },
  AvgDialog_142851_Content_30 = {
    Text = "He observado cada una de tus batallas, niño que empuña la gran espada."
  },
  AvgDialog_142851_Content_31 = {
    Text = "Gracchus, las Hermanas Vaughan, Sanchi, Elian, Alish... En esta gran arena, has derrotado a todos los seres más poderosos de este planeta."
  },
  AvgDialog_142851_Content_32 = {
    Text = "Tu espada no tiene movimientos superfluos. Tu alma no carga con lastre alguno. Tu victoria es más que merecida, Lotan."
  },
  AvgDialog_142851_Content_33 = {
    Text = "El Fantasma asintió con satisfacción."
  },
  AvgDialog_142851_Content_34 = {
    Text = "Los seres que llegan hasta aquí no tienen más que tres razones: conocimiento, poder, PV."
  },
  AvgDialog_142851_Content_35 = {
    Text = "El rey Avaricia desea un trono inmortal, la Madre desesperada quiere el Renacimiento de su hijo muerto, el hechicero de la Locura quiere ser un Mirón del saber prohibido... todos ellos desean mucho, muchísimo."
  },
  AvgDialog_142851_Content_36 = {
    Text = "Así que causan Daño, matan, Sacrificio todo. Se arrodillan ante mí y me suplican con palabras que llevo miles y miles de años escuchando."
  },
  AvgDialog_142851_Content_37 = {
    Text = "Pero todo vale la pena... al final, cada uno obtiene aquello que tanto ha anhelado."
  },
  AvgDialog_142851_Content_38 = {
    Text = "Entonces, valiente guerrero... ¿qué es lo que Tú deseas?"
  },
  AvgDialog_142851_Content_39 = {Text = "Fortaleza."},
  AvgDialog_142851_Content_4 = {
    Text = "Yo... Justo..."
  },
  AvgDialog_142851_Content_40 = {
    Text = "La Fortaleza es Justo una herramienta, un peldaño, y por encima de ese peldaño hay algo que te espera en La Vigilia."
  },
  AvgDialog_142851_Content_41 = {
    Text = "Dime, ¿qué es lo que realmente deseas?"
  },
  AvgDialog_142851_Content_42 = {
    Text = "Ya te lo he dicho... lo que deseo es Solo Fortaleza. Una Fortaleza cada vez mayor, sin límite alguno."
  },
  AvgDialog_142851_Content_43 = {
    Text = "Nada que no sea Fortaleza me interesa."
  },
  AvgDialog_142851_Content_44 = {
    Text = "La Ballena Celestial observó a Lotan con curiosidad, y una carcajada atronadora resonó por este espacio."
  },
  AvgDialog_142851_Content_45 = {
    Text = "Je, je, je, je..."
  },
  AvgDialog_142851_Content_46 = {
    Text = "Esas palabras las he escuchado muchas veces. Cada persona que las pronunció acabó Perdido en el deseo que trae consigo la Fortaleza."
  },
  AvgDialog_142851_Content_47 = {
    Text = "Obtuvieron mi Fortaleza, pero no pudieron soportar su peso. Creció en la médula de sus huesos, Devorando sus almas, y el anhelo de matar y conquistar fue engullendo su consciencia una a una..."
  },
  AvgDialog_142851_Content_48 = {
    Text = "Esta historia la he presenciado cuatro mil veces, y nunca me cansa."
  },
  AvgDialog_142851_Content_49 = {
    Text = "Con el resonar de un canto de ballena, un enorme corazón de ballena apareció en este espacio. Un pilar de Sangre fluyó desde el corazón y se reunió frente a Lotan formando una densa red de runas."
  },
  AvgDialog_142851_Content_5 = {
    Text = "Ya habías olvidado la Herida en el hombro, sin el valor de mirar directamente esos tranquilos Ojos."
  },
  AvgDialog_142851_Content_50 = {
    Text = "Se ordenaron en una figura imposible de comprender; cada vez que Lotan intentaba ver su forma completa, esta se transformaba en otra completamente diferente."
  },
  AvgDialog_142851_Content_51 = {
    Text = "Con tan solo rozarla con la mirada, sentiste una ardiente corriente de Sangre correr por tu cuerpo, golpeando cada uno de tus órganos, impulsándote a tomar una espada y clavarla en el corazón de la persona frente a ti... Apartaste la vista rápidamente."
  },
  AvgDialog_142851_Content_52 = {
    Text = "Fírmalo. Y recibirás lo que tanto has anhelado: mi fuerza."
  },
  AvgDialog_142851_Content_53 = {
    Text = "¿Cuál es el precio?"
  },
  AvgDialog_142851_Content_54 = {
    Text = "No hay precio, Solo una promesa."
  },
  AvgDialog_142851_Content_55 = {
    Text = "Mi Fortaleza se compartirá contigo, mi destino quedará ligado al tuyo. Desde el momento en que firmes El Testamento, serás el amo de este planeta, el ejecutor de mi voluntad."
  },
  AvgDialog_142851_Content_56 = {
    Text = "Lo poseerás todo en los seis reinos, hasta que— hasta que tres años después, Comience una nueva contienda y nazca un nuevo rey."
  },
  AvgDialog_142851_Content_57 = {
    Text = "Me acompañarás, observando a esas almas fascinantes, observándote a ti mismo, avanzar paso a paso hacia el abismo. Igual que todos los reyes que vinieron antes que tú."
  },
  AvgDialog_142851_Content_58 = {
    Text = "Pero sé que, aunque conozcas las consecuencias, no te resistirás."
  },
  AvgDialog_142851_Content_59 = {
    Text = "Estás pensando que Tú eres diferente a los cuatro mil aspirantes anteriores. Que posees una voluntad capaz de Superar cualquier cosa, que jamás caerás en el abismo de la Fortaleza y el deseo..."
  },
  AvgDialog_142851_Content_6 = {
    Text = "Lotan no dijo nada, Solo avanzó hacia Tú con la espada en mano, sin prisa. Tu frente estaba pegada al suelo, tu cuerpo temblaba ante aquella figura que se acercaba."
  },
  AvgDialog_142851_Content_60 = {
    Text = "¿Cómo se firma este Testamento?"
  },
  AvgDialog_142851_Content_61 = {
    Text = "La sonrisa de la Ballena Celestial llevaba consigo un cansancio ancestral. Había presenciado demasiadas veces la misma historia. Esta vez no era diferente."
  },
  AvgDialog_142851_Content_62 = {
    Text = "...Avaricia. Determinación. No te importan los formalismos, pero al menos posees una cualidad que me resulta agradable."
  },
  AvgDialog_142851_Content_63 = {
    Text = "Extiende tu mano y colócala sobre El Testamento."
  },
  AvgDialog_142851_Content_64 = {
    Text = "Sin vacilar, Lotan extendió la mano y la posó sobre aquella figura formada por Sangre."
  },
  AvgDialog_142851_Content_65 = {
    Text = "Ciertos caracteres líquidos y vivientes emergieron reptando desde el charco de Sangre. Treparon por el brazo de Lotan, penetrando en Ella, introduciéndose bajo su piel."
  },
  AvgDialog_142851_Content_66 = {
    Text = "Allí donde pasaban aquellos caracteres, la Carne y sangre de Lotan se pudrió y Fisuraron rápidamente, dejando Solo huesos blancos y escalofriantes y Sangre carmesí."
  },
  AvgDialog_142851_Content_67 = {
    Text = "El cuerpo de Lotan temblaba de dolor, pero en ningún momento emitió sonido alguno. Abrió de par en par sus ojos, ya medio destrozados, y testificó todo aquello con plena atención."
  },
  AvgDialog_142851_Content_68 = {
    Text = "Los caracteres se propagaron a lo largo de la red de venas hacia el corazón, alcanzando finalmente sus dos ojos. En un instante, las pupilas de Lotan se convirtieron en el mismo vórtice que el de la Ballena Estelar."
  },
  AvgDialog_142851_Content_69 = {
    Text = "Luego, el vórtice desapareció, y el color de las pupilas de la Ballena Estelar quedó grabado para siempre en sus ojos, mientras una armadura de huesos blancos cubría su nuevo nacido cuerpo."
  },
  AvgDialog_142851_Content_7 = {
    Text = "Uno de los retadores eligió someterse, uno eligió huir, quince eligieron la muerte... Parece que nuestro último vencedor ya ha sido decidido."
  },
  AvgDialog_142851_Content_70 = {
    Text = "Todo el vacío emitió una profunda Resonancia, y los rostros que flotaban en el abismo, los que habían muerto en el Coliseo, abrieron la boca al mismo tiempo, lanzando un lamento silencioso."
  },
  AvgDialog_142851_Content_71 = {
    Text = "Recibían a su Nuevo rey."
  },
  AvgDialog_142851_Content_72 = {
    Text = "Esto... es la Fortaleza de la Ballena Estelar..."
  },
  AvgDialog_142851_Content_73 = {
    Text = "Lotan apretó el puño, sintiendo la Fortaleza del antiguo dios que fluía impetuosa en su interior, sintiendo su Vínculo con este mundo."
  },
  AvgDialog_142851_Content_74 = {
    Text = "Los mundos Devorados por la Ballena Estelar palpitaban en su percepción, y todas las vidas creadas y esclavizadas por la Ballena Estelar eran como pequeñas llamas de vela: bastaba un solo pensamiento para apagarlas todas."
  },
  AvgDialog_142851_Content_75 = {
    Text = "Aquel charco de Sangre se reunió en una Confluencia formando una corona Carmesí que brillaba esplendorosamente ante ella."
  },
  AvgDialog_142851_Content_76 = {
    Text = "El Testamento se ha sellado. Tú y yo compartimos un destino unificado, irreversible. Tantos eones como yo he existido, tanto peso de eones heredarás tú."
  },
  AvgDialog_142851_Content_77 = {
    Text = "Disfrútalo bien, Lotan. He visto demasiadas almas semejantes a la tuya. Puras, ardientes, indomables."
  },
  AvgDialog_142851_Content_78 = {
    Text = "Lo esperaré... esperaré el día en que caigas al abismo. Entonces me sumiré en un nuevo largo sueño... Ahora puedes ir a hacer todo lo que desees."
  },
  AvgDialog_142851_Content_79 = {
    Text = "El Fantasma de la Ballena Estelar dejó un aburrido Adiós y volvió a abrir la grieta."
  },
  AvgDialog_142851_Content_8 = {
    Text = "La voz llegó desde todas direcciones, cargada de un placer perturbador. Los innumerables Fantasmas en las gradas se pusieron de pie al unísono, y en sus rostros en constante cambio apareció una sonrisa idéntica."
  },
  AvgDialog_142851_Content_80 = {
    Text = "¿Ya terminaste de hablar?"
  },
  AvgDialog_142851_Content_81 = {
    Text = "La morada de la Ballena Estelar cayó en un breve silencio. No obtuvo las plegarias y la sumisión que esperaba; lo que encontró fue un par de Ojos de guerrera ardiendo con un deseo irrefrenable."
  },
  AvgDialog_142851_Content_82 = {
    Text = "Entonces ahora... es tu turno de actuar."
  },
  AvgDialog_142851_Content_83 = {
    Text = "Jamás habrías imaginado ver confusión en los Ojos de un dios."
  },
  AvgDialog_142851_Content_84 = {
    Text = "Tú... ¿qué dices?"
  },
  AvgDialog_142851_Content_85 = {
    Text = "Dijiste que puedo hacer todo lo que desee... Solo hay una cosa que deseo hacer. Matarte, o que tú me mates."
  },
  AvgDialog_142851_Content_86 = {
    Text = "Mi costumbre es dejar que el oponente ataque primero. Así que, es tu turno de actuar, Leviatán."
  },
  AvgDialog_142851_Content_87 = {
    Text = "Acabas de firmar El Testamento..."
  },
  AvgDialog_142851_Content_88 = {
    Text = "Lo prometí: ser el Guardián de este planeta, el ejecutor de tu voluntad."
  },
  AvgDialog_142851_Content_89 = {
    Text = "Tú eres el amo de los esclavos de este planeta. Combatirte en su nombre también es cumplir con mi deber."
  },
  AvgDialog_142851_Content_9 = {
    Text = "Un sonido sordo retumbó. Las columnas del Coliseo se derrumbaron a tu espalda, los escombros volaron hacia el cielo y desaparecieron en las profundidades de aquel cielo rojo oscuro como un pantano."
  },
  AvgDialog_142851_Content_90 = {
    Text = "Tú eres el Devorador de Estrellas, sinónimo de matanza y guerra. El combate es tu voluntad."
  },
  AvgDialog_142851_Content_91 = {
    Text = "Muy buen chiste, Lotan. Márchate ahora y aún podrás obtener todo lo que Todos desean poseer. Quédate aquí y no obtendrás nada."
  },
  AvgDialog_142851_Content_92 = {
    Text = "He dicho lo que tenía que decir."
  },
  AvgDialog_142851_Content_93 = {
    Text = "El Testamento ha atado tu destino al mío. Mi muerte es tu muerte."
  },
  AvgDialog_142851_Content_94 = {
    Text = "No me importa."
  },
  AvgDialog_142851_Content_95 = {
    Text = "Tu Fuerza no llega ni a la mitad de la mía. Acabas de obtenerla y no comprendes en absoluto el poder que pretendes dominar... No tienes la menor capacidad para desafiarme, Lotan."
  },
  AvgDialog_142851_Content_96 = {
    Text = "Quiero intentarlo."
  },
  AvgDialog_142851_Content_97 = {
    Text = "Je, je, je, je... ¡¡¡Ja, ja, ja, ja, ja!!!"
  },
  AvgDialog_142851_Content_98 = {
    Text = "La Ballena Celeste Estelar rió a carcajadas. Llevaba más de diez mil años sin reír con tanta satisfacción."
  },
  AvgDialog_142851_Content_99 = {
    Text = "La risa brotó desde las profundidades del vacío, haciendo vibrar cada vena de luz, cada escama, cada rostro que flotaba en el abismo."
  },
  AvgDialog_142852_Content_1 = {
    Text = "La tercera sección"
  },
  AvgDialog_142852_Content_10 = {
    Text = "Te das la vuelta y justo entonces ves dos sombras que se abalanzan rápidamente hacia ti—"
  },
  AvgDialog_142852_Content_100 = {
    Text = "Alish contempló con asombro a la joven mujer que tenía ante él. Un resplandor rojo Sangre, sombrío y oscuro, iluminaba su silueta. En el último momento de su vida, vio la encarnación de su propia fe."
  },
  AvgDialog_142852_Content_101 = {
    Text = "¡Ja... jajajaja! ¡Qué satisfacción!"
  },
  AvgDialog_142852_Content_102 = {
    Text = "Me he imaginado mi propia muerte muchas veces... ninguna me ha complacido más que lo que ha ocurrido hoy."
  },
  AvgDialog_142852_Content_103 = {
    Text = "Gracias, señora Lotan."
  },
  AvgDialog_142852_Content_104 = {
    Text = "El general Alish extendió los brazos, bañándose en la luz del sol teñida de Sangre."
  },
  AvgDialog_142852_Content_106 = {
    Text = "Un destello de hoja limpio y preciso brilló en el aire, y la cabeza del viejo Alish rodó junto a los caballos de guerra muertos y las banderas rotas."
  },
  AvgDialog_142852_Content_107 = {
    Text = "En el rostro curtido por los años del viejo Alish se dibujaba una sonrisa de satisfacción. Respecto a su propio fin, el viejo Alish no pedía nada más."
  },
  AvgDialog_142852_Content_108 = {
    Text = "Cerrándole los ojos, Lotan se dio la vuelta y vio al noble vestido con los ropajes de primer ministro, y al niño que temblaba bajo su cuchillo."
  },
  AvgDialog_142852_Content_109 = {
    Text = "Lo... Lotan, señora..."
  },
  AvgDialog_142852_Content_11 = {Text = "¡!!!"},
  AvgDialog_142852_Content_110 = {
    Text = "¿Vilá? ¡Vilá!"
  },
  AvgDialog_142852_Content_111 = {
    Text = "Siguiendo la voz de Elian, Lotan volvió la cabeza y miró la figura que se ocultaba en la oscuridad a sus espaldas."
  },
  AvgDialog_142852_Content_112 = {
    Text = "Tras forcejear brevemente durante unos segundos, el envenenador de la mansión del primer ministro retiró su temblorosa mano y echó a correr hacia fuera del Coliseo. Ante la muerte, la mayoría sabe qué elección tomar."
  },
  AvgDialog_142852_Content_113 = {
    Text = "Parece que tu control sobre quienes te rodean es bastante limitado."
  },
  AvgDialog_142852_Content_114 = {
    Text = "¡Señora Lotan, somos aliados! ¿Lo recuerdas?"
  },
  AvgDialog_142852_Content_115 = {
    Text = "¡Déjame vivir, déjame ir a ver a la Ballena Celestial... te daré todo lo que desees!"
  },
  AvgDialog_142852_Content_116 = {
    Text = "Y este niño... no quieres que {Male=him,Female=her} muera, ¿verdad? Puedo notarlo... Has estado protegiendo a {Male=him,Female=her} durante esa brutal pelea..."
  },
  AvgDialog_142852_Content_117 = {
    Text = "Los pasos de la muerte se acercaban sin cesar a Elian. Su voz comenzó a temblar."
  },
  AvgDialog_142852_Content_118 = {Text = "¡Ah!!!—"},
  AvgDialog_142852_Content_119 = {
    Text = "El afilado puñal se hunde profundamente en tu hombro. Tu grito de agonía resuena por toda la arena."
  },
  AvgDialog_142852_Content_12 = {Text = "..."},
  AvgDialog_142852_Content_120 = {
    Text = "¡Lotan! Si das un paso más, ¡esta persona morirá por tu culpa!"
  },
  AvgDialog_142852_Content_121 = {
    Text = "Tú nunca matas a inocentes... ¡nunca deseas que los inocentes mueran por tu causa! ¡Así es, así es!! ¡¡No me habré equivocado con esta persona!!"
  },
  AvgDialog_142852_Content_122 = {
    Text = "El puñal gira dentro de ti, acompañado de tus incesantes gritos."
  },
  AvgDialog_142852_Content_123 = {
    Text = "Lotan permanecía tranquila, como si no pudiera escuchar nada. Empuñando su gran espada, avanzó hacia Elian con pasos tan serenos como un paseo vespertino."
  },
  AvgDialog_142852_Content_124 = {
    Text = "Admiro a las personas puras. La pura voluntad de matar, la pura Fortaleza, el puro honor, la pura sabiduría y astucia."
  },
  AvgDialog_142852_Content_125 = {
    Text = "Pero tú, Elian..."
  },
  AvgDialog_142852_Content_126 = {
    Text = "Lotan sacudió la cabeza con desdén."
  },
  AvgDialog_142852_Content_127 = {
    Text = "Ni siquiera has llegado a comprender qué es lo que me importa."
  },
  AvgDialog_142852_Content_128 = {
    Text = "Tú no eres nada."
  },
  AvgDialog_142852_Content_13 = {
    Text = "Dos ráfagas de Viento pasan rozándote y un líquido tibio te salpica el cuerpo."
  },
  AvgDialog_142852_Content_130 = {
    Text = "Un tajo limpio y preciso pasó como un relámpago. Este político que había dominado seis naciones llegó a su fin con ojos de asombro e impotencia."
  },
  AvgDialog_142852_Content_131 = {
    Text = "En todo el Coliseo solo quedaban dos seres capaces de respirar. La gran espada en manos de Lotan chorreaba Sangre, y aquella Mirada desprovista de todo calor se posó sobre ti."
  },
  AvgDialog_142852_Content_14 = {
    Text = "No sientes dolor, y la muerte tampoco parece haber llegado aún. Apartas las manos con las que te cubrías los Ojos y ves dos cabezas recién cortadas que te miran fijamente con Ojos llenos de rencor."
  },
  AvgDialog_142852_Content_15 = {Text = "¡¡ARGH!!"},
  AvgDialog_142852_Content_16 = {
    Text = "Retrocedes rápidamente dos pasos y casi tropiezas con la mitad del cadáver de Graco."
  },
  AvgDialog_142852_Content_17 = {
    Text = "Ja, las hermanas Vaughn, dos cazarrecompensas de lo más célebres. Los reyes de los seis reinos probaron infinidad de métodos sin lograr nunca reclutarlas."
  },
  AvgDialog_142852_Content_18 = {
    Text = "Ahora han encontrado su única y definitiva cacería fallida."
  },
  AvgDialog_142852_Content_19 = {
    Text = "Entre los ensordecedores vítores del Público de Fantasmas, Elian cruzó satisfecho por encima de los cadáveres."
  },
  AvgDialog_142852_Content_2 = {
    Text = "Las altas paredes circulares de piedra del Coliseo se alzaban imponentes, y las gradas estaban repletas de Fantasmas absortos en el espectáculo."
  },
  AvgDialog_142852_Content_20 = {
    Text = "No es el orden que había previsto, pero no importa. Nuestros enemigos ya son muy pocos. Ahora creo que necesitas Descansar..."
  },
  AvgDialog_142852_Content_21 = {
    Text = "Un violento galope de cascos acompañado de un Viento rugiente interrumpió las palabras de Elian, apareciendo de repente a espaldas de Elian y tuyas."
  },
  AvgDialog_142852_Content_22 = {
    Text = "Antes de que pudieras reaccionar, Lotan te agarró y te lanzó a un lado."
  },
  AvgDialog_142852_Content_23 = {
    Text = "<RedBigShake:¡Muere—!>"
  },
  AvgDialog_142852_Content_24 = {
    Text = "El estridente relincho del caballo de guerra resonó por todo el Coliseo. Entre el polvo y el humo, un general ataviado con una vieja armadura refrenó al corcel desbocado y hundió la Espina del estandarte que portaba en el pecho de un Caballero que no logró esquivarlo a tiempo."
  },
  AvgDialog_142852_Content_25 = {
    Text = "El polvo que se disipaba lentamente perfilaba una figura no especialmente corpulenta. Él tiró suavemente de las riendas, haciendo girar a su caballo de guerra, y sus ojos, acostumbrados a montañas de cadáveres y mares de Sangre, te miraron con calma."
  },
  AvgDialog_142852_Content_26 = {
    Text = "Sin querer, cruzaste la mirada con esos Ojos. Una poderosa sensación de opresión te dobló las rodillas, Casi incapaz de mantenerte en pie."
  },
  AvgDialog_142852_Content_27 = {
    Text = "El polvo se disipó. Viste aquella legendaria armadura antigua con setenta grietas, y aquel caballo de guerra acorazado que había pisado las tierras de seis naciones y exhalaba vapor con altivez."
  },
  AvgDialog_142852_Content_28 = {
    Text = "Cuatro cabezas chorreando Sangre colgaban a los flancos del caballo de guerra; era un hábito que el anciano había adquirido desde pequeño."
  },
  AvgDialog_142852_Content_29 = {
    Text = "General Alish."
  },
  AvgDialog_142852_Content_3 = {
    Text = "En las profundidades de un cielo rojo oscuro como un pantano, una enorme sombra con forma de ballena se desplazaba lentamente."
  },
  AvgDialog_142852_Content_30 = {
    Text = "Notaste que el tono de Lotan cambiaba de manera evidente por primera vez. Su voz era ronca y llena de Elación, como la de un león que huele a su presa."
  },
  AvgDialog_142852_Content_31 = {
    Text = "Dime, ¿cómo se llama mi oponente?"
  },
  AvgDialog_142852_Content_32 = {
    Text = "Puedes llamarme Lotan."
  },
  AvgDialog_142852_Content_33 = {
    Text = "Lotan... A la mayoría de los que merecen cruzar armas conmigo en este mundo los he oído mencionar, pero no recuerdo ese nombre."
  },
  AvgDialog_142852_Content_34 = {
    Text = "Quizás sea porque la mayoría de los que oyeron ese nombre ya están muertos. No importa. Dentro de cinco minutos, recordarás mi nombre."
  },
  AvgDialog_142852_Content_35 = {
    Text = "Ja... Este mundo a menudo presenta cambios a los que me cuesta Adaptación, quizás los jóvenes de hoy tienen razones para hacerme reconsiderar."
  },
  AvgDialog_142852_Content_36 = {
    Text = "Han pasado ya media hora desde que comenzó la carrera de salida. Haber sobrevivido hasta ahora significa que tienes la fuerza que respalda tu arrogancia."
  },
  AvgDialog_142852_Content_37 = {
    Text = "Nos malinterpreta, General Alish; no somos sus enemigos."
  },
  AvgDialog_142852_Content_38 = {
    Text = "Apártate, Elian."
  },
  AvgDialog_142852_Content_39 = {
    Text = "(En voz baja) Señorita Lotan, por favor no olvide el plan que trazamos antes. Ahora deberíamos eliminar primero a los demás enemigos. Alish es viejo y débil; cuando le fallen las fuerzas..."
  },
  AvgDialog_142852_Content_4 = {
    Text = "¿Acaso Él siempre ha disfrutado tanto del espectáculo?"
  },
  AvgDialog_142852_Content_40 = {
    Text = "He dicho que te apartes."
  },
  AvgDialog_142852_Content_41 = {
    Text = "Elian había conocido a muchas personas peligrosas; la voz de Lotan no era en absoluto más intensa que la de ellas, pero aquellas palabras frías le provocaron un miedo más intenso que cualquier otro que hubiera sentido."
  },
  AvgDialog_142852_Content_42 = {
    Text = "No lo pensó demasiado y se apartó del camino con expresión impasible."
  },
  AvgDialog_142852_Content_43 = {
    Text = "No quedan muchas personas en este Coliseo. Solo hay un oponente que merezca mi desafío."
  },
  AvgDialog_142852_Content_44 = {
    Text = "Lotan puso la mano en la empuñadura de su espadón y avanzó en dirección a Alish."
  },
  AvgDialog_142852_Content_45 = {
    Text = "Las Apariciones en las gradas caen en un silencio absoluto, sus rostros sin rasgos girándose al unísono para seguir los pasos de Lotan."
  },
  AvgDialog_142852_Content_46 = {
    Text = "El zumbido de baja frecuencia en el aire se volvió más nítido, como una antigua y Avaricia expectativa."
  },
  AvgDialog_142852_Content_47 = {
    Text = "He visto cómo combates, joven. En mis setenta años de campaña, jamás había encontrado un oponente tan fuerte como Tú."
  },
  AvgDialog_142852_Content_48 = {
    Text = "En este Coliseo se encuentran los enemigos más poderosos del mundo, todos quieren atacar primero, pero Tú no. Tú siempre esperas a que tu oponente desenvaine primero..."
  },
  AvgDialog_142852_Content_49 = {
    Text = "¿Puedes decirme por qué?"
  },
  AvgDialog_142852_Content_5 = {
    Text = "Lotan sacudió la cabeza y extrajo la gran espada del cadáver que yacía a sus pies."
  },
  AvgDialog_142852_Content_50 = {
    Text = "Porque... un enemigo que desenvaina su espada es algo más fuerte."
  },
  AvgDialog_142852_Content_51 = {
    Text = "¿Algo... más fuerte?"
  },
  AvgDialog_142852_Content_52 = {
    Text = "Solo me interesan las cosas más fuertes. Alza tu estandarte de guerra, Alish."
  },
  AvgDialog_142852_Content_53 = {
    Text = "Las palabras de Lotan no tenían ni el más mínimo rastro de provocación. Ella tenía la mano sobre la gran espada, los Ojos fijos en Ese general ya entrado en años, y sus pasos eran tan solemnes como los de un peregrino."
  },
  AvgDialog_142852_Content_54 = {
    Text = "Je, je... ¡ja, ja, ja, ja!"
  },
  AvgDialog_142852_Content_55 = {
    Text = "El viejo general echó la cabeza hacia atrás y soltó una carcajada. Su caballo de guerra permanecía inmóvil, hombre y bestia solos en el centro del Coliseo, mientras la bandera de color Sangre ondeaba Desordenada en el Viento."
  },
  AvgDialog_142852_Content_56 = {
    Text = "Muy parecido. Realmente muy parecido... Si fuéramos un poco más jóvenes, quizás podríamos ver a otro nosotros mismos en este mundo."
  },
  AvgDialog_142852_Content_57 = {
    Text = "De cualquier manera... ¡espero que ninguno de los dos decepcione al otro!"
  },
  AvgDialog_142852_Content_58 = {
    Text = "La voz de Alish se eleva de repente, sus piernas guiando a su montura con destreza. El corcel que lo ha llevado a través de innumerables campañas se lanza hacia adelante, su agudo relincho resonando por toda la vasta arena—"
  },
  AvgDialog_142852_Content_59 = {
    Text = "La bandera ondeó, como un rayo rojo que rasgara el polvo del centro del Coliseo, abalanzándose hacia Lotan."
  },
  AvgDialog_142852_Content_6 = {
    Text = "Los huesos perforados rozaron la hoja con un chirrido que ponía los dientes de punta, el corpulento cuerpo fue desgarrado en dos, y aquellos ojos llenos de rencor rodaron junto con la mitad del torso hacia la alcantarilla encharcada en Sangre."
  },
  AvgDialog_142852_Content_60 = {
    Text = "Ves que las comisuras de los labios de Lotan se elevan sin poder Inhibir. Es la primera vez que ves la sonrisa de Lotan."
  },
  AvgDialog_142852_Content_61 = {
    Text = "Ella desenvainó la gran espada y se lanzó de frente contra aquel rayo rojo—"
  },
  AvgDialog_142852_Content_62 = {Text = "..."},
  AvgDialog_142852_Content_63 = {
    Text = "¡¡¡BOOM!!!—"
  },
  AvgDialog_142852_Content_64 = {
    Text = "La gran espada blanca chocó contra el estandarte rojo, y un sonido agudo y estridente hizo vibrar los tímpanos de todos los presentes."
  },
  AvgDialog_142852_Content_65 = {
    Text = "Los cascos de hierro del caballo levantaron una nube de polvo, y las siluetas de Lotan y Alish se cruzaron en el sombrío campo de batalla."
  },
  AvgDialog_142852_Content_66 = {
    Text = "Cada colisión hacía que la sombra de la enorme ballena en el cielo temblara violentamente, Como Si estuviera saboreando un Manjar Exquisito difícil de encontrar."
  },
  AvgDialog_142852_Content_67 = {Text = "..."},
  AvgDialog_142852_Content_68 = {
    Text = "General Alish... Señora Lotan..."
  },
  AvgDialog_142852_Content_69 = {
    Text = "Qué batalla tan asombrosa..."
  },
  AvgDialog_142852_Content_7 = {
    Text = "¿Cómo dijo que se llamaba?"
  },
  AvgDialog_142852_Content_70 = {
    Text = "Te esfuerzas por capturar con tus Ojos las siluetas de ambos, pero te resulta muy difícil distinguirlas."
  },
  AvgDialog_142852_Content_71 = {
    Text = "Vera, procede."
  },
  AvgDialog_142852_Content_72 = {
    Text = "Sí, señor Elian."
  },
  AvgDialog_142852_Content_73 = {Text = "¡!!!"},
  AvgDialog_142852_Content_74 = {
    Text = "Ese es... ¿el hechicero envenenador de la mansión del primer ministro?! ¡Señora Lotan! Ten cuidado..."
  },
  AvgDialog_142852_Content_75 = {
    Text = "Antes de que pudieras terminar de hablar, una sensación helada rozó tu piel."
  },
  AvgDialog_142852_Content_76 = {
    Text = "Shhh... pajarito. Siempre me has sido leal, ¿y ahora quieres traicionarme por alguien que ni siquiera conoces?"
  },
  AvgDialog_142852_Content_77 = {
    Text = "Yo... pero..."
  },
  AvgDialog_142852_Content_78 = {
    Text = "Ya lo dije: cuando obtenga la corona de la Ballena Celestial y me convierta en el rey supremo de los seis reinos, tú y tu familia recibirán la recompensa que merecen."
  },
  AvgDialog_142852_Content_79 = {
    Text = "Pero ahora, cierra bien la boca."
  },
  AvgDialog_142852_Content_8 = {
    Text = "Graco... el Gladiador más famoso de todo el norte, que jamás había conocido la derrota en los Coliseos de los seis reinos..."
  },
  AvgDialog_142852_Content_80 = {
    Text = "La garganta se agitó. Solo quien ha sido esclavo sabe cuán poderosa es la tentación que encierran esas palabras de Elian."
  },
  AvgDialog_142852_Content_81 = {
    Text = "Observas al envenenador ocultarse, deslizándose entre el polvo arremolinado. No dices nada más."
  },
  AvgDialog_142852_Content_82 = {Text = "¿Hm?"},
  AvgDialog_142852_Content_83 = {
    Text = "El general, que cabalgaba a toda velocidad, vislumbró una silueta que se desvanecía entre el humo y frunció el ceño con fuerza. Eso hizo que su reacción se retrasara un instante."
  },
  AvgDialog_142852_Content_84 = {
    Text = "Cuando aquella feroz y enorme espada volvió a abalanzarse sobre él, Solo pudo alzar el estandarte militar para bloquearlo a duras penas."
  },
  AvgDialog_142852_Content_85 = {Text = "..."},
  AvgDialog_142852_Content_86 = {
    Text = "Un tremendo choque de Queso de cerdo hizo que el caballo de guerra tropezara y cayera de golpe al suelo. El rojo estandarte se partió en dos, y una enorme espada quedó atravesada en su cuello."
  },
  AvgDialog_142852_Content_87 = {
    Text = "Tus movimientos se han vuelto lentos, Alish."
  },
  AvgDialog_142852_Content_88 = {
    Text = "... Tu aliado te ha traicionado."
  },
  AvgDialog_142852_Content_89 = {
    Text = "¿Acaso eso importa?"
  },
  AvgDialog_142852_Content_9 = {
    Text = "Tú has visto morir a mucha gente, pero la escena que tienes ante los Ojos aún te revuelve el estómago."
  },
  AvgDialog_142852_Content_90 = {
    Text = "¿Qué... qué dices?"
  },
  AvgDialog_142852_Content_91 = {
    Text = "Lotan exhaló un suave suspiro, lleno de pesar."
  },
  AvgDialog_142852_Content_92 = {
    Text = "Estás muy cerca, Alish, pero no es suficiente. Más allá de la Fortaleza y el combate, tienes otro anhelo: el honor."
  },
  AvgDialog_142852_Content_93 = {
    Text = "Te importan demasiado esas cosas sin sentido. No eres lo suficientemente puro."
  },
  AvgDialog_142852_Content_94 = {
    Text = "Lotan Abre los ojos, sacudió la cabeza, sin prestar atención alguna a la sombra que se ocultaba tras Ella."
  },
  AvgDialog_142852_Content_95 = {
    Text = "Crees que, con la ayuda de Elian, enfrentarse varios de vosotros contra mí sería una victoria sin mérito."
  },
  AvgDialog_142852_Content_96 = {
    Text = "¿Acaso no debería ser así? Dos personas de capacidades y mentalidad similares, un duelo justo..."
  },
  AvgDialog_142852_Content_97 = {
    Text = "Mira cuántas palabras has usado. Honor, justicia, dignidad... no son más que cadenas que los débiles se forjan a sí mismos."
  },
  AvgDialog_142852_Content_98 = {
    Text = "El guerrero nace Solo para existir en el combate. El combate... Solo es combate. No tiene relación con ninguna otra cosa."
  },
  AvgDialog_142852_Content_99 = {
    Text = "La sombra en el cielo se detuvo, emitiendo un rugido de placer."
  },
  AvgDialog_142853_Content_1 = {
    Text = "La segunda sección"
  },
  AvgDialog_142853_Content_10 = {
    Text = "Yo digo... Gran Lotan... ¿Podría caminar un poco más despacio...?"
  },
  AvgDialog_142853_Content_100 = {
    Text = "Señora Lotan... ¡no crea en sus palabras! Es un embustero... Estando a su lado, he visto cómo cometía innumerables crímenes..."
  },
  AvgDialog_142853_Content_101 = {
    Text = "Estoy seguro de que usted no colaboraría con alguien como él..."
  },
  AvgDialog_142853_Content_102 = {
    Text = "Tú agitas las manos repetidamente hacia Lotan. Quieres advertirle lo astuto que es Elian."
  },
  AvgDialog_142853_Content_103 = {
    Text = "De esclavo a Mercader, de Mercader a noble, de noble a primer ministro, Elian recorrió un Camino arduo dejando innumerables huellas, y cada una de ellas estaba empapada de Una Mentira y Festín de Sangre."
  },
  AvgDialog_142853_Content_104 = {
    Text = "Pero Lotan no te miró. Giró la cabeza y contempló el cielo de un rojo oscuro. La enorme sombra con forma de ballena seguía moviéndose lentamente, y su silueta cubierta de espinas óseas aparecía y desaparecía entre las sombras."
  },
  AvgDialog_142853_Content_105 = {
    Text = "Apártense."
  },
  AvgDialog_142853_Content_106 = {
    Text = "Tú te apartas con indiferencia. Lotan pasa a tu lado, inclina la cabeza y mira desde arriba al primer ministro que tiene ante Ella. La luz rojo oscuro traza a su espalda una silueta afilada."
  },
  AvgDialog_142853_Content_107 = {
    Text = "Eres mucho más interesante que tu orden de Caballeros, Elian. No me importa qué tipo de persona eres, ni me preocupa cuándo me traicionarás. Con que puedas ayudarme, es suficiente."
  },
  AvgDialog_142853_Content_108 = {
    Text = "Acepto tu petición. No interrumpas mis combates; ese es mi único requisito."
  },
  AvgDialog_142853_Content_109 = {
    Text = "Señora Lotan... Usted..."
  },
  AvgDialog_142853_Content_11 = {
    Text = "Durante todo el Camino no ha dicho casi nada, Solo se ha dedicado a matar y avanzar, sin apenas descansar..."
  },
  AvgDialog_142853_Content_110 = {
    Text = "La sed de poder que flota en el aire te envuelve como una marea. Una sonrisa amarga se dibuja en tu rostro. Todos aquí son iguales... no deberías haber esperado nada diferente."
  },
  AvgDialog_142853_Content_111 = {
    Text = "Elian esbozó una sonrisa; en su expresión no había ni un ápice de alegría que fuera más allá de la sorpresa, Como Si se tratara de una negociación cuya victoria era inevitable."
  },
  AvgDialog_142853_Content_112 = {
    Text = "Se dio la vuelta y se dirigió hacia las gradas junto al Coliseo."
  },
  AvgDialog_142853_Content_113 = {
    Text = "La información de Todos, los equipos que formarán, el momento en que se romperán, y el orden de desafíos que más placer le causará, ya lo he pensado todo por usted."
  },
  AvgDialog_142853_Content_114 = {
    Text = "Disfrute de esta batalla, señora Lotan."
  },
  AvgDialog_142853_Content_12 = {
    Text = "¿Prefieres callarte tú solo, o prefieres que te meta mi espada en la boca?"
  },
  AvgDialog_142853_Content_13 = {Text = "..."},
  AvgDialog_142853_Content_14 = {
    Text = "Tú te tapas la boca con fuerza. La Mirada de Lotan no se detiene en ti. Ella observa los Alrededores, pasando la mano sobre un fragmento de columna de Piedra rota."
  },
  AvgDialog_142853_Content_15 = {
    Text = "La sección de la columna está cubierta de venas negras, como trazos de vasos sanguíneos, como si el tejido de algún ser vivo estuviera creciendo."
  },
  AvgDialog_142853_Content_16 = {Text = "Eso es..."},
  AvgDialog_142853_Content_17 = {
    Text = "Tú pegas el oído a la columna de Piedra y percibes vagamente un ritmo muy profundo y grave, como si alguna criatura enorme respirara lentamente en las profundidades de la Piedra."
  },
  AvgDialog_142853_Content_18 = {
    Text = "Una náusea repentina y un impulso asesino invaden tu cuerpo, y te apartas rápidamente."
  },
  AvgDialog_142853_Content_19 = {
    Text = "¿Esta cosa... está viva?!"
  },
  AvgDialog_142853_Content_2 = {
    Text = "¿Este es el Camino que nos indicaste?"
  },
  AvgDialog_142853_Content_20 = {
    Text = "Según la leyenda, la Ballena del Cielo Estelar creó este mundo con Su cuerpo, y los pueblos de los seis reinos existen sobre Su ser."
  },
  AvgDialog_142853_Content_21 = {
    Text = "Parece que ya estamos muy cerca de ella."
  },
  AvgDialog_142853_Content_22 = {
    Text = "Lotan se dirige hacia una mesa de Piedra en el centro de la plaza. Esa mesa de Piedra hecha de lapislázuli, con su exquisita factura y sus costosos materiales, desentona completamente con este lugar desolado."
  },
  AvgDialog_142853_Content_23 = {
    Text = "La superficie de la mesa de Piedra está cubierta por una capa de escamas finas y húmedas que se abren y cierran lentamente bajo la tenue luz, a un ritmo igual al de la respiración que acabas de escuchar."
  },
  AvgDialog_142853_Content_24 = {
    Text = "Lotan coloca los dos Sigilos de Hueso sobre él. En el instante en que las escamas tocan los Sigilos, se cierran como innumerables dedos atrapando una presa y devoran los dos Sigilos por completo."
  },
  AvgDialog_142853_Content_25 = {
    Text = "¡¡¡Nuestros sellos de hueso!!!"
  },
  AvgDialog_142853_Content_26 = {
    Text = "¡Ah! ¡Dos nuevos retadores!"
  },
  AvgDialog_142853_Content_27 = {
    Text = "Mientras tú te lanzas hacia la mesa de Piedra, una silueta con forma humana emerge lentamente desde el centro de la mesa."
  },
  AvgDialog_142853_Content_28 = {
    Text = "Su rostro cambia sin cesar: a veces es un rey, a veces un Caballero, a veces algo que no puedes reconocer."
  },
  AvgDialog_142853_Content_29 = {
    Text = "Su voz parece provenir de debajo de un charco de Sangre, y cada sílaba lleva una extraña Resonancia."
  },
  AvgDialog_142853_Content_3 = {
    Text = "Buscamos el Coliseo, no unas ruinas. Este lugar parece abandonado desde hace muchos años."
  },
  AvgDialog_142853_Content_30 = {
    Text = "Soy el Fantasma de la Ballena del Cielo Estelar, Su más fiel servidor, y también el administrador y el Público de este Coliseo."
  },
  AvgDialog_142853_Content_31 = {
    Text = "Han superado innumerables peligros y, finalmente, han llegado hasta aquí gracias a su propia Fuerza e inteligencia. Son el orgullo de los seis reinos, los más poderosos y tenaces..."
  },
  AvgDialog_142853_Content_32 = {
    Text = "Menos palabras innecesarias."
  },
  AvgDialog_142853_Content_33 = {
    Text = "......Eres bastante maleducado, retador. Por suerte, la Ballena Celestial jamás se preocupa por esas cosas."
  },
  AvgDialog_142853_Content_34 = {
    Text = "Solo le importa una cosa: la Fortaleza. Pura, sin la más mínima impureza."
  },
  AvgDialog_142853_Content_35 = {
    Text = "Bienvenido, bienvenido al Coliseo de la Ballena Celestial, bienvenido al escenario de la Fuerza pura—"
  },
  AvgDialog_142853_Content_36 = {
    Text = "El Fantasma levanta ambos brazos, y un sonido de baja frecuencia, vasto como el canto de una ballena, emerge de su interior, atraviesa tus huesos y Resuena dentro de tu cavidad craneal."
  },
  AvgDialog_142853_Content_37 = {
    Text = "!!! Esto es..."
  },
  AvgDialog_142853_Content_38 = {
    Text = "La canción se expande en ondas. Por donde se extiende, el cielo queda teñido de un rojo sombrío. Las ruinas desmoronadas, unidas por una sustancia viscosa imposible de identificar, se fusionan formando una gran arena ancestral."
  },
  AvgDialog_142853_Content_39 = {
    Text = "Las enormes esculturas de deidades alrededor adoptan distintas posturas, observando con ojos de compasión o de ira a los seres insignificantes como hormigas a sus pies."
  },
  AvgDialog_142853_Content_4 = {
    Text = "Recuerdo el mapa muy bien, debería ser este lugar sin duda... ¿Por qué no se parece a lo que estaba Registrado?"
  },
  AvgDialog_142853_Content_40 = {
    Text = "Una docena de retadores están dispersos por la plataforma, estudiándote."
  },
  AvgDialog_142853_Content_41 = {
    Text = "Uno, dos, tres... quince, dieciséis."
  },
  AvgDialog_142853_Content_42 = {
    Text = "Hay veinte Sigilos de Hueso en total... deberían venir dos personas más..."
  },
  AvgDialog_142853_Content_43 = {
    Text = "No hay más retadores. Esos dos Sigilos ya fueron destruidos en la ronda anterior."
  },
  AvgDialog_142853_Content_44 = {
    Text = "Felicitaciones. Al ser el último en llegar, te ganas el honor de la atención plena de todos—"
  },
  AvgDialog_142853_Content_45 = {
    Text = "Entre las risas ligeras del Fantasma, dieciséis miradas llenas de malas intenciones se dirigen hacia vosotros."
  },
  AvgDialog_142853_Content_46 = {
    Text = "Esa persona me resulta muy familiar... ¿No la habré visto en algún cartel publicitario de algún coliseo?"
  },
  AvgDialog_142853_Content_47 = {
    Text = "Esa ropa... ¡parece pertenecer a la organización de asesinos llamada Meñique! No esperaba encontrar a alguien de ellos aquí..."
  },
  AvgDialog_142853_Content_48 = {
    Text = "Sabes bastante."
  },
  AvgDialog_142853_Content_49 = {
    Text = "No podía hablar en las reuniones del Caballero, pero asistí como oyente muchas veces. El señor Elian nos contó muchas cosas..."
  },
  AvgDialog_142853_Content_5 = {
    Text = "Miraste los muros derruidos y erosionados por el Viento durante años que te rodeaban y te rascaste la cabeza."
  },
  AvgDialog_142853_Content_50 = {
    Text = "¡Ah! ¡Mira allá!! ¡Esa persona con la armadura vieja!"
  },
  AvgDialog_142853_Content_51 = {
    Text = "¡Es el general más valiente de los seis reinos! ¡Una vez mató al rey enemigo en el campo de batalla él Solo, y crecí escuchando sus historias!"
  },
  AvgDialog_142853_Content_52 = {
    Text = "¡Una leyenda viva! No esperaba... no esperaba poder verlo aquí."
  },
  AvgDialog_142853_Content_53 = {
    Text = "Lotan ignoró tus gritos de Elación incontenible. Echó un vistazo a los participantes y se recostó contra la columna de piedra cerrando los ojos."
  },
  AvgDialog_142853_Content_54 = {
    Text = "Antes de que el Caballero participara en esta contienda, hice una Apuesta con la señora sobre quién sería la persona en entrar al palacio de la Ballena Celestial."
  },
  AvgDialog_142853_Content_55 = {
    Text = "Lo has hecho muy bien, pequeño gorrión. Cuando este tedioso juego termine, la señora tendrá que pagarme una buena suma de dinero."
  },
  AvgDialog_142853_Content_56 = {Text = "¡!!!"},
  AvgDialog_142853_Content_57 = {
    Text = "E... el señor Elian..."
  },
  AvgDialog_142853_Content_58 = {
    Text = "Una Voz suave, pasos firmes, una túnica amplia hecha de telas preciosas, la fragancia del perfume de enebro... incluso reducido a Cenizas, podrías reconocerle."
  },
  AvgDialog_142853_Content_59 = {
    Text = "Usted... ¿cómo es que viene en persona...? Quiero decir..."
  },
  AvgDialog_142853_Content_6 = {
    Text = "El rey escribió en su diario que las paredes de este lugar estaban hechas de Oro, que en su cielo volaban mensajeros divinos de seis alas, y que por sus ríos fluían miel y vino..."
  },
  AvgDialog_142853_Content_60 = {
    Text = "Usted pidió al Caballero que le ayudara a Conquistar la corona, yo pensé..."
  },
  AvgDialog_142853_Content_61 = {
    Text = "¿Creías que pondría todas mis esperanzas en un Caballero que ni siquiera puede vencer a mercenarios? Te lo he enseñado, pequeño gorrión, nunca pongas todos los huevos en la misma cesta."
  },
  AvgDialog_142853_Content_62 = {
    Text = "Ten un poco de fe en el bondadoso Elian; la gran Ballena Celestial siempre otorga su Bendición a las buenas personas."
  },
  AvgDialog_142853_Content_63 = {
    Text = "El noble sonrió con elegancia. La Mirada nunca se apartó de Lotan."
  },
  AvgDialog_142853_Content_64 = {
    Text = "Este es... ¿tu amigo?"
  },
  AvgDialog_142853_Content_65 = {
    Text = "Eh, quizás no exactamente..."
  },
  AvgDialog_142853_Content_66 = {
    Text = "Lotan. Una guerrera."
  },
  AvgDialog_142853_Content_67 = {
    Text = "Es un placer conocerte, señorita Lotan. Espero que mis sirvientes no te hayan causado molestias."
  },
  AvgDialog_142853_Content_68 = {
    Text = "¿El primer ministro?"
  },
  AvgDialog_142853_Content_69 = {
    Text = "La Mirada de Lotan recorrió los adornos de su vestimenta y la espada que llevaba al cinto. Aunque no le importara en absoluto la política de los seis reinos, la Marca del primer ministro seguía siendo muy fácil de reconocer."
  },
  AvgDialog_142853_Content_7 = {
    Text = "Y ahora esta plaza que parece una ruina... tampoco se ve a nadie revisando los sellos de hueso."
  },
  AvgDialog_142853_Content_70 = {
    Text = "No es más que un título honorífico; su único propósito es ahorrar tiempo en las presentaciones."
  },
  AvgDialog_142853_Content_71 = {
    Text = "Elian sonrió y se sentó en la columna de piedra frente a Lotan."
  },
  AvgDialog_142853_Content_72 = {
    Text = "Has traído a mi siervo hasta aquí, pero mi Caballero ha desaparecido. Creo que ya me hago una idea de lo que ocurrió en el Camino."
  },
  AvgDialog_142853_Content_73 = {
    Text = "Tu Caballero murió de la manera más aburrida. Doce personas, y ninguna llegó a rozar siquiera la armadura de un guerrero de baja estofa."
  },
  AvgDialog_142853_Content_74 = {
    Text = "Y tú, te convertiste en el ganador de esa batalla con gran facilidad."
  },
  AvgDialog_142853_Content_75 = {
    Text = "Parece que su muerte no te interesa en lo más mínimo."
  },
  AvgDialog_142853_Content_76 = {
    Text = "Ah, no, no, no, me malinterpreta, señorita Lotan..."
  },
  AvgDialog_142853_Content_77 = {
    Text = "Elian soltó una gran carcajada y sacudió la cabeza."
  },
  AvgDialog_142853_Content_78 = {
    Text = "Mis Caballeros son buenas personas, con lealtad, dedicados... pero esto es el Coliseo de la Ballena Celestial. Los débiles han encontrado el final que les corresponde, y eso no me preocupa en absoluto."
  },
  AvgDialog_142853_Content_79 = {
    Text = "Lo que me preocupa eres tú, señorita Lotan. Una guerrera poderosa, que ama las espadas, la matanza y el Festín de Sangre, dispuesta a sacrificarlo todo por esa corona forjada en sangre..."
  },
  AvgDialog_142853_Content_8 = {
    Text = "¡Oye! Espérame..."
  },
  AvgDialog_142853_Content_80 = {
    Text = "El ritmo de las palabras de Elian se aceleraba cada vez más. La matanza y el ansia de poder que flotaban en el aire lo impregnaban, haciendo que incluso su corazón, curtido por los años, latiera sin poder contenerse."
  },
  AvgDialog_142853_Content_81 = {
    Text = "Como si se hubiera dado cuenta de su propio descontrol, respiró profundo y retrocedió medio paso."
  },
  AvgDialog_142853_Content_82 = {
    Text = "Creo que podemos colaborar."
  },
  AvgDialog_142853_Content_83 = {
    Text = "¿Crees que soy alguien a quien le gusta colaborar?"
  },
  AvgDialog_142853_Content_84 = {
    Text = "Los débiles siempre tienen el hábito de agruparse, tú desde luego no eres así. Pero, todo el mundo tiene necesidad de colaborar en algún momento, y tú no eres la excepción."
  },
  AvgDialog_142853_Content_85 = {
    Text = "Lotan aún no había respondido cuando innumerables Fantasmas idénticos aparecieron en los asientos del Coliseo, llenando hasta el último rincón de las abarrotadas gradas, y una voz semejante al canto de una ballena resonó de nuevo por todo el vasto Coliseo."
  },
  AvgDialog_142853_Content_86 = {
    Text = "¡Bien, aspirantes, ya no podemos esperar más. La prueba final está a punto de comenzar en este glorioso Coliseo!"
  },
  AvgDialog_142853_Content_87 = {
    Text = "¡Cuando el último vencedor emerja victorioso, una Puerta hacia el palacio de la Ballena Celestial se abrirá para él!"
  },
  AvgDialog_142853_Content_88 = {
    Text = "¡Tras esa Puerta aguardan gloria infinita, riqueza, poder... ¡todo!"
  },
  AvgDialog_142853_Content_89 = {
    Text = "Elegir al vencedor... ¿cuáles son las reglas?"
  },
  AvgDialog_142853_Content_9 = {
    Text = "Mientras hablabas solo frente al antiguo pedestal de piedra, Lotan se dirigió hacia el centro de la enorme plaza."
  },
  AvgDialog_142853_Content_90 = {
    Text = "¿Reglas? Je, je, je... ¡ja, ja, ja, ja! ¿Reglas?..."
  },
  AvgDialog_142853_Content_91 = {
    Text = "Las exageradas carcajadas de los Fantasmas hicieron vibrar dolorosamente los tímpanos de Todos los presentes en el Coliseo. Entre risas de Locura, dejaron de hablar y miraron con expectación hacia el centro del vasto Coliseo."
  },
  AvgDialog_142853_Content_92 = {
    Text = "Pero... todavía no ha dicho cuáles son las reglas..."
  },
  AvgDialog_142853_Content_93 = {
    Text = "Ya lo ha dicho. \"El último vencedor\", Solo Uno. Esa es la única regla, pajarillo."
  },
  AvgDialog_142853_Content_94 = {
    Text = "Matar, desafiar, aliarse, traicionar... Dieciocho participantes, solo una persona en pie podrá cruzar esa Puerta."
  },
  AvgDialog_142853_Content_95 = {
    Text = "La sonrisa familiar que Tú conoces vuelve a aparecer en el rostro de Elian."
  },
  AvgDialog_142853_Content_96 = {
    Text = "A lo que Tú te enfrentarás será a las personas más poderosas de este mundo."
  },
  AvgDialog_142853_Content_97 = {
    Text = "Por favor, no me malinterprete, no Dudar en absoluto de su Fortaleza, señora Lotan."
  },
  AvgDialog_142853_Content_98 = {
    Text = "Pero creo que tampoco desearía que personas aburridas le arruinaran el placer mientras disfruta de esas matanzas tan deliciosas, ¿verdad?"
  },
  AvgDialog_142853_Content_99 = {
    Text = "Lotan levantó la cabeza en serio por primera vez. Vio un rostro con una sonrisa amable, y sobre él, unos Ojos que parecían capaces de ver a través de todo."
  },
  AvgDialog_142854_Content_1 = {
    Text = "La quinta sección"
  },
  AvgDialog_142854_Content_10 = {
    Text = "Lo... ¿Lord Lotan?"
  },
  AvgDialog_142854_Content_11 = {
    Text = "No puedes reconocer si la persona cubierta de Sangre ante ti es Lotan o no."
  },
  AvgDialog_142854_Content_12 = {
    Text = "Una Sangre sucia y de podredumbre cubre su cuerpo, sin saber si proviene de ella misma o de alguna otra cosa."
  },
  AvgDialog_142854_Content_13 = {
    Text = "Bajo esa Sangre sucia y la armadura destrozada, la mitad de su cuerpo no es más que huesos blancos y desnudos."
  },
  AvgDialog_142854_Content_14 = {
    Text = "La guerrera con medio cuerpo sale de esa grieta impregnada de olor a Sangre. Sus pasos son lentos y agotados, la enorme espada rota arrastrándose por el suelo, trazando un surco superficial en el charco de Sangre."
  },
  AvgDialog_142854_Content_15 = {
    Text = "En su otra mano, la corona formada por el Festín de Sangre gotea Sangre sucia."
  },
  AvgDialog_142854_Content_16 = {
    Text = "Sus Ojos brillan como nunca antes."
  },
  AvgDialog_142854_Content_17 = {
    Text = "Lo... Lord Lotan... La Ballena Celestial... Ella..."
  },
  AvgDialog_142854_Content_18 = {Text = "Perdió."},
  AvgDialog_142854_Content_19 = {
    Text = "La voz de Lotan no tiene el menor temblor, Como Si simplemente estuviera relatando algo que inevitablemente iba a ocurrir."
  },
  AvgDialog_142854_Content_2 = {
    Text = "Tos... Tos, tos..."
  },
  AvgDialog_142854_Content_20 = {
    Text = "Usted firmó El Testamento con Ella... Si Ella recibía Daño, usted también..."
  },
  AvgDialog_142854_Content_21 = {
    Text = "No necesitas seguir preguntando. Las heridas en el cuerpo de Lotan ya lo dicen todo."
  },
  AvgDialog_142854_Content_22 = {
    Text = "Lady Lotan, has derrotado a todos los retadores... ¡incluso al Cetus Astral!"
  },
  AvgDialog_142854_Content_23 = {
    Text = "Ahora, usted es el rey indiscutible de este planeta... ¡Ahora es el momento más glorioso de su vida! Ahora..."
  },
  AvgDialog_142854_Content_24 = {
    Text = "Ahora es también su momento más Frágil."
  },
  AvgDialog_142854_Content_25 = {
    Text = "El olor a Sangre que emana de la grieta te envuelve, y el Susurro semejante al canto de una ballena se vuelve cada vez más claro en tus oídos."
  },
  AvgDialog_142854_Content_26 = {
    Text = "Mira, la corona formada por el Festín de Sangre..."
  },
  AvgDialog_142854_Content_27 = {
    Text = "Los tronos de seis naciones, la sumisión de millones de personas, riquezas y gloria inagotables... esa corona puede otorgar todo a su portador."
  },
  AvgDialog_142854_Content_28 = {
    Text = "Cada persona en el Coliseo la anhela. Esos Caballeros que te Regañan a diario, Graco, las hermanas Vorn, el General Alish, el todopoderoso Lord Elian..."
  },
  AvgDialog_142854_Content_29 = {
    Text = "Y Tú también, pequeño gorrión. Tú también la anhelas..."
  },
  AvgDialog_142854_Content_3 = {Text = "Eso es..."},
  AvgDialog_142854_Content_30 = {
    Text = "Contemplas la corona Carmesí en manos de Lotan. Con cada gota de Sangre que cae, el Susurro de la Ballena del Cielo Estelar se vuelve más nítido."
  },
  AvgDialog_142854_Content_31 = {
    Text = "Nunca volverás a ser una esclava, pequeño gorrión."
  },
  AvgDialog_142854_Content_32 = {
    Text = "Construirás un gran mausoleo para tu madre. Sacarás a tus hermanos de los establos para que vivan contigo en un espléndido palacio."
  },
  AvgDialog_142854_Content_33 = {
    Text = "Quienes alguna vez os humillaron se arrodillarán ante ti y besarán el dorso de tus pies."
  },
  AvgDialog_142854_Content_34 = {
    Text = "El poder. El poder supremo."
  },
  AvgDialog_142854_Content_35 = {
    Text = "Los nombres que fluyen en las leyendas murieron por él... y ahora, está ante tus Ojos, al alcance de tu mano."
  },
  AvgDialog_142854_Content_36 = {
    Text = "¡Ve, pequeño gorrión! ¡En toda tu vida, esta es tu única oportunidad!"
  },
  AvgDialog_142854_Content_37 = {
    Text = "El susurro se convirtió en estruendo, y un impulso intenso Surge en tu mente. Tu garganta reseca se mueve, y tu mano temblorosa levanta la daga enjoyada que dejó Elian. En la hoja de la daga aún hay rastros de tu propia Sangre."
  },
  AvgDialog_142854_Content_38 = {
    Text = "Ya has llegado hasta aquí, ¿por qué no puedes dar un paso más? Eso te pertenece... la corona siempre te perteneció..."
  },
  AvgDialog_142854_Content_39 = {
    Text = "Ya has llegado hasta aquí, ¿por qué no puedes dar un paso más? Eso te pertenece... la corona siempre te perteneció..."
  },
  AvgDialog_142854_Content_4 = {
    Text = "Te levantaste del suelo cubierto de polvo, sacudiste la gravilla de tu cuerpo y tardaste unos segundos en recordar dónde te encontrabas."
  },
  AvgDialog_142854_Content_40 = {
    Text = "<Red:¿Mátala?... Mátala... mátala... ¡¡¡mátala!!!>"
  },
  AvgDialog_142854_Content_41 = {
    Text = "Tres pasos. Solo tres pasos te separan de esa gloria suprema..."
  },
  AvgDialog_142854_Content_42 = {
    Text = "Justo cuando reunías el valor para dar el primer paso, Lotan volvió la cabeza. Esos Ojos cansados te miraron con calma."
  },
  AvgDialog_142854_Content_43 = {
    Text = "Justo cuando reunías el valor para dar el primer paso, Lotan volvió la cabeza. Esos Ojos cansados te miraron con calma."
  },
  AvgDialog_142854_Content_44 = {
    Text = "En el instante en que La Mirada se posó sobre ti, todos los susurros que te sostenían desaparecieron al mismo tiempo, y tu sangre hirviente se enfrió de golpe."
  },
  AvgDialog_142854_Content_45 = {Text = "Yo...Yo..."},
  AvgDialog_142854_Content_46 = {
    Text = "En los Ojos de Lotan no había ni el más mínimo deseo de matar. Al mirar esos Ojos, comprendiste de repente que, de no ser por ver a la Ballena del Cielo Estelar, nadie aquí merecía que Ella levantara un dedo."
  },
  AvgDialog_142854_Content_47 = {
    Text = "En los Ojos de Lotan no había ni el más mínimo deseo de matar. Al mirar esos Ojos, comprendiste de repente que, de no ser por ver a la Ballena del Cielo Estelar, nadie aquí merecía que Ella levantara un dedo."
  },
  AvgDialog_142854_Content_48 = {
    Text = "Era la mirada de alguien que observa desde lo alto cómo las hormigas se pelean por un terrón de azúcar. Nada más, ninguna otra emoción."
  },
  AvgDialog_142854_Content_49 = {
    Text = "La historia de las hormigas nunca cambia. Ella alzó su mano, ya reducida a huesos, y colocó descuidadamente lo que sostenía sobre tu cabeza."
  },
  AvgDialog_142854_Content_5 = {
    Text = "Las paredes de Piedra del Coliseo se fragmentaron como papel, enormes bloques de roca cayeron desde las gradas, y los últimos vestigios de los espectadores fantasmales del Público habían desaparecido por completo."
  },
  AvgDialog_142854_Content_50 = {
    Text = "!!! Esto es..."
  },
  AvgDialog_142854_Content_51 = {
    Text = "Gotas de Sangre cálida y sucia cayeron desde lo alto de tu cabeza. Extendiste la mano y, sobre tu propia cabeza, palpaste aquella corona fría y pegajosa formada por Sangre."
  },
  AvgDialog_142854_Content_52 = {
    Text = "Innumerables héroes mataron por Ella, innumerables almas perdieron su humanidad por Ella. El poder y la riqueza de seis naciones, la dignidad y la gloria supremas, en este momento reposaban ligeramente sobre tu cabeza."
  },
  AvgDialog_142854_Content_53 = {
    Text = "La vencedora final te la arrojó sin más, como quien mete un terrón de azúcar en la boca Avariciosa de un niño. Ahora, lo tienes todo."
  },
  AvgDialog_142854_Content_54 = {
    Text = "Señora Lotan... Usted... Usted..."
  },
  AvgDialog_142854_Content_55 = {
    Text = "Hazme un favor."
  },
  AvgDialog_142854_Content_56 = {
    Text = "Voy a buscar un nuevo oponente. Antes de eso, necesito un nuevo par de espadas."
  },
  AvgDialog_142854_Content_57 = {
    Text = "Lotan contempló el par de enormes espadas que la habían acompañado durante tantos años y guardó sus restos destrozados en las vainas."
  },
  AvgDialog_142854_Content_58 = {
    Text = "Ella se dio la vuelta y, arrastrando su cuerpo maltrecho, avanzó con paso cansado y lento hacia adelante, hacia un destino que tú jamás podrías comprender."
  },
  AvgDialog_142854_Content_59 = {
    Text = "En la grieta que tienes a tus espaldas, las antiguas runas se apagan una a una, y esa deidad que se desmorona y corrompe muestra una sonrisa de alivio que nunca antes habías visto."
  },
  AvgDialog_142854_Content_6 = {
    Text = "Yacías tendido sobre el suelo cubierto de escombros, con un zumbido incesante en los oídos. La Fisura dimensional flotaba en el centro del Coliseo, sus bordes se contraían violentamente, como una Herida feroz y grotesca."
  },
  AvgDialog_142854_Content_60 = {
    Text = "En mi lugar... Recuerda su nombre."
  },
  AvgDialog_142854_Content_61 = {
    Text = "Tú te arrodillas en el charco de Sangre, contemplando esa silueta que se aleja poco a poco, sin poder levantarte durante largo tiempo."
  },
  AvgDialog_142854_Content_62 = {
    Text = "La Corona sobre tu cabeza es pesada, muy pesada. El peso de doce milenios de deseo te lleva de rodillas al charco de sangre. La observas alejarse, incapaz de levantarte durante un largo, largo tiempo."
  },
  AvgDialog_142854_Content_63 = {
    Text = "La corona sobre su cabeza era tan ligera, tan ligera, que parecía no haber existido jamás."
  },
  AvgDialog_142854_Content_7 = {
    Text = "Un lamento grave y prolongado emergió de la Herida, atravesó tu cráneo y llegó hasta lo más profundo de tu mente, tan pesado como el suspiro de un planeta."
  },
  AvgDialog_142854_Content_8 = {
    Text = "Ese sonido... ¿es la Ballena Estelar?!"
  },
  AvgDialog_142854_Content_9 = {
    Text = "De la fisura emanaba un intenso y nauseabundo olor a Sangre. Cuando te disponías a acercarte lentamente, un pie reducido a puro hueso blanco cruzó desde la fisura hacia afuera."
  },
  AvgDialog_142888_Content_1 = {
    Text = "Una Mentira"
  },
  AvgDialog_142888_Content_10 = {
    Text = "No tienes forma de responder. Tus recuerdos están ahora tan revueltos como un perro de pelo largo que ha dado tres vueltas rodando en el barro."
  },
  AvgDialog_142888_Content_100 = {
    Text = "Inundando el pecho, inundando los oídos, inundando..."
  },
  AvgDialog_142888_Content_101 = {
    Text = "¡Mi señor!"
  },
  AvgDialog_142888_Content_102 = {
    Text = "De repente vuelves a la realidad. A lo lejos, Ogier, Lotan y Ramona caminan hacia ti tras haber terminado su entrenamiento. Las marionetas divididas de Doll están analizando los datos del entrenamiento."
  },
  AvgDialog_142888_Content_103 = {
    Text = "La persona a tu lado exhala un suspiro lleno de pesar."
  },
  AvgDialog_142888_Content_104 = {
    Text = "No te preocupes, siempre mantendré esta elección abierta para ti."
  },
  AvgDialog_142888_Content_105 = {
    Text = "Nadie permanece a tu lado. El horizonte donde el sol poniente está a punto de hundirse refracta un tenue resplandor nacarado, ligeramente psicodélico."
  },
  AvgDialog_142888_Content_106 = {Text = "Ah..."},
  AvgDialog_142888_Content_107 = {
    Text = "Tienes mucho más que decir. Sobre aquella catástrofe que no tuvo objetivo alguno, provocada simplemente por N que, movido por la travesura, sedujo a los fieles."
  },
  AvgDialog_142888_Content_108 = {
    Text = "Sobre el papel del Santuario de la Linterna en avivar las llamas, sobre los diversos actos de represalia desquiciados de Pontos durante el siglo siguiente, más o menos."
  },
  AvgDialog_142888_Content_109 = {
    Text = "Sobre si... hubo un instante en que él también dudó ante otra posibilidad, y por eso los años dejaron su marca en él."
  },
  AvgDialog_142888_Content_11 = {
    Text = "Leisha, que también estaba casi agotada por la batalla anterior, hizo un esfuerzo por incorporarse y se interpuso entre tú y Pontos."
  },
  AvgDialog_142888_Content_110 = {
    Text = "Sobre si Jago y Leisha siguen de fiesta en Ebwynnos ahora mismo."
  },
  AvgDialog_142888_Content_111 = {
    Text = "...Al final, lo único que deseas es rezar para que no le pase algo con el profesor Dexter en la escuela."
  },
  AvgDialog_142888_Content_112 = {
    Text = "Niegas con la cabeza y caminas hacia tus amigos sin dudarlo."
  },
  AvgDialog_142888_Content_12 = {
    Text = "Pontos, se acabó."
  },
  AvgDialog_142888_Content_13 = {
    Text = "Los que aún viven, si se quedan en Ebwynnos, tendrán que pagar el precio de olvidar los recuerdos del mundo exterior."
  },
  AvgDialog_142888_Content_14 = {
    Text = "Y los que, como yo, ya han muerto y han sido reconfigurados como pesadillas, acabarán viendo todos sus recuerdos lentamente corroídos."
  },
  AvgDialog_142888_Content_15 = {
    Text = "Jago ya ha tomado su decisión, y yo también he tomado la mía...\nVámonos."
  },
  AvgDialog_142888_Content_16 = {
    Text = "Los labios de Pontos se apretaron formando una línea indiferente, con la mandíbula tensa."
  },
  AvgDialog_142888_Content_17 = {
    Text = "Deberías recordar que existes gracias a Ebwynnos. Si lo abandonas, morirás."
  },
  AvgDialog_142888_Content_18 = {
    Text = "Sí, pero mis recuerdos del pasado también volverán. Moriré como un ser humano; es la única manera."
  },
  AvgDialog_142888_Content_19 = {
    Text = "Ya... no puedo recordar cómo erais tú y Jago de niños. Al menos, antes de que os olvide por completo."
  },
  AvgDialog_142888_Content_2 = {
    Text = "La sofocante Intimidación se retira como una marea, y tu mente recibe una punzada aguda, con destellos blancos ante tus ojos."
  },
  AvgDialog_142888_Content_20 = {
    Text = "Pontos se quedó paralizado. Por primera vez, viste aparecer en su rostro una expresión de tan profunda tristeza."
  },
  AvgDialog_142888_Content_21 = {
    Text = "...Ojalá pudiera decir que esa fuerza aún me controla."
  },
  AvgDialog_142888_Content_22 = {
    Text = "Cerró los ojos, como si quisiera escapar de algo que no deseaba enfrentar. Al final, esbozó una sonrisa de autoburla y abatimiento."
  },
  AvgDialog_142888_Content_23 = {
    Text = "Así podría ir en contra de vuestra voluntad con toda la razón del mundo y haceros daño."
  },
  AvgDialog_142888_Content_24 = {Text = "..."},
  AvgDialog_142888_Content_25 = {
    Text = "Pontos cede en silencio. El carruaje que una vez lo llevó a la venganza contra sus enemigos ahora lleva a Leisha en su camino también."
  },
  AvgDialog_142888_Content_26 = {
    Text = "Mientras el carruaje de indescriptible luz nacarada se desliza hacia el cielo más allá de Ebwynnos, una expresión de alivio aparece en el rostro de Leisha. Se vuelve para miraros a ambos..."
  },
  AvgDialog_142888_Content_27 = {
    Text = "Y luego se desvaneció por completo en la brisa nocturna del mar."
  },
  AvgDialog_142888_Content_28 = {
    Text = "Ninguno de vosotros habló; solo contemplasteis en silencio ese Oblivion durante largo tiempo, hasta que Pontos rompió el silencio."
  },
  AvgDialog_142888_Content_29 = {
    Text = "¿Cómo fue la vida de\"Tú\"después de que abandonaras Ebwynnos, la vida de\"Tú\"?"
  },
  AvgDialog_142888_Content_3 = {
    Text = "¡Sss, duele mucho!"
  },
  AvgDialog_142888_Content_30 = {
    Text = "No esperabas que esas fueran sus primeras palabras; te quedaste un momento desconcertado antes de empezar a ordenar aquellos recuerdos dispersos."
  },
  AvgDialog_142888_Content_31 = {
    Text = "Algo parece haber salido mal con este Dominio. Ni los recuerdos de Jago ni los tuyos están del todo intactos."
  },
  AvgDialog_142888_Content_32 = {
    Text = "...No lo recuerdo con claridad. Mi mente ahora alberga tanto recuerdos de ser Jago como recuerdos de ser otra persona, en un lugar lejano. Todos los recuerdos están mezclados."
  },
  AvgDialog_142888_Content_33 = {
    Text = "Instintivamente metiste la mano en el bolsillo para acariciar el saltamontes de paja."
  },
  AvgDialog_142888_Content_34 = {
    Text = "Pero aun así—sencilla, ordinaria, ajetreada, las mismas rutinas día tras día—fue una vida feliz."
  },
  AvgDialog_142888_Content_35 = {
    Text = "Lo suficientemente feliz como para hacerme quien soy. Lo suficientemente feliz como para que, pase lo que pase, quiera volver."
  },
  AvgDialog_142888_Content_36 = {
    Text = "Te mira a los ojos, tranquilo e inmóvil. Casi parece la forma en que... la forma en que Leisha solía mirarte."
  },
  AvgDialog_142888_Content_37 = {
    Text = "<Red:No solo está mirando a Jago.>"
  },
  AvgDialog_142888_Content_38 = {
    Text = "Estáis equivocados, Jago... <Red:%player%>."
  },
  AvgDialog_142888_Content_39 = {
    Text = "¡¡¡¿¿¿???"
  },
  AvgDialog_142888_Content_4 = {
    Text = "Pontos está de pie, solo, en el mismo lugar. No puedes distinguir su expresión."
  },
  AvgDialog_142888_Content_40 = {Text = "¿Qué?!"},
  AvgDialog_142888_Content_41 = {
    Text = "Un escalofrío te recorre. ¿Cómo puede saber <Red:«tu»> nombre? ¿Acaso esto no es solo un Dominio?"
  },
  AvgDialog_142888_Content_42 = {
    Text = "Vuelve a esa compostura fría y aristocrática, como si nada se le hubiera escapado jamás de las manos, y te dedica una sonrisa tranquila."
  },
  AvgDialog_142888_Content_43 = {
    Text = "Sé que <Red:「Tú」> has estado aquí todo el tiempo, sé que <Red:「Tú」> eres\"Él\", desde que <Red:「Tú」> eras pequeño, siempre supe que <Red:「Tú」> eras diferente a los demás."
  },
  AvgDialog_142888_Content_44 = {
    Text = "El ruido sordo del agua del mar volvió a inundarte los oídos."
  },
  AvgDialog_142888_Content_45 = {
    Text = "Sois demasiado pequeños, demasiado ingenuos, creyendo que esa mediocridad se llama felicidad."
  },
  AvgDialog_142888_Content_46 = {
    Text = "Esta vez, no cometeré el <Red:error> de dejar la elección en tus manos de nuevo."
  },
  AvgDialog_142888_Content_47 = {
    Text = "Estabas equivocado. Nunca cedió. No va a, ni iba a, soltar. Solo tendió un cebo luminoso."
  },
  AvgDialog_142888_Content_48 = {
    Text = "Hacía tiempo que había descubierto la otra parte de «ti». \nIba a encontrarte. No permitiría más sorpresas."
  },
  AvgDialog_142888_Content_49 = {
    Text = "Demasiado fácil. Esa batalla, esa victoria. \nHabía sido una trampa para atraer a <Italic:ti>."
  },
  AvgDialog_142888_Content_5 = {
    Text = "Pero evidentemente, algo ya lo había abandonado."
  },
  AvgDialog_142888_Content_50 = {
    Text = "Sin importar el precio a pagar, sin importar a qué existencia deba jurarle lealtad..."
  },
  AvgDialog_142888_Content_51 = {
    Text = "Haré que el festín de Ebwynnos continúe para siempre."
  },
  AvgDialog_142888_Content_52 = {
    Text = "Nadie sabía por qué de repente permitió que el envejecimiento se apoderara de él."
  },
  AvgDialog_142888_Content_53 = {
    Text = "Todo Ebwynnos tiembla con él. Los médiums a su alrededor y el agua del mar que surge de su pecho se fusionan, indistinguibles el uno del otro."
  },
  AvgDialog_142888_Content_54 = {
    Text = "Quizás hay amigos, quizás enemigos. Innumerables brazos negros emergen de su pecho, arañando su piel, acariciándola."
  },
  AvgDialog_142888_Content_55 = {
    Text = "Como si intentaran huir. Como si anhelaran estar con él para siempre."
  },
  AvgDialog_142888_Content_56 = {
    Text = "Estoy en un camino sin retorno. Ni lo necesito."
  },
  AvgDialog_142888_Content_57 = {
    Text = "Los años que nunca has vivido no significan nada. Aquí en Ebwynnos, son dóciles. Controlables. No pueden hacerte daño."
  },
  AvgDialog_142888_Content_58 = {
    Text = "Realmente es una lástima. Aún no puedo retenerte aquí. Se nos ha acabado el tiempo, <Red:%player%>."
  },
  AvgDialog_142888_Content_59 = {Text = "¡!!!"},
  AvgDialog_142888_Content_6 = {
    Text = "Dame una razón."
  },
  AvgDialog_142888_Content_60 = {
    Text = "Una ingravidez te toma por sorpresa, arrancándote hacia arriba y fuera del espacio desgarrado. Los Gaunt que oscurecen el cielo despliegan sus alas membranosas y se lanzan hacia ti en una suave embestida."
  },
  AvgDialog_142888_Content_61 = {
    Text = "No te preocupes. Nos veremos de nuevo muy pronto."
  },
  AvgDialog_142888_Content_62 = {
    Text = "Ebwynnos y yo esperaremos tu regreso. Para siempre."
  },
  AvgDialog_142888_Content_63 = {
    Text = "Las huellas del tiempo se extienden por el cuerpo de Pontos como una erosión."
  },
  AvgDialog_142888_Content_64 = {
    Text = "Riendo, alza su copa hacia ti desde Ebwynnos, que se aleja rápidamente en la distancia."
  },
  AvgDialog_142888_Content_65 = {
    Text = "En tu último vistazo antes de que la oscuridad lo envuelva, ves dos figuras de pie a su lado."
  },
  AvgDialog_142888_Content_66 = {
    Text = "No dejó ir a nadie. Los retuvo a todos, hasta el último."
  },
  AvgDialog_142888_Content_67 = {
    Text = "<Red:Es Leisha, y Jago cuando era joven.>"
  },
  AvgDialog_142888_Content_68 = {Text = "..."},
  AvgDialog_142888_Content_69 = {
    Text = "¿Eh?! ¿Y luego qué, y luego qué? ¡Guardián, ¿acaso te dejó caer a tu muerte?!"
  },
  AvgDialog_142888_Content_7 = {
    Text = "Su voz es ronca, pero su cuerpo sigue tenso, como una bestia acorralada sin salida."
  },
  AvgDialog_142888_Content_70 = {
    Text = "¡El tío Pontos era muy malo! ¡No puede hacerte eso!!"
  },
  AvgDialog_142888_Content_71 = {
    Text = "¡Sí, cómo puedes ser tan malo, Pontos!"
  },
  AvgDialog_142888_Content_72 = {
    Text = "Estabas contándole animadamente a Aurita tu experiencia en el mundo de los sueños, cuando de repente te giraste..."
  },
  AvgDialog_142888_Content_73 = {
    Text = "Y te sobresaltaste al ver a alguien igualmente curioso, con las manos en los bolsillos, apoyado en el marco de la Puerta, sin saber cuánto tiempo llevaba escuchando."
  },
  AvgDialog_142888_Content_74 = {
    Text = "Después, el pequeño Jago logró salir sano y salvo. Abrió los ojos y despertó del sueño."
  },
  AvgDialog_142888_Content_75 = {
    Text = "Se encontró acostado en su propia cama en casa, con las personas que amaba reunidas a su alrededor."
  },
  AvgDialog_142888_Content_76 = {
    Text = "El otro protagonista de la historia se apoya en la pared del dormitorio de Aurita y, en voz baja y pausada, proporciona el desenlace."
  },
  AvgDialog_142888_Content_77 = {
    Text = "Recordó todos los recuerdos de su vida, cerró los ojos en paz y se fue a un lugar de felicidad."
  },
  AvgDialog_142888_Content_78 = {
    Text = "Aurita emitió un pequeño y satisfecho resoplido por la nariz y fue quedándose dormida poco a poco, igual que Vera en tus recuerdos."
  },
  AvgDialog_142888_Content_79 = {
    Text = "Pontos inclina la cabeza hacia la puerta y hace un gesto de invitación."
  },
  AvgDialog_142888_Content_8 = {
    Text = "Por qué, por qué incluso tú tienes que irte, por qué preferirías arrojarte a la muerte en lugar de—"
  },
  AvgDialog_142888_Content_80 = {
    Text = "Imagino que querrás hablar conmigo, ¿verdad?"
  },
  AvgDialog_142888_Content_81 = {Text = "..."},
  AvgDialog_142888_Content_82 = {
    Text = "Reunidos tras una larga separación — qué frase tan hermosa."
  },
  AvgDialog_142888_Content_83 = {
    Text = "No le dijiste a Aurita cómo terminó realmente. Mentiste, ¿verdad?"
  },
  AvgDialog_142888_Content_84 = {
    Text = "Nunca dejaste ir a Leisha. Y el único que pudo salir de Ebwynnos fui yo, no Jago."
  },
  AvgDialog_142888_Content_85 = {
    Text = "Cortado tan bruscamente, Pontos no se molesta en absoluto. Sonríe y arquea una ceja."
  },
  AvgDialog_142888_Content_86 = {
    Text = "Por supuesto, evidentemente. Hay historias que no son adecuadas para contarles a los niños, ¿verdad?"
  },
  AvgDialog_142888_Content_87 = {
    Text = "Entonces imagino que esta... <Italic:apariencia> que llevas ahora... es solo para mostrarle a todos que envejecer —lo único que te perdiste— no significa nada para ti."
  },
  AvgDialog_142888_Content_88 = {
    Text = "Para demostrar que tienes todo bajo control, ¿eh? El tiempo. El envejecimiento. Incluso las vidas de los demás..."
  },
  AvgDialog_142888_Content_89 = {
    Text = "La hostilidad en tus palabras probablemente se está volviendo demasiado obvia para pasar desapercibida. Pontos no responde directamente; simplemente te dedica una sonrisa que te exaspera sobremanera."
  },
  AvgDialog_142888_Content_9 = {Text = "Y no\"Yo\"."},
  AvgDialog_142888_Content_90 = {
    Text = "¿Quién sabe? Quizás simplemente quería probar algo nuevo."
  },
  AvgDialog_142888_Content_91 = {
    Text = "De todos modos, me alegra que hayas recordado. Desde la primera vez que vine a Misaq, he estado esperando este día."
  },
  AvgDialog_142888_Content_92 = {
    Text = "Ebwynnos todavía te espera, %player%."
  },
  AvgDialog_142888_Content_93 = {
    Text = "...Si necesitas un recordatorio, Misaq cuenta con un sistema de seguridad completo."
  },
  AvgDialog_142888_Content_94 = {
    Text = "No estés tan tenso."
  },
  AvgDialog_142888_Content_95 = {
    Text = "Hablando de eso, tengo bastante curiosidad. Mi pequeño de Misaq, ya no eres Jago. ¿Tienes una respuesta para mí ahora?"
  },
  AvgDialog_142888_Content_96 = {
    Text = "Pontos gira la cabeza levemente, y tú miras sus ojos de un azul profundo."
  },
  AvgDialog_142888_Content_97 = {
    Text = "Si te diera una oportunidad más para elegir, ¿elegirías la vida eterna con juventud perpetua, o los recuerdos creados a lo largo de toda una vida?"
  },
  AvgDialog_142888_Content_98 = {
    Text = "El sonido del mar, el aleteo de las alas."
  },
  AvgDialog_142888_Content_99 = {
    Text = "El familiar y lejano ruido blanco vuelve a impregnar lentamente el cuerpo."
  },
  AvgDialog_142889_Content_1 = {
    Text = "Lo Mejor de Todo"
  },
  AvgDialog_142889_Content_10 = {
    Text = "Cuando crezcas lo entenderás. Siempre volveremos a vernos. Y cuando estemos separados, estaré pensando en ti todo el tiempo."
  },
  AvgDialog_142889_Content_100 = {
    Text = "Suspira. Con una sonrisa perfectamente natural, termina el resto de la frase junto con otra voz."
  },
  AvgDialog_142889_Content_101 = {
    Text = "¿De qué hablas? Esto es Ebwynnos. Aquí no hay envejecimiento. Festejaremos por siempre, eternamente jóvenes."
  },
  AvgDialog_142889_Content_102 = {
    Text = "<Italic:Alguien> sale de detrás de Orney. Habla en voz baja y ronca, como el más magnánimo y digno de los ancianos."
  },
  AvgDialog_142889_Content_103 = {
    Text = "Esa no es la voz de Pontos."
  },
  AvgDialog_142889_Content_104 = {
    Text = "Su antigüedad borraba toda sensación de familiaridad, dejando solo el Eco del agua marina desde las <Red:profundidades> del océano, que volvía a purgar tu conciencia."
  },
  AvgDialog_142889_Content_105 = {
    Text = "Sí, sí, esto es Ebwynnos. He regresado a Ebwynnos."
  },
  AvgDialog_142889_Content_106 = {
    Text = "<Shake:<Red:Festejaremos por siempre.>>"
  },
  AvgDialog_142889_Content_107 = {
    Text = "<Red:Seremos jóvenes por siempre.>"
  },
  AvgDialog_142889_Content_108 = {
    Text = "Eres tan feliz, tan despreocupado. Estás en Ebwynnos."
  },
  AvgDialog_142889_Content_109 = {
    Text = "Aparte de eso, todos los pensamientos sin importancia se desvanecieron."
  },
  AvgDialog_142889_Content_11 = {
    Text = "<Red:¡Clic!>"
  },
  AvgDialog_142889_Content_110 = {
    Text = "Sin embargo, por alguna razón, no dejaste que nadie viera aquel saltamontes cuyo nombre habías olvidado."
  },
  AvgDialog_142889_Content_12 = {
    Text = "En el instante en que la brújula acaba de abandonar tu mano, llega desde fuera de la ventana una serie de suaves y rápidos sonidos."
  },
  AvgDialog_142889_Content_13 = {
    Text = "Inmediatamente después, una suave carcajada."
  },
  AvgDialog_142889_Content_14 = {
    Text = "Déjame ver quién es este apuesto jovencito..."
  },
  AvgDialog_142889_Content_15 = {
    Text = "Con una fuerza invisible e inmensa, la ventana se abrió de par en par. En la profunda y cacofónica oscuridad, la luna plateada parpadeaba entre los huecos."
  },
  AvgDialog_142889_Content_16 = {
    Text = "Hola, Jago."
  },
  AvgDialog_142889_Content_17 = {
    Text = "Tantas... ¡¡tantas alas, abuelo!!"
  },
  AvgDialog_142889_Content_18 = {
    Text = "Innumerables y enormes alas membranosas negras, oscureciendo el cielo, se abalanzaron hacia ti. Tus pupilas temblaban mientras mirabas fijamente el centro oscuro, incapaz de moverte."
  },
  AvgDialog_142889_Content_19 = {
    Text = "<Red:Tío Pontos...>"
  },
  AvgDialog_142889_Content_2 = {
    Text = "El recuerdo termina. Guardas silencio durante un largo rato."
  },
  AvgDialog_142889_Content_20 = {
    Text = "Squish... glu squish... <LightGray:*sonido húmedo de compresión>"
  },
  AvgDialog_142889_Content_21 = {
    Text = "Las pequeñas manos de Vera se aferraron a ti con fuerza, dejando al final solo un profundo arañazo.\nEnvolver, asfixiar, engullir."
  },
  AvgDialog_142889_Content_22 = {
    Text = "Sereno. Tranquilo. Familiar. Placentero..."
  },
  AvgDialog_142889_Content_23 = {
    Text = "Oleadas de ruido blanco han engullido tus oídos."
  },
  AvgDialog_142889_Content_24 = {
    Text = "<Red:Caída.>"
  },
  AvgDialog_142889_Content_25 = {Text = "..."},
  AvgDialog_142889_Content_26 = {
    Text = "Jago, despierta. Deja de dormir."
  },
  AvgDialog_142889_Content_27 = {
    Text = "La festividad de hoy está a punto de comenzar. Todos te están esperando."
  },
  AvgDialog_142889_Content_28 = {
    Text = "Un ruido blanco penetrante envía un dolor agudo a través de tus tímpanos, y por instinto te incorporas de un salto de la cama."
  },
  AvgDialog_142889_Content_29 = {
    Text = "Te dije que volvería en sí pronto. Mi Jago es un muchachito extraordinario."
  },
  AvgDialog_142889_Content_3 = {
    Text = "Llámalo egoísmo de viejo, piensas, porque puede que seas la última persona que los recuerda, y no quieres que caigan en el olvido."
  },
  AvgDialog_142889_Content_30 = {
    Text = "Pontos sonríe y le da un codazo a Leisha. Orney, Tío White y muchos rostros familiares están todos apiñados alrededor de tu cama."
  },
  AvgDialog_142889_Content_31 = {
    Text = "Tu consciencia se siente sumergida en aguas profundas. Tienes la persistente sensación de que has olvidado algo, y la agilidad de tu cuerpo te resulta sutilmente extraña."
  },
  AvgDialog_142889_Content_32 = {
    Text = "Tío Pontos, ¿mamá? ¿Qué pasó? ¿Por qué están todos aquí?"
  },
  AvgDialog_142889_Content_33 = {
    Text = "Oh, te fuiste de viaje, pequeño, y tardé muchísimo tiempo en encontrarte."
  },
  AvgDialog_142889_Content_34 = {
    Text = "Ahora te he traído a casa."
  },
  AvgDialog_142889_Content_35 = {
    Text = "El sol poniente atraviesa las nubes, tallando el mar en ondas resplandecientes como oro disperso reflejado en el cristal de la ventana. Has vuelto a la posada junto al mar donde creciste."
  },
  AvgDialog_142889_Content_36 = {
    Text = "Ah, cierto. Este lugar es... @4"
  },
  AvgDialog_142889_Content_37 = {Text = "¿?!!!"},
  AvgDialog_142889_Content_38 = {
    Text = "ABYSSABYSSABYSSABYSSABYSSABYSSABYSSABYSS\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n厄@2@3波@1@3厄@2yssSS@2YA@4\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1@2@3扬@1@3斯@2y!!ab@2YA@4\nABYssABySSabySSAByssabYSSa@2SAByssabyssABYSS@2\nABYSSABYSSABYSS@4@3SSABYSS@2@3\n@3@2@4@3@1@3@3!!!!!!!\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n@3@4YssAby!!!!!!!ABYSSABYSSABy@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4<Red:!!!!!!>"
  },
  AvgDialog_142889_Content_39 = {
    Text = "Un dolor palpitante, una presión que empuja—el nombre del pueblo se queda atrapado en la punta de tu lengua."
  },
  AvgDialog_142889_Content_4 = {
    Text = "Miras a Vera con ternura. Tu familia, considerada, los ha dejado solos para que no te agotes."
  },
  AvgDialog_142889_Content_40 = {
    Text = "Un estruendo chirriante como hierro raspando cristal estalla desde el interior de tu cráneo hasta tu garganta, convirtiendo tu cerebro en una pasta espesa y viscosa."
  },
  AvgDialog_142889_Content_41 = {
    Text = "Hasta que esa palma cálida y áspera sostiene la nuca de tu cabeza, y como siempre, él ríe y presiona su frente contra la tuya."
  },
  AvgDialog_142889_Content_42 = {
    Text = "Oye, vuelve conmigo. ¿Qué te pasa?"
  },
  AvgDialog_142889_Content_43 = {
    Text = "Abres la boca lentamente, buscando tu voz."
  },
  AvgDialog_142889_Content_44 = {
    Text = "Pontos te observa atentamente, y no lo entiendes—la forma en que te mira, es la forma en que alguien mira algo que creía haber perdido para siempre."
  },
  AvgDialog_142889_Content_45 = {
    Text = "Me Gusta mirar la cosa más preciada del mundo."
  },
  AvgDialog_142889_Content_46 = {
    Text = "Bienvenido de vuelta a Ebwynnos, Jago."
  },
  AvgDialog_142889_Content_47 = {
    Text = "La consciencia regresa de golpe. Miras todas las cosas familiares a tu alrededor, la luz del sol horneando las tablas del suelo hasta que sudan granos de sal..."
  },
  AvgDialog_142889_Content_48 = {
    Text = "Una extraña y serena felicidad ahoga cualquier otro pensamiento. Una sonrisa aflora lentamente en tu rostro."
  },
  AvgDialog_142889_Content_49 = {
    Text = "Ahora recuerdo. Ebwynnos. Esto es Ebwynnos—el lugar donde crecí..."
  },
  AvgDialog_142889_Content_5 = {
    Text = "Nunca volví a ver a mamá ni al tío Pontos. Si no fuera por esta brújula, probablemente pensaría que todo fue una alucinación causada por la explosión."
  },
  AvgDialog_142889_Content_50 = {
    Text = "Así es. ¡Cuánto tiempo sin verte!"
  },
  AvgDialog_142889_Content_51 = {
    Text = "Por fin has vuelto a casa, Jago."
  },
  AvgDialog_142889_Content_52 = {Text = "..."},
  AvgDialog_142889_Content_53 = {
    Text = "Tus pensamientos se sienten como si hubieran sido empapados en un jarabe llamado felicidad. Todos a tu alrededor lucen igual de jóvenes que cuando se separaron..."
  },
  AvgDialog_142889_Content_54 = {
    Text = "Oh... se separaron."
  },
  AvgDialog_142889_Content_55 = {
    Text = "¿Cuándo te fuiste de Ebwynnos, y cómo volviste? Parece que no hace mucho estabas acostado en otra cama. Tienes una nieta, llamada..."
  },
  AvgDialog_142889_Content_56 = {
    Text = "¿Qué tienes en mente, pequeño?"
  },
  AvgDialog_142889_Content_57 = {
    Text = "Pontos se apoyó contra la ventana, el sol poniente ya hundiéndose en el mar, sus últimos rayos de luz ocultándose tras él."
  },
  AvgDialog_142889_Content_58 = {
    Text = "Tío Pontos, siento que he olvidado algo muy importante. ¿Qué era...?"
  },
  AvgDialog_142889_Content_59 = {
    Text = "¡Ja, ja, ja! Si por ahora no puedes recordarlo, significa que no es tan importante. No te apresures; en Ebwynnos, tenemos todo el tiempo del mundo."
  },
  AvgDialog_142889_Content_6 = {
    Text = "Así que, Vera, por eso quería el abuelo contarte esta historia."
  },
  AvgDialog_142889_Content_60 = {
    Text = "¡Vamos! Eres joven, tienes toda una vida de buenos momentos por delante, y por supuesto hay que usarlos para celebrar."
  },
  AvgDialog_142889_Content_61 = {
    Text = "Te rodeó los hombros con el brazo y caminó hacia el salón recién decorado en la planta baja, donde la multitud vitoreante los arrastró juntos a la pista de baile."
  },
  AvgDialog_142889_Content_62 = {
    Text = "Solo ahora notas que la posada se ha convertido en un salón de deslumbrante esplendor."
  },
  AvgDialog_142889_Content_63 = {
    Text = "Rostros familiares ríen a lo largo de la pista de baile, alzando sus copas y saludándote, copas de madera y vidrio chocando entre sí en un clamor disperso."
  },
  AvgDialog_142889_Content_64 = {
    Text = "Aún soy joven, aún soy... ¿joven?"
  },
  AvgDialog_142889_Content_65 = {
    Text = "Un fuerte mareo te invade de nuevo. Ese extraño felicidad te aferra con fuerza, sin soltarte."
  },
  AvgDialog_142889_Content_66 = {
    Text = "Alzas el brazo y ves dos manos jóvenes y fuertes;"
  },
  AvgDialog_142889_Content_67 = {
    Text = "miras el espejo, y el rostro de un joven luce la misma risa que todos los demás."
  },
  AvgDialog_142889_Content_68 = {
    Text = "Amigos, alcemos nuestras copas—¡por Ebwynnos!"
  },
  AvgDialog_142889_Content_69 = {
    Text = "Antes de que puedas recomponerte, Pontos pasa por encima de tu hombro y alza su copa hacia la multitud."
  },
  AvgDialog_142889_Content_7 = {
    Text = "Puede que sigan sobrevolando el cielo nocturno en algún lugar. Y si algún día desaparezco, quizás sea porque vinieron a llevarme a casa."
  },
  AvgDialog_142889_Content_70 = {
    Text = "¡Por Ebwynnos!"
  },
  AvgDialog_142889_Content_71 = {
    Text = "En medio de una alegría inmensa y desconcertante, alzas tu copa junto a los demás, y el oleaje de voces te arrastra hacia el centro de la multitud."
  },
  AvgDialog_142889_Content_72 = {
    Text = "Celebras, bailas, bebes sin medida."
  },
  AvgDialog_142889_Content_73 = {
    Text = "Los rayos de luz de la gran casa atraviesan la niebla que se eleva del mar, brillando toda la noche."
  },
  AvgDialog_142889_Content_74 = {
    Text = "No fue hasta que una tenue luz pálida apareció en el horizonte y la gente se desplomó unos contra otros para dormir que tú, algo achispado, tarareaste una canción y te recostaste en los cojines forrados de terciopelo."
  },
  AvgDialog_142889_Content_75 = {Text = "..."},
  AvgDialog_142889_Content_76 = {
    Text = "Estás casi adormilado cuando de repente ves el rostro de Leisha en un rincón del salón. Te apresuras hacia ella."
  },
  AvgDialog_142889_Content_77 = {
    Text = "¡Mamá! Espérame, ¿adónde fuiste? No te he visto en toda la noche."
  },
  AvgDialog_142889_Content_78 = {
    Text = "Un pánico inexplicable se apodera de tu corazón, y no puedes evitar murmurar para ti mismo."
  },
  AvgDialog_142889_Content_79 = {
    Text = "Qué extraño—¿no acabo de estar de viaje? ¿Por qué se siente como si no nos hubiéramos visto en tanto tiempo?"
  },
  AvgDialog_142889_Content_8 = {
    Text = "Pero... no quiero separarme del abuelo. ¿Puedes llevarme contigo?"
  },
  AvgDialog_142889_Content_80 = {
    Text = "Tus pasos se detuvieron abruptamente—por la expresión de absoluta impotencia y tristeza en el rostro de Leisha."
  },
  AvgDialog_142889_Content_81 = {
    Text = "Te encontró. Mi pobre Jago, nunca debiste haber venido aquí."
  },
  AvgDialog_142889_Content_82 = {
    Text = "Piensa, rápido—mientras aún no hayas olvidado. Recuerda qué clase de vida viviste."
  },
  AvgDialog_142889_Content_83 = {
    Text = "Las lágrimas de madre cayeron sobre tu mano, tan frías que retrocediste instintivamente. El aire gélido envió escalofríos recorriendo todo tu cuerpo en un instante."
  },
  AvgDialog_142889_Content_84 = {
    Text = "Mira a la gente que te rodea. Mírame a mí. Mira lo que deberíamos ser."
  },
  AvgDialog_142889_Content_85 = {
    Text = "Mete la mano en el bolsillo, Jago."
  },
  AvgDialog_142889_Content_86 = {
    Text = "Torpe, tosco, algo que pincha — allí hay un <Red:saltamontes>."
  },
  AvgDialog_142889_Content_87 = {
    Text = "Un saltamontes hecho por <Red:Vera>, llamado <Red:Vera>."
  },
  AvgDialog_142889_Content_88 = {
    Text = "<Shake:<Red:Vera>... no, ya lo he... hace mucho tiempo...>"
  },
  AvgDialog_142889_Content_89 = {
    Text = "<Shake:Me estoy muriendo, estoy tumbado en la cama, tuve amigos, tuve al amor de mi vida, tuve hijos, yo era...>"
  },
  AvgDialog_142889_Content_9 = {
    Text = "No puedes evitar sonreír, sacas de tu pecho aquella brújula que no te ha abandonado en décadas y la depositas en la palma de la mano de Vera."
  },
  AvgDialog_142889_Content_90 = {
    Text = "Todo a tu alrededor gira en un caos desordenado, dos corrientes de pensamiento completamente distintas enredadas entre sí."
  },
  AvgDialog_142889_Content_91 = {
    Text = "Te agarras la cabeza, doblándote de dolor, jadeando en busca de aire."
  },
  AvgDialog_142889_Content_92 = {
    Text = "¡Santo cielo, Jago, qué te pasa? ¡Tienes un aspecto terrible!"
  },
  AvgDialog_142889_Content_93 = {
    Text = "Orney se lanza contra ti de la nada, y el zumbido en tus oídos desaparece de golpe."
  },
  AvgDialog_142889_Content_94 = {
    Text = "Levantas la vista, y Leisha ya se ha ido."
  },
  AvgDialog_142889_Content_95 = {
    Text = "¡Orney, Orney, no, no, ahora lo recuerdo!"
  },
  AvgDialog_142889_Content_96 = {
    Text = "Crecimos juntos, ¿verdad? Estuve en tu graduación, en tu boda. ¡No deberías ser tan joven! Tenemos la misma edad, los dos hemos envejecido..."
  },
  AvgDialog_142889_Content_97 = {
    Text = "Orney te mira con una expresión que no reconoces en absoluto, y te mira durante mucho, mucho tiempo, hasta que casi sientes ganas de huir."
  },
  AvgDialog_142889_Content_98 = {Text = "Luego..."},
  AvgDialog_142889_Content_99 = {
    Text = "Ah, Jago..."
  },
  AvgDialog_142890_Content_1 = {Text = "Ella y Él"},
  AvgDialog_142890_Content_10 = {
    Text = "Gracias por tu regalo, tío Pontos, pero..."
  },
  AvgDialog_142890_Content_11 = {
    Text = "Debe de haber sido una vida muy larga y valiosa; por eso, estoy dispuesto a renunciar a la eterna juventud y a la PV."
  },
  AvgDialog_142890_Content_12 = {
    Text = "La gente deja de hablar. Al unísono, todos se vuelven para mirarte."
  },
  AvgDialog_142890_Content_13 = {
    Text = "Los tímpanos te duelen y laten como si fueran a reventar, y el sonido del agua del mar se abre paso perforando tu cráneo."
  },
  AvgDialog_142890_Content_14 = {
    Text = "A través del pesado rumor del mar, escuchas un suspiro."
  },
  AvgDialog_142890_Content_15 = {
    Text = "<Red:Otra vez esto.>"
  },
  AvgDialog_142890_Content_16 = {
    Text = "<Shake:<Red:Chii... muu, gurr, gu...>>"
  },
  AvgDialog_142890_Content_17 = {
    Text = "Las cuatro paredes tiemblan, todo gotea en una mucosidad húmeda."
  },
  AvgDialog_142890_Content_18 = {
    Text = "Incluso después de haberte separado, la vejez aún te hace decir esas <Red:estupideces débiles>, igual que Leisha."
  },
  AvgDialog_142890_Content_19 = {
    Text = "De repente sentiste que él <Red:ya no era> Pontos."
  },
  AvgDialog_142890_Content_2 = {
    Text = "Al contemplar esa mano familiar y cálida, finalmente— retrocediste un paso."
  },
  AvgDialog_142890_Content_20 = {
    Text = "Un miedo antiguo, olvidado, vasto, imponente e imposible de contemplar te paralizó en el lugar arrancándote un <Red:grito> silencioso."
  },
  AvgDialog_142890_Content_21 = {
    Text = "ABYSSABYSSABYSSABYSSABYSSABYSSABYSSABYSS\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n厄@2@3波@1@3厄@2yssSS@2YA@4\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1@2@3扬@1@3斯@2y!!ab@2YA@4\nABYssABySSabySSAByssabYSSa@2SAByssabyssABYSS@2\nABYSSABYSSABYSS@4@3SSABYSS@2@3\n@3@2@4@3@1@3@3!!!!!!!\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n@3@4YssAby!!!!!!!ABYSSABYSSABy@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4<Red:!!!!!!>"
  },
  AvgDialog_142890_Content_22 = {
    Text = "Recordaste — ese sonido de cuando llegaste a Ebwynnos, cuando dejaste Ebwynnos, cuando regresaste a Ebwynnos."
  },
  AvgDialog_142890_Content_23 = {
    Text = "Piel, costillas, despegándose hacia afuera, desplegándose, y luego..."
  },
  AvgDialog_142890_Content_24 = {
    Text = "Vacío absoluto, incontables manos, vacío absoluto, vacío absoluto, vacío absoluto, vacío absoluto, vacío absoluto, @2y@2, @4@4@2@4\n@3@2@4@3@1@3@3!!!!!!"
  },
  AvgDialog_142890_Content_25 = {
    Text = "Quédate aquí, quédate en Ebwynnos."
  },
  AvgDialog_142890_Content_26 = {
    Text = "<Change>Obedece al abismo, arrójate al abismo."
  },
  AvgDialog_142890_Content_27 = {Text = "Luna."},
  AvgDialog_142890_Content_28 = {
    Text = "La Luna radiante cuelga en el lejano cielo, muy lejos."
  },
  AvgDialog_142890_Content_29 = {
    Text = [[
Sus costillas su piel sus brazos su pecho su abrazo
Su abrazo su abrazo su abrazo su abrazo su abrazo
Su abrazo su abrazo su abrazo su abrazo su abrazo
Eb@3@4wyn@3@2nos
Ebwy@4@3@2nn@4@3@2os
Su abrazo sus costillas su piel sus brazos su pecho
Eterno eterno eterno eterno eterno eterno eterno
Eternoeternoeternoeternoeternoeternoeterno <Red:Ebwynnos>]]
  },
  AvgDialog_142890_Content_3 = {
    Text = "...Sí lo hay."
  },
  AvgDialog_142890_Content_30 = {
    Text = "<Red:Ebwynnos en su abrazo.>"
  },
  AvgDialog_142890_Content_31 = {
    Text = "Capas y capas de alas, envolviendo en su interior un abrazo denso y firme, irresistible y absorbente."
  },
  AvgDialog_142890_Content_32 = {
    Text = "Eres empujada, eres envuelta, eres contenida, caes en una calma infinita."
  },
  AvgDialog_142890_Content_33 = {Text = "¡Detente!"},
  AvgDialog_142890_Content_34 = {
    Text = "Una figura irrumpió con fuerza entre la fría multitud inconsciente, abriéndose paso hacia el vórtice de <Red:「Pontos」>."
  },
  AvgDialog_142890_Content_35 = {
    Text = "Sin causar ningún daño, pero con una conmoción extremadamente evidente, las pupilas de <Red:「Pontos」> se estremecieron, clavando la mirada en su rostro."
  },
  AvgDialog_142890_Content_36 = {
    Text = "Siempre creí... que solo había reconstruido una Cáscara vacía."
  },
  AvgDialog_142890_Content_37 = {
    Text = "Al igual que las cosas que Jago olvidó pero que aún lo influyen, una parte de mí también sigue existiendo."
  },
  AvgDialog_142890_Content_38 = {
    Text = "Déjalo ir, Pontos, él no pertenece a este lugar."
  },
  AvgDialog_142890_Content_39 = {
    Text = "Oh, Leisha."
  },
  AvgDialog_142890_Content_4 = {Text = "¿Qué?"},
  AvgDialog_142890_Content_40 = {
    Text = "Lo amo, igual que tú lo amas."
  },
  AvgDialog_142890_Content_41 = {
    Text = "Orney, White."
  },
  AvgDialog_142890_Content_42 = {
    Text = "Toda la gente de Ebwynnos."
  },
  AvgDialog_142890_Content_43 = {
    Text = "En silencio, junto a la pesadilla, se acercan a ti como un muro aplastante que se cierra."
  },
  AvgDialog_142890_Content_44 = {
    Text = "¡No, no no no! ¡No!!"
  },
  AvgDialog_142890_Content_45 = {
    Text = "Leisha te mira a ti, mira a Jago, y también mira a... ti."
  },
  AvgDialog_142890_Content_46 = {
    Text = "Sé por qué los deseas tanto. Allí no solo está Jago, hay más de un alma."
  },
  AvgDialog_142890_Content_47 = {
    Text = "Ah... todos olvidarán todo, se quedarán aquí."
  },
  AvgDialog_142890_Content_48 = {
    Text = "Leisha queda atrapada una vez más. Retuerce su cuerpo con todas sus fuerzas y te mira fijamente—no a tu rostro, sino a través de él, como si intentara ver en lo más profundo de tu alma."
  },
  AvgDialog_142890_Content_49 = {
    Text = "Por favor. Quienquiera que seas—sé que estás ahí dentro. Devuelve a Jago. \n¡Devuélvelo a la vida que debíais vivir!"
  },
  AvgDialog_142890_Content_5 = {
    Text = "Como si no hubiera entendido tu pregunta, frunce el ceño levemente con incredulidad."
  },
  AvgDialog_142890_Content_50 = {
    Text = "Densas membranas negras se despliegan. Todo es tan silencioso, tan... cautivador, que casi te diriges hacia Ellos."
  },
  AvgDialog_142890_Content_51 = {
    Text = "Entonces, escuchaste... la voz de <Red:「Tú」>."
  },
  AvgDialog_142890_Content_52 = {
    Text = "Creo que <Red:「Yo」> ya ha tomado una decisión."
  },
  AvgDialog_142890_Content_53 = {
    Text = "Desde las profundidades del mar del conocimiento, un espíritu lucha por emerger."
  },
  AvgDialog_142890_Content_54 = {
    Text = "\"Tú\", que sobreviviste a la gran explosión de Akut como <Red:「Guardián de Misaq」>, tomaste el control de este cuerpo."
  },
  AvgDialog_142890_Content_55 = {
    Text = "Un resplandor de Plata parpadeó en tu palma."
  },
  AvgDialog_142890_Content_56 = {
    Text = "Los recuerdos dispersos de Jago se van reuniendo, pieza a pieza."
  },
  AvgDialog_142890_Content_57 = {
    Text = "¿Sabes, tío Pontos? Lo primero que acabo de recordar era algo muy pequeño. Algo que no debería haber importado en absoluto."
  },
  AvgDialog_142890_Content_58 = {Text = "..."},
  AvgDialog_142890_Content_59 = {
    Text = "\"Pontos\" no habla. Te estudia en silencio."
  },
  AvgDialog_142890_Content_6 = {
    Text = "Tienen significado, esos recuerdos."
  },
  AvgDialog_142890_Content_60 = {
    Text = "Cuando \"Yo\" cumplí dieciocho años, Orney y yo nos colamos a escondidas en el vapor más cercano y le suplicamos a los marineros que nos dejaran trabajar en la cubierta inferior a cambio del pasaje. Un viaje gratis, así de simple."
  },
  AvgDialog_142890_Content_61 = {
    Text = "A la mañana siguiente, vimos el amanecer más hermoso que ninguno de los dos había visto jamás. Orney dijo que ojalá el sol nunca se pusiera. Pero yo no."
  },
  AvgDialog_142890_Content_62 = {
    Text = "Porque el sol sí se pone. Porque cada día termina. Eso es lo que hace que las cosas que vivimos tengan significado."
  },
  AvgDialog_142890_Content_63 = {
    Text = "Basta de tonterías. En Ebwynnos, puedo hacer que el sol salga y se ponga a tu antojo, si eso es lo que deseas."
  },
  AvgDialog_142890_Content_64 = {
    Text = "Cierra los ojos, agotado, con la paciencia finalmente agotada. Niegas con la cabeza con firmeza."
  },
  AvgDialog_142890_Content_65 = {
    Text = "Lo que importa es el tiempo que vivimos. No un sol que permanece ahí para siempre."
  },
  AvgDialog_142890_Content_66 = {
    Text = "Lo siento, Pontos."
  },
  AvgDialog_142890_Content_67 = {
    Text = "Levanta la mano. El muro de Siervo-Gaunts se cierra sobre ti."
  },
  AvgDialog_142890_Content_68 = {
    Text = "Id, siervos."
  },
  AvgDialog_142890_Content_7 = {
    Text = "No para los demás, sino para mí mismo."
  },
  AvgDialog_142890_Content_8 = {
    Text = "Quiero saber qué clase de vida viví; después de perder la memoria, ¿por qué cualquier alegría me hace sentir que me falta algo?"
  },
  AvgDialog_142890_Content_9 = {
    Text = "Las espinas del saltamontes de paja te pinchan suavemente la yema de los dedos, y sin saber por qué, recuerdas la silueta de aquel niño que lloraba junto a la cama."
  },
  AvgDialog_142891_Content_1 = {
    Text = "Secreto de Familia"
  },
  AvgDialog_142891_Content_10 = {
    Text = "Se llama — mm, se llama Vera, porque Vera es el nombre que le puso el abuelo, y es el mejor nombre."
  },
  AvgDialog_142891_Content_100 = {
    Text = "Su ira os consumirá, solo la Alegría puede... @1!"
  },
  AvgDialog_142891_Content_101 = {Text = "Pfft."},
  AvgDialog_142891_Content_102 = {
    Text = "La sangre salpicó, y tú miraste atónito cómo Leisha y varios de los habituales de la posada combatían montados en las mismas criaturas que vosotros habíais cabalgado."
  },
  AvgDialog_142891_Content_103 = {
    Text = "¿Por qué demonios habrán venido estas malditas cosas hasta aquí...\nBueno, este debería ser el último."
  },
  AvgDialog_142891_Content_104 = {
    Text = "Ojalá solo estén de paso..."
  },
  AvgDialog_142891_Content_105 = {
    Text = "Leisha y sus compañeros se marcharon. Tú y Pontos permanecisteis en las sombras. Te habrías desplomado en el suelo si él no te hubiera sujetado por los hombros."
  },
  AvgDialog_142891_Content_106 = {
    Text = "Te aferraste al borde de su ropa. Su voz era tranquila y suave, como si se esforzara al máximo por no asustarte más."
  },
  AvgDialog_142891_Content_107 = {
    Text = "Jago, es igual que lo que viste... esas criaturas que nos trajeron aquí hace un momento se llaman Siervo-Gaunt. Las llevamos a luchar por nosotros."
  },
  AvgDialog_142891_Content_108 = {
    Text = "Hizo una pausa, con la mano apoyada en el flanco del Gaunt, haciendo crujir los nudillos, como si dudara sobre cómo explicarlo."
  },
  AvgDialog_142891_Content_109 = {
    Text = "Bueno, somos los héroes de una historia de aventuras, del tipo que doma dragones, solo que nosotros domamos estos Siervo-Gaunt."
  },
  AvgDialog_142891_Content_11 = {
    Text = "Vera... El abuelo necesita descansar, ven con papá."
  },
  AvgDialog_142891_Content_110 = {
    Text = "¿Q-qué... De qué estás hablando, tío Pontos?! Nuestra familia solo lleva una posada..."
  },
  AvgDialog_142891_Content_111 = {
    Text = "Después... después del accidente, quedamos muy pocos. Leisha hizo mucho por todos, y la gente dependía de ella."
  },
  AvgDialog_142891_Content_112 = {
    Text = "Pero ella no quería que nosotros, especialmente tú, tuviéramos nada que ver con todo esto. Esta vida tranquila y anónima es exactamente la que ella quería para nosotros."
  },
  AvgDialog_142891_Content_113 = {
    Text = "Pero todavía hay tantas cosas malas y feas ahí fuera en este mundo, igual que las que viste hoy. No lo entiendo..."
  },
  AvgDialog_142891_Content_114 = {
    Text = "Un destello de frustración cruzó el rostro de Pontos —algo poco habitual en él— y se echó hacia atrás el suelto cabello dorado que le caía sobre la frente."
  },
  AvgDialog_142891_Content_115 = {
    Text = "Últimamente, los Siervo-Gaunt me encontraron. Y puedo sentir algo mucho más poderoso detrás de ellos. Él me ha elegido, Él me está llamando."
  },
  AvgDialog_142891_Content_116 = {
    Text = "Podría hacer mucho más. Pero Leisha cree que mientras nos escondamos bien, todo irá bien."
  },
  AvgDialog_142891_Content_117 = {
    Text = "El peso de todo aquello te dejó parpadeando sin comprender. Por primera vez, conocías cada palabra y aun así no podías darle sentido a ninguna de ellas encadenadas."
  },
  AvgDialog_142891_Content_118 = {
    Text = "Pontos pareció darse cuenta, volvió al momento presente y te dedicó una sonrisa."
  },
  AvgDialog_142891_Content_119 = {
    Text = "Lo siento, Jago. ¿Te he soltado demasiado de golpe?"
  },
  AvgDialog_142891_Content_12 = {
    Text = "Tu hijo está algo preocupado por tu salud y quiere llevarse a la nieta, ella frunce el labio, a punto de romper a llorar."
  },
  AvgDialog_142891_Content_120 = {
    Text = "Volvamos antes de que Leisha descubra que nos escabullimos. Tenemos todo el tiempo del mundo para hablar de esto."
  },
  AvgDialog_142891_Content_121 = {
    Text = "A lo lejos, Leisha pareció mirarte. El tío Pontos te hizo de nuevo el gesto de <Italic:silencio>."
  },
  AvgDialog_142891_Content_122 = {Text = "..."},
  AvgDialog_142891_Content_123 = {
    Text = "La ventana se abrió y se cerró de nuevo, sin hacer ningún ruido."
  },
  AvgDialog_142891_Content_124 = {
    Text = "Como si el viento simplemente hubiera abierto la ventana. Afuera, las olas rompían y se retiraban. Escuchaste el sonido de Leisha subiendo las escaleras desde abajo."
  },
  AvgDialog_142891_Content_125 = {
    Text = "Ambos hunden la cara en la almohada con la respiración calmada, fingiendo que esta sigue siendo una noche cualquiera."
  },
  AvgDialog_142891_Content_13 = {
    Text = "Sonreíste y tosiste unas veces, esforzándote por incorporar ese frágil esqueleto, apoyándote en el cabecero de la cama."
  },
  AvgDialog_142891_Content_14 = {
    Text = "Vera, no llores. La luz de la luna afuera es tan hermosa, apaga un poco las luces."
  },
  AvgDialog_142891_Content_15 = {
    Text = "El abuelo aún tiene tiempo para contarte una historia más, déjame pensar..."
  },
  AvgDialog_142891_Content_16 = {
    Text = "Tu mirada cae sobre la brújula de latón que nunca se ha separado de tu lado. Intacta por los años, luce un suave y delicado borde plateado bajo la luz de la luna."
  },
  AvgDialog_142891_Content_17 = {
    Text = "Pasas el pulgar lentamente por su superficie, lleno de anhelo, y tu voz se vuelve ronca mientras te hundes en los recuerdos."
  },
  AvgDialog_142891_Content_18 = {
    Text = "Fue... hace más de sesenta años, cuando yo aún era un niño."
  },
  AvgDialog_142891_Content_19 = {
    Text = "Leisha, el barco está a punto de zarpar. ¿Aún no ha vuelto?"
  },
  AvgDialog_142891_Content_2 = {Text = "Luna."},
  AvgDialog_142891_Content_20 = {
    Text = "Parece que realmente no podremos despedirnos en persona. Por favor, al menos acepta este broche..."
  },
  AvgDialog_142891_Content_21 = {
    Text = "Sonó el silbato del puerto. Los dueños de las baratijas dejaron atrás un montón tintineante de joyas personales, con rostros llenos de pesar mientras regresaban al barco."
  },
  AvgDialog_142891_Content_22 = {
    Text = "Dios mío, por el amor de @3, querida, ¿cuándo va a aprender tu tío a no tener tantos \"amigos\"?"
  },
  AvgDialog_142891_Content_23 = {
    Text = "Tu madre Leisha te miró con una expresión entre divertida y resignada, suspiró y metió las joyas en la pequeña caja que sería devuelta al capitán para su entrega la próxima vez que el barco atracara."
  },
  AvgDialog_142891_Content_24 = {
    Text = "Tu familia regentaba una pequeña posada perfectamente normal en un pueblo costero. Solo una cosa era ligeramente especial..."
  },
  AvgDialog_142891_Content_25 = {
    Text = "Déjame ver quién es este apuesto jovencito..."
  },
  AvgDialog_142891_Content_26 = {
    Text = "La Puerta se abre de nuevo con el Viento salado, y \"ese asunto especial\" se ríe a carcajadas mientras te agarra por la cintura y te hace girar en el aire."
  },
  AvgDialog_142891_Content_27 = {
    Text = "¡Pontos! ¡Cuántas veces te he dicho que le vas a arrancar los brazos!"
  },
  AvgDialog_142891_Content_28 = {
    Text = "¡Tío Pontos!"
  },
  AvgDialog_142891_Content_29 = {
    Text = "¡Eh, pequeño Jago, mira lo que te he traído!"
  },
  AvgDialog_142891_Content_3 = {
    Text = "La luna llena más brillante que jamás hayas visto cuelga en el cielo. Tus extremidades están Debilitadas y sin fuerzas, y tu mente también está algo entorpecida."
  },
  AvgDialog_142891_Content_30 = {
    Text = "Chasqueó los dedos, abrió la mano en el aire y una pesada brújula chapada en cobre cayó en tu palma."
  },
  AvgDialog_142891_Content_31 = {
    Text = "Más vale que esto haya llegado por medios honestos. Esta casa no puede albergar más \"muestras de amor\" ni \"corazones rotos\"."
  },
  AvgDialog_142891_Content_32 = {
    Text = "Leisha le devolvió la caja de joyas con una sonrisa burlona y señaló con la barbilla hacia la ventana, por donde el barco que llevaba la otra mitad de esos \"corazones rotos\" acababa de salir del puerto."
  },
  AvgDialog_142891_Content_33 = {
    Text = "Ah, vamos... me conoces. Nunca he sabido decir que no."
  },
  AvgDialog_142891_Content_34 = {
    Text = "Sonriendo, Pontos ladeó la cabeza y esquivó un fuerte manotazo de Leisha, luego te dejó en el suelo."
  },
  AvgDialog_142891_Content_35 = {
    Text = "Por cierto, he hecho nuevos amigos. Puede que tengamos que hablar, Leisha."
  },
  AvgDialog_142891_Content_36 = {
    Text = "Sobre las cosas de las que no quieres hablar."
  },
  AvgDialog_142891_Content_37 = {
    Text = "Demasiado ocupado estudiando tu nuevo tesoro, no notaste la expresión sombría que se dibujó en el rostro de Leisha. Pontos te revolvió el cabello."
  },
  AvgDialog_142891_Content_38 = {
    Text = "Tu madre y yo tenemos algunas cosas de las que hablar. Si mi joven favorito está dispuesto a ir a jugar arriba un rato, le contaré maravillosas historias de mis viajes. ¿Trato?"
  },
  AvgDialog_142891_Content_39 = {
    Text = "Extendió la mano, y por el bien de la brújula la tomaste—es el \"Apretón de Trato\" que pertenecía solo a los dos."
  },
  AvgDialog_142891_Content_4 = {
    Text = "Al levantar la mano, las arrugas que representan la vejez ya se han extendido por toda tu piel."
  },
  AvgDialog_142891_Content_40 = {Text = "..."},
  AvgDialog_142891_Content_41 = {
    Text = "Tumbado en el suelo del dormitorio de arriba, sacaste un mapa y te pusiste, con profunda concentración, a usar la brújula para encontrar los rumbos de aquellas historias marineras."
  },
  AvgDialog_142891_Content_42 = {
    Text = "Sin embargo, esta casa era demasiado vieja, y el océano y el viento la habían ido desgastando constantemente. Algunas palabras sueltas aún se filtraban por las rendijas del suelo."
  },
  AvgDialog_142891_Content_43 = {
    Text = "...ya... decir... no puedes solo... esconderse no es una solución."
  },
  AvgDialog_142891_Content_44 = {
    Text = "...Esos <Italic:seres>... puedo... Mi talento..."
  },
  AvgDialog_142891_Content_45 = {
    Text = "El tono del tío Pontos se volvía cada vez más urgente. Justo cuando estabas a punto de acercar más la oreja por curiosidad..."
  },
  AvgDialog_142891_Content_46 = {
    Text = "¡CRASH! ¡PUM!"
  },
  AvgDialog_142891_Content_47 = {
    Text = "La puerta se abrió de golpe, Pontos fue arrojado dentro agarrado por el cuello, y Leisha puso cara seria con una expresión que significaba \"no hay nada que discutir\"."
  },
  AvgDialog_142891_Content_48 = {
    Text = "No estoy de acuerdo, Pontos. Mi único deseo es que todos estéis a salvo y con vida... Aléjate de esos nuevos amigos tuyos."
  },
  AvgDialog_142891_Content_49 = {
    Text = "Si las cosas realmente se salen de control, os llevaré a todos lejos de aquí."
  },
  AvgDialog_142891_Content_5 = {
    Text = "Ah, resulta que ya he llegado a esta edad... Quizás esta sea la última noche."
  },
  AvgDialog_142891_Content_50 = {
    Text = "Oye, Leisha, ¡ya no soy un niño! No podemos seguir huyendo para siempre."
  },
  AvgDialog_142891_Content_51 = {
    Text = "Primero aprende a ayudarme con el negocio. Deja de andar vagando por ahí todo el día antes de hablar de eso."
  },
  AvgDialog_142891_Content_52 = {
    Text = "Pocas veces habías oído a Leisha hablar con tanta dureza. Tomó aire y logró esbozar una sonrisa forzada para ti."
  },
  AvgDialog_142891_Content_53 = {
    Text = "Jago, hazle un favor a mamá. Vigila a tu tío, al menos esta noche no dejes que salga a deambular."
  },
  AvgDialog_142891_Content_54 = {
    Text = "Dejó esas palabras atrás y bajó rápidamente a los libros de cuentas que nunca parecían acabar, como si tuviera prisa por poner fin a la conversación lo antes posible."
  },
  AvgDialog_142891_Content_55 = {
    Text = "Pontos arqueó una ceja y se encogió de hombros mirándote."
  },
  AvgDialog_142891_Content_56 = {
    Text = "Bueno, Jago, parece que podemos adelantar un poquito la hora de los cuentos."
  },
  AvgDialog_142891_Content_57 = {Text = "..."},
  AvgDialog_142891_Content_58 = {
    Text = "Quizás aquellos relatos que salían rodando de los camarotes junto con la carga eran demasiado emocionantes y fantásticos. Incluso a medianoche, no dormías profundamente."
  },
  AvgDialog_142891_Content_59 = {
    Text = "La luz de la luna que entraba por la ventana bañaba tus párpados con un brillo plateado. Algo la bloqueó."
  },
  AvgDialog_142891_Content_6 = {
    Text = "Los recuerdos regresan gradualmente, pero extrañamente, no hay miedo a la muerte en tu corazón. En su lugar, sonríes desde una profunda paz interior."
  },
  AvgDialog_142891_Content_60 = {
    Text = "Un clic—el pestillo de la ventana. Abriste los ojos. La ventana ya estaba abierta de par en par."
  },
  AvgDialog_142891_Content_61 = {Text = "¡!"},
  AvgDialog_142891_Content_62 = {
    Text = "¡Tío Pontos, no puedes salir por la ventana! ¡Mamá se enfadará!"
  },
  AvgDialog_142891_Content_63 = {
    Text = "Pontos ya había asomado más de medio cuerpo por el alféizar de la ventana, y sin pensarlo dos veces corriste a abrazarlo, olvidando incluso preguntarte por qué parecía estar... suspendido en el aire."
  },
  AvgDialog_142891_Content_64 = {
    Text = "¡Espera, ten cuidado!"
  },
  AvgDialog_142891_Content_65 = {
    Text = "Llegó la sensación de ingravidez, y luego—"
  },
  AvgDialog_142891_Content_66 = {
    Text = "¡¡WHOOSH!!"
  },
  AvgDialog_142891_Content_67 = {
    Text = "¡¡Raaas—!!"
  },
  AvgDialog_142891_Content_69 = {
    Text = "...! ...!!!!"
  },
  AvgDialog_142891_Content_7 = {
    Text = "Tus seres queridos te rodean, y la más pequeña de tus nietas, Vera, aún no entiende nada, solo se recuesta afectuosamente junto a tu mano."
  },
  AvgDialog_142891_Content_70 = {
    Text = "Te levantaron de un tirón por la tela de tu cintura, la extraña sensación de un pelaje suave rozándote la cara."
  },
  AvgDialog_142891_Content_71 = {
    Text = "Cuando abriste los ojos, un escalofrío de horror te recorrió la columna vertebral."
  },
  AvgDialog_142891_Content_72 = {Text = "Pon—"},
  AvgDialog_142891_Content_73 = {
    Text = "La cola de una criatura sin rasgos e indescriptible estaba enganchada detrás de tu espalda, con la punta cubierta de horribles púas."
  },
  AvgDialog_142891_Content_74 = {
    Text = "No tuviste tiempo de asimilar que esa cosa aterradora claramente acababa de salvarte—de forma incontrolable, un grito ahogado se abrió paso desde tu garganta."
  },
  AvgDialog_142891_Content_75 = {Text = "¡Shh!"},
  AvgDialog_142891_Content_76 = {
    Text = "Pontos, tendido sobre aquella criatura sin rostro, te alzó de un tirón, tapándote la boca con fuerza, mientras la criatura desplegaba sus enormes alas de murciélago y se deslizaba en silencio hacia la oscuridad de la noche."
  },
  AvgDialog_142891_Content_77 = {
    Text = "No tengas miedo. No te harán daño."
  },
  AvgDialog_142891_Content_78 = {
    Text = "No hay tiempo, Jago. Quédate callado—ya te lo explicaré todo después."
  },
  AvgDialog_142891_Content_79 = {
    Text = "Pontos te rodeó los hombros con un brazo para tranquilizarte, colocándote entre él y la criatura, con el cuerpo agachado y los ojos fijos en los arrecifes rocosos de un rincón remoto del puerto."
  },
  AvgDialog_142891_Content_8 = {
    Text = "Abuelo, ¿cuándo podrás volver a jugar conmigo? Mira, ya aprendí lo que me enseñaste la última vez."
  },
  AvgDialog_142891_Content_80 = {
    Text = "Antes de que pudieras preguntar nada, un sonido amenazador emergió reptando del mar, como gusanos."
  },
  AvgDialog_142891_Content_81 = {
    Text = "<Shake:<Red:Susurro, susurro... susurro, susurro...>>"
  },
  AvgDialog_142891_Content_82 = {
    Text = "<Shake:<Red:Plaf, plaf... ¡Splat!>>"
  },
  AvgDialog_142891_Content_83 = {
    Text = "!... Urgh..."
  },
  AvgDialog_142891_Content_84 = {
    Text = "Primero aparecieron pies con garras cubiertos de escamas, luego brazos —o quizás extremidades blandas y retorcidas de artrópodo—, cuerpos incrustados de percebes y una baba blasfemamente abominable..."
  },
  AvgDialog_142891_Content_85 = {
    Text = "Solo conocías el mar como una fuente inagotable de alimento. Jamás imaginaste que también pudiera albergar semejantes abominaciones. Sus ojos saltones y aterradores estaban llenos de malicia mientras contemplaban los edificios del pueblo."
  },
  AvgDialog_142891_Content_86 = {
    Text = "<Change>@4Tipu... por donde pasa..."
  },
  AvgDialog_142891_Content_87 = {
    Text = "<Change>...debe pasar por aquí... ¡alimentar la Disolución, entregarse a la Disolución! ¡Carne, carne!!"
  },
  AvgDialog_142891_Content_88 = {
    Text = "<Small:<Shake:¡Tío, un mons... hay un monstruo!!>>"
  },
  AvgDialog_142891_Content_89 = {
    Text = "Al segundo siguiente, la criatura alada sin rostro bajo tus pies se lanzó en picado. Pontos extendió sus dedos huesudos y una luz oscura se precipitó hacia los dos monstruos miserables."
  },
  AvgDialog_142891_Content_9 = {
    Text = "Ella sostiene un saltamontes de paja torcido y lo coloca sobre la manta."
  },
  AvgDialog_142891_Content_90 = {
    Text = "¡Ngh, mmph!"
  },
  AvgDialog_142891_Content_91 = {
    Text = "Se desplomaron inertes en el suelo, como dos estatuas de piedra cercenadas."
  },
  AvgDialog_142891_Content_92 = {
    Text = "Tap... un toque suave."
  },
  AvgDialog_142891_Content_93 = {
    Text = "Luego aquellos dos fragmentos de cuerpo cayeron al suelo y se convirtieron en polvo gris arrastrado por el viento del mar."
  },
  AvgDialog_142891_Content_94 = {
    Text = "Vaya, sabía que siempre habría uno o dos que se escaparían de la red; Leisha y los demás siguen siendo demasiado descuidados."
  },
  AvgDialog_142891_Content_95 = {
    Text = "<Shake:¿Mamá y los demás? Tío Pontos, ¿qué está pasando aquí?!>"
  },
  AvgDialog_142891_Content_96 = {
    Text = "El miedo casi te dobló las piernas y estuviste a punto de resbalar del liso lomo de la criatura."
  },
  AvgDialog_142891_Content_97 = {
    Text = "Aguanta un poco más. Primero necesito asegurarme de que están bien."
  },
  AvgDialog_142891_Content_98 = {
    Text = "Pontos te dio una palmada en el hombro y luego guió a la criatura para que los llevara a ambos hacia la costa al otro lado del pueblo."
  },
  AvgDialog_142891_Content_99 = {Text = "..."},
  AvgDialog_142892_Content_1 = {
    Text = "Cuando Te Fuiste"
  },
  AvgDialog_142892_Content_10 = {
    Text = "Arena amarilla."
  },
  AvgDialog_142892_Content_11 = {
    Text = "Campos de Nieve."
  },
  AvgDialog_142892_Content_12 = {Text = "Vacío."},
  AvgDialog_142892_Content_13 = {
    Text = "Y luego de vuelta a la noche."
  },
  AvgDialog_142892_Content_14 = {
    Text = "Este no es un viaje ni una trayectoria que los humanos puedan comprender. El tiempo y el espacio han perdido todo significado. Simplemente sigues atravesando, patrullando. Lo experimentas todo, y luego eres destruido por todo."
  },
  AvgDialog_142892_Content_15 = {
    Text = "¡Ya que se atrevieron a entrometerse, desterradlos del mundo mortal! ¡Haced que nos teman! ¡Haced que recuerden mi nombre!"
  },
  AvgDialog_142892_Content_16 = {
    Text = "Pontos gasta el poder que ha tomado con temerario abandono, y los seres que lo han ganado ahora despedazan también a sus enemigos."
  },
  AvgDialog_142892_Content_17 = {
    Text = "Incontables monstruos retorcidos y repugnantes son cazados por los Siervos-Gaunt y los Guardianes-Gaunt."
  },
  AvgDialog_142892_Content_18 = {
    Text = "Son atravesados, incorporados a la juerga, arrancando silbidos y carcajadas de celebración sin fin."
  },
  AvgDialog_142892_Content_19 = {
    Text = "¡No, no, otra vez no, nonononono!!!!!!"
  },
  AvgDialog_142892_Content_2 = {
    Text = "La extraña sensación de un pelaje suave, el afilado aguijón en su cola, enormes alas membranosas cortando silenciosamente el cielo nocturno."
  },
  AvgDialog_142892_Content_20 = {
    Text = "Viste con tus propios ojos cómo el rayo que Pontos desató redujo al fanático a polvo, pero inmediatamente después, su cuerpo se reensambló una vez más, un aullido de miedo brotando de su boca."
  },
  AvgDialog_142892_Content_21 = {
    Text = "Este era el más devoto de todos los cultistas. Y ya ha soportado la muerte y el reensamblaje en agonía más veces de las que nadie podría contar."
  },
  AvgDialog_142892_Content_22 = {
    Text = "Tío Pontos, esta... <Italic:cosa>... ¿está volviendo a la vida?"
  },
  AvgDialog_142892_Content_23 = {
    Text = "No. Simplemente está muriendo y volviendo, una y otra vez, para saborear el sufrimiento que se le prometió."
  },
  AvgDialog_142892_Content_24 = {
    Text = "A veces los dejo morir, siempre y cuando renuncien a adorar a esos dioses inmundos y blasfemos."
  },
  AvgDialog_142892_Content_25 = {
    Text = "Pero si su fe es demasiado profunda, entonces ni siquiera la muerte puede liberarlos de su sufrimiento."
  },
  AvgDialog_142892_Content_26 = {
    Text = "Hablando con tanta naturalidad como si fuera un asunto trivial, Pontos alzó la palma. Una fuerza invisible extendió los brazos del fanático, dobló su torso hacia delante y lo obligó a arrodillarse postrado ante Pontos."
  },
  AvgDialog_142892_Content_27 = {
    Text = "Ahora, dime una vez más... ¿sigues adorando a tu dios inmundo?"
  },
  AvgDialog_142892_Content_28 = {
    Text = "<LightGray:*sollozos>No... no, te lo suplico, por favor, déjame morir, ¡Siempre Que me dejes morir!"
  },
  AvgDialog_142892_Content_29 = {
    Text = "<Shake:Jajaja, jajajajaja, no hay salvador, no hay ningún salvador, solo AB@2S, ¡¡solo @2@3!!>"
  },
  AvgDialog_142892_Content_3 = {
    Text = "Pontos te lleva consigo en la cacería que precede a la juerga nocturna de Ebwynnos."
  },
  AvgDialog_142892_Content_30 = {
    Text = "Muy bien, presa. Levanta la cabeza. Expón tu garganta."
  },
  AvgDialog_142892_Content_31 = {
    Text = "El fanático, con la mente en crash, emite sollozos distorsionados y carcajadas enloquecidas, avanza de rodillas y levanta el cuello en una postura grotesca."
  },
  AvgDialog_142892_Content_32 = {
    Text = "Te concederé la muerte."
  },
  AvgDialog_142892_Content_33 = {
    Text = "La luz atravesó Su garganta como un cuchillo caliente a través de la mantequilla. Su cuerpo se desplomó repentinamente en cenizas y polvo, arrastrado por el viento hacia el océano."
  },
  AvgDialog_142892_Content_34 = {
    Text = "Esta vez, el patético cultista no regresa."
  },
  AvgDialog_142892_Content_35 = {
    Text = "¿Adónde van los demás? ¿Los monstruos que son atrapados?"
  },
  AvgDialog_142892_Content_36 = {
    Text = "También están en Ebwynnos."
  },
  AvgDialog_142892_Content_37 = {
    Text = "Un Ebwynnos igual de eterno, solo que sin la alegría."
  },
  AvgDialog_142892_Content_38 = {
    Text = "Allí, nada existe. Incluso el dolor sería una misericordia."
  },
  AvgDialog_142892_Content_39 = {
    Text = "Lo entiendes a medias. La luz de la luna brilla. Los Gaunt te guardan mientras este extraño viaje se acerca a su fin."
  },
  AvgDialog_142892_Content_4 = {
    Text = "A través de incontables medios más allá de toda comprensión, los habitantes de Ebwynnos cazan a su \"presa\" por innumerables dimensiones."
  },
  AvgDialog_142892_Content_40 = {
    Text = "Cierra los ojos, Jago."
  },
  AvgDialog_142892_Content_41 = {
    Text = "Una oscuridad húmeda, familiar e íntima te abrazó, te engulló por completo."
  },
  AvgDialog_142892_Content_42 = {
    Text = "Regresaste a la Casa Alta. Pontos descendió del carruaje, desvelando el preludio de otra celebración más."
  },
  AvgDialog_142892_Content_43 = {
    Text = "Parece que este niño te ha tomado bastante cariño."
  },
  AvgDialog_142892_Content_44 = {
    Text = "Cerca del alféizar junto a la terraza, Pontos se apartó de la animada multitud y extendió su mano hacia la Pesadilla que sobrevolaba fuera de la ventana."
  },
  AvgDialog_142892_Content_45 = {
    Text = "No puedo recordar muchas cosas con claridad por alguna razón, pero... Tío Pontos, ya no eres humano, y este ya no es el mundo tal como lo entiendo, ¿verdad?"
  },
  AvgDialog_142892_Content_46 = {
    Text = "¿Ya estoy muerto?"
  },
  AvgDialog_142892_Content_47 = {
    Text = "Aparentemente sin esperar que preguntaras tan directamente, Pontos alzó las cejas con sorpresa, y luego—se rio."
  },
  AvgDialog_142892_Content_48 = {
    Text = "Mi querido pequeño amigo, por supuesto que no."
  },
  AvgDialog_142892_Content_49 = {
    Text = "Quédate en Ebwynnos, y vivirás la vida grandiosa y extraordinaria que anhelabas cuando leías cuentos de niño. Nunca más serás desgastado."
  },
  AvgDialog_142892_Content_5 = {
    Text = "Ese inquietante resplandor aún pulsa desde el interior de las ventanas de la casa."
  },
  AvgDialog_142892_Content_50 = {
    Text = "Viviremos aventuras, escaparemos del mundo mundano. Esos enemigos que trajeron caos y desastre a nuestras vidas serán finalmente derrotados hasta que nunca más se atrevan a mostrar sus rostros."
  },
  AvgDialog_142892_Content_51 = {
    Text = "Respiraste hondo. Sentiste ese saltamontes de nuevo—tosco, áspero, ligeramente punzante."
  },
  AvgDialog_142892_Content_52 = {
    Text = "Sí, todo eso suena maravilloso."
  },
  AvgDialog_142892_Content_53 = {
    Text = "Pero, ¿qué precio debo pagar, tío Pontos?"
  },
  AvgDialog_142892_Content_54 = {
    Text = "Su ceño se frunció con una lentitud agónica, cargando una especie de altiva arrogancia que no te resultaba familiar."
  },
  AvgDialog_142892_Content_55 = {
    Text = "El precio es solo... algo que en absoluto importa, algo que no necesitas y que no recordarás. <Red:Dámelo>, Jago."
  },
  AvgDialog_142892_Content_56 = {
    Text = "En el instante en que terminó de hablar, la cola con púas de la pesadilla descendió desde fuera de la ventana hacia tu bolsillo."
  },
  AvgDialog_142892_Content_57 = {
    Text = "Hacia el saltamontes desvencijado que has estado escondiendo."
  },
  AvgDialog_142892_Content_58 = {Text = "¡No!"},
  AvgDialog_142892_Content_59 = {
    Text = "Retrocediste instintivamente a trompicones, pero el movimiento pareció enfurecer a Pontos, y te agarró del brazo."
  },
  AvgDialog_142892_Content_6 = {
    Text = "Siervo-Gaunt tras Siervo-Gaunt giran en el aire, hasta que Pontos —de pie a tu lado dentro de un carruaje que irradia un indescriptible resplandor nacarado— suelta un grito resonante."
  },
  AvgDialog_142892_Content_60 = {
    Text = "Simplemente no lo entiendes, niño. ¿Sabes cuánto esfuerzo me costó encontrarte...?"
  },
  AvgDialog_142892_Content_61 = {
    Text = "Cu–cu, cu–cu..."
  },
  AvgDialog_142892_Content_62 = {
    Text = "Te quedaste paralizado en el sitio. No eran solo los dedos de Pontos presionando contra tu piel—un miedo innombrable te hizo levantar la mirada, y las pupilas azul profundo de Pontos se cernieron pesadamente sobre ti."
  },
  AvgDialog_142892_Content_63 = {
    Text = "Ya que quieres ver, entonces mira bien—exactamente de qué clase de cosa te rescaté."
  },
  AvgDialog_142892_Content_64 = {
    Text = "Has sido <Red:engullido> de nuevo."
  },
  AvgDialog_142892_Content_65 = {Text = "..."},
  AvgDialog_142892_Content_66 = {
    Text = "¡Eh, eh, viejo amigo! ¿Oíste lo que dije? ¡Te has quedado en las nubes otra vez! ¡Cuidado!"
  },
  AvgDialog_142892_Content_67 = {
    Text = "¡Splash! Agua fangosa te golpeó la cara y volviste de golpe a la realidad, mirando atónito a la persona a tu lado. Envejecido, encorvado y parloteando sin cesar—pero lo reconociste. Era inconfundiblemente un Orney anciano."
  },
  AvgDialog_142892_Content_68 = {
    Text = "¡Estos malditos Marineros, completamente fuera de control! Si me preguntas, tanto viaje les ha asilvestrado el corazón. ¡No son capaces de centrarse en nada práctico!"
  },
  AvgDialog_142892_Content_69 = {
    Text = "¿Orney? ...¿De qué estás hablando? De niños siempre soñabas con ser marinero, con ver todos los continentes."
  },
  AvgDialog_142892_Content_7 = {
    Text = "¡Atrápalos, asegúrate de que nunca puedan volver a irse, haz que sufran aquí por toda la eternidad!"
  },
  AvgDialog_142892_Content_70 = {
    Text = "¿De verdad dije algo así? No seas ridículo. A nuestra edad, deberías saber que la estabilidad es lo mejor."
  },
  AvgDialog_142892_Content_71 = {
    Text = "¿Lo olvidaste, viejo amigo? Desde segundo año de universidad dejamos de hablar de eso. Hablamos de las noticias del periódico, de esos malditos informes uno tras otro, de la pensión de jubilación, de las reuniones familiares cada dos semanas."
  },
  AvgDialog_142892_Content_72 = {
    Text = "Te dio una palmada en el hombro y recogió temblorosamente dos bolsas de papel de la ventanilla de la farmacia."
  },
  AvgDialog_142892_Content_73 = {
    Text = "¿No eres igual que yo? Después de graduarnos y volver aquí, menos mal, ya ni nos molestamos en hacer un viaje largo."
  },
  AvgDialog_142892_Content_74 = {
    Text = "Esta maldita artritis. Gracias a Dios—aparte de ti y de estos analgésicos, no hay nada más que me obligue a salir de casa."
  },
  AvgDialog_142892_Content_75 = {
    Text = "¡La soledad! De jóvenes pensábamos que era tan real como el Bigfoot."
  },
  AvgDialog_142892_Content_76 = {
    Text = "Orney seguía parloteando sobre algo. Te quedaste mirando sus labios abriéndose y cerrándose, y una repentina oleada de mareo te arrancó de la rutina mundana."
  },
  AvgDialog_142892_Content_77 = {Text = "..."},
  AvgDialog_142892_Content_78 = {
    Text = "¿Viste en qué convirtieron esos días mundanos a Orney? Ve a echar otro vistazo—a lo que intercambiaste."
  },
  AvgDialog_142892_Content_79 = {
    Text = "Te ves a ti mismo, tendido en la cama, marchito y consumido."
  },
  AvgDialog_142892_Content_8 = {Text = "Nubes."},
  AvgDialog_142892_Content_80 = {
    Text = "Por supuesto, al principio estarán tristes, derramarán algunas lágrimas por ti."
  },
  AvgDialog_142892_Content_81 = {
    Text = "Ves a una pareja y a su pequeña hija saliendo a pasear, consolándose mutuamente."
  },
  AvgDialog_142892_Content_82 = {
    Text = "Pero en una semana, o incluso en unos pocos días, lo superarán sin más."
  },
  AvgDialog_142892_Content_83 = {
    Text = "Cenas, paseos, a la universidad, ¿quién sabe? Los niños quizás aguanten un poco más. No mucho, claro."
  },
  AvgDialog_142892_Content_84 = {
    Text = "Al final, no quedará nada. Nadie te recordará."
  },
  AvgDialog_142892_Content_85 = {
    Text = "Invierno, primavera, otro invierno. Observas cómo el polvo se asienta lentamente por toda la casa."
  },
  AvgDialog_142892_Content_86 = {
    Text = "¿Lo entiendes ahora, Jago? Simplemente traje las partes interesantes de todos ustedes... las partes vibrantes... a Ebwynnos."
  },
  AvgDialog_142892_Content_87 = {
    Text = "Tu cuerpo vacío está a punto de morir. Con o sin ti, todos los que alguna vez conociste seguirán viviendo sus propias vidas, vidas que no tienen nada que ver contigo."
  },
  AvgDialog_142892_Content_88 = {
    Text = "La voz de Pontos resuena en tus oídos, y al segundo siguiente, reapareces en el gran salón de la Casa Alta de Ebwynnos."
  },
  AvgDialog_142892_Content_89 = {
    Text = "Ahora, Jago, piénsalo—piénsalo bien. Despréndete de ese cascarón, abandona esos recuerdos sin sentido y quédate con nosotros."
  },
  AvgDialog_142892_Content_9 = {
    Text = "Tierra aniquilada."
  },
  AvgDialog_142892_Content_90 = {
    Text = "Orney, Tío White y todos en el abarrotado salón de baile de Ebwynnos parecen darse cuenta de repente."
  },
  AvgDialog_142892_Content_91 = {
    Text = "¡Eh, por qué tienen esas caras ustedes dos? ¡Acabamos de conseguir otra gran victoria!"
  },
  AvgDialog_142892_Content_92 = {
    Text = "¡Vamos, Jago, bebe bien con nosotros. No hay nada de qué preocuparse en Ebwynnos!"
  },
  AvgDialog_142892_Content_93 = {
    Text = "Ríen de buena gana y te acogen entre ellos."
  },
  AvgDialog_142892_Content_94 = {
    Text = "La gente está repartiendo ahora el botín. Las mareas vuelven a resonar en tus oídos."
  },
  AvgDialog_142892_Content_95 = {
    Text = "Pontos te tiende la mano, esperando que la tomes."
  },
  AvgDialog_142892_Content_96 = {
    Text = "Igual que ese \"apretón de trato\" que acordaron de niños."
  },
  AvgDialog_142893_Content_1 = {Text = "La Razón"},
  AvgDialog_142893_Content_10 = {
    Text = "<Red:No debería ser así.>"
  },
  AvgDialog_142893_Content_11 = {
    Text = "Debería haber sido que tú descubrieras tu linaje por accidente, que mamá fuera persuadida por el tío Pontos para guiarte, y juntos emprendierais un viaje, experimentando todo tipo de cosas emocionantes, apasionantes y maravillosas."
  },
  AvgDialog_142893_Content_12 = {
    Text = "<Shake:Y entonces te convertirás en un gran <Red:héroe>, así es como se escribe en las novelas de aventuras.>"
  },
  AvgDialog_142893_Content_13 = {
    Text = "¡Jago! ¡Anímate, todo irá bien, tu madre es la más fuerte de los Gauntward que he conocido, todo se resolverá!"
  },
  AvgDialog_142893_Content_14 = {
    Text = "Yo... Tío Pontos, mamá..."
  },
  AvgDialog_142893_Content_15 = {
    Text = "El que una vez fue un pueblo tranquilo quedó completamente envuelto en llamas."
  },
  AvgDialog_142893_Content_16 = {
    Text = "Solo había pasado un día cuando, de repente y de manera abrumadora, los fanáticos inundaron todo cuanto alcanzaba tu vista."
  },
  AvgDialog_142893_Content_17 = {
    Text = "Entre ellos había tanto humanos como monstruos de pies a cabeza, y sus ataques indiscriminados hacían que todo el pueblo ardiera en llamas."
  },
  AvgDialog_142893_Content_18 = {
    Text = "Sangre con un sabor salobre y metálico te salpicó el rostro y el cuerpo. Pontos canalizaba desesperadamente el silbato de caza en su mano, abriendo un camino a la fuerza junto a su Pesadilla."
  },
  AvgDialog_142893_Content_19 = {
    Text = "¡Pontos, llévate a Jago y corred!"
  },
  AvgDialog_142893_Content_2 = {
    Text = "Esa noche, agotado por tanto miedo y tanto pensar, te quedaste dormido enseguida."
  },
  AvgDialog_142893_Content_20 = {
    Text = "Leisha, que junto a los demás Gauntward luchaba desesperadamente por detener la marea de monstruos, al verte sano y salvo, le brillaron los Ojos y gritó a Pontos con todas sus fuerzas."
  },
  AvgDialog_142893_Content_21 = {Text = "¡Screeee!"},
  AvgDialog_142893_Content_22 = {
    Text = "Otra cabeza similar a una anémona de mar fue desgarrada por las afiladas garras de la Pesadilla. Leisha lanzó despreocupadamente un destello de la misma luz blanca críptica que Pontos, impidiéndole cargar hacia ella."
  },
  AvgDialog_142893_Content_23 = {
    Text = "No podemos ganar esta, pero aún podemos ganar algo de tiempo. ¡Corred, tan lejos como podáis!"
  },
  AvgDialog_142893_Content_24 = {
    Text = "¡No seas ridículo, has resuelto situaciones con más enemigos que esta sin problemas, no te pasará nada! Además, ya sabes, siempre encontramos la manera."
  },
  AvgDialog_142893_Content_25 = {
    Text = "No sabías qué quería decir el tío Pontos con «una salida». Solo viste cómo su mirada caía sobre aquel silbato de caza, el que no había soltado de su mano desde el día en que regresó."
  },
  AvgDialog_142893_Content_26 = {
    Text = "No, <Red:jamás.>"
  },
  AvgDialog_142893_Content_27 = {
    Text = "<Shake:Sé lo que estás pensando. <Red:¡Mi hermano no puede quedarse atrapado para siempre en ese maldito lugar!>   >"
  },
  AvgDialog_142893_Content_28 = {
    Text = "¡Abraza el Festín@1, alimenta la Erosión!"
  },
  AvgDialog_142893_Content_29 = {
    Text = "¡¡¡Leisha!!!"
  },
  AvgDialog_142893_Content_3 = {
    Text = "Tanto tú como Pontos pensabais que tendríais muchas más oportunidades de hablar de ello."
  },
  AvgDialog_142893_Content_30 = {
    Text = "Entre el estruendo de escamas que se desgarraban, un fanático con medio cuerpo ya arrancado hizo que sus Carmesí globos oculares sobresalieran por completo, y se abalanzó sobre Leisha gruñendo con Furia."
  },
  AvgDialog_142893_Content_31 = {
    Text = "...El chirriante sonido de piel y músculo desgarrándose."
  },
  AvgDialog_142893_Content_32 = {
    Text = "El sonido de dos cuerpos estrellándose contra el camino empedrado."
  },
  AvgDialog_142893_Content_33 = {
    Text = "El sonido de entrañas derramándose."
  },
  AvgDialog_142893_Content_34 = {
    Text = "Entonces, el mundo enmudeció en un instante. No podías oír nada, no podías ver nada."
  },
  AvgDialog_142893_Content_35 = {
    Text = "Sangre, cielo nocturno, luna."
  },
  AvgDialog_142893_Content_36 = {
    Text = "Una luna color sangre, colgando a lo lejos en el cielo distante."
  },
  AvgDialog_142893_Content_37 = {
    Text = "Ah... ahhh."
  },
  AvgDialog_142893_Content_38 = {
    Text = "¡¡¡¡¡AAAAAAAAHHHHH!!!!!"
  },
  AvgDialog_142893_Content_39 = {
    Text = "Tras un breve gemido sin aliento exprimido desde lo más profundo de su garganta, Pontos emitió algo que jamás habías escuchado en toda tu vida."
  },
  AvgDialog_142893_Content_4 = {
    Text = "<Red:Pero no fue así.>"
  },
  AvgDialog_142893_Content_40 = {
    Text = "Un lamento completamente inhumano."
  },
  AvgDialog_142893_Content_41 = {
    Text = "Her... Hermana... Leisha, ¡¡¡LEISHA!!!"
  },
  AvgDialog_142893_Content_42 = {
    Text = "Un zumbido penetrante resonó en tu cerebro, y una oleada abrumadora de desconcierto te golpeó como un maremoto. No, no, no, no, no no no no no no..."
  },
  AvgDialog_142893_Content_43 = {
    Text = "Nadie sobrevivió. Los Siervo-Gaunt, que de día no parecían más que amables vecinos, caían uno tras otro. Los habitantes ordinarios del pueblo chillaban en el mar de fuego y la marea de monstruos."
  },
  AvgDialog_142893_Content_44 = {
    Text = "Pero tú ya no podías escuchar nada de eso. Tu cuerpo te había traicionado por completo y lloraba junto a ellos, un grito crudo y desgarrador."
  },
  AvgDialog_142893_Content_45 = {
    Text = "<Change>¡Sacrificio! ¡Sacrificadlos a todos al <Red:Éxtasis>!"
  },
  AvgDialog_142893_Content_46 = {
    Text = "Los demás fanáticos te localizaron sin el menor problema, y justo cuando aquellas garras escamosas, chorreando una baba blasfema, se extendieron hacia ti..."
  },
  AvgDialog_142893_Content_47 = {
    Text = "Pontos sopló el silbato de caza."
  },
  AvgDialog_142893_Content_48 = {
    Text = "Jamás habías escuchado un sonido tan estridente y tan antiguo. Algún poder irracional atravesó directamente tus tímpanos y golpeó hasta el último vestigio de cordura en tu mente."
  },
  AvgDialog_142893_Content_49 = {
    Text = "¡Una presión incomparable y vasta se abatió sobre la tierra!"
  },
  AvgDialog_142893_Content_5 = {
    Text = "¡Hisss...!"
  },
  AvgDialog_142893_Content_50 = {
    Text = "Una fuerza invisible y enorme aplastó a Pontos contra el suelo, pero él no parecía sentirla en absoluto, con los ojos abiertos de par en par mientras recitaba una oración incomprensible."
  },
  AvgDialog_142893_Content_51 = {
    Text = "Oh @2, @4,@3 Señor del Abismo, te invoco en nombre de @3..."
  },
  AvgDialog_142893_Content_52 = {
    Text = "Incontables presencias semejantes a brazos negros se extendieron desde grietas más profundas que el océano más antiguo, buscando a la única <Red:presa> que deseaban."
  },
  AvgDialog_142893_Content_53 = {
    Text = "<Shake:Buscando al <Red:amo >que Ellos habían elegido.>"
  },
  AvgDialog_142893_Content_54 = {
    Text = "<Change>¡Toma mi carne, toma mi alma, toma todo!"
  },
  AvgDialog_142893_Content_55 = {
    Text = "En aquel rostro que siempre lucía una sonrisa despreocupada, apareció ahora una expresión de trágica determinación y temerario abandono."
  },
  AvgDialog_142893_Content_56 = {
    Text = "Mientras algo mucho más grande y torrencial se fusionaba en él, unas alas que oscurecían el cielo se alzaron, levantando barrera tras barrera de oscuridad de un negro absoluto."
  },
  AvgDialog_142893_Content_57 = {
    Text = "<Change>¡Responde a la plegaria de tu Executor... ¡¡redúcelos a polvo!!"
  },
  AvgDialog_142893_Content_58 = {
    Text = "A estas alturas, nadie podía distinguir aquel sonido profundo e insondable de la voz que alguna vez había sido la de Pontos."
  },
  AvgDialog_142893_Content_59 = {
    Text = "Se convirtieron en uno, indistinguibles, tal como Ellos deseaban."
  },
  AvgDialog_142893_Content_6 = {
    Text = "<Shake:<Red:No es así, la historia de aventuras del héroe no debería ser así.>>"
  },
  AvgDialog_142893_Content_60 = {
    Text = "Mientras el estridente silbido resonaba a lo largo de la costa, cada último sectario se desmoronó en cenizas blancas."
  },
  AvgDialog_142893_Content_61 = {Text = "..."},
  AvgDialog_142893_Content_62 = {
    Text = "¡Ahhh! ...¿Qué pasó después? El tío Pontos, y la madre del abuelo... ellos..."
  },
  AvgDialog_142893_Content_63 = {
    Text = "Vera había contenido la respiración durante todo el relato, y finalmente no pudo evitar exclamar, con los ojos a punto de llenarse de lágrimas."
  },
  AvgDialog_142893_Content_64 = {
    Text = "Lo que pasó después, por más que lo intento, simplemente no puedo recordarlo. Lo único que recuerdo es..."
  },
  AvgDialog_142893_Content_65 = {Text = "..."},
  AvgDialog_142893_Content_66 = {
    Text = "*Sollozo*... Jago... ¡Jago! Gracias al cielo, por fin despertaste."
  },
  AvgDialog_142893_Content_67 = {
    Text = "Papá, tía Resa, todos, nuestro pueblo, todo... ¡¡Buaaaaaaaaaa!!"
  },
  AvgDialog_142893_Content_68 = {
    Text = "A través del relato entre sollozos de Orney, tu amiga de la infancia, supiste que todo el pueblo había sido arrasado por una explosión masiva."
  },
  AvgDialog_142893_Content_69 = {
    Text = "Solo un puñado de personas sobrevivió entre las ruinas y fueron acogidas por familiares o amigos en pueblos vecinos. Habías estado inconsciente durante cuatro días enteros."
  },
  AvgDialog_142893_Content_7 = {
    Text = "¡Jago, cierra los ojos y sígueme!"
  },
  AvgDialog_142893_Content_70 = {
    Text = "No, no fue una explosión. Recuerdo claramente... ¡Ugh! Me duele mucho la cabeza."
  },
  AvgDialog_142893_Content_71 = {
    Text = "El penetrante ruido blanco en tu mente te hizo volver a caer dormido. Cuando despertaste de nuevo, te encontraste vagamente acunado en el abrazo de alguien."
  },
  AvgDialog_142893_Content_72 = {
    Text = "Mamá... ¿¡Mamá?!"
  },
  AvgDialog_142893_Content_73 = {
    Text = "No te muevas mucho. Tus heridas aún no han sanado."
  },
  AvgDialog_142893_Content_74 = {
    Text = "Viste con tus propios ojos que Leisha —a quien los fanáticos le habían desgarrado el vientre— estaba sentada junto a la cama completamente ilesa. La inmensa alegría hizo que tus ojos se abrieran de par en par mientras las lágrimas corrían por tu rostro."
  },
  AvgDialog_142893_Content_75 = {
    Text = "¡Mamá! ¿Fue todo un sueño? Sabía que estabas bien, sigues viva."
  },
  AvgDialog_142893_Content_76 = {
    Text = "Shh, escúchame, Jago. Mamá tiene que dejarte e irse a un lugar muy lejano."
  },
  AvgDialog_142893_Content_77 = {
    Text = "La familia de Orney cuidará bien de ti. Mañana por la mañana encontrarán suficiente dinero sobre la mesa. Debes vivir bien."
  },
  AvgDialog_142893_Content_78 = {
    Text = "Espera, ¿dejarme? Mamá, ¿por qué? ¿Y el tío Pontos? ¿Dónde está?"
  },
  AvgDialog_142893_Content_79 = {
    Text = "Leisha se quedó en silencio de repente. Tras un momento, apretó tu mano con fuerza, presionó la brújula de cobre que habías dejado caer de vuelta en tu palma, y se inclinó para besar tu frente."
  },
  AvgDialog_142893_Content_8 = {
    Text = "¡Roar! ¡Roar!"
  },
  AvgDialog_142893_Content_80 = {
    Text = "Jago, guarda esto. Júrame que seguirás viviendo a salvo, en algún lugar."
  },
  AvgDialog_142893_Content_81 = {
    Text = "Querías desesperadamente negar con la cabeza, pero Leisha no te dio la oportunidad."
  },
  AvgDialog_142893_Content_82 = {
    Text = "Recuerda, nunca vengas a buscarme ni a tu tío. Nunca."
  },
  AvgDialog_142893_Content_83 = {
    Text = "¡Mamá!..."
  },
  AvgDialog_142893_Content_84 = {
    Text = "Te incorporaste de golpe."
  },
  AvgDialog_142893_Content_85 = {
    Text = "Una suave brisa agitó las hojas. La noche había caído sin que te dieras cuenta."
  },
  AvgDialog_142893_Content_86 = {
    Text = "¿Fue un sueño? Tu madre Leisha no estaba por ningún lado. Orney, que dormitaba a tu lado vigilándote, pareció sobresaltarse."
  },
  AvgDialog_142893_Content_87 = {
    Text = "¿¡Jago?! ¿Qué pasa?"
  },
  AvgDialog_142893_Content_88 = {
    Text = "Miraste con la vista perdida por la ventana. La luna aún colgaba lejana en el cielo."
  },
  AvgDialog_142893_Content_89 = {
    Text = "Más allá de eso, no había nada."
  },
  AvgDialog_142893_Content_9 = {
    Text = "Pontos te abraza con fuerza y corre tierra adentro, alejándose de la costa, protegiéndote con su espalda. Contemplas aterrado las llamas por todas partes y a la gente abriéndose paso entre el caos."
  },
  AvgDialog_145231_Content_1 = {Text = "Bang—"},
  AvgDialog_145231_Content_10 = {
    Text = "Hoy, no podía concentrarme en mi hoja ni en mi enemigo."
  },
  AvgDialog_145231_Content_11 = {
    Text = "Algo más seguía distrayéndome."
  },
  AvgDialog_145231_Content_12 = {
    Text = "¿Algo más? ¿Como qué?"
  },
  AvgDialog_145231_Content_13 = {Text = "Tú."},
  AvgDialog_145231_Content_14 = {
    Text = "¿¿¿??? Quieres decir..."
  },
  AvgDialog_145231_Content_15 = {
    Text = "Sí. Esa loca de Thais, y su río enloquecido."
  },
  AvgDialog_145231_Content_16 = {
    Text = "No pasa nada por perder una pelea de vez en cuando. Justo descansa aquí por ahora, voy a buscarte algo de medicina..."
  },
  AvgDialog_145231_Content_17 = {Text = "..."},
  AvgDialog_145231_Content_18 = {
    Text = "Intentas escabullirte de la habitación, pero Lotan no te da la oportunidad."
  },
  AvgDialog_145231_Content_19 = {
    Text = "Dos chasquidos agudos resuenan junto a tus oídos. Las hojas de hueso de Lotan atraviesan la cama, y sus empuñaduras de hueso clavan tus manos contra el colchón. No puedes moverte."
  },
  AvgDialog_145231_Content_2 = {
    Text = "La puerta se abre de golpe con un estruendo como un tambor de guerra. Oliendo a sangre, alguien irrumpe y cae sobre tu cama, jadeando."
  },
  AvgDialog_145231_Content_20 = {
    Text = "No vine aquí a curarme. Vine a resolver un problema. Y tú... eres el problema."
  },
  AvgDialog_145231_Content_21 = {
    Text = "¡Oye! Lotan... qué... qué estás haciendo..."
  },
  AvgDialog_145231_Content_22 = {
    Text = "Odio no poder concentrarme en la pelea. Me irrita."
  },
  AvgDialog_145231_Content_23 = {
    Text = "¡Y-yo tengo una idea! Podrías ir a buscar a Thais... mmph..."
  },
  AvgDialog_145231_Content_24 = {
    Text = "Una mano manchada de sangre te tapa la boca, ahogando tu voz en gemidos incoherentes."
  },
  AvgDialog_145231_Content_25 = {
    Text = "Mi mente nunca ha albergado nada más que la batalla. Pero tener una excepción... no está tan mal."
  },
  AvgDialog_145231_Content_26 = {
    Text = "Me gusta concentrarme en una sola cosa a la vez. Ya sea una pelea... o cualquier otra cosa."
  },
  AvgDialog_145231_Content_27 = {
    Text = "Lotan te mira fijamente desde arriba como si inmovilizara a una rival que le brinda el placer supremo, y el espíritu combativo en sus ojos se convierte en un hambre descarada."
  },
  AvgDialog_145231_Content_28 = {
    Text = "Derramé toda esta sangre por tu culpa. Tendrás que pagar por eso, ¿verdad?"
  },
  AvgDialog_145231_Content_29 = {
    Text = "Las garras de hierro de sus guanteletes recorren tu mandíbula, deslizándose por tu garganta, tu pecho y tu cintura... Te retuerces con desesperación, dejando escapar sonidos sin sentido, pero las cuchillas te sujetan con firmeza, inmóviles como la piedra."
  },
  AvgDialog_145231_Content_3 = {
    Text = "¡Ah! ¿Quién—"
  },
  AvgDialog_145231_Content_30 = {
    Text = "Lotan se inclina hacia ti, admirando tu rostro enrojecido por la lucha."
  },
  AvgDialog_145231_Content_31 = {
    Text = "Sonríe, dejando que su sangre gotee de sus labios sobre tu cara."
  },
  AvgDialog_145231_Content_32 = {
    Text = "Lucha cuanto quieras. A ver si puedes liberarte... mi \"contrincante\"."
  },
  AvgDialog_145231_Content_4 = {
    Text = "...¿Lotan? ¿Estás herida?!"
  },
  AvgDialog_145231_Content_5 = {
    Text = "La miras con incredulidad, contemplando su maltrecha figura."
  },
  AvgDialog_145231_Content_6 = {
    Text = "Solo rasguños. Nada grave."
  },
  AvgDialog_145231_Content_7 = {
    Text = "¿Qué pasó... Quién pudo haberte herido así?"
  },
  AvgDialog_145231_Content_8 = {
    Text = "Un Gusano del Mar Astral. Debería haber sido una presa fácil. Pero hoy..."
  },
  AvgDialog_145231_Content_9 = {
    Text = "Frunce el ceño, con un destello de irritación en sus ojos."
  },
  AvgDialog_14530_Content_10 = {
    Text = "Los labios se separaron, un leve sabor salado se extendió.\nEsto no es lluvia."
  },
  AvgDialog_14530_Content_11 = {
    Text = "<Gray: ...¿Lágrimas?>"
  },
  AvgDialog_14530_Content_12 = {
    Text = "Como si estuvieran limpiados por la lluvia, la vista se vuelve gradualmente más clara."
  },
  AvgDialog_14530_Content_14 = {
    Text = "Ra... Mona..."
  },
  AvgDialog_14530_Content_15 = {
    Text = "Tu llamada termina de repente."
  },
  AvgDialog_14530_Content_16 = {
    Text = "El estrés abrumador proviene de todas direcciones, y las mareas negras te envuelven."
  },
  AvgDialog_14530_Content_17 = {Text = "..."},
  AvgDialog_14530_Content_18 = {
    Text = "El reloj hace tictac, y el sonido del canto de los pájaros se filtra a través de la ventana entreabierta."
  },
  AvgDialog_14530_Content_19 = {
    Text = "La sofocación persistente te hace palmadear instintivamente el pecho. Al sentarte lentamente, pasa un tiempo antes de que realmente sientas que estás despierto."
  },
  AvgDialog_14530_Content_2 = {
    Text = "Lágrimas de Lluvia"
  },
  AvgDialog_14530_Content_20 = {
    Text = "<Gray:He tenido muchos sueños extraños, pero esta es la primera vez que sueño con mi propia muerte.>"
  },
  AvgDialog_14530_Content_21 = {
    Text = "Se siente extraño."
  },
  AvgDialog_14530_Content_22 = {
    Text = "Bastante interesante."
  },
  AvgDialog_14530_Content_23 = {
    Text = "Ring Ring—"
  },
  AvgDialog_14530_Content_24 = {
    Text = "Apagas el despertador, te levantas y te estiras."
  },
  AvgDialog_14530_Content_25 = {
    Text = "Está bien, lo que sea. Recuerdo que necesito ir hoy—"
  },
  AvgDialog_14530_Content_26 = {
    Text = "Entrenamiento especial mañana a las 8 AM en la Sala de Despertar. No llegues tarde"
  },
  AvgDialog_14530_Content_27 = {
    Text = "¿Sala de Despertar? ¿Es para entrenamiento relacionado con el despertar?"
  },
  AvgDialog_14530_Content_28 = {
    Text = "Probando la estabilidad de <Yellow:Dominio Artificial>."
  },
  AvgDialog_14530_Content_29 = {
    Text = "¿Qué es eso?"
  },
  AvgDialog_14530_Content_3 = {Text = "Cayendo."},
  AvgDialog_14530_Content_30 = {
    Text = "Un pequeño proyecto en el que he estado trabajando, más como un pasatiempo—usar la amplificación del dispositivo de Despertar para mejorar la conciencia y el espíritu durante el sueño"
  },
  AvgDialog_14530_Content_31 = {
    Text = "En teoría, un espíritu lo suficientemente grande puede formar un dominio, y un dominio estabilizado puede existir independientemente de la dimensión de la realidad y de la dimensión del espíritu."
  },
  AvgDialog_14530_Content_32 = {
    Text = "Este reino es bastante similar al <Yellow:Domain>, así que lo llamo un Dominio Artificial."
  },
  AvgDialog_14530_Content_33 = {
    Text = "A diferencia de los dominios que ocurren naturalmente y que irrumpen en la realidad desde la dimensión espiritual, los dominios artificiales son no agresivos, más estables y controlables, y pueden <Yellow:recrear un momento de un tiempo que no existe en el presente>."
  },
  AvgDialog_14530_Content_34 = {
    Text = "\"El presente no existe\"—¿Estás diciendo que puede mostrar los recuerdos de alguien?"
  },
  AvgDialog_14530_Content_35 = {
    Text = "Puede <Yellow:presentar un recuerdo basado en la comprensión del Maestro del Espíritu>, y también permite que otros ingresen a este recuerdo."
  },
  AvgDialog_14530_Content_36 = {
    Text = "¿Como entrar en el Dominio...?"
  },
  AvgDialog_14530_Content_37 = {
    Text = "No está nada mal. Sí, después de que se forme un Dominio artificial, otros individuos pueden ingresar físicamente y interactuar con la conciencia de la entidad espiritual—el dueño del Dominio."
  },
  AvgDialog_14530_Content_38 = {
    Text = "En este momento, ya sea que el espíritu reconozca al visitante y qué actitud mantiene... Ja, solo pensar en ello es interesante."
  },
  AvgDialog_14530_Content_39 = {
    Text = "Si el Dominio Artificial funciona, será la mejor manera para que los Investigadores, Guardianes y sus respectivos Despertadores construyan relaciones y profundicen en la comprensión."
  },
  AvgDialog_14530_Content_4 = {
    Text = "Estás cayendo."
  },
  AvgDialog_14530_Content_40 = {
    Text = "Pensando en los ojos ansiosos de la Muñeca, sentiste un escalofrío recorrer tu cabeza."
  },
  AvgDialog_14530_Content_41 = {
    Text = [[
Lo llaman entrenamiento especial, pero solo somos conejillos de indias...
Espero que nada salga mal hoy.]]
  },
  AvgDialog_14530_Content_42 = {
    Text = "Reúnes tu espíritu y empujas la puerta en el pasaje subterráneo."
  },
  AvgDialog_14530_Content_43 = {
    Text = "Antes de que puedas reaccionar, una luz deslumbrante te traga por completo."
  },
  AvgDialog_14530_Content_5 = {
    Text = "La sensación de caer te atrae, sacando lentamente tu conciencia del sueño negro como la tinta."
  },
  AvgDialog_14530_Content_6 = {
    Text = "Una luz borrosa aparece ante tus ojos. Después de un momento de confusión, te das cuenta de que parece que has abierto los ojos."
  },
  AvgDialog_14530_Content_7 = {
    Text = "<Gray:¿Cómo... no puedo ver claramente...>"
  },
  AvgDialog_14530_Content_8 = {
    Text = "Una gota, dos gotas... Un líquido fresco cae sobre tu frente, rodando por tu mejilla."
  },
  AvgDialog_14530_Content_9 = {
    Text = "¿Lluvia...?"
  },
  AvgDialog_145510_Content_10 = {
    Text = "Al pie de las montañas nevadas, un mercado caótico brota del suelo helado. Cobertizos de madera, tiendas de campaña y puestos Temporales de piel de yak se apiñan a ambos lados de un lodoso sendero de montaña."
  },
  AvgDialog_145510_Content_11 = {
    Text = "El Continente del Norte Final es demasiado frío, echo un poco de menos el té caliente de la señorita Sylvia…"
  },
  AvgDialog_145510_Content_12 = {
    Text = "Aunque es pronto para decirlo, cuando regresemos a Misaq, le pediré a la señorita Sylvia que te suministre té caliente en Ciclo continuo las 24 horas."
  },
  AvgDialog_145510_Content_13 = {
    Text = "Por ahora, concentrémonos en la misión que tenemos entre manos."
  },
  AvgDialog_145510_Content_14 = {
    Text = "Sacas el folleto promocional que lleva arrugado entre el equipaje y lo giras hacia el Sol para compararlo."
  },
  AvgDialog_145510_Content_15 = {
    Text = "La línea de unión de la montaña parte desde el borde del folleto y encaja perfectamente con el perfil de las cumbres bajo el cielo sombrío."
  },
  AvgDialog_145510_Content_16 = {
    Text = "Es aquí, Justo que no sé cómo encontrar a ese misterioso líder cuyos títulos se apilan más alto que el Everest…"
  },
  AvgDialog_145510_Content_17 = {
    Text = "<Shake:¡Atención, todooos!>"
  },
  AvgDialog_145510_Content_18 = {
    Text = "Siguiendo la voz que Llamar, una chica vestida de blanco estaba sola frente a una tienda en lo alto de una colina, contemplando a la escasa multitud."
  },
  AvgDialog_145510_Content_19 = {
    Text = "Soy el Executor del dios supremo, la gran Hada del culto Caraboo, encarnación de la diosa de las nieves Umapati caída en el mundo de los mortales."
  },
  AvgDialog_145510_Content_2 = {
    Text = "Los Atrapados en la Nieve"
  },
  AvgDialog_145510_Content_20 = {
    Text = "(Esto es un poco diferente a lo que decía el folleto…)"
  },
  AvgDialog_145510_Content_21 = {
    Text = "¡Vaya, si eres la diosa de las nieves, muéstranos algún hechizo!"
  },
  AvgDialog_145510_Content_22 = {
    Text = "La Pulla del hombre provocó algunas risas dispersas."
  },
  AvgDialog_145510_Content_23 = {
    Text = "No, ahora mismo no puedo hacerlo."
  },
  AvgDialog_145510_Content_24 = {
    Text = "La chica sacó despreocupadamente una manzana roja brillante y le dio un mordisco."
  },
  AvgDialog_145510_Content_25 = {
    Text = "Porque perdí siete artefactos mágicos, siete tesoros que amo profundamente."
  },
  AvgDialog_145510_Content_26 = {
    Text = "Son la Manzana Dorada de Eris, el Espejo de Yata, la Pluma de Ma'at, la Llave de Salomón, el Ojo de Balor..."
  },
  AvgDialog_145510_Content_27 = {
    Text = "¡Vaya, tus artefactos mágicos provienen de civilizaciones bastante variadas y dispares!"
  },
  AvgDialog_145510_Content_28 = {
    Text = "Otra carcajada general, pero la chica no le prestó la menor atención."
  },
  AvgDialog_145510_Content_29 = {
    Text = "Y también el Hilo de Moira y la Corona de Ariadna."
  },
  AvgDialog_145510_Content_3 = {
    Text = "La mayor mentira de este mundo,\nsale de la boca de quien jamás miente."
  },
  AvgDialog_145510_Content_30 = {
    Text = "El Hilo de Moira… el telar de las Tres Parcas…"
  },
  AvgDialog_145510_Content_31 = {
    Text = "¿Acaso es esto lo que Aracne llamaba \"el destino que debemos recibir\"?"
  },
  AvgDialog_145510_Content_32 = {
    Text = "Sacas aquel pequeño rollo de Hilo del bolsillo interior de tu ropa; el brillante Hilo centellea entre tus dedos con colores cambiantes difíciles de captar a simple vista."
  },
  AvgDialog_145510_Content_33 = {
    Text = "Espera un poco más y actúa con cautela."
  },
  AvgDialog_145510_Content_34 = {
    Text = "Aunque el destino nos ha guiado hasta aquí, no nos ha revelado qué papel desempeña el dueño del manual en esta historia."
  },
  AvgDialog_145510_Content_35 = {
    Text = "*Tos, tos!*"
  },
  AvgDialog_145510_Content_36 = {
    Text = "¡Si lo han entendido todo, dejen aquí su Mantenimiento!"
  },
  AvgDialog_145510_Content_37 = {
    Text = "¡Ni más ni menos, Siempre Que sean cincuenta Rosa Dorada! ¡Así podrán hacer sentir su sinceridad a la diosa de la montaña nevada, Umapati!"
  },
  AvgDialog_145510_Content_38 = {
    Text = "¡Como diosa de la montaña nevada, una vez que reúna los siete grandes artefactos y renazca bajo la luna nueva, responderé a sus plegarias cien, mil veces!"
  },
  AvgDialog_145510_Content_39 = {
    Text = "¡Después de tanto palabrerío, resulta que venías a pedir donaciones!"
  },
  AvgDialog_145510_Content_4 = {
    Text = "–Altitud 4000 m–"
  },
  AvgDialog_145510_Content_40 = {
    Text = "Desde que la diosa de la montaña nevada se manifestó, han llegado grupos de escaladores a miles, si no a cientos, y ninguno vino con las manos vacías."
  },
  AvgDialog_145510_Content_41 = {
    Text = "¡Tú, que Solo piensas en obtener cosas sin esfuerzo, será mejor que te largues cuanto antes y aprendas a cumplir tus deseos con tus propias manos trabajadoras!"
  },
  AvgDialog_145510_Content_42 = {
    Text = "Los curiosos se dispersaron en desbandada."
  },
  AvgDialog_145510_Content_43 = {
    Text = "Aprovechando el momento, te abres paso a contracorriente entre la multitud y te acercas a la solitaria joven para preguntarle."
  },
  AvgDialog_145510_Content_44 = {
    Text = "Disculpe… Me gustaría preguntarle, ¿fue usted quien envió este folleto?"
  },
  AvgDialog_145510_Content_45 = {
    Text = "Sacas ese folleto llamativo y lleno de colores, y golpeteas las palabras \"el gran líder, El Elegido de la Deidad, Amigo cercano del Rey Divino\"."
  },
  AvgDialog_145510_Content_46 = {
    Text = "Los ojos de la joven se iluminaron al instante."
  },
  AvgDialog_145510_Content_47 = {
    Text = "<Shake:¡Ohhh! ¡De verdad conseguiste mi folleto de reclutamiento!>"
  },
  AvgDialog_145510_Content_48 = {
    Text = "Entonces, ¿dónde están tus doce apóstoles y los demás fieles?"
  },
  AvgDialog_145510_Content_49 = {
    Text = "Esa historia es larga de contar. Mi grandiosa secta fue víctima de una traición, pues uno de los doce apóstoles albergaba malas intenciones, anhelando para sí solo la gloria suprema."
  },
  AvgDialog_145510_Content_5 = {
    Text = "Hemos llegado"
  },
  AvgDialog_145510_Content_50 = {
    Text = "Los demás fieles fueron manipulados y enfrentados entre sí hasta que todo se desmoronó. Solo yo, la Líder, quedé sola, emprendiendo un largo y arduo camino para revivir la secta."
  },
  AvgDialog_145510_Content_51 = {
    Text = "Si cada uno de ustedes patrocina ahora con mil Rosa Dorada, podrá ocupar el primer puesto de los nuevos Doce Apóstoles y convertirse en mi discípulo número uno…"
  },
  AvgDialog_145510_Content_52 = {
    Text = "Pero hace un momento, cuando actuabas en la calle, dijiste que eras Umapati, la diosa de la montaña nevada."
  },
  AvgDialog_145510_Content_53 = {
    Text = "¿Es eso lo que se llama que, cuando sales al mundo, la Identidad te la das tú misma?"
  },
  AvgDialog_145510_Content_54 = {
    Text = "Vaya, me descubriste."
  },
  AvgDialog_145510_Content_55 = {
    Text = "La joven dio un salto ágil y en un abrir y cerrar de ojos desapareció detrás de una tienda."
  },
  AvgDialog_145510_Content_56 = {
    Text = "Justo cuando ibas a perseguir a la joven, alguien te dio una palmada en la espalda."
  },
  AvgDialog_145510_Content_57 = {
    Text = "Estimados visitantes, ¿han venido a escalar la montaña?"
  },
  AvgDialog_145510_Content_58 = {
    Text = "¿Eh, nosotros?"
  },
  AvgDialog_145510_Content_59 = {
    Text = "Así es, con solo mirarlos se nota que tienen un porte distinguido. No son personas locales, ¿verdad?"
  },
  AvgDialog_145510_Content_6 = {
    Text = "Este es el último punto de abastecimiento en el camino al Everest."
  },
  AvgDialog_145510_Content_60 = {
    Text = "Últimamente, todos los que llegan a estas tierras baldías vienen buscando a la diosa en la cima de la montaña, esa que dicen que puede conceder cualquier deseo."
  },
  AvgDialog_145510_Content_61 = {
    Text = "Ustedes dos no traen mucho equipo; parece que piensan aprovechar los recursos de otros. Qué casualidad, ¿no?"
  },
  AvgDialog_145510_Content_62 = {
    Text = "<Yellow:Me llamo Naraka. Soy guía Sherpa local.>"
  },
  AvgDialog_145510_Content_63 = {
    Text = "El equipo de escalada al que pertenecemos está financiado por la Fundación Green; los suministros ya están listos, solo esperamos a \"los elegidos por el destino\" para llegar juntos a la cima."
  },
  AvgDialog_145510_Content_64 = {
    Text = "¿Una persona predestinada?"
  },
  AvgDialog_145510_Content_65 = {
    Text = "Sí, llevo muchos años viviendo al pie de la montaña nevada. Quién tiene la capacidad de llegar a la cima—"
  },
  AvgDialog_145510_Content_66 = {
    Text = "Señaló sus propios ojos."
  },
  AvgDialog_145510_Content_67 = {
    Text = "Estos ojos lo ven de un vistazo."
  },
  AvgDialog_145510_Content_68 = {
    Text = "¿Oh? ¿Por qué no nos lo cuentas?"
  },
  AvgDialog_145510_Content_69 = {
    Text = "Primero, por supuesto, una edad adecuada, un cuerpo robusto y una Fuerza espiritual estable."
  },
  AvgDialog_145510_Content_7 = {
    Text = "Más arriba, los vehículos ya no pueden continuar."
  },
  AvgDialog_145510_Content_70 = {
    Text = "Además de eso, más importante aún es la tenacidad y la determinación para llegar a la cima — la determinación de no exhalar el último aliento Siempre Que no se haya alcanzado la cumbre."
  },
  AvgDialog_145510_Content_71 = {
    Text = "Exhalar el último aliento en la cima — parece que no tienes intención de dejarnos bajar con vida, ¿verdad?"
  },
  AvgDialog_145510_Content_72 = {
    Text = "Vamos, no se puede decir eso. Al llegar a la cima y ver a la diosa de la montaña nevada, cualquier deseo puede hacerse realidad. En ese momento, bajar de la montaña es algo tan insignificante que ni vale la pena preocuparse, ¿no?"
  },
  AvgDialog_145510_Content_73 = {
    Text = "Vamos, venid conmigo al campamento de montañismo. Os garantizo que quedaréis satisfechos."
  },
  AvgDialog_145510_Content_74 = {
    Text = "Lanzas una mirada a William, pidiéndole su opinión en silencio."
  },
  AvgDialog_145510_Content_75 = {
    Text = "Vamos. No sé adónde fue esa chica de antes."
  },
  AvgDialog_145510_Content_76 = {
    Text = "Si realmente vamos a escalar la montaña, un guía local y provisiones completas son indispensables."
  },
  AvgDialog_145510_Content_77 = {
    Text = "Vamos, a ver el campamento."
  },
  AvgDialog_145510_Content_79 = {
    Text = "Qué voz tan hermosa…"
  },
  AvgDialog_145510_Content_8 = {
    Text = "Abres la puerta del vehículo y el aire, impregnado del aroma tostado del té de mantequilla, el olor a ganado y el frío tenue y cortante propio de la meseta, se precipita ansioso por tus fosas nasales."
  },
  AvgDialog_145510_Content_80 = {
    Text = "Me resulta familiar."
  },
  AvgDialog_145510_Content_81 = {
    Text = "Como si fluyera desde una galaxia lejana y remota, o como si emergiera suavemente desde las profundidades del Aequor sin fin."
  },
  AvgDialog_145510_Content_83 = {
    Text = "El canto llegaba desde la dirección del campamento, hebra a hebra, volviéndose cada vez más nítido, como la niebla que se disipa y revela el resplandor puro de la luna llena."
  },
  AvgDialog_145510_Content_85 = {
    Text = "En un claro junto al campamento, una joven de semblante apesadumbrado cantaba a plena voz."
  },
  AvgDialog_145510_Content_86 = {
    Text = "Todos los que pasaban por allí ralentizaban involuntariamente el paso y contenían la respiración, temerosos de perturbar esa voz que fluía como la luz de la luna."
  },
  AvgDialog_145510_Content_88 = {
    Text = "Solo cuando la melodía llegó a su fin, Ella salió del mundo en el que estaba sumida y descubrió vuestra presencia."
  },
  AvgDialog_145510_Content_89 = {
    Text = "¿Hay nuevos miembros en el equipo?"
  },
  AvgDialog_145510_Content_9 = {
    Text = "Un cielo plomizo se cierne sobre el confín del mundo. Las cumbres nevadas se alzan como una hilera de dioses silenciosos, erguidas en la frontera entre el crepúsculo y las nubes."
  },
  AvgDialog_145511_Content_1 = {
    Text = "Algo no está del todo bien."
  },
  AvgDialog_145511_Content_10 = {
    Text = "No, no era solo la capa; desde su espalda, también se alzaba otra cosa."
  },
  AvgDialog_145511_Content_11 = {
    Text = "Era un par de alas."
  },
  AvgDialog_145511_Content_12 = {
    Text = "Un par de alas negras—un negro intenso, profundo, que transmitía un funesto presentimiento a todo aquel que lo mirara."
  },
  AvgDialog_145511_Content_13 = {
    Text = "<BigShake:¡Con este cuerpo imperecedero, resistiré toda Catástrofe!>"
  },
  AvgDialog_145511_Content_14 = {
    Text = "Castor desplegó sus Alas Desplegadas y la nieve acumulada a sus espaldas estalló trazando un arco blanco y brillante, Casi perpendicular."
  },
  AvgDialog_145511_Content_15 = {
    Text = "Se impulsa desde la ladera nevada, cubriendo una distancia que de otro modo nunca habría podido cruzar—"
  },
  AvgDialog_145511_Content_16 = {
    Text = "Y entonces se interpuso entre el wendigo y Evelyn."
  },
  AvgDialog_145511_Content_17 = {
    Text = "Sus alas se despliegan ampliamente, formando una enorme barrera de un negro absoluto a sus espaldas."
  },
  AvgDialog_145511_Content_18 = {
    Text = "Las fauces del wendigo, que estaban a punto de cerrarse, mordieron su ala derecha, arrancando de raíz un buen número de Plumas."
  },
  AvgDialog_145511_Content_19 = {
    Text = "<Shake:¡Ugh!!>"
  },
  AvgDialog_145511_Content_2 = {
    Text = "En el rabillo del ojo, en un rincón de la manada, el wendigo más alto y delgado no había atacado desde el comienzo del combate."
  },
  AvgDialog_145511_Content_20 = {
    Text = "Castor suelta un gruñido ahogado, pero no retrocede."
  },
  AvgDialog_145511_Content_21 = {
    Text = "¡No desperdicies la oportunidad que Castor ha creado, ahora mismo!"
  },
  AvgDialog_145511_Content_3 = {
    Text = "Esperaba, observando el eslabón más débil del equipo de alpinismo."
  },
  AvgDialog_145511_Content_4 = {
    Text = "Rodeó a los tres y se abalanzó ferozmente sobre Evelyn."
  },
  AvgDialog_145511_Content_5 = {
    Text = "¡Evelyn—!"
  },
  AvgDialog_145511_Content_6 = {
    Text = "Caraboo estaba demasiado lejos; en el momento en que gritó, ya sabía que no llegaría a tiempo."
  },
  AvgDialog_145511_Content_7 = {
    Text = "—Pero alguien sí llegó a tiempo."
  },
  AvgDialog_145511_Content_8 = {
    Text = "Castor corrió a toda velocidad y extendió la mano para desatar los cordones de su capa."
  },
  AvgDialog_145511_Content_9 = {
    Text = "La capa ondeó agitándose a sus espaldas—"
  },
  AvgDialog_145512_Content_1 = {
    Text = "Se acabó, perdedor."
  },
  AvgDialog_145512_Content_10 = {
    Text = "¿No fue así como te lo dijo tu amo: mi querida y adorada, has trabajado mucho, esto es tu recompensa por todo lo que has dado hasta ahora?"
  },
  AvgDialog_145512_Content_11 = {
    Text = "¿Que Justo necesitabas escalar tú mismo el pico nevado, repeler a los oponentes y recuperar tu corona?"
  },
  AvgDialog_145512_Content_12 = {
    Text = "Lo siento mucho, <BigShake:TE — HAN — EN — GA — ÑA — DO —>"
  },
  AvgDialog_145512_Content_13 = {
    Text = "Un peón siempre será Solo un peón, y cuando sea necesario, también se convertirá en pieza sacrificada."
  },
  AvgDialog_145512_Content_14 = {
    Text = "Cuando el valor que puedes aportar haya sido exprimido hasta el límite, cuando empieces a sentir descontento… llegará el momento de que ofrezcas tu cabeza."
  },
  AvgDialog_145512_Content_15 = {
    Text = "Como una de las siete Ofrendas en el altar, ¿tienes alguna última palabra que quieras pronunciar?"
  },
  AvgDialog_145512_Content_16 = {
    Text = "No debería… no debería haber confiado en nadie…"
  },
  AvgDialog_145512_Content_17 = {
    Text = "Desde el principio, confiar en la gracia de esa señora… Después… anhelar la venganza de los de mi especie…"
  },
  AvgDialog_145512_Content_18 = {
    Text = "Y ahora, impulsada por la promesa de alguien…"
  },
  AvgDialog_145512_Content_19 = {
    Text = "Bueno, bueno, el tiempo que te doy para pronunciar tus últimas palabras es Justo una cortesía; a nadie le importa de verdad tu miserable y fracasada vida."
  },
  AvgDialog_145512_Content_2 = {
    Text = "Caraboo pasó por encima de Helot, que yacía de rodillas en el suelo, y recogió delicadamente el globo ocular del círculo mágico."
  },
  AvgDialog_145512_Content_20 = {
    Text = "Lo que no puedes ganar por ti mismo, ve a robarlo, engañar o arrebatarlo. ¿De qué sirve Solo esperar a que otros te lo den?"
  },
  AvgDialog_145512_Content_21 = {
    Text = "Ya no queda tiempo para eso; el resto de la reflexión, déjalo para la próxima vida."
  },
  AvgDialog_145512_Content_22 = {
    Text = "Caraboo levantó la mano y lanzó suavemente el globo ocular, que se hundió en el cuerpo de Helot."
  },
  AvgDialog_145512_Content_23 = {
    Text = "Acto seguido, resonó un crujido, el sonido de la Ingestión."
  },
  AvgDialog_145512_Content_24 = {
    Text = "Come, come."
  },
  AvgDialog_145512_Content_25 = {
    Text = "El cuerpo de Helot se desmoronó rápidamente, dejando un lodazal color Sangre."
  },
  AvgDialog_145512_Content_26 = {
    Text = "Así es, exactamente así, te devorarán hasta no dejar ni los huesos…"
  },
  AvgDialog_145512_Content_27 = {
    Text = "En El Rostro de Caraboo, vislumbraste cierta cruel satisfacción."
  },
  AvgDialog_145512_Content_28 = {
    Text = "Mira, tus miserables consecuencias tienen su Fuente en tu estupidez, en tu credulidad ante Una Mentira."
  },
  AvgDialog_145512_Content_29 = {Text = "Caraboo…"},
  AvgDialog_145512_Content_3 = {
    Text = "Tu deseo también se convertirá en abono que nutra la montaña nevada."
  },
  AvgDialog_145512_Content_30 = {
    Text = "¿Hmm? ¿Qué ocurre?"
  },
  AvgDialog_145512_Content_31 = {
    Text = "Ella se volvió y observó detenidamente tu expresión."
  },
  AvgDialog_145512_Content_32 = {
    Text = "Ella adoptó su habitual actitud coqueta y mimosa, pero Tú aún pudiste leer en el destello de arrogancia en el rabillo de su Ojo el odio Oculto que albergaba."
  },
  AvgDialog_145512_Content_33 = {
    Text = "¿Puedo ver esos seis artefactos?"
  },
  AvgDialog_145512_Content_34 = {
    Text = "¡Por supuesto!"
  },
  AvgDialog_145512_Content_35 = {
    Text = "Caraboo se hizo a un lado y te cedió el lugar frente a la formación mágica."
  },
  AvgDialog_145512_Content_36 = {
    Text = "El Hilo de Moira, un regalo de Arachne."
  },
  AvgDialog_145512_Content_37 = {
    Text = "El Espejo de Yata, recogido a orillas del lago helado donde Tinct deambulaba."
  },
  AvgDialog_145512_Content_38 = {
    Text = "La Pluma de Ma'at, que cayó entre la Nieve y el Viento tras la partida de Castor."
  },
  AvgDialog_145512_Content_39 = {
    Text = "El Ojo de Balor, cristalizado en el charco de Sangre de Helot."
  },
  AvgDialog_145512_Content_4 = {
    Text = "De repente, aquel globo ocular adoptó una expresión feroz; su pupila rojo carmesí se abrió de par en par, irradiando un resplandor de Sangre."
  },
  AvgDialog_145512_Content_40 = {
    Text = "la Manzana Dorada, Caraboo la sacó de quién sabe qué bolsa."
  },
  AvgDialog_145512_Content_41 = {
    Text = "La Llave de Salomón es, en realidad, la Llave de Plata que llevas contigo."
  },
  AvgDialog_145512_Content_42 = {
    Text = "Y además, lo que encontró la expedición anterior, la Corona de Ariadna…"
  },
  AvgDialog_145512_Content_43 = {
    Text = "Te quedas atónito."
  },
  AvgDialog_145512_Content_44 = {
    Text = "La Corona de Ariadna… ¿qué Corona de Ariadna es esta? ¡Si esto es la <Yellow:Corona de Tulu>!"
  },
  AvgDialog_145512_Content_45 = {
    Text = "¿Qué tiene de sorprendente? ¿Acaso la Manzana Dorada es dorada?"
  },
  AvgDialog_145512_Content_46 = {
    Text = "Pero, ¿por qué estaría aquí la corona de Tulu?"
  },
  AvgDialog_145512_Content_47 = {
    Text = "Porque es Su artefacto ritual, Su ofrenda, Su ingrediente favorito."
  },
  AvgDialog_145512_Content_48 = {
    Text = "Con las últimas palabras de Caraboo, la Tierra tembló de repente."
  },
  AvgDialog_145512_Content_49 = {
    Text = "¿Qué está pasando?"
  },
  AvgDialog_145512_Content_5 = {
    Text = "No, ¿cómo es posible…?"
  },
  AvgDialog_145512_Content_50 = {
    Text = "¡Está riendo!"
  },
  AvgDialog_145512_Content_51 = {
    Text = "…¿Riendo?"
  },
  AvgDialog_145512_Content_52 = {
    Text = "La cima de la montaña temblaba una y otra vez, Como Si fuera una joven doncella que, al presenciar algo gracioso, se riera tanto que todo su cuerpo se sacudiera."
  },
  AvgDialog_145512_Content_53 = {
    Text = "La Nieve acumulada se desprendió."
  },
  AvgDialog_145512_Content_54 = {
    Text = "Aquel pico no era una montaña, sino un enorme gusano enroscado sobre la cima, semejante a una serpiente gigantesca capaz de devorar el cielo y la tierra."
  },
  AvgDialog_145512_Content_55 = {
    Text = "Por la debilidad de los humanos, incapaces de enfrentarse a la realidad, eligieron creer en Una Mentira y encomendaron sus deseos a Deidades del Oblivion."
  },
  AvgDialog_145512_Content_56 = {
    Text = "Nunca pensaron que las llamadas Deidades también podían mentir. Porque las Deidades también tienen deseos que quieren cumplir."
  },
  AvgDialog_145512_Content_57 = {
    Text = "El deseo de la Deidad era — devorarlos."
  },
  AvgDialog_145512_Content_58 = {
    Text = "La Corona, el Hilo, la Llave de Plata, el fruto prohibido, la pluma alada, el espejo luminoso, el ojo mágico. Siete artefactos rituales, Ofrendas forjadas con la PV de esos humanos Avaros."
  },
  AvgDialog_145512_Content_59 = {
    Text = "Todo lo que sois no es más que un festín para Ella."
  },
  AvgDialog_145512_Content_6 = {
    Text = "El Ojo de Balor, el ojo demoníaco del dios maligno. Capaz de aniquilar todo lo que contempla, y sin embargo su único punto débil."
  },
  AvgDialog_145512_Content_60 = {
    Text = "¡Ahora que Él ha obtenido lo que quería, por supuesto que debería reír!"
  },
  AvgDialog_145512_Content_61 = {
    Text = "Llegados a este punto, ¿no es hora de decirnos la verdad?"
  },
  AvgDialog_145512_Content_62 = {
    Text = "Tú no te uniste a este viaje por casualidad, como pretendías aparentar."
  },
  AvgDialog_145512_Content_63 = {
    Text = "Más bien, todo el equipo de escalada llegó hasta aquí guiado por ti."
  },
  AvgDialog_145512_Content_64 = {
    Text = "El encuentro fortuito en la cueva al principio, la elección de Tinct de ir a contemplar el lago de hielo…"
  },
  AvgDialog_145512_Content_65 = {
    Text = "Y este Helot que nos ha seguido todo el tiempo… en realidad lo habías previsto todo desde el principio."
  },
  AvgDialog_145512_Content_66 = {
    Text = "¿Quién eres realmente?"
  },
  AvgDialog_145512_Content_7 = {
    Text = "¿Tu amo no te lo dijo? Este globo ocular solo merece ser llamado \"Ojo de Balor\" si está impregnado de tu Festín de Sangre."
  },
  AvgDialog_145512_Content_8 = {
    Text = "Él dijo…"
  },
  AvgDialog_145512_Content_9 = {
    Text = "Chist, déjame adivinar."
  },
  AvgDialog_145513_Content_1 = {
    Text = "Pacto de Mentirosos"
  },
  AvgDialog_145513_Content_10 = {
    Text = "<Yellow:Fuiste tú quien quemó mi paquete>, ¿verdad? Voy a arrancarte esa máscara de piel humana que llevas puesta—"
  },
  AvgDialog_145513_Content_11 = {
    Text = "Ella agarró con fuerza las mejillas de Naraka y tiró hacia ambos lados."
  },
  AvgDialog_145513_Content_12 = {
    Text = "<Shake:¡ESPERA!>"
  },
  AvgDialog_145513_Content_13 = {
    Text = "¡Desgarrón!"
  },
  AvgDialog_145513_Content_14 = {
    Text = "La envoltura conocida como \"Naraka\" queda partida en dos de un tajo limpio, como una muñeca de goma en manos de un niño travieso."
  },
  AvgDialog_145513_Content_15 = {
    Text = "De la grieta brotaba a borbotones un humo negro llamado \"Caos\"."
  },
  AvgDialog_145513_Content_16 = {
    Text = "El humo se agitó, se enroscó, se condensó, y luego extendió con descaro una rosa."
  },
  AvgDialog_145513_Content_17 = {
    Text = "Nos volvemos a ver, viejo amigo."
  },
  AvgDialog_145513_Content_18 = {
    Text = "Antes de ponernos al día, ¿qué tal un pequeño calentamiento para apaciguar a nuestra furiosa pequeña embustera?"
  },
  AvgDialog_145513_Content_2 = {
    Text = "Al final del Hilo, la joven emergió de entre las sombras."
  },
  AvgDialog_145513_Content_3 = {
    Text = "Vaya, pequeña embustera, ¿te has metido tú misma en esto también?"
  },
  AvgDialog_145513_Content_4 = {
    Text = "Las palabras de Naraka solo agudizan el temperamento de una chica que ya tenía la cabeza gacha de frustración."
  },
  AvgDialog_145513_Content_5 = {
    Text = "Tú sí que estás tranquilo."
  },
  AvgDialog_145513_Content_6 = {
    Text = "Caraboo levantó la cabeza, con los ojos ardiendo de furia, clavados en Naraka."
  },
  AvgDialog_145513_Content_7 = {
    Text = "Deja de fingir. Un guía Sherpa tragado por las entrañas de la montaña, ¿y aún tiene ganas de bromear?"
  },
  AvgDialog_145513_Content_8 = {
    Text = "Desde el momento en que te vi, supe que tú también eres un farsante."
  },
  AvgDialog_145513_Content_9 = {
    Text = "Caraboo se lanzó sobre ella. Esta vez, no le permitió a Naraka esquivarla."
  },
  AvgDialog_145514_Content_1 = {
    Text = "El último wendigo se desvaneció bajo la sombra de Castor."
  },
  AvgDialog_145514_Content_10 = {
    Text = "Quizás las relaciones entre personas Comienzan precisamente cuando se revela algún pequeño secreto, ¿verdad?"
  },
  AvgDialog_145514_Content_11 = {
    Text = "Sin saber cuándo, Caraboo se había acercado y, con una sonrisa, pronunció frente a ti exactamente lo que tenías en mente."
  },
  AvgDialog_145514_Content_12 = {
    Text = "Intercambiar secretos no es algo unilateral."
  },
  AvgDialog_145514_Content_13 = {
    Text = "Esa Tía Rosa a la que has Llamado tantas veces, ¿es alguien muy importante para ti?"
  },
  AvgDialog_145514_Content_14 = {
    Text = "Claro que me lo inventé. ¿No te lo habrás creído de verdad?"
  },
  AvgDialog_145514_Content_15 = {
    Text = "Jeje, engañar a un tonto no tiene mérito, pero engañarte a ti no es nada fácil."
  },
  AvgDialog_145514_Content_16 = {
    Text = "Hacer que los wendigos creyeran que estabas hechizado es mucho más difícil que engañarme a mí."
  },
  AvgDialog_145514_Content_17 = {
    Text = "Ellos pueden escuchar la voz de tu corazón y luego repetirla a través del Viento."
  },
  AvgDialog_145514_Content_18 = {
    Text = "¿Y quién podría saberlo? Quizás la diosa de la montaña nevada tiene tantas historias en su corazón que cada una parece real."
  },
  AvgDialog_145514_Content_19 = {
    Text = "Caraboo lo esquivó con ligereza usando una broma ingeniosa."
  },
  AvgDialog_145514_Content_2 = {
    Text = "Luego, el viento que rozaba sus oídos se volvió repentinamente claro. Ya no traía consigo ningún sonido."
  },
  AvgDialog_145514_Content_20 = {
    Text = "Si no quieres hablar de ello, desde luego no te vamos a presionar."
  },
  AvgDialog_145514_Content_21 = {
    Text = "Pero la sinceridad es algo muy valioso. Aunque seas un embustero, es mejor no defraudar las esperanzas de todos."
  },
  AvgDialog_145514_Content_22 = {
    Text = "Este es mi consejo sincero, depende de ti si lo escuchas o no."
  },
  AvgDialog_145514_Content_23 = {
    Text = "William terminó de hablar y se adelantó al frente del grupo."
  },
  AvgDialog_145514_Content_24 = {Text = "Hmph."},
  AvgDialog_145514_Content_25 = {
    Text = "Benefactor, usted no sería tan insensible como él, ¿verdad?"
  },
  AvgDialog_145514_Content_26 = {
    Text = "He pasado mucho tiempo trabajando con William. No es un hombre que diga nada innecesario."
  },
  AvgDialog_145514_Content_27 = {
    Text = "En mi recuerdo, cada consejo que ha dado ha resultado efectivo."
  },
  AvgDialog_145514_Content_28 = {
    Text = "<Shake:Buaaa, benefactor, resulta que usted también es igual de cruel...>"
  },
  AvgDialog_145514_Content_29 = {
    Text = "Caraboo se alejó fingiendo estar triste, mientras tú alcanzaste a William, que estaba conversando con Naraka."
  },
  AvgDialog_145514_Content_3 = {
    Text = "El silencio significaba seguridad, pero esa seguridad dejaba un vacío melancólico en el corazón."
  },
  AvgDialog_145514_Content_30 = {
    Text = "Con la mirada te indicó que te apartaras unos pasos, hasta que los de al lado no pudieran escuchar vuestros susurros."
  },
  AvgDialog_145514_Content_31 = {
    Text = "En el combate de hace un momento contra el Wendigo, ¿notaste algo extraño?"
  },
  AvgDialog_145514_Content_32 = {Text = "¿Dónde?"},
  AvgDialog_145514_Content_33 = {Text = "Naraka."},
  AvgDialog_145514_Content_34 = {
    Text = "Piénsalo bien: desde que resonaron aquellas voces en el Viento, hasta que apareció el Wendigo, hasta el cerco de hace un momento—"
  },
  AvgDialog_145514_Content_35 = {
    Text = "Naraka, ¿hubo algún instante, en cualquier momento, en que algún Wendigo se acercara a ti?"
  },
  AvgDialog_145514_Content_36 = {
    Text = "Caraboo fue atacada por un Wendigo mientras fingía ser la víctima, Evelyn fue derribada por el Wendigo más alto, a Castor le arrancaron de un mordisco una Pluma…"
  },
  AvgDialog_145514_Content_37 = {
    Text = "Incluyendo la vez anterior en que los Wendigos intentaron hechizarlos, Naraka tampoco pareció verse afectada en absoluto."
  },
  AvgDialog_145514_Content_38 = {
    Text = "Entonces quieres decir..."
  },
  AvgDialog_145514_Content_39 = {
    Text = "No insinúo nada."
  },
  AvgDialog_145514_Content_4 = {
    Text = "Evelyn echó un vistazo a las alas de Castor, pero su expresión no cambió, Como Si fuera lo más natural del mundo que cada persona ocultara un par de alas."
  },
  AvgDialog_145514_Content_40 = {
    Text = "Quedan cuatro o cinco días de ascenso, y no tenemos ningún otro guía al que recurrir."
  },
  AvgDialog_145514_Content_41 = {
    Text = "Espero estar preocupándome de más, pero no podemos dejar de estar alerta."
  },
  AvgDialog_145514_Content_42 = {
    Text = "En este Camino, ya hemos perdido a un Tinct. No quiero que, por mi descuido, nadie más se quede en esta montaña."
  },
  AvgDialog_145514_Content_43 = {
    Text = "El Viento rodeaba el borde exterior de la cresta rocosa."
  },
  AvgDialog_145514_Content_44 = {
    Text = "Rodea la silueta que está a lo lejos, agachada golpeando el hielo."
  },
  AvgDialog_145514_Content_45 = {
    Text = "La punta del pico de Naraka golpea los trozos de hielo de la suela del zapato, emitiendo un sonido estable y rítmico como el de un péndulo."
  },
  AvgDialog_145514_Content_46 = {
    Text = "-Altitud 6.500 m-"
  },
  AvgDialog_145514_Content_5 = {
    Text = "Déjame vendarte las heridas."
  },
  AvgDialog_145514_Content_6 = {
    Text = "Lo siento… por haber ocultado esto todo este tiempo."
  },
  AvgDialog_145514_Content_7 = {
    Text = "No importa. Todos hemos venido a buscar un Milagro sobrenatural capaz de resucitar a los muertos… En un momento como este, descubrir una existencia que desafía el sentido común es una buena noticia."
  },
  AvgDialog_145514_Content_8 = {
    Text = "Además, llevas esa capa puesta incluso para dormir y no te la quitas nunca. Cualquiera sabría que guardas un secreto."
  },
  AvgDialog_145514_Content_9 = {
    Text = "Aunque las palabras sonaban a reproche, notabas claramente que, tras esta batalla, todos Comenzaban a bajar la guardia y a sentirse más cercanos."
  },
  AvgDialog_145515_Content_1 = {
    Text = "Siete Hilos del Destino"
  },
  AvgDialog_145515_Content_10 = {
    Text = "<Shake:¡Mirad allí — !>"
  },
  AvgDialog_145515_Content_11 = {
    Text = "Antes de que sus palabras terminaran, ella ya corría hacia la ladera suave del otro lado."
  },
  AvgDialog_145515_Content_12 = {
    Text = "Era un altar hexagonal."
  },
  AvgDialog_145515_Content_13 = {
    Text = "En el centro del altar, ya había sido colocada una Corona."
  },
  AvgDialog_145515_Content_14 = {
    Text = "La mujer encadenada inventariaba los tesoros arrebatados.%player%La Llave de Plata y el Hilo en el bolsillo, el espejo, la Pluma negra y la Manzana dorada en el paquete de Caraboo."
  },
  AvgDialog_145515_Content_15 = {
    Text = "¿El globo ocular de Balor?"
  },
  AvgDialog_145515_Content_16 = {
    Text = "Helot soltó una risita burlona y acto seguido clavó sus afiladas uñas en la bola de cadena que llevaba a su lado."
  },
  AvgDialog_145515_Content_17 = {
    Text = "Con un sonido húmedo y viscoso, la bola de cadena emitió un extraño crujido pegajoso."
  },
  AvgDialog_145515_Content_18 = {
    Text = "Ella revolvió, escarbó… hasta extraer de su interior un globo ocular ensangrentado."
  },
  AvgDialog_145515_Content_19 = {
    Text = "Todo para ti, glotón."
  },
  AvgDialog_145515_Content_2 = {
    Text = "–8800 metros de altitud–"
  },
  AvgDialog_145515_Content_20 = {
    Text = "Colocó las seis reliquias en cada esquina del altar."
  },
  AvgDialog_145515_Content_21 = {
    Text = "Ahora, es momento de que se cumpla mi deseo."
  },
  AvgDialog_145515_Content_22 = {
    Text = "Cerró los ojos y guardó silencio."
  },
  AvgDialog_145515_Content_23 = {
    Text = "Que Ella renazca… que yo pueda matar a mi enemigo con mis propias manos y cumplir mi tan anhelada venganza."
  },
  AvgDialog_145515_Content_24 = {
    Text = "Un Viento gélido sopló sobre las cimas de Los Atrapados en la Nieve. Su deseo no obtuvo respuesta alguna."
  },
  AvgDialog_145515_Content_25 = {
    Text = "¿Por qué? ¿Acaso no te he entregado ya los siete Mantenimientos?"
  },
  AvgDialog_145515_Content_26 = {
    Text = "La voz de protesta de Helot resonó entre los lejanos picos, desencadenando una avalancha tras otra."
  },
  AvgDialog_145515_Content_27 = {
    Text = "¿Porque alguna de las ofrendas es falsa, quizás?"
  },
  AvgDialog_145515_Content_28 = {Text = "¿Quién?!"},
  AvgDialog_145515_Content_29 = {
    Text = "Caraboo avanzó dando saltitos ligeros, Como Si Helot no le importara en absoluto."
  },
  AvgDialog_145515_Content_3 = {
    Text = "Este era un lugar donde las huellas humanas jamás habían llegado."
  },
  AvgDialog_145515_Content_30 = {
    Text = "Vosotros Solo pensáis en vuestros propios deseos, pero nunca os habéis preguntado qué ofrenda es la que la Deidad realmente desea."
  },
  AvgDialog_145515_Content_31 = {
    Text = "la Manzana Dorada, la Manzana Dorada… ¿No creerás que con Solo elegir una Manzana de color dorado ya habrás acertado, verdad?"
  },
  AvgDialog_145515_Content_32 = {
    Text = "Tomó la Manzana Dorada del altar y le dio un pequeño mordisco."
  },
  AvgDialog_145515_Content_33 = {
    Text = "Mmm, tal como imaginaba."
  },
  AvgDialog_145515_Content_34 = {
    Text = "El papel de aluminio dorado se desprendió, revelando lo que había en su interior."
  },
  AvgDialog_145515_Content_35 = {
    Text = "Aperitivo, caramelo, tableta de cacao, llámalo como quieras; en definitiva, era el chocolate más corriente y vulgar del mundo."
  },
  AvgDialog_145515_Content_36 = {
    Text = "<BigShake:¡Fanfarria! ¡La Bendición de las hadas, el manjar supremo!>"
  },
  AvgDialog_145515_Content_37 = {
    Text = "Tú… embustero…"
  },
  AvgDialog_145515_Content_38 = {
    Text = "Un ladrón tampoco es mucho mejor que un embustero, ¿no?"
  },
  AvgDialog_145515_Content_39 = {
    Text = "¡Deja de parlotear y entrega la verdadera Manzana Dorada!"
  },
  AvgDialog_145515_Content_4 = {
    Text = "De pie en la cima de la montaña nevada, contemplando las blancas cumbres a lo lejos, lo que resonaba en el pecho no era precisamente la sensación de Logros por haber llegado a la cima."
  },
  AvgDialog_145515_Content_40 = {
    Text = "Para eso tendrás que preguntarles a ellos si están de acuerdo."
  },
  AvgDialog_145515_Content_41 = {
    Text = "Caraboo se hizo a un lado; los miembros del equipo de montañismo acababan de escalar el último peñasco."
  },
  AvgDialog_145515_Content_5 = {
    Text = "Sino miedo."
  },
  AvgDialog_145515_Content_6 = {
    Text = "El miedo de alejarse del mundo humano, el miedo de estar separado de todo lo conocido."
  },
  AvgDialog_145515_Content_7 = {
    Text = "Aquí no había cumbres más altas, y lo único que podía hacer quien llegara a la cima era arrodillarse ante el cielo."
  },
  AvgDialog_145515_Content_8 = {
    Text = "Todos, hemos llegado a la cima."
  },
  AvgDialog_145515_Content_9 = {
    Text = "Entre los miembros del equipo de montañismo, solo una persona no se vio en absoluto conmovida por el paisaje de la cumbre."
  },
  AvgDialog_145516_Content_1 = {
    Text = "El Precursor"
  },
  AvgDialog_145516_Content_10 = {
    Text = "Así que aún nos faltan la <Blue:Llave de Salomón> y el <Blue:Ojo de Balor>."
  },
  AvgDialog_145516_Content_11 = {
    Text = "Caraboo contaba con los dedos, murmurando entre dientes."
  },
  AvgDialog_145516_Content_12 = {
    Text = "¿Crees que el Ojo de Balor también caerá del cielo de repente, igual que la Pluma de Ma'at?"
  },
  AvgDialog_145516_Content_13 = {
    Text = "Ese chiste no tiene ninguna gracia."
  },
  AvgDialog_145516_Content_14 = {
    Text = "No sabías qué le había ocurrido a Castor, pero en aquella Pluma de un negro absoluto quedaba el rastro de su presencia."
  },
  AvgDialog_145516_Content_15 = {
    Text = "Ya no queda mucho por delante."
  },
  AvgDialog_145516_Content_16 = {
    Text = "Antes de llegar a la cima, no podemos dar la vuelta."
  },
  AvgDialog_145516_Content_17 = {
    Text = "William te dio una palmada en el hombro. Era evidente que sabía lo que estabas pensando."
  },
  AvgDialog_145516_Content_18 = {
    Text = "¿Sabes? Tengo una corazonada."
  },
  AvgDialog_145516_Content_19 = {
    Text = "Castor seguramente encontró lo que quería perseguir, y por eso abandonó el equipo."
  },
  AvgDialog_145516_Content_2 = {
    Text = "Este es el último punto de descanso antes de llegar a la cima."
  },
  AvgDialog_145516_Content_20 = {
    Text = "Y si es él, estoy segura de que logrará cumplir su deseo."
  },
  AvgDialog_145516_Content_21 = {
    Text = "Evelyn carraspeó levemente, como si quisiera dar más peso a sus palabras, y añadió algo más."
  },
  AvgDialog_145516_Content_22 = {
    Text = "Siempre Que uno vive el tiempo suficiente, puede Mirar furtivamente el rumbo del destino ajeno incluso en breves encuentros."
  },
  AvgDialog_145516_Content_23 = {
    Text = "En Castor, ¿qué fue lo que viste?"
  },
  AvgDialog_145516_Content_24 = {
    Text = "Sencillez y tenacidad."
  },
  AvgDialog_145516_Content_25 = {
    Text = "Hasta obtener esa única respuesta, no se detendrá.\nNo dudará, ni tampoco se rendirá."
  },
  AvgDialog_145516_Content_26 = {
    Text = "¿Y tú, Evelyn? ¿Dónde está Tu respuesta?"
  },
  AvgDialog_145516_Content_27 = {
    Text = "Está en la montaña."
  },
  AvgDialog_145516_Content_28 = {
    Text = "¡Qué conveniente, vamos por el mismo Camino!"
  },
  AvgDialog_145516_Content_29 = {
    Text = "Caraboo sacó una Manzana de quién sabe dónde, la lanzó al aire y la atrapó."
  },
  AvgDialog_145516_Content_3 = {
    Text = "Al mirar atrás hacia las montañas lejanas, bajo tus pies se extiende una vasta extensión de hielo y Nieve que se pierde en el horizonte entre las nubes del desfiladero."
  },
  AvgDialog_145516_Content_30 = {
    Text = "Si todos están listos, Comenzar el último tramo."
  },
  AvgDialog_145516_Content_31 = {
    Text = "No bajen la guardia. Muchos imprevistos ocurren en el último kilómetro."
  },
  AvgDialog_145516_Content_32 = {
    Text = "Ante ustedes se alza una pared de hielo casi vertical."
  },
  AvgDialog_145516_Content_33 = {
    Text = "#N/ANaraka balancea el piolet, clavando el pico diagonalmente en la nieve dura con un golpe sordo, luego desplaza su peso hacia arriba, con los puntos delanteros pisando con precisión el pequeño agujero dejado por el pico."
  },
  AvgDialog_145516_Content_34 = {
    Text = "Qué extraño, parece que alguien ha estado aquí recientemente."
  },
  AvgDialog_145516_Content_35 = {
    Text = "Miren, aquí hay algunos agujeros que parecen haber sido hechos por un piolet."
  },
  AvgDialog_145516_Content_36 = {
    Text = "¿Podrían ser los restos del equipo explorador anterior?"
  },
  AvgDialog_145516_Content_37 = {
    Text = "No lo parece. Ha pasado demasiado tiempo; las huellas de entonces ya habrían quedado selladas bajo el hielo nuevamente."
  },
  AvgDialog_145516_Content_38 = {
    Text = "En fin, no hay que darle más vueltas. Que alguien haya pasado por aquí es buena señal; significa que este camino es viable."
  },
  AvgDialog_145516_Content_39 = {
    Text = "Tomó un tornillo de hielo del arnés, lo hizo girar y lo clavó en la capa de hielo, arrancando un crujido que ponía los dientes de punta."
  },
  AvgDialog_145516_Content_4 = {
    Text = "El magnífico paisaje les brinda cierto alivio a pesar del cansancio que ya sentían."
  },
  AvgDialog_145516_Content_40 = {
    Text = "Hasta que el pitón quedó enterrado hasta la base, Naraka colocó un mosquetón de rosca sobre él, pasó la cuerda principal por dentro y cerró el seguro hasta el fondo."
  },
  AvgDialog_145516_Content_41 = {
    Text = "Primer punto de protección."
  },
  AvgDialog_145516_Content_42 = {
    Text = "Todos, enganchen el bloqueador a la cuerda principal. Usen los crampones de las botas de montaña para afianzarse en los agujeros que he tallado y avancen despacio."
  },
  AvgDialog_145516_Content_43 = {
    Text = "Buscaste con el piolet un punto de apoyo sólido sobre tu cabeza, clavaste la punta con firmeza, luego levantaste el pie derecho y pateaste con fuerza la superficie de hielo con los dientes delanteros, dejando que esos dos colmillos de acero mordieran bien."
  },
  AvgDialog_145516_Content_44 = {
    Text = "Carga el peso sobre los pies, no te abraces a la pared de hielo."
  },
  AvgDialog_145516_Content_45 = {
    Text = "Inhalaste profundamente el aire tan enrarecido que dolía, alejaste el cuerpo un poco de la pared de hielo y dejaste que los crampones soportaran el peso. El pie izquierdo siguió el movimiento con otra patada."
  },
  AvgDialog_145516_Content_46 = {
    Text = "El bloqueador fue deslizándose lentamente hacia arriba contigo, traqueteando en falso con cada pequeño avance."
  },
  AvgDialog_145516_Content_47 = {
    Text = "A mitad del trayecto, ya estabas empapado en sudor y la concentración que habías reunido se disipaba sin remedio."
  },
  AvgDialog_145516_Content_48 = {
    Text = "Espabila; este tramo no admite ningún imprevisto."
  },
  AvgDialog_145516_Content_49 = {
    Text = "Justo cuando sus palabras terminaron de caer, ocurrió el imprevisto."
  },
  AvgDialog_145516_Content_5 = {
    Text = "<Shake:Es... espera un momento.>"
  },
  AvgDialog_145516_Content_50 = {Text = "..."},
  AvgDialog_145516_Content_51 = {
    Text = "Un destello de luz roja parpadeó en la oscuridad, y la nariz de William se agitó—"
  },
  AvgDialog_145516_Content_52 = {
    Text = "<BigShake:¡Al suelo—!>"
  },
  AvgDialog_145516_Content_53 = {
    Text = "Antes de que sus palabras terminaran, ya se había lanzado sobre ti con violencia, aplastándote con todo su cuerpo; solo la cuerda de seguridad los sostenía a ambos, golpeando contra la pared de hielo."
  },
  AvgDialog_145516_Content_54 = {
    Text = "Un fino hilo de sangre apareció en su mejilla."
  },
  AvgDialog_145516_Content_55 = {
    Text = "Vaya, reflejos bastante rápidos."
  },
  AvgDialog_145516_Content_56 = {
    Text = "Desde las profundidades de la oscuridad, unas pesadas cadenas se arrastraban por el suelo; el roce del metal contra el piso producía un sonido sordo y prolongado."
  },
  AvgDialog_145516_Content_57 = {
    Text = "Así que eres tú, el tipo que nos ha estado siguiendo todo el camino."
  },
  AvgDialog_145516_Content_58 = {
    Text = "¿Siguiéndonos todo el camino?"
  },
  AvgDialog_145516_Content_59 = {
    Text = "Sí, cuando nos encontramos con Castor, ya os avisé de que alguien nos seguía."
  },
  AvgDialog_145516_Content_6 = {
    Text = "Evelyn respiraba con dificultad. La baja presión de la gran altitud claramente estaba afectando gravemente su cuerpo."
  },
  AvgDialog_145516_Content_60 = {
    Text = "Lo que no sé es cuándo se adelantó a nosotros."
  },
  AvgDialog_145516_Content_61 = {
    Text = "No me extraña que esa presencia me resultara tan familiar."
  },
  AvgDialog_145516_Content_62 = {
    Text = "Recuerdo tu nombre——"
  },
  AvgDialog_145516_Content_63 = {
    Text = "Perfecto, así nos ahorramos las presentaciones."
  },
  AvgDialog_145516_Content_64 = {
    Text = "En la frontera entre la luz y la sombra, una silueta avanzó lentamente."
  },
  AvgDialog_145516_Content_65 = {
    Text = "Tenía ambas muñecas cercenadas y arrastraba tras de sí dos pesadas bolas de cadena, sobre las cuales un par de enormes ojos de color sangre contemplaban el mundo con ferocidad."
  },
  AvgDialog_145516_Content_66 = {
    Text = "……Helot: Catena."
  },
  AvgDialog_145516_Content_67 = {
    Text = "En el mundo anterior, ella fue la última persona que vi."
  },
  AvgDialog_145516_Content_68 = {
    Text = "Dicho de otro modo— ella fue quien me mató."
  },
  AvgDialog_145516_Content_69 = {
    Text = "En aquel entonces, obedecía a Herbert, obedecía a la Asociación de Escultores."
  },
  AvgDialog_145516_Content_7 = {
    Text = "Detrás de ella, la pequeña chica caminaba con paso ligero."
  },
  AvgDialog_145516_Content_70 = {
    Text = "¿Y ahora? ¿<Yellow:Quién> te envía?"
  },
  AvgDialog_145516_Content_71 = {
    Text = "Solo los perros se preocupan por saber quién es su amo."
  },
  AvgDialog_145516_Content_72 = {
    Text = "Solo tengo una cosa que hacer: que os quedéis enterrados aquí para siempre."
  },
  AvgDialog_145516_Content_73 = {
    Text = "Innumerables pústulas emergen del suelo, rodeándoos por completo."
  },
  AvgDialog_145516_Content_8 = {
    Text = "Ya tenemos el <Blue:Espejo de Yata> y la <Blue:Pluma de Ma'at>. La <Blue:Corona de Ariadna> debería estar en la cima."
  },
  AvgDialog_145516_Content_9 = {
    Text = "En cuanto al <Blue:Hilo de Moira>... Jeje, algunos no me lo dirán, pero sé dónde está. Y puedo conseguirnos una <Blue:Manzana Dorada>."
  },
  AvgDialog_145517_Content_1 = {
    Text = "Hoy Parten los Pájaros"
  },
  AvgDialog_145517_Content_10 = {
    Text = "Salid ya, me habéis seguido durante todo el Camino, ¿verdad?"
  },
  AvgDialog_145517_Content_11 = {
    Text = "Ya estoy solo y la distancia ahora no es suficiente para pedir ayuda a gritos."
  },
  AvgDialog_145517_Content_12 = {
    Text = "<Shake:Dejemos... que nos... enfrentemos...>"
  },
  AvgDialog_145517_Content_13 = {
    Text = "La persona que emergió del bosque parecía haber salido de su sueño."
  },
  AvgDialog_145517_Content_14 = {
    Text = "<Shake:No… tú eres…>"
  },
  AvgDialog_145517_Content_15 = {
    Text = "Una figura erguida y distinguida, aún más delgada que cuando se separaron."
  },
  AvgDialog_145517_Content_16 = {
    Text = "Mi nombre es Pollux. Por orden del Maestro, he venido a capturar al fugitivo Castor."
  },
  AvgDialog_145517_Content_17 = {
    Text = "El contenido ya no importaba; su voz resonaba en los oídos de Castor como Susurros."
  },
  AvgDialog_145517_Content_18 = {
    Text = "<SmallShake:¿Un Wendigo?>"
  },
  AvgDialog_145517_Content_19 = {
    Text = "No, no era un Wendigo. Incluso la más sublime de las ilusiones no podía falsificar la textura de lo real."
  },
  AvgDialog_145517_Content_2 = {
    Text = "El joven corría velozmente por la Nieve."
  },
  AvgDialog_145517_Content_20 = {
    Text = "Pecador… Castor… La luz sagrada revelará tus crímenes."
  },
  AvgDialog_145517_Content_21 = {
    Text = "Real, áspero, gélido, cruel, estremecedor."
  },
  AvgDialog_145517_Content_22 = {Text = "Pollux…"},
  AvgDialog_145517_Content_23 = {
    Text = "Un dolor punzante que le invadió el corazón."
  },
  AvgDialog_145517_Content_24 = {
    Text = "¿Cuánto tiempo más podría Evadir? ¿Cuánto tiempo más podría seguir evadiendo?"
  },
  AvgDialog_145517_Content_25 = {
    Text = "Castor caminó sobre la Nieve, paso a paso, avanzando hacia Pollux."
  },
  AvgDialog_145517_Content_26 = {
    Text = "<Red:<Shake:¡Arrodíllate ante la Linterna, y yo te absolveré de tus pecados, concediéndote el renacimiento en una nueva forma sobre la santa tierra sin pecado!>"
  },
  AvgDialog_145517_Content_27 = {
    Text = "Castor no obedeció. Solo siguió avanzando hacia Pollux."
  },
  AvgDialog_145517_Content_28 = {
    Text = "Aunque fuera un Wendigo, no le importaba. Solo avanzaba."
  },
  AvgDialog_145517_Content_29 = {
    Text = "Pollux levantó su cuchillo. Un cuchillo familiar. En la última Persecución, había Atravesado el pecho de Castor."
  },
  AvgDialog_145517_Content_3 = {
    Text = "Ya nada podía detenerlo."
  },
  AvgDialog_145517_Content_30 = {
    Text = "<Big:¡Un paso más, y la luz sagrada te fulminará!>"
  },
  AvgDialog_145517_Content_4 = {
    Text = "El Camino de bajada… era tan ligero como volar con el Viento."
  },
  AvgDialog_145517_Content_5 = {
    Text = "Un Camino sin el peso de Una Mentira hacía que su corazón también se elevara flotando."
  },
  AvgDialog_145517_Content_6 = {
    Text = "Lo siento, no debí engañaros."
  },
  AvgDialog_145517_Content_7 = {
    Text = "Por suerte, aún hay tiempo para remediarlo."
  },
  AvgDialog_145517_Content_8 = {
    Text = "Cada vez que se detenía un momento, desde el bosque a su espalda llegaba un sonido parecido al de la Nieve al caer."
  },
  AvgDialog_145517_Content_9 = {
    Text = "Eran unos pasos que se detenían de golpe."
  },
  AvgDialog_145518_Content_1 = {
    Text = "La Luna sin Hielo"
  },
  AvgDialog_145518_Content_10 = {
    Text = "Aceptas de buen grado."
  },
  AvgDialog_145518_Content_100 = {
    Text = "Ay, el astuto embaucador, siempre aparece con la imagen más pura de víctima…"
  },
  AvgDialog_145518_Content_101 = {
    Text = "Ella tarareó una melodía y volvió a adelantarse al frente de la fila."
  },
  AvgDialog_145518_Content_102 = {
    Text = "¿Qué quiso decir con eso?"
  },
  AvgDialog_145518_Content_103 = {
    Text = "Tampoco lo entendí."
  },
  AvgDialog_145518_Content_104 = {
    Text = "¡Eh~, sígueme, no te quedes atrás~!"
  },
  AvgDialog_145518_Content_105 = {
    Text = "Los dos, sin entender nada, no tuvieron más remedio que seguir adelante."
  },
  AvgDialog_145518_Content_106 = {
    Text = "–Altitud 6000 m–"
  },
  AvgDialog_145518_Content_11 = {
    Text = "Sé que es difícil de creer, pero vengo de una estrella muy, muy lejana. He vagado tanto tiempo que lo único que recuerdo es que en sus últimos días, la llamábamos <Blue:Estrella Infausta.>"
  },
  AvgDialog_145518_Content_12 = {
    Text = "Viajé a través de un tiempo tan largo que no podría contarse, hasta llegar aquí."
  },
  AvgDialog_145518_Content_13 = {Text = "Te creo."},
  AvgDialog_145518_Content_14 = {
    Text = "Lo que quiero decir es… la Estrella Infausta está tan lejos, tan lejos, que incluso imaginarla o describirla resulta muy difícil."
  },
  AvgDialog_145518_Content_15 = {
    Text = "Pero hace un momento, en el lago… creo haber visto a mi hermana, Faint."
  },
  AvgDialog_145518_Content_16 = {
    Text = "Tinct se muerde el labio."
  },
  AvgDialog_145518_Content_17 = {
    Text = "No, en realidad tampoco es eso… Solo es que percibí cierto presagio; la sombra en el lago también proviene de la Estrella Infausta…"
  },
  AvgDialog_145518_Content_18 = {
    Text = "Sé que es imposible, pero siento que... <Shake:no fue una alucinación...>"
  },
  AvgDialog_145518_Content_19 = {
    Text = "Pareces muy cansada."
  },
  AvgDialog_145518_Content_2 = {
    Text = "La ventisca había cesado en algún momento, y solo quedaba un silencio tan vasto que hacía temblar. Sobre vuestras cabezas se extendía un azul profundo sin una sola nube, y hasta los picos nevados en la distancia se revelaban con una nitidez absoluta."
  },
  AvgDialog_145518_Content_20 = {
    Text = "Evelyn mostró una expresión de preocupación."
  },
  AvgDialog_145518_Content_21 = {
    Text = "Si te sientes cansada, deberías Descansar a tiempo."
  },
  AvgDialog_145518_Content_22 = {
    Text = "Acabamos de Partir, así que bajar la montaña sola tampoco sería peligroso."
  },
  AvgDialog_145518_Content_23 = {
    Text = "<Yellow:<Big:¡No...! ¡No estoy cansada! ¡NO ME VOY A IR!>>"
  },
  AvgDialog_145518_Content_24 = {
    Text = "Para sorpresa de todos, Tinct soltó un grito como si hubiera recibido un impacto."
  },
  AvgDialog_145518_Content_25 = {
    Text = "Al darse cuenta de que todas las miradas estaban puestas en ella, Tinct intentó calmarse, pero su pecho agitado traicionó sus sentimientos reales."
  },
  AvgDialog_145518_Content_26 = {
    Text = "Lo siento… me he dejado llevar. Gracias por tu preocupación, pero <Yellow:no estoy cansada.>"
  },
  AvgDialog_145518_Content_27 = {
    Text = "Mentir no tiene ninguna gracia."
  },
  AvgDialog_145518_Content_28 = {
    Text = "Soy muy perseverante. No me quedaré atrás."
  },
  AvgDialog_145518_Content_29 = {
    Text = "Tinct volvió a apretar los labios, echó un último vistazo al lago helado y dio un paso para Partir."
  },
  AvgDialog_145518_Content_3 = {
    Text = "Bajo ese cielo despejado, recorréis el camino hasta llegar a la orilla de un lago helado."
  },
  AvgDialog_145518_Content_30 = {
    Text = "Sobre la superficie helada del lago, Solo se reflejaba su silueta borrosa."
  },
  AvgDialog_145518_Content_31 = {
    Text = "Tras medio día de marcha, encontrasteis un terreno llano para acampar, y Naraka ordenó a todos los montañeros que recogieran Nieve derretida para hervir agua con los hornillos de alta montaña."
  },
  AvgDialog_145518_Content_32 = {
    Text = "Pero cuando regresasteis con la Nieve acumulada, descubristeis que había una densa columna de humo junto al campamento."
  },
  AvgDialog_145518_Content_33 = {
    Text = "Oye, ¿de quién es el equipaje que está ardiendo por allí?"
  },
  AvgDialog_145518_Content_34 = {
    Text = "¿Eh…? ¡¡¡No!!!"
  },
  AvgDialog_145518_Content_35 = {
    Text = "Las llamas lamían la pequeña bolsa de tela que Caraboo siempre había tratado como un tesoro."
  },
  AvgDialog_145518_Content_36 = {
    Text = "Espera, ¿esta bolsa de monedas de oro que tienes en la mochila?"
  },
  AvgDialog_145518_Content_37 = {
    Text = "Bajo el calor de las llamas, las monedas de oro se fueron ablandando y hundiendo."
  },
  AvgDialog_145518_Content_38 = {
    Text = "¡No! ¡No pasa nada! ¡Puedo rescatarlas!"
  },
  AvgDialog_145518_Content_39 = {
    Text = "¡No, déjame ver!"
  },
  AvgDialog_145518_Content_4 = {
    Text = "Tinct contempla el lago absorta, con la mirada perdida."
  },
  AvgDialog_145518_Content_40 = {
    Text = "Al rasgar el envoltorio, todas las monedas semiderretidas cayeron al suelo."
  },
  AvgDialog_145518_Content_41 = {
    Text = "Una de ellas rodó hasta los pies de William, quien se agachó para recogerla."
  },
  AvgDialog_145518_Content_42 = {
    Text = "<Blue:Debauve & Gallais, chocolate Pistoles de Marie...>"
  },
  AvgDialog_145518_Content_43 = {
    Text = "¿¡Chocolate?!"
  },
  AvgDialog_145518_Content_44 = {
    Text = "<Shake:Ja, jaja…> Esto… ¡aunque solo sea chocolate, es muy caro!"
  },
  AvgDialog_145518_Content_45 = {
    Text = "¡Déjate de tonterías! ¡Si no puedes pagar la tarifa del guía, lárgate del grupo!"
  },
  AvgDialog_145518_Content_46 = {
    Text = "<Shake:No, por favor, yo sola no conozco el Camino…>"
  },
  AvgDialog_145518_Content_47 = {
    Text = "<Shake:¡Si me echas del grupo, seguro que moriré en el descenso!>"
  },
  AvgDialog_145518_Content_48 = {
    Text = "¡A la porra! ¿De qué sirve ponerse a llorar ahora? ¡Quien engaña debe estar preparado para ser descubierto!"
  },
  AvgDialog_145518_Content_49 = {
    Text = "Al ver que Naraka no cedía ni a ruegos ni a amenazas, Caraboo miró a su alrededor y luego, Como Si se aferrara a un salvavidas, cayó de rodillas con un golpe seco y se agarró con fuerza a tus piernas."
  },
  AvgDialog_145518_Content_5 = {
    Text = "¿Hay algo en el lago?"
  },
  AvgDialog_145518_Content_50 = {
    Text = "<Shake:Por favor, alma caritativa, no puedes dejar que una chica joven baje la montaña sola y desamparada, ¿verdad?>"
  },
  AvgDialog_145518_Content_51 = {
    Text = "<Shake:Buaaah, siempre es lo mismo, siempre me abandonan, no importa adónde vaya, todo el mundo me desprecia por no tener nada…>"
  },
  AvgDialog_145518_Content_52 = {
    Text = "<Shake:Buena persona, alma bondadosa, seguro que tú eres diferente a ellos, seguro que me ayudarás, ¿verdad?>"
  },
  AvgDialog_145518_Content_53 = {
    Text = "Ella levantó la cabeza y te miró fijamente con los ojos llenos de lágrimas."
  },
  AvgDialog_145518_Content_54 = {
    Text = "…Está bien. Su tarifa de guía, te la pagaré cuando bajemos."
  },
  AvgDialog_145518_Content_55 = {
    Text = "Sin poder resistir su mirada, cediste y aceptaste."
  },
  AvgDialog_145518_Content_56 = {
    Text = "<Big:¡Gracias, muchas gracias, mi benefactor!!> ¡Eres el salvador más grandioso y magnífico que Caraboo ha conocido jamás!!"
  },
  AvgDialog_145518_Content_57 = {
    Text = "Caraboo secó sus lágrimas al instante y saltó con una sonrisa de oreja a oreja."
  },
  AvgDialog_145518_Content_58 = {
    Text = "¡Benefactor, una vez que haya recuperado mi poder como diosa de la montaña, repagaré tu bondad mil veces!"
  },
  AvgDialog_145518_Content_59 = {
    Text = "¡Cuando llegue ese momento, no solo podré pagar treinta monedas de oro, sino trescientas, o incluso tres mil!"
  },
  AvgDialog_145518_Content_6 = {
    Text = "No, no, nada, no hay nada…"
  },
  AvgDialog_145518_Content_60 = {
    Text = "Claro, claro."
  },
  AvgDialog_145518_Content_61 = {
    Text = "Respondes con evasivas."
  },
  AvgDialog_145518_Content_62 = {
    Text = "Al fin y al cabo, todos tenemos que escalar juntos. Con tal de que este asunto pase pronto, será suficiente."
  },
  AvgDialog_145518_Content_63 = {
    Text = "La situación finalmente se calma, y todos vuelven a sus ocupaciones o a descansar."
  },
  AvgDialog_145518_Content_64 = {
    Text = "William te lleva a un lado y te habla en voz baja."
  },
  AvgDialog_145518_Content_65 = {
    Text = "Qué extraño, recuerdo que la mochila de Caraboo no estaba en esa posición antes."
  },
  AvgDialog_145518_Content_66 = {
    Text = "<Red:¿Quién lo acercó a la fogata?>"
  },
  AvgDialog_145518_Content_67 = {
    Text = "El agua ya hirvió. Beban un poco para entrar en calor."
  },
  AvgDialog_145518_Content_68 = {
    Text = "¿Hay sopa de ajo?"
  },
  AvgDialog_145518_Content_69 = {
    Text = "¿Me preguntas a mí? No tengo nada de eso. Toma un poco de agua caliente para conformarte."
  },
  AvgDialog_145518_Content_7 = {
    Text = "Tinct vuelve en sí de repente, con una expresión de quien quiere decir algo pero se contiene."
  },
  AvgDialog_145518_Content_70 = {
    Text = "Hmph, no hay... Vaya guía Sherpa tan excelente que eres, y encima cobras tanto por tus servicios."
  },
  AvgDialog_145518_Content_71 = {
    Text = "Viendo que la tensión estaba a punto de estallar de nuevo, Evelyn se apresuró a intervenir."
  },
  AvgDialog_145518_Content_72 = {
    Text = "Si quieres tomar algo caliente, yo tengo un poco de chocolate caliente."
  },
  AvgDialog_145518_Content_73 = {
    Text = "Y tú, pequeño, ¿no llevas suficientes provisiones? He notado que casi no has comido nada."
  },
  AvgDialog_145518_Content_74 = {
    Text = "¿Yo? No hay problema, cuando hacemos retiro espiritual, también comemos solo una vez al día."
  },
  AvgDialog_145518_Content_75 = {
    Text = "Pero al escalar, no puedes dejar de reponer suficiente energía."
  },
  AvgDialog_145518_Content_76 = {
    Text = "Mi marido, cuando escalaba, también era como tú y siempre prefería llevar Las Mochilas más ligeras."
  },
  AvgDialog_145518_Content_77 = {
    Text = "Desde que una vez quedó atrapado por una ventisca durante varios días, siempre optó por estrategias más prudentes."
  },
  AvgDialog_145518_Content_78 = {
    Text = "Su marido... ¿también era Alpinista?"
  },
  AvgDialog_145518_Content_79 = {
    Text = "Sí, es un Alpinista muy destacado, antes también intentó llegar a la cima del Everest y del K2."
  },
  AvgDialog_145518_Content_8 = {
    Text = "Tras un momento, se vuelve hacia ti y habla en voz baja."
  },
  AvgDialog_145518_Content_80 = {
    Text = "¿Y entonces qué?"
  },
  AvgDialog_145518_Content_81 = {Text = "¿Y luego?"},
  AvgDialog_145518_Content_82 = {
    Text = "Tu esposo, ¿ya no escala montañas?"
  },
  AvgDialog_145518_Content_83 = {
    Text = "<Shake:¿Eh? ¿Por qué me jalas?>"
  },
  AvgDialog_145518_Content_84 = {
    Text = "Todos miraron hacia un lado siguiendo sus palabras. Caraboo tenía una sonrisa en el rostro, pero su mano jalaba disimuladamente la manga de Castor."
  },
  AvgDialog_145518_Content_85 = {
    Text = "Al ver que su Acción había sido descubierta, retiró la mano con cierta torpeza y murmuró algo en voz baja."
  },
  AvgDialog_145518_Content_86 = {
    Text = "<Small:Idiota>."
  },
  AvgDialog_145518_Content_87 = {
    Text = "No pasa nada…"
  },
  AvgDialog_145518_Content_88 = {
    Text = "Mi esposo… desapareció durante su último intento de llegar a la cima del Everest. Nadie sabe adónde fue. Tampoco encontraron su cuerpo."
  },
  AvgDialog_145518_Content_89 = {
    Text = "Antes siempre lo acompañaba, aunque me quedaba esperando alrededor del punto C2."
  },
  AvgDialog_145518_Content_9 = {
    Text = "Disculpa, no sé por qué, pero contigo siempre tengo una sensación de gran familiaridad. Así que… ¿podrías escucharme un momento?"
  },
  AvgDialog_145518_Content_90 = {
    Text = "Ahora que él se ha ido, también quiero ver el paisaje que él veía…"
  },
  AvgDialog_145518_Content_91 = {
    Text = "Evelyn contemplaba la cresta de la montaña en la distancia. La montaña de Nieve eterna guardaba silencio, respondiendo con el Aullido del Viento."
  },
  AvgDialog_145518_Content_92 = {
    Text = "Esta vez llegaremos a la cima sin falta."
  },
  AvgDialog_145518_Content_93 = {
    Text = "Así lo creo."
  },
  AvgDialog_145518_Content_94 = {
    Text = "Poco Después de que terminara la conversación, Caraboo recuperó su aire despreocupado y deambulaba de un lado a otro con las manos a la espalda."
  },
  AvgDialog_145518_Content_95 = {
    Text = "Se acercó a Castor con aire misterioso."
  },
  AvgDialog_145518_Content_96 = {
    Text = "Oye, idiota, ¿no tienes la sensación de que alguien nos está siguiendo?"
  },
  AvgDialog_145518_Content_97 = {
    Text = "Parece que no. Durante todo el Camino he estado alerta ante el rastreo de la Iglesia de los Portadores de Luz. Pero vosotros sois las primeras personas que me he encontrado…"
  },
  AvgDialog_145518_Content_98 = {
    Text = "Yo tampoco lo he notado."
  },
  AvgDialog_145518_Content_99 = {
    Text = "¿Ah sí? Entonces supongo que me lo estaba imaginando."
  },
  AvgDialog_145519_Content_1 = {Text = "..."},
  AvgDialog_145519_Content_10 = {
    Text = "El Espejo de Yata, junto con la Espada Kusanagi y el Magatama de Yasakani, son conocidos en la mitología japonesa como los Tres Tesoros Sagrados. En las representaciones más comunes, el Espejo de Yata está hecho de metal, con decoraciones de estilo japonés grabadas en su reverso."
  },
  AvgDialog_145519_Content_11 = {
    Text = "Pero mira este espejo…"
  },
  AvgDialog_145519_Content_12 = {
    Text = "La superficie del espejo es delgada, plana y pulida, de forma perfectamente redonda, como la luna llena suspendida en lo alto del cielo."
  },
  AvgDialog_145519_Content_13 = {
    Text = "Bajo la fría superficie de cristal, parecen circular tenuemente partículas de luz de algún tipo."
  },
  AvgDialog_145519_Content_14 = {
    Text = "De todas formas, primero saquémoslo para verlo."
  },
  AvgDialog_145519_Content_15 = {
    Text = "Naraka levantó un pico de hielo y rompió la capa de hielo con facilidad, extrayendo el espejo."
  },
  AvgDialog_145519_Content_16 = {
    Text = "Caraboo se abalanzó hacia adelante, lo arrebató de un tirón y lo guardó velozmente en su bolsa."
  },
  AvgDialog_145519_Content_17 = {
    Text = "<Shake:¡Oye! ¿Qué miran? ¡No me miren!>"
  },
  AvgDialog_145519_Content_18 = {
    Text = "¡Este tesoro siempre perteneció a la diosa de la montaña nevada, así que es obvio que al descubrirlo me corresponde a mí!"
  },
  AvgDialog_145519_Content_19 = {
    Text = "Nadie intentó disputarle la propiedad."
  },
  AvgDialog_145519_Content_2 = {
    Text = "Deambuláis junto al lago de hielo. La superficie del lago es Como Si fuera un espejo, tersa e inmaculada, con una vista despejada en todas direcciones; no hay rastro de Tinct."
  },
  AvgDialog_145519_Content_20 = {
    Text = "Comparado con un espejo que parecía completamente ordinario, la desaparición de Tinct era evidentemente más digna de atención."
  },
  AvgDialog_145519_Content_21 = {
    Text = "Pero nadie volvió a hablar del asunto. Solo su sombra seguía pesando, inevitable y opresiva, en el corazón de cada uno."
  },
  AvgDialog_145519_Content_3 = {
    Text = "Entre la Reverberación del Viento en las montañas nevadas, Como Si se mezclaran el canto de Tinct y unos sollozos tenues — presentes y ausentes a la vez, sin poder distinguir si era el Viento o un Fantasma."
  },
  AvgDialog_145519_Content_4 = {
    Text = "Tinct… ¿acaso no va a volver?"
  },
  AvgDialog_145519_Content_5 = {
    Text = "Nadie la contradijo."
  },
  AvgDialog_145519_Content_6 = {
    Text = "Qué extraño, ¿esto estaba aquí ayer?"
  },
  AvgDialog_145519_Content_7 = {
    Text = "En la superficie del lago helado, encerrado en silencio dentro del hielo transparente y sólido, había un Espejo perfectamente redondo."
  },
  AvgDialog_145519_Content_8 = {
    Text = "<Shake:¡El Espejo de Yata! ¡Este es el Espejo de Yata que debe ser ofrendado a la diosa de la montaña!>"
  },
  AvgDialog_145519_Content_9 = {
    Text = "William, parece que tienes algo que decir pero te lo estás guardando."
  },
  AvgDialog_145520_Content_1 = {
    Text = "Séptimo Viajero"
  },
  AvgDialog_145520_Content_10 = {
    Text = "Estos días no hay otros grupos de alpinistas, así que podéis descansar aquí tranquilamente, nadie vendrá a molestaros—"
  },
  AvgDialog_145520_Content_100 = {
    Text = "¡Cuidado! ¡Algo está saliendo a la superficie!"
  },
  AvgDialog_145520_Content_11 = {
    Text = "Antes de que Naraka terminara de hablar, un susurro repentino llegó desde el rincón de la cueva."
  },
  AvgDialog_145520_Content_12 = {
    Text = "…¿Eh, hay alguien?"
  },
  AvgDialog_145520_Content_13 = {
    Text = "La voz de William preguntando resonó por la cueva sin obtener respuesta."
  },
  AvgDialog_145520_Content_14 = {
    Text = "Somos un grupo de alpinistas, venimos aquí a refugiarnos del viento y la nieve, no tenemos malas intenciones."
  },
  AvgDialog_145520_Content_15 = {
    Text = "Enviando señales amistosas, tomaste la lámpara y te dirigiste hacia detrás de las rocas."
  },
  AvgDialog_145520_Content_16 = {Text = "¡Cuidado!"},
  AvgDialog_145520_Content_17 = {
    Text = "La silueta tras las rocas se tensó de repente. Sin esperar a que nadie explicara nada, un ataque feroz surgió desde la oscuridad."
  },
  AvgDialog_145520_Content_19 = {
    Text = "Quizás por enfrentarse a varios en solitario, el recién llegado lanzó una Emboscada y al instante se fundió de nuevo con las sombras. Pero tú lograste reconocer aquella silueta en el breve combate."
  },
  AvgDialog_145520_Content_2 = {
    Text = "Después de que Naraka os guiara un trecho, una grieta oscura apareció entre los picos de la montaña."
  },
  AvgDialog_145520_Content_20 = {
    Text = "<Shake:¿Castor?!>"
  },
  AvgDialog_145520_Content_21 = {
    Text = "Al cabo de un momento, una capa negra emergió de entre las sombras, y por detrás de ella asomó medio rostro con expresión cautelosa."
  },
  AvgDialog_145520_Content_22 = {
    Text = "…¿Tú me conoces?"
  },
  AvgDialog_145520_Content_23 = {
    Text = "No, eso es una historia muy larga de contar…"
  },
  AvgDialog_145520_Content_24 = {
    Text = "Entonces, ¿por qué estás aquí solo?"
  },
  AvgDialog_145520_Content_25 = {Text = "..."},
  AvgDialog_145520_Content_26 = {Text = "..."},
  AvgDialog_145520_Content_27 = {
    Text = "Bueno, mi hermano Pollux y yo acordamos escapar de la Iglesia de los Portadores de Luz por separado y de diferentes maneras. Pero esperé un mes en el lugar que habíamos acordado y él nunca apareció."
  },
  AvgDialog_145520_Content_28 = {
    Text = "Supongo que mi huida hizo que la señora Juliette reforzara la vigilancia. Desde entonces, he estado buscando la manera de rescatarlo."
  },
  AvgDialog_145520_Content_29 = {
    Text = "<Yellow:Por suerte, me escondí bien y logré escapar de su rastreo.>"
  },
  AvgDialog_145520_Content_3 = {Text = "Entramos."},
  AvgDialog_145520_Content_30 = {
    Text = "Al final, escuché que en la cima de la montaña nevada había una Deidad capaz de conceder cualquier deseo."
  },
  AvgDialog_145520_Content_31 = {
    Text = "Pero no puedo unirme a ningún equipo de escalada… Los espías de la Iglesia están por todas partes, y si aparezco con frecuencia, sería demasiado fácil que me descubrieran."
  },
  AvgDialog_145520_Content_32 = {Text = "Estúpido."},
  AvgDialog_145520_Content_33 = {Text = "¿Ah…?"},
  AvgDialog_145520_Content_34 = {
    Text = "Nunca había visto a nadie tan estúpido como tú."
  },
  AvgDialog_145520_Content_35 = {
    Text = "Aunque subieras la montaña solo, ¿dónde irías a buscar los siete artefactos mágicos?"
  },
  AvgDialog_145520_Content_36 = {Text = "..."},
  AvgDialog_145520_Content_37 = {
    Text = "Parece que no había pensado en eso…"
  },
  AvgDialog_145520_Content_38 = {
    Text = "¡Exacto! Ahora es cuando necesitas la ayuda de la Diosa de la Nieve."
  },
  AvgDialog_145520_Content_39 = {
    Text = "¡Vamos! Siempre Que te unas a La Orden Sagrada, te prometo que, tras llegar a la cima con éxito, ¡te ayudaré a resolver el dolor de la Separación entre tú y tu hermano!"
  },
  AvgDialog_145520_Content_4 = {
    Text = "Apoyándoos mutuamente, bajasteis por las rocas escarpadas, y tú volviste la vista hacia la entrada de la cueva."
  },
  AvgDialog_145520_Content_40 = {
    Text = "¿De verdad?"
  },
  AvgDialog_145520_Content_41 = {
    Text = "¡Por supuesto que es verdad! ¡No podría ser más verdad!"
  },
  AvgDialog_145520_Content_42 = {
    Text = "Pero para demostrar tu lealtad a La Orden Sagrada, deberás entregar todos los tesoros que lleves contigo para que la hada los guarde en tu nombre."
  },
  AvgDialog_145520_Content_43 = {
    Text = "......Está bien."
  },
  AvgDialog_145520_Content_44 = {
    Text = "Castor estuvo dudando un buen rato y finalmente sacó unas pocas monedas y un Libro de Cuentos muy manoseado y desgastado."
  },
  AvgDialog_145520_Content_45 = {
    Text = "Solo tengo esto. ¿Puedo unirme?"
  },
  AvgDialog_145520_Content_46 = {
    Text = "William te dio un golpecito en el brazo."
  },
  AvgDialog_145520_Content_47 = {
    Text = "¿Ya te has divertido bastante con el espectáculo?"
  },
  AvgDialog_145520_Content_48 = {
    Text = "Ejem, bueno, Castor, bienvenido a nuestro equipo de exploración."
  },
  AvgDialog_145520_Content_49 = {
    Text = "Caraboo solo estaba bromeando contigo; Siempre Que traigas tus propios suministros, no necesitas entregar nada más."
  },
  AvgDialog_145520_Content_5 = {
    Text = "La hendidura era larga y estrecha, como un ojo entreabierto, que mantenía el viento y la nieve a raya."
  },
  AvgDialog_145520_Content_50 = {
    Text = "Hmph, ni la diosa de la montaña nevada se dignaría aceptar esta miserable ofrenda de Mantenimiento. Guárdatela tú mismo."
  },
  AvgDialog_145520_Content_51 = {
    Text = "Castor alisó con cuidado los pliegues del Libro de Cuentos, tratándolo como un tesoro, y luego lo guardó con delicadeza en su pecho."
  },
  AvgDialog_145520_Content_52 = {
    Text = "Después echó un vistazo a las monedas y su mirada vagó entre vosotros."
  },
  AvgDialog_145520_Content_53 = {
    Text = "Si nadie las quiere, me las quedo yo con mucho gusto."
  },
  AvgDialog_145520_Content_54 = {
    Text = "Naraka agitó la mano y la piedra quedó vacía al instante."
  },
  AvgDialog_145520_Content_55 = {
    Text = "La tarifa de guía de este joven es mucho más barata que la de los demás."
  },
  AvgDialog_145520_Content_56 = {
    Text = "Si no recuerdo mal, ya pagamos tu tarifa de guía."
  },
  AvgDialog_145520_Content_57 = {
    Text = "Si hay que pagar una tarifa adicional, yo la cubriré por él."
  },
  AvgDialog_145520_Content_58 = {
    Text = "No es necesario, no nos conocemos de nada, no quisiera causarle molestias..."
  },
  AvgDialog_145520_Content_59 = {
    Text = "La mano extendida de Evelyn interrumpió las palabras de Castor, quien dudó medio segundo y luego le devolvió el apretón."
  },
  AvgDialog_145520_Content_6 = {
    Text = "Aquí Interior… qué calor…"
  },
  AvgDialog_145520_Content_60 = {
    Text = "Evelyn, me llamo Evelyn, soy arqueóloga."
  },
  AvgDialog_145520_Content_61 = {
    Text = "Ahora ya no somos desconocidos, ¿verdad?"
  },
  AvgDialog_145520_Content_62 = {Text = "..."},
  AvgDialog_145520_Content_63 = {
    Text = "La ventisca os atrapa a todos en la estrecha cueva. Sin fuego todavía, la conversación es vuestra única defensa contra el frío."
  },
  AvgDialog_145520_Content_64 = {
    Text = "Dijiste antes que estás buscando a tu hermano gemelo, ¿verdad?"
  },
  AvgDialog_145520_Content_65 = {Text = "Bien."},
  AvgDialog_145520_Content_66 = {
    Text = "Castor asintió con cautela."
  },
  AvgDialog_145520_Content_67 = {
    Text = "Qué coincidencia, yo también estoy buscando a mi hermana gemela."
  },
  AvgDialog_145520_Content_68 = {
    Text = "Faint y yo somos personas muy diferentes. Aunque mi hermana mayor tiene problemas de salud, en realidad es una persona valiente y fuerte."
  },
  AvgDialog_145520_Content_69 = {
    Text = "Al mencionar a su hermana gemela, Tinct, que solía estar siempre perdida en sus ensoñaciones, pareció cobrar vida y esbozó una leve sonrisa."
  },
  AvgDialog_145520_Content_7 = {
    Text = "Buf, buf, yo que soy la diosa de la montaña nevada, ¿cómo es que no sabía que existía un lugar así en la montaña?"
  },
  AvgDialog_145520_Content_70 = {
    Text = "¿Y Ese Pollux? ¿Cómo es él?"
  },
  AvgDialog_145520_Content_71 = {
    Text = "<Shake:Pollux...>"
  },
  AvgDialog_145520_Content_72 = {
    Text = "Tampoco es muy parecido a mí. Es inteligente, agudo, con gran capacidad de comprensión. Desde pequeño hasta ahora, el líder y los maestros siempre lo han preferido a él…"
  },
  AvgDialog_145520_Content_73 = {
    Text = "No te preocupes. Tú también tienes tus virtudes. Por ejemplo, ¿no acabas de decir que lograste escapar del rastreo de la iglesia? Eso también es bastante impresionante."
  },
  AvgDialog_145520_Content_74 = {
    Text = "Castor se sonrojó levemente, tosió una vez y desvió el tema de vuelta hacia Tinct."
  },
  AvgDialog_145520_Content_75 = {
    Text = "¿Y tú y tu hermana, por qué se separaron?"
  },
  AvgDialog_145520_Content_76 = {
    Text = "En el momento de escapar, ella me dejó el último pasaje."
  },
  AvgDialog_145520_Content_77 = {
    Text = "Su voz era muy suave, Como Si con el más mínimo esfuerzo, aquel recuerdo pudiera ser dispersado por el Viento y la Nieve."
  },
  AvgDialog_145520_Content_78 = {
    Text = "Ojalá al final podamos reencontrarnos con ellos."
  },
  AvgDialog_145520_Content_79 = {
    Text = "Castor guardó Silencio por un momento, y La Mirada pasó por encima de ella para posarse en la tormenta blanca que rugía sin cesar fuera de la cueva."
  },
  AvgDialog_145520_Content_8 = {
    Text = "Claro que no, la tarifa de guía de los Sherpa no se cobra en vano."
  },
  AvgDialog_145520_Content_80 = {
    Text = "Entre charlas, el tiempo fue pasando segundo a segundo."
  },
  AvgDialog_145520_Content_81 = {Text = "..."},
  AvgDialog_145520_Content_82 = {
    Text = "A la séptima hora, la tormenta alcanza un pico casi malicioso."
  },
  AvgDialog_145520_Content_83 = {
    Text = "Parece que esta noche tendremos que pasar la noche en la cueva."
  },
  AvgDialog_145520_Content_84 = {
    Text = "Naraka apartó los restos ya húmedos del centro de la cueva e intentó encender una nueva hoguera con madera seca."
  },
  AvgDialog_145520_Content_85 = {
    Text = "Desde la oscuridad de las Profundidades de la cueva llegó un sonido tenue y fragmentado, como si algo estuviera arañando la pared de piedra con las uñas."
  },
  AvgDialog_145520_Content_86 = {
    Text = "¿Hay ratones?"
  },
  AvgDialog_145520_Content_87 = {
    Text = "A esta altitud no debería haber ratones…"
  },
  AvgDialog_145520_Content_88 = {
    Text = "El sonido se detuvo de repente. El Silencio dentro de la cueva era inquietante."
  },
  AvgDialog_145520_Content_89 = {
    Text = "Desde aquella oscuridad tan densa que no dejaba pasar ni un rayo de luz, una sensación de malicia Le viento en la cara."
  },
  AvgDialog_145520_Content_9 = {
    Text = "Los ancianos dicen que esta grieta apareció de repente tras un alud de nieve."
  },
  AvgDialog_145520_Content_90 = {
    Text = "Naraka levantó la antorcha y la dirigió hacia las Profundidades de la cueva siguiendo el sonido. La luz avanzó apenas unos pasos antes de ser engullida por la oscuridad del frente."
  },
  AvgDialog_145520_Content_91 = {Text = "No vayas."},
  AvgDialog_145520_Content_92 = {
    Text = "Solo echo un vistazo."
  },
  AvgDialog_145520_Content_93 = {
    Text = "Naraka se apoyó en la pared rocosa y asomó el cuerpo con cuidado."
  },
  AvgDialog_145520_Content_94 = {
    Text = "La luz temblorosa de las llamas pasó por encima del borde de piedra bajo sus pies, iluminando un estanque de oscuridad absoluta. La superficie del agua era tan lisa que no tenía ni una sola ondulación, casi Fusionarse en uno con las sombras de los Alrededores."
  },
  AvgDialog_145520_Content_95 = {
    Text = "Abajo hay agua. <Shake:Parece muy profundo——>"
  },
  AvgDialog_145520_Content_96 = {
    Text = "Antes de que terminara de hablar, aquella \"superficie de agua\" completamente negra se hundió de repente hacia abajo."
  },
  AvgDialog_145520_Content_97 = {
    Text = "Naraka perdió el equilibrio y medio pie ya había caído en el hueco que se había abierto de golpe."
  },
  AvgDialog_145520_Content_98 = {
    Text = "<Shake:¡Agárrame——!>"
  },
  AvgDialog_145520_Content_99 = {
    Text = "Tú lo agarraste bruscamente del cuello de la ropa y lo jalaste hacia atrás."
  },
  AvgDialog_145521_Content_1 = {
    Text = "Junto al Fuego, al Caer la Noche"
  },
  AvgDialog_145521_Content_10 = {
    Text = "En un rincón había apiladas varias cajas de madera enmohecidas, y en la pared rocosa del fondo colgaba un trozo de cadena de hierro rota."
  },
  AvgDialog_145521_Content_100 = {
    Text = "Cerró los Ojos y sintió el contorno que rozaban sus yemas."
  },
  AvgDialog_145521_Content_101 = {
    Text = "<Small:<Italic:...\"El villano lanzó un hechizo y convirtió a su hermano menor en un cuervo.\">>"
  },
  AvgDialog_145521_Content_102 = {
    Text = "<Small:<Italic:...\"Pero el hermano mayor conocía el color de sus alas.\">>"
  },
  AvgDialog_145521_Content_103 = {
    Text = "La llama parpadeó una vez y luego se apagó."
  },
  AvgDialog_145521_Content_104 = {
    Text = "¿Podré traerte de vuelta?"
  },
  AvgDialog_145521_Content_105 = {
    Text = "La próxima vez que nos veamos, ¿podrás reconocerme?"
  },
  AvgDialog_145521_Content_106 = {Text = "..."},
  AvgDialog_145521_Content_107 = {
    Text = "Mucho tiempo después, cerró el libro, se levantó y caminó en silencio hasta la entrada de la cueva, agachándose para limpiar las grietas de ventilación obstruidas por la nieve nocturna."
  },
  AvgDialog_145521_Content_108 = {
    Text = "La nieve se escurrió entre sus dedos y cayó sobre el pequeño montículo ya acumulado, sin hacer ningún ruido."
  },
  AvgDialog_145521_Content_109 = {
    Text = "El alba aún no había llegado."
  },
  AvgDialog_145521_Content_11 = {
    Text = "¿Aquí vivió alguien antes?"
  },
  AvgDialog_145521_Content_110 = {
    Text = "Tú fuiste despertado por la tenue luz que se filtraba por la entrada de la cueva."
  },
  AvgDialog_145521_Content_111 = {
    Text = "Castor ya había recogido Las Mochilas y estaba de pie en la entrada de la cueva, esperando a que despertaras."
  },
  AvgDialog_145521_Content_112 = {
    Text = "Lo siento, me preparo para partir."
  },
  AvgDialog_145521_Content_113 = {
    Text = "Mi deseo es diferente al de vosotros."
  },
  AvgDialog_145521_Content_114 = {
    Text = "Quiero encontrar a mi hermano, y puedo lograrlo con mis propias manos."
  },
  AvgDialog_145521_Content_115 = {
    Text = "Pero este camino es demasiado peligroso, tú solo—"
  },
  AvgDialog_145521_Content_116 = {
    Text = "…Hay otra cosa sobre la que dudaba si debía contaros. Pero ahora es el momento de ser sincero—"
  },
  AvgDialog_145521_Content_117 = {
    Text = "Castor respiró profundamente, como si hubiera tomado una gran decisión."
  },
  AvgDialog_145521_Content_118 = {
    Text = "La primera vez que nos vimos, Tinct dijo que, aunque no era tan agradable como Pollux, yo también tenía mis virtudes: podía escapar solo del rastreo de la Iglesia de los Portadores de Luz."
  },
  AvgDialog_145521_Content_119 = {
    Text = "Pero era mentira. Os estaba engañando."
  },
  AvgDialog_145521_Content_12 = {
    Text = "Era un refugio de un antiguo equipo de montañismo, abandonado hace muchos años. El lugar para la hoguera está por allí, voy a limpiarlo."
  },
  AvgDialog_145521_Content_120 = {
    Text = "Soy mucho más débil de lo que creéis, y no lo logré."
  },
  AvgDialog_145521_Content_121 = {
    Text = "Los fieles han estado pisándome los talones todo el tiempo. Si me quedo, seré una carga para todos vosotros."
  },
  AvgDialog_145521_Content_122 = {
    Text = "Levantó la cabeza y miró hacia el Interior de la cueva, donde los demás aún dormían."
  },
  AvgDialog_145521_Content_123 = {
    Text = "El símbolo dañado en la caverna, lo reconocí: es el símbolo de la Iglesia de los Portadores de Luz."
  },
  AvgDialog_145521_Content_124 = {
    Text = "Este es su punto de apoyo Temporal."
  },
  AvgDialog_145521_Content_125 = {
    Text = "Cuanto más arriba, más despejado está. Tarde o temprano me Descubrirán. Mejor irme pronto, mezclarme con la multitud; así podré escapar más fácilmente de su Persecución."
  },
  AvgDialog_145521_Content_126 = {
    Text = "Él se dio la vuelta y se adentró en la Nieve y el Viento."
  },
  AvgDialog_145521_Content_127 = {
    Text = "Tú te quedaste en el mismo lugar mirando durante mucho tiempo, hasta que su silueta desapareció por completo."
  },
  AvgDialog_145521_Content_128 = {
    Text = "Desde atrás llegaron unos suaves pasos."
  },
  AvgDialog_145521_Content_129 = {
    Text = "Caraboo, sin saber cuándo se había levantado, estaba recostada en la entrada de la cueva, mirando en la dirección por la que Castor se había marchado."
  },
  AvgDialog_145521_Content_13 = {
    Text = "Se dirigió con paso seguro hacia una plataforma de piedra ennegrecida por el humo en el centro de la cueva, se agachó y comenzó a apartar las Cenizas acumuladas durante años."
  },
  AvgDialog_145521_Content_130 = {Text = "…Idiota."},
  AvgDialog_145521_Content_131 = {
    Text = "En su tono de voz no había la Espina habitual de siempre."
  },
  AvgDialog_145521_Content_132 = {
    Text = "El equipo de escalada pasó de cinco personas a cuatro."
  },
  AvgDialog_145521_Content_14 = {
    Text = "La Mirada de Castor se detuvo brevemente en las inscripciones de la pared. No dijo nada, Solo apartó La Mirada."
  },
  AvgDialog_145521_Content_15 = {
    Text = "Antes de que nadie pudiera preguntar, todos dirigieron La Mirada hacia donde Llamar Caraboo."
  },
  AvgDialog_145521_Content_16 = {
    Text = "<Big:¡Una cueva calentita! ¡Hoguera! ¡Descansar largo! >"
  },
  AvgDialog_145521_Content_17 = {
    Text = "Caraboo estaba lleno de Elación."
  },
  AvgDialog_145521_Content_18 = {
    Text = "Aunque todos se esforzaban por mantenerse despiertos, podías ver que el combate contra el Wendigo había dejado a todos agotados."
  },
  AvgDialog_145521_Content_19 = {
    Text = "Una cueva perfecta. Un descanso perfecto."
  },
  AvgDialog_145521_Content_2 = {
    Text = "La ventisca no amainaba. Siguiendo las grietas del hielo en busca de refugio, finalmente encontrasteis una cueva de nieve resguardada del viento bajo una pared rocosa."
  },
  AvgDialog_145521_Content_20 = {
    Text = "Sin importar qué peligros acechan más adelante, nada puede impedir que disfrutéis de un momento de tranquilidad ahora mismo."
  },
  AvgDialog_145521_Content_21 = {
    Text = "El fuego arde en el interior de la entrada de la cueva, cerca del borde. El humo es arrastrado hacia afuera por el viento oblicuo."
  },
  AvgDialog_145521_Content_22 = {
    Text = "Evelyn sacó de su mochila una esterilla impermeable, primero aplastó una fina capa de Nieve en el suelo y luego extendió la esterilla encima."
  },
  AvgDialog_145521_Content_23 = {
    Text = "Todos se quitaron los abrigos endurecidos por el frío y se reunieron alrededor de la hoguera, acercando las manos lo más posible a las llamas."
  },
  AvgDialog_145521_Content_24 = {
    Text = "Ojalá la montaña pudiera estar siempre tan cálida."
  },
  AvgDialog_145521_Content_25 = {Text = "Pfft."},
  AvgDialog_145521_Content_26 = {
    Text = "¿De qué te ríes?"
  },
  AvgDialog_145521_Content_27 = {
    Text = "Me río de ti, tonto, por no saber medir tus palabras. ¿Y si la diosa de la montaña nevada lo toma como tu deseo real y te lo concede?"
  },
  AvgDialog_145521_Content_28 = {
    Text = "Tampoco estaría mal. En ese caso, los alpinistas estarían mucho más seguros."
  },
  AvgDialog_145521_Content_29 = {
    Text = "La luz de la hoguera se reflejaba en los ojos serios de Castor."
  },
  AvgDialog_145521_Content_3 = {
    Text = "La entrada era estrecha, pero el interior resultó ser sorprendentemente amplio."
  },
  AvgDialog_145521_Content_30 = {
    Text = "Bah, no tiene gracia tomarte el pelo, tonto."
  },
  AvgDialog_145521_Content_31 = {
    Text = "Caraboo, ¿tú tienes algún deseo?"
  },
  AvgDialog_145521_Content_32 = {
    Text = "Caraboo pareció no esperar la pregunta repentina; tras un momento de sorpresa, sus ojos giraron pensativos."
  },
  AvgDialog_145521_Content_33 = {
    Text = "¡Yo soy la diosa de la montaña nevada, la encargada de conceder vuestros deseos!"
  },
  AvgDialog_145521_Content_34 = {
    Text = "Si tuviera que decir algún deseo, sería recuperar mi poder."
  },
  AvgDialog_145521_Content_35 = {
    Text = "¡Sí! ¡Exacto! ¡Después de recuperar mi poder, reorganizaré La Orden Sagrada y haré que todo el continente venga a rendir Mantenimiento a la diosa de la montaña nevada!"
  },
  AvgDialog_145521_Content_36 = {
    Text = "Evelyn suelta una suave carcajada. El resplandor del fuego parpadea en sus oscuros ojos."
  },
  AvgDialog_145521_Content_37 = {
    Text = "¿Y qué pasa con los demás?"
  },
  AvgDialog_145521_Content_38 = {
    Text = "Ella se volvió hacia ti, con una mirada sin curiosidad alguna, solo la preocupación propia de una Charla cotidiana."
  },
  AvgDialog_145521_Content_39 = {
    Text = "¡Yo también tengo curiosidad! ¿Qué tipo de deseo debería concederle a mi benefactor?"
  },
  AvgDialog_145521_Content_4 = {
    Text = "Que nadie entre todavía."
  },
  AvgDialog_145521_Content_40 = {
    Text = "Alguien me ha señalado un Camino de regreso a Nuestro Hogar. Para volver, necesito encontrar a una persona."
  },
  AvgDialog_145521_Content_41 = {
    Text = "Tú también eres tonto. ¿Por qué no pides simplemente un deseo para regresar?"
  },
  AvgDialog_145521_Content_42 = {
    Text = "Alguien escribió una Profecía para mí."
  },
  AvgDialog_145521_Content_43 = {
    Text = "<Yellow:El destino es una trama de eslabones entrelazados; quien pretenda saltarse cualquier nudo para llegar directamente al final, sufrirá inevitablemente el dolor de ver roto el hilo.>"
  },
  AvgDialog_145521_Content_44 = {
    Text = "Entendido. ¿Y qué hay del señor William que está a tu lado?"
  },
  AvgDialog_145521_Content_45 = {
    Text = "La historia de William es algo complicada de contar."
  },
  AvgDialog_145521_Content_46 = {
    Text = "Al menos por ahora, lo más importante para mí es acompañar a %player% de regreso a Misaq, de regreso al lado de Ramona."
  },
  AvgDialog_145521_Content_47 = {
    Text = "Miras a William con asombro. Él tiene una expresión tranquila, y en sus microexpresiones no encuentras ni el menor rastro de mentira."
  },
  AvgDialog_145521_Content_48 = {
    Text = "No hace falta que me mires así."
  },
  AvgDialog_145521_Content_49 = {
    Text = "<Yellow:Mis otras obligaciones en este mundo han llegado a un fin temporal.>"
  },
  AvgDialog_145521_Content_5 = {
    Text = "Levantó el pico de hielo y fue golpeando palmo a palmo la parte superior del interior de la entrada de la cueva."
  },
  AvgDialog_145521_Content_50 = {
    Text = "Al decir esto, William deliberadamente levantó la mano para apartar los mechones de cabello que le cubrían los ojos, ocultando así gran parte de su expresión."
  },
  AvgDialog_145521_Content_51 = {
    Text = "¿Y tú, tonto?"
  },
  AvgDialog_145521_Content_52 = {Text = "¿Yo?"},
  AvgDialog_145521_Content_53 = {
    Text = "Castor miraba fijamente la hoguera, absorto."
  },
  AvgDialog_145521_Content_54 = {
    Text = "Quiero que Pollux… vuelva."
  },
  AvgDialog_145521_Content_55 = {
    Text = "Caraboo levantó la vista hacia Castor, y ese atisbo habitual de cinismo en su mirada desapareció brevemente."
  },
  AvgDialog_145521_Content_56 = {
    Text = "Lo que acabas de decir es que quieres que él vuelva."
  },
  AvgDialog_145521_Content_57 = {
    Text = "Pero cuando nos vimos por primera vez, dijiste que querías rescatarlo."
  },
  AvgDialog_145521_Content_58 = {
    Text = "Hay una sutil diferencia entre esas dos formas de decirlo… aunque no necesariamente son incompatibles."
  },
  AvgDialog_145521_Content_59 = {
    Text = "Castor, tu hermano, ¿de verdad está prisionero de ese tal líder religioso?"
  },
  AvgDialog_145521_Content_6 = {
    Text = "Esta parte está Suelto, evitad acampar justo debajo."
  },
  AvgDialog_145521_Content_60 = {
    Text = "Un breve Silencio. Caraboo tomó la Manzana y le dio otro mordisco, cambiando de tema como si nada hubiera pasado."
  },
  AvgDialog_145521_Content_61 = {
    Text = "La verdad es que cumplir un deseo es muy sencillo."
  },
  AvgDialog_145521_Content_62 = {
    Text = "Mira, entre esos siete tesoros hay una pluma, ¿verdad? Quizás la pluma que llevas encima sea la <Yellow:Pluma de Ma'at>."
  },
  AvgDialog_145521_Content_63 = {
    Text = "Ma'at, diosa de la verdad, el orden y la justicia, lleva una pluma de avestruz en la cabeza."
  },
  AvgDialog_145521_Content_64 = {
    Text = "Durante el juicio de los muertos, Anubis coloca el corazón del difunto en una balanza junto a esta pluma. Si el corazón pesa más que la pluma, es devorado por el monstruo Ammit; si es tan ligero como la pluma, el alma puede entrar en el Campo de las Cañas."
  },
  AvgDialog_145521_Content_65 = {
    Text = "La pluma representa la \"inocencia\" en la mitología egipcia."
  },
  AvgDialog_145521_Content_66 = {
    Text = "La pluma de la inocencia… qué ironía."
  },
  AvgDialog_145521_Content_67 = {
    Text = "Castor esbozó una sonrisa levemente resignada."
  },
  AvgDialog_145521_Content_68 = {
    Text = "Estas alas me las implantaron a mí y a mi hermano la líder de la Iglesia de los Portadores de Luz, Juliette, para crear a su deidad."
  },
  AvgDialog_145521_Content_69 = {
    Text = "En su relato, escuchaste una voz. Una voz de dolor imposible de reprimir."
  },
  AvgDialog_145521_Content_7 = {
    Text = "Agachándose, se adentró más en la cueva, se arrodilló y pegó el oído al suelo durante un momento, luego comprobó la humedad de la roca con el dorso de la mano."
  },
  AvgDialog_145521_Content_70 = {
    Text = "Después, ella también arrancó las alas de Pollux. Ahora, solo yo conservo estas alas de la Profanación."
  },
  AvgDialog_145521_Content_71 = {
    Text = "Castor acariciaba suavemente las plumas en la punta de sus alas, y por un instante te pareció ver en ellas manchas de sangre."
  },
  AvgDialog_145521_Content_72 = {
    Text = "Así que, hablar de inocencia… estas alas quizás sean lo más alejado de la inocencia que existe."
  },
  AvgDialog_145521_Content_73 = {
    Text = "El aire se quedó en silencio, solo se escuchaba el crepitar de la hoguera al Quemar."
  },
  AvgDialog_145521_Content_74 = {
    Text = "Naraka, ¿y cuál es tu deseo?"
  },
  AvgDialog_145521_Content_75 = {
    Text = "William se giró de repente hacia Naraka, que estaba calentándose junto al fuego y no parecía tener intención de unirse a la conversación."
  },
  AvgDialog_145521_Content_76 = {
    Text = "Soy solo un guía, no tenía pensado pedir ningún deseo junto a vosotros."
  },
  AvgDialog_145521_Content_77 = {
    Text = "Si hubiera que hablar de <Yellow:el deseo de Naraka>, quizás él esperaría que el nombre de los guías Sherpa también quedara registrado en los anales de los escaladores."
  },
  AvgDialog_145521_Content_78 = {
    Text = "Pero lograr ese deseo mediante un milagro sería demasiado aburrido, ¿no crees?"
  },
  AvgDialog_145521_Content_79 = {
    Text = "Fabricar mentiras a través de la Historia mediante la redacción y falsificación de libros es demasiado sencillo, demasiado fácil, tan fácil que pierde todo valor."
  },
  AvgDialog_145521_Content_8 = {
    Text = "Podéis entrar, el Interior debería ser seguro."
  },
  AvgDialog_145521_Content_80 = {
    Text = "Llegar a la cima es algo que hay que lograr con los propios pies."
  },
  AvgDialog_145521_Content_81 = {
    Text = "Con uno mismo…"
  },
  AvgDialog_145521_Content_82 = {
    Text = "Castor pareció intuir algo."
  },
  AvgDialog_145521_Content_83 = {
    Text = "Eh— no pareces el tipo de persona que dice esas cosas tan sensatas."
  },
  AvgDialog_145521_Content_84 = {
    Text = "Caraboo se tapó la nariz y agitó la mano, Como Si hubiera olido algo desagradable."
  },
  AvgDialog_145521_Content_85 = {
    Text = "Turno de sinceridad, deja de actuar, ¿hablamos con honestidad?"
  },
  AvgDialog_145521_Content_86 = {
    Text = "Ella miraba con picardía los Ojos de Naraka; Naraka intentaba Evadir La Mirada, pero Ella se agachaba, siguiéndola sin soltarla."
  },
  AvgDialog_145521_Content_87 = {
    Text = "<Shake:¡Vamos, muéstrame tu verdadero rostro!>"
  },
  AvgDialog_145521_Content_88 = {
    Text = "Caraboo se abalanzó hacia adelante intentando atrapar a Naraka como un águila a su presa, pero Naraka Solo se echó ligeramente a un lado y la esquivó."
  },
  AvgDialog_145521_Content_89 = {
    Text = "Deja de hacer el tonto, mañana hay que seguir el Camino. No quiero que no lleguen a la cima."
  },
  AvgDialog_145521_Content_9 = {
    Text = "En la pared rocosa quedaban restos de un motivo descolorido, como el contorno de algún símbolo cuya pintura se había desprendido hasta hacerse irreconocible."
  },
  AvgDialog_145521_Content_90 = {
    Text = "Caraboo falló el salto y aprovechó para sentarse directamente en la Nieve, sonriendo de oreja a oreja."
  },
  AvgDialog_145521_Content_91 = {
    Text = "Ya que tú también quieres que lleguemos a la cima, me quedo tranquila."
  },
  AvgDialog_145521_Content_92 = {Text = "..."},
  AvgDialog_145521_Content_93 = {
    Text = "La hoguera arde hasta bien entrada la noche, reduciéndose a brasas dispersas de luz roja."
  },
  AvgDialog_145521_Content_94 = {
    Text = "Naraka repartió los turnos de guardia nocturna, dos horas por persona.\nLos demás fueron quedándose dormidos uno a uno. Desde los sacos de dormir llegaban suaves y contenidos ronquidos."
  },
  AvgDialog_145521_Content_95 = {
    Text = "Castor tomó naturalmente el primer turno. Apoyado contra la pared de la cueva, sacó del fondo de Las Mochilas un pequeño libro con las esquinas desgastadas y blanquecinas."
  },
  AvgDialog_145521_Content_96 = {
    Text = "Era un Libro de Cuentos."
  },
  AvgDialog_145521_Content_97 = {
    Text = "Sus yemas de los dedos recorrieron los dos nombres en la página de presentación."
  },
  AvgDialog_145521_Content_98 = {
    Text = "La letra infantil y ordenada era la suya propia; la otra estaba trazada con torpeza en crayón rojo, cuyo color se había ido desvaneciendo con el paso del tiempo."
  },
  AvgDialog_145521_Content_99 = {Text = "Pollux…"},
  AvgDialog_145522_Content_1 = {
    Text = "No Respondas"
  },
  AvgDialog_145522_Content_10 = {
    Text = "Castor caminaba al final del grupo, más silencioso que de costumbre."
  },
  AvgDialog_145522_Content_11 = {
    Text = "Oye, tonto. ¿Tienes mucho frío?"
  },
  AvgDialog_145522_Content_12 = {
    Text = "Estoy bien."
  },
  AvgDialog_145522_Content_13 = {
    Text = "Igual aquí. Qué extraño."
  },
  AvgDialog_145522_Content_14 = {
    Text = "Entonces, ¿de quién proviene esa respiración tan pesada y agitada?"
  },
  AvgDialog_145522_Content_15 = {
    Text = "El grupo se detuvo. Todos se giraron al mismo tiempo. Detrás de ellos solo estaban las huellas que ellos mismos habían dejado, unas más profundas que otras."
  },
  AvgDialog_145522_Content_16 = {
    Text = "En los bordes de las huellas, la Nieve estaba limpia. Tan limpia como si algo la hubiera borrado suavemente."
  },
  AvgDialog_145522_Content_17 = {
    Text = "Silencio. Solo el Viento. El Viento soplaba desde muy lejos, rodeaba la cresta de la montaña y se colaba por el cuello de cada persona."
  },
  AvgDialog_145522_Content_18 = {
    Text = "En el Viento se escuchaba un sonido Casi imperceptible. No era un canto. Era un Llamar."
  },
  AvgDialog_145522_Content_19 = {
    Text = "<Change>...Eve...lyn..."
  },
  AvgDialog_145522_Content_2 = {
    Text = "La ventisca amainó, pero el cielo tenía un aspecto aún más sombrío que cuando la tormenta arreciaba."
  },
  AvgDialog_145522_Content_20 = {Text = "¿?!"},
  AvgDialog_145522_Content_21 = {
    Text = "Ella se giró bruscamente. El Campo de Nieve estaba vacío, no había nada. Pero aquella voz volvió, esta vez más cerca, con una ternura casi cruel."
  },
  AvgDialog_145522_Content_22 = {
    Text = "<Change>...Evelyn... Tengo frío..."
  },
  AvgDialog_145522_Content_23 = {Text = "Eso es..."},
  AvgDialog_145522_Content_24 = {
    Text = "<Shake:Imposible…>"
  },
  AvgDialog_145522_Content_25 = {
    Text = "El Rostro de Ella perdió el color al instante. Sus labios estaban pálidos, su voz temblaba, como si el momento que había imaginado más de una vez hubiera llegado por fin."
  },
  AvgDialog_145522_Content_26 = {
    Text = "¿Vosotros… vosotros también lo habéis escuchado?!"
  },
  AvgDialog_145522_Content_27 = {Text = "Es él."},
  AvgDialog_145522_Content_28 = {
    Text = "<Shake:Es su voz…>"
  },
  AvgDialog_145522_Content_29 = {
    Text = "Señorita Evelyn, sin importar a quién escuches, no le respondas."
  },
  AvgDialog_145522_Content_3 = {
    Text = "Las nubes de color gris plomo se cernían pesadamente sobre la cresta de la montaña, como una capa de viejo Sueño que pesaba demasiado para disiparse."
  },
  AvgDialog_145522_Content_30 = {
    Text = "Contienen la respiración. El Viento del Campo de Nieve roza sus oídos, y entonces— \nTodos ustedes también lo escuchan."
  },
  AvgDialog_145522_Content_31 = {
    Text = "El Viento se convierte en innumerables voces, innumerables Llamadas entrelazadas. Cada una llega desde una dirección que alguna vez te resultó familiar y que alguna vez perdiste."
  },
  AvgDialog_145522_Content_32 = {
    Text = "Una voz. Una voz que te Llama. Fría y cristalina."
  },
  AvgDialog_145522_Content_33 = {
    Text = "<Change>Te estoy esperando, compañero..."
  },
  AvgDialog_145522_Content_34 = {
    Text = "<Change>No te quedes atrás. Llegaremos juntos al final de esto."
  },
  AvgDialog_145522_Content_35 = {Text = "Ramona..."},
  AvgDialog_145522_Content_36 = {
    Text = "Aprietas los dientes y te Contador el deseo de seguir esa voz."
  },
  AvgDialog_145522_Content_37 = {
    Text = "Tus pies parecen congelados en la nieve, sin obedecerte. Puedes sentir una fuerza sumamente leve y suave que, desde la dirección de la voz, lenta, lentamente, arrastra tu centro de gravedad hacia adelante."
  },
  AvgDialog_145522_Content_38 = {
    Text = "Es una Invitación. Una Invitación imposible de rechazar."
  },
  AvgDialog_145522_Content_39 = {
    Text = "Siempre Que estés dispuesto a dar un paso adelante, podrás regresar a cualquier momento cálido del pasado—"
  },
  AvgDialog_145522_Content_4 = {
    Text = "Nadie hablaba. Los perros guía iban a la cabeza, y hasta ellos habían sofocado ese leve gemido habitual que llevaban en la garganta."
  },
  AvgDialog_145522_Content_40 = {
    Text = "Guardián—"
  },
  AvgDialog_145522_Content_41 = {
    Text = "La voz de William llega desde un lugar muy lejano. Solo entonces te das cuenta de que, sin saber cuándo, ya habías dado medio paso."
  },
  AvgDialog_145522_Content_42 = {
    Text = "Un par de perros guía yacen muertos en el suelo junto a ti, con las gargantas brutalmente desgarradas, y sangre carmesí salpicada en manchas llamativas y crudas sobre la nieve inmaculada."
  },
  AvgDialog_145522_Content_43 = {Text = "Retrocede."},
  AvgDialog_145522_Content_44 = {
    Text = "Dame tu mano."
  },
  AvgDialog_145522_Content_45 = {
    Text = "El rostro de William está pálido como el papel; la mano con la que te sujeta el brazo tiembla sin que él lo note."
  },
  AvgDialog_145522_Content_46 = {
    Text = "Puedes sentir que se esfuerza por contenerse, por no dejarse seducir por aquella voz."
  },
  AvgDialog_145522_Content_47 = {
    Text = "Esa voz es falsa. Tienen que despertar."
  },
  AvgDialog_145522_Content_48 = {
    Text = "Lo dice en un tono muy bajo, como si estuviera pronunciando un Juicio."
  },
  AvgDialog_145522_Content_49 = {
    Text = "<Shake:<Small:Uu… Tía Rosa…>>"
  },
  AvgDialog_145522_Content_5 = {
    Text = "Camina más despacio, el terreno no está bien."
  },
  AvgDialog_145522_Content_50 = {
    Text = "Caraboo despertó como de un sueño, aún murmurando algo entre dientes."
  },
  AvgDialog_145522_Content_51 = {
    Text = "Pero no todos logran despertar."
  },
  AvgDialog_145522_Content_52 = {
    Text = "¡Pollux…! ¡Pollux…! ¿Dónde estás?!"
  },
  AvgDialog_145522_Content_53 = {
    Text = "<Shake:<Big:¡Pollux…!!!>>"
  },
  AvgDialog_145522_Content_54 = {
    Text = "<Italic:…Hermano, tengo frío…>"
  },
  AvgDialog_145522_Content_55 = {
    Text = "<Italic:Hermano, la celda está muy oscura, tengo mucho miedo… te lo suplico… déjame salir… Su Santidad, ella…>"
  },
  AvgDialog_145522_Content_56 = {
    Text = "<Shake:<Italic:…Hermano, ¿por qué no vienes a buscarme…?>>"
  },
  AvgDialog_145522_Content_57 = {
    Text = "¡Pollux!! ¡Espérame, ya voy—!"
  },
  AvgDialog_145522_Content_58 = {
    Text = "<Shake:Oye, idiota, ¡detente!>"
  },
  AvgDialog_145522_Content_59 = {
    Text = "Sin hacer caso a vuestros llamados, Castor salió disparado."
  },
  AvgDialog_145522_Content_6 = {
    Text = "Este tramo antes era una pendiente recta, ahora se han abierto grietas transversales."
  },
  AvgDialog_145522_Content_60 = {
    Text = "<Shake:¡Agarradlo!>"
  },
  AvgDialog_145522_Content_61 = {
    Text = "¡No dejéis que ese idiota se deje engañar!"
  },
  AvgDialog_145522_Content_7 = {
    Text = "Son nuevas fisuras formadas tras el último alud… no deberían ser tan profundas."
  },
  AvgDialog_145522_Content_8 = {
    Text = "La forma de la montaña está cambiando."
  },
  AvgDialog_145522_Content_9 = {
    Text = "William no continuó hablando. Sus ojos verdes miraban a lo lejos, con el ceño levemente fruncido."
  },
  AvgDialog_145523_Content_1 = {
    Text = "La Cima sin Deseos"
  },
  AvgDialog_145523_Content_10 = {
    Text = "William se agacha lentamente, con las yemas de los dedos rozando los intrincados grabados entre los pedestales, los que habías tomado por mera decoración."
  },
  AvgDialog_145523_Content_100 = {
    Text = "<Shake:¡Detente! ¡Apágalo! <Red:¡Me pudriré antes de que el deseo sea concedido!>>"
  },
  AvgDialog_145523_Content_101 = {
    Text = "Eso nunca formó parte de nuestro trato."
  },
  AvgDialog_145523_Content_102 = {
    Text = "Sí, él solo prometió iniciar el ritual por ti. Nunca prometió que sobrevivirías."
  },
  AvgDialog_145523_Content_103 = {
    Text = "Entiendo… Cada palabra que dijo William era la pura verdad… pero entrelazadas, formaron una mentira perfecta."
  },
  AvgDialog_145523_Content_104 = {
    Text = "El sexto halo se eleva."
  },
  AvgDialog_145523_Content_105 = {
    Text = "La montaña entera se estremece como algo que agoniza. Innumerables masas pálidas de carne emergen bajo las rocas que se agrietan y se lanzan hacia el altar como una ola."
  },
  AvgDialog_145523_Content_106 = {
    Text = "¡No! ¡Eso es mío! ¡Mi Carne y sangre! ¡Mi Fortaleza! ¡Mis deseos!"
  },
  AvgDialog_145523_Content_107 = {
    Text = "O quizás nunca te pertenecieron. Ese poder no te corresponde. Son los deseos robados de los innumerables peregrinos que atrajiste y enterraste aquí."
  },
  AvgDialog_145523_Content_108 = {
    Text = "Ese poder pertenece a todos aquellos a quienes has engañado, devorado y desechado. No tienes ningún derecho a reclamarlo..."
  },
  AvgDialog_145523_Content_109 = {
    Text = "...Y ahora, simplemente están regresando a donde pertenecen."
  },
  AvgDialog_145523_Content_11 = {
    Text = "Imposible... cómo puede estar esto aquí... Estas marcas junto a los grabados del altar... las reconozco."
  },
  AvgDialog_145523_Content_110 = {
    Text = "Tinct, Castor, Evelyn y Fengol, a quien nunca llegaste a conocer en persona..."
  },
  AvgDialog_145523_Content_111 = {
    Text = "Cara tras cara, nombre tras nombre emergen a la superficie de tu mente, antes de hundirse en la quieta oscuridad de los recuerdos."
  },
  AvgDialog_145523_Content_112 = {
    Text = "<BigShake:¡No te atrevas! ¡NO TE ATREVAS!>"
  },
  AvgDialog_145523_Content_113 = {
    Text = "<Big:<Red:¡Primero destruiré el altar, luego los masticaré a todos hasta hacerlos pedazos!>"
  },
  AvgDialog_145523_Content_114 = {
    Text = "William te hace un gesto con la cabeza."
  },
  AvgDialog_145523_Content_115 = {
    Text = "Cada uno haga su parte. Yo mantendré el ritual en marcha."
  },
  AvgDialog_145523_Content_116 = {
    Text = "Déjamelo a mí. ¡Yo detendré al gusano!"
  },
  AvgDialog_145523_Content_12 = {
    Text = "Esto es obra de Fengol."
  },
  AvgDialog_145523_Content_13 = {Text = "¿Fengol?"},
  AvgDialog_145523_Content_14 = {
    Text = "Conoces ese nombre. El compañero de William, el Investigador que desapareció de \"ese mundo\" antes que él."
  },
  AvgDialog_145523_Content_15 = {
    Text = "Así que es eso… la Llave de Salomón… la razón por la que el gusano no puede iniciar el ritual… y el propósito por el que Fengol vino a este mundo…"
  },
  AvgDialog_145523_Content_16 = {
    Text = "Jajaja... ¡Ya veo! ¡Ahora lo entiendo! ¡Esto es de lo más gracioso!"
  },
  AvgDialog_145523_Content_17 = {
    Text = "Así que esto es lo que ese tejedor adicto al trabajo pretendía mostrarme. ¡Bien valió la pena traerlos a todos hasta aquí arriba!"
  },
  AvgDialog_145523_Content_18 = {
    Text = "¿Qué quieres decir?"
  },
  AvgDialog_145523_Content_19 = {
    Text = "N simplemente se encoge de hombros."
  },
  AvgDialog_145523_Content_2 = {
    Text = "Era un altar enorme, Como Si tuviera la misma edad que toda la cordillera."
  },
  AvgDialog_145523_Content_20 = {
    Text = "Vaya, yo no soy tu traductor. ¿Ves a este señor William aquí? Pregúntale a él. Sí me dejaste salir de tus entrañas, pero ¿acaso parezco alguien que tenga intención de devolver el \"favor\"?"
  },
  AvgDialog_145523_Content_21 = {
    Text = "Yo me encargo de explicarlo."
  },
  AvgDialog_145523_Content_22 = {
    Text = "\"La Llave de Salomón\" no es en realidad una llave, sino un grimorio."
  },
  AvgDialog_145523_Content_23 = {
    Text = "Y el contenido más crucial registrado en el grimorio es el método para convocar a los setenta y dos demonios de Salomón. En otras palabras, el método para conectar mundos."
  },
  AvgDialog_145523_Content_24 = {
    Text = "Levantó la cabeza y miró hacia el centro exacto de los siete pedestales — una cerradura estrecha que Casi se fundía con las sombras."
  },
  AvgDialog_145523_Content_25 = {
    Text = "Estas marcas son un código secreto que Solo él y yo podemos descifrar."
  },
  AvgDialog_145523_Content_26 = {
    Text = "William se arrodilla ante el círculo mágico, con la mano trazando cuidadosamente los grabados en el suelo. Poco a poco, las palabras silenciosas comienzan a cobrar sentido en su mente, formando una voz familiar."
  },
  AvgDialog_145523_Content_27 = {
    Text = "¿Es William? Sabía que llegarías hasta aquí.\n\nEl círculo mágico de aquí contiene tres escrituras antiguas distintas. Me atrevería a apostar que, entre los nuestros, solo tú, el estudiante diligente, podrías leerlas todas de una sola vez.\nSon hechizos de invocación y sellado. Deberías entender lo que eso significa."
  },
  AvgDialog_145523_Content_28 = {
    Text = "Controla la apertura y el cierre de cierta \"Puerta.\""
  },
  AvgDialog_145523_Content_29 = {
    Text = "#N/AEn resumen, este círculo mágico usa la \"Corona\" como medio, conectándose con el origen de este mundo. Por lo tanto, solo dentro de este mundo, puede conceder cualquier deseo.\n\nSeguramente te habrás preguntado por qué fuiste arrojado a este mundo desconocido, ¿verdad?\n\nAhora puedo darte la respuesta.\n\nTú eres ese deseo... mi deseo."
  },
  AvgDialog_145523_Content_3 = {
    Text = "Escalones de piedra circulares ascendían en capas, y al final se erguían siete pedestales vacíos dispuestos en círculo. Entre pedestal y pedestal, en unas ranuras antiguas, se había coagulado una luz dorada oscura, ya completamente seca."
  },
  AvgDialog_145523_Content_30 = {
    Text = "Lamentablemente, el poder que ofrecí no fue suficiente. Solo pude abrir una grieta para que tu Núcleo de plata pudiera pasar.\n\nEl destino al que yo no pude llegar... tú debes alcanzarlo en mi lugar.\n\nAl fin y al cabo, eres el legendario Investigador William, ¿no es así?"
  },
  AvgDialog_145523_Content_31 = {
    Text = "Espero que aún conserves mi Llave de Plata.\n\nÚsala para activar el círculo mágico, luego pide tu deseo, y Él te guiará a la tierra prometida.\n\nEl camino que queda por delante—eso te lo dejo a ti.\n\nAtentamente,\nFengol"
  },
  AvgDialog_145523_Content_32 = {
    Text = "Los dedos de William se detuvieron."
  },
  AvgDialog_145523_Content_33 = {
    Text = "No dice ni una palabra. Nunca habías visto esa expresión en su rostro."
  },
  AvgDialog_145523_Content_34 = {Text = "%player%."},
  AvgDialog_145523_Content_35 = {
    Text = "Estoy aquí."
  },
  AvgDialog_145523_Content_36 = {
    Text = "¿No me preguntaste en aquel entonces por qué fui la primera persona en despertar bajo el Llamar del Wendigo?"
  },
  AvgDialog_145523_Content_37 = {
    Text = "Porque soy el único entre nosotros que ha visto sus huesos."
  },
  AvgDialog_145523_Content_38 = {
    Text = "Su cuerpo estaba completamente podrido, era imposible identificarlo. Pero reconocí la mitad de la Llave de plata que llevaba consigo."
  },
  AvgDialog_145523_Content_39 = {
    Text = "Número I-1021, el número perteneciente a Fengol. Cada vez que un número desaparece de los Registros, sabemos que otro predecesor ha sido olvidado por el mundo."
  },
  AvgDialog_145523_Content_4 = {
    Text = "Este es el destino al que el Gusano de la Montaña atraía a incontables alpinistas, usando los deseos como cebo."
  },
  AvgDialog_145523_Content_40 = {
    Text = "Desde entonces, siempre he llevado esta Llave de plata junto a mí."
  },
  AvgDialog_145523_Content_41 = {
    Text = "Cerró los ojos. Cuando los volvió a abrir, en aquellos ojos de color verde azulado solo quedaba algo sereno e inquebrantable."
  },
  AvgDialog_145523_Content_42 = {
    Text = "…Fengol, gracias por la confianza que me has dado."
  },
  AvgDialog_145523_Content_43 = {
    Text = "Gusano de la Montaña, te diré cómo activar el ritual."
  },
  AvgDialog_145523_Content_44 = {
    Text = "Quienes ofrecen sus deseos a la montaña entregan sus propias almas para alimentar el círculo mágico. A través de ellos, se construye un puente hacia el Origen del mundo."
  },
  AvgDialog_145523_Content_45 = {
    Text = "¿El Origen del mundo?"
  },
  AvgDialog_145523_Content_46 = {
    Text = "Si mi hipótesis es correcta, es el Sol Negro que cuelga en el cielo."
  },
  AvgDialog_145523_Content_47 = {
    Text = "El Sol Negro existe de manera muy similar al \"Black Pool\" de Misaq: todo lo abarca, una suspensión de las ruinas de todo pasado y futuro, ahogándose en una marea corrosiva."
  },
  AvgDialog_145523_Content_48 = {
    Text = "La magnitud del deseo concedido depende enteramente de cuánto de esa marea se atreva a extraer el que desea del Sol Negro."
  },
  AvgDialog_145523_Content_49 = {
    Text = "Niña, no le quites los ojos de encima. Asegúrate de que no esté tejiendo mentiras."
  },
  AvgDialog_145523_Content_5 = {
    Text = "Nadie ha salido jamás de este lugar con vida. Todos los escaladores del pasado... están todos aquí. Bajo nuestros pies. En las entrañas de la montaña."
  },
  AvgDialog_145523_Content_50 = {
    Text = "A regañadientes, Caraboo da un paso al frente y clava la mirada en los ojos de William."
  },
  AvgDialog_145523_Content_51 = {Text = "<Shake:!!>"},
  AvgDialog_145523_Content_52 = {
    Text = "William cierra los ojos y sacude la cabeza suavemente."
  },
  AvgDialog_145523_Content_53 = {
    Text = "Cada palabra que acaba de decir es verdad."
  },
  AvgDialog_145523_Content_54 = {
    Text = "<Shake:¡No me mientas! Dudaste hace un momento, ¡pequeño farsante!>"
  },
  AvgDialog_145523_Content_55 = {
    Text = "¿Estoy mintiendo? Tú deberías saberlo mejor que yo."
  },
  AvgDialog_145523_Content_56 = {
    Text = "El Gusano suelta una carcajada fría y burlona, haciendo que una avalancha de nieve retumbe por los acantilados."
  },
  AvgDialog_145523_Content_57 = {
    Text = "Hmph. El ritual es lo único que importa. Una vez que esto termine, me ocuparé de ti personalmente, traidor."
  },
  AvgDialog_145523_Content_58 = {
    Text = "Dime entonces, Gusano de la Montaña, ¿cuál es la magnitud del deseo que anhelas?"
  },
  AvgDialog_145523_Content_59 = {
    Text = "Jajaja... ¿acaso necesitas preguntarlo? ¡Cuanto más grandioso, mejor! ¡Quiero engullir el mundo entero en mi vientre, un festín interminable e inagotable!"
  },
  AvgDialog_145523_Content_6 = {
    Text = "Basta de charla. Dime cómo funciona este círculo mágico."
  },
  AvgDialog_145523_Content_60 = {
    Text = "Qué criatura codiciosa y necia. Quizás deberías haber aprendido la belleza de la moderación."
  },
  AvgDialog_145523_Content_61 = {
    Text = "¿Cómo podría entenderlo un parásito del Caos como tú? Si hubiera seguido las reglas, jamás habría alcanzado estas alturas."
  },
  AvgDialog_145523_Content_62 = {
    Text = "¿Y por \"alturas\" te refieres a arrastrar tu cuerpo hinchado y retorcido por una cima helada?"
  },
  AvgDialog_145523_Content_63 = {
    Text = "Ugh... olvídalo. De todas formas, nadie escucha jamás mis excelentes consejos."
  },
  AvgDialog_145523_Content_64 = {
    Text = "¡Entendido!"
  },
  AvgDialog_145523_Content_65 = {
    Text = "William asintió."
  },
  AvgDialog_145523_Content_66 = {
    Text = "Para exigir un deseo de la mayor magnitud, debes entregar cada una de las ofrendas."
  },
  AvgDialog_145523_Content_67 = {
    Text = "<BigShake:¡Tómalos! ¡Tómalos todos! ¡Existen precisamente para este momento!>"
  },
  AvgDialog_145523_Content_68 = {
    Text = "%player%, dame la Ofrenda."
  },
  AvgDialog_145523_Content_69 = {
    Text = "Abres el maletín."
  },
  AvgDialog_145523_Content_7 = {
    Text = "La voz del gusano de la montaña llegó desde abajo. Esta vez, su tono ya no contenía solo burla, sino también una urgencia reprimida durante largos años."
  },
  AvgDialog_145523_Content_70 = {
    Text = "la Manzana Dorada, el Espejo de Yata, la Pluma de Ma'at, el Ojo de Balor, el hilo de la diosa del destino, la Corona de Ariadna… y la propia Llave de Plata."
  },
  AvgDialog_145523_Content_71 = {
    Text = "Las siete ofrendas encuentran su lugar en los pedestales, y a través de los surcos ancestrales, una luz dorada oscura fluye y surge de nuevo, uniéndose en un anillo completo."
  },
  AvgDialog_145523_Content_72 = {
    Text = "<Shake:Jaja... Por fin... ¡POR FIN!>"
  },
  AvgDialog_145523_Content_73 = {
    Text = "La Montaña tendrá Su festín. La Montaña gastará todo Su tesoro acumulado."
  },
  AvgDialog_145523_Content_74 = {
    Text = "La Montaña ha padecido hambre de esto durante tanto, tanto tiempo."
  },
  AvgDialog_145523_Content_75 = {
    Text = "William sostuvo aquella llave única en su mano e introdujo en la cerradura."
  },
  AvgDialog_145523_Content_76 = {
    Text = "En nombre de Fengol—"
  },
  AvgDialog_145523_Content_77 = {
    Text = "<Red:Inicio este ritual.>"
  },
  AvgDialog_145523_Content_78 = {Text = "Clic."},
  AvgDialog_145523_Content_79 = {
    Text = "Con un sonido suave y agudo, las siete ofrendas estallan en una luz cegadora."
  },
  AvgDialog_145523_Content_8 = {
    Text = "Todas las miradas se dirigen hacia el altar, atraídas por la densa y misteriosa escritura que cubre su superficie."
  },
  AvgDialog_145523_Content_80 = {
    Text = "El primer anillo de luz se eleva sobre el altar. Luego el segundo, y el tercero. Los deseos que dormitan en los siete artefactos resuenan en armonía, como siete ríos que se precipitan hacia un único y oscuro mar."
  },
  AvgDialog_145523_Content_81 = {
    Text = "Si la Montaña tuviera manos, arañaría el cielo para aferrar ese brillante anillo, consumida por un hambre desesperada."
  },
  AvgDialog_145523_Content_82 = {
    Text = "<Shake:¡Este día ha llegado por fin!>"
  },
  AvgDialog_145523_Content_83 = {
    Text = "Arrancaría el anillo de los cielos y lo presionaría con fuerza contra Su pecho, hundiéndolo en Su carne hinchada hasta devorar hasta la última gota de su poder."
  },
  AvgDialog_145523_Content_84 = {
    Text = "Miras fijamente el cielo convulso. Cuando el deseo de la Montaña sea concedido, ¿qué será de vuestras vidas? ¿Acaso vuestro viaje terminará simplemente en este páramo helado?"
  },
  AvgDialog_145523_Content_85 = {
    Text = "En ese instante fugaz, ves el destello del monóculo de William."
  },
  AvgDialog_145523_Content_86 = {
    Text = "Inmediatamente después, el cuarto anillo de luz se enciende."
  },
  AvgDialog_145523_Content_87 = {
    Text = "La roca sólida bajo tus pies gime con un retumbo grave y pesado, un estremecimiento que no pertenece a la piedra, sino a la carne viva. Débiles y enfermizos destellos de luz comienzan a sangrar desde las capas resquebrajadas de hielo que hay abajo."
  },
  AvgDialog_145523_Content_88 = {
    Text = "<Shake:...¿Qué es esto?>"
  },
  AvgDialog_145523_Content_89 = {
    Text = "<Shake:¿Por qué... mis fuerzas... se desvanecen?>"
  },
  AvgDialog_145523_Content_9 = {
    Text = "Espera… estos trazos…"
  },
  AvgDialog_145523_Content_90 = {
    Text = "Este es el precio del ritual que tanto anhelabas."
  },
  AvgDialog_145523_Content_91 = {
    Text = "Tras pagar el precio, ¿qué será de ello?"
  },
  AvgDialog_145523_Content_92 = {
    Text = "El ritual extraerá \"toda\" la Fortaleza de la Ofrenda, así que supongo que volverá a ser como era antes de conocerte, o incluso más débil."
  },
  AvgDialog_145523_Content_93 = {
    Text = "¿Así que... tan débil como para ser un pequeño y miserable gusano retorciéndose dentro de una manzana podrida? ¿Uno que podríamos aplastar con un simple pellizco?"
  },
  AvgDialog_145523_Content_94 = {
    Text = "<BigShake:¡Me engañaste! ¡Miserable mentiroso!>"
  },
  AvgDialog_145523_Content_95 = {
    Text = "Te prometí que iniciaría el ritual por completo, y tú aceptaste entregar <Italic:todas> las ofrendas."
  },
  AvgDialog_145523_Content_96 = {
    Text = "Todo lo que has devorado, la fuerza vital entera de esta montaña, será ofrecida al altar... sacrificada al dios que talló esta formación."
  },
  AvgDialog_145523_Content_97 = {
    Text = "El quinto halo se eleva."
  },
  AvgDialog_145523_Content_98 = {
    Text = "Las rocas bajo los pies comenzaron a agrietarse y desprenderse, dejando al descubierto la capa inferior: húmeda, pálida, carne que se contraía violentamente."
  },
  AvgDialog_145523_Content_99 = {
    Text = "Enormes placas de nieve se desploman con un estruendo ensordecedor, y el cielo es engullido, pedazo a pedazo, por una sombra inimaginable."
  },
  AvgDialog_145524_Content_1 = {
    Text = "¡Tú… no te acerques!"
  },
  AvgDialog_145524_Content_10 = {
    Text = "<Change>¿Recuerdas cuál es tu misión?"
  },
  AvgDialog_145524_Content_11 = {
    Text = "<Small:Eliminar... al traidor... debo...>"
  },
  AvgDialog_145524_Content_12 = {
    Text = "El Caos en los ojos de Pollux fue desvaneciéndose poco a poco, reemplazado por una especie de vacío, un vacío que solo podía ser impulsado por las Voces en tu cabeza."
  },
  AvgDialog_145524_Content_13 = {
    Text = "Sí, es cierto, soy un traidor. Soy quien te traicionó y huyó."
  },
  AvgDialog_145524_Content_14 = {
    Text = "Pero ahora, no volveré a irme."
  },
  AvgDialog_145524_Content_15 = {
    Text = "<Shake:Traidor, Castor...>"
  },
  AvgDialog_145524_Content_16 = {
    Text = "Estaba confundido, quería resistir algo, aferrarse a algo, pero las voces en su cabeza no dejaban de luchar."
  },
  AvgDialog_145524_Content_17 = {
    Text = "Pollux, nos has seguido todo el tiempo, seguro que tú también te encontraste con el Wendigo."
  },
  AvgDialog_145524_Content_18 = {
    Text = "En la Ilusión del Wendigo, ¿qué escuchaste?"
  },
  AvgDialog_145524_Content_19 = {
    Text = "Las pupilas de Pollux se dilataron de repente y luego se fueron disipando poco a poco. Cayó en una meditación parecida a los Susurros."
  },
  AvgDialog_145524_Content_2 = {
    Text = "Pollux abrió los Ojos de par en par. No comprendía lo que pensaba el fanático que tenía ante él."
  },
  AvgDialog_145524_Content_20 = {
    Text = "Escuché... que alguien me Llamaba..."
  },
  AvgDialog_145524_Content_21 = {
    Text = "Decía que podríamos convertirnos en caballeros extraordinarios."
  },
  AvgDialog_145524_Content_22 = {
    Text = "Montábamos a caballo, cruzábamos grandes montañas, cruzábamos ríos y mares, y matábamos dragones..."
  },
  AvgDialog_145524_Content_23 = {
    Text = "Y luego, luego, al final del sueño…"
  },
  AvgDialog_145524_Content_24 = {Text = "..."},
  AvgDialog_145524_Content_25 = {
    Text = "<BigShake:No, no…!>"
  },
  AvgDialog_145524_Content_26 = {
    Text = "Es muy doloroso, Juliette, <Shake:¡Ayúdame, ayúdame…>"
  },
  AvgDialog_145524_Content_27 = {
    Text = "<Shake:Soy… el noble… el único… Hijo Santo… ¡Ayúdame…<Small:No puedo…>>"
  },
  AvgDialog_145524_Content_28 = {
    Text = "No importa… No tienes que recordarlo."
  },
  AvgDialog_145524_Content_29 = {
    Text = "El sufrimiento insoportable, déjame cargarlo a mí. Como cuando éramos pequeños."
  },
  AvgDialog_145524_Content_3 = {
    Text = "En el rostro de Castor no había reverencia por los dogmas, ni miedo a la hostilidad."
  },
  AvgDialog_145524_Content_30 = {
    Text = "Al fin y al cabo, soy el hermano mayor."
  },
  AvgDialog_145524_Content_31 = {
    Text = "Castor abrazó a Pollux, calmándolo con una voz suave como la de quien arrulla a un niño."
  },
  AvgDialog_145524_Content_32 = {
    Text = "La respiración de Pollux se fue apaciguando, con el rostro apoyado en el hombro de Castor, sus párpados descendiendo poco a poco."
  },
  AvgDialog_145524_Content_33 = {
    Text = "<Shake:Castor…>"
  },
  AvgDialog_145524_Content_34 = {
    Text = "Soy yo, soy, Castor…"
  },
  AvgDialog_145524_Content_35 = {
    Text = "<Shake:Castor, Castor…>"
  },
  AvgDialog_145524_Content_36 = {
    Text = "<Shake:<Small:...¿Hermano?>>"
  },
  AvgDialog_145524_Content_37 = {
    Text = "Sus pupilas dispersas se aclararon de repente, y la voz de Pollux era tan leve que Casi la dispersaba el viento, pero aun así llegó sin desviarse a los oídos de Castor."
  },
  AvgDialog_145524_Content_38 = {
    Text = "El llamar que había trazado incontables veces en su imaginación resonó por fin de nuevo junto a su oído."
  },
  AvgDialog_145524_Content_39 = {Text = "Ah—"},
  AvgDialog_145524_Content_4 = {
    Text = "Justo avanzó, cruzando más allá de ese cuchillo, más allá de todos los obstáculos que deberían haber existido pero ya no existían."
  },
  AvgDialog_145524_Content_40 = {
    Text = "Quería llorar, quería gritar, quería rugir."
  },
  AvgDialog_145524_Content_41 = {
    Text = "Aunque en ese momento solo lo rodeaba el vasto e interminable Campo de Nieve, quería proclamarlo al mundo entero sin ningún sentido: su hermano menor había vuelto."
  },
  AvgDialog_145524_Content_42 = {
    Text = "Pero no dijo nada, como siempre, como cuando Pollux se burlaba de él diciéndole que era un palo, y Caraboo se burlaba de él llamándolo tonto."
  },
  AvgDialog_145524_Content_43 = {
    Text = "<Shake:Pollux...>"
  },
  AvgDialog_145524_Content_44 = {
    Text = "—En ese preciso instante, en lo alto de la montaña nevada —en algún lugar aún más alto, cuya cima no podía verse—"
  },
  AvgDialog_145524_Content_45 = {
    Text = "La Mirada de un Juicio descendió sobre ellos."
  },
  AvgDialog_145524_Content_46 = {
    Text = "<Change>Producto defectuoso."
  },
  AvgDialog_145524_Content_47 = {
    Text = "Castor aferró a su hermano con fuerza—"
  },
  AvgDialog_145524_Content_48 = {
    Text = "Pero no sirvió de nada. La luz brotó desde el pecho de Pollux."
  },
  AvgDialog_145524_Content_49 = {
    Text = "La luz atravesó de lleno el pecho de ambos, traspasó la vieja capa de Castor, traspasó las Alas con que Castor los envolvía—"
  },
  AvgDialog_145524_Content_5 = {
    Text = "Estrechó a Pollux en un abrazo apretado."
  },
  AvgDialog_145524_Content_50 = {
    Text = "Como cadenas de blancura pura, los ataron firmemente el uno al otro, sellando el juramento de nunca más Separación."
  },
  AvgDialog_145524_Content_51 = {
    Text = "Hermano… lo siento…"
  },
  AvgDialog_145524_Content_52 = {
    Text = "Con esas últimas palabras, Pollux se recostó sobre el hombro de Castor y se sumió en un profundo sueño."
  },
  AvgDialog_145524_Content_53 = {
    Text = "Así… está bien… ya nunca más nos separaremos…"
  },
  AvgDialog_145524_Content_54 = {
    Text = "Esto también es… un pequeño egoísmo mío…"
  },
  AvgDialog_145524_Content_55 = {
    Text = "Dirigió la mirada hacia lo alto de la montaña, imaginando a sus antiguos compañeros de escalada apoyándose mutuamente en el ascenso."
  },
  AvgDialog_145524_Content_56 = {
    Text = "Una Mentira había llegado a su fin; este viaje ya no le pertenecía."
  },
  AvgDialog_145524_Content_57 = {
    Text = "Reemplazar una Mentira con otra Mentira…"
  },
  AvgDialog_145524_Content_58 = {
    Text = "Adiós… a todos… que vuestro viaje… llegue al fin a la tierra prometida…"
  },
  AvgDialog_145524_Content_59 = {
    Text = "Una Pluma negra se desprendió de las Alas de Castor y fue arrastrada hacia lo alto por el Viento de Nieve."
  },
  AvgDialog_145524_Content_6 = {
    Text = "Como cuando estaban juntos en el líquido amniótico."
  },
  AvgDialog_145524_Content_60 = {
    Text = "Que vaya ella en nuestro lugar, hacia esa tierra pura e inocente que tú deseabas…"
  },
  AvgDialog_145524_Content_61 = {
    Text = "Una grieta se abrió bajo los pies de ambos, engullendo lentamente todo el peso en el hielo y la Nieve del vientre de la montaña."
  },
  AvgDialog_145524_Content_62 = {
    Text = "Buenas noches, Pollux."
  },
  AvgDialog_145524_Content_63 = {
    Text = "Habéis escalado por nuevos senderos de montaña y reorganizado el pesado equipo."
  },
  AvgDialog_145524_Content_64 = {
    Text = "Una ráfaga de Viento de Nieve, Como Si tuviera voluntad propia, se arremolinó en lo alto."
  },
  AvgDialog_145524_Content_65 = {Text = "Eso es..."},
  AvgDialog_145524_Content_66 = {
    Text = "Entre el Viento de Nieve, una Pluma de un negro intenso descendía lentamente."
  },
  AvgDialog_145524_Content_67 = {
    Text = "Levantas la mano y ella cae suavemente en tu palma."
  },
  AvgDialog_145524_Content_68 = {
    Text = "Como una Bendición venido de lejos."
  },
  AvgDialog_145524_Content_69 = {
    Text = "Altitud -7000 metros-"
  },
  AvgDialog_145524_Content_7 = {
    Text = "Vuelve, Pollux. Como cuando éramos pequeños."
  },
  AvgDialog_145524_Content_8 = {
    Text = "La mente de Pollux estaba llena de confusión, llena de incomprensión. Pero por alguna razón, no fue capaz de rechazar aquel cálido abrazo."
  },
  AvgDialog_145524_Content_9 = {
    Text = "Una severa reprimenda resonó de repente junto a su oído."
  },
  AvgDialog_145525_Content_1 = {
    Text = "La caverna recuperó una calma extraña, y todos, aún con el susto en el cuerpo, se miraron unos a otros."
  },
  AvgDialog_145525_Content_10 = {
    Text = "Justo que en esta montaña hay alguna presencia distinta a la diosa, que está tramando arrebataros vuestros deseos."
  },
  AvgDialog_145525_Content_11 = {
    Text = "Deja de asustar a todos, Caraboo."
  },
  AvgDialog_145525_Content_12 = {
    Text = "Creedlo o no, como queráis. La diosa de la montaña nevada puede percibirlo, está cerca de nuestro grupo, siguiéndonos de cerca…"
  },
  AvgDialog_145525_Content_13 = {
    Text = "No podéis discernir por su tono si realmente está fingiendo o si verdaderamente ha percibido algo."
  },
  AvgDialog_145525_Content_14 = {
    Text = "La ventisca fue amainando."
  },
  AvgDialog_145525_Content_15 = {
    Text = "En medio de ese peso, volvéis a partir."
  },
  AvgDialog_145525_Content_2 = {
    Text = "Qué raro, he acompañado al equipo de montañismo a esta altitud muchas veces y es la primera vez que me encuentro con algo así…"
  },
  AvgDialog_145525_Content_3 = {
    Text = "Eso demuestra que los peligros de esta montaña nevada no se limitan a los treinta grados bajo cero y la falta de oxígeno por la altitud."
  },
  AvgDialog_145525_Content_4 = {
    Text = "Caraboo bajó la voz y habló lentamente con un tono que helaba la sangre."
  },
  AvgDialog_145525_Content_5 = {
    Text = "La diosa de la montaña nevada existe de verdad."
  },
  AvgDialog_145525_Content_6 = {
    Text = "<Red:La diosa de la montaña no os da la bienvenida. No da la bienvenida a quienes carecen de devoción.>"
  },
  AvgDialog_145525_Content_7 = {
    Text = "El aire se tensó."
  },
  AvgDialog_145525_Content_8 = {
    Text = "¡Era una broma! ¡No se lo habrán creído de verdad!"
  },
  AvgDialog_145525_Content_9 = {
    Text = "Soy la diosa de la montaña nevada más bondadosa que existe; con mis bendiciones, la montaña os recibirá y llegaréis hasta la cima."
  },
  AvgDialog_145526_Content_1 = {
    Text = "Día de Partida"
  },
  AvgDialog_145526_Content_10 = {
    Text = "Justo ahora Solo resistimos un ataque, pero su ofensiva no se detendrá."
  },
  AvgDialog_145526_Content_11 = {
    Text = "En un lugar tan peligroso como las altas montañas, es inevitable que las personas muestren momentos de Frágil y debilidad..."
  },
  AvgDialog_145526_Content_12 = {
    Text = "En esos momentos, es mejor engañarlo."
  },
  AvgDialog_145526_Content_13 = {
    Text = "Caraboo sacó una Manzana de no se sabe dónde, le dio un mordisco con un crujido, y adoptó una expresión despreocupada de \"yo no he dicho eso\"."
  },
  AvgDialog_145526_Content_14 = {
    Text = "...Tampoco estás equivocado en decir eso."
  },
  AvgDialog_145526_Content_15 = {
    Text = "En fin, tenemos que encontrarlo y luego atraparlo."
  },
  AvgDialog_145526_Content_16 = {
    Text = "Pero no dejan rastro al caminar sobre la Nieve, ¿cómo vamos a...?"
  },
  AvgDialog_145526_Content_17 = {
    Text = "Déjenmelo a mí. Soy el mejor lidiando con embusteros, ¿no es así?"
  },
  AvgDialog_145526_Content_18 = {
    Text = "Mira, ya están por llegar."
  },
  AvgDialog_145526_Content_19 = {
    Text = "Caraboo señala al último perro guía que te queda. Se ha agachado, gimiendo suavemente."
  },
  AvgDialog_145526_Content_2 = {Text = "Wendigo."},
  AvgDialog_145526_Content_20 = {
    Text = "No os mováis, y no digáis nada."
  },
  AvgDialog_145526_Content_21 = {
    Text = "Ella te lanzó la manzana de la que había dado un mordisco."
  },
  AvgDialog_145526_Content_22 = {
    Text = "En el corte se escondía un pequeño papel: Pase lo que pase a partir de ahora, no creas nada de lo que diga."
  },
  AvgDialog_145526_Content_23 = {
    Text = "Caraboo se quedó en silencio, cerró los ojos y luego los volvió a abrir."
  },
  AvgDialog_145526_Content_24 = {
    Text = "En ese instante, su mirada cambió. Aturdida, angustiada, perdida, emociones complejas se agolpaban en sus pequeños ojos."
  },
  AvgDialog_145526_Content_25 = {
    Text = "<Shake:Tía Rosa, ¿eres tú?>"
  },
  AvgDialog_145526_Content_26 = {
    Text = "<Shake:¿Está haciendo tarta de Manzana otra vez? Puedo oler el aroma.>"
  },
  AvgDialog_145526_Content_27 = {
    Text = "<Shake:Tía Rosa, nunca más me quejaré de que la masa de la tarta de Manzana es demasiado gruesa. Desde entonces, jamás he vuelto a comer una tarta tan deliciosa. Echo de menos ese aroma tostado.>"
  },
  AvgDialog_145526_Content_28 = {
    Text = "<Shake:Tía Rosa. Ahora voy a buscarte, espérame.>"
  },
  AvgDialog_145526_Content_29 = {
    Text = "Caraboo avanzó tambaleándose."
  },
  AvgDialog_145526_Content_3 = {
    Text = "William recitó las palabras una por una."
  },
  AvgDialog_145526_Content_30 = {
    Text = "Sobre la nieve, a espaldas de Caraboo, surgieron abruptamente dos montículos de nieve de metro y medio de altura."
  },
  AvgDialog_145526_Content_31 = {
    Text = "Se lanza contra Caraboo. En el momento en que salta sobre ella, ella se agacha."
  },
  AvgDialog_145526_Content_32 = {
    Text = "<Big:¡William, prepárate!!>"
  },
  AvgDialog_145526_Content_4 = {
    Text = "<Italic:\"Sus patas están forjadas en fuego — cuando corre, la Nieve arde bajo sus patas.\">"
  },
  AvgDialog_145526_Content_5 = {
    Text = "En el séptimo tomo de \"Crónicas del Norte\" está escrito: <Italic:Quien escuche el Susurro en las noches de invierno, jamás debe responder.>"
  },
  AvgDialog_145526_Content_6 = {
    Text = "<Italic:Responde una vez, y Registrará tu nombre; responde dos veces, y reconocerá tu sombra; responde una tercera vez — y tú serás él.>"
  },
  AvgDialog_145526_Content_7 = {
    Text = "¿No podemos rodearlo?"
  },
  AvgDialog_145526_Content_8 = {
    Text = "Es inútil. Siempre Que el Viento y la Nieve se extiendan, ese territorio es el dominio donde vaga el Wendigo."
  },
  AvgDialog_145526_Content_9 = {
    Text = "Alguna vez fueron personas. Se transformaron al devorar a sus semejantes, y desde entonces sus labios y dientes se pudrieron, condenados al Hambre eterna — ni siquiera devorando un Bosque entero quedarían saciados."
  },
  AvgDialog_145527_Content_1 = {
    Text = "Las Mochilas"
  },
  AvgDialog_145527_Content_10 = {Text = "No."},
  AvgDialog_145527_Content_100 = {
    Text = "Acercó sus propias ramas al brasero para encenderlas y luego se unió a vosotros."
  },
  AvgDialog_145527_Content_101 = {
    Text = "Las llamas se transmitieron de rama en rama, y el Parpadeo del fuego fue iluminando uno a uno cada El Rostro alzado."
  },
  AvgDialog_145527_Content_102 = {
    Text = "En el silencio absoluto, Como Si se pudiera escuchar a lo lejos el grave sonido de cánticos, el tintineo de campanas y el redoble de tambores."
  },
  AvgDialog_145527_Content_103 = {
    Text = "Grita Lha Gyalo y luego arrójalas a la hoguera."
  },
  AvgDialog_145527_Content_104 = {
    Text = "Una voz ronca pero poderosa resonó en el aire enrarecido, y las ramas en las manos cayeron una a una a la hoguera al ritmo de los gritos."
  },
  AvgDialog_145527_Content_105 = {
    Text = "Gracias al dios de la montaña por tolerar nuestra irreverencia al pisar su dominio sagrado."
  },
  AvgDialog_145527_Content_106 = {
    Text = "Las ramas de pino y ciprés crepitan en el fuego, enviando humo gris que sube recto antes de ser desgarrado por los fuertes vientos."
  },
  AvgDialog_145527_Content_107 = {
    Text = "Y tú percibiste entre ellas un leve presagio de mal agüero."
  },
  AvgDialog_145527_Content_108 = {Text = "..."},
  AvgDialog_145527_Content_109 = {
    Text = "Bien, ya hemos explicado a todos los peligros de esta ascensión y los planes de emergencia."
  },
  AvgDialog_145527_Content_11 = {
    Text = "¡¡¡Eh!!! ¿¡¡Por qué!!?"
  },
  AvgDialog_145527_Content_110 = {
    Text = "Durante la última Semana, todos se han adaptado a moverse con guantes, botas de montaña y gafas de Nieve, y han practicado y dominado el uso de cuerdas y tornillos de hielo."
  },
  AvgDialog_145527_Content_111 = {
    Text = "Según el seguimiento exhaustivo de los últimos días, los próximos 5-7 días constituyen la ventana meteorológica más favorable para escalar, así que es un buen momento para partir."
  },
  AvgDialog_145527_Content_112 = {
    Text = "Por favor, comprueben cada uno los mapas de ruta, alimentos, combustible, bombonas de oxígeno, botiquines y demás suministros que llevan consigo."
  },
  AvgDialog_145527_Content_113 = {
    Text = "Recuerden una vez más que durante la ascensión deben <Yellow:obedecer completamente las órdenes del guía>, y que, salvo los miembros que se retiren antes, el resto <Yellow:tiene estrictamente prohibido actuar fuera del grupo>."
  },
  AvgDialog_145527_Content_114 = {
    Text = "¡Si están listos, partamos!"
  },
  AvgDialog_145527_Content_115 = {Text = "..."},
  AvgDialog_145527_Content_116 = {Text = "..."},
  AvgDialog_145527_Content_117 = {
    Text = "Apenas llevaban medio día avanzando por la montaña cuando el cielo despejado se cubrió repentinamente de nubes oscuras."
  },
  AvgDialog_145527_Content_118 = {
    Text = "El viento y la nieve se intensifican de repente; incluso las crestas de las montañas apenas se distinguen, y los perros guía gimen, reacios a seguir adelante."
  },
  AvgDialog_145527_Content_119 = {
    Text = "Qué extraño, según nuestros datos de seguimiento, no debería aparecer un clima anómalo tan pronto."
  },
  AvgDialog_145527_Content_12 = {
    Text = "¿Acaso esos dos no se unieron también recientemente?"
  },
  AvgDialog_145527_Content_120 = {
    Text = "¿Han encontrado alguna vez una situación similar?"
  },
  AvgDialog_145527_Content_121 = {
    Text = "Nunca. Incluso cuando hay desviaciones en el seguimiento, suelen aparecer tres días después del resultado previsto."
  },
  AvgDialog_145527_Content_122 = {
    Text = "<Shake:Una ventisca antinatural… como si… <Yellow:la montaña nos rechazara>.>"
  },
  AvgDialog_145527_Content_123 = {
    Text = "¡Imposible! ¿Cómo puede ser eso si yo, la gran diosa de la montaña, estoy aquí mismo?"
  },
  AvgDialog_145527_Content_124 = {
    Text = "No hay que preocuparse demasiado; al bajar también se encuentran a veces ventiscas inesperadas."
  },
  AvgDialog_145527_Content_125 = {
    Text = "Hay un refugio cerca; incluso tiene algunos suministros adicionales. Vayamos a Descansar un rato y, cuando amaine la ventisca, nos reorganizamos y partimos de nuevo."
  },
  AvgDialog_145527_Content_126 = {
    Text = "¡Entonces no hay más que decir, vamos rápido!"
  },
  AvgDialog_145527_Content_13 = {
    Text = "Caraboo, con el rostro lleno de indignación, extendió el dedo y señaló a Tú y a William."
  },
  AvgDialog_145527_Content_14 = {
    Text = "Es sencillo. Esos dos son adultos y tienen la capacidad de cuidarse a sí mismos."
  },
  AvgDialog_145527_Content_15 = {
    Text = "Escalar montañas no es un juego de niños, pequeña."
  },
  AvgDialog_145527_Content_16 = {
    Text = "Aquí puedes decir que eres el padre, la madre, la diosa de la Nieve o la Voluntad Suprema, lo que quieras."
  },
  AvgDialog_145527_Content_17 = {
    Text = "Pero cuando llegues a las cumbres de más de cinco mil metros de altitud, todas las mentiras quedarán al descubierto entre el Viento, la Nieve y el mal de altura."
  },
  AvgDialog_145527_Content_18 = {
    Text = "¡Pero tengo dinero, tengo <Italic:MUCHÍSIMO>!"
  },
  AvgDialog_145527_Content_19 = {
    Text = "Eres solo una niña, ¿cuánto puedes tener tú——"
  },
  AvgDialog_145527_Content_2 = {
    Text = "Bajo la guía de Naraka, tú y los miembros del equipo de escalada os presentáis unos a otros."
  },
  AvgDialog_145527_Content_20 = {Text = "<Big:¡!>"},
  AvgDialog_145527_Content_21 = {
    Text = "Las palabras de Naraka se cortaron en seco."
  },
  AvgDialog_145527_Content_22 = {
    Text = "La chica saca una pesada bolsa de tela, toma un gran puñado de monedas de oro y las deja caer de vuelta a la bolsa con un tintineo en cascada. Se queda con solo una, haciéndola girar y voltear entre sus dedos."
  },
  AvgDialog_145527_Content_23 = {
    Text = "¡Ya te dije que soy un hada, cómo me va a faltar un Objeto ajeno como el dinero!"
  },
  AvgDialog_145527_Content_24 = {
    Text = "<Small:Pero ¿no acabas de decir que eras una diosa...?>"
  },
  AvgDialog_145527_Content_25 = {
    Text = "¡Da igual, a quién le importa!"
  },
  AvgDialog_145527_Content_26 = {
    Text = "Caraboo lanzó la moneda de oro al aire sin más, y Naraka se abalanzó a atraparla, tropezando y a punto de caer en la Nieve."
  },
  AvgDialog_145527_Content_27 = {
    Text = "La sostuvo entre las manos, le dio un mordisco y no pudo contener su alegría."
  },
  AvgDialog_145527_Content_28 = {
    Text = "<Shake:Es auténtico...!>"
  },
  AvgDialog_145527_Content_29 = {
    Text = "Hmph, ¿cómo iba a ser falsa una moneda de oro de manos de un hada?"
  },
  AvgDialog_145527_Content_3 = {
    Text = "Tinct, una cantante misteriosa y distante, que dice querer encontrar a su hermana."
  },
  AvgDialog_145527_Content_30 = {
    Text = "En fin, ¿ya me pueden incluir en el grupo de montañismo?"
  },
  AvgDialog_145527_Content_31 = {
    Text = "<Shake:<Small:Ciertamente, dejar que una niña se una al grupo de montañismo no es muy responsable de nuestra parte en cuanto a tu seguridad…>>"
  },
  AvgDialog_145527_Content_32 = {
    Text = "<BigShake:¿Eh?>"
  },
  AvgDialog_145527_Content_33 = {
    Text = "Pero pensándolo bien, nuestro grupo de montañismo tiene una amplia Experiencia en escalada y provisiones más que suficientes, ¡proteger a alguien como tú nos <Big:sobra y basta>!"
  },
  AvgDialog_145527_Content_34 = {
    Text = "Eso sí, te aviso desde ya: si decides dar media vuelta a mitad del camino, te dejaremos los recursos necesarios para bajar, pero la tarifa de guía <Big:no se devuelve> ni un céntimo."
  },
  AvgDialog_145527_Content_35 = {
    Text = "Sí, sí, ¿acaso un hada se va a preocupar por tan poca cosa?"
  },
  AvgDialog_145527_Content_36 = {
    Text = "<Shake:<Small:Qué raro, ¿no estaba Ella pidiendo limosna con actuaciones hace un momento?>>"
  },
  AvgDialog_145527_Content_37 = {
    Text = "¡No creas que no te oigo!"
  },
  AvgDialog_145527_Content_38 = {
    Text = "Ya lo dije, ¡eso es un Mantenimiento! Lo que la diosa recibe es la sinceridad de todos, ¿entiendes o no?"
  },
  AvgDialog_145527_Content_39 = {
    Text = "<Shake:<Small:Cuando no es necesario, el oído también es muy bueno…>>"
  },
  AvgDialog_145527_Content_4 = {
    Text = "Evelyn, arqueóloga, que ha venido a este mundo postapocalíptico en busca de investigación científica."
  },
  AvgDialog_145527_Content_40 = {
    Text = "<BigShake:¡ESE TAMBIÉN LO ESCUCHO YO!>"
  },
  AvgDialog_145527_Content_41 = {
    Text = "Vuestro grupo hace inventario de los suministros, y la conversación pronto deriva hacia el ritual."
  },
  AvgDialog_145527_Content_42 = {
    Text = "¿De verdad creen que en la cima hay una diosa capaz de conceder cualquier deseo?"
  },
  AvgDialog_145527_Content_43 = {
    Text = "William preguntó con fingida indiferencia."
  },
  AvgDialog_145527_Content_44 = {
    Text = "Al menos las personas locales sí lo creen. Por culpa del último grupo de alpinistas."
  },
  AvgDialog_145527_Content_45 = {
    Text = "¿El último grupo de alpinistas?"
  },
  AvgDialog_145527_Content_46 = {
    Text = "Sí. Desde que se corrió la voz sobre la Diosa de la Montaña, el Continente del Norte Final se convirtió en una tierra gobernada por completo por la búsqueda de deseos, con toda una sociedad construida en torno al ascenso. Ese equipo de escalada era el más disciplinado y mejor entrenado de cuantos lo intentaron; tenían las mejores posibilidades de alcanzar la cima."
  },
  AvgDialog_145527_Content_47 = {
    Text = "Partieron siendo siete en total. Pero durante el ascenso, los miembros fueron muriendo uno a uno, sucesivamente."
  },
  AvgDialog_145527_Content_48 = {
    Text = "Alguien abandonó la tienda a medianoche y caminó descalzo hacia la ventisca; alguien cortó su propia cuerda de seguridad y saltó desde el precipicio de hielo;"
  },
  AvgDialog_145527_Content_49 = {
    Text = "Y otro desapareció durante varios días, para finalmente ser encontrado congelado frente al grupo—"
  },
  AvgDialog_145527_Content_5 = {
    Text = "Mientras deliberabais sobre los planes para Partir al día siguiente, de repente asomó una cabeza blanca por la entrada del campamento."
  },
  AvgDialog_145527_Content_50 = {
    Text = "Como si, incluso después de morir, hubiera seguido ascendiendo la montaña."
  },
  AvgDialog_145527_Content_51 = {
    Text = "Sin ponerse de acuerdo, todos fueron ralentizando sus movimientos al revisar los suministros."
  },
  AvgDialog_145527_Content_52 = {
    Text = "Al final, solo una persona regresó viva al pie de la montaña."
  },
  AvgDialog_145527_Content_53 = {
    Text = "Aunque tampoco se puede decir que realmente \"volviera vivo\"."
  },
  AvgDialog_145527_Content_54 = {
    Text = "¿Qué quieres decir?"
  },
  AvgDialog_145527_Content_55 = {
    Text = "Sus diez dedos estaban completamente gangrenados por el frío, y sus oídos estaban llenos de Nieve mezclada con Sangre. Sin importar lo que le preguntaran, solo repetía una y otra vez las mismas frases."
  },
  AvgDialog_145527_Content_56 = {
    Text = "Naraka bajó la voz, imitando el tono de Susurros del superviviente."
  },
  AvgDialog_145527_Content_57 = {
    Text = "<Shake:\"La leyenda es verdad. El deseo en la cima de la montaña es verdad.\">"
  },
  AvgDialog_145527_Content_58 = {
    Text = "<Shake:<Red:\"Tápate los oídos, no escuches.\">>"
  },
  AvgDialog_145527_Content_59 = {
    Text = "<Shake:\"Quien escuche el canto será seducido, Devorado… y luego ascenderá al cielo, convirtiéndose en la <Red:Luna>.\">"
  },
  AvgDialog_145527_Content_6 = {
    Text = "Oye~ ¿Es este el equipo de montañismo de Naraka?"
  },
  AvgDialog_145527_Content_60 = {
    Text = "¿Y entonces qué?"
  },
  AvgDialog_145527_Content_61 = {
    Text = "Después…"
  },
  AvgDialog_145527_Content_62 = {
    Text = "Naraka esbozó una extraña sonrisa a medio camino entre la burla y la indiferencia."
  },
  AvgDialog_145527_Content_63 = {
    Text = "Los lugareños creyeron que debían haber profanado a la diosa de la montaña. Temiendo que estos forasteros pudieran atraer la ira de la diosa sobre sus aldeas…"
  },
  AvgDialog_145527_Content_64 = {
    Text = "Así que eligieron una noche oscura y tormentosa, y lo arrojaron a una grieta de hielo de profundidad insondable."
  },
  AvgDialog_145527_Content_65 = {
    Text = "¿Ese es el final de la historia?"
  },
  AvgDialog_145527_Content_66 = {Text = "No."},
  AvgDialog_145527_Content_67 = {
    Text = "Desde entonces, cada vez que hay luna llena, quienes pasan junto a esa grieta de hielo aún escuchan a alguien cantar desde Abajo."
  },
  AvgDialog_145527_Content_68 = {
    Text = "Así todos supieron que decía la verdad. En la montaña debía de existir algo."
  },
  AvgDialog_145527_Content_69 = {
    Text = "Naraka volvió a bajar la cabeza y fue enrollando la cuerda en espirales dentro de Las Mochilas, Como Si lo que acababa de contar no fuera más que un viejo asunto sin importancia."
  },
  AvgDialog_145527_Content_7 = {
    Text = "¿Me buscas a mí?"
  },
  AvgDialog_145527_Content_70 = {
    Text = "En el breve silencio, Solo el Viento rozaba la tienda, emitiendo un gemido largo y difuso."
  },
  AvgDialog_145527_Content_71 = {
    Text = "También he oído que, durante el ascenso, escucharon el canto de las sirenas."
  },
  AvgDialog_145527_Content_72 = {
    Text = "Estás diciendo tonterías otra vez. Las sirenas son monstruos marinos, ¿cómo iban a aparecer en una montaña?"
  },
  AvgDialog_145527_Content_73 = {
    Text = "Caraboo frunció los labios con disgusto y soltó un leve resoplido."
  },
  AvgDialog_145527_Content_74 = {
    Text = "En el mar hay monstruos que cantan, ¿por qué no podría haberlos en la montaña?"
  },
  AvgDialog_145527_Content_75 = {
    Text = "Creer o no, es tu elección. Cuando escuches el canto, recuerda taparse los oídos."
  },
  AvgDialog_145527_Content_76 = {
    Text = "Cuando estás a punto de seguir preguntando, te das cuenta de que Caraboo ya se ha dado la vuelta y ha entrado en la cabaña, sin intención de continuar con la conversación."
  },
  AvgDialog_145527_Content_77 = {Text = "..."},
  AvgDialog_145527_Content_78 = {
    Text = "Siete días después"
  },
  AvgDialog_145527_Content_79 = {
    Text = "El entrenamiento de hoy termina aquí. Mañana es el día oficial del ascenso."
  },
  AvgDialog_145527_Content_8 = {
    Text = "¡Jeje, he oído que eres el mejor guía de montaña de todo el pueblo Sherpa!"
  },
  AvgDialog_145527_Content_80 = {
    Text = "Caraboo se adelantó de repente y detuvo a Naraka, que se disponía a marcharse."
  },
  AvgDialog_145527_Content_81 = {
    Text = "¿No se va a celebrar <Yellow:el Ritual Lhasang>?"
  },
  AvgDialog_145527_Content_82 = {
    Text = "El Ritual Lhasang, ¿qué es eso?"
  },
  AvgDialog_145527_Content_83 = {
    Text = "Antes de cada ascenso, diez de cada diez Sherpas realizan este ritual de Oración. ¿Acaso no tienes ningún respeto por las Deidades?"
  },
  AvgDialog_145527_Content_84 = {
    Text = "Naraka se dio una palmada en la frente."
  },
  AvgDialog_145527_Content_85 = {
    Text = "<Yellow:Ah, con todo lo que ha pasado, se me fue de la cabeza.>"
  },
  AvgDialog_145527_Content_86 = {
    Text = "¿Cómo puedes olvidar algo así?"
  },
  AvgDialog_145527_Content_87 = {
    Text = "No importa, mañana por la mañana haré uno sencillo rápidamente."
  },
  AvgDialog_145527_Content_88 = {Text = "..."},
  AvgDialog_145527_Content_89 = {
    Text = "Mueves los hombros entumecidos y abres la Puerta de la habitación; en el pasillo ya se cuela un tenue hilo de humo."
  },
  AvgDialog_145527_Content_9 = {
    Text = "¡Con la Bendición de la diosa de la Nieve, podrías llevarme contigo a escalar la montaña?"
  },
  AvgDialog_145527_Content_90 = {
    Text = "William está de pie frente al espejo de bronce a unos pasos de distancia, alisando uno a uno los pliegues de su cuello."
  },
  AvgDialog_145527_Content_91 = {
    Text = "Buenos días, Guardián."
  },
  AvgDialog_145527_Content_92 = {
    Text = "Olfateas el aire. Este lleva el aroma de madera ardiendo y hierbas, con una fragancia fresca y helada que se percibe por debajo."
  },
  AvgDialog_145527_Content_93 = {
    Text = "Al abrir la puerta principal, el frío y el denso aroma del incienso irrumpen a la vez."
  },
  AvgDialog_145527_Content_94 = {
    Text = "En el espacio abierto del patio, arde un pequeño brasero de sang. Un humo blanquiazul se eleva entre ramas de pino y ciprés y hierbas aromáticas, ascendiendo recto hacia el cielo gris azulado."
  },
  AvgDialog_145527_Content_95 = {
    Text = "Los Sherpas consideran las cumbres como espíritus divinos, y en el monte Everest habita incluso la diosa madre del mundo."
  },
  AvgDialog_145527_Content_96 = {
    Text = "Antes del primer ascenso oficial, los Sherpas erigen altares, izan banderas de oración, recitan sutras y realizan el ritual de \"quemar sang\" junto al altar, para que el humo transmita las ofrendas y las Oraciones a las Deidades."
  },
  AvgDialog_145527_Content_97 = {
    Text = "El ritual de bendición es bastante elaborado; la ceremonia formal puede durar incluso de tres a cuatro horas."
  },
  AvgDialog_145527_Content_98 = {
    Text = "Naraka sacó un manojo de ramas de pino y ciprés de una bolsa de tela y repartió una a cada persona."
  },
  AvgDialog_145527_Content_99 = {
    Text = "Levantadlas en alto y acercadlas."
  },
  AvgDialog_145528_Content_1 = {
    Text = "Te lanzas sobre él y rodeas la cintura de Castor por detrás con todas tus fuerzas. Castor sigue forcejando, y sus cuerdas vocales lloran y aúllan en el Viento y la Nieve, Casi al borde del Desgarramiento."
  },
  AvgDialog_145528_Content_10 = {
    Text = "Evelyn se acercó paso a paso. Se agachó y quedó a la misma altura que el joven al que tú y William tenían inmovilizado en la nieve."
  },
  AvgDialog_145528_Content_11 = {
    Text = "Castor, escúchame. Yo también creí alguna vez que el Wendigo era una criatura que solo existía en las leyendas."
  },
  AvgDialog_145528_Content_12 = {
    Text = "Pero hace un momento… lo escuché."
  },
  AvgDialog_145528_Content_13 = {
    Text = "Escuché… a mi esposo llamándome."
  },
  AvgDialog_145528_Content_14 = {
    Text = "Desde el día en que desapareció, cada día escucho ese llamado, pero nunca había sido tan claro, tan real…"
  },
  AvgDialog_145528_Content_15 = {
    Text = "La voz de Evelyn se vuelve levemente ronca por un momento."
  },
  AvgDialog_145528_Content_16 = {
    Text = "<Shake:Pero Castor… ¿sabes?…>"
  },
  AvgDialog_145528_Content_17 = {
    Text = "Han pasado más de noventa días desde que mi esposo desapareció en la montaña nevada, mucho después del tiempo óptimo de rescate."
  },
  AvgDialog_145528_Content_18 = {
    Text = "En el mejor de los casos, lo único que puedo esperar es encontrar sus restos en algún sendero de la montaña."
  },
  AvgDialog_145528_Content_19 = {
    Text = "Él no estará vivo… aquí. Tu hermano, mucho menos."
  },
  AvgDialog_145528_Content_2 = {
    Text = "Castor, ese no es él."
  },
  AvgDialog_145528_Content_20 = {
    Text = "Debemos seguir subiendo, hasta llegar al confín de la montaña."
  },
  AvgDialog_145528_Content_21 = {
    Text = "Esa es la única oportunidad que tenemos de Reencuentro con ellos."
  },
  AvgDialog_145528_Content_22 = {
    Text = "Castor, bajo las palabras tranquilizadoras de Evelyn, fue calmándose poco a poco."
  },
  AvgDialog_145528_Content_23 = {
    Text = "Tienes razón… en la montaña nevada no habría celdas de confinamiento… él no está en un lugar así."
  },
  AvgDialog_145528_Content_24 = {
    Text = "Seguiré adelante… hasta el Reencuentro con él."
  },
  AvgDialog_145528_Content_25 = {
    Text = "A vuestras espaldas, alguien tomó un piolet y golpeó la roca dos veces con un sonido seco."
  },
  AvgDialog_145528_Content_26 = {
    Text = "Si todos ya han calmado sus emociones, necesitamos prepararnos para enfrentar la verdadera amenaza."
  },
  AvgDialog_145528_Content_27 = {
    Text = "<Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_3 = {
    Text = "<Shake:¿Cómo sabes que no es él?! ¡Tú ni siquiera lo conoces!>"
  },
  AvgDialog_145528_Content_4 = {
    Text = "¡Ninguno de vosotros lo conoce! Solo yo lo conozco, ¡conozco su voz!! ¡Fui yo quien lo abandonó allí!"
  },
  AvgDialog_145528_Content_5 = {
    Text = "Es la primera vez que le levanta la voz a William. Luego se sobresalta con el sonido de su propia voz."
  },
  AvgDialog_145528_Content_6 = {
    Text = "Castor, cálmate, eso es un <Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_7 = {
    Text = "El Wendigo, monstruo de las montañas… escava en las sombras más profundas de tu corazón…"
  },
  AvgDialog_145528_Content_8 = {
    Text = "Luego, toma prestada la voz de quien más añoras para tentar al Extraviado y hacerle caer en su trampa."
  },
  AvgDialog_145528_Content_9 = {
    Text = "<Shake:No, ¿con qué certeza dices eso—>"
  },
  AvgDialog_145529_Content_1 = {
    Text = "Otra Primavera"
  },
  AvgDialog_145529_Content_10 = {
    Text = "<Shake:Este lugar… ¿dónde estoy?>"
  },
  AvgDialog_145529_Content_100 = {
    Text = "Ya fuera una vida tranquila, o un mayor lleno de cariño."
  },
  AvgDialog_145529_Content_101 = {
    Text = "Incluso aquel conejito."
  },
  AvgDialog_145529_Content_102 = {
    Text = "La liebre del campo se dio la vuelta, y sus dos Ojos redondos y brillantes se encontraron con los de Ella."
  },
  AvgDialog_145529_Content_103 = {
    Text = "Luego se giró, impulsó sus patas traseras contra la tierra y se metió en su madriguera."
  },
  AvgDialog_145529_Content_11 = {
    Text = "A juzgar por las últimas palabras de Caraboo, ahora mismo nos encontramos En Posición normal en el vientre de la montaña."
  },
  AvgDialog_145529_Content_12 = {
    Text = "Lo más urgente es encontrar el Camino para Escapar."
  },
  AvgDialog_145529_Content_13 = {
    Text = "Yo tampoco he estado en este lugar, me temo que no podré servirles de guía."
  },
  AvgDialog_145529_Content_14 = {
    Text = "No te preocupes, hemos pasado por momentos mucho más difíciles que este."
  },
  AvgDialog_145529_Content_15 = {
    Text = "%player%, ¿qué es lo que tienes en la mano?"
  },
  AvgDialog_145529_Content_16 = {
    Text = "Vaya, esto es… el Hilo de Arachne…"
  },
  AvgDialog_145529_Content_17 = {
    Text = "Sin saber cuándo, este Hilo se ha enredado silenciosamente en tu dedo meñique."
  },
  AvgDialog_145529_Content_18 = {
    Text = "El Hilo, que antes permanecía en Silencio y era suave al tacto, ahora brilla y fluye con un lustre hipnótico, extendiéndose naturalmente desde su extremo hacia la oscuridad lejana."
  },
  AvgDialog_145529_Content_19 = {
    Text = "¿Es una guía del destino? Sigámoslo y veamos adónde lleva."
  },
  AvgDialog_145529_Content_2 = {
    Text = "oscuridad. oscuridad sin fin."
  },
  AvgDialog_145529_Content_20 = {
    Text = "Caraboo siguió el Hilo sin saber cuánto tiempo avanzó. Al final del Hilo, apareció un destello de luz."
  },
  AvgDialog_145529_Content_21 = {Text = "¿Luz…?"},
  AvgDialog_145529_Content_22 = {
    Text = "La luz y las sombras cambiaron de repente."
  },
  AvgDialog_145529_Content_23 = {
    Text = "¿Aquí es...?"
  },
  AvgDialog_145529_Content_24 = {
    Text = "Oye, Caraboo, ¡más despacio!"
  },
  AvgDialog_145529_Content_25 = {
    Text = "¡Mira, Tía Rosa, hay un conejo allí!"
  },
  AvgDialog_145529_Content_26 = {
    Text = "¡Se metió en un agujero!"
  },
  AvgDialog_145529_Content_27 = {
    Text = "Ella esperó desde el día hasta la noche, pero el conejo nunca salió."
  },
  AvgDialog_145529_Content_28 = {
    Text = "¡Tía Rosa, lo vi con mis propios ojos! ¡El conejo entró justo en este agujero!"
  },
  AvgDialog_145529_Content_29 = {
    Text = "Tía Rosa acarició suavemente el cabello de Caraboo."
  },
  AvgDialog_145529_Content_3 = {
    Text = "Duele, duele, duele… ¿Dónde estoy?"
  },
  AvgDialog_145529_Content_30 = {
    Text = "Tontuela, los conejos no son animales tan simples."
  },
  AvgDialog_145529_Content_31 = {
    Text = "Las madrigueras bajo estos campos son como una gran red enredada de túneles. Todos están conectados."
  },
  AvgDialog_145529_Content_32 = {
    Text = "El conejito blanco que tenías en la mira ya habrá escapado por alguna otra madriguera hace rato."
  },
  AvgDialog_145529_Content_33 = {
    Text = "¿Y entonces qué hacemos?"
  },
  AvgDialog_145529_Content_34 = {
    Text = "Nada, pequeña Caraboo."
  },
  AvgDialog_145529_Content_35 = {
    Text = "Sembramos en los campos, los regamos, esperamos en La Vigilia a que maduren, los cosechamos y disfrutamos de los frutos que la Deidad nos otorga."
  },
  AvgDialog_145529_Content_36 = {
    Text = "Pero, ¿y si quiero ese conejo?"
  },
  AvgDialog_145529_Content_37 = {
    Text = "Querida pequeña Caraboo, no debemos desear ese conejo. Si quieres comer algo de carne, podemos ir al mercado a cambiarlo por frutas y verduras."
  },
  AvgDialog_145529_Content_38 = {
    Text = "Pero, ¿y si sigo queriendo ese conejo?"
  },
  AvgDialog_145529_Content_39 = {
    Text = "<Red:¿Por qué… Por qué no puedo tener ese conejo?>"
  },
  AvgDialog_145529_Content_4 = {
    Text = "Sin necesidad de preguntar, ella ya lo sabía. Estaba en el vientre del gusano."
  },
  AvgDialog_145529_Content_40 = {Text = "..."},
  AvgDialog_145529_Content_41 = {Text = "..."},
  AvgDialog_145529_Content_42 = {
    Text = "¿Por qué en este momento veo recuerdos de mi infancia…?"
  },
  AvgDialog_145529_Content_43 = {
    Text = "Calma. Puede que sea por haber caminado demasiado tiempo en la oscuridad, estoy viendo Fantasmas."
  },
  AvgDialog_145529_Content_44 = {
    Text = "¿Esto no es un Fantasma, verdad?"
  },
  AvgDialog_145529_Content_45 = {
    Text = "<Shake:¡Aaaah! ¡Un fantasma!!>"
  },
  AvgDialog_145529_Content_46 = {
    Text = "¿Recuerdas uno de los siete artefactos sagrados, el Hilo del destino? Lo que ves es la Trayectoria del destino."
  },
  AvgDialog_145529_Content_47 = {
    Text = "A continuación, la Trayectoria del destino te revelará otra posibilidad y su punto de divergencia."
  },
  AvgDialog_145529_Content_48 = {
    Text = "¿Qué tiene que ver todo eso con que ahora mismo esté atrapada en el estómago de un monstruo?"
  },
  AvgDialog_145529_Content_49 = {
    Text = "Porque ese es tu deseo. Los deseos son la mecha que guía a cada persona hacia su destino final."
  },
  AvgDialog_145529_Content_5 = {
    Text = "Maldita sea, atraje a alguien hacia aquí y terminé siendo devorada yo misma."
  },
  AvgDialog_145529_Content_50 = {
    Text = "¡Deja los acertijos! ¿Podrías usar algo de ese aliento para decirme cómo salir de aquí en su lugar?! <BigShake:¡EH—>"
  },
  AvgDialog_145529_Content_51 = {
    Text = "La sombra desapareció en silencio."
  },
  AvgDialog_145529_Content_52 = {
    Text = "Vaya, qué tacaño. No hay nada que hacer, de todos modos no hay otro camino en la cavidad abdominal del gusano, sigamos adelante."
  },
  AvgDialog_145529_Content_53 = {Text = "..."},
  AvgDialog_145529_Content_54 = {Text = "..."},
  AvgDialog_145529_Content_55 = {
    Text = "¡Tía Rosa! No se apresure, ¡ya voy a ayudarla!"
  },
  AvgDialog_145529_Content_56 = {
    Text = "Esta es… ¿yo?"
  },
  AvgDialog_145529_Content_57 = {
    Text = "Buena chica, tu tía solo vino a verte."
  },
  AvgDialog_145529_Content_58 = {
    Text = "Tía, sus piernas no están bien, no tiene que venir siempre a la plantación. En cuanto termine de recoger esta albahaca, volveremos juntas a dar de comer a los conejos."
  },
  AvgDialog_145529_Content_59 = {
    Text = "¿Ya los has visto? ¡Lechuga tuvo una camada anoche! ¡Muchísimos conejitos, todos de distintos colores!"
  },
  AvgDialog_145529_Content_6 = {
    Text = "Espera, ¿qué es esto? ¿Un Hilo…?"
  },
  AvgDialog_145529_Content_60 = {
    Text = "Nuestra Caraboo ya se ha convertido en toda una señorita."
  },
  AvgDialog_145529_Content_61 = {
    Text = "Tía, qué cosas dice. Estas labores del campo ya las hacía yo sola cuando tenía trece años."
  },
  AvgDialog_145529_Content_62 = {
    Text = "La decisión más acertada que tomé en mi vida fue traerte de casa de tus padres para que estuvieras conmigo."
  },
  AvgDialog_145529_Content_63 = {
    Text = "Cuando me dijiste que tu padre te golpeaba cuando estaba borracho, dudé toda una noche y luego, en la madrugada, tomé el primer tren."
  },
  AvgDialog_145529_Content_64 = {
    Text = "Casi me peleo con tu padre antes de poder llevarte de vuelta."
  },
  AvgDialog_145529_Content_65 = {
    Text = "Desde entonces, ya han pasado casi diez años, ¿verdad?"
  },
  AvgDialog_145529_Content_66 = {
    Text = "Ahora, sin ti, con estas piernas mías, no sé cómo podría vivir solo—"
  },
  AvgDialog_145529_Content_67 = {
    Text = "Ah— Ah—"
  },
  AvgDialog_145529_Content_68 = {
    Text = "Esta es... aquella noche— aquella noche— una posibilidad diferente—"
  },
  AvgDialog_145529_Content_69 = {
    Text = "Aquella noche, la noche en que ella se encontró con el \"Gusano de la Montaña\", la noche en que decidió liberarse del destino con sus propias manos."
  },
  AvgDialog_145529_Content_7 = {
    Text = "Un Hilo cristalino y luminoso emergió desde la oscuridad lejana y se quedó suspendido frente a Caraboo."
  },
  AvgDialog_145529_Content_70 = {
    Text = "Perteneciente al mundo real, aquella noche que ella vivió."
  },
  AvgDialog_145529_Content_71 = {
    Text = "Entre el crepitar de las llamas de la chimenea, ella se quedó de pie ante el lecho de su padre embriagado, dudando durante largo, largo tiempo."
  },
  AvgDialog_145529_Content_72 = {
    Text = "Adelante, haz lo que siempre has querido hacer."
  },
  AvgDialog_145529_Content_73 = {
    Text = "Ella levantó el cuchillo—"
  },
  AvgDialog_145529_Content_74 = {
    Text = "Exacto, así es."
  },
  AvgDialog_145529_Content_75 = {
    Text = "Mátalo, y todos podrán ser felices."
  },
  AvgDialog_145529_Content_76 = {
    Text = "Y luego, lentamente, lentamente, lo bajó."
  },
  AvgDialog_145529_Content_77 = {
    Text = "Lo siento, sigo sin poder hacerlo."
  },
  AvgDialog_145529_Content_78 = {
    Text = "Vete, Siempre Que huyas lejos de aquí, no tendrás que seguir soportando el dolor."
  },
  AvgDialog_145529_Content_79 = {
    Text = "Pequeña inútil."
  },
  AvgDialog_145529_Content_8 = {
    Text = "¡Da igual, da igual, más te vale no estar engañándome!"
  },
  AvgDialog_145529_Content_80 = {
    Text = "Bueno, lo que me interesa de ti es otra cosa."
  },
  AvgDialog_145529_Content_81 = {
    Text = "Vamos, con esa lengua astuta tuya, igual podemos conseguir el tesoro más preciado."
  },
  AvgDialog_145529_Content_82 = {
    Text = "A la mañana siguiente, me escondí a escondidas entre la paja de un carro de bueyes y me colé en el pueblo más cercano."
  },
  AvgDialog_145529_Content_83 = {
    Text = "Luego, con una Identidad y documentos falsificados, subí al tren que iba hacia el este."
  },
  AvgDialog_145529_Content_84 = {
    Text = "Desde entonces, he tenido muchas identidades: sobrina del jefe de tren, amiga del Guardia, Hada del culto, diosa de la montaña nevada…"
  },
  AvgDialog_145529_Content_85 = {
    Text = "Dejé todo mi pasado atrás, abandonado en aquella noche de gran nevada en que huí."
  },
  AvgDialog_145529_Content_86 = {
    Text = "Después, mucho, mucho tiempo Después, fue por boca de un compatriota que encontré por casualidad en el campo de batalla que supe—"
  },
  AvgDialog_145529_Content_87 = {
    Text = "¿El señor Hans?"
  },
  AvgDialog_145529_Content_88 = {
    Text = "Un día de gran nevada, estaba completamente borracho."
  },
  AvgDialog_145529_Content_89 = {
    Text = "El fuego de la chimenea fue apagado por la Nieve derretida que goteaba del techo; normalmente, su hijita iba a encenderlo por él."
  },
  AvgDialog_145529_Content_9 = {
    Text = "Despiertas de tu sopor y ante tus ojos se extiende un vacío suave, húmedo y opresivo."
  },
  AvgDialog_145529_Content_90 = {
    Text = "Justo ese día, por alguna razón, la niña no estaba en Nuestro Hogar."
  },
  AvgDialog_145529_Content_91 = {
    Text = "Murió congelado en aquella noche de Nieve."
  },
  AvgDialog_145529_Content_92 = {
    Text = "Después tampoco volvimos a ver a aquella niña."
  },
  AvgDialog_145529_Content_93 = {
    Text = "Por cierto, gran Hada, ¿por qué pregunta usted de repente por esto? Mi Bendición, ¿ya me la puede dar?"
  },
  AvgDialog_145529_Content_94 = {
    Text = "Caraboo le llenó la mano al joven que tenía delante con un puñado de caramelos."
  },
  AvgDialog_145529_Content_95 = {
    Text = "Por la Hada que está en lo alto, uno cada día; cuando termine estos caramelos bendecidos, su herida en la pierna sanará."
  },
  AvgDialog_145529_Content_96 = {
    Text = "Aunque Ella sabía en su corazón que ningún caramelo podría curar las piernas ya amputadas del joven."
  },
  AvgDialog_145529_Content_97 = {Text = "..."},
  AvgDialog_145529_Content_98 = {Text = "..."},
  AvgDialog_145529_Content_99 = {
    Text = "Qué ridículo, verdaderamente ridículo. Resulta que aquella noche, Siempre Que no hubiera hecho nada, habría obtenido la felicidad que tanto anhelaba."
  },
  AvgDialog_145530_Content_1 = {
    Text = "El Largo Sueño"
  },
  AvgDialog_145530_Content_10 = {
    Text = "En ese caso, te apoyo."
  },
  AvgDialog_145530_Content_11 = {
    Text = "Te apoyo para que recuperes a ese tú que fue abandonado."
  },
  AvgDialog_145530_Content_12 = {
    Text = "Al fin y al cabo, nosotros somos las personas más egoístas que existen."
  },
  AvgDialog_145530_Content_13 = {
    Text = "La montaña de Nieve murió."
  },
  AvgDialog_145530_Content_14 = {
    Text = "<Shake:Terminó...>"
  },
  AvgDialog_145530_Content_15 = {
    Text = "En el centro de la montaña de Nieve se abrió una Herida escalofriante, desde la cima del gusano hasta el extremo de su cavidad abdominal."
  },
  AvgDialog_145530_Content_16 = {
    Text = "El cuerpo del gusano, siguiendo esa Herida, se fue derrumbando lenta, lentamente hacia ambos lados."
  },
  AvgDialog_145530_Content_17 = {
    Text = "Vosotros también caísteis en picado junto con el derrumbe de la cima de la montaña."
  },
  AvgDialog_145530_Content_18 = {
    Text = "<Shake:¡Cuidado, se está derrumbando!>"
  },
  AvgDialog_145530_Content_19 = {
    Text = "Entre el Viento de la caída, de improviso, escuchaste un Susurro."
  },
  AvgDialog_145530_Content_2 = {
    Text = "¿Ya lo has decidido?"
  },
  AvgDialog_145530_Content_20 = {
    Text = "Aún no ha terminado."
  },
  AvgDialog_145530_Content_21 = {
    Text = "Caraboo extendió su mano."
  },
  AvgDialog_145530_Content_22 = {
    Text = "En El Rostro surcado de lágrimas, Ella esbozó una sonrisa despreocupada."
  },
  AvgDialog_145530_Content_23 = {
    Text = "Entonces, en medio de la gravedad que escapaba a vuestro control, los siete halos de luz se iluminaron."
  },
  AvgDialog_145530_Content_24 = {
    Text = "Lo que murió… Solo la montaña nevada… El ritual… ¡Sigue en marcha!"
  },
  AvgDialog_145530_Content_25 = {
    Text = "En ese instante, el cielo y la Tierra parecían haber perdido todo sonido."
  },
  AvgDialog_145530_Content_26 = {
    Text = "Solo viste cómo sus labios se movían apenas, dejando escapar unas palabras que tardarían muchos segundos en comenzar a resonar por el cielo y la Tierra."
  },
  AvgDialog_145530_Content_27 = {
    Text = "Mi deseo es que en este mundo no exista ninguna mentira más."
  },
  AvgDialog_145530_Content_28 = {
    Text = "En el instante en que sus palabras salieron, el mundo ante tus ojos se desintegró."
  },
  AvgDialog_145530_Content_29 = {
    Text = "Una profusa ceniza plateada caía desde las alturas lejanas, con una ligereza y lentitud extremas."
  },
  AvgDialog_145530_Content_3 = {
    Text = "Sí, ya he tomado mi decisión."
  },
  AvgDialog_145530_Content_30 = {
    Text = "Fue un derrumbe silencioso, un crash lento, la Caída del telón de un Sueño eterno y ancestral."
  },
  AvgDialog_145530_Content_31 = {
    Text = "Las cumbres."
  },
  AvgDialog_145530_Content_32 = {
    Text = "La Nieve acumulada."
  },
  AvgDialog_145530_Content_33 = {Text = "El cielo."},
  AvgDialog_145530_Content_34 = {Text = "La Tierra."},
  AvgDialog_145530_Content_35 = {
    Text = "Todo lo que alguna vez existió se convirtió en Oblivion, Como Si Una Mentira hubiera sido descubierta."
  },
  AvgDialog_145530_Content_36 = {
    Text = "...¿Por qué?"
  },
  AvgDialog_145530_Content_37 = {
    Text = "Un conocimiento que no deberías poseer, junto con recuerdos lejanos, se clavó en tu mente Como Si fuera una Espina."
  },
  AvgDialog_145530_Content_38 = {
    Text = "Este barco es un sueño, pero cuando se levanta el velo de mentiras..."
  },
  AvgDialog_145530_Content_39 = {
    Text = "Todo el mundo también es el sueño de alguien, solo que este sueño es más grande, más ilusorio y más distante..."
  },
  AvgDialog_145530_Content_4 = {
    Text = "Esto es Una Mentira, es una traición."
  },
  AvgDialog_145530_Content_40 = {
    Text = "La luna, el sol y las estrellas provienen de su invención, solo los seres ligados a su espíritu pueden..."
  },
  AvgDialog_145530_Content_41 = {
    Text = "<Italic:El mundo entero es una enorme mentira.>"
  },
  AvgDialog_145530_Content_42 = {
    Text = "Acompañada de esta revelación, la desintegración se aceleró. Del cielo comenzó a caer una densa lluvia plateada."
  },
  AvgDialog_145530_Content_43 = {
    Text = "La lluvia cae sobre el agua. Aquellos fragmentos que alguna vez fueron el \"mundo\" se convirtieron en gotas plateadas, hundiéndose lentamente hacia un mar insondable."
  },
  AvgDialog_145530_Content_44 = {
    Text = "Y Tú estabas en medio de esas aguas."
  },
  AvgDialog_145530_Content_45 = {
    Text = "Hundiéndote, hundiéndote."
  },
  AvgDialog_145530_Content_46 = {
    Text = "Hasta que el largo Sueño ilusorio terminó y volviste a abrir los ojos."
  },
  AvgDialog_145530_Content_47 = {
    Text = "Enfrentando la verdad real de este mundo."
  },
  AvgDialog_145530_Content_48 = {
    Text = "En el fondo más profundo y oscuro del Aequor."
  },
  AvgDialog_145530_Content_49 = {
    Text = "El grandioso Reino Divino, ya extinto, reveló al fin su verdadero rostro."
  },
  AvgDialog_145530_Content_5 = {
    Text = "Todos te han cuidado con esmero, y ellos también tienen deseos que quieren cumplir."
  },
  AvgDialog_145530_Content_6 = {
    Text = "Pero la oportunidad de pedir un deseo, Solo hay una."
  },
  AvgDialog_145530_Content_7 = {
    Text = "Aun así, ¿deseas pedir <Yellow:\"ese\"> deseo?"
  },
  AvgDialog_145530_Content_8 = {
    Text = "No hay ningún deseo más importante que este."
  },
  AvgDialog_145530_Content_9 = {
    Text = "La sombra sonrió."
  },
  AvgDialog_145531_Content_1 = {
    Text = "Buenas Noches"
  },
  AvgDialog_145531_Content_10 = {
    Text = "A sus espaldas, alguien abrió silenciosamente un Ojo, Mirando furtivamente la silueta de ella alejarse."
  },
  AvgDialog_145531_Content_11 = {
    Text = "Tinct avanzó lentamente siguiendo el rastro del canto, mientras los fragmentos de hielo y el suelo helado crujían bajo sus zapatos de suela delgada."
  },
  AvgDialog_145531_Content_12 = {
    Text = "(Aquí es… el lago de hielo de durante el día…)"
  },
  AvgDialog_145531_Content_13 = {
    Text = "(Pero hay algo un poco diferente…)"
  },
  AvgDialog_145531_Content_14 = {
    Text = "El lago que había permanecido congelado durante el día había Despertado, sin que se supiera por qué."
  },
  AvgDialog_145531_Content_15 = {
    Text = "La superficie del agua, serena y sin ondas, Abre los ojos hacia el firmamento, como un espejo luminoso que refleja en silencio la Luna eterna."
  },
  AvgDialog_145531_Content_16 = {
    Text = "Faint, ¿eres tú?"
  },
  AvgDialog_145531_Content_17 = {
    Text = "(El agua del lago… extraordinariamente clara…)"
  },
  AvgDialog_145531_Content_18 = {
    Text = "Ella miró hacia el fondo del lago."
  },
  AvgDialog_145531_Content_19 = {
    Text = "El lago era insondable, Como Si Atravesara la Tierra, conduciéndola a un lugar aún más lejano que las Estrellas."
  },
  AvgDialog_145531_Content_2 = {
    Text = "A medianoche, Tinct es despertada por un sonido lejano y tenue."
  },
  AvgDialog_145531_Content_20 = {
    Text = "Una canción flota en el viento. Ronca, antigua, como si hubiera resistido un paso del tiempo inimaginablemente largo y aún no hubiera cesado."
  },
  AvgDialog_145531_Content_21 = {
    Text = "<Italic:La—la la~ la~ ♪>"
  },
  AvgDialog_145531_Content_22 = {
    Text = "Tinct cerró los ojos y respiró profundamente."
  },
  AvgDialog_145531_Content_23 = {
    Text = "(Una melodía familiar… un aliento… añorado…)"
  },
  AvgDialog_145531_Content_24 = {
    Text = "La textura de aquella voz evocaba un lecho de río seco, capas de arenisca erosionadas durante cien mil años, el clamor de antiguos Bosques comprimidos hasta convertirse en carbón bajo el peso de las eras geológicas."
  },
  AvgDialog_145531_Content_25 = {
    Text = "(Esto parece ser… una melodía… proveniente de la Estrella Infausta…)"
  },
  AvgDialog_145531_Content_26 = {
    Text = "Los recuerdos de mil años atrás comenzaron a Reanimar, y Ella empezó a intentar tararear, a intentar seguir aquella voz errante."
  },
  AvgDialog_145531_Content_27 = {
    Text = "<Shake:La la~ la la la~♪>"
  },
  AvgDialog_145531_Content_28 = {
    Text = "Ella lo sintió, Ella lo capturó."
  },
  AvgDialog_145531_Content_29 = {
    Text = "En El Rostro de Ella afloró una alegría sincera."
  },
  AvgDialog_145531_Content_3 = {
    Text = "(Lo de afuera… esto es… ¿un canto?)"
  },
  AvgDialog_145531_Content_30 = {
    Text = "Su registro vocal se expandió, hacia arriba. Una voz clara como la del ruiseñor se fue Entrelazando, suave y ligera, con aquella melodía grave y ronca."
  },
  AvgDialog_145531_Content_31 = {
    Text = "Las dos voces comenzaron a tensarse, a enredarse, a acercarse."
  },
  AvgDialog_145531_Content_32 = {
    Text = "<Change>La la la la la la~♪"
  },
  AvgDialog_145531_Content_33 = {
    Text = "La capa de hielo se fue cerrando poco a poco; en las profundidades del lago, incontables rostros pálidos alzaron la vista siguiendo el canto."
  },
  AvgDialog_145531_Content_34 = {
    Text = "Pero Tinct no se percataba de nada."
  },
  AvgDialog_145531_Content_35 = {
    Text = "Solo existía el canto. El canto que cruzaba Los Atrapados en la Nieve y la tundra helada, que cruzaba el cosmos y el mar de estrellas, que cruzaba los tiempos eternos, transformándose en algo que cada ser debería considerar eterno."
  },
  AvgDialog_145531_Content_36 = {
    Text = "Sí, no debería seguir engañándome a mí misma…"
  },
  AvgDialog_145531_Content_37 = {
    Text = "Ya no quiero seguir buscando… La esperanza no existe en ningún lugar… Ella vive en mis recuerdos, y solo en mis recuerdos…"
  },
  AvgDialog_145531_Content_38 = {
    Text = "El anciano conocido en el agua le extendió la mano."
  },
  AvgDialog_145531_Content_39 = {
    Text = "Una voz anciana y melodiosa la llamaba con ternura, invocando su nombre de hace mil años."
  },
  AvgDialog_145531_Content_4 = {
    Text = "El sonido es extremadamente suave, filtrándose desde alguna profundidad insondable a través de incontables capas de hielo, nieve y roca."
  },
  AvgDialog_145531_Content_40 = {Text = "…@1@3…"},
  AvgDialog_145531_Content_41 = {
    Text = "Debería rendirme…"
  },
  AvgDialog_145531_Content_42 = {
    Text = "Este viaje ha sido demasiado largo, demasiado largo. Ya hace mucho que estoy agotada…"
  },
  AvgDialog_145531_Content_43 = {
    Text = "El llamado vibraba contra sus huesos, otorgándole el consuelo que tanto anhelaba. Su angustia sin refugio, su tristeza sin destino, por fin eran completamente comprendidas y aceptadas por algún ser."
  },
  AvgDialog_145531_Content_44 = {
    Text = "<Shake:Abrázame, Faint… Oh, sombra de mis recuerdos… Abrázame, como lo hacías antes…>"
  },
  AvgDialog_145531_Content_45 = {
    Text = "<Shake:Concédeme la Ning que tanto anhelo…>"
  },
  AvgDialog_145531_Content_46 = {
    Text = "Ella, suave y lentamente, se adentró en las tranquilas aguas del lago."
  },
  AvgDialog_145531_Content_47 = {
    Text = "El lago no agita ni una sola onda. Como una lengua fría, lame con ternura su cintura, sus hombros, su garganta."
  },
  AvgDialog_145531_Content_48 = {
    Text = "<Change>La la la…"
  },
  AvgDialog_145531_Content_49 = {
    Text = "Ella seguía cantando."
  },
  AvgDialog_145531_Content_5 = {
    Text = "Es ronca y lenta, cada sílaba suena como arena arrastrada por el viento rodando por la tierra. Obstinada e incesante, continúa como un río subterráneo que fluye eternamente."
  },
  AvgDialog_145531_Content_50 = {
    Text = "Su silueta, su cuerpo, su existencia se fueron diluyendo junto con el canto, fundiéndose y dispersándose bajo la luz de la luna."
  },
  AvgDialog_145531_Content_51 = {
    Text = "Un pensamiento, un pensamiento tan débil que Casi era imposible de capturar, en ese instante, trepó de manera inexplicable a la conciencia de Tinct."
  },
  AvgDialog_145531_Content_52 = {
    Text = "(Qué extraño… hoy… se suponía que era luna nueva…)"
  },
  AvgDialog_145531_Content_53 = {
    Text = "Y entonces — la superficie del lago se hundió de repente hacia adentro."
  },
  AvgDialog_145531_Content_54 = {
    Text = "Sin salpicaduras, sin gritos. Solo el canto que seguía flotando en el aire."
  },
  AvgDialog_145531_Content_55 = {
    Text = "La Luna en el cielo había desaparecido sin que nadie supiera cuándo."
  },
  AvgDialog_145531_Content_56 = {
    Text = "Solo quedaba el lago mecido por la Luna, reflejando con nitidez la silueta de Tinct."
  },
  AvgDialog_145531_Content_57 = {Text = "..."},
  AvgDialog_145531_Content_58 = {
    Text = "A la mañana siguiente."
  },
  AvgDialog_145531_Content_59 = {
    Text = "¿Alguien ha visto a Tinct?"
  },
  AvgDialog_145531_Content_6 = {
    Text = "(Muy lejana, y sin embargo muy familiar…)"
  },
  AvgDialog_145531_Content_60 = {
    Text = "Todos negaron con la cabeza."
  },
  AvgDialog_145531_Content_61 = {
    Text = "Mmm… Anoche escuché movimiento a mi lado, pero me quedé dormido enseguida."
  },
  AvgDialog_145531_Content_62 = {
    Text = "He buscado en todas las tiendas y no está en ninguna."
  },
  AvgDialog_145531_Content_63 = {
    Text = "¿Puede que se haya retirado a mitad de camino?"
  },
  AvgDialog_145531_Content_64 = {
    Text = "Ayer, cuando estaba junto al lago de hielo, su Estado ya era muy extraño…"
  },
  AvgDialog_145531_Content_65 = {
    Text = "Evelyn murmuró Impaciente."
  },
  AvgDialog_145531_Content_66 = {
    Text = "Ni siquiera se llevó la botella de oxígeno al salir."
  },
  AvgDialog_145531_Content_67 = {
    Text = "Estamos a seis mil metros de altitud; cada persona debe, y Solo puede, ser responsable de su propia PV."
  },
  AvgDialog_145531_Content_68 = {
    Text = "Al menos… al menos ir a echar un vistazo a la orilla del lago de hielo."
  },
  AvgDialog_145531_Content_69 = {Text = "¿Vamos?"},
  AvgDialog_145531_Content_7 = {
    Text = "Los compañeros de equipo en las tiendas cercanas habían caído en un sueño profundo, agotados por la escalada del día. Hasta los perros guía roncaban."
  },
  AvgDialog_145531_Content_70 = {
    Text = "Tú deseas ir a buscar a Tinct y no quieres abandonar ni la más mínima posibilidad. Pero también sabes que cada decisión que tomes lleva consigo la vida de todo el equipo."
  },
  AvgDialog_145531_Content_71 = {
    Text = "Vamos, la altitud de aquí y la del lago de hielo es Casi la misma, y el tiempo de ida y vuelta está dentro de lo controlable."
  },
  AvgDialog_145531_Content_72 = {
    Text = "Lo único a lo que hay que prestar atención son las bestias salvajes en el camino."
  },
  AvgDialog_145531_Content_8 = {
    Text = "Es hora de salir."
  },
  AvgDialog_145531_Content_9 = {
    Text = "Ella abrió el saco de dormir, levantó la lona de la tienda y salió lentamente al exterior."
  },
  AvgDialog_145532_Content_1 = {
    Text = "Él Miró Atrás"
  },
  AvgDialog_145532_Content_10 = {
    Text = "Luego, le toca a Evelyn. William cierra la marcha, con La Mirada serena y concentrada Guardián de todos."
  },
  AvgDialog_145532_Content_11 = {Text = "Espera…"},
  AvgDialog_145532_Content_12 = {
    Text = "La Mirada de Evelyn se fija en un trozo de cuerda sobre la pared rota."
  },
  AvgDialog_145532_Content_13 = {
    Text = "Esto es… ¡su mosquetón! ¡Reconozco esta marca!"
  },
  AvgDialog_145532_Content_14 = {
    Text = "¡El ángulo formado por la cornisa de Nieve! ¡El ángulo formado por la cornisa de Nieve crea una zona segura que impide que la Nieve caída la cubra!"
  },
  AvgDialog_145532_Content_15 = {
    Text = "Tú miras hacia abajo en dirección a Evelyn. Con Solo una mirada, el Fantasma de la caída te marea."
  },
  AvgDialog_145532_Content_16 = {
    Text = "¡Tengo que ir a buscarlo!"
  },
  AvgDialog_145532_Content_17 = {
    Text = "Evelyn soltó el mosquetón y comenzó a descender lentamente."
  },
  AvgDialog_145532_Content_18 = {
    Text = "¡Es demasiado peligroso, Evelyn!"
  },
  AvgDialog_145532_Content_19 = {
    Text = "No importa, ¡para eso he venido! Si hablamos de peligro, ¡la escalada en sí ya es suficientemente peligrosa!"
  },
  AvgDialog_145532_Content_2 = {
    Text = "Cuatro personas, como cuatro dados, suspendidas sobre el tablero llamado pared de hielo."
  },
  AvgDialog_145532_Content_20 = {
    Text = "¡No se preocupen por mí! ¡Los alcanzaré en un momento!"
  },
  AvgDialog_145532_Content_21 = {
    Text = "En las profundidades de la grieta de hielo, Como Si algo la estuviera tentando."
  },
  AvgDialog_145532_Content_22 = {
    Text = "¡Evelyn, no puedes—!"
  },
  AvgDialog_145532_Content_23 = {
    Text = "Extiendes la mano hacia tu mosquetón, respiras profundo y te preparas para caer."
  },
  AvgDialog_145532_Content_24 = {
    Text = "%player%..."
  },
  AvgDialog_145532_Content_25 = {
    Text = "William detiene tu mano y niega suavemente con la cabeza."
  },
  AvgDialog_145532_Content_26 = {
    Text = "Nadie sabe si Helot volverá, no podemos quedarnos todos suspendidos en el aire."
  },
  AvgDialog_145532_Content_27 = {
    Text = "Mira hacia arriba."
  },
  AvgDialog_145532_Content_28 = {
    Text = "Caraboo ya ha escalado el último acantilado de hielo."
  },
  AvgDialog_145532_Content_29 = {
    Text = "Hacia arriba está el final de este viaje, la tierra prometida donde todos los deseos se hacen realidad."
  },
  AvgDialog_145532_Content_3 = {
    Text = "Cada uno aferraba con fuerza la cuerda de seguridad en su mano, buscando con dificultad el siguiente punto de apoyo."
  },
  AvgDialog_145532_Content_30 = {
    Text = "Hacia abajo, un abismo de oscuridad sin fondo."
  },
  AvgDialog_145532_Content_31 = {
    Text = "¡Pero no podemos perder a otro compañero—!"
  },
  AvgDialog_145532_Content_32 = {Text = "Sé."},
  AvgDialog_145532_Content_33 = {
    Text = "Así que, déjamelo a mí."
  },
  AvgDialog_145532_Content_34 = {
    Text = "Antes de que puedas procesar las palabras, William se desabrocha el arnés y se lanza directamente al abismo."
  },
  AvgDialog_145532_Content_35 = {
    Text = "La pared de hielo vertical que te costó todas tus fuerzas escalar queda conquistada en cuestión de segundos en el descenso. En un instante, William y Evelyn se han reducido a dos pequeños puntos lejanos, engullidos por las estrechas fauces de la grieta."
  },
  AvgDialog_145532_Content_36 = {
    Text = "Observas cómo Evelyn y William descienden cada vez más, dirigiéndose hacia la grieta de hielo."
  },
  AvgDialog_145532_Content_37 = {
    Text = "Luego alzas la vista y clavas el siguiente pitón en la roca."
  },
  AvgDialog_145532_Content_38 = {Text = "..."},
  AvgDialog_145532_Content_39 = {Text = "..."},
  AvgDialog_145532_Content_4 = {
    Text = "Arriba hay una roca, tenemos que superarla."
  },
  AvgDialog_145532_Content_40 = {
    Text = "La grieta de hielo no tiene fondo visible; cuando volvieron a pisar tierra firme, ya reinaba una oscuridad tan densa que no se veía la mano delante de la cara."
  },
  AvgDialog_145532_Content_41 = {
    Text = "Espera, Evelyn…"
  },
  AvgDialog_145532_Content_42 = {
    Text = "La luz de la linterna frontal se agitaba explorando el camino."
  },
  AvgDialog_145532_Content_43 = {
    Text = "Bajo la grieta de hielo parecía haber una cueva de estalactitas, con un ambiente distinto al del resto. Frío, húmedo, y el Viento traía consigo un extraño olor indefinible."
  },
  AvgDialog_145532_Content_44 = {
    Text = "Cuidado con el suelo, aquí hay un hundimiento…"
  },
  AvgDialog_145532_Content_45 = {
    Text = "Sus palabras se atascaron en la garganta, convirtiéndose en un jadeo de aire frío."
  },
  AvgDialog_145532_Content_46 = {
    Text = "Donde la luz barría, había decenas de esqueletos ya saponificados."
  },
  AvgDialog_145532_Content_47 = {
    Text = "Mantenían la postura en que habían caído, algunos encogidos, otros abrazados, cubriendo el suelo en silencio, capa sobre capa."
  },
  AvgDialog_145532_Content_48 = {
    Text = "Este es… el uniforme de la expedición Green."
  },
  AvgDialog_145532_Content_49 = {
    Text = "Todos están aquí."
  },
  AvgDialog_145532_Content_5 = {
    Text = "Vosotros os movéis con sumo cuidado alrededor de la gran roca, comprobando si lo que hay bajo vuestros pies es roca sólida o Nieve Suelta."
  },
  AvgDialog_145532_Content_50 = {
    Text = "Tras un largo silencio, Evelyn se dio la vuelta y fijó su Mirada con seriedad en los Ojos de William."
  },
  AvgDialog_145532_Content_51 = {
    Text = "Parece que aquí tampoco hay mucha información que necesiten, ¿verdad?"
  },
  AvgDialog_145532_Content_52 = {
    Text = "En ese caso, ¿podrían dejarme sola aquí un momento? Quiero buscar si él está entre ellos."
  },
  AvgDialog_145532_Content_53 = {
    Text = "Si es posible, me gustaría poder hablar con él."
  },
  AvgDialog_145532_Content_54 = {
    Text = "Estos cadáveres podrían albergar bacterias peligrosas…"
  },
  AvgDialog_145532_Content_55 = {
    Text = "Evelyn expresó su determinación con la mirada."
  },
  AvgDialog_145532_Content_56 = {
    Text = "¡Entendido!"
  },
  AvgDialog_145532_Content_57 = {
    Text = "Pero prométeme que saldrás de aquí sana y salva."
  },
  AvgDialog_145532_Content_58 = {
    Text = "Sí, de acuerdo, te lo prometo. Definitivamente completaré la ascensión a la cima."
  },
  AvgDialog_145532_Content_59 = {
    Text = "William asintió."
  },
  AvgDialog_145532_Content_6 = {
    Text = "Después de rodearla por fin, antes de que podáis recuperar el aliento, aparece bajo vuestros pies una grieta de profundidad insondable."
  },
  AvgDialog_145532_Content_60 = {
    Text = "Te espero en la entrada de la cueva."
  },
  AvgDialog_145532_Content_61 = {Text = "..."},
  AvgDialog_145532_Content_62 = {Text = "..."},
  AvgDialog_145532_Content_63 = {
    Text = "Pasó mucho, mucho tiempo, tanto que William Casi no pudo resistir el impulso de entrar a investigar, cuando por fin llegó desde el interior de la cueva el susurro del roce de la ropa."
  },
  AvgDialog_145532_Content_64 = {
    Text = "Entonces apareció Evelyn."
  },
  AvgDialog_145532_Content_65 = {
    Text = "Tú… ¿lo encontraste?"
  },
  AvgDialog_145532_Content_66 = {
    Text = "Sí, lo encontré."
  },
  AvgDialog_145532_Content_67 = {
    Text = "Evelyn asintió, con un tono de voz sereno, sin el menor rastro de emoción."
  },
  AvgDialog_145532_Content_68 = {
    Text = "Lo siento mucho."
  },
  AvgDialog_145532_Content_69 = {
    Text = "No, gracias."
  },
  AvgDialog_145532_Content_7 = {
    Text = "Con cuidado, no miréis hacia abajo."
  },
  AvgDialog_145532_Content_70 = {
    Text = "Evelyn soltó una leve risa."
  },
  AvgDialog_145532_Content_71 = {
    Text = "Siempre supe que terminaría así."
  },
  AvgDialog_145532_Content_72 = {
    Text = "Tú también, ¿verdad?"
  },
  AvgDialog_145532_Content_73 = {
    Text = "Tú también buscas a alguien que nunca volverá."
  },
  AvgDialog_145532_Content_74 = {
    Text = "Siempre es igual."
  },
  AvgDialog_145532_Content_75 = {
    Text = "Al principio, uno siempre alberga esperanza, pensando que quizás mañana regrese."
  },
  AvgDialog_145532_Content_76 = {
    Text = "Luego un mañana…"
  },
  AvgDialog_145532_Content_77 = {
    Text = "…y otro mañana más."
  },
  AvgDialog_145532_Content_78 = {
    Text = "La esperanza se va diluyendo, y la Piedra en el fondo del corazón se vuelve cada vez más pesada."
  },
  AvgDialog_145532_Content_79 = {
    Text = "Cae y cae, día tras día."
  },
  AvgDialog_145532_Content_8 = {
    Text = "Tú sigues de cerca a Naraka, agarrando la cuerda con todas tus fuerzas para cruzar la grieta."
  },
  AvgDialog_145532_Content_80 = {
    Text = "Hasta que un día, Descubres que ya no piensas en ello."
  },
  AvgDialog_145532_Content_81 = {
    Text = "Comes, duermes, trabajas, viajas, hablas con otros, ríes… como siempre."
  },
  AvgDialog_145532_Content_82 = {
    Text = "Y luego, por mucho, mucho tiempo, dejas de mencionarlo."
  },
  AvgDialog_145532_Content_83 = {
    Text = "La voz de Evelyn cambió levemente de tono."
  },
  AvgDialog_145532_Content_84 = {
    Text = "Pero sabes que no lo has olvidado, que nunca lo has olvidado."
  },
  AvgDialog_145532_Content_85 = {
    Text = "Nunca lo olvidarás."
  },
  AvgDialog_145532_Content_86 = {
    Text = "Basta con una leyenda, una chispa, y Comenzará a Quemar…"
  },
  AvgDialog_145532_Content_87 = {
    Text = "Te engullirá por completo..."
  },
  AvgDialog_145532_Content_88 = {
    Text = "...y te reducirá a cenizas."
  },
  AvgDialog_145532_Content_89 = {
    Text = "William levantó la cabeza de golpe y clavó La Mirada en Evelyn."
  },
  AvgDialog_145532_Content_9 = {
    Text = "Al echar un vistazo de reojo, Solo ves una oscuridad aterradora en el interior de la grieta, sin saber dónde termina."
  },
  AvgDialog_145532_Content_90 = {
    Text = "Pero ella simplemente le devolvió una mirada serena; lo que llenaba aquellos Ojos, si era fuego o vacío, él no podía distinguirlo a través del reflejo de las gafas protectoras."
  },
  AvgDialog_145532_Content_91 = {
    Text = "Deja de distraerte, vamos. Te prometí que subiría a la cima contigo, ¿no es así?"
  },
  AvgDialog_145532_Content_92 = {
    Text = "Sin saber por qué, William siempre sentía que, aunque sus miradas se cruzaban, el objetivo de las palabras de ella no parecía ser él."
  },
  AvgDialog_145532_Content_93 = {
    Text = "Evelyn ya no lo esperaba. Se dio la vuelta y caminó hacia la salida de la cueva, agachándose para revisar la cuerda de tracción con movimientos tan ágiles que parecía como si aquel Soliloquio de hace un momento nunca hubiera ocurrido."
  },
  AvgDialog_145532_Content_94 = {
    Text = "William se queda paralizado en el sitio, con las palabras que no fue capaz de pronunciar atascadas en la garganta. La observa alejarse hasta perderse de vista, luego vuelve la mirada hacia la oscura y abierta boca de la cueva a sus espaldas."
  },
  AvgDialog_145532_Content_95 = {
    Text = "No encontraba razón para quedarse un segundo más. Apartó La Mirada y siguió sus pasos en Silencio."
  },
  AvgDialog_145534_Content_1 = {
    Text = "La farsa ha terminado. Ahora, la montaña de nieve os devorará."
  },
  AvgDialog_145534_Content_10 = {
    Text = "La cima se Desgarrar de repente desde el centro, abriéndose cada vez más, transformándose en una colosal fauces que atraviesa el cielo y la Tierra de arriba abajo; una saliva carmesí Surge a raudales entre los colmillos escalonados, cayendo como lluvia."
  },
  AvgDialog_145534_Content_11 = {
    Text = "Las fauces se cerraron de golpe—"
  },
  AvgDialog_145534_Content_12 = {
    Text = "Antes de que la multitud pudiera lanzar el primer grito, ya habían sido engullidos en sus insondables entrañas."
  },
  AvgDialog_145534_Content_13 = {
    Text = "La Tierra dejó de temblar, y entre la Nieve que caía suavemente, se alzó un pequeño sombrero de punta."
  },
  AvgDialog_145534_Content_14 = {
    Text = "Caraboo sacudió la Nieve que cubría su cuerpo y contempló satisfecha el resultado de su hazaña—"
  },
  AvgDialog_145534_Content_15 = {
    Text = "¿Por qué? ¿Por qué sigues aquí?"
  },
  AvgDialog_145534_Content_16 = {
    Text = "Una silueta solitaria que no debería existir, la de otra persona."
  },
  AvgDialog_145534_Content_17 = {
    Text = "Yo también quisiera saber por qué sigo aquí."
  },
  AvgDialog_145534_Content_18 = {
    Text = "Acabas de decir que los visitantes ofrecen sus deseos a la montaña, y que la montaña responde a las súplicas."
  },
  AvgDialog_145534_Content_19 = {
    Text = "Quizás sea porque, comparada con todos ustedes, no tengo ningún deseo. Soy demasiado ordinaria, demasiado común, no lo suficientemente apetecible, ¿no?"
  },
  AvgDialog_145534_Content_2 = {
    Text = "Caraboo se giró hacia las montañas que se extendían sin fin, hacia el Viento y la Nieve del vasto páramo."
  },
  AvgDialog_145534_Content_20 = {
    Text = "No, eso no puede ser. ¿Acaso no tienes ningún deseo que entregarle a la montaña?"
  },
  AvgDialog_145534_Content_21 = {
    Text = "Caraboo abrió los ojos de par en par; en su reproche se ocultaba un atisbo de incredulidad e irritación."
  },
  AvgDialog_145534_Content_22 = {
    Text = "No. El único deseo que traía en este viaje ya se ha cumplido."
  },
  AvgDialog_145534_Content_23 = {
    Text = "Al pie del último acantilado, encontré sus restos. Qué suerte tan grande: estaba atrapado entre las grietas de las rocas, sin haber quedado sepultado bajo la nieve."
  },
  AvgDialog_145534_Content_24 = {
    Text = "La carne ya es podredumbre, pero la Placa sigue ahí. Aún puedo reconocerlo, aún puedo confirmar que existió."
  },
  AvgDialog_145534_Content_25 = {
    Text = "¡Imposible, cómo puede ser que se haya satisfecho con tanta facilidad!"
  },
  AvgDialog_145534_Content_26 = {
    Text = "Así son las cosas. Los deseos de los mortales no deberían ser algo que requiera del poder divino para cumplirse."
  },
  AvgDialog_145534_Content_27 = {
    Text = "Y hay más buenas noticias. A juzgar por el equipo que llevaba, sufrieron un percance durante el descenso."
  },
  AvgDialog_145534_Content_28 = {
    Text = "Así que, en vida, ya había cumplido su deseo de alcanzar la cima más alta."
  },
  AvgDialog_145534_Content_29 = {
    Text = "Aunque separados por un tiempo, aquí mismo, ambos moriremos en plenitud."
  },
  AvgDialog_145534_Content_3 = {
    Text = "¡Verdadera hada de la montaña nevada, gran dios de los gusanos, os traigo vuestro Mantenimiento!"
  },
  AvgDialog_145534_Content_30 = {
    Text = "<Shake:No, te estás engañando a ti misma… eso no es verdad, debes querer más…>"
  },
  AvgDialog_145534_Content_31 = {
    Text = "La voz de Caraboo se volvió cada vez más aguda, y las lágrimas brotaron de las comisuras de sus ojos."
  },
  AvgDialog_145534_Content_32 = {
    Text = "Evelyn solo la miraba con La Mirada llena de compasión."
  },
  AvgDialog_145534_Content_33 = {
    Text = "La Nieve seguía cayendo."
  },
  AvgDialog_145534_Content_34 = {
    Text = "Después de un largo silencio, Evelyn se acercó y sacudió la nieve caída sobre los hombros de Caraboo."
  },
  AvgDialog_145534_Content_35 = {
    Text = "Piénsalo bien. Voy a acompañar a mi esposo."
  },
  AvgDialog_145534_Content_36 = {
    Text = "Tras decir esto, ella tarareó algo suavemente y caminó paso a paso hacia el fondo del precipicio."
  },
  AvgDialog_145534_Content_37 = {
    Text = "Sin cuerda de seguridad fija, no temía caer. La grieta de hielo al pie de la roca era su destino."
  },
  AvgDialog_145534_Content_38 = {
    Text = "<Shake:No te vayas, Evelyn, no te vayas—>"
  },
  AvgDialog_145534_Content_39 = {
    Text = "Quien la rechazaba no era Evelyn."
  },
  AvgDialog_145534_Content_4 = {
    Text = "Ella estaba eufórica, Ella reía a carcajadas. Ella sentía placer por el éxito de su engaño."
  },
  AvgDialog_145534_Content_40 = {
    Text = "Quien la retenía tampoco era alguien ajeno a Evelyn."
  },
  AvgDialog_145534_Content_41 = {Text = "¿Por qué"},
  AvgDialog_145534_Content_42 = {
    Text = "¿Por qué… la montaña tiembla?…"
  },
  AvgDialog_145534_Content_43 = {Text = "..."},
  AvgDialog_145534_Content_44 = {
    Text = "En la montaña mora la criatura de mayor terror."
  },
  AvgDialog_145534_Content_45 = {
    Text = "Se extiende por mil millas, serpenteando sobre la tierra que reclama. Se festeja con los corazones de los hombres y devora sus ilusiones."
  },
  AvgDialog_145534_Content_46 = {
    Text = "Ahora, ha venido a capturar a su presa."
  },
  AvgDialog_145534_Content_47 = {
    Text = "<Change>Un deseo… un deseo… un deseo ardiente…"
  },
  AvgDialog_145534_Content_48 = {
    Text = "¡No! ¡Los engañé a todos para traerlos ante ti, prometiste que no me comerías!"
  },
  AvgDialog_145534_Content_49 = {
    Text = "<Change>Quién seguiría… el pacto… de un mentiroso…"
  },
  AvgDialog_145534_Content_5 = {
    Text = "Gente codiciosa, gente estúpida."
  },
  AvgDialog_145534_Content_50 = {
    Text = "El gusano sobre la Manzana también alzó la voz y soltó una risa estridente."
  },
  AvgDialog_145534_Content_51 = {
    Text = "Además, ¿acaso no sabías desde el principio que una de las Ofrendas era \"la Manzana Dorada\"?"
  },
  AvgDialog_145534_Content_52 = {
    Text = "¡No, yo soy la diosa de la montaña nevada, la Manzana Dorada es mi artefacto sagrado, no puedo ser una Ofrenda!"
  },
  AvgDialog_145534_Content_53 = {
    Text = "¿Has olvidado quién eres? Permíteme recordártelo, Caraboo, tú no eres nadie."
  },
  AvgDialog_145534_Content_54 = {
    Text = [[
No eres una diosa, ni una princesa, ni un hada.
Eres solo una refugiada nacida entre los escombros del campo de batalla, que ni siquiera recuerda el rostro de sus padres.]]
  },
  AvgDialog_145534_Content_55 = {
    Text = "Deberías haberlo sabido desde hace tiempo… las Identidades que te inventaste, los honores que obtuviste mediante el engaño… algún día te serían devueltos con creces, de la peor manera."
  },
  AvgDialog_145534_Content_56 = {
    Text = "Hoy es ese día."
  },
  AvgDialog_145534_Content_57 = {
    Text = "La montaña abrió sus fauces de Sangre."
  },
  AvgDialog_145534_Content_58 = {
    Text = "<Change>Entra… en mi vientre… y conviértete… en mi Fortaleza…"
  },
  AvgDialog_145534_Content_59 = {Text = "..."},
  AvgDialog_145534_Content_6 = {
    Text = "Entregad vuestros deseos a la montaña, entregad vuestras ansias a la montaña."
  },
  AvgDialog_145534_Content_60 = {
    Text = "La pendiente suave se volvió repentinamente empinada, y Evelyn, a tan solo unas decenas de metros de la grieta en el hielo, abandonó todo lo que la frenaba."
  },
  AvgDialog_145534_Content_61 = {
    Text = "Ella arrancó el gancho de la botella de oxígeno, se quitó las pesadas botas con crampones y, sin vacilar, cortó la única cuerda principal que llevaba consigo."
  },
  AvgDialog_145534_Content_62 = {
    Text = "Ya nada podía retenerla."
  },
  AvgDialog_145534_Content_63 = {
    Text = "Ella, Justo con ligereza, casi con alegría, se lanzó hacia su amado que dormía en la grieta del hielo."
  },
  AvgDialog_145534_Content_64 = {
    Text = "Querido, he venido a buscarte."
  },
  AvgDialog_145534_Content_65 = {
    Text = "En medio de una nueva sacudida, Evelyn abrazó con ternura los huesos de su ser amado."
  },
  AvgDialog_145534_Content_66 = {
    Text = "En el Campo de visión de la caída, la montaña nevada abría sus enormes fauces, engullendo aquella pequeña silueta que parecía un pastel de nata y cerezas."
  },
  AvgDialog_145534_Content_67 = {
    Text = "De un solo bocado, en el vientre de las montañas."
  },
  AvgDialog_145534_Content_7 = {
    Text = "<BigShake:¡La montaña os escuchará y luego os \"responderá\"!>"
  },
  AvgDialog_145534_Content_8 = {
    Text = "En un instante, la montaña Surge de repente desde sus cimientos — la nieve blanca se desprende en cascada, el cuerpo segmentado se retuerce y enrosca, alzándose tramo a tramo como un glaciar que se derrumba."
  },
  AvgDialog_145534_Content_9 = {
    Text = "La \"montaña\" entera se irguió con estruendo, inclinándose hacia ellos, y cada centímetro de su reptante avance redujo a polvo el Campo de Nieve bajo sus pies."
  },
  AvgDialog_145535_Content_1 = {
    Text = "Invitados al Festín"
  },
  AvgDialog_145535_Content_10 = {
    Text = "¿Engañar? ¿Y qué si engañé? ¿Acaso no engaña todo el mundo?"
  },
  AvgDialog_145535_Content_11 = {
    Text = "Puedes notarlo, ¿verdad, %player%? Sé que puedes oler las mentiras igual que yo."
  },
  AvgDialog_145535_Content_12 = {
    Text = "<Yellow:Por suerte, me escondí bien y logré escapar de su rastreo.>"
  },
  AvgDialog_145535_Content_13 = {
    Text = "<Yellow:<Big:¡No...! ¡No estoy cansada! ¡NO ME VOY A IR!>>"
  },
  AvgDialog_145535_Content_14 = {
    Text = "<Yellow:Mis otras obligaciones en este mundo han llegado a un fin temporal.>"
  },
  AvgDialog_145535_Content_15 = {
    Text = "Tinct claramente no iba a sobrevivir aquella noche, pero eligió ocultar su Enfermedad. ¿Acaso ella no es una mentirosa?"
  },
  AvgDialog_145535_Content_16 = {
    Text = "Castor, desde el momento en que nos conocimos, ocultó el hecho de cargar con las Alas. ¿Acaso él no es un mentiroso?"
  },
  AvgDialog_145535_Content_17 = {
    Text = "William claramente quería algo más. Algo personal. Pero no quiso contárnoslo. También él es un mentiroso, ¿no es así?"
  },
  AvgDialog_145535_Content_18 = {
    Text = "Todos engañan, todos son mentirosos. ¿Por qué me señalan solo a mí?"
  },
  AvgDialog_145535_Content_19 = {
    Text = "Pero Tinct solo quería seguir avanzando un poco más. En cuanto a las alas de Castor y el deseo secreto de William... eso es asunto suyo."
  },
  AvgDialog_145535_Content_2 = {
    Text = "¿Quién eres realmente?"
  },
  AvgDialog_145535_Content_20 = {
    Text = "No dijeron la verdad, pero tampoco tenían intención de hacerle Daño a nadie."
  },
  AvgDialog_145535_Content_21 = {
    Text = "¿Cómo es que todavía no lo entiendes? Las personas, al vivir en este mundo, las cosas que anhelan — ya sea Fortaleza o deseos — son como esta Manzana —"
  },
  AvgDialog_145535_Content_22 = {
    Text = "Todos la quieren, todos la buscan con desesperación…"
  },
  AvgDialog_145535_Content_23 = {
    Text = "Caraboo lanzó la Manzana al azar, fingió perseguirla y luego se dejó caer dramáticamente sobre un montón de nieve."
  },
  AvgDialog_145535_Content_24 = {Text = "Pero..."},
  AvgDialog_145535_Content_25 = {
    Text = "Siempre, siempre, solo un número limitado de personas puede obtenerla."
  },
  AvgDialog_145535_Content_26 = {
    Text = "Y yo seré su dueña eterna y única."
  },
  AvgDialog_145535_Content_27 = {
    Text = "Pero el medio que usaste para lograr ese objetivo fue Una Mentira."
  },
  AvgDialog_145535_Content_28 = {
    Text = "Sí, ¿acaso Una Mentira no es suficiente?"
  },
  AvgDialog_145535_Content_29 = {
    Text = "Lo que os atrajo no fue algo grandioso ni imponente como el destino o el rey de los dioses, ¡Justo Una Mentira, nada más que una mentira!"
  },
  AvgDialog_145535_Content_3 = {
    Text = "Caraboo soltó una leve carcajada."
  },
  AvgDialog_145535_Content_30 = {
    Text = "Ofrecéis vuestro Mantenimiento a la montaña, y la montaña responde a vuestros deseos según su humor. No es tan diferente de las Deidades del mundo mortal."
  },
  AvgDialog_145535_Content_31 = {
    Text = "Justo esta vez, lo que la montaña exige que ofrendéis es... <RedItalic:todo.>"
  },
  AvgDialog_145535_Content_32 = {
    Text = "¡No te saldrás con la tuya...!"
  },
  AvgDialog_145535_Content_4 = {
    Text = "¿Quién soy realmente?"
  },
  AvgDialog_145535_Content_5 = {
    Text = "¿Acaso no os lo dije desde el principio? Soy la diosa de la montaña nevada, el hada madrina, la encarnación de la voluntad de la Nieve."
  },
  AvgDialog_145535_Content_6 = {
    Text = "Soy el Guía más, más importante y más, más adorable, Caraboo, que ahora va a alimentaros a vosotros a Él."
  },
  AvgDialog_145535_Content_7 = {
    Text = "Caraboo… nos engañaste."
  },
  AvgDialog_145535_Content_8 = {
    Text = "Engañaste a Evelyn, que te cuidó durante todo el Camino, y engañaste a %player%, que en medio de la disputa luchó por darte la oportunidad de quedarte."
  },
  AvgDialog_145535_Content_9 = {
    Text = "¿Es este el resultado que buscabas?"
  },
  AvgDialog_145862_Content_1 = {Text = "Caraboo…"},
  AvgDialog_145862_Content_2 = {
    Text = "Lo que dijiste antes… ¿era verdad?"
  },
  AvgDialog_145862_Content_3 = {
    Text = "¿Qué piensas?"
  },
  AvgDialog_145862_Content_4 = {Text = "No sé..."},
  AvgDialog_145862_Content_5 = {
    Text = "Entonces no pienses en eso. ¡Ten cuidado, vienen enemigos por allí!"
  },
  AvgDialog_146405_Content_1 = {
    Text = "¡Apartaos, dejadme ir a buscarlo!"
  },
  AvgDialog_146405_Content_2 = {
    Text = "¡Pollux me está llamando!"
  },
  AvgDialog_146516_Content_1 = {
    Text = "Maldición, ¿es que estas pústulas no se pueden congelar?"
  },
  AvgDialog_146516_Content_10 = {
    Text = "Hasta ese momento, nadie había prestado atención al tesoro del que hablaba Caraboo."
  },
  AvgDialog_146516_Content_11 = {
    Text = "Al fin y al cabo, ninguna leyenda mencionaba ese elemento."
  },
  AvgDialog_146516_Content_12 = {
    Text = "Solo decían que, al llegar a la cima, vuestros deseos se harían realidad."
  },
  AvgDialog_146516_Content_13 = {Text = "Listo."},
  AvgDialog_146516_Content_14 = {
    Text = "Así que, cuando la bola encadenada de Helot pasó rozando a todos vosotros y enganchó los bultos de cada uno, nadie lo vio venir."
  },
  AvgDialog_146516_Content_15 = {
    Text = "Solo una infinidad de monedas de chocolate doradas salió volando por las rasgaduras de los fardos, derramándose por el precipicio."
  },
  AvgDialog_146516_Content_16 = {
    Text = "Como una lluvia de oro resplandeciente."
  },
  AvgDialog_146516_Content_17 = {
    Text = "<Shake:Tinct… Castor…>"
  },
  AvgDialog_146516_Content_18 = {
    Text = "No sabes qué has perdido.\nPero seguramente habéis perdido algo, algo muy importante."
  },
  AvgDialog_146516_Content_19 = {
    Text = "¡No os rindáis! ¡Ella se dirige al altar en la cima!"
  },
  AvgDialog_146516_Content_2 = {
    Text = "Hm, son criaturas que han crecido entre la nieve desde pequeñas."
  },
  AvgDialog_146516_Content_20 = {
    Text = "¡Mientras el ritual no haya terminado, aún hay oportunidad!"
  },
  AvgDialog_146516_Content_21 = {
    Text = "Caraboo fue la primera en recuperar el ánimo y comenzar a escalar, sin olvidar bajar la cabeza para llamaros."
  },
  AvgDialog_146516_Content_22 = {
    Text = "Por alguna razón, en sus ojos viste una alegría de origen inexplicable."
  },
  AvgDialog_146516_Content_23 = {
    Text = "Haced caso a Caraboo."
  },
  AvgDialog_146516_Content_24 = {
    Text = "Y con Helot: Catena… nos vemos en la cima."
  },
  AvgDialog_146516_Content_25 = {
    Text = "A lo lejos, el perfil de la cima nevada aparecía y desaparecía entre las nubes."
  },
  AvgDialog_146516_Content_26 = {
    Text = "-Altitud 7950 m-"
  },
  AvgDialog_146516_Content_3 = {
    Text = "Las bolas de cadena vuelan por el aire, y tú y William protegéis a Evelyn y a Naraka, aunque apenas podéis con todo."
  },
  AvgDialog_146516_Content_4 = {
    Text = "Caraboo se esconde detrás de algún montón de nieve; la nieve blanca inmaculada oculta su figura."
  },
  AvgDialog_146516_Content_5 = {
    Text = "¿No os parece extraño? Lleva siguiéndonos desde que empezamos a subir la montaña."
  },
  AvgDialog_146516_Content_6 = {
    Text = "¿Por qué lanzar un ataque justo ahora?"
  },
  AvgDialog_146516_Content_7 = {
    Text = "<Shake:Si su objetivo no era matarnos, sino——>"
  },
  AvgDialog_146516_Content_8 = {
    Text = "Ya es demasiado tarde. Las cadenas giratorias separaron a todos y os impidieron prestar atención a vuestro pesado equipaje."
  },
  AvgDialog_146516_Content_9 = {
    Text = "<Big:——¡El tesoro que llevamos en las manos!>"
  },
  AvgDialog_147080_Content_1 = {Text = "..."},
  AvgDialog_147080_Content_10 = {
    Text = "Bien, bien, bien, lo sé. Pero no puedo decíroslo."
  },
  AvgDialog_147080_Content_100 = {
    Text = "Teseo salió del laberinto gracias al hilo de Ariadna, pero su amor no recibió la Bendición de la diosa del destino…"
  },
  AvgDialog_147080_Content_101 = {
    Text = "Al final, el dios del vino Dioniso le obsequió a Ariadna una espléndida corona adornada con siete resplandecientes gemas."
  },
  AvgDialog_147080_Content_102 = {
    Text = "William le lanzó una mirada de reojo a Caraboo."
  },
  AvgDialog_147080_Content_103 = {
    Text = "A pesar de haber viajado juntos y superado dificultades, quizás Teseo y Ariadna estaban destinados a no ser compañeros de camino."
  },
  AvgDialog_147080_Content_104 = {
    Text = "Caraboo apartó la mirada de William."
  },
  AvgDialog_147080_Content_105 = {
    Text = "Una Cáscara vacía que ya ha cumplido su misión, a cambio de un deseo capaz de reescribir el destino, ¿no crees que sales perdiendo?"
  },
  AvgDialog_147080_Content_106 = {
    Text = "El propósito de nuestra ascensión a la montaña era precisamente encontrar al dueño de la Corona a través de esta Corona."
  },
  AvgDialog_147080_Content_107 = {
    Text = "Tú puedes leer directamente la conciencia de Caraboo, y Ella puede observar si estamos diciendo Una Mentira."
  },
  AvgDialog_147080_Content_108 = {
    Text = "Así que puedes estar seguro de que lo que digo ahora es la verdad, ¿verdad?"
  },
  AvgDialog_147080_Content_109 = {
    Text = "<Yellow:Mi carta oculta es precisamente mostrar mi carta oculta>."
  },
  AvgDialog_147080_Content_11 = {
    Text = "Le respondes con una mirada furiosa."
  },
  AvgDialog_147080_Content_110 = {Text = "..."},
  AvgDialog_147080_Content_111 = {
    Text = "<Shake:¡Ja, jajajaja!> Exactamente, incluso se puede aprovechar este mecanismo a la inversa. Hacer negocios con gente inteligente es sencillo."
  },
  AvgDialog_147080_Content_112 = {
    Text = "<Big:¡Prepárense para recuperar su libertad!>"
  },
  AvgDialog_147080_Content_113 = {
    Text = "<Shake:Cuenta regresiva: tres, dos, uno—>"
  },
  AvgDialog_147080_Content_114 = {Text = "—Cero."},
  AvgDialog_147080_Content_115 = {
    Text = "Las paredes de carne de todos lados se cierran sobre ustedes al mismo tiempo. El líquido viscoso que rezuma entre los pliegues se convierte en innumerables tentáculos alargados que se enredan en muñecas, tobillos y cinturas."
  },
  AvgDialog_147080_Content_116 = {
    Text = "Espera, ¿no hay una pequeña diferencia entre esto y la libertad que prometiste—"
  },
  AvgDialog_147080_Content_117 = {
    Text = "Solo prometí sacarlos. Nunca prometí que el viaje sería cómodo."
  },
  AvgDialog_147080_Content_118 = {
    Text = "Una Fuerza irresistible surge desde el suelo."
  },
  AvgDialog_147080_Content_119 = {
    Text = "Son expulsados como un cuerpo extraño tragado que asciende por el esófago, subiendo velozmente por un estrecho y resbaladizo túnel de Carne y sangre."
  },
  AvgDialog_147080_Content_12 = {
    Text = "No te enojes, no te enojes, ahora mismo empiezo a explicar."
  },
  AvgDialog_147080_Content_120 = {
    Text = "El Campo de visión es devorado por la oscuridad. Al oído solo queda el pegajoso sonido de la Carne y sangre rozándose, y el latido sordo y prolongado de toda la montaña."
  },
  AvgDialog_147080_Content_121 = {Text = "Dong."},
  AvgDialog_147080_Content_122 = {Text = "Dong."},
  AvgDialog_147080_Content_123 = {
    Text = "<Red:Bum—>"
  },
  AvgDialog_147080_Content_124 = {
    Text = "Cuando cae el último latido, al frente se abre una cegadora luz blanca."
  },
  AvgDialog_147080_Content_125 = {
    Text = "El Viento furioso arrastra la Nieve Le viento en la cara."
  },
  AvgDialog_147080_Content_126 = {
    Text = "Esa Fuerza los lanza violentamente hacia afuera, y caen de golpe en la Nieve acumulada hasta las rodillas."
  },
  AvgDialog_147080_Content_127 = {
    Text = "Tos… Este tipo definitivamente se está vengando."
  },
  AvgDialog_147080_Content_128 = {
    Text = "Al menos no les cobró la limpieza al hacer el check-out. Según Sus estándares de hospitalidad, eso ya puede considerarse generoso."
  },
  AvgDialog_147080_Content_129 = {
    Text = "Te apoyas en la Nieve y te pones de pie. El persistente olor a Sangre en tus pulmones es finalmente disipado por el gélido Viento."
  },
  AvgDialog_147080_Content_13 = {
    Text = "Para hablar de cómo salir de aquí, primero debemos saber dónde estamos y por qué estamos aquí."
  },
  AvgDialog_147080_Content_130 = {
    Text = "Este lugar ya no es la cresta de la montaña por la que llegaron."
  },
  AvgDialog_147080_Content_131 = {
    Text = "A la vista, todos los picos más bajos están sumergidos bajo un mar de nubes. El cielo negro está tan cerca que parece al alcance de la mano, mientras las Estrellas parpadean intermitentes tras el velo de Nieve levantado por el Viento furioso."
  },
  AvgDialog_147080_Content_132 = {
    Text = "Están de pie en el pico más alto de toda la cordillera."
  },
  AvgDialog_147080_Content_133 = {
    Text = "Este lugar..."
  },
  AvgDialog_147080_Content_134 = {
    Text = "La verdadera cima de la montaña."
  },
  AvgDialog_147080_Content_135 = {
    Text = "Una voz llegó desde debajo de la nieve acumulada."
  },
  AvgDialog_147080_Content_136 = {
    Text = "La capa de hielo tembló levemente, Como Si esta cumbre nevada no fuera más que un fragmento de hueso expuesto de alguna criatura colosal."
  },
  AvgDialog_147080_Content_137 = {
    Text = "El lugar del ritual está justo adelante. Devuelvan los siete artefactos a sus lugares correspondientes y el círculo mágico les indicará qué hacer a continuación."
  },
  AvgDialog_147080_Content_138 = {
    Text = "¿No vienes con nosotros?"
  },
  AvgDialog_147080_Content_139 = {
    Text = "Estoy en todas partes."
  },
  AvgDialog_147080_Content_14 = {
    Text = "Estamos dentro del vientre del Gusano de la Montaña, y la razón por la que el Gusano de la Montaña usó el ritual del deseo para atraerlos a todos aquí..."
  },
  AvgDialog_147080_Content_140 = {
    Text = "Una risa grave y profunda resonó bajo sus pies."
  },
  AvgDialog_147080_Content_141 = {
    Text = "Toda la montaña es mi envoltura. Cada paso que dan, lo dan sobre mi Carne y sangre."
  },
  AvgDialog_147080_Content_142 = {
    Text = "Así que no se les ocurra intentar ningún truco ridículo."
  },
  AvgDialog_147080_Content_143 = {
    Text = "Avancen. Déjenme ver qué clase de Puerta abrirán para mí, ustedes que cargan con tantos deseos."
  },
  AvgDialog_147080_Content_144 = {
    Text = "La nieve acumulada se abrió lentamente ante ustedes."
  },
  AvgDialog_147080_Content_145 = {
    Text = "Una antigua escalinata de piedra, sepultada bajo la Nieve y el Viento durante quién sabe cuántos años, quedó al descubierto, serpenteando hacia la cima."
  },
  AvgDialog_147080_Content_146 = {
    Text = "Y al final de los escalones, siete tenues destellos dorados se encendieron uno tras otro, como Ojos que hubieran dormido mil años y por fin encontraran a quien los Despertara."
  },
  AvgDialog_147080_Content_147 = {
    Text = "William fue el primero en subir los escalones."
  },
  AvgDialog_147080_Content_148 = {
    Text = "Su mano permaneció todo el tiempo apoyada en el interior de su abrigo — Como Si estuviera consolando un deseo que ya había sido abandonado."
  },
  AvgDialog_147080_Content_149 = {
    Text = "En ese momento, nadie se dio cuenta de que aquella Llave que había permanecido en Silencio durante años estaba emitiendo un temblor sumamente tenue a través de la tela."
  },
  AvgDialog_147080_Content_15 = {
    Text = "para Devorar su Fortaleza."
  },
  AvgDialog_147080_Content_150 = {
    Text = "Como Si algo en la cima de la montaña la estuviera esperando."
  },
  AvgDialog_147080_Content_16 = {
    Text = "Una explicación clara y sencilla."
  },
  AvgDialog_147080_Content_17 = {
    Text = "Entonces, la Fortaleza de los demás alpinistas…"
  },
  AvgDialog_147080_Content_18 = {
    Text = "está contenida en estas Ofrendas."
  },
  AvgDialog_147080_Content_19 = {
    Text = "El mecanismo de cooperación entre Caraboo y el Gusano de la Montaña era que Ella seleccionaba Ofrendas con deseos intensos y espiritualidad, atrayendo a los demás a adentrarse en las montañas."
  },
  AvgDialog_147080_Content_2 = {
    Text = "Entonces, estimado señor, ¿qué capricho le llevó a hacer el papel de guía de montaña Sherpa? No será por amor a los deportes extremos humanos, ¿verdad?"
  },
  AvgDialog_147080_Content_20 = {
    Text = "Aquí surge la pregunta: ¿por qué el Gusano de la Montaña rompió activamente esta cooperación?"
  },
  AvgDialog_147080_Content_21 = {
    Text = "Porque sabía que yo había empezado a dudar."
  },
  AvgDialog_147080_Content_22 = {
    Text = "Caraboo mencionó la última conversación en la cima de la cresta."
  },
  AvgDialog_147080_Content_23 = {
    Text = "Antes creía que nadie podía Contador su Codicia, que para cumplir los deseos Solo se podía depender de \"lo no humano\". Pero Ella me hizo entender que conformarse con la vida ordinaria también puede traer felicidad."
  },
  AvgDialog_147080_Content_24 = {
    Text = "En ese instante, surgió en mí un \"deseo\" innecesario."
  },
  AvgDialog_147080_Content_25 = {
    Text = "El \"deseo\" es el cebo, es la mecha."
  },
  AvgDialog_147080_Content_26 = {
    Text = "Desde el principio, yo era la \"Manzana Dorada\" destinada a Ser devorada."
  },
  AvgDialog_147080_Content_27 = {
    Text = "¿Cómo podemos confirmar que no nos estás engañando de nuevo?"
  },
  AvgDialog_147080_Content_28 = {
    Text = "Creerlo o no es cosa tuya. Ahora mismo, soy quien más odia al Gusano de la Montaña de entre todos vosotros."
  },
  AvgDialog_147080_Content_29 = {
    Text = "Si no fuera porque aquella noche de nieve el Gusano de la Montaña me engañó y llegué a un acuerdo con él mediante El Testamento… nunca habría tomado el camino que me trajo hasta aquí."
  },
  AvgDialog_147080_Content_3 = {
    Text = "¿Me creerías si te dijera que es para dar voz al pueblo Sherpa?"
  },
  AvgDialog_147080_Content_30 = {
    Text = "<Small:Maldito embustero>."
  },
  AvgDialog_147080_Content_31 = {
    Text = "En el breve Silencio, solo se oía la nauseabunda respiración de las paredes de Carne y sangre, que subían y bajaban."
  },
  AvgDialog_147080_Content_32 = {
    Text = "Entendido. Siempre Que no hagas nada fuera de lugar, no vamos a exigirte cuentas por el pasado por ahora."
  },
  AvgDialog_147080_Content_33 = {
    Text = "Lo más urgente ahora es encontrar la manera de salir del estómago de esta Deidad… preferiblemente sin recurrir a la Fortaleza del señor N."
  },
  AvgDialog_147080_Content_34 = {
    Text = "Vaya, vaya, ¿así desperdician la buena voluntad del amable y generoso señor N?"
  },
  AvgDialog_147080_Content_35 = {
    Text = "¿O acaso creen que salir de Su vientre es tan sencillo como dejar una habitación de hotel que no les satisface?"
  },
  AvgDialog_147080_Content_36 = {
    Text = "Dijiste que no podías contárnoslo."
  },
  AvgDialog_147080_Content_37 = {
    Text = "¿Creen que lo hago a propósito? Eso me ofende profundamente."
  },
  AvgDialog_147080_Content_38 = {
    Text = "N jugueteaba con la rosa que había surgido de la nada entre sus dedos, y posó La Mirada sobre Caraboo con toda la calma del mundo."
  },
  AvgDialog_147080_Content_39 = {
    Text = "Cualquier método que tenga, no puedo dejarte saberlo. ¿Verdad, pequeña embustera?"
  },
  AvgDialog_147080_Content_4 = {
    Text = "Claro que sí, no solo me creo eso, sino también que la Señora Sorel defiende el laissez-faire, que Ryker se ha retirado del juego para siempre sin volver a tocar una Apuesta, y que Erica es un alma comprensiva con un don para las palabras ingeniosas…"
  },
  AvgDialog_147080_Content_40 = {
    Text = "Caraboo no replicó. Justo se mordió el labio inferior con fuerza y apartó la vista de todos."
  },
  AvgDialog_147080_Content_41 = {Text = "¿Caraboo?"},
  AvgDialog_147080_Content_42 = {
    Text = "…Él puede oírme."
  },
  AvgDialog_147080_Content_43 = {
    Text = "No es una metáfora. Cuando tenía seis años y lo seguí para alejarme de aquella noche de Nieve, empeñé mi alma ante él."
  },
  AvgDialog_147080_Content_44 = {
    Text = "Este es El Testamento entre él y yo. Él me prestó la Fortaleza de \"Una Mentira\", permitiéndome engañar a todos en este mundo; y como precio—"
  },
  AvgDialog_147080_Content_45 = {
    Text = "Ante él, no puedo ocultar ningún pensamiento."
  },
  AvgDialog_147080_Content_46 = {
    Text = "…Entonces, en este momento, cada palabra que decimos—"
  },
  AvgDialog_147080_Content_47 = {
    Text = "Siempre Que llegue a mis oídos y entre en mi cabeza, él lo sabrá todo."
  },
  AvgDialog_147080_Content_48 = {
    Text = "La Carne y sangre que los rodeaba se tensó bruscamente un instante y luego se fue relajando poco a poco. Como si alguna criatura colosal estuviera escondida tras el telón, escuchando todo aquello con gran interés."
  },
  AvgDialog_147080_Content_49 = {
    Text = "¿Ahora lo entienden?"
  },
  AvgDialog_147080_Content_5 = {
    Text = "Ahora no es momento de discutir."
  },
  AvgDialog_147080_Content_50 = {
    Text = "Siempre ha habido una manera. Pero si llega a oídos de esta joven señorita, es como si jugaras al Texas Hold'em con tus cartas ganadoras boca arriba."
  },
  AvgDialog_147080_Content_51 = {
    Text = "¿Podría Caraboo Evadir la situación mientras discutimos el plan?"
  },
  AvgDialog_147080_Content_52 = {
    Text = "Incluso si no escucho su plan, podría notar algo inusual durante la ejecución."
  },
  AvgDialog_147080_Content_53 = {
    Text = "No puedo ver tus microexpresiones, tus pequeños gestos. De lo contrario, sabría qué frase es Una Mentira."
  },
  AvgDialog_147080_Content_54 = {
    Text = "Quizás, ¿podrías no mirar?"
  },
  AvgDialog_147080_Content_55 = {
    Text = "No, Una Mentira es un ambiente que fluye… y yo llevo demasiado tiempo sumergida en él."
  },
  AvgDialog_147080_Content_56 = {
    Text = "A veces, aunque nadie hable, puedo sentir la presencia de Una Mentira en el aire inmóvil."
  },
  AvgDialog_147080_Content_57 = {
    Text = "Déjame intentarlo."
  },
  AvgDialog_147080_Content_58 = {
    Text = "Acompañado de un nítido chasquido de dedos, una oscura niebla trepó hasta los ojos de Caraboo."
  },
  AvgDialog_147080_Content_59 = {
    Text = "Bien, Abre los ojos."
  },
  AvgDialog_147080_Content_6 = {
    Text = "Arachne nos ha traído hasta aquí, seguro que tiene sus razones. Y tú debes de ser un eslabón del destino."
  },
  AvgDialog_147080_Content_60 = {
    Text = "Caraboo Abre los ojos. Todo lo que tenía ante Ella estaba envuelto en una capa de humo de Distorsión, y hasta los sonidos se volvieron confusos y lejanos."
  },
  AvgDialog_147080_Content_61 = {
    Text = "William, en cambio, bajó la mirada de repente, apoyando los nudillos en la barbilla, como si estuviera trazando una Proyección de una partida de ajedrez que Solo él podía ver."
  },
  AvgDialog_147080_Content_62 = {Text = "Detente."},
  AvgDialog_147080_Content_63 = {Text = "¿Hm?"},
  AvgDialog_147080_Content_64 = {
    Text = "No es necesario cubrirle los Ojos."
  },
  AvgDialog_147080_Content_65 = {
    Text = "Todo lo contrario: a partir de ahora, espero que Caraboo esté completamente alerta para discernir la veracidad de cada palabra que diga."
  },
  AvgDialog_147080_Content_66 = {
    Text = "Escucha bien, Caraboo — o más bien, el Gusano de la Montaña que está detrás de Caraboo. Quiero hacer un trato contigo."
  },
  AvgDialog_147080_Content_67 = {
    Text = "Las paredes de carne temblaron con algo parecido a una carcajada burlona."
  },
  AvgDialog_147080_Content_68 = {
    Text = "Qué chiste. Estáis dentro de mi vientre. ¿Con qué pretendes negociar conmigo?"
  },
  AvgDialog_147080_Content_69 = {Text = "Un deseo."},
  AvgDialog_147080_Content_7 = {
    Text = "Sabes cómo salir de aquí, ¿verdad, N?"
  },
  AvgDialog_147080_Content_70 = {
    Text = "De repente, todo a su alrededor quedó en silencio."
  },
  AvgDialog_147080_Content_71 = {
    Text = "El círculo de deseos en la cima de la montaña <Yellow:no fue creado por ti>, sino por algo más antiguo que tú, ¿verdad?"
  },
  AvgDialog_147080_Content_72 = {Text = "..."},
  AvgDialog_147080_Content_73 = {
    Text = "El Gusano de la Montaña guardó silencio un instante y luego soltó una risa ambigua."
  },
  AvgDialog_147080_Content_74 = {
    Text = "Interesante. Continúa."
  },
  AvgDialog_147080_Content_75 = {
    Text = "Antes de esta ascensión, la leyenda que Caraboo relató difería un poco de la que circula entre los montañeses. En pocas palabras, los montañeses solo saben que llegar a la cima puede conceder deseos, pero desconocen la existencia de los siete artefactos rituales."
  },
  AvgDialog_147080_Content_76 = {
    Text = "Tiene sentido. Si el único propósito fuera atraer a los humanos para que escalen la montaña y luego devorarlos, no habría necesidad de tejer la leyenda de los siete artefactos rituales."
  },
  AvgDialog_147080_Content_77 = {
    Text = "Bastaría con decirle a todo el mundo que llegar a la cima concede deseos."
  },
  AvgDialog_147080_Content_78 = {
    Text = "A mayor dificultad, menos desafiantes. Esa lógica básica no puede escapárseos, a menos que—"
  },
  AvgDialog_147080_Content_79 = {
    Text = "A menos que—"
  },
  AvgDialog_147080_Content_8 = {
    Text = "Sé… o quizás no sé… Vaya, qué pregunta tan interesante."
  },
  AvgDialog_147080_Content_80 = {
    Text = "El Gusano de la Montaña alargó su tono con sarcasmo burlón."
  },
  AvgDialog_147080_Content_81 = {
    Text = "A menos que los siete artefactos rituales existan de verdad, y el ritual para conceder deseos también exista de verdad."
  },
  AvgDialog_147080_Content_82 = {
    Text = "Y tú, apostado junto al círculo ritual, no estás aquí solo para devorar a los escaladores.\nTambién aguardas una oportunidad para activar el ritual."
  },
  AvgDialog_147080_Content_83 = {
    Text = "El mundo de Carne y sangre dejó de respirar."
  },
  AvgDialog_147080_Content_84 = {
    Text = "Si llevas tanto tiempo custodiando el ritual, ¿por qué no lo activas tú mismo?"
  },
  AvgDialog_147080_Content_85 = {
    Text = "Humano, haces demasiadas preguntas."
  },
  AvgDialog_147080_Content_86 = {
    Text = "Parece que pregunté lo correcto."
  },
  AvgDialog_147080_Content_87 = {
    Text = "Déjame adivinar."
  },
  AvgDialog_147080_Content_88 = {
    Text = "En el círculo mágico existe un núcleo que no puedes descifrar, ¿verdad? Por eso, durante todos estos años, has acumulado una y otra vez Ofrendas, pero nunca has podido abrir esa última Puerta."
  },
  AvgDialog_147080_Content_89 = {
    Text = "Las paredes de carne se contrajeron de repente, Casi aplastando a todos."
  },
  AvgDialog_147080_Content_9 = {
    Text = "No te andes con rodeos, habla directamente."
  },
  AvgDialog_147080_Content_90 = {
    Text = "Sé por qué no puedes descifrarlo. Hace un momento eché un vistazo al círculo mágico, y las runas grabadas en él contienen latín y otros caracteres antiguos."
  },
  AvgDialog_147080_Content_91 = {
    Text = "Y esta… pequeña Executor tuya, calculando desde el tiempo en que abandonó Nuestro Hogar, es evidente que nunca recibió una buena educación académica…"
  },
  AvgDialog_147080_Content_92 = {
    Text = "<Shake:¡¿Y a ti qué te importa que no sepa leer?!>"
  },
  AvgDialog_147080_Content_93 = {
    Text = "El tiempo era escaso, y antes de poder leerlo con detalle ya me habías tragado aquí. Pero supongo que lo que está Registrado en él tiene que ver en su mayor parte con el conocimiento relacionado con la activación del círculo mágico."
  },
  AvgDialog_147080_Content_94 = {
    Text = "La diosa del destino nos ha guiado hasta aquí, los siete artefactos ya están reunidos. Deberías saber que esta es la vez que más cerca has estado de cumplir tu deseo."
  },
  AvgDialog_147080_Content_95 = {
    Text = "Y nosotros podemos <Yellow:renunciar voluntariamente a la oportunidad de pedir un deseo a la montaña>."
  },
  AvgDialog_147080_Content_96 = {
    Text = "El gusano de la montaña cayó en un largo Silencio. Cuando ya creíais que no respondería, emitió un suave gruñido."
  },
  AvgDialog_147080_Content_97 = {
    Text = "Renunciar a un deseo… vaya Sacrificio tan admirable. Lo que quieres no es solo que os deje salir, ¿verdad?"
  },
  AvgDialog_147080_Content_98 = {
    Text = "Después del ritual, todos los demás artefactos pueden quedarse contigo, pero nosotros nos llevaremos la <Blue:Corona de Ariadna>."
  },
  AvgDialog_147080_Content_99 = {
    Text = "La Corona de Ariadna…"
  },
  AvgDialog_147095_Content_1 = {
    Text = "En el salón vacío, solo resuenan los pasos de tú y Murphy."
  },
  AvgDialog_149752_Content_1 = {
    Text = "Guarida del Dragón"
  },
  AvgDialog_149752_Content_10 = {
    Text = "Ya no tienes nada, no puedes soportar el olvido una vez más."
  },
  AvgDialog_149752_Content_11 = {
    Text = "Las llamas que ardían con fuerza han sido apagadas por la lluvia. Atraviesas la puerta sin guardia y contemplas el caos que lo cubre todo."
  },
  AvgDialog_149752_Content_12 = {
    Text = "El castillo se alza en el silencio: barriles vacíos, sacos rotos, escudos destrozados, lanzas partidas, flechas que se doblan como juncos al viento, y el olor a barro húmedo mezclado con el persistente hedor a quemado."
  },
  AvgDialog_149752_Content_13 = {
    Text = "Aquí hubo una batalla, y ahora solo quedan sombras."
  },
  AvgDialog_149752_Content_14 = {
    Text = "Las sombras se extienden sin freno por la oscuridad, trepan por los muros, se arrastran por las almenas, engullen los cadáveres tendidos en el suelo y emiten un sonido húmedo y viscoso. Procuras no pensar en lo que eso significa."
  },
  AvgDialog_149752_Content_15 = {
    Text = "Sigue a las sombras… solo tienes que seguir a las sombras…"
  },
  AvgDialog_149752_Content_16 = {
    Text = "Ugh, ugh… sál… sálvame…"
  },
  AvgDialog_149752_Content_17 = {
    Text = "Bajo el yelmo deformado llegan gemidos de agonía, y las sombras se acurrucan junto a él como un amante íntimo. Armándote de valor, te acercas."
  },
  AvgDialog_149752_Content_18 = {
    Text = "Ese hombre que trajo las sombras… ¿adónde fue?"
  },
  AvgDialog_149752_Content_19 = {
    Text = "<Shake:¿Som… bras? No, no, ¡era un monstruo! Sangre negra… hueco por dentro… caballero de la muerte… ¡es verdad, todo es verdad!>"
  },
  AvgDialog_149752_Content_2 = {
    Text = "¿Qué es un pacto? Una magia que solo se hace realidad si se cree en ella."
  },
  AvgDialog_149752_Content_20 = {
    Text = "<Shake:Huye… ugh… ¡huye rápido! Un monstruo inmortal… venganza… destrucción… glu… glu glu glu…>"
  },
  AvgDialog_149752_Content_21 = {
    Text = "De la garganta del monstruo brotan sonidos espesos y viscosos. Se convulsiona como un pez varado, pero su brazo se eleva lentamente hacia el paquete que llevas en el pecho, mientras por las juntas de la armadura rezuma un lodo blando y retorcido."
  },
  AvgDialog_149752_Content_22 = {
    Text = "Son las sombras. Quieren el cáliz sagrado."
  },
  AvgDialog_149752_Content_23 = {
    Text = "No, imposible. Esto es algo importante, no puedo dártelo."
  },
  AvgDialog_149752_Content_24 = {
    Text = "La negativa no surte efecto. Las sombras se deslizan por los muros y se precipitan velozmente hacia ti. Aprietas el paquete contra tu pecho con desesperación y corres hacia las profundidades del castillo."
  },
  AvgDialog_149752_Content_25 = {
    Text = "La torre del portal, el gran salón, la capilla… una escalera de piedra que serpentea hacia las entrañas de la tierra. El castillo es un peligroso nido de dragones. El aire se vuelve cada vez más frío, y tus jadeos y pasos se amplifican entre los muros de piedra, como si pertenecieran a otra persona."
  },
  AvgDialog_149752_Content_26 = {
    Text = "Al final de la escalera de caracol brilló una llama, y reconociste una silueta familiar."
  },
  AvgDialog_149752_Content_27 = {Text = "O——"},
  AvgDialog_149752_Content_28 = {
    Text = "Estabas a punto de llamarlo con alegría cuando de repente te diste cuenta de que no erais los únicos. El monstruo tomó la palabra antes que tú."
  },
  AvgDialog_149752_Content_29 = {
    Text = "<Shake:Tos, tos, tos, tos… Ogier…>"
  },
  AvgDialog_149752_Content_3 = {
    Text = "¿Qué es la separación? El instante que sigue a la llegada."
  },
  AvgDialog_149752_Content_30 = {
    Text = "¿Cómo has llegado a este estado?"
  },
  AvgDialog_149752_Content_31 = {
    Text = "¿Mi… estado?"
  },
  AvgDialog_149752_Content_32 = {
    Text = "Sobre la mesa había vino exquisito y manjares, la vajilla de plata relucía a la luz de las velas, y de no ser por el frío cortante que se filtraba entre las grietas de la piedra, aquella cuidadosa disposición casi habría hecho olvidar que se estaba en las profundidades de la oscuridad."
  },
  AvgDialog_149752_Content_33 = {
    Text = "El señor demacrado estaba sentado solo tras la mesa, con los ojos hundidos y los pómulos prominentes, enterrado bajo capas de pesada seda, como un dragón maligno agazapado entre oro y plata."
  },
  AvgDialog_149752_Content_34 = {
    Text = "Tu caballero avanzaba paso a paso hacia él, arrastrando una larga sombra a sus espaldas. Quizás él mismo era también una sombra. Sus ropas estaban andrajosas, su rostro era terrible, y sus pasos no hacían ningún ruido."
  },
  AvgDialog_149752_Content_35 = {
    Text = "Sí, de no haberlo visto con mis propios ojos, casi no podría creerlo… tos, tos, tos… el caballero más joven del ducado, convertido en un monstruo."
  },
  AvgDialog_149752_Content_36 = {
    Text = "El ducado… ya ha sido destruido."
  },
  AvgDialog_149752_Content_37 = {
    Text = "Por tu culpa."
  },
  AvgDialog_149752_Content_38 = {
    Text = "Por la guerra, por la plaga, por la codicia de los países vecinos, por la propia debilidad. Son muchas las razones que pueden llevar a un ducado a su ruina, y yo solo soy, tos tos, la más insignificante de todas ellas."
  },
  AvgDialog_149752_Content_39 = {
    Text = "<Shake:Tú… traicionaste al ducado… confabulaste con el enemigo… vendiste… a los súbditos…>"
  },
  AvgDialog_149752_Content_4 = {
    Text = "¿Qué es la muerte? Un mañana sin despedida."
  },
  AvgDialog_149752_Content_40 = {
    Text = "<Shake:Traidor… mereces morir.>"
  },
  AvgDialog_149752_Content_41 = {
    Text = "Sí, sí, como puedes ver, las consecuencias ya han caído sobre mí. Me queda poco tiempo, tos, tos, tos, tos."
  },
  AvgDialog_149752_Content_42 = {
    Text = "La plaga no me ha perdonado, Ogier. La muerte no hace distinciones, espera con paciencia al otro lado del puente, nadie puede escapar de ella… excepto tú."
  },
  AvgDialog_149752_Content_43 = {
    Text = "Dime, ¿qué trato hiciste con el diablo?"
  },
  AvgDialog_149752_Content_44 = {Text = "..."},
  AvgDialog_149752_Content_45 = {
    Text = "El precio de huir de la muerte siempre será más pesado que la muerte misma. Caballero de la Muerte… convertirte en su verdugo, ¿fue un deseo que pediste o un castigo que recibiste?"
  },
  AvgDialog_149752_Content_46 = {
    Text = "Ogier, el caballero más leal y devoto del ducado, ja, <Shake:tos, tos, tos, tos, tos…>"
  },
  AvgDialog_149752_Content_47 = {
    Text = "Soy un maldito traidor, ¿acaso tú no lo eres?"
  },
  AvgDialog_149752_Content_48 = {Text = "¡¡!!"},
  AvgDialog_149752_Content_49 = {
    Text = "Un rayo invisible golpeó a tu caballero, clavándolo firmemente en el lugar. Las sombras en la oscuridad temblaron violentamente, jubilosas o furiosas, ya no podían contenerse más."
  },
  AvgDialog_149752_Content_5 = {
    Text = "¿Qué es el olvido?"
  },
  AvgDialog_149752_Content_50 = {
    Text = "Yo traicioné al Gran Duque, pero tú, tú y tu princesa, vosotros traicionasteis a los dioses."
  },
  AvgDialog_149752_Content_51 = {
    Text = "¿Aún recuerdas...? ¿Cómo te atreves a mencionarlo...?"
  },
  AvgDialog_149752_Content_52 = {
    Text = "<Red:La princesa bruja>, tos tos tos, qué ironía, sus trucos finalmente quedaron al descubierto, y sin embargo nadie recuerda siquiera su nombre. Siempre lo dije: entregadla y el fuego de la guerra se apagaría, el ducado no tendría que haber caído."
  },
  AvgDialog_149752_Content_53 = {
    Text = "Sabes lo que ella atrajo, lo sabes muy bien. La maldición... la guerra comenzó por ella, y por ella terminó. Gracias a ella, @3el ducado se convirtió en un lugar olvidado."
  },
  AvgDialog_149752_Content_54 = {
    Text = "¡Cállate! ¡Tú... no mereces... mencionarla!"
  },
  AvgDialog_149752_Content_55 = {
    Text = "La lanza amorfa partió la larga mesa en dos, copas y platos cayeron al suelo estrepitosamente, el falso banquete quedó hecho añicos, revelando su verdadero rostro de caos."
  },
  AvgDialog_149752_Content_56 = {
    Text = "Las sombras extendieron pseudópodos viscosos, devorando ávidamente todo lo que tocaban; el pantano brotó desde la oscuridad sin luz, y el mundo comenzó a hundirse."
  },
  AvgDialog_149752_Content_57 = {
    Text = "La muerte... y luego el olvido... como si nunca hubiera ocurrido. Este es el destino de quienes abandonan a los dioses."
  },
  AvgDialog_149752_Content_58 = {
    Text = "Fue ella quien te convirtió en esto... arrastró a todo el ducado al vacío y dejó atrás a un títere lleno de odio, sembrando la muerte real por toda la tierra. ¿A eso que llevas a cabo lo llamas lealtad?"
  },
  AvgDialog_149752_Content_59 = {
    Text = "Ogier... ¿a quién sirves realmente?"
  },
  AvgDialog_149752_Content_6 = {Text = "..."},
  AvgDialog_149752_Content_60 = {
    Text = "<Shake:No... no... la princesa no es... glu... gluglu...>"
  },
  AvgDialog_149752_Content_61 = {
    Text = "Tu caballero se aferró la cabeza con agonía, las sombras brotaron de su pecho, de sus oídos, de las comisuras de sus ojos. El tormento incesante del demonio lo había debilitado; ya no podía emitir sonido alguno, como un muñeco de barro disolviéndose en aguas negras."
  },
  AvgDialog_149752_Content_62 = {
    Text = "En un momento en que ninguno de vosotros prestaba atención, el señor giró su silla de ruedas; en la pared de piedra a sus espaldas había una tronera del tamaño de un puño. Una sombra negra como una serpiente cruzó ante vuestros ojos, acompañada de un golpe sordo, y una lanza de hierro atravesó el pecho de tu caballero."
  },
  AvgDialog_149752_Content_63 = {
    Text = "<Big:¡¡¡Ogier!!!>"
  },
  AvgDialog_149752_Content_64 = {
    Text = "<Shake:Tos tos tos tos...> Los monstruos que salen arrastrándose de sus tumbas harían mejor en volver a ellas cuanto antes."
  },
  AvgDialog_149752_Content_65 = {
    Text = "Tú y tu pequeño monstruo, quedaos enterrados aquí juntos."
  },
  AvgDialog_149752_Content_66 = {
    Text = "Varios guardias completamente armados emergieron del pasadizo secreto; escudos y espadas destellaban con un brillo siniestro, y la trampa final salió por fin a la luz."
  },
  AvgDialog_149752_Content_7 = {Text = "..."},
  AvgDialog_149752_Content_8 = {
    Text = "<Red:Una maldición.>"
  },
  AvgDialog_149752_Content_9 = {
    Text = "Maldición. Plaga. Castigo. El vacío carcomido por gusanos. El lecho del río resquebrajado. Pudrirse en el silencio. Erosionarse. Hundirse. Una mirada agotada. Desvanecerse de la historia hasta convertirse en sombra. La última muerte."
  },
  AvgDialog_149753_Content_1 = {
    Text = "Cáliz Sagrado"
  },
  AvgDialog_149753_Content_10 = {
    Text = "Nada de lo que hago es propio de un caballero, ya lo has visto."
  },
  AvgDialog_149753_Content_11 = {
    Text = "¿Por qué? Los caballeros deben luchar contra los monstruos, ese es tu deber, y lo haces muy bien."
  },
  AvgDialog_149753_Content_12 = {
    Text = "Y además estás buscando algo, ¿verdad? Me he dado cuenta. Llevas buscando de un lugar a otro desde que entramos a la ciudad, ya van varios días. ¿Los monstruos también te robaron algo?"
  },
  AvgDialog_149753_Content_13 = {Text = "..."},
  AvgDialog_149753_Content_14 = {
    Text = "\"Estamos aquí.\""
  },
  AvgDialog_149753_Content_15 = {
    Text = "La cálida y tentadora luz de las velas llenaba las cuatro paredes, la puerta de roble bloqueaba el viento frío; para los vagabundos sin hogar, el almacén del monasterio abierto en una noche de lluvia podía incluso salvar vidas."
  },
  AvgDialog_149753_Content_16 = {
    Text = "Pero no te dejarías engañar por las apariencias, los recuerdas. Aquellos que deambulaban con candelabros de un lado a otro, con túnicas negras y colgantes de latón, los verdugos que se llamaban a sí mismos pastores: eran monstruos entre los monstruos."
  },
  AvgDialog_149753_Content_17 = {
    Text = "<Small:¿Por qué hemos venido aquí… lo que buscas está aquí?>"
  },
  AvgDialog_149753_Content_18 = {
    Text = "Quédate aquí y espérame, no me sigas."
  },
  AvgDialog_149753_Content_19 = {
    Text = "<Big:¿Qué?! ¡No! ¡De ninguna manera!>"
  },
  AvgDialog_149753_Content_2 = {
    Text = "<Shake:No lo sé, no sé que eso era — no, no, no, por favor, por favor, perdóneme —>"
  },
  AvgDialog_149753_Content_20 = {
    Text = "<Big:¡No me quedo aquí, no me quedaré aquí bajo ningún concepto! ¡Quiero ir contigo!>"
  },
  AvgDialog_149753_Content_21 = {
    Text = "¿Qué ocurre? Niña, ¿necesitas ayuda?"
  },
  AvgDialog_149753_Content_22 = {
    Text = "Sí, por favor cuídela y no la deje escapar."
  },
  AvgDialog_149753_Content_23 = {
    Text = "Oh… a estas horas, con esta lluvia tan fuerte, ¿adónde vas con tanta prisa? Espera a que salga el sol, no dejes a tu hermanita sola."
  },
  AvgDialog_149753_Content_24 = {
    Text = "Vendré a buscarla cuando amanezca."
  },
  AvgDialog_149753_Content_25 = {
    Text = "Si insistes, está bien, está bien. Pobrecita, empapada de arriba abajo, ven, acércate, déjame que te seque la cara."
  },
  AvgDialog_149753_Content_26 = {
    Text = "Estás atrapada, sin poder moverte, una tela de lino seca roza tus mejillas, y no sabes en qué momento podría cubrirte la boca y la nariz."
  },
  AvgDialog_149753_Content_27 = {
    Text = "El miedo aplasta tu pecho, no puedes respirar, solo puedes gritar."
  },
  AvgDialog_149753_Content_28 = {
    Text = "<Shake:¡Vuelve! Eres mi caballero, debes protegerme, no puedes abandonarme — ¡me lo prometiste!>"
  },
  AvgDialog_149753_Content_29 = {
    Text = "<Shake:Por favor, no causaré problemas, déjame ir contigo!>!"
  },
  AvgDialog_149753_Content_3 = {Text = "¡Ah!!"},
  AvgDialog_149753_Content_30 = {
    Text = "Muchos ojos fueron atraídos por tus gritos desesperados, algunos parecían de escarabajo, otros de cabra, otros de búho."
  },
  AvgDialog_149753_Content_31 = {
    Text = "Te miraban fijamente, como si solo tú fueras la que no tenía ojos."
  },
  AvgDialog_149753_Content_32 = {
    Text = "<SmallShake:No… no te vayas… me lo habías prometido…>"
  },
  AvgDialog_149753_Content_33 = {
    Text = "<SmallShake:Por favor, no me abandones…>"
  },
  AvgDialog_149753_Content_34 = {
    Text = "He cambiado de opinión, déjala venir conmigo."
  },
  AvgDialog_149753_Content_35 = {
    Text = "Alzas la cabeza de golpe, tu caballero había regresado sin que supieras cuándo, bloqueando con su espalda todas las miradas de los monstruos."
  },
  AvgDialog_149753_Content_36 = {
    Text = "Pero ¿adónde piensas llevarla? Hay pocos lugares en la ciudad donde refugiarse de la lluvia, y ninguno es apropiado para una niña."
  },
  AvgDialog_149753_Content_37 = {
    Text = "El lugar al que voy no está en la ciudad."
  },
  AvgDialog_149753_Content_38 = {
    Text = "Fuera de la ciudad hay aún menos — ¡ah! ¿Acaso vas a ir a esa mansión?"
  },
  AvgDialog_149753_Content_39 = {
    Text = "¿Qué pasa con esa mansión?"
  },
  AvgDialog_149753_Content_4 = {
    Text = "Los gritos fueron apagados por la lluvia torrencial, mezclándose con sangre que corría hacia las cunetas junto a los muros, pudriéndose entre el barro, el estiércol de caballo y las hojas de verdura, hasta ser engullidos por el callejón oscuro."
  },
  AvgDialog_149753_Content_40 = {
    Text = "Ese lugar, ese lugar… ay, vosotros también venís huyendo, ¿verdad? Niña, no te acerques a ese sitio."
  },
  AvgDialog_149753_Content_41 = {
    Text = "Ese señor, en otro tiempo fue un buen hombre, pero la guerra, la peste, las calamidades subían y bajaban como mareas, y la gente dejó de ser gente. Todos dicen que se volvió loco. Cada vez hay menos gente en la ciudad, y los que fueron a pedir pan nunca regresaron."
  },
  AvgDialog_149753_Content_42 = {
    Text = "Que el Señor perdone… todos dicen que come personas a escondidas."
  },
  AvgDialog_149753_Content_43 = {
    Text = "Los monstruos comen personas, lo sabías desde hace tiempo, así que no te sorprende nada, ni sientes miedo… al menos no tanto miedo. Tienes a tu caballero."
  },
  AvgDialog_149753_Content_44 = {
    Text = "Sígueme de cerca, aquí algo no está bien."
  },
  AvgDialog_149753_Content_45 = {
    Text = "Está bien, está bien."
  },
  AvgDialog_149753_Content_46 = {
    Text = "La enorme mansión estaba completamente vacía, sin guardias ni sirvientes, como si llevara mucho tiempo abandonada, y en los largos corredores solo se escuchaban vuestros pasos deliberadamente silenciosos."
  },
  AvgDialog_149753_Content_47 = {
    Text = "Entonces… ¿qué estás buscando exactamente? ¿Es importante para ti? Dime cómo es y yo también puedo ayudarte a encontrarlo."
  },
  AvgDialog_149753_Content_48 = {
    Text = "Una copa de oro."
  },
  AvgDialog_149753_Content_49 = {
    Text = "¿Una copa de oro? ¿Quieres decir hecha de oro? Vaya, ¿qué tan grande es, qué tan alta? ¿Para qué se usa? ¿Cómo es el oro, brilla por la noche como la luna?"
  },
  AvgDialog_149753_Content_5 = {
    Text = "El cadáver cayó al suelo sin fuerzas, el frío destello del metal brilló un instante y desapareció, el asesino se ciñó la capa y se alejó a paso rápido, sus pisadas también se desvanecieron en la lluvia."
  },
  AvgDialog_149753_Content_50 = {Text = "...No sé."},
  AvgDialog_149753_Content_51 = {
    Text = "¿Eh? ¿No es tuya?"
  },
  AvgDialog_149753_Content_52 = {
    Text = "No, pero es muy importante para mí."
  },
  AvgDialog_149753_Content_53 = {
    Text = "¡Oh! Ya entiendo, es el Santo Grial, ¿verdad? Lo escuché en un cuento, un tesoro mágico que solo puede obtener el caballero que supere las pruebas. No me extraña que lleves tanto tiempo buscándolo."
  },
  AvgDialog_149753_Content_54 = {
    Text = "Ejem, ejem, como tu princesa, si pudieras obtener el Santo Grial, también me beneficiaría a mí, así que…"
  },
  AvgDialog_149753_Content_55 = {
    Text = "De repente se detuvo, levantó el dedo índice y te hizo un gesto de silencio."
  },
  AvgDialog_149753_Content_56 = {
    Text = "Te quedaste inmóvil al instante, conteniendo el aliento sin darte cuenta. La Linterna se apagó y la oscuridad te envolvió por completo, hermética e impenetrable."
  },
  AvgDialog_149753_Content_57 = {
    Text = "Contaste catorce latidos del corazón cuando, al fondo del pasillo, resonó un golpe sordo acompañado del estrépito de objetos al caer y romperse, y varios gritos descontrolados rompieron el silencio."
  },
  AvgDialog_149753_Content_58 = {
    Text = "Apareció una luz, parpadeante, como las siluetas de muchas personas en plena lucha. Corriste hacia allí, pero una ola de calor te obligó a retroceder. Era fuego, fuego azul."
  },
  AvgDialog_149753_Content_59 = {
    Text = "¡Suél— ejem, ejem— suéltame! ¡Estaba a punto de lograrlo! ¡Solo un poco más, solo un poco más!"
  },
  AvgDialog_149753_Content_6 = {
    Text = "Te apresuraste a ponerte la capucha y corriste bajo la lluvia para poder seguirle a duras penas."
  },
  AvgDialog_149753_Content_60 = {
    Text = "La cámara secreta estaba impregnada de un olor acre. Un líquido rojizo sospechoso fluía lentamente por tubos de cristal, las velas habían prendido fuego al líquido derramado en el suelo, y llamas azul pálido ardían en silencio. En lo más profundo de la mansión se ocultaba una cámara alquímica secreta."
  },
  AvgDialog_149753_Content_61 = {
    Text = "En medio de numerosos recipientes de cristal, una copa de pie de oro puro resplandecía con una luz más brillante que el Wick. Sin duda era el Santo Grial."
  },
  AvgDialog_149753_Content_62 = {
    Text = "¿Qué pusiste dentro?"
  },
  AvgDialog_149753_Content_63 = {
    Text = "¡Suéltame! ¡No lo entiendes! Ya casi llega, ya casi llega… Atravesando los cortinajes podridos, extendiéndose por el sendero del olvido. Los vivos, los muertos, nadie puede escapar… nadie puede escapar…"
  },
  AvgDialog_149753_Content_64 = {Text = "¿Ello?"},
  AvgDialog_149753_Content_65 = {
    Text = "Ello… la noche eterna sin fin, la extinción definitiva… es una maldición… <Shake:¡La maldición está por llegar! La maldición que todo lo devora, ¡¡la maldición de la <Red:princesa bruja>!!>"
  },
  AvgDialog_149753_Content_66 = {
    Text = "¿Qué dijiste?!"
  },
  AvgDialog_149753_Content_67 = {
    Text = "La sombra detrás de él tembló violentamente. Las llamas cayeron en sus ojos, abiertos de par en par por el horror. ¿Encendieron algo? ¿Miedo, o esperanza?"
  },
  AvgDialog_149753_Content_68 = {
    Text = "En esas palabras debía de ocultarse algún poderoso conjuro, porque tu caballero se quedó de repente petrificado como una estatua de piedra, como si cobrara vida por primera vez. Su sombra no dejaba de temblar."
  },
  AvgDialog_149753_Content_69 = {
    Text = "Tú, tú… ¿la recuerdas? ¿Qué más recuerdas?"
  },
  AvgDialog_149753_Content_7 = {
    Text = "¿Qué estás buscando?"
  },
  AvgDialog_149753_Content_70 = {
    Text = "<Shake:Vanidad, vanidad de vanidades, todo es vanidad… Los hombres se afanan como polvo sobre piedra, sin pasado, sin futuro…>"
  },
  AvgDialog_149753_Content_71 = {
    Text = "No, ¡la copa de oro! ¡La copa de oro es la única salvación! Déjame beber la verdad, déjame— ¡debo continuar!"
  },
  AvgDialog_149753_Content_72 = {
    Text = "<Big:¡Responde mi pregunta! @1@2Princesa, ¿cuánto recuerdas de lo que tiene que ver con ella?!>"
  },
  AvgDialog_149753_Content_73 = {
    Text = "Las sombras se agitan, las sombras se revuelven, las sombras danzan frenéticas, las sombras se aprietan en círculos alrededor del cuello del monstruo, y sus dos labios se abren y cierran en vano."
  },
  AvgDialog_149753_Content_74 = {
    Text = "<Shake:Recuerdo… la plaga… el brebaje… la maldición… crac, crac… recuerdo, te recuerdo a ti…>"
  },
  AvgDialog_149753_Content_75 = {
    Text = "<Shake:<Red:Au… gil>… mi caballero… tú… huye…>"
  },
  AvgDialog_149753_Content_76 = {Text = "\"Crac.\""},
  AvgDialog_149753_Content_77 = {
    Text = "Las palabras quedaron inconclusas, pues ya no podía continuar; las sombras le quebraron el cuello. La cabeza hinchada, como un saco de arpillera bien atado, cayó lánguidamente hacia un lado, y por los agujeros asomaron dos globos oculares oxidados que seguían clavados en el vacío."
  },
  AvgDialog_149753_Content_78 = {Text = "..."},
  AvgDialog_149753_Content_79 = {
    Text = "Au… gil? ¿Acaso ese es… tu nombre?"
  },
  AvgDialog_149753_Content_8 = {
    Text = "No te prometí que pudieras seguirme."
  },
  AvgDialog_149753_Content_80 = {
    Text = "Se giró de repente, como un espectro al que le han revelado su verdadera identidad, con una expresión a medio camino entre la perplejidad y el odio. Las sombras en la pared se balanceaban, marcando pasos de un baile jubiloso, rodeándoos en el centro."
  },
  AvgDialog_149753_Content_81 = {
    Text = "No, ¿no es correcto? Bueno… de todos modos, sin importar cómo te llames, eres mi caballero."
  },
  AvgDialog_149753_Content_82 = {
    Text = "El cáliz sagrado ya ha sido encontrado. ¿Adónde vamos ahora?"
  },
  AvgDialog_149753_Content_83 = {
    Text = "Recordado por ti, él giró lentamente la cabeza hacia la copa de oro sobre la mesa, y luego, con dificultad, se desprendió de las sombras y tomó la media copa restante de antídoto, o de veneno, no lo sabes."
  },
  AvgDialog_149753_Content_84 = {
    Text = "Solo ves cómo echa la cabeza hacia atrás y la bebe de un trago."
  },
  AvgDialog_149753_Content_85 = {
    Text = "<Big:¡¡Oye!!>"
  },
  AvgDialog_149753_Content_9 = {
    Text = "Si no te sigo, ¿qué pasa si traicionas a tu princesa? Ni siquiera quisiste jurarlo."
  },
  AvgDialog_149754_Content_1 = {
    Text = "Un estruendo ensordecedor sacudió el ambiente, como si toda la torre principal temblara; ladrillos y piedras rotas caían con chasquidos, y los monstruos restantes rodearon estrechamente al señor en el centro, retrocediendo en masa hacia el pasadizo secreto."
  },
  AvgDialog_149754_Content_10 = {
    Text = "Sin saber cuánto habéis caminado, una brisa sopla de frente. Salada. Es el mar."
  },
  AvgDialog_149754_Content_11 = {
    Text = "¡Sa-salimos! ¡Hemos escapado! Ogier, ¿me escuchas? ¡¡Estamos salvados!!"
  },
  AvgDialog_149754_Content_12 = {
    Text = "…¿Ogier?"
  },
  AvgDialog_149754_Content_13 = {
    Text = "No emite ningún sonido; ni siquiera puedes sentir su respiración. Las olas golpean los arrecifes, el agua helada del mar mezclada con lluvia te azota el rostro, y es como si sintieras el frío por primera vez, sin poder evitar que te invada un temblor."
  },
  AvgDialog_149754_Content_14 = {
    Text = "<SmallShake:…Tos… tos, tos…>"
  },
  AvgDialog_149754_Content_15 = {
    Text = "¡Ogier! Qué alivio, sabía que no ibas a morir."
  },
  AvgDialog_149754_Content_16 = {
    Text = "<Shake:Yo… no… te prometí… venir.>"
  },
  AvgDialog_149754_Content_17 = {
    Text = "Ya lo sé, ¿cuántas veces más lo vas a repetir? ¿Acaso una princesa necesita el permiso de su caballero para ir adonde quiera?"
  },
  AvgDialog_149754_Content_18 = {Text = "..."},
  AvgDialog_149754_Content_19 = {
    Text = "<Shake:Yo… tuve… una vez… una… princesa.>"
  },
  AvgDialog_149754_Content_2 = {
    Text = "Tu caballero se esfuerza por mantenerse en pie, un rugido ronco brota de su pecho destrozado, pero las sombras se abalanzan como una marea. Más que a los enemigos, parecen querer devorarle vivo."
  },
  AvgDialog_149754_Content_20 = {
    Text = "<Shake:No… pude… protegerla.>"
  },
  AvgDialog_149754_Content_21 = {
    Text = "Su débil murmullo sonaba como el delirio de un sueño, y el viento del mar lo dispersó con facilidad; tuviste que contener la respiración para escucharle."
  },
  AvgDialog_149754_Content_22 = {
    Text = "Antes de que… estallara la guerra… ella me ordenó… que me marchara…"
  },
  AvgDialog_149754_Content_23 = {
    Text = "Yo… obedecí."
  },
  AvgDialog_149754_Content_24 = {
    Text = "No esperaba… que el enemigo… llegara tan rápido… No pude llegar a tiempo, tos tos, no pude llegar a tiempo…"
  },
  AvgDialog_149754_Content_25 = {
    Text = "La masacre… los cadáveres… la plaga negra… <Shake:La princesa… ella misma, tos tos tos tos!>"
  },
  AvgDialog_149754_Content_26 = {
    Text = "Sin saber qué dolorosos recuerdos le han asaltado, puedes sentir cómo se encoge sobre sí mismo, como una babosa cubierta de sal."
  },
  AvgDialog_149754_Content_27 = {
    Text = "<Shake:Fui yo… no pude protegerlos… todo desapareció… todo desaparecerá…>"
  },
  AvgDialog_149754_Content_28 = {
    Text = "<Shake:Alguna vez… quise ser caballero…>"
  },
  AvgDialog_149754_Content_29 = {
    Text = "<Shake:Pero… ahora… yo soy… ¿quién?…>"
  },
  AvgDialog_149754_Content_3 = {
    Text = "¡Alto! ¡Los monstruos sois vosotros! ¡¡No os escapéis!!"
  },
  AvgDialog_149754_Content_30 = {
    Text = "El pasado es el pasado, el presente es el presente. Ahora también tienes una princesa, y aún debes protegerme."
  },
  AvgDialog_149754_Content_31 = {
    Text = "Tardó mucho en responder, pero se agitó levemente."
  },
  AvgDialog_149754_Content_32 = {
    Text = "<Shake:Suél, tos tos tos, suéltame.>"
  },
  AvgDialog_149754_Content_33 = {
    Text = "Soy el más débil… el más inútil…"
  },
  AvgDialog_149754_Content_34 = {
    Text = "El que más merece… quedarse… quedarse en… el pasado… olvidado…"
  },
  AvgDialog_149754_Content_35 = {
    Text = "¡Imposible! Tu promesa aún no se ha cumplido, ¿acaso quieres retractarte?"
  },
  AvgDialog_149754_Content_36 = {
    Text = "El agua de la marea alta te cubre las rodillas, avanzas con dificultad en la oscuridad, los afilados arrecifes te desgarran las pantorrillas, las heridas se adormecen empapadas por el mar, aprietas los dientes sin emitir un quejido."
  },
  AvgDialog_149754_Content_37 = {
    Text = "Las palabras se desgarran entre jadeos pesados, fuerzas las frases a salir de tu garganta, y con cada frase que terminas, das un paso adelante, como si ellas te sostuvieran para seguir avanzando."
  },
  AvgDialog_149754_Content_38 = {
    Text = "Eres el caballero, que yo, elegí. Si te quedas, ¿cómo podrá la princesa, sola, vencer al monstruo, y completar la aventura?"
  },
  AvgDialog_149754_Content_39 = {
    Text = "… Eso no es más que un cuento."
  },
  AvgDialog_149754_Content_4 = {
    Text = "Presa de la angustia y la rabia, lanzas con fuerza el paquete que sostenías entre los brazos. Estaba repleto, y el nudo flojo se deshace en el aire, esparciendo los objetos de alguien: velas, un peine, una figurita de piedra… y el cáliz sagrado."
  },
  AvgDialog_149754_Content_40 = {
    Text = "Todo, es un cuento."
  },
  AvgDialog_149754_Content_41 = {
    Text = "El ayer, es el cuento del hoy, el hoy es, el cuento del mañana. Algunos, desaparecen, otros, continúan. Pero no puede ser, sin un cuento."
  },
  AvgDialog_149754_Content_42 = {
    Text = "Así que, ve a buscar, la isla de las manzanas. Ve, hah, hah… ve a completar, nuestra historia."
  },
  AvgDialog_149754_Content_5 = {
    Text = "La luz dorada rueda y vuela por encima del pantano de sombras, choca contra la pared de piedra, rebota dos veces en el suelo y, finalmente, se detiene justo a los pies del señor."
  },
  AvgDialog_149754_Content_6 = {
    Text = "Lo ves levantar la mano para detener a sus guardias, agacharse personalmente y recoger la pequeña copa dorada. La acaricia con el pulgar, siguiendo los grabados de la pared, como si recordara algo, y te lanza una mirada cargada de burla."
  },
  AvgDialog_149754_Content_7 = {
    Text = "Que rápidamente se convierte en terror."
  },
  AvgDialog_149754_Content_8 = {
    Text = "…Antes de que el castillo se derrumbara por completo en ruinas, sepultando sombras, dragón y reliquias, tu caballero te arrastró hasta un pasadizo secreto."
  },
  AvgDialog_149754_Content_9 = {
    Text = "Agotado, incapaz incluso de mantenerse en pie, lo aferras con fuerza del brazo y avanzas con dificultad, como si cargases un saco lleno de trigo."
  },
  AvgDialog_149755_Content_1 = {
    Text = "Isla Manzana"
  },
  AvgDialog_149755_Content_10 = {
    Text = "La herida de la pierna nunca había llegado a cicatrizar; al contrario, con los días de lluvia continua el dolor no hacía más que empeorar. Tenías la pierna hinchada como una zanahoria desde la rodilla hacia abajo, y no podías dar ni un paso. Durante los últimos días, había sido Ogier quien te cargaba a cuestas por montañas y valles."
  },
  AvgDialog_149755_Content_100 = {
    Text = "Alteza, no lloréis por mí. Ya hay demasiados monstruos en el mundo. Lo único que puedo hacer por vos es proteger el paraíso que pertenece a los humanos, que os pertenece a vos. Es mi deber, y también mi redención."
  },
  AvgDialog_149755_Content_101 = {
    Text = "No me dirijo hacia el fin; lo cruzaré, pues ya he alcanzado el alba."
  },
  AvgDialog_149755_Content_102 = {
    Text = "Seguiré velando por vos allí donde nace el sol."
  },
  AvgDialog_149755_Content_103 = {
    Text = "En lugar de sangre, brotaron sombras a raudales. Quien se adentraba en aquella torrente rugiente desaparecía en un abrir y cerrar de ojos, pero las sombras aún no se habían disipado."
  },
  AvgDialog_149755_Content_104 = {
    Text = "Las sombras se agitan, las sombras se revuelven, las sombras se condensan en escudo, en muro, y al final en una enorme presa. Clavaas la mirada en la oscuridad más profunda, hasta que el carro de bueyes dobla una curva y ya no puedes ver la superficie del río."
  },
  AvgDialog_149755_Content_105 = {
    Text = "Tu caballero desapareció desde entonces sin dejar rastro. Solo cumplió la mitad de su promesa, pero dejó unas últimas palabras sumamente astutas que hacen que, incluso llorando hasta quedarte dormida, sigas esperando el mañana."
  },
  AvgDialog_149755_Content_106 = {
    Text = "Porque entonces nacerá un nuevo sol, día tras día, sin que eso cambie jamás."
  },
  AvgDialog_149755_Content_11 = {
    Text = "Toma, recién cogida."
  },
  AvgDialog_149755_Content_12 = {
    Text = "Como si quisiera consolarte, metió una fruta en tu mano. La mordiste medio dormida, y solo cuando una acidez aguda se extendió por tus encías caíste en la cuenta de lo que era."
  },
  AvgDialog_149755_Content_13 = {
    Text = "…¿Una manzana?"
  },
  AvgDialog_149755_Content_14 = {
    Text = "Sí, antes pasamos junto a un manzanar."
  },
  AvgDialog_149755_Content_15 = {
    Text = "Manzanas… la Isla de las Manzanas. ¿Ya hemos llegado?"
  },
  AvgDialog_149755_Content_16 = {Text = "Casi."},
  AvgDialog_149755_Content_17 = {
    Text = "Él deshizo el vendaje, aplicó las hierbas sobre la herida y volvió a envolverla vuelta a vuelta. Lo observaste atentamente y pensaste que su expresión no era de esperanza."
  },
  AvgDialog_149755_Content_18 = {
    Text = "Ibas a seguir preguntando, pero te interrumpió un ladrido que se acercaba desde lejos."
  },
  AvgDialog_149755_Content_19 = {
    Text = "¡Espera, no corras tan rápido! ¿Adónde vas? Por ahí no se vuelve a la aldea… ¡Ah!"
  },
  AvgDialog_149755_Content_2 = {
    Text = "……despierta……"
  },
  AvgDialog_149755_Content_20 = {
    Text = "Un perro pastor irrumpió furioso entre los arbustos, ladrando con fuerza para ahuyentar a los intrusos. La joven que venía corriendo detrás no pudo evitar soltar un grito al veros, y la cesta de mimbre que llevaba en la mano cayó al suelo."
  },
  AvgDialog_149755_Content_21 = {
    Text = "Era Ogier. Unas cicatrices negras y sucias le cubrían el rostro, como el de un muñeco de trapo destrozado y remendado a la ligera, evocando toda clase de leyendas aterradoras."
  },
  AvgDialog_149755_Content_22 = {
    Text = "Él y la joven se miraron en silencio, luego se levantó y se puso la capucha."
  },
  AvgDialog_149755_Content_23 = {
    Text = "Nos vamos ahora."
  },
  AvgDialog_149755_Content_24 = {
    Text = "No… no, yo no— ¡espera un momento!"
  },
  AvgDialog_149755_Content_25 = {
    Text = "Ogier apenas había dado unos pasos cargándote a la espalda cuando la joven lo siguió apresuradamente."
  },
  AvgDialog_149755_Content_26 = {
    Text = "¡No te vayas! No era eso lo que quería decir, hay muchos enfermos en el pueblo, ¡los llevaré con ustedes!"
  },
  AvgDialog_149755_Content_27 = {
    Text = "¿Enfermos?"
  },
  AvgDialog_149755_Content_28 = {
    Text = "Sí, todos son leprosos. Al principio solo había leprosos, pero luego llegó el ejército, destruyó innumerables aldeas, aunque nunca se acercaba a los pueblos de leprosos, así que llegaron personas que habían perdido sus hogares. Yo también soy una de ellas."
  },
  AvgDialog_149755_Content_29 = {
    Text = "No te preocupes, todos estamos acostumbrados. En realidad, salvo que parecemos diferentes, no somos tan distintos: todos comemos, dormimos, trabajamos igual… La lepra no es tan aterradora como el ejército. Con el tiempo te acostumbras."
  },
  AvgDialog_149755_Content_3 = {
    Text = "……llueve……descansa……despierta……"
  },
  AvgDialog_149755_Content_30 = {
    Text = "Lo siento, no es que te tenga miedo, es solo que nunca había visto… ¡Lo siento! Toma esta cesta de manzanas azules, las escogí yo misma, ¡te prometo que son las más grandes y las más dulces!"
  },
  AvgDialog_149755_Content_31 = {
    Text = "¿Cómo debería ser el paraíso?"
  },
  AvgDialog_149755_Content_32 = {
    Text = "Sin monstruos, sin desesperación, sin ese pánico indescriptible, sin ojos acechando en la oscuridad, sin miedo a no poder despertar antes de dormir, y con sopa caliente todos los días."
  },
  AvgDialog_149755_Content_33 = {
    Text = "No sabes si hay algún lugar que se parezca más al paraíso que este."
  },
  AvgDialog_149755_Content_34 = {
    Text = "…Ya está."
  },
  AvgDialog_149755_Content_35 = {
    Text = "Un cuchillo afilado abre el absceso, extirpando poco a poco la carne podrida y corrompida; un hierro al rojo vivo se presiona sobre la herida que no deja de sangrar. El dolor agudo te arranca un grito ahogado mientras te empapas en sudor."
  },
  AvgDialog_149755_Content_36 = {
    Text = "Terminó. Alguien retira el trapo que tenías metido en la boca; respiras con todas tus fuerzas, casi como si fueras a tragarte el aire entero."
  },
  AvgDialog_149755_Content_37 = {
    Text = "Esta vez es diferente, lo sabes. Ellos están aquí para salvarte, y tu caballero también está a tu lado."
  },
  AvgDialog_149755_Content_38 = {
    Text = "La medicina, llévala y hiérvela en agua. Una vez al amanecer, una vez al anochecer."
  },
  AvgDialog_149755_Content_39 = {
    Text = "Bien, gracias."
  },
  AvgDialog_149755_Content_4 = {
    Text = "Alguien te despierta con suaves sacudidas. Con la mente aún adormecida, escuchas el suave repiqueteo de la lluvia."
  },
  AvgDialog_149755_Content_40 = {
    Text = "Él sacó unas monedas como pago, pero el barbero las rechazó con un gesto. En un lugar aislado del mundo, los precios del exterior no sirven de nada; la gente de aquí no vive para eso."
  },
  AvgDialog_149755_Content_41 = {
    Text = "<Small:El cielo se ha despejado…>"
  },
  AvgDialog_149755_Content_42 = {
    Text = "<Small:Ogier, quiero ir al manzanar.>"
  },
  AvgDialog_149755_Content_43 = {
    Text = "Necesitas descansar."
  },
  AvgDialog_149755_Content_44 = {
    Text = "Llévame allí, tengo un gran descubrimiento… que contarte."
  },
  AvgDialog_149755_Content_45 = {
    Text = "Ya llegamos. ¿Qué gran descubrimiento?"
  },
  AvgDialog_149755_Content_46 = {
    Text = "Uf… He descubierto que este lugar es la Isla de las Manzanas, ya la hemos encontrado."
  },
  AvgDialog_149755_Content_47 = {
    Text = "Tu caballero te sienta sobre un tronco caído, dobla la rodilla y con cuidado endereza tu pierna herida. Su mirada es atenta y preocupada; evidentemente, la verdad que acabas de revelar no logra sorprenderle."
  },
  AvgDialog_149755_Content_48 = {
    Text = "Pero esto no es una isla."
  },
  AvgDialog_149755_Content_49 = {
    Text = "Nadie ha dicho que una isla deba estar en el mar, ¿verdad? Con tal de no estar conectada con el exterior, ya es una isla."
  },
  AvgDialog_149755_Content_5 = {
    Text = "La lluvia ha vuelto a caer. En realidad, nunca dejó de hacerlo."
  },
  AvgDialog_149755_Content_50 = {
    Text = "Además, aquí también hay hadas."
  },
  AvgDialog_149755_Content_51 = {Text = "¿Hadas?"},
  AvgDialog_149755_Content_52 = {
    Text = "Sí, en el pueblo hay muchas hadas. Algunas tienen rostro de león, otras tienen escamas de pez, y otras mudan la piel como las serpientes. Son las hadas que viven en un mundo de ensueño."
  },
  AvgDialog_149755_Content_53 = {
    Text = "¿Son hadas… y no monstruos?"
  },
  AvgDialog_149755_Content_54 = {
    Text = "¡Por supuesto que no! ¿Cómo podrían ser iguales las hadas y los monstruos?"
  },
  AvgDialog_149755_Content_55 = {
    Text = "Los monstruos devoran a las personas, hacen todo lo posible por comérselas: a veces las matan directamente con un cuchillo, otras veces inventan mentiras para encerrarlas y arrancarles la carne a tajos."
  },
  AvgDialog_149755_Content_56 = {
    Text = "No solo comen ellos mismos, sino que también hacen sopas, carnes en salazón y papillas para dárselas a otros. Carne humana por todas partes: no comerla significa morir de hambre, pero quien haya comido a una persona se convierte en monstruo, así que cada vez hay más monstruos."
  },
  AvgDialog_149755_Content_57 = {
    Text = "Los humanos no se comen entre sí, y las hadas tampoco comen personas. En la Isla de las Manzanas, ellas son puras e inmaculadas."
  },
  AvgDialog_149755_Content_58 = {
    Text = "¿Y yo? Yo no soy humano ni hada. Tengo las manos manchadas de sangre y un demonio habita en mi cuerpo; tú mismo has visto su forma."
  },
  AvgDialog_149755_Content_59 = {
    Text = "¿Por qué no tienes miedo?"
  },
  AvgDialog_149755_Content_6 = {
    Text = "El bosque ocultaba a los fugitivos. La noticia de la masacre del castillo a manos de los monstruos llegó a oídos de los gobernantes, los carteles de búsqueda y captura cubrían cada ciudad, y tanto los caballeros de la Iglesia como los mercenarios habían sido movilizados. No os quedaba más remedio que marchar día y noche."
  },
  AvgDialog_149755_Content_60 = {
    Text = "¿Por qué habría de tenerlo? Desde el primer momento en que lo viste, supiste que era sin duda un caballero. A través de las sombras que lo envuelven sin disiparse, aún puedes ver en él la imagen de un caballero: tan nítida, tan inequívoca, como si lo hubieras visto en algún otro lugar."
  },
  AvgDialog_149755_Content_61 = {
    Text = "¿Qué se necesita para convertirse en un verdadero caballero? Lealtad, valentía, compasión, sacrificio, y…"
  },
  AvgDialog_149755_Content_62 = {
    Text = "La investidura del señor."
  },
  AvgDialog_149755_Content_63 = {
    Text = "Ejem, ejem… Entonces, declaro, en nombre de la princesa, que te armo caballero."
  },
  AvgDialog_149755_Content_64 = {
    Text = "Derrotaste al monstruo, obtuviste el Santo Grial, resististe al demonio y me protegiste. Has cumplido tu promesa y has llevado a tu princesa a la Isla de las Manzanas."
  },
  AvgDialog_149755_Content_65 = {
    Text = "Sin importar quién hayas sido, en nuestra historia eres un caballero, y ninguna princesa teme a su caballero."
  },
  AvgDialog_149755_Content_66 = {
    Text = "Serás mi caballero para siempre."
  },
  AvgDialog_149755_Content_67 = {
    Text = "Tu caballero quedó paralizado, con una mano aferrando con fuerza la capa, como si quisiera ocultarse en aquella amplia sombra. La capa cubría los rastros de su sombra; solo él sabía cuán miserable era lo que se escondía bajo ese disfraz."
  },
  AvgDialog_149755_Content_68 = {
    Text = "Las delgadas ramas, aún húmedas por la lluvia, se posaron suavemente sobre sus hombros. Un anhelo tan lejano que casi había sido olvidado se hizo realidad de repente, pero lo que hizo estremecer su alma no fue la alegría."
  },
  AvgDialog_149755_Content_69 = {
    Text = "Sino miedo."
  },
  AvgDialog_149755_Content_7 = {
    Text = "Hay una aldea más adelante. Voy a conseguir algo de comida y medicinas. Descansa aquí; cuando pare la lluvia, seguiremos."
  },
  AvgDialog_149755_Content_70 = {
    Text = "Las llamas del miedo ascendían desde el abismo sin fondo, bajo sus pies, sobre su cabeza, en los ojos aterrados que miraban por las grietas. Ardientes, cálidas, brotando a chorros de cuellos rotos, manando de pechos abiertos. Las llamas tan retorcidas que las sombras enloquecían con ellas. El fuego y la sombra son uno solo."
  },
  AvgDialog_149755_Content_71 = {
    Text = "Fue una masacre, sin honor alguno, sin justicia alguna, igual para todos. El sangriento desenlace desgarró los adornos de las palabras engañosas; la muerte no era más que muerte. No recordaba cómo había sobrevivido; quizás nunca lo hizo."
  },
  AvgDialog_149755_Content_72 = {
    Text = "Monstruo caído, espectro vengativo, su búsqueda era como echar leña al fuego; El Perdido se deslizaba irremediablemente hacia su fin, sin haber creído jamás que podría encontrar redención."
  },
  AvgDialog_149755_Content_73 = {
    Text = "<Shake:Pero… pero…>"
  },
  AvgDialog_149755_Content_74 = {
    Text = "Ogier, ¿Ogier? Oye, ¿me estás escuchando? Ya terminé, te toca a ti."
  },
  AvgDialog_149755_Content_75 = {Text = "..."},
  AvgDialog_149755_Content_76 = {
    Text = "Sí, acepto."
  },
  AvgDialog_149755_Content_77 = {
    Text = "En nombre de mi patria perdida, yo, Ogier, hijo de la Familia Dansk, os juro lealtad y devoción."
  },
  AvgDialog_149755_Content_78 = {
    Text = "Os ofrezco mi escudo y mi lanza, junto con la fe que he manchado, mi eterno temor y mi corazón incompleto. Perdí mi nombre en la larga noche, y fue vuestro llamado el que encendió el alba."
  },
  AvgDialog_149755_Content_79 = {
    Text = "Quien rompe sus juramentos no merece llamarse fiel, pero si vuestra mirada aún está dispuesta a detenerse en mí, entonces os perteneceré hasta el último aliento de mi vida."
  },
  AvgDialog_149755_Content_8 = {
    Text = "<Small:Entendido… Vuelve pronto.>"
  },
  AvgDialog_149755_Content_80 = {
    Text = "Las historias no siempre tienen comienzos llenos de color; también pueden nacer en la orilla de la desesperación."
  },
  AvgDialog_149755_Content_81 = {
    Text = "Aunque el final permanezca erguido por toda la eternidad, proyectando su pesada sombra sobre todas las cosas, antes de llegar a él, aún tenéis la libertad de elegir qué se convertirá en vuestro destino."
  },
  AvgDialog_149755_Content_82 = {
    Text = "La brisa suave, la luz del sol, el aroma de las manzanas maduras, la neblina que se eleva del bosque como nubes; el mundo es tan hermoso como una pintura, y sonríes con alegría, como si hubieras llegado a un final perfecto."
  },
  AvgDialog_149755_Content_83 = {
    Text = "Pero sabes que la historia continuará; siempre continúa."
  },
  AvgDialog_149755_Content_84 = {
    Text = "<Big:¿Cuántos no han despertado aún? ¡Id a avisarles, viene una inundación!>"
  },
  AvgDialog_149755_Content_85 = {
    Text = "La oscuridad de la noche amplificó la furia de la tormenta. Las gotas de lluvia caían como piedras con estruendo, el turbio río rugía desbordándose por ambas orillas, y el agua acumulada ya superaba las rodillas."
  },
  AvgDialog_149755_Content_86 = {
    Text = "Las siluetas corrían de un lado a otro, gritando a voz en cuello, golpeando con fuerza cada puerta y ventana, pero los espíritus se movían con lentitud, y al caer no podían levantarse, incapaces de cruzar solos los charcos llenos de baches."
  },
  AvgDialog_149755_Content_87 = {
    Text = "\"¡BOOM!!\" Un estruendo ensordecedor te sacudió el corazón, pero bajo el manto de la noche, la gente miraba desconcertada a su alrededor, sin saber qué estaba a punto de derrumbarse."
  },
  AvgDialog_149755_Content_88 = {
    Text = "<Big:¡Mal asunto, es el dique!!>"
  },
  AvgDialog_149755_Content_89 = {
    Text = "<Big:¡Corred! ¡Todo el que pueda moverse, corred, ya no hay tiempo!>"
  },
  AvgDialog_149755_Content_9 = {
    Text = "Aunque no querías quedarte, tu cuerpo ardía de fiebre y ya no te quedaban fuerzas para seguirle el paso."
  },
  AvgDialog_149755_Content_90 = {
    Text = "Súplicas, gemidos, llantos... el paraíso de tus sueños se tambaleaba, a punto de ser arrasado por la lluvia interminable, dejando tras de sí solo ruinas desoladas. Y tú ni siquiera podías caminar por tu propio pie, solo podías observar impotente."
  },
  AvgDialog_149755_Content_91 = {
    Text = "Tu caballero te subió al borde del carruaje, se quitó la capa y te envolvió en ella con cuidado."
  },
  AvgDialog_149755_Content_92 = {
    Text = "Alteza, os ruego que me permitáis marcharme para hacer frente a la devastadora inundación."
  },
  AvgDialog_149755_Content_93 = {
    Text = "¿Puedes detener las aguas?"
  },
  AvgDialog_149755_Content_94 = {
    Text = "Haré todo lo que esté en mi mano."
  },
  AvgDialog_149755_Content_95 = {
    Text = "¿Podrás regresar?"
  },
  AvgDialog_149755_Content_96 = {
    Text = "……Haré todo lo que esté en mi mano."
  },
  AvgDialog_149755_Content_97 = {
    Text = "<Big:No, no, ¡me niego! ¡No lo permito!>"
  },
  AvgDialog_149755_Content_98 = {
    Text = "Nos vamos, nos vamos ahora mismo… siempre habrá otro lugar, la Isla Manzana, la Isla Calabaza, lo que sea, ¡siempre habrá otro lugar!"
  },
  AvgDialog_149755_Content_99 = {
    Text = "Con todas tus fuerzas te aferraste al borde de su ropa, aunque en tu corazón sabías que era en vano: él ya había tomado su decisión. Te hizo una reverencia, como el héroe más gentil y el caballero más leal de todos los cuentos."
  },
  AvgDialog_149756_Content_1 = {Text = "Princesa"},
  AvgDialog_149756_Content_10 = {
    Text = "Quieres gritar en respuesta, quieres reírte, quieres maldecir, quieres chillar, pero un trapo empapado en aceite te tapa la boca. El objeto viscoso y maloliente presiona con fuerza la raíz de tu lengua, y salvo arcadas, no puedes emitir ningún sonido."
  },
  AvgDialog_149756_Content_11 = {
    Text = "¡Miradla, está temblando! El demonio se retuerce dentro de ella, esa es su verdadera y repugnante naturaleza."
  },
  AvgDialog_149756_Content_12 = {
    Text = "Señor misericordioso, os ruego que desatéis su boca sellada por el diablo, que ella misma confiese sus pecados, si aún guarda en su corazón el anhelo de la redención."
  },
  AvgDialog_149756_Content_13 = {
    Text = "El trapo que te tapaba la boca es arrancado bruscamente, toses y te atragantas un par de veces, jadeas con fuerza, y la saliva te corre por las comisuras de los labios."
  },
  AvgDialog_149756_Content_14 = {
    Text = "Los monstruos forman un círculo a tu alrededor blandiendo hachas y horcas, observándote con recelo. Más lejos, en los linderos de los campos, entre las ramas de los árboles, tras ventanas entornadas, se ocultan aún más ojos."
  },
  AvgDialog_149756_Content_15 = {
    Text = "¡Habla, niña! ¡Proclama ante el Señor tu arrepentimiento, este es tu último momento para librarte del castigo eterno!"
  },
  AvgDialog_149756_Content_16 = {
    Text = "<Small:…Monstruos.>"
  },
  AvgDialog_149756_Content_17 = {
    Text = "¿Qué? ¿Qué ha dicho?"
  },
  AvgDialog_149756_Content_18 = {
    Text = "<BigShake:¡Monstruos! ¡Monstruos! ¡Mons— ¡cof, cof, cof!>"
  },
  AvgDialog_149756_Content_19 = {
    Text = "Has desenmascarado el engaño cuidadosamente urdido, los monstruos muestran expresiones de pánico y desconcierto, y sientes una cruel y amarga satisfacción."
  },
  AvgDialog_149756_Content_2 = {
    Text = "Los monstruos se comieron a mi familia y ahora pretenden comerme a mí."
  },
  AvgDialog_149756_Content_20 = {
    Text = "¡Una maldición, es una maldición! ¡Maldita bruja!"
  },
  AvgDialog_149756_Content_21 = {
    Text = "¡Tapadle la boca rápido!"
  },
  AvgDialog_149756_Content_22 = {
    Text = "Señor… protégenos…"
  },
  AvgDialog_149756_Content_23 = {
    Text = "<Big:¡Quemadla! ¡Quemadla!>"
  },
  AvgDialog_149756_Content_24 = {
    Text = "<Big:¡Duendes! ¡Pantaneros! ¡Carroñeros! ¡Monstruos! ¡Todos vosotros sois mons— uuuuu——!!>"
  },
  AvgDialog_149756_Content_25 = {
    Text = "El diablo ya se ha llevado su alma. Para proteger nuestro pueblo de los maleficios, debemos deshacernos de esta impureza."
  },
  AvgDialog_149756_Content_26 = {
    Text = "Que el fuego sagrado queme sus pecados, que el Señor nos conceda la paz."
  },
  AvgDialog_149756_Content_27 = {
    Text = "Un fardo tras otro de leña seca se apilaba a tus pies, las zarzas desgarraban tu piel desnuda, y el dolor te hacía retorcerte, haciendo resonar las cadenas de hierro."
  },
  AvgDialog_149756_Content_28 = {
    Text = "Eso te valió aún más insultos, y una cuerda de cáñamo atada con más fuerza."
  },
  AvgDialog_149756_Content_29 = {
    Text = "El fuego se encendió."
  },
  AvgDialog_149756_Content_3 = {
    Text = "El crepúsculo es un presagio de cierto despertar; el sol poniente parece una mancha roja enfermiza, y el cielo se hincha como un moretón."
  },
  AvgDialog_149756_Content_30 = {
    Text = "Te exorcizamos… alma impura, hereje apóstata… como el humo dispersado por el viento, como la cera derretida por el fuego…"
  },
  AvgDialog_149756_Content_31 = {
    Text = "Caído, perseguidor, desterrado, en nombre de Su Majestad, te ordeno: ¡teme, sométete, huye—!"
  },
  AvgDialog_149756_Content_32 = {
    Text = "Su voz se cortó en seco, como si unas tijeras la hubieran cercenado por la mitad."
  },
  AvgDialog_149756_Content_33 = {
    Text = "Esforzándote por abrir tus ojos irritados, a través del humo denso y arremolinado, viste una figura desconocida de pie junto al sacerdote."
  },
  AvgDialog_149756_Content_34 = {
    Text = "¿Cuándo había aparecido? No lo sabías. Miraste al resto de los monstruos; no se movían, como un grupo de ranas boquiabiertas."
  },
  AvgDialog_149756_Content_35 = {
    Text = "El sacerdote comenzó a convulsionar nerviosamente, con ambas manos cubriéndose el cuello; la sangre se derramaba entre sus dedos y brotaba a chorros de su boca, su rostro del mismo color que el cielo. Cayó."
  },
  AvgDialog_149756_Content_36 = {
    Text = "<Big:¡Ah—!!>"
  },
  AvgDialog_149756_Content_37 = {
    Text = "Un grito, más agudo que un silbato, hizo temblar incluso las lenguas de fuego."
  },
  AvgDialog_149756_Content_38 = {
    Text = "¡Sangre… tanta sangre… han matado a alguien! ¡Socorro, el monstruo ha matado a alguien!"
  },
  AvgDialog_149756_Content_39 = {
    Text = "No, no… un demonio, ¡es un demonio! ¡Esa bruja ha invocado algo del infierno! Señor, te rogamos que nos perdones…"
  },
  AvgDialog_149756_Content_4 = {
    Text = "El fuego aún no se ha encendido, pero los árboles secos ya se han retorcido, con esa postura desesperada, como si incluso la luz del día que regresa una y otra vez fuera una quemadura insoportable."
  },
  AvgDialog_149756_Content_40 = {
    Text = "Tu corazón latía con fuerza, sabías quién era él, sabías que tu vida no terminaría hoy, que no era más que un preludio, un interludio, para dar la bienvenida a su llegada."
  },
  AvgDialog_149756_Content_41 = {
    Text = "Llena de esperanza ardiente, te retorcías con todas tus fuerzas, llamándole con gemidos, ansiosa por que te mirara, casi olvidando las cadenas al rojo vivo."
  },
  AvgDialog_149756_Content_43 = {
    Text = "Una mano enguantada te arrancó de la hoguera; tus piernas cedieron sin control y caíste al suelo, tosiendo y vomitando al mismo tiempo, con lágrimas y mocos mezclados."
  },
  AvgDialog_149756_Content_44 = {
    Text = "<Shake:¡Tos tos tos tos tos tos tos—!! Es-espera, tos tos tos tos, ¡espera! ¡No te vayas!>"
  },
  AvgDialog_149756_Content_45 = {
    Text = "Antes de que él se diera la vuelta para marcharse, agarraste su capa a toda prisa."
  },
  AvgDialog_149756_Content_46 = {
    Text = "Parecía no haber esperado tu gesto; su capucha se deslizó hacia un lado, dejando al descubierto el rostro de un joven."
  },
  AvgDialog_149756_Content_47 = {Text = "Suéltame."},
  AvgDialog_149756_Content_48 = {
    Text = "Eres inteligente, sabes distinguir entre una amenaza vacía y una advertencia real. Al recordar la muerte del sacerdote de hace poco, te encogiste."
  },
  AvgDialog_149756_Content_49 = {
    Text = "Pero entonces viste su rostro, sin lugar a dudas, así debía ser el noble caballero de los cuentos. Seguramente había venido por ti, e incluso sentiste que esos rasgos te resultaban familiares."
  },
  AvgDialog_149756_Content_5 = {
    Text = "<BigShake:¡No os dejéis engañar por su apariencia!> El rostro de niña no es más que un disfraz; en ese cuerpo habita un demonio, y el Señor ha visto todos sus pecados."
  },
  AvgDialog_149756_Content_50 = {
    Text = "Claro, debías haberlo visto en algún lugar, en un sueño, en una maldición o en una profecía. ¿Cómo si no explicar ese valor repentino que te invadió?"
  },
  AvgDialog_149756_Content_51 = {
    Text = "<Shake:No… tос tос tос, no puedes irte.>"
  },
  AvgDialog_149756_Content_52 = {
    Text = "¿Por qué?"
  },
  AvgDialog_149756_Content_53 = {
    Text = "Porque, tос tос, porque has venido a salvarme, ¿cómo puedes dejarme atrás?"
  },
  AvgDialog_149756_Content_54 = {
    Text = "Ya estás a salvo. Vuelve a la vida que te corresponde."
  },
  AvgDialog_149756_Content_55 = {
    Text = "No hay ninguna vida para mí aquí. Hay monstruos por todas partes que no hacen más que atrapar y devorar personas. Ya lo has visto."
  },
  AvgDialog_149756_Content_56 = {
    Text = "No es asunto mío."
  },
  AvgDialog_149756_Content_57 = {
    Text = "¿Cómo puede no ser asunto tuyo? Llevo todo este tiempo esperándote."
  },
  AvgDialog_149756_Content_58 = {
    Text = "¿Esperándome? Tú… ¿me conoces?"
  },
  AvgDialog_149756_Content_59 = {
    Text = "Por supuesto, eres mi caballero."
  },
  AvgDialog_149756_Content_6 = {
    Text = "Es una ladrona, una embustera, una sierva de la oscuridad. La calamidad fluye de su boca, el veneno contamina pozos y ríos, y así el ganado cae muerto en sus corrales y los piadosos enferman de males terribles."
  },
  AvgDialog_149756_Content_60 = {
    Text = "Asombro, confusión, pánico, dolor: múltiples expresiones se agolparon en su rostro a la vez. Te apartó de un tirón brusco, como si esquivara una serpiente venenosa, y apoyó la daga ensangrentada contra tu cuello."
  },
  AvgDialog_149756_Content_61 = {
    Text = "¡¿Quién eres?!"
  },
  AvgDialog_149756_Content_62 = {
    Text = "¡Yo, yo soy una princesa! Así es, soy una princesa, los monstruos me secuestraron y he estado esperando que vinieras a rescatarme."
  },
  AvgDialog_149756_Content_63 = {
    Text = "No lo dudes. Si no fuera una princesa, ¿por qué el cielo habría enviado a un caballero a salvarme?"
  },
  AvgDialog_149756_Content_64 = {Text = "..."},
  AvgDialog_149756_Content_65 = {
    Text = "Enfundó la daga, se levantó y se adentró en el bosque espeso sin dirigirte ni una palabra más."
  },
  AvgDialog_149756_Content_66 = {
    Text = "Espera, ¿adónde vas? Yo, tос, voy contigo."
  },
  AvgDialog_149756_Content_67 = {
    Text = "<Shake:¡Alto! Tос tос, en nombre de la princesa, ¡te ordeno que te detengas!>"
  },
  AvgDialog_149756_Content_68 = {
    Text = "Aunque él era sorprendentemente ágil, tú llevabas ventaja por conocer aquel bosque como la palma de tu mano."
  },
  AvgDialog_149756_Content_69 = {
    Text = "Y además ya no tienes adónde ir, solo puedes seguir adelante, seguir adelante, aunque caigas aquí mismo en el bosque y te conviertas en alimento para las bestias."
  },
  AvgDialog_149756_Content_7 = {
    Text = "Sois todos testigos, ¿cuántas veces la habéis visto adentrarse en el bosque, desaparecer, y regresar como si nada? ¡Esa es la prueba de que practica la brujería!"
  },
  AvgDialog_149756_Content_70 = {
    Text = "<Shake:Ah… ah… espera, yo… yo conozco las reglas.>"
  },
  AvgDialog_149756_Content_71 = {
    Text = "Tengo un lugar al que ir. Llévame allí y recibirás honor y recompensa."
  },
  AvgDialog_149756_Content_72 = {
    Text = "No los necesito."
  },
  AvgDialog_149756_Content_73 = {
    Text = "Sí los necesitas. Al menos ahora, necesitas a alguien que te saque de aquí, ¿no es así?"
  },
  AvgDialog_149756_Content_74 = {
    Text = "Él no respondió, pero poco a poco fue deteniendo sus pasos."
  },
  AvgDialog_149756_Content_75 = {
    Text = "¿A dónde vas?"
  },
  AvgDialog_149756_Content_76 = {
    Text = "Mm… ah, cierto, la Isla de las Manzanas, ¿la has oído mencionar? Un paraíso donde no hay que cultivar, donde nadie enferma y donde no existe el invierno. Allí es adonde voy."
  },
  AvgDialog_149756_Content_77 = {
    Text = "Nunca la he oído. ¿Dónde está?"
  },
  AvgDialog_149756_Content_78 = {
    Text = "El hada no me dijo la dirección, pero me dijo que algún día la encontraría, igual que ella. Podemos ir caminando y buscarla al mismo tiempo. Al fin y al cabo, las grandes aventuras siempre están llenas de desafíos, ¿verdad?"
  },
  AvgDialog_149756_Content_79 = {
    Text = "La capa negra se fundió con la oscuridad de la noche. Él estaba de pie tras unos arbustos revueltos, con el rostro difuso e irreconocible."
  },
  AvgDialog_149756_Content_8 = {
    Text = "<SmallShake:La plaga… la bruja… sí, es por la bruja… la maldición de la bruja…>"
  },
  AvgDialog_149756_Content_80 = {
    Text = "Te acercas a él muy lentamente, con sumo cuidado, como si temieras asustar a un lobo salvaje."
  },
  AvgDialog_149756_Content_81 = {
    Text = "Para. Quédate ahí. No des un paso más."
  },
  AvgDialog_149756_Content_82 = {Text = "Guíame."},
  AvgDialog_149756_Content_83 = {
    Text = "¿Significa eso que has aceptado, valiente caballero?"
  },
  AvgDialog_149756_Content_84 = {Text = "..."},
  AvgDialog_149756_Content_85 = {
    Text = "No soy un caballero."
  },
  AvgDialog_149756_Content_86 = {
    Text = "Sí lo eres. A partir de ahora, eres mi leal caballero."
  },
  AvgDialog_149756_Content_87 = {
    Text = "Los caballeros cumplen sus promesas. Hasta que lleguemos a la Isla de las Manzanas, debes protegerme. Debes caminar delante de mí, despejarme el camino de espinas y enredaderas, y si algún monstruo nos persigue, debes ahuyentarlo, y además…"
  },
  AvgDialog_149756_Content_88 = {
    Text = "¿Adónde vas? Todavía no has jurado. Si te atreves a mentirle a tu princesa, los monstruos vendrán a devorarte. Jura primero."
  },
  AvgDialog_149756_Content_89 = {
    Text = "¡Oye! No te vayas, espérame — ¡yo conozco el camino!"
  },
  AvgDialog_149756_Content_9 = {
    Text = "¿Una bruja de menos de diez años? Ni un loco sería capaz de inventar semejante mentira."
  },
  AvgDialog_149757_Content_1 = {Text = "Túmulo"},
  AvgDialog_149757_Content_10 = {
    Text = "<Shake:Hah, hah… ¿Dónde estás…? Mi caballero…>"
  },
  AvgDialog_149757_Content_11 = {
    Text = "Recordaste aquel rumor y tu preocupación creció aún más. No podías permitir que el único caballero que tenías fuera derrotado por el demonio. Recordarías su nombre, ya lo habías memorizado."
  },
  AvgDialog_149757_Content_12 = {
    Text = "Ogier… eso es, ¡Ogier! ¿Dónde estás? <Big:¡O—gier—!>"
  },
  AvgDialog_149757_Content_13 = {
    Text = "Un grito de dolor atravesó el manto de lluvia, más parecido al aullido de una bestia herida que al de un ser humano. De inmediato echaste a correr hacia donde provenía el sonido."
  },
  AvgDialog_149757_Content_14 = {
    Text = "¡Deja de esconderte! ¡Ya te he visto!"
  },
  AvgDialog_149757_Content_15 = {
    Text = "¡Aléjate! ¡No, ha, no te acerques!!"
  },
  AvgDialog_149757_Content_16 = {
    Text = "La llama de la linterna temblaba sin cesar, incapaz de disipar la oscuridad que se cerraba desde todos lados. Tu caballero había sido acorralado sin salida, su espalda tensa como un arco a punto de disparar."
  },
  AvgDialog_149757_Content_17 = {
    Text = "¡Cállate! ¡No lo he olvidado! Eso no es… no, yo nunca… ¡no lo olvidaré!"
  },
  AvgDialog_149757_Content_18 = {
    Text = "<Shake:Me vengaré por ellos… debo vengarme por ellos… ojo por ojo, diente por diente…>"
  },
  AvgDialog_149757_Content_19 = {
    Text = "No, no lo hará, ¡estás mintiendo! La princesa no diría eso, la princesa, ella—"
  },
  AvgDialog_149757_Content_2 = {
    Text = "Alguien te dijo una vez que el nombre de cada persona es un conjuro."
  },
  AvgDialog_149757_Content_20 = {
    Text = "<Big:¡Aaah—!!>"
  },
  AvgDialog_149757_Content_21 = {
    Text = "Las palabras incoherentes fueron interrumpidas por un grito desgarrador. Como si alguien le hubiera clavado una lanza en el pecho, cayó de rodillas tambaleándose, mientras la sombra a su espalda permanecía inmóvil en su lugar, como una armadura, como una jaula."
  },
  AvgDialog_149757_Content_22 = {
    Text = "Sentiste una oleada de pánico. Sabías que si no lo detenías ahora, la sombra se convertiría en persona, y la persona caería hasta convertirse en sombra."
  },
  AvgDialog_149757_Content_23 = {
    Text = "¡Despierta! ¡Deja de escucharla, tu princesa está aquí!!"
  },
  AvgDialog_149757_Content_24 = {
    Text = "<Shake:…@1@2Princesa… ¿os he decepcionado?>"
  },
  AvgDialog_149757_Content_25 = {
    Text = "<Shake:No huí, fuisteis vos quien me pidió—>No, no me refería a eso, soy yo quien os ha fallado. No tengo derecho a suplicar vuestro perdón."
  },
  AvgDialog_149757_Content_26 = {
    Text = "<Shake:La vergüenza… la vergüenza la vergüenza la vergüenza la vergüenza la vergüenza la vergüenza la vergüenza la vergüenza, la vergüenza es lo único que tengo…>"
  },
  AvgDialog_149757_Content_27 = {
    Text = "<Shake:No soy un caballero, soy… soy…>"
  },
  AvgDialog_149757_Content_28 = {
    Text = "<Red:¿Quién?>"
  },
  AvgDialog_149757_Content_29 = {
    Text = "En el instante de su confusión, levantó el rostro para mirarte — si es que aún podía llamarse rostro."
  },
  AvgDialog_149757_Content_3 = {
    Text = "Si por descuido se pierde el nombre, ya sea porque uno mismo lo olvida o porque otros lo olvidan, es como una oveja que se separa del rebaño: pierde su amparo y el diablo la tiene en la mira."
  },
  AvgDialog_149757_Content_30 = {
    Text = "Las sombras habían corroído su carne, dejando rastros como los de un caracol al arrastrarse. Su semblante estaba moteado y ulcerado, y de las heridas brotaba a borbotones un lodo negro y espeso."
  },
  AvgDialog_149757_Content_31 = {
    Text = "¿A quién esperaba que le respondiera? La lluvia fría te había entumecido los labios y la lengua. Permanecías inmóvil en el barro, mientras un temblor tardío recorría tus extremidades."
  },
  AvgDialog_149757_Content_32 = {
    Text = "…Es-espera, ¡lo sé! Tú eres —"
  },
  AvgDialog_149757_Content_33 = {
    Text = "<BigShake:¡No! ¡¡Ogier!!>"
  },
  AvgDialog_149757_Content_34 = {
    Text = "El lodo negro brotó a chorros de su pecho. Tu caballero agotó sus fuerzas en el silencio y se desplomó, como una cáscara vacía abandonada, mientras las sombras lo rodeaban riendo y llorando al mismo tiempo."
  },
  AvgDialog_149757_Content_35 = {
    Text = "Fuiste testigo de cómo un hombre se desmoronaba por completo."
  },
  AvgDialog_149757_Content_36 = {
    Text = "¡Ogier! ¡Eres Ogier! ¡Lo sé, lo recuerdo! ¡El demonio no puede hacerte daño, ya lo recuerdo!"
  },
  AvgDialog_149757_Content_37 = {
    Text = "¡Despierta! ¿Me oyes? ¡Despierta ya, aún no hemos llegado! Estarás bien, la Isla de las Manzanas, el demonio no puede ir allí, ¡cuando lleguemos a la Isla de las Manzanas todo irá bien! ¡Levántate, levántate ya!"
  },
  AvgDialog_149757_Content_38 = {
    Text = "La tormenta había convertido el bosque en un pantano putrefacto. Gritabas con todas tus fuerzas, tirabas, llorabas, pero solo conseguías hundirte más. No sabías adónde más podías huir."
  },
  AvgDialog_149757_Content_39 = {
    Text = "Así que esta era la causa de la muerte del mundo… enterrado vivo por la desesperación."
  },
  AvgDialog_149757_Content_4 = {
    Text = "Quizás tu caballero, igual que tú, tuvo todo arrebatado por el monstruo; él incluso perdió más que tú, pues ni siquiera pudo conservar su nombre."
  },
  AvgDialog_149757_Content_40 = {
    Text = "<SmallShake:Tos… tos tos…>"
  },
  AvgDialog_149757_Content_41 = {
    Text = "<SmallShake:Cuando pare la lluvia… al cementerio…>"
  },
  AvgDialog_149757_Content_42 = {
    Text = "¡Ogier! ¡Sigues vivo!"
  },
  AvgDialog_149757_Content_43 = {
    Text = "Espera, ¿para qué ir al cementerio? Tú, ¿estás vivo o no?"
  },
  AvgDialog_149757_Content_44 = {
    Text = "<Shake:Al cementerio… enterrar… no hay tiempo… tengo que ir a enterrar…>"
  },
  AvgDialog_149757_Content_45 = {
    Text = "¿A quién? ¿A quién vas a enterrar?"
  },
  AvgDialog_149757_Content_46 = {Text = "..."},
  AvgDialog_149757_Content_47 = {
    Text = "Dejó de hablar y miró fijamente hacia arriba, hacia el final de todos los pantanos, donde todo recuerdo y todo olvido se disuelven, donde la lluvia cae y hace el aire cada vez más escaso."
  },
  AvgDialog_149757_Content_48 = {
    Text = "Pero vosotros no podéis alcanzar el cielo, así que solo podéis dirigiros al cementerio. Allí es donde más cerca se está del final."
  },
  AvgDialog_149757_Content_49 = {
    Text = "Solo por un pedazo de tierra vacía, hay que gastar tanto dinero…"
  },
  AvgDialog_149757_Content_5 = {
    Text = "Entonces el <Red:demonio> que acechaba mostró sus garras."
  },
  AvgDialog_149757_Content_50 = {
    Text = "Si hubieras sabido antes lo caro que es el lugar donde los monstruos se entierran a sí mismos, seguro que no habrías venido."
  },
  AvgDialog_149757_Content_51 = {
    Text = "La lluvia cayó sin cesar durante tres días y por fin hizo una breve pausa. Tu caballero resultó gravemente herido en su enfrentamiento con el demonio, y tuvo que enviarte a ti al cementerio para enterrar el paquete que llevaba consigo. Dijo que eran los objetos personales de alguien."
  },
  AvgDialog_149757_Content_52 = {
    Text = "La lápida estaba completamente en blanco, sin nombre alguno. No sabías para quién había sido erigida."
  },
  AvgDialog_149757_Content_53 = {
    Text = "Una vela, un peine, una figurita de piedra, un pergamino…"
  },
  AvgDialog_149757_Content_54 = {
    Text = "El paquete era ligero y contenía pocas cosas, pero todas estaban muy deterioradas. Por más que te esforzaste, no encontraste respuesta alguna. Tu caballero también era un misterio para ti; no sabías nada de él."
  },
  AvgDialog_149757_Content_55 = {
    Text = "…¿Incluso el cáliz sagrado hay que enterrarlo?"
  },
  AvgDialog_149757_Content_56 = {
    Text = "Eh, pequeña de allá, ¿de qué familia eres? ¿Qué estás haciendo aquí merodeando?"
  },
  AvgDialog_149757_Content_57 = {
    Text = "Unos monstruos con armadura cruzaron el cementerio. Uno de ellos se detuvo de repente, y entonces toda la fila se detuvo. Estaban perfectamente alineados, sin diferencia alguna entre ellos, como un ciempiés enorme y lleno de segmentos."
  },
  AvgDialog_149757_Content_58 = {
    Text = "¿Estás sorda? Te pregunto de dónde— ¡eh, adónde corres? ¡Atrapadla!"
  },
  AvgDialog_149757_Content_59 = {
    Text = "¡Suéltame! ¡Suéltame! ¡No he hecho nada, este terreno lo compré yo!"
  },
  AvgDialog_149757_Content_6 = {
    Text = "¿Dónde… dónde… ¿Acaso no era en esta dirección?"
  },
  AvgDialog_149757_Content_60 = {
    Text = "¿Lo compraste tú? Ja, entonces dinos, la lápida no tiene ni nombre, ¿de quién es la tumba?"
  },
  AvgDialog_149757_Content_61 = {Text = "I... I..."},
  AvgDialog_149757_Content_62 = {
    Text = "Señores, este es el cementerio de la Diócesis. La niña sí compró el terreno; está registrado en el libro de registros."
  },
  AvgDialog_149757_Content_63 = {
    Text = "En cuanto al nombre, la peste ya ha llegado. Cada día desaparecen personas. ¿Acaso escasean las lápidas sin nombre?"
  },
  AvgDialog_149757_Content_64 = {
    Text = "Los rostros de los monstruos cambiaron. Se miraron unos a otros y se marcharon apresuradamente, como si temieran contagiarse de algo. En aquellos ojos reconociste un miedo familiar."
  },
  AvgDialog_149757_Content_65 = {Text = "¿Plaga?"},
  AvgDialog_149757_Content_66 = {
    Text = "Sí, la cruel peste, la terrible peste. Hacer que las personas olviden solo requiere un poco de tiempo; hacer que las piedras olviden, en cambio, requiere convertirlas en arena."
  },
  AvgDialog_149757_Content_67 = {
    Text = "Cada vez hay más piedras que olvidan, los ancianos quedan tan en blanco como los niños. Ya no tenemos historias."
  },
  AvgDialog_149757_Content_68 = {
    Text = "Tú… ¿no crees que esto es una maldición? Por culpa de alguna bruja, o de algo más."
  },
  AvgDialog_149757_Content_69 = {
    Text = "Maldición, plaga, castigo del Señor o venganza del caballero de la muerte, ¿qué diferencia hay? No podemos hacer nada, niño, solo podemos contemplar el presente, el presente es todo lo que podemos tener, siempre ha sido así."
  },
  AvgDialog_149757_Content_7 = {
    Text = "La noche sin luna era demasiado oscura, y el denso bosque parecía no tener fondo. Con la Linterna entre tus brazos, buscabas por todas partes siguiendo los rastros de una huida desesperada."
  },
  AvgDialog_149757_Content_70 = {
    Text = "Vuelve a casa, pronto oscurecerá."
  },
  AvgDialog_149757_Content_71 = {
    Text = "Espera, ¿el caballero de la muerte? ¿Qué es eso?"
  },
  AvgDialog_149757_Content_72 = {
    Text = "Una leyenda. Aquella guerra fue un error, clamaban por erradicar la plaga y solo lograron que llegara más rápido, crearon un monstruo."
  },
  AvgDialog_149757_Content_73 = {
    Text = "Se oculta en las sombras de los árboles, los barcos, los muros de piedra y las aves en vuelo, desplazándose de un lugar a otro, sin que la luz del sol pueda alcanzarlo."
  },
  AvgDialog_149757_Content_74 = {
    Text = "Su sangre es negra como la pez, su corazón arde con fuego espectral, sus ojos brillan como luces en lo profundo de un pantano, y allí donde pasa, deja sombras que parten el día en dos."
  },
  AvgDialog_149757_Content_75 = {
    Text = "Es la prolongación de aquella guerra, la suma del rencor de los muertos, solo aparece de noche para aniquilar a sus enemigos. Nunca olvida, nunca descuida, el motivo de su llegada es evidente: nuestro señor gobernó una tierra que una vez le perteneció."
  },
  AvgDialog_149757_Content_76 = {
    Text = "¿Qué? ¿Quieres decir que el señor es su enemigo y que vino aquí… para vengarse?"
  },
  AvgDialog_149757_Content_77 = {
    Text = "Por supuesto, todos lo sabemos, el señor también lo sabe. ¿Si no, por qué de repente hay tantos soldados patrullando la ciudad?"
  },
  AvgDialog_149757_Content_78 = {
    Text = "Todos lo están esperando."
  },
  AvgDialog_149757_Content_79 = {
    Text = "La lluvia ha vuelto a caer, las calles parecen un río que fluye."
  },
  AvgDialog_149757_Content_8 = {
    Text = "Antes de ser engullido por las sombras, él te pidió que te fueras, pero ¿cómo podría una princesa quedarse sin su caballero? Intentaste rescatarlo, pero él apartó tu mano de un manotazo, rompió la ventana de un golpe y saltó desde el altillo, desapareciendo en el bosque salvaje más allá de la mansión."
  },
  AvgDialog_149757_Content_80 = {
    Text = "Corres a toda velocidad por los callejones estrechos con todas las reliquias entre los brazos, esquivando por los pelos a una patrulla tras otra de guardias, directo al cobertizo de paja donde os escondéis."
  },
  AvgDialog_149757_Content_81 = {
    Text = "<Shake:Rápido, rápido, vuelve y dile…>"
  },
  AvgDialog_149757_Content_82 = {
    Text = "El monstruo en boca de los monstruos, sin duda tu caballero, cuyas matanzas a plena vista han llegado por fin a oídos del señor. Se dice que esta noche los guardias registrarán hasta el último rincón de la ciudad."
  },
  AvgDialog_149757_Content_83 = {
    Text = "Aún hay tiempo, las puertas de la ciudad no se han cerrado, solo hay que ir un poco más rápido…"
  },
  AvgDialog_149757_Content_84 = {
    Text = "<Big:¡Ogier! ¡Corre, vienen a por nosotros!>"
  },
  AvgDialog_149757_Content_85 = {
    Text = "El estrecho cobertizo está construido al fondo de un callejón sin salida, rodeado de sacos de arpillera apilados que aun así no logran contener el barro que se derrama. Te lanzas hacia la figura tendida en el rincón más profundo y agarras su capa de un tirón — solo la capa."
  },
  AvgDialog_149757_Content_86 = {
    Text = "Dentro del cobertizo no hay nada más que paja seca, tu caballero ha desaparecido sin dejar rastro."
  },
  AvgDialog_149757_Content_9 = {
    Text = "La tormenta había borrado las ramas rotas y las huellas que quedaban. El paisaje a tu alrededor era idéntico en todas direcciones, tus pasos se volvían cada vez más lentos hasta que finalmente te detuviste, desorientada."
  },
  AvgDialog_15363_Content_1 = {
    Text = "La Dama Coral Caída"
  },
  AvgDialog_15363_Content_10 = {
    Text = "La gente se apiñaba tan apretada a su alrededor que ni una gota de agua habría podido pasar. Innumerables flashes de cámaras se dispararon al unísono, y un clamor de conversaciones subía y bajaba—hasta que un miembro del personal retiró la cubierta de un solo movimiento."
  },
  AvgDialog_15363_Content_11 = {
    Text = "Esto es... Dios mío."
  },
  AvgDialog_15363_Content_12 = {
    Text = "...Increíble."
  },
  AvgDialog_15363_Content_13 = {
    Text = "Como si se hubiera accionado un interruptor, la multitud enmudeció por sí sola. La sala, antes ruidosa y animada, de repente se sintió casi vacía."
  },
  AvgDialog_15363_Content_14 = {
    Text = "Te abriste paso a empujones entre la multitud, logrando al fin vislumbrar la obra rodeada en el centro."
  },
  AvgDialog_15363_Content_15 = {Text = "..."},
  AvgDialog_15363_Content_16 = {
    Text = "Era Sanga. Ella había perdido todo color y emoción, transformada en una escultura de coral blanco puro."
  },
  AvgDialog_15363_Content_17 = {
    Text = "La brillante luz del día se refractaba a través de la prístina cúpula de cristal de Arriba, envolviendo a Ella en un suave velo de luz dorada pálida."
  },
  AvgDialog_15363_Content_18 = {
    Text = "Bajaste la mirada hacia la placa de latón en el pedestal de la escultura. Arriba, en una elegante caligrafía, estaba grabado el nombre de la escultura: <Red:\"Hija del Coral Sin Nombre\">."
  },
  AvgDialog_15363_Content_19 = {
    Text = "Coral Sin Nombre..."
  },
  AvgDialog_15363_Content_2 = {
    Text = "Estimado Monsieur Claudel:\n\nHan sucedido muchas cosas últimamente. Le ruego disculpe mi tardanza en responder.\n\nTras la partida de la señorita Sanga, Monsieur Agosto nunca más fue capaz de producir obras destacables.\nBajo la presión de la opinión pública, anunció la suspensión indefinida de su carrera como escultor.\nRecibió el castigo que merecía, pero no logro alegrarme—<Yellow:el paradero de la señorita Sanga sigue siendo desconocido.>"
  },
  AvgDialog_15363_Content_20 = {
    Text = "Contemplaste la cadena de palabras aturdido, tu consciencia parecía mecerse y retorcerse junto con aquellas elegantes curvas de las letras..."
  },
  AvgDialog_15363_Content_21 = {
    Text = "Levantaste una mano para frotarte los ojos, solo para Descubrir que, en algún momento, capas de un blanco áspero y opaco habían comenzado a trepar por tus dedos."
  },
  AvgDialog_15363_Content_22 = {Text = "¿?!"},
  AvgDialog_15363_Content_23 = {
    Text = "La bruma de coral blanco continuó su Propagación desde tus dedos, cubriendo todo tu cuerpo poco a poco, inundando rápidamente toda la sala de exposiciones, y entonces—"
  },
  AvgDialog_15363_Content_24 = {Text = "—¡!!"},
  AvgDialog_15363_Content_25 = {
    Text = "Tú y la sala de exposiciones se fragmentaron simultáneamente en incontables pedazos blancos, precipitándose hacia las profundidades sin fin del océano."
  },
  AvgDialog_15363_Content_26 = {
    Text = "Entre incontables esculturas blancas y corales, bajo la tranquila luz matutina, las ruinas blancas de un palacio se alzaban imponentes."
  },
  AvgDialog_15363_Content_27 = {
    Text = "Peces de todos los colores se escabullían entre los arcos inclinados y los corredores de las ruinas, disfrutando de sus agradables momentos de ocio."
  },
  AvgDialog_15363_Content_28 = {
    Text = "Las ruinas enteras parecían abandonadas en la sombra del tiempo, lejos de la Corrosión del mundo mundano, alejadas de las molestias de la multitud."
  },
  AvgDialog_15363_Content_29 = {
    Text = "Una vez que hayas visto esos Milagros... me comprenderás..."
  },
  AvgDialog_15363_Content_3 = {
    Text = "<Yellow:Mañana iré a la exposición del Salón de la Cité a buscar las \"respuestas\" de las que habló la señorita Sanga.>\nDeséame suerte.\n\nCamille@1\nA.F.2@1, septiembre"
  },
  AvgDialog_15363_Content_30 = {
    Text = "¿Es este... el Milagro que viste, señorita Sanga?"
  },
  AvgDialog_15363_Content_31 = {
    Text = "Flotaste a través de las cálidas aguas marinas, contemplando todo ante ti con fascinación y desconcierto."
  },
  AvgDialog_15363_Content_32 = {
    Text = "¡¡Apártense, déjenme pasar!!"
  },
  AvgDialog_15363_Content_33 = {
    Text = "<Big:¡Déjame pasar!!>"
  },
  AvgDialog_15363_Content_34 = {
    Text = "El clamor del alboroto te arrastró de vuelta a la realidad."
  },
  AvgDialog_15363_Content_35 = {
    Text = "Un anciano harapiento rompió las capas de Esclavitud de seguridad y se abalanzó hacia ti, aferrando tu mano con un agarre mortal."
  },
  AvgDialog_15363_Content_36 = {
    Text = "Tú también lo viste, ¿verdad? El mar profundo, el palacio, todas esas ilusiones caóticas..."
  },
  AvgDialog_15363_Content_37 = {Text = "?!"},
  AvgDialog_15363_Content_38 = {
    Text = "Esta mujer malvada, Ella es una ladrona..."
  },
  AvgDialog_15363_Content_39 = {
    Text = "El anciano murmuraba sin cesar. Contemplaste el rostro oculto bajo el ala ancha de su sombrero y la espesa barba, y de repente vislumbraste algo familiar."
  },
  AvgDialog_15363_Content_4 = {
    Text = "Exposición del Salón de la Cité\nDía de inauguración"
  },
  AvgDialog_15363_Content_40 = {
    Text = "...¿¡Sr. Agosto?!"
  },
  AvgDialog_15363_Content_41 = {
    Text = "Hiss, realmente es él... ¡Dios mío! ¿Qué le ha pasado?"
  },
  AvgDialog_15363_Content_42 = {
    Text = "Se arruinó hace mucho tiempo, ¿no lo escuchaste? Después del fiasco de la \"Musa Trágica\", invirtió mucho en varios proyectos, pero ninguno se vendió"
  },
  AvgDialog_15363_Content_43 = {
    Text = "El gobierno desconfía de su reputación ahora y ha dejado de darle encargos. Probablemente se ha vuelto loco por demasiado estrés..."
  },
  AvgDialog_15363_Content_44 = {
    Text = "La multitud observaba a Agosto desde una distancia prudente, tanto conmocionada como temerosa."
  },
  AvgDialog_15363_Content_45 = {
    Text = "Agosto apartó tu mano de un tirón. Cojeó hacia la escultura, con los ojos rebosantes de un Odio que ya no podía contener."
  },
  AvgDialog_15363_Content_46 = {
    Text = "Ja... ¿Pensaste que morir borraría todo lo que has hecho?"
  },
  AvgDialog_15363_Content_47 = {
    Text = "Engañaste a Todos... Mi talento, mi Inspiración y mi reputación, todo me lo arrebataste tú."
  },
  AvgDialog_15363_Content_48 = {
    Text = "Estoy arruinado, completamente arruinado. ¿Y tú? Sentada aquí tan tranquila, disfrutando de que todos te Miren hacia arriba, esperando a que te consagren como un clásico..."
  },
  AvgDialog_15363_Content_49 = {Text = "..."},
  AvgDialog_15363_Content_5 = {
    Text = "¿Te has enterado? El Sr. Agosto ha venido a exponer sus esculturas de nuevo."
  },
  AvgDialog_15363_Content_50 = {
    Text = "Ante las Maldiciones histéricas de su antiguo maestro, la escultura permaneció en silencio, sin que su expresión indiferente se alterara en lo más mínimo."
  },
  AvgDialog_15363_Content_51 = {
    Text = "Agosto no pudo soportarlo más. Se abalanzó ferozmente contra la escultura."
  },
  AvgDialog_15363_Content_52 = {
    Text = "Esa expresión otra vez, esa burla otra vez...\""
  },
  AvgDialog_15363_Content_53 = {
    Text = "Demonio... ¡Demonio! <Big:¡Te arrancaré la máscara!>"
  },
  AvgDialog_15363_Content_6 = {
    Text = "¿Agosto, el escultor? ¿No desapareció después de que le lanzaran esa Dudar sobre el plagio? Pensé que nunca volvería a dar la cara."
  },
  AvgDialog_15363_Content_7 = {
    Text = "Aunque tengo bastante curiosidad. Sin esa aprendiz suya, ¿qué podría crear ahora..."
  },
  AvgDialog_15363_Content_8 = {
    Text = "La ceremonia de inauguración de la exposición del salón estaba repleta de visitantes."
  },
  AvgDialog_15363_Content_9 = {
    Text = "La obra de Agosto se encontraba en el centro de la sala de exposiciones, cubierta bajo capas de tela pesada, despertando la curiosidad de innumerables espectadores."
  },
  AvgDialog_15364_Content_1 = {Text = "¡UUGHH!"},
  AvgDialog_15364_Content_10 = {
    Text = "Exposición del Salón Cité\nNoche de inauguración"
  },
  AvgDialog_15364_Content_11 = {
    Text = "Cuando la última Cerradura de hierro encajó en su lugar, la sala de exposiciones se sumió en un silencio de oscuridad absoluta."
  },
  AvgDialog_15364_Content_12 = {
    Text = "Saliste de las sombras en la esquina y te plantaste ante Ella una vez más."
  },
  AvgDialog_15364_Content_13 = {
    Text = "Libre del bullicio del día, este era el momento perfecto para hablar."
  },
  AvgDialog_15364_Content_14 = {
    Text = "Señorita Sanga, el señor Agosto fue llevado hoy. Dijo...\nQue engañaste a Todos."
  },
  AvgDialog_15364_Content_15 = {
    Text = "¿\"Todos\" me incluye a mí?"
  },
  AvgDialog_15364_Content_16 = {Text = "..."},
  AvgDialog_15364_Content_17 = {
    Text = "Una vez prometiste que vendrías a casa conmigo. ¿Era verdad?"
  },
  AvgDialog_15364_Content_18 = {Text = "..."},
  AvgDialog_15364_Content_19 = {
    Text = "La escultura permaneció en silencio como siempre. Aunque las vidas de todos se habían desviado de su curso por culpa de Ella, nunca bajó la mirada de la distancia."
  },
  AvgDialog_15364_Content_2 = {
    Text = "Suéltenme, a quien deberían arrestar es a Ella, es Ella—"
  },
  AvgDialog_15364_Content_20 = {
    Text = "La luz de la Luna atravesaba los ventanales de cristal de la sala de exposiciones, envolviéndola en una bruma de luz blanca y pálida."
  },
  AvgDialog_15364_Content_21 = {
    Text = "<Red:Sigue mi mirada...>"
  },
  AvgDialog_15364_Content_22 = {
    Text = "Sigue la mirada... ¿Podría ser?!"
  },
  AvgDialog_15364_Content_23 = {
    Text = "Te pusiste de puntillas, solo para Descubrir que bajo la luz de la Luna, los ojos antes distantes y desenfocados de la escultura habían cambiado hacía tiempo, cristalizándose en algo concreto e intensamente emotivo."
  },
  AvgDialog_15364_Content_24 = {
    Text = "Su mirada siempre había estado fija en la distancia."
  },
  AvgDialog_15364_Content_25 = {
    Text = "Te diste la vuelta, siguiendo su línea de visión."
  },
  AvgDialog_15364_Content_26 = {
    Text = "En el instante en que tus ojos vagaron, la sala de exposiciones bajo tus pies desapareció como por Milagro."
  },
  AvgDialog_15364_Content_27 = {
    Text = "En su lugar se extendía un mar infinito y una vasta extensión de arena blanca."
  },
  AvgDialog_15364_Content_28 = {
    Text = "El retumbar de un trueno lejano rodó hacia ti mientras las mareas Surge violentamente, precipitándose en tu dirección."
  },
  AvgDialog_15364_Content_29 = {
    Text = "Este era el mar que tú y Sanga habían visitado juntas."
  },
  AvgDialog_15364_Content_3 = {
    Text = "Sr. Agosto, hemos recibido una denuncia de que su comportamiento ha causado una grave alteración del orden de la exposición del salón. Por favor, acompáñenos ahora."
  },
  AvgDialog_15364_Content_4 = {Text = "No, no..."},
  AvgDialog_15364_Content_5 = {
    Text = "La escena era un Caos absoluto. La multitud que surgía de todas direcciones te separó completamente de Agosto. Solo pudiste observar cómo era arrastrado a la fuerza por la policía."
  },
  AvgDialog_15364_Content_6 = {
    Text = "No cantes victoria tan pronto... Una día, acabarás igual que yo..."
  },
  AvgDialog_15364_Content_7 = {
    Text = "Je... Jejejej..."
  },
  AvgDialog_15364_Content_8 = {
    Text = "El orden fue finalmente restaurado en la sala de exposiciones."
  },
  AvgDialog_15364_Content_9 = {
    Text = "La última risa temblorosa y neurótica de Agosto persistió como ondas que se desvanecían, apenas perceptibles en la vasta y vacía sala."
  },
  AvgDialog_15365_Content_1 = {
    Text = "Medios del mar"
  },
  AvgDialog_15365_Content_10 = {
    Text = "Así que eres tú.\nPerdona, ¿te desperté al levantarme?"
  },
  AvgDialog_15365_Content_11 = {
    Text = "En lugar de preocuparte por despertarme, deberías preocuparte más por molestar a esos <Blue:viejos que duermen bajo tierra>."
  },
  AvgDialog_15365_Content_12 = {
    Text = "Alzaste la barbilla para señalar la tumba frente a ella, excavada casi un pie de profundidad."
  },
  AvgDialog_15365_Content_13 = {
    Text = "Parece que buscas algo. ¿Necesitas ayuda?"
  },
  AvgDialog_15365_Content_14 = {
    Text = "Está bien, ya lo he encontrado."
  },
  AvgDialog_15365_Content_15 = {
    Text = "Sanga abrió la mano hacia ti con una radiante sonrisa. Estaba cubierta de un líquido viscoso de un negro intenso—"
  },
  AvgDialog_15365_Content_16 = {
    Text = "D-Slime. No podría resultarte más familiar."
  },
  AvgDialog_15365_Content_17 = {
    Text = "¿Ves? Bajo la luz de la luna, emiten un extraño tono azulado. Durante el día, adoptan una apariencia completamente diferente..."
  },
  AvgDialog_15365_Content_18 = {
    Text = "Este es el material de escultura más perfecto que he visto en mi vida."
  },
  AvgDialog_15365_Content_19 = {Text = "..."},
  AvgDialog_15365_Content_2 = {
    Text = "Estimado Sr. Claud:\n\nLa Srta. Sanga no ha rechazado la petición de volver a casa, pero espera que pueda darle algo de tiempo.\nDijo: <Yellow:Cuando termine la exposición del Salón, podré volver a casa.>\n\nDicho esto, el Estado de la Srta. Sanga últimamente ha sido preocupante.\nCada noche se escabulle en silencio y no regresa hasta la madrugada."
  },
  AvgDialog_15365_Content_20 = {
    Text = "¿Has estado escapándote cada noche solo para recolectar D-Slime aquí?"
  },
  AvgDialog_15365_Content_21 = {
    Text = "¿Sabes cómo se llaman? Parece que estás bastante familiarizada con ellos."
  },
  AvgDialog_15365_Content_22 = {
    Text = "No es... nada raro. Hay mucho de eso en Besanzón."
  },
  AvgDialog_15365_Content_23 = {
    Text = "Ya veo... Yo pensaba que era un descubrimiento maravilloso solo mío."
  },
  AvgDialog_15365_Content_24 = {
    Text = "Fusión... Qué nombre tan apropiado, sin duda."
  },
  AvgDialog_15365_Content_25 = {
    Text = "No es momento para bromas, Sanga."
  },
  AvgDialog_15365_Content_26 = {
    Text = "Morirás. Esto no es algo que la gente corriente como nosotras debería tocar."
  },
  AvgDialog_15365_Content_27 = {
    Text = "Lo entiendo, por supuesto que lo entiendo... La belleza inevitablemente atrae el peligro."
  },
  AvgDialog_15365_Content_28 = {
    Text = "Pero, por otro lado, ¿acaso el peligro en sí no es una forma de belleza?\nPara mí, la muerte no es algo que deba temerse."
  },
  AvgDialog_15365_Content_29 = {
    Text = "Lo verdaderamente aterrador es..."
  },
  AvgDialog_15365_Content_3 = {
    Text = "Curiosamente, este patrón persistente de dormir de día y salir de noche la ha llenado de vitalidad,\ne incluso el Sr. Agosto está bastante satisfecho con su eficiencia de trabajo reciente.\n\n<Yellow:Se ha vuelto tan irreconocible.>\n\nVarias noches, me desperté de pesadillas y la encontré simplemente de pie junto a mi cama...\nMe miraba fijamente sin parpadear, con los ojos llenos de cosas aterradoras que no podía comprender."
  },
  AvgDialog_15365_Content_30 = {
    Text = "Una suave brisa de Viento pasó, tragándose las siguientes palabras de Sanga. La Luna había emergido de entre las capas de nubes oscuras en algún momento, derramando su fría luz lunar sobre ustedes dos."
  },
  AvgDialog_15365_Content_31 = {
    Text = "Entonces viste las cicatrices en el cuello de Sanga."
  },
  AvgDialog_15365_Content_32 = {
    Text = "Eran como Tentáculos de coral, Propagándose cada vez más hacia arriba, parpadeando con un Mar de Ardora gris azulado en los intervalos donde la luz de la luna cambiaba."
  },
  AvgDialog_15365_Content_33 = {
    Text = "Señorita Sanga, ¿ya ha sido infectada...?!"
  },
  AvgDialog_15365_Content_34 = {
    Text = "Aun sabiendo que esto era Solo un Sueño, tu corazón sintió una breve punzada de dolor."
  },
  AvgDialog_15365_Content_35 = {
    Text = "Después de todo, ahora poseías todos los recuerdos y emociones de la huésped original. ¿Quién es esta Doncella del campo de Besanzón que sentía un profundo afecto por Ella, su señora?"
  },
  AvgDialog_15365_Content_36 = {
    Text = "¿Es por el señor Agosto? ¿Sus palabras te presionaron demasiado, así que...?"
  },
  AvgDialog_15365_Content_37 = {
    Text = "Sanga negó con la cabeza."
  },
  AvgDialog_15365_Content_38 = {
    Text = "De principio a fin, este asunto no tuvo nada que ver con él.\nVen, déjame llevarte a un lugar."
  },
  AvgDialog_15365_Content_39 = {
    Text = "Por fin llegamos — mi base secreta."
  },
  AvgDialog_15365_Content_4 = {
    Text = "<Yellow:He decidido seguirla en secreto esta noche y ver qué está haciendo realmente.>\nDeséame suerte.\n\nCamille@1\nA.F.2@1 Septiembre"
  },
  AvgDialog_15365_Content_40 = {
    Text = "Era un almacén abandonado junto al mar. Dentro había muchos Estudios de escultura retorcidos de formas extrañas en todo tipo de poses."
  },
  AvgDialog_15365_Content_41 = {
    Text = "Coral, conchas, tentáculos, y edificios y criaturas adornados con extraños grabados... Su única afinidad es su estrecha conexión con el océano."
  },
  AvgDialog_15365_Content_42 = {
    Text = "La textura de estas esculturas..."
  },
  AvgDialog_15365_Content_43 = {
    Text = "No es ni mármol ni granito. ¿Dónde encontraste este material?"
  },
  AvgDialog_15365_Content_44 = {
    Text = "Sanga te dedicó un parpadeo juguetón."
  },
  AvgDialog_15365_Content_45 = {
    Text = "Eso es mi secreto. Algún día lo descubrirás."
  },
  AvgDialog_15365_Content_46 = {
    Text = "En el centro de la cabaña de madera se alzaba una escultura humanoide sin terminar."
  },
  AvgDialog_15365_Content_47 = {
    Text = "Su cuerpo estaba envuelto en retorcidos Tentáculos, doblado en ángulos imposibles. Las venas del cuello sobresalían tensas, Como Si fueran una serpiente sinuosa."
  },
  AvgDialog_15365_Content_48 = {
    Text = "Hermoso, ¿no?\nTodos me llaman \"la Carnicera\", porque siempre soy despiadada con mis modelos."
  },
  AvgDialog_15365_Content_49 = {
    Text = "Pero es precisamente por eso que puedo capturar la esencia — la agonía enmarañada que yace bajo la piel y la carne."
  },
  AvgDialog_15365_Content_5 = {
    Text = "Septiembre en la Cité ya es amargamente frío.\nCaminas silenciosamente por la calle, tratando de ocultarte en las sombras."
  },
  AvgDialog_15365_Content_50 = {
    Text = "Pero mi maestro siempre trataba a sus modelos con excesivo cuidado, por eso nunca pudo ser más que un escultor de segunda categoría."
  },
  AvgDialog_15365_Content_51 = {
    Text = "Contemplas la escultura ante ti. Es innegablemente hermosa, pero también cruel."
  },
  AvgDialog_15365_Content_52 = {
    Text = "¿Es esta la pieza que planeas llevar a la exposición?"
  },
  AvgDialog_15365_Content_53 = {
    Text = "Sanga negó con la cabeza."
  },
  AvgDialog_15365_Content_54 = {
    Text = "Solo algunos bocetos. Antes de encontrarme con esos... D-Slimes, mi comprensión de la escultura era aún bastante superficial."
  },
  AvgDialog_15365_Content_55 = {
    Text = "Ahora soy como una recién nacida que acaba de abrir los ojos, obligada a redescubrir el mundo ante mí..."
  },
  AvgDialog_15365_Content_56 = {
    Text = "<Yellow:Y a redescubrirte a ti.>"
  },
  AvgDialog_15365_Content_57 = {Text = "¿Yo...?"},
  AvgDialog_15365_Content_58 = {
    Text = "Sí, a ti. En tus ojos y tu expresión, veo nuevas posibilidades."
  },
  AvgDialog_15365_Content_59 = {
    Text = "Sanga trazó suavemente los contornos de tu rostro con sus dedos."
  },
  AvgDialog_15365_Content_6 = {
    Text = "La esbelta figura de Sanga estaba justo delante.\nMantenías una distancia entre ambas —ni demasiado cerca ni demasiado lejos— como si estuvierais conectadas por un hilo invisible."
  },
  AvgDialog_15365_Content_60 = {
    Text = "A diferencia de otras señoritas consentidas, las yemas de sus dedos tenían una fina capa de callosidades, dándoles una textura singularmente áspera."
  },
  AvgDialog_15365_Content_61 = {
    Text = "Tienes miedo. No te preocupes, no te obligaré a hacer nada."
  },
  AvgDialog_15365_Content_62 = {
    Text = "¿Aún recuerdas cuando éramos niños?"
  },
  AvgDialog_15365_Content_63 = {
    Text = "¿Cuando éramos niños?"
  },
  AvgDialog_15365_Content_64 = {
    Text = "Siguiendo sus palabras, te adentras cada vez más en los enmarañados recuerdos del dueño original, explorando..."
  },
  AvgDialog_15365_Content_65 = {
    Text = "Hasta que finalmente te detienes en aquel verano tenue y brumoso."
  },
  AvgDialog_15365_Content_66 = {
    Text = "Claro que lo recuerdo. Cuando tenías 5 años, ya podías esculpir un esqueleto humano con barro."
  },
  AvgDialog_15365_Content_67 = {
    Text = "Yo iba a la orilla del mar a buscar todo tipo de materiales para ti, y el Señorito Paul Claud se encargaba de meter esos modelos en el horno para cocerlos."
  },
  AvgDialog_15365_Content_68 = {
    Text = "Sí, era nuestro pequeño secreto — solo de nosotros tres."
  },
  AvgDialog_15365_Content_69 = {
    Text = "Una vez, cuando tu padre lo descubrió, tú asumiste toda la culpa y hasta te hicieron quedarte de pie como castigo toda una noche."
  },
  AvgDialog_15365_Content_7 = {
    Text = "Ese hilo os guio a ambas más allá de edificio tras edificio, a través de la larga y lúgubre escarcha, hasta que finalmente llegasteis a vuestro destino compartido—"
  },
  AvgDialog_15365_Content_70 = {
    Text = "Una fina y triste bruma afloró en los ojos grises de Sanga."
  },
  AvgDialog_15365_Content_71 = {
    Text = "Ella te abraza suavemente."
  },
  AvgDialog_15365_Content_72 = {
    Text = "Todos sois mi familia, para siempre. Fue Paul quien te envió a buscarme, ¿verdad?"
  },
  AvgDialog_15365_Content_73 = {
    Text = "Sí. El señorito... ha caído enfermo y no pudo venir en persona."
  },
  AvgDialog_15365_Content_74 = {
    Text = "Respiras suavemente contra el hueco del cuello de Sanga, su aroma llenándote las fosas nasales.\nEl sabor embriagador de las olas del mar."
  },
  AvgDialog_15365_Content_75 = {
    Text = "No te preocupes. Ya que te prometí que volveríamos a casa juntos, no faltaré a mi palabra."
  },
  AvgDialog_15365_Content_76 = {
    Text = "Pero antes de eso, debo dejarte."
  },
  AvgDialog_15365_Content_77 = {
    Text = "¿Dejarme...? ¿Adónde vas?"
  },
  AvgDialog_15365_Content_78 = {
    Text = "Sanga no dice nada más y se vuelve para contemplar el brumoso mar gris del exterior."
  },
  AvgDialog_15365_Content_79 = {
    Text = "Es una noche envuelta en niebla. Las suaves olas avanzan en un ritmo eterno e inmutable, igual que el pulso que se siente en el costado del cuello de Sanga."
  },
  AvgDialog_15365_Content_8 = {
    Text = "Una tumba desolada."
  },
  AvgDialog_15365_Content_80 = {
    Text = "No lo sé. Quizás las profundidades del océano, o quizás @1..."
  },
  AvgDialog_15365_Content_81 = {
    Text = "Después de aquel día, la señorita Sanga desapareció."
  },
  AvgDialog_15365_Content_82 = {
    Text = "Fui a todos los lugares que pude, pregunté a todas las personas que encontré, pero no hallé nada.\n\nSe fue como una ráfaga de viento.\nIncluso ahora, sigo reviviendo aquella noche junto al mar, una y otra vez."
  },
  AvgDialog_15365_Content_83 = {
    Text = "En aquel momento, la señorita Sanga me abrazó con fuerza.\nQuizá me dijo algo más después, o quizá no. No lo sé.\n\nMis recuerdos empezaron a volverse borrosos a partir de aquel día.\n\n<Red:Coral blanco, conchas en espiral, un palacio misterioso bajo el mar...>\nIncluso ahora, esas imágenes caóticas siguen atormentando mi mente en la oscuridad de la noche."
  },
  AvgDialog_15365_Content_84 = {
    Text = "<Yellow:\"Ve a la exposición del Salón y busca las respuestas.\">\n\nEso fue lo que la señorita Sanga me dijo. También dijo—"
  },
  AvgDialog_15365_Content_85 = {
    Text = "Cuando hayas presenciado esos milagros, me comprenderás."
  },
  AvgDialog_15365_Content_86 = {
    Text = "Solo sigas mi mirada..."
  },
  AvgDialog_15365_Content_87 = {
    Text = "Te lo prometo."
  },
  AvgDialog_15365_Content_9 = {
    Text = "Miss Sanga."
  },
  AvgDialog_15367_Content_1 = {
    Text = "¡Aléjate, no me toques...!!"
  },
  AvgDialog_15367_Content_10 = {
    Text = "Sé que has estado dirigiendo en secreto una especie de <Yellow:estudio> por tu cuenta, pero creo que debería recordarte algo."
  },
  AvgDialog_15367_Content_11 = {
    Text = "No esperes que tus <Yellow:Profanación, abominables creaciones de aficionada> se ganen el favor de los funcionarios del gobierno."
  },
  AvgDialog_15367_Content_12 = {
    Text = "Admito que tienes mucho talento, y has sido de gran ayuda para el estudio. Pero para dedicarse al arte en un lugar como Cité, se necesita mucho más que talento."
  },
  AvgDialog_15367_Content_13 = {
    Text = "Si me enfadas..."
  },
  AvgDialog_15367_Content_14 = {
    Text = "Señor August, por favor, cuida tus palabras."
  },
  AvgDialog_15367_Content_15 = {
    Text = "Está bien, Camille."
  },
  AvgDialog_15367_Content_16 = {
    Text = "Sanga te jaló suavemente hacia atrás desde detrás. Ante los reproches de Agosto, su expresión permaneció serena."
  },
  AvgDialog_15367_Content_17 = {
    Text = "Se arrodilló, recogió uno a uno los fragmentos rotos del rostro de la escultura y los arrojó al montón de basura cercano."
  },
  AvgDialog_15367_Content_18 = {
    Text = "Si te hago enfadar, mis obras no podrán exhibirse, no podrán venderse, y como artista nunca veré la luz del día. Y al final..."
  },
  AvgDialog_15367_Content_19 = {
    Text = "Solo me moriré de frío en las calles, o me enviarán a un asilo."
  },
  AvgDialog_15367_Content_2 = {
    Text = "Todos se apresuraron a contener a ¿Quién es — el maestro escultor, fuera de sí de ira."
  },
  AvgDialog_15367_Content_20 = {
    Text = "Por supuesto que sé todo esto perfectamente, maestro."
  },
  AvgDialog_15367_Content_3 = {
    Text = "No seas imprudente, querida maestra."
  },
  AvgDialog_15367_Content_4 = {
    Text = "Una obra tan mediocre arruinaría no solo mi ánimo, sino también su reputación."
  },
  AvgDialog_15367_Content_5 = {
    Text = "Je... No seas tan presuntuosa. La exposición del Salón es en menos de medio año. ¿Acaso puedes sacar algo mejor de la nada?"
  },
  AvgDialog_15367_Content_6 = {Text = "Un mes."},
  AvgDialog_15367_Content_7 = {Text = "...¿Qué?"},
  AvgDialog_15367_Content_8 = {
    Text = "Dame un mes, y te entregaré una absoluta <Yellow:sorpresa>."
  },
  AvgDialog_15367_Content_9 = {Text = "...Hmph."},
  AvgDialog_15368_Content_1 = {
    Text = "Una carta para ti"
  },
  AvgDialog_15368_Content_10 = {
    Text = "Tus sienes están palpitando. Intentas mover tu cuerpo, pero—"
  },
  AvgDialog_15368_Content_11 = {Text = "¡Ah!..."},
  AvgDialog_15368_Content_12 = {
    Text = "<Shake:Mis piernas... se me han dormido...>"
  },
  AvgDialog_15368_Content_13 = {
    Text = "Vaya, ¿será mi imaginación? En el momento en que abriste los ojos, me pareció ver un brillo que nunca había visto antes."
  },
  AvgDialog_15368_Content_14 = {
    Text = "No, no es mi imaginación. Tu expresión también es diferente..."
  },
  AvgDialog_15368_Content_15 = {
    Text = "Los ojos de la joven aprendiz de escultora brillan con Elación mientras de repente se acerca mucho a ti."
  },
  AvgDialog_15368_Content_16 = {
    Text = "¿Quién eres tú?"
  },
  AvgDialog_15368_Content_17 = {
    Text = "Tu Sirvienta"
  },
  AvgDialog_15368_Content_18 = {
    Text = "<Shake:S–soy tu Sirvienta, Camille@1! ¿No te acuerdas? Jaja...>"
  },
  AvgDialog_15368_Content_19 = {
    Text = "Mantienes tu identidad firmemente en mente."
  },
  AvgDialog_15368_Content_2 = {
    Text = "Estimado Monsieur Claudel:\n\nHe llegado a Cité.\nA diferencia de la tranquilidad de Besançon, este lugar siempre está lleno de ruido estridente.\nRepiques de campanas, el traqueteo de los carruajes y el incesante bullicio de la multitud...\nPensar que la señorita Sanga ha estado viviendo en semejante entorno me llena de inquietud."
  },
  AvgDialog_15368_Content_20 = {
    Text = "Esta vez, eres la Doncella que creció con Sanga desde la infancia, enviada por el Señorito Paul para llevar a Sanga a casa."
  },
  AvgDialog_15368_Content_21 = {
    Text = "\"Debes rescatar su alma de las garras de ese demonio que Solo explota y plagia a los demás.\""
  },
  AvgDialog_15368_Content_23 = {
    Text = "<Gray:No, eso no es correcto...>"
  },
  AvgDialog_15368_Content_24 = {
    Text = "Mantienes tu identidad firmemente en mente."
  },
  AvgDialog_15368_Content_25 = {
    Text = "Esta vez, eres una criada que creció con Sanga y has sido enviada por el Maestro @1·Claudel para llevarla a casa."
  },
  AvgDialog_15368_Content_26 = {
    Text = "\"Debes rescatar su alma de las garras de ese demonio que Solo explota y plagia a sus subordinados.\""
  },
  AvgDialog_15368_Content_27 = {
    Text = "S–soy tu Sirvienta, Camille@1! ¿No te acuerdas? Jaja..."
  },
  AvgDialog_15368_Content_28 = {
    Text = "<Shake:Después de tantos años separadas, ambas hemos cambiado un poco, ¿no?>"
  },
  AvgDialog_15368_Content_29 = {Text = "..."},
  AvgDialog_15368_Content_3 = {
    Text = "Los rumores ya se han extendido.\nLa gente dice que la señorita Sanga pasa sus días y noches con un hombre más de 20 años mayor que ella, \"por el bien del arte\".\nEsto es completamente absurdo. Mañana visitaré el estudio para verlo con mis propios ojos.\n\nEsta vez, cumpliré con su petición—\n<Yellow:Traer a su hermana, nuestra querida señorita Sanga, de vuelta a Besançon.>\n\nCamille@1\nA.F.2@1 Agosto"
  },
  AvgDialog_15368_Content_30 = {
    Text = "Realmente eres bastante diferente. Eres mucho más vívida ahora que antes.\nEs como si... de repente hubieras cobrado vida."
  },
  AvgDialog_15368_Content_31 = {
    Text = "<Gray:Así que este es el Olfato de una artista... Tendré que ser más cuidadoso/a de ahora en adelante.>"
  },
  AvgDialog_15368_Content_32 = {
    Text = "<Shake:Si no te importa, ¿podrías ayudarme? Ahora mismo no puedo ponerme en pie...>"
  },
  AvgDialog_15368_Content_33 = {
    Text = "Sanga toma tu mano con delicadeza, un destello de preocupación atravesando sus ojos serenos e imperturbables."
  },
  AvgDialog_15368_Content_34 = {
    Text = "Lo siento, estaba demasiado absorta en mi trabajo. Debes de sentirte muy incómodo/a ahora mismo. Déjame echar un vistazo."
  },
  AvgDialog_15368_Content_35 = {
    Text = "¡¡Whoosh—!!"
  },
  AvgDialog_15368_Content_36 = {
    Text = "La puerta del estudio se abrió de golpe."
  },
  AvgDialog_15368_Content_37 = {
    Text = "Un hombre alto y sombrío entró, seguido de varios rostros desconocidos."
  },
  AvgDialog_15368_Content_38 = {
    Text = "Sin necesidad de acceder a los recuerdos del huésped original, lo reconociste por su característico bigote—"
  },
  AvgDialog_15368_Content_39 = {
    Text = "El renombrado escultor, <Blue:Agosto>."
  },
  AvgDialog_15368_Content_4 = {
    Text = "Señorita Sanga, vuelva conmigo. Aquí ni siquiera hay un lugar donde resguardarse del frío—"
  },
  AvgDialog_15368_Content_40 = {
    Text = "Incluso hoy en día, sus esculturas siguen siendo aclamadas como obras maestras, muy codiciadas en las subastas de Londinium."
  },
  AvgDialog_15368_Content_41 = {
    Text = "Al ver tus manos y las de Sanga entrelazadas, Agosto frunció el ceño. Pero pronto, su atención se vio atraída por la escultura que tenía delante."
  },
  AvgDialog_15368_Content_42 = {
    Text = "Esto es... <Big:¡Una obra maestra, una obra maestra indiscutible!>"
  },
  AvgDialog_15368_Content_43 = {
    Text = "Los demás se reunieron también alrededor, contemplando con curiosidad la escultura recién terminada, dejando escapar oleadas de admiración."
  },
  AvgDialog_15368_Content_44 = {
    Text = "Bien, muy bien... Contactad con la gente del Ministerio de Cultura. Decidles que tenemos una pieza prometedora para la exposición de Cité de este año."
  },
  AvgDialog_15368_Content_45 = {
    Text = "No puedo esperar a ver las caras de esos críticos cuando se les caiga la mandíbula... ¡Jajajaja!"
  },
  AvgDialog_15368_Content_46 = {
    Text = "La sonora carcajada de Agosto resonó por el espacioso estudio. Te apartó de un empujón y agarró con firmeza la mano de Sanga."
  },
  AvgDialog_15368_Content_47 = {
    Text = "Sabía que no me decepcionarías, Sanga."
  },
  AvgDialog_15368_Content_48 = {
    Text = "Sanga retiró lentamente su mano y se acercó a la escultura."
  },
  AvgDialog_15368_Content_49 = {
    Text = "¿Una... obra maestra indiscutible?"
  },
  AvgDialog_15368_Content_5 = {
    Text = "No te muevas, y no hables. Solo quédate así.\nSí, justo así..."
  },
  AvgDialog_15368_Content_50 = {
    Text = "¿Qué piensas, Camille?"
  },
  AvgDialog_15368_Content_51 = {
    Text = "¿Eh, yo...?"
  },
  AvgDialog_15368_Content_52 = {
    Text = "Contemplaste la escultura que se parecía casi exactamente a \"ti\" y te sumiste en profundos pensamientos..."
  },
  AvgDialog_15368_Content_53 = {Text = "Mediocre"},
  AvgDialog_15368_Content_54 = {
    Text = "Hmm, la expresión es rígida, la estructura es caótica y le falta tensión..."
  },
  AvgDialog_15368_Content_55 = {
    Text = "Comentaste con aire de autoridad. En realidad, siempre has estado completamente desvinculado del arte. La única razón por la que dijiste eso fue porque no soportabas la actitud prepotente de Agosto."
  },
  AvgDialog_15368_Content_56 = {
    Text = "No te gusta él."
  },
  AvgDialog_15368_Content_57 = {
    Text = "Sanga te observó con una sonrisa, como una madre cariñosa ante el balbuceo sin sentido de un niño."
  },
  AvgDialog_15368_Content_58 = {
    Text = "Hmm... Aunque nuestras razones difieren, hemos llegado a la misma conclusión."
  },
  AvgDialog_15368_Content_59 = {
    Text = "¡Una obra maestra!"
  },
  AvgDialog_15368_Content_6 = {
    Text = "Sé un buen modelo para mí, déjame terminar esta pieza... luego podemos hablar de volver a casa."
  },
  AvgDialog_15368_Content_60 = {
    Text = "Verdaderamente incomparable. No puedo encontrarle un solo defecto."
  },
  AvgDialog_15368_Content_61 = {
    Text = "Como todos los demás, tu mente quedó completamente cautivada por esta escultura — aparentemente libre, pero meticulosamente precisa."
  },
  AvgDialog_15368_Content_62 = {
    Text = "Por supuesto, esto también tenía que ver con la mala circulación de Sangre causada por mantener la misma pose durante tanto tiempo."
  },
  AvgDialog_15368_Content_63 = {
    Text = "Un cerebro privado de oxígeno no puede percibir las cosas con claridad, pero la adulación nunca está de más."
  },
  AvgDialog_15368_Content_64 = {
    Text = "Tienes razón. No tener defectos — ese es precisamente su mayor problema."
  },
  AvgDialog_15368_Content_65 = {
    Text = "Ahora... ¿qué debería hacer contigo?"
  },
  AvgDialog_15368_Content_66 = {
    Text = "Sanga apoyó la barbilla en su mano, contemplando la escultura frente a ella. Luego extendió el dedo índice y tocó despreocupadamente la escultura entre las cejas—"
  },
  AvgDialog_15368_Content_67 = {
    Text = "¡¡CRASH—!!"
  },
  AvgDialog_15368_Content_68 = {
    Text = "La escultura trazó un elegante arco en el aire y luego se estrelló contra el suelo."
  },
  AvgDialog_15368_Content_69 = {
    Text = "Camille — o más bien, ese rostro tuyo lleno de ansiedad — se hizo añicos en un instante."
  },
  AvgDialog_15368_Content_7 = {
    Text = "¿Qué es esto...?"
  },
  AvgDialog_15368_Content_70 = {Text = "..."},
  AvgDialog_15368_Content_71 = {
    Text = "Señorita Claudel, ¿¡ha perdido la cabeza?!"
  },
  AvgDialog_15368_Content_72 = {
    Text = "Agosto se abalanzó hacia ti con ira."
  },
  AvgDialog_15368_Content_73 = {
    Text = "<Big:Este era el más puro mármol pentélico, extraído de Paros—>"
  },
  AvgDialog_15368_Content_8 = {
    Text = "Una habitación desordenada."
  },
  AvgDialog_15368_Content_9 = {
    Text = "Esculturas de diversas arcillas Pegajosas, mármol y granito están colocadas al azar, convirtiendo este espacio en un improvisado estudio de escultura."
  },
  AvgDialog_15370_Content_1 = {
    Text = "Cabeza Dorada"
  },
  AvgDialog_15370_Content_10 = {
    Text = "La lluvia se hacía cada vez más intensa, tu garganta cada vez más seca.\nEn una tormenta como esta, tenías que gritar solo para escuchar tu propia voz."
  },
  AvgDialog_15370_Content_11 = {
    Text = "Aquí... estoy aquí..."
  },
  AvgDialog_15370_Content_12 = {
    Text = "A@1je je je aquí aquí aquí@2quí quí quí..."
  },
  AvgDialog_15370_Content_13 = {
    Text = "Innumerables voces te asaltaron desde todas las direcciones. Incapaz de resistir más, finalmente te desplomaste sobre la arena."
  },
  AvgDialog_15370_Content_14 = {
    Text = "Quizás todo era solo un Fantasma tuyo... quizás la Srta. Sanga ya se había ido para siempre."
  },
  AvgDialog_15370_Content_15 = {
    Text = "<Shake:Srta. Sanga, por favor sal... sé que estás aquí...>"
  },
  AvgDialog_15370_Content_16 = {
    Text = "En algún momento, la consciencia de la Doncella te había Devorado gradualmente. Sus esperanzas y su sufrimiento conmovieron profundamente tu corazón."
  },
  AvgDialog_15370_Content_17 = {
    Text = "Presionas la frente contra la arena húmeda, un extraño quejido escapa de tu garganta."
  },
  AvgDialog_15370_Content_18 = {
    Text = "<Shake:Señorita Sanga...>"
  },
  AvgDialog_15370_Content_19 = {
    Text = "<Red:Aquí... estoy aquí...>"
  },
  AvgDialog_15370_Content_2 = {
    Text = "Querido Sr. Claud:\n\n\"La Dama Coral Caída\" fue un tremendo éxito en Cité. Todos hablan de ella.\nAl contemplar esta escultura, no puedo evitar pensar en ti.\n\nEstá hecha de un material blanco y tenue, muy parecido a la Piedra que cubrió todo tu cuerpo y te dejó sin poder moverte.\nPero no me dejan tocar la escultura@1\nEncontraré la manera."
  },
  AvgDialog_15370_Content_20 = {
    Text = "...¿Qué es esto?"
  },
  AvgDialog_15370_Content_21 = {
    Text = "Un frío glacial alcanza las puntas de tus dedos."
  },
  AvgDialog_15370_Content_22 = {
    Text = "La bruma blanca se Propaga desde entre tus dedos una vez más, como enredaderas vivientes..."
  },
  AvgDialog_15370_Content_23 = {
    Text = "Lenta, metódicamente..."
  },
  AvgDialog_15370_Content_24 = {
    Text = "Al fin... este momento ha llegado por fin."
  },
  AvgDialog_15370_Content_25 = {
    Text = "Un par de delicados zapatos de cuero de mujer se detienen frente a ti.\nSanga sostiene un cuchillo de tallar, su expresión tan indiferente como siempre."
  },
  AvgDialog_15370_Content_26 = {
    Text = "Señorita Sanga... realmente sigue con vida..."
  },
  AvgDialog_15370_Content_27 = {
    Text = "Eso depende de cómo definas \"estar viva\"."
  },
  AvgDialog_15370_Content_28 = {
    Text = "La suave luz de las luces distantes envuelve suavemente el cuerpo de Sanga. Ella te sonríe en silencio."
  },
  AvgDialog_15370_Content_29 = {
    Text = "He vuelto, Camille. Debes haber estado esperándome mucho tiempo, ¿verdad?"
  },
  AvgDialog_15370_Content_3 = {
    Text = "La Srta. Sanga finalmente cumplió su deseo. Intercambió sus propios PV para alcanzar un arte inmortal.\nPero debido a eso, nos ha dejado para siempre.\nHa pasado casi un mes desde la exposición, y aún la extraño profundamente.\n\n<Yellow:La encontraré y la llevaré a casa.>\n\nCamille@1\nA.F.2@1 Agosto"
  },
  AvgDialog_15370_Content_30 = {
    Text = "Angustia, conmoción, éxtasis..."
  },
  AvgDialog_15370_Content_31 = {
    Text = "Incontables emociones surgen en tu pecho. Abres la boca, solo para Descubrir que ya no puedes formar una sílaba completa."
  },
  AvgDialog_15370_Content_32 = {
    Text = "Sanga@1... no@2..."
  },
  AvgDialog_15370_Content_33 = {Text = "¡Shh..."},
  AvgDialog_15370_Content_34 = {
    Text = "¿Sabías que? El cuerpo humano es como un mundo tembloroso y pulsante."
  },
  AvgDialog_15370_Content_35 = {
    Text = "Cuando la carne y el alma han sido templadas lo suficiente, en el pico más alto de la erupción emocional, sufren una Metamorfosis y se convierten en la escultura más perfecta..."
  },
  AvgDialog_15370_Content_36 = {
    Text = "Unos dedos gélidos acarician tu rostro que se endurece gradualmente."
  },
  AvgDialog_15370_Content_37 = {
    Text = "Sanga te contempló con amor, sus ojos ardientes Casi te reducían a cenizas."
  },
  AvgDialog_15370_Content_38 = {
    Text = "Solo como tú ahora..."
  },
  AvgDialog_15370_Content_39 = {
    Text = "¿Como yo ahora...? Sra. Sanga, ¿es el D-Slime..."
  },
  AvgDialog_15370_Content_4 = {
    Text = "Llegaste tambaleándote a la orilla. No había nadie aquí — solo el tenue Silencio del mar y el horizonte brumoso te hacían compañía."
  },
  AvgDialog_15370_Content_40 = {
    Text = "Shh... Silencio."
  },
  AvgDialog_15370_Content_41 = {
    Text = "Para mí, la muerte nunca ha sido algo aterrador. Lo verdaderamente aterrador es..."
  },
  AvgDialog_15370_Content_42 = {
    Text = "<Yellow:Perder belleza, o cerrar los ojos a ella.>"
  },
  AvgDialog_15370_Content_43 = {
    Text = "<Shake:Aléjate... Déjame...>"
  },
  AvgDialog_15370_Content_44 = {
    Text = "No seas tonta, Camille."
  },
  AvgDialog_15370_Content_45 = {
    Text = "<Red:Ya llevas muerta mucho tiempo. ¿No lo recuerdas?>"
  },
  AvgDialog_15370_Content_46 = {
    Text = "<Red:Muerta...>"
  },
  AvgDialog_15370_Content_47 = {Text = "..."},
  AvgDialog_15370_Content_48 = {
    Text = "Te sumergiste una vez más en las profundidades del interminable océano."
  },
  AvgDialog_15370_Content_49 = {
    Text = "Fragmentos sellados en la memoria emergieron como espuma blanca flotando por doquier, surgiendo sin cesar, encontrándose sin cesar con la Destrucción..."
  },
  AvgDialog_15370_Content_5 = {
    Text = "Todos ustedes son mi familia, para siempre."
  },
  AvgDialog_15370_Content_50 = {
    Text = "En el último instante antes de la muerte, no tuviste más remedio que enfrentar esas crueles verdades real—"
  },
  AvgDialog_15370_Content_51 = {
    Text = "Es todo culpa mía, Camille. Es todo culpa mía... Déjame abrazarte, y la Herida dejará de doler."
  },
  AvgDialog_15370_Content_52 = {
    Text = "Mi hermana es una verdadera genio. ¡Seguro que se convertirá en una gran artista inmortalizada en los libros!"
  },
  AvgDialog_15370_Content_53 = {
    Text = "*cof, cof*... Deja de engañarte a ti misma, Camille..."
  },
  AvgDialog_15370_Content_54 = {
    Text = "Tráela de vuelta para que me vea@2Hay algo que quiero preguntarle cara a cara..."
  },
  AvgDialog_15370_Content_55 = {
    Text = "¡¡Última hora!!"
  },
  AvgDialog_15370_Content_56 = {
    Text = "¡El impactante <Yellow:caso del asesinato de la escultura> se cobra otra víctima más!"
  },
  AvgDialog_15370_Content_57 = {
    Text = "Hasta el momento, los casos de <Yellow:Aturdir e Histeria> provocados por contemplar \"La Dama Coral Caída\" han ascendido a 54..."
  },
  AvgDialog_15370_Content_58 = {
    Text = "<Red:De ellos, 23 ya se han suicidado...>"
  },
  AvgDialog_15370_Content_59 = {Text = "..."},
  AvgDialog_15370_Content_6 = {
    Text = "No te preocupes. Ya que te prometí que volveríamos a casa juntos, no faltaré a mi palabra."
  },
  AvgDialog_15370_Content_60 = {
    Text = "Así que yo... lo supe todo desde el principio..."
  },
  AvgDialog_15370_Content_61 = {
    Text = "Ves ese palacio oceánico blanco una vez más. El plancton se agrupa sobre el carbonato de calcio blanco, estirando perezosamente sus extremidades."
  },
  AvgDialog_15370_Content_62 = {
    Text = "También ves aquellas esculturas blancas flotando sin rumbo por el agua marina."
  },
  AvgDialog_15370_Content_63 = {
    Text = "Entre ellos hay algunos rostros familiares — el Señor Agosto, por ejemplo, aún congelado en la ira y la desesperación del momento en que se abalanzó sobre la escultura."
  },
  AvgDialog_15370_Content_64 = {
    Text = "El Señor Paulo, por otro lado, sus cuencas Enredadas rebosantes de melancolía, como si hubiera previsto desde hacía mucho su propio Destino."
  },
  AvgDialog_15370_Content_65 = {
    Text = "El agua de mar cálida envuelve tu cuerpo, su ritmo incesante como una nana fluida."
  },
  AvgDialog_15370_Content_66 = {
    Text = "Antes de Abrir los ojos el infante agita sus pequeñas manos\nAferrando figuras de arcilla sintiendo una alegría semejante al amor de una madre\nEl arte de moldear y controlar desde entonces se Propaga entre los dedos\n\n<Red:Abre los ojos y todo lo que se ve nace de la belleza belleza belleza belleza belleza belleza belleza...>"
  },
  AvgDialog_15370_Content_67 = {
    Text = "Unas manos frías te abrazan con suavidad. Sanga hunde su mejilla suave contra tu hombro rígido."
  },
  AvgDialog_15370_Content_68 = {
    Text = "¿Puedes oírlos? Esos cantos — resuenan sin cesar en mi mente."
  },
  AvgDialog_15370_Content_69 = {
    Text = "Son <Yellow:Ellos> quienes Convocan, el Destino ineludible que me Convoca..."
  },
  AvgDialog_15370_Content_7 = {
    Text = "Ella no rompería su promesa... no lo haría."
  },
  AvgDialog_15370_Content_70 = {
    Text = "Seguí esos cantos y finalmente encontré este lugar."
  },
  AvgDialog_15370_Content_71 = {
    Text = "El Milagro y la belleza de las profundidades del océano... No tengo nada que ofrecerles salvo a ti."
  },
  AvgDialog_15370_Content_72 = {Text = "¿Yo...?"},
  AvgDialog_15370_Content_73 = {
    Text = "Sí, Solo tú — %player%."
  },
  AvgDialog_15370_Content_74 = {
    Text = "Ella pronunció tu nombre original con claridad, sin lugar a dudas."
  },
  AvgDialog_15370_Content_75 = {
    Text = "Desde el mismo momento en que abriste los ojos, lo supe."
  },
  AvgDialog_15370_Content_76 = {
    Text = "<Yellow:Tú eres la verdadera \"La Dama Coral Caída\".>"
  },
  AvgDialog_15370_Content_77 = {
    Text = "La consciencia se desvanece. El coral White se ha Propagado desde hace mucho por todo tu cuerpo."
  },
  AvgDialog_15370_Content_78 = {
    Text = "Sientes tu Sangre y tu carne volverse pesadas, y sin embargo, extrañamente, sus cuerpos siguen ascendiendo entre la espuma y el coral."
  },
  AvgDialog_15370_Content_79 = {
    Text = "<Shake:No... casa... ir a casa...>"
  },
  AvgDialog_15370_Content_8 = {
    Text = "Te levantaste el dobladillo de la falda y seguiste Corriendo a lo largo de la extensa costa."
  },
  AvgDialog_15370_Content_80 = {
    Text = "Este es tu hogar, %player%."
  },
  AvgDialog_15370_Content_81 = {Text = "No..."},
  AvgDialog_15370_Content_82 = {
    Text = "Miras fijamente con los ojos bien abiertos el rostro de Sanga, hasta que tus pupilas también son cubiertas por el coral gris pálido."
  },
  AvgDialog_15370_Content_83 = {
    Text = "Te hundes en un vacío sin límites."
  },
  AvgDialog_15370_Content_84 = {
    Text = "Todo el océano, el coral, las esculturas se alejan de ti, pero su voz permanece."
  },
  AvgDialog_15370_Content_85 = {
    Text = "Amable como siempre, esa voz fría y distante."
  },
  AvgDialog_15370_Content_86 = {
    Text = "Te prometí que te llevaría a casa conmigo..."
  },
  AvgDialog_15370_Content_87 = {
    Text = "Te lo prometo."
  },
  AvgDialog_15370_Content_9 = {
    Text = "Srta. Sanga— Srta. Sanga—"
  },
  AvgDialog_15605_Content_1 = {
    Text = "Iniciar Prueba"
  },
  AvgDialog_15605_Content_10 = {
    Text = "¿Podrías haber entrado en el pasado del Cuerpo Despertado otra vez? Recuerdas que estabas leyendo unos documentos..."
  },
  AvgDialog_15605_Content_11 = {
    Text = "¿Por qué no hay respuesta? ¿Está fallando el módulo auditivo?"
  },
  AvgDialog_15605_Content_12 = {
    Text = "Eso depende— ¿te colaste a toquetear los módulos otra vez después de que me fui ayer?"
  },
  AvgDialog_15605_Content_13 = {
    Text = "No no, esta vez de verdad que no, ¡lo juro!\nDéjame intentarlo otra vez— Tic-Tac, ¿puedes oírme?"
  },
  AvgDialog_15605_Content_14 = {Text = "Sí."},
  AvgDialog_15605_Content_15 = {
    Text = "¡Mira, mira! ¡Su boca se movió! ¡Te dije que funcionaría!"
  },
  AvgDialog_15605_Content_16 = {
    Text = "¡La primera marioneta mecánica totalmente automática del mundo que puede seguir comandos de voz! ¡La primera! ¡Totalmente automática!\nQuerido Padre Dios, llévame ahora, no me quedan arrepentimientos en la vida."
  },
  AvgDialog_15605_Content_17 = {
    Text = "Hay muchos arrepentimientos, sin embargo—como no haber completado la prueba de respuesta a comandos, la prueba de flexibilidad de extremidades, la prueba de duración operativa..."
  },
  AvgDialog_15605_Content_18 = {
    Text = "Yo—e—tú de verdad que no tienes nada de gracia."
  },
  AvgDialog_15605_Content_19 = {
    Text = "...prueba de coordinación general, prueba de equilibrio, prueba de carga..."
  },
  AvgDialog_15605_Content_2 = {
    Text = "Engranajes, normal; sistema hidráulico, sin fugas de presión detectadas; motor MF311000 funcionando con normalidad, temperatura ligeramente elevada pero dentro del rango aceptable."
  },
  AvgDialog_15605_Content_20 = {
    Text = "¡Vale, vale, lo pillo! <Small:Eres incluso más mecánica que el Tic-Tac.>"
  },
  AvgDialog_15605_Content_21 = {
    Text = "¿Qué dijiste?"
  },
  AvgDialog_15605_Content_22 = {
    Text = "Ah... ¡ahora comienza la prueba básica de recepción y comprensión de comandos!\nTic-Tac, parpadea."
  },
  AvgDialog_15605_Content_23 = {Text = "Parpadeo"},
  AvgDialog_15605_Content_24 = {
    Text = "Sigue mi dedo, bien.\n¿Abre la boca? Muy bien, qué niño tan bueno."
  },
  AvgDialog_15605_Content_25 = {Text = "...Ugh."},
  AvgDialog_15605_Content_26 = {
    Text = "¡Pero bueno! Lo construí pieza a pieza con mis propias manos... es perfectamente razonable que me llame mamá."
  },
  AvgDialog_15605_Content_27 = {
    Text = "Sí, sí, Mamá Maníaca de los Engranajes. Trae el brazo izquierdo de tu querido bebé de acero... es hora de empezar la prueba de extremidades."
  },
  AvgDialog_15605_Content_28 = {
    Text = "Un brazo compuesto de intrincados engranajes y estructuras mecánicas que no podrías ni empezar a comprender apareció brevemente en tu Campo de visión, luego desapareció hacia tu lado izquierdo, seguido del derecho."
  },
  AvgDialog_15605_Content_29 = {
    Text = "La instalación de las cuatro extremidades fue sin problemas. Levantaste los brazos y extendiste las piernas siguiendo los comandos, y la sonrisa en el rostro de Erica se hacía cada vez más radiante."
  },
  AvgDialog_15605_Content_3 = {
    Text = "Fuente de energía especial S, estado estable."
  },
  AvgDialog_15605_Content_30 = {
    Text = "Bien, lo siguiente... ¡Ah!"
  },
  AvgDialog_15605_Content_31 = {
    Text = "Un espeso humo negro se elevó desde debajo de tu línea de visión: algo estaba ardiendo.\nMiraste hacia abajo y viste chispas eléctricas y destellos de luz parpadeando en tu cavidad abdominal."
  },
  AvgDialog_15605_Content_32 = {
    Text = "Extintor, Mei, ¡Mei!"
  },
  AvgDialog_15605_Content_33 = {
    Text = "¡Fuera del camino!"
  },
  AvgDialog_15605_Content_34 = {
    Text = "La espuma blanca salió disparada del extintor, y el olor a quemado se difundió por el aire.\nErica se abalanzó hacia delante y, sin importarle el calor abrasador, desconectó el motor."
  },
  AvgDialog_15605_Content_35 = {Text = "¡Erica!"},
  AvgDialog_15605_Content_36 = {
    Text = "El motor ennegrecido quedó sobre la mesa de trabajo. Erica recuperó el aliento y, tardíamente, sopló sobre sus manos cubiertas de espuma blanca."
  },
  AvgDialog_15605_Content_37 = {
    Text = "¡Ay, ay, ay, está ardiendo!"
  },
  AvgDialog_15605_Content_38 = {
    Text = "¡Primordial S, rápido, comprueba el Primordial S!"
  },
  AvgDialog_15605_Content_39 = {
    Text = "Erica se acercó al motor, sus dedos ligeramente enrojecidos por el calor acariciaron con suavidad la carcasa metálica."
  },
  AvgDialog_15605_Content_4 = {
    Text = "Uf— ¿estás lista?\nAutómata Tic-Tac, decimotercera prueba de activación, Comenzar."
  },
  AvgDialog_15605_Content_40 = {
    Text = "Parece que el cableado externo hizo cortocircuito y se incendió. El interior debería estar intacto."
  },
  AvgDialog_15605_Content_41 = {
    Text = "No te preocupes, haré una revisión completa en un momento."
  },
  AvgDialog_15605_Content_42 = {
    Text = "...¿Vas a echarme otra vez?"
  },
  AvgDialog_15605_Content_43 = {Text = "Mei..."},
  AvgDialog_15605_Content_44 = {
    Text = "Sé que estuvo mal experimentar con la Fuente S sin permiso, pero conoces nuestra situación de financiamiento. Usar S como avance podría darnos más tiempo y materiales."
  },
  AvgDialog_15605_Content_45 = {
    Text = "Solo déjame echar un vistazo, por favor. Solo una vez. Te juro que no revelaré ninguna información sobre eso a nadie.\nPor favor."
  },
  AvgDialog_15605_Content_46 = {
    Text = "Ya te lo he dicho, no hay nada Dentro."
  },
  AvgDialog_15605_Content_47 = {
    Text = "...Ya ni te molestas en inventar una excusa. ¿De verdad es necesario ser tan reservada conmigo?\n¿Acaso no he estado siempre pensando en nuestro futuro?"
  },
  AvgDialog_15605_Content_48 = {Text = "..."},
  AvgDialog_15605_Content_49 = {
    Text = "Olvídalo.\nVoy a sentarme un rato en el Restaurante de Joey. Haz lo que quieras."
  },
  AvgDialog_15605_Content_5 = {
    Text = "Abre los ojos"
  },
  AvgDialog_15605_Content_50 = {
    Text = "La Puerta se cerró, los pasos se desvanecieron en la distancia, y Erica dejó escapar un suspiro."
  },
  AvgDialog_15605_Content_51 = {
    Text = "Ella todavía... pero esa persona me advirtió sobre la Fuente S...\nNo puedo dejar que Mei comparta este riesgo conmigo."
  },
  AvgDialog_15605_Content_52 = {
    Text = "Ella se volvió hacia el motor, como si reuniera su determinación."
  },
  AvgDialog_15605_Content_53 = {
    Text = "Lo resolveré. Espérame, Mei."
  },
  AvgDialog_15605_Content_54 = {
    Text = "Desenroscó la tapa y extrajo un cilindro negro de su Dentro."
  },
  AvgDialog_15605_Content_55 = {
    Text = "En ese instante, tu mundo se sumió en la oscuridad."
  },
  AvgDialog_15605_Content_6 = {
    Text = "Tic-Tac, ¿puedes oírme?"
  },
  AvgDialog_15605_Content_7 = {
    Text = "...¿Erica?"
  },
  AvgDialog_15605_Content_8 = {
    Text = "Ese rostro familiar lleva una expresión natural completamente diferente a la que hay en tu memoria. Más que un autómata, parece una persona viva."
  },
  AvgDialog_15605_Content_9 = {
    Text = "...¿Qué está pasando?"
  },
  AvgDialog_15606_Content_1 = {
    Text = "La voz dijo así"
  },
  AvgDialog_15606_Content_10 = {
    Text = "Ella murmuró mientras se marchaba, dejándote a solas con los motores y las piezas sobre el banco de trabajo."
  },
  AvgDialog_15606_Content_11 = {
    Text = "Miras tus propias manos."
  },
  AvgDialog_15606_Content_12 = {
    Text = "Esbeltas, fuertes, con la delicada carcasa de porcelana cuidadosamente limpiada y mantenida. Aunque frías al tacto, bajo la tenue luz no se distinguían de las de una persona viva."
  },
  AvgDialog_15606_Content_13 = {
    Text = "Estas son las manos de Erica—las manos del <Blue:autómata Erica> que una vez conociste.\nParece que has tomado el cuerpo Después de Ella, convirtiéndote en el autómata que Ella Fabricó."
  },
  AvgDialog_15606_Content_14 = {
    Text = "La Ella que acabas de ver era claramente una humana.\n¿Qué clase de Experiencia podría haberla convertido en lo que Ella Después llegó a ser?"
  },
  AvgDialog_15606_Content_15 = {Text = "¿Erica?"},
  AvgDialog_15606_Content_16 = {
    Text = "Parpadeas, y Mei ha entrado en la habitación en algún momento sin que te dieras cuenta.\nSu mirada recorre la habitación antes de posarse finalmente en el motor junto a ti."
  },
  AvgDialog_15606_Content_17 = {Text = "..."},
  AvgDialog_15606_Content_18 = {
    Text = "Tras examinar la habitación una segunda vez, Ella cierra la Puerta y avanza rápidamente hacia el motor."
  },
  AvgDialog_15606_Content_19 = {
    Text = "Lo siento, Erica."
  },
  AvgDialog_15606_Content_2 = {
    Text = "Tic-Tac, cariño, ¿puedes oírme?"
  },
  AvgDialog_15606_Content_20 = {
    Text = "La tapa se desenrosca, y Mei pellizca el objeto de Dentro. Esta vez lo ves claramente—un cilindro metálico de no más de 5 centímetros de diámetro, con la letra \"S\" grabada en su costado."
  },
  AvgDialog_15606_Content_21 = {
    Text = "Una vez que Ella extraiga completamente el cilindro, perderás la consciencia de nuevo.\nAsí que antes de que eso ocurra, debes—"
  },
  AvgDialog_15606_Content_22 = {
    Text = "Agarrar su mano"
  },
  AvgDialog_15606_Content_23 = {Text = "¡¡Auch!!"},
  AvgDialog_15606_Content_24 = {
    Text = "Qué pasa, qué pasa—"
  },
  AvgDialog_15606_Content_25 = {
    Text = "Erica irrumpe en la habitación, la preocupación en su rostro se congela en el instante en que Ella ve el cilindro en la mano de Mei."
  },
  AvgDialog_15606_Content_26 = {
    Text = "¿Mei, qué estás haciendo?"
  },
  AvgDialog_15606_Content_27 = {
    Text = "¿Qué estás haciendo!"
  },
  AvgDialog_15606_Content_28 = {
    Text = "Solo estaba intentando... Esta fuente de energía... Realmente funciona..."
  },
  AvgDialog_15606_Content_29 = {
    Text = "Mirando fijamente el pequeño cilindro que había alimentado todo el motor y toda la maquinaria conectada, los ojos de Mei se abrieron de par en par."
  },
  AvgDialog_15606_Content_3 = {
    Text = "Despertando de la oscuridad eterna, descubres que sigues en el taller. El motor carbonizado permanece sobre el banco de trabajo, conectado a tu cuerpo por cables de distintos grosores."
  },
  AvgDialog_15606_Content_30 = {
    Text = "¿Sabes lo que esto significa, Erica?"
  },
  AvgDialog_15606_Content_31 = {
    Text = "Significa que es peligroso. Te lo dije, Mei, no puedes simplemente jugar con eso..."
  },
  AvgDialog_15606_Content_32 = {
    Text = "No, no, escucha, Erica... Esta cosa, esta cosita diminuta, puede proporcionar un suministro de energía a largo plazo sin pérdidas y sin emisiones. ¿No lo entiendes?"
  },
  AvgDialog_15606_Content_33 = {
    Text = "El carbón, el petróleo... no son nada comparados con esto. Si podemos producirlo en masa, reescribiremos toda la infraestructura energética de la humanidad. ¡Pasaremos a la historia!"
  },
  AvgDialog_15606_Content_34 = {
    Text = "Tienes que decirme cómo lo hiciste. ¡Tienes que hacerlo!"
  },
  AvgDialog_15606_Content_35 = {
    Text = "Erica, ¿adónde vas? ¿Cómo que no sabes cómo está hecho? ¡Erica!"
  },
  AvgDialog_15606_Content_36 = {
    Text = "El inversor dijo que, mientras vea un prototipo, está dispuesto a proporcionarnos una financiación enorme, incluso un taller dedicado."
  },
  AvgDialog_15606_Content_37 = {
    Text = "¿Por qué no escuchas? No sé cómo está hecha esta cosa. ¡No puedo fabricarla!"
  },
  AvgDialog_15606_Content_38 = {
    Text = "Ya pasé la edad de creer en cuentos de hadas, Erica. ¿Un <Blue:Vendedor Misterioso>? Si vas a quitarme de encima, al menos invéntate una excusa mejor."
  },
  AvgDialog_15606_Content_39 = {
    Text = "Claramente puedes crear algo tan increíble. ¿Por qué no puedes ver el panorama general?"
  },
  AvgDialog_15606_Content_4 = {
    Text = "Puedo oírte."
  },
  AvgDialog_15606_Content_40 = {
    Text = "¿Por qué insistes en encerrarte en un lugar como este, trasteando con chatarra?"
  },
  AvgDialog_15606_Content_41 = {
    Text = "Las palabras de Mei golpearon a Erica como una bofetada en la cara. Se quedó mirando a su socia, su compañera, incapaz de creer lo que estaba oyendo."
  },
  AvgDialog_15606_Content_42 = {
    Text = "...Chatarra. ¿Eso es lo que realmente piensas?"
  },
  AvgDialog_15606_Content_43 = {
    Text = "Pensé que compartíamos el mismo sueño."
  },
  AvgDialog_15606_Content_44 = {
    Text = "Mei apretó los dientes y aferró con más fuerza el cilindro."
  },
  AvgDialog_15606_Content_45 = {
    Text = "Afronta los hechos, Erica. Nadie está dispuesto a gastar dinero en autómatas. La nueva energía... esa es la Salida para nosotras."
  },
  AvgDialog_15606_Content_46 = {
    Text = "...Deja la fuente de energía especial."
  },
  AvgDialog_15606_Content_47 = {
    Text = "Piensa en todo lo que podríamos tener... más financiación, más recursos.\nCon eso, puedes continuar tu sueño. Con eso, puedes..."
  },
  AvgDialog_15606_Content_48 = {
    Text = "¡He dicho que lo sueltes!"
  },
  AvgDialog_15606_Content_49 = {
    Text = "Erica se abalanzó para arrebatárselo. Mei no pudo esquivarla a tiempo y chocó contra un armario cercano."
  },
  AvgDialog_15606_Content_5 = {
    Text = "Perdona por eso. ¡Te prometo que me centraré en el módulo de voz a continuación! Solo aguanta un poco, ¿vale?"
  },
  AvgDialog_15606_Content_50 = {Text = "¡¡!!"},
  AvgDialog_15606_Content_51 = {
    Text = "Botellas y frascos llenos de diversos reactivos y combustibles empezaron a caer. Te lanzaste hacia delante para protegerlas a las dos, y al segundo siguiente—"
  },
  AvgDialog_15606_Content_6 = {Text = "Asentir."},
  AvgDialog_15606_Content_7 = {
    Text = "Bendito sea el Padre Dios, qué bien. Tenía mucho miedo de que algún cable se hubiera quemado."
  },
  AvgDialog_15606_Content_8 = {
    Text = "Ella dejó escapar un suspiro de alivio y luego soltó un gran bostezo, como si la fatiga acabara de alcanzarla."
  },
  AvgDialog_15606_Content_9 = {
    Text = "Necesito ir a buscar una taza de café, y cenar..."
  },
  AvgDialog_15607_Content_1 = {
    Text = "El cañón de plasma disparó contra la mano gigante. La Plata se liberó de la palma por el Impacto y cayó silenciosamente al suelo."
  },
  AvgDialog_15607_Content_10 = {
    Text = "¿Qué... he... hecho..."
  },
  AvgDialog_15607_Content_11 = {
    Text = "Aún no lo entiendes. Pero no importa—ya has encendido esta revolución de vida y alma—esta <Red:\"Trascendencia\">.\nMuere en paz. Me aseguraré de que el mundo entero recuerde tu contribución."
  },
  AvgDialog_15607_Content_12 = {
    Text = "Erica cerró los ojos."
  },
  AvgDialog_15607_Content_13 = {
    Text = "Tienes... razón, siempre has tenido..."
  },
  AvgDialog_15607_Content_14 = {
    Text = "Lágrimas negras se deslizaron por las comisuras de sus ojos. Arrugó la nariz y, de repente, se giró para mirarte."
  },
  AvgDialog_15607_Content_15 = {
    Text = "Debería haber... escuchado... lo que decías... desde el principio... No... debería haber tomado esta cosa..."
  },
  AvgDialog_15607_Content_16 = {
    Text = "Mi cordura... mi... ayúdame... esta última vez..."
  },
  AvgDialog_15607_Content_17 = {
    Text = "¿Existe realmente una tercera consciencia dentro de este cuerpo, o eres simplemente la manifestación de su culpa bajo la influencia de la Fusión? No tienes forma de saberlo."
  },
  AvgDialog_15607_Content_18 = {
    Text = "Ella extiende su mano hacia ti."
  },
  AvgDialog_15607_Content_19 = {
    Text = "Ayúdame... a salvar..."
  },
  AvgDialog_15607_Content_2 = {
    Text = "Tras un momento de quietud, la mano gigante se desplomó y se desintegró. Limo negro cayó como una lluvia torrencial — te atravesó, pero tiñó de negro el fantasma de Erica."
  },
  AvgDialog_15607_Content_20 = {
    Text = "Todo lo que sabes es que la ayudarás, y serás quien pueda testificar de su final como \"humana\"."
  },
  AvgDialog_15607_Content_21 = {
    Text = "Tomar su mano"
  },
  AvgDialog_15607_Content_22 = {
    Text = "Ella te mira con sorpresa, como si nunca hubiera imaginado que pudiera tocar realmente su propia \"cordura\"."
  },
  AvgDialog_15607_Content_23 = {Text = "Asiente"},
  AvgDialog_15607_Content_24 = {
    Text = "Ella te mira con sorpresa, como si nunca hubiera esperado que su propia \"consciencia\" pudiera darle una respuesta."
  },
  AvgDialog_15607_Content_25 = {Text = "Gracias..."},
  AvgDialog_15607_Content_26 = {
    Text = "El fantasma estalla y se disipa como una burbuja, dejando Solo el orbe de luz Parpadeante, aún emitiendo su último resplandor."
  },
  AvgDialog_15607_Content_27 = {
    Text = "Acunas en tus brazos el ahora reducido orbe de luz y diriges la mirada hacia la Plata fragmentada cercana."
  },
  AvgDialog_15607_Content_28 = {
    Text = "Tendrás éxito."
  },
  AvgDialog_15607_Content_3 = {
    Text = "Está... terminado..."
  },
  AvgDialog_15607_Content_4 = {
    Text = "¿Realmente piensas eso?"
  },
  AvgDialog_15607_Content_5 = {Text = "¡Ah!"},
  AvgDialog_15607_Content_6 = {
    Text = "Te lo dije, solo entre en este corazón de Plata, la verdadera inmortalidad me espera."
  },
  AvgDialog_15607_Content_7 = {
    Text = "Lucha todo lo que quieras. La sustancia negra acabará borrándote, y entonces podré traer la verdadera <Red:\"Metamorfosis\"> al mundo — a todos se les concederá la inmortalidad, a todos se les concederá la vida eterna."
  },
  AvgDialog_15607_Content_8 = {
    Text = "Eso es... muerte... no..."
  },
  AvgDialog_15607_Content_9 = {
    Text = "Cada vez más negro consumía su cuerpo. Erica se dobló de agonía, su espíritu al borde del colapso."
  },
  AvgDialog_15608_Content_1 = {
    Text = "Esto es... ¿el Mundo espiritual?"
  },
  AvgDialog_15608_Content_2 = {
    Text = "Dios mío, pero qué demonios, qué demonios es..."
  },
  AvgDialog_15608_Content_3 = {
    Text = "Una voz... ¡Erica!"
  },
  AvgDialog_15609_Content_1 = {
    Text = "No, Erica, ¡no lo creas!"
  },
  AvgDialog_15609_Content_10 = {
    Text = "Un cuerpo de Carne y sangre no es más que Esclavitud para el alma. Solo liberando el alma podrá unirse a nosotros.\nSolo un cuerpo y una mente de metal pueden concedernos la eternidad."
  },
  AvgDialog_15609_Content_11 = {
    Text = "Los dedos se apretaron, y una expresión de agonía apareció en el rostro de Mei."
  },
  AvgDialog_15609_Content_12 = {
    Text = "<Shake:Tú... demente...>"
  },
  AvgDialog_15609_Content_13 = {
    Text = "Otra mano temblorosa apareció en el encuadre. Erica se agarró su propia muñeca y la retorció, desprendiendo la mano incontrolable y arrojándola a un lado."
  },
  AvgDialog_15609_Content_14 = {
    Text = "La mano gigante se detuvo por un momento, como si estuviera algo confundida."
  },
  AvgDialog_15609_Content_15 = {
    Text = "¿Por qué te resistes a mí? Le estoy dando un nuevo nacido sanado."
  },
  AvgDialog_15609_Content_16 = {
    Text = "Fantasma, es todo, un Fantasma."
  },
  AvgDialog_15609_Content_17 = {
    Text = "Erica sostuvo a Mei, inconsciente, y se puso lentamente de pie."
  },
  AvgDialog_15609_Content_18 = {
    Text = "Necesito llevarla a un hospital. Necesito... mantenerla con vida."
  },
  AvgDialog_15609_Content_19 = {
    Text = "Apoyó a Mei sobre su hombro, cruzó el estudio destrozado por la explosión y se dirigió hacia la Puerta que no estaba lejos."
  },
  AvgDialog_15609_Content_2 = {
    Text = "¡Erica, Erica!"
  },
  AvgDialog_15609_Content_3 = {
    Text = "Mientras luchabas contra el enemigo frente a ti, un monstruo hecho de baba rodeó por detrás y se abalanzó sobre el orbe de luz que representaba el espíritu de Erica."
  },
  AvgDialog_15609_Content_4 = {
    Text = "Como tinta vertida en agua, la oscuridad se extendió dentro del orbe de luz, cubriendo todo lo de Dentro.\nEl orbe de luz comenzó a parpadear."
  },
  AvgDialog_15609_Content_5 = {
    Text = "Qué está pasando, mis manos... por su cuenta..."
  },
  AvgDialog_15609_Content_6 = {
    Text = "¿Eres tú quien hace esto? Para, <Big:¡para ya!>"
  },
  AvgDialog_15609_Content_7 = {
    Text = "¿Por qué, ya no quieres salvarla a Ella?"
  },
  AvgDialog_15609_Content_8 = {
    Text = "¡Estás intentando estrangularla! ¡Suelta!"
  },
  AvgDialog_15609_Content_9 = {
    Text = "Entre destellos de oscuridad y luz, viste la mano mecánica acercarse cada vez más al cuello de Mei."
  },
  AvgDialog_15610_Content_1 = {
    Text = "La línea de defensa de una sola persona era prácticamente Ninguno. Sin importar cuántos Monstruos destrozaras, sus cuerpos hechos de limo podían reagruparse rápidamente, escabullirse y saltar directamente hacia el orbe de luz."
  },
  AvgDialog_15610_Content_10 = {
    Text = "Plasma dorado crepitaba a través de la sombra, y la forma de Erica se volvía cada vez más sólida."
  },
  AvgDialog_15610_Content_11 = {
    Text = "Levantó la mano y dispersó a los Monstruos frente a ti con plasma. La mano gigante se agitó levemente y dejó escapar un suspiro."
  },
  AvgDialog_15610_Content_12 = {
    Text = "Solo quería devolverte el favor por traerme de vuelta y darme un cuerpo nuevo. ¿Por qué tienes que hacerme Daño?"
  },
  AvgDialog_15610_Content_13 = {
    Text = "¿Traer de vuelta? ¿Qué quieres decir con traer de vuelta? Yo nunca..."
  },
  AvgDialog_15610_Content_14 = {
    Text = "¿Esta cosa puede alimentar a mi marioneta?"
  },
  AvgDialog_15610_Content_15 = {
    Text = "Erica sostuvo el tubo de metal negro con suspicacia, examinándolo desde todos los ángulos."
  },
  AvgDialog_15610_Content_16 = {
    Text = "Si te preocupa que no pueda mantener el funcionamiento prolongado de la marioneta, no es necesario.\nAlgo como esto es más que suficiente para alimentar algo mucho más intrincado y masivo."
  },
  AvgDialog_15610_Content_17 = {
    Text = "¿Estás diciendo que alguien más está usando este tipo de fuente de energía?"
  },
  AvgDialog_15610_Content_18 = {
    Text = "¿Algo similar? Sí. ¿Pero una copia exacta? Absolutamente imposible."
  },
  AvgDialog_15610_Content_19 = {
    Text = "Lo que querías era una \"fuente de energía única en su clase\", y la pequeña tienda de Daffodil nunca decepciona a sus clientes."
  },
  AvgDialog_15610_Content_2 = {
    Text = "Maldita... sea..."
  },
  AvgDialog_15610_Content_20 = {
    Text = "Ah, y un recordatorio amistoso — no sientas curiosidad por su construcción o su funcionamiento.\nUna vez que se abre la caja de Pandora, tendrás que cargar con las consecuencias tú misma."
  },
  AvgDialog_15610_Content_21 = {
    Text = "Odiaría ver a una genio como tú morir joven. Además del proyector, tengo tantas ideas más que quiero hacer realidad."
  },
  AvgDialog_15610_Content_22 = {
    Text = "Esperando tu próxima visita, Erica."
  },
  AvgDialog_15610_Content_23 = {
    Text = "No, eso es imposible. Dentro de la Fuente de Energía S, claramente solo había—"
  },
  AvgDialog_15610_Content_24 = {
    Text = "Un diminuto <Yellow:fragmento de Plata>, ¿verdad?\nUna pequeña maravilla — no solo puede alimentar maquinaria, también puede preservar las almas de los seres vivos."
  },
  AvgDialog_15610_Content_25 = {
    Text = "Tu espíritu ya se ha fusionado con este cuerpo con la ayuda de la sustancia negra. Solo entres en el <Yellow:corazón de Plata> antes de ser corroída por ella, podrás alcanzar la verdadera inmortalidad. Tú y yo.\n\nComo mi \"madre\" en esta vida, tienes derecho a compartirlo conmigo.\nUna lástima que tuvieras que ser tan obstinada."
  },
  AvgDialog_15610_Content_26 = {
    Text = "No tengo más opción que dejar que la <Yellow:sustancia negra> te devore."
  },
  AvgDialog_15610_Content_27 = {
    Text = "La mano gigante se puso en movimiento de repente, extendiendo sus cinco dedos para revelar la palma. La Plata en su interior estaba cubierta de grietas, pero aún brillaba con intensidad."
  },
  AvgDialog_15610_Content_28 = {
    Text = "Adiós, mi breve creadora."
  },
  AvgDialog_15610_Content_3 = {
    Text = "El orbe de luz parpadeó de nuevo, y viste las piernas de Erica temblando incontrolablemente."
  },
  AvgDialog_15610_Content_4 = {
    Text = "Los engranajes se entrelazaron y apretaron entre sí, y brillantes arcos de electricidad amarilla destellaron entre las tuberías y los soportes."
  },
  AvgDialog_15610_Content_5 = {
    Text = "Deja de resistirte. Entrégame el control de tu cuerpo."
  },
  AvgDialog_15610_Content_6 = {
    Text = "¿Ya no quieres salvarla? ¿No quieres que obtenga la eternidad junto contigo?"
  },
  AvgDialog_15610_Content_7 = {
    Text = "Más arcos de electricidad aparecieron en la escena."
  },
  AvgDialog_15610_Content_8 = {
    Text = "Partículas centelleantes se disiparon del orbe de luz, reuniéndose para formar un fantasma humanoide."
  },
  AvgDialog_15610_Content_9 = {
    Text = "¿E-Erica?!"
  },
  AvgDialog_15611_Content_1 = {
    Text = "¿Por qué salvarla?\nElla cambió tu Sueño por su propia carrera. ¿De verdad no sientes ningún Rancor en absoluto?"
  },
  AvgDialog_15611_Content_10 = {
    Text = "Pero pronto comprendí: esto no es un desastre, no es un Fantasma, sino una oportunidad para la humanidad."
  },
  AvgDialog_15611_Content_11 = {
    Text = "Sin dolor ni muerte en las máquinas; en las máquinas, podemos crear un verdadero Reino Divino, mejor que el tuyo falso.\n\nPodemos trascender la vida de Caro."
  },
  AvgDialog_15611_Content_12 = {
    Text = "El limo negro goteó una vez más de la mano gigante. Las gotas temblaban y se retorcían, arrastrándose hacia adelante mientras se fusionaban unas con otras, estremeciéndose de Elación ante la siniestra visión que la voz pintaba."
  },
  AvgDialog_15611_Content_13 = {
    Text = "La voz alcanzó un crescendo. La mano gigante se balanceó, lanzando más limo, más Monstruos."
  },
  AvgDialog_15611_Content_14 = {
    Text = "Podemos convertirnos en dioses nosotros mismos."
  },
  AvgDialog_15611_Content_15 = {
    Text = "El limo aceleró de repente, abalanzándose una vez más hacia el orbe de luz detrás de ti."
  },
  AvgDialog_15611_Content_2 = {
    Text = "Solo... tomó una decisión equivocada.\nCuando despierte, lo hablaremos, y todo se podrá resolver."
  },
  AvgDialog_15611_Content_3 = {
    Text = "La cabina telefónica más cercana está a un Kilómetro de distancia. Ella no puede permitirse esperar."
  },
  AvgDialog_15611_Content_4 = {
    Text = "Lo siento, prefiero creer en la voluntad de supervivencia de la humanidad que en tus tonterías sobre \"liberar almas\"."
  },
  AvgDialog_15611_Content_5 = {
    Text = "Si mis palabras son falsas, ¿cómo explicas tu Estado actual?\nTu cuerpo de Carne y sangre se ha hecho pedazos, y sin embargo tu espíritu persiste, e incluso puede controlar este cuerpo para seguir viviendo.\n\n¿No es eso prueba suficiente de lo que digo?"
  },
  AvgDialog_15611_Content_6 = {
    Text = "<Big:¡No puedes estar seguro de que esa sea la razón por la que me convertí en esto!>"
  },
  AvgDialog_15611_Content_7 = {
    Text = "Erica se detuvo. Parecía querer tomar un respiro, pero ya había perdido los órganos para hacerlo."
  },
  AvgDialog_15611_Content_8 = {
    Text = "Qué estoy haciendo, discutiendo con un Fantasma... No escuches, no pienses, es un Fantasma, un Fantasma causado por gases tóxicos—"
  },
  AvgDialog_15611_Content_9 = {
    Text = "Tienes miedo, así que intentas huir.\nLo entiendo. Cuando Solo había completado mi <Red:\"Metamorfosis\">, estaba lleno de miedo igual que tú."
  },
  AvgDialog_15612_Content_1 = {
    Text = "Un ritmo invisible te rodea, te envuelve. Tenues puntos de luz parpadean en la distancia, Frágiles e imposiblemente lejanos."
  },
  AvgDialog_15612_Content_10 = {
    Text = "<Gray:No puede ser... ¿podría ser...?>"
  },
  AvgDialog_15612_Content_11 = {
    Text = "¿Será posible que ahora mismo tú y Erica estéis compartiendo el mismo cuerpo?\n¿Podría ser esta la razón por la que ella se convirtió en un autómata mecánico?"
  },
  AvgDialog_15612_Content_12 = {
    Text = "<Gray:Pero, ¿cómo podría una explosión ordinaria tener este tipo de Efecto?>"
  },
  AvgDialog_15612_Content_13 = {
    Text = "¿Quieres salvarla?"
  },
  AvgDialog_15612_Content_14 = {Text = "?!"},
  AvgDialog_15612_Content_15 = {
    Text = "Una voz surge de la nada—omnipresente, pero imposible de rastrear.\nMiras a tu alrededor. En la vastedad vacía del Espacio mental, una silueta comienza a emerger."
  },
  AvgDialog_15612_Content_16 = {
    Text = "¿Quién, quién está ahí?"
  },
  AvgDialog_15612_Content_17 = {
    Text = "Soy la voluntad que responde a tu llamada, la vida a la que has dado un cuerpo completamente nuevo."
  },
  AvgDialog_15612_Content_18 = {
    Text = "Podrías llamarme tu Reliquia, y tú, eres mi \"madre\" en esta vida."
  },
  AvgDialog_15612_Content_19 = {
    Text = "Una mano enorme se materializó detrás del orbe de luz que representaba el espíritu de Erica, con las puntas de los dedos crispándose y temblando, goteando gotas de baba negra."
  },
  AvgDialog_15612_Content_2 = {
    Text = "¡Mei, Mei! ¡Despierta, Mei!"
  },
  AvgDialog_15612_Content_20 = {
    Text = "...¿Tic-Tac...?"
  },
  AvgDialog_15612_Content_21 = {
    Text = "Me gusta ese nombre. Sí, llámame el Hombre Goteando.\nComo pago por concederme un nuevo nacido sanado, puedo ayudarte a salvarla a Ella.\nSolo necesitas soltar."
  },
  AvgDialog_15612_Content_22 = {
    Text = "Suelta, y después, déjamelo todo a mí."
  },
  AvgDialog_15612_Content_23 = {
    Text = "La baba acumulada en el suelo se agitó de repente. Se fusionaron entre sí, coalesciendo en formas individuales retorcidas, retorciéndose y arrastrándose hacia la luz."
  },
  AvgDialog_15612_Content_3 = {
    Text = "Te apresuras hacia el origen de la voz."
  },
  AvgDialog_15612_Content_4 = {
    Text = "Es una esfera de luz suspendida en el aire. A través de ella, ves un rostro cubierto de Sangre y polvo: el rostro de Mei."
  },
  AvgDialog_15612_Content_5 = {
    Text = "Parece haberse desmayado. Incluso cuando una mano pálida la palmea suavemente, no hay respuesta."
  },
  AvgDialog_15612_Content_6 = {
    Text = "<Gray:esa mano...>"
  },
  AvgDialog_15612_Content_7 = {
    Text = "Bajas la mirada y confirmas la sospecha en tu mente: la mano que se muestra en la esfera de luz es idéntica a la tuya.\nEs la mano de un autómata, moviéndose ahora según la voluntad de otra persona."
  },
  AvgDialog_15612_Content_8 = {
    Text = "¡Maldita sea, Mei! ¡Tenemos que salir de aquí, Mei!"
  },
  AvgDialog_15612_Content_9 = {
    Text = "La mano mecánica se desplaza hasta posarse sobre el hombro de Mei. La escena dentro de la esfera de luz cambia, revelando el taller aún en llamas, como si alguien estuviera mirando frenéticamente a su alrededor."
  },
  AvgDialog_15613_Content_1 = {
    Text = "Un Fin Brillante"
  },
  AvgDialog_15613_Content_10 = {
    Text = "Pie derecho."
  },
  AvgDialog_15613_Content_11 = {
    Text = "Erica se desploma hacia delante de rodillas. Los cortocircuitos demasiado frecuentes han privado de energía a su pierna izquierda, dejándola apenas sosteniéndose con su brazo derecho, al que le falta la mano."
  },
  AvgDialog_15613_Content_12 = {
    Text = "Apoya con cuidado a Mei contra la cabina telefónica, luego se arrastra dentro a gatas.\nLa corriente eléctrica fuerza la activación de la cabina. Pulsa el botón de llamada de emergencia y dice la ubicación de la cabina telefónica."
  },
  AvgDialog_15613_Content_13 = {
    Text = "De esta manera... ella... estará a salvo..."
  },
  AvgDialog_15613_Content_14 = {
    Text = "Qué... viene... ahora..."
  },
  AvgDialog_15613_Content_15 = {
    Text = "Sabes lo que es."
  },
  AvgDialog_15613_Content_16 = {
    Text = "Ahora recuerdas—el contenido del archivo que leíste antes de entrar en este lugar."
  },
  AvgDialog_15613_Content_17 = {
    Text = "A.F. 297, @1/@1, 03:47. Una explosión no identificada ocurrió al sureste del pueblo de @1@2@1, provincia de @3, República de Agro. La onda expansiva provocó un terremoto local de magnitud 3,8, con temblores perceptibles que alcanzaron aldeas a 5 kilómetros del pueblo de @1@2@1.\n\n...\n\nA.F. 297, @1/@1. Se recuperaron 13 componentes del bosque al sureste del pueblo de @3@1@2@1, provincia de @3, República de Agro, numerados del A101 al A114. Entre ellos, los componentes A108, A109 y A113 estaban gravemente dañados y han sido entregados a Doll para la reconstrucción del diseño.\nEl equipo de investigación recuperó una serie de planos de diseño del Camino @2 N.º @1. Los dibujos coinciden con los componentes residuales encontrados en el lugar de la explosión y se sospecha que son planos del dispositivo explosivo. También han sido entregados a Doll para su análisis."
  },
  AvgDialog_15613_Content_18 = {
    Text = "Oyes el sonido del viento acariciando las hojas."
  },
  AvgDialog_15613_Content_19 = {
    Text = "El orbe de luz se ha vuelto muy tenue, casi fundiéndose con la oscuridad circundante."
  },
  AvgDialog_15613_Content_2 = {
    Text = "Pie izquierdo."
  },
  AvgDialog_15613_Content_20 = {
    Text = "Aunque salves su cuerpo de carne y sangre, ¿y qué?\nLa muerte llegará tarde o temprano. Cuando llegue, ¿te lo agradecerá, o te odiará por robarle la oportunidad de la inmortalidad?\n\nDéjalo, Erica. Déjame tomar el control de este cuerpo.\nLe concederé la <Red:\"Metamorfosis\">, y le daré un futuro mejor."
  },
  AvgDialog_15613_Content_21 = {
    Text = "Yo... siempre pensé... que moriría en una explosión...\nLo siento... por... arrastrarte conmigo..."
  },
  AvgDialog_15613_Content_22 = {
    Text = "...¿Qué estás haciendo?"
  },
  AvgDialog_15613_Content_23 = {
    Text = "Cállate... demonio... No estoy... hablándote a ti..."
  },
  AvgDialog_15613_Content_24 = {
    Text = "La imagen que aparece dentro del orbe de luz es una mano mecánica, ya cubierta de marcas de quemaduras, que aún sigue perdiendo electroplasma sin cesar."
  },
  AvgDialog_15613_Content_25 = {
    Text = "En algún momento, la mano había agarrado varios cables, recubiertos de limo negro."
  },
  AvgDialog_15613_Content_26 = {
    Text = "Lo siento, Tic-Tac... Al final... tengo que... destruirte con mis propias manos..."
  },
  AvgDialog_15613_Content_27 = {
    Text = "El Silencio desciende entre ustedes.\nAún no estás seguro de tu identidad en este Sueño, y ella tampoco parece estar esperando una respuesta."
  },
  AvgDialog_15613_Content_28 = {
    Text = "*suspiro*..."
  },
  AvgDialog_15613_Content_29 = {
    Text = "Qué... lástima..."
  },
  AvgDialog_15613_Content_3 = {
    Text = "Pie derecho."
  },
  AvgDialog_15613_Content_30 = {
    Text = "Ella tira con todas sus fuerzas."
  },
  AvgDialog_15613_Content_32 = {
    Text = "Te incorporas de golpe y te encuentras de vuelta en tu habitación de siempre."
  },
  AvgDialog_15613_Content_33 = {
    Text = "Alguien está llamando a tu puerta."
  },
  AvgDialog_15613_Content_34 = {Text = "Entra."},
  AvgDialog_15613_Content_35 = {
    Text = "Buenas tardes, Guardián. Tienes un mensaje de Muñeca. ¿Te gustaría recibirlo?"
  },
  AvgDialog_15613_Content_36 = {
    Text = "Qué nueva función habrá inventado Doll esta vez... Recibir."
  },
  AvgDialog_15613_Content_37 = {
    Text = "Bip— ¿Recuerdas qué día es hoy, %player%? Dos palabras: el examen."
  },
  AvgDialog_15613_Content_38 = {Text = "...Oh, no."},
  AvgDialog_15613_Content_39 = {
    Text = "Te sugiero que aparezcas en el aula en cinco minutos, o no puedo garantizar cómo será tu vida de entrenamiento durante los próximos 30 días. ¿Quizás se duplique el régimen de entrenamiento físico?"
  },
  AvgDialog_15613_Content_4 = {
    Text = "Con cada paso, saltan chispas. Con cada paso, se oye el chirrido de la maquinaria rechinando contra sí misma."
  },
  AvgDialog_15613_Content_40 = {
    Text = "Bip— Fin del mensaje. ¿Desea responder?"
  },
  AvgDialog_15613_Content_41 = {
    Text = "¿¡Responder!? ¡¡No hay tiempo para eso, tengo que correr!!"
  },
  AvgDialog_15613_Content_42 = {
    Text = "La figura del Guardián desapareció al final del pasillo. Erica se dio la vuelta y miró los documentos esparcidos sobre el escritorio."
  },
  AvgDialog_15613_Content_43 = {
    Text = "Desbordamiento 298, @1/@2, Universidad de Misag, Despertar, @3\nSe completó la restauración del torso del autómata E basándose en el plano T-38, número de serie EA301881.\nEste es nuestro décimo intento de restauración. Debo admirar a quien originalmente diseñó y realizó la Fabricación de esto— el autómata es extraordinariamente intrincado y elegante. Cientos y miles de engranajes y rodamientos se entrelazan, ejecutando juntos una magnífica sinfonía de ingeniería mecánica. Incluso ahora, mientras permanece inmóvil, puedo percibir una vitalidad única en su interior.\nDesafortunadamente, aún no hemos encontrado la clave del plano del motor— un cilindro de 5 centímetros de diámetro y 10 centímetros de longitud. Debería ser el núcleo energético de todo el autómata, pero nunca he visto algo de ese tamaño capaz de alimentar un mecanismo tan complejo...\nEspero que la profesora Doll pueda encontrar una solución. Apenas puedo esperar para verlo cobrar vida de verdad."
  },
  AvgDialog_15613_Content_44 = {
    Text = "Desbordamiento 298, @1/@2, Universidad de Misag, Despertar, @3\nSe completó la restauración del motor, número de serie MF311028.\nAunque encontramos bastantes contratiempos en el camino (¡Padre Dios, hicimos 28 intentos completos, 28!), la hipótesis final de la profesora Doll resultó ser correcta— el núcleo de energía del motor es un Núcleo de plata.\nTras probar múltiples Núcleos de plata, Solo el Núcleo de plata E-1929 permitió que el motor funcionara correctamente. No puedo evitar imaginar que se trata de alguna influencia persistente de la voluntad del diseñador, aunque todavía desconocemos el paradero de esta persona."
  },
  AvgDialog_15613_Content_45 = {
    Text = "Desbordamiento 300, @2/@1, Universidad de Misag, Despertar, Doll\nEl autómata Erica Despertó con éxito.\nEl Cuerpo Despertado exhibe una agresividad extrema e impulsos destructivos. Incluso con un Investigador manteniendo su Estado mental, Ella aún muestra claras tendencias de ATQ y Libera incontrolablemente corrientes eléctricas, realizando ataques indiscriminados contra los objetos circundantes.\nAlistair determinó que E-1929 contiene dos espíritus— uno abrumadoramente poderoso en su Locura, y otro que, aunque débil, posee mayor racionalidad. Se debería intentar Separar a ambos, o Inhibir la Locura hasta un nivel controlable.\n...\nDesbordamiento 300, @2/@2, Universidad de Misag, Despertar, Doll\nImposible Separar los espíritus. Considerando activamente el segundo plan.\nUn dispositivo de Inhibición de espíritus es una buena idea.\n...\nDesbordamiento 303, @1/@2, Universidad de Misag, Despertar, Doll\nDispositivo de Inhibición fabricado e instalado con éxito.\nLa Locura del Cuerpo Despertado ha sido Inhibida. El Estado general tiende hacia la estabilidad, aunque aún ocurren breves lapsos en la Inhibición.\nLa personalidad, intereses y otros rasgos del Cuerpo Despertado se han perdido por completo. Su comportamiento se asemeja más al de una muñeca que al de una persona.\nAl menos Ella ya no está al borde de explotar a cada momento.\n..."
  },
  AvgDialog_15613_Content_46 = {
    Text = "Erica inclinó la cabeza, ordenó los documentos y salió de la habitación."
  },
  AvgDialog_15613_Content_5 = {
    Text = "Bajo una farola no muy lejos, una cabina telefónica pública permanece en silencio."
  },
  AvgDialog_15613_Content_6 = {
    Text = "Pie izquierdo."
  },
  AvgDialog_15613_Content_7 = {
    Text = "Pie derecho."
  },
  AvgDialog_15613_Content_8 = {
    Text = "Como si notara tu determinación, el limo desplomado en el suelo continúa su asalto contra la consciencia de Erica, tiñéndote a ti también de negro absoluto."
  },
  AvgDialog_15613_Content_9 = {
    Text = "Pie izquierdo."
  },
  AvgDialog_18708_Content_1 = {Text = "¡!!!"},
  AvgDialog_18708_Content_10 = {
    Text = "Acompañado de gemidos dolorosos, las características del Cazador de Calaveras se retorcían de una manera inverosímil, con quistes llenos de pus retorciéndose bajo la piel, listos para estallar."
  },
  AvgDialog_18708_Content_11 = {
    Text = "¿Qué es esto...?"
  },
  AvgDialog_18708_Content_13 = {
    Text = "Tu cabeza es brutalmente separada, D-Slime negro brotando del cuello, casi salpicando tu cara."
  },
  AvgDialog_18708_Content_14 = {
    Text = "Ser demasiado curioso no es un buen hábito, Guardián."
  },
  AvgDialog_18708_Content_15 = {
    Text = "Su cráneo estaba lleno de D-Slime acumulado. Te sugiero que mantengas tu distancia."
  },
  AvgDialog_18708_Content_16 = {
    Text = "¡Dama Daffodil!"
  },
  AvgDialog_18708_Content_17 = {
    Text = "Buenas noches, mi pequeña rosa."
  },
  AvgDialog_18708_Content_18 = {
    Text = "¿Por qué eres tú otra vez...?"
  },
  AvgDialog_18708_Content_19 = {
    Text = "Seguí el rastro del Cazador de Cráneos hasta aquí y recuperé mi flor."
  },
  AvgDialog_18708_Content_2 = {
    Text = "El Cazador de Calaveras colapsa pesadamente en el suelo, emitiendo un leve gemido."
  },
  AvgDialog_18708_Content_20 = {
    Text = "Daffodil caminó sin esfuerzo sobre el suelo manchado de sangre y D-Limo, tomó un narciso de la mesita y lo olfateó suavemente."
  },
  AvgDialog_18708_Content_21 = {
    Text = "Este es mi Narciso Marrón, que he cultivado con cuidado durante tres años. Tiene un efecto calmante y relajante."
  },
  AvgDialog_18708_Content_22 = {
    Text = "¿Te gustaría olerlo?"
  },
  AvgDialog_18708_Content_23 = {
    Text = "<LightGray:No es de extrañar que haya dormido tan profundamente hace un momento...>"
  },
  AvgDialog_18708_Content_24 = {
    Text = "Apartaste irritablemente el narciso en su mano que estaba húmedo y en flor."
  },
  AvgDialog_18708_Content_25 = {
    Text = "Parece que sabes mucho sobre el Cazador de Cráneos."
  },
  AvgDialog_18708_Content_26 = {
    Text = "¿Cómo sabes que su cerebro secretaría D-baba?"
  },
  AvgDialog_18708_Content_27 = {
    Text = "Si hubieras vivido tanto tiempo como yo y visto suficientes pacientes de Disolución, naturalmente entenderías más."
  },
  AvgDialog_18708_Content_28 = {
    Text = "¿La Pista del Cazador de Cráneos?"
  },
  AvgDialog_18708_Content_29 = {
    Text = "\"Siguiendo la huella del Cazador de Calaveras\"—¿Puedes sentir su ubicación?"
  },
  AvgDialog_18708_Content_3 = {
    Text = "Oyes \"thud, thud, thud\" proveniente de las escaleras. La puerta de madera detrás de ti se abre de repente."
  },
  AvgDialog_18708_Content_30 = {
    Text = "Tengo mis métodos. Sin embargo... para no asustar a los niños, mejor no los revelo."
  },
  AvgDialog_18708_Content_31 = {Text = "..."},
  AvgDialog_18708_Content_32 = {
    Text = "Por favor, ve por ahora, Señora Narciso. No interfieras en la investigación del Guardián."
  },
  AvgDialog_18708_Content_33 = {
    Text = "Eh, ¿ya no dudas de mí?"
  },
  AvgDialog_18708_Content_34 = {
    Text = "No puedo descartar completamente tu sospecha todavía. Pero mi intuición me dice..."
  },
  AvgDialog_18708_Content_35 = {
    Text = "Si fueras el \"**Cazador de Calaveras**\", lo manejarías de manera más limpia y eficiente, sin dejar tales rastros obvios atrás."
  },
  AvgDialog_18708_Content_36 = {
    Text = "Oh Dios mío, ¿es eso un cumplido para mí?\nPara ser preciso, es un hecho, no solo una intuición."
  },
  AvgDialog_18708_Content_37 = {
    Text = "...No cambies de tema."
  },
  AvgDialog_18708_Content_38 = {
    Text = "Desde que solo llegaste a la ciudad hoy, ¿quién era esa persona que vi anoche?"
  },
  AvgDialog_18708_Content_39 = {
    Text = "¿Tienes una hermana gemela?"
  },
  AvgDialog_18708_Content_4 = {
    Text = "{Male=Mr.,Female=Miss} %player%, acabo de oír un ruido, ¿qué ha pasado?"
  },
  AvgDialog_18708_Content_40 = {Text = "..."},
  AvgDialog_18708_Content_41 = {
    Text = "Daffodil parecía preocupada en sus pensamientos, luego de repente se acercó a ti."
  },
  AvgDialog_18708_Content_42 = {
    Text = "D dulces y suaves yemas de los dedos rozan tu rostro por un momento, luego se deslizan hacia tu cuello, deteniéndose para sentir el pulso profundo dentro de tus vasos sanguíneos."
  },
  AvgDialog_18708_Content_43 = {
    Text = "<Shake:...?>"
  },
  AvgDialog_18708_Content_44 = {
    Text = "Siempre pensé que los humanos eran criaturas hábiles en el disfraz."
  },
  AvgDialog_18708_Content_45 = {
    Text = "Se envuelven en similar Caro, hablando palabras similares, con pulsos y latidos del corazón similares..."
  },
  AvgDialog_18708_Content_46 = {
    Text = "Durante mucho tiempo, no pude distinguir entre ustedes, así como ustedes no pudieron distinguirme."
  },
  AvgDialog_18708_Content_47 = {
    Text = "Entonces... ¿quieres decir que no son gemelos, sino que comparten algún tipo de relación especial?"
  },
  AvgDialog_18708_Content_48 = {
    Text = "Es posible. ¿Quieres hacer una suposición? Tienes tres oportunidades."
  },
  AvgDialog_18708_Content_49 = {
    Text = "...Me niego."
  },
  AvgDialog_18708_Content_5 = {
    Text = "E-¿Esto es...?!"
  },
  AvgDialog_18708_Content_50 = {
    Text = "Incluso si adivino correctamente, aún no me dirás la verdadera respuesta. ¿Estoy en lo correcto?"
  },
  AvgDialog_18708_Content_51 = {
    Text = "Narciso trazó descuidadamente las venas de tu cuello con sus yemas de los dedos, sus ojos llenos de una sonrisa aún más profunda."
  },
  AvgDialog_18708_Content_52 = {
    Text = "Realmente estás llegando a conocerme mejor, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_18708_Content_53 = {
    Text = "Das medio paso atrás, alejándote del alcance de Narciso, y le lanzas una mirada de advertencia."
  },
  AvgDialog_18708_Content_54 = {
    Text = "A tus ojos, ¿parecerse exactamente hace que sean gemelos?"
  },
  AvgDialog_18708_Content_55 = {
    Text = "En términos generales, esta es probablemente la única posibilidad."
  },
  AvgDialog_18708_Content_56 = {
    Text = "Pero tú y yo sabemos que el mundo en el que vivimos es todo menos \"ordinario\""
  },
  AvgDialog_18708_Content_57 = {
    Text = "Claro. El aspecto más lamentable de este mundo es su \"no convencionalidad\""
  },
  AvgDialog_18708_Content_58 = {
    Text = "Ser un par de hermanas gemelas despreocupadas también parece agradable."
  },
  AvgDialog_18708_Content_6 = {
    Text = "Te acercas y desplazas la capucha negra del Cazador de Calaveras, revelando el rostro debajo"
  },
  AvgDialog_18708_Content_7 = {
    Text = "Pómulos altos, nariz aguileña y mejillas hundidas—una cara completamente desconocida."
  },
  AvgDialog_18708_Content_8 = {
    Text = "Realmente sabes cómo elegir tus objetivos, persiguiéndome hasta aquí. ¿Quién eres exactamente?"
  },
  AvgDialog_18708_Content_9 = {
    Text = "Ugh... Ah..."
  },
  AvgDialog_18709_Content_1 = {
    Text = "Lluvia amarga"
  },
  AvgDialog_18709_Content_10 = {
    Text = "Tú te apoyas contra el cabecero de la cama, recuerdos de eventos recientes desfilando ante tus ojos. Muchos problemas siguen sin resolverse."
  },
  AvgDialog_18709_Content_11 = {
    Text = "Preguntemos primero a la señorita Horla qué sabe."
  },
  AvgDialog_18709_Content_12 = {
    Text = "Preguntar a Old Freeman"
  },
  AvgDialog_18709_Content_13 = {
    Text = "¿El viejo Freeman? Así que todavía está vivo..."
  },
  AvgDialog_18709_Content_14 = {
    Text = "He oído a los aldeanos decir que era una persona optimista y alegre cuando era joven, y a todos les gustaba."
  },
  AvgDialog_18709_Content_15 = {
    Text = "Después de la <Yellow:plaga>, dejó la Ciudad Reny y regresó como una persona completamente diferente."
  },
  AvgDialog_18709_Content_16 = {Text = "¿Plaga?"},
  AvgDialog_18709_Content_17 = {
    Text = "Hace tres años, ocurrió un desastre de Disolución al norte de la ciudad de Ryker. Los lugareños lo denominaron una plaga."
  },
  AvgDialog_18709_Content_18 = {
    Text = "Ahora se ha convertido completamente en una tierra muerta."
  },
  AvgDialog_18709_Content_19 = {
    Text = "Preguntar a Daffodil"
  },
  AvgDialog_18709_Content_2 = {Text = "..."},
  AvgDialog_18709_Content_20 = {
    Text = "Señorita Horla, el tono que usaste al hablar de Narciso hace un momento... ¿se conocían antes?"
  },
  AvgDialog_18709_Content_21 = {
    Text = "La Dama Narciso..."
  },
  AvgDialog_18709_Content_22 = {
    Text = "Horla miró la página del libro en su mano, una leve sonrisa jugando en su rostro."
  },
  AvgDialog_18709_Content_23 = {
    Text = "La Dama Narciso, ella... me ayudó."
  },
  AvgDialog_18709_Content_24 = {
    Text = "Año 15@1, San Pedro"
  },
  AvgDialog_18709_Content_25 = {
    Text = "Esta colección de poemas de Longsa es única en su tipo. Asegúrate de atesorarla."
  },
  AvgDialog_18709_Content_26 = {
    Text = "Muchas gracias, Dama Narciso. No puedo creer que realmente lo encontraste..."
  },
  AvgDialog_18709_Content_27 = {
    Text = "\"Que siempre retengas la radiante belleza de una rosa.\""
  },
  AvgDialog_18709_Content_28 = {
    Text = "Hermosa poesía. Tienes un excelente gusto."
  },
  AvgDialog_18709_Content_29 = {
    Text = "Sí, pero prefiero \"Honro este momento con leche y flores...\""
  },
  AvgDialog_18709_Content_3 = {
    Text = "Por fin despertaste, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_18709_Content_30 = {
    Text = "Ah... Lo siento, me distraje de nuevo."
  },
  AvgDialog_18709_Content_31 = {
    Text = "Conozco las reglas de la \"Tienda de Intercambio.\" Entonces, ¿qué quieres de mí?"
  },
  AvgDialog_18709_Content_32 = {
    Text = "Hmm... Tendré que observarte de cerca, mi pequeña rosa."
  },
  AvgDialog_18709_Content_33 = {
    Text = "La mirada recorrió todo el cuerpo de Horla sin emoción. La niña involuntariamente enderezó su espalda."
  },
  AvgDialog_18709_Content_34 = {
    Text = "¿Puedes compartir un recuerdo conmigo?\nDoloroso, triste... cualquier recuerdo infeliz servirá."
  },
  AvgDialog_18709_Content_35 = {
    Text = "¿Recuerdos infelices? Th-That's no es una buena cosa. ¿Qué planeas hacer con ellos...?"
  },
  AvgDialog_18709_Content_36 = {
    Text = "Planeo usarlo para un pequeño experimento. Entonces lo sabrás."
  },
  AvgDialog_18709_Content_37 = {
    Text = "Días de agotamiento implacable erosionaron tus nervios; te dejas llevar al sueño por las suaves palabras de Horla."
  },
  AvgDialog_18709_Content_38 = {Text = "..."},
  AvgDialog_18709_Content_39 = {
    Text = "Después de un tiempo desconocido, comenzó una ligera llovizna afuera de la ventana."
  },
  AvgDialog_18709_Content_4 = {
    Text = "Recuerdo que parecía desmayarme, y luego..."
  },
  AvgDialog_18709_Content_40 = {
    Text = "Alguien está avanzando lenta y sin fin por el camino lodoso bajo la lluvia."
  },
  AvgDialog_18709_Content_41 = {
    Text = "Solo aparecen en noches lluviosas, sus pasos ocultos por la lluvia, acercándose sigilosamente detrás de ti..."
  },
  AvgDialog_18709_Content_42 = {
    Text = "Los Cazadores de Cráneos no son una persona ni dos. Los Cazadores de Cráneos son una organización."
  },
  AvgDialog_18709_Content_43 = {
    Text = "Una noche lluviosa, solo... <Red:¿No es esta tu situación actual?>"
  },
  AvgDialog_18709_Content_44 = {
    Text = "<Red:Zzz... Krr...>"
  },
  AvgDialog_18709_Content_45 = {
    Text = "<RedBig:¡Pum!>"
  },
  AvgDialog_18709_Content_46 = {Text = "¿?!"},
  AvgDialog_18709_Content_47 = {
    Text = "Un pálido rayo de luz atraviesa la quietud de la noche. Abres abruptamente los ojos en la oscuridad."
  },
  AvgDialog_18709_Content_48 = {
    Text = "Alguien está de pie junto a tu cama."
  },
  AvgDialog_18709_Content_49 = {
    Text = "La pesada mirada se siente como una guadaña fría y húmeda trazando tus extremidades, espalda, y..."
  },
  AvgDialog_18709_Content_5 = {
    Text = "Sí, fue la Dama Narciso quien te trajo de vuelta y me instruyó a cuidar de ti."
  },
  AvgDialog_18709_Content_50 = {
    Text = "Un cuello desprotegido."
  },
  AvgDialog_18709_Content_51 = {
    Text = "Cabeza@1 Calavera@4"
  },
  AvgDialog_18709_Content_54 = {Text = "Hmm...!!"},
  AvgDialog_18709_Content_55 = {
    Text = "De repente, caes de la cama e instinctivamente cubres tu cuello."
  },
  AvgDialog_18709_Content_56 = {
    Text = "Una figura sombría sosteniendo una guadaña está de pie junto a la cama, casi fusionándose con la oscura noche detrás."
  },
  AvgDialog_18709_Content_57 = {
    Text = "El aire está impregnado con el aroma de lluvia y óxido. Sangre roja oscura gotea de la fría hoja blanca, acumulándose en el suelo."
  },
  AvgDialog_18709_Content_58 = {
    Text = "—Es el Cazador de Calaveras."
  },
  AvgDialog_18709_Content_6 = {
    Text = "¿Daffodil...?"
  },
  AvgDialog_18709_Content_7 = {
    Text = "Atrapas un olor familiar."
  },
  AvgDialog_18709_Content_8 = {
    Text = "Un jarrón de cuello delgado ha aparecido en la mesita de noche, con flores de narciso blancas extendiendo sus pétalos hacia la luz del sol."
  },
  AvgDialog_18709_Content_9 = {
    Text = "Es su aroma..."
  },
  AvgDialog_18710_Content_1 = {
    Text = "Reino de bestias"
  },
  AvgDialog_18710_Content_10 = {
    Text = "Era una clara noche de verano, y yo estaba llevando diligentemente mis \"botines\" como de costumbre."
  },
  AvgDialog_18710_Content_11 = {
    Text = "<Shake:Cabezas... más cabezas...>"
  },
  AvgDialog_18710_Content_12 = {
    Text = "Toca. Toca. Toca."
  },
  AvgDialog_18710_Content_13 = {
    Text = "El sonido de pasos ligeros se acercó silenciosamente, y una voz suave vino desde arriba."
  },
  AvgDialog_18710_Content_14 = {
    Text = "Heh... ¿Mira lo que he encontrado? Una pequeña bestia callejera."
  },
  AvgDialog_18710_Content_15 = {
    Text = "Esa noche, una mujer vino a mí."
  },
  AvgDialog_18710_Content_16 = {
    Text = "Cuando ella se acercó a mí, percibí una fragancia agradable.\nEra el aroma de flores y niebla."
  },
  AvgDialog_18710_Content_17 = {
    Text = "Este es el aroma de otro mundo, tan diferente de mi reino como el día de la noche, nunca destinado a intersectarse."
  },
  AvgDialog_18710_Content_18 = {
    Text = "Pero ella aún avanzó a través del lodazal de mal olor, caminó por las sombras de la ciudad y se extendió hacia mí."
  },
  AvgDialog_18710_Content_19 = {
    Text = "Ella dijo..."
  },
  AvgDialog_18710_Content_2 = {
    Text = "Soy una bestia... Soy un paciente.\n\nEstoy más allá de la redención."
  },
  AvgDialog_18710_Content_20 = {
    Text = "¿Te gustaría venir conmigo, pequeña bestia?"
  },
  AvgDialog_18710_Content_21 = {
    Text = "5:00, al norte de Reni Town"
  },
  AvgDialog_18710_Content_22 = {
    Text = "Este lugar es... verdaderamente desolado."
  },
  AvgDialog_18710_Content_23 = {
    Text = "Hace tres años, apareció un <Yellow:S-Class D-Rift> aquí. Agua, vegetación... todo el ecosistema sufrió daños severos."
  },
  AvgDialog_18710_Content_24 = {
    Text = "Afortunadamente, hubo pocas bajas y los residentes fueron evacuados bajo el arreglo del Comité."
  },
  AvgDialog_18710_Content_25 = {
    Text = "Miras las paredes desoladas y los árboles pálidos y marchitos delante de ti."
  },
  AvgDialog_18710_Content_26 = {
    Text = "Si no fuera por la Disolución, este sería un campo verde en plena floración con lilas. Cuando sopla el viento, la hierba se ondula como olas, pareciendo un océano verde."
  },
  AvgDialog_18710_Content_27 = {
    Text = "¿Estás seguro de que el Cazador de Cráneos está aquí, Dama Narciso?"
  },
  AvgDialog_18710_Content_28 = {
    Text = "La única respuesta es el croar áspero de los cuervos."
  },
  AvgDialog_18710_Content_29 = {
    Text = "Oh, ¿la Dama del narciso está desaparecida?"
  },
  AvgDialog_18710_Content_3 = {
    Text = "Durante el día, me escondo en las sombras de la ciudad, acostado sobre mi espalda con mi vientre hacia arriba, durmiendo profundamente."
  },
  AvgDialog_18710_Content_30 = {
    Text = "Bueno, las consecuencias de confiar en los demás."
  },
  AvgDialog_18710_Content_31 = {
    Text = "Ahem. Ella siempre es tan impredecible en sus movimientos; ya me he acostumbrado a ello desde hace tiempo."
  },
  AvgDialog_18710_Content_32 = {
    Text = "¡No te preocupes, puedo investigar por mí mismo. Definitivamente encontraré algo aquí..."
  },
  AvgDialog_18710_Content_33 = {
    Text = "<Big:¡Boom—!!>"
  },
  AvgDialog_18710_Content_34 = {
    Text = "El trueno retumba en las nubes bajas, y las hojas secas susurran en el viento otoñal."
  },
  AvgDialog_18710_Content_35 = {
    Text = "Esta es una señal de lluvia."
  },
  AvgDialog_18710_Content_36 = {
    Text = "¿Por qué solo aparece en días lluviosos?"
  },
  AvgDialog_18710_Content_37 = {
    Text = "Porque cuando llueve, la sangre y la lluvia se mezclan y fluyen hacia las alcantarillas."
  },
  AvgDialog_18710_Content_38 = {
    Text = "Sí, fluye hacia las alcantarillas, ataúdes y los pequeños desagües a tu alrededor..."
  },
  AvgDialog_18710_Content_39 = {
    Text = "<Red:Zzz... Krr...>"
  },
  AvgDialog_18710_Content_4 = {
    Text = "De noche, vagando por las calles como un fantasma, busco una cabeza tras otra."
  },
  AvgDialog_18710_Content_40 = {
    Text = "Una noche lluviosa y oscura... No, estoy soñando despierto de nuevo."
  },
  AvgDialog_18710_Content_41 = {
    Text = "Sacudiste la cabeza con fuerza, tratando de despejar el caos de tu mente."
  },
  AvgDialog_18710_Content_42 = {
    Text = "El tiempo se está acabando. Debes actuar rápido."
  },
  AvgDialog_18710_Content_5 = {
    Text = "<Red:Cráneo. Cráneo. Cráneo.>"
  },
  AvgDialog_18710_Content_6 = {
    Text = [[
<RedBig:Cabecas.
        Cabecas.
                Cabecas.
                        Cabecas.
                                Cabecas.
                                        Cabecas...>]]
  },
  AvgDialog_18710_Content_7 = {
    Text = "Mi mente ya no puede contemplar la supervivencia, el amor y la dignidad.\n\nHa estado llena hasta el borde con esas fantasías insaciables."
  },
  AvgDialog_18710_Content_8 = {
    Text = "Soy irredeemible."
  },
  AvgDialog_18710_Content_9 = {
    Text = "Año 15@1, Ciudad San Pedro"
  },
  AvgDialog_18711_Content_1 = {
    Text = "¡Ahhhh—!"
  },
  AvgDialog_18711_Content_10 = {
    Text = "Ella ignoró la baba sucia y la sangre en el suelo, se agachó y miró a la criatura que luchaba frente a ella."
  },
  AvgDialog_18711_Content_11 = {
    Text = "¡Deja de buscar! Se han ido y nunca volverán."
  },
  AvgDialog_18711_Content_12 = {
    Text = "Lo que necesitas no son estas cosas."
  },
  AvgDialog_18711_Content_13 = {
    Text = "¿No es necesario...? No, Head@1, dámelo."
  },
  AvgDialog_18711_Content_14 = {Text = "..."},
  AvgDialog_18711_Content_15 = {
    Text = "¿Sabías? En realidad... somos iguales.\nEntiendo tu dolor."
  },
  AvgDialog_18711_Content_16 = {
    Text = "Año 15@1, Ciudad San Pedro"
  },
  AvgDialog_18711_Content_17 = {
    Text = "¿Vendrás conmigo, pequeña bestia? Necesitas ayuda."
  },
  AvgDialog_18711_Content_18 = {
    Text = "Año 15@1 En el verano del primer año, una mujer me extendió la mano."
  },
  AvgDialog_18711_Content_19 = {
    Text = "Quizás es su agradable aroma, o quizás solo parece gentil."
  },
  AvgDialog_18711_Content_2 = {
    Text = "Una masa de carne colapsa, derramando D-Slim y moco gris, revelando el frágil cuerpo de Harriet."
  },
  AvgDialog_18711_Content_20 = {
    Text = "En resumen, no la rechacé."
  },
  AvgDialog_18711_Content_21 = {
    Text = "Agarré ingenuamente su mano, y con ella, mi destino futuro."
  },
  AvgDialog_18711_Content_22 = {
    Text = "Tos... Tos..."
  },
  AvgDialog_18711_Content_23 = {
    Text = "Estás muriendo, Narciso."
  },
  AvgDialog_18711_Content_24 = {
    Text = "Niño tonto... Después de todos estos años, todavía no has aprendido a hablar correctamente."
  },
  AvgDialog_18711_Content_25 = {
    Text = "No llores... *tos*..."
  },
  AvgDialog_18711_Content_26 = {
    Text = "<Shake:Yo... no lo hice...>"
  },
  AvgDialog_18711_Content_27 = {
    Text = "Toma mi cabeza. Te confío mi identidad, apariencia y esta pequeña tienda."
  },
  AvgDialog_18711_Content_28 = {Text = "¿?!"},
  AvgDialog_18711_Content_29 = {
    Text = "Sé, cough cough... siempre has anhelado caminar por el mundo como un humano ordinario."
  },
  AvgDialog_18711_Content_3 = {
    Text = "Cráneos grisáceos y blancos surgieron, solo para desvanecerse en un abrir y cerrar de ojos."
  },
  AvgDialog_18711_Content_30 = {
    Text = "Te escondes en la esquina, observando cómo hablo y camino. Cuando no estoy, secretamente usas mi ropa e incluso pretendes ser yo para hacer amigos..."
  },
  AvgDialog_18711_Content_31 = {
    Text = "Siempre supe."
  },
  AvgDialog_18711_Content_32 = {
    Text = "Lo siento, Narciso, no quise..."
  },
  AvgDialog_18711_Content_33 = {
    Text = "Ahora, cumpliré tu deseo, eh... pero debes prometerme..."
  },
  AvgDialog_18711_Content_34 = {
    Text = "En el futuro, no cortes casualmente las cabezas de los inocentes. Si te encuentras con alguien como tú, debes ayudarlo."
  },
  AvgDialog_18711_Content_35 = {
    Text = "Solo como te estoy ayudando ahora."
  },
  AvgDialog_18711_Content_36 = {
    Text = "<Shake:Sálvame, sálvame...>"
  },
  AvgDialog_18711_Content_37 = {
    Text = "Harriet emite un aullido bestial y se extendió temblorosamente hacia la Dama Narciso."
  },
  AvgDialog_18711_Content_38 = {Text = "..."},
  AvgDialog_18711_Content_39 = {
    Text = "En aquel entonces... cuando viste a tu esposo en el cementerio, debiste sentirte completamente desesperada, ¿verdad?"
  },
  AvgDialog_18711_Content_4 = {
    Text = "Cabeza@1 No..."
  },
  AvgDialog_18711_Content_40 = {
    Text = "Freeman... ¿Eh?@2..."
  },
  AvgDialog_18711_Content_41 = {
    Text = "Compartimos la misma maldición, pero soy mucho más afortunado que tú."
  },
  AvgDialog_18711_Content_42 = {
    Text = "Cuando aún no conocía la diferencia entre el bien y el mal, fue esa dama quien me tendió la mano."
  },
  AvgDialog_18711_Content_43 = {
    Text = "Narciso se arrodilló ante la Sra. Harriet, sosteniendo suavemente su mano marcada y cubierta de D-Slimy."
  },
  AvgDialog_18711_Content_44 = {
    Text = "Aprendí a hablar y a caminar como ella, moldeándome en su imagen."
  },
  AvgDialog_18711_Content_45 = {
    Text = "¡Cuidado, Dama Narciso! Las manos de Harriet están cubiertas de D-baba—"
  },
  AvgDialog_18711_Content_46 = {
    Text = "Shh... Aún tengo algo que decirle."
  },
  AvgDialog_18711_Content_47 = {
    Text = "Narciso continuó mirando a Harriet. Una conexión secreta fluía entre ellos, aislándolos de todas las distracciones."
  },
  AvgDialog_18711_Content_48 = {
    Text = "Ahora puedo finalmente extender la mano a los demás, tal como ella lo hizo... Pero es demasiado tarde."
  },
  AvgDialog_18711_Content_49 = {
    Text = "Un humo púrpura pálido se eleva gradualmente, flotando lentamente en la oscura habitación."
  },
  AvgDialog_18711_Content_5 = {
    Text = "Harriet, sin cabeza y inquieta, se retorcía mientras las venas de su cuello pulsaban rápidamente, emitiendo un leve zumbido."
  },
  AvgDialog_18711_Content_50 = {
    Text = "Atrapas ese olor floral familiar nuevamente, mezclado con la humedad de la neblina de medianoche, diluyendo el pesado olor a sangre de la habitación."
  },
  AvgDialog_18711_Content_51 = {
    Text = "Narciso colocó suavemente su mano al lado de la Sra. Harriet."
  },
  AvgDialog_18711_Content_52 = {
    Text = "Ten la seguridad, Lady Harriet. No sentirás ningún dolor."
  },
  AvgDialog_18711_Content_53 = {
    Text = "Una ruptura se abre rápidamente desde su palma, engullendo lentamente a Harriet..."
  },
  AvgDialog_18711_Content_54 = {
    Text = "<Shake:...>"
  },
  AvgDialog_18711_Content_55 = {
    Text = "Dile a mi esposo@2 que deje de beber."
  },
  AvgDialog_18711_Content_56 = {
    Text = "Hay más..."
  },
  AvgDialog_18711_Content_57 = {
    Text = "La garganta expuesta de Harriet tembló ligeramente, pero finalmente cayó en silencio como una hoja marchita."
  },
  AvgDialog_18711_Content_58 = {
    Text = "Ella soltó la mano de Narciso y cayó en silencio en una insondable grieta dimensional."
  },
  AvgDialog_18711_Content_59 = {
    Text = "<Change> Adiós, adiós..."
  },
  AvgDialog_18711_Content_6 = {
    Text = "Dame@2 cabezas, dame..."
  },
  AvgDialog_18711_Content_60 = {
    Text = "Finalmente... ¿se acabó? ¿Dónde la llevaste, Dama Daffodil?"
  },
  AvgDialog_18711_Content_61 = {
    Text = "El Océano Primal. Tendrá mucho tiempo para recordar... o olvidar todo lo que sucedió."
  },
  AvgDialog_18711_Content_62 = {
    Text = "La Dama Harriet..."
  },
  AvgDialog_18711_Content_63 = {
    Text = "Antes de que puedas reunir tus pensamientos dispersos, pasos tenues resuenan afuera de la casa."
  },
  AvgDialog_18711_Content_64 = {
    Text = "¿Quién está ahí? Sigamos y echemos un vistazo."
  },
  AvgDialog_18711_Content_65 = {
    Text = "Sí, soy yo... hic."
  },
  AvgDialog_18711_Content_66 = {
    Text = "¡Cuánto tiempo sin verte, pequeño detective! ¿Me recuerdas, el sepulturero Viejo Freeman?"
  },
  AvgDialog_18711_Content_67 = {
    Text = "El viejo Freeman, sosteniendo una botella de brandy, seguía eructando con una sonrisa incómoda en su rostro."
  },
  AvgDialog_18711_Content_68 = {
    Text = "¿¡El viejo Freeman?! ¿Qué estás haciendo aquí... ¿Oíste todo?"
  },
  AvgDialog_18711_Content_69 = {Text = "Yo..."},
  AvgDialog_18711_Content_7 = {
    Text = "Ella se arrastró ansiosamente por el suelo, sus brazos huesudos agitando. Como una bestia acorralada, dejó escapar gemidos desesperados de su garganta."
  },
  AvgDialog_18711_Content_70 = {
    Text = "Tampoco sé qué pasó. Dormí como un tronco después de beber."
  },
  AvgDialog_18711_Content_71 = {
    Text = "No puedo recordar qué pasó en el medio, pero de alguna manera terminé aquí aturdido."
  },
  AvgDialog_18711_Content_72 = {
    Text = "Entonces escuché un ruido dentro... ¡No te preocupes, no miré ni una sola vez!"
  },
  AvgDialog_18711_Content_73 = {
    Text = "El viejo Freeman de repente se acercó y te guiñó un ojo de manera misteriosa.\nNo lograste esquivarlo a tiempo y captaste un fuerte olor penetrante a humo y alcohol."
  },
  AvgDialog_18711_Content_74 = {
    Text = "Mataste a ese Cazador de Calaveras, ¿verdad?"
  },
  AvgDialog_18711_Content_75 = {
    Text = "No es genial, pero es lo suficientemente cercano. Nadie interrumpirá tu sueño a partir de ahora."
  },
  AvgDialog_18711_Content_76 = {
    Text = "Te pinzas la nariz, das tres pasos atrás y asientes de manera superficial."
  },
  AvgDialog_18711_Content_77 = {Text = "Oh..."},
  AvgDialog_18711_Content_78 = {
    Text = "El viejo Freeman se frotó el cabello desordenado, un indicio de confusión destellando en sus ojos."
  },
  AvgDialog_18711_Content_79 = {
    Text = "Bastante bien, bastante bien..."
  },
  AvgDialog_18711_Content_8 = {Text = "..."},
  AvgDialog_18711_Content_80 = {
    Text = "Señor Freeman. A partir de ahora... nada de beber."
  },
  AvgDialog_18711_Content_81 = {
    Text = "¿Dejar de beber? No, no, no... Preferiría morir."
  },
  AvgDialog_18711_Content_82 = {
    Text = "Esta es una solicitud de un amigo. Ella se ha ido muy, muy lejos... pero aún se preocupa por ti."
  },
  AvgDialog_18711_Content_83 = {
    Text = "¿Amigos? Heh, no te engañes. El viejo Freeman no tiene amigos..."
  },
  AvgDialog_18711_Content_84 = {
    Text = "Te despidió de manera despectiva, murmurando mientras se alejaba tambaleándose."
  },
  AvgDialog_18711_Content_85 = {
    Text = "Él se ve tan abatido. Qué pena...\nNunca sabrá por qué se siente así."
  },
  AvgDialog_18711_Content_86 = {
    Text = "Es como si él no entendiera por qué está aquí."
  },
  AvgDialog_18711_Content_87 = {
    Text = "Esto debe ser lo que la señora Harriet había esperado."
  },
  AvgDialog_18711_Content_88 = {
    Text = "No le digas nada... Puede seguir bebiendo, cantando y flotando por la vida como lo hace ahora."
  },
  AvgDialog_18711_Content_89 = {
    Text = "De alguna manera, esto también es una especie de suerte. La vida de un humano es muy corta..."
  },
  AvgDialog_18711_Content_9 = {
    Text = "Narciso emitió un suave suspiro, sus ojos brillando con una tristeza no expresada."
  },
  AvgDialog_18711_Content_90 = {
    Text = "Observas alejarse al Viejo Freeman."
  },
  AvgDialog_18711_Content_91 = {
    Text = "Una figura encorvada tiembla en el viento sombrío, haciéndose cada vez más pequeña, cada vez más lejana..."
  },
  AvgDialog_18711_Content_92 = {
    Text = "Hasta ser completamente tragado por el horizonte distante."
  },
  AvgDialog_18711_Content_93 = {
    Text = "Entonces, ves un rayo tenue de amanecer atravesando la niebla, iluminando gradualmente el cielo."
  },
  AvgDialog_18711_Content_94 = {
    Text = "La lluvia ha cesado... Narciso."
  },
  AvgDialog_18712_Content_1 = {
    Text = "Himno de sombra"
  },
  AvgDialog_18712_Content_10 = {
    Text = "Dámelo... <Big:Devuélvemelo>!"
  },
  AvgDialog_18712_Content_11 = {
    Text = "Las tenues negras se extienden continuamente desde su cuello, absorbiendo codiciosamente las cabezas caídas en su cuerpo."
  },
  AvgDialog_18712_Content_12 = {
    Text = "Con cada calavera que devora, su tamaño aumenta aún más."
  },
  AvgDialog_18712_Content_13 = {
    Text = "Lo último que se encuentra ante ti es un montón masivo de carne apilada."
  },
  AvgDialog_18712_Content_14 = {
    Text = "<Bold:—¡!!!>"
  },
  AvgDialog_18712_Content_15 = {
    Text = "Estas cabezas... las he visto antes."
  },
  AvgDialog_18712_Content_16 = {
    Text = "Has visto algunos de ellos en los archivos que la policía te dio, en esas frías fotos alineadas de víctimas."
  },
  AvgDialog_18712_Content_17 = {
    Text = "Les has visto."
  },
  AvgDialog_18712_Content_18 = {
    Text = "Ahora entiendes, nunca hubo ninguna organización de Cazadores de Calaveras."
  },
  AvgDialog_18712_Content_19 = {
    Text = "<Yellow:Desde el principio, el Cazador de Cráneos siempre ha estado solo.>"
  },
  AvgDialog_18712_Content_2 = {
    Text = "¿Dama Daffodil...?!"
  },
  AvgDialog_18712_Content_20 = {
    Text = "<RedShake: No es suficiente...>"
  },
  AvgDialog_18712_Content_21 = {
    Text = "<RedShake: No es suficiente... no es suficiente...>"
  },
  AvgDialog_18712_Content_22 = {
    Text = "Un cuerpo hinchado incrustado con innumerables cabezas expresando dolor y llorando, subiendo y bajando con la suave grasa..."
  },
  AvgDialog_18712_Content_23 = {
    Text = "¡Qué olas de espíritu tan familiares...! ¿Podría ser el Millar de Espejos?"
  },
  AvgDialog_18712_Content_24 = {
    Text = "Es un poder que proviene de la misma fuente que el Mil Espejismo, por eso puedo sentir su ubicación."
  },
  AvgDialog_18712_Content_25 = {
    Text = "Ahora está completamente fuera de control y sigue creciendo.\nDebemos actuar rápidamente."
  },
  AvgDialog_18712_Content_26 = {
    Text = "Así que..."
  },
  AvgDialog_18712_Content_27 = {
    Text = "Daffodil de repente se inclinó, agarrando la Llave de Plata de tu pecho."
  },
  AvgDialog_18712_Content_28 = {
    Text = "¿Te gustaría asociarte conmigo, %player%?"
  },
  AvgDialog_18712_Content_29 = {
    Text = "Oh, ¿quieres unirte a mí?"
  },
  AvgDialog_18712_Content_3 = {
    Text = "Lo siento... Te dejé aquí deliberadamente para atraerlo. Debes estar culpándome en tu corazón, ¿verdad?"
  },
  AvgDialog_18712_Content_30 = {
    Text = "Después de todo este tiempo trabajando juntos, pensé que tendríamos algún entendimiento para ahora"
  },
  AvgDialog_18712_Content_31 = {
    Text = "¿O... no estás seguro de que puedes manejarme?"
  },
  AvgDialog_18712_Content_32 = {
    Text = "Heh... ¿Vamos a intentarlo?"
  },
  AvgDialog_18712_Content_33 = {
    Text = "Cierras los ojos y te concentras, instando a la Llave de Plata en tu pecho."
  },
  AvgDialog_18712_Content_34 = {
    Text = "Pronto, la llave plateada comenzó a emitir una vibración continua y débil, y el destello blanco frío rápidamente engulló toda la sala oscura."
  },
  AvgDialog_18712_Content_35 = {
    Text = "Sientes como si estuvieras en un inmenso mar de tiempo."
  },
  AvgDialog_18712_Content_36 = {
    Text = "Una energía extraña surge en tu pecho, un torrente cruzando dimensiones."
  },
  AvgDialog_18712_Content_37 = {
    Text = "A través del vasto mar del tiempo, el Narciso te observa en silencio.\nEn este momento, una expresión sutil y desconocida aparece en su rostro."
  },
  AvgDialog_18712_Content_38 = {
    Text = "Esa es una confianza absoluta e indiscutible, perfeccionada a lo largo de cientos de años a través de innumerables confrontaciones y batallas."
  },
  AvgDialog_18712_Content_39 = {
    Text = "Partamos, %player%. Estoy completamente preparado."
  },
  AvgDialog_18712_Content_4 = {Text = "..."},
  AvgDialog_18712_Content_5 = {
    Text = "Resolveremos esto una vez que salgamos."
  },
  AvgDialog_18712_Content_6 = {
    Text = "<Shake:Mi cabeza... Devuélvemela...>"
  },
  AvgDialog_18712_Content_7 = {
    Text = "\"Harriet\" desequilibró dos pasos hacia adelante, alcanzando inútilmente por encima de su cuello."
  },
  AvgDialog_18712_Content_8 = {
    Text = "Un golpe, dos golpes..."
  },
  AvgDialog_18712_Content_9 = {
    Text = "Al darse cuenta de que ya le habían cortado la cabeza, dejó escapar una serie de gritos agudos."
  },
  AvgDialog_18713_Content_1 = {
    Text = "Está lloviendo."
  },
  AvgDialog_18713_Content_10 = {
    Text = "Te limpias la lluvia de la cara apresuradamente y parpadeas, solo para darte cuenta de que alguien realmente te está hablando."
  },
  AvgDialog_18713_Content_11 = {
    Text = "Pensé que aquí ya no vivía nadie."
  },
  AvgDialog_18713_Content_12 = {
    Text = "La mayoría de la gente se ha mudado."
  },
  AvgDialog_18713_Content_13 = {
    Text = "Aquellos que estaban enfermos o eran ancianos eligieron quedarse, mientras que algunos salieron y luego regresaron..."
  },
  AvgDialog_18713_Content_14 = {
    Text = "No todos pueden adaptarse a la vida afuera."
  },
  AvgDialog_18713_Content_15 = {
    Text = "Ya veo. Pero no vi a nadie hace un momento."
  },
  AvgDialog_18713_Content_16 = {
    Text = "...Ellos odian tratar con forasteros."
  },
  AvgDialog_18713_Content_17 = {
    Text = "Miras a tu alrededor en las escasas y dilapidadas casas."
  },
  AvgDialog_18713_Content_18 = {
    Text = "A través de las ventanas pitch-black, se pueden ver vagamente miradas silenciosas, llenas de cautela y hostilidad."
  },
  AvgDialog_18713_Content_19 = {
    Text = "Hola, señora. ¿Puedo preguntarle—?"
  },
  AvgDialog_18713_Content_2 = {
    Text = "Caminas solo bajo la lluvia, el agua fría y húmeda empapando tu ropa y adheriéndose a tu piel."
  },
  AvgDialog_18713_Content_20 = {
    Text = "¿Has visto algo extraño?"
  },
  AvgDialog_18713_Content_21 = {
    Text = "¿Cosas extrañas...?"
  },
  AvgDialog_18713_Content_22 = {
    Text = "Uh... ya sea una persona o una bestia, se mueve extremadamente rápido."
  },
  AvgDialog_18713_Content_23 = {
    Text = "La mujer sacudió la cabeza."
  },
  AvgDialog_18713_Content_24 = {
    Text = "Ha pasado mucho tiempo desde que alguien vino aquí; incluso los buitres se niegan a acercarse."
  },
  AvgDialog_18713_Content_25 = {
    Text = "¿Has visto Narciso?"
  },
  AvgDialog_18713_Content_26 = {
    Text = "¿Has visto a una hermosa dama con un vestido largo púrpura?"
  },
  AvgDialog_18713_Content_27 = {
    Text = "La mujer sacudió la cabeza."
  },
  AvgDialog_18713_Content_28 = {
    Text = "Ha pasado mucho tiempo desde que alguien vino aquí; incluso los buitres se niegan a acercarse."
  },
  AvgDialog_18713_Content_29 = {
    Text = "<Big:¡Boom—>"
  },
  AvgDialog_18713_Content_3 = {
    Text = "Caminas a través de una casa abandonada tras otra, pasando junto a una tumba tras otra."
  },
  AvgDialog_18713_Content_30 = {
    Text = "La lluvia cae con más fuerza, volviendo todo gris."
  },
  AvgDialog_18713_Content_31 = {
    Text = "La figura de la mujer comienza a difuminarse y perder enfoque, y hasta su voz se vuelve cada vez más tenue..."
  },
  AvgDialog_18713_Content_32 = {
    Text = "Entra, {Male=sir,Female=miss}. Te vas a resfriar con esta lluvia tan fuerte..."
  },
  AvgDialog_18713_Content_33 = {Text = "..."},
  AvgDialog_18713_Content_34 = {
    Text = "Con placer."
  },
  AvgDialog_18713_Content_4 = {
    Text = "Dondequiera que vayan, solo hay cicatrices y desolación."
  },
  AvgDialog_18713_Content_5 = {
    Text = "Solo lluvia. Lluvia incesante y fría te acompaña todo el camino."
  },
  AvgDialog_18713_Content_6 = {
    Text = "{Male=señor,Female=señorita}..."
  },
  AvgDialog_18713_Content_7 = {
    Text = "Una anciana se encuentra frente a la cabaña, saludándote."
  },
  AvgDialog_18713_Content_8 = {
    Text = "Llevaba un vestido apagado, su rostro oculto en la grisácea lluvia, integrándose perfectamente con la casa deteriorada detrás de ella."
  },
  AvgDialog_18713_Content_9 = {
    Text = "{Male=Sir,Female=Miss}, pareces tener mucho frío... ¿Te gustaría pasar y sentarte?"
  },
  AvgDialog_18714_Content_1 = {
    Text = "Ruptura de tormenta"
  },
  AvgDialog_18714_Content_10 = {
    Text = "¿¡Una sola persona!?"
  },
  AvgDialog_18714_Content_11 = {
    Text = "Oh querido, te ves terrible. ¿Necesitas ayuda?"
  },
  AvgDialog_18714_Content_12 = {
    Text = "Te echas atrás. Tengo algo que preguntarte."
  },
  AvgDialog_18714_Content_13 = {
    Text = "Eso es realmente hiriente. ¿Qué, estoy emitiendo algún tipo de olor desagradable?"
  },
  AvgDialog_18714_Content_14 = {
    Text = "No sé... ¿Quizás el aroma de los muertos?"
  },
  AvgDialog_18714_Content_15 = {
    Text = "Beren Stock, Dwight Williams... ¿Te suenan esos nombres?"
  },
  AvgDialog_18714_Content_16 = {Text = "..."},
  AvgDialog_18714_Content_17 = {
    Text = "Veo, sospechas que soy el Cazador de Calaveras."
  },
  AvgDialog_18714_Content_18 = {
    Text = "Y tú sabes claramente los nombres de las víctimas del Cazador de Calaveras."
  },
  AvgDialog_18714_Content_19 = {Text = "..."},
  AvgDialog_18714_Content_2 = {
    Text = "Daffodil se acerca a ti con un aire de elegante despreocupación, como si estuviera aquí de vacaciones."
  },
  AvgDialog_18714_Content_20 = {
    Text = "Pensé que al pasar tiempo con Lai, podríamos construir un poco de confianza."
  },
  AvgDialog_18714_Content_21 = {
    Text = "El Cazador de Cráneos me robó un <Yellow:cabeza preciosa>, así que solo estoy llevando a cabo una pequeña investigación. Es tan simple como eso."
  },
  AvgDialog_18714_Content_22 = {
    Text = "¿De quién podría ser esta preciosa cabeza...?"
  },
  AvgDialog_18714_Content_23 = {Text = "..."},
  AvgDialog_18714_Content_24 = {
    Text = "Daffodil te sonríe. Siempre pone esta sonrisa cuando no quiere responder a las preguntas de los demás."
  },
  AvgDialog_18714_Content_25 = {
    Text = "Si recuerdo correctamente, siempre has tenido la costumbre de coleccionar cabezas. Renny está a menos de 15 millas de Rai en línea recta, lo que hace que el viaje de ida y vuelta sea bastante conveniente."
  },
  AvgDialog_18714_Content_26 = {
    Text = "Lo siento, solo colecciono cabezas, no las produzco."
  },
  AvgDialog_18714_Content_27 = {
    Text = "Hay una sutil diferencia entre ambas cosas... Creo que lo puedes entender, ¿nuestro inteligente Guardián?"
  },
  AvgDialog_18714_Content_28 = {
    Text = "Claro, lo entiendo.\nEntonces, ¿dónde estabas y qué hacías a las 8:15 anoche?"
  },
  AvgDialog_18714_Content_29 = {
    Text = "Déjame pensar... La tienda recibió un nuevo lote de sales de baño, así que las probé en la bañera."
  },
  AvgDialog_18714_Content_3 = {
    Text = "Eres tú...?"
  },
  AvgDialog_18714_Content_30 = {
    Text = "Bueno, ¿quieres escuchar los detalles de mi juicio?"
  },
  AvgDialog_18714_Content_31 = {
    Text = "¿Es así? Pero cuando te vi anoche, estabas de pie solo bajo la luz de la calle, sosteniendo una cabeza humana."
  },
  AvgDialog_18714_Content_32 = {
    Text = "No parece en absoluto sales de baño."
  },
  AvgDialog_18714_Content_33 = {Text = "..."},
  AvgDialog_18714_Content_34 = {
    Text = "¿Estás diciendo... que viste a alguien que se parece exactamente a mí anoche?"
  },
  AvgDialog_18714_Content_35 = {
    Text = "Recuerdas haber visto a Narciso anoche."
  },
  AvgDialog_18714_Content_36 = {
    Text = "Sin duda, sus apariencias son casi idénticas, pero su comportamiento y aura son muy diferentes."
  },
  AvgDialog_18714_Content_37 = {
    Text = "¿O más bien, vi <Yellow:you>, no a alguien que se parezca exactamente a ti?"
  },
  AvgDialog_18714_Content_38 = {
    Text = "Toda la evidencia desfavorable ahora apunta hacia ti, y tengo toda la razón para sospechar de ti."
  },
  AvgDialog_18714_Content_39 = {
    Text = "Hmm, tu sospecha es de hecho bien fundamentada."
  },
  AvgDialog_18714_Content_4 = {
    Text = "Oh querido, ¿alguien parece no estar dispuesto a verme?"
  },
  AvgDialog_18714_Content_40 = {Text = "..."},
  AvgDialog_18714_Content_41 = {
    Text = "¿No tienes nada que explicar?"
  },
  AvgDialog_18714_Content_42 = {
    Text = "Narciso te miró con sorpresa, como si hubieras hecho una pregunta ridícula."
  },
  AvgDialog_18714_Content_43 = {
    Text = "¿Explicar? Lo siento, no necesito explicar nada a nadie."
  },
  AvgDialog_18714_Content_44 = {
    Text = "Ella avanza graciosamente hacia ti."
  },
  AvgDialog_18714_Content_45 = {
    Text = "La amplia falda susurra las hojas muertas, mientras el humo púrpura se enrolla como tentáculos alrededor."
  },
  AvgDialog_18714_Content_46 = {
    Text = "En el siguiente segundo, ella desapareció en el aire ante tus ojos."
  },
  AvgDialog_18714_Content_47 = {
    Text = "Las nubes bajas bloquean completamente la luz del sol, haciéndote sentir como si estuvieras en un sueño gris, con los susurros de Narciso resonando en tus oídos—"
  },
  AvgDialog_18714_Content_48 = {
    Text = "Desde que piensas que soy el \"Cazador de Calaveras\"... ¿qué sigue? ¿Qué planeas hacerme?"
  },
  AvgDialog_18714_Content_49 = {
    Text = "¿O más bien... qué puedes hacerme?"
  },
  AvgDialog_18714_Content_5 = {
    Text = "El desolador viento otoñal sopla desde detrás de ti. Te vuelves, pero no hay nada frente a ti; el Viejo Freeman ha desaparecido hace mucho tiempo."
  },
  AvgDialog_18714_Content_6 = {
    Text = "Recordando todo lo que acaba de suceder, fue como una pesadilla."
  },
  AvgDialog_18714_Content_7 = {
    Text = "¿Señor Freeman...?"
  },
  AvgDialog_18714_Content_8 = {
    Text = "Hmm, ¿trajiste un compañero? ¿Es esa chica que siempre se ve tan seria?"
  },
  AvgDialog_18714_Content_9 = {
    Text = "Justo ahora, estabas de pie aquí solo, completamente quieto, como si estuvieras poseso."
  },
  AvgDialog_18715_Content_1 = {
    Text = "Me rindo, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_18715_Content_10 = {
    Text = "Te lanzas a un mar de esencia primordial gris."
  },
  AvgDialog_18715_Content_11 = {
    Text = "La luz del día pica tus ojos, revelando una vasta extensión de océano gris."
  },
  AvgDialog_18715_Content_12 = {
    Text = "Las olas grises enérgicas brillan con una luz centelleante, salpicadas de innumerables manchas negras."
  },
  AvgDialog_18715_Content_13 = {
    Text = "A medida que tu visión se ajusta gradualmente, te das cuenta de que no es una mancha negra, sino solo un cráneo."
  },
  AvgDialog_18715_Content_14 = {
    Text = "Incontables cabezas están sumergidas en el mar gris, subiendo y bajando con las olas. Gritan y lamentan, ahogándose en un inmenso pesar y miedo."
  },
  AvgDialog_18715_Content_15 = {
    Text = "<Change>Crystals, crystals..."
  },
  AvgDialog_18715_Content_16 = {
    Text = "<Shake:¡No toques ese librito, no lo toques...>"
  },
  AvgDialog_18715_Content_17 = {
    Text = "<Shake:San Pedro, déjame regresar, déjame regresar...>"
  },
  AvgDialog_18715_Content_18 = {
    Text = "Incontables voces gritan en tus oídos, obligándote a cubrirlos, como si miles de agujas estuvieran perforando tu mente."
  },
  AvgDialog_18715_Content_19 = {
    Text = "Hmm... <Big:¡Aaah...!!>"
  },
  AvgDialog_18715_Content_2 = {
    Text = "Dado que no puedo soportar ver que te lastiman, continuar esta pelea sería solo una pérdida de tiempo para todos."
  },
  AvgDialog_18715_Content_20 = {
    Text = "Sangre caliente fluye de tus oídos y fosas nasales, creando enormes olas en el momento en que toca el agua."
  },
  AvgDialog_18715_Content_21 = {
    Text = "La marea arremete con ira y miedo, llevando innumerables cabezas flotando en sus olas, corriendo hacia ti."
  },
  AvgDialog_18715_Content_22 = {
    Text = "<Change>No, no..."
  },
  AvgDialog_18715_Content_23 = {
    Text = "<Shake:Intrusos... ¡Intrusos!!>"
  },
  AvgDialog_18715_Content_24 = {
    Text = "No tienes salida. Solo cierra los ojos."
  },
  AvgDialog_18715_Content_25 = {Text = "Ngh...!"},
  AvgDialog_18715_Content_26 = {
    Text = "Tos... Tos..."
  },
  AvgDialog_18715_Content_27 = {
    Text = "Narciso se llevó la mano a la frente y frunció el ceño al mirarte."
  },
  AvgDialog_18715_Content_28 = {
    Text = "¿Fuera tan pronto...? Pensé que podría tenerte atrapado durante al menos un día entero."
  },
  AvgDialog_18715_Content_29 = {
    Text = "Parece que estamos destinados a estar unidos, ¿no?"
  },
  AvgDialog_18715_Content_3 = {
    Text = "Dadas las diferencias irreconciliables entre nosotros, te sugiero que dejes de molestarme."
  },
  AvgDialog_18715_Content_30 = {
    Text = "Cabeza... duele..."
  },
  AvgDialog_18715_Content_31 = {
    Text = "¿Qué fue eso justo ahora...? ¿Qué tipo de cosa era...?"
  },
  AvgDialog_18715_Content_32 = {
    Text = "Este es mi espacio ultra-dimensional. Lo he nombrado <Yellow:Mil Espejos>.\n¿Qué piensas? ¿No es fascinante?"
  },
  AvgDialog_18715_Content_33 = {Text = "..."},
  AvgDialog_18715_Content_34 = {
    Text = "%player%, estás teniendo un sangrado nasal. Espera, incluso tus oídos están sangrando..."
  },
  AvgDialog_18715_Content_35 = {
    Text = "<Shake:Estoy bien... Mantente alejado...>"
  },
  AvgDialog_18715_Content_36 = {
    Text = "No es prudente actuar duro ahora; apenas puedes mantenerte en pie."
  },
  AvgDialog_18715_Content_37 = {
    Text = "*Tose tose*... no te acerques más..."
  },
  AvgDialog_18715_Content_38 = {
    Text = "Tu visión se vuelve negra y colapsas pesadamente sobre el suelo."
  },
  AvgDialog_18715_Content_39 = {
    Text = "En la oscuridad, parece que oyes una voz familiar."
  },
  AvgDialog_18715_Content_4 = {
    Text = "Daffodil, con una expresión fría, trazó rápidamente una serie de runas púrpuras brillantes en el aire."
  },
  AvgDialog_18715_Content_40 = {
    Text = "Suave, indiferente, envuelta en un leve zumbido eléctrico, apareciendo distante y vaga."
  },
  AvgDialog_18715_Content_41 = {
    Text = "%player%, ¿puedes oírme ahora...<Red:Dirección de investigación incorrecta>..."
  },
  AvgDialog_18715_Content_42 = {
    Text = "El Cazador de Cráneos ataca de nuevo...\nTres víctimas, todas con sus cabezas tomadas..."
  },
  AvgDialog_18715_Content_43 = {
    Text = "Solo hace un momento..."
  },
  AvgDialog_18715_Content_5 = {
    Text = "<Change>Mil Espejismos, activar."
  },
  AvgDialog_18715_Content_6 = {
    Text = "El mundo ante tus ojos se transforma de repente en reflejos fragmentados en el agua, parpadeando suavemente frente a ti."
  },
  AvgDialog_18715_Content_7 = {
    Text = "Instintivamente extiendes la mano, pero te arrastran hacia un profundo vórtice en el momento en que tocas los Fragmentos de Sombra."
  },
  AvgDialog_18715_Content_8 = {
    Text = "¡Aaaah...!!"
  },
  AvgDialog_18715_Content_9 = {Text = "Eso es..."},
  AvgDialog_18716_Content_1 = {
    Text = "¡Aaahh—!!"
  },
  AvgDialog_18716_Content_10 = {
    Text = "Los hilos se contrajeron de repente, destrozando la puerta del dormitorio mientras innumerables cabezas rodaban hacia afuera."
  },
  AvgDialog_18716_Content_11 = {
    Text = "Cuando recuperaste el sentido, una cabeza algo familiar ya estaba unida al cuello vacío de Harriet."
  },
  AvgDialog_18716_Content_12 = {
    Text = "Esta cabeza... Esta cara..."
  },
  AvgDialog_18716_Content_13 = {
    Text = "Beren Stock, la víctima anterior... ¿Qué está pasando?!"
  },
  AvgDialog_18716_Content_14 = {
    Text = "El cráneo pálido emite un sonido de crujido rígido y finalmente abre sus ojos desenfocados."
  },
  AvgDialog_18716_Content_15 = {
    Text = "La renacida \"Harriet\" sonríe y te carga con una velocidad increíble."
  },
  AvgDialog_18716_Content_16 = {
    Text = "¡Aaaahhh—!!"
  },
  AvgDialog_18716_Content_18 = {
    Text = "La fría hoja corta sin piedad a través de la oscuridad."
  },
  AvgDialog_18716_Content_19 = {
    Text = "En el siguiente segundo, la cabeza de \"Harriet\" voló elegantemente y rodó junto a su amplia falda."
  },
  AvgDialog_18716_Content_2 = {
    Text = "Harriet colapsó en el suelo, emitiendo un grito penetrante desde lo profundo de su garganta."
  },
  AvgDialog_18716_Content_20 = {
    Text = "Uff... Parece que no estoy demasiado tarde."
  },
  AvgDialog_18716_Content_21 = {
    Text = "Te ves animado, %player%."
  },
  AvgDialog_18716_Content_3 = {
    Text = "Te acercas y la agarras del collar."
  },
  AvgDialog_18716_Content_4 = {
    Text = "Habla, ¿quiénes son tus cómplices y dónde están? ¿Es Old Freeman uno de ellos?"
  },
  AvgDialog_18716_Content_5 = {
    Text = "Freeman...? Je... Jejeje..."
  },
  AvgDialog_18716_Content_6 = {
    Text = "Su rostro se contorsionó violentamente, con innumerables pápulas hinchándose bajo su piel delgada, al borde de estallar."
  },
  AvgDialog_18716_Content_7 = {
    Text = "¡Zzzzap—!!"
  },
  AvgDialog_18716_Content_8 = {
    Text = "La cabeza de Harriet fue volada y convertida en una pulpa caliente."
  },
  AvgDialog_18716_Content_9 = {
    Text = "Su cuello se retorcía continuamente, con D-baba mezclado con sangre formando hilos delgados que se extendían hacia el techo, las paredes y el suelo..."
  },
  AvgDialog_18717_Content_1 = {
    Text = "Musa felina"
  },
  AvgDialog_18717_Content_10 = {
    Text = "Fue una experiencia bastante interesante."
  },
  AvgDialog_18717_Content_11 = {
    Text = "Los recuerdos originalmente tristes, reinterpretados a través de imágenes, adquirieron inesperadamente un encanto cómico."
  },
  AvgDialog_18717_Content_12 = {
    Text = "Escuché que más tarde formaste un club de cine llamado <Yellow:\"Sociedad de Poesía Philin\">"
  },
  AvgDialog_18717_Content_13 = {
    Text = "Sí... A veces ayudo a escribir guiones, aunque siempre he sido un terrible dramaturgo."
  },
  AvgDialog_18717_Content_14 = {
    Text = "¡Fue la Dama Narciso quien me ayudó a avanzar desde el pasado, sin importar sus verdaderas intenciones!"
  },
  AvgDialog_18717_Content_15 = {
    Text = "Siempre he estado agradecido con la Dama Narciso."
  },
  AvgDialog_18717_Content_16 = {
    Text = "Veo, así que eso fue lo que ella te dijo."
  },
  AvgDialog_18717_Content_17 = {
    Text = "También estoy profundamente agradecido a la Señorita Horla. Fue un encuentro hermoso."
  },
  AvgDialog_18717_Content_18 = {
    Text = "Así que, por el bien de la señorita Horla, confiaré en ti esta vez."
  },
  AvgDialog_18717_Content_19 = {
    Text = "<LightGray:Además, las personas enviadas por la escuela ya están en camino.>"
  },
  AvgDialog_18717_Content_2 = {
    Text = "2:15, Calle Kenting"
  },
  AvgDialog_18717_Content_20 = {
    Text = "<LightGray:Si me demoro demasiado, no se quedarán sentados...>"
  },
  AvgDialog_18717_Content_21 = {
    Text = "Entonces pongámonos en marcha, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_18717_Content_22 = {
    Text = "Narciso asintió felizmente, extendiendo su mano hacia ti."
  },
  AvgDialog_18717_Content_23 = {Text = "..."},
  AvgDialog_18717_Content_24 = {
    Text = "Con cuidado, sostienes la mano de Narciso. Contrario a las expectativas, su mano es suave y cálida."
  },
  AvgDialog_18717_Content_25 = {
    Text = "Aguanta firme, Guardián."
  },
  AvgDialog_18717_Content_26 = {
    Text = "Tu estabilidad vacila, y te arrastran a una dimensión profunda."
  },
  AvgDialog_18717_Content_27 = {
    Text = "Bienvenido de nuevo a mi \"Mil Espejismos.\""
  },
  AvgDialog_18717_Content_28 = {
    Text = "Aquí está esa familiar Mar de Esencia Primordial otra vez, con cabezas aún bobando junto a las olas."
  },
  AvgDialog_18717_Content_29 = {
    Text = "A diferencia de la última vez, las cabezas parecen mucho más tranquilas ahora. Sus cuencas vacías se vuelven todas hacia ti, pero continúan susurrando entre ellas."
  },
  AvgDialog_18717_Content_3 = {
    Text = "No esperaba que aceptaras venir conmigo tan fácilmente. ¿No estás preocupado de que pueda llevarte a algún lugar extraño?"
  },
  AvgDialog_18717_Content_30 = {
    Text = "Daffodil agitó su mano ligeramente, y dos cabezas temblaron mientras flotaban a la altura de sus ojos."
  },
  AvgDialog_18717_Content_31 = {
    Text = "<Change>Mi maestro..."
  },
  AvgDialog_18717_Content_32 = {
    Text = "<Change> Hace mucho que no nos vemos..."
  },
  AvgDialog_18717_Content_33 = {
    Text = "<Change>Ayúdame a encontrar a alguien..."
  },
  AvgDialog_18717_Content_34 = {
    Text = "Narciso y el cráneo susurran en un idioma que no puedes entender. Lo que sea que discutieron, la hizo reír felizmente."
  },
  AvgDialog_18717_Content_35 = {
    Text = "Nunca la has visto sonreír así; se siente fuera de lugar."
  },
  AvgDialog_18717_Content_36 = {
    Text = "En cambio, atravesó cientos de años y aterrizó en un rincón de una historia desconocida para ti."
  },
  AvgDialog_18717_Content_37 = {Text = "..."},
  AvgDialog_18717_Content_38 = {
    Text = "¿Qué pasa? ¿Hay algo en mi cara?"
  },
  AvgDialog_18717_Content_39 = {
    Text = "Mirarás con deleite."
  },
  AvgDialog_18717_Content_4 = {
    Text = "Entonces, ¿me llevarás a lugares extraños?"
  },
  AvgDialog_18717_Content_40 = {
    Text = "Estas son todas mis colecciones apreciadas."
  },
  AvgDialog_18717_Content_41 = {
    Text = "Ha pasado mucho tiempo desde que regresé por última vez. Les echo mucho de menos."
  },
  AvgDialog_18717_Content_42 = {
    Text = "¿De qué estás hablando?"
  },
  AvgDialog_18717_Content_43 = {
    Text = "Pasado, presente y futuro."
  },
  AvgDialog_18717_Content_44 = {
    Text = "Cada una de estas cabezas es una <Yellow:proyección de la realidad>. Su visión y memoria trascienden las dimensiones del tiempo y el espacio, ayudándome a descubrir muchas cosas inesperadas."
  },
  AvgDialog_18717_Content_45 = {
    Text = "Así que por eso tu tienda tiene tantos objetos extraños e inusuales...?"
  },
  AvgDialog_18717_Content_46 = {
    Text = "Narciso parpadeó, asintiendo tácitamente con tu suposición."
  },
  AvgDialog_18717_Content_47 = {
    Text = "¿De dónde vinieron todas estas cabezas?"
  },
  AvgDialog_18717_Content_48 = {
    Text = "Intercambio, regalo y un poco de suerte.\nPor supuesto, también tomé algo para mí."
  },
  AvgDialog_18717_Content_49 = {
    Text = "Se dice que has cazado hasta @1 cabezas—este es solo el número oficialmente registrado."
  },
  AvgDialog_18717_Content_5 = {
    Text = "Por supuesto."
  },
  AvgDialog_18717_Content_50 = {
    Text = "Narciso tomó tranquilamente una profunda calada de su larga pipa, luego exhaló una bocanada de humo blanco."
  },
  AvgDialog_18717_Content_51 = {
    Text = "Lamento decepcionarte, Guardián {Male=Mr.,Female=Miss}, pero los reproches morales no me afectan."
  },
  AvgDialog_18717_Content_52 = {
    Text = "Las reglas creadas por los humanos no se aplican a nosotros. Lo que ves ahora soy yo, con ojos y una nariz como la tuya..."
  },
  AvgDialog_18717_Content_53 = {
    Text = "Daffodil recogió la Llave de Plata de tu pecho, trazando suavemente sus intrincados patrones."
  },
  AvgDialog_18717_Content_54 = {
    Text = "Zumbidos y vibraciones caóticas llenan su pecho, chocando ferozmente como una guerra silenciosa."
  },
  AvgDialog_18717_Content_55 = {
    Text = "¿Lo sientes? No somos humanos. Somos \"bestias,\" o como algunos nos llamarían..."
  },
  AvgDialog_18717_Content_56 = {
    Text = "Somos <Yellow:seres superiores>."
  },
  AvgDialog_18717_Content_57 = {
    Text = "Toleramos a los humanos ignorantes, seguimos reglas cambiantes, obedecemos enlaces frágiles, todo por miedo..."
  },
  AvgDialog_18717_Content_58 = {
    Text = "Ella acaricia suavemente tu rostro."
  },
  AvgDialog_18717_Content_59 = {
    Text = "Y una promesa."
  },
  AvgDialog_18717_Content_6 = {Text = "..."},
  AvgDialog_18717_Content_60 = {Text = "..."},
  AvgDialog_18717_Content_61 = {
    Text = "Así que te convertiste en uno de los pocos Despertadores registrados sin ningún Enlace."
  },
  AvgDialog_18717_Content_62 = {
    Text = "Nadie nace para disfrutar ser controlado; la mayoría de las criaturas anhelan inherentemente la libertad."
  },
  AvgDialog_18717_Content_63 = {
    Text = "Personalmente, no desecho lo que se llama \"Enlace\"... Siempre que sea mutuamente beneficioso, ¿por qué preocuparse por las apariencias?"
  },
  AvgDialog_18717_Content_64 = {
    Text = "El problema podría no estar conmigo.\nNadie se conecta conmigo porque no están calificados. ¿Entendido?"
  },
  AvgDialog_18717_Content_65 = {Text = "Er..."},
  AvgDialog_18717_Content_66 = {
    Text = "¿Qué pasa conmigo? ¿Soy también uno de esos \"no calificados\"...?"
  },
  AvgDialog_18717_Content_67 = {
    Text = "Narciso estalló en risa, pero se atragantó con el humo y no pudo evitar toser varias veces."
  },
  AvgDialog_18717_Content_68 = {
    Text = "No te preocupes, niño... Pronto conocerás la respuesta."
  },
  AvgDialog_18717_Content_69 = {
    Text = "<LightGray: Otra respuesta ambigua...>"
  },
  AvgDialog_18717_Content_7 = {
    Text = "En realidad... la señorita Horla me habló de su primer encuentro esta tarde. Ella dijo—"
  },
  AvgDialog_18717_Content_70 = {
    Text = "¡Ups, podría haber dicho un poco demasiado!"
  },
  AvgDialog_18717_Content_71 = {
    Text = "Daffodil levantó su mano y tocó cada frente, haciendo que floten obedientemente."
  },
  AvgDialog_18717_Content_72 = {
    Text = "<Change>Gracias a todos."
  },
  AvgDialog_18717_Content_73 = {
    Text = "Está bien. Vamos, Guardián."
  },
  AvgDialog_18717_Content_74 = {
    Text = "Ya sé la ubicación del Cazador de Cráneos."
  },
  AvgDialog_18717_Content_8 = {
    Text = "Después me enteré de que ella había convertido ese recuerdo en algo llamado \"película.\""
  },
  AvgDialog_18717_Content_9 = {
    Text = "Me senté en la audiencia y vi la primera película de mi vida."
  },
  AvgDialog_18718_Content_1 = {
    Text = "Una Reunión Solitaria"
  },
  AvgDialog_18718_Content_10 = {
    Text = "Este es mi hogar.\nNo tengo otro lugar al que ir aparte de aquí."
  },
  AvgDialog_18718_Content_11 = {
    Text = "Para personas como nosotros del campo, da igual a dónde vayamos."
  },
  AvgDialog_18718_Content_12 = {
    Text = "La Dama Harriet..."
  },
  AvgDialog_18718_Content_13 = {
    Text = "La atmósfera dentro de la casa se volvió algo pesada."
  },
  AvgDialog_18718_Content_14 = {
    Text = "La lluvia aún cae suavemente mientras tú y ella miran la interminable cortina de lluvia."
  },
  AvgDialog_18718_Content_15 = {
    Text = "El exterior está envuelto en una niebla gris, con vapor de agua envolviéndote fuertemente, haciendo parecer que eres la única vida que queda entre cielo y tierra."
  },
  AvgDialog_18718_Content_16 = {
    Text = "<LightGray:¿Dónde está la Dama del narciso ahora...>"
  },
  AvgDialog_18718_Content_17 = {
    Text = "Espera un momento, {Male=sir,Female=miss}. Voy a preparar un poco de té caliente en la cocina."
  },
  AvgDialog_18718_Content_18 = {
    Text = "Aunque aquí es humilde, aún puedo ofrecerte una taza de té."
  },
  AvgDialog_18718_Content_19 = {
    Text = "La Sra. Harriet arrastró sus pasos lentos hacia la cocina."
  },
  AvgDialog_18718_Content_2 = {
    Text = "Sigues a la mujer dentro de la cabaña de madera.\nEl interior es muy simple y captas un olor a madera húmeda."
  },
  AvgDialog_18718_Content_20 = {
    Text = "Hasta que su silueta fue tragada por las profundas sombras del corredor, finalmente volviste a tus sentidos."
  },
  AvgDialog_18718_Content_21 = {
    Text = "Parece que tardará un tiempo antes de que pare la lluvia. Vamos a echar un vistazo."
  },
  AvgDialog_18718_Content_3 = {
    Text = "La mujer se inclinó lentamente, recogió unos troncos de leña de la esquina y los arrojó al pequeño fogón oscuro."
  },
  AvgDialog_18718_Content_4 = {
    Text = "Pon tus manos aquí, caliéntalas un poco más, y no sentirás frío."
  },
  AvgDialog_18718_Content_5 = {
    Text = "Muchas gracias..."
  },
  AvgDialog_18718_Content_6 = {
    Text = "Mi nombre es Harriet: @1, {Male=sir,Female=miss}. Puedes llamarme Harriet."
  },
  AvgDialog_18718_Content_7 = {
    Text = "Claro, Sra. Harriet. Para ser honesto, tengo curiosidad—¿por qué te quedas aquí?"
  },
  AvgDialog_18718_Content_8 = {
    Text = "Esta área no parece muy habitable."
  },
  AvgDialog_18718_Content_9 = {
    Text = "La Sra. Harriet se agachó, jugueteando con la madera para el fuego. Las llamas parpadeantes danzaban en su rostro demacrado y cansado."
  },
  AvgDialog_18719_Content_1 = {
    Text = "Reunión de caza de cráneos"
  },
  AvgDialog_18719_Content_10 = {
    Text = "Anoche, no lograste alcanzar a Narciso y solo pudiste seguir la dirección proporcionada por Ramona a la residencia de Horla."
  },
  AvgDialog_18719_Content_11 = {
    Text = "B-Buenos días, señorita Horla."
  },
  AvgDialog_18719_Content_12 = {
    Text = "Buenos días, {Male=Mr.,Female=Miss} %player%."
  },
  AvgDialog_18719_Content_13 = {Text = "..."},
  AvgDialog_18719_Content_14 = {Text = "..."},
  AvgDialog_18719_Content_15 = {
    Text = "Un silencio incómodo llena el aire. Te das cuenta de que este Despertador no parece ser muy bueno en socializar."
  },
  AvgDialog_18719_Content_16 = {
    Text = "Señorita Horla, estoy aquí respecto al evento del Cazador de Cráneos.\nDado que has vivido aquí durante mucho tiempo, ¿tienes alguna pista o información?"
  },
  AvgDialog_18719_Content_17 = {
    Text = "\"Cazador de Calaveras\"... Por favor, espera un momento."
  },
  AvgDialog_18719_Content_18 = {
    Text = "Horla se volvió y comenzó a buscar en la alta estantería."
  },
  AvgDialog_18719_Content_19 = {
    Text = "¡Lo encontré! *Tos, tos...*"
  },
  AvgDialog_18719_Content_2 = {
    Text = "¡Daffodil!"
  },
  AvgDialog_18719_Content_20 = {
    Text = "Horla apartó el polvo que flotaba y colocó el cuaderno amarillento en tu mano."
  },
  AvgDialog_18719_Content_21 = {
    Text = "Hace un mes, la señorita Muñeca solicitó mi ayuda."
  },
  AvgDialog_18719_Content_22 = {
    Text = "No tengo habilidades particulares, pero he documentado todos los casos recientes. Con suerte, esto será de ayuda."
  },
  AvgDialog_18719_Content_23 = {
    Text = "Abres el cuaderno y, con una escritura elegante, se registra la hora y el lugar de descubrimiento de cada caso, incluso incluyendo bocetos de los cuerpos y escenas del crimen."
  },
  AvgDialog_18719_Content_24 = {
    Text = "<Shake:Lo siento, mis habilidades de dibujo son bastante pobres. Simplemente puedes ignorarlo...>"
  },
  AvgDialog_18719_Content_25 = {
    Text = "No, es muy impresionante.\nGracias, Señorita Horla. Esta nota es crucial para nosotros."
  },
  AvgDialog_18719_Content_26 = {
    Text = "No importa qué, me alegra ayudar. Esas pobres personas..."
  },
  AvgDialog_18719_Content_27 = {
    Text = "Horla soltó un suave suspiro y se volvió a mirar el sombrío cielo afuera."
  },
  AvgDialog_18719_Content_28 = {
    Text = "El Pueblo Lluvioso (Lluvioso) es un lugar donde llueve todo el año. Sin embargo, después de la lluvia, lo que a menudo enfrenta no es una cosecha abundante sino inundaciones y plagas interminables."
  },
  AvgDialog_18719_Content_29 = {
    Text = "Los jóvenes trabajan en grandes ciudades como Londinium, dejando solo a los ancianos y a los niños."
  },
  AvgDialog_18719_Content_3 = {
    Text = "Huh... ¿Dónde es este lugar?"
  },
  AvgDialog_18719_Content_30 = {
    Text = "Ahora, incluso los ancianos empiezan a irse uno por uno..."
  },
  AvgDialog_18719_Content_31 = {
    Text = "He asistido a algunos funerales locales. Cada vez que un ser querido fallece, los Reenianos cantan una canción antigua..."
  },
  AvgDialog_18719_Content_32 = {
    Text = "Horla comenzó a tararear suavemente, y la melodía melancólica pronto se unió a palabras tan oscuras como la tinta."
  },
  AvgDialog_18719_Content_33 = {
    Text = [[
<RedItalic:Escribimos con sangre como pluma y barro como papel.>
<RedItalic:Inscribimos tristeza y miedo con cuerpos empapados de lluvia...>]]
  },
  AvgDialog_18719_Content_34 = {
    Text = "Estas palabras fluyeron lentamente alrededor de Horla, luego formaron una carta amarillenta que la envolvía."
  },
  AvgDialog_18719_Content_35 = {
    Text = "Ella dejó escapar un suave suspiro, con lágrimas brillando en sus ojos."
  },
  AvgDialog_18719_Content_36 = {
    Text = "¿No es todo lo que está pasando ahora el dolor que los Renier escribieron con sus cuerpos empapados de lluvia...?"
  },
  AvgDialog_18719_Content_37 = {
    Text = "El aire está lleno de una silenciosa y espesa sensación de depresión, que casi te sofoca."
  },
  AvgDialog_18719_Content_38 = {
    Text = "<Shake:Cof, señorita Horla...>"
  },
  AvgDialog_18719_Content_39 = {Text = "..."},
  AvgDialog_18719_Content_4 = {
    Text = "El alegre trino de los pájaros te regresa a la realidad desde tus sueños."
  },
  AvgDialog_18719_Content_40 = {
    Text = "¡Ah! Lo siento, lo hice de nuevo..."
  },
  AvgDialog_18719_Content_41 = {
    Text = "Horla volvió en sí y tomó dos respiraciones profundas."
  },
  AvgDialog_18719_Content_42 = {
    Text = "Las emociones opresivas finalmente se disipan, y el peso pesado en tu pecho se aligera significativamente."
  },
  AvgDialog_18719_Content_43 = {Text = "..."},
  AvgDialog_18719_Content_44 = {Text = "..."},
  AvgDialog_18719_Content_45 = {
    Text = "Ah, cierto, cierto."
  },
  AvgDialog_18719_Content_46 = {
    Text = "Preparé una olla de té de rosas usando pétalos recién recogidos. ¿Te gustaría unirte a mí para probarlo?"
  },
  AvgDialog_18719_Content_47 = {
    Text = "En media hora"
  },
  AvgDialog_18719_Content_48 = {
    Text = "En una mano, sostienes una taza de porcelana de hueso llena de té de rosa, mientras que con la otra, hojeas las notas de Horla, buscando un posible avance."
  },
  AvgDialog_18719_Content_49 = {
    Text = "¿Dónde están las personas de la estación de policía?"
  },
  AvgDialog_18719_Content_5 = {
    Text = "Miras la habitación limpia y sencilla con confusión, luego levantas la manta y tomas un sorbo."
  },
  AvgDialog_18719_Content_50 = {
    Text = "En la calle Norwich, el lugar por donde pasaste anoche."
  },
  AvgDialog_18719_Content_51 = {Text = "..."},
  AvgDialog_18719_Content_52 = {
    Text = "Lluvia. Sangre. Narciso.\nRecordando el encuentro de anoche, no puedes decir si fue un sueño o una realidad."
  },
  AvgDialog_18719_Content_53 = {
    Text = "Te suenas débil... ¿No descansaste bien anoche?"
  },
  AvgDialog_18719_Content_54 = {
    Text = "No, es solo..."
  },
  AvgDialog_18719_Content_55 = {
    Text = "Sacudiste la cabeza, tratando de aclarar los pensamientos confusos de tu mente."
  },
  AvgDialog_18719_Content_56 = {Text = "..."},
  AvgDialog_18719_Content_57 = {
    Text = "La investigación en la Ciudad Lai concluyó hace apenas dos días, y tus heridas aún no han sanado por completo."
  },
  AvgDialog_18719_Content_58 = {
    Text = "Sigh, no se puede evitar que los otros Investigadores también estén ocupados, ¿verdad?"
  },
  AvgDialog_18719_Content_59 = {
    Text = "En este punto, cerremos este caso rápidamente. Quiero tomarme unas vacaciones."
  },
  AvgDialog_18719_Content_6 = {
    Text = "Bien. Seco y suave, sin olor a lluvia ni a sangre."
  },
  AvgDialog_18719_Content_60 = {
    Text = "Eh, esto es..."
  },
  AvgDialog_18719_Content_61 = {
    Text = "El sonido de pasar páginas se detuvo abruptamente."
  },
  AvgDialog_18719_Content_62 = {
    Text = "Te concentras en la página congelada, comenzando a formular tu próximo plan de investigación"
  },
  AvgDialog_18719_Content_63 = {
    Text = "Ramona... Antes de reunirme con el detective, quiero ir a algún lugar primero."
  },
  AvgDialog_18719_Content_7 = {
    Text = "Buenos días, {Male=Mr.,Female=Miss} %player%. Bienvenido a mi humilde morada..."
  },
  AvgDialog_18719_Content_8 = {
    Text = "¡¿Señorita Horla?!"
  },
  AvgDialog_18719_Content_9 = {
    Text = "La memoria comienza a recuperarse gradualmente."
  },
  AvgDialog_18720_Content_1 = {
    Text = "11:00, Cementerio de Highgate"
  },
  AvgDialog_18720_Content_10 = {
    Text = "No esperes demasiado de la experiencia de los detectives en áreas remotas."
  },
  AvgDialog_18720_Content_11 = {
    Text = "...Tiene sentido."
  },
  AvgDialog_18720_Content_12 = {
    Text = "Sacas tu lupa y continúas observando el esqueleto."
  },
  AvgDialog_18720_Content_13 = {
    Text = "Hay un <Red:corte irregular> en el hueso del cuello..."
  },
  AvgDialog_18720_Content_14 = {
    Text = "Sin embargo, está bastante desordenado con numerosos cortes superpuestos, completamente diferente de lo que vimos en las fotos antes."
  },
  AvgDialog_18720_Content_15 = {
    Text = "¿Aún bastante inexperto, primera vez cometiendo un crimen?"
  },
  AvgDialog_18720_Content_16 = {
    Text = "Comienza la investigación centrada en el Templo de los Entierros.\nLos novatos inexpertos normalmente no se aventuran lejos de casa durante su primer delito."
  },
  AvgDialog_18720_Content_17 = {
    Text = "¡Entendido! Estoy seguro esta vez; ¡el culpable será atrapado pronto!"
  },
  AvgDialog_18720_Content_18 = {
    Text = "¿Asesino? ¿Cómo te atreves a asumir, *hic*, que solo hay un asesino?"
  },
  AvgDialog_18720_Content_19 = {
    Text = "De las profundidades del denso bosque emergió un anciano, apestando a alcohol y con mejillas sonrojadas."
  },
  AvgDialog_18720_Content_2 = {
    Text = "Caminas solo a través de los desolados montículos de entierro."
  },
  AvgDialog_18720_Content_20 = {
    Text = "Lo siento, no quise escuchar tu monólogo."
  },
  AvgDialog_18720_Content_21 = {
    Text = "Soy el cuidador de este cementerio. Puedes llamarme... eh, <Blue:Old Freeman>."
  },
  AvgDialog_18720_Content_22 = {
    Text = "Buenas tardes, Sr. Freeman.\n¿Acabas de insinuar que hay más de un asesino?"
  },
  AvgDialog_18720_Content_23 = {
    Text = "El viejo Freeman agarró la botella y se la embucha, su gordo manzana de Adán subiendo y bajando."
  },
  AvgDialog_18720_Content_24 = {
    Text = "¡Eructo! Este maldito bosque nunca ve un alma durante todo el día. Dado que estás aquí, déjame contarte una historia..."
  },
  AvgDialog_18720_Content_25 = {
    Text = "Eso fue probablemente a principios de este año...? No lo recuerdo muy bien."
  },
  AvgDialog_18720_Content_26 = {
    Text = "Como de costumbre, bebí y me quedé dormido en un lugar sombrío."
  },
  AvgDialog_18720_Content_27 = {
    Text = "Y luego escuché algunos ruidos extraños, casi como..."
  },
  AvgDialog_18720_Content_28 = {
    Text = "<RedItalic:Zzz... Crack...>"
  },
  AvgDialog_18720_Content_29 = {
    Text = "Sonido extraño. ¿Qué sigue?"
  },
  AvgDialog_18720_Content_3 = {
    Text = "Los cuervos se deslizan a través del cielo sombrío mientras el viento desolado de otoño aúlla."
  },
  AvgDialog_18720_Content_30 = {
    Text = "No te preocupes, pequeño detective.\nAbrí los ojos... hic, ¿adivina qué vi?"
  },
  AvgDialog_18720_Content_31 = {
    Text = "¡No puede ser, solo es el Cazador de Calaveras, ¿verdad?"
  },
  AvgDialog_18720_Content_32 = {
    Text = "Claro, ¡es un Cazador de Calaveras! O, podrías decir que es una mujer..."
  },
  AvgDialog_18720_Content_33 = {
    Text = "¡Una mujer está cortando la cabeza de Pinocho!"
  },
  AvgDialog_18720_Content_34 = {
    Text = "Entonces, me vio—hic—como si hubiera visto un fantasma, ¡y corrió más rápido que nadie!"
  },
  AvgDialog_18720_Content_35 = {
    Text = "¡Mi pobre Pinoko, su cuello apenas se sostiene por un hilo!"
  },
  AvgDialog_18720_Content_36 = {
    Text = "Haha, <Big:Hahahaha...>"
  },
  AvgDialog_18720_Content_37 = {
    Text = "El viejo Freeman estalló en una serie de risas fuertes, incluso derramando lágrimas de alegría."
  },
  AvgDialog_18720_Content_38 = {
    Text = "<SmallShake:Paciencia, paciencia...>"
  },
  AvgDialog_18720_Content_39 = {
    Text = "¡Hic, hic! Ha pasado aproximadamente un mes, y escuché esa voz de nuevo..."
  },
  AvgDialog_18720_Content_4 = {
    Text = "Lo encontré."
  },
  AvgDialog_18720_Content_40 = {
    Text = "<RedItalic:Zzz... Crack... Crack...>"
  },
  AvgDialog_18720_Content_41 = {
    Text = "Esta vez, no fue la mujer quien regresó, sino un hombre muy delgado."
  },
  AvgDialog_18720_Content_42 = {
    Text = "¡Ese es un trabajador hábil! Con un solo corte..."
  },
  AvgDialog_18720_Content_43 = {
    Text = "<RedBig:¡Whoosh! La cabeza de Pinoko ha desaparecido!>"
  },
  AvgDialog_18720_Content_44 = {
    Text = "Suena como si hubiera dos Cazadores de Calaveras. ¿Qué sucedió después?"
  },
  AvgDialog_18720_Content_45 = {
    Text = "¿Más tarde? No hay más tarde. Esa es toda la historia de Old Freeman y los Headcrabs, hic."
  },
  AvgDialog_18720_Content_46 = {
    Text = "El viejo Freeman dejó escapar un eructo satisfecho, entrecerró sus ojos amarillentos y te miró de arriba abajo."
  },
  AvgDialog_18720_Content_47 = {
    Text = "Pareces completamente desinformado, pobre detective. ¿Alguna vez has oído hablar de <Red:La Leyenda del Cazador de Calaveras>?"
  },
  AvgDialog_18720_Content_48 = {
    Text = "¿La Leyenda del Cazador de Calaveras? Cuéntame."
  },
  AvgDialog_18720_Content_49 = {
    Text = "El viejo Freeman se reclinó cómodamente contra la lápida, tomó unos tragos para terminar el licor que quedaba en la botella y la arrojó despreocupadamente al suelo."
  },
  AvgDialog_18720_Content_5 = {
    Text = "Te detienes frente a una tumba solitaria, la tapa del ataúd en descomposición ya abierta abajo."
  },
  AvgDialog_18720_Content_50 = {
    Text = "El líquido brotó de la botella rota, dejando un rastro serpenteante en el suelo. Como lágrimas, o quizás sangre."
  },
  AvgDialog_18720_Content_51 = {
    Text = "Algunos dicen que el Cazador de Cráneos es un monstruo nacido de la <Yellow:Epidemia>."
  },
  AvgDialog_18720_Content_52 = {
    Text = "Algunos dicen que el Cazador de Cráneos no es una persona ni dos personas."
  },
  AvgDialog_18720_Content_53 = {
    Text = "<Red:Los Cazadores de Cráneos son una organización.>"
  },
  AvgDialog_18720_Content_54 = {
    Text = "¿Organización?"
  },
  AvgDialog_18720_Content_55 = {
    Text = "Sí, una organización."
  },
  AvgDialog_18720_Content_56 = {
    Text = "Solo aparecen en noches lluviosas, sus pasos ocultos por la lluvia, acercándose silenciosamente detrás de ti..."
  },
  AvgDialog_18720_Content_57 = {
    Text = "<RedBig:¡Pum!>"
  },
  AvgDialog_18720_Content_58 = {Text = "¡¡!!"},
  AvgDialog_18720_Content_59 = {
    Text = "¡Jajaja! ¿Qué es esto? ¿Ya asustado, mi pequeño detective?"
  },
  AvgDialog_18720_Content_6 = {
    Text = "Un esqueleto sin cabeza reposa en el ataúd, ahora un paraíso para musgo e insectos."
  },
  AvgDialog_18720_Content_60 = {
    Text = "Se acerca, sus ojos amarillos turbios girando, casi ardiendo en ti."
  },
  AvgDialog_18720_Content_61 = {
    Text = "Esta persona parece extraña. Sal de este lugar rápidamente."
  },
  AvgDialog_18720_Content_62 = {
    Text = "Lo siento, Mr. Freeman. Se está haciendo tarde. Creo que tengo que irme..."
  },
  AvgDialog_18720_Content_63 = {
    Text = "Tomaste un leve respiro y te alejaste sin mirar atrás."
  },
  AvgDialog_18720_Content_64 = {
    Text = "Risas burlonas vienen de atrás, pero no puedes permitirte preocuparte por eso ahora. Todo lo que quieres es irte."
  },
  AvgDialog_18720_Content_65 = {
    Text = "El cielo se oscureció gradualmente, con nubes oscuras colgando bajo bloqueando la pálida luz del sol. El viento agitó las hojas, haciéndolas undular como olas."
  },
  AvgDialog_18720_Content_66 = {
    Text = "Al final del cementerio, ves una figura que es tanto familiar como extraña."
  },
  AvgDialog_18720_Content_67 = {
    Text = "Es Narciso. La mayor parte de su cara está oculta bajo el ala de su sombrero inclinado, con cabello gris-blanco balanceándose suavemente en el viento."
  },
  AvgDialog_18720_Content_68 = {
    Text = "Al verte en tan desaliñado estado, Narciso se rió felices."
  },
  AvgDialog_18720_Content_69 = {
    Text = "Cuánto tiempo sin vernos, {Male=Mr.,Female=Miss} Guardián."
  },
  AvgDialog_18720_Content_7 = {
    Text = "La nota registra el tiempo de descubrimiento como hace medio año; el momento de la muerte debe ser aún más temprano..."
  },
  AvgDialog_18720_Content_8 = {
    Text = "En otras palabras, esta es probablemente la primera víctima conocida del \"Cazador de Calaveras\". Sin embargo, los registros policiales nunca lo mencionaron..."
  },
  AvgDialog_18720_Content_9 = {
    Text = "No hay un hospital adecuado ni una funeraria aquí, y nadie presta mucha atención a los muertos."
  },
  AvgDialog_18721_Content_1 = {
    Text = "¿Quizás intentar usar Rastro Mental para encontrar al Cazador de Calaveras?"
  },
  AvgDialog_18721_Content_2 = {
    Text = "Este método tiene poco efecto en las criaturas del Reino Ultra."
  },
  AvgDialog_18721_Content_3 = {
    Text = "La retrospección espiritual tampoco es omnipotente."
  },
  AvgDialog_18722_Content_1 = {
    Text = "Hasta que nos volvamos a encontrar"
  },
  AvgDialog_18722_Content_10 = {
    Text = "<LightGray:¿Un cráneo precioso? ¿De quién podría ser...>"
  },
  AvgDialog_18722_Content_11 = {Text = "..."},
  AvgDialog_18722_Content_12 = {
    Text = "Pareces preocupado, %player%. ¿Parece que realmente quieres saber la respuesta?"
  },
  AvgDialog_18722_Content_13 = {
    Text = "Es solo así así."
  },
  AvgDialog_18722_Content_14 = {
    Text = "Ahem, no soy el tipo de persona que curiosea en la privacidad de los demás."
  },
  AvgDialog_18722_Content_15 = {
    Text = "¿Es así? Pero tu expresión ya te ha traicionado."
  },
  AvgDialog_18722_Content_16 = {
    Text = "Claro, quiero saber."
  },
  AvgDialog_18722_Content_17 = {
    Text = "Solo quiero saber más sobre ti, Dama Narciso."
  },
  AvgDialog_18722_Content_18 = {
    Text = "Oh? Alguien parece volverse más codicioso."
  },
  AvgDialog_18722_Content_19 = {
    Text = "Aquí tienes una pista: <Yellow:Es algo que ya has visto antes.>"
  },
  AvgDialog_18722_Content_2 = {
    Text = "Las tropas de apoyo y el Comité están en camino. Quédate aquí y asegura el área."
  },
  AvgDialog_18722_Content_20 = {
    Text = "¿Has visto esto antes...?"
  },
  AvgDialog_18722_Content_21 = {
    Text = "Reflexionas profundamente, la historia de los últimos dos días y las personas que has conocido pasan ante tus ojos como una linterna giratoria."
  },
  AvgDialog_18722_Content_22 = {Text = "..."},
  AvgDialog_18722_Content_23 = {Text = "¡¡!!"},
  AvgDialog_18722_Content_24 = {
    Text = "¿Podría ser la que está en Norwich Street que se parece exactamente a ti...?"
  },
  AvgDialog_18722_Content_25 = {
    Text = "Muy inteligente."
  },
  AvgDialog_18722_Content_26 = {
    Text = "Pero, ¿por qué...? No entiendo."
  },
  AvgDialog_18722_Content_27 = {
    Text = "Narciso contempló el amanecer brumoso en el horizonte distante, el viento frío levantando su largo cabello."
  },
  AvgDialog_18722_Content_28 = {
    Text = "Eso es un \"especimen\". Pertenecía a mi antiguo maestro."
  },
  AvgDialog_18722_Content_29 = {
    Text = "Aquí hay un secreto: Mi rostro actual está modelado a partir de eso."
  },
  AvgDialog_18722_Content_3 = {
    Text = "No te preocupes, esta vez seré bueno y esperaré aquí. No correré por todas partes."
  },
  AvgDialog_18722_Content_30 = {Text = "?!"},
  AvgDialog_18722_Content_31 = {
    Text = "<LightGray:Así que esta no es la verdadera apariencia de la Dama del narciso...>"
  },
  AvgDialog_18722_Content_32 = {
    Text = "Realmente me ayudaste esta vez.\nTodavía no puedo perdonarme por usar a un Guardián tan inexperto como cebo."
  },
  AvgDialog_18722_Content_33 = {
    Text = "...No importa. Mientras la investigación se complete, no me importa ser usado una vez."
  },
  AvgDialog_18722_Content_34 = {
    Text = "¿Es así? Pero realmente me siento mal por ello. Así que..."
  },
  AvgDialog_18722_Content_35 = {
    Text = "Como disculpa, puedo concederte un deseo."
  },
  AvgDialog_18722_Content_36 = {Text = "Es gratis~"},
  AvgDialog_18722_Content_37 = {Text = "¡¡!!"},
  AvgDialog_18722_Content_38 = {
    Text = "La persona frente a ti es un comerciante astuto y despiadado, poseyendo inteligencia, conocimiento tabú y coleccionables preciosos que muchos codician."
  },
  AvgDialog_18722_Content_39 = {
    Text = "Y ahora, puede concederte un deseo sin cargo."
  },
  AvgDialog_18722_Content_4 = {
    Text = "Nunca esperé que la investigación se completara tan rápido.\n¡Gran trabajo, %player%!"
  },
  AvgDialog_18722_Content_40 = {
    Text = "<LightGray:No... La Señorita Muñeca se molestaría si supiera que estoy haciendo tratos con otros fuera.>"
  },
  AvgDialog_18722_Content_41 = {
    Text = "Una oleada de posibilidades parpadea en tu mente—Reliquias de oro perdidas, los pasteles más deliciosos, enormes Colmillos de Leo..."
  },
  AvgDialog_18722_Content_42 = {
    Text = "Los pensamientos en conflicto se entrelazan y chocan, pero eventualmente retroceden como la marea — decides seguir tus instintos."
  },
  AvgDialog_18722_Content_43 = {
    Text = "¿Has decidido sobre tu solicitud? No seas demasiado codicioso."
  },
  AvgDialog_18722_Content_44 = {
    Text = "He tomado una decisión. Mis requisitos son simples."
  },
  AvgDialog_18722_Content_45 = {
    Text = "Déjame ver tu verdadera forma."
  },
  AvgDialog_18722_Content_46 = {Text = "..."},
  AvgDialog_18722_Content_47 = {
    Text = "¿Es realmente tan simple? Piénsalo. Puedo darte muchas cosas, cualquiera de las cuales vale más que esto."
  },
  AvgDialog_18722_Content_48 = {
    Text = "El valor es determinado por mi juicio. Esa es mi única demanda."
  },
  AvgDialog_18722_Content_49 = {
    Text = "Como era de esperar de un Guardián de {Male=Mr.,Female=Miss}, siempre me sorprendes. Así que..."
  },
  AvgDialog_18722_Content_5 = {
    Text = "Tos, gracias a la Dama del narciso esta vez."
  },
  AvgDialog_18722_Content_50 = {
    Text = "Daffodil caminó hacia ti. El viento levantó su largo cabello, haciéndolo ondear como olas grises."
  },
  AvgDialog_18722_Content_51 = {
    Text = "Estás tan cerca que casi puedes ver tu reflejo en sus ojos."
  },
  AvgDialog_18722_Content_52 = {
    Text = "Recuerda mantenerlo en secreto, %player%."
  },
  AvgDialog_18722_Content_53 = {
    Text = "No bien había hablado cuando sus rasgos comenzaron a borrarse y disolverse, como pinturas al óleo en agua..."
  },
  AvgDialog_18722_Content_54 = {
    Text = "Finalmente, finalmente viste su rostro claramente."
  },
  AvgDialog_18722_Content_55 = {
    Text = "Esa era una cara @2, recordándote muchas cosas."
  },
  AvgDialog_18722_Content_56 = {
    Text = "Como la húmeda neblina después de la lluvia, el narciso floreciendo silenciosamente en la esquina, o el pequeño animal enrollado en la oscuridad..."
  },
  AvgDialog_18722_Content_57 = {
    Text = "Antes de que pudieras mirar más de cerca, la cara desapareció como una gota de agua fusionándose con el agua."
  },
  AvgDialog_18722_Content_58 = {
    Text = "Entonces... esta es tu verdadera forma."
  },
  AvgDialog_18722_Content_59 = {
    Text = "¿Cómo es? Es feo, ¿verdad?"
  },
  AvgDialog_18722_Content_6 = {
    Text = "Es solo un pequeño esfuerzo, y también he recuperado lo que se había perdido."
  },
  AvgDialog_18722_Content_60 = {
    Text = "Sacudes la cabeza."
  },
  AvgDialog_18722_Content_61 = {
    Text = "Inesperadamente... pero tan típico de ti."
  },
  AvgDialog_18722_Content_62 = {
    Text = "La luz del sol de la mañana barría la humedad de la lluvia, envolviéndola en un suave halo."
  },
  AvgDialog_18722_Content_63 = {
    Text = "Para ser honesto... estaba un poco asustado hace un momento, y luego me sorprendí de mi propio miedo."
  },
  AvgDialog_18722_Content_64 = {
    Text = "¿Diez años, cincuenta años? Ni siquiera puedo recordar la última vez que sentí miedo."
  },
  AvgDialog_18722_Content_65 = {
    Text = "¿Asustado...? ¿Podría ser que te preocupe que piense que no eres atractivo?"
  },
  AvgDialog_18722_Content_66 = {
    Text = "Narciso no respondió, solo te acarició el cabello suavemente."
  },
  AvgDialog_18722_Content_67 = {
    Text = "%player%, ahora eres la única persona en el mundo que ha visto \"a mí\"."
  },
  AvgDialog_18722_Content_68 = {
    Text = "Je, ahora tengo un poco de ventaja sobre ti."
  },
  AvgDialog_18722_Content_69 = {
    Text = "Antes de perder mi memoria, necesito dibujar rápidamente tu cara en papel."
  },
  AvgDialog_18722_Content_7 = {
    Text = "Desde la perspectiva del comerciante, este era un \"trato\" perfecto"
  },
  AvgDialog_18722_Content_70 = {
    Text = "Daffodil sonrió, sus ojos se curvaban en un hermoso arco."
  },
  AvgDialog_18722_Content_71 = {
    Text = "Qué niño tan tonto."
  },
  AvgDialog_18722_Content_72 = {
    Text = "Bueno, tu Comité y los amigos de la policía deberían estar en camino ahora, ¿verdad?"
  },
  AvgDialog_18722_Content_73 = {
    Text = "<Shake:Así que lo sabías todo el tiempo...>"
  },
  AvgDialog_18722_Content_74 = {
    Text = "No tengo la paciencia para esos tediosos interrogatorios.\nLa próxima vez, busquemos un lugar tranquilo y tomemos una taza de café."
  },
  AvgDialog_18722_Content_75 = {
    Text = "Adiós, mi Guardián {Male=Mr.,Female=Miss}."
  },
  AvgDialog_18722_Content_76 = {
    Text = "¿Eh? Oh... Adiós, Lady Narciso."
  },
  AvgDialog_18722_Content_77 = {
    Text = "Daffodil te saludó y se alejó."
  },
  AvgDialog_18722_Content_78 = {
    Text = "Al contemplar su figura relajada a lo lejos, sientes que tu ánimo se aligera."
  },
  AvgDialog_18722_Content_79 = {
    Text = "La neblina persistente se ha disipado por completo, y el cielo finalmente se ha despejado. La luz del sol filtra a través de las nubes perezosas, calentando todo tu cuerpo."
  },
  AvgDialog_18722_Content_8 = {
    Text = "Cosas perdidas..."
  },
  AvgDialog_18722_Content_80 = {
    Text = "Por alguna razón, tienes una premonición—"
  },
  AvgDialog_18722_Content_81 = {
    Text = "Seguirás encontrándote el uno al otro a través de diferentes tiempos y dimensiones."
  },
  AvgDialog_18722_Content_9 = {
    Text = "El Cazador de Cráneos me robó un <Yellow:cabeza preciosa>, así que estoy aquí para hacer un poco de investigación. Es así de simple."
  },
  AvgDialog_18723_Content_1 = {
    Text = "Cof, cof, los Despertadores del Reino Ultra son realmente difíciles de alcanzar..."
  },
  AvgDialog_18723_Content_10 = {
    Text = "¿Responder...?"
  },
  AvgDialog_18723_Content_11 = {
    Text = "Se escapó mientras estabas temporalmente ausente, y la Sra. Horla y yo estábamos charlando."
  },
  AvgDialog_18723_Content_12 = {
    Text = "Pero no hay necesidad de preocuparse. Si me sigues, lo verás pronto."
  },
  AvgDialog_18723_Content_13 = {
    Text = "¿Está en el <Blue:Desierto al norte de Reny Town>?"
  },
  AvgDialog_18723_Content_14 = {
    Text = "Oh? Parece que nuestra pequeña detective es bastante astuta. ¿Cómo lograste averiguarlo?"
  },
  AvgDialog_18723_Content_15 = {
    Text = "Ese tipo exhibe el Fenómeno D, que probablemente está relacionado con la plaga que ocurrió en el norte hace tres años."
  },
  AvgDialog_18723_Content_16 = {
    Text = "Ahora que está gravemente herido y enfrentando ataques tanto de nosotros como de la policía, no hay muchos lugares a los que pueda ir."
  },
  AvgDialog_18723_Content_17 = {
    Text = "No importa si está escondido en el yermo, es un avance que vale la pena investigar."
  },
  AvgDialog_18723_Content_18 = {
    Text = "No está mal, bastante ingenioso. Pero, ¿sabes cuán vasto es ese desierto?"
  },
  AvgDialog_18723_Content_19 = {
    Text = "Aproximadamente 50 millas cuadradas.\nNo querrías desperdiciar tus preciadas vacaciones en exploraciones geológicas y trabajos de censo de población, ¿verdad?"
  },
  AvgDialog_18723_Content_2 = {
    Text = "Te tambaleas hacia una encrucijada."
  },
  AvgDialog_18723_Content_20 = {
    Text = "Y por casualidad sé su lugar exacto de escondite.\n¿Te gustaría venir?"
  },
  AvgDialog_18723_Content_21 = {
    Text = "¡No estés de acuerdo! Es extremadamente peligrosa; no te dejes engañar por ella."
  },
  AvgDialog_18723_Content_22 = {
    Text = "Contaré hasta tres. Tres, dos..."
  },
  AvgDialog_18723_Content_23 = {Text = "..."},
  AvgDialog_18723_Content_24 = {
    Text = "Iré contigo."
  },
  AvgDialog_18723_Content_25 = {Text = "..."},
  AvgDialog_18723_Content_26 = {
    Text = "Hmm, qué niño tan obediente."
  },
  AvgDialog_18723_Content_27 = {
    Text = "Dama Daffodil, ¿puedo acompañarte?"
  },
  AvgDialog_18723_Content_28 = {
    Text = "Una frágil chica sale de las sombras de los árboles detrás de ti, con los ojos llenos de preocupación."
  },
  AvgDialog_18723_Content_29 = {
    Text = "Sé que estás preocupado por %player%."
  },
  AvgDialog_18723_Content_3 = {
    Text = "No hay más cazadores aquí, solo Narciso y su sombra alargada."
  },
  AvgDialog_18723_Content_30 = {
    Text = "Pero lo siento, mi pequeña rosa. Esta vez solo puedo llevar a una persona."
  },
  AvgDialog_18723_Content_31 = {
    Text = "El viento helado aúlla por las calles nocturnas. Horla se envuelve tightly en la carta a prueba de viento y caliente, su pálido rostro se levanta mientras mira a Narciso con una expresión seria."
  },
  AvgDialog_18723_Content_32 = {
    Text = "¿Por qué? Puede que no sea buena en combate, pero una mano extra siempre es útil, ¿no?"
  },
  AvgDialog_18723_Content_33 = {
    Text = "Solo puedo llevarme uno. Lo siento, Pequeña Rosa, tengo mis razones."
  },
  AvgDialog_18723_Content_34 = {Text = "..."},
  AvgDialog_18723_Content_35 = {
    Text = "Lady Daffodil, seguramente escoltará a {Male=Mr.,Female=Miss} %player% de vuelta sana y salva, ¿verdad?"
  },
  AvgDialog_18723_Content_36 = {
    Text = "Daffodil observó a las polillas revoloteando bajo la luz de la calle y sopló tranquilamente un anillo de humo desde su boca."
  },
  AvgDialog_18723_Content_37 = {
    Text = "Por supuesto, ten la seguridad."
  },
  AvgDialog_18723_Content_4 = {
    Text = "Por alguna razón, sientes que ella ha estado de pie allí durante mucho tiempo."
  },
  AvgDialog_18723_Content_5 = {
    Text = "Parece que desde tiempos antiguos, ella ha estado aquí sola, mirando en silencio a la distancia sin pronunciar una palabra."
  },
  AvgDialog_18723_Content_6 = {
    Text = "Estás aquí."
  },
  AvgDialog_18723_Content_7 = {
    Text = "Daffodil se dio la vuelta, su expresión aún tenue."
  },
  AvgDialog_18723_Content_8 = {
    Text = "¿Dónde está el Cazador de Cráneos? ¿Te has perdido?"
  },
  AvgDialog_18723_Content_9 = {
    Text = "Sí, perdimos el rumbo. Pero... creo que ya sé la respuesta."
  },
  AvgDialog_18724_Content_1 = {
    Text = "Desde lejos"
  },
  AvgDialog_18724_Content_10 = {
    Text = "Basado en el estado de los cuerpos y las declaraciones de testigos, los dos murieron dentro de media hora el uno del otro."
  },
  AvgDialog_18724_Content_11 = {
    Text = "¿Está el lugar de la muerte cerca?"
  },
  AvgDialog_18724_Content_12 = {
    Text = "Ramona sacudió la cabeza."
  },
  AvgDialog_18724_Content_13 = {
    Text = "Incluso en coche, se tarda más de una hora, sin mencionar que muy pocas personas en la ciudad tienen coches."
  },
  AvgDialog_18724_Content_14 = {
    Text = "... Quizás el viejo Freeman tenía razón."
  },
  AvgDialog_18724_Content_15 = {
    Text = "Los Cazadores de Cráneos son una organización. ¿Pero cuál es su verdadero propósito?"
  },
  AvgDialog_18724_Content_16 = {
    Text = "Cabezas@2 Más cabezas..."
  },
  AvgDialog_18724_Content_17 = {
    Text = "Un repentino viento frío sopló desde atrás."
  },
  AvgDialog_18724_Content_18 = {
    Text = "Te das la vuelta, solo para ver el cuerpo sin cabeza corriendo hacia ti a una velocidad increíble."
  },
  AvgDialog_18724_Content_19 = {Text = "?!"},
  AvgDialog_18724_Content_2 = {
    Text = "00:15, Cabaña de Horla"
  },
  AvgDialog_18724_Content_20 = {
    Text = "Dame cabeza@3, dame@1, cabeza@4"
  },
  AvgDialog_18724_Content_21 = {
    Text = "Rápidamente desvías tu cuerpo a un lado. El cadáver se estrella contra el cristal delante de ti, desapareciendo en la vasta noche."
  },
  AvgDialog_18724_Content_22 = {
    Text = "¡Tal velocidad increíble...! ¿Podría ser un Despertador del Reino Ultra?"
  },
  AvgDialog_18724_Content_23 = {
    Text = "Así como estás confundido, un fuerte aroma de narciso te envuelve completamente."
  },
  AvgDialog_18724_Content_24 = {
    Text = "Una falda púrpura pasa rápidamente a tu lado y luego desaparece ante tus ojos."
  },
  AvgDialog_18724_Content_25 = {
    Text = "¿Dama Daffodil...?"
  },
  AvgDialog_18724_Content_26 = {
    Text = "¡Rápido, alcanza! No dejes que la pista importante se escape."
  },
  AvgDialog_18724_Content_3 = {
    Text = "Encontraste un rincón tranquilo y le explicaste a Ramona lo que había sucedido."
  },
  AvgDialog_18724_Content_4 = {
    Text = "Claro, simplemente omite la parte donde casi te cortan la garganta."
  },
  AvgDialog_18724_Content_5 = {Text = "..."},
  AvgDialog_18724_Content_6 = {
    Text = "He llamado <Red:35> veces desde esta tarde, pero no ha habido respuesta."
  },
  AvgDialog_18724_Content_7 = {
    Text = "Lo siento, sucedió tan repentinamente..."
  },
  AvgDialog_18724_Content_8 = {
    Text = "...Esto no volverá a ocurrir."
  },
  AvgDialog_18724_Content_9 = {
    Text = "Las identidades de las víctimas encontradas durante el día han sido confirmadas.\nCarpintero Damon Mendes, 35; joven desempleado Thomas Quillen, 23."
  },
  AvgDialog_18725_Content_1 = {
    Text = "Un marco de imagen invertido llama tu atención."
  },
  AvgDialog_18725_Content_10 = {
    Text = "<RedItalic:Él bebió diez botellas de alcohol el domingo, perdió su trabajo y perdió a su esposa.>"
  },
  AvgDialog_18725_Content_11 = {
    Text = "Alguien está tarareando suavemente una canción de cuna sin ritmo."
  },
  AvgDialog_18725_Content_12 = {
    Text = "La melodía seca se siente como una mano invisible y húmeda acariciando suavemente los ya levantados vellos en la nuca."
  },
  AvgDialog_18725_Content_13 = {
    Text = "<RedItalic:El viejo Freeman gimió y bebió once botellas de licor nuevamente el lunes...>"
  },
  AvgDialog_18725_Content_14 = {
    Text = "Acompañada del chirrido de las tablas de madera, Harriet se quedó en silencio ante el pasillo tenuemente iluminado."
  },
  AvgDialog_18725_Content_15 = {
    Text = "¡Eso es correcto, el Viejo Freeman es mi esposo!"
  },
  AvgDialog_18725_Content_16 = {Text = "¿Qué?!"},
  AvgDialog_18725_Content_17 = {
    Text = "En ese momento, todos pensaron que estaba muerta, incluido mi esposo."
  },
  AvgDialog_18725_Content_18 = {
    Text = "Más tarde, después de un tiempo desconocido, volví a la vida... pero algo en mí había cambiado."
  },
  AvgDialog_18725_Content_19 = {
    Text = "Te mantienes en silencio, ya adivinando el resto de la historia."
  },
  AvgDialog_18725_Content_2 = {
    Text = "De la cocina vino el sonido burbujeante del agua hirviendo; la Sra. Harriet todavía estaba ocupada en su interior."
  },
  AvgDialog_18725_Content_20 = {
    Text = "Los humanos infectados por la Disolución sufren daños mentales irreversibles, lo que lleva a diversas complicaciones"
  },
  AvgDialog_18725_Content_21 = {
    Text = "No es de extrañar que la señora Harriet haya terminado así."
  },
  AvgDialog_18725_Content_22 = {
    Text = "Comencé a ansiar cabezas, muchas cabezas... Así que me colé en un cementerio."
  },
  AvgDialog_18725_Content_23 = {
    Text = "Me incliné sobre el cuerpo del viejo Pinoco, usando una guadaña oxidada para intentar cortarle la cabeza.\nPero estaba demasiado débil en ese momento, y no podía ni siquiera sostener la guadaña con firmeza..."
  },
  AvgDialog_18725_Content_24 = {
    Text = "¿Y adivina a quién conocí?"
  },
  AvgDialog_18725_Content_25 = {Text = "..."},
  AvgDialog_18725_Content_26 = {
    Text = "Conocí a mi esposo."
  },
  AvgDialog_18725_Content_27 = {
    Text = "Él se ha vuelto más gordo, más viejo y se ha convertido en un borracho."
  },
  AvgDialog_18725_Content_28 = {
    Text = "Heh... Este mundo siempre encuentra nuevas formas de atormentarnos a nosotros, pobres almas."
  },
  AvgDialog_18725_Content_29 = {
    Text = "Él sostuvo su bebida y me miró como un perro callejero."
  },
  AvgDialog_18725_Content_3 = {
    Text = "Con cuidado, das la vuelta al marco de la foto."
  },
  AvgDialog_18725_Content_30 = {
    Text = "Él ha estado riendo todo el tiempo. Sí, sé que debí haberme visto tanto patético como ridículo en ese entonces."
  },
  AvgDialog_18725_Content_31 = {
    Text = "Pero él... no me reconoce en absoluto."
  },
  AvgDialog_18725_Content_32 = {
    Text = "...Así que tú eres el cazador de calaveras de quien habló."
  },
  AvgDialog_18725_Content_33 = {
    Text = "Harriet inclinó mecánicamente la cabeza hacia la derecha, produciendo un sonido de \"crujido\" desde su cuello."
  },
  AvgDialog_18725_Content_34 = {
    Text = "Sí. A pesar de que sé que no me recuerda, todavía lo miro de reojo."
  },
  AvgDialog_18725_Content_35 = {
    Text = "Así que oíste nuestra conversación, aprendiste que estaba llevando a cabo una investigación sobre los asesinatos, y decidiste seguirme y emboscarme?"
  },
  AvgDialog_18725_Content_36 = {Text = "..."},
  AvgDialog_18725_Content_37 = {
    Text = "Realmente eres diferente de ellos. He dicho tanto, sin embargo, tú te mantienes sereno."
  },
  AvgDialog_18725_Content_38 = {
    Text = "Dejaste escapar un suspiro suave, mirando hacia la puerta cerrada junto a ti."
  },
  AvgDialog_18725_Content_39 = {
    Text = "La sangre roja oscura gotea como un jarabe espeso por la rendija de la puerta, deslizándose lentamente hacia tus pies."
  },
  AvgDialog_18725_Content_4 = {
    Text = "Esta es una vieja foto familiar. Los rostros de la esposa y el hijo han estado borrados desde hace tiempo, dejando solo al esposo de pie a la extrema izquierda."
  },
  AvgDialog_18725_Content_40 = {
    Text = "¿Sabías...?"
  },
  AvgDialog_18725_Content_41 = {
    Text = "El suelo, el techo, los armarios... todos huelen a sangre y la pestilencia de la muerte."
  },
  AvgDialog_18725_Content_42 = {
    Text = "Desde el momento en que entré, supe todo."
  },
  AvgDialog_18725_Content_5 = {
    Text = "Se mantiene erguido y relajado frente a su casa recién construida, mostrando una brillante sonrisa a la cámara."
  },
  AvgDialog_18725_Content_6 = {
    Text = "Miras su frente y ojos algo familiares, y de repente un pensamiento ridículo atraviesa tu mente."
  },
  AvgDialog_18725_Content_7 = {
    Text = "¿El viejo Freeman...?!"
  },
  AvgDialog_18725_Content_8 = {
    Text = "¿Podría ser el esposo de la Sra. Harriet?"
  },
  AvgDialog_18725_Content_9 = {
    Text = "<RedItalic:Viejo Freeman, viejo Freeman, el pobre y loco borracho viejo Freeman...>"
  },
  AvgDialog_18726_Content_1 = {
    Text = "Caminas más adentro del callejón, tu abrigo ya empapado por la lluvia."
  },
  AvgDialog_18726_Content_10 = {
    Text = "Toca, toca, toca."
  },
  AvgDialog_18726_Content_11 = {
    Text = "El sonido de pasos pausados resonó desde la calle fuera del callejón, y una figura borrosa apareció bajo la farola."
  },
  AvgDialog_18726_Content_12 = {
    Text = "Es peligroso aquí, sal inmediatamente—"
  },
  AvgDialog_18726_Content_13 = {
    Text = "Esa es una mujer."
  },
  AvgDialog_18726_Content_14 = {
    Text = "Ella se queda sola bajo la farola, sosteniendo una cabeza regordeta que encaja perfectamente con el cuello del cuerpo sin cabeza detrás de ti."
  },
  AvgDialog_18726_Content_15 = {
    Text = "La sangre gotea del cuello, fluyendo lentamente por las grietas en los azulejos del suelo."
  },
  AvgDialog_18726_Content_16 = {
    Text = "Quédate ahí.\n¿Quién eres?"
  },
  AvgDialog_18726_Content_17 = {
    Text = "Las luces tenues de la calle parpadean, emitiendo un irritante zumbido eléctrico."
  },
  AvgDialog_18726_Content_18 = {
    Text = "La mujer levanta la cabeza y finalmente logras distinguir sus rasgos."
  },
  AvgDialog_18726_Content_19 = {Text = "..."},
  AvgDialog_18726_Content_2 = {
    Text = "La sangre roja oscura fluye del <Sombra>, extendiendo tentáculos amenazantes, invitándote en silencio."
  },
  AvgDialog_18726_Content_20 = {
    Text = "<Gray:Daphne... ¿Lady Delf?>"
  },
  AvgDialog_18726_Content_3 = {
    Text = "Está tranquilo aquí; solo puedes oír el sonido de la lluvia, pasos y respiración."
  },
  AvgDialog_18726_Content_4 = {
    Text = "Suena como un ritmo de tambor caótico, creciendo más rápido y más fuerte, hasta que llegas al final del callejón."
  },
  AvgDialog_18726_Content_5 = {
    Text = "El cadáver hinchado yace inerte en la pila de basura, despreocupadamente desechado."
  },
  AvgDialog_18726_Content_6 = {
    Text = "La incisión en el cuello está borrosa, con sangre roja oscura brotando de los vasos."
  },
  AvgDialog_18726_Content_7 = {
    Text = "No necesitas tocarlo para saber que la sangre está caliente."
  },
  AvgDialog_18726_Content_8 = {
    Text = "Cabeza faltante, heridas irregulares en el cuello..."
  },
  AvgDialog_18726_Content_9 = {
    Text = "Es \"Cazador de Calaveras\""
  },
  AvgDialog_18727_Content_1 = {Text = "Serendipia"},
  AvgDialog_18727_Content_10 = {
    Text = "Si ella no mintió ni se equivocó al juzgar, entonces sí."
  },
  AvgDialog_18727_Content_11 = {
    Text = "<Blue:Vanguardia> llegó a la Ciudad Rini hace una semana y detectó signos de un Plata activo en el lugar de la muerte."
  },
  AvgDialog_18727_Content_12 = {
    Text = "Incluyendo los últimos tres, este es el octavo <Blue:Evento Depredador Craneal> en la Ciudad Rennie."
  },
  AvgDialog_18727_Content_13 = {
    Text = "¿Cazador de cráneos? ¿Es así como llaman las personas aquí al asesino?"
  },
  AvgDialog_18727_Content_14 = {
    Text = "Muy vívido, ¿no? Gracias a él, nadie se atreve a salir después de oscurecer aquí."
  },
  AvgDialog_18727_Content_15 = {
    Text = "Miras la calle desolada frente a ti."
  },
  AvgDialog_18727_Content_16 = {
    Text = "Para las 8 PM, todas las puertas y ventanas cercanas están firmemente cerradas. El miedo se filtra desde las ventanas pitch-black, envolviendo silenciosamente los alrededores."
  },
  AvgDialog_18727_Content_17 = {
    Text = "Aparte de algunos ladridos de perro prolongados, aquí está inquietantemente silencioso."
  },
  AvgDialog_18727_Content_18 = {
    Text = "Pitter-patter..."
  },
  AvgDialog_18727_Content_19 = {
    Text = "Hmm, ¿está lloviendo?"
  },
  AvgDialog_18727_Content_2 = {
    Text = "Belen Stock, 46 años, murió en casa en la cocina el 12 de septiembre.\n<Red:Cabeza faltante>, cuerpo intacto excepto por un corte irregular en el cuello."
  },
  AvgDialog_18727_Content_20 = {
    Text = "Una fina y fresca lluvia cae del cielo nocturno, lanzando un velo blanco ante ti."
  },
  AvgDialog_18727_Content_21 = {
    Text = "Escucho la lluvia de tu lado. ¿Tienes un paraguas?"
  },
  AvgDialog_18727_Content_22 = {
    Text = "<Shake:Oh no. Tú siempre eres quien trae un paraguas, así que...>"
  },
  AvgDialog_18727_Content_23 = {
    Text = "Parece que todavía necesito acostumbrarme a la vida sin ti."
  },
  AvgDialog_18727_Content_24 = {Text = "..."},
  AvgDialog_18727_Content_25 = {
    Text = "Lo siento, no pude ir contigo esta vez."
  },
  AvgDialog_18727_Content_26 = {
    Text = "La Señorita Muñeca insiste en que me quede para realizar una investigación de disolución supuestamente \"importante\" con ella..."
  },
  AvgDialog_18727_Content_27 = {
    Text = "<Small:Ramona, ¿podrías pasarme la muestra de plata en el tercer estante de la quinta fila, código SI-3007...?>"
  },
  AvgDialog_18727_Content_28 = {Text = "..."},
  AvgDialog_18727_Content_29 = {
    Text = "Cuida de ti mismo, %player%. En cuanto al alojamiento... <Blue:Señorita Horla> se encargará de todo."
  },
  AvgDialog_18727_Content_3 = {
    Text = "Dwight Williams, 56 años, murió en la intersección de Deman Street el 13 de septiembre.\n<Red:Cabeza Faltante>, cuerpo intacto con un corte irregular en el cuello."
  },
  AvgDialog_18727_Content_30 = {
    Text = "¿Señorita Horla? No es de extrañar que rara vez la veamos en la escuela; ¿vive afuera?"
  },
  AvgDialog_18727_Content_31 = {
    Text = "Mitag no es un campamento de una sola dirección."
  },
  AvgDialog_18727_Content_32 = {
    Text = "Los Despertadores de bajo riesgo pueden irse de vacaciones, quedarse a dormir o visitar a la familia.\nLa condición es simple: aplicar con anticipación y evitar causar problemas."
  },
  AvgDialog_18727_Content_33 = {
    Text = "Uh... ¿Así que la señorita Horla también participará en la investigación?"
  },
  AvgDialog_18727_Content_34 = {
    Text = "No todos los Despertadores están interesados en misiones de campo. Si crees que es necesario, pregúntale su opinión."
  },
  AvgDialog_18727_Content_35 = {
    Text = "La situación actual es estable y manejable, no es necesario—"
  },
  AvgDialog_18727_Content_36 = {
    Text = "¿Whoosh—"
  },
  AvgDialog_18727_Content_37 = {
    Text = "De repente, el sonido de Caro salpicando vino de la calle adelante, seguido de pasos caóticos, rompiendo abruptamente el silencio de la noche."
  },
  AvgDialog_18727_Content_38 = {Text = "?!"},
  AvgDialog_18727_Content_39 = {
    Text = "En este momento, este sonido... ¿Podría ser...?"
  },
  AvgDialog_18727_Content_4 = {
    Text = "Fallecido No. 012, identidad y edad desconocidas, murió junto al Lago Knerl en el norte en la madrugada del 16 de septiembre..."
  },
  AvgDialog_18727_Content_40 = {
    Text = "Sigamos y echemos un vistazo. Recuerda mantenerte en contacto."
  },
  AvgDialog_18727_Content_41 = {
    Text = "Que la Llave de plata ilumine mi camino."
  },
  AvgDialog_18727_Content_5 = {
    Text = [[
20:00, Calle Norwich
Renny Town]]
  },
  AvgDialog_18727_Content_6 = {
    Text = "Falta la cabeza, cicatrices dentadas..."
  },
  AvgDialog_18727_Content_7 = {
    Text = "Y todos murieron ya sea saliendo solos o en casa."
  },
  AvgDialog_18727_Content_8 = {
    Text = "Además, una semana después de la muerte de Dwight Williams, su esposa afirmó haberlo visto corriendo apresuradamente en la wilderness."
  },
  AvgDialog_18727_Content_9 = {
    Text = "...¿Resucitada?"
  },
  AvgDialog_18764_Content_1 = {
    Text = "No, no lo hagas..."
  },
  AvgDialog_18764_Content_10 = {
    Text = "Cof, cof, cof... T-tú, ¡¿cómo puedes hacer trampa así?!"
  },
  AvgDialog_18764_Content_11 = {
    Text = "<SmallShake:Solo era un juego de adivinanzas, no hace falta alterarse tanto...>"
  },
  AvgDialog_18764_Content_12 = {
    Text = "¿Dónde está la salida del laberinto?"
  },
  AvgDialog_18764_Content_13 = {
    Text = "Jeje, ¿quieres saber? Entonces arrodíllate, ofrécele a esta gran reina una disculpa apropiada, y luego..."
  },
  AvgDialog_18764_Content_14 = {
    Text = "Lentamente levantas tu mano."
  },
  AvgDialog_18764_Content_15 = {
    Text = "<Shake:¡E-espera! Hablaré...>"
  },
  AvgDialog_18764_Content_16 = {
    Text = "La niña abrió la boca, y luego agachó la cabeza con abatimiento."
  },
  AvgDialog_18764_Content_17 = {
    Text = "En realidad... yo tampoco lo sé. Llevo encerrada aquí casi mil años..."
  },
  AvgDialog_18764_Content_18 = {
    Text = "¡Todos lo que hago es dormir, quedarme en blanco y gestionar a mi descendencia. ¡Me estoy volviendo loca del aburrimiento!"
  },
  AvgDialog_18764_Content_19 = {Text = "..."},
  AvgDialog_18764_Content_20 = {
    Text = "¿No eres la señora del laberinto? ¿Cómo es posible que no sepas dónde está la salida?"
  },
  AvgDialog_18764_Content_21 = {
    Text = "<SmallShake:Eso tendrías que preguntárselo a quien me encerró aquí. ¿Cómo voy a saber yo lo que estaba pensando...>"
  },
  AvgDialog_18764_Content_22 = {
    Text = "Cómo puede ser..."
  },
  AvgDialog_18764_Content_23 = {
    Text = "Entonces, ¿y si, quiero decir hipotéticamente—"
  },
  AvgDialog_18764_Content_24 = {
    Text = "¿Y si la persona que entró en el laberinto no está presente físicamente, sino que existe en alguna forma de consciencia?"
  },
  AvgDialog_18764_Content_25 = {
    Text = "¿Sería posible que, eh, digamos... eludiera las reglas de este laberinto?"
  },
  AvgDialog_18764_Content_26 = {
    Text = "Agrippa te miró con expresión desconcertada."
  },
  AvgDialog_18764_Content_27 = {
    Text = "Por supuesto que no."
  },
  AvgDialog_18764_Content_28 = {
    Text = "¿Quieres adivinar por qué has estado viendo tantas personas y lugares familiares en el laberinto?"
  },
  AvgDialog_18764_Content_29 = {
    Text = "¿Fantasma? No, recuerdos..."
  },
  AvgDialog_18764_Content_3 = {
    Text = "Finalmente eliminaste a la última \"Charlotte\"."
  },
  AvgDialog_18764_Content_30 = {
    Text = "Agrippa negó con la cabeza."
  },
  AvgDialog_18764_Content_31 = {
    Text = "Ninguno de los dos. Para ser precisos, es <Yellow:consciencia>."
  },
  AvgDialog_18764_Content_32 = {
    Text = "<Yellow:Lo que ha estado atrapado en el laberinto siempre fue solo tu consciencia, después de todo.>"
  },
  AvgDialog_18764_Content_4 = {
    Text = "La Keygrave se desvaneció gradualmente, y regresaste al lugar donde todo comenzó."
  },
  AvgDialog_18764_Content_5 = {
    Text = "Sal. Sé dónde estás."
  },
  AvgDialog_18764_Content_6 = {
    Text = "Un zumbido similar a un temblor surgió desde las profundidades del subsuelo, y el suelo se agrietó lentamente."
  },
  AvgDialog_18764_Content_7 = {Text = "¡¡BOOM!!"},
  AvgDialog_18764_Content_8 = {
    Text = "¡¡Puaj... Ptuu ptuu ptuu!!"
  },
  AvgDialog_18764_Content_9 = {
    Text = "Agrippa emergió del subsuelo, cubierta de polvo."
  },
  AvgDialog_18765_Content_1 = {
    Text = "Conciencia colectiva"
  },
  AvgDialog_18765_Content_10 = {
    Text = "¿Has hecho los deberes de esta semana? El examen de \"Introducción a la Disolución\" es pronto. ¿Cómo llevas el repaso?"
  },
  AvgDialog_18765_Content_11 = {
    Text = "¿¡Ramona!? No, yo no... Espera, eso no es..."
  },
  AvgDialog_18765_Content_12 = {
    Text = "%player%, hoy llegaste 5 minutos tarde a clase. Tu tardanza acumulada este mes es de 30 minutos y 15 segundos."
  },
  AvgDialog_18765_Content_13 = {
    Text = "Ven a mi oficina después de clase."
  },
  AvgDialog_18765_Content_14 = {Text = "—¡!!"},
  AvgDialog_18765_Content_15 = {
    Text = "Pfft. <Big:¡Ajajajajajaja!>"
  },
  AvgDialog_18765_Content_16 = {
    Text = "Asustado, ¿verdad? Deberías mirarte en un espejo y ver qué cara tienes ahora mismo."
  },
  AvgDialog_18765_Content_17 = {Text = "..."},
  AvgDialog_18765_Content_18 = {
    Text = "Estos... trucos de cambio de forma, ¿dónde los aprendiste todos?"
  },
  AvgDialog_18765_Content_19 = {
    Text = "Una vez viste el expediente de Agrippa en los archivos de los Despertados. No había registros relacionados con \"cambio de forma\" en Arriba."
  },
  AvgDialog_18765_Content_20 = {
    Text = "¿Aprender? Yo soy el amo de este laberinto. En mi dominio, puedo hacer lo... que... me plazca."
  },
  AvgDialog_18765_Content_21 = {
    Text = "Olvida solo uno... Puedo montar un espectáculo con diez, con cien de ellos."
  },
  AvgDialog_18765_Content_22 = {
    Text = "Tras hablar, Agrippa desapareció una vez más."
  },
  AvgDialog_18765_Content_23 = {
    Text = "Al poco tiempo, una, dos... incluso más Charlottes aparecieron ante ti."
  },
  AvgDialog_18765_Content_24 = {
    Text = "¿Adivina cuál es el verdadero yo, jeje..."
  },
  AvgDialog_18765_Content_25 = {
    Text = "Buaaa... ¿Cuál Charlotte es realmente Agrippa?"
  },
  AvgDialog_18765_Content_26 = {
    Text = "Una oportunidad, Solo una oportunidad..."
  },
  AvgDialog_18765_Content_27 = {
    Text = "Incontables voces estridentes se entrelazaron en una melodía caótica y discordante, flotando por tu mente."
  },
  AvgDialog_18765_Content_28 = {
    Text = "Fuera... ¡¡fuera de aquí...!!"
  },
  AvgDialog_18765_Content_29 = {
    Text = "Respiraste hondo y finalmente lograste calmar tus nervios."
  },
  AvgDialog_18765_Content_3 = {
    Text = "Charlotte, ¿cómo terminaste así?"
  },
  AvgDialog_18765_Content_30 = {
    Text = "Lo siento. Todas se ven iguales. No puedo distinguirlas."
  },
  AvgDialog_18765_Content_31 = {
    Text = "¿Eh? ¿Te rindes tan pronto? Qué aburrido."
  },
  AvgDialog_18765_Content_33 = {
    Text = "Al segundo siguiente, una \"Charlotte\" fue derribada al suelo.\nTe frotaste las sienes y dijiste con calma—"
  },
  AvgDialog_18765_Content_34 = {
    Text = "Pero no importa."
  },
  AvgDialog_18765_Content_35 = {
    Text = "Puedo tumbarlas a todas y cada una, y luego preguntar una por una."
  },
  AvgDialog_18765_Content_4 = {
    Text = "\"Charlotte\" torció la cabeza, y un zumbido escalofriante emanó desde lo más profundo de su garganta."
  },
  AvgDialog_18765_Content_5 = {
    Text = "<Shake:Ji ji, no te lo esperabas, ¿verdad? ¡Esa amiguita tuya hace mucho que se convirtió en una de mis crías!>"
  },
  AvgDialog_18765_Content_6 = {
    Text = "Esa voz... ¿Eres tú, Agrippa?"
  },
  AvgDialog_18765_Content_7 = {
    Text = "Qué conmovedor, aún recuerdas mi voz.\n¡Espera, déjame enseñarte algo impresionante!"
  },
  AvgDialog_18765_Content_8 = {
    Text = "Un sonido de risa ahogada surgió de la garganta de \"Charlotte\", luego su cuello se torció bruscamente y, en un instante, su apariencia cambió por completo."
  },
  AvgDialog_18765_Content_9 = {
    Text = "¡%player%, estás picoteando a escondidas otra vez!"
  },
  AvgDialog_18766_Content_1 = {Text = "Puerta"},
  AvgDialog_18766_Content_10 = {
    Text = "¿Estás listo/a, @1? Empujémosla juntos."
  },
  AvgDialog_18766_Content_11 = {Text = "Creak—"},
  AvgDialog_18766_Content_12 = {
    Text = "<Big:¡!!!>"
  },
  AvgDialog_18766_Content_13 = {
    Text = "Esto es... ¿qué clase de lugar...?"
  },
  AvgDialog_18766_Content_14 = {
    Text = "Es el lugar donde te quedarás obedientemente por el resto de tu vida."
  },
  AvgDialog_18766_Content_15 = {
    Text = "La niña estaba sentada en la plataforma hueca con una sonrisa juguetona, el mentón apoyado en ambas manos, su pierna derecha cruzada balanceándose perezosamente."
  },
  AvgDialog_18766_Content_16 = {
    Text = "Bienvenido/a a mi laberinto."
  },
  AvgDialog_18766_Content_17 = {
    Text = "Estabas durmiendo tan profundamente. Estaba a punto de darte de comer unos bichitos para animarte."
  },
  AvgDialog_18766_Content_18 = {
    Text = "<LightGray: Agrippa...?>"
  },
  AvgDialog_18766_Content_19 = {
    Text = "Miras hacia abajo la ropa desconocida que llevas puesta y te das cuenta de que has entrado a Soñar una vez más."
  },
  AvgDialog_18766_Content_2 = {
    Text = "La gente dice que en el laberinto de \"Él\", no es solo tu sentido de la orientación lo que se pierde."
  },
  AvgDialog_18766_Content_20 = {
    Text = "Lo diferente es que esta vez Casi has perdido todos los recuerdos de la huésped original.\n¿Quién es Ella? ¿De dónde vino Ella?"
  },
  AvgDialog_18766_Content_21 = {
    Text = "No sabes nada."
  },
  AvgDialog_18766_Content_22 = {
    Text = "<Shake:Qué está pasando... La huésped original, no, quién soy yo...>"
  },
  AvgDialog_18766_Content_23 = {
    Text = "Bien, deja de pensar. No vas a recordar nada."
  },
  AvgDialog_18766_Content_24 = {
    Text = "Incluso después de 1 día, 100 días, 1000 días, tu mente seguirá tan limpia como la de un bebé recién nacido."
  },
  AvgDialog_18766_Content_25 = {
    Text = "Ahora te daré dos opciones."
  },
  AvgDialog_18766_Content_26 = {
    Text = "<Red:Una: Firma un contrato conmigo y conviértete en mi descendiente.>"
  },
  AvgDialog_18766_Content_27 = {
    Text = "<Red:Dos: Muere de hambre en el laberinto y luego conviértete en mi descendiente.>"
  },
  AvgDialog_18766_Content_28 = {
    Text = "Agrippa expuso hábilmente la situación y te presentó las opciones, como si esta rutina ya se hubiera repetido incontables veces."
  },
  AvgDialog_18766_Content_29 = {
    Text = "¿Descendencia? ¿Qué es eso?"
  },
  AvgDialog_18766_Content_3 = {
    Text = "Tu nombre, tu tierra natal, tu ser amado... todo lo importante y lo que no, todo quedará atrás."
  },
  AvgDialog_18766_Content_30 = {
    Text = "Relájate. Sin veneno, sin dolor, sin daño. ¿Efectos secundarios? Ni siquiera notarás que existen."
  },
  AvgDialog_18766_Content_31 = {
    Text = "Entonces, comparado con esos dioses malvados que constantemente te exigen que ofrezcas tu vida o que mates a tus seres queridos, ¿no crees que soy mucho más amable?"
  },
  AvgDialog_18766_Content_32 = {Text = "..."},
  AvgDialog_18766_Content_33 = {
    Text = "Ahora te daré tres segundos para que tomes tu decisión. ¿Firmar el pacto o morir de hambre?"
  },
  AvgDialog_18766_Content_34 = {Text = "Tres—"},
  AvgDialog_18766_Content_35 = {Text = "Dos—"},
  AvgDialog_18766_Content_36 = {
    Text = "Bien, ya me he decidido."
  },
  AvgDialog_18766_Content_37 = {Text = "Uh...?"},
  AvgDialog_18766_Content_38 = {
    Text = "Decisiva. No eres... nada mal. Entonces dime tu elección."
  },
  AvgDialog_18766_Content_39 = {
    Text = "Asientes, desplazando silenciosamente tu pie derecho hacia atrás una corta distancia."
  },
  AvgDialog_18766_Content_4 = {
    Text = "Desde entonces, Solo tienes una identidad: <Red:Su progenie>."
  },
  AvgDialog_18766_Content_40 = {
    Text = "Mi elección es—"
  },
  AvgDialog_18766_Content_41 = {
    Text = "Giras sobre ti misma sin dudarlo y sales corriendo a toda velocidad."
  },
  AvgDialog_18766_Content_42 = {
    Text = "<BigShake:¡Corre!!>"
  },
  AvgDialog_18766_Content_43 = {
    Text = "Mucho, mucho tiempo Después..."
  },
  AvgDialog_18766_Content_44 = {
    Text = "Buf... buf..."
  },
  AvgDialog_18766_Content_45 = {
    Text = "Corres por el largo corredor, hasta que una Puerta bloquea tu Camino."
  },
  AvgDialog_18766_Content_46 = {
    Text = "¿El Museo de cera? Otra vez..."
  },
  AvgDialog_18766_Content_47 = {
    Text = "Si recuerdo correctamente, esta es la 23ª vez que lo veo."
  },
  AvgDialog_18766_Content_48 = {
    Text = "Sí, hay incontables Puertas aquí, que conducen a incontables espacios."
  },
  AvgDialog_18766_Content_49 = {
    Text = "Aparecen ante ti una y otra vez, con tal frecuencia que bastaría para volver loco incluso al Investigador más sereno."
  },
  AvgDialog_18766_Content_5 = {
    Text = "<Shake:¿P–progenie?>"
  },
  AvgDialog_18766_Content_50 = {
    Text = "Empujas la Puerta para abrirla y continúas por el corredor."
  },
  AvgDialog_18766_Content_51 = {
    Text = "Este corredor otra vez... 15 veces."
  },
  AvgDialog_18766_Content_52 = {
    Text = "Instintivamente tocas los Cufflinks de plata incrustados en tu manga."
  },
  AvgDialog_18766_Content_53 = {
    Text = "Un viejo emblema escolar de Misaq... ¿Así que esta vez me he convertido en una estudiante veterana del pasado?"
  },
  AvgDialog_18766_Content_54 = {
    Text = "Pero, ¿cómo entró ella en el laberinto?"
  },
  AvgDialog_18766_Content_55 = {
    Text = "Mientras reflexionas, otra Puerta más bloquea tu Camino."
  },
  AvgDialog_18766_Content_56 = {
    Text = "Estás frente a esta Puerta ahora, @1. Ábrela."
  },
  AvgDialog_18766_Content_57 = {
    Text = "¿Quién está hablando?!"
  },
  AvgDialog_18766_Content_58 = {
    Text = "Cabeza... duele. ¿Son estos los recuerdos de Senpai?"
  },
  AvgDialog_18766_Content_59 = {
    Text = "Respira hondo, %player%. Despeja tu mente..."
  },
  AvgDialog_18766_Content_6 = {
    Text = "Sí. Innumerables progenies, como una marea pálida, irrumpen en el laberinto desde todas las direcciones."
  },
  AvgDialog_18766_Content_60 = {
    Text = "Te obligas a calmarte, giras la manija de latón y abres la Puerta suavemente."
  },
  AvgDialog_18766_Content_61 = {
    Text = "...¿Keygrave?"
  },
  AvgDialog_18766_Content_62 = {
    Text = "A través de la niebla arremolinada, distingues una figura tanto familiar como extraña."
  },
  AvgDialog_18766_Content_63 = {
    Text = "Charlotte... <Big:¡Charlotte!>"
  },
  AvgDialog_18766_Content_64 = {
    Text = "Recuerdas a la niña llamada Charlotte. Era la amiga que llevó a \"ti\" al laberinto."
  },
  AvgDialog_18766_Content_65 = {
    Text = "<Big:¡Espera por mí, Charlotte!>"
  },
  AvgDialog_18766_Content_66 = {
    Text = "Corres hacia adelante y agarras a Charlotte por la muñeca."
  },
  AvgDialog_18766_Content_67 = {
    Text = "En el instante en que tu piel toca la suya, innumerables fragmentos caóticos destellan en tu mente."
  },
  AvgDialog_18766_Content_68 = {
    Text = "Abre la Puerta, @1."
  },
  AvgDialog_18766_Content_69 = {
    Text = "<Shake:No, yo— Acabo de recordar que no terminé mi tarea, quiero—>"
  },
  AvgDialog_18766_Content_7 = {
    Text = "Los pasajes hacia el laberinto están por todas partes. En las paredes, en las alcantarillas, y donde estamos ahora..."
  },
  AvgDialog_18766_Content_70 = {
    Text = "<Big:¡¡Aaaaah!!>"
  },
  AvgDialog_18766_Content_71 = {
    Text = "<Shake:Charlotte, tu cara...>"
  },
  AvgDialog_18766_Content_72 = {
    Text = "Puerta... Puerta..."
  },
  AvgDialog_18766_Content_73 = {
    Text = "@1Puerta@2abrir@4"
  },
  AvgDialog_18766_Content_74 = {
    Text = "<RedBig:Abre la Puerta...>"
  },
  AvgDialog_18766_Content_75 = {
    Text = "Así que es eso. Tú eres quien atrajo a \"mí\" al laberinto..."
  },
  AvgDialog_18766_Content_76 = {
    Text = "Instintivamente sueltas la muñeca de Charlotte y retrocedes unos pasos tambaleándote."
  },
  AvgDialog_18766_Content_77 = {
    Text = "La niebla se disipó gradualmente. Charlotte se giró con dificultad y te miró con tristeza."
  },
  AvgDialog_18766_Content_78 = {
    Text = "...@4Puerta@4@1"
  },
  AvgDialog_18766_Content_79 = {
    Text = "—Con esas cuencas huecas y vacías que tiene por ojos."
  },
  AvgDialog_18766_Content_8 = {
    Text = "En una puerta oculta bajo la <Blue:Biblioteca Municipal>."
  },
  AvgDialog_18766_Content_9 = {
    Text = "<Shake:Yo... No puedo creer que un lugar así realmente exista... Todas esas leyendas eran ciertas...>"
  },
  AvgDialog_18767_Content_1 = {
    Text = "El final del laberinto"
  },
  AvgDialog_18767_Content_10 = {
    Text = "Shh... Cierra los ojos, despeja tu mente, no pienses en nada."
  },
  AvgDialog_18767_Content_11 = {
    Text = "No hagas nada..."
  },
  AvgDialog_18767_Content_12 = {Text = "¡UUGHH!"},
  AvgDialog_18767_Content_13 = {
    Text = "Mi cabeza está a punto de partirse... Mejor no usar este método muy seguido..."
  },
  AvgDialog_18767_Content_14 = {
    Text = "<Shake:¡Fuera del camino, todos fuera de mi camino!>"
  },
  AvgDialog_18767_Content_15 = {
    Text = "Quien se atreva a tocar a mi familia... ¡¡primero mataré a este cerdo!!"
  },
  AvgDialog_18767_Content_16 = {
    Text = "Una Cuchilla temblorosa se presiona contra tu garganta."
  },
  AvgDialog_18767_Content_17 = {Text = "......¿?"},
  AvgDialog_18767_Content_18 = {
    Text = "Soñar exitoso— aunque no exactamente la entrada que habías imaginado."
  },
  AvgDialog_18767_Content_19 = {
    Text = "Delante se alza una multitud de esclavos con el torso desnudo. Su habitual sumisión ha desaparecido hace mucho, sus ojos brillan con odio."
  },
  AvgDialog_18767_Content_2 = {
    Text = "¿Quieres decir que puedes sumergirte en mi consciencia y cambiar el pasado?"
  },
  AvgDialog_18767_Content_20 = {
    Text = "Ante la amenaza de Agrippa, guardan silencio al principio, luego estallan en una Explosión de carcajadas."
  },
  AvgDialog_18767_Content_21 = {
    Text = "Pfft. ¡Jajajajajajaja!"
  },
  AvgDialog_18767_Content_22 = {
    Text = "Vaya, vaya, ¡nuestra pequeña Princesa sí que tiene agallas!"
  },
  AvgDialog_18767_Content_23 = {
    Text = "Je. No me creen, ¿ver..."
  },
  AvgDialog_18767_Content_24 = {
    Text = "La Cuchilla corta rápidamente, y un dolor abrasador recorre tu cuello."
  },
  AvgDialog_18767_Content_25 = {
    Text = "¡Ngh! ¡¡Lo dices en serio!!"
  },
  AvgDialog_18767_Content_26 = {
    Text = "<Big:¡¡Cállense!!> ¡Tú y ellos— están todos juntos en esto! ¡Tú eres quien robó la llave de mi familia y los contratos de servidumbre!"
  },
  AvgDialog_18767_Content_27 = {Text = "......?"},
  AvgDialog_18767_Content_28 = {
    Text = "¡Y todos ustedes! Si alguien se ríe de nuevo, ¡haré otro corte en el cuello de {Male=his,Female=her}!"
  },
  AvgDialog_18767_Content_29 = {
    Text = "Baja el cuchillo, Agrippa... <Big:¡Correr!>"
  },
  AvgDialog_18767_Content_3 = {
    Text = "Si realmente tuvieras ese tipo de poder, ¿cómo podría haberte atrapado?"
  },
  AvgDialog_18767_Content_31 = {
    Text = "El látigo azotó con saña a la mujer. Antes de que pudiera emitir un sonido, cayó inconsciente."
  },
  AvgDialog_18767_Content_32 = {
    Text = "<Big:¡Madre!!>"
  },
  AvgDialog_18767_Content_33 = {
    Text = "Deja esa ridícula actuación tuya. Ya no somos tus esclavos."
  },
  AvgDialog_18767_Content_34 = {
    Text = "Cuando te pavoneabas sobre nosotros en los campos de entrenamiento, ¿por qué no pensaste en el día de hoy?"
  },
  AvgDialog_18767_Content_35 = {
    Text = "Abre los ojos y mira bien, \"pequeña Princesa.\" Mira cómo te humillamos..."
  },
  AvgDialog_18767_Content_36 = {
    Text = "<Shake:¡Cobardes, todos sois unos cobardes! Cómo os atrevéis...>"
  },
  AvgDialog_18767_Content_37 = {
    Text = "<Shake:Quien os maltrataba era yo, no ellas... No, fui demasiado estúpida. No debería haberos tratado así...>"
  },
  AvgDialog_18767_Content_38 = {
    Text = "<Shake:¡Venid a por mí, haced lo que queráis! Solo dejéis ir a mi madre...>"
  },
  AvgDialog_18767_Content_39 = {
    Text = "La niña ya estaba tan aterrorizada que sus palabras salían incoherentes. La daga en su mano temblaba violentamente, Casi cayéndose al suelo."
  },
  AvgDialog_18767_Content_4 = {
    Text = "Ahem... Para ser precisos, es influencia, no cambio."
  },
  AvgDialog_18767_Content_40 = {
    Text = "Dejaste escapar un suave suspiro y con delicadeza le quitaste la daga de la mano."
  },
  AvgDialog_18767_Content_41 = {
    Text = "¡No tengas miedo, Agrippa! Te ayudaré."
  },
  AvgDialog_18767_Content_42 = {
    Text = "¿Ayúdame? ¿No eres tú...?"
  },
  AvgDialog_18767_Content_43 = {
    Text = "Te pusiste frente a Agrippa, mirando a Los esclavos directamente a los ojos."
  },
  AvgDialog_18767_Content_44 = {
    Text = "Muy bien, el Tiempo de juego se acabó.\nYa habéis conseguido lo que queríais. Ahora podéis iros."
  },
  AvgDialog_18767_Content_45 = {
    Text = "Oh, alguien se las da de jefe ahora, dándonos lecciones y todo."
  },
  AvgDialog_18767_Content_46 = {
    Text = "Cres, ¿no se supone que estás de nuestro lado?"
  },
  AvgDialog_18767_Content_47 = {
    Text = "Sacudes la cabeza."
  },
  AvgDialog_18767_Content_48 = {
    Text = "Siempre he respetado vuestra causa para la rebelión, pero nadie tiene derecho a masacrar a los inocentes."
  },
  AvgDialog_18767_Content_49 = {
    Text = "\"¿Inocente\"...?\""
  },
  AvgDialog_18767_Content_5 = {
    Text = "No te subestimes. Tu laberinto es mucho más complejo de lo que esperaba..."
  },
  AvgDialog_18767_Content_50 = {
    Text = "Ja, este tipo nos ha traicionado por completo. Para qué perder más palabras con él."
  },
  AvgDialog_18767_Content_51 = {
    Text = "<Big:¡Mátalo!>"
  },
  AvgDialog_18767_Content_6 = {
    Text = "Agrippa te mira con suspicacia."
  },
  AvgDialog_18767_Content_7 = {
    Text = "Olvídalo, no es como si hubiera otra forma.\n¿Qué necesitas que haga?"
  },
  AvgDialog_18767_Content_8 = {
    Text = "Te esfuerzas por recordar tu Estado cada vez que entraste a Soñar, y tomas suavemente la mano de Agrippa."
  },
  AvgDialog_18767_Content_9 = {
    Text = "¡Oye, tú... no estarás intentando aprovecharte de mí, ¿verdad?"
  },
  AvgDialog_18768_Content_1 = {
    Text = "Tos... Tos..."
  },
  AvgDialog_18768_Content_10 = {
    Text = "El sonido grave de los cuernos resuena tenuemente desde la distancia—aún no habéis logrado escapar de la Caza del ejército rebelde."
  },
  AvgDialog_18768_Content_11 = {
    Text = "Agrippa y tú corréis de la mano bajo el cielo negro como la brea."
  },
  AvgDialog_18768_Content_12 = {
    Text = "La familia de Ella no está lejos de vosotros. Todos, impulsados tanto por el miedo como por la esperanza, corren hacia un horizonte sin fin a la vista."
  },
  AvgDialog_18768_Content_13 = {
    Text = "¿Quién eres tú? ¿Por qué me salvaste?"
  },
  AvgDialog_18768_Content_14 = {
    Text = "Hmm... para ser preciso, lo hice para salvarme a mí mismo."
  },
  AvgDialog_18768_Content_15 = {
    Text = "Oh... sin importar la razón, eres... una buena persona."
  },
  AvgDialog_18768_Content_16 = {
    Text = "Una vez que nos rescaten, te daré todo el dinero y las joyas que he guardado en secreto a lo largo de los años."
  },
  AvgDialog_18768_Content_17 = {
    Text = "No puedes evitar reírte."
  },
  AvgDialog_18768_Content_18 = {
    Text = "No necesito tu dinero. Pero... si quieres corresponderme, tengo una petición."
  },
  AvgDialog_18768_Content_19 = {
    Text = "Dime—lo haré realidad, sin importar qué sea."
  },
  AvgDialog_18768_Content_2 = {
    Text = "Por respeto a los viejos tiempos, los hermanos se contuvieron hace un momento."
  },
  AvgDialog_18768_Content_20 = {
    Text = "Una estrella fugaz surca el cielo nocturno—es el momento perfecto para pedir un deseo."
  },
  AvgDialog_18768_Content_21 = {
    Text = "Mi petición es sencilla. Sigue sonriendo y recuerda cómo te sientes ahora mismo."
  },
  AvgDialog_18768_Content_22 = {
    Text = "¿Cómo me siento ahora mismo? Hmm... ¿Feliz, aliviada, preocupada? ¡¿A cuál te refieres?!"
  },
  AvgDialog_18768_Content_23 = {
    Text = "Sigue a tu corazón. Tengo curiosidad por saber a qué Agrippa me llevarán."
  },
  AvgDialog_18768_Content_24 = {Text = "¿Qué?"},
  AvgDialog_18768_Content_25 = {
    Text = "<SmallShake:Puede que este tipo sea buena persona, pero su forma de hablar es realmente extraña...>"
  },
  AvgDialog_18768_Content_26 = {
    Text = "El sonido del cuerno finalmente se desvaneció, y la tranquilidad de la noche regresó una vez más."
  },
  AvgDialog_18768_Content_27 = {
    Text = "Finalmente... se acabó."
  },
  AvgDialog_18768_Content_28 = {
    Text = "La doncella corrió hasta la cima de la duna de arena en unos pocos pasos rápidos, apretó los puños y gritó hacia donde el cuerno había desaparecido."
  },
  AvgDialog_18768_Content_29 = {
    Text = "¡Apuesto a que no te esperabas esto, @2, soy yo quien sobrevivió hasta el final!"
  },
  AvgDialog_18768_Content_3 = {
    Text = "Ya que insistes en ayudarlos, no nos culpes por no mostrar piedad—"
  },
  AvgDialog_18768_Content_30 = {
    Text = "¡Jajajajajaja, @2!"
  },
  AvgDialog_18768_Content_31 = {
    Text = "<Shake:¡Agrippa! Sé una dama, una dama...!>"
  },
  AvgDialog_18768_Content_32 = {
    Text = "¡¡¡No te oigo!!!"
  },
  AvgDialog_18768_Content_33 = {
    Text = "¡¡Al diablo con ser una dama y toda esa etiqueta, por fin soy libre!!"
  },
  AvgDialog_18768_Content_34 = {
    Text = "Con esa rotunda declaración, la doncella extendió los brazos de par en par, como si acunara entre sus manos el magnífico cielo estrellado sobre ella."
  },
  AvgDialog_18768_Content_35 = {
    Text = "<Big:¡¡Soy libre—!!>"
  },
  AvgDialog_18768_Content_36 = {
    Text = "¡¡CRASH—!!"
  },
  AvgDialog_18768_Content_37 = {Text = "...¿Eh?"},
  AvgDialog_18768_Content_38 = {
    Text = "El cielo desapareció, y el laberinto desapareció con él."
  },
  AvgDialog_18768_Content_39 = {
    Text = "El Cañón Cámbrico irrumpió de lleno en tu campo de visión."
  },
  AvgDialog_18768_Content_4 = {Text = "¡CRASH!"},
  AvgDialog_18768_Content_40 = {
    Text = "Las aguas profundas del lago, semejantes a un espejo, fluían en quieta calma, mientras el viento abría la superficie, enviando anillos de ondas resplandecientes."
  },
  AvgDialog_18768_Content_41 = {
    Text = "Agrippa se sentó aturdida sobre la hierba, contemplando con la mirada perdida todo lo que tenía ante ella."
  },
  AvgDialog_18768_Content_42 = {
    Text = "%player%, ¿hemos... salido?"
  },
  AvgDialog_18768_Content_43 = {
    Text = "Bienvenido de nuevo al mundo real, Agrippa."
  },
  AvgDialog_18768_Content_44 = {Text = "...Oh."},
  AvgDialog_18768_Content_45 = {
    Text = "Así que este es el valle del río. Es cien veces más hermoso de lo que dicen... no, mil veces más hermoso."
  },
  AvgDialog_18768_Content_46 = {
    Text = "Una tenue luz matutina atraviesa la niebla y cae sobre ti."
  },
  AvgDialog_18768_Content_47 = {
    Text = "Agrippa cierra los ojos, saboreando con avidez los aromas que tanto había echado de menos."
  },
  AvgDialog_18768_Content_48 = {
    Text = "Puedo oler tantas cosas. Tierra, hierba, fresias y luz del sol..."
  },
  AvgDialog_18768_Content_49 = {
    Text = "¿La luz del sol también tiene olor?"
  },
  AvgDialog_18768_Content_5 = {
    Text = "Aprovechando el caos, empujas el pilar que bloquea el camino y todo el edificio comienza a tambalearse al borde inestable del derrumbe."
  },
  AvgDialog_18768_Content_50 = {
    Text = "Ajá. El tipo de olor que te da somnolencia."
  },
  AvgDialog_18768_Content_51 = {
    Text = "Gracias, %player%."
  },
  AvgDialog_18768_Content_52 = {
    Text = "Se estira perezosamente y comienza a tararear suavemente una antigua balada romana."
  },
  AvgDialog_18768_Content_53 = {
    Text = "La ligera melodía se eleva en espiral por el aire, llevando el buen humor de su cantante a cada rincón del valle del río."
  },
  AvgDialog_18768_Content_54 = {
    Text = "Después de más de mil años, por fin ha vuelto a ver la luz del sol."
  },
  AvgDialog_18768_Content_55 = {
    Text = "Y por fin ha visto el valle del río por primera vez."
  },
  AvgDialog_18768_Content_6 = {
    Text = "¡Esta es nuestra oportunidad, seguidme, rápido!"
  },
  AvgDialog_18768_Content_7 = {
    Text = "Agarras la mano de Agrippa y huyes apresuradamente con la familia de Ella."
  },
  AvgDialog_18768_Content_8 = {
    Text = "El otrora glorioso patio se derrumba como una bestia silenciosa que se desploma contra el suelo."
  },
  AvgDialog_18768_Content_9 = {
    Text = "16@1 años antes del Desbordamiento, afueras de Capua"
  },
  AvgDialog_18769_Content_1 = {
    Text = "Barrera de Recuerdos"
  },
  AvgDialog_18769_Content_10 = {
    Text = "Qué acabas@1 de decir—"
  },
  AvgDialog_18769_Content_11 = {
    Text = "Déjalo, no te metas con ese tipo. Es un lunático..."
  },
  AvgDialog_18769_Content_12 = {
    Text = "Los esclavos se empujaron unos a otros mientras se marchaban, y la oscura celda finalmente quedó en silencio."
  },
  AvgDialog_18769_Content_13 = {
    Text = "La niña emergió de las sombras en la esquina de la celda, con la cabeza gacha."
  },
  AvgDialog_18769_Content_14 = {
    Text = "¿Por qué no te fuiste con ellos? Esta noche sería una oportunidad perfecta para recuperar tu libertad."
  },
  AvgDialog_18769_Content_15 = {
    Text = "Me gusta estar aquí. ¿Por qué me iría?"
  },
  AvgDialog_18769_Content_16 = {
    Text = "¿Te gusta...? Jaja, qué notable. ¿Te gusta que te insulten, o te gusta que te azote con mi látigo?"
  },
  AvgDialog_18769_Content_17 = {
    Text = "Gladiador bostezó y estiró sus extremidades cómodamente."
  },
  AvgDialog_18769_Content_18 = {
    Text = "Me gusta la Sangre, y matar me gusta aún más. Para mí, matar es libertad."
  },
  AvgDialog_18769_Content_19 = {
    Text = "En cuanto al título de esclavo, no me importa cuántos me pongan. ¿Por qué me iría?"
  },
  AvgDialog_18769_Content_2 = {
    Text = "16 años antes del Desbordamiento@1, Capua"
  },
  AvgDialog_18769_Content_20 = {Text = "..."},
  AvgDialog_18769_Content_21 = {
    Text = "Je... Ahora sí que empiezo a verte con otros ojos. Eres un auténtico lunático."
  },
  AvgDialog_18769_Content_22 = {
    Text = "Agrippa alzó la mirada hacia la salida de la mazmorra, con una expresión perfectamente serena."
  },
  AvgDialog_18769_Content_23 = {
    Text = "Olas carmesíes de fuego se elevaban hacia el cielo. Risas, llantos, gritos... toda clase de sonidos se congregaban, componiendo una sinfonía del infierno."
  },
  AvgDialog_18769_Content_24 = {
    Text = "Pronto me encontrarán,@1 a mí, y luego me cortarán la cabeza, igual que hicieron con mis padres."
  },
  AvgDialog_18769_Content_25 = {
    Text = "No quiero a estas criaturas despreciables cerca de mí. Pero tú..."
  },
  AvgDialog_18769_Content_26 = {
    Text = "Eres diferente a ellos.\nSé que hemos tenido \"mala sangre\" entre nosotros, pero esta vez seguramente no rechazarás mi petición."
  },
  AvgDialog_18769_Content_27 = {
    Text = "¿Oh? Veamos qué es."
  },
  AvgDialog_18769_Content_28 = {Text = "..."},
  AvgDialog_18769_Content_29 = {Text = "Mátame."},
  AvgDialog_18769_Content_3 = {
    Text = "Maldición, esa mujer se ha ido."
  },
  AvgDialog_18769_Content_30 = {
    Text = "<RedBig:Mátame...>"
  },
  AvgDialog_18769_Content_31 = {
    Text = "Agrippa...?"
  },
  AvgDialog_18769_Content_32 = {
    Text = "<RedBig:Mátame mátame mátame mátame mátame mátame mátame mátame...>"
  },
  AvgDialog_18769_Content_33 = {Text = "¡Agrippa!"},
  AvgDialog_18769_Content_34 = {Text = "¡¡!!"},
  AvgDialog_18769_Content_35 = {
    Text = "<Shake:Ugh...>"
  },
  AvgDialog_18769_Content_36 = {
    Text = "Tuve un Sueño muy, muy largo..."
  },
  AvgDialog_18769_Content_37 = {
    Text = "Escucha, parece que pasamos por alto algunas preguntas antes."
  },
  AvgDialog_18769_Content_38 = {
    Text = "¡Tonterías! Soy el Señor del laberinto—todo está bajo mi control—"
  },
  AvgDialog_18769_Content_39 = {
    Text = "Primero, ¿por qué tu descendencia puede entrar y salir libremente del laberinto, pero tú y yo no podemos?"
  },
  AvgDialog_18769_Content_4 = {
    Text = "Je, je. ¿Así que ahora sabe esconderse? Cuando la encontremos, le cortaremos las piernas primero..."
  },
  AvgDialog_18769_Content_40 = {
    Text = "¿Acaso no comparten una consciencia colectiva?"
  },
  AvgDialog_18769_Content_41 = {
    Text = "¿Qué sabrás tú? Como Señor del laberinto, debo mantener un aura de misterio en todo momento."
  },
  AvgDialog_18769_Content_42 = {
    Text = "Además, Solo yo quiera, todos tienen que arrastrarse obedientemente de vuelta. ¿Cómo es eso \"entrar y salir libremente\"?"
  },
  AvgDialog_18769_Content_43 = {
    Text = "Asientes y luego sacas el cuaderno que llevas en la mano."
  },
  AvgDialog_18769_Content_44 = {
    Text = "Hay una pregunta más."
  },
  AvgDialog_18769_Content_45 = {
    Text = "Llevé un Registro de todos los lugares que encontré en el laberinto—la escuela, el Museo de cera, las calles de Londinium..."
  },
  AvgDialog_18769_Content_46 = {
    Text = "Pero ninguno de los lugares que has Experimentado estaba allí. Ni uno solo."
  },
  AvgDialog_18769_Content_47 = {
    Text = "¿Por qué? ¿Acaso no estás atrapado aquí también?"
  },
  AvgDialog_18769_Content_48 = {
    Text = "¡Tantas preguntas! Porque este gran rey no quiere rememorar, ¿para qué molestarse pensando en cosas desagradables?"
  },
  AvgDialog_18769_Content_49 = {
    Text = "Sí, <Yellow:no quieres recordar>."
  },
  AvgDialog_18769_Content_5 = {
    Text = "Hola, Uvhash, ¿has visto a Agrippa?"
  },
  AvgDialog_18769_Content_50 = {
    Text = "¿Es posible que...?"
  },
  AvgDialog_18769_Content_51 = {
    Text = "Es precisamente porque tú —la Señor del laberinto— rechazas compartir la consciencia que este laberinto, formado a partir de la consciencia de quienes están atrapados en él, permanecerá incompleto para siempre."
  },
  AvgDialog_18769_Content_52 = {
    Text = "Así que nunca podremos encontrar la salida."
  },
  AvgDialog_18769_Content_53 = {Text = "..."},
  AvgDialog_18769_Content_54 = {
    Text = "Las preguntas que planteas... yo también pensé en ellas en su momento. Después de todo, este es mi laberinto."
  },
  AvgDialog_18769_Content_55 = {
    Text = "Pero en el momento en que pienso en el pasado, me vuelve completamente loca..."
  },
  AvgDialog_18769_Content_56 = {
    Text = "Agrippa se agarró la cabeza, las palabras brotando rápidamente de sus labios como murmullos en un sueño."
  },
  AvgDialog_18769_Content_57 = {
    Text = "Esas alimañas despreciables... cómo se atrevieron a hacerme eso..."
  },
  AvgDialog_18769_Content_58 = {
    Text = "No eran más que esclavos, apenas humanos. Merecían ser pisoteados bajo nuestros pies por toda la eternidad."
  },
  AvgDialog_18769_Content_59 = {
    Text = "¿Rebelión? Qué fantasía."
  },
  AvgDialog_18769_Content_6 = {
    Text = "El Gladiador en las sombras abrió lentamente los ojos."
  },
  AvgDialog_18769_Content_60 = {
    Text = "Pero no solo lo hicieron, sino que colgaron las cabezas de mis padres en las murallas de la ciudad, me agarraron del pelo y me obligaron a mirar de cerca, con detenimiento, sin permitirme perder un solo detalle."
  },
  AvgDialog_18769_Content_61 = {
    Text = "Y luego mi hermana pequeña, Julia. Cuando la encontré, todo su cuerpo@3, y era aún tan joven..."
  },
  AvgDialog_18769_Content_62 = {
    Text = "Qué ridículo... ¿Crees que lloré?"
  },
  AvgDialog_18769_Content_63 = {
    Text = "No, jamás. Preferiría morir antes que derramar una sola lágrima frente a ellos."
  },
  AvgDialog_18769_Content_64 = {
    Text = "Somos descendientes del Lobo Gris. Morimos con dignidad, como verdaderos lobos. Esos mestizos nunca lo entenderán en toda su vida."
  },
  AvgDialog_18769_Content_65 = {
    Text = "Jajajaja..."
  },
  AvgDialog_18769_Content_66 = {
    Text = "Agrippa se agarró el estómago, riendo tan fuerte que las lágrimas le corrían por el rostro."
  },
  AvgDialog_18769_Content_67 = {
    Text = "Debieron quedar tan decepcionados cuando vieron mi cadáver... Jajaja..."
  },
  AvgDialog_18769_Content_68 = {
    Text = "¿Agrippa...? ¡Agrippa!"
  },
  AvgDialog_18769_Content_69 = {
    Text = "Agarras con fuerza los hombros de Agrippa, intentando traerla de vuelta de la Pesadilla del pasado."
  },
  AvgDialog_18769_Content_7 = {
    Text = "...Lárgate."
  },
  AvgDialog_18769_Content_70 = {
    Text = "Para. Todo eso ya quedó en el pasado."
  },
  AvgDialog_18769_Content_71 = {Text = "..."},
  AvgDialog_18769_Content_72 = {
    Text = "Lo siento, Agrippa. No lo sabía antes... Dejemos que esas cosas desagradables se queden en el pasado."
  },
  AvgDialog_18769_Content_73 = {
    Text = "Después de todo, eres la Señor del laberinto. Nada puede hacerte daño de verdad."
  },
  AvgDialog_18769_Content_74 = {Text = "...Mm."},
  AvgDialog_18769_Content_75 = {
    Text = "Agrippa cae en un silencio poco habitual. Parece que aún no ha salido de las sombras del pasado."
  },
  AvgDialog_18769_Content_76 = {
    Text = "<LightGray:Si tan solo pudiera cambiar el pasado de verdad... Así podría ayudarla y encontrar una salida a esta situación.>"
  },
  AvgDialog_18769_Content_77 = {
    Text = "<LightGray:No, no te rindas todavía. Piensa en otra forma...>"
  },
  AvgDialog_18769_Content_78 = {
    Text = "Buscas desesperadamente entre tus recuerdos fragmentados cualquier información que pueda ser útil."
  },
  AvgDialog_18769_Content_79 = {
    Text = "Soñar no puede cambiar el pasado, pero puede influir en el futuro. Por eso, durante Soñar, el Guardián debe aprender a ejercer el Contrataque."
  },
  AvgDialog_18769_Content_8 = {
    Text = "Je je, todos los hermanos luchan por la gran causa, y solo tú estás dispuesto a quedarte atrás y seguir siendo un perro."
  },
  AvgDialog_18769_Content_80 = {
    Text = "¿Influir en el futuro?"
  },
  AvgDialog_18769_Content_81 = {
    Text = "Para decirlo de forma sencilla, la memoria de una persona es como un lago tranquilo."
  },
  AvgDialog_18769_Content_82 = {
    Text = "Soñar es como lanzar una piedra Dentro—las ondas que crea pronto se desvanecerán."
  },
  AvgDialog_18769_Content_83 = {
    Text = "Pero la piedra permanece."
  },
  AvgDialog_18769_Content_84 = {
    Text = "Exacto. Incluso si la persona que fue sometida a Soñar no recuerda nada al despertar..."
  },
  AvgDialog_18769_Content_85 = {
    Text = "Esa piedra se hundirá para siempre en su subconsciente, influyendo en su presente."
  },
  AvgDialog_18769_Content_86 = {Text = "¡¡¡!!"},
  AvgDialog_18769_Content_87 = {
    Text = "Agrippa, sé cómo salir."
  },
  AvgDialog_18769_Content_9 = {
    Text = "He dicho que te largues. ¿No entiendes?"
  },
  AvgDialog_18770_Content_1 = {Text = "Su Reino"},
  AvgDialog_18770_Content_10 = {
    Text = "¡Es inútil, completamente inútil! Cuando estaban atrapados en el laberinto, también había personas brillantes como matemáticos, ¿sabes?"
  },
  AvgDialog_18770_Content_11 = {
    Text = "Si ni siquiera ellos pudieron resolver este enigma, ni te molestes en intentarlo."
  },
  AvgDialog_18770_Content_12 = {
    Text = "En mi opinión, ya que ninguna de las dos puede matar a la otra, bien podríamos llevarnos bien."
  },
  AvgDialog_18770_Content_13 = {
    Text = "¡Charlamos! O jugamos a las cartas. ¿Qué juegos de cartas conoces?"
  },
  AvgDialog_18770_Content_14 = {
    Text = "Que no te engañe el hecho de que haya estado atrapada bajo tierra—he desarrollado unas habilidades increíbles con las cartas. ¡Nadie puede ganarme!"
  },
  AvgDialog_18770_Content_15 = {
    Text = "Tenías que admitir que sus palabras fueron una especie de golpe para ti."
  },
  AvgDialog_18770_Content_16 = {
    Text = "Si nadie ha podido descifrar este laberinto después de tantos años, ¿qué te hace pensar que tú podrás?"
  },
  AvgDialog_18770_Content_17 = {
    Text = "Desde luego, no tienes una mente tan aguda como la de Ramona."
  },
  AvgDialog_18770_Content_18 = {
    Text = "Con ese pensamiento, te desplomas de bruces sobre la suave almohada."
  },
  AvgDialog_18770_Content_19 = {
    Text = "No se me dan muy bien las cartas. Mejor charlemos.\n¿Cómo acabaste atrapada en este laberinto?"
  },
  AvgDialog_18770_Content_2 = {
    Text = "39, 40, 41..."
  },
  AvgDialog_18770_Content_20 = {Text = "Er..."},
  AvgDialog_18770_Content_21 = {
    Text = "Como si no hubiera anticipado esta pregunta, los ojos compuestos que rotaban sin cesar dentro de las cuencas oculares de la niña se congelaron todos colectivamente por un instante."
  },
  AvgDialog_18770_Content_22 = {
    Text = "Tú eres la que dijo que debíamos llevarnos bien. Pues entonces, ser honestas la una con la otra es el primer paso."
  },
  AvgDialog_18770_Content_23 = {
    Text = "Está bien, hablaré, hablaré...! De todas formas, es una historia cliché."
  },
  AvgDialog_18770_Content_24 = {
    Text = "En mis tiempos, mi familia era la más rica de Capua. La fila de esclavos que me seguía cada día se extendía hasta donde alcanzaba la vista..."
  },
  AvgDialog_18770_Content_25 = {
    Text = "Después, esos necios empezaron una revolución, hablando de \"liberación\" y \"libertad\" — cosas que nunca entendí de todas formas."
  },
  AvgDialog_18770_Content_26 = {
    Text = "No quería morir a sus manos, así que hice que un gladiador me matara en su lugar."
  },
  AvgDialog_18770_Content_27 = {
    Text = "Dijo Agrippa, extendiendo las manos hacia ti."
  },
  AvgDialog_18770_Content_28 = {
    Text = "...Cuando desperté, ya estaba aquí."
  },
  AvgDialog_18770_Content_29 = {
    Text = "He oído sobre esta revolución en la clase de Historia. Supuestamente—"
  },
  AvgDialog_18770_Content_3 = {
    Text = "Anotaste apresuradamente el Registro de <Blue:Dormitorio de estudiantes: 41> en el cuaderno que llevaba tu compañero mayor."
  },
  AvgDialog_18770_Content_30 = {
    Text = "No quiero oírlo. ¡Este tema es tan aburrido! Siguiente tema, siguiente tema."
  },
  AvgDialog_18770_Content_31 = {
    Text = "Una hora después..."
  },
  AvgDialog_18770_Content_32 = {
    Text = "La insípida conversación continuó, hasta que Agrippa finalmente recondujo el tema hacia sí misma."
  },
  AvgDialog_18770_Content_33 = {
    Text = "¿Sabes? Hay un millar de vástagos bajo mi mando ahora..."
  },
  AvgDialog_18770_Content_34 = {
    Text = "Pueden ir y venir libremente por el laberinto, recopilando historias de lo que sucede afuera para mí, e incluso traer de vuelta pobres almas aptas para convertirse en nuevos vástagos."
  },
  AvgDialog_18770_Content_35 = {
    Text = "Si no fuera por ellos, habría muerto de aburrimiento hace mucho tiempo."
  },
  AvgDialog_18770_Content_36 = {
    Text = "Mientras escuchas sus quejas divagantes, por alguna razón, una imagen surge en tu mente—"
  },
  AvgDialog_18770_Content_37 = {
    Text = "Un rey anciano apoyado en un bastón, Enredado en un trono pesado y en podredumbre."
  },
  AvgDialog_18770_Content_38 = {
    Text = "Su dominio se extiende sin fin, su poder fuera de toda duda."
  },
  AvgDialog_18770_Content_39 = {
    Text = "Envió a muchos emisarios, haciendo que trajeran historias venido de lejos: gemas verdes de ojo de gato, elefantes perdidos y arcoíris tras la lluvia..."
  },
  AvgDialog_18770_Content_4 = {
    Text = "¡Deja de perder el tiempo con eso y ven a jugar conmigo!"
  },
  AvgDialog_18770_Content_40 = {
    Text = "Cuando los relatos llegaban a sus partes más emocionantes, los emisarios agitaban los brazos con deleite. Pero el rey siempre permanecía en silencio, como una estatua cubierta de musgo."
  },
  AvgDialog_18770_Content_41 = {
    Text = "No podía hacer nada, pues hacía mucho que era incapaz de alejarse de su trono ni medio paso."
  },
  AvgDialog_18770_Content_42 = {
    Text = "Agrippa, has escuchado tantas historias del exterior... ¿Hay algún lugar al que te gustaría ir?"
  },
  AvgDialog_18770_Content_43 = {
    Text = "Un lugar al que me gustaría ir..."
  },
  AvgDialog_18770_Content_44 = {
    Text = "El <Blue:Cañón Cámbrico>, supongo."
  },
  AvgDialog_18770_Content_45 = {
    Text = "Agrippa respondió casi sin vacilar."
  },
  AvgDialog_18770_Content_46 = {
    Text = "Mis descendientes me contaron que el centro de este laberinto parece encontrarse debajo de un valle llamado Cámbrico."
  },
  AvgDialog_18770_Content_47 = {
    Text = "He oído que es un lugar hermoso, con lagos como un espejo."
  },
  AvgDialog_18770_Content_48 = {
    Text = "Cada primavera, unas flores llamadas Freesia florecen por todas partes..."
  },
  AvgDialog_18770_Content_49 = {
    Text = "Agrippa apoyó la barbilla en la mano, contemplando pensativa la distancia."
  },
  AvgDialog_18770_Content_5 = {Text = "..."},
  AvgDialog_18770_Content_50 = {
    Text = "En mi tierra natal también hay un lago hermoso, pero nunca lo he visto."
  },
  AvgDialog_18770_Content_51 = {
    Text = "¿Por qué no vas a verlo?"
  },
  AvgDialog_18770_Content_52 = {
    Text = "Agrippa te lanzó una mirada altiva, alzando su pequeña barbilla puntiaguda."
  },
  AvgDialog_18770_Content_53 = {
    Text = "Soy una dama romana de noble puerta. Una dama no puede simplemente deambular a su antojo."
  },
  AvgDialog_18770_Content_54 = {
    Text = "Así que puedes dar órdenes a muchos esclavos, pero tú misma no eres del todo libre."
  },
  AvgDialog_18770_Content_55 = {
    Text = "Al quedar su realidad al descubierto con tu simple comentario, el rostro de la niña se ensombreció al instante, como una berenjena marchita por la escarcha."
  },
  AvgDialog_18770_Content_56 = {
    Text = "En aquel entonces, yo estaba incluso peor que esos esclavos. Y no digamos ahora..."
  },
  AvgDialog_18770_Content_6 = {
    Text = "Perdona, ¿podrías ponerte otra cara antes de hablarme?"
  },
  AvgDialog_18770_Content_7 = {
    Text = "¡Tch, qué mezquina!"
  },
  AvgDialog_18770_Content_8 = {
    Text = "\"William\" puso los ojos en blanco y luego se desvaneció en el aire con un \"puf\"."
  },
  AvgDialog_18770_Content_9 = {
    Text = "Volviste a enterrar la cabeza en el denso expediente académico que tenías delante, intentando encontrar la manera de descifrar el laberinto."
  },
  AvgDialog_18779_Content_1 = {
    Text = "E-esto... ¿es el embrión?"
  },
  AvgDialog_18779_Content_10 = {
    Text = "¿Está absorbiendo energía de Miriam?!\n¿Otra vez?"
  },
  AvgDialog_18779_Content_11 = {
    Text = "Inútil.\nEstá protegido por la \"placenta\", y la energía de Miriam puede repararla al menos tres veces más"
  },
  AvgDialog_18779_Content_12 = {
    Text = "Para derrotarlo completamente, debemos atacar el núcleo"
  },
  AvgDialog_18779_Content_13 = {Text = "¿Núcleo?"},
  AvgDialog_18779_Content_14 = {
    Text = "El corazón pálido incrustado en el capullo transparente, bajo la luz de la luna, su sombra apenas visible"
  },
  AvgDialog_18779_Content_15 = {
    Text = "¿Es la \"falsificación\" en sí?"
  },
  AvgDialog_18779_Content_16 = {Text = "Sí y no"},
  AvgDialog_18779_Content_17 = {
    Text = "¿Eres... Murphy?"
  },
  AvgDialog_18779_Content_18 = {
    Text = "¡Sí, claro!"
  },
  AvgDialog_18779_Content_19 = {
    Text = "Miria forzó la ceremonia antes de tiempo, pero \"Él\" nació de mentiras y deseos, y su existencia no será reconocida por la realidad antes de que las estrellas alcancen la alineación"
  },
  AvgDialog_18779_Content_2 = {
    Text = "Parece haberse quedado quieto"
  },
  AvgDialog_18779_Content_20 = {
    Text = "Antes de nacer, el núcleo seguía siendo ella"
  },
  AvgDialog_18779_Content_3 = {
    Text = "Aún no ha terminado."
  },
  AvgDialog_18779_Content_4 = {
    Text = "\"El 'corazón' ha dejado de latir, pero el bajo lamento traído por la brisa marina es imposible de ignorar.\""
  },
  AvgDialog_18779_Content_5 = {
    Text = "¿Escucharon un llanto?"
  },
  AvgDialog_18779_Content_6 = {
    Text = "Las olas se elevaban, y el capullo gigante se levantaba del mar con el apoyo de Miriam"
  },
  AvgDialog_18779_Content_7 = {Text = "Sí, así"},
  AvgDialog_18779_Content_8 = {
    Text = "Tomar lo que desees es tu derecho, por tu nacimiento, para castigar a estos no creyentes"
  },
  AvgDialog_18779_Content_9 = {
    Text = "La voz de Miriam se debilitaba, pero la entidad en el capullo dormido se volvía más sólida"
  },
  AvgDialog_18784_Content_10 = {
    Text = "Patético. Solo perder un enlace de Plata te reduce a esto."
  },
  AvgDialog_18784_Content_11 = {
    Text = "El monstruo del globo de pus ignora las burlas hacia Lotan, solo grita y ataca al enemigo"
  },
  AvgDialog_18784_Content_12 = {
    Text = "<Change> Dame... a... mí..."
  },
  AvgDialog_18784_Content_13 = {
    Text = "Si puedo atrapar a esa chica... si puedo convertirme en la gemela santa con ella"
  },
  AvgDialog_18784_Content_14 = {
    Text = "No será abandonada, no lamentará su origen, ni será una pieza manipulada"
  },
  AvgDialog_18784_Content_17 = {
    Text = "<Change>¡Entrégala... a... mí!"
  },
  AvgDialog_18784_Content_18 = {
    Text = "¿Has perdido incluso la capacidad de hablar?"
  },
  AvgDialog_18784_Content_19 = {
    Text = "Si es así, pon tus palabras y sentimientos en tu espada.\n¡Déjame escuchar tu furia!"
  },
  AvgDialog_18784_Content_2 = {
    Text = "<BigShake:¡Rugido——>"
  },
  AvgDialog_18784_Content_3 = {
    Text = "No han avanzado mucho en la oscuridad cuando una criatura viscosa emerge del puente, su enorme cuerpo arrastrando numerosas bolas pegajosas, cayendo de golpe frente a ustedes"
  },
  AvgDialog_18784_Content_4 = {
    Text = "El monstruo levanta la parte superior de su cuerpo, que apenas conserva forma humana, y los mira a ustedes, deteniéndose en la figura de Lily, su expresión poco a poco se vuelve loca"
  },
  AvgDialog_18784_Content_6 = {
    Text = "¡Dámela... a mí!"
  },
  AvgDialog_18784_Content_7 = {
    Text = "Lotan se interpone frente a ustedes, enfrentando con orgullo la mirada del monstruo"
  },
  AvgDialog_18784_Content_8 = {
    Text = "Las cadenas se rompen, el cuerpo se deforma, pero la sucia cara bajo el cabello enmarañado aún revela la identidad del dueño"
  },
  AvgDialog_18784_Content_9 = {
    Text = "¿Eres... Helot...?"
  },
  AvgDialog_18785_Content_1 = {
    Text = "Realidad distorsionada"
  },
  AvgDialog_18785_Content_10 = {
    Text = "A la luz, vio innumerables heridas negras en la piel lisa de la \"madre\""
  },
  AvgDialog_18785_Content_11 = {
    Text = "\"Lo siento...\""
  },
  AvgDialog_18785_Content_12 = {
    Text = "El moco negro se agitaba, rompiendo la calma del fondo"
  },
  AvgDialog_18785_Content_13 = {
    Text = "\"La 'Madre' emitió un grito agudo, sus tentáculos se movieron, insertando algo en el pecho del polluelo.\""
  },
  AvgDialog_18785_Content_14 = {
    Text = "Los tentáculos suaves y fríos la envuelven, el agua negra ya no obstruye su boca y nariz, sino que, como el líquido amniótico, sostiene su vida"
  },
  AvgDialog_18785_Content_15 = {
    Text = [[
<Change>"Lo siento......"
"No quiero...... morir......"]]
  },
  AvgDialog_18785_Content_16 = {
    Text = "La superficie del agua permaneció en calma durante mucho tiempo, ni siquiera el viento polar pudo hacer que el agua espesa formara ondas"
  },
  AvgDialog_18785_Content_17 = {
    Text = "Señora Miriam, ¿la santa ya...?"
  },
  AvgDialog_18785_Content_18 = {
    Text = "Nació en el último momento de alineación estelar, es un \"niño visible.\""
  },
  AvgDialog_18785_Content_19 = {
    Text = "En el mundo, nadie merece más el reconocimiento de la sangre divina que ella"
  },
  AvgDialog_18785_Content_2 = {
    Text = "El pichón con alas rotas cayó en el estanque negro"
  },
  AvgDialog_18785_Content_20 = {
    Text = "La mujer delgada está rodeada, de pie en el punto más alto, mirando a todos.\nUn velo oculta su rostro, ni siquiera sus sirvientes pueden leer sus pensamientos"
  },
  AvgDialog_18785_Content_21 = {Text = "Murphy..."},
  AvgDialog_18785_Content_3 = {
    Text = "Las oraciones del Sumo Sacerdote eran etéreas pero firmes, sus palabras fervientes atravesaron el líquido negro, convirtiéndose en cuchillas que abrieron el pecho del polluelo"
  },
  AvgDialog_18785_Content_4 = {
    Text = "Líquido rojo sube del pecho y se extiende sobre el agua negra"
  },
  AvgDialog_18785_Content_5 = {
    Text = "Pero ella seguía hundiéndose, con raíces ensangrentadas, descendiendo al fondo, a un abrazo suave y frío"
  },
  AvgDialog_18785_Content_6 = {Text = "..."},
  AvgDialog_18785_Content_7 = {Text = "..."},
  AvgDialog_18785_Content_8 = {
    Text = "Lo vio.\nMiró hacia arriba, \"Madre\" bajó sus tres pares de ojos y la miró"
  },
  AvgDialog_18785_Content_9 = {
    Text = "Era una enorme criatura carmesí, con partes transparentes donde la sangre la había manchado. \"Madre\" emitía un débil resplandor, iluminando un pequeño espacio"
  },
  AvgDialog_18786_Content_1 = {
    Text = "Video fundido de entrada"
  },
  AvgDialog_18786_Content_2 = {
    Text = "Video en bucle 1"
  },
  AvgDialog_18786_Content_3 = {
    Text = "Video en bucle 2"
  },
  AvgDialog_18786_Content_4 = {
    Text = "Video desvaneciéndose"
  },
  AvgDialog_18786_Content_5 = {Text = "Nada"},
  AvgDialog_18787_Content_1 = {
    Text = "Pero ahora hay cosas más urgentes"
  },
  AvgDialog_18787_Content_10 = {
    Text = "Esta es la chica que Herbert está rastreando, podría tener pistas para su investigación"
  },
  AvgDialog_18787_Content_11 = {
    Text = "Vamos, ¿qué esperan?\n¿Les gusta dormir al aire libre con los lobos?"
  },
  AvgDialog_18787_Content_12 = {
    Text = "Para acampar al aire libre, siempre estoy listo, pero dudo que soportes, niña delicada"
  },
  AvgDialog_18787_Content_13 = {
    Text = "Lotan le dio una palmadita en el hombro a Ramona, quien mostró una expresión como si hubiera comido una mosca, pero no dijo nada"
  },
  AvgDialog_18787_Content_14 = {
    Text = "La dama del narciso... Suena como una persona generosa y rica, ¿verdad?"
  },
  AvgDialog_18787_Content_2 = {Text = "¿Qué?"},
  AvgDialog_18787_Content_3 = {
    Text = "Si no planeas usar la nieve como manta, deberías pensar dónde pasaremos la noche, Guardián del Secreto"
  },
  AvgDialog_18787_Content_4 = {
    Text = "<Italic:Hermano mayor, hermana mayor, ¿vinieron de muy, muy lejos?>"
  },
  AvgDialog_18787_Content_5 = {
    Text = "Una voz infantil interrumpió su conversación"
  },
  AvgDialog_18787_Content_6 = {
    Text = "¿Quién está ahí?"
  },
  AvgDialog_18787_Content_7 = {
    Text = "La nieve en la pared refleja la luz de la luna, y en el centro hay una chica más blanca que la luz de la luna"
  },
  AvgDialog_18787_Content_8 = {
    Text = "Si no puedes encontrar un lugar para quedarte, puedes quedarte temporalmente en la habitación de <Blue:Dama del narciso>.\nEstá justo a la vuelta de la esquina."
  },
  AvgDialog_18787_Content_9 = {
    Text = "Le hiciste una señal a Ramona, y ella te devolvió una mirada afirmativa"
  },
  AvgDialog_18790_Content_1 = {
    Text = "Ustedes llegaron a la proa del barco, pero antes de mirar al mar, un impacto desde abajo inclinó el barco aún más"
  },
  AvgDialog_18790_Content_2 = {
    Text = "El carguero sube y baja con las olas, algo emerge del agua—"
  },
  AvgDialog_18790_Content_3 = {Text = "¡Murphy!"},
  AvgDialog_18790_Content_4 = {
    Text = "La cabeza de la serpiente mordía el cuerpo de la joven, y Miriam solo podía rezar con un susurro ronco"
  },
  AvgDialog_18790_Content_5 = {
    Text = "Ph'nglui mglw'nafh @3..."
  },
  AvgDialog_18790_Content_6 = {
    Text = "Elevó a Murphy bajo la luz de la luna, manos negras y pequeñas surgieron de su pecho, envolviéndola en un capullo negro"
  },
  AvgDialog_18790_Content_7 = {
    Text = "En el bajo rugido apagado, las manos y los hilos oscuros ven a miria como un soporte, permitiendo que el capullo se enrede firmemente en su inmenso cuerpo"
  },
  AvgDialog_18790_Content_8 = {
    Text = "La cáscara del capullo se volvió transparente debido a la expansión, innumerables manos se entrelazaron formando un trono, levantando un corazón pálido"
  },
  AvgDialog_18790_Content_9 = {
    Text = "Ph'nglui mglw'nafh @1'@2 wgah'nagl fhtagn!"
  },
  AvgDialog_18792_Content_1 = {
    Text = "Solo es una niña de los barrios bajos, no sabe nada. No supondrá ninguna amenaza para usted..."
  },
  AvgDialog_18792_Content_10 = {
    Text = "Qué molesto, me duelen las manos. ¿Piensas morir aquí hoy, 24?"
  },
  AvgDialog_18792_Content_11 = {
    Text = "Sin un esclavo obediente como tú, también lloraré~"
  },
  AvgDialog_18792_Content_12 = {
    Text = "Lo siento... No me moveré de aquí"
  },
  AvgDialog_18792_Content_14 = {Text = "¡Pah!"},
  AvgDialog_18792_Content_15 = {
    Text = "En poco tiempo, el cuerpo entero de 24 es un amasijo ensangrentado. Sin embargo, no se mueve ni un ápice, repitiendo las mismas palabras una y otra vez."
  },
  AvgDialog_18792_Content_16 = {
    Text = "<Shake:D–Déjela ir... Por favor...>"
  },
  AvgDialog_18792_Content_17 = {
    Text = "<Shake:Déjala ir...>"
  },
  AvgDialog_18792_Content_18 = {
    Text = "¡Si tienes agallas, ven a por mí, montón de inútiles! No"
  },
  AvgDialog_18792_Content_19 = {
    Text = "<Bold:No golpees a mi hermana...>"
  },
  AvgDialog_18792_Content_2 = {Text = "¡Pah!"},
  AvgDialog_18792_Content_20 = {
    Text = "¡Señorita 24! Detente... ugh"
  },
  AvgDialog_18792_Content_21 = {
    Text = "<Small:No puedo moverme. Necesito sacar la llave de plata...>"
  },
  AvgDialog_18792_Content_22 = {
    Text = "¡Qué torpe, qué torpe! Entonces no me culpes por ser cruel~"
  },
  AvgDialog_18792_Content_23 = {
    Text = "Leigh, es tu turno de brillar"
  },
  AvgDialog_18792_Content_3 = {
    Text = "El látigo cayó sin piedad, dejando una marca roja en la cara de 24"
  },
  AvgDialog_18792_Content_4 = {Text = "¡Hngh—!"},
  AvgDialog_18792_Content_5 = {
    Text = "24 protegiendo a Jenkins, sus delgados omóplatos temblando como alas de mariposa"
  },
  AvgDialog_18792_Content_6 = {
    Text = "Forzó una sonrisa, pero parecía más una mueca"
  },
  AvgDialog_18792_Content_7 = {
    Text = "Mi lord, por favor ten piedad... Déjala ir y haré cualquier cosa..."
  },
  AvgDialog_18792_Content_8 = {Text = "¡Pah!"},
  AvgDialog_18792_Content_9 = {
    Text = "Incontables latigazos caen como gotas de lluvia."
  },
  AvgDialog_18795_Content_1 = {
    Text = "La punta de la espada atraviesa las escamas de energía de la serpiente, apuñalando su punto vital"
  },
  AvgDialog_18795_Content_10 = {
    Text = "Rey... Mi señor... Murphy... Murphy..."
  },
  AvgDialog_18795_Content_12 = {
    Text = "Ahora... aún hay espacio para la reconciliación.\nVuelve a la orden, seguirás siendo la \"Madre Divina\""
  },
  AvgDialog_18795_Content_13 = {
    Text = "Tu funeral será la ceremonia más grandiosa en la historia del Reino de Dios, admirado por decenas de miles... Tu nombre también será inscrito en los anales de la historia, transmitido a través de los tiempos."
  },
  AvgDialog_18795_Content_14 = {
    Text = "Vuelve a mí, juntos... ejecutaremos a este <Blue:hereje>"
  },
  AvgDialog_18795_Content_15 = {
    Text = "¡Ejecuta... a este impostor que se disfraza de nuestro Señor!"
  },
  AvgDialog_18795_Content_16 = {
    Text = "La enorme serpiente se disolvía y se reunía, y el espacio se distorsionaba y cambiaba bajo el impacto del poder de Miriam"
  },
  AvgDialog_18795_Content_17 = {
    Text = "¡Miryam! ¡Te ordeno que te detengas!"
  },
  AvgDialog_18795_Content_18 = {
    Text = "Falsos dioses, impostores, irreverentes... aquellos sin @1@2... no deben usar la apariencia de @3@4"
  },
  AvgDialog_18795_Content_19 = {
    Text = "En un instante, la sombra que cubría la sala de poder se condensó en una entidad.  \nUn edificio distorsionado y difícil de describir emergió de la tierra"
  },
  AvgDialog_18795_Content_2 = {
    Text = "¡Eh, eh! ¡Alguien se va a caer!"
  },
  AvgDialog_18795_Content_20 = {
    Text = "<Change>Persona irreverente... persona irreverente...... irreverente irreverente irreverente ▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_18795_Content_21 = {
    Text = "Emitió un ruido chirriante ininteligible, Miriam se agarró el cuello con ambas manos, su cuerpo se deformó y alargó"
  },
  AvgDialog_18795_Content_22 = {
    Text = "¡Cuidado! ¡Ella va a perder el control!"
  },
  AvgDialog_18795_Content_3 = {
    Text = "También caíste en el rugido de la serpiente gigante"
  },
  AvgDialog_18795_Content_4 = {
    Text = "——Luego, caíste en un abrazo cálido y tembloroso"
  },
  AvgDialog_18795_Content_5 = {
    Text = "......%player%."
  },
  AvgDialog_18795_Content_6 = {
    Text = "¿Estoy en el cielo?"
  },
  AvgDialog_18795_Content_7 = {
    Text = "Lo siento, todavía estamos en el Sonaniel. Y la crisis está cerca"
  },
  AvgDialog_18795_Content_8 = {
    Text = "<Small:Imperdonable...>"
  },
  AvgDialog_18795_Content_9 = {
    Text = "¡Cuidado! ¡Miriam está actuando raro!"
  },
  AvgDialog_18796_Content_1 = {
    Text = "Ahem, ¡hola a todos! ¡Hoy vamos a probar el efecto de transición de Z1~!"
  },
  AvgDialog_18796_Content_10 = {
    Text = "Adecuado para cambiar rápidamente a escenas más oscuras."
  },
  AvgDialog_18796_Content_11 = {
    Text = "Uf... Estoy agotado, no hace falta que lo diga. ¡Después del número 4, obviamente viene el número 5!"
  },
  AvgDialog_18796_Content_12 = {
    Text = "Mmm... en resumen, la transición número 5 es la más utilizada, adecuada para muchas situaciones"
  },
  AvgDialog_18796_Content_13 = {
    Text = "Está bien, ahora el último cambio de escena——¡Adelante, número 6!"
  },
  AvgDialog_18796_Content_14 = {
    Text = "Es la transición más larga"
  },
  AvgDialog_18796_Content_15 = {
    Text = "Eso es todo para los efectos de transición, ¿todos lo entendieron?"
  },
  AvgDialog_18796_Content_16 = {
    Text = "Hasta la próxima vez♡"
  },
  AvgDialog_18796_Content_2 = {
    Text = "¡A continuación, el cambio de escena número 1 - cambio de escena izquierda y derecha~!"
  },
  AvgDialog_18796_Content_3 = {
    Text = "¡Tachán, tachán, tachán! ¿Qué tal, no es espléndido?"
  },
  AvgDialog_18796_Content_4 = {
    Text = "Esta transición se usa normalmente para cambiar entre escenas en el mismo lugar"
  },
  AvgDialog_18796_Content_5 = {
    Text = "A continuación, transición número 2—"
  },
  AvgDialog_18796_Content_6 = {
    Text = "Esta transición se usa normalmente para cambiar a una escena más brillante"
  },
  AvgDialog_18796_Content_7 = {
    Text = "Luego... ¡Cambio de escena 3!"
  },
  AvgDialog_18796_Content_8 = {
    Text = "La 3.ª transición también se aplica al cambio a escenas brillantes, aunque el ritmo será un poco más lento, jeje"
  },
  AvgDialog_18796_Content_9 = {
    Text = "El siguiente en acercarse es... ¡el número 4!"
  },
  AvgDialog_18797_Content_1 = {
    Text = "Mi...@1...uh"
  },
  AvgDialog_18797_Content_10 = {
    Text = "¡No eres el \"Rey Dios\"!"
  },
  AvgDialog_18797_Content_11 = {
    Text = "Al final, como servidor de Miriam, tú fuiste quien profetizó el renacimiento del dios, ¿verdad?"
  },
  AvgDialog_18797_Content_12 = {Text = "Tú..."},
  AvgDialog_18797_Content_13 = {
    Text = "Acabo de ver... a través del enlace, vi tus recuerdos"
  },
  AvgDialog_18797_Content_14 = {Text = "...Sí."},
  AvgDialog_18797_Content_15 = {
    Text = "Es la profecía que he dado, pero no existe tal \"oráculo\""
  },
  AvgDialog_18797_Content_16 = {Text = "¿Qué?"},
  AvgDialog_18797_Content_17 = {
    Text = "Mucho antes de que llegara la gran inundación, había perdido la capacidad de vislumbrar el futuro en los sueños del dios. \nNo sé dónde está Él, puede que haya despertado, o puede que se haya ido"
  },
  AvgDialog_18797_Content_18 = {
    Text = "Entonces, tu profecía"
  },
  AvgDialog_18797_Content_19 = {
    Text = "Miryam es una devota creyente, nacida para el Reino Divino y guiada por Mi voluntad."
  },
  AvgDialog_18797_Content_2 = {
    Text = "Murphy emitió un gemido de dolor, sus murmullos eran incoherentes"
  },
  AvgDialog_18797_Content_20 = {
    Text = "Solo esperaba que mis palabras la confortaran en sus momentos finales, nunca imaginé que las tomaría como el evangelio y buscaría reconstruir el Reino Divino."
  },
  AvgDialog_18797_Content_21 = {Text = "Todo esto"},
  AvgDialog_18797_Content_22 = {
    Text = "Sí, todo esto es mi culpa"
  },
  AvgDialog_18797_Content_23 = {
    Text = "Cuenta regresiva 60 minutos"
  },
  AvgDialog_18797_Content_3 = {
    Text = "¡¿Qué es esto?!"
  },
  AvgDialog_18797_Content_4 = {
    Text = "Las espantosas marcas azul-negras aparecieron en la cara de Murphy, como raíces profundas en su piel"
  },
  AvgDialog_18797_Content_5 = {
    Text = "Ha comenzado a bloquear el flujo sanguíneo del huésped"
  },
  AvgDialog_18797_Content_6 = {
    Text = "¿No dijiste que alejarse del cuerpo celeste sería suficiente?"
  },
  AvgDialog_18797_Content_7 = {
    Text = "Quiero decir que tal vez ella no se sienta tan mal"
  },
  AvgDialog_18797_Content_8 = {
    Text = "El cuerpo celeste está en órbita, no hay vuelta atrás"
  },
  AvgDialog_18797_Content_9 = {
    Text = "¿No hay ninguna solución?"
  },
  AvgDialog_18798_Content_1 = {
    Text = "Uf... Uf... No lo vi arriba, tampoco abajo"
  },
  AvgDialog_18798_Content_10 = {
    Text = "Murphy se dejó caer, apoyándose en la borda y deslizándose hasta la cubierta, sin preocuparse por su postura"
  },
  AvgDialog_18798_Content_11 = {
    Text = "Quería encontrar un apoyo para no caer, y después de buscar, se apoyó en tu hombro"
  },
  AvgDialog_18798_Content_12 = {
    Text = "Solo un momento..."
  },
  AvgDialog_18798_Content_13 = {
    Text = "En unos segundos, se escuchó una respiración rápida y rítmica.\nMurphy perdió el conocimiento de nuevo"
  },
  AvgDialog_18798_Content_14 = {
    Text = "Se está debilitando..."
  },
  AvgDialog_18798_Content_15 = {
    Text = "El dios al que estoy conectado viene de entre las estrellas, incluso si es una falsificación, no puede ser resistido por los humanos"
  },
  AvgDialog_18798_Content_16 = {
    Text = "¿No hay forma de aliviarlo?"
  },
  AvgDialog_18798_Content_17 = {
    Text = "......Llévatela"
  },
  AvgDialog_18798_Content_18 = {
    Text = "Alejarse de los cuerpos celestes podría hacerla sentir mejor"
  },
  AvgDialog_18798_Content_2 = {
    Text = "Ellos... ¿dónde están?"
  },
  AvgDialog_18798_Content_3 = {
    Text = "<Small:Odio esto... ¿por qué este barco es tan grande...?>"
  },
  AvgDialog_18798_Content_4 = {
    Text = "¿Estás bien?"
  },
  AvgDialog_18798_Content_5 = {
    Text = "¡Estoy perfectamente bien! ¡Tos, tos..."
  },
  AvgDialog_18798_Content_6 = {
    Text = "Murphy te respondió en voz alta, pero se atragantó y comenzó a toser violentamente"
  },
  AvgDialog_18798_Content_7 = {
    Text = "Pero estoy muy cansado, y me duele un poco la cabeza"
  },
  AvgDialog_18798_Content_8 = {
    Text = "Mientras hablaban, ya te habías sentado"
  },
  AvgDialog_18798_Content_9 = {
    Text = "Eso, eso... descansemos un poco... solo un momento"
  },
  AvgDialog_18802_Content_1 = {
    Text = "Si fuera más fuerte, si pudiera resistirlo...\nPero no puedo, no puedo"
  },
  AvgDialog_18802_Content_10 = {
    Text = "Lo siento... lo siento... todo es mi culpa"
  },
  AvgDialog_18802_Content_11 = {
    Text = "Soy un monstruo inútil, maté a tanta gente y no pude salvar a la hermana de Jenkins"
  },
  AvgDialog_18802_Content_12 = {
    Text = "Se la llevaron, se la llevaron, pero ni siquiera sé a dónde...\nNi siquiera sé quién nos controla"
  },
  AvgDialog_18802_Content_13 = {
    Text = "Ramona se arrodilló frente a Aigis y la abrazó suavemente"
  },
  AvgDialog_18802_Content_14 = {
    Text = "Has hecho todo lo posible, Aigis. No fue tu culpa"
  },
  AvgDialog_18802_Content_15 = {
    Text = "Eso es el verdadero Destripador, el que te controla y comete estos crímenes.\nNunca fue tu culpa"
  },
  AvgDialog_18802_Content_16 = {
    Text = "La niña se lanzó a los brazos de Ramona llorando, pero no dejó de cubrirse el ojo derecho"
  },
  AvgDialog_18802_Content_17 = {
    Text = "Encontraremos a esa persona."
  },
  AvgDialog_18802_Content_18 = {
    Text = "Lo encontraremos y pagará el precio.\nTe lo juro"
  },
  AvgDialog_18802_Content_19 = {
    Text = "Gracias, gracias a todos... Gracias a todos"
  },
  AvgDialog_18802_Content_2 = {
    Text = "La última vez que lo resistí, fue peor... no puedo hacerlo, ¡buaaa!"
  },
  AvgDialog_18802_Content_20 = {
    Text = "La luz dorada del atardecer atravesó la gran cara transparente del reloj de la torre, bañando a la niña"
  },
  AvgDialog_18802_Content_21 = {
    Text = "Aigis se giró y puso una mano en el vidrio, entrecerrando los ojos hacia el cálido sol"
  },
  AvgDialog_18802_Content_22 = {
    Text = "Hoy, se puede ver el sol"
  },
  AvgDialog_18802_Content_24 = {
    Text = "Como emocionada por el raro día soleado, se levantó y tambaleándose se acercó a un vidrio limpio"
  },
  AvgDialog_18802_Content_25 = {
    Text = "La visión borrosa finalmente se aclara, observa las calles familiares y desconocidas, y parece escuchar un susurro"
  },
  AvgDialog_18802_Content_26 = {
    Text = "Mira, esa voz dijo que esta noche veremos un cielo estrellado"
  },
  AvgDialog_18802_Content_28 = {
    Text = "La niña baja la cabeza y sonríe con nostalgia"
  },
  AvgDialog_18802_Content_29 = {
    Text = "Antes, cada vez que podíamos ver el sol, Tiyug me llevaba en secreto por la noche"
  },
  AvgDialog_18802_Content_3 = {
    Text = "Basta, no me obligues a hacer esto"
  },
  AvgDialog_18802_Content_30 = {
    Text = "La señorita Sarah nunca nos permitió venir aquí, dijo que era muy peligroso, y podríamos lastimarnos fácilmente. Pero a Teiog no le importa eso"
  },
  AvgDialog_18802_Content_31 = {
    Text = "Tenía una vista excelente, podía ver claramente en la oscuridad"
  },
  AvgDialog_18802_Content_32 = {
    Text = "Es tan astuto y valiente como Jenkins, siempre sabe los caminos y mecanismos ocultos"
  },
  AvgDialog_18802_Content_33 = {
    Text = "Con él, no seremos descubiertos por la señorita Sarah"
  },
  AvgDialog_18802_Content_34 = {
    Text = "Mientras él esté aquí, este lugar será siempre nuestra base secreta"
  },
  AvgDialog_18802_Content_35 = {
    Text = "Me dijo que debo estar en contacto con las estrellas para fortalecer mi magia.\nAunque aquí no podemos ver ni una estrella"
  },
  AvgDialog_18802_Content_36 = {
    Text = "En ese momento, él era el único que me creía.\nCreía que podía ver esas cosas negras, me dijo que era un don de bruja"
  },
  AvgDialog_18802_Content_37 = {
    Text = "Después él... Después de eso, los doctores comenzaron a llevarse a los pacientes, ya no los trataban en el asilo. No pude recolectar pruebas ni vengar a Tiyug"
  },
  AvgDialog_18802_Content_38 = {
    Text = "Si fuera tan inteligente como él, tan valiente como Jenkins, ya habría descubierto la verdad"
  },
  AvgDialog_18802_Content_39 = {
    Text = "Pero no soy una bruja"
  },
  AvgDialog_18802_Content_4 = {
    Text = "No quiero herir a nadie, no quiero matar"
  },
  AvgDialog_18802_Content_40 = {
    Text = "Solo soy un cobarde"
  },
  AvgDialog_18802_Content_41 = {
    Text = "Un monstruo"
  },
  AvgDialog_18802_Content_42 = {
    Text = "Un... asesino."
  },
  AvgDialog_18802_Content_43 = {
    Text = "¿Saben cuántas veces he sido manipulado?\n¿Saben cuánta sangre he derramado?"
  },
  AvgDialog_18802_Content_44 = {
    Text = "Estoy aterrorizado, temo en lo que me voy a convertir"
  },
  AvgDialog_18802_Content_46 = {
    Text = "Mis ojos y cuerpo solían doler, pero ahora no siento nada, como si también fuera de piedra"
  },
  AvgDialog_18802_Content_48 = {
    Text = "Maldita sea, ¿dónde se han ido todos...?"
  },
  AvgDialog_18802_Content_49 = {Text = "Eso es..."},
  AvgDialog_18802_Content_5 = {
    Text = "<Shake:<AvgNormalFont:¡No! ¡No!\nNo dejes que el pequeño Mike haga esto, es tan pequeño, ¿cómo puede...<Shake:te lo ruego...>>>"
  },
  AvgDialog_18802_Content_50 = {
    Text = "¿Aigis?! ¡Aigis—!"
  },
  AvgDialog_18802_Content_51 = {
    Text = "Desde abajo del campanario, de repente se escuchó la voz de Jenkins, que apareció en el patio sin que nadie lo notara"
  },
  AvgDialog_18802_Content_52 = {
    Text = "Ella gritó ansiosamente el nombre de Aigis, abriendo los brazos hacia el cielo"
  },
  AvgDialog_18802_Content_53 = {
    Text = "El pequeño cuerpo de la niña desaparece para siempre en la noche mientras cae"
  },
  AvgDialog_18802_Content_54 = {
    Text = "Un pájaro vuela a través del cielo nocturno, desapareciendo en la espesa niebla sin dejar rastro."
  },
  AvgDialog_18802_Content_55 = {
    Text = "Las manos extendidas de Jenkin solo sostuvieron con confusión el vestido vacío de Aigis, y junto a esto, se dispersaron como copos de nieve una serie de hojas de papel cuadradas"
  },
  AvgDialog_18802_Content_56 = {
    Text = "A... Aigis...? \n¿Qué... qué está pasando...?"
  },
  AvgDialog_18802_Content_57 = {
    Text = "En el papel hay una mariposa dorada, los bordes arrugados están cuidadosamente alisados, y huele a caramelo al caer"
  },
  AvgDialog_18802_Content_58 = {
    Text = "Uu... Aigis"
  },
  AvgDialog_18802_Content_59 = {
    Text = "Una cinta ensangrentada cae en la mano de la niña junto con un envoltorio de caramelo, moviéndose suavemente con el viento, como una caricia"
  },
  AvgDialog_18802_Content_6 = {
    Text = "No escucho, no escucho, no escucho, no escucho—"
  },
  AvgDialog_18802_Content_60 = {
    Text = "La niña parpadeó, y las lágrimas que nublaban su vista cayeron, siendo atrapadas silenciosamente por el rojo brillante"
  },
  AvgDialog_18802_Content_61 = {
    Text = "Este color y textura familiares... Solo falta una hebilla plateada para coincidir perfectamente con su recuerdo"
  },
  AvgDialog_18802_Content_62 = {
    Text = "...¿Hermana...?"
  },
  AvgDialog_18802_Content_7 = {
    Text = "¿Lo-lo logramos?\nCorre, rápido, pero por favor no se lo digas a nadie"
  },
  AvgDialog_18802_Content_8 = {
    Text = "<Shake:<AvgNormalFont:Espera, no, ¿qué es esto? Mi cabeza, mi cabeza... \nAh... ¡Ahhh...! <Shake:¡Ahhh!>>>"
  },
  AvgDialog_18802_Content_9 = {
    Text = "Lo siento... lo siento"
  },
  AvgDialog_18804_Content_1 = {
    Text = "¡Un guardián digno de ese nombre, robado por unos niños! Todo un año de entrenamiento desperdiciado. Los nuevos de la escuela pública son más listos que tú"
  },
  AvgDialog_18804_Content_2 = {
    Text = "Por suerte el ladrón también estaba en el lugar de la misión, de lo contrario, habrías tenido mala suerte. No permitiré que desperdicies tiempo de misión por asuntos personales"
  },
  AvgDialog_18804_Content_3 = {
    Text = "No es tan grave, muñeca; dale a %player% un poco de confianza"
  },
  AvgDialog_18804_Content_4 = {
    Text = "Por favor, no interfieras con la investigación del Guardián del Secreto"
  },
  AvgDialog_18805_Content_1 = {
    Text = "¡Un guardián digno de ese nombre, robado por unos niños! Todo un año de entrenamiento desperdiciado. Los nuevos de la escuela pública son más listos que tú"
  },
  AvgDialog_18805_Content_2 = {
    Text = "Por suerte el ladrón también estaba en el lugar de la misión, de lo contrario, habrías tenido mala suerte. No permitiré que desperdicies tiempo de misión por asuntos personales"
  },
  AvgDialog_18805_Content_3 = {
    Text = "No es tan grave, muñeca; dale a %player% un poco de confianza"
  },
  AvgDialog_18805_Content_4 = {
    Text = "Por favor, no interfieras con la investigación del Guardián del Secreto"
  },
  AvgDialog_18808_Content_1 = {
    Text = "Es una prueba de diálogo sin contexto 1"
  },
  AvgDialog_18808_Content_2 = {
    Text = "Es una prueba de diálogo sin contexto 2"
  },
  AvgDialog_18809_Content_1 = {
    Text = "Murphy no dudó, arrastrando a Ramona a un lado y comenzando a desvestirse.\nCon el último botón desabrochado, Ramona vio al \"dios\" dentro de la chica"
  },
  AvgDialog_18809_Content_2 = {
    Text = "En el pecho hay una piel transparente, tirando de la piel y los músculos circundantes, haciendo que toda la cavidad torácica y abdominal se vea gris y marchita"
  },
  AvgDialog_18809_Content_3 = {
    Text = "Con tal fenómeno, los órganos en el pecho eran visibles, Ramona vio un joven corazón rojo pálido y un \"huevo\" blanco"
  },
  AvgDialog_18809_Content_4 = {
    Text = "Filamentos interminables se extienden desde el \"huevo\", entrelazándose estrechamente con los vasos sanguíneos de Murphy, dependiendo uno del otro"
  },
  AvgDialog_18809_Content_5 = {
    Text = "Si no fuera porque su existencia ya presionaba el corazón de Murphy, parecería una con el tórax transparente, sin parecer un objeto externo"
  },
  AvgDialog_18809_Content_6 = {
    Text = "Él es caótico y silencioso, el triángulo invertido negro grabado sobre él se solidifica también, como una extraña obra de arte"
  },
  AvgDialog_18809_Content_7 = {
    Text = "Corrosión... esto ya ha sido corroído"
  },
  AvgDialog_18809_Content_8 = {
    Text = "¿Has visto suficiente?"
  },
  AvgDialog_18809_Content_9 = {
    Text = "Lo siento, fui imprudente, ponte la ropa"
  },
  AvgDialog_18810_Content_1 = {
    Text = "Cuenta regresiva 20 minutos"
  },
  AvgDialog_18810_Content_10 = {
    Text = "¡Cuidado! ¡No caigas al mar!"
  },
  AvgDialog_18810_Content_11 = {
    Text = "Una enorme serpiente emergió del mar, casi volcando el barco.\nVarias cabezas de serpiente se retorcían, proyectando sombras aterradoras en la cubierta"
  },
  AvgDialog_18810_Content_12 = {
    Text = "Usurpador... ¡Imbécil... Tonto!"
  },
  AvgDialog_18810_Content_13 = {
    Text = "Madre divina... Madre divina...@3!"
  },
  AvgDialog_18810_Content_14 = {
    Text = "¡Vaya, es Miriam!"
  },
  AvgDialog_18810_Content_15 = {
    Text = "¡Lleva a Murphy abajo!"
  },
  AvgDialog_18810_Content_16 = {Text = "¡Ah!!"},
  AvgDialog_18810_Content_17 = {
    Text = "Mirarás de nuevo hacia la cubierta; Murphy ya no está. La cabeza de una serpiente gigante ha agarrado a la niña y la ha arrastrado hacia Aequor."
  },
  AvgDialog_18810_Content_2 = {
    Text = "¿Enlace? ¿Significa que debe depender de ti para vivir en el futuro?"
  },
  AvgDialog_18810_Content_3 = {
    Text = "Solo es una medida provisional, no tenemos intención de llevarnos a la Señorita Celeste de sus manos"
  },
  AvgDialog_18810_Content_4 = {
    Text = "No es algo que pueda decidir"
  },
  AvgDialog_18810_Content_5 = {
    Text = "Celeste, ¿estás dispuesta?"
  },
  AvgDialog_18810_Content_6 = {
    Text = "Como si hubieran activado una palabra clave, Celeste levantó la cabeza, pero miró hacia el mar detrás de ella, y la navegación se detuvo"
  },
  AvgDialog_18810_Content_7 = {
    Text = "El barco no se mueve"
  },
  AvgDialog_18810_Content_8 = {
    Text = "Algo me agarró"
  },
  AvgDialog_18810_Content_9 = {
    Text = "Apenas terminó de hablar, el suelo comenzó a temblar violentamente como nunca antes, el barco se inclinó a un ángulo increíble"
  },
  AvgDialog_18812_Content_1 = {
    Text = "¿Incluso ustedes...? Un grupo de adultos que solo hablan por sí mismos"
  },
  AvgDialog_18812_Content_10 = {
    Text = "La luz deslumbrante te hiere los ojos, provocando lágrimas incontrolables."
  },
  AvgDialog_18812_Content_11 = {
    Text = "¡E-esto es!?"
  },
  AvgDialog_18812_Content_12 = {
    Text = "A medida que el líquido turbio se drena, tus ojos finalmente vuelven a enfocarse en la chica."
  },
  AvgDialog_18812_Content_13 = {
    Text = "Con una hoja hundida profundamente en su pecho, la joven bañada por la luz de la luna abre los ojos."
  },
  AvgDialog_18812_Content_14 = {
    Text = "La luna llena, símbolo de muerte, se cierne cerca, pero ni un rastro de miedo se muestra en su joven rostro."
  },
  AvgDialog_18812_Content_15 = {
    Text = "I... lo perforé... No nacerá..."
  },
  AvgDialog_18812_Content_16 = {
    Text = "Ahora, puedo..."
  },
  AvgDialog_18812_Content_17 = {
    Text = "Su mano que empuñaba el cuchillo cae débilmente, mientras un líquido espeso, viscoso y de un carmesí oscuro fluye desde la hoja, goteando entre sus dedos hacia el mar."
  },
  AvgDialog_18812_Content_18 = {
    Text = "La sangre se escapa rápidamente de su cuerpo, se vuelve pálido pero irradia una vitalidad extraña"
  },
  AvgDialog_18812_Content_19 = {
    Text = "No... no, no, no, no, ahhh—"
  },
  AvgDialog_18812_Content_2 = {
    Text = "Nadie me ha consultado ni una sola vez... Hmph"
  },
  AvgDialog_18812_Content_20 = {
    Text = "Dios todopoderoso, perdóname, perdona a este niño, perdona a tu devoto creyente"
  },
  AvgDialog_18812_Content_21 = {
    Text = "La hora de alinear, la hora de alinear se acerca, se acerca"
  },
  AvgDialog_18812_Content_22 = {
    Text = "\"Placenta\" se rompe, el \"Corazón\" colapsa, innumerables manos emergen, el pecho de la chica se destroza"
  },
  AvgDialog_18812_Content_23 = {
    Text = "Una mano deforme aprieta los restos irreconocibles, superponiéndose, hinchándose, superponiéndose, hinchándose——"
  },
  AvgDialog_18812_Content_24 = {
    Text = "Ah... Me escuchaste... Me respondiste..."
  },
  AvgDialog_18812_Content_25 = {
    Text = "Empujaron una existencia deformada a la luz de la luna"
  },
  AvgDialog_18812_Content_26 = {
    Text = "¡Mi gran Dios...!"
  },
  AvgDialog_18812_Content_3 = {
    Text = "¿Una vida ganada con sacrificio...? ¿Quién la quiere?"
  },
  AvgDialog_18812_Content_4 = {
    Text = "No, la placenta está demasiado turbia.\n¿Podemos ver dentro con \"Retrospección Mental\"?"
  },
  AvgDialog_18812_Content_5 = {
    Text = "Aprietas la llave de plata temblorosa y te sumerges de nuevo en el espacio de la conciencia"
  },
  AvgDialog_18812_Content_6 = {
    Text = "En el espacio cubierto por d-baba, aquel resplandor que simboliza la vida y la inteligencia brilla intensamente"
  },
  AvgDialog_18812_Content_7 = {
    Text = "——Era un cuchillo ritual que reflejaba la fría luz de la luna"
  },
  AvgDialog_18812_Content_8 = {
    Text = "——¡Ugh!"
  },
  AvgDialog_18812_Content_9 = {
    Text = "La luz estalla de repente, expulsándote del mundo espiritual"
  },
  AvgDialog_18813_Content_1 = {
    Text = "A continuación, vamos a probar el efecto de transición de tiempo lento"
  },
  AvgDialog_18813_Content_10 = {
    Text = "Tormenta de arena 2"
  },
  AvgDialog_18813_Content_11 = {
    Text = "Fin de prueba"
  },
  AvgDialog_18813_Content_12 = {
    Text = "A continuación, probaremos el efecto de pantalla vibración continua"
  },
  AvgDialog_18813_Content_13 = {
    Text = "Inicio de prueba"
  },
  AvgDialog_18813_Content_14 = {
    Text = "Cierras los ojos ante su expresión de asombro."
  },
  AvgDialog_18813_Content_15 = {
    Text = "Al igual que el día de la Ceremonia de Concesión de Llaves, tomaste la mano de Ramona."
  },
  AvgDialog_18813_Content_16 = {
    Text = "Fin de prueba"
  },
  AvgDialog_18813_Content_17 = {
    Text = "A continuación, vamos a ejecutar el video del efecto[pantalla] llave de plata"
  },
  AvgDialog_18813_Content_18 = {
    Text = "Inicio de prueba"
  },
  AvgDialog_18813_Content_19 = {
    Text = "Fin de prueba, pero voy a iniciar directamente el efecto de activación de la llave plateada [efecto de pantalla] Prueba"
  },
  AvgDialog_18813_Content_2 = {
