  },
  AvgDialog_18813_Content_21 = {
    Text = "En progreso"
  },
  AvgDialog_18813_Content_22 = {
    Text = "Fin de prueba"
  },
  AvgDialog_18813_Content_23 = {
    Text = "A continuación, probaremos el efecto FadeDarkRole"
  },
  AvgDialog_18813_Content_24 = {
    Text = "Cierras los ojos ante su expresión de asombro."
  },
  AvgDialog_18813_Content_25 = {
    Text = "Al igual que el día de la Ceremonia de Concesión de Llaves, tomaste la mano de Ramona."
  },
  AvgDialog_18813_Content_26 = {Text = "Fin"},
