  },
  AvgDialog_62168_Content_19 = {
    Text = "¿Juliette? ¿Qué viste?!"
  },
  AvgDialog_62168_Content_2 = {
    Text = "¡Percusión, comienza!"
  },
  AvgDialog_62168_Content_20 = {
    Text = "La verdad... Así que esta es la verdad..."
  },
